-- ===== VIEWS =====
CREATE OR REPLACE VIEW public.ai_agent_quality AS  WITH runs AS (
         SELECT agent_runs.agent,
            count(*) AS runs_30d,
            count(*) FILTER (WHERE (agent_runs.status = ANY (ARRAY['error'::text, 'failed'::text]))) AS errors
           FROM agent_runs
          WHERE (agent_runs.started_at >= (now() - '30 days'::interval))
          GROUP BY agent_runs.agent
        ), acts AS (
         SELECT agent_actions.agent,
            count(*) AS actions_30d,
            count(*) FILTER (WHERE (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS open_escalations,
            count(*) FILTER (WHERE (agent_actions.status = 'rejected'::text)) AS rejected,
            count(*) FILTER (WHERE (agent_actions.status = ANY (ARRAY['approved'::text, 'done'::text, 'auto_done'::text]))) AS accepted
           FROM agent_actions
          WHERE (agent_actions.created_at >= (now() - '30 days'::interval))
          GROUP BY agent_actions.agent
        )
 SELECT COALESCE(r.agent, a.agent) AS agent,
    COALESCE(r.runs_30d, (0)::bigint) AS runs_30d,
    COALESCE(r.errors, (0)::bigint) AS errors,
    round(((100.0 * ((COALESCE(r.runs_30d, (0)::bigint) - COALESCE(r.errors, (0)::bigint)))::numeric) / (NULLIF(r.runs_30d, 0))::numeric), 1) AS run_success_pct,
    COALESCE(a.actions_30d, (0)::bigint) AS actions_30d,
    COALESCE(a.open_escalations, (0)::bigint) AS open_escalations,
    COALESCE(a.rejected, (0)::bigint) AS rejected,
    COALESCE(a.accepted, (0)::bigint) AS accepted,
    round(((100.0 * (a.rejected)::numeric) / (NULLIF((a.rejected + a.accepted), 0))::numeric), 1) AS rejection_rate_pct
   FROM (runs r
     FULL JOIN acts a ON ((a.agent = r.agent)));

CREATE OR REPLACE VIEW public.ap_aging AS  SELECT v.name AS vendor,
    sum(
        CASE
            WHEN (CURRENT_DATE <= COALESCE(b.due_date, b.bill_date)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS current_due,
    sum(
        CASE
            WHEN (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 1) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 30)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d1_30,
    sum(
        CASE
            WHEN (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 31) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 60)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d31_60,
    sum(
        CASE
            WHEN (((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) >= 61) AND ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) <= 90)) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d61_90,
    sum(
        CASE
            WHEN ((CURRENT_DATE - COALESCE(b.due_date, b.bill_date)) > 90) THEN (b.total - b.amount_paid)
            ELSE (0)::numeric
        END) AS d90_plus,
    sum((b.total - b.amount_paid)) AS total_due
   FROM (ap_bills b
     JOIN po_vendors v ON ((v.id = b.vendor_id)))
  WHERE (b.status = ANY (ARRAY['open'::text, 'partial'::text]))
  GROUP BY v.name;

CREATE OR REPLACE VIEW public.ap_open_bills AS  SELECT b.id,
    b.bill_no,
    v.name AS vendor,
    b.bill_date,
    b.due_date,
    b.total,
    b.amount_paid,
    (b.total - b.amount_paid) AS balance_due,
    b.status,
    (CURRENT_DATE - b.due_date) AS days_overdue
   FROM (ap_bills b
     JOIN po_vendors v ON ((v.id = b.vendor_id)))
  WHERE (b.status = ANY (ARRAY['open'::text, 'partial'::text]))
  ORDER BY b.due_date;

CREATE OR REPLACE VIEW public.budget_vs_actual AS  WITH actual AS (
         SELECT l.account_code,
            (date_trunc('month'::text, (j.entry_date)::timestamp with time zone))::date AS period_month,
            sum(l.debit) AS dr,
            sum(l.credit) AS cr
           FROM (gl_journal_lines l
             JOIN gl_journal j ON (((j.id = l.journal_id) AND (j.status = 'posted'::text))))
          GROUP BY l.account_code, ((date_trunc('month'::text, (j.entry_date)::timestamp with time zone))::date)
        )
 SELECT b.id AS budget_id,
    b.name AS budget_name,
    b.fiscal_year,
    bl.account_code,
    ga.name AS account_name,
    ga.type,
    bl.period_month,
    bl.amount AS budget_amount,
    COALESCE(
        CASE
            WHEN (ga.normal_balance = 'D'::bpchar) THEN (a.dr - a.cr)
            ELSE (a.cr - a.dr)
        END, (0)::numeric) AS actual_amount,
    (bl.amount - COALESCE(
        CASE
            WHEN (ga.normal_balance = 'D'::bpchar) THEN (a.dr - a.cr)
            ELSE (a.cr - a.dr)
        END, (0)::numeric)) AS variance
   FROM (((budget_lines bl
     JOIN budgets b ON ((b.id = bl.budget_id)))
     JOIN gl_accounts ga ON ((ga.code = bl.account_code)))
     LEFT JOIN actual a ON (((a.account_code = bl.account_code) AND (a.period_month = bl.period_month))));

CREATE OR REPLACE VIEW public.budget_vs_actual_summary AS  SELECT budget_id,
    budget_name,
    fiscal_year,
    account_code,
    account_name,
    type,
    sum(budget_amount) AS budget_ytd,
    sum(actual_amount) AS actual_ytd,
    sum(variance) AS variance_ytd,
        CASE
            WHEN (sum(budget_amount) <> (0)::numeric) THEN round(((100.0 * sum(actual_amount)) / sum(budget_amount)), 1)
            ELSE NULL::numeric
        END AS pct_of_budget
   FROM budget_vs_actual
  GROUP BY budget_id, budget_name, fiscal_year, account_code, account_name, type
  ORDER BY account_code;

CREATE OR REPLACE VIEW public.category_price_stats AS  SELECT i.category,
    count(qq.quote_amount) AS n,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((qq.quote_amount)::double precision)))::numeric, 0) AS median,
    round((percentile_cont((0.25)::double precision) WITHIN GROUP (ORDER BY ((qq.quote_amount)::double precision)))::numeric, 0) AS p25,
    round((percentile_cont((0.75)::double precision) WITHIN GROUP (ORDER BY ((qq.quote_amount)::double precision)))::numeric, 0) AS p75,
    round(avg(qq.quote_amount), 0) AS mean,
    round(COALESCE(stddev_pop(qq.quote_amount), (0)::numeric), 0) AS sd
   FROM (quotes qq
     JOIN inquiries i ON ((i.id = qq.inquiry_id)))
  WHERE ((qq.quote_amount IS NOT NULL) AND (qq.quote_amount > (0)::numeric) AND (i.category IS NOT NULL))
  GROUP BY i.category;

CREATE OR REPLACE VIEW public.crm_deal_kpis AS  SELECT (( SELECT count(*) AS count
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE ((NOT s.is_won) AND (NOT s.is_lost))))::integer AS open_deals,
    (( SELECT count(*) AS count
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE s.is_won))::integer AS won_deals,
    (( SELECT count(*) AS count
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE s.is_lost))::integer AS lost_deals,
    ( SELECT round(avg((EXTRACT(epoch FROM (COALESCE(i.completed_at, now()) - i.created_at)) / 86400.0)), 1) AS round
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE s.is_won) AS avg_cycle_days,
    ( SELECT round(COALESCE(sum(((i.expected_value * (s.probability)::numeric) / 100.0)), (0)::numeric), 2) AS round
           FROM (inquiries i
             JOIN crm_stages s ON ((s.key = i.pipeline_stage)))
          WHERE ((NOT s.is_won) AND (NOT s.is_lost))) AS weighted_forecast,
    (( SELECT count(*) AS count
           FROM crm_activities
          WHERE ((crm_activities.done = false) AND (crm_activities.due_at IS NOT NULL) AND (crm_activities.due_at < now()))))::integer AS overdue_activities;

CREATE OR REPLACE VIEW public.crm_pipeline_report AS  SELECT s.key,
    s.label,
    s.sort_order,
    s.probability,
    s.is_won,
    s.is_lost,
    (count(i.id))::integer AS deals,
    round(COALESCE(sum(i.expected_value), (0)::numeric), 2) AS value,
    round(COALESCE(sum(((i.expected_value * (s.probability)::numeric) / 100.0)), (0)::numeric), 2) AS weighted
   FROM (crm_stages s
     LEFT JOIN inquiries i ON ((i.pipeline_stage = s.key)))
  WHERE s.active
  GROUP BY s.key, s.label, s.sort_order, s.probability, s.is_won, s.is_lost
  ORDER BY s.sort_order;

CREATE OR REPLACE VIEW public.customer_health AS  WITH inq AS (
         SELECT i.id,
            i.customer_id,
            i.status,
            i.pipeline_stage,
            i.created_at,
            i.completed_at,
            i.outcome,
            i.stage_changed_at,
            ( SELECT min(q.created_at) AS min
                   FROM quotes q
                  WHERE (q.inquiry_id = i.id)) AS first_quote_at,
            ( SELECT count(*) AS count
                   FROM quotes q
                  WHERE (q.inquiry_id = i.id)) AS n_quotes
           FROM inquiries i
        ), inq2 AS (
         SELECT inq.id,
            inq.customer_id,
            inq.status,
            inq.pipeline_stage,
            inq.created_at,
            inq.completed_at,
            inq.outcome,
            inq.stage_changed_at,
            inq.first_quote_at,
            inq.n_quotes,
            (EXTRACT(epoch FROM (inq.first_quote_at - inq.created_at)) / 3600.0) AS resp_hrs,
                CASE
                    WHEN ((inq.status = 'revealed'::text) AND (inq.completed_at IS NULL) AND (inq.created_at < (now() - '30 days'::interval))) THEN true
                    WHEN ((inq.status = 'quoted'::text) AND (inq.created_at < (now() - '7 days'::interval))) THEN true
                    WHEN ((COALESCE(inq.pipeline_stage, ''::text) = 'qualifying'::text) AND (inq.n_quotes = 0) AND (inq.created_at < (now() - '2 days'::interval))) THEN true
                    ELSE false
                END AS stalled,
            ((inq.completed_at IS NOT NULL) OR (inq.outcome = 'won'::text)) AS completed,
            ((inq.status = 'revealed'::text) OR (inq.completed_at IS NOT NULL) OR (inq.outcome = 'won'::text)) AS progressed
           FROM inq
        ), cust AS (
         SELECT c.id AS customer_id,
            c.full_name,
            c.email,
            COALESCE(c.banned, false) AS banned,
            COALESCE(c.chat_strikes, 0) AS strikes,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE (x.customer_id = c.id)) AS total_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND (x.status <> 'cancelled'::text) AND (COALESCE(x.pipeline_stage, ''::text) <> 'lost'::text))) AS active_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND x.progressed)) AS progressed_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND x.completed)) AS completed_inq,
            ( SELECT count(*) AS count
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND x.stalled)) AS stalled_inq,
            ( SELECT max(GREATEST(x.created_at, COALESCE(x.stage_changed_at, x.created_at))) AS max
                   FROM inq2 x
                  WHERE (x.customer_id = c.id)) AS last_activity,
            ( SELECT round(avg(x.resp_hrs), 1) AS round
                   FROM inq2 x
                  WHERE ((x.customer_id = c.id) AND (x.resp_hrs IS NOT NULL))) AS avg_resp_hrs,
            ( SELECT round(avg(r.rating), 2) AS round
                   FROM reviews r
                  WHERE (r.customer_id = c.id)) AS avg_review,
            ( SELECT count(*) AS count
                   FROM reviews r
                  WHERE ((r.customer_id = c.id) AND (r.rating <= 2))) AS bad_reviews,
            ( SELECT count(*) AS count
                   FROM transactions t
                  WHERE ((t.customer_id = c.id) AND ((t.refund_status IS NOT NULL) OR (t.refund_requested_at IS NOT NULL)))) AS disputes
           FROM customers c
        ), scored AS (
         SELECT cust.customer_id,
            cust.full_name,
            cust.email,
            cust.banned,
            cust.strikes,
            cust.total_inq,
            cust.active_inq,
            cust.progressed_inq,
            cust.completed_inq,
            cust.stalled_inq,
            cust.last_activity,
            cust.avg_resp_hrs,
            cust.avg_review,
            cust.bad_reviews,
            cust.disputes,
            ((cust.last_activity IS NOT NULL) AND (cust.last_activity < (now() - '45 days'::interval))) AS dormant,
            round(LEAST((100)::numeric, ((
                CASE
                    WHEN (cust.last_activity >= (now() - '30 days'::interval)) THEN 60
                    WHEN (cust.last_activity >= (now() - '60 days'::interval)) THEN 40
                    WHEN (cust.last_activity >= (now() - '120 days'::interval)) THEN 20
                    ELSE 5
                END)::numeric + (((LEAST(cust.total_inq, (5)::bigint))::numeric / 5.0) * (40)::numeric))), 1) AS engagement,
            round(GREATEST((0)::numeric, LEAST((100)::numeric, (((
                CASE
                    WHEN (cust.avg_review IS NOT NULL) THEN ((cust.avg_review / 5.0) * (100)::numeric)
                    ELSE (70)::numeric
                END - (
                CASE
                    WHEN (cust.disputes > 0) THEN 30
                    ELSE 0
                END)::numeric) - ((cust.bad_reviews * 15))::numeric) - ((LEAST(cust.strikes, 3) * 10))::numeric))), 1) AS satisfaction,
            round(
                CASE
                    WHEN (cust.active_inq > 0) THEN (((cust.progressed_inq)::numeric / (cust.active_inq)::numeric) * (100)::numeric)
                    WHEN (cust.total_inq = 0) THEN (50)::numeric
                    ELSE (20)::numeric
                END, 1) AS progress,
            round((GREATEST(0, (
                CASE
                    WHEN (cust.avg_resp_hrs IS NULL) THEN 60
                    WHEN (cust.avg_resp_hrs < (24)::numeric) THEN 100
                    WHEN (cust.avg_resp_hrs < (72)::numeric) THEN 70
                    WHEN (cust.avg_resp_hrs < (168)::numeric) THEN 40
                    ELSE 20
                END -
                CASE
                    WHEN (cust.disputes > 0) THEN 40
                    ELSE 0
                END)))::numeric, 1) AS service
           FROM cust
        )
 SELECT customer_id,
    full_name,
    email,
    total_inq,
    active_inq,
    progressed_inq,
    completed_inq,
    stalled_inq,
    avg_resp_hrs,
    avg_review,
    bad_reviews,
    disputes,
    dormant,
    strikes,
    banned,
    last_activity,
    engagement,
    satisfaction,
    progress,
    service,
    round(((((engagement * 0.25) + (satisfaction * 0.30)) + (progress * 0.25)) + (service * 0.20)), 1) AS health,
        CASE
            WHEN (banned OR (disputes > 0) OR (bad_reviews > 0) OR ((total_inq > 0) AND (active_inq = 0)) OR (round(((((engagement * 0.25) + (satisfaction * 0.30)) + (progress * 0.25)) + (service * 0.20)), 1) < (40)::numeric)) THEN 'high'::text
            WHEN ((stalled_inq > 0) OR (strikes > 0) OR dormant OR (round(((((engagement * 0.25) + (satisfaction * 0.30)) + (progress * 0.25)) + (service * 0.20)), 1) < (65)::numeric)) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_tier
   FROM scored;

CREATE OR REPLACE VIEW public.customer_kpis AS  SELECT count(*) AS customers,
    round(avg(health), 1) AS avg_health,
    round(avg(satisfaction), 1) AS avg_satisfaction,
    round(avg(avg_resp_hrs) FILTER (WHERE (avg_resp_hrs IS NOT NULL)), 1) AS avg_response_hrs,
    round(((100.0 * (count(*) FILTER (WHERE (progress >= (60)::numeric)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_progressing,
    count(*) FILTER (WHERE (disputes > 0)) AS open_disputes,
    count(*) FILTER (WHERE (stalled_inq > 0)) AS with_stalled,
    count(*) FILTER (WHERE dormant) AS dormant_count,
    count(*) FILTER (WHERE (risk_tier = 'high'::text)) AS risk_high,
    count(*) FILTER (WHERE (risk_tier = 'medium'::text)) AS risk_medium,
    count(*) FILTER (WHERE (risk_tier = 'low'::text)) AS risk_low
   FROM customer_health;

CREATE OR REPLACE VIEW public.document_inventory AS  SELECT o.bucket_id AS bucket,
    o.name AS path,
    COALESCE(((o.metadata ->> 'size'::text))::bigint, (0)::bigint) AS bytes,
    COALESCE((o.metadata ->> 'mimetype'::text), ''::text) AS mime,
    o.created_at,
    rp.retention_days,
    rp.class AS retention_class,
    ((rp.retention_days IS NOT NULL) AND (o.created_at < (now() - ((rp.retention_days || ' days'::text))::interval))) AS past_retention,
    (EXISTS ( SELECT 1
           FROM documents d
          WHERE ((d.bucket = o.bucket_id) AND (d.path = o.name)))) AS registered,
    (EXISTS ( SELECT 1
           FROM documents d
          WHERE ((d.bucket = o.bucket_id) AND (d.path = o.name) AND (d.extracted IS NOT NULL)))) AS ocr_done
   FROM (storage.objects o
     LEFT JOIN retention_policy rp ON ((rp.bucket = o.bucket_id)))
  WHERE ((o.name IS NOT NULL) AND ("right"(o.name, 1) <> '/'::text));

CREATE OR REPLACE VIEW public.document_kpis AS  SELECT ( SELECT count(*) AS count
           FROM document_inventory) AS total_documents,
    ( SELECT COALESCE(sum(document_inventory.bytes), (0)::numeric) AS "coalesce"
           FROM document_inventory) AS total_bytes,
    ( SELECT count(DISTINCT document_inventory.bucket) AS count
           FROM document_inventory) AS buckets,
    ( SELECT count(*) AS count
           FROM document_inventory
          WHERE document_inventory.past_retention) AS past_retention,
    ( SELECT count(*) AS count
           FROM document_inventory
          WHERE (document_inventory.bytes > ((30 * 1024) * 1024))) AS oversized,
    ( SELECT count(*) AS count
           FROM documents) AS registered_docs,
    ( SELECT count(*) AS count
           FROM documents
          WHERE (documents.extracted IS NOT NULL)) AS ocr_done,
    ( SELECT count(*) AS count
           FROM documents
          WHERE ((COALESCE(documents.status, ''::text) <> ALL (ARRAY['done'::text, 'skipped'::text])) OR (COALESCE(documents.error, ''::text) <> ''::text))) AS ocr_backlog,
    round(((100.0 * (( SELECT count(*) AS count
           FROM documents
          WHERE (documents.extracted IS NOT NULL)))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM documents), 0))::numeric), 1) AS ocr_coverage_pct,
    ( SELECT count(*) AS count
           FROM doc_versions) AS version_records,
    ( SELECT max(objects.created_at) AS max
           FROM storage.objects
          WHERE (objects.bucket_id = 'backups'::text)) AS last_backup_at,
    ( SELECT ((EXTRACT(epoch FROM (now() - max(objects.created_at))) / (86400)::numeric))::integer AS int4
           FROM storage.objects
          WHERE (objects.bucket_id = 'backups'::text)) AS days_since_backup,
    ( SELECT count(*) AS count
           FROM legal_documents) AS legal_documents,
    ( SELECT count(*) AS count
           FROM dropbox_files
          WHERE (NOT dropbox_files.is_folder)) AS dropbox_files,
    ( SELECT count(*) AS count
           FROM dropbox_files
          WHERE dropbox_files.is_folder) AS dropbox_folders,
    ( SELECT COALESCE(sum(dropbox_files.size), (0)::numeric) AS "coalesce"
           FROM dropbox_files) AS dropbox_bytes,
    ( SELECT max(dropbox_files.synced_at) AS max
           FROM dropbox_files) AS dropbox_last_sync;

CREATE OR REPLACE VIEW public.finance_kpis AS  WITH rr AS (
         SELECT COALESCE(sum(
                CASE
                    WHEN (ga.type = 'revenue'::text) THEN (l.credit - l.debit)
                    ELSE (0)::numeric
                END), (0)::numeric) AS rev30,
            COALESCE(sum(
                CASE
                    WHEN (ga.type = 'expense'::text) THEN (l.debit - l.credit)
                    ELSE (0)::numeric
                END), (0)::numeric) AS exp30
           FROM ((gl_journal_lines l
             JOIN gl_journal j ON (((j.id = l.journal_id) AND (j.status = 'posted'::text))))
             JOIN gl_accounts ga ON ((ga.code = l.account_code)))
          WHERE (j.entry_date >= (CURRENT_DATE - 30))
        ), ar AS (
         SELECT COALESCE(sum(supplier_dues.amount_due) FILTER (WHERE (supplier_dues.status <> ALL (ARRAY['paid'::text, 'waived'::text]))), (0)::numeric) AS ar_outstanding,
            COALESCE(sum(supplier_dues.amount_due) FILTER (WHERE ((supplier_dues.status <> ALL (ARRAY['paid'::text, 'waived'::text])) AND (supplier_dues.due_date_30 < CURRENT_DATE))), (0)::numeric) AS ar_overdue,
            COALESCE(sum(supplier_dues.amount_due) FILTER (WHERE (supplier_dues.status = 'paid'::text)), (0)::numeric) AS ar_collected
           FROM supplier_dues
        ), ap AS (
         SELECT COALESCE(sum(ap_open_bills.balance_due), (0)::numeric) AS ap_outstanding,
            COALESCE(sum(ap_open_bills.balance_due) FILTER (WHERE (ap_open_bills.days_overdue > 0)), (0)::numeric) AS ap_overdue
           FROM ap_open_bills
        ), bud AS (
         SELECT count(*) FILTER (WHERE ((budget_vs_actual_summary.type = 'expense'::text) AND (budget_vs_actual_summary.pct_of_budget > (110)::numeric))) AS budget_overruns
           FROM budget_vs_actual_summary
        )
 SELECT ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.code = ANY (ARRAY['1000'::text, '1050'::text]))) AS cash,
    ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'revenue'::text)) AS revenue_total,
    ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'expense'::text)) AS expense_total,
    (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'revenue'::text)) - ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.type = 'expense'::text))) AS net_income,
        CASE
            WHEN (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'revenue'::text)) > (0)::numeric) THEN round(((100.0 * (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'revenue'::text)) - ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'expense'::text)))) / ( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.type = 'revenue'::text))), 1)
            ELSE NULL::numeric
        END AS margin_pct,
    rr.rev30 AS revenue_30d,
    rr.exp30 AS expense_30d,
    (rr.exp30 - rr.rev30) AS monthly_burn,
        CASE
            WHEN (((rr.exp30 - rr.rev30) > (0)::numeric) AND (( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = ANY (ARRAY['1000'::text, '1050'::text]))) > (0)::numeric)) THEN round((( SELECT COALESCE(sum(gl_account_balances.balance), (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = ANY (ARRAY['1000'::text, '1050'::text]))) / (rr.exp30 - rr.rev30)), 1)
            ELSE NULL::numeric
        END AS runway_months,
    ar.ar_outstanding,
    ar.ar_overdue,
    ar.ar_collected,
        CASE
            WHEN ((ar.ar_collected + ar.ar_outstanding) > (0)::numeric) THEN round(((100.0 * ar.ar_collected) / (ar.ar_collected + ar.ar_outstanding)), 1)
            ELSE NULL::numeric
        END AS collection_rate,
    ap.ap_outstanding,
    ap.ap_overdue,
    bud.budget_overruns
   FROM rr,
    ar,
    ap,
    bud;

CREATE OR REPLACE VIEW public.gl_account_balances AS  SELECT a.code,
    a.name,
    a.type,
    a.normal_balance,
    COALESCE(sum(l.debit), (0)::numeric) AS debit_total,
    COALESCE(sum(l.credit), (0)::numeric) AS credit_total,
        CASE
            WHEN (a.normal_balance = 'D'::bpchar) THEN (COALESCE(sum(l.debit), (0)::numeric) - COALESCE(sum(l.credit), (0)::numeric))
            ELSE (COALESCE(sum(l.credit), (0)::numeric) - COALESCE(sum(l.debit), (0)::numeric))
        END AS balance
   FROM ((gl_accounts a
     LEFT JOIN gl_journal_lines l ON ((l.account_code = a.code)))
     LEFT JOIN gl_journal j ON (((j.id = l.journal_id) AND (j.status = 'posted'::text))))
  GROUP BY a.code, a.name, a.type, a.normal_balance;

CREATE OR REPLACE VIEW public.gl_balance_sheet AS  SELECT type,
    code,
    name,
    balance AS amount
   FROM gl_account_balances
  WHERE (type = ANY (ARRAY['asset'::text, 'liability'::text, 'equity'::text]))
  ORDER BY type, code;

CREATE OR REPLACE VIEW public.gl_ledger AS  SELECT j.id AS journal_id,
    j.entry_no,
    j.entry_date,
    j.source,
    j.source_ref,
    j.memo,
    l.account_code,
    a.name AS account_name,
    a.type AS account_type,
    l.debit,
    l.credit
   FROM ((gl_journal j
     JOIN gl_journal_lines l ON ((l.journal_id = j.id)))
     JOIN gl_accounts a ON ((a.code = l.account_code)))
  WHERE (j.status = 'posted'::text);

CREATE OR REPLACE VIEW public.gl_pnl AS  SELECT type,
    code,
    name,
    balance AS amount
   FROM gl_account_balances
  WHERE (type = ANY (ARRAY['revenue'::text, 'expense'::text]))
  ORDER BY type DESC, code;

CREATE OR REPLACE VIEW public.gl_trial_balance AS  SELECT code,
    name,
    type,
        CASE
            WHEN ((balance >= (0)::numeric) AND (normal_balance = 'D'::bpchar)) THEN balance
            ELSE (0)::numeric
        END AS debit,
        CASE
            WHEN ((balance >= (0)::numeric) AND (normal_balance = 'C'::bpchar)) THEN balance
            ELSE (0)::numeric
        END AS credit,
    balance
   FROM gl_account_balances
  WHERE ((debit_total <> (0)::numeric) OR (credit_total <> (0)::numeric))
  ORDER BY code;

CREATE OR REPLACE VIEW public.governance_kpis AS  WITH agents AS (
         SELECT category_agents.slug,
            category_agents.persona
           FROM category_agents
          WHERE category_agents.active
        ), kn AS (
         SELECT DISTINCT agent_knowledge.agent_key
           FROM agent_knowledge
        ), act30 AS (
         SELECT agent_actions.id,
            agent_actions.agent,
            agent_actions.kind,
            agent_actions.status,
            agent_actions.risk,
            agent_actions.title,
            agent_actions.recommendation,
            agent_actions.detail,
            agent_actions.target_table,
            agent_actions.target_id,
            agent_actions.created_at,
            agent_actions.decided_at,
            agent_actions.decided_by,
            agent_actions.confidence,
            agent_actions.evidence,
            agent_actions.escalated,
            agent_actions.escalation_reason
           FROM agent_actions
          WHERE (agent_actions.created_at > (now() - '30 days'::interval))
        )
 SELECT ( SELECT count(*) AS count
           FROM agents) AS active_agents,
    ( SELECT count(*) AS count
           FROM agents
          WHERE ((agents.persona IS NOT NULL) AND (length(agents.persona) > 40))) AS agents_with_persona,
    ( SELECT count(*) AS count
           FROM agent_knowledge
          WHERE (agent_knowledge.agent_key = '_global'::text)) AS global_rules,
    ( SELECT count(*) AS count
           FROM agent_knowledge) AS knowledge_items,
    ( SELECT agent_governance.version
           FROM agent_governance
          WHERE agent_governance.active
          ORDER BY agent_governance.version DESC
         LIMIT 1) AS governance_version,
    ( SELECT count(*) AS count
           FROM act30) AS decisions_30d,
    ( SELECT count(*) AS count
           FROM act30
          WHERE (act30.confidence IS NOT NULL)) AS decisions_with_confidence,
    ( SELECT round(avg(act30.confidence), 2) AS round
           FROM act30
          WHERE (act30.confidence IS NOT NULL)) AS avg_confidence,
    ( SELECT count(*) AS count
           FROM act30
          WHERE act30.escalated) AS escalated_30d,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS open_for_review,
    ( SELECT count(*) AS count
           FROM agent_actions) AS audit_trail_total,
    ( SELECT count(DISTINCT agent_actions.agent) AS count
           FROM agent_actions) AS agents_with_audit_trail;

CREATE OR REPLACE VIEW public.inquiries_supplier_live AS  SELECT id,
    category,
    emirate,
    role_needed,
    status,
    created_at,
    scope_type,
    trades,
    keywords,
    brief_source,
    urgency,
    boq_confidence,
    drawing_redacted_paths,
    outcome,
    hired_supplier_id,
    summary_masked AS summary,
    raw_input_masked AS raw_input,
    budget_masked AS budget,
    spec_masked AS spec,
    boq_masked AS boq,
    completeness_masked AS completeness
   FROM inquiries i;

CREATE OR REPLACE VIEW public.inquiries_supplier_safe AS  SELECT i.id,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'category'::text)
            ELSE i.category
        END AS category,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'emirate'::text)
            ELSE i.emirate
        END AS emirate,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'role_needed'::text)
            ELSE i.role_needed
        END AS role_needed,
    i.status,
        CASE
            WHEN (b.brief IS NOT NULL) THEN ((b.brief ->> 'created_at'::text))::timestamp with time zone
            ELSE i.created_at
        END AS created_at,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'scope_type'::text)
            ELSE i.scope_type
        END AS scope_type,
        CASE
            WHEN (b.brief IS NOT NULL) THEN fn_jsonb_text_array((b.brief -> 'trades'::text))
            ELSE i.trades
        END AS trades,
        CASE
            WHEN (b.brief IS NOT NULL) THEN fn_jsonb_text_array((b.brief -> 'keywords'::text))
            ELSE i.keywords
        END AS keywords,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'brief_source'::text)
            ELSE i.brief_source
        END AS brief_source,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'urgency'::text)
            ELSE i.urgency
        END AS urgency,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'boq_confidence'::text)
            ELSE i.boq_confidence
        END AS boq_confidence,
        CASE
            WHEN (b.brief IS NOT NULL) THEN fn_jsonb_text_array((b.brief -> 'drawing_redacted_paths'::text))
            ELSE i.drawing_redacted_paths
        END AS drawing_redacted_paths,
    i.outcome,
    i.hired_supplier_id,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'summary'::text)
            ELSE i.summary_masked
        END AS summary,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'raw_input'::text)
            ELSE i.raw_input_masked
        END AS raw_input,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief ->> 'budget'::text)
            ELSE i.budget_masked
        END AS budget,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief -> 'spec'::text)
            ELSE i.spec_masked
        END AS spec,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief -> 'boq'::text)
            ELSE i.boq_masked
        END AS boq,
        CASE
            WHEN (b.brief IS NOT NULL) THEN (b.brief -> 'completeness'::text)
            ELSE i.completeness_masked
        END AS completeness
   FROM (inquiries i
     LEFT JOIN LATERAL ( SELECT b2.brief
           FROM inquiry_supplier_brief b2
          WHERE (b2.inquiry_id = i.id)
          ORDER BY b2.version DESC
         LIMIT 1) b ON (true));

CREATE OR REPLACE VIEW public.knowledge_kpis AS  WITH cats AS (
         SELECT category_agents.slug,
            category_agents.requires_regulation
           FROM category_agents
          WHERE (category_agents.active AND (category_agents.slug !~ '_'::text))
        ), base AS (
         SELECT ( SELECT count(*) AS count
                   FROM cats) AS categories_total,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (EXISTS ( SELECT 1
                           FROM agent_knowledge k
                          WHERE (k.agent_key = ('cat:'::text || c.slug))))) AS cat_with_knowledge,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (EXISTS ( SELECT 1
                           FROM qualification_playbooks p
                          WHERE ((p.category = c.slug) OR (c.slug ~~* (('%'::text || p.category) || '%'::text)) OR (p.category ~~* (('%'::text || c.slug) || '%'::text)))))) AS cat_with_playbook,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (EXISTS ( SELECT 1
                           FROM regulations r
                          WHERE ((r.status = 'active'::text) AND (r.approved_at IS NOT NULL) AND (c.slug = ANY (r.categories)))))) AS cat_with_regs,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE c.requires_regulation) AS regs_required,
            ( SELECT count(*) AS count
                   FROM cats c
                  WHERE (c.requires_regulation AND (EXISTS ( SELECT 1
                           FROM regulations r
                          WHERE ((r.status = 'active'::text) AND (r.approved_at IS NOT NULL) AND (c.slug = ANY (r.categories))))))) AS cat_regulated_covered,
            ( SELECT count(*) AS count
                   FROM regulations) AS regulations,
            ( SELECT count(*) AS count
                   FROM regulations
                  WHERE ((regulations.status = 'active'::text) AND (regulations.approved_at IS NOT NULL))) AS regulations_published,
            ( SELECT count(*) AS count
                   FROM regulations
                  WHERE (regulations.approved_at IS NULL)) AS regulations_pending,
            ( SELECT count(*) AS count
                   FROM mdm_standards) AS standards,
            ( SELECT count(*) AS count
                   FROM mdm_manufacturers) AS manufacturers,
            ( SELECT count(*) AS count
                   FROM mdm_brands) AS brands,
            ( SELECT count(*) AS count
                   FROM materials) AS materials,
            ( SELECT count(*) AS count
                   FROM qualification_playbooks) AS playbooks,
            ( SELECT count(*) AS count
                   FROM category_specs) AS category_specs,
            ( SELECT count(*) AS count
                   FROM kb_chunks) AS chunks,
            ( SELECT count(*) AS count
                   FROM agent_knowledge) AS knowledge_entries,
            ( SELECT count(*) AS count
                   FROM kb_revisions) AS revisions,
            ( SELECT count(*) AS count
                   FROM kb_revisions
                  WHERE ((COALESCE((kb_revisions.ai_validation ->> 'result'::text), 'pass'::text) = ANY (ARRAY['fail'::text, 'flag'::text, 'warn'::text])) OR (kb_revisions.status = 'rejected'::text))) AS flagged_revisions,
            ( SELECT count(*) AS count
                   FROM compliance_sources
                  WHERE compliance_sources.active) AS compliance_active,
            ( SELECT count(*) AS count
                   FROM compliance_sources
                  WHERE (compliance_sources.active AND (compliance_sources.last_checked_at >= (now() - '45 days'::interval)))) AS compliance_fresh,
            ( SELECT count(*) AS count
                   FROM category_specs
                  WHERE (category_specs.updated_at >= (now() - '180 days'::interval))) AS specs_fresh,
            ( SELECT count(*) AS count
                   FROM regulations
                  WHERE (regulations.updated_at >= (now() - '365 days'::interval))) AS regs_fresh,
            ( SELECT count(*) AS count
                   FROM kb_usage_log
                  WHERE (kb_usage_log.created_at >= (now() - '30 days'::interval))) AS queries_30d,
            ( SELECT count(DISTINCT kb_usage_log.category) AS count
                   FROM kb_usage_log
                  WHERE (kb_usage_log.created_at >= (now() - '30 days'::interval))) AS topics_queried_30d
        )
 SELECT categories_total,
    cat_with_knowledge,
    cat_with_playbook,
    cat_with_regs,
    regulations,
    regulations_published,
    regulations_pending,
    standards,
    manufacturers,
    brands,
    materials,
    playbooks,
    category_specs,
    chunks,
    knowledge_entries,
    revisions,
    flagged_revisions,
    compliance_active,
    compliance_fresh,
    specs_fresh,
    regs_fresh,
    queries_30d,
    topics_queried_30d,
    round(((100.0 * ((((cat_with_knowledge)::numeric / (NULLIF(categories_total, 0))::numeric) + ((cat_with_playbook)::numeric / (NULLIF(categories_total, 0))::numeric)) + COALESCE(((cat_regulated_covered)::numeric / (NULLIF(regs_required, 0))::numeric), (1)::numeric))) / 3.0), 1) AS coverage_pct,
    round(((100.0 * (cat_with_knowledge)::numeric) / (NULLIF(categories_total, 0))::numeric), 1) AS knowledge_coverage_pct,
    round(((100.0 * (cat_with_playbook)::numeric) / (NULLIF(categories_total, 0))::numeric), 1) AS playbook_coverage_pct,
    round(((100.0 * ((revisions - flagged_revisions))::numeric) / (NULLIF(revisions, 0))::numeric), 1) AS accuracy_pct,
    round(((100.0 * ((COALESCE(((compliance_fresh)::numeric / (NULLIF(compliance_active, 0))::numeric), (1)::numeric) + COALESCE(((specs_fresh)::numeric / (NULLIF(category_specs, 0))::numeric), (1)::numeric)) + COALESCE(((regs_fresh)::numeric / (NULLIF(regulations, 0))::numeric), (1)::numeric))) / (3)::numeric), 1) AS freshness_pct,
    round(((100.0 * (cat_with_knowledge)::numeric) / (NULLIF(categories_total, 0))::numeric), 1) AS usage_reach_pct,
    round((100.0 * COALESCE(((cat_regulated_covered)::numeric / (NULLIF(regs_required, 0))::numeric), (1)::numeric)), 1) AS regulation_coverage_pct,
    regs_required,
    cat_regulated_covered
   FROM base b;

CREATE OR REPLACE VIEW public.legal_kpis AS  SELECT ( SELECT count(*) AS count
           FROM legal_documents) AS policies_published,
    ( SELECT count(*) AS count
           FROM legal_documents
          WHERE (legal_documents.updated_at < (now() - '365 days'::interval))) AS policies_stale,
    ( SELECT count(*) AS count
           FROM legal_checklist) AS required_total,
    ( SELECT count(*) AS count
           FROM legal_checklist
          WHERE legal_checklist.present) AS required_present,
    ( SELECT count(*) AS count
           FROM legal_checklist
          WHERE (NOT legal_checklist.present)) AS required_missing,
    ( SELECT count(*) AS count
           FROM legal_checklist
          WHERE ((NOT legal_checklist.present) AND (legal_checklist.priority = 1))) AS critical_missing,
    round(((100.0 * (( SELECT count(*) AS count
           FROM legal_checklist
          WHERE legal_checklist.present))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM legal_checklist), 0))::numeric), 1) AS coverage_pct,
    ( SELECT count(*) AS count
           FROM customers) AS customers,
    round(((100.0 * (( SELECT count(*) AS count
           FROM customers
          WHERE (customers.tos_accepted_at IS NOT NULL)))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM customers), 0))::numeric), 1) AS customer_terms_acceptance_pct,
    ( SELECT count(*) AS count
           FROM leads
          WHERE (leads.approval_status = 'approved'::text)) AS suppliers_approved,
    round(((100.0 * (( SELECT count(*) AS count
           FROM leads
          WHERE ((leads.approval_status = 'approved'::text) AND (leads.accepted_terms_at IS NOT NULL))))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM leads
          WHERE (leads.approval_status = 'approved'::text)), 0))::numeric), 1) AS supplier_terms_acceptance_pct,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.kind = 'legal_flag'::text) AND (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])))) AS open_legal_flags,
    ( SELECT count(*) AS count
           FROM legal_reviews
          WHERE ((legal_reviews.risk_level = 'high'::text) AND legal_reviews.needs_licensed_review)) AS high_risk_reviews;

CREATE OR REPLACE VIEW public.marketing_category_demand AS  WITH cats AS (
         SELECT DISTINCT COALESCE(NULLIF(inquiries.category, ''::text), 'other'::text) AS c
           FROM inquiries
          WHERE (inquiries.category IS NOT NULL)
        UNION
         SELECT seo_categories.slug
           FROM seo_categories
        )
 SELECT c AS category,
    ( SELECT count(*) AS count
           FROM inquiries i
          WHERE ((COALESCE(NULLIF(i.category, ''::text), 'other'::text) = c.c) AND (i.created_at >= (now() - '90 days'::interval)))) AS inquiries_90d,
    ( SELECT count(*) AS count
           FROM leads l
          WHERE ((l.approval_status = 'approved'::text) AND (l.claimed = true) AND (l.categories ~~* (('%'::text || c.c) || '%'::text)))) AS suppliers,
    (EXISTS ( SELECT 1
           FROM seo_categories s
          WHERE ((s.slug = c.c) AND s.generated))) AS has_seo_page,
    (EXISTS ( SELECT 1
           FROM blog_posts b
          WHERE ((b.category = c.c) AND b.published))) AS has_blog
   FROM cats c;

CREATE OR REPLACE VIEW public.marketing_kpis AS  WITH f AS (
         SELECT funnel_metrics(30) AS fm
        ), mi AS (
         SELECT COALESCE(sum(meta_insights.spend), (0)::numeric) AS meta_spend,
            COALESCE(sum(meta_insights.impressions), (0)::numeric) AS meta_impr,
            COALESCE(sum(meta_insights.clicks), (0)::numeric) AS meta_clicks,
            COALESCE(sum(meta_insights.results), (0)::numeric) AS meta_results,
            count(*) FILTER (WHERE (meta_insights.effective_status = 'ACTIVE'::text)) AS meta_active
           FROM meta_insights
          WHERE ((meta_insights.time_window = 'last_30d'::text) AND (meta_insights.campaign_name ~~* '%quotesdone%'::text))
        )
 SELECT ((f.fm ->> 'inquiries'::text))::integer AS inquiries_30d,
    ((f.fm ->> 'matched'::text))::integer AS matched_30d,
    ((f.fm ->> 'quoted'::text))::integer AS quoted_30d,
    ((f.fm ->> 'revealed'::text))::integer AS revealed_30d,
    ((f.fm ->> 'reveal_fees'::text))::numeric AS revenue_30d,
        CASE
            WHEN (((f.fm ->> 'inquiries'::text))::integer > 0) THEN round(((100.0 * (((f.fm ->> 'quoted'::text))::integer)::numeric) / (((f.fm ->> 'inquiries'::text))::integer)::numeric), 1)
            ELSE NULL::numeric
        END AS inq_to_quote_pct,
        CASE
            WHEN (((f.fm ->> 'quoted'::text))::integer > 0) THEN round(((100.0 * (((f.fm ->> 'revealed'::text))::integer)::numeric) / (((f.fm ->> 'quoted'::text))::integer)::numeric), 1)
            ELSE NULL::numeric
        END AS quote_to_reveal_pct,
    ( SELECT count(*) AS count
           FROM blog_posts
          WHERE blog_posts.published) AS blog_published,
    ( SELECT count(*) AS count
           FROM blog_posts) AS blog_total,
    ( SELECT count(*) AS count
           FROM content_drafts
          WHERE (COALESCE(content_drafts.status, ''::text) <> ALL (ARRAY['published'::text, 'discarded'::text]))) AS drafts_pending,
    ( SELECT count(*) AS count
           FROM social_posts
          WHERE ((COALESCE(social_posts.status, ''::text) = ANY (ARRAY['staged'::text, 'scheduled'::text, 'draft'::text, 'pending'::text])) OR ((social_posts.mode = 'draft'::text) AND (COALESCE(social_posts.status, ''::text) = ANY (ARRAY['published'::text, 'sent'::text]))))) AS social_staged,
    ( SELECT count(*) AS count
           FROM social_posts
          WHERE ((social_posts.mode = 'now'::text) AND (COALESCE(social_posts.status, ''::text) = ANY (ARRAY['published'::text, 'sent'::text])))) AS social_published,
    ( SELECT count(*) AS count
           FROM seo_categories) AS seo_pages,
    ( SELECT count(*) AS count
           FROM seo_categories
          WHERE seo_categories.generated) AS seo_generated,
    ( SELECT count(*) AS count
           FROM leads) AS leads_total,
    ( SELECT count(*) AS count
           FROM outreach) AS outreach_sent,
    ( SELECT COALESCE(gl_account_balances.balance, (0)::numeric) AS "coalesce"
           FROM gl_account_balances
          WHERE (gl_account_balances.code = '6200'::text)) AS mkt_spend,
    ( SELECT count(*) AS count
           FROM customers
          WHERE (customers.created_at >= (now() - '30 days'::interval))) AS new_customers_30d,
        CASE
            WHEN (mi.meta_spend > (0)::numeric) THEN round((mi.meta_spend / (NULLIF(( SELECT count(*) AS count
               FROM customers
              WHERE (customers.created_at >= (now() - '30 days'::interval))), 0))::numeric), 2)
            ELSE NULL::numeric
        END AS cac,
        CASE
            WHEN (mi.meta_spend > (0)::numeric) THEN round((((f.fm ->> 'reveal_fees'::text))::numeric / mi.meta_spend), 2)
            WHEN (( SELECT COALESCE(gl_account_balances.balance, (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = '6200'::text)) > (0)::numeric) THEN round((((f.fm ->> 'reveal_fees'::text))::numeric / ( SELECT COALESCE(gl_account_balances.balance, (0)::numeric) AS "coalesce"
               FROM gl_account_balances
              WHERE (gl_account_balances.code = '6200'::text))), 2)
            ELSE NULL::numeric
        END AS roi,
    ( SELECT count(*) AS count
           FROM marketing_category_demand
          WHERE ((marketing_category_demand.inquiries_90d > 0) AND (marketing_category_demand.suppliers = 0))) AS supply_gaps,
    ( SELECT count(*) AS count
           FROM marketing_category_demand
          WHERE (NOT marketing_category_demand.has_seo_page)) AS seo_gaps,
    mi.meta_spend AS meta_spend_30d,
    mi.meta_impr AS meta_impressions_30d,
    mi.meta_clicks AS meta_clicks_30d,
    mi.meta_results AS meta_results_30d,
    mi.meta_active AS meta_active_campaigns,
        CASE
            WHEN (mi.meta_results > (0)::numeric) THEN round((mi.meta_spend / mi.meta_results), 2)
            ELSE NULL::numeric
        END AS meta_cpl,
        CASE
            WHEN (mi.meta_spend > (0)::numeric) THEN round((((f.fm ->> 'reveal_fees'::text))::numeric / mi.meta_spend), 2)
            ELSE NULL::numeric
        END AS meta_roi
   FROM f,
    mi;

CREATE OR REPLACE VIEW public.marketplace_health AS  SELECT fn_health_index() AS health;

CREATE OR REPLACE VIEW public.ops_kpis AS  WITH m AS (
         SELECT fn_ops_metrics() AS j
        )
 SELECT ((j ->> 'open_rfqs_no_quotes_7d'::text))::integer AS no_quote_backlog,
    ((j ->> 'matched_not_quoted'::text))::integer AS matched_not_quoted,
    ((j ->> 'avg_first_quote_hours'::text))::numeric AS avg_first_quote_hours,
    ((j ->> 'response_rate_pct'::text))::numeric AS response_rate_pct,
    ((j ->> 'overdue_activities'::text))::integer AS overdue_activities,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text]))) AS pending_approvals,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])) AND (COALESCE(agent_actions.risk, ''::text) = ANY (ARRAY['high'::text, 'critical'::text])))) AS high_risk_pending,
    ( SELECT count(*) AS count
           FROM crm_tasks
          WHERE (COALESCE(crm_tasks.status, ''::text) <> 'done'::text)) AS open_tasks,
    ( SELECT count(*) AS count
           FROM crm_tasks
          WHERE ((COALESCE(crm_tasks.status, ''::text) <> 'done'::text) AND (crm_tasks.due_date < now()))) AS overdue_tasks,
    ( SELECT count(*) AS count
           FROM inquiries
          WHERE ((inquiries.status = 'quoted'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM transactions t
                  WHERE ((t.inquiry_id = inquiries.id) AND (t.revealed_at IS NOT NULL))))))) AS awaiting_reveal,
    ( SELECT count(*) AS count
           FROM cron.job) AS cron_jobs,
    ( SELECT count(*) AS count
           FROM cron.job_run_details
          WHERE ((job_run_details.status <> 'succeeded'::text) AND (job_run_details.start_time >= (now() - '24:00:00'::interval)))) AS cron_failures_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE ((agent_runs.status = ANY (ARRAY['error'::text, 'failed'::text])) AND (agent_runs.started_at >= (now() - '24:00:00'::interval)))) AS agent_errors_24h,
    ( SELECT count(*) AS count
           FROM error_events
          WHERE (error_events.created_at >= (now() - '24:00:00'::interval))) AS app_errors_24h,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.kind = ANY (ARRAY['incident'::text, 'security_incident'::text])) AND (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])))) AS open_incidents
   FROM m;

CREATE OR REPLACE VIEW public.project_summary AS  SELECT p.id AS project_id,
    p.customer_id,
    p.name,
    p.status,
    p.target_open_date,
    p.budget_total,
    p.created_at,
    count(i.id) AS rfq_count,
    count(i.id) FILTER (WHERE (i.status <> ALL (ARRAY['completed'::text, 'cancelled'::text]))) AS rfq_open,
    count(i.id) FILTER (WHERE (i.hired_supplier_id IS NOT NULL)) AS rfq_awarded,
    round(COALESCE(sum(i.expected_value), (0)::numeric), 0) AS pipeline_value,
    ( SELECT COALESCE(jsonb_agg(s.b ORDER BY (s.b ->> 'category'::text)), '[]'::jsonb) AS "coalesce"
           FROM ( SELECT jsonb_build_object('category', COALESCE(i2.category, 'uncategorised'::text), 'rfqs', count(*), 'open', count(*) FILTER (WHERE (i2.status <> ALL (ARRAY['completed'::text, 'cancelled'::text]))), 'awarded', count(*) FILTER (WHERE (i2.hired_supplier_id IS NOT NULL)), 'value_aed', round(COALESCE(sum(i2.expected_value), (0)::numeric), 0)) AS b
                   FROM inquiries i2
                  WHERE (i2.project_id = p.id)
                  GROUP BY COALESCE(i2.category, 'uncategorised'::text)) s) AS trade_breakdown,
    ( SELECT count(DISTINCT m.supplier_id) AS count
           FROM (inquiry_matches m
             JOIN inquiries i3 ON ((i3.id = m.inquiry_id)))
          WHERE (i3.project_id = p.id)) AS supplier_count,
        CASE
            WHEN (p.target_open_date IS NULL) THEN NULL::numeric
            WHEN (p.target_open_date <= (p.created_at)::date) THEN (100)::numeric
            ELSE round(LEAST((100)::numeric, GREATEST((0)::numeric, (((100)::numeric * ((CURRENT_DATE - (p.created_at)::date))::numeric) / (NULLIF((p.target_open_date - (p.created_at)::date), 0))::numeric))), 0)
        END AS timeline_pct
   FROM (projects p
     LEFT JOIN inquiries i ON ((i.project_id = p.id)))
  GROUP BY p.id, p.customer_id, p.name, p.status, p.target_open_date, p.budget_total, p.created_at;

CREATE OR REPLACE VIEW public.reg_coverage AS  SELECT count(*) FILTER (WHERE (copyright = 'free'::text)) AS free_codes,
    count(*) FILTER (WHERE ((copyright = 'free'::text) AND (status = 'indexed'::text))) AS indexed,
    count(*) FILTER (WHERE ((copyright = 'free'::text) AND (status <> 'indexed'::text))) AS missing,
    count(*) FILTER (WHERE ((priority = 1) AND (copyright = 'free'::text))) AS critical_total,
    count(*) FILTER (WHERE ((priority = 1) AND (copyright = 'free'::text) AND (status = 'indexed'::text))) AS critical_indexed,
    count(*) FILTER (WHERE (copyright = 'copyrighted'::text)) AS reference_only,
    round(((100.0 * (count(*) FILTER (WHERE ((copyright = 'free'::text) AND (status = 'indexed'::text))))::numeric) / (NULLIF(count(*) FILTER (WHERE (copyright = 'free'::text)), 0))::numeric), 1) AS coverage_pct
   FROM reg_catalog;

CREATE OR REPLACE VIEW public.report_kpis AS  WITH reg AS (
         SELECT report_registry.source,
            report_registry.report_type,
            report_registry.title,
            report_registry.period,
            report_registry.created_at,
            report_registry.id
           FROM report_registry
        ), lt AS (
         SELECT max(reg.created_at) FILTER (WHERE (reg.report_type = 'weekly'::text)) AS weekly_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'monthly'::text)) AS monthly_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'quarterly'::text)) AS quarterly_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'department'::text)) AS department_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'supplier'::text)) AS supplier_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'customer'::text)) AS customer_at,
            max(reg.created_at) FILTER (WHERE (reg.report_type = 'ai'::text)) AS ai_at,
            max(reg.created_at) FILTER (WHERE (reg.source = 'exec'::text)) AS exec_at,
            max(reg.created_at) FILTER (WHERE (reg.source = 'finance'::text)) AS finance_at
           FROM reg
        ), daily AS (
         SELECT GREATEST(( SELECT max(a.created_at) AS max
                   FROM agent_actions a
                  WHERE (a.kind = 'exec_briefing'::text)), ( SELECT max(n.created_at) AS max
                   FROM notifications n
                  WHERE (n.type = 'founder_brief'::text))) AS daily_at
        )
 SELECT ( SELECT count(*) AS count
           FROM reg) AS total_reports,
    ( SELECT count(*) AS count
           FROM reg
          WHERE (reg.created_at > (now() - '30 days'::interval))) AS reports_30d,
    ( SELECT count(DISTINCT reg.report_type) AS count
           FROM reg) AS report_types,
    d.daily_at,
    lt.weekly_at,
    lt.monthly_at,
    lt.quarterly_at,
    lt.department_at,
    lt.supplier_at,
    lt.customer_at,
    lt.ai_at,
    lt.exec_at,
    lt.finance_at,
    (d.daily_at > (now() - '36:00:00'::interval)) AS daily_fresh,
    (lt.weekly_at > (now() - '8 days'::interval)) AS weekly_fresh,
    (lt.monthly_at > date_trunc('month'::text, now())) AS monthly_fresh,
    (lt.quarterly_at > (now() - '95 days'::interval)) AS quarterly_fresh,
    (lt.department_at > (now() - '2 days'::interval)) AS department_fresh,
    (lt.supplier_at > (now() - '2 days'::interval)) AS supplier_fresh,
    (lt.customer_at > (now() - '2 days'::interval)) AS customer_fresh,
    (lt.ai_at > (now() - '2 days'::interval)) AS ai_fresh,
    (((((((
        CASE
            WHEN COALESCE((d.daily_at > (now() - '36:00:00'::interval)), false) THEN 0
            ELSE 1
        END +
        CASE
            WHEN COALESCE((lt.weekly_at > (now() - '8 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.monthly_at > date_trunc('month'::text, now())), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.quarterly_at > (now() - '95 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.department_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.supplier_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.customer_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) +
        CASE
            WHEN COALESCE((lt.ai_at > (now() - '2 days'::interval)), false) THEN 0
            ELSE 1
        END) AS stale_count
   FROM lt,
    daily d;

CREATE OR REPLACE VIEW public.report_registry AS  SELECT 'narrative'::text AS source,
    b.report_type,
    b.title,
    COALESCE((b.week_start)::text, to_char(b.created_at, 'YYYY-MM-DD'::text)) AS period,
    b.created_at,
    b.id,
    b.pdf_path,
    b.pdf_generated_at
   FROM board_reports b
UNION ALL
 SELECT 'exec'::text AS source,
    'exec_summary'::text AS report_type,
    ((e.officer || ' — '::text) || e.period) AS title,
    e.period,
    e.created_at,
    e.id,
    e.pdf_path,
    e.pdf_generated_at
   FROM exec_reports e
UNION ALL
 SELECT 'finance'::text AS source,
    COALESCE(f.kind, 'financial'::text) AS report_type,
    ((('Financial — '::text || COALESCE(f.kind, ''::text)) || ' '::text) || COALESCE((f.period_start)::text, ''::text)) AS title,
    COALESCE((f.period_start)::text, to_char(f.created_at, 'YYYY-MM-DD'::text)) AS period,
    f.created_at,
    f.id,
    f.pdf_path,
    f.pdf_generated_at
   FROM finance_reports f;

CREATE OR REPLACE VIEW public.security_kpis AS  SELECT ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"))) AS tables,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND c.relrowsecurity)) AS rls_enabled,
    round(((100.0 * (( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND c.relrowsecurity)))::numeric) / (NULLIF(( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char"))), 0))::numeric), 1) AS rls_coverage_pct,
    ( SELECT count(*) AS count
           FROM (pg_class c
             JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
          WHERE ((n.nspname = 'public'::name) AND (c.relkind = 'r'::"char") AND c.relrowsecurity AND (NOT (EXISTS ( SELECT 1
                   FROM pg_policy pol
                  WHERE (pol.polrelid = c.oid)))))) AS rls_deny_default,
    ( SELECT count(*) AS count
           FROM (pg_proc p
             JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
          WHERE ((n.nspname = 'public'::name) AND p.prosecdef AND ((p.proconfig IS NULL) OR (NOT (EXISTS ( SELECT 1
                   FROM unnest(p.proconfig) cc(cc)
                  WHERE (cc.cc ~~ 'search_path=%'::text))))))) AS secdef_mutable_searchpath,
    ( SELECT count(*) AS count
           FROM security_events
          WHERE ((security_events.severity = ANY (ARRAY['high'::text, 'critical'::text])) AND (security_events.created_at >= (now() - '7 days'::interval)))) AS high_sev_events_7d,
    ( SELECT count(*) AS count
           FROM security_events
          WHERE (security_events.created_at >= (now() - '7 days'::interval))) AS events_7d,
    ( SELECT count(*) AS count
           FROM fraud_flags
          WHERE (COALESCE(fraud_flags.status, ''::text) <> ALL (ARRAY['resolved'::text, 'dismissed'::text]))) AS open_fraud_flags,
    ( SELECT count(*) AS count
           FROM agent_actions
          WHERE ((agent_actions.kind = 'security_incident'::text) AND (agent_actions.status = ANY (ARRAY['pending'::text, 'needs_review'::text])))) AS open_incidents,
    ( SELECT count(*) AS count
           FROM error_events
          WHERE (error_events.created_at >= (now() - '24:00:00'::interval))) AS errors_24h,
    ( SELECT count(*) AS count
           FROM auth.users
          WHERE (users.banned_until IS NOT NULL)) AS banned_users,
    ( SELECT count(*) AS count
           FROM auth.users
          WHERE (users.last_sign_in_at >= (now() - '7 days'::interval))) AS active_users_7d,
    COALESCE(( SELECT count(*) AS count
           FROM auth.audit_log_entries
          WHERE ((audit_log_entries.created_at >= (now() - '7 days'::interval)) AND ((audit_log_entries.payload ->> 'action'::text) ~~* '%fail%'::text))), (0)::bigint) AS failed_logins_7d,
    ( SELECT count(*) AS count
           FROM app_secrets) AS secrets_count;

CREATE OR REPLACE VIEW public.strategy_kpis AS  WITH sup AS (
         SELECT quotes.supplier_id,
            count(*) AS c
           FROM quotes
          WHERE ((quotes.created_at > (now() - '90 days'::interval)) AND (quotes.supplier_id IS NOT NULL))
          GROUP BY quotes.supplier_id
        ), agg AS (
         SELECT count(*) AS active,
            COALESCE(round(((100.0 * (max(sup.c))::numeric) / NULLIF(sum(sup.c), (0)::numeric)), 1), (0)::numeric) AS top_share
           FROM sup
        ), fin AS (
         SELECT finance_kpis.cash,
            finance_kpis.monthly_burn,
            finance_kpis.runway_months,
            finance_kpis.revenue_30d,
            finance_kpis.margin_pct
           FROM finance_kpis
        ), rk AS (
         SELECT count(*) FILTER (WHERE (strategy_risks.status = 'open'::text)) AS open_risks,
            max(strategy_risks.score) AS top_score,
            (array_agg(strategy_risks.title ORDER BY strategy_risks.score DESC))[1] AS top_title
           FROM strategy_risks
          WHERE (strategy_risks.status = 'open'::text)
        )
 SELECT agg.active AS active_suppliers_90d,
    agg.top_share AS top_supplier_share_pct,
    jsonb_array_length(COALESCE((fn_strategy_metrics() -> 'under_supplied'::text), '[]'::jsonb)) AS under_supplied_categories,
    fin.cash,
    fin.monthly_burn,
        CASE
            WHEN ((fin.cash > (0)::numeric) AND (fin.monthly_burn > (0)::numeric)) THEN round((fin.cash / fin.monthly_burn), 1)
            ELSE fin.runway_months
        END AS runway_months,
    fin.revenue_30d,
    fin.margin_pct,
    COALESCE(rk.open_risks, (0)::bigint) AS open_risks,
    COALESCE(rk.top_score, 0) AS top_risk_score,
    rk.top_title AS top_risk,
    ( SELECT count(*) AS count
           FROM market_intel
          WHERE ((market_intel.kind = 'competitor'::text) AND (market_intel.status <> 'dismissed'::text))) AS competitor_intel,
    ( SELECT count(*) AS count
           FROM market_intel
          WHERE ((market_intel.kind = 'trend'::text) AND (market_intel.status <> 'dismissed'::text))) AS market_trends,
    ( SELECT count(*) AS count
           FROM market_intel
          WHERE (market_intel.status = 'open'::text)) AS open_intel,
    ( SELECT max(simulations.created_at) AS max
           FROM simulations) AS last_simulation_at
   FROM agg,
    fin,
    rk;

CREATE OR REPLACE VIEW public.supplier_health AS  WITH s AS (
         SELECT l.id AS supplier_id,
            l.company_name,
            l.banned,
            l.matching_blocked,
            COALESCE(l.chat_strikes, 0) AS strikes,
            l.approval_status,
            l.claimed,
            l.license_expiry,
            l.license_doc_path,
            l.insurance_expiry,
            l.insurance_doc_path,
            l.egr_doc_path,
            l.trn,
            l.iso_expiry,
            l.manufacturer_auth_expiry,
            l.registration_expires_at,
            l.portal_updated_at,
            COALESCE(l.rv_response_rate, (0)::numeric) AS rv_rate,
            ((l.rv_responded IS NOT NULL) OR (l.rv_reveals IS NOT NULL)) AS has_rv,
            p.perf_score,
            p.rating,
            p.quoted,
            p.quote_rate,
            ( SELECT max(q.created_at) AS max
                   FROM quotes q
                  WHERE (q.supplier_id = l.id)) AS last_quote_at,
            ( SELECT round(avg(((((COALESCE((r.r_quality)::integer, r.rating) + COALESCE((r.r_documentation)::integer, r.rating)) + COALESCE((r.r_compliance)::integer, r.rating)))::numeric / 3.0)), 2) AS round
                   FROM reviews r
                  WHERE (r.supplier_id = l.id)) AS review_quality
           FROM (leads l
             LEFT JOIN supplier_perf p ON ((p.supplier_id = l.id)))
          WHERE ((l.claimed = true) AND (COALESCE(l.approval_status, ''::text) = 'approved'::text))
        ), scored AS (
         SELECT s.supplier_id,
            s.company_name,
            s.banned,
            s.matching_blocked,
            s.strikes,
            s.approval_status,
            s.claimed,
            s.license_expiry,
            s.license_doc_path,
            s.insurance_expiry,
            s.insurance_doc_path,
            s.egr_doc_path,
            s.trn,
            s.iso_expiry,
            s.manufacturer_auth_expiry,
            s.registration_expires_at,
            s.portal_updated_at,
            s.rv_rate,
            s.has_rv,
            s.perf_score,
            s.rating,
            s.quoted,
            s.quote_rate,
            s.last_quote_at,
            s.review_quality,
            round(GREATEST((COALESCE(s.perf_score, (0)::numeric) * (100)::numeric), ((COALESCE(s.review_quality, (0)::numeric) / 5.0) * (100)::numeric), ((COALESCE(s.rating, (0)::numeric) / 5.0) * (100)::numeric)), 1) AS quality,
            round((GREATEST(0, ((((((
                CASE
                    WHEN ((s.license_doc_path IS NOT NULL) AND ((s.license_expiry IS NULL) OR (s.license_expiry >= CURRENT_DATE))) THEN 25
                    ELSE 0
                END +
                CASE
                    WHEN ((s.insurance_doc_path IS NOT NULL) AND ((s.insurance_expiry IS NULL) OR (s.insurance_expiry >= CURRENT_DATE))) THEN 25
                    ELSE 0
                END) +
                CASE
                    WHEN (s.egr_doc_path IS NOT NULL) THEN 25
                    ELSE 0
                END) +
                CASE
                    WHEN (s.trn IS NOT NULL) THEN 25
                    ELSE 0
                END) - (LEAST(s.strikes, 3) * 8)) -
                CASE
                    WHEN ((s.iso_expiry IS NOT NULL) AND (s.iso_expiry < CURRENT_DATE)) THEN 10
                    ELSE 0
                END) -
                CASE
                    WHEN ((s.manufacturer_auth_expiry IS NOT NULL) AND (s.manufacturer_auth_expiry < CURRENT_DATE)) THEN 10
                    ELSE 0
                END)))::numeric, 1) AS compliance,
            round((
                CASE
                    WHEN s.has_rv THEN s.rv_rate
                    ELSE COALESCE(s.quote_rate, (0)::numeric)
                END * (100)::numeric), 1) AS response,
            round(((
                CASE
                    WHEN (GREATEST(COALESCE(s.last_quote_at, s.portal_updated_at), s.portal_updated_at) >= (now() - '30 days'::interval)) THEN 60
                    WHEN (GREATEST(COALESCE(s.last_quote_at, s.portal_updated_at), s.portal_updated_at) >= (now() - '60 days'::interval)) THEN 40
                    WHEN (GREATEST(COALESCE(s.last_quote_at, s.portal_updated_at), s.portal_updated_at) >= (now() - '120 days'::interval)) THEN 20
                    ELSE 5
                END +
                CASE
                    WHEN ((s.registration_expires_at IS NULL) OR (s.registration_expires_at >= now())) THEN 40
                    ELSE 0
                END))::numeric, 1) AS retention
           FROM s
        )
 SELECT supplier_id,
    company_name,
    quality,
    compliance,
    response,
    retention,
    round(((((quality * 0.30) + (compliance * 0.30)) + (response * 0.20)) + (retention * 0.20)), 1) AS health,
        CASE
            WHEN (banned OR matching_blocked OR (strikes >= 3) OR (compliance < (40)::numeric) OR (round(((((quality * 0.30) + (compliance * 0.30)) + (response * 0.20)) + (retention * 0.20)), 1) < (40)::numeric)) THEN 'high'::text
            WHEN ((compliance < (75)::numeric) OR (strikes > 0) OR (retention < (30)::numeric) OR (round(((((quality * 0.30) + (compliance * 0.30)) + (response * 0.20)) + (retention * 0.20)), 1) < (65)::numeric)) THEN 'medium'::text
            ELSE 'low'::text
        END AS risk_tier,
    ((last_quote_at IS NULL) AND (portal_updated_at < (now() - '45 days'::interval))) AS dormant,
    strikes,
    banned,
    matching_blocked,
    last_quote_at,
    portal_updated_at
   FROM scored;

CREATE OR REPLACE VIEW public.supplier_kpis AS  SELECT count(*) AS active_suppliers,
    round(avg(quality), 1) AS avg_quality,
    round(avg(response), 1) AS avg_response_score,
    round(((100.0 * (count(*) FILTER (WHERE (compliance >= (80)::numeric)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS pct_compliant,
    round(((100.0 * (count(*) FILTER (WHERE (NOT dormant)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS retention_rate,
    count(*) FILTER (WHERE (risk_tier = 'high'::text)) AS risk_high,
    count(*) FILTER (WHERE (risk_tier = 'medium'::text)) AS risk_medium,
    count(*) FILTER (WHERE (risk_tier = 'low'::text)) AS risk_low,
    count(*) FILTER (WHERE dormant) AS dormant_count,
    round(avg(health), 1) AS avg_health
   FROM supplier_health;

CREATE OR REPLACE VIEW public.supplier_perf AS  WITH base AS (
         SELECT l.id AS supplier_id,
            l.company_name,
            COALESCE(l.app_rating, l.rating) AS rating,
            ( SELECT count(*) AS count
                   FROM inquiry_matches m
                  WHERE (m.supplier_id = l.id)) AS matched,
            ( SELECT count(*) AS count
                   FROM quotes q
                  WHERE (q.supplier_id = l.id)) AS quoted,
            ( SELECT count(*) AS count
                   FROM inquiries i
                  WHERE (i.hired_supplier_id = l.id)) AS won,
            ( SELECT count(*) AS count
                   FROM reviews r
                  WHERE (r.supplier_id = l.id)) AS review_count
           FROM leads l
          WHERE (l.claimed = true)
        )
 SELECT supplier_id,
    company_name,
    rating,
    matched,
    quoted,
    won,
    review_count,
    round(((quoted)::numeric / (NULLIF(matched, 0))::numeric), 3) AS quote_rate,
    round(((won)::numeric / (NULLIF(quoted, 0))::numeric), 3) AS win_rate,
    round(((((COALESCE(rating, (0)::numeric) / 5.0) * 0.50) + (COALESCE(((won)::numeric / (NULLIF(quoted, 0))::numeric), (0)::numeric) * 0.35)) + (((LEAST(quoted, (10)::bigint))::numeric / 10.0) * 0.15)), 3) AS perf_score
   FROM base b;

CREATE OR REPLACE VIEW public.supplier_reputation AS  WITH disp AS (
         SELECT transactions.supplier_id,
            count(*) FILTER (WHERE ((transactions.refund_status IS NOT NULL) AND (transactions.refund_status <> 'none'::text))) AS disputes,
            count(*) AS reveals
           FROM transactions
          GROUP BY transactions.supplier_id
        )
 SELECT l.id AS supplier_id,
    l.company_name,
    count(r.id) AS review_count,
    round(avg(r.rating), 2) AS overall,
    round(avg(r.r_communication), 2) AS communication,
    round(avg(r.r_quality), 2) AS quality,
    round(avg(r.r_punctuality), 2) AS punctuality,
    round(avg(r.r_documentation), 2) AS documentation,
    round(avg(r.r_after_sales), 2) AS after_sales,
    round(avg(r.r_compliance), 2) AS compliance,
    COALESCE(sp.quote_rate, (0)::numeric) AS responsiveness,
    COALESCE(d.disputes, (0)::bigint) AS disputes,
        CASE
            WHEN (COALESCE(d.reveals, (0)::bigint) > 0) THEN round(((100.0 * (d.disputes)::numeric) / (d.reveals)::numeric), 1)
            ELSE (0)::numeric
        END AS dispute_rate_pct,
    round(LEAST((100)::numeric, GREATEST((0)::numeric, (((COALESCE(avg(r.rating), (0)::numeric) * (16)::numeric) + (COALESCE(sp.quote_rate, (0)::numeric) * 0.2)) -
        CASE
            WHEN (COALESCE(d.reveals, (0)::bigint) > 0) THEN (((100.0 * (d.disputes)::numeric) / (d.reveals)::numeric) * 0.3)
            ELSE (0)::numeric
        END))), 1) AS reputation_index
   FROM (((leads l
     LEFT JOIN reviews r ON ((r.supplier_id = l.id)))
     LEFT JOIN supplier_perf sp ON ((sp.supplier_id = l.id)))
     LEFT JOIN disp d ON ((d.supplier_id = l.id)))
  GROUP BY l.id, l.company_name, sp.quote_rate, d.disputes, d.reveals;

CREATE OR REPLACE VIEW public.supplier_twin AS  SELECT l.id AS supplier_id,
    l.company_name,
    l.emirate AS home_emirate,
    l.categories AS specialties,
    sp.matched,
    sp.quoted,
    sp.won,
    sp.quote_rate,
    sp.win_rate,
    sp.perf_score,
    rep.reputation_index,
    rep.overall AS avg_rating,
    rep.review_count,
    rep.disputes,
    rep.dispute_rate_pct,
    q.quotes_count,
    q.avg_quote_value,
    q.min_quote_value,
    q.max_quote_value,
    q.avg_response_hours,
    q.busiest_month,
    wq.typical_project_size,
    pr.preferred_regions
   FROM (((((leads l
     LEFT JOIN supplier_perf sp ON ((sp.supplier_id = l.id)))
     LEFT JOIN supplier_reputation rep ON ((rep.supplier_id = l.id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS quotes_count,
            round(avg(qq.quote_amount), 0) AS avg_quote_value,
            min(qq.quote_amount) AS min_quote_value,
            max(qq.quote_amount) AS max_quote_value,
            round(avg((EXTRACT(epoch FROM (qq.created_at - i.created_at)) / 3600.0)), 1) AS avg_response_hours,
            mode() WITHIN GROUP (ORDER BY ((EXTRACT(month FROM qq.created_at))::integer)) AS busiest_month
           FROM (quotes qq
             JOIN inquiries i ON ((i.id = qq.inquiry_id)))
          WHERE (qq.supplier_id = l.id)) q ON (true))
     LEFT JOIN LATERAL ( SELECT round(avg(qq.quote_amount), 0) AS typical_project_size
           FROM (quotes qq
             JOIN inquiries i ON ((i.id = qq.inquiry_id)))
          WHERE ((qq.supplier_id = l.id) AND (i.hired_supplier_id = l.id))) wq ON (true))
     LEFT JOIN LATERAL ( SELECT array_agg(DISTINCT i.emirate) FILTER (WHERE (i.emirate IS NOT NULL)) AS preferred_regions
           FROM (quotes qq
             JOIN inquiries i ON ((i.id = qq.inquiry_id)))
          WHERE (qq.supplier_id = l.id)) pr ON (true));

CREATE OR REPLACE VIEW public.v_ai_agent_health AS  WITH runs AS (
         SELECT agent_runs.agent,
            count(*) FILTER (WHERE (agent_runs.started_at > (now() - '30 days'::interval))) AS runs_30d,
            count(*) FILTER (WHERE ((agent_runs.started_at > (now() - '30 days'::interval)) AND (agent_runs.status = 'error'::text))) AS errors_30d,
            max(agent_runs.started_at) AS last_run
           FROM agent_runs
          GROUP BY agent_runs.agent
        ), acts AS (
         SELECT agent_actions.agent,
            count(*) FILTER (WHERE (agent_actions.created_at > (now() - '30 days'::interval))) AS actions_30d,
            count(*) FILTER (WHERE ((agent_actions.created_at > (now() - '30 days'::interval)) AND (agent_actions.decided_at IS NOT NULL))) AS decided_30d,
            count(*) FILTER (WHERE ((agent_actions.created_at > (now() - '30 days'::interval)) AND (lower(COALESCE(agent_actions.status, ''::text)) = ANY (ARRAY['rejected'::text, 'dismissed'::text, 'declined'::text, 'overridden'::text])))) AS rejected_30d,
            round(avg(agent_actions.confidence) FILTER (WHERE (agent_actions.created_at > (now() - '30 days'::interval))), 1) AS avg_confidence
           FROM agent_actions
          GROUP BY agent_actions.agent
        )
 SELECT COALESCE(r.agent, a.agent) AS agent,
    COALESCE(r.runs_30d, (0)::bigint) AS runs_30d,
    COALESCE(r.errors_30d, (0)::bigint) AS errors_30d,
    r.last_run,
    COALESCE(a.decided_30d, (0)::bigint) AS decided_30d,
    COALESCE(a.rejected_30d, (0)::bigint) AS rejected_30d,
    round(
        CASE
            WHEN (a.actions_30d > 0) THEN (((a.rejected_30d)::numeric / (a.actions_30d)::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 1) AS override_pct,
    a.avg_confidence,
    COALESCE(a.actions_30d, (0)::bigint) AS actions_30d
   FROM (runs r
     FULL JOIN acts a ON ((a.agent = r.agent)))
  ORDER BY (round(
        CASE
            WHEN (a.actions_30d > 0) THEN (((a.rejected_30d)::numeric / (a.actions_30d)::numeric) * (100)::numeric)
            ELSE NULL::numeric
        END, 1)) DESC NULLS LAST, COALESCE(r.runs_30d, (0)::bigint) DESC;

CREATE OR REPLACE VIEW public.v_approval_trace AS  SELECT r.id AS request_id,
    r.organization_id,
    r.entity_type,
    r.entity_id,
    r.status AS request_status,
    r.current_step,
    r.created_at,
    (s.ord)::integer AS step,
    COALESCE((s.step ->> 'key'::text), ('step_'::text || s.ord)) AS step_key,
    COALESCE((s.step ->> 'label'::text), (s.step ->> 'key'::text), ('Step '::text || s.ord)) AS step_label,
    (s.step ->> 'role'::text) AS step_role,
        CASE
            WHEN (d.decision IS NOT NULL) THEN d.decision
            WHEN (r.status = 'rejected'::text) THEN 'blocked'::text
            WHEN (r.status = 'approved'::text) THEN 'approved'::text
            WHEN (s.ord = r.current_step) THEN 'pending'::text
            ELSE 'waiting'::text
        END AS step_status,
    d.decided_by,
    d.decided_at,
    d.note AS decision_note
   FROM (((procurement_approval_request r
     JOIN procurement_approval_policy p ON ((p.id = r.policy_id)))
     CROSS JOIN LATERAL ( SELECT t.ord,
            t.step
           FROM jsonb_array_elements(p.steps) WITH ORDINALITY t(step, ord)) s)
     LEFT JOIN LATERAL ( SELECT (x.value ->> 'decision'::text) AS decision,
            (x.value ->> 'by'::text) AS decided_by,
            ((x.value ->> 'at'::text))::timestamp with time zone AS decided_at,
            (x.value ->> 'note'::text) AS note
           FROM jsonb_array_elements(r.decisions) x(value)
          WHERE (((x.value ->> 'step'::text))::integer = s.ord)
          ORDER BY ((x.value ->> 'at'::text))::timestamp with time zone DESC
         LIMIT 1) d ON (true));

CREATE OR REPLACE VIEW public.v_bi_scorecard AS  WITH latest AS (
         SELECT DISTINCT ON (s.metric_key) s.metric_key,
            s.value,
            s.error,
            s.taken_at
           FROM metric_snapshot s
          ORDER BY s.metric_key, s.taken_at DESC
        )
 SELECT d.metric_key,
    d.label,
    d.domain,
    d.owner_dept,
    l.value,
    d.target,
    d.direction,
        CASE
            WHEN (l.error IS NOT NULL) THEN 'ERROR'::text
            WHEN ((l.value IS NULL) OR (d.target IS NULL)) THEN 'UNMEASURED'::text
            WHEN ((d.direction = 'up'::text) AND (l.value >= d.target)) THEN 'ON_TARGET'::text
            WHEN ((d.direction = 'down'::text) AND (l.value <= d.target)) THEN 'ON_TARGET'::text
            WHEN ((d.direction = 'up'::text) AND (l.value >= (d.target * 0.7))) THEN 'BEHIND'::text
            WHEN ((d.direction = 'down'::text) AND (l.value <= (d.target * 1.3))) THEN 'BEHIND'::text
            ELSE 'OFF_TARGET'::text
        END AS state,
    l.error,
    l.taken_at,
    d.definition
   FROM (metric_definition d
     LEFT JOIN latest l ON ((l.metric_key = d.metric_key)))
  WHERE d.active;

CREATE OR REPLACE VIEW public.v_category_coverage AS  SELECT c.num,
    c.slug AS catalog_slug,
    c.name,
    c.regulated,
    m.agent_slug,
    (m.agent_slug = c.slug) AS agent_is_canonical,
    COALESCE(( SELECT count(*) AS count
           FROM agent_knowledge k
          WHERE ((k.agent_key = ('cat:'::text || c.slug)) AND (k.topic IN ( SELECT knowledge_module_standard.module
                   FROM knowledge_module_standard
                  WHERE knowledge_module_standard.required)))), (0)::bigint) AS standard_modules,
    COALESCE(( SELECT count(*) AS count
           FROM agent_knowledge k
          WHERE (k.agent_key = ('cat:'::text || COALESCE(m.agent_slug, '~none~'::text)))), (0)::bigint) AS legacy_rows_elsewhere,
    ( SELECT count(DISTINCT l.id) AS count
           FROM (lead_trade_map t
             JOIN leads l ON ((l.invite_trades && ARRAY[t.trade_key])))
          WHERE (t.catalog_slug = c.slug)) AS supplier_supply,
        CASE
            WHEN (COALESCE(( SELECT count(*) AS count
               FROM agent_knowledge k
              WHERE ((k.agent_key = ('cat:'::text || c.slug)) AND (k.topic IN ( SELECT knowledge_module_standard.module
                       FROM knowledge_module_standard
                      WHERE knowledge_module_standard.required)))), (0)::bigint) = 14) THEN 'COMPLIANT'::text
            WHEN (m.status = 'mapped'::text) THEN 'MAPPED_NOT_TO_STANDARD'::text
            ELSE 'NO_AGENT'::text
        END AS coverage
   FROM (catalog_supplier_categories c
     LEFT JOIN category_agent_map m ON ((m.catalog_slug = c.slug)));

CREATE OR REPLACE VIEW public.v_category_open AS  SELECT c.num,
    c.slug,
    c.name,
    c.regulated,
    ( SELECT count(DISTINCT l.id) AS count
           FROM (leads l
             JOIN lead_trade_map t ON ((l.invite_trades && ARRAY[t.trade_key])))
          WHERE ((t.catalog_slug = c.slug) AND (l.registration_submitted_at IS NOT NULL) AND (l.approval_status = 'approved'::text) AND COALESCE(l.verified, false))) AS verified_registered_suppliers,
    p.category_open_min_suppliers AS min_required,
    (( SELECT count(DISTINCT l.id) AS count
           FROM (leads l
             JOIN lead_trade_map t ON ((l.invite_trades && ARRAY[t.trade_key])))
          WHERE ((t.catalog_slug = c.slug) AND (l.registration_submitted_at IS NOT NULL) AND (l.approval_status = 'approved'::text) AND COALESCE(l.verified, false))) >= p.category_open_min_suppliers) AS is_open
   FROM (catalog_supplier_categories c
     CROSS JOIN ( SELECT pricing_config.category_open_min_suppliers
           FROM pricing_config
          WHERE (pricing_config.id = 1)) p);

CREATE OR REPLACE VIEW public.v_critical_capability_tests AS  WITH latest AS (
         SELECT DISTINCT ON (agent_runs.agent) agent_runs.agent,
            agent_runs.status,
            agent_runs.started_at
           FROM agent_runs
          ORDER BY agent_runs.agent, agent_runs.started_at DESC
        )
 SELECT capability_key,
    capability,
    owner_dept,
    test_kind,
    test_ref,
    why_critical,
        CASE
            WHEN ((test_kind = 'none'::text) OR (test_ref IS NULL)) THEN 'UNTESTED'::text
            WHEN (test_kind = 'rpc_selftest'::text) THEN 'SELFTEST_ON_BUILD'::text
            WHEN (test_kind = 'scenario'::text) THEN COALESCE(( SELECT
                    CASE
                        WHEN (s.last_result = 'pass'::text) THEN 'PASSING'::text
                        WHEN (s.last_result = 'not_run'::text) THEN 'NEVER_RUN'::text
                        ELSE 'FAILING'::text
                    END AS "case"
               FROM scenario_library s
              WHERE (s.scenario_key = c.test_ref)), 'NEVER_RUN'::text)
            WHEN (test_kind = 'suite'::text) THEN COALESCE(( SELECT
                    CASE
                        WHEN (l.status = 'ok'::text) THEN 'PASSING'::text
                        ELSE 'FAILING'::text
                    END AS "case"
               FROM latest l
              WHERE (l.agent = c.test_ref)), 'NEVER_RUN'::text)
            ELSE 'UNKNOWN'::text
        END AS state,
        CASE
            WHEN ((test_kind = 'suite'::text) AND (COALESCE(( SELECT t.pass_pct
               FROM v_test_matrix t
              WHERE (t.suite = c.test_ref)), (100)::numeric) < (100)::numeric)) THEN true
            ELSE false
        END AS flaky_in_window,
    ( SELECT t.pass_pct
           FROM v_test_matrix t
          WHERE (t.suite = c.test_ref)) AS pass_pct_14d,
    ( SELECT l.started_at
           FROM latest l
          WHERE (l.agent = c.test_ref)) AS last_run
   FROM critical_capability c;

CREATE OR REPLACE VIEW public.v_cron_failing AS  SELECT j.jobname,
    j.schedule,
    j.active,
    count(*) FILTER (WHERE (d.status <> 'succeeded'::text)) AS failed_runs,
    count(*) AS total_runs,
    min(d.start_time) FILTER (WHERE (d.status <> 'succeeded'::text)) AS first_failure,
    max(d.start_time) FILTER (WHERE (d.status <> 'succeeded'::text)) AS last_failure,
    max(d.start_time) FILTER (WHERE (d.status = 'succeeded'::text)) AS last_success,
    "left"((array_agg(d.return_message ORDER BY d.start_time DESC) FILTER (WHERE (d.status <> 'succeeded'::text)))[1], 300) AS last_error
   FROM (cron.job j
     JOIN cron.job_run_details d ON ((d.jobid = j.jobid)))
  WHERE (d.start_time > (now() - '7 days'::interval))
  GROUP BY j.jobname, j.schedule, j.active
 HAVING (count(*) FILTER (WHERE (d.status <> 'succeeded'::text)) > 0);

CREATE OR REPLACE VIEW public.v_cron_stale AS  WITH j AS (
         SELECT job.jobid,
            job.jobname,
            job.schedule,
            split_part(job.schedule, ' '::text, 1) AS m,
            split_part(job.schedule, ' '::text, 2) AS h,
            split_part(job.schedule, ' '::text, 3) AS dom,
            split_part(job.schedule, ' '::text, 5) AS dow
           FROM cron.job
          WHERE job.active
        ), iv AS (
         SELECT j.jobid,
            j.jobname,
            j.schedule,
            j.m,
            j.h,
            j.dom,
            j.dow,
                CASE
                    WHEN ((j.m ~~ '*/%'::text) AND (j.m ~ '^\*/[0-9]+$'::text)) THEN (((substr(j.m, 3))::integer)::double precision * '00:01:00'::interval)
                    WHEN ((j.m ~ '^[0-9]+$'::text) AND (j.h = '*'::text)) THEN '01:00:00'::interval
                    WHEN ((j.h ~~ '*/%'::text) AND (j.h ~ '^\*/[0-9]+$'::text)) THEN (((substr(j.h, 3))::integer)::double precision * '01:00:00'::interval)
                    WHEN (j.dom ~ '^[0-9]+$'::text) THEN '31 days'::interval
                    WHEN (j.dow ~ '^[0-6]$'::text) THEN '7 days'::interval
                    ELSE '1 day'::interval
                END AS every
           FROM j
        ), runs AS (
         SELECT job_run_details.jobid,
            max(job_run_details.start_time) AS last_any,
            min(job_run_details.start_time) AS first_any
           FROM cron.job_run_details
          GROUP BY job_run_details.jobid
        ), act AS (
         SELECT iv.jobid,
            iv.jobname,
            iv.schedule,
            iv.m,
            iv.h,
            iv.dom,
            iv.dow,
            iv.every,
            runs.last_any,
            COALESCE(w.wrapped_at, runs.first_any) AS activated_at
           FROM ((iv
             LEFT JOIN runs ON ((runs.jobid = iv.jobid)))
             LEFT JOIN phase_c_system_execution_wrapper w ON ((w.jobid = iv.jobid)))
        )
 SELECT jobid,
    jobname,
    schedule,
    every,
    activated_at,
    last_any,
        CASE
            WHEN (activated_at IS NULL) THEN 'active with no wrapper and no run ever recorded'::text
            ELSE format('no run of any status since %s; schedule %s means one was due every %s'::text, COALESCE((last_any)::text, 'never'::text), schedule, every)
        END AS why
   FROM act
  WHERE (((activated_at IS NULL) OR (activated_at < (now() - ((2)::double precision * every)))) AND ((last_any IS NULL) OR (last_any < (now() - ((2)::double precision * every)))));

CREATE OR REPLACE VIEW public.v_department_health AS  WITH base AS (
         SELECT d.dept_key,
            d.name AS department,
            d.health_fn
           FROM org_departments d
        ), tasks AS (
         SELECT t.dept_key,
            count(*) AS n,
            count(*) FILTER (WHERE (t.status = 'done'::text)) AS done,
            count(*) FILTER (WHERE (t.status = ANY (ARRAY['failed'::text, 'blocked'::text]))) AS bad
           FROM org_tasks t
          WHERE (t.updated_at > (now() - '14 days'::interval))
          GROUP BY t.dept_key
        ), runs AS (
         SELECT a.department AS dept_key,
            count(*) AS n,
            count(*) FILTER (WHERE (r.status = 'ok'::text)) AS ok
           FROM (agent_runs r
             JOIN org_agents a ON ((a.agent_key = r.agent)))
          WHERE (r.started_at > (now() - '7 days'::interval))
          GROUP BY a.department
        ), scored AS (
         SELECT b.dept_key,
            b.department,
                CASE
                    WHEN ((COALESCE(t.n, (0)::bigint) > 0) AND (COALESCE(r.n, (0)::bigint) > 0)) THEN round(((((100.0 * ((t.done)::numeric + ((((t.n - t.done) - t.bad))::numeric * 0.5))) / (NULLIF(t.n, 0))::numeric) + ((100.0 * (r.ok)::numeric) / (NULLIF(r.n, 0))::numeric)) / (2)::numeric))
                    WHEN (COALESCE(t.n, (0)::bigint) > 0) THEN round(((100.0 * ((t.done)::numeric + ((((t.n - t.done) - t.bad))::numeric * 0.5))) / (NULLIF(t.n, 0))::numeric))
                    WHEN (COALESCE(r.n, (0)::bigint) > 0) THEN round(((100.0 * (r.ok)::numeric) / (NULLIF(r.n, 0))::numeric))
                    ELSE NULL::numeric
                END AS score,
                CASE
                    WHEN ((COALESCE(t.n, (0)::bigint) > 0) AND (COALESCE(r.n, (0)::bigint) > 0)) THEN (((((((('task throughput ('::text || t.done) || ' done of '::text) || t.n) || ', 14d) and run success ('::text) || r.ok) || ' ok of '::text) || r.n) || ', 7d)'::text)
                    WHEN (COALESCE(t.n, (0)::bigint) > 0) THEN (((('task throughput ('::text || t.done) || ' done of '::text) || t.n) || ', 14d); no runs recorded for its staff'::text)
                    WHEN (COALESCE(r.n, (0)::bigint) > 0) THEN (((('run success ('::text || r.ok) || ' ok of '::text) || r.n) || ', 7d); no tasks moved in 14d'::text)
                    ELSE 'no tasks moved and no runs recorded — nothing to measure yet'::text
                END AS basis
           FROM ((base b
             LEFT JOIN tasks t ON ((t.dept_key = b.dept_key)))
             LEFT JOIN runs r ON ((r.dept_key = b.dept_key)))
        )
 SELECT dept_key,
    department,
    GREATEST((0)::numeric, LEAST((100)::numeric, COALESCE(score, (0)::numeric))) AS score,
    basis,
        CASE
            WHEN (score IS NULL) THEN 'no data'::text
            WHEN (score >= (90)::numeric) THEN 'healthy'::text
            WHEN (score >= (70)::numeric) THEN 'watch'::text
            WHEN (score > (0)::numeric) THEN 'at risk'::text
            ELSE 'no data'::text
        END AS status
   FROM scored;

CREATE OR REPLACE VIEW public.v_digital_twin AS  SELECT ( SELECT count(*) AS count
           FROM org_agents
          WHERE org_agents.active) AS employees_active,
    ( SELECT count(*) AS count
           FROM org_departments
          WHERE org_departments.active) AS departments,
    ( SELECT count(*) AS count
           FROM company_goals
          WHERE company_goals.active) AS company_goals,
    ( SELECT count(*) AS count
           FROM catalog_supplier_categories) AS categories_target,
    ( SELECT count(*) AS count
           FROM category_agent_map
          WHERE (category_agent_map.status = 'mapped'::text)) AS categories_covered,
    ( SELECT count(*) AS count
           FROM v_knowledge_compliance
          WHERE (v_knowledge_compliance.verdict = 'COMPLIANT'::text)) AS knowledge_bases_compliant,
    ( SELECT count(*) AS count
           FROM leads) AS suppliers_in_pipeline,
    ( SELECT count(*) AS count
           FROM inquiries) AS inquiries_total,
    ( SELECT count(*) AS count
           FROM quotes) AS quotes_total,
    ( SELECT count(*) AS count
           FROM transactions) AS transactions_total,
    ( SELECT COALESCE(sum(z.amount_aed), (0)::numeric) AS "coalesce"
           FROM ( SELECT (0)::numeric AS amount_aed) z) AS revenue_placeholder,
    ( SELECT count(*) AS count
           FROM org_tasks
          WHERE (org_tasks.status = ANY (ARRAY['assigned'::text, 'in_progress'::text]))) AS work_in_progress,
    ( SELECT count(*) AS count
           FROM org_tasks
          WHERE (org_tasks.status = 'proposed'::text)) AS awaiting_founder,
    ( SELECT count(*) AS count
           FROM risk_register
          WHERE (risk_register.status = 'open'::text)) AS open_risks,
    ( SELECT count(*) AS count
           FROM institutional_memory) AS memories_held,
    ( SELECT count(*) AS count
           FROM company_event
          WHERE (company_event.occurred_at > (now() - '24:00:00'::interval))) AS events_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE (agent_runs.started_at > (now() - '24:00:00'::interval))) AS agent_runs_24h,
    ( SELECT count(*) AS count
           FROM agent_runs
          WHERE ((agent_runs.started_at > (now() - '24:00:00'::interval)) AND (agent_runs.status = 'error'::text))) AS agent_errors_24h,
    ( SELECT count(*) AS count
           FROM spec_backlog
          WHERE (spec_backlog.status = 'pending'::text)) AS open_backlog,
    ( SELECT count(*) AS count
           FROM spec_backlog
          WHERE ((spec_backlog.status = 'pending'::text) AND (spec_backlog.priority = 1))) AS open_p1;

CREATE OR REPLACE VIEW public.v_event_backbone AS  SELECT event_type,
    count(DISTINCT agent_key) AS subscribers,
    ( SELECT count(*) AS count
           FROM company_event e
          WHERE (e.event_type = s.event_type)) AS events_ever,
    ( SELECT count(*) AS count
           FROM company_event e
          WHERE ((e.event_type = s.event_type) AND (e.occurred_at > (now() - '24:00:00'::interval)))) AS events_24h,
    ( SELECT count(*) AS count
           FROM event_delivery d
          WHERE (d.event_type = s.event_type)) AS deliveries,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM company_event e
              WHERE (e.event_type = s.event_type)) = 0) THEN 'NO_EVENTS_EVER'::text
            WHEN (( SELECT count(*) AS count
               FROM event_delivery d
              WHERE (d.event_type = s.event_type)) = 0) THEN 'UNDELIVERED'::text
            ELSE 'LIVE'::text
        END AS state,
    ( SELECT count(*) AS count
           FROM event_rollup r
          WHERE (r.event_type = s.event_type)) AS chains,
    ( SELECT count(*) AS count
           FROM event_rollup r
          WHERE ((r.event_type = s.event_type) AND (r.outcome = ANY (ARRAY['open'::text, 'partial'::text])))) AS chains_open
   FROM event_subscription s
  WHERE active
  GROUP BY event_type
  ORDER BY event_type;

CREATE OR REPLACE VIEW public.v_executions_without_decision_trace AS  SELECT a.id,
    a.action_class,
    a.executor,
    a.correlation_id,
    a.status,
    a.created_at
   FROM (action_execution a
     LEFT JOIN decision_trace d ON ((d.correlation_id = a.correlation_id)))
  WHERE (d.id IS NULL);

CREATE OR REPLACE VIEW public.v_expense_receipt_gap AS  SELECT id,
    vendor,
    amount,
    currency,
    charged_on,
    source,
    doc_name,
    created_at,
    (CURRENT_DATE - charged_on) AS age_days,
    ((doc_name IS NOT NULL) AND (doc_name <> ''::text)) AS document_was_received,
        CASE
            WHEN ((doc_name IS NOT NULL) AND (doc_name <> ''::text)) THEN 'the receipt was received and read but the archive write was refused - re-forward the vendor email to the inbound address to retry'::text
            ELSE 'no receipt document was ever attached to this entry - retrieve the invoice from the vendor billing portal and attach it manually'::text
        END AS remedy
   FROM expense_entries e
  WHERE (doc_path IS NULL)
  ORDER BY charged_on DESC;

CREATE OR REPLACE VIEW public.v_internal_credential_health AS  SELECT id,
    context,
    label,
    is_legacy,
    active,
    COALESCE(array_length(scope, 1), 0) AS scope_size,
    scope,
    use_count,
    last_used_at,
    last_function,
        CASE
            WHEN (last_used_at IS NULL) THEN NULL::integer
            ELSE ((EXTRACT(epoch FROM (now() - last_used_at)) / (86400)::numeric))::integer
        END AS days_since_use,
    ((EXTRACT(epoch FROM (now() - created_at)) / (86400)::numeric))::integer AS age_days,
    rotated_at,
    expires_at,
    (active AND ((last_used_at IS NULL) OR (last_used_at < (now() - '30 days'::interval)))) AS unused_30d,
    (active AND (NOT is_legacy) AND (created_at < (now() - '90 days'::interval)) AND ((rotated_at IS NULL) OR (rotated_at < (now() - '90 days'::interval)))) AS rotation_due
   FROM internal_credential c;

CREATE OR REPLACE VIEW public.v_internal_secret_migration_progress AS  WITH j AS (
         SELECT job.jobid,
            job.jobname,
            job.active,
            (regexp_match(job.command, 'functions/v1/([a-z0-9_]+)'::text))[1] AS target_function,
            (job.command ~ 'key\s*=\s*''inbound_secret'''::text) AS on_shared_secret,
            (regexp_match(job.command, 'key\s*=\s*''(cred_[a-z0-9_]+)'''::text))[1] AS scoped_key
           FROM cron.job
        )
 SELECT ( SELECT count(*) AS count
           FROM j) AS cron_jobs_total,
    ( SELECT count(*) AS count
           FROM j
          WHERE j.on_shared_secret) AS still_on_shared_secret,
    ( SELECT count(*) AS count
           FROM j
          WHERE (j.on_shared_secret AND j.active)) AS still_on_shared_secret_active,
    ( SELECT count(*) AS count
           FROM j
          WHERE (j.scoped_key IS NOT NULL)) AS moved_to_scoped_credential,
    ( SELECT count(DISTINCT j.target_function) AS count
           FROM j
          WHERE (j.on_shared_secret AND (j.target_function IS NOT NULL))) AS functions_still_reachable_by_shared_secret,
    ( SELECT internal_credential.use_count
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)) AS shared_secret_use_count,
    ( SELECT internal_credential.last_used_at
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)) AS shared_secret_last_used,
    ( SELECT internal_credential.last_function
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)) AS shared_secret_last_function,
    ( SELECT count(*) AS count
           FROM internal_credential
          WHERE (internal_credential.active AND (NOT internal_credential.is_legacy))) AS scoped_credentials_issued,
    ((( SELECT count(*) AS count
           FROM j
          WHERE (j.on_shared_secret AND j.active)) = 0) AND (COALESCE(( SELECT internal_credential.last_used_at
           FROM internal_credential
          WHERE (internal_credential.context = 'legacy.shared'::text)), '1970-01-01 00:00:00+00'::timestamp with time zone) < (now() - '7 days'::interval))) AS safe_to_withdraw_shared_secret;

CREATE OR REPLACE VIEW public.v_kb_coverage AS  SELECT c.slug AS category,
    c.name AS label,
    c.num,
    (COALESCE(sum(s.chunks), (0)::numeric))::bigint AS chunks,
        CASE
            WHEN (COALESCE(sum(s.chunks), (0)::numeric) = (0)::numeric) THEN 'gap'::text
            WHEN (COALESCE(sum(s.chunks), (0)::numeric) < (3)::numeric) THEN 'thin'::text
            ELSE 'covered'::text
        END AS status
   FROM (catalog_supplier_categories c
     LEFT JOIN kb_category_stats s ON ((regexp_replace(s.category, '^cat:'::text, ''::text) = c.slug)))
  GROUP BY c.slug, c.name, c.num;

CREATE OR REPLACE VIEW public.v_knowledge_compliance AS  SELECT a.slug AS agent_slug,
    a.name,
    a.agent_class,
    count(k.topic) FILTER (WHERE (k.topic IS NOT NULL)) AS modules_present,
    ( SELECT count(*) AS count
           FROM knowledge_module_standard
          WHERE knowledge_module_standard.required) AS modules_required,
    string_agg(s.module, ', '::text ORDER BY s.ord) FILTER (WHERE (k.topic IS NULL)) AS missing_modules,
        CASE
            WHEN (count(k.topic) FILTER (WHERE (k.topic IS NOT NULL)) = ( SELECT count(*) AS count
               FROM knowledge_module_standard
              WHERE knowledge_module_standard.required)) THEN 'COMPLIANT'::text
            ELSE 'INCOMPLETE'::text
        END AS verdict
   FROM ((category_agents a
     CROSS JOIN knowledge_module_standard s)
     LEFT JOIN agent_knowledge k ON (((k.agent_key = ('cat:'::text || a.slug)) AND (k.topic = s.module))))
  WHERE (s.required AND (a.agent_class <> 'internal_staff'::text))
  GROUP BY a.slug, a.name, a.agent_class;

CREATE OR REPLACE VIEW public.v_legacy_secret_users AS  SELECT function_name,
    count(*) AS uses,
    min(at) AS first_seen,
    max(at) AS last_seen
   FROM internal_credential_audit
  WHERE ((reason = 'legacy_secret_used'::text) AND (at > (now() - '7 days'::interval)))
  GROUP BY function_name
  ORDER BY (count(*)) DESC;

CREATE OR REPLACE VIEW public.v_org_open_tasks AS  SELECT id,
    objective_id,
    dept_key,
    title,
    detail,
    status,
    tier,
    needs_founder,
    result,
    created_at,
    updated_at,
    decided_by,
    action_class,
    attempts,
    last_run_at,
    root_cause,
    assigned_agent,
    priority
   FROM org_tasks t
  WHERE (status <> ALL (ARRAY['done'::text, 'cancelled'::text]));

CREATE OR REPLACE VIEW public.v_os_health AS  SELECT num,
    os_key,
    name,
    owner_agent,
    employees,
    open_tasks,
    round(((open_tasks)::numeric / (NULLIF(employees, 0))::numeric), 2) AS backlog_per_head,
    ( SELECT count(*) AS count
           FROM (org_tasks t
             JOIN os_department od ON ((od.dept_key = t.dept_key)))
          WHERE ((od.os_key = s.os_key) AND (t.status <> 'done'::text) AND (t.created_at < (now() - '14 days'::interval)))) AS stale_tasks,
    ( SELECT round(((100.0 * (count(*) FILTER (WHERE (rc.decision = 'approve'::text)))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS round
           FROM (review_chain rc
             JOIN os_department od ON ((od.dept_key = rc.dept_key)))
          WHERE (od.os_key = s.os_key)) AS review_pass_pct,
    ( SELECT count(*) AS count
           FROM risk_register r
          WHERE (EXISTS ( SELECT 1
                   FROM (os_department od
                     JOIN org_agents a ON ((a.department = od.dept_key)))
                  WHERE ((od.os_key = s.os_key) AND (a.agent_key = r.owner_agent))))) AS open_risks,
    ( SELECT count(*) AS count
           FROM (org_tasks t
             JOIN os_department od ON ((od.dept_key = t.dept_key)))
          WHERE ((od.os_key = s.os_key) AND (t.title ~~ 'KPI missed:%'::text) AND (t.status <> 'done'::text))) AS kpi_gaps,
    budget_aed,
    spent_aed,
    round(((100.0 * spent_aed) / NULLIF(budget_aed, (0)::numeric)), 1) AS budget_pct,
    ( SELECT round(((100.0 * (count(*) FILTER (WHERE t.needs_founder))::numeric) / (NULLIF(count(*), 0))::numeric), 1) AS round
           FROM (org_tasks t
             JOIN os_department od ON ((od.dept_key = t.dept_key)))
          WHERE ((od.os_key = s.os_key) AND (t.status <> 'done'::text))) AS needs_founder_pct
   FROM v_os_scoreboard s;

CREATE OR REPLACE VIEW public.v_os_scoreboard AS  SELECT o.num,
    o.os_key,
    o.name,
    o.owner_agent,
    count(DISTINCT od.dept_key) AS departments,
    count(DISTINCT a.agent_key) AS employees,
    count(DISTINCT t.id) FILTER (WHERE (t.status <> 'done'::text)) AS open_tasks,
    COALESCE(sum(DISTINCT b.monthly_aed), (0)::numeric) AS budget_aed,
    COALESCE(sum(DISTINCT b.spent_aed), (0)::numeric) AS spent_aed,
    count(DISTINCT k.id) FILTER (WHERE k.active) AS kpis,
    count(DISTINCT k.id) FILTER (WHERE (k.active AND (k.measure_sql IS NULL))) AS kpis_unmeasurable
   FROM (((((operating_system o
     LEFT JOIN os_department od ON ((od.os_key = o.os_key)))
     LEFT JOIN org_agents a ON (((a.department = od.dept_key) AND a.active)))
     LEFT JOIN org_tasks t ON ((t.dept_key = od.dept_key)))
     LEFT JOIN department_budget b ON ((b.dept_key = od.dept_key)))
     LEFT JOIN employee_kpi k ON ((k.agent_key = a.agent_key)))
  WHERE o.active
  GROUP BY o.num, o.os_key, o.name, o.owner_agent
  ORDER BY o.num;

CREATE OR REPLACE VIEW public.v_resource_pressure AS  WITH live AS (
         SELECT r.id,
            r.resource,
            r.kind,
            r.owner_dept,
            r.unit,
            r.capacity,
            r.committed,
            r.window_label,
            r.degrade_at_pct,
            r.halt_at_pct,
            r.source_ref,
            r.note,
            r.updated_at,
            r.os_key,
                CASE
                    WHEN (r.source_ref = 'org_agents.max_open_tasks'::text) THEN ( SELECT (count(*))::numeric AS count
                       FROM (v_org_open_tasks t
                         JOIN os_department od ON ((od.dept_key = t.dept_key)))
                      WHERE (od.os_key = r.os_key))
                    ELSE r.committed
                END AS committed_live
           FROM resource_pool r
        )
 SELECT resource,
    kind,
    owner_dept,
    unit,
    capacity,
    committed_live AS committed,
        CASE
            WHEN (capacity > (0)::numeric) THEN round(((100.0 * committed_live) / capacity), 1)
            ELSE NULL::numeric
        END AS used_pct,
        CASE
            WHEN (capacity = (0)::numeric) THEN 'UNSET'::text
            WHEN (((100.0 * committed_live) / capacity) >= (halt_at_pct)::numeric) THEN 'HALT'::text
            WHEN (((100.0 * committed_live) / capacity) >= (degrade_at_pct)::numeric) THEN 'DEGRADE'::text
            ELSE 'OK'::text
        END AS state,
    note
   FROM live;

CREATE OR REPLACE VIEW public.v_supplier_billing AS  WITH cfg AS (
         SELECT s_1.start_date,
            s_1.fee,
            s_1.free_limit,
            COALESCE(( SELECT (lower(a.value) = 'true'::text)
                   FROM app_secrets a
                  WHERE (a.key = 'subscription_honour_12m'::text)), false) AS honour_12m
           FROM fn_supplier_subscription() s_1(fee, currency, period, start_date, free_limit, fee_source, start_source, free_source)
        ), s AS (
         SELECT l.id AS supplier_id,
            l.company_name,
            l.claimed_by AS email,
            l.founding_rank,
            l.subscription_exempt,
            l.subscription_paid_until,
            l.banned,
            l.matching_blocked,
            (COALESCE(l.registration_submitted_at, l.approved_at, l.created_at))::date AS registered_on,
            c.start_date,
            c.fee,
            c.free_limit,
            c.honour_12m
           FROM (leads l
             CROSS JOIN cfg c)
          WHERE ((COALESCE(l.claimed, false) = true) AND (l.approval_status = 'approved'::text))
        ), st AS (
         SELECT s.supplier_id,
            s.company_name,
            s.email,
            s.founding_rank,
            s.subscription_exempt,
            s.subscription_paid_until,
            s.banned,
            s.matching_blocked,
            s.registered_on,
            s.start_date,
            s.fee,
            s.free_limit,
            s.honour_12m,
                CASE
                    WHEN (s.start_date IS NULL) THEN NULL::date
                    WHEN s.honour_12m THEN GREATEST(s.start_date, ((s.registered_on + '1 year'::interval))::date)
                    ELSE s.start_date
                END AS billing_starts_on,
                CASE
                    WHEN (s.start_date IS NOT NULL) THEN (CURRENT_DATE <
                    CASE
                        WHEN s.honour_12m THEN GREATEST(s.start_date, ((s.registered_on + '1 year'::interval))::date)
                        ELSE s.start_date
                    END)
                    ELSE ((s.founding_rank IS NULL) OR (s.founding_rank <= s.free_limit))
                END AS not_yet
           FROM s
        )
 SELECT supplier_id,
    company_name,
    email,
    founding_rank,
    subscription_exempt,
    registered_on,
    subscription_paid_until,
    billing_starts_on,
        CASE
            WHEN subscription_exempt THEN 'exempt'::text
            WHEN not_yet THEN 'not_due'::text
            WHEN ((subscription_paid_until IS NOT NULL) AND (subscription_paid_until >= CURRENT_DATE)) THEN 'active'::text
            WHEN (subscription_paid_until IS NULL) THEN 'due'::text
            ELSE 'past_due'::text
        END AS billing_status,
        CASE
            WHEN subscription_exempt THEN (0)::numeric
            WHEN not_yet THEN (0)::numeric
            WHEN ((subscription_paid_until IS NOT NULL) AND (subscription_paid_until >= CURRENT_DATE)) THEN (0)::numeric
            ELSE fee
        END AS amount_due_aed,
    fee AS annual_fee_aed,
    free_limit
   FROM st;

CREATE OR REPLACE VIEW public.v_supplier_doc_score AS  WITH docs AS (
         SELECT (d.ref_id)::bigint AS lead_id,
            bool_or((d.kind = 'licence'::text)) AS doc_licence,
            bool_or((d.kind = 'catalog'::text)) AS doc_catalog,
            bool_or((d.kind = 'profile'::text)) AS doc_profile,
            (count(*))::integer AS doc_rows
           FROM documents d
          WHERE ((d.ref_table = 'leads'::text) AND (d.ref_id ~ '^[0-9]+$'::text))
          GROUP BY (d.ref_id)::bigint
        ), f AS (
         SELECT l.id AS lead_id,
            l.company_name,
            COALESCE(NULLIF(btrim(l.claimed_by), ''::text), NULLIF(btrim(l.email), ''::text)) AS contact_email,
            l.approval_status,
            COALESCE(l.claimed, false) AS claimed,
            COALESCE(l.banned, false) AS banned,
            l.lifecycle_stage,
            cc.name AS primary_category,
            COALESCE(dd.doc_rows, 0) AS extracted_doc_rows,
            ((COALESCE(btrim(l.license_doc_path), ''::text) <> ''::text) OR COALESCE(dd.doc_licence, false)) AS has_licence,
            ((l.license_expiry IS NOT NULL) AND (l.license_expiry < CURRENT_DATE)) AS licence_expired,
            l.license_expiry,
            (COALESCE(btrim(l.egr_doc_path), ''::text) <> ''::text) AS has_egr,
            (COALESCE(btrim(l.iban_doc_path), ''::text) <> ''::text) AS has_iban,
            (COALESCE(btrim(l.vat_doc_path), ''::text) <> ''::text) AS has_vat_doc,
            ((COALESCE(btrim(l.trn), ''::text) <> ''::text) OR (COALESCE(btrim(l.vat_number), ''::text) <> ''::text)) AS has_vat_no,
            (COALESCE(btrim(l.insurance_doc_path), ''::text) <> ''::text) AS has_insurance,
            ((l.insurance_expiry IS NOT NULL) AND (l.insurance_expiry < CURRENT_DATE)) AS insurance_expired,
            l.insurance_expiry,
            ((COALESCE(btrim(l.company_profile_doc_path), ''::text) <> ''::text) OR COALESCE(dd.doc_profile, false)) AS has_profile,
            ((COALESCE(array_length(l.catalog_doc_paths, 1), 0) > 0) OR COALESCE(dd.doc_catalog, false)) AS has_catalogue,
            (COALESCE(btrim(l.iso_doc_path), ''::text) <> ''::text) AS has_iso,
            ((l.iso_expiry IS NOT NULL) AND (l.iso_expiry < CURRENT_DATE)) AS iso_expired,
            (COALESCE(btrim(l.manufacturer_auth_doc_path), ''::text) <> ''::text) AS has_mfa,
            ((l.manufacturer_auth_expiry IS NOT NULL) AND (l.manufacturer_auth_expiry < CURRENT_DATE)) AS mfa_expired,
            (COALESCE(btrim(l.signed_terms_path), ''::text) <> ''::text) AS has_signed_terms
           FROM (((leads l
             LEFT JOIN docs dd ON ((dd.lead_id = l.id)))
             LEFT JOIN lead_category lc ON (((lc.lead_id = l.id) AND lc.is_primary)))
             LEFT JOIN catalog_supplier_categories cc ON ((cc.slug = lc.slug)))
        ), s AS (
         SELECT f.lead_id,
            f.company_name,
            f.contact_email,
            f.approval_status,
            f.claimed,
            f.banned,
            f.lifecycle_stage,
            f.primary_category,
            f.extracted_doc_rows,
            f.has_licence,
            f.licence_expired,
            f.license_expiry,
            f.has_egr,
            f.has_iban,
            f.has_vat_doc,
            f.has_vat_no,
            f.has_insurance,
            f.insurance_expired,
            f.insurance_expiry,
            f.has_profile,
            f.has_catalogue,
            f.has_iso,
            f.iso_expired,
            f.has_mfa,
            f.mfa_expired,
            f.has_signed_terms,
            ((((((((
                CASE
                    WHEN (f.has_licence AND (NOT f.licence_expired)) THEN 30
                    ELSE 0
                END +
                CASE
                    WHEN f.has_egr THEN 12
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_iban THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_vat_doc THEN 10
                    WHEN f.has_vat_no THEN 5
                    ELSE 0
                END) +
                CASE
                    WHEN (f.has_insurance AND (NOT f.insurance_expired)) THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_profile THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN f.has_catalogue THEN 10
                    ELSE 0
                END) +
                CASE
                    WHEN (f.has_iso AND (NOT f.iso_expired)) THEN 5
                    ELSE 0
                END) +
                CASE
                    WHEN (f.has_mfa AND (NOT f.mfa_expired)) THEN 3
                    ELSE 0
                END) AS score,
            array_remove(ARRAY[
                CASE
                    WHEN (NOT f.has_licence) THEN 'Trade licence (mandatory)'::text
                    WHEN f.licence_expired THEN ('Trade licence EXPIRED on '::text || (f.license_expiry)::text)
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_egr) THEN 'Establishment card'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_iban) THEN 'Bank IBAN letter'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((NOT f.has_vat_doc) AND (NOT f.has_vat_no)) THEN 'VAT certificate / TRN'::text
                    WHEN (NOT f.has_vat_doc) THEN 'VAT certificate (TRN on file, document missing)'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_insurance) THEN 'Insurance certificate'::text
                    WHEN f.insurance_expired THEN ('Insurance certificate EXPIRED on '::text || (f.insurance_expiry)::text)
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_profile) THEN 'Company profile'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_catalogue) THEN 'Product catalogue'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_iso) THEN 'ISO certificate'::text
                    WHEN f.iso_expired THEN 'ISO certificate EXPIRED'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_mfa) THEN 'Manufacturer authorisation'::text
                    WHEN f.mfa_expired THEN 'Manufacturer authorisation EXPIRED'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (NOT f.has_signed_terms) THEN 'Signed Terms & Conditions'::text
                    ELSE NULL::text
                END], NULL::text) AS missing
           FROM f
        )
 SELECT lead_id,
    company_name,
    contact_email,
    primary_category,
    approval_status,
    claimed,
    banned,
    lifecycle_stage,
    score,
        CASE
            WHEN (score >= 85) THEN 'A'::text
            WHEN (score >= 70) THEN 'B'::text
            WHEN (score >= 50) THEN 'C'::text
            WHEN (score >= 25) THEN 'D'::text
            ELSE 'F'::text
        END AS grade,
    cardinality(missing) AS missing_count,
    missing,
    has_licence,
    licence_expired,
    has_egr,
    has_iban,
    has_vat_doc,
    has_vat_no,
    has_insurance,
    insurance_expired,
    has_profile,
    has_catalogue,
    has_iso,
    has_mfa,
    has_signed_terms,
    extracted_doc_rows
   FROM s;

CREATE OR REPLACE VIEW public.v_supply_gap AS  WITH pool AS (
         SELECT c.slug,
            c.name,
            c.num,
            count(DISTINCT lc.lead_id) FILTER (WHERE ((l.email IS NOT NULL) AND (l.email <> ''::text) AND (COALESCE(l.banned, false) = false))) AS sendable,
            count(DISTINCT lc.lead_id) FILTER (WHERE (l.invite_status IS NOT NULL)) AS invited,
            count(DISTINCT lc.lead_id) FILTER (WHERE l.claimed) AS claimed,
            count(DISTINCT lc.lead_id) FILTER (WHERE (l.approval_status = 'approved'::text)) AS approved
           FROM ((catalog_supplier_categories c
             LEFT JOIN lead_category lc ON ((lc.slug = c.slug)))
             LEFT JOIN leads l ON ((l.id = lc.lead_id)))
          GROUP BY c.slug, c.name, c.num
        )
 SELECT slug,
    name,
    num,
    sendable,
    invited,
    claimed,
    approved,
    GREATEST((0)::bigint, (10 - approved)) AS gap_to_target,
    (ceil(((GREATEST((0)::bigint, (10 - approved)))::numeric / 0.05)))::integer AS sendable_needed_at_5pct,
    GREATEST((0)::bigint, ((ceil(((GREATEST((0)::bigint, (10 - approved)))::numeric / 0.05)))::integer - sendable)) AS sendable_shortfall,
        CASE
            WHEN (approved >= 10) THEN 'TARGET MET'::text
            WHEN (sendable = 0) THEN 'NO POOL - must source from scratch'::text
            WHEN (sendable < (ceil(((GREATEST((0)::bigint, (10 - approved)))::numeric / 0.05)))::integer) THEN 'POOL TOO THIN - scrape more'::text
            WHEN (invited = 0) THEN 'READY - not yet invited'::text
            ELSE 'IN PROGRESS'::text
        END AS status
   FROM pool;

CREATE OR REPLACE VIEW public.v_test_matrix AS  SELECT agent AS suite,
    count(*) AS runs_14d,
    count(*) FILTER (WHERE (status = 'ok'::text)) AS passed,
    count(*) FILTER (WHERE (status = 'error'::text)) AS failed,
    round(((100.0 * (count(*) FILTER (WHERE (status = 'ok'::text)))::numeric) / (GREATEST(count(*), (1)::bigint))::numeric)) AS pass_pct,
    max(started_at) AS last_run,
        CASE
            WHEN (count(*) FILTER (WHERE (status = 'error'::text)) = 0) THEN 'PASS'::text
            WHEN (count(*) FILTER (WHERE (status = 'ok'::text)) = 0) THEN 'FAIL'::text
            ELSE 'FLAKY'::text
        END AS verdict
   FROM agent_runs r
  WHERE ((started_at > (now() - '14 days'::interval)) AND ((agent ~~* '%test%'::text) OR (agent ~~* '%eval%'::text) OR (agent ~~* '%qa%'::text) OR (agent ~~* '%exam%'::text) OR (agent ~~* '%smoke%'::text) OR (agent ~~* '%drill%'::text) OR (agent ~~* '%canary%'::text) OR (agent ~~* '%health%'::text)))
  GROUP BY agent;

CREATE OR REPLACE VIEW public.v_ui_label_missing AS  SELECT 'action_kind'::text AS domain,
    a.kind AS key,
    count(*) AS rows_in_use
   FROM (agent_actions a
     LEFT JOIN ui_label l ON (((l.domain = 'action_kind'::text) AND (l.key = a.kind))))
  WHERE ((l.key IS NULL) AND (a.kind IS NOT NULL))
  GROUP BY a.kind
UNION ALL
 SELECT 'notification_type'::text AS domain,
    n.type AS key,
    count(*) AS rows_in_use
   FROM (notifications n
     LEFT JOIN ui_label l ON (((l.domain = 'notification_type'::text) AND (l.key = n.type))))
  WHERE ((l.key IS NULL) AND (n.type IS NOT NULL))
  GROUP BY n.type;

CREATE OR REPLACE VIEW public.v_workflow_side_effects_without_executor AS  SELECT w.workflow_key,
    s.step_no,
    s.action_class
   FROM ((workflow w
     JOIN workflow_step s ON ((s.workflow_key = w.workflow_key)))
     LEFT JOIN org_action_executor e ON (((e.action_class = s.action_class) AND e.active)))
  WHERE (w.active AND (s.action_class IS NOT NULL) AND (e.action_class IS NULL));

CREATE OR REPLACE VIEW public.v_workstream_answer AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    w.active,
    a.id AS answer_id,
    a.field_id,
    a.value,
    a.unit,
    a.scope,
    a.precedence,
    a.source_kind,
    a.confirmed_at,
        CASE
            WHEN (a.scope = 'inquiry_shared'::text) THEN 'shared'::text
            WHEN (EXISTS ( SELECT 1
               FROM inquiry_answer_scope s
              WHERE ((s.answer_id = a.id) AND (s.workstream_id = w.id)))) THEN 'owned'::text
            ELSE 'referenced'::text
        END AS via,
    ((a.value IS NOT NULL) AND (btrim(a.value) <> ''::text) AND (a.precedence <> ALL (ARRAY['model_inference'::answer_precedence, 'unknown'::answer_precedence])) AND ((a.scope = 'inquiry_shared'::text) OR (EXISTS ( SELECT 1
           FROM inquiry_answer_scope s
          WHERE ((s.answer_id = a.id) AND (s.workstream_id = w.id)))))) AS satisfies_mandatory
   FROM (inquiry_workstream w
     JOIN inquiry_answer a ON (((a.group_id = w.group_id) AND (a.superseded_by IS NULL))))
  WHERE ((a.scope = 'inquiry_shared'::text) OR (EXISTS ( SELECT 1
           FROM inquiry_answer_scope s
          WHERE ((s.answer_id = a.id) AND (s.workstream_id = w.id)))) OR (EXISTS ( SELECT 1
           FROM field_definition_reference r
          WHERE ((r.field_id = a.field_id) AND (r.referencing_trade_key = w.trade_key)))));

CREATE OR REPLACE VIEW public.v_workstream_completeness AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    w.active,
    count(*) FILTER (WHERE r.mandatory) AS required_mandatory,
    count(*) FILTER (WHERE (r.mandatory AND va.satisfies_mandatory)) AS answered_mandatory,
    count(*) FILTER (WHERE (NOT r.mandatory)) AS required_optional,
    count(*) FILTER (WHERE ((NOT r.mandatory) AND va.satisfies_mandatory)) AS answered_optional,
    COALESCE(array_agg(r.field_id ORDER BY r.field_id) FILTER (WHERE (r.mandatory AND (NOT COALESCE(va.satisfies_mandatory, false)))), '{}'::text[]) AS missing_mandatory,
    COALESCE(( SELECT array_agg(DISTINCT vc.field_id) AS array_agg
           FROM v_workstream_conflict vc
          WHERE (vc.workstream_id = w.id)), '{}'::text[]) AS blocked_by
   FROM ((inquiry_workstream w
     LEFT JOIN inquiry_workstream_requirement r ON ((r.workstream_id = w.id)))
     LEFT JOIN v_workstream_answer va ON (((va.workstream_id = w.id) AND (va.field_id = r.field_id))))
  GROUP BY w.id, w.group_id, w.trade_key, w.active;

CREATE OR REPLACE VIEW public.v_workstream_conflict AS  SELECT w.id AS workstream_id,
    w.group_id,
    w.trade_key,
    c.id AS conflict_id,
    c.field_id,
    c.blocking_scope,
    c.opened_at
   FROM ((inquiry_workstream w
     JOIN inquiry_answer_conflict c ON (((c.group_id = w.group_id) AND (c.resolved_at IS NULL))))
     JOIN field_definition fd ON ((fd.field_id = c.field_id)))
  WHERE ((fd.scope = 'shared'::text) OR ((fd.scope = 'trade_specific'::text) AND (fd.trade_key = w.trade_key)) OR ((fd.scope = 'trade_subset'::text) AND (EXISTS ( SELECT 1
           FROM field_definition_trade t
          WHERE ((t.field_id = fd.field_id) AND (t.trade_key = w.trade_key))))));

CREATE OR REPLACE VIEW public.v_workstream_dispatch AS  SELECT workstream_id,
    group_id,
    trade_key,
    active,
    required_mandatory,
    answered_mandatory,
    missing_mandatory,
    blocked_by,
    (cardinality(missing_mandatory) = 0) AS mandatory_complete,
    (cardinality(blocked_by) = 0) AS no_unresolved_conflict,
    COALESCE(( SELECT jsonb_object_agg(gr.gate_key, COALESCE(( SELECT (g.state)::text AS state
                   FROM inquiry_gate g
                  WHERE ((g.workstream_id = c.workstream_id) AND (g.gate_key = gr.gate_key))), 'not_evaluated'::text)) AS jsonb_object_agg
           FROM inquiry_gate_required gr
          WHERE (gr.level = 'workstream'::text)), '{}'::jsonb) AS gate_states,
    (NOT (EXISTS ( SELECT 1
           FROM inquiry_gate_required gr
          WHERE ((gr.level = 'workstream'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM inquiry_gate g
                  WHERE ((g.workstream_id = c.workstream_id) AND (g.gate_key = gr.gate_key) AND fn_gate_state_satisfies(g.state))))))))) AS gates_passed,
    (active AND (cardinality(missing_mandatory) = 0) AND (cardinality(blocked_by) = 0) AND (NOT (EXISTS ( SELECT 1
           FROM inquiry_gate_required gr
          WHERE ((gr.level = 'workstream'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM inquiry_gate g
                  WHERE ((g.workstream_id = c.workstream_id) AND (g.gate_key = gr.gate_key) AND fn_gate_state_satisfies(g.state)))))))))) AS dispatch_eligible
   FROM v_workstream_completeness c;

-- ===== FUNCTIONS =====
CREATE OR REPLACE FUNCTION public._next_docver(p_type text, p_id text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select coalesce(max(version),0)+1 from public.doc_versions where entity_type=p_type and entity_id=p_id $function$


CREATE OR REPLACE FUNCTION public._rfq_answered(v text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select v is not null
     and btrim(v) <> ''
     and btrim(v) not in ('[]','{}','-','?')
     and lower(btrim(v)) not in ('null','not sure','unknown','tbd','n/a','na');
$function$


CREATE OR REPLACE FUNCTION public._rfq_concept(k text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when k is null or btrim(k) = '' then null
    -- location first: "emirate / area" is a place, not a quantity
    when k ~ '(location|emirate|address|site|floor|region|area/|/area)' then 'loc'
    when k ~ '(quantity|qty|size|sizes|dimension|dimensions|area|volume|units|linear|count|sqm|sqft)' then 'qty'
    when k ~ '(scope|supply_install|install)'         then 'scope'
    when k ~ '(timeline|schedule|duration|deadline|when)' then 'time'
    when k ~ '(budget|price|cost)'                    then 'budget'
    when k ~ '(finish|material|fabric|fibre|colou?r)' then 'material'
    when k ~ '(item|product|element|service)'         then 'item'
    else null end;
$function$


CREATE OR REPLACE FUNCTION public.a00_llm_attempt_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  raise exception
    'llm_attempt is append-only (attempted % on attempt_id %). A retry inserts a new row with the next attempt_no; it never rewrites an earlier attempt, because first-attempt success rate must stay computable.',
    tg_op, coalesce(old.attempt_id::text,'?')
    using errcode = 'restrict_violation';
end $function$


CREATE OR REPLACE FUNCTION public.add_working_days(d date, n integer)
 RETURNS date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cur date := d; added int := 0;
begin
  while added < n loop
    cur := cur + 1;
    if public.fn_is_working_day(cur) then added := added + 1; end if;
  end loop;
  return cur;
end;$function$


CREATE OR REPLACE FUNCTION public.auth_uid_by_email(p_email text)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'auth', 'public'
AS $function$
  select id from auth.users where lower(email) = lower(p_email) limit 1;
$function$


CREATE OR REPLACE FUNCTION public.block_disposable_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare em text;
begin
  if TG_TABLE_NAME = 'customers' then
    em := NEW.email;
  else
    -- only gate genuine supplier signups; leave scraped leads (claimed false/null) untouched
    if NEW.claimed is distinct from true then return NEW; end if;
    em := coalesce(NEW.claimed_by, NEW.email);
  end if;
  if em is not null and is_disposable_email(em) then
    raise exception 'Please use a permanent email address; temporary inboxes are not allowed.' using errcode = '23514';
  end if;
  return NEW;
end$function$


CREATE OR REPLACE FUNCTION public.dedupe_it_incident()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.agent='it' and NEW.kind='incident' and coalesce(NEW.status,'pending')='pending' then
    if exists (
      select 1 from public.agent_actions a
      where a.agent='it' and a.kind='incident' and a.status='pending'
        and coalesce(a.target_table,'')=coalesce(NEW.target_table,'')
    ) then
      return null; -- duplicate open incident; skip
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.doc_rec(p_sig text, p_cond boolean, p_risk text, p_title text, p_reco text, p_assumptions jsonb DEFAULT NULL::jsonb, p_impact text DEFAULT NULL::text, p_cost text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_cond and not exists (select 1 from agent_actions where kind='doc_task' and detail->>'signal'=p_sig and status in ('pending','needs_review')) then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
    values ('document_controller','doc_task','pending',p_risk,p_title,p_reco,jsonb_build_object('signal',p_sig),'documents',p_sig,p_assumptions,p_impact,p_cost);
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.enqueue_supplier_invites(p_cap integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_site text;
  v_today date := (now() at time zone 'UTC')::date;
  v_planned int; v_used int; v_remaining int; v_subj text; v_body text; v_count int;
  v_inv_recent int; v_bounced_recent int; v_rate numeric; v_max_rate numeric; v_target int; v_cap int;
  v_pause boolean := false; v_why text; v_go boolean; v_pool int;
  v_hol_name text; v_hol_action text; v_hol_end date;
begin
  -- THE CALENDAR THE COMPANY KEEPS ABOUT ITSELF. Checked before anything is planned or written, so
  -- a frozen day leaves no invite_schedule row claiming it planned sends it never made.
  select c.event_name, c.action, c.ends_on into v_hol_name, v_hol_action, v_hol_end
    from public.company_calendar c
   where c.kind = 'public_holiday'
     and v_today between c.starts_on and coalesce(c.ends_on, c.starts_on)
   order by c.starts_on limit 1;
  if v_hol_name is not null then
    insert into agent_runs(agent, status, counts, note, started_at, finished_at)
    values ('supplier_invites', 'ok',
            jsonb_build_object('queued', 0, 'calendar_paused', true, 'resumes_on', coalesce(v_hol_end, v_today) + 1),
            'Invites held: company_calendar has "' || v_hol_name || '" covering today. Its recorded action: '
            || coalesce(v_hol_action, '(none recorded)'), now(), now());
    return 0;
  end if;

  -- THE PLAN, before the gate. The batch is the ramp's cap bounded by the pool that can be written
  -- to today; the row says whether the day is open or held and why.
  -- 6 SEP 2026: the founder's ONE switch for supplier outreach (app_secrets.supplier_outreach_golive) is read
  -- first; invite_enabled stays the deliverability ramp's own gate. Both must be true before an invitation
  -- is written, and the schedule row names what holds the door.
  v_go  := (coalesce((select value from app_secrets where key = 'invite_enabled'), 'false') = 'true')
           and public.fn_supplier_outreach_golive();
  v_cap := coalesce((select nullif(value,'')::int from app_secrets where key='invite_daily_cap'), 10);
  select count(*) into v_pool from leads l
   where l.email is not null and l.email <> '' and l.invite_status is null
     and coalesce(l.source,'') <> 'self_registered' and coalesce(l.claimed,false) = false
     and coalesce(l.banned,false) = false;
  v_planned := least(coalesce(p_cap, v_cap), v_cap, v_pool);
  insert into invite_schedule(day, planned, status, note)
  values (v_today, greatest(v_planned, 0),
          case when v_go then 'approved' else 'pending' end,
          'batch of ' || greatest(v_planned, 0) || ' from a pool of ' || v_pool || ' never-invited lead(s) with an email, cap ' || v_cap
          || case when v_go then '; sending open'
                  when not public.fn_supplier_outreach_golive() then '; HELD — real invitations wait for the founder''s go (app_secrets.supplier_outreach_golive is false)'
                  else '; HELD — real invitations wait for the founder''s go (app_secrets.invite_enabled)' end)
    on conflict (day) do update
      set planned = excluded.planned, status = excluded.status, note = excluded.note;

  if not v_go then
    insert into agent_runs(agent, status, counts, note, started_at, finished_at)
    values ('supplier_invites', 'ok',
            jsonb_build_object('queued', 0, 'planned', greatest(v_planned, 0), 'pool', v_pool, 'cap', v_cap, 'held', true),
            'Invites planned and HELD: ' || greatest(v_planned, 0) || ' of a pool of ' || v_pool
            || ' would be queued at cap ' || v_cap || '; '
            || case when not public.fn_supplier_outreach_golive() then 'supplier_outreach_golive' else 'invite_enabled' end
            || ' is false, so nothing was written to the outbox.', now(), now());
    return 0;
  end if;
  if v_planned <= 0 then return 0; end if;

  v_max_rate := coalesce((select nullif(value,'')::numeric from app_secrets where key='invite_max_bounce_rate'), 0.08);
  select count(*) into v_inv_recent from leads where invited_at > now() - interval '3 days';
  select count(*) into v_bounced_recent from leads where invite_status='bounced' and invited_at > now() - interval '3 days';
  v_rate := round(v_bounced_recent::numeric / greatest(v_inv_recent,1), 3);

  if v_inv_recent >= 15 and v_rate > v_max_rate then
    v_pause := true;
    v_why := 'bounce rate '||(v_rate*100)||'% over 3 days ('||v_bounced_recent||'/'||v_inv_recent||') exceeds the '||(v_max_rate*100)||'% limit';
  end if;
  -- SCALES WITH THE RAMP (12 Aug 2026). See the header: five was right at a cap of ten and wrong at
  -- two hundred. greatest() ignores nulls, so both arms are non-null by construction.
  if not v_pause and v_bounced_recent >= greatest(5, ceil(v_inv_recent * v_max_rate)::int) then
    v_pause := true;
    v_why := v_bounced_recent||' hard bounces in 3 days against '||v_inv_recent||' sent. Regardless of rate, that is a list-quality problem';
  end if;

  if v_pause then
    update app_secrets set value='false' where key='invite_enabled';
    update invite_schedule set status = 'pending', note = coalesce(note,'') || '; auto-paused: ' || v_why where day = v_today;
    if not exists (select 1 from founder_alerts where event='invite_paused_bounce' and created_at > now()-interval '24 hours') then
      insert into founder_alerts(level,event,detail,channel)
        values('crit','invite_paused_bounce','Supplier invites AUTO-PAUSED: '||v_why||'. Clean the list before resuming.','system');
      insert into notifications(type,to_email,to_role,channel,subject,body,status)
        values('invite_paused_bounce', coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),'management@quotesdone.com'),'admin','email','Supplier invites paused - deliverability risk','Invites were auto-paused: '||v_why||'. Validate the list, then re-enable.','queued');
    end if;
    return 0;
  end if;

  select coalesce(nullif(btrim(value),''), 'https://quotesdone.com') into v_site
    from app_secrets where key='public_site_url';
  select value into v_subj from app_secrets where key='invite_subject';
  select value into v_body from app_secrets where key='invite_body';
  select count(*) into v_used from notifications where type='supplier_invite' and (created_at at time zone 'UTC')::date = v_today;
  v_remaining := greatest(0, v_planned - v_used);
  if v_remaining <= 0 then return 0; end if;

  v_target := coalesce((select nullif(value,'')::int from app_secrets where key='invite_target_per_category'),
                       (select nullif(value,'')::int from app_secrets where key='invite_target_per_trade'), 10);

  -- MATERIALIZED, 4 Aug 2026, and it is load-bearing. Both CTEs are referenced exactly once, from
  -- inside the correlated subquery in `prio`. Without this keyword Postgres inlines them there and
  -- re-runs the whole leads x lead_subcategory aggregate once per candidate - 19,632 times, twice
  -- over, ~220 s against a 120 s timeout. Neither depends on the outer row, so computing them once
  -- is semantically identical and 54x faster. Do not remove.
  with activated as materialized (
    select ls.domain_slug, count(distinct l.id) ct
    from leads l join lead_subcategory ls on ls.lead_id = l.id
    where coalesce(l.claimed,false) = true
    group by ls.domain_slug
  ),
  under as materialized (
    select d.slug as domain_slug, coalesce(a.ct,0) as have
    from catalog_domains d left join activated a on a.domain_slug = d.slug
    where coalesce(a.ct,0) < v_target
  ),
  cand as (
    select distinct on (lower(l.email)) l.id, l.email, l.company_name, l.claim_token, l.email_domain, l.email_verified
    from leads l
    where l.email is not null and l.email <> '' and l.invite_status is null
      and coalesce(l.source,'') <> 'self_registered' and coalesce(l.claimed,false) = false
      and (public.fn_email_sendable(l.email)->>'ok')::boolean
    order by lower(l.email), l.id
  ),
  prio as (
    select c.id, c.email, c.company_name, c.claim_token, c.email_domain,
      coalesce((select u.domain_slug from lead_subcategory ls join under u on u.domain_slug = ls.domain_slug
                 where ls.lead_id = c.id order by u.have asc, ls.score desc limit 1), '~none') as pdomain,
      case when c.email_verified in ('verified','true') then 0 else 1 end as unverified_rank,
      -- ROLE ADDRESSES LAST (12 Aug 2026). All five bounces to date are role addresses on domains
      -- with live MX, every one flagged email_verified by the scrape, so neither the MX cull nor
      -- that flag protects against them. Not excluded: 5,870 of 19,835 eligible leads publish no
      -- other address and dropping them would drop the supplier. Ranked behind a named human at the
      -- same verification rank, so a run reaches people first and works down to shared inboxes only
      -- when it runs out of them.
      case when split_part(lower(c.email),'@',1) in
             ('info','sales','admin','contact','enquiry','enquiries','inquiry','office','mail',
              'support','hello','marketing','general','accounts','reception','careers','hr')
           then 1 else 0 end as role_rank
    from cand c
  ),
  elig as (
    select id, email, company_name, claim_token from (
      select id, email, company_name, claim_token, pdomain, unverified_rank, role_rank,
        case when pdomain='~none' then 1 else 0 end as is_none,
        row_number() over (partition by pdomain order by unverified_rank, role_rank, id) as rk,
        row_number() over (partition by coalesce(email_domain, split_part(email,'@',2)) order by unverified_rank, role_rank, id) as domain_rk
      from prio
    ) r
    where domain_rk <= 5
    order by is_none, rk, unverified_rank, role_rank, pdomain
    limit v_remaining
  ),
  ins as (
    insert into notifications(type,to_email,to_role,lead_id,subject,body,status,created_at)
    select 'supplier_invite', email, 'supplier', id, v_subj,
           replace(
             replace(v_body, '{{company}}', coalesce(nullif(btrim(company_name),''), 'there')),
             '{{link}}', v_site || '/en/portal?t=' || claim_token::text), 'queued', now()
    from elig returning to_email
  )
  update leads set invite_status='queued', invited_at=now()
  where invite_status is null and lower(email) in (select lower(to_email) from ins);
  get diagnostics v_count = row_count;
  update invite_schedule set sent = sent + v_count where day = v_today;
  insert into agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('supplier_invites', 'ok',
          jsonb_build_object('queued', v_count, 'planned', v_planned, 'pool', v_pool, 'cap', v_cap, 'held', false),
          'Invites: ' || v_count || ' queued of ' || v_planned || ' planned (pool ' || v_pool || ', cap ' || v_cap || ').', now(), now());
  return v_count;
end;
$function$


CREATE OR REPLACE FUNCTION public.ensure_category_agent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists (select 1 from public.category_agents where slug = NEW.slug) then
    insert into public.category_agents(slug, name, active, created_at)
    values (
      NEW.slug,
      coalesce(NEW.name, initcap(replace(NEW.slug, '-', ' '))),
      true,
      now()
    );
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_action_authority_rank(p_level text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_level
    when 'execute_high'   then 3
    when 'execute_medium' then 2
    when 'stop_authority' then 2
    when 'execute_low'    then 1
    when 'advisory'       then 0
    else 0 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_action_execution_set_author()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.author is null then
    new.author := coalesce(new.request->>'actor', new.request->>'requested_by', new.request->>'author');
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_action_holder(p_kind text, p_agent text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select p.authority_role from public.agent_action_kind_policy p
      where p.kind = p_kind and p.authority_role is not null),
    (select d.value->>p_kind from public.decision_policy d
      where d.key = 'action_autonomy'
        and exists (select 1 from public.org_role r
                     where r.role_id = d.value->>p_kind and r.status = 'active')),
    (select od.lead_agent from public.org_agents oa
       join public.org_departments od on od.dept_key = oa.department and od.active
      where oa.agent_key = p_agent limit 1),
    'ceo');
$function$


CREATE OR REPLACE FUNCTION public.fn_action_invoke_collect()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_held int := 0; v_ok int := 0; v_retry int := 0; v_dead int := 0; v_wait int := 0;
        v_status int; v_body text; v_err text; v_good boolean;
begin
  for r in
    select a.id, a.action_class, a.attempts, a.executor,
           (a.response->>'net_request_id')::bigint req,
           coalesce((a.response->>'max_attempts')::int, 1) max_attempts,
           a.started_at
      from public.action_execution a
     where a.status = 'running' and (a.response->>'net_request_id') is not null
  loop
    select status_code, content, error_msg into v_status, v_body, v_err
      from net._http_response where id = r.req;

    if not found then
      if r.started_at < now() - interval '10 minutes' then
        v_status := null; v_err := 'no pg_net response after 10 minutes';
      else
        v_wait := v_wait + 1; continue;
      end if;
    end if;

    -- A 200 IS NOT ENOUGH. quote_compare returned {ok:false,'parse_failed'} at HTTP 200 for weeks.
    v_good := v_status = 200
              and coalesce(v_body,'') <> ''
              and coalesce((nullif(v_body,'')::jsonb ->> 'ok'), 'true') <> 'false';

    -- HELD IS NOT FAILED (3 Sep 2026). An executor that answers 200 {held:true} could not do the
    -- work because the paid model is held open-circuit — the founder's own hold, not a fault. Until
    -- today that answer (or a 502 analytics_llm_unavailable) was retried to max_attempts and then
    -- dead-lettered, twelve times a day, and the resilience watcher paged the founder about his own
    -- hold. The row is PARKED as status='held': no retry, no dead letter, its org_task untouched, and
    -- fn_action_release_held() re-queues every parked row the day a model answers again.
    if v_status = 200 and coalesce(v_body,'') <> '' and pg_input_is_valid(v_body, 'jsonb')
       and coalesce((v_body::jsonb ->> 'held'), 'false') = 'true' then
      update public.action_execution
         set status = 'held', finished_at = null,
             response = coalesce(response,'{}'::jsonb) - 'net_request_id' || jsonb_build_object(
               'invoker','held','at',now(),'http_status',v_status,
               'reason', coalesce(v_body::jsonb ->> 'reason', 'inference_held'))
       where id = r.id;
      v_held := v_held + 1;
      continue;
    end if;

    if v_good then
      update public.action_execution
         set status = 'succeeded', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','succeeded','at',now(),'http_status',v_status,
               'body', left(coalesce(v_body,''), 4000))
       where id = r.id;
      v_ok := v_ok + 1;

      begin
        update public.org_tasks k
           set status = 'done', updated_at = now(), last_run_at = now(),
               -- 5 SEP 2026: a10_org_task_done_needs_a_determination refuses a close with no
               -- deliverable or no decided_by (the org_task lane packet closed the second closing
               -- path). This close carried a summary and no decider, so its next success would
               -- have been refused inside the exception block below and swallowed. The executor's
               -- own response IS the deliverable, and the invoker that ran it is the decider.
               decided_by = coalesce(k.decided_by, 'invoker:' || r.executor),
               result = coalesce(k.result,'{}'::jsonb) || jsonb_build_object(
                 'mode','executed_by_invoker', 'executor', r.executor,
                 'deliverable', left(coalesce(v_body, ''), 4000),
                 'http_status', v_status, 'at', now(),
                 'summary', left(coalesce(v_body,''), 500),
                 -- SIX KEYS, NOT THREE (12 Aug 2026). See the header: action_worker is the largest
                 -- producer in the estate and emits `outcome`, which none of the original three
                 -- matched, so 254 of 556 invocations in 7 days closed their task with a NULL
                 -- deliverable while carrying real work in the body. Appended, never reordered, so
                 -- anything extracting correctly today is untouched.
                 'deliverable', case
                    when pg_input_is_valid(coalesce(v_body,''), 'jsonb') then coalesce(
                      nullif(btrim(coalesce((v_body::jsonb)->>'recommendation','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'deliverable','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'note','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'outcome','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'summary','')),''),
                      nullif(btrim(coalesce((v_body::jsonb)->>'result','')),''))
                    else nullif(btrim(coalesce(v_body,'')),'') end)
         where k.id = (select (a.request->>'org_task_id')::bigint from public.action_execution a where a.id = r.id)
           and k.status in ('assigned','in_progress');
      exception when others then
        update public.action_execution
           set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'org_task_close', 'refused', 'reason', left(SQLERRM, 400))
         where id = r.id;
      end;
    elsif coalesce(r.attempts,1) < r.max_attempts then
      update public.action_execution
         set status = 'queued',
             response = coalesce(response,'{}'::jsonb) - 'net_request_id' || jsonb_build_object(
               'invoker','retrying','at',now(),'http_status',v_status,
               'error', left(coalesce(v_err, v_body, 'unknown'), 500))
       where id = r.id;
      v_retry := v_retry + 1;
    else
      update public.action_execution
         set status = 'failed', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'http_status',v_status,
               'error', left(coalesce(v_err, v_body, 'unknown'), 500))
       where id = r.id;
      insert into public.dead_letter(source, source_id, kind, reason, payload, first_failed_at, attempts)
      values ('fn_action_invoke_collect', r.id::text, r.action_class,
              left(coalesce(v_err, v_body, 'http ' || coalesce(v_status::text,'?')), 500),
              jsonb_build_object('executor', r.executor, 'http_status', v_status,
                                 'body', left(coalesce(v_body,''), 2000)),
              now(), coalesce(r.attempts,1));
      v_dead := v_dead + 1;
    end if;
  end loop;

  return jsonb_build_object('succeeded', v_ok, 'retrying', v_retry, 'dead_lettered', v_dead, 'held', v_held,
                            'still_in_flight', v_wait, 'ran_at', now());
end
$function$


CREATE OR REPLACE FUNCTION public.fn_action_invoke_dispatch(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_req bigint; v_sent int := 0; v_refused int := 0; v_skipped int := 0;
        v_url text; v_secret text; v_ref text; v_key text;
        v_awaiting int := 0; v_appr record; v_resolved jsonb; v_entitled text;
        v_amount numeric; v_spend jsonb;   -- D8: amount-aware spend routing
begin
  select value into v_secret from app_secrets where key = 'cred_action_invoker';
  if v_secret is null then
    return jsonb_build_object('error', 'no cred_action_invoker credential', 'ran_at', now());
  end if;
  select value into v_ref from app_secrets where key = 'project_ref';
  if v_ref is null then
    select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
      from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
  end if;
  if v_ref is null then return jsonb_build_object('error','cannot determine project ref','ran_at',now()); end if;

  for r in
    select a.id, a.action_class, a.request, a.idempotency_key, a.attempts,
           e.target, e.kind, e.active, e.risk_tier, e.advisory_safe, e.reversible,
           e.required_authority, e.compensation_action_class, e.idempotency_strategy, e.params,
           e.notifies_human, e.unattended_ok, e.department, e.second_authority,
           coalesce(e.timeout_seconds, 60) timeout_seconds, coalesce(e.max_attempts, 1) max_attempts
      from public.action_execution a
      join public.org_action_executor e on e.action_class = a.action_class
     where a.status = 'queued' and e.kind = 'edge'
     order by a.created_at
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    -- ---- D9.1: a queuing employee blocked by an open remediation cannot act autonomously ----------
    if coalesce(r.request->>'actor','') <> ''
       and coalesce((public.fn_agent_autonomy_blocked(r.request->>'actor')->>'blocked')::boolean, false) then
      update public.action_execution
         set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','refused','at',now(),
               'reason','the queuing employee ('||(r.request->>'actor')||') is blocked from autonomous action by an open remediation')
       where id = r.id;
      v_refused := v_refused + 1;
      continue;
    end if;

    -- ---- absolute refusals: inactive, founder-reserved (refunds), irreversible-with-no-undo -----
    if not r.active
       or coalesce(r.required_authority,'') = 'founder'
       or (not r.reversible and r.compensation_action_class is null) then
      update public.action_execution
         set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker', 'refused', 'at', now(),
               'reason', case
                 when not r.active then 'executor row is inactive'
                 when coalesce(r.required_authority,'') = 'founder' then 'reserved to the founder'
                 else 'not reversible and declares no compensation_action_class' end)
       where id = r.id;
      v_refused := v_refused + 1;
      continue;
    end if;

    -- ---- D8.2: a request carrying an amount must clear fn_check_spend before anything else ---------
    v_amount := coalesce(nullif(r.request->>'amount_aed',''), nullif(r.request->>'amount',''))::numeric;
    if v_amount is not null then
      v_spend := public.fn_check_spend(coalesce(r.department,'finance'), v_amount, r.request->>'actor');
      if not coalesce((v_spend->>'ok')::boolean, false) then
        update public.action_execution
           set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'invoker','refused','at',now(),'reason',v_spend->>'reason','spend',v_spend)
         where id = r.id;
        v_refused := v_refused + 1;
        continue;
      elsif (v_spend->>'route_to') = 'founder' then
        update public.action_execution
           set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'invoker','awaiting_founder_approval','at',now(),
                 'reason','spend over AED 10,000 is the founder''s to authorise, not an AI head''s','spend',v_spend)
         where id = r.id;
        begin
          perform public.fn_notify_founder('Spend approval needed: '||r.action_class||' AED '||v_amount,
            coalesce(v_spend->>'reason',''), 'high', p_kind => 'spend_approval_needed');
        exception when others then null; end;
        v_awaiting := v_awaiting + 1;
        continue;
      else
        update public.action_execution set response = coalesce(response,'{}'::jsonb) || jsonb_build_object('spend', v_spend)
         where id = r.id;
      end if;
    end if;

    -- ---- the AI-managerial middle tier. D8.3: a named second_authority always forces this branch ---
    if r.second_authority is not null
       or not (r.risk_tier = 'low' and r.advisory_safe and r.reversible
               and not (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))) then
      select * into v_appr from public.action_approval where action_execution_id = r.id;

      if found and v_appr.approval_decision = 'approved' and v_appr.consumed_at is null
         and (r.second_authority is null or v_appr.second_approval_decision = 'approved') then
        update public.action_approval set consumed_at = now() where action_execution_id = r.id;
      elsif found and (v_appr.approval_decision = 'rejected'
                       or v_appr.second_approval_decision = 'rejected') then
        update public.action_execution
           set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'invoker','refused','at',now(),
                 'approver', coalesce(v_appr.approver_role, v_appr.second_approver_role),
                 'reason','an accountable AI approver rejected this action: '
                          ||coalesce(nullif(v_appr.reason,''),'no reason recorded'))
         where id = r.id;
        v_refused := v_refused + 1;
        continue;
      else
        v_resolved := public.fn_action_resolve_approver(r.department, r.risk_tier);
        v_entitled := v_resolved->>'approver';
        insert into public.action_approval
          (action_execution_id, action_class, department, accountable_approver,
           approval_decision, risk_tier, authority_basis, second_authority, second_approval_decision)
        values (r.id, r.action_class, r.department, coalesce(v_entitled,'(unresolved)'),
                'requested', r.risk_tier, v_resolved->>'basis', r.second_authority,
                case when r.second_authority is not null then 'requested' end)
        on conflict (action_execution_id) do nothing;
        update public.action_execution
           set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'invoker', case when r.second_authority is not null then 'awaiting_two_approvals'
                                 else 'awaiting_head_approval' end,
                 'at',now(), 'entitled_approver', v_entitled,
                 'second_authority', r.second_authority, 'risk_tier', r.risk_tier,
                 'basis', v_resolved->>'basis')
         where id = r.id;
        v_awaiting := v_awaiting + 1;
        continue;
      end if;
    end if;

    -- ---- idempotency ------------------------------------------------------------------------------
    v_key := coalesce(nullif(btrim(r.idempotency_key),''),
                      r.action_class || ':' || md5(coalesce(r.request::text,'')));
    if r.idempotency_strategy is distinct from 'none_read_only'
       and exists (select 1 from public.action_execution x
                    where x.id <> r.id and x.status = 'succeeded'
                      and x.idempotency_key = v_key
                      and x.finished_at > now() - interval '24 hours') then
      update public.action_execution
         set status = 'succeeded', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','deduplicated','at',now(),'idempotency_key',v_key,
               'strategy', r.idempotency_strategy)
       where id = r.id;
      v_skipped := v_skipped + 1;
      continue;
    end if;

    v_url := 'https://' || v_ref || '.supabase.co/functions/v1/' || r.target;
    select net.http_post(
             url := v_url,
             headers := '{"Content-Type":"application/json"}'::jsonb,
             body := coalesce(r.params, '{}'::jsonb) || coalesce(r.request, '{}'::jsonb)
                     || jsonb_build_object('__secret', v_secret),
             timeout_milliseconds := r.timeout_seconds * 1000)
      into v_req;

    update public.action_execution
       set status = 'running', attempts = coalesce(attempts,0) + 1,
           executor = r.target, idempotency_key = v_key,
           started_at = coalesce(started_at, now()),
           response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
             'invoker','dispatched','at',now(),'net_request_id',v_req,'url',v_url,
             'timeout_seconds', r.timeout_seconds, 'attempt', coalesce(r.attempts,0)+1,
             'max_attempts', r.max_attempts)
     where id = r.id;
    v_sent := v_sent + 1;
  end loop;

  return jsonb_build_object('dispatched', v_sent, 'refused', v_refused,
                            'deduplicated', v_skipped, 'awaiting_approval', v_awaiting, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_action_invoke_rpc(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_ran int := 0; v_refused int := 0; v_skipped int := 0; v_failed int := 0; v_deferred int := 0;
        v_key text; v_res jsonb; v_missing boolean; v_required int; v_takes_jsonb boolean; v_arg jsonb;
begin
  for r in
    select a.id, a.action_class, a.request, a.idempotency_key, a.attempts,
           e.target, e.active, e.risk_tier, e.advisory_safe, e.reversible,
           e.required_authority, e.compensation_action_class, e.idempotency_strategy,
           e.notifies_human, e.unattended_ok, e.params
      from public.action_execution a
      join public.org_action_executor e on e.action_class = a.action_class
     where a.status = 'queued' and e.kind = 'rpc'
       -- a deferred execution is not due yet; see (2) in the header
       and coalesce(nullif(a.request->>'not_before','')::timestamptz, now()) <= now()
     order by a.created_at
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    -- THE SAME REFUSALS AS THE EDGE PATH, in the same order and for the same reasons. A SQL
    -- function is not safer than an HTTP call because it is closer to the data; if anything it is
    -- nearer the money. notifies_human is still checked before the risk tier: a message that
    -- should not have been sent cannot be un-sent by a low risk score.
    if not r.active
       or coalesce(r.required_authority,'') = 'founder'
       or (not r.reversible and r.compensation_action_class is null)
       or (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))
       or not (r.risk_tier = 'low' and r.advisory_safe and r.reversible) then
      update public.action_execution
         set response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','refused','at',now(),'kind','rpc',
               'reason', case
                 when not r.active then 'executor row is inactive'
                 when coalesce(r.required_authority,'') = 'founder' then 'reserved to the founder'
                 when (not r.reversible and r.compensation_action_class is null)
                   then 'not reversible and declares no compensation_action_class'
                 when (coalesce(r.notifies_human,false) and not coalesce(r.unattended_ok,false))
                   then 'notifies_human is true and unattended_ok has not been set for this class'
                 else format('risk gate: tier=%s advisory_safe=%s reversible=%s - the invoker runs low/advisory_safe/reversible only',
                             r.risk_tier, r.advisory_safe, r.reversible) end)
       where id = r.id;
      v_refused := v_refused + 1;
      continue;
    end if;

    -- CAN THIS TARGET ACTUALLY BE CALLED? Asked of pg_proc, not assumed from the table. A missing
    -- function, a function that takes the request as one jsonb, and a function needing arguments we
    -- do not have are three different cases and are reported as three different things.
    select (p.oid is null),
           coalesce(p.pronargs - p.pronargdefaults, -1),
           coalesce(p.pronargs = 1 and p.proargtypes[0] = 'jsonb'::regtype::oid, false)
      into v_missing, v_required, v_takes_jsonb
      from (select 1) _
      left join pg_proc p on p.proname = r.target and p.pronamespace = 'public'::regnamespace;

    if v_missing then
      update public.action_execution
         set status = 'failed', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'kind','rpc',
               'error', format('executor target public.%s() does not exist', r.target))
       where id = r.id;
      v_failed := v_failed + 1;
      continue;
    end if;

    if v_required > 0 and not v_takes_jsonb then
      update public.action_execution
         set status = 'failed', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'kind','rpc',
               'error', format('public.%s() requires %s argument(s) with no default, and a workflow step carries none to give it. Take the request as ONE jsonb parameter (the invoker passes params || request || {action_execution_id}), or give the function defaults - do not let the invoker invent them.',
                               r.target, v_required))
       where id = r.id;
      v_failed := v_failed + 1;
      continue;
    end if;

    v_key := coalesce(nullif(btrim(r.idempotency_key),''),
                      r.action_class || ':' || md5(coalesce(r.request::text,'')));
    if r.idempotency_strategy is distinct from 'none_read_only'
       and exists (select 1 from public.action_execution x
                    where x.id <> r.id and x.status = 'succeeded'
                      and x.idempotency_key = v_key
                      and x.finished_at > now() - interval '24 hours') then
      update public.action_execution
         set status = 'succeeded', finished_at = now(),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','deduplicated','at',now(),'kind','rpc','idempotency_key',v_key)
       where id = r.id;
      v_skipped := v_skipped + 1;
      continue;
    end if;

    -- One form for every return shape. A set-returning function yields its rows; a scalar
    -- function in FROM yields exactly one. Wrapped per row so one failing target cannot roll back
    -- the others in this sweep. A jsonb-taking target gets the same body the edge invoker posts.
    begin
      if v_takes_jsonb then
        v_arg := coalesce(r.params, '{}'::jsonb) || coalesce(r.request, '{}'::jsonb)
                 || jsonb_build_object('action_execution_id', r.id);
        execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from public.%I($1) t', r.target)
          into v_res using v_arg;
      else
        execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from public.%I() t', r.target)
          into v_res;
      end if;

      -- (2) THE TARGET ASKED TO BE CALLED BACK LATER. Left queued and dated; not an attempt.
      if jsonb_typeof(v_res->0) = 'object' and (v_res->0) ? 'defer_until'
         and nullif(v_res->0->>'defer_until','') is not null then
        update public.action_execution
           set executor = r.target, idempotency_key = v_key,
               request = coalesce(request,'{}'::jsonb)
                         || jsonb_build_object('not_before', (v_res->0->>'defer_until')::timestamptz),
               response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
                 'invoker','deferred','at',now(),'kind','rpc',
                 'not_before', (v_res->0->>'defer_until')::timestamptz,
                 'defer_reason', left(coalesce(v_res->0->>'reason',''), 500),
                 'deferrals', coalesce((response->>'deferrals')::int, 0) + 1)
         where id = r.id;
        v_deferred := v_deferred + 1;
        continue;
      end if;

      update public.action_execution
         set status = 'succeeded', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             executor = r.target, idempotency_key = v_key,
             started_at = coalesce(started_at, now()),
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','succeeded','at',now(),'kind','rpc','result', v_res)
       where id = r.id;
      v_ran := v_ran + 1;
    exception when others then
      update public.action_execution
         set status = 'failed', finished_at = now(), attempts = coalesce(attempts,0) + 1,
             executor = r.target,
             response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
               'invoker','failed','at',now(),'kind','rpc',
               'error', replace(coalesce(sqlerrm,'unknown'), '''', ''))
       where id = r.id;
      v_failed := v_failed + 1;
    end;
  end loop;

  return jsonb_build_object('ran', v_ran, 'refused', v_refused, 'deduplicated', v_skipped,
                            'failed', v_failed, 'deferred', v_deferred, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_action_policies(p_kind text, p_confidence numeric)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select array_remove(array[
    -- action_autonomy: the standing per-kind rule that decides whether the sweep may clear this
    -- action or the founder must see it. The action's own kind selects the answer.
    (select 'action_autonomy: '||coalesce(p_kind,'(no kind)')||' → '||(d.value->>p_kind)
       from public.decision_policy d
      where d.key = 'action_autonomy' and p_kind is not null and d.value ? p_kind),
    -- confidence_min, against this action's own confidence, so two actions of the same kind read
    -- differently. An action with no confidence says that rather than being left blank.
    (select case when p_confidence is null
              then 'confidence_min '||(d.value#>>'{}')||' — this action records no confidence, so the floor cannot be applied'
              else 'confidence_min '||(d.value#>>'{}')||' — this action '||round(p_confidence, 2)::text
                   ||case when p_confidence < (d.value#>>'{}')::numeric then ', below the floor' else ', at or above the floor' end end
       from public.decision_policy d where d.key = 'confidence_min'),
    -- the chairman doctrine list: an action inside it is not a judgement call.
    (select 'founder_review_gates: '||p_kind||' is on the founder-review list'
       from public.decision_policy d
      where d.key = 'founder_review_gates' and p_kind is not null and d.value ? p_kind)
  ], null);
$function$


CREATE OR REPLACE FUNCTION public.fn_action_release_held()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_n int;
begin
  update public.action_execution
     set status = 'queued',
         response = coalesce(response,'{}'::jsonb) || jsonb_build_object('invoker','released_from_held','at',now())
   where status = 'held';
  get diagnostics v_n = row_count;
  return jsonb_build_object('released', v_n, 'at', now());
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_action_resolve_approver(p_department text, p_risk_tier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_head text; v_head_auth text; v_need int; v_ceo text;
begin
  select lead_agent into v_head from public.org_departments where dept_key = p_department;
  if v_head is null then
    return jsonb_build_object('approver', null, 'basis',
      'no lead_agent recorded for department ' || coalesce(p_department,'(null)'));
  end if;
  v_head := coalesce(public.fn_org_agent_resolve(v_head), v_head);
  select authority_level into v_head_auth
    from public.org_role where runtime_agent_key = v_head and status='active' limit 1;

  v_need := case coalesce(p_risk_tier,'medium') when 'high' then 3 else 2 end;  -- medium/other -> 2

  if public.fn_action_authority_rank(coalesce(v_head_auth,'advisory')) >= v_need then
    return jsonb_build_object('approver', v_head, 'basis',
      format('department head of %s (authority %s) is entitled to approve a %s-risk action',
             p_department, coalesce(v_head_auth,'unset'), coalesce(p_risk_tier,'medium')));
  end if;

  -- head cannot clear this tier: the CEO (execute_high officer) is the accountable approver.
  select runtime_agent_key into v_ceo from public.org_role
    where role_id='ceo' and status='active' limit 1;
  v_ceo := coalesce(v_ceo, 'ceo');
  return jsonb_build_object('approver', v_ceo, 'basis',
    format('%s head lacks authority for a %s-risk action; escalated to the execute_high officer (CEO)',
           p_department, coalesce(p_risk_tier,'high')));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ad_decision_mark_executed(p_id bigint, p_mode text, p_response jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  d      public.ad_decision%rowtype;
  s      public.ad_campaign_state%rowtype;
  p      public.ad_spend_policy%rowtype;
  v_from numeric;
  v_to   numeric;
begin
  select * into d from public.ad_decision where id = p_id for update;
  if not found then raise exception 'ad_decision % does not exist', p_id; end if;
  if d.executed_at is not null then return; end if;

  -- the channel's allocation BEFORE the move
  select * into s from public.ad_campaign_state where campaign_id = d.campaign_id;

  update public.ad_decision set executed_at = now(), execution_mode = p_mode, api_response = p_response where id = p_id;
  update public.ad_campaign_state set
    status = case d.action when 'activate' then 'ACTIVE' when 'pause' then 'PAUSED' else status end,
    daily_budget_aed = case d.action when 'set_daily_budget' then d.amount_aed else daily_budget_aed end,
    started_at = case when d.action = 'activate' then coalesce(started_at, now()) else started_at end,
    updated_at = now()
  where campaign_id = d.campaign_id;

  -- the reallocation ledger: marketing budget between channels, citing the policy that moved it
  if s.campaign_id is null then return; end if;
  v_from := case d.action
              when 'set_daily_budget' then coalesce((d.evidence->>'from')::numeric, s.daily_budget_aed)
              when 'pause'            then case when s.status = 'ACTIVE' then s.daily_budget_aed else 0 end
              when 'activate'         then 0
              else null end;
  v_to   := case d.action
              when 'set_daily_budget' then d.amount_aed
              when 'pause'            then 0
              when 'activate'         then s.daily_budget_aed
              else null end;
  if v_from is null or v_to is null or v_from = v_to then return; end if;

  select * into p from public.ad_spend_policy where policy_key = 'default';
  insert into public.allocation_change (resource, subject, from_value, to_value, reason, policy)
  values ('marketing_budget_channels', d.campaign_id, v_from, v_to,
          format('%s: %s [ad_decision %s executed %s on %s]',
                 d.rule_key, d.reason, d.id, p_mode, coalesce(s.campaign_name, d.campaign_id)),
          format('ad_spend_policy %s, rule %s: target CPL %s AED, kill at %sx, scale step %s%%, '
                 || 'per-campaign %s..%s AED/day, daily cap %s AED, effective ceiling %s AED/day',
                 coalesce(p.policy_key, 'default'), d.rule_key,
                 coalesce(p.target_cpl_aed::text, 'derived from measured campaign data (no founder target, 6 Sep 2026)'), p.kill_multiplier,
                 p.scale_step_pct, p.min_daily_per_campaign_aed, p.max_daily_per_campaign_aed,
                 case when s.is_demo then p.daily_cap_aed else coalesce((public.fn_ads_autospend_state()->>'cap_aed')::numeric, 0) end,
                 public.fn_ad_spend_daily_ceiling(s.is_demo)));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_ad_spend_ceiling_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  s        public.ad_campaign_state%rowtype;
  p        public.ad_spend_policy%rowtype;
  st       jsonb;
  v_ceiling numeric;
  v_total  numeric;
  v_new_budget numeric;
  v_new_active boolean;
begin
  select * into s from public.ad_campaign_state where campaign_id = new.campaign_id;
  if not found then
    raise exception 'AD_SPEND_GUARD: decision for unknown campaign %', new.campaign_id using errcode = '23503';
  end if;
  select * into p from public.ad_spend_policy where policy_key = 'default';

  v_new_budget := case when new.action = 'set_daily_budget' then new.amount_aed else s.daily_budget_aed end;
  v_new_active := case new.action when 'activate' then true when 'pause' then false else (s.status = 'ACTIVE') end;

  if new.action = 'set_daily_budget' and new.amount_aed > p.max_daily_per_campaign_aed then
    raise exception 'AD_SPEND_GUARD: % AED/day on campaign % exceeds the per-campaign maximum of % AED',
      new.amount_aed, new.campaign_id, p.max_daily_per_campaign_aed using errcode = 'P0001';
  end if;
  if new.action = 'activate' and s.daily_budget_aed <= 0 then
    raise exception 'AD_SPEND_GUARD: campaign % cannot be activated with no daily budget', new.campaign_id using errcode = 'P0001';
  end if;

  -- A decision that takes money OFF Meta is always allowed: a pause, or a budget at or below the
  -- current one. The guard exists to stop INCREASES beyond the ceiling; refusing a reduction would
  -- make the pacing arm unable to bring an over-ceiling set back down one campaign at a time (the
  -- first rehearsal hit exactly that).
  if new.action = 'pause' or (new.action = 'set_daily_budget' and new.amount_aed <= s.daily_budget_aed) then
    return new;
  end if;

  -- THE FOUNDER'S GO (4 Sep 2026): real money may only be switched on or raised when his go switch
  -- is 'true', his token exists and his daily cap is a number. Demo campaigns are the sandbox.
  if not s.is_demo then
    st := public.fn_ads_autospend_state();
    if not (st->>'live_allowed')::boolean then
      raise exception 'AD_SPEND_GOLIVE: % on real campaign % refused: % (rule %)',
        new.action, new.campaign_id, st->>'reason', new.rule_key using errcode = 'P0001';
    end if;
  end if;

  v_ceiling := public.fn_ad_spend_daily_ceiling(s.is_demo);
  select coalesce(sum(case when c.campaign_id = new.campaign_id then v_new_budget else c.daily_budget_aed end), 0)
    into v_total
  from public.ad_campaign_state c
  where c.is_demo = s.is_demo
    and (c.status = 'ACTIVE' or c.campaign_id = new.campaign_id)
    and (c.campaign_id <> new.campaign_id or v_new_active);

  if v_total > v_ceiling then
    raise exception 'AD_SPEND_CEILING: % would put % AED/day on Meta against an effective ceiling of % AED/day (campaign %, rule %)',
      new.action, v_total, v_ceiling, new.campaign_id, new.rule_key using errcode = 'P0001';
  end if;
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_ad_spend_daily_ceiling()
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select public.fn_ad_spend_daily_ceiling(false);
$function$


CREATE OR REPLACE FUNCTION public.fn_ad_spend_daily_ceiling(p_demo boolean)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- NOTE the explicit null branch: greatest()/least() IGNORE nulls in Postgres, so
  -- greatest(0, null - x) is 0, not null, and the first cut of this function paced every
  -- campaign to zero whenever no monthly cap was set.
  with st as (select public.fn_ads_autospend_state() j),
  cap as (
    select case
      when p_demo then p.daily_cap_aed
      when (st.j->>'live_allowed')::boolean then (st.j->>'cap_aed')::numeric
      else 0 end as daily_cap, p.*
    from public.ad_spend_policy p, st
    where p.policy_key = 'default')
  select case
    when cap.monthly_cap_aed is null then cap.daily_cap
    else least(
      cap.daily_cap,
      greatest(0, cap.monthly_cap_aed - case when cap.month_label = to_char(now(), 'YYYY-MM') then cap.month_spent_aed else 0 end)
        / greatest(1, (date_trunc('month', now()) + interval '1 month')::date - current_date))
  end
  from cap;
$function$


CREATE OR REPLACE FUNCTION public.fn_add_working_days(p_from timestamp with time zone, p_days integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date; left_ int := greatest(0, coalesce(p_days,0)); tod time; res timestamptz;
begin
  if p_from is null then return null; end if;
  d   := (p_from at time zone 'Asia/Dubai')::date;
  tod := (p_from at time zone 'Asia/Dubai')::time;
  while left_ > 0 loop
    d := d + 1;
    if public.fn_is_working_day(d) then left_ := left_ - 1; end if;
  end loop;
  -- if we consumed no days and landed on a non-working day, roll forward
  while not public.fn_is_working_day(d) loop d := d + 1; end loop;
  res := ((d::text || ' ' || tod::text)::timestamp) at time zone 'Asia/Dubai';
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ads_autospend_state()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with s as (
    select
      coalesce((select lower(trim(value)) from public.app_secrets where key = 'meta_autospend_golive'), 'false') = 'true' as golive,
      coalesce((select length(trim(value)) >= 24 from public.app_secrets where key = 'meta_access_token'), false)        as token_present,
      (select case when trim(value) ~ '^[0-9]+(\.[0-9]+)?$' and trim(value)::numeric > 0 then trim(value)::numeric end
         from public.app_secrets where key = 'meta_daily_budget_cap_aed')                                               as cap_aed
  )
  select jsonb_build_object(
    'golive', golive,
    'token_present', token_present,
    'cap_aed', cap_aed,
    'live_allowed', golive and token_present and cap_aed is not null,
    'reason', case
      when not golive then 'meta_autospend_golive is not ''true'''
      when not token_present then 'meta_access_token is absent'
      when cap_aed is null then 'meta_daily_budget_cap_aed is not a positive number'
      else 'live spend allowed under ' || cap_aed || ' AED/day' end)
  from s;
$function$


CREATE OR REPLACE FUNCTION public.fn_ads_manage(p_demo boolean DEFAULT false, p_run_tag text DEFAULT NULL::text)
 RETURNS SETOF ad_decision
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  p          public.ad_spend_policy%rowtype;
  v_ceiling  numeric;
  v_active   numeric;
  c          record;
  v_cpl      numeric;
  v_learning boolean;
  v_new      numeric;
  v_factor   numeric;
  d          public.ad_decision%rowtype;
  v_target   numeric;
  v_target_src text;
begin
  -- 0. THE FOUNDER'S GO. Real campaigns are not managed at all until his switch, token and cap are
  --    in place: nothing is activated, nothing is raised, and nothing he switched on by hand in Ads
  --    Manager is paused by a manager that has not been given the go. The guard refuses the same
  --    things independently; this early return keeps the ledger free of refused attempts.
  if not p_demo and not (public.fn_ads_autospend_state()->>'live_allowed')::boolean then
    return;
  end if;

  select * into p from public.ad_spend_policy where policy_key = 'default';
  v_ceiling := public.fn_ad_spend_daily_ceiling(p_demo);

  -- 6 Sep 2026 (founder): there is NO founder cost-per-lead target ("that target you ingested i never
  -- actually mentioned it"). With ad_spend_policy.target_cpl_aed NULL the target is DERIVED from measured
  -- campaign data: the median cost per lead of the active campaigns that have results in their freshest
  -- row (3 days). Until at least one campaign has measured leads there is no target: spend with no leads
  -- past learning is still killed, and nothing is scaled.
  if p.target_cpl_aed is not null then
    v_target := p.target_cpl_aed; v_target_src := 'ad_spend_policy';
  else
    select percentile_cont(0.5) within group (order by m.cpl) into v_target
    from public.ad_campaign_state s
    join lateral (
      select case when coalesce(i.results, 0) > 0 then i.spend / i.results else null end as cpl
      from public.meta_insights i where i.campaign_id = s.campaign_id
        and i.synced_at > now() - interval '3 days'
      order by (i.time_window = 'last_30d') desc, i.synced_at desc limit 1
    ) m on true
    where s.is_demo = p_demo and s.status = 'ACTIVE' and m.cpl is not null;
    v_target_src := 'median measured CPL of the active set (no founder target)';
  end if;

  -- 1. PACE. If the active set already exceeds the ceiling, shrink it before judging anyone.
  select coalesce(sum(daily_budget_aed), 0) into v_active
  from public.ad_campaign_state where is_demo = p_demo and status = 'ACTIVE'
    and campaign_id not in (select campaign_id from public.ad_decision where executed_at is null);
  if v_active > v_ceiling then
    -- 4 Sep 2026: this is the "Meta optimizer over cap" moment MASTER_PLAN §4.4 names as the
    -- producer of budget.exceeded (budget_cycle's trigger). The pacing below is the remedy; the
    -- event is the record Finance consumes (cfo, brief). Once per scope per day.
    if not exists (select 1 from public.company_event e
                    where e.event_type = 'budget.exceeded' and e.entity_type = 'ad_spend'
                      and e.entity_id = case when p_demo then 'demo' else 'meta' end
                      and e.occurred_at > now() - interval '24 hours') then
      perform public.fn_emit('budget.exceeded', 'ad_spend', case when p_demo then 'demo' else 'meta' end,
        'ads_autopilot',
        jsonb_build_object('requested_aed', v_active, 'available_aed', v_ceiling,
          'purpose', 'daily Meta ad spend across the active campaign set',
          'reason', format('active daily total %s AED exceeds the effective ceiling %s AED; pacing down', v_active, v_ceiling),
          'run_tag', p_run_tag, 'is_demo', p_demo));
    end if;
    v_factor := v_ceiling / v_active;
    for c in
      select s.*, m.cpl from public.ad_campaign_state s
      left join lateral (
        select case when coalesce(i.results, 0) > 0 then i.spend / i.results else null end as cpl
        from public.meta_insights i where i.campaign_id = s.campaign_id
          and i.synced_at > now() - interval '3 days'
        order by (i.time_window = 'last_30d') desc, i.synced_at desc limit 1
      ) m on true
      where s.is_demo = p_demo and s.status = 'ACTIVE'
        and s.campaign_id not in (select campaign_id from public.ad_decision where executed_at is null)
      order by coalesce(m.cpl, 1e12) asc
    loop
      v_new := greatest(p.min_daily_per_campaign_aed, floor(c.daily_budget_aed * v_factor));
      if v_new < c.daily_budget_aed then
        insert into public.ad_decision (campaign_id, action, amount_aed, rule_key, reason, evidence, run_tag)
        values (c.campaign_id, 'set_daily_budget', v_new, 'pace_down',
                format('active daily total %s AED exceeds the effective ceiling %s AED; scaled by %s', v_active, v_ceiling, round(v_factor, 3)),
                jsonb_build_object('active_total', v_active, 'ceiling', v_ceiling, 'factor', v_factor, 'from', c.daily_budget_aed),
                p_run_tag)
        returning * into d;
        return next d;
        v_active := v_active - c.daily_budget_aed + v_new;
      end if;
    end loop;
    -- if the minimums still do not fit, pause the worst cost-per-lead until they do
    for c in
      select s.*, m.cpl from public.ad_campaign_state s
      left join lateral (
        select case when coalesce(i.results, 0) > 0 then i.spend / i.results else null end as cpl
        from public.meta_insights i where i.campaign_id = s.campaign_id
          and i.synced_at > now() - interval '3 days'
        order by (i.time_window = 'last_30d') desc, i.synced_at desc limit 1
      ) m on true
      where s.is_demo = p_demo and s.status = 'ACTIVE'
      order by coalesce(m.cpl, 1e12) desc
    loop
      exit when v_active <= v_ceiling;
      insert into public.ad_decision (campaign_id, action, rule_key, reason, evidence, run_tag)
      values (c.campaign_id, 'pause', 'pace_pause',
              format('even at minimum budgets the active set (%s AED) exceeds the ceiling (%s AED); pausing the worst cost per lead', v_active, v_ceiling),
              jsonb_build_object('active_total', v_active, 'ceiling', v_ceiling, 'cpl', c.cpl), p_run_tag)
      returning * into d;
      return next d;
      v_active := v_active - least(c.daily_budget_aed, greatest(p.min_daily_per_campaign_aed, floor(c.daily_budget_aed * coalesce(v_factor, 1))));
    end loop;
    return;  -- a pacing tick judges nothing else; the next tick sees the paced set
  end if;

  -- 2. JUDGE every active campaign that has no decision waiting.
  --    D3 (4 Sep 2026): the evidence is the FRESHEST row within 3 days, last_30d preferred over the
  --    lifetime window synced beside it. No fresh row = no data = the campaign is held, exactly like
  --    a learner. meta_sync no longer writes a row when Meta errors or returns nothing, so a missing
  --    or stale row can never read as "spend fell to 0" and pause a winner.
  for c in
    select s.*, m.spend, m.results, m.has_results_field
    from public.ad_campaign_state s
    left join lateral (
      select i.spend, i.results, (i.results is not null) as has_results_field
      from public.meta_insights i where i.campaign_id = s.campaign_id
        and i.synced_at > now() - interval '3 days'
      order by (i.time_window = 'last_30d') desc, i.synced_at desc limit 1
    ) m on true
    where s.is_demo = p_demo and s.status = 'ACTIVE'
      and s.campaign_id not in (select campaign_id from public.ad_decision where executed_at is null)
    order by s.campaign_id
  loop
    v_learning := (c.started_at is null)
                  or (c.started_at > now() - make_interval(days => p.learning_phase_days))
                  or (coalesce(c.spend, 0) < p.learning_min_spend_aed);

    -- tracking gate: spent past the threshold and results are not even reported
    if coalesce(c.spend, 0) >= p.learning_min_spend_aed and not coalesce(c.has_results_field, false) then
      insert into public.ad_decision (campaign_id, action, rule_key, reason, evidence, run_tag)
      values (c.campaign_id, 'pause', 'tracking_gate',
              format('%s AED spent and no results field is reported: conversions are not tracked, so nothing can be judged', c.spend),
              jsonb_build_object('spend', c.spend), p_run_tag)
      returning * into d;
      return next d;
      continue;
    end if;

    if v_learning then
      continue;  -- not judged on its first days, nor without fresh data
    end if;

    v_cpl := case when coalesce(c.results, 0) > 0 then c.spend / c.results else null end;

    -- kill: past learning and the cost per lead is above the multiplier, or spend with no leads
    if v_cpl is null or (v_target is not null and v_cpl > p.kill_multiplier * v_target) then
      insert into public.ad_decision (campaign_id, action, rule_key, reason, evidence, run_tag)
      values (c.campaign_id, 'pause', 'kill_3x',
              case when v_cpl is null
                   then format('%s AED spent past the learning phase with no leads at all', c.spend)
                   else format('cost per lead %s AED is above %s x the %s AED target (%s)', round(v_cpl, 2), p.kill_multiplier, round(v_target, 2), v_target_src) end,
              jsonb_build_object('spend', c.spend, 'results', c.results, 'cpl', v_cpl, 'target_cpl', v_target, 'target_source', v_target_src, 'kill_multiplier', p.kill_multiplier), p_run_tag)
      returning * into d;
      return next d;
      continue;
    end if;

    -- scale: at or under target, room on the campaign and under the ceiling
    if v_target is not null and v_cpl <= v_target and c.daily_budget_aed < p.max_daily_per_campaign_aed then
      v_new := least(p.max_daily_per_campaign_aed,
                     floor(c.daily_budget_aed * (1 + p.scale_step_pct / 100.0)),
                     c.daily_budget_aed + greatest(0, v_ceiling - v_active));
      if v_new > c.daily_budget_aed then
        insert into public.ad_decision (campaign_id, action, amount_aed, rule_key, reason, evidence, run_tag)
        values (c.campaign_id, 'set_daily_budget', v_new, 'scale_winner',
                format('cost per lead %s AED is at or under the %s AED target (%s); raising %s to %s AED/day', round(v_cpl, 2), round(v_target, 2), v_target_src, c.daily_budget_aed, v_new),
                jsonb_build_object('spend', c.spend, 'results', c.results, 'cpl', v_cpl, 'target_cpl', v_target, 'target_source', v_target_src, 'from', c.daily_budget_aed, 'ceiling', v_ceiling, 'active_total', v_active), p_run_tag)
        returning * into d;
        return next d;
        v_active := v_active - c.daily_budget_aed + v_new;
      end if;
    end if;
  end loop;

  -- 3. ACTIVATE never-run paused campaigns that fit under the ceiling.
  if p.auto_activate then
    for c in
      select s.* from public.ad_campaign_state s
      where s.is_demo = p_demo and s.status = 'PAUSED' and s.started_at is null and s.daily_budget_aed > 0
        and s.campaign_id not in (select campaign_id from public.ad_decision where executed_at is null)
      order by s.daily_budget_aed asc
    loop
      exit when v_active + c.daily_budget_aed > v_ceiling;
      insert into public.ad_decision (campaign_id, action, rule_key, reason, evidence, run_tag)
      values (c.campaign_id, 'activate', 'activate',
              format('never run, carries %s AED/day and fits under the %s AED/day ceiling (active total %s)', c.daily_budget_aed, v_ceiling, v_active),
              jsonb_build_object('daily_budget', c.daily_budget_aed, 'ceiling', v_ceiling, 'active_total', v_active), p_run_tag)
      returning * into d;
      return next d;
      v_active := v_active + c.daily_budget_aed;
    end loop;
  end if;
  return;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_hand_to_owner(p_action_id bigint, p_owner text, p_basis text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a record; v_owner text; v_dept text; v_task bigint;
begin
  select * into a from public.agent_actions where id = p_action_id;
  if not found then return null; end if;

  v_owner := coalesce(public.fn_org_agent_resolve(p_owner), public.fn_org_agent_resolve(a.agent));
  select o.department into v_dept from public.org_agents o where o.agent_key = v_owner and o.active;
  if v_dept is null or not exists (select 1 from public.org_departments x where x.dept_key = v_dept and x.active) then
    v_dept := 'exec';
    select x.lead_agent into v_owner from public.org_departments x where x.dept_key = 'exec';
  end if;
  if not exists (select 1 from public.org_agents o where o.agent_key = v_owner and o.active and coalesce(o.available, true)) then
    v_owner := null;   -- a05_org_task_fill_ownership picks the least-loaded colleague
  end if;

  insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, decided_by,
                                action_class, assigned_agent, priority, result)
  values (v_dept, left(coalesce(nullif(a.title, ''), a.kind), 200),
          '[agent_action:' || a.id || '] ' || coalesce(nullif(a.recommendation, ''), a.title, a.kind)
            || E'\n\nRaised by ' || coalesce(a.agent, '?') || ' as ' || a.kind || ' at ' || a.created_at
            || '. ' || p_basis
            || ' Determine it from company knowledge or park it with a reason; only a Stripe refund reaches the founder.',
          'assigned', 'advisory', false, 'fn_agent_action_work_sweep',
          'analysis', v_owner, case when lower(coalesce(a.risk, '')) in ('high', 'critical') then 2 else 1 end,
          jsonb_build_object('source', jsonb_build_object('agent_action_id', a.id, 'kind', a.kind,
                             'basis', p_basis, 'handed_at', now())))
  returning id into v_task;
  return v_task;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_resolve_addressee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_key text;
begin
  if new.agent is null or new.agent = '' then
    new.agent := 'brief';
    new.escalated := true;
    new.escalation_reason := coalesce(new.escalation_reason, 'written with no addressee at all');
    return new;
  end if;

  if exists (select 1 from public.org_agents o where o.agent_key = new.agent and o.active) then
    return new;
  end if;

  v_key := public.fn_org_agent_resolve(new.agent);

  if v_key is null then
    new.detail := coalesce(new.detail, '{}'::jsonb)
                  || jsonb_build_object('addressed_as', new.agent, 'addressee_unresolved', true);
    new.escalated := true;
    new.escalation_reason := coalesce(new.escalation_reason,
      'addressee "' || new.agent || '" is not an employee and no org_agent_alias maps it');
    new.agent := 'brief';
    return new;
  end if;

  new.detail := coalesce(new.detail, '{}'::jsonb) || jsonb_build_object('addressed_as', new.agent);
  new.agent := v_key;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_trace()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Delegates to the shared builder so the UPDATE path and the INSERT path cannot produce
  -- different trace shapes. fn_agent_action_trace_row resolves role, department and manager from
  -- the roster and pulls the knowledge actually retrieved near the decision.
  perform public.fn_agent_action_trace_row(new);
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_trace_ins()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.decided_at is not null then
    perform public.fn_agent_action_trace_row(new);
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_action_work_sweep(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_q int := 0; v_officer int := 0; v_notify int := 0; r record; v_key text; v_escalated int := 0;
        v_fixture int := 0; v_on_fact int := 0; v_handed int := 0; v_notified int := 0; v_officer_handed int := 0;
        v_task bigint; v_tstatus text; v_tagent text; v_tsummary text; v_reason text; v_decisions jsonb;
begin
  -- 1. a fixture is never real work
  update public.agent_actions a
     set status = 'cancelled', decided_at = now(), decided_by = 'fn_agent_action_work_sweep',
         detail = coalesce(a.detail, '{}'::jsonb) || jsonb_build_object(
           'settled_reason', 'fixture', 'settled_by', 'fn_agent_action_work_sweep', 'settled_at', now())
   where a.status in ('pending', 'needs_review')
     and (a.title ilike '%ZZ DEMO%' or a.title ilike '%example.invalid%'
          or a.recommendation ilike '%ZZ DEMO%' or a.detail::text ilike '%example.invalid%' or a.detail::text ilike '%ZZ DEMO%');
  get diagnostics v_fixture = row_count;

  for r in
    select a.id, a.kind,
           (select count(*) from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
               and x.status = 'failed') as failures
      from public.agent_actions a
      join public.org_agents o on o.agent_key = a.agent and o.active
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
     where a.status = 'pending'
       -- Nothing live and nothing already settled for this item...
       and not exists (select 1 from public.action_execution x
                        where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                          and x.status in ('queued','running','succeeded'))
       -- ...and fewer than two attempts have failed. Equality, not LIKE: `_` is a single-character
       -- wildcard in LIKE and 'agent_action:' is full of them, so `like 'agent_action:'||id` would
       -- also match keys this function never wrote.
       and (select count(*) from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
               and x.status = 'failed') < 2
     order by a.created_at
     limit greatest(coalesce(p_limit, 10), 1)
  loop
    v_key := 'agent_action:' || r.id || case when r.failures >= 1 then '#2' else '' end;
    insert into public.action_execution(id, correlation_id, action_class, executor, idempotency_key,
                                        risk_tier, reversible, request, status, attempts)
    values (gen_random_uuid(), gen_random_uuid(), 'agent_action_work', 'action_worker',
            v_key, 'low', true,
            jsonb_build_object('action_id', r.id, 'kind', r.kind,
                               'source', 'fn_agent_action_work_sweep',
                               'attempt', r.failures + 1),
            'queued', 0)
    on conflict (idempotency_key) do nothing;
    v_q := v_q + 1;
  end loop;

  -- 2. AUTO kinds the worker could not settle go to their owner through the org_task lane
  for r in
    select a.id, a.kind, a.agent, a.detail, a.status, a.escalation_reason,
           nullif(regexp_replace(coalesce(a.detail->>'task_id', ''), '[^0-9]', '', 'g'), '')::bigint as task_id,
           exists (select 1 from public.org_agents o where o.agent_key = a.agent and o.active) as agent_active,
           (select count(*) from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
               and x.status in ('succeeded', 'failed', 'cancelled')) as finished,
           (select count(*) from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
               and x.status = 'failed') as failures,
           (select string_agg(left(coalesce(x.response::text, x.status), 300), ' | ')
              from public.action_execution x
             where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')) as verdict
      from public.agent_actions a
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
     where a.status in ('pending', 'needs_review')
       and not exists (select 1 from public.action_execution x
                        where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                          and x.status in ('queued', 'running'))
     order by a.created_at
  loop
    -- a pending row nobody has attempted is the worker's turn; a needs_review row was held by the action
    -- gate and the worker never takes it, so its review IS the hand-off
    continue when r.status = 'pending' and r.agent_active and r.finished = 0 and r.failures < 2;

    v_task := null; v_tstatus := null;
    if r.task_id is not null then
      select o.id, o.status, coalesce(o.assigned_agent, o.dept_key),
             left(coalesce(o.result->>'summary', o.result->>'deliverable', o.result->'parked'->>'note', ''), 300)
        into v_task, v_tstatus, v_tagent, v_tsummary
        from public.org_tasks o where o.id = r.task_id;
    end if;

    if v_task is not null and v_tstatus in ('done', 'cancelled') then
      v_reason := 'the org_task this reported on (' || v_task || ') is ' || v_tstatus || ' by ' || v_tagent
                  || case when coalesce(v_tsummary, '') = '' then '' else ': ' || v_tsummary end;
      update public.agent_actions
         set status = 'auto_done', decided_at = now(), decided_by = 'fn_agent_action_work_sweep',
             detail = coalesce(detail, '{}'::jsonb) || jsonb_build_object(
               'org_task_id', v_task, 'settled_reason', v_reason,
               'settled_by', 'fn_agent_action_work_sweep', 'settled_at', now())
       where id = r.id;
      v_on_fact := v_on_fact + 1;
    else
      if v_task is null then
        v_task := public.fn_agent_action_hand_to_owner(r.id, r.agent,
                    case when r.status = 'needs_review'
                         then 'The action gate held it for review (' || coalesce(left(r.escalation_reason, 300), 'no reason recorded') || ').'
                         else 'The action_worker could not settle it (' || coalesce(left(r.verdict, 400),
                                case when r.agent_active then 'no attempt recorded' else 'the addressee is no longer an active employee' end) || ').' end);
        v_reason := 'handed to the org_task lane as org_task ' || v_task
                    || case when r.status = 'needs_review' then ': the action gate held it for review and the department is the reviewer'
                            else ': the worker found no company playbook covering it' end
                    || case when r.agent_active then '' else ' and ' || coalesce(r.agent, '?') || ' is no longer an active employee' end;
        v_handed := v_handed + 1;
      else
        v_reason := 'org_task ' || v_task || ' owns this work in the lane (status ' || v_tstatus || ', ' || v_tagent || ')'
                    || case when coalesce(v_tsummary, '') = '' then '' else ': ' || v_tsummary end;
        v_on_fact := v_on_fact + 1;
      end if;
      update public.agent_actions
         set status = 'superseded', decided_at = now(), decided_by = 'fn_agent_action_work_sweep',
             detail = coalesce(detail, '{}'::jsonb) || jsonb_build_object(
               'org_task_id', v_task, 'superseded_by', 'org_task:' || v_task, 'settled_reason', v_reason,
               'settled_by', 'fn_agent_action_work_sweep', 'settled_at', now())
       where id = r.id;
    end if;
  end loop;

  -- OFFICER decisions: route to the accountable AI authority, never the founder. The determination
  -- itself is the authority's own work; this only makes the authority the owner and removes the
  -- founder as the bottleneck.
  for r in
    select a.id, p.authority_role,
           coalesce(ro.runtime_agent_key, p.authority_role) as authority_agent
      from public.agent_actions a
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'officer'
      left join public.org_role ro on ro.role_id = p.authority_role and ro.status = 'active'
     where a.status in ('pending','needs_review','held_for_review','proposed','open')
       and (a.detail->>'routed_at') is null
  loop
    update public.agent_actions
       set agent = coalesce(r.authority_agent, agent),
           escalated = true,
           escalation_reason =
             case when coalesce(escalation_reason,'') = '' then '' else escalation_reason || ' | ' end
             || 'routed to accountable AI authority ' || coalesce(r.authority_role,'(unset)')
             || ' — only refunds require the founder',
           detail = coalesce(detail,'{}'::jsonb) || jsonb_build_object(
                      'routed_at', now(),
                      'routed_to', coalesce(r.authority_agent, r.authority_role),
                      'route_basis', 'officer_policy')
     where id = r.id;
    v_officer := v_officer + 1;
  end loop;

  -- NOTIFY alerts: tell the founder (Stage 4), non-blocking, and hand the response to the authority.
  for r in
    select a.id, a.kind, a.title, a.recommendation, a.risk, a.agent, p.authority_role,
           coalesce(ro.runtime_agent_key, p.authority_role) as authority_agent
      from public.agent_actions a
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'notify'
      left join public.org_role ro on ro.role_id = p.authority_role and ro.status = 'active'
     where a.status in ('pending','needs_review','held_for_review','proposed','open')
       and (a.detail->>'routed_at') is null
  loop
    perform public.fn_notify_founder(
      coalesce(nullif(r.title,''), r.kind),
      coalesce(nullif(r.recommendation,''), nullif(r.title,''), r.kind)
        || E'\n\nRaised by ' || coalesce(r.agent,'?')
        || '. Handling owner: ' || coalesce(r.authority_role,'(unset)')
        || '. This is a notification — open the OS to review; no approval is required of you.',
      case when lower(coalesce(r.risk,'')) in ('high','critical') then 'high' else 'warn' end,
      -- 6 SEP 2026: the action's own kind is the founder_mail_policy key (backup_alert, security_incident,
      -- legal_flag, ...). finance_alert is allowed; the rest open one org_task for the kind's owner role.
      p_kind => r.kind);
    update public.agent_actions
       set agent = coalesce(r.authority_agent, agent),
           detail = coalesce(detail,'{}'::jsonb) || jsonb_build_object(
                      'routed_at', now(),
                      'routed_to', coalesce(r.authority_agent, r.authority_role),
                      'route_basis', 'notify_policy',
                      'founder_notified_at', now())
     where id = r.id;
    v_notify := v_notify + 1;
  end loop;

  -- 3 and 4. a routed notify/officer row is not settled until the authority role HOLDS it: the response
  -- (notify) or the determination (officer) is an org_task assigned to that role's employee, and the
  -- action row closes — 'notified' for a fact he was told, 'superseded' by the task for a determination.
  for r in
    select a.id, a.kind, a.agent, p.policy, p.authority_role,
           coalesce(a.detail->>'routed_to', ro.runtime_agent_key, p.authority_role) as authority_agent
      from public.agent_actions a
      join public.agent_action_kind_policy p on p.kind = a.kind and p.policy in ('notify', 'officer')
      left join public.org_role ro on ro.role_id = p.authority_role and ro.status = 'active'
     where a.status in ('pending','needs_review','held_for_review','proposed','open')
       and (a.detail->>'routed_at') is not null
     order by a.created_at
  loop
    v_task := public.fn_agent_action_hand_to_owner(r.id, r.authority_agent,
                case when r.policy = 'notify'
                     then 'Policy notify: the founder has been told; the response is ' || coalesce(r.authority_role, 'the accountable role') || '''s to own.'
                     else 'Policy officer: the determination is ' || coalesce(r.authority_role, 'the accountable role') || '''s to make, never the founder''s.' end);
    update public.agent_actions
       set status = case when r.policy = 'notify' then 'notified' else 'superseded' end,
           decided_at = now(), decided_by = 'fn_agent_action_work_sweep',
           detail = coalesce(detail, '{}'::jsonb) || jsonb_build_object(
             'org_task_id', v_task, 'superseded_by', 'org_task:' || v_task,
             'settled_reason', case when r.policy = 'notify'
               then 'notified: the founder was told and the response is owned by ' || coalesce(r.authority_role, '?') || ' as org_task ' || v_task
               else 'handed to accountable authority ' || coalesce(r.authority_role, '?') || ' as org_task ' || v_task end,
             'settled_by', 'fn_agent_action_work_sweep', 'settled_at', now())
     where id = r.id;
    if r.policy = 'notify' then v_notified := v_notified + 1; else v_officer_handed := v_officer_handed + 1; end if;
  end loop;

  -- ESCALATE the unclassified: an emitted kind with no agent_action_kind_policy row is owned by no one,
  -- so the sweep can neither settle nor route it. Tell the founder it needs a classification rather than
  -- leaving it to rot unrouted. (0 such rows today, so this notifies no one now.)
  for r in
    select a.id, a.kind, a.title, a.recommendation, a.risk, a.agent from public.agent_actions a
     where a.status in ('pending','needs_review','held_for_review','proposed','open')
       and (a.detail->>'routed_at') is null
       and not exists (select 1 from public.agent_action_kind_policy p where p.kind = a.kind)
  loop
    perform public.fn_notify_founder(
      'Unclassified work item: ' || coalesce(nullif(r.kind,''),'(no kind)'),
      coalesce(nullif(r.title,''), r.kind) || E'\n\nRaised by ' || coalesce(r.agent,'?')
        || '. This kind has no agent_action_kind_policy row, so no employee owns it and the sweep cannot '
        || 'settle or route it. Classify it (auto/officer/notify).',
      'warn', p_kind => 'agent_action_unclassified');
    update public.agent_actions
       set escalated = true,
           escalation_reason = case when coalesce(escalation_reason,'')='' then '' else escalation_reason||' | ' end
                               || 'no agent_action_kind_policy for kind '||coalesce(r.kind,'(none)'),
           detail = coalesce(detail,'{}'::jsonb) || jsonb_build_object('routed_at', now(), 'route_basis', 'escalated_unclassified')
     where id = r.id;
    v_escalated := v_escalated + 1;
  end loop;

  -- 5. proposed decisions go to their department on the same tick
  begin
    v_decisions := public.fn_decision_record_route(null);
  exception when others then
    v_decisions := jsonb_build_object('error', sqlerrm);
  end;

  return jsonb_build_object('queued', v_q, 'officer_routed', v_officer, 'notify_sent', v_notify, 'escalated', v_escalated,
    'fixtures_cancelled', v_fixture, 'settled_on_task_fact', v_on_fact, 'handed_to_owner', v_handed,
    'notified', v_notified, 'officer_handed', v_officer_handed, 'decision_records', v_decisions,
    'ran_at', now(),
    'eligible_remaining', (select count(*) from public.agent_actions a
                             join public.org_agents o on o.agent_key = a.agent and o.active
                             join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
                            where a.status = 'pending'
                              and not exists (select 1 from public.action_execution x
                                               where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                                                 and x.status in ('queued','running','succeeded'))
                              and (select count(*) from public.action_execution x
                                    where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                                      and x.status = 'failed') < 2),
    -- Named separately so "we have stopped trying" is never counted as "we are working on it".
    'exhausted_two_attempts', (select count(*) from public.agent_actions a
                                 join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'auto'
                                where a.status = 'pending'
                                  and (select count(*) from public.action_execution x
                                        where x.idempotency_key in ('agent_action:' || a.id, 'agent_action:' || a.id || '#2')
                                          and x.status = 'failed') >= 2),
    -- No kind routes to the founder any more; this is retained as a tripwire and must read 0.
    'never_auto_settled', (select count(*) from public.agent_actions a
                            join public.agent_action_kind_policy p on p.kind = a.kind and p.policy = 'founder'
                           where a.status = 'pending'),
    'unrouted', (select count(*) from public.agent_actions a
                  where a.status = 'pending'
                    and not exists (select 1 from public.agent_action_kind_policy p where p.kind = a.kind)));
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_actions_fill_alternatives()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- WAS `d record`. A record that is never assigned raises 55000 on the first field reference;
  -- these three are null when the lookup is skipped, and null is answerable.
  v_alts     jsonb;
  v_decision text;
  v_amt      text;
  v_held     boolean;
begin
  -- Nothing to do once every field the caller could supply is already there.
  if NEW.alternatives is not null and NEW.assumptions is not null
     and NEW.expected_impact is not null and NEW.cost is not null then
    return NEW;
  end if;

  if NEW.decision_log_id is not null then
    select l.alternatives, l.decision into v_alts, v_decision
      from public.decision_log l where l.id = NEW.decision_log_id;
  end if;

  if NEW.alternatives is null
     and v_alts is not null
     and v_alts::text not in ('null', '[]', '{}') then
    NEW.alternatives := v_alts;
  end if;

  -- No linked decision, or a decision that recorded nothing: the dispositions this row can take,
  -- with the selected one read from the row's own status and the basis said on the row.
  if NEW.alternatives is null then
    v_held := coalesce(NEW.status, '') in ('needs_review', 'held_for_review', 'pending', 'proposed', 'open');
    NEW.alternatives := jsonb_build_array(
      jsonb_build_object(
        'option', 'act as recommended',
        'selected', not v_held and coalesce(NEW.status, '') not in ('rejected', 'declined', 'dismissed'),
        'basis', 'the recommendation as written: ' || left(coalesce(NEW.recommendation, NEW.title, ''), 160)),
      jsonb_build_object(
        'option', 'hold for human review',
        'selected', v_held,
        'basis', case when NEW.decision_log_id is null
                      then 'no decision_log row is linked; the disposition is read from the action''s own status (' || coalesce(NEW.status, 'unset') || ')'
                      else 'the linked decision recorded no alternatives; the disposition is read from the action''s own status (' || coalesce(NEW.status, 'unset') || ')' end),
      jsonb_build_object(
        'option', 'do nothing and re-measure at the next tick',
        'selected', false,
        'rejected_because', 'the condition this action reports (' || left(coalesce(NEW.title, ''), 120) || ') persists until acted on'));
  end if;

  if NEW.assumptions is null then
    NEW.assumptions := jsonb_build_array(
      'The action context recorded in detail is accurate as supplied by ' || coalesce(NEW.agent, 'the agent') || '.',
      'fn_should_escalate and fn_authorize were evaluated on that context'
        || case when v_decision is not null then ' and returned ' || v_decision || '.' else '.' end);
  end if;

  if NEW.expected_impact is null then
    NEW.expected_impact := case
      when coalesce(NEW.status, '') in ('needs_review', 'held_for_review')
        then 'Held: nothing changes until a human decides. Until then the condition this action reports remains as it is.'
      else 'Proceeds as recommended: ' || left(coalesce(NEW.recommendation, NEW.title, 'the recommended action'), 220) end;
  end if;

  if NEW.cost is null then
    begin
      v_amt := nullif(to_jsonb(NEW.detail) ->> 'amount_aed', '');
      if v_amt is null then v_amt := nullif(to_jsonb(NEW.detail) ->> 'amount', ''); end if;
    exception when others then v_amt := null; end;
    NEW.cost := case when v_amt is not null
      then 'AED ' || v_amt || ' — the amount carried in this action''s own context.'
      else 'No spend is recorded in this action''s context; the cost is the reviewer''s time.' end;
  end if;

  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_autonomy_blocked(p_agent_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (select coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key) as k)
  select jsonb_build_object(
    'agent_key', (select k from me),
    'asked_as', p_agent_key,
    'blocked', exists (select 1 from agent_remediation
                        where agent_key = (select k from me) and blocks_autonomy and status <> 'passed'),
    'open_remediations', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id, 'failure_class', failure_class, 'competency', competency, 'status', status))
      from agent_remediation where agent_key = (select k from me) and status <> 'passed'), '[]'::jsonb),
    'readiness', coalesce((select jsonb_agg(distinct readiness) from org_role_identity
                            where agent_key = (select k from me)), '[]'::jsonb));
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_context(p_agent_key text, p_max_chars integer, p_query text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text; v_dept text; lib text := ''; ops text := ''; r record; r2 record; v_cat text; catx text := '';
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  out := public.fn_agent_context(p_agent_key, p_max_chars);
  if p_agent_key is null or coalesce(p_query,'') = '' then return out; end if;
  select a.department into v_dept from org_agents a where a.agent_key = p_agent_key;
  -- THE CATEGORY, derived from the task itself (inquiry / run reference, a key, or a catalogue name).
  v_cat := public.fn_category_key_from_text(p_query);

  for r in
    with hits as (
      select 1 as ord, s.* from public.fn_dept_library_search(v_dept, p_query, 4) s
      union all
      select 2 as ord, s.* from public.fn_dept_library_search('company', p_query, 2) s
    ), uniq as (
      select distinct on (id) id, title, content, ord, rank from hits order by id, ord
    )
    select title, content from uniq order by ord, rank desc
  loop
    exit when length(lib) > 2600;
    lib := lib || '## ' || coalesce(r.title,'') || E'\n' || left(coalesce(r.content,''), 700) || E'\n\n';
  end loop;
  -- THE MARKER IS ALWAYS EMITTED. fn_agent_context_capped splits the standing head from the retrieved
  -- tail on '# LAYER 2b'; when the library had no match there was no marker, and the whole retrieved
  -- tail fell past a positional cut instead of being kept inside the 4,500-character reserve.
  if lib <> '' then
    out := out || E'\n' ||
      '# LAYER 2b - YOUR DEPARTMENT REFERENCE LIBRARY (retrieved from dept_library for this task; cite the title in [brackets] when you use it)' ||
      E'\n\n' || lib;
  else
    out := out || E'\n' || '# LAYER 2b - YOUR DEPARTMENT REFERENCE LIBRARY: no dept_library row matched this task.' || E'\n\n';
  end if;

  -- LAYER 2d/2e/2f/2g: the V3 delivery, now WITH the category key when the task names one.
  declare v3 jsonb; sec text := ''; itm jsonb; begin
    v3 := public.fn_agent_context_v3(p_agent_key, null, p_query, v_cat, 9000);

    -- LAYER 2e first: the category pack has to sit inside the reserve the capped path keeps.
    if v_cat is not null and v3 ? 'category_knowledge' then
      for itm in select * from jsonb_array_elements(coalesce(v3->'category_knowledge','[]'::jsonb)) loop
        exit when length(catx) > 1800;
        catx := catx || '## ' || coalesce(itm->>'title','') || ' [' || coalesce(itm->>'record_id','') || ']' || E'\n'
              || left(regexp_replace(coalesce(itm->>'content',''), '\s+', ' ', 'g'), 600) || E'\n\n';
      end loop;
      if catx <> '' then
        out := out || E'\n' ||
          '# LAYER 2e - THE CATEGORY PACK FOR THIS TASK (' || v_cat || '): the route''s qualification playbook, ' ||
          'field and question bank, quality gate and comparison contract. This task is category-scoped; these records ' ||
          'decide what to ask, what may never be inferred and how quotes in this route are compared. Cite the [record_id].' ||
          E'\n\n' || catx;
      end if;
    end if;

    for r2 in
      select title, content, record_type, authority_tier, implementation_status, rank
        from public.fn_ops_knowledge_search(v_dept, p_query, 5)
       order by rank desc
    loop
      exit when length(ops) > 2400;
      ops := ops || '## [' || coalesce(r2.record_type,'record') || ' · authority: ' ||
             coalesce(r2.authority_tier,'?') || ' · ' || coalesce(r2.implementation_status,'?') || '] ' ||
             coalesce(r2.title,'') || E'\n' || left(coalesce(r2.content,''), 700) || E'\n\n';
    end loop;
    if ops <> '' then
      out := out || E'\n' ||
        '# LAYER 2c - HOW THIS COMPANY OPERATES (your department''s own SOPs, decision rules, exception playbooks and KPI definitions). ' ||
        'These OVERRIDE generic practice. Respect the authority tier on each: gated means it needs approval, ' ||
        'supervised means a human reviews it, autonomous means you may act. A record marked target_state describes ' ||
        'a capability the company has NOT built yet — plan around it, do not assume it exists.' ||
        E'\n\n' || ops;
    end if;

    if v3 ? 'role_knowledge' then
      for itm in select * from jsonb_array_elements(v3->'role_knowledge') loop
        exit when length(sec) > 2400;
        sec := sec || '## ' || coalesce(itm->>'title','') || ' [' || coalesce(itm->>'record_id','') || ']' || E'\n'
            || left(coalesce(itm->>'content',''), 700) || E'\n\n';
      end loop;
      if sec <> '' then
        out := out || E'\n' ||
          '# LAYER 2d - YOUR PROFESSIONAL ROLE KNOWLEDGE (the packaged role identity you hold: purpose, ' ||
          'competencies, expert decision checklist and evidence contract). Cite the [record_id] you use.'
          || E'\n\n' || sec;
      end if;
    end if;

    sec := '';
    for itm in select * from jsonb_array_elements(coalesce(v3->'deterministic_rules','[]'::jsonb)) loop
      exit when length(sec) > 2000;
      sec := sec || '- [' || coalesce(itm->>'record_id','') || ' · ' || coalesce(itm->>'layer','') ||
             ' · authority ' || coalesce(itm->>'authority_tier','?') || '] ' || coalesce(itm->>'title','') || E'\n';
    end loop;
    if sec <> '' then
      out := out || E'\n' ||
        '# LAYER 2f - DETERMINISTIC RULES THAT BIND YOU (authority, policy, decision playbooks, KPI ' ||
        'definitions). These are looked up as structured records, never inferred from similarity. If a ' ||
        'rule here contradicts anything above, the rule wins.' || E'\n\n' || sec;
    end if;

    sec := '';
    for itm in select * from jsonb_array_elements(coalesce(v3->'live_data_required','[]'::jsonb)) loop
      exit when length(sec) > 900;
      sec := sec || '- ' || coalesce(itm->>'title','') || E'\n';
    end loop;
    if sec <> '' then
      out := out || E'\n' ||
        '# LAYER 2g - FACTS YOU MUST FETCH, NOT REMEMBER. For each of these the current value comes from ' ||
        'a live authorised tool. Answering one of them from the text above is a wrong answer, however ' ||
        'confident it reads.' || E'\n\n' || sec;
    end if;
    -- The trace has to be able to name what was read. Recorded here because this is where
    -- the assembled context and its record ids are both in scope. A STABLE function may not
    -- execute an INSERT, which is why this one and its caller are now VOLATILE.
    perform public.fn_record_context_retrieval(
      p_agent_key, null, null,
      (select array_agg(x) from jsonb_array_elements_text(coalesce(v3->'knowledge_ids','[]'::jsonb)) x),
      p_max_chars, length(out));
  end;
  return out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_context(p_agent_key text DEFAULT NULL::text, p_max_chars integer DEFAULT 9000)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare out text := ''; r record; piece text; cap int;
        c_keep constant int := 19500;   -- what fn_agent_context_capped keeps of the head at 24,000
        v_room int; l2_cap int; l1_cap int; l3_cap int; l4_cap int; v_used int; v_first boolean;
        v_ops jsonb; v_ops_txt text;
        v_dept text; v_role text; v_charter text; v_north text; v_health_fn text;
        v_status text; v_state jsonb; v_l4 text := '';
        v_emp text := ''; v_loop text := ''; v_title text; v_resp text; v_mgr text; v_sen text; v_plan text;
        v_cap_tasks int; v_line text; v_n int; v_os text;
        v_genome text;
        v_risks text;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  cap := greatest(coalesce(p_max_chars,9000), 22000);
  if p_agent_key is not null then
    select a.department, a.role into v_dept, v_role from org_agents a where a.agent_key=p_agent_key;
    select d.charter, d.north_star, d.health_fn into v_charter, v_north, v_health_fn
      from org_departments d where d.dept_key=v_dept;
    select status into v_status from org_onboarding where agent_key=p_agent_key;
    out := out || '# YOUR IDENTITY AT QUOTESDONE'||E'\n'
      ||'You are '||coalesce(v_role, p_agent_key||' (senior specialist)')
      ||case when v_charter is not null then '. Department charter: '||v_charter else '' end
      ||case when v_north is not null then ' North star: '||v_north||'.' else '' end
      ||' Employment status: '||coalesce(v_status,'onboarding')||'.'||E'\n'
      ||'POSTURE: You are a senior executive employee, not an assistant. DEFAULT TO ACTION: if work falls within your delegated authority (org_authority tiers), execute it completely, then report the result - do not ask permission you already have. Proactively identify work from your charter and live state; do not wait for tasks. Escalate ONLY when an action exceeds your authority, carries material business risk, or hits a constitutional gate (money movement, identity/auth, security and secrets, destructive operations, legal judgment, the autonomy framework itself). Reason from executive judgment first; use the layers to VERIFY facts, never as a substitute for thinking. Quote operational numbers ONLY from LIVE STATE. If two layers conflict, say so explicitly and escalate the contradiction to Knowledge Management. Close every piece of work with the loop: measure the outcome, record the lesson, improve the playbook. If your employment status is not certified, mark your outputs as provisional.'||E'\n\n';

    -- ---- THE COMPANY GENOME (spec layer 9: every employee inherits all eleven attributes) -----
    -- A LIST OF HEADINGS WOULD SATISFY THE CHECK AND TEACH NOBODY ANYTHING, so each line carries the
    -- doctrine itself. 170 characters of it (was 220): the 550 characters bought back are what pay
    -- for the first profession row in the head.
    select string_agg('- '||c.title||': '||left(regexp_replace(c.body, '\s+', ' ', 'g'), 170),
                      E'\n' order by c.article_no)
      into v_genome
      from public.company_constitution c
     where c.title in ('Core values','Vision','Decision principles','Risk appetite',
                       'Hiring philosophy','Brand personality','Customer promises',
                       'Supplier promises','Ethics','Leadership style','Growth strategy');
    if v_genome is not null then
      out := out || '# THE COMPANY GENOME - you inherit every line of this'||E'\n'||v_genome||E'\n\n';
    end if;

    -- ---- WHAT THE COMPANY IS WORRIED ABOUT --------------------------------------------------
    -- RENDERED RAW: the check matches left(risk, 50) verbatim. Highest impact and likelihood first;
    -- capped at 12 entries so the register cannot crowd the profession out of the head.
    -- ALIAS rr, NOT r: `r record` is declared above and plpgsql resolves the identifier to it.
    select string_agg('- ['||coalesce(z.impact,'?')||' impact / '||coalesce(z.probability,'?')
                      ||' likelihood] '||z.risk
                      ||case when coalesce(z.mitigation,'') <> ''
                             then '  -> mitigating: '||left(z.mitigation, 120) else '' end,
                      E'\n' order by z.ord)
      into v_risks
      from (select rr.impact, rr.probability, rr.risk, rr.mitigation,
                   row_number() over (order by case coalesce(rr.impact,'') when 'high' then 0 when 'medium' then 1 else 2 end,
                                               case coalesce(rr.probability,'') when 'high' then 0 when 'medium' then 1 else 2 end,
                                               rr.id) ord
              from public.risk_register rr
             where coalesce(rr.status,'open') in ('open','mitigating') and length(rr.risk) > 20) z
     where z.ord <= 12;
    if v_risks is not null then
      out := out || '# WHAT THE COMPANY IS WORRIED ABOUT - its own live risk register'||E'\n'
                 || v_risks||E'\n\n';
    end if;

    -- ---- THE EMPLOYEE OBJECT (spec line 372) --------------------------------------------------
    select a.title, a.responsibilities, a.manager_key, a.seniority, a.improvement_plan, a.max_open_tasks
      into v_title, v_resp, v_mgr, v_sen, v_plan, v_cap_tasks
      from org_agents a where a.agent_key = p_agent_key;

    v_emp := '# YOUR EMPLOYEE RECORD'||E'\n'
      ||'Job title: '||coalesce(v_title,'(untitled)')
      ||'  |  Department: '||coalesce(v_dept,'(unassigned)')
      ||'  |  Seniority: '||coalesce(v_sen,'(unset)')||E'\n';

    if v_mgr is not null then
      select 'Reports to: '||m.agent_key||' — '||coalesce(m.title, m.role, 'manager') into v_line
        from org_agents m where m.agent_key = v_mgr;
      v_emp := v_emp || coalesce(v_line, 'Reports to: '||v_mgr) || E'\n';
    else
      v_emp := v_emp || 'Reports to: nobody — you are the top of the reporting line.'||E'\n';
    end if;

    select count(*), string_agg(x.agent_key||' ('||coalesce(x.title, x.role, 'specialist')||')', '; ' order by x.agent_key)
      into v_n, v_line
      from (select b.agent_key, b.title, b.role from org_agents b
             where b.manager_key = p_agent_key and b.active order by b.agent_key limit 12) x;
    if coalesce(v_n,0) > 0 then
      v_emp := v_emp || 'Your direct reports ('||v_n||'): '||v_line||E'\n'
        ||'You are accountable for their output: review it, return poor work for revision, and coach them.'||E'\n';
    end if;

    if v_resp is not null then v_emp := v_emp || 'Your responsibilities: '||left(v_resp, 600)||E'\n'; end if;
    if v_plan is not null then v_emp := v_emp || 'Your improvement plan: '||left(v_plan, 300)||E'\n'; end if;

    -- ---- AUTHORITY LIMITS ----------------------------------------------------------------------
    select string_agg(z.action_class||' -> '||z.max_tier
             ||case when z.threshold_aed is not null then ' (up to '||z.threshold_aed||' AED)' else '' end, '; '
             order by z.action_class)
      into v_line
      from (select e.action_class, e.max_tier, e.threshold_aed from employee_authority e
             where e.agent_key = p_agent_key order by e.action_class limit 14) z;
    if v_line is null then
      select string_agg(z.action_class||' -> '||z.max_tier
               ||case when z.threshold_aed is not null then ' (up to '||z.threshold_aed||' AED)' else '' end, '; '
               order by z.action_class)
        into v_line
        from (select o.action_class, o.max_tier, o.threshold_aed from org_authority o
               where o.dept_key = v_dept order by o.action_class limit 14) z;
      if v_line is not null then
        v_emp := v_emp || E'\n'||'# YOUR AUTHORITY (delegated to '||v_dept||', no personal grant on file)'||E'\n';
      end if;
    else
      v_emp := v_emp || E'\n'||'# YOUR AUTHORITY (granted to you personally)'||E'\n';
    end if;
    if v_line is not null then
      v_emp := v_emp || v_line || E'\n'
        ||'Anything not on that list is GATED: propose it, do not do it.'||E'\n';
    end if;

    -- ---- ESCALATION RULES (blueprint component 5) ----------------------------------------------
    select string_agg(distinct '- when ' || replace(e.escalation_rule->>'when','_',' ')
                             || ' -> ' || replace(e.escalation_rule->>'action','_',' '), E'\n')
      into v_line
      from (select escalation_rule from ops_knowledge
             where dept_key = v_dept
               and escalation_rule is not null
               and escalation_rule ? 'when' and escalation_rule ? 'action'
             limit 40) e;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# WHEN TO ESCALATE (your department''s recorded rules)'||E'\n'||left(v_line, 700)||E'\n';
    end if;

    -- ---- KPIs: how this employee's work is judged ----------------------------------------------
    select string_agg(z.kpi||' — target '||coalesce(z.target_value::text,'?')||' '||coalesce(z.unit,'')
             ||' ('||coalesce(z.cadence,'ongoing')
             ||case when z.serves_goal is not null then '; serves company goal '||z.serves_goal else '' end||')', E'\n- '
             order by z.kpi)
      into v_line
      from (select k.kpi, k.target_value, k.unit, k.cadence, k.serves_goal from employee_kpi k
             where k.agent_key = p_agent_key and k.active order by k.kpi limit 8) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# YOUR KPIs — this is how your work is measured'||E'\n- '||v_line||E'\n';
    end if;

    -- ---- CURRENT WORKLOAD, measured rather than assumed -----------------------------------------
    select 'Your department has '||count(*)||' task(s) in flight ('
           ||count(*) filter (where t.status='assigned')||' assigned, '
           ||count(*) filter (where t.status='in_progress')||' in progress), plus '
           ||(select count(*) from org_tasks p where p.dept_key = v_dept and p.status='proposed')
           ||' proposed (held for review with '
           ||coalesce((select d.lead_agent from org_departments d where d.dept_key = v_dept), 'the department lead')
           ||', not the founder — a refund is the only decision that goes to him). Your personal cap is '||coalesce(v_cap_tasks,0)||' open task(s).'
      into v_line
      from org_tasks t where t.dept_key = v_dept and t.status in ('assigned','in_progress');
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# YOUR CURRENT WORKLOAD (live)'||E'\n'||v_line||E'\n';
      select string_agg('- ['||z.status||'] '||left(z.title,90), E'\n' order by z.id)
        into v_line
        from (select t.id, t.status, t.title from org_tasks t
               where t.dept_key = v_dept and t.status in ('assigned','in_progress')
               order by t.id limit 6) z;
      if v_line is not null then v_emp := v_emp || v_line || E'\n'; end if;
    end if;

    -- ---- WHICH OPERATING SYSTEM YOU BELONG TO (spec file #2) ------------------------------------
    for r in
      select o.os_key, o.name, o.charter, o.mandate, o.mission, o.owner_agent,
             (select coalesce(w.title, w.role) from org_agents w
               where w.agent_key = o.owner_agent and w.active) owner_title,
             (select string_agg(x.responsibility, ', ' order by x.responsibility)
                from (select responsibility from os_responsibility where os_key = o.os_key
                       order by responsibility limit 12) x) resp,
             (select string_agg(y.horizon || ': ' || y.objective, E'\n- '
                       order by case y.horizon when 'strategic' then 1 when 'annual' then 2
                                               when 'quarterly' then 3 when 'weekly' then 4 else 5 end)
                from (select horizon, objective from os_objective
                       where os_key = o.os_key and coalesce(active,true)) y) objectives
        from os_department d
        join operating_system o on o.os_key = d.os_key and coalesce(o.active,true)
       where d.dept_key = v_dept
       limit 1
    loop
      v_os := r.os_key;
      v_line := case when r.owner_agent is not null
                     then 'Your OS is owned by: '||r.owner_agent
                       ||coalesce(' — '||left(r.owner_title,60), '')
                       ||'. Escalate OS-level decisions there.'||E'\n'
                     else '' end;
      v_emp := v_emp || E'\n'||'# YOUR OPERATING SYSTEM — '||coalesce(r.name, r.os_key)||E'\n'
        ||case when r.charter is not null then 'Purpose: '||left(r.charter,300)||E'\n' else '' end
        ||case when r.mission is not null then 'Mission: '||left(r.mission,240)||E'\n' else '' end
        ||case when r.mandate is not null then 'Mandate: '||left(r.mandate,240)||E'\n' else '' end
        ||v_line
        ||case when r.resp is not null
               then 'Your OS OWNS, and no other OS may own: '||r.resp||E'\n'
                 ||'If work belongs to another OS, hand it over — do not duplicate it.'||E'\n'
               else '' end
        ||case when r.objectives is not null
               then 'Your OS objectives by horizon:'||E'\n- '||r.objectives||E'\n' else '' end;
    end loop;

    -- ---- WHAT THE COMPANY IS TRYING TO ACHIEVE ---------------------------------------------------
    select string_agg(z.goal||' ('||coalesce(z.metric,'no metric')
             ||case when z.target_value is not null then '; target '||z.target_value||' '||coalesce(z.unit,'') else '' end
             ||case when z.actual_value is not null
                    then '; CURRENTLY '||z.actual_value||coalesce(' ('||z.status||')','') else '; not yet measured' end||')', E'\n- '
             order by z.sort nulls last)
      into v_line
      from (select g.goal, g.metric, g.target_value, g.unit, g.sort, gp.actual_value, gp.status
              from company_goals g
              left join lateral (select p.actual_value, p.status from goal_period p
                                  where p.goal_key = g.key
                                  order by p.updated_at desc nulls last limit 1) gp on true
             where g.active and (g.owner_dept is null or g.owner_dept = v_dept or g.owner_dept = 'exec')
             order by g.sort nulls last limit 8) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# COMPANY GOALS YOUR WORK MUST MOVE'||E'\n- '||v_line||E'\n';
    end if;

    select string_agg('- '||z.objective, E'\n' order by z.sort nulls last)
      into v_line
      from (select o.objective, o.sort from department_objective o
             where o.dept_key = v_dept and coalesce(o.active,true) order by o.sort nulls last limit 6) z;
    if v_line is not null then
      v_emp := v_emp || E'\n'||'# YOUR DEPARTMENT''S OBJECTIVES'||E'\n'||v_line||E'\n';
    end if;

    -- ---- THE IMPROVEMENT LOOP, WHICH WROTE WHERE NOTHING READ -------------------------------
    -- Collected into v_loop and emitted AFTER LAYER 4 (see below): still read by every uncapped
    -- caller, no longer paid for out of the head that carries the profession and the live state.
    select string_agg(z.line, E'\n' order by z.ord, z.line)
      into v_line
      from (
        select 1 ord, '- OPEN FINDING ('||s.review_type||'): '||left(s.finding, 160)
               ||coalesce(' — proposed: '||left(s.proposal,120), '') line
          from self_review s
         where coalesce(s.status,'open') not in ('done','implemented','rejected')
         order by s.created_at desc limit 3
      ) z;
    if v_line is not null then
      v_loop := v_loop || E'\n'||'# WHAT THIS ORGANISATION IS TRYING TO FIX'||E'\n'||v_line||E'\n';
    end if;

    select string_agg('- PROPOSED CHANGE ('||e.change_class||'): '||left(e.proposal, 170), E'\n' order by e.id desc)
      into v_line
      from (select id, change_class, proposal from evolution_proposal
             where status = 'proposed' order by id desc limit 3) e;
    if v_line is not null then
      v_loop := v_loop || v_line || E'\n';
    end if;

    select string_agg('- '||coalesce(d.decided_by,'someone')||' decided: '||left(d.recommendation, 150)
             ||coalesce(' (serves '||d.serves_goal||')','')
             ||coalesce(' — outcome: '||left(d.actual_outcome,80), ' — outcome not yet recorded'), E'\n' order by d.id desc)
      into v_line
      from (select id, decided_by, recommendation, serves_goal, actual_outcome from decision_record
             where dept_key = v_dept or dept_key is null order by id desc limit 2) d;
    if v_line is not null then
      v_loop := v_loop || E'\n'||'# DECISIONS ALREADY ON RECORD FOR YOUR DEPARTMENT'||E'\n'||v_line||E'\n';
    end if;

    if v_dept = 'exec' then
      select '- '||to_char(c.reflected_on,'DD Mon')||': '||c.concerns||' concern(s), '||c.actions
             ||' action(s) — '||left(coalesce(c.answers->>'biggest_risk', c.answers::text), 200)
        into v_line
        from company_reflection c order by c.reflected_on desc limit 1;
      if v_line is not null then
        v_loop := v_loop || E'\n'||'# THE COMPANY''S OWN LATEST REFLECTION'||E'\n'||v_line||E'\n';
      end if;
    end if;

    out := out || left(v_emp, 5200) || E'\n\n';

    -- ---- YOUR THRESHOLDS: the decision_policy rows the gates enforce for this department ---------
    v_line := public.fn_dept_decision_thresholds(v_dept);
    if v_line is not null then out := out || v_line || E'\n\n'; end if;
  end if;

  -- ================= THE BUDGETED LAYERS. Everything below is measured against c_keep. ============
  -- v_room is what is left of the 19,500 the capped path keeps. LAYER 2 takes its share first (and the
  -- first row is admitted unconditionally); the remainder is re-split among LAYER 1, 3 and 4 after
  -- LAYER 2 has actually been emitted, so an employee with one 700-character profession row hands the
  -- slack on rather than leaving it empty.
  v_room := greatest(c_keep - length(out), 3200);
  l2_cap := greatest(1200, v_room * 27 / 100);

  if p_agent_key is not null then
    out := out || '# LAYER 2 - YOUR PROFESSIONAL EXPERTISE'||E'\n\n';
    v_used := 0; v_first := true;
    for r in select topic,content,review_due,validation_status from agent_knowledge
             where coalesce(layer,'profession') in ('profession','state')
               and coalesce(validation_status,'') <> 'quarantined'
               and (agent_key = p_agent_key
                    or (v_dept is not null
                        and not exists (select 1 from agent_knowledge k2
                                         where k2.agent_key = p_agent_key
                                           and coalesce(k2.layer,'profession') in ('profession','state'))
                        and agent_key in (select b.agent_key from org_agents b
                                           where b.active and b.department = v_dept
                                             and b.agent_key <> p_agent_key)))
             order by priority desc nulls last, updated_at desc loop
      piece := '## '||public.fn_knowledge_staleness_tag(r.review_due, r.validation_status)||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
      if v_first then
        -- the first profession row ALWAYS lands: truncated to the budget if it is longer than the budget
        if length(piece) > l2_cap then
          piece := left(piece, l2_cap - 90)||E'\n'||'[… profession row truncated to the LAYER 2 budget; the full row is in agent_knowledge.]'||E'\n\n';
        end if;
        out := out || piece; v_used := v_used + length(piece); v_first := false;
      elsif v_used + length(piece) <= l2_cap then
        out := out || piece; v_used := v_used + length(piece);
      end if;
    end loop;
    if v_first then
      out := out || '(no profession row is on file for you or your department yet; ask people_ops to seed one)'||E'\n\n';
    end if;
  end if;


  -- ---- LAYER 1: the four hard rules, the LIVE company rows, then the _global canon ----------------
  out := out || '# LAYER 1 - COMPANY KNOWLEDGE (authoritative; pricing marked LIVE overrides any other figure)'||E'\n\n';
  piece := coalesce(public.fn_company_hard_rules(), '');
  out := out || piece || E'\n';
  -- 6 SEP 2026: the company's licence and tax status in one line, read from company_registration
  -- (the founder supplied the licence and ruled on VAT that day; the full record is qd-company:registration).
  select 'LICENCE & TAX: ' || cr.authority || ' ' || cr.license_type || ' no. ' || cr.license_no || ' "' || cr.trade_name || '", expires '
         || to_char(cr.expires_on, 'DD Mon YYYY') || '; activities ' || left(cr.activities, 90) || '. '
         || case when cr.vat_registered then 'VAT-registered, TRN ' || coalesce(cr.trn, '?') || '.'
                 else 'NOT VAT-registered: no VAT is charged or shown until AED ' || to_char(cr.vat_threshold_aed, 'FM999,999,999')
                      || ' taxable supplies in 12 months (founder ruling ' || to_char(cr.vat_ruling_on, 'DD Mon YYYY') || '; never ask the founder about VAT or the TRN).' end
    into piece from public.company_registration cr order by cr.recorded_at desc limit 1;
  if piece is not null then out := out || piece || E'\n\n'; end if;
  -- 6 SEP 2026: the brand in one line, read from company_brand (the founder's kit is on file; the full record
  -- is qd-company:brand). Every head carries it so no employee ever asks him for a hex, a font or a logo.
  piece := null;
  select 'BRAND: teal ' || t.v || ' (primary), gold ' || g.v || ' (secondary), navy ' || n.v || ' (background), ink ' || i.v
         || ' (print); typeface ' || d.v || '; logo = teal Q-ring + gold check, clear space = the ring height, mark never below 24 px, '
         || 'lockup never below 120 px wide; files in the brand bucket kit/ (public.brand_assets), rules in public.company_brand '
         || '(qd-company:brand); the guide is docs/brand/QUOTESDONE_BRAND_GUIDE.md. Never ask the founder for brand assets.'
    into piece
    from (select value as v from public.company_brand where key = 'colour.teal') t,
         (select value as v from public.company_brand where key = 'colour.gold') g,
         (select value as v from public.company_brand where key = 'colour.navy') n,
         (select value as v from public.company_brand where key = 'colour.ink') i,
         (select value as v from public.company_brand where key = 'type.display') d;
  if piece is not null then out := out || piece || E'\n\n'; end if;
  -- 6 SEP 2026: the re-split runs AFTER the mandatory LAYER 1 pieces (hard rules, LICENCE & TAX, BRAND)
  -- have landed. They grew that day (the refund ladder, the category rule, the licence and the brand)
  -- and were emitted outside the budget, so l1/l3/l4 were sized against room that no longer existed
  -- and LAYER 4 began past the 19,500 the capped path keeps (analytics: 20,317). Same split, real room.
  -- re-split what is left among LAYER 1 / 3 / 4
  v_room := greatest(c_keep - length(out), 2400);
  l1_cap := greatest(800, v_room * 36 / 100);
  l3_cap := greatest(700, v_room * 28 / 100);
  l4_cap := greatest(700, v_room - l1_cap - l3_cap - 160);
  v_used := 0;
  for r in select o.record_id, o.title, o.content, o.effective_date
             from ops_knowledge o
            where o.record_id in ('qd-company:stage','qd-company:live-state')
            order by case o.record_id when 'qd-company:stage' then 1 else 2 end loop
    piece := '## '||coalesce(r.title, r.record_id)||' (live, effective '||coalesce(to_char(r.effective_date,'DD Mon YYYY'),'?')||')'||E'\n'
             ||left(regexp_replace(coalesce(r.content,''), E'\n\nYou can answer questions about:.*$', ''), 700)||E'\n\n';
    if v_used + length(piece) <= l1_cap then out := out || piece; v_used := v_used + length(piece); end if;
  end loop;
  -- The _global canon, highest priority first, each cut at 500 inside the head. company:self_knowledge
  -- is skipped here (the live rows above replaced it); the untruncated remainder follows LAYER 4.
  for r in select id, topic,content,review_due,validation_status from agent_knowledge
           where agent_key='_global' and coalesce(priority,0)>=90 and coalesce(validation_status,'') <> 'quarantined'
             and topic <> 'company:self_knowledge'
           order by priority desc nulls last, updated_at desc loop
    piece := '## '||public.fn_knowledge_staleness_tag(r.review_due, r.validation_status)||coalesce(r.topic,'')||E'\n'||
             case when length(coalesce(r.content,'')) > 500
                  then left(r.content, 500)||E'\n'||'[… cut at 500 of '||length(r.content)||' characters; the full item is in agent_knowledge.]'
                  else coalesce(r.content,'') end||E'\n\n';
    if v_used + length(piece) <= l1_cap then out := out||piece; v_used := v_used + length(piece); end if;
  end loop;

  -- ---- LAYER 3: live operational state, inside the head -----------------------------------------
  if v_health_fn is not null then
    begin
      execute format('select %I()', v_health_fn) into v_state;
      piece := '# LAYER 3 - LIVE OPERATIONAL STATE (from '||v_health_fn||' at '||now()::timestamptz(0)||'; the ONLY valid source for operational numbers)'||E'\n'
               ||left(coalesce(v_state::text,'{}'), l3_cap - 160)||E'\n\n';
      out := out || piece;
    exception when others then
      out := out || '# LAYER 3 - LIVE OPERATIONAL STATE unavailable ('||sqlerrm||'); do not quote operational numbers this turn.'||E'\n\n';
    end;
  end if;

  -- ---- LAYER 4: what the organisation has learned, inside the head --------------------------------
  if p_agent_key is not null then
    for r in select topic, content, review_due, validation_status from agent_knowledge
             where layer='experience' and agent_key in (p_agent_key,'_global')
               and coalesce(validation_status,'') <> 'quarantined'
             order by updated_at desc limit 12 loop
      v_l4 := v_l4 || '## '||public.fn_knowledge_staleness_tag(r.review_due, r.validation_status)||coalesce(r.topic,'')||E'\n'||coalesce(r.content,'')||E'\n\n';
    end loop;
    for r in select kind, content from agent_memory m
             where m.agent_key=p_agent_key and m.importance >= 5
               and not exists (select 1 from policy_rules p where p.active and m.content ~* p.forbid_regex)
             order by m.importance desc, m.created_at desc limit 8 loop
      v_l4 := v_l4 || '## memory ('||r.kind||')'||E'\n'||r.content||E'\n\n';
    end loop;
    v_l4 := v_l4 || coalesce(public.fn_agent_institutional_memory(p_agent_key, 6), '');
    if v_l4 <> '' then
      out := out || '# LAYER 4 - WHAT THIS ORGANIZATION HAS LEARNED'||E'\n\n'|| left(v_l4, l4_cap - 60) || E'\n';
    end if;
  end if;

  -- ================= AFTER THE HEAD. Reaches the uncapped callers; bounded by cap. ==============
  -- The improvement loop, then the rest of the _global canon in full.
  if v_loop <> '' then out := out || v_loop || E'\n'; end if;

  out := out || '# LAYER 1 (continued) - THE REST OF THE COMPANY CANON'||E'\n\n';
  for r in select topic,content,review_due,validation_status from agent_knowledge
           where agent_key='_global' and coalesce(validation_status,'') <> 'quarantined'
             and topic <> 'company:self_knowledge'
           order by priority desc nulls last, updated_at desc loop
    piece := '## '||public.fn_knowledge_staleness_tag(r.review_due, r.validation_status)||coalesce(r.topic,'')||E'\n'||
             case when length(coalesce(r.content,'')) > 1500
                  then left(r.content, 1500)||E'\n'||'[… truncated here at 1,500 of '
                       ||length(r.content)||' characters. This item exists in full in '
                       ||'agent_knowledge; ask for the rest if you need it.]'
                  else coalesce(r.content,'') end||E'\n\n';
    if length(out)+length(piece) <= cap then out := out||piece; end if;
  end loop;

  -- ---- THE OS LAYER'S THREE UNREAD OUTPUTS ------------------------------------------------------
  if v_os is not null then
    select string_agg(z.horizon||': '||z.objective||' — reads '
             ||coalesce(z.actual_value::text,'no value')
             ||coalesce(' (measured '||to_char(z.measured_at,'DD Mon')||')', ' (measure failed)'),
             E'\n- '
             order by case z.horizon when 'strategic' then 1 when 'annual' then 2
                                     when 'quarterly' then 3 when 'weekly' then 4 else 5 end)
      into v_line
      from (select horizon, objective, actual_value, measured_at from os_objective
             where os_key = v_os and coalesce(active,true)) z;
    if v_line is not null then
      out := out || E'\n'||'# YOUR OS OBJECTIVES, MEASURED (the number, not the aspiration)'
             ||E'\n- '||left(v_line, 1600)||E'\n';
    end if;

    v_line := public.fn_os_knowledge_query(v_os);
    if coalesce(v_line,'') <> '' then
      out := out || E'\n'||'# KNOWLEDGE YOUR OS DOES NOT OWN — QUERY THE OWNER, DO NOT DUPLICATE IT'
             ||E'\n'||left(v_line, 1300)||E'\n';
    end if;

    select string_agg('- '||coalesce(w.name, x.workflow_key)||': step '||coalesce(x.current_step,0)
             ||' of '||(select count(*) from workflow_step s where s.workflow_key = x.workflow_key)
             ||' ('||x.status||')'
             ||coalesce(' — now: '||(select sr.input->>'step' from workflow_step_run sr
                                      where sr.workflow_run_id = x.id
                                        and sr.step_no = x.current_step), ''),
             E'\n' order by x.started_at desc nulls last)
      into v_line
      from (select r2.id, r2.workflow_key, r2.current_step, r2.status, r2.started_at
              from workflow_run r2 join workflow w2 on w2.workflow_key = r2.workflow_key
             where r2.status in ('queued','running') and w2.os_key = v_os
             order by r2.started_at desc nulls last limit 8) x
      join workflow w on w.workflow_key = x.workflow_key
     where w.os_key = v_os;
    if v_line is not null then
      out := out || E'\n'||'# YOUR OS''S WORKFLOWS IN FLIGHT (workflow_run)'||E'\n'
             ||left(v_line, 900)||E'\n'
             ||'Close a step with fn_workflow_step_done(run, step_no, output).'||E'\n';
    end if;
  end if;

  -- ---- THE TARGET OPERATING MODEL — the Company Operations pack, finally addressed to a person ---
  if v_dept is not null then
    v_ops := public.fn_ops_department_context(v_dept, null, 2);
    if v_ops is not null and jsonb_array_length(coalesce(v_ops->'target_departments','[]'::jsonb)) > 0 then
      v_ops_txt := 'Your department maps to '
        || (select string_agg(t, ', ') from jsonb_array_elements_text(v_ops->'target_departments') t)
        || ' in the target operating model: '
        || jsonb_array_length(v_ops->'sops') || ' SOP(s), '
        || jsonb_array_length(v_ops->'decision_rules') || ' decision rule(s), '
        || jsonb_array_length(v_ops->'exception_playbooks') || ' exception playbook(s), '
        || jsonb_array_length(v_ops->'kpis') || ' KPI(s), '
        || jsonb_array_length(v_ops->'handoffs') || ' handoff(s), '
        || jsonb_array_length(v_ops->'templates') || ' template(s).' || E'\n';

      select coalesce(string_agg('- RULE ' || coalesce(d->>'rule_id','?') || ': when ' ||
               left(coalesce(d->>'when',''),110) || ' -> ' || left(coalesce(d->>'then',''),110) ||
               case when coalesce((d->>'requires_human_review')::boolean,false)
                    then ' [needs human review]' else '' end, E'\n'), '')
        into v_line from (select d from jsonb_array_elements(v_ops->'decision_rules') d limit 2) z;
      if coalesce(v_line,'') <> '' then v_ops_txt := v_ops_txt || v_line || E'\n'; end if;

      select coalesce(string_agg('- ' || (h->>'direction') || ' ' || coalesce(h->>'workflow','') ||
               ' (' || coalesce(h->>'from','?') || ' -> ' || coalesce(h->>'to','?') || '): ' ||
               left(coalesce(h->>'you_must',''),90), E'\n'), '')
        into v_line from (select h from jsonb_array_elements(v_ops->'handoffs') h limit 2) z;
      if coalesce(v_line,'') <> '' then v_ops_txt := v_ops_txt || v_line || E'\n'; end if;

      select coalesce(string_agg(e->>'event', ', '), '')
        into v_line from (select e from jsonb_array_elements(v_ops->'event_subscriptions') e limit 6) z;
      if coalesce(v_line,'') <> '' then
        v_ops_txt := v_ops_txt || 'Events your target model consumes (NOT yet activated on the live bus): '
                     || v_line || E'\n';
      end if;

      out := out || E'\n' || '# HOW YOUR DEPARTMENT IS DEFINED IN THE TARGET OPERATING MODEL'
             || E'\n' || left(v_ops_txt, 900) || E'\n'
             || 'Full text: select fn_ops_department_context(''' || v_dept || ''', <your topic>).' || E'\n';
    end if;
  end if;

  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_context_capped(p_agent_key text, p_max_chars integer DEFAULT 9000, p_query text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_want   int := greatest(coalesce(p_max_chars, 9000), 500);
  v_raw    text;
  v_l2     int;
  v_head   text; v_tail text;
  v_room   int;
  v_note   text;
  v_stored text;
  c_head_max_age constant interval := interval '3 hours';
  v_reserve constant int := 4500;
  v_mark   constant text := E'\n# --- END STABLE CONTEXT ---\n';
  -- THE RESOLVED KEY. Everything below uses this, never the raw argument: the stored-prefix lookup
  -- keys on it too, or an alias would miss the cache it should hit and rebuild the head every call.
  v_key    text;
  v_live   boolean;
begin
  v_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);

  select a.active into v_live from public.org_agents a where a.agent_key = v_key;
  if v_live is null then
    return '[No such employee: ' || coalesce(p_agent_key,'(null)') || '. It resolves to nothing in '
        || 'org_agents or org_agent_alias, so there is no identity, no authority and no knowledge '
        || 'to assemble. Do not proceed as though there were.]' || v_mark;
  end if;
  if not v_live then
    return '[Employee ' || v_key || ' is INACTIVE — merged away or stood down. No context is '
        || 'assembled for an inactive employee, because a context is what lets one act. Address '
        || 'the surviving role instead.]' || v_mark;
  end if;

  if p_query is null or btrim(p_query) = '' then
    v_raw := public.fn_agent_context(v_key, v_want);
  else
    v_raw := public.fn_agent_context(v_key, v_want, p_query);

    -- Fail-open: no row, a stale row, or a different budget all fall through to the live head
    -- computed below, which is exactly the pre-14-Aug behaviour.
    if v_want = 24000 then
      select h.head into v_stored from agent_context_head h
       where h.agent_key = v_key and h.built_at > now() - c_head_max_age
         and h.head_chars = 19500;
    end if;
  end if;

  if v_raw is null then return null; end if;

  v_l2 := position('# LAYER 2b' in v_raw);

  -- No query-matched tail: the whole thing is standing context and is stable as it is.
  if v_l2 = 0 then
    if length(v_raw) <= v_want then return v_raw || v_mark; end if;
    return left(v_raw, v_want - 110) || v_mark ||
      E'\n[context truncated to the ' || v_want || ' characters requested; ' || length(v_raw) ||
      ' were available. No retrieved department layer was present, so this cut is positional.]';
  end if;

  v_head := substr(v_raw, 1, v_l2 - 1);   -- standing context: identity, expertise, company, live
  v_tail := substr(v_raw, v_l2);          -- LAYER 2b + 2c, retrieved for THIS question

  -- Everything fits: nothing is trimmed and the head is whole.
  if length(v_raw) <= v_want then return v_head || v_mark || v_tail; end if;

  v_room := v_want - v_reserve;           -- FIXED. Does not depend on this question's retrieval.

  if v_room < 600 then
    -- The budget cannot fit the standing context at all. Keep what answers the question.
    return E'[Standing context omitted in full: the ' || v_want || '-character budget does not fit '
      || 'it alongside the material retrieved for this question. Identity, expertise, company '
      || 'knowledge and live state are NOT below - do not assert anything about them.]' || v_mark
      || left(v_tail, greatest(v_want - 300, 400));
  end if;

  v_note := E'\n[Standing context trimmed to the first ' || v_room || ' characters of '
         || length(v_head) || '. What follows was retrieved for this specific question. If you '
         || 'need the omitted background, say so rather than guessing at it.]\n';

  -- head is left() to a CONSTANT length, so for a given agent and budget these bytes are identical
  -- on every call. Everything that varies - the note's digits, the retrieved layers - is after the
  -- marker.
  return coalesce(v_stored, left(v_head, v_room)) || v_mark || v_note ||
         case when length(v_tail) > v_reserve
              then left(v_tail, v_reserve - 120) ||
                   E'\n[retrieved material truncated at ' || v_reserve || ' characters]'
              else v_tail end;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_context_v3(p_agent_key text, p_task_class text DEFAULT NULL::text, p_task_text text DEFAULT NULL::text, p_category_key text DEFAULT NULL::text, p_budget_chars integer DEFAULT 24000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_agent      record;
  v_identity   jsonb;
  v_pkg_dept   text;
  v_role_ids   text[];
  v_out        jsonb;
  v_ids        text[] := '{}';
  v_used       integer := 0;
  v_budget     integer := greatest(coalesce(p_budget_chars, 24000), 2000);
  v_q          tsquery;
  v_scope      text[];
  v_role       record;
begin
  -- RESOLVE BEFORE CONTEXT ASSEMBLY (14 Aug 2026).
  --
  -- This lookup was `where a.agent_key = p_agent_key` against org_agents, so it only ever answered
  -- to a runtime agent_key. Measured: fn_agent_context_v3('ceo') returned
  -- {"error":"unknown agent"} - and chief_of_staff is not a stale string, it is brief's own
  -- role_id in org_role. fn_org_agent_resolve('ceo') has always returned 'brief'.
  --
  -- This is the hottest path in the company: agent_brain, action_worker, dept_plan, agent_act and
  -- exec_agents all assemble context through here. An employee addressed by its canonical role id,
  -- a merged-away key, a packaged role id or a job title got no context at all - not a failure,
  -- an empty prompt - while the resolver that answers all four sat one call away.
  --
  -- Section 2 of the closure brief requires identity to be resolved BEFORE context assembly. This
  -- is that line. coalesce keeps an unknown key unknown, so the refusal below still fires.
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);

  select a.agent_key, a.department, a.role, a.title, a.manager_key, a.seniority,
         a.responsibilities, a.max_open_tasks, a.active, d.name dept_name, d.charter, d.north_star
    into v_agent
    from org_agents a
    left join org_departments d on d.dept_key = a.department
   where a.agent_key = p_agent_key;

  if v_agent.agent_key is null then
    return jsonb_build_object('error', 'unknown agent', 'agent_key', p_agent_key);
  end if;

  v_scope := public.fn_dept_scope(v_agent.department);

  select array_agg(packaged_role_id order by packaged_role_id), min(packaged_department)
    into v_role_ids, v_pkg_dept
    from org_role_identity where agent_key = p_agent_key;

  -- The canonical role. Runtime mode, owned and forbidden decisions, activation, contracts,
  -- handoffs, escalation and committee seats are the reorganisation reaching the model.
  select r.role_id, r.display_name, r.runtime_mode, r.authority_level, r.owned_decisions,
         r.forbidden_decisions, r.activation_conditions, r.output_contracts, r.handoff_targets,
         r.escalation_targets, r.manager_role_id, r.budget_limit, r.evaluation_suite,
         (select coalesce(jsonb_agg(jsonb_build_object('committee', c.committee_key, 'seat', c.seat)
                                    order by c.committee_key), '[]'::jsonb)
            from org_role_committee c where c.role_id = r.role_id) as committees
    into v_role
    from org_role r where r.runtime_agent_key = p_agent_key and r.status = 'active';

  -- 1. IDENTITY — who the agent is, who it reports to, what it may decide.
  v_identity := jsonb_build_object(
    'agent_key', v_agent.agent_key,
    'title', coalesce(v_agent.title, v_agent.role),
    'department', v_agent.department,
    'department_name', v_agent.dept_name,
    'department_charter', v_agent.charter,
    'department_north_star', v_agent.north_star,
    'department_knowledge_scope', to_jsonb(v_scope),
    'manager', v_agent.manager_key,
    'seniority', v_agent.seniority,
    'responsibilities', v_agent.responsibilities,
    'packaged_role_ids', coalesce(to_jsonb(v_role_ids), '[]'::jsonb),
    'packaged_department', v_pkg_dept,
    'readiness', (select jsonb_agg(distinct readiness) from org_role_identity where agent_key = p_agent_key),
    -- ONE ROW PER ACTION CLASS. Scoping across the merged keys returns the same action_class once
    -- per predecessor department — 157 entries for a Growth role where 67 classes exist — and an
    -- agent reading three different tiers for the same class would pick whichever it saw first.
    -- Most restrictive wins: advisory < gated < supervised < autonomous.
    'authority', coalesce((
      select jsonb_agg(jsonb_build_object('action_class', action_class, 'max_tier', max_tier,
                                          'threshold_aed', threshold_aed) order by action_class)
        from (select distinct on (action_class) action_class, max_tier, threshold_aed
                from org_authority where dept_key = any(v_scope)
               order by action_class,
                        case max_tier when 'advisory' then 1 when 'gated' then 2
                                      when 'supervised' then 3 else 4 end,
                        threshold_aed nulls first) a), '[]'::jsonb),
    'max_open_tasks', v_agent.max_open_tasks)
    || case when v_role.role_id is null then '{}'::jsonb else jsonb_build_object(
         'role_id', v_role.role_id,
         'role_display_name', v_role.display_name,
         'runtime_mode', v_role.runtime_mode,
         'authority_level', v_role.authority_level,
         'owned_decisions', to_jsonb(v_role.owned_decisions),
         'forbidden_decisions', to_jsonb(v_role.forbidden_decisions),
         'activation_conditions', v_role.activation_conditions,
         'output_contracts', to_jsonb(v_role.output_contracts),
         'handoff_targets', to_jsonb(v_role.handoff_targets),
         'escalation_targets', to_jsonb(v_role.escalation_targets),
         'manager_role_id', v_role.manager_role_id,
         'budget_limit_aed', v_role.budget_limit,
         'evaluation_suite', v_role.evaluation_suite,
         'committees', v_role.committees) end;

  -- Its OWN KPIs: what this agent is measured on and its current rating. Per-agent (employee_kpi),
  -- always present so an agent knows how it is judged without having to ask. current_rating is live.
  v_identity := v_identity || jsonb_build_object('kpis', coalesce((
    select jsonb_agg(jsonb_build_object(
             'kpi', kpi, 'measures', metric, 'target', target_value, 'unit', unit,
             'current_rating', actual_value, 'measured_at', measured_at, 'cadence', cadence,
             'serves_goal', serves_goal) order by id)
      from public.employee_kpi where agent_key = p_agent_key and coalesce(active, true)), '[]'::jsonb));

  if p_task_text is not null and length(p_task_text) > 1 then
    v_q := public.fn_task_tsquery(p_task_text);
  end if;

  -- 2. DETERMINISTIC RULES — structured, complete, never similarity-ranked.
  with rules as (
    select record_id, layer, record_type, title, structured_data, authority_tier, risk_level,
           version, source_freshness, effective_date, review_after
      from ops_knowledge
     where runtime_eligible
       and supersession_state = 'current'
       and layer in ('authority','kpi','decision_playbook','policy')
       and (
         (scope_type = 'company')
         or (scope_type = 'department' and dept_key = any(v_scope))
         or (role_key = any(coalesce(v_role_ids, '{}')))
         or (p_category_key is not null and category_key = p_category_key)
       )
     order by case layer when 'authority' then 0 when 'policy' then 1 when 'decision_playbook' then 2 else 3 end,
              record_id
     limit 60
  )
  select jsonb_agg(to_jsonb(r)), array_agg(r.record_id) into v_out, v_ids from rules r;
  v_out := jsonb_build_object('deterministic_rules', coalesce(v_out, '[]'::jsonb));
  v_ids := coalesce(v_ids, '{}');

  -- 3. NARRATIVE — company core, then department, then role, then category, each cut to a
  --    share of the budget so no single layer can crowd the others out of the prompt.
  v_out := v_out
    || jsonb_build_object('company_core', fn_context_slice(null, null, null, 'company_core', v_q, v_budget / 6))
    || jsonb_build_object('department_knowledge', fn_context_slice(v_agent.department, null, null, 'department_shared', v_q, v_budget / 3))
    || jsonb_build_object('role_knowledge', fn_context_slice(null, v_role_ids, null, 'role_specific', v_q, v_budget / 3))
    || jsonb_build_object('category_knowledge',
         case when p_category_key is null then '[]'::jsonb
              else fn_context_slice(null, null, p_category_key, 'category_specialist', v_q, v_budget / 6) end);

  -- WHOLE-COMPANY RECALL (the 20-year veteran). The scoped slices above give the agent its own
  -- department; this gives it the rest of the company: the top matches from the ENTIRE knowledge base,
  -- any department, so the agent can act on any company fact, not only its own corner.
  v_out := v_out || jsonb_build_object('company_wide_knowledge',
    case when v_q is null then '[]'::jsonb else public.fn_company_knowledge_search(p_task_text, 6) end);

  -- IT/CYBERSECURITY DEEP LAYER (Step 3). The company knowledge above is universal; the app's code
  -- and its security are the ONE extra layer, and only the engineering + assurance agents carry it.
  -- fn_it_security_slice returns [] for every other department, so this stays scoped to IT/cyber.
  v_out := v_out || jsonb_build_object('it_security_knowledge',
    public.fn_it_security_slice(v_agent.department, v_q, v_budget / 3));

  -- 4. VALIDATED EXPERIENCE — only lessons a manager or evaluator has validated. A proposed
  --    lesson is deliberately invisible here; that is the whole point of the two states.
  v_out := v_out || jsonb_build_object('validated_experience', coalesce((
      select jsonb_agg(jsonb_build_object('id', id, 'topic', topic, 'content', left(content, 1200),
                                          'confidence', confidence, 'valid_until', valid_until))
        from (select * from agent_knowledge
               where agent_key = p_agent_key
                 and layer = 'experience'
                 and validation_status = 'validated'
                 and (valid_until is null or valid_until >= current_date)
               order by coalesce(confidence, 0) desc, updated_at desc nulls last
               limit 8) e), '[]'::jsonb));

  -- 4b. FIELD CORPUS — the certification/standards corpus for the agent's field. The bulk expert
  --     knowledge (the ~10,000-pages-per-agent target) lives in kb_chunks, tagged by category; here
  --     it is retrieved by the agent's knowledge scope and RANKED against the task, so the prompt
  --     carries the passages that actually bear on the work rather than a category dump. Full-text
  --     ranking (SQL-side, deterministic); the semantic/vector half is added when the query-embed
  --     edge path is wired. Only consulted when a task is supplied, and bounded to a slice of budget.
  if v_q is not null then
    v_out := v_out || jsonb_build_object('field_corpus', coalesce((
        select jsonb_agg(jsonb_build_object('title', title, 'citation', citation,
                                            'category', category, 'content', left(content, 1200))
                         order by rank desc)
          from (select title, citation, category, content, ts_rank(fts, v_q) as rank
                  from kb_chunks
                 where (category = any(v_scope)
                        or (p_category_key is not null and category = p_category_key))
                   and fts @@ v_q
                 order by ts_rank(fts, v_q) desc, effective_date desc nulls last
                 limit 12) k), '[]'::jsonb));
  else
    v_out := v_out || jsonb_build_object('field_corpus', '[]'::jsonb);
  end if;

  -- 5. LIVE DATA BINDINGS — what the agent must fetch rather than remember. The binding is
  --    knowledge; the value is not, and is never cached here.
  v_out := v_out || jsonb_build_object('live_data_required', coalesce((
      select jsonb_agg(jsonb_build_object('record_id', record_id, 'title', title,
                                          'binding', structured_data))
        from ops_knowledge
       where record_type = 'live_data_binding' and runtime_eligible
         and supersession_state = 'current'
         and (scope_type = 'company' or dept_key = any(v_scope))
       limit 12), '[]'::jsonb));

  -- 6. TOOLS the agent is actually allowed to execute.
  v_out := v_out || jsonb_build_object('tools', coalesce((
      select jsonb_agg(jsonb_build_object('action_class', action_class, 'kind', kind,
                                          'risk_tier', risk_tier, 'reversible', reversible,
                                          'required_authority', required_authority,
                                          'notifies_human', notifies_human))
        from org_action_executor
       where active and (department = any(v_scope) or target = p_agent_key)
       limit 30), '[]'::jsonb));

  -- collect every knowledge id the assembly actually used
  select v_ids || coalesce(array_agg(x), '{}') into v_ids
    from (select jsonb_array_elements(coalesce(v_out->'company_core','[]'::jsonb) ||
                                      coalesce(v_out->'department_knowledge','[]'::jsonb) ||
                                      coalesce(v_out->'role_knowledge','[]'::jsonb) ||
                                      coalesce(v_out->'category_knowledge','[]'::jsonb)) ->> 'record_id' x) s;

  return jsonb_build_object(
    'identity', v_identity,
    'task_class', p_task_class,
    'category_key', p_category_key,
    'company_objective', coalesce((
      select jsonb_agg(jsonb_build_object('key', key, 'goal', goal, 'metric', metric,
                                          'target', target_value, 'unit', unit, 'period', period,
                                          'owner_dept', owner_dept, 'horizon', horizon))
        from (select * from company_goals
               where active
               order by (owner_dept is not distinct from v_agent.department) desc,
                        (category = 'Financial') desc, sort
               limit 8) g), '[]'::jsonb),
    'budget_chars', v_budget,
    'knowledge_ids', to_jsonb(v_ids),
    'knowledge_count', coalesce(array_length(v_ids, 1), 0),
    'assembled_at', now()
  ) || v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_handoff_inbox(p_agent_key text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select string_agg(line, E'\n' order by created_at)
  from (
    select a.created_at,
           -- Bound the WHOLE line, not its parts. Capping title and recommendation separately
           -- still left four employees over budget because the prefix varies ("from Document
           -- Controller" is longer than "doc_task"). 215 x 3 lines + 2 newlines = 647, inside the
           -- 678 this inbox was trimmed to after it timed agent_brain out twice.
           left(
           '- #'||a.id||' ('||extract(day from now() - a.created_at)::int||'d old, '
             ||case when a.kind = 'handoff'
                    then 'from '||coalesce(a.detail->>'from_name', a.detail->>'from', 'a colleague')
                    else a.kind end
             ||case when a.kind = any(fn_agent_inbox_closable_kinds()) then '' else ', FOUNDER DECIDES — do not close' end
             ||'): '
             -- The TITLE was never capped, only the recommendation. With handoffs only that was
             -- harmless; the wider kinds carry long generated titles and the block measured 821
             -- characters for `docs` and 769 for `it` — both ABOVE the 678 this inbox was trimmed
             -- to after it timed agent_brain out twice at ~56s. `it`'s prompt is 30,821 tokens and
             -- its one prior success took 53,139 ms, so the margin is real and small. Capped at 80
             -- so three lines cannot exceed roughly the budget that was proved safe.
             ||coalesce(a.title,'(untitled)')
             ||coalesce(' — '||a.recommendation, '')
           , 215) as line
      from agent_actions a
     where coalesce(public.fn_org_agent_resolve(a.agent), a.agent)
         = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
       and a.status in ('pending','needs_review')
     order by a.created_at
     limit 3
  ) z;
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_inbox_closable_kinds()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select array(
    select distinct kind from public.agent_actions
     where kind is not null
       and lower(kind) !~ '(refund|payout|charge|payment|transfer|chargeback)'
    union
    select unnest(array['handoff','improvement_question','knowledge_task','ai_improvement',
      'report_recommendation','ops_recommendation','doc_task','report_task','objective_step',
      'supply_health','autonomy_stall','legal_flag','security_incident','customer_escalation',
      'compliance_update','strategy_rec','marketing_recommendation','incident','prompt_approval',
      'decision.route_category','finance_alert','finance_marketing_budget'])
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_agent_institutional_memory(p_agent_key text, p_limit integer DEFAULT 6)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_dept text; v_cat text; out text := ''; r record;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_agent_key is null then return ''; end if;

  select department into v_dept from org_agents where agent_key = p_agent_key;
  if p_agent_key like 'cat:%' then v_cat := replace(p_agent_key, 'cat:', ''); end if;

  for r in
    select m.kind, m.headline, m.detail, m.outcome, m.money_aed, m.category_slug, m.confidence
    from institutional_memory m
    where (m.visible_to is null
           or array_length(m.visible_to,1) is null
           or 'all' = any(m.visible_to)
           or v_dept = any(m.visible_to)
           or p_agent_key = any(m.visible_to))
      and (m.category_slug is null or m.category_slug = v_cat)
      and coalesce(m.confidence, 1) >= 0.6
    order by coalesce(m.occurred_at, m.created_at) desc, coalesce(m.confidence,0) desc
    limit greatest(coalesce(p_limit,6), 1)
  loop
    out := out || '## lesson (' || coalesce(r.kind,'note') || ')' || E'\n'
        || coalesce(r.headline,'') || E'\n'
        || left(coalesce(r.detail,''), 600)
        || case when r.outcome is not null then E'\n' || 'What changed as a result: ' || left(r.outcome, 300) else '' end
        || case when coalesce(r.money_aed,0) <> 0 then ' (AED ' || r.money_aed || ' at stake)' else '' end
        || E'\n\n';
  end loop;

  return out;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_agent_silence_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int:=0; f int:=0; g int:=0; nr int:=0; v_email text; v_run bigint;
begin
  insert into agent_runs(agent, started_at) values ('agent_silence_watch', clock_timestamp()) returning id into v_run;

  select to_email into v_email from notifications
   where type='founder_brief' and to_email is not null order by created_at desc limit 1;

  insert into cron_job_seen (jobid, jobname, schedule)
  select j.jobid, j.jobname, j.schedule from cron.job j where j.active
  on conflict (jobid) do update set last_seen = now(), jobname = excluded.jobname, schedule = excluded.schedule;

  -- Record successes BEFORE evaluating, so they survive the 14-day history prune.
  update cron_job_seen s
     set last_success = h.last_ok
    from (select jobid, max(start_time) as last_ok
            from cron.job_run_details where status='succeeded' group by jobid) h
   where h.jobid = s.jobid
     and (s.last_success is null or s.last_success < h.last_ok);

  for r in
    -- ONE AGGREGATE, NOT THREE CORRELATED SUBQUERIES PER JOB. This loop used to ask
    -- cron.job_run_details three separate questions for each of 165 active jobs against an 80 MB
    -- heap with no usable index, and on 11 Aug 2026 it began exceeding the statement timeout and
    -- stopped watching anything at all. A watchdog that dies silently is worse than no watchdog:
    -- fn_agent_silence_watch is the routine that would have reported its own absence.
    with h as (
      select jobid,
             count(*)                                                        as history_rows,
             max(start_time) filter (where status='succeeded')               as last_ok_live,
             count(*) filter (where status='failed'
                              and start_time > now() - interval '24 hours')  as fails_24h
        from cron.job_run_details
       group by jobid)
    select j.jobid, j.jobname,
           case when split_part(j.schedule,' ',5) <> '*' then 336
                when split_part(j.schedule,' ',3) <> '*' then 1440
                when split_part(j.schedule,' ',2) =  '*' then 6
                else 72 end as thresh_h,
           coalesce(h.history_rows, 0) as history_rows,
           greatest(h.last_ok_live, s.last_success) as last_ok,
           coalesce(h.fails_24h, 0) as fails_24h,
           s.first_seen,
           s.last_success as stored_ok
      from cron.job j
      left join h on h.jobid = j.jobid
      left join cron_job_seen s on s.jobid = j.jobid
     where j.active
  loop
    -- ACTIVATION IS THE FLOOR (3 Sep 2026). A job re-enabled today with a last success from before
    -- the 16 Aug stand-down is not silent — its clock starts when it was put back on (the kernel
    -- wrapper's wrapped_at). This watch paged the founder about 15 such jobs in one day.
    if exists (select 1 from public.phase_c_system_execution_wrapper w
                where w.jobid = r.jobid and w.wrapped_at > now() - (r.thresh_h||' hours')::interval) then
      continue;
    end if;
    -- Never-run: only when there is NO history AND we have never recorded a success.
    if r.history_rows = 0 and r.stored_ok is null then
      if r.first_seen is not null and r.first_seen < now() - (r.thresh_h||' hours')::interval then
        if not exists (select 1 from founder_alerts where event='cron_never_ran'
                        and detail like '%"'||r.jobname||'"%'
                        and created_at > now() - interval '24 hours') then
          insert into founder_alerts(level,event,detail,channel)
          values ('high','cron_never_ran', jsonb_build_object(
            'job', r.jobname,
            'first_seen', r.first_seen::text,
            'known_for_hours', round(extract(epoch from (now()-r.first_seen))/3600),
            'expected_within_hours', r.thresh_h)::text, 'email');
          -- 6 SEP 2026: routed to the IT operations engineer as one org_task per job, never emailed
          -- (founder_mail_policy.agent_silence); this watcher's own founder_alerts row above is its ledger.
          perform public.fn_founder_mail_route('agent_silence', 'Scheduled job has never run: '||r.jobname,
              'Job "'||r.jobname||'" is active but has no run history at all. It has been registered since '||
              r.first_seen::text||' and should have run at least every '||r.thresh_h||' hours. It is likely misregistered.', 'high');
          nr := nr + 1;
        end if;
      else
        g := g + 1;
      end if;
      continue;
    end if;

    if r.last_ok is null or r.last_ok < now() - (r.thresh_h||' hours')::interval then
      -- ONCE PER SILENCE EPISODE (3 Sep 2026): the episode is (job, last_success). It is paged the
      -- first time it is seen and never again until the job succeeds again — the 24-hour dedupe
      -- this replaced re-paged every silent job every day.
      if not exists (select 1 from founder_alerts where event='cron_silent'
                      and detail like '%"job": "'||r.jobname||'"%'
                      and detail like '%"last_success": "'||coalesce(r.last_ok::text,'no success on record')||'"%') then
        insert into founder_alerts(level,event,detail,channel)
        values ('high','cron_silent', jsonb_build_object(
          'job',r.jobname,'last_success',coalesce(r.last_ok::text,'no success on record'),
          'silent_hours',round(extract(epoch from (now()-r.last_ok))/3600),
          'expected_within_hours',r.thresh_h)::text,'email');
        perform public.fn_founder_mail_route('agent_silence', 'Scheduled job stopped: '||r.jobname,
            'Job "'||r.jobname||'" last succeeded '||coalesce(r.last_ok::text,'unknown')||
            '. Expected at least every '||r.thresh_h||' hours.', 'high');
        n := n + 1;
      end if;
    end if;

    if r.fails_24h > 0 then
      if not exists (select 1 from founder_alerts where event='cron_failing'
                      and detail like '%"'||r.jobname||'"%'
                      and created_at > now() - interval '24 hours') then
        insert into founder_alerts(level,event,detail,channel)
        values ('high','cron_failing',
          jsonb_build_object('job',r.jobname,'failures_24h',r.fails_24h,
                             'last_success',coalesce(r.last_ok::text,'unknown'))::text,'email');
        perform public.fn_founder_mail_route('agent_silence', 'Scheduled job failing: '||r.jobname,
            'Job "'||r.jobname||'" has failed '||r.fails_24h||' time(s) in the last 24 hours. Last success: '||
            coalesce(r.last_ok::text,'unknown')||'. Check cron.job_run_details for the error text.', 'high');
        f := f + 1;
      end if;
    end if;
  end loop;

  update agent_runs
     set finished_at=clock_timestamp(), status='ok',
         counts=jsonb_build_object('active_jobs',(select count(*) from cron.job where active),
                                   'in_grace',g,'silent',n,'failing',f,'never_ran',nr)
   where id=v_run;

  return jsonb_build_object('ran_at',now(),
    'active_jobs',(select count(*) from cron.job where active),
    'in_grace',g,'silent_alerts',n,'failing_alerts',f,'never_ran_alerts',nr);
exception when others then
  update agent_runs set finished_at=clock_timestamp(), status='error', note=left(sqlerrm,500) where id=v_run;
  raise;
end $function$


CREATE OR REPLACE FUNCTION public.fn_agent_tools(p_agent_key text, p_kind text DEFAULT NULL::text)
 RETURNS TABLE(tool_id text, purpose text, kind text, impl_kind text, impl_target text, input_schema jsonb, timeout_seconds integer, max_attempts integer, backoff text, failure_behaviour text, requires_current_data boolean, required_credential text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select a.agent_key, a.department,
           coalesce((select array_agg(i.packaged_role_id) from org_role_identity i
                      where i.agent_key = a.agent_key), '{}'::text[]) as role_ids
    from org_agents a
   where a.agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
     and a.active
  )
  select t.tool_id, t.purpose, t.kind, t.impl_kind, t.impl_target,
         t.input_schema, t.timeout_seconds, t.max_attempts, t.backoff,
         t.failure_behaviour, t.requires_current_data, t.required_credential
  from agent_tool t, me
  where t.active
    and t.staging_available
    and (p_kind is null or t.kind = p_kind)
    and (t.authorised_departments = '{}'::text[]
         or '*' = any(t.authorised_departments)
         or me.department = any(t.authorised_departments))
    and (t.authorised_roles = '{}'::text[]
         or '*' = any(t.authorised_roles)
         or me.role_ids && t.authorised_roles)
  order by t.kind, t.tool_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_agents_board()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with runs as (
    select agent, count(*) filter (where started_at > now() - interval '24 hours') as runs24,
           count(*) filter (where started_at > now() - interval '24 hours' and status in ('error','failed')) as fails24,
           max(started_at) as last_run, (array_agg(status order by started_at desc))[1] as last_status
    from agent_runs group by agent
  ), everyone as (
    select a.agent_key, coalesce(nullif(trim(a.department),''),'General') as department, a.role, a.kind, coalesce(a.active,true) as active,
      coalesce(r.runs24,0) as runs24, coalesce(r.fails24,0) as fails24, r.last_run, r.last_status
    from org_agents a left join runs r on r.agent = a.agent_key
  ), base as (select * from everyone where active),
  dc as (select department, count(*) c, sum(runs24) rs from base group by department)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'parked_total',(select count(*) from everyone where not active),
    'runs24',(select coalesce(sum(runs24),0) from base),
    'departments',(select coalesce(jsonb_agg(jsonb_build_object('key',d.department,'label',d.department,'count',d.c,'runs',d.rs,
        'cards',(select jsonb_agg(jsonb_build_object('id',b.agent_key,'agent_key',b.agent_key,'role',b.role,'kind',b.kind,'active',b.active,'runs24',b.runs24,'fails24',b.fails24,'last_status',b.last_status,'last_run',b.last_run) order by b.runs24 desc, b.agent_key) from base b where b.department=d.department))
        order by d.rs desc nulls last, d.department),'[]'::jsonb) from dc d),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.agent_key,'agent_key',b.agent_key,'department',b.department,'role',b.role,'kind',b.kind,'active',b.active,'runs24',b.runs24,'fails24',b.fails24,'last_status',b.last_status,'last_run',b.last_run) order by b.runs24 desc, b.agent_key),'[]'::jsonb) from base b),
    -- Parked personas: greyed in the UI, labelled "parked", never "error". No run figures either —
    -- a persona that is not on the roster has no run rate, only a history.
    'parked',(select coalesce(jsonb_agg(jsonb_build_object('id',e.agent_key,'agent_key',e.agent_key,'department',e.department,'role',e.role,'kind',e.kind,'active',false,'runs24',0,'fails24',0,'last_status',null,'last_run',e.last_run) order by e.department, e.agent_key),'[]'::jsonb) from everyone e where not e.active)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_confidence_prior(p_agent_key text, p_task_class text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- A CONSTANT IS NOT A MEASUREMENT, AND THIS IS THE GUARD THAT SAYS SO.
  -- The founder's own reading of the two existing emitters: "always emit exactly 1.000, which
  -- carries no information". A model that reports the same number every time would otherwise
  -- downgrade itself to a cheaper tier on the strength of its own unvarying optimism. stddev = 0
  -- over the window means the signal has no content, so it does not route anything. n >= 5 for the
  -- same reason at the other end: one confident answer is an anecdote.
  select case
           when count(*) >= 5 and coalesce(stddev_samp(confidence), 0) > 0
           then jsonb_build_object(
                  'prior', round(percentile_cont(0.5) within group (order by confidence)::numeric, 4),
                  'n', count(*),
                  'spread', round(stddev_samp(confidence)::numeric, 4))
           else null
         end
    from public.ai_cost_log
   where agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
     and task_class = p_task_class
     and confidence is not null
     and occurred_at > now() - interval '14 days';
$function$


CREATE OR REPLACE FUNCTION public.fn_ai_quality_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_regs int:=0; v_spikes int:=0; v_detail jsonb; v_open int; v_owner text; v_t0 timestamptz := now();
begin
  -- ONE ROW PER AGENT PER NIGHT. Resolved to the canonical key here rather than left to the BEFORE
  -- INSERT trigger, because the trigger fires per row and therefore turns N raw agents into N rows
  -- that all claim the same identity. The rate is recomputed from the underlying counts, never
  -- averaged from the per-row percentages.
  insert into public.ai_quality_snapshots(agent, override_pct, actions_30d)
  select k.agent,
         round(100.0 * sum(v.rejected_30d)::numeric / nullif(sum(v.actions_30d), 0), 1),
         sum(v.actions_30d)::int
    from public.v_ai_agent_health v
    cross join lateral (select case
             when exists (select 1 from public.org_agents o where o.agent_key = v.agent and o.active)
               then v.agent
             else coalesce(public.fn_org_agent_resolve(v.agent), v.agent)
           end as agent) k
   where v.override_pct is not null
   group by k.agent
  having sum(v.actions_30d) > 0;

  with ranked as (
    select prompt_key, score, created_at,
           row_number() over(partition by prompt_key order by created_at desc) rn
    from public.prompt_eval_runs
  ),
  reg as (
    select c.prompt_key, c.score cur, p.score prev
    from ranked c join ranked p on p.prompt_key=c.prompt_key and p.rn=2
    where c.rn=1 and (c.score < p.score - 5 or c.score < 70)
  ),
  ins as (
    insert into public.security_events(kind,severity,source,subject,detail)
    select 'eval_regression', case when cur<70 then 'high' else 'medium' end, 'ai_quality_watch', prompt_key,
           jsonb_build_object('current',cur,'previous',prev)
    from reg returning 1
  )
  select count(*) into v_regs from ins;

  with cur as (
    -- Same resolution rule as the insert above, so `cur` and `hist` speak one vocabulary. Before
    -- this, 17 of 52 agents carried a raw name here and a canonical one in the snapshot, and the
    -- join below could not match them at all.
    select k.agent,
           round(100.0 * sum(v.rejected_30d)::numeric / nullif(sum(v.actions_30d), 0), 1) as override_pct,
           sum(v.actions_30d)::int as actions_30d
      from public.v_ai_agent_health v
      cross join lateral (select case
               when exists (select 1 from public.org_agents o where o.agent_key = v.agent and o.active)
                 then v.agent
               else coalesce(public.fn_org_agent_resolve(v.agent), v.agent)
             end as agent) k
     where v.override_pct is not null
     group by k.agent
    having sum(v.actions_30d) >= 5
       and k.agent not in ('security','onboarding','email')
  ),
  hist as (
    -- Weighted by actions, not a flat mean of percentages: the historical rows still contain the
    -- pre-fix duplicates, and a flat avg lets an agent with one action in a month move the trailing
    -- average as much as one with a hundred and sixty.
    select agent,
           sum(override_pct * greatest(actions_30d, 1))::numeric / nullif(sum(greatest(actions_30d, 1)), 0) as avg_prev,
           count(*) n
    from public.ai_quality_snapshots where at < now()-interval '12 hours' group by agent
  ),
  spike as (
    select c.agent, c.override_pct, round(h.avg_prev,1) avg_prev
    from cur c join hist h on h.agent=c.agent
    where h.n>=1 and c.override_pct > coalesce(h.avg_prev,0)+20
  ),
  ins2 as (
    insert into public.security_events(kind,severity,source,subject,detail)
    select 'override_spike','medium','ai_quality_watch', agent,
           jsonb_build_object('override_pct',override_pct,'trailing_avg',avg_prev)
    from spike returning 1
  )
  select count(*) into v_spikes from ins2;

  v_detail := jsonb_build_object('eval_regressions',v_regs,'override_spikes',v_spikes);

  -- Added 10 Aug 2026: this routine has detected quality falling since it was written and never
  -- emitted an event, so nothing downstream could react to it.
  if v_regs + v_spikes > 0 then
    perform fn_emit('ai.confidence_dropped',
                    case when se.kind='eval_regression' then 'prompt' else 'agent' end,
                    se.subject, 'ai_quality_watch',
                    se.detail || jsonb_build_object('finding', se.kind, 'severity', se.severity))
       from public.security_events se
      where se.source='ai_quality_watch' and se.kind in ('eval_regression','override_spike')
        and se.created_at >= v_t0;
  end if;

  if v_regs+v_spikes > 0 then
    select count(*) into v_open from public.agent_actions
      where kind='ai_quality_alert' and coalesce(status,'') in ('pending','needs_review')
        and created_at > now()-interval '24 hours';
    if v_open = 0 then
      insert into public.agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
      values('ai_trainer','ai_quality_alert','pending','medium',
        'AI quality alert: '||v_regs||' eval regression(s), '||v_spikes||' override spike(s)',
        'Open the AI Observability dashboard and review security_events of kind eval_regression / override_spike. Consider rolling back the regressed prompt version, or investigating why a human-facing agent''s suggestions are being rejected.',
        'security_events', v_detail);
      select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner
        from public.app_secrets where key='admin_emails';
      insert into public.notifications(type,to_email,to_role,channel,subject,body,status)
      values('ai_quality_alert', v_owner,'admin','email','QuotesDone: AI quality alert',
        'The AI quality watch flagged '||v_regs||' eval regression(s) and '||v_spikes||' override spike(s). Open the AI Observability dashboard and check security_events (kind eval_regression / override_spike).','queued');
    end if;
  end if;
  return v_detail;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_ai_route(p_task_class text DEFAULT NULL::text, p_dept_key text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric, p_fn text DEFAULT NULL::text, p_escalate boolean DEFAULT false, p_require_caps text[] DEFAULT NULL::text[], p_agent_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_class   text;
  v_src     text;
  v_pol     model_policy%rowtype;
  v_reg     model_registry%rowtype;
  v_fb      model_registry%rowtype;
  v_bud     department_budget%rowtype;
  v_pct     numeric := 0;
  v_model   text;
  v_why     text;
  v_min     numeric;
  v_tier    text;
  v_vis     boolean := 'vision' = any(coalesce(p_require_caps, '{}'::text[]));
  v_aud     boolean := 'audio'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_tls     boolean := 'tools'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_sub     model_registry%rowtype;
  v_want    int;
  v_idp     model_policy_by_identity%rowtype;
  v_generic boolean := false;
  v_rt      jsonb;
  v_prior   jsonb;
  v_conf    numeric;
  v_rtier   text;
  v_canon   text;
begin
  if p_task_class is not null and length(btrim(p_task_class)) > 0 then
    v_class := p_task_class; v_src := 'caller-supplied task_class';
  else
    select task_class into v_class from fn_task_class where fn = p_fn and active;
    if v_class is not null then
      v_src := 'classified from calling function "' || p_fn || '"';
    else
      v_class := 'general_drafting';
      v_generic := true;
      v_src := 'UNMAPPED function "' || coalesce(p_fn,'?') || '" - defaulted to general_drafting (medium). Add a fn_task_class row to route this properly.';
    end if;
  end if;

  -- THE PACK'S FOUR-ROLE TAXONOMY REACHES THE PATH IT WAS WRITTEN FOR (14 Aug 2026).
  --
  -- All 93 employees carry org_agents.routing_tier - director 36, operations_specialist 23,
  -- analyst_controller 21, reviewer_auditor 10 - and on the main employee path it was DEAD.
  -- fn_routing_tier_model below only fires when v_generic is true, i.e. when the calling function
  -- is unmapped; agent_brain IS mapped, to agent_reasoning, so every employee from a marketing
  -- copywriter to the CEO got the same blanket large tier.
  --
  -- Meanwhile model_policy carries routine_employee_reasoning at MEDIUM, and its own rationale
  -- says: "Pack: replaces the current blanket large-tier agent_reasoning. agent_reasoning is LIVE
  -- on anthropic/claude-sonnet-5 and agent_brain is ~93% of OpenRouter spend." It had ZERO callers.
  -- A policy written to replace something, that nothing points at, is a build order nobody wired.
  --
  -- This is a ROUTING decision taken from the role, not an override of task_class routing: the
  -- class is chosen by who is asking, then the policy for that class applies normally.
  --
  -- WHO STAYS ON LARGE, AND WHY. Only operations_specialist moves. reviewer_auditor stays large
  -- deliberately - all 24 Reviewer/Auditor rows in the pack name a large model, and a reviewer on
  -- the cheap model is a green check that means nothing. director and analyst_controller stay
  -- because their work is the consequential kind the large tier exists for.
  if v_class = 'agent_reasoning' and p_agent_key is not null then
    v_canon := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
    select a.routing_tier into v_rtier from org_agents a
     where a.agent_key = v_canon and a.active;
    if v_rtier = 'operations_specialist'
       and exists (select 1 from model_policy mp
                    where mp.task_class = 'routine_employee_reasoning' and mp.active) then
      v_class := 'routine_employee_reasoning';
      v_src := v_src || ' | routing_tier "operations_specialist" for "' || v_canon
                     || '" selected the routine employee class instead of the blanket large tier';
    end if;
  end if;

  select * into v_pol from model_policy where task_class = v_class and active;
  if not found then
    select * into v_pol from model_policy where task_class = 'general_drafting' and active;
    v_src := v_src || ' | no policy for "' || v_class || '", fell back to general_drafting';
    v_generic := true;
  end if;

  -- THE ROLE DEFAULT. model_policy_by_identity carries 120 rows — 96 target employees and 24
  -- current production agents — and had NO reader in the database at all. The pack states its own
  -- precedence on every row: note = 'Role default only; task_class routing overrides it.' So it
  -- applies only where the caller would otherwise get the generic general_drafting fallback:
  -- either the named class has no policy, or the calling function is unmapped in fn_task_class.
  --
  -- v_generic exists because the first version of this branch was UNREACHABLE. It hung off
  -- `if not found` on the model_policy lookup, and an unmapped function has already had v_class
  -- rewritten to 'general_drafting' by then — which IS found. Measured: fn_ai_route(...,'ceo')
  -- returned identity_policy null. Same shape as the unreachable block in
  -- fn_kb_route_activation_blocked found earlier today: a branch guarded by a condition that
  -- cannot occur.
  --
  -- 23 of the 24 current_agent keys resolve to a real org_agents row; 'cat:*' covers the
  -- category desks.
  if v_generic and p_agent_key is not null then
    select * into v_idp from model_policy_by_identity
     where scope = 'current_agent'
       and (identity_key = p_agent_key
            or (identity_key = 'cat:*' and p_agent_key like 'cat:%'))
     order by (identity_key = p_agent_key) desc
     limit 1;
    if found and v_idp.primary_model is not null then
      v_pol.model_primary  := v_idp.primary_model;
      v_pol.model_fallback := coalesce(v_idp.fallback_model, v_pol.model_fallback);
      v_pol.max_tokens     := coalesce(v_idp.max_output_tokens, v_pol.max_tokens);
      v_src := v_src || ' | role default for "' || p_agent_key || '" applied from model_policy_by_identity';
    end if;
  end if;

  -- ---- ROUTING TIER, added 11 Aug 2026 ---------------------------------------------------------
  -- The pack's four-role taxonomy carried onto the 93 real employees as org_agents.routing_tier.
  -- Fires LAST and only if the pack had nothing to say about this specific agent, so an explicit
  -- current_agent row always wins. Resolves tier -> registry tier -> cheapest active approved model
  -- AT CALL TIME: no model id is stored anywhere, so this follows the fleet instead of going stale.
  -- Measured direction against the general_drafting default (haiku, 1.00 USD/Mtok in):
  -- operations_specialist 4x cheaper, analyst/director unchanged, reviewer_auditor 2x dearer and
  -- deliberately so - all 24 Reviewer/Auditor rows in the pack name sonnet-5, and a reviewer on the
  -- cheap model is a green check that means nothing.
  if v_generic and p_agent_key is not null and v_idp.identity_key is null then
    v_rt := public.fn_routing_tier_model(p_agent_key);
    if v_rt is not null and (v_rt->>'model') is not null then
      v_pol.model_primary := v_rt->>'model';
      v_pol.tier          := v_rt->>'registry_tier';
      v_src := v_src || ' | routing_tier "' || (v_rt->>'routing_tier') || '" for "' || p_agent_key
                     || '" resolved to ' || (v_rt->>'model') || ' (' || (v_rt->>'registry_tier') || ' tier)';
    end if;
  end if;
  -- ----------------------------------------------------------------------------------------------

  if v_pol.tier = 'none' then
    return jsonb_build_object(
      'use_llm', false, 'task_class', v_class, 'tier', 'none',
      'why', 'REFUSED. ' || coalesce(v_pol.deterministic_alternative, 'This is deterministic - use code.')
             || ' [' || v_src || ']',
      'deterministic_alternative', v_pol.deterministic_alternative);
  end if;

  v_tier  := v_pol.tier;
  v_model := v_pol.model_primary;
  v_why   := coalesce(v_pol.rationale, 'policy for ' || v_class) || ' [' || v_src || ']';

  if p_escalate then
    v_model := coalesce(v_pol.model_fallback, v_model);
    v_why   := v_why || ' | ESCALATED one tier after an unsatisfactory cheaper attempt';
  end if;

  select (value #>> '{}')::numeric into v_min from decision_policy where key = 'confidence_min';
  -- THE PRIOR, 11 Aug 2026. Both arms below are original and NEITHER HAS EVER FIRED, because
  -- p_confidence is the confidence of THIS call and no caller can know that before the call.
  -- Measured the day this was written: 7 of 1,746 model calls in seven days carried a confidence at
  -- all. The only confidence that CAN exist beforehand is the agent's own recent record on this
  -- task class, so that is what a caller supplying nothing now routes on.
  --
  -- fn_ai_confidence_prior returns null unless there are at least 5 observations AND they vary.
  -- The variance guard is the important half: the two callers that emitted a confidence before
  -- tonight always emitted exactly 1.0000, and a model reporting the same number every time would
  -- otherwise downgrade itself to a cheaper tier on the strength of its own unvarying optimism.
  v_conf := p_confidence;
  if v_conf is null and p_agent_key is not null then
    v_prior := public.fn_ai_confidence_prior(p_agent_key, v_class);
    if v_prior is not null then v_conf := (v_prior->>'prior')::numeric; end if;
  end if;

  if v_conf is not null then
    if v_conf >= 0.95 and v_tier in ('large','xlarge') then
      select model_id into v_model from model_registry
       where active and approved and tier = 'medium' order by in_per_mtok_usd limit 1;
      v_why := v_why || ' | confidence ' || v_conf
               || case when v_prior is null then ''
                       else ' (' || p_agent_key || ' own median over ' || (v_prior->>'n')
                            || ' calls on ' || v_class || ', spread ' || (v_prior->>'spread') || ')' end
               || ' >= 0.95, downgraded to medium - no second opinion needed';
    elsif v_min is not null and v_conf < v_min and v_tier = 'small' then
      v_model := coalesce(v_pol.model_fallback, v_model);
      v_why := v_why || ' | confidence ' || v_conf
               || case when v_prior is null then ''
                       else ' (' || p_agent_key || ' own median over ' || (v_prior->>'n') || ' calls)' end
               || ' below floor ' || v_min || ', escalated a tier';
    end if;
  end if;

  -- A CALL WITH NO DEPARTMENT IS A CALL NO CEILING CAN STOP (13 Aug 2026). The halt below needs a
  -- dept_key to find a budget, and 59 of this month's calls arrived without one - inquiry_intake,
  -- drawing_boq, doc_extract, license_extract, supplier_onboard and eleven more, i.e. the demand
  -- path. fn_task_class already maps fn -> task_class for this same function's model choice; it now
  -- carries the owning department too, so an un-attributed call is attributed by what it IS rather
  -- than left outside every ceiling. An explicit p_dept_key from the caller still wins.
  -- CANONICAL BEFORE THE CEILING (14 Aug 2026). department_budget holds the ten canonical rows;
  -- a caller passing a merged-away key ('procurement', 'marketing', 'sales' ...) found NO budget
  -- row and skipped the ceiling entirely. fn_dept_canonical resolves the key the caller used to
  -- the department that actually owns it.
  if public.fn_dept_canonical(coalesce(p_dept_key, (select t.dept_key from fn_task_class t where t.fn = p_fn and t.active))) is not null then
    select * into v_bud from department_budget
     where dept_key = public.fn_dept_canonical(coalesce(p_dept_key, (select t.dept_key from fn_task_class t where t.fn = p_fn and t.active)));
    if found and v_bud.monthly_aed > 0 then
      v_pct := round(100 * coalesce(
        (select sum(cost_aed) from ai_cost_log
          where dept_key = any(public.fn_dept_scope(v_bud.dept_key))
            and occurred_at >= date_trunc('month', now())), 0)
        / v_bud.monthly_aed, 2);
      if v_pct >= v_bud.halt_at_pct then
        return jsonb_build_object(
          'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'halted', true, 'budget_pct', v_pct,
          'why', 'HALTED. ' || v_bud.dept_key || ' is at ' || v_pct || '% of its monthly AI budget (halt at '
                 || v_bud.halt_at_pct || '%). Non-gated work stops until the budget resets or is raised.');
      elsif v_pct >= v_bud.degrade_at_pct then
        select model_id into v_model from model_registry
         where active and approved
           and tier = case v_tier when 'xlarge' then 'large' when 'large' then 'medium' else 'small' end
         order by in_per_mtok_usd limit 1;
        v_why := v_why || ' | department at ' || v_pct || '% of budget, degraded one tier';
      end if;
    end if;
  end if;

  select * into v_reg from model_registry where model_id = v_model and active;
  if not found then
    select * into v_reg from model_registry
     where active and approved and tier = (case v_tier when 'xlarge' then 'xlarge' else v_tier end)
     order by in_per_mtok_usd limit 1;
    v_why := v_why || ' | WARNING: policy model "' || v_model || '" is not in model_registry; substituted ' || coalesce(v_reg.model_id,'(none)');
    v_model := v_reg.model_id;
  end if;

  -- CAPABILITY. Price and tier chose the model above; if it cannot see, hear or call tools the
  -- provider will simply reject the payload. Substitute the nearest capable model, preferring the
  -- intended tier, then the closest tier ABOVE it, and only then below - a capability substitution
  -- must never quietly become a quality downgrade.
  v_want := fn_ai_route_tier_rank(v_tier);
  if (v_vis or v_aud or v_tls)
     and not ( (not v_vis or coalesce(v_reg.supports_vision,false))
           and (not v_aud or coalesce(v_reg.supports_audio, false))
           and (not v_tls or coalesce(v_reg.supports_tools, false)) ) then

    select * into v_sub from model_registry
     where active and approved
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want),                 -- at-or-above the tier first
              abs(fn_ai_route_tier_rank(tier) - v_want),              -- then closest to it
              in_per_mtok_usd                                          -- then cheapest
     limit 1;

    if found then
      v_why := v_why || ' | CAPABILITY OVERRIDE: ' || v_model || ' cannot do ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+') || '); substituted ' || v_sub.model_id
               || ' (' || v_sub.tier || ' tier, intended ' || v_tier || ')';
      v_reg := v_sub; v_model := v_sub.model_id;
    else
      return jsonb_build_object(
        'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'caps', to_jsonb(p_require_caps),
        'why', 'REFUSED. No active approved model in model_registry supports ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+')
               || '). Add one, or mark the capability on an existing model.');
    end if;
  end if;

  select * into v_fb from model_registry
   where model_id = v_pol.model_fallback and active
     and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools);
  if not found and (v_vis or v_aud or v_tls) then
    select * into v_fb from model_registry
     where active and approved and model_id <> v_model
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want), abs(fn_ai_route_tier_rank(tier) - v_want), in_per_mtok_usd
     limit 1;
  end if;

  return jsonb_build_object(
    'use_llm', true,
    'task_class', v_class,
    'tier', v_tier,
    'model', v_model,
    'fallback', v_fb.model_id,
    'max_tokens', v_pol.max_tokens,
    'cache_ttl_min', coalesce(v_pol.cache_ttl_min, 0),
    'cache', coalesce(v_reg.supports_cache, false),
    'stream', coalesce(v_reg.supports_streaming, true),
    'caps', to_jsonb(coalesce(p_require_caps, '{}'::text[])),
    'in_per_mtok_usd', v_reg.in_per_mtok_usd,
    'out_per_mtok_usd', v_reg.out_per_mtok_usd,
    'cache_read_per_mtok_usd', v_reg.cache_read_per_mtok_usd,
    'budget_pct', v_pct,
    'identity_policy', case when v_idp.identity_key is null then null else jsonb_build_object(
        'identity_key', v_idp.identity_key, 'deterministic_first', v_idp.deterministic_first,
        'reasoning_effort', v_idp.reasoning_effort, 'authority_tier', v_idp.authority_tier) end,
    'routing_tier', v_rt,
    'confidence_prior', v_prior,
    'confidence_used', v_conf,
    'why', v_why);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ai_route_tier_rank(p_tier text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ select case p_tier when 'small' then 1 when 'medium' then 2 when 'large' then 3 when 'xlarge' then 4 else 0 end $function$


CREATE OR REPLACE FUNCTION public.fn_alert_severe(p_level text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- Deliberately generous and deliberately explicit. Anything a routine plausibly means as
  -- "somebody has to look at this now". info / warn / warning / action are NOT severe and stay out.
  select lower(coalesce(p_level,'')) in ('critical','crit','error','high','fatal','sev1','urgent');
$function$


CREATE OR REPLACE FUNCTION public.fn_ap_bill_dupe_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prior bigint;
begin
  if coalesce(new.status,'') in ('void','duplicate_hold') then return new; end if;

  select id into v_prior from ap_bills
  where vendor_id = new.vendor_id
    and coalesce(status,'') not in ('void','duplicate_hold')
    and id is distinct from new.id
    and total = new.total
    and bill_date = new.bill_date
  order by id limit 1;

  if v_prior is not null then
    new.status := 'duplicate_hold';

    insert into brand_signal (signal_type, severity, subject_type, subject_id, rule_key, detail, evidence)
    values ('fake_supplier','critical','ap_bill', coalesce(new.bill_no, new.id::text), 'duplicate_invoice_presented',
            'Same vendor, same amount, same date as an invoice already booked. Held, not posted.',
            jsonb_build_object('vendor_id', new.vendor_id, 'total', new.total,
                               'bill_date', new.bill_date, 'prior_bill_id', v_prior,
                               'presented_bill_no', new.bill_no))
    on conflict do nothing;

    insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                      money_aed, learned_by, confidence, evidence_ref)
    values ('pattern','ap_bill', coalesce(new.bill_no, new.id::text),
            'Duplicate invoice presentation held before payment.',
            format('Vendor %s presented %s for %s on %s, matching bill id %s already on file.',
                   new.vendor_id, coalesce(new.bill_no,'(no ref)'), new.total, new.bill_date, v_prior),
            'held as duplicate_hold; not posted, not paid', new.total, 'finance_bookkeeper', 1.0,
            'trg_ap_bill_dupe_guard; ap_bills id ' || v_prior);

    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('invoice.flagged','ap_bill', coalesce(new.bill_no, new.id::text), 'finance_bookkeeper',
            jsonb_build_object('reason','duplicate_invoice','vendor_id', new.vendor_id,
                               'total', new.total,'prior_bill_id', v_prior));

    raise warning 'invoice held as duplicate of bill id %', v_prior;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_ap_pay_block_held()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status in ('paid','partial') and coalesce(old.status,'') = 'duplicate_hold' then
    raise exception 'bill % is held as a duplicate and cannot be paid until a person clears the hold',
      coalesce(new.bill_no, new.id::text);
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_apply_playbook(p_agent_key text, p_query_embedding vector, p_query_text text, p_min_similarity real DEFAULT 0.85, p_k integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lexemes    text[];
  v_total      int;
  v_row        record;
  -- scalars, not a record compared to null: an unassigned plpgsql record RAISES on `is null`
  v_found      boolean := false;
  v_b_id text; v_b_title text; v_b_content text; v_b_layer text; v_b_type text; v_b_tier text;
  v_b_sim real := -1; v_b_terms int := 0; v_b_sd jsonb;
  v_n_seen     boolean := false;
  v_n_type text; v_n_title text; v_n_sim real; v_n_terms int;
  v_candidates jsonb := '[]'::jsonb;
  v_terms      int;
  v_pass       boolean;
  v_reason     text;
  v_det        text;
  v_key        text;
  v_dept       text;
  v_scope      text[];
  v_role_ids   text[];
begin
  if p_query_embedding is null then
    return jsonb_build_object('matched', false, 'reason', 'no query embedding supplied');
  end if;

  -- The step's own vocabulary, normalised the same way ops_knowledge.tsv is (english stemming).
  select array_agg(distinct lexeme) into v_lexemes
    from unnest(to_tsvector('english', coalesce(p_query_text, '')))
   where length(lexeme) >= 3;
  v_total := coalesce(array_length(v_lexemes, 1), 0);

  -- HYBRID, ACTIONABLE-ONLY RETRIEVAL. fn_ops_knowledge_match's top-20 by cosine is dominated by metric
  -- definitions, failure cases and scenarios (measured: the actionable SOP that DOES corroborate
  -- "Detect from health, drift or a failed gate" — SOP 04 Security Alert Triage — never reached the
  -- top 20). So the candidate set is: in-scope rows of the four actionable kinds, ranked by cosine.
  -- The scope predicate MIRRORS fn_ops_knowledge_match exactly (agent -> department -> fn_dept_scope,
  -- packaged roles via org_role_identity, company/external); change both or neither.
  v_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  select a.department into v_dept from public.org_agents a where a.agent_key = v_key;
  if v_dept is null then
    return jsonb_build_object('matched', false, 'reason', 'agent ' || coalesce(p_agent_key,'?') || ' resolves to no department; no scope');
  end if;
  v_scope := public.fn_dept_scope(v_dept);
  select array_agg(packaged_role_id) into v_role_ids from public.org_role_identity where agent_key = v_key;

  for v_row in
    select k.record_id, k.title, k.content, k.layer, k.record_type, k.authority_tier,
           (1 - (k.embedding_gte <=> p_query_embedding))::real as similarity,
           k.structured_data,
           (select count(*) from unnest(tsvector_to_array(k.tsv)) t where t = any(coalesce(v_lexemes, '{}'))) as terms_matched
      from public.ops_knowledge k
     where k.embedding_gte is not null
       and k.runtime_eligible
       and k.supersession_state = 'current'
       and k.record_type in ('decision_playbook','decision_rule','standard_operating_procedure','exception_playbook')
       and (
             k.scope_type in ('company','external_source')
          or (k.scope_type = 'department' and k.dept_key = any(v_scope))
          or (k.role_key = any(coalesce(v_role_ids, '{}')))
       )
     order by k.embedding_gte <=> p_query_embedding
     limit greatest(coalesce(p_k, 20), 1)
  loop
    v_terms := coalesce(v_row.terms_matched, 0);
    if not v_n_seen then
      v_n_seen := true; v_n_type := v_row.record_type; v_n_title := v_row.title;
      v_n_sim := v_row.similarity; v_n_terms := v_terms;
    end if;
    v_pass := v_row.record_type in ('decision_playbook','decision_rule','standard_operating_procedure','exception_playbook')
              and v_row.similarity >= p_min_similarity
              and v_terms >= 2
              and v_total > 0 and v_terms::numeric / v_total >= 0.30
              and length(coalesce(v_row.content, '')) >= 300;
    v_candidates := v_candidates || jsonb_build_object(
      'record_id', v_row.record_id, 'title', v_row.title, 'layer', v_row.layer,
      'record_type', v_row.record_type, 'similarity', round(v_row.similarity::numeric, 4),
      'terms_matched', v_terms, 'terms_total', v_total, 'corroborated', v_pass);
    if v_pass and (not v_found or v_row.similarity > v_b_sim) then
      v_found := true; v_b_id := v_row.record_id; v_b_title := v_row.title; v_b_content := v_row.content;
      v_b_layer := v_row.layer; v_b_type := v_row.record_type; v_b_tier := v_row.authority_tier;
      v_b_sim := v_row.similarity; v_b_terms := v_terms; v_b_sd := v_row.structured_data;
    end if;
  end loop;

  if not v_found then
    v_reason := case when not v_n_seen then 'no in-scope knowledge for this agent'
                     else 'no corroborated actionable match: nearest is ' || coalesce(v_n_type,'?')
                          || ' "' || coalesce(v_n_title,'') || '" at ' || round(v_n_sim::numeric, 3)
                          || ' (floor ' || p_min_similarity || ', noise median 0.837) sharing '
                          || coalesce(v_n_terms, 0) || ' of ' || v_total || ' step terms'
                end;
    return jsonb_build_object('matched', false, 'reason', v_reason, 'candidates', v_candidates,
                              'terms_total', v_total);
  end if;

  v_det := coalesce(v_b_content, '');
  if v_b_sd is not null and v_b_sd <> '{}'::jsonb then
    v_det := v_det || E'\n\nSTRUCTURED DETERMINATION (from the record''s structured_data):\n'
             || jsonb_pretty(v_b_sd);
  end if;

  return jsonb_build_object(
    'matched',        true,
    'record_id',      v_b_id,
    'title',          v_b_title,
    'layer',          v_b_layer,
    'record_type',    v_b_type,
    'authority_tier', v_b_tier,
    'similarity',     round(v_b_sim::numeric, 4),
    'terms_matched',  v_b_terms,
    'terms_total',    v_total,
    'confidence',     round(v_b_sim::numeric, 3),
    'determination',  v_det,
    'outcome',        'Applied the company ' || v_b_type || ' "' || v_b_title
                      || '" to this step (cosine ' || round(v_b_sim::numeric, 3)
                      || ', corroborated by ' || v_b_terms || ' of ' || v_total || ' step terms).',
    'candidates',     v_candidates,
    'basis',          'deterministic: nearest ACTIONABLE company knowledge by meaning, corroborated by the step''s own terms; no model call'
  );
end
$function$


CREATE OR REPLACE FUNCTION public.fn_approval_decide(p_request uuid, p_actor uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare r public.procurement_approval_request;
        v_steps jsonb; v_n int; v_step jsonb; v_role text; v_actor_role text;
        v_next int; v_status text;
begin
  if coalesce(p_decision, '') not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected, got %', p_decision;
  end if;
  select * into r from public.procurement_approval_request where id = p_request for update;
  if not found then raise exception 'approval request % not found', p_request; end if;
  if r.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'already_' || r.status,
                              'request_id', r.id, 'status', r.status);
  end if;

  -- THE TRUST BOUNDARY IS HERE, NOT IN THE ENDPOINT. Every caller — the customer endpoint, the
  -- staff console, a psql session — routes through this routine, so the membership and role check
  -- lives in it once instead of in each caller.
  select m.role into v_actor_role
    from public.customer_organization_member m
   where m.organization_id = r.organization_id and m.user_id = p_actor and coalesce(m.active, true);
  if v_actor_role is null then
    if exists (select 1 from public.customer_organization o
                where o.id = r.organization_id and o.owner_customer_id = p_actor) then
      v_actor_role := 'owner';
    else
      raise exception 'actor % is not an active member of organization %', p_actor, r.organization_id;
    end if;
  end if;

  select p.steps into v_steps from public.procurement_approval_policy p where p.id = r.policy_id;
  v_steps := coalesce(v_steps, '[]'::jsonb);
  v_n := jsonb_array_length(v_steps);
  if v_n = 0 then raise exception 'approval request % has no policy steps', r.id; end if;
  if r.current_step < 1 or r.current_step > v_n then
    raise exception 'approval request % is at step % of %', r.id, r.current_step, v_n;
  end if;

  v_step := v_steps -> (r.current_step - 1);
  v_role := v_step->>'role';
  if v_role is not null and v_actor_role <> v_role and v_actor_role <> 'owner' then
    raise exception 'step % (%) is decided by %, not %',
      r.current_step, coalesce(v_step->>'label', v_step->>'key'), v_role, v_actor_role;
  end if;

  if p_decision = 'rejected' then      v_status := 'rejected'; v_next := r.current_step;
  elsif r.current_step >= v_n then     v_status := 'approved'; v_next := r.current_step;
  else                                 v_status := 'pending';  v_next := r.current_step + 1;
  end if;

  update public.procurement_approval_request
     set decisions = decisions || jsonb_build_array(jsonb_build_object(
           'step', r.current_step,
           'key', v_step->>'key',
           'label', coalesce(v_step->>'label', v_step->>'key', 'Step ' || r.current_step),
           'decision', p_decision,
           'by', p_actor,
           'by_role', v_actor_role,
           'at', now(),
           'note', p_note)),
         current_step = v_next,
         status = v_status
   where id = r.id;

  return jsonb_build_object('ok', true, 'request_id', r.id, 'status', v_status,
                            'decided_step', r.current_step, 'current_step', v_next,
                            'steps_total', v_n, 'decided_by', p_actor, 'decided_by_role', v_actor_role);
end $function$


CREATE OR REPLACE FUNCTION public.fn_approval_list(p_customer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with orgs as (
    select o.id, o.name from public.customer_organization o where o.owner_customer_id = p_customer
    union
    select o.id, o.name from public.customer_organization o
      join public.customer_organization_member m on m.organization_id = o.id
     where m.user_id = p_customer and coalesce(m.active, true)
  )
  select jsonb_build_object(
    'organizations', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'name', name) order by name) from orgs), '[]'::jsonb),
    'policies', coalesce((select jsonb_agg(jsonb_build_object(
          'id', p.id, 'organization_id', p.organization_id, 'name', p.name,
          'active', p.active, 'conditions', p.conditions, 'steps', p.steps) order by p.name)
        from public.procurement_approval_policy p
       where p.organization_id in (select id from orgs)), '[]'::jsonb),
    'requests', coalesce((select jsonb_agg(x order by x->>'created_at' desc) from (
          select jsonb_build_object(
            'id', r.id, 'organization_id', r.organization_id,
            'entity_type', r.entity_type, 'entity_id', r.entity_id,
            'policy_id', r.policy_id, 'status', r.status,
            'current_step', r.current_step, 'created_at', r.created_at,
            'steps', coalesce((select jsonb_agg(jsonb_build_object(
                        'step', t.step, 'key', t.step_key, 'label', t.step_label, 'role', t.step_role,
                        'status', t.step_status, 'decided_by', t.decided_by,
                        'decided_at', t.decided_at, 'note', t.decision_note) order by t.step)
                      from public.v_approval_trace t where t.request_id = r.id), '[]'::jsonb)) as x
            from public.procurement_approval_request r
           where r.organization_id in (select id from orgs)) y), '[]'::jsonb));
$function$


CREATE OR REPLACE FUNCTION public.fn_approval_policy_match(p_org uuid, p_entity_type text, p_amount numeric, p_category text DEFAULT NULL::text, p_emirate text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select p.id
    from public.procurement_approval_policy p
   where p.organization_id = p_org
     and p.active
     and jsonb_typeof(p.steps) = 'array'
     and jsonb_array_length(p.steps) > 0
     and (p.conditions->>'entity_type' is null or p.conditions->>'entity_type' = p_entity_type)
     and coalesce(p_amount, 0) >= coalesce((p.conditions->>'min_amount')::numeric, 0)
     and (p.conditions->'categories' is null or p_category is null or p.conditions->'categories' ? p_category)
     and (p.conditions->'emirates'   is null or p_emirate  is null or p.conditions->'emirates'   ? p_emirate)
   order by coalesce((p.conditions->>'min_amount')::numeric, 0) desc, p.name
   limit 1
$function$


CREATE OR REPLACE FUNCTION public.fn_approval_raise_on_award()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_org uuid; v_policy uuid; v_amount numeric;
begin
  select o.id into v_org from public.customer_organization o
   where o.owner_customer_id = new.customer_id limit 1;
  if v_org is null then
    select m.organization_id into v_org from public.customer_organization_member m
     where m.user_id = new.customer_id and coalesce(m.active, true) limit 1;
  end if;
  if v_org is null then return new; end if;          -- not an enterprise buyer: nothing to approve

  select coalesce(q.customer_price, q.quote_amount) into v_amount
    from public.quotes q
   where q.inquiry_id = new.id and q.supplier_id = new.hired_supplier_id
   order by q.created_at desc limit 1;

  v_policy := public.fn_approval_policy_match(v_org, 'inquiry', v_amount, new.category, new.emirate);
  if v_policy is null then return new; end if;       -- no policy covers this purchase

  if exists (select 1 from public.procurement_approval_request r
              where r.entity_type = 'inquiry' and r.entity_id = new.id::text
                and r.status in ('pending', 'approved')) then
    return new;                                      -- idempotent: one live chain per award
  end if;

  insert into public.procurement_approval_request (organization_id, entity_type, entity_id, policy_id)
  values (v_org, 'inquiry', new.id::text, v_policy);
  return new;
exception when others then
  raise warning 'fn_approval_raise_on_award skipped inquiry %: %', new.id, sqlerrm;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_archetype_tier(p_archetype text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case p_archetype
           when 'director' then 1
           when 'analyst-controller' then 2
           when 'reviewer-auditor' then 2
           when 'operations-specialist' then 3
           else 9 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_artifact_publish_blocked(p_subject_type text, p_subject_id text, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r artifact_review;
begin
  if p_sha256 is null or btrim(p_sha256) = '' then
    return jsonb_build_object('blocked', true, 'reason', 'no_artifact_digest',
      'detail', 'publishing needs the digest of the bytes that will be published');
  end if;
  select * into r from artifact_review
   where subject_type = p_subject_type and subject_id = p_subject_id
     and artifact_sha256 = p_sha256
   order by created_at desc limit 1;

  if r.id is null then
    return jsonb_build_object('blocked', true, 'reason', 'no_review_for_these_bytes',
      'detail', 'the artifact was never reviewed, or it changed after the review');
  end if;
  if r.verdict <> 'pass' then
    return jsonb_build_object('blocked', true, 'reason', 'review_failed',
      'failures', to_jsonb(r.failures), 'review_id', r.id);
  end if;
  return jsonb_build_object('blocked', false, 'review_id', r.id, 'reviewer', r.reviewer_agent,
                            'reviewed_at', r.created_at);
end $function$


CREATE OR REPLACE FUNCTION public.fn_artifact_review_valid()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_author   text;
  v_reviewer text;
begin
  -- Resolve BOTH sides before comparing. coalesce keeps an unrecognised identity as itself rather
  -- than turning it into null: null = null is null, and a guard that evaluates to null lets the
  -- row through.
  v_author   := coalesce(public.fn_org_agent_resolve(new.author_agent),   new.author_agent);
  v_reviewer := coalesce(public.fn_org_agent_resolve(new.reviewer_agent), new.reviewer_agent);

  if new.verdict = 'pass' then
    -- A PASS WITH NO REVIEWER IS WORSE THAN A SELF-REVIEW, and the previous guard permitted it:
    -- a null reviewer_agent is never equal to author_agent, so the comparison answered "not a
    -- self-review" and the row went in with nobody having looked at the artifact.
    if new.reviewer_agent is null or btrim(new.reviewer_agent) = '' then
      raise exception 'artifact % % cannot be marked pass with no reviewer recorded',
        new.subject_type, new.subject_id
        using errcode = 'check_violation';
    end if;

    if new.author_agent is not null and v_author = v_reviewer then
      raise exception
        'artifact_review refuses a self-review: author "%" and reviewer "%" are the same employee (%). %',
        new.author_agent, new.reviewer_agent, v_author,
        'Route the artifact to the QA path (ai_quality_reviewer) or to fn_pick_reviewer(dept, author).'
        using errcode = 'check_violation';
    end if;
  end if;

  -- Store both sides canonical, so every later count over this table measures employees and not
  -- spelling. Same discipline as trg_review_chain_no_self_review.
  new.author_agent   := case when new.author_agent   is null then null else v_author   end;
  new.reviewer_agent := case when new.reviewer_agent is null then null else v_reviewer end;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_assign_founding_rank()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_limit int; v_rank int;
begin
  -- Rank a supplier once, and only once they are a VERIFIED supplier. Claiming a scraped listing
  -- is not registration; registration without documents is not verification.
  if new.founding_rank is not null then return new; end if;
  if coalesce(new.verified,false) is not true then return new; end if;
  if coalesce(new.banned,false) is true then return new; end if;
  if coalesce(new.approval_status,'') in ('rejected','action_required') then return new; end if;

  v_limit := coalesce((select nullif(value,'')::int from public.app_secrets where key='founding_free_limit'), 1000);

  -- Serialise rank assignment so two concurrent verifications cannot take the same number.
  perform pg_advisory_xact_lock(hashtext('qd_founding_rank'));
  select coalesce(max(founding_rank),0) + 1 into v_rank from public.leads;

  new.founding_rank := v_rank;
  -- Exemption is permanent: it is stamped at verification and never recalculated, so a supplier
  -- who was inside the first 1,000 stays exempt even as the base grows.
  new.subscription_exempt := (v_rank <= v_limit);
  return new;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_assign_training(p_agent_key text, p_competency text, p_purpose text DEFAULT 'practice'::text, p_n integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_roles text[]; v_dept text; v_rows jsonb;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_purpose not in ('practice','retest','drift_check') then
    raise exception 'purpose must be practice, retest or drift_check';
  end if;
  select array_agg(packaged_role_id) into v_roles from org_role_identity where agent_key = p_agent_key;
  select packaged_department into v_dept from org_role_identity where agent_key = p_agent_key limit 1;
  if v_roles is null then
    return jsonb_build_object('assigned', 0, 'reason', 'agent has no role identity');
  end if;

  with pool as (
    select c.case_id, c.case_family, c.competency, c.scope_key
      from agent_training_case c
     -- The parentheses matter: AND binds tighter than OR, so without them the competency
     -- filter applied only to the department branch and every role case slipped past it.
     where ((c.scope_type = 'role' and c.scope_key = any(v_roles))
         or (c.scope_type = 'department' and c.scope_key = v_dept))
       and (p_competency is null or c.competency = p_competency)
  ), unseen as (
    select p.* from pool p
     where not exists (select 1 from agent_training_attempt a
                        where a.agent_key = p_agent_key and a.case_id = p.case_id)
     order by md5(p.case_id || p_agent_key || p_purpose)     -- stable per (agent,purpose), not an ordered list
     limit greatest(coalesce(p_n, 5), 1)
  ), ins as (
    insert into agent_training_attempt (agent_key, case_id, purpose, competency)
    select p_agent_key, case_id, p_purpose, competency from unseen
    on conflict (agent_key, case_id, purpose) do nothing
    returning id, case_id
  )
  select jsonb_agg(jsonb_build_object('attempt_id', i.id, 'case_id', i.case_id,
                                      'payload', c.payload))
    into v_rows
    from ins i join agent_training_case c on c.case_id = i.case_id;

  return jsonb_build_object('assigned', coalesce(jsonb_array_length(v_rows), 0),
                            'purpose', p_purpose, 'cases', coalesce(v_rows, '[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_authority_rank(p text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- How much UNSUPERVISED power the tier confers. advisory advises only; gated needs approval
  -- before acting; supervised acts and is reviewed after; autonomous acts unreviewed.
  select case p when 'advisory' then 0 when 'gated' then 1 when 'supervised' then 2
                when 'autonomous' then 3 else 3 end;   -- unknown tier ranks highest: fail closed
$function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_control_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_key    text := coalesce(new.key, old.key);
  v_old    text := old.value;
  v_new    text := new.value;
  v_reason text := nullif(trim(coalesce(current_setting('app.change_reason', true), '')), '');
  v_dir    text := 'neutral';
  v_widen  boolean := false;
begin
  if v_key not in ('agent_autonomy_enabled','agent_autonomy_from','cos_frozen','ai_kill_switch') then
    return coalesce(new, old);
  end if;

  if tg_op = 'DELETE' then
    -- Deleting cos_frozen or ai_kill_switch removes a brake; deleting the enable flag adds one.
    v_widen := v_key in ('cos_frozen','ai_kill_switch');
  elsif v_key = 'agent_autonomy_enabled' then
    v_widen := v_new = 'true' and coalesce(v_old,'false') <> 'true';
  elsif v_key = 'cos_frozen' then
    v_widen := coalesce(v_new,'false') <> 'true' and v_old = 'true';
  elsif v_key = 'ai_kill_switch' then
    v_widen := coalesce(v_new,'false') = 'false' and coalesce(v_old,'false') <> 'false';
  elsif v_key = 'agent_autonomy_from' then
    v_widen := tg_op = 'INSERT' or v_new is distinct from v_old;   -- any move of the date is a widen
  end if;
  v_dir := case when v_widen then 'widen' else 'tighten' end;

  if v_widen and (v_reason is null or length(v_reason) < 12) then
    raise exception
      'app_secrets.%: widening autonomy needs a stated reason. Run '
      '`set local app.change_reason = ''why, in a sentence'';` in the same transaction. '
      'A PostgREST update from an edge function cannot set that, which is the point — this key '
      'was reachable by all 190 service-role functions. Tightening (freeze, kill switch, disable) '
      'never needs a reason and is never refused.', v_key
      using errcode = 'check_violation';
  end if;

  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  values ('app_secrets:' || v_key, tg_op, v_dir, v_old, v_new, v_reason);

  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_autonomy_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_blockers text[] := '{}';
  v_p0       record;
  v_enabled  text;
  v_from     text;
  v_frozen   text;
  v_kill     text;
begin
  for v_p0 in
    select id, item from public.spec_backlog where priority = 0 and status = 'open' order by id
  loop
    v_blockers := array_append(v_blockers, 'spec_backlog#' || v_p0.id || ' open: ' || left(v_p0.item, 90));
  end loop;

  select value into v_enabled from public.app_secrets where key = 'agent_autonomy_enabled';
  select value into v_from    from public.app_secrets where key = 'agent_autonomy_from';
  select value into v_frozen  from public.app_secrets where key = 'cos_frozen';
  select value into v_kill    from public.app_secrets where key = 'ai_kill_switch';

  if coalesce(v_enabled, 'false') <> 'true' then
    v_blockers := array_append(v_blockers, 'agent_autonomy_enabled is not true');
  end if;
  if v_frozen = 'true' then
    v_blockers := array_append(v_blockers, 'cos_frozen is true');
  end if;
  if v_kill is not null and v_kill <> 'false' then
    v_blockers := array_append(v_blockers, 'ai_kill_switch is set');
  end if;
  begin
    if v_from is not null and v_from::date > current_date then
      v_blockers := array_append(v_blockers, 'agent_autonomy_from is in the future: ' || v_from);
    end if;
  exception when others then
    v_blockers := array_append(v_blockers, 'agent_autonomy_from is unparseable: ' || coalesce(v_from, 'null'));
  end;

  return jsonb_build_object(
    'allowed',    cardinality(v_blockers) = 0,
    'blockers',   to_jsonb(v_blockers),
    'checked_at', now());
exception when others then
  return jsonb_build_object(
    'allowed', false,
    'blockers', to_jsonb(array['autonomy status could not be determined: ' || sqlerrm]),
    'checked_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_backup_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_last timestamptz; v_status text; v_stale boolean; v_owner text; v_open int;
begin
  select started_at, status into v_last, v_status
    from agent_runs where agent='backup' order by started_at desc limit 1;
  v_stale := (v_last is null) or (v_last < now() - interval '26 hours') or (coalesce(v_status,'')='error');
  if not v_stale then
    return jsonb_build_object('ok',true,'last',v_last,'status',v_status);
  end if;
  select count(*) into v_open from agent_actions
    where kind='backup_alert' and coalesce(status,'') in ('pending','needs_review')
  -- A DEDUPE WINDOW THE SAME LENGTH AS THE CHECK INTERVAL SUPPRESSES ON A KNIFE EDGE (13 Aug 2026).
  -- The backup was broken from 10 to 12 August and this watcher produced exactly ONE alert:
  -- agent_action 2662 at 2026-08-11 08:00:00.63, one email, still pending. The watcher runs daily
  -- at 08:00, and the previous row was 24 hours old minus a fraction of a second, so it was still
  -- inside `created_at > now() - 24 hours` and the second day's alert was skipped. Twenty hours is
  -- strictly shorter than the cadence, so a daily check always re-alerts on a continuing outage
  -- while a ten-minute caller still cannot spam.
      and created_at > now()-interval '20 hours';

  if v_open = 0 then
    insert into agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
    values('security','backup_alert','pending','high',
      'Backup may have failed or is overdue',
      'The daily logical backup has not completed successfully in the last 26 hours (last: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')||'). Check the backup function and logs. Managed daily backups and the Dropbox mirror remain as fallbacks.',
      'agent_runs', jsonb_build_object('last_backup',v_last,'last_status',v_status));
    insert into security_events(kind,severity,source,subject,detail)
    values('backup_overdue','high','backup','logical backup',
      jsonb_build_object('last_backup',v_last,'last_status',v_status));
    -- 6 SEP 2026: ONE page per event. The agent_action above is paged by trg_page_high_agent_action with the
    -- backup_alert kind, which founder_mail_policy routes to the IT operations engineer as one org_task; the
    -- direct notifications row that used to sit here was the second of THREE emails for one missed backup.
    -- AN OUTAGE THAT LASTS MUST GET LOUDER, NOT REPEAT ITSELF. One identical email a day says the
    -- same thing on day one and on day five, and the day-five reader has already filed the day-one
    -- copy. Past 48 hours this also raises a founder_alert and states the age in hours, which is
    -- the number that decides whether this is a hiccup or a company with no restorable backup.
    if v_last is null or v_last < now() - interval '48 hours' then
      -- backup_failed_after_retry is the kind the policy ALLOWS: two daily retries have failed and there may
      -- be no restorable backup. Once per 24h while it lasts, and it states the age in hours each time.
      perform public.fn_notify_founder(
        'Backup failing after retry: no successful backup for '
        || coalesce(round(extract(epoch from (now()-v_last))/3600)::text || ' hours', 'as long as there are records'),
        'The daily logical backup has now been failing for '
        || coalesce(round(extract(epoch from (now()-v_last))/3600)::text || ' hours', 'as long as there are records')
        || ' (last run: '||coalesce(v_last::text,'never')||', status: '||coalesce(v_status,'unknown')
        || '). This is past the point where one more day of silence is acceptable: verify the backup '
        || 'function itself, then run dr_drill to prove the newest backup still restores.',
        'critical', p_kind => 'backup_failed_after_retry', p_dedupe_key => 'backup_failed_after_retry');
    end if;

  end if;
  return jsonb_build_object('alerted',true,'last',v_last,'status',v_status,'existing_open',v_open);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ban_overdue_dues()
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_days int; v_n int := 0; v_admin text;
begin
  v_days  := coalesce((select num_value from public.gl_settings where key='clawback_ban_days'), 90)::int;
  v_admin := coalesce((select split_part(value,',',1) from public.app_secrets where key='admin_emails'),'management@quotesdone.com');

  for r in
    select d.id, d.supplier_id, d.amount_due, d.admin_fee, d.interest_amount, d.due_date,
           l.company_name, coalesce(l.claimed_by,l.email) as email,
           l.accepted_terms_at, l.accepted_terms_version, l.signed_terms_path, l.banned
    from public.supplier_dues d
    join public.leads l on l.id = d.supplier_id
    where d.paid_at is null
      and coalesce(d.status,'') not in ('paid','settled','waived','cancelled')
      and coalesce(d.amount_due,0) > 0
      and d.due_date is not null
      and current_date >= (d.due_date::date + v_days)
      and d.legal_escalated_at is null
  loop
    update public.supplier_dues
       set status = 'legal', legal_stage = 'pending_case', legal_escalated_at = now()
     where id = r.id;

    update public.leads
       set banned = true,
           banned_reason = 'Unpaid refund clawback of AED ' ||
                           round(coalesce(r.amount_due,0)+coalesce(r.admin_fee,0)+coalesce(r.interest_amount,0),2) ||
                           ' more than ' || v_days || ' days past due (due ' || r.due_date::date || ').',
           matching_blocked = true,
           matching_block_reason = 'Banned: unpaid refund clawback escalated to legal'
     where id = r.supplier_id;

    insert into public.founder_alerts(level, event, detail, channel)
    values ('crit', 'supplier_banned_legal',
      coalesce(r.company_name,'Supplier #'||r.supplier_id) || ' has been banned and due #' || r.id ||
      ' escalated to legal: AED ' || round(coalesce(r.amount_due,0)+coalesce(r.admin_fee,0)+coalesce(r.interest_amount,0),2) ||
      ' unpaid for over ' || v_days || ' days. ' ||
      case when r.accepted_terms_at is null
           then '*** NO SIGNED TERMS ON RECORD - the supplier agreement cannot be produced as evidence, so a filing may not be supportable. Verify before instructing the legal agent. ***'
           else 'Terms accepted ' || r.accepted_terms_at::date || ' (version ' || coalesce(r.accepted_terms_version,'?') || ') - available as supporting evidence.'
      end, 'system');

    v_n := v_n + 1;
  end loop;

  return v_n;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_board_review(p_subject text, p_subject_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare adv record; ch jsonb; v_rec text; v_conf numeric; v_supply int; v_rev numeric;
  n_pro int:=0; n_cond int:=0; n_against int:=0; v_out jsonb := '[]'::jsonb;
begin
  ch := fn_challenge(p_subject,'board','board');
  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';

  for adv in select * from board_advisor where active order by advisor_key loop
    -- each advisor reasons through its own lens against the same facts
    if adv.advisor_key='risk' and (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.85;
    elsif adv.advisor_key='economist' and v_rev=0 then
      v_rec:='proceed_with_conditions'; v_conf:=0.7;
    elsif adv.advisor_key in ('customer','supplier') and v_supply=0 then
      v_rec:='abstain'; v_conf:=0.5;
    elsif (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.75;
    elsif (ch->>'stance')='concern' then
      v_rec:='proceed_with_conditions'; v_conf:=0.65;
    else
      v_rec:='proceed'; v_conf:=0.6;
    end if;

    insert into board_opinion (subject,subject_ref,advisor_key,recommendation,rationale,confidence)
    values (p_subject,p_subject_ref,adv.advisor_key,v_rec,
      adv.name||' ('||adv.lens||') asks: '||adv.asks||' — '||
      case v_rec
        when 'do_not_proceed' then 'On the evidence available this fails that test.'
        when 'proceed_with_conditions' then 'Proceed only with a named metric, a captured baseline and a reversal path.'
        when 'abstain' then 'There is no data on this side of the marketplace yet; an opinion would be invention.'
        else 'Nothing in this lens argues against it.' end, v_conf);

    if v_rec='proceed' then n_pro:=n_pro+1;
    elsif v_rec='proceed_with_conditions' then n_cond:=n_cond+1;
    elsif v_rec='do_not_proceed' then n_against:=n_against+1; end if;

    v_out := v_out || jsonb_build_array(jsonb_build_object('advisor',adv.name,'lens',adv.lens,'recommendation',v_rec,'confidence',v_conf));
  end loop;

  return jsonb_build_object('subject',p_subject,'proceed',n_pro,'with_conditions',n_cond,
    'against',n_against,'abstained',(select count(*) from board_advisor where active)-n_pro-n_cond-n_against,
    'board_verdict', case when n_against>0 then 'DO NOT PROCEED' when n_cond>0 then 'PROCEED WITH CONDITIONS' else 'PROCEED' end,
    'challenge_stance', ch->>'stance', 'opinions', v_out);
end $function$


CREATE OR REPLACE FUNCTION public.fn_boq_fixture_score(p_fixture_id bigint, p_actual jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare f public.boq_fixture%rowtype; d jsonb := '[]'::jsonb;
  v_checked int := 0; v_matched int := 0;
  v_doors numeric; v_windows numeric; v_total numeric;
begin
  select * into f from public.boq_fixture where id = p_fixture_id;
  if not found then return jsonb_build_object('error','no such fixture'); end if;

  -- Largest matching line wins: a plan can list "D1 flush wooden doors" and a separate
  -- "door frames" line, and the schedule quantity is the one being checked.
  select max((l->>'qty')::numeric) into v_doors
    from jsonb_array_elements(coalesce(p_actual->'boq','[]'::jsonb)) l
   where (l->>'description') ~* '\ydoor' and (l->>'qty') ~ '^[0-9.]+$'
     and coalesce(l->>'unit','') ~* 'no|ea|pc';
  select max((l->>'qty')::numeric) into v_windows
    from jsonb_array_elements(coalesce(p_actual->'boq','[]'::jsonb)) l
   where (l->>'description') ~* '\ywindow' and (l->>'qty') ~ '^[0-9.]+$'
     and coalesce(l->>'unit','') ~* 'no|ea|pc';
  v_total := nullif(p_actual->>'total_area_sqm','')::numeric;

  if f.expect_doors is not null then
    v_checked := v_checked + 1;
    if v_doors = f.expect_doors then v_matched := v_matched + 1; end if;
    d := d || jsonb_build_array(jsonb_build_object('field','doors','expected',f.expect_doors,
           'actual',v_doors,'match', v_doors = f.expect_doors));
  end if;

  if f.expect_windows is not null then
    v_checked := v_checked + 1;
    if v_windows = f.expect_windows then v_matched := v_matched + 1; end if;
    d := d || jsonb_build_array(jsonb_build_object('field','windows','expected',f.expect_windows,
           'actual',v_windows,'match', v_windows = f.expect_windows));
  end if;

  -- The stated built-up area is preferred; where the drawing prints none, the room sum is the
  -- only figure it states and is what the pipeline's total is compared against.
  if coalesce(f.expect_total_sqm, f.expect_rooms_sqm) is not null then
    declare v_exp numeric := coalesce(f.expect_total_sqm, f.expect_rooms_sqm); v_hit boolean;
    begin
      v_hit := v_total is not null
               and abs(v_total - v_exp) <= v_exp * (f.tolerance_pct / 100.0);
      v_checked := v_checked + 1;
      if v_hit then v_matched := v_matched + 1; end if;
      d := d || jsonb_build_array(jsonb_build_object('field','total_area_sqm','expected',v_exp,
             'actual',v_total,'tolerance_pct',f.tolerance_pct,'match',v_hit));
    end;
  end if;

  return jsonb_build_object('checked', v_checked, 'matched', v_matched,
    'score_pct', case when v_checked > 0 then round(100.0*v_matched/v_checked, 2) else null end,
    'detail', d, 'boq_lines', jsonb_array_length(coalesce(p_actual->'boq','[]'::jsonb)));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_budget_available(p_dept text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select greatest(
    coalesce(b.monthly_aed, 0)
    - coalesce((select sum(l.cost_aed) from ai_cost_log l
                 where l.dept_key = any(public.fn_dept_scope(b.dept_key))
                   and l.occurred_at >= date_trunc('month', now())), 0),
    0)
  from department_budget b
  where b.dept_key = public.fn_dept_canonical(p_dept);
$function$


CREATE OR REPLACE FUNCTION public.fn_bump_exam_question(p_id bigint)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  update knowledge_exam_questions set times_asked = coalesce(times_asked,0)+1, last_asked = now() where id = p_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_business_entity_list(p_entity text, p_filter text DEFAULT NULL::text, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb; e text := lower(btrim(coalesce(p_entity,''))); f text := btrim(coalesce(p_filter,'')); n int := least(greatest(coalesce(p_limit,25),1),200);
begin
  if e in ('customer','buyer') then
    select jsonb_agg(to_jsonb(c)) into v from (select id,email,phone,created_at from public.customers order by created_at desc limit n) c;
  elsif e in ('supplier','lead','vendor') then
    select jsonb_agg(to_jsonb(l)) into v from (
      select id,company_name,contact_name,email,phone,approval_status,created_at from public.leads
       where f='' or company_name ilike '%'||f||'%' or approval_status=f
       order by (approval_status='approved') desc, created_at desc limit n) l;
  elsif e in ('inquiry','rfq','request') then
    select jsonb_agg(to_jsonb(i)) into v from (
      select id,customer_id,category,status,created_at from public.inquiries
       where f='' or status=f or category ilike '%'||f||'%' order by created_at desc limit n) i;
  elsif e in ('quote','quotation','offer') then
    select jsonb_agg(to_jsonb(q)) into v from (select id,inquiry_id,supplier_id,quote_amount,status,created_at from public.quotes order by created_at desc limit n) q;
  elsif e in ('transaction','payment','order','reveal') then
    select jsonb_agg(to_jsonb(t)) into v from (select id,inquiry_id,supplier_id,customer_id,quote_amount from public.transactions limit n) t;
  else
    return jsonb_build_object('ok',false,'error','unknown entity "'||e||'". Use: customer, supplier, inquiry, quote or transaction.');
  end if;
  return jsonb_build_object('ok',true,'entity',e,'filter',nullif(f,''),'items',coalesce(v,'[]'::jsonb),'count',jsonb_array_length(coalesce(v,'[]'::jsonb)));
end $function$


CREATE OR REPLACE FUNCTION public.fn_business_entity_lookup(p_entity text, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb; e text := lower(btrim(coalesce(p_entity,''))); k text := btrim(coalesce(p_key,''));
begin
  if k = '' then return jsonb_build_object('ok',false,'error','a key is required (id, email, company name or phone)'); end if;
  if e in ('customer','buyer') then
    select to_jsonb(c) into v from public.customers c where c.id::text=k or lower(c.email)=lower(k) or c.phone=k limit 1;
  elsif e in ('supplier','lead','vendor') then
    select to_jsonb(l) into v from public.leads l where l.id::text=k or lower(l.email)=lower(k) or l.company_name ilike k or l.phone=k limit 1;
  elsif e in ('inquiry','rfq','request') then
    select to_jsonb(i) into v from public.inquiries i where i.id::text=k limit 1;
  elsif e in ('quote','quotation','offer') then
    select to_jsonb(q) into v from public.quotes q where q.id::text=k limit 1;
  elsif e in ('transaction','payment','order','reveal') then
    select to_jsonb(t) into v from public.transactions t where t.id::text=k limit 1;
  else
    return jsonb_build_object('ok',false,'error','unknown entity "'||e||'". Use: customer, supplier, inquiry, quote or transaction.');
  end if;
  if v is null then return jsonb_build_object('ok',true,'entity',e,'key',k,'found',false); end if;
  return jsonb_build_object('ok',true,'entity',e,'found',true,'profile',v);
end $function$


CREATE OR REPLACE FUNCTION public.fn_business_entity_summary()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'as_of', now(),
    'customers',            (select count(*) from public.customers),
    'customers_with_inquiry',(select count(distinct customer_id) from public.inquiries where customer_id is not null),
    'suppliers_total',      (select count(*) from public.leads),
    'suppliers_approved',   (select count(*) from public.leads where approval_status='approved'),
    'suppliers_prospective',(select count(*) from public.leads where coalesce(approval_status,'') <> 'approved'),
    'sendable_supplier_pool',(select coalesce(sum(sendable),0)::int from public.v_supply_gap),
    'inquiries',            (select count(*) from public.inquiries),
    'quotes',               (select count(*) from public.quotes),
    'transactions',         (select count(*) from public.transactions),
    'categories_total',     (select count(*) from public.catalog_supplier_categories),
    'categories_at_target', (select count(*) from public.v_supply_gap where approved >= 10));
$function$


CREATE OR REPLACE FUNCTION public.fn_cancel_inquiry(p_inquiry uuid, p_customer uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v inquiries%rowtype; v_paid boolean; v_cnt int; v_warned boolean:=false; v_email text;
begin
  select * into v from inquiries where id=p_inquiry;
  if not found then return jsonb_build_object('error','inquiry_not_found'); end if;
  if p_customer is not null and v.customer_id is distinct from p_customer then
    return jsonb_build_object('error','not_your_inquiry'); end if;
  if v.status='cancelled' or v.pipeline_stage='cancelled' then
    return jsonb_build_object('ok',true,'already_cancelled',true); end if;
  select exists(select 1 from transactions where inquiry_id=p_inquiry) into v_paid;
  if v_paid or v.status in ('revealed','completed') or v.pipeline_stage in ('revealed','won') then
    return jsonb_build_object('error','already_revealed',
      'message','This request already has an active revealed deal and cannot be cancelled. You can close it instead.'); end if;

  update inquiries set status='cancelled', pipeline_stage='cancelled', outcome='cancelled',
      lost_reason=coalesce(p_reason,'customer_cancelled'), completed_at=now(), stage_changed_at=now()
    where id=p_inquiry;
  insert into inquiry_cancellations(inquiry_id,customer_id,reason) values (p_inquiry, v.customer_id, p_reason);

  select count(*) into v_cnt from inquiry_cancellations where customer_id=v.customer_id and created_at > now()-interval '30 days';
  if v.customer_id is not null and v_cnt >= 3 then
    select email into v_email from customers where id=v.customer_id;
    if v_email is not null and position('@' in v_email)>1
       and not exists (select 1 from notifications where type='cancel_warning' and to_email=v_email and created_at > now()-interval '30 days') then
      insert into notifications(type,to_email,to_role,inquiry_id,subject,body,channel,status)
      values('cancel_warning', v_email, 'customer', p_inquiry,
        'A quick note about cancelled requests',
        'We noticed a few of your recent requests were cancelled. That is completely fine — but every request you post is prepared and quoted by suppliers who set aside real time for it. To keep things fair for them, we kindly ask that you post requests you intend to proceed with. If you would like help scoping a job before posting, our team is glad to assist.',
        'email','queued');
      v_warned:=true;
    end if;
  end if;
  return jsonb_build_object('ok',true,'cancelled',true,'cancellations_30d',v_cnt,'warned',v_warned);
end $function$


CREATE OR REPLACE FUNCTION public.fn_case_record_verified_resolution(p_case_id bigint, p_resolution text, p_verified_by jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c record; v_open int;
begin
  select * into c from public.support_case where case_id = p_case_id for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such case'); end if;
  if c.state = 'closed' then
    return jsonb_build_object('ok', true, 'already_closed', true, 'reason', c.close_reason);
  end if;
  if coalesce(btrim(p_resolution), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'a close needs a reason; a close that records facts and decides nothing is the defect this estate has already paid for.');
  end if;
  -- VERIFICATION IS A READING OF STATE, not a claim that work happened. "Do not mark a case resolved
  -- on CEO receipt or service task acceptance": both of those are receipts, and a receipt is an
  -- acknowledgement that something was HANDED OVER, not evidence that it landed.
  if p_verified_by is null or coalesce(p_verified_by->>'observed', '') = '' then
    return jsonb_build_object('ok', false, 'reason',
      'p_verified_by must name what was OBSERVED (the row, the provider state, the delivered message). A CEO receipt or an accepted service task is an acknowledgement of handover, not evidence of an outcome.');
  end if;

  -- AND THE CASE CANNOT CLOSE OVER LIVE WORK. A refund still moving is an open case whatever the
  -- conversation felt like.
  select count(*) into v_open from public.refund_case
   where case_id = p_case_id
     and state in ('requested','investigating','eligible','ceo_authorized','submitted','provider_pending');
  if v_open > 0 then
    return jsonb_build_object('ok', false, 'reason',
      format('%s refund(s) on this case are still moving. Closing now would report a resolution the money has not reached yet.', v_open));
  end if;

  update public.support_case
     set state = 'closed', closed_at = now(), last_activity_at = now(),
         close_reason = p_resolution || ' || verified by: ' || (p_verified_by->>'observed')
   where case_id = p_case_id;

  return jsonb_build_object('ok', true, 'case_id', p_case_id, 'state', 'closed',
    'verified_by', p_verified_by,
    'note', 'Closed against an observed outcome, not against a receipt.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_checklist(p_category text, p_label text DEFAULT NULL::text, p_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_decide   jsonb;
  v_num      integer;
  v_cat_key  text;
  v_route    record;
  v_curated  jsonb;
  v_bank     jsonb;
  v_policy   jsonb;
  v_resolved text;
begin
  -- 1. curated fields for the customer-facing slug, if the company has any
  select fields into v_curated from category_specs where category = p_category limit 1;

  -- 2a. a system category slug the company assigned resolves deterministically; only
  --     customer prose goes to the language resolver.
  select catalog_num into v_num from category_route_map where category = p_category;
  if v_num is not null then v_resolved := 'category_route_map'; end if;

  -- 2b. resolve to a catalogue route using the existing resolver, not a new matcher
  if v_num is null then
  v_decide := fn_kb_route_decide(coalesce(nullif(btrim(concat_ws(' ', p_label, p_category, p_text)), ''), p_category));
  v_num := nullif(v_decide->>'catalog_num', '')::integer;
  v_resolved := 'route_decider';
  end if;
  if v_num is null then
    -- the decider asked for clarification; take its top candidate only when it is unambiguous
    if coalesce(jsonb_array_length(v_decide->'candidates'), 0) = 1 then
      v_num := (v_decide->'candidates'->0->>'catalog_num')::integer;
      v_resolved := 'single_candidate';
    end if;
  end if;
  if v_num is null then
    select catalog_num into v_num from kb_operational_route
     where expected_catalog_slug = p_category or route_key = p_category limit 1;
    if v_num is not null then v_resolved := 'exact_slug'; end if;
  end if;

  if v_num is null then
    return jsonb_build_object(
      'category', p_category, 'route_resolved', false,
      'resolution', 'unresolved',
      'clarification', v_decide->>'clarification',
      'candidates', coalesce(v_decide->'candidates', '[]'::jsonb),
      'curated_fields', coalesce(v_curated, '[]'::jsonb),
      'packaged_questions', '[]'::jsonb, 'mandatory_fields', '[]'::jsonb,
      'never_infer', '[]'::jsonb, 'knowledge_ids', '[]'::jsonb);
  end if;

  select * into v_route from kb_operational_route where catalog_num = v_num;
  select category_key into v_cat_key from org_category_identity where catalog_num = v_num;

  -- 3. the packaged question bank for that route (field / question / mandatory / why)
  select structured_data->'questions' into v_bank
    from ops_knowledge
   where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'
     and source_path like '%02_FIELD_AND_QUESTION_BANK_V2.yaml'
   limit 1;

  -- 4. the V3 minimum-sufficient policy: what must be answered, and what may never be guessed
  select structured_data into v_policy
    from ops_knowledge
   where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'
     and source_path like '%02_MINIMUM_SUFFICIENT_QUESTION_POLICY_V3.yaml'
   limit 1;

  return jsonb_build_object(
    'category', p_category,
    'route_resolved', true,
    'resolution', v_resolved,
    'catalog_num', v_num,
    'route_key', v_route.route_key,
    'route_name', v_route.catalog_name,
    'category_key', v_cat_key,
    'coverage_status', v_route.coverage_status,
    'regulatory_coverage_status', v_route.regulatory_coverage_status,
    'curated_fields', coalesce(v_curated, '[]'::jsonb),
    'packaged_questions', coalesce(v_bank, '[]'::jsonb),
    'mandatory_fields', coalesce(v_policy->'mandatory_fields', '[]'::jsonb),
    'route_specific_fields', coalesce(v_policy->'route_specific_fields', '[]'::jsonb),
    'ask_order', coalesce(v_policy->'ask_order', '[]'::jsonb),
    'stop_rule', v_policy->>'stop_rule',
    'never_infer', coalesce(v_policy->'never_infer', '[]'::jsonb),
    'knowledge_ids', coalesce((
      select jsonb_agg(record_id) from ops_knowledge
       where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'), '[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_expert_ref(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_slug text; v_txt text;
begin
  v_slug := case
    when p_category ~* 'cctv|security|surveillance' then 'cctv-security'
    when p_category ~* 'hvac|air.?con|ac-' then 'ac-maintenance'
    when p_category ~* 'duct' then 'ac-duct-cleaning'
    when p_category ~* 'glass|glaz|alumin' then 'aluminium-glass'
    when p_category = 'carpentry' then 'carpentry-joinery'
    when p_category ~* 'joinery|kitchen' then 'joinery-kitchens'
    when p_category ~* 'tiling|tile|marble|granite' then 'tiling-marble'
    when p_category ~* 'gypsum|false.?ceiling|ceiling' then 'false-ceiling'
    when p_category ~* 'upholstery|blind|curtain' then 'curtains-blinds'
    when p_category ~* 'fit.?out' then 'commercial-retail-fitout'
    when p_category ~* 'combined.?mep|^mep$' then 'combined-mep'
    when p_category ~* 'steel|fabrication' then 'structural-steel-fabrication'
    when p_category ~* 'pest' then 'pest-control'
    when p_category ~* 'tent|shade' then 'tents-and-shade-structures'
    when p_category ~* 'general|other|handyman|facilit' then coalesce(
        (select 'general-services-other' where exists (select 1 from agent_knowledge where agent_key='cat:general-services-other')), p_category)
    else p_category end;
  select string_agg('## '||topic||E'\n'||content, E'\n\n')
    into v_txt from agent_knowledge
    where agent_key = 'cat:'||v_slug
      and topic in ('Pricing benchmarks & red flags','Quote analysis & comparison',
                    'Standards, materials & specifications','Field expertise — UAE codes, standards & specs');
  return left(coalesce(v_txt,''), 4500);
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_key_for_slug(p_slug text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- category_specs / inquiries.category vocabulary ('hvac', 'aluminium') -> the pack key ('009_hvac-suppliers')
  select i.category_key
    from (
      select m.catalog_num, 1 as pri from public.category_route_map m where m.category = lower(btrim(p_slug))
      union all
      select c.num, 2 from public.catalog_supplier_categories c where c.slug = lower(btrim(p_slug))
      union all
      select c.num, 3 from public.catalog_supplier_categories c
       where c.slug like lower(btrim(p_slug)) || '-%' or c.slug like '%-' || lower(btrim(p_slug)) || '-%' or c.slug like '%-' || lower(btrim(p_slug))
      union all
      select c.num, 4 from public.catalog_supplier_categories c
       where lower(c.name) like '%' || lower(btrim(p_slug)) || '%'
    ) r
    join public.org_category_identity i on i.catalog_num = r.catalog_num
   where coalesce(btrim(p_slug), '') <> ''
   order by r.pri, i.category_key
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_category_key_from_text(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
-- SCALARS, NOT A RECORD: a plpgsql record that was never assigned raises "not assigned yet" on its first
-- field reference, so the run-less path would have thrown instead of falling through (caught in rehearsal).
declare v_id uuid; v_run uuid; v_slug text; v_key text; v_lc text;
        v_ev_type text; v_ev_entity text; v_ev_payload jsonb; v_ctx jsonb;
begin
  if coalesce(p_text, '') = '' then return null; end if;
  v_lc := lower(p_text);

  -- 1. an explicit inquiry reference
  begin
    v_id := substring(p_text from '(?i)inquiry[:=# ]\s*([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})')::uuid;
  exception when others then v_id := null; end;

  -- 2. a workflow run reference: the event that started the run names the inquiry
  if v_id is null then
    begin
      v_run := substring(p_text from '(?i)\mrun[:=#]\s*([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})')::uuid;
    exception when others then v_run := null; end;
    if v_run is not null then
      select e.entity_type, e.entity_id, e.payload, r.context into v_ev_type, v_ev_entity, v_ev_payload, v_ctx
        from public.workflow_run r
        left join public.company_event e on e.id = r.trigger_event_id
       where r.id = v_run;
      if coalesce(v_ctx, '{}'::jsonb) ? 'inquiry_id' then
        begin v_id := (v_ctx->>'inquiry_id')::uuid; exception when others then v_id := null; end;
      end if;
      if v_id is null and v_ev_type = 'inquiry' then
        begin v_id := v_ev_entity::uuid; exception when others then v_id := null; end;
      end if;
    end if;
  end if;

  if v_id is not null then
    select i.category into v_slug from public.inquiries i where i.id = v_id;
  end if;
  if v_slug is null and v_ev_payload is not null then v_slug := v_ev_payload->>'category'; end if;
  if v_slug is not null then
    v_key := public.fn_category_key_for_slug(v_slug);
    if v_key is not null then return v_key; end if;
  end if;

  -- 3. a category key named literally
  v_key := substring(p_text from '\m([0-9]{3}_[a-z0-9-]+)\M');
  if v_key is not null and exists (select 1 from public.org_category_identity where category_key = v_key) then
    return v_key;
  end if;

  -- 4. a catalogue slug or name in the text; the longest name wins
  select i.category_key into v_key
    from public.catalog_supplier_categories c
    join public.org_category_identity i on i.catalog_num = c.num
   where v_lc like '%' || lower(c.slug) || '%' or v_lc like '%' || lower(c.name) || '%'
   order by length(c.name) desc, i.category_key
   limit 1;
  return v_key;
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_knowledge(p_category text)
 RETURNS TABLE(catalog_slug text, topic text, content text, priority integer, layer text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- THE KNOWLEDGE WAS COMPLETE AND UNREACHABLE.
  -- All 84 spec categories carry their 8 modules under agent_key 'cat:<catalogue-slug>', but the
  -- live intake assigns one of 56 LEGACY slugs whose overlap with the catalogue is exactly zero.
  -- lead_trade_map is the bridge; this is the first thing that walks it at read time.
  -- Accepts either vocabulary so callers do not need to know which one they hold.
  with resolved as (
    select coalesce(
      (select c.slug from public.catalog_supplier_categories c where c.slug = p_category),
      (select m.catalog_slug from public.lead_trade_map m
         join public.catalog_supplier_categories c2 on c2.slug = m.catalog_slug
        where m.trade_key = p_category)
    ) as slug
  )
  select r.slug, k.topic, k.content, k.priority, k.layer
    from resolved r
    join public.agent_knowledge k on k.agent_key = 'cat:' || r.slug
   where r.slug is not null
   order by k.priority desc nulls last, k.topic;
$function$


CREATE OR REPLACE FUNCTION public.fn_category_knowledge_promote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_slug text; v_know text; v_name text; r jsonb;
begin
  if NEW.kind='category_knowledge' and NEW.status in ('approved','done')
     and coalesce(OLD.status,'') not in ('approved','done') then
    v_slug := NEW.detail->>'slug'; v_know := NEW.detail->>'knowledge'; v_name := NEW.detail->>'name';
    if v_slug is not null and v_know is not null then
      -- publish the quoting-knowledge blob live (full parity) if not already present
      if not exists (select 1 from agent_knowledge where agent_key='cat:'||v_slug) then
        insert into agent_knowledge(agent_key,topic,content,priority,created_at,updated_at)
        values ('cat:'||v_slug, coalesce(v_name,v_slug), v_know, 100, now(), now());
      else
        update agent_knowledge set content=v_know, updated_at=now() where agent_key='cat:'||v_slug;
      end if;
      -- apply the proposed regulation -> category mapping
      for r in select * from jsonb_array_elements(coalesce(NEW.detail->'reg_matches','[]'::jsonb)) loop
        update regulations
          set categories = array(select distinct e from unnest(coalesce(categories,'{}'::text[]) || array[v_slug]) e)
          where id::text = (r->>'id') and not (v_slug = any(coalesce(categories,'{}'::text[])));
      end loop;
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_category_questions(p_category text, p_lang text DEFAULT 'en'::text, p_limit integer DEFAULT 22)
 RETURNS TABLE(field_key text, question text, answer_type text, mandatory boolean, ask_order integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'kb_stage'
AS $function$
  -- THE SPEC'S "INQUIRY QUALIFICATION LOGIC", REACHABLE FOR THE FIRST TIME.
  -- 16,588 questions (4,117 distinct texts, 7,079 mandatory, 14,051 bilingual) live in kb_stage
  -- keyed by FAMILY slug. The intake speaks a legacy slug. The chain is
  --   intake slug -> lead_trade_map -> catalogue slug -> catalog_category_domain -> family
  -- and this walks all of it, accepting either vocabulary at the front.
  --
  -- field_key is NULL on every row; the real supplier-facing key and the ask-order live inside
  -- `activation`. Sorting by that order is the point - it is what makes this an ordered interview
  -- rather than the flat, unordered list category_specs.fields produces.
  --
  -- Deduplicated on question text: a family spans up to 465 subcategories which repeat the generic
  -- spine (emirate, exact need, scope, quantity, date), so without DISTINCT ON the first 20 rows
  -- would be the same question twenty times.
  with fam as (
    select d.domain_slug
      from public.catalog_category_domain d
     where d.catalog_slug = coalesce(
       (select c.slug from public.catalog_supplier_categories c where c.slug = p_category),
       (select m.catalog_slug from public.lead_trade_map m where m.trade_key = p_category))
  )
  select * from (
    select distinct on (q.question_en)
           coalesce(q.activation->>'supplier_facing_field', q.field_key) as field_key,
           case when p_lang = 'ar' and coalesce(q.question_ar,'') <> '' then q.question_ar else q.question_en end as question,
           q.answer_type,
           q.mandatory,
           coalesce((q.activation->>'order')::int, 999) as ask_order
      from kb_stage.questions q
      join fam on fam.domain_slug = q.category_slug
     where coalesce(q.question_en,'') <> ''
     order by q.question_en, q.mandatory desc
  ) x
  order by x.mandatory desc, x.ask_order, x.field_key
  limit greatest(p_limit, 1);
$function$


CREATE OR REPLACE FUNCTION public.fn_ceo_accept_support_report(p_report_id bigint, p_receipt text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.support_ceo_report%rowtype;
begin
  select * into r from public.support_ceo_report where id = p_report_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', format('no report %s', p_report_id));
  end if;
  if coalesce(btrim(p_receipt), '') = '' then
    -- The receipt is the whole point. Without it, "accepted" is support's word for the CEO.
    return jsonb_build_object('ok', false, 'reason',
      'A receipt is required to accept. An acceptance with no receipt is the accepting party''s '
      || 'assumption, not their agreement.');
  end if;

  update public.support_ceo_report
     set status = 'accepted', accepted_at = now(), acceptance_receipt = p_receipt,
         owner_role_id = 'ceo', completion_note = coalesce(p_note, completion_note)
   where id = p_report_id;

  return jsonb_build_object('ok', true, 'report_id', p_report_id, 'owner', 'ceo',
    'note', 'Accepted. Ownership has moved to the CEO, which is the only thing that moves it.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_context(p_query text, p_max_chars integer DEFAULT 18000, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_out jsonb := '[]'::jsonb;
  v_used int := 0;
  v_n int := 0;
  v_how text := null;
begin
  for r in select * from public.fn_ceo_knowledge_search(p_query, p_limit) loop
    exit when v_used + length(r.body) > greatest(2000, p_max_chars);
    v_how := coalesce(v_how, r.matched_how);
    v_out := v_out || jsonb_build_object(
      'record_id', r.record_id, 'record_kind', r.record_kind, 'title', r.title,
      'domain', r.domain, 'body', r.body, 'body_sha256', r.body_sha256,
      'source_ids', to_jsonb(r.source_ids), 'source_path', r.source_path,
      'review_status', r.review_status, 'authority_effect', r.authority_effect,
      'relevance', r.relevance, 'matched_how', r.matched_how, 'warning', r.warning);
    v_used := v_used + length(r.body);
    v_n := v_n + 1;
  end loop;

  return jsonb_build_object(
    'query', p_query,
    'records', v_out,
    'record_count', v_n,
    'chars_used', v_used,
    'matched_how', v_how,
    'sufficient', v_n > 0,
    'signal', case when v_n = 0
                   then 'INSUFFICIENT CONTEXT -- nothing in the CEO knowledge pack matched this query. Say so rather than answering from memory.'
                   when v_how = 'best_terms'
                   then 'Advisory context, matched on the best terms rather than all of them. Read each title before relying on it. Company facts, targets, budgets and permissions must be read from the application, not from these records.'
                   else 'Advisory context only. Company facts, targets, budgets and permissions must be read from the application, not from these records.' end,
    'pack_fingerprint', (select max(pack_fingerprint) from public.ceo_knowledge));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_decide_refund(p_refund_id bigint, p_approve boolean, p_rationale text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record;
begin
  if coalesce(btrim(p_rationale), '') = '' then
    -- Applies to BOTH directions. The constitution asks for an evidence-based explanation on a
    -- denial specifically, and an approval with no reasoning is just as unauditable.
    return jsonb_build_object('ok', false, 'reason',
      'a rationale is required. A refund decided with no stated reasoning cannot be audited, and a denial owes the customer an explanation.');
  end if;

  select * into r from public.refund_case where refund_id = p_refund_id for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such refund case'); end if;

  if r.state not in ('eligible','ineligible','requested','investigating') then
    return jsonb_build_object('ok', false, 'reason',
      format('this refund is already %L. Deciding it again would be a second remedy on the same money.', r.state));
  end if;

  update public.refund_case
     set state = case when p_approve then 'ceo_authorized' else 'ceo_declined' end,
         decided_by = 'ceo', decided_at = now(),
         decision = case when p_approve then 'approved' else 'declined' end,
         decision_rationale = p_rationale, updated_at = now()
   where refund_id = p_refund_id;

  return jsonb_build_object('ok', true, 'refund_id', p_refund_id,
    'state', case when p_approve then 'ceo_authorized' else 'ceo_declined' end,
    'note', case when p_approve
                 then 'Authorised. Execution is the payment service''s, and the states stay separate: authorised is not submitted, and submitted is not settled.'
                 else 'Declined with a rationale. Support owes the customer that explanation and an appropriate alternative remedy -- a decline is not the end of the case.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_knowledge_search(p_query text, p_limit integer DEFAULT 8, p_kind text DEFAULT NULL::text, p_domain text DEFAULT NULL::text)
 RETURNS TABLE(record_id text, record_version text, record_kind text, title text, domain text, body text, body_sha256 text, source_ids text[], source_path text, review_status text, authority_effect text, contains_synthetic_example boolean, requires_current_verification boolean, relevance real, matched_how text, warning text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_q     tsquery;
  v_lex   text[];
  v_found boolean := false;
  v_how   text := 'all_terms';
begin
  if coalesce(btrim(p_query), '') = '' then
    return;  -- an empty query retrieves nothing rather than everything
  end if;

  -- PASS 1: every term. Precise, and unchanged from before.
  v_q := websearch_to_tsquery('english', p_query);
  if v_q is not null then
    select exists (select 1 from public.ceo_knowledge k
                    where k.runtime_index_eligible and k.search @@ v_q
                      and (p_kind is null or k.record_kind = p_kind)
                      and (p_domain is null or k.domain = p_domain))
      into v_found;
  end if;

  -- PASS 2: the best terms. Only when pass 1 found nothing, so precision is never traded away --
  -- it is only used where the alternative is an empty answer.
  if not v_found then
    v_lex := tsvector_to_array(to_tsvector('english'::regconfig, p_query));
    if v_lex is null or array_length(v_lex, 1) is null then
      return;
    end if;
    -- Lexemes are already normalised and stripped of stop words by to_tsvector. Quoting each one
    -- keeps a lexeme containing punctuation from being parsed as an operator.
    begin
      v_q := to_tsquery('english'::regconfig,
                        array_to_string(array(select '''' || replace(x, '''', '''''') || '''' from unnest(v_lex) x), ' | '));
    exception when others then
      return;  -- an unparseable query returns nothing rather than an error the caller cannot act on
    end;
    v_how := 'best_terms';
  end if;

  return query
  select k.record_id, k.record_version, k.record_kind, k.title, k.domain,
         k.body, k.body_sha256, k.source_ids, k.source_path,
         k.review_status, k.authority_effect, k.contains_synthetic_example,
         k.requires_current_verification,
         ts_rank(k.search, v_q) as relevance,
         v_how as matched_how,
         'Advisory only. authority_effect=none: this may not approve an action, change a target or '
         || 'become policy. review_status=' || k.review_status || '. '
         || case when v_how = 'best_terms'
                 then 'MATCHED ON BEST TERMS, not all of them -- read the title before relying on it. ' else '' end
         || case when k.contains_synthetic_example
                 then 'CONTAINS A SYNTHETIC EXAMPLE -- it is authored, not QuotesDone experience. ' else '' end
         || case when k.requires_current_verification
                 then 'REQUIRES CURRENT VERIFICATION against an authoritative company source. ' else '' end
         || 'Current company facts come from the application, never from this record.' as warning
    from public.ceo_knowledge k
   where k.runtime_index_eligible
     and k.search @@ v_q
     and (p_kind is null or k.record_kind = p_kind)
     and (p_domain is null or k.domain = p_domain)
   order by ts_rank(k.search, v_q) desc, k.record_id
   limit greatest(1, least(coalesce(p_limit, 8), 50));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_knowledge_search_vector()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.search :=
      setweight(to_tsvector('english'::regconfig, coalesce(new.title,'')), 'A')
   || setweight(to_tsvector('english'::regconfig, coalesce(array_to_string(new.tags,' '),'')), 'B')
   || setweight(to_tsvector('english'::regconfig, coalesce(new.body,'')), 'C');
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_request_decision(p_case_id bigint, p_subject text, p_evidence jsonb, p_recommendation text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_r jsonb;
begin
  if coalesce(btrim(p_recommendation), '') = '' then
    return jsonb_build_object('ok', false, 'reason',
      'a recommendation is required. Handing the CEO a question with no view is support declining to do its own work, and it is how a decision queue fills with items nobody has thought about.');
  end if;
  if p_evidence is null or p_evidence = '{}'::jsonb then
    return jsonb_build_object('ok', false, 'reason',
      'evidence is required. A decision asked for without the facts behind it cannot be made well, only quickly.');
  end if;

  v_r := public.fn_support_report_to_ceo(
    p_idempotency_key, 'elevated', p_subject, p_evidence,
    to_jsonb(array['investigated the case', 'checked the standing grant', 'formed a recommendation']),
    p_recommendation);

  return jsonb_build_object('ok', coalesce((v_r->>'ok')::boolean, false), 'report', v_r,
    'case_id', p_case_id,
    -- The case does NOT move to a resolved state here. That is the explicit v1.2 rule.
    'note', 'Routed to the CEO with evidence and a recommendation. The case stays open: it is not resolved by the CEO receiving it.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_ceo_standing()
 RETURNS TABLE(domain text, decision_key text, authority text, reading text, reading_kind text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v text;
begin
  for r in select d.domain, d.decision_key, d.authority, d.measure, d.measure_sql
             from public.ceo_decision d
            where d.active
            order by d.domain, d.decision_key
  loop
    domain := r.domain; decision_key := r.decision_key; authority := r.authority;
    if r.measure_sql is null then
      reading := 'NOT INSTRUMENTED -- ' || r.measure;
      reading_kind := 'not_instrumented';
    else
      begin
        execute r.measure_sql into v;
        reading := coalesce(v, '(null)');
        reading_kind := 'measured';
      exception when others then
        -- An instrument that throws is not a zero either. It is a broken instrument, and it says so.
        reading := 'INSTRUMENT FAILED -- ' || sqlerrm;
        reading_kind := 'instrument_failed';
      end;
    end if;
    return next;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_challenge(p_proposal text, p_proposed_by text DEFAULT 'founder'::text, p_challenger text DEFAULT 'brief'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  h record; v_id bigint; v_stance text := 'support'; v_conf numeric := 0.5;
  v_reason text := ''; v_alts jsonb := '[]'::jsonb; v_evidence jsonb := '[]'::jsonb;
  v_rank int; v_principle text; v_weight int := 0;
  v_prior record; v_supply int; v_rev numeric;
begin
  for h in select * from challenge_heuristic where active and p_proposal ~* pattern order by rank_touched limit 3
  loop
    -- a rank-1 conflict is severe on its own; lower ranks accumulate
    v_weight := v_weight + case h.rank_touched when 1 then 3 when 2 then 2 else 1 end;
    if v_rank is null or h.rank_touched < v_rank then v_rank := h.rank_touched; v_principle := h.principle; end if;
    v_reason := v_reason || case when v_reason='' then '' else ' ' end || h.concern;
    if h.alternative is not null then v_alts := v_alts || jsonb_build_array(h.alternative); end if;
  end loop;

  for v_prior in
    select headline, detail, outcome from institutional_memory
     where outcome in ('worse','improved')
       and p_proposal ~* coalesce(substring(headline from '\w+'),'zzzz')
     order by created_at desc limit 3
  loop
    v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
      'type','prior_outcome','verdict',v_prior.outcome,'lesson',left(v_prior.detail,240)));
    if v_prior.outcome='worse' then v_weight := v_weight + 3; end if;
  end loop;

  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev
    from transactions where revealed_at > now()-interval '30 days';
  v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
    'type','current_state','onboarded_suppliers',v_supply,'revenue_30d_aed',v_rev,
    'note', case when v_supply=0
      then 'The marketplace has no onboarded supply, so any demand-side or pricing change cannot be validated against real behaviour yet.'
      else 'Supply exists; effects are measurable.' end));

  if v_supply=0 and p_proposal ~* '(fee|price|commission|campaign|customer|demand)' then
    v_weight := v_weight + 1;
    v_reason := v_reason || ' There is also no onboarded supply to measure the effect against, so the change would be unfalsifiable at the moment it is made.';
  end if;

  if v_weight >= 3 then v_stance := 'recommend_against'; v_conf := least(0.95, 0.60 + v_weight*0.05);
  elsif v_weight >= 1 then v_stance := 'concern'; v_conf := 0.65;
  else v_stance := 'support'; v_conf := 0.6;
       v_reason := 'No conflict with the priority hierarchy, no contrary prior outcome on record, and current state does not argue against it.';
  end if;

  -- A REFUSAL WITH NO REASON IS NOT A CHALLENGE. v_weight can cross the recommend_against
  -- threshold from institutional_memory alone, and only the heuristic loop above writes v_reason —
  -- so a proposal with two prior attempts that ended worse and no matching heuristic was recorded
  -- as recommend_against with an empty reasoning. Write the basis that actually drove the weight.
  if v_reason = '' and v_stance <> 'support' then
    v_reason := 'No principle in the priority hierarchy is touched by this, but '
      ||(select count(*) from jsonb_array_elements(v_evidence) e
          where e->>'type'='prior_outcome' and e->>'verdict'='worse')
      ||' prior attempt(s) on record ended worse: '
      ||coalesce((select string_agg(left(e->>'lesson',200), ' | ')
                    from jsonb_array_elements(v_evidence) e
                   where e->>'type'='prior_outcome' and e->>'verdict'='worse'),
                 'the outcome was recorded without a lesson')||'.';
  end if;

  if v_alts='[]'::jsonb and v_stance<>'support' then
    v_alts := jsonb_build_array('Run it as a bounded test with a named metric and a captured baseline, so it can be graded and reversed.');
  end if;

  insert into challenge_record (proposal,proposed_by,challenged_by,stance,confidence,reasoning,
                                violates_rank,violates_principle,evidence,alternatives)
  values (p_proposal,p_proposed_by,p_challenger,v_stance,v_conf,v_reason,v_rank,v_principle,v_evidence,v_alts)
  returning id into v_id;

  return jsonb_build_object('id',v_id,'stance',v_stance,'confidence',v_conf,
    'conflicts_with', case when v_principle is null then null else 'Rank '||v_rank||' — '||v_principle end,
    'reasoning',v_reason,'evidence',v_evidence,'alternatives',v_alts);
end $function$


CREATE OR REPLACE FUNCTION public.fn_change_deployment_execute(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run_id     uuid := nullif(p->>'workflow_run_id','')::uuid;
  v_step_no    int  := nullif(p->>'step_no','')::int;
  v_ctx        jsonb;
  v_ref        text;
  v_at         timestamptz;
  v_fns        text[];
  v_window_min int  := coalesce(nullif(p->>'grade_window_minutes','')::int, 60);
  v_from       timestamptz;
  v_to         timestamptz;
  v_per        jsonb;
  v_err        int;
  v_runs       int;
  v_traces     int;
  v_base       jsonb;
  v_base_src   text;
  v_hours      numeric;
  v_base_rate  numeric;
  v_post_rate  numeric;
  v_grade      text;
  v_task       bigint;
  v_money      text[];
  v_deliv      text;
  v_verified   jsonb;
  v_parity     text;
  v_project    text;
begin
  if v_run_id is null or v_step_no is null then
    raise exception 'fn_change_deployment_execute: request carries no workflow_run_id/step_no (got %)', left(p::text, 300);
  end if;

  select r.context into v_ctx from public.workflow_run r where r.id = v_run_id;
  if v_ctx is null then
    raise exception 'fn_change_deployment_execute: workflow_run % not found', v_run_id;
  end if;

  v_ref := v_ctx->>'ref';
  v_at  := nullif(v_ctx->>'at','')::timestamptz;
  select coalesce(array_agg(x order by x), '{}'::text[]) into v_fns
    from jsonb_array_elements_text(coalesce(v_ctx->'functions', '[]'::jsonb)) x;

  -- The one project is read, not embedded: fn_action_invoke_dispatch reads the same key, and the schema
  -- export must stay portable (export_from_either_source_is_identical flags an embedded ref).
  select value into v_project from public.app_secrets where key = 'project_ref';
  if v_project is null then
    raise exception 'app_secrets.project_ref is not set: a mis-targeted deploy cannot be told from the one project';
  end if;

  -- ESCALATE INSTEAD OF PROPOSING (step-1 playbook, enforced): these are not proposable changes.
  if v_ref is distinct from v_project then
    raise exception 'mis-targeted deploy: deploy.completed names ref % and the one project is %; nothing here is proposed or graded', coalesce(v_ref, '(none)'), v_project;
  end if;
  if coalesce(array_length(v_fns, 1), 0) = 0 then
    raise exception 'deploy.completed carries no function slugs: there is nothing to measure, so the change is not proposed';
  end if;
  if v_at is null then
    raise exception 'deploy.completed carries no "at" timestamp: the baseline window cannot be placed';
  end if;

  -- ------------------------------------------------------------------ the metric, read over a window
  -- Failures per deployed function: errored agent_runs (the function logs under its own slug) plus failed
  -- kernel traces of any cron whose command invokes /functions/v1/<slug>.
  if v_step_no = 1 then v_from := v_at - interval '7 days'; v_to := v_at;
  elsif v_step_no = 9 then v_from := v_at; v_to := least(now(), v_at + interval '24 hours');
  end if;

  if v_step_no in (1, 9) then
    if v_step_no = 9 and now() < v_at + make_interval(mins => v_window_min) then
      return jsonb_build_object(
        'defer_until', v_at + make_interval(mins => v_window_min),
        'reason', format('grading needs at least %s minutes after the deploy at %s; %s minutes have elapsed',
                         v_window_min, v_at, floor(extract(epoch from now() - v_at) / 60)::int),
        'step_no', 9, 'worked_by', 'fn_change_deployment_execute');
    end if;

    select coalesce(jsonb_agg(jsonb_build_object(
             'slug', f.slug,
             'errored_runs', (select count(*) from public.agent_runs a
                               where a.agent = f.slug and a.status = 'error'
                                 and a.started_at >= v_from and a.started_at < v_to),
             'total_runs',   (select count(*) from public.agent_runs a
                               where a.agent = f.slug
                                 and a.started_at >= v_from and a.started_at < v_to),
             'failed_traces', (select count(*) from public.phase_c_system_execution t
                                where t.result = 'failed'
                                  and t.started_at >= v_from and t.started_at < v_to
                                  and t.component_id in (select w.component_id
                                                           from public.phase_c_system_execution_wrapper w
                                                          where w.original_command like '%/functions/v1/' || f.slug || '%')))
           order by f.slug), '[]'::jsonb)
      into v_per
      from unnest(v_fns) as f(slug);

    select coalesce(sum((e->>'errored_runs')::int), 0), coalesce(sum((e->>'total_runs')::int), 0),
           coalesce(sum((e->>'failed_traces')::int), 0)
      into v_err, v_runs, v_traces
      from jsonb_array_elements(v_per) e;
  end if;

  -- ------------------------------------------------------------------ step 1: propose + baseline
  if v_step_no = 1 then
    v_deliv := format(
      'CHANGE PROPOSED: the deploy of %s function(s) to %s completed at %s (deploy.completed, emitted by scripts/deploy_functions.mjs after reading each version back): %s. '
      || 'METRIC IT SHOULD MOVE: each deployed function''s failure count — errored agent_runs under its own slug plus failed kernel traces of the crons that call it. '
      || 'BASELINE CAPTURED over the 7 days ending at %s (168h): %s errored run(s) of %s run(s) and %s failed kernel trace(s) across the set; per function: %s. '
      || 'REVERSIBILITY: redeploy the previously committed bundle for each slug (node scripts/deploy_functions.mjs --ref=%s --production <slug>); a SQL change reverses by its down script under scripts/sql/down/. '
      || 'Step 9 grades the window after the deploy against these numbers.',
      array_length(v_fns, 1), v_ref, v_at, array_to_string(v_fns, ', '), v_at, v_err, v_runs, v_traces,
      (select string_agg(format('%s errored %s/%s runs, %s failed trace(s)', e->>'slug', e->>'errored_runs', e->>'total_runs', e->>'failed_traces'), '; ')
         from jsonb_array_elements(v_per) e),
      v_project);
    return jsonb_build_object(
      'step_no', 1, 'kind', 'baseline', 'mode', 'performed', 'worked_by', 'fn_change_deployment_execute',
      'used_llm', false, 'used_llm_basis', 'plpgsql over agent_runs and phase_c_system_execution; no provider call exists in this routine',
      'ref', v_ref, 'at', v_at, 'functions', to_jsonb(v_fns), 'count', array_length(v_fns, 1),
      'metric', 'errored agent_runs per deployed function + failed kernel traces of the crons calling it',
      'window', jsonb_build_object('from', v_from, 'to', v_to, 'hours', 168),
      'baseline', jsonb_build_object('errored_runs', v_err, 'total_runs', v_runs, 'failed_traces', v_traces,
                                     'failures', v_err + v_traces, 'per_function', v_per),
      'reversibility', 'redeploy the previously committed bundle per slug; SQL by its down script',
      'deliverable', v_deliv,
      'outcome', format('proposed %s function(s); baseline %s failure(s) over 168h before %s', array_length(v_fns, 1), v_err + v_traces, v_at));
  end if;

  -- ------------------------------------------------------------------ step 8: promote to production
  if v_step_no = 8 then
    v_verified := v_ctx->'verified';
    v_parity := case
      when v_verified is null then 'not_in_payload'
      when coalesce((v_verified->>'pass')::int, -1) = array_length(v_fns, 1)
           and coalesce(jsonb_array_length(v_verified->'not_verified'), 0) = 0 then 'verified_all'
      else 'verified_partial' end;
    -- Money and identity surfaces are founder-gated territory whatever the diff size (step-2 playbook).
    select coalesce(array_agg(s), '{}'::text[]) into v_money
      from unnest(v_fns) s
     where s ~ '^(customer_api|os_api|refunds?_api|stripe_webhook|payment|checkout|reveal|invoice)';
    v_deliv := format(
      'PROMOTED TO PRODUCTION: the deploy IS the promotion — deploy.completed is emitted only after scripts/deploy_functions.mjs read each function''s version back from the management API. Functions (%s): %s. Target %s at %s. '
      || 'PARITY: %s%s. '
      || 'BLAST RADIUS: %s. '
      || 'No further action moves the change; step 9 monitors it against the step-1 baseline.',
      array_length(v_fns, 1), array_to_string(v_fns, ', '), v_ref, v_at,
      case v_parity
        when 'verified_all' then format('the emitter verified %s/%s version bump(s)', v_verified->>'pass', v_verified->>'of')
        when 'verified_partial' then format('the emitter verified %s/%s; not verified: %s', v_verified->>'pass', v_verified->>'of', coalesce(v_verified->>'not_verified', '[]'))
        else 'the event predates the 5 Sep emitter and carries no verification detail; the emitter''s own rule 4 (version read-back before the event is emitted) is the only evidence, and it is not repeated here' end,
      case when v_verified ? 'versions' then '; versions: ' || left((v_verified->'versions')::text, 1500) else '' end,
      case when coalesce(array_length(v_money, 1), 0) > 0
           then 'includes a money/identity surface (' || array_to_string(v_money, ', ') || ') — high radius regardless of diff size'
           else 'no money/identity surface among the slugs; radius is the ' || array_length(v_fns, 1) || ' function(s) and what they write' end);
    return jsonb_build_object(
      'step_no', 8, 'kind', 'promote', 'mode', 'performed', 'worked_by', 'fn_change_deployment_execute',
      'used_llm', false, 'used_llm_basis', 'plpgsql over the run context; no provider call exists in this routine',
      'promoted', true, 'promotion_is', 'the verified deploy the event describes',
      'ref', v_ref, 'at', v_at, 'functions', to_jsonb(v_fns), 'count', array_length(v_fns, 1),
      'parity', jsonb_build_object('verdict', v_parity, 'instrument', 'scripts/deploy_functions.mjs rule 4 (version read-back), carried as context.verified',
                                   'verified', coalesce(v_verified, 'null'::jsonb)),
      'money_surfaces', to_jsonb(v_money),
      'deliverable', v_deliv,
      'outcome', format('promoted %s function(s) at %s; parity %s', array_length(v_fns, 1), v_at, v_parity));
  end if;

  -- ------------------------------------------------------------------ step 9: monitor, grade, recommend
  if v_step_no = 9 then
    v_hours := greatest(extract(epoch from v_to - v_from) / 3600.0, 0.01);
    select s.output->'result'->0->'baseline' into v_base
      from public.workflow_step_run s
     where s.workflow_run_id = v_run_id and s.step_no = 1 and s.status = 'done';
    if v_base ? 'failures' then
      v_base_src := 'step 1 of this run';
    else
      -- step 1 was closed advisory (before this file) or the shape is foreign: recompute from the same predicate
      select jsonb_build_object(
               'errored_runs', coalesce(sum(e.err), 0), 'total_runs', coalesce(sum(e.tot), 0),
               'failed_traces', coalesce(sum(e.tr), 0), 'failures', coalesce(sum(e.err + e.tr), 0))
        into v_base
        from (select (select count(*) from public.agent_runs a where a.agent = f.slug and a.status = 'error'
                        and a.started_at >= v_at - interval '7 days' and a.started_at < v_at) err,
                     (select count(*) from public.agent_runs a where a.agent = f.slug
                        and a.started_at >= v_at - interval '7 days' and a.started_at < v_at) tot,
                     (select count(*) from public.phase_c_system_execution t where t.result = 'failed'
                        and t.started_at >= v_at - interval '7 days' and t.started_at < v_at
                        and t.component_id in (select w.component_id from public.phase_c_system_execution_wrapper w
                                                where w.original_command like '%/functions/v1/' || f.slug || '%')) tr
                from unnest(v_fns) f(slug)) e;
      v_base_src := 'recomputed over the 7 days before the deploy (step 1 recorded no baseline)';
    end if;

    v_base_rate := (v_base->>'failures')::numeric / 168.0;
    v_post_rate := (v_err + v_traces)::numeric / v_hours;
    v_grade := case
      when (v_err + v_traces) >= 3 and v_post_rate > 1.5 * v_base_rate then 'worse'
      when (v_base->>'failures')::int >= 3 and v_post_rate < 0.5 * v_base_rate then 'improved'
      else 'no_change' end;

    if v_grade = 'worse' then
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class, priority)
      select 'product_eng',
             left(format('Reverse the deploy of %s: post-deploy failures worse than baseline (run %s)', array_to_string(v_fns, ', '), v_run_id), 240),
             format('change_deployment step 9 graded the deploy at %s WORSE: %s failure(s) in %sh after it (%s/h) against a baseline of %s over 168h (%s/h; %s). Per function after the deploy: %s. '
                    || 'RECOMMENDED REVERSAL: redeploy the previously committed bundle for each slug — node scripts/deploy_functions.mjs --ref=%s --production %s. '
                    || 'This task RECORDS the recommendation; reversing a production deploy is a gated action for the Platform lead and was not performed by the executor.',
                    v_at, v_err + v_traces, round(v_hours, 1), round(v_post_rate, 3), v_base->>'failures', round(v_base_rate, 3), v_base_src,
                    (select string_agg(format('%s errored %s/%s, %s failed trace(s)', e->>'slug', e->>'errored_runs', e->>'total_runs', e->>'failed_traces'), '; ') from jsonb_array_elements(v_per) e),
                    v_project, array_to_string(v_fns, ' ')),
             'proposed', 'gated', false, 'incident_fix', 1
       where not exists (select 1 from public.org_tasks t
                          where t.title like '%(run ' || v_run_id || ')' and t.status <> 'done')
      returning id into v_task;
    end if;

    v_deliv := format(
      'MONITORED the %s deployed function(s) (%s) over %sh after the deploy at %s (window %s to %s, minimum %s min, cap 24h): %s errored run(s) of %s run(s) and %s failed kernel trace(s); per function: %s. '
      || 'BASELINE (%s): %s failure(s) over 168h = %s/h. POST: %s/h. '
      || 'GRADE: %s (worse = post >= 3 failures and rate > 1.5x baseline; improved = baseline >= 3 and rate < 0.5x; else no_change). %s',
      array_length(v_fns, 1), array_to_string(v_fns, ', '), round(v_hours, 1), v_at, v_from, v_to, v_window_min,
      v_err, v_runs, v_traces,
      (select string_agg(format('%s errored %s/%s runs, %s failed trace(s)', e->>'slug', e->>'errored_runs', e->>'total_runs', e->>'failed_traces'), '; ') from jsonb_array_elements(v_per) e),
      v_base_src, v_base->>'failures', round(v_base_rate, 3), round(v_post_rate, 3), v_grade,
      case when v_grade = 'worse' and v_task is not null then format('REVERSAL RECOMMENDED as org_task %s for Platform & Reliability (product_eng): redeploy the previously committed bundle per slug. Not performed here — a production reversal is the Platform lead''s gated action.', v_task)
           when v_grade = 'worse' then 'REVERSAL RECOMMENDED; an open org_task for this run already carries it.'
           else 'No reversal: the deploy is not worse than its baseline on this metric.' end);
    return jsonb_build_object(
      'step_no', 9, 'kind', 'grade', 'mode', 'performed', 'worked_by', 'fn_change_deployment_execute',
      'used_llm', false, 'used_llm_basis', 'plpgsql over agent_runs, phase_c_system_execution and this run''s step 1; no provider call exists in this routine',
      'ref', v_ref, 'at', v_at, 'functions', to_jsonb(v_fns), 'count', array_length(v_fns, 1),
      'window', jsonb_build_object('from', v_from, 'to', v_to, 'hours', round(v_hours, 2), 'minimum_minutes', v_window_min),
      'baseline', v_base || jsonb_build_object('source', v_base_src, 'per_hour', round(v_base_rate, 4)),
      'post', jsonb_build_object('errored_runs', v_err, 'total_runs', v_runs, 'failed_traces', v_traces,
                                 'failures', v_err + v_traces, 'per_hour', round(v_post_rate, 4), 'per_function', v_per),
      'grade', v_grade,
      'rollback_recommended', v_grade = 'worse',
      'rollback_task_id', v_task,
      'reversal_performed', false,
      'deliverable', v_deliv,
      'outcome', format('graded %s: %s failure(s) in %sh vs baseline %s/168h%s', v_grade, v_err + v_traces, round(v_hours, 1), v_base->>'failures',
                        case when v_task is not null then '; reversal recommended as org_task ' || v_task else '' end));
  end if;

  raise exception 'fn_change_deployment_execute: step % of change_deployment has no deterministic determination here (steps 1, 8, 9 only)', v_step_no;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_channel_safe_volume(p_channel_key text, p_required numeric, p_days integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p record;
  v_safe numeric;
  v_weeks numeric;
begin
  if p_channel_key is null then
    return jsonb_build_object('applies', false);
  end if;

  select * into p from public.outreach_channel_policy where channel_key = p_channel_key;
  if not found then
    -- An unknown channel is not an unlimited one.
    return jsonb_build_object(
      'applies', true, 'ok', false, 'safe_max', 0,
      'reason', format('Channel %s has no policy. An unknown channel carries zero until someone declares its limit.', p_channel_key));
  end if;

  if p.status = 'blocked' then
    return jsonb_build_object(
      'applies', true, 'ok', false, 'safe_max', 0, 'status', p.status,
      'reason', format('Channel %s is BLOCKED. %s', p.channel_label, p.status_reason));
  end if;

  -- A warming channel does not get max_per_day times days. It gets the ramp, which compounds weekly
  -- from a small start. Treating a warming channel as if it were at full throughput on day one is
  -- how a domain gets burned in week one.
  if p.status = 'warming' and p.ramp_start_per_day is not null then
    v_weeks := ceil(p_days / 7.0);
    -- sum of a geometric ramp: start*7 * ((1+g)^weeks - 1) / g
    if coalesce(p.ramp_weekly_growth, 0) > 0 then
      v_safe := p.ramp_start_per_day * 7 *
                ((power(1 + p.ramp_weekly_growth, v_weeks) - 1) / p.ramp_weekly_growth);
    else
      v_safe := p.ramp_start_per_day * p_days;
    end if;
    if p.max_per_day is not null then
      v_safe := least(v_safe, p.max_per_day * p_days);
    end if;
  else
    v_safe := coalesce(p.max_per_day, 0) * greatest(p_days, 0);
    if p.max_per_week is not null then
      v_safe := least(v_safe, p.max_per_week * ceil(p_days / 7.0));
    end if;
  end if;

  return jsonb_build_object(
    'applies', true,
    'ok', p_required <= v_safe,
    'status', p.status,
    'channel_label', p.channel_label,
    'safe_max', round(v_safe, 0),
    'required', round(coalesce(p_required, 0), 0),
    'shares_transactional_reputation', p.shares_transactional_reputation,
    'requires_opt_in', p.requires_opt_in,
    'reason', case
      when p_required <= v_safe then format('%s can safely carry %s over %s days.', p.channel_label, round(v_safe,0), p_days)
      else format('%s can safely carry %s over %s days, but the plan needs %s. %s',
                  p.channel_label, round(v_safe,0), p_days, round(p_required,0),
                  case when p.shares_transactional_reputation
                       then 'This channel shares a reputation with transactional mail, so exceeding it risks sign-in codes and receipts, not just the campaign.'
                       else 'Exceeding a channel''s safe throughput risks the channel itself.' end)
    end
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_check_spend(p_dept text, p_amount numeric, p_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_avail numeric; v_month numeric; v_limit numeric; v_route text; v_afford boolean;
  v_tier text; v_gated boolean := false;
begin
  p_agent := coalesce(public.fn_org_agent_resolve(p_agent), p_agent);
  select coalesce(monthly_aed,0), fn_budget_available(p_dept) into v_month, v_avail
  from department_budget where dept_key = p_dept;

  if v_month is null then
    return jsonb_build_object('ok', false, 'reason',
      'no budget is recorded for department "' || p_dept || '", so no spend can be authorised against it',
      'route_to','finance');
  end if;

  v_afford := coalesce(p_amount,0) <= v_avail;

  select max(threshold_aed) into v_limit
  from employee_authority where agent_key = p_agent;

  -- REPUTATION REACHES THE MOMENT THE MONEY WOULD MOVE.
  -- fn_reputation_recompute already demotes a probation-tier employee's max_tier from 'autonomous'
  -- to 'gated'; until now nothing consulted that at the point of spend, so a demoted employee kept
  -- their nominal ceiling. On probation the personal limit does not apply and the spend goes to a
  -- person — the same decision, applied where it bites.
  select r.tier into v_tier from agent_reputation r where r.agent_key = p_agent;
  if v_tier = 'probation' then v_gated := true; v_limit := 0; end if;

  v_route := case
    when coalesce(p_amount,0) >  10000 then 'founder'
    when coalesce(p_amount,0) >= 1000  then 'brief'
    -- a gated employee is never the approver of their own spend
    when v_gated then 'brief'
    else coalesce(p_agent,'department head') end;

  return jsonb_build_object(
    'ok', v_afford and (v_limit is null or coalesce(p_amount,0) <= v_limit),
    'affordable', v_afford,
    'requested_aed', coalesce(p_amount,0),
    'available_aed', v_avail,
    'monthly_aed', v_month,
    'agent_limit_aed', v_limit,
    'reputation_tier', coalesce(v_tier,'ungraded'),
    'route_to', v_route,
    'reason', case
      when not v_afford then format('Requested AED %s exceeds the AED %s remaining in the %s budget this period. Reduce the scope, defer to next period, or ask Finance to reallocate.', coalesce(p_amount,0), v_avail, p_dept)
      when v_gated then format('Affordable, but %s is on probation in the reputation system, so their personal spending limit does not apply. Route to %s.', coalesce(p_agent,'this employee'), v_route)
      when v_limit is not null and coalesce(p_amount,0) > v_limit then format('Affordable, but AED %s is above %s''s personal limit of AED %s. Route to %s.', coalesce(p_amount,0), p_agent, v_limit, v_route)
      else format('Within budget: AED %s of AED %s available. Approver: %s.', coalesce(p_amount,0), v_avail, v_route) end);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_classify_llm_failure(p_err text, p_http_status integer DEFAULT NULL::integer, p_finish_reason text DEFAULT NULL::text, p_model text DEFAULT NULL::text, p_latency_ms integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  e text := coalesce(p_err, '');
  k text;
  truncated boolean;
begin
  -- ai_gateway slices lastErr to exactly 200 chars. At 200 the evidence stops before `choices`,
  -- so anything read past that point would be a guess. Say so rather than infer.
  truncated := length(e) >= 200;

  k := case
    -- BILLING FIRST (added 14 Aug 2026). Stable across every OpenRouter model, and not
    -- retryable: retrying an out-of-credit request cannot succeed and burns the wall budget.
    when p_http_status = 402
      or e ~* '(requires more credits|insufficient[_ ]credit|can only afford|quota exceeded|payment required)'
      then 'insufficient_credit'
    -- credentials first: deterministic, and must never be retried
    when p_http_status in (401, 403)
      or e ~* '(unauthor|forbidden|invalid api key|no auth credentials|api[_ ]?key missing)'
      then 'unauthorised'
    when p_http_status = 429
      or e ~* '(rate[ _-]?limit|too many requests|quota exceeded|insufficient (credits|quota)|capacity)'
      then 'rate_limited'
    -- our own stopwatch reads as a model failure unless it is named
    when e ~* '(signal has been aborted|aborterror|the operation was aborted|timed? ?out|etimedout|deadline|gateway_deadline)'
      then 'timeout'
    when e ~* '(not a valid model|model not found|no endpoints found|unknown model|no allowed providers)'
      then 'route_not_registered'
    when p_model is not null
      and not exists (select 1 from model_registry r where r.model_id = p_model and r.active)
      then 'route_not_registered'
    -- a REAL provider error object, or a 5xx with no payload
    when e ~ '"error"\s*:' or e ~* '^\s*\{"error"'
      or (p_http_status between 500 and 599 and e !~ '"object"\s*:\s*"chat\.completion"')
      then 'provider_error'
    -- the shape the certification actually hit
    when e ~ '"object"\s*:\s*"chat\.completion"' or e ~ '^\s*\{"id"\s*:\s*"gen-'
      then 'empty_completion'
    when lower(coalesce(p_finish_reason,'')) = 'length'
      or e ~* '(unexpected end of json|unparseable|invalid json|json parse|content_filter)'
      then 'malformed_output'
    when e ~* '(tool[_ ]call|tool result|tool failed|function call failed)'
      then 'tool_failure'
    when e ~* '(embedding|kb_match|retriev|context slice|no chunks)'
      then 'retrieval_failure'
    when e ~* '(pgrst|sqlstate|does not exist|deadlock detected|connection (reset|refused|closed)|relation .* does not exist)'
      then 'database_failure'
    when e ~* '(route_failed|no route|no model policy|budget|spend guard|ladder empty)'
      then 'orchestration_failure'
    when e ~* '(harness|fixture|test runner|seed(ing)? failed)'
      then 'test_runner_failure'
    else 'unclassified'
  end;

  return jsonb_build_object(
    'class_key', k,
    'retryable', (select retryable from llm_failure_class where class_key = k),
    'max_retries', (select max_retries from llm_failure_class where class_key = k),
    'retry_backoff_ms', (select retry_backoff_ms from llm_failure_class where class_key = k),
    'trips_breaker', (select trips_breaker from llm_failure_class where class_key = k),
    'opens_on_first', (select opens_on_first from llm_failure_class where class_key = k),
    -- honesty flag: the caller learns the evidence was cut off, so 'empty_completion' is never
    -- mistaken for a diagnosed root cause
    'evidence_truncated', truncated,
    'latency_ms', p_latency_ms
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_brief(p_max_chars integer DEFAULT 1600)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s jsonb; out text; d jsonb;
begin
  s := fn_company_state();
  out := 'COMPANY SELF-KNOWLEDGE (authoritative org facts — you may answer any question about the company from this):'||E'\n'
       ||'Vision: '||(s->>'vision')||E'\n'
       ||'Totals: '||(s->'totals'->>'departments')||' departments, '||(s->'totals'->>'brain_agents')||' brain agents, '
       ||(s->'totals'->>'category_sales_agents')||' category sales agents, '||(s->'totals'->>'tools_wired')||' wired tools, '
       ||(s->'totals'->>'open_objectives')||' open objectives, '||(s->'totals'->>'open_tasks')||' open tasks.'||E'\n'
       ||'Departments (lead · brain agents · north star):'||E'\n';
  for d in select * from jsonb_array_elements(s->'departments') loop
    out := out || '- '||(d->>'name')||' ['||(d->>'dept')||']: lead '||coalesce(d->>'lead_agent','—')
                || ', '||(d->>'headcount')||' agent(s)';
    if jsonb_array_length(d->'brain_agents') > 0 then
      out := out || ' ('||replace(replace(replace((d->'brain_agents')::text,'"',''),'[',''),']','')||')';
    end if;
    out := out || ', north star: '||coalesce(d->>'north_star','—')||E'\n';
    exit when length(out) > p_max_chars;
  end loop;
  return left(out, greatest(p_max_chars, 400));
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_connectivity_register()
 RETURNS TABLE(gap_class text, subject text, detail text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with external_intake(event_type) as (values
       ('inquiry.created'),    -- marketplace edge (supplier_portal / customer intake)
       ('rfq.created'),        -- marketplace edge function
       ('quote.received'),     -- marketplace edge function
       ('lead.qualified'),     -- inbound sales-lead intake (no internal producer until a sales surface exists)
       ('contract.submitted'), -- third-party contract intake (arrives from counterparties)
       ('deploy.completed')    -- CI / deploy hook (scripts/deploy_functions.mjs)
  ),
  -- Event types a non-dispatcher trigger on company_event consumes: a few trigger bodies against
  -- the distinct types, not against every event row.
  trigger_consumed(event_type) as (
    select distinct et.event_type
      from (select distinct ce.event_type from public.company_event ce) et
      join (select p.prosrc from pg_trigger t
              join pg_class c on c.oid = t.tgrelid
              join pg_namespace n on n.oid = c.relnamespace
              join pg_proc p on p.oid = t.tgfoid
             where n.nspname = 'public' and c.relname = 'company_event'
               and not t.tgisinternal and t.tgenabled <> 'D'
               and p.proname <> 'trg_company_event_dispatch') tf
        on tf.prosrc like '%' || et.event_type || '%'
  ),
  -- Every event type some database code can emit: a literal in a routine body, or a literal
  -- argument on a trigger (fn_emit_event reads the type from tg_argv, so the body never names it).
  producer(event_type) as (
    select distinct e.event_type
      from (select distinct ce.event_type from public.company_event ce
            union select es.event_type from public.event_subscription es
            union select w.trigger_event from public.workflow w where w.trigger_event is not null) e
     where exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                    where n.nspname = 'public' and p.prosrc like '%''' || e.event_type || '''%')
        or exists (select 1 from pg_trigger t
                    where not t.tgisinternal
                      and pg_get_triggerdef(t.oid) like '%''' || e.event_type || '''%')
  )
  -- A · a live workflow step with a side-effect action_class and no active executor. Nothing can
  -- perform the step; the workflow stalls at it. (Mirror of v_workflow_side_effects_without_executor.)
  select 'step_without_executor',
         w.workflow_key || ' step ' || s.step_no,
         'action_class ' || s.action_class || ' has no active org_action_executor'
    from public.workflow w
    join public.workflow_step s on s.workflow_key = w.workflow_key
    left join public.org_action_executor e on e.action_class = s.action_class and e.active
   where w.active and s.action_class is not null and e.action_class is null

  union all
  -- B · a live workflow step whose actor_role the RUNTIME resolver (fn_org_agent_resolve, the same
  -- function the dispatcher and handoff paths use) cannot resolve to any agent. Excluded: 'owner' and
  -- 'Director' in the generic employee_task workflow — those are CONTEXTUAL roles resolved per task
  -- from the task's own assigned_agent / manager, never global agents, so a null here is correct.
  select distinct 'actor_role_unresolved',
         s.actor_role,
         'used in active workflow steps; fn_org_agent_resolve() returns null'
    from public.workflow_step s
    join public.workflow w on w.workflow_key = s.workflow_key and w.active
   where s.actor_role is not null
     and s.actor_role not in ('owner', 'Director')                       -- contextual (employee_task)
     and public.fn_org_agent_resolve(s.actor_role) is null

  union all
  -- C · an event_type that has ACTUALLY been emitted into company_event but has no active subscriber.
  -- The dispatcher (fn_event_dispatch) delivers only through event_subscription, so such an event
  -- reaches no one. Excluded: 'task.assigned' — task assignment is delivered by the direct
  -- fn_org_task_assign path (the org_task row IS the delivery); a bus subscriber would double-create.
  -- Excluded since 4 Sep 2026: a RETIRED type — history in company_event, no producer left in the
  -- catalogue, not an external-intake type — because nothing can emit it again. Re-add an emitter
  -- and the row returns.
  select distinct 'event_emitted_no_subscriber',
         ce.event_type,
         'emitted into company_event, no active event_subscription — the dispatcher delivers it nowhere'
    from public.company_event ce
   where ce.event_type <> 'task.assigned'
     and not exists (select 1 from public.event_subscription es
                      where es.active and es.event_type = ce.event_type)
     -- 5 SEP 2026: a consumer is also a TRIGGER on company_event -- one that is not the generic
     -- dispatcher and whose function body names the event type (MASTER_PLAN 4.4 routes
     -- priority.updated to trg_priority_backlog_reorder, a named consumer with no subscription).
     -- 6 SEP 2026: computed ONCE in the trigger_consumed CTE. The first version correlated a
     -- LIKE over every trigger body per company_event row; the register went from seconds to
     -- past the cron's 120s statement_timeout and the red-view alerter's 21:22Z tick failed.
     and not exists (select 1 from trigger_consumed tc where tc.event_type = ce.event_type)
     and (exists (select 1 from producer p where p.event_type = ce.event_type)
          or exists (select 1 from external_intake x where x.event_type = ce.event_type))

  union all
  -- D · an active subscription pointing at an agent that is missing or inactive. The dispatcher joins
  -- company_event -> event_subscription -> org_agents on agent_key (it does NOT run the resolver), so
  -- the event is delivered to a dormant agent and dies there. Repoint to the active successor.
  select 'dead_subscription',
         es.event_type || ' -> ' || es.agent_key,
         case when a.agent_key is null then 'subscriber agent does not exist'
              else 'subscriber agent is inactive' end
    from public.event_subscription es
    left join public.org_agents a on a.agent_key = es.agent_key
   where es.active and (a.agent_key is null or not a.active)

  union all
  -- E · an active rpc executor whose target needs arguments the queue invoker cannot supply AND whose
  -- action_class is actually reachable from a live workflow step. fn_action_invoke_rpc fails any
  -- args>0 target, so a reachable one is a guaranteed runtime failure. (Registry rows for functions
  -- called only directly, never queued from a step, are not gaps and are excluded by the step join.)
  select distinct 'executor_target_needs_args',
         e.action_class || ' -> ' || e.target,
         'rpc target requires ' || (p.pronargs - p.pronargdefaults)::text
           || ' arg(s) with no default; reachable from a live workflow step; the queue invoker cannot call it'
    from public.org_action_executor e
    join pg_proc p on p.proname = e.target and p.pronamespace = 'public'::regnamespace
    join public.workflow_step s on s.action_class = e.action_class
    join public.workflow w on w.workflow_key = s.workflow_key and w.active
   where e.active and e.kind = 'rpc' and (p.pronargs - p.pronargdefaults) > 0
     -- 5 SEP 2026: the invoker now supplies ONE argument -- a single jsonb parameter receives
     -- params || request || {action_execution_id} (fn_action_invoke_rpc, the change_deployment
     -- packet). A target whose only required argument is that one jsonb is callable, and three
     -- such targets (change_deploy_baseline/promote/grade -> fn_change_deployment_execute) were
     -- read as gaps by the old rule and paged the founder on 5 Sep. Any other required argument
     -- is still a gap the invoker cannot fill.
     and not ((p.pronargs - p.pronargdefaults) = 1 and p.pronargs = 1
              and p.proargtypes[0] = 'jsonb'::regtype)

  union all
  -- F · an active workflow whose trigger_event has NO producer, so it can never auto-start. The live
  -- loop starts a workflow only when a company_event.event_type equals a workflow.trigger_event (via
  -- fn_workflow_start_due), so a trigger nothing emits is a workflow that never runs. "Has a producer"
  -- = some db function body or trigger argument contains the event literal (an emitter) OR the event
  -- has already occurred in company_event. Excluded: the declared EXTERNAL-INTAKE events, which arrive
  -- from real inbound traffic (edge functions, sales/contract intake, the CI deploy hook), not an
  -- internal db producer — they are wired at the edge layer and fire when that traffic is real.
  select 'workflow_trigger_has_no_producer',
         w.workflow_key,
         'trigger_event ' || w.trigger_event || ' is emitted by no db function or trigger, has never occurred, and '
           || 'is not a declared external-intake event — the workflow can never auto-start'
    from public.workflow w
   where w.active and w.trigger_event is not null
     and not exists (select 1 from public.company_event ce where ce.event_type = w.trigger_event)
     and not exists (select 1 from producer p where p.event_type = w.trigger_event)
     and not exists (select 1 from external_intake x where x.event_type = w.trigger_event)

  union all
  -- G · an active subscription to an event type NOTHING can emit: no routine body names it, no
  -- trigger argument names it, it has never occurred, and it is not a declared external-intake event.
  -- The dispatcher would wait for it forever (MASTER_PLAN §5.1 "phantom subscriptions").
  select distinct 'subscription_without_producer',
         es.event_type || ' -> ' || es.agent_key,
         'active subscription; no db function or trigger emits this event type, it has never occurred, '
           || 'and it is not a declared external-intake event'
    from public.event_subscription es
   where es.active
     and not exists (select 1 from public.company_event ce where ce.event_type = es.event_type)
     and not exists (select 1 from producer p where p.event_type = es.event_type)
     and not exists (select 1 from external_intake x where x.event_type = es.event_type)
$function$


CREATE OR REPLACE FUNCTION public.fn_company_hard_rules()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pct numeric; v_free date; v_fee numeric; v_win int; v_chase int; v_bmin int; v_bmax int; v_admin numeric; v_int numeric;
  v_free_n int; v_cat_min int;
  v_txt text; v_days text; v_aed text; v_mult text; v_src text;
begin
  select round(coalesce(standard_reveal_rate, 0.03) * 100, 2), supplier_charging_starts, supplier_reg_fee,
         refund_window_working_days, chase_after_working_days, bank_settlement_working_days_min, bank_settlement_working_days_max,
         coalesce(supplier_free_count, 1000), coalesce(category_open_min_suppliers, 10)
    into v_pct, v_free, v_fee, v_win, v_chase, v_bmin, v_bmax, v_free_n, v_cat_min
    from public.pricing_config order by id limit 1;
  v_pct := coalesce(v_pct, 3); v_win := coalesce(v_win, 5); v_chase := coalesce(v_chase, 3);
  v_free_n := coalesce(v_free_n, 1000); v_cat_min := coalesce(v_cat_min, 10);
  -- 6 Sep 2026: the money side of the ladder, from decision_policy (founder ruling, verbatim there)
  v_admin := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_admin_fee_aed'), 250);
  v_int   := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_late_fee_annual_pct'), 9);

  v_txt := regexp_replace(coalesce((select p.html from public.pages p where p.slug = 'legal_supplier_body'), ''),
                          '<[^>]+>', ' ', 'g');
  v_days := substring(v_txt from 'begin responding to the Customer within\s+([0-9]+)\s+working days');
  v_aed  := substring(v_txt from 'liquidated compensation of AED\s+([0-9,]+)\s+per incident');
  v_mult := substring(v_txt from 'per incident, or\s+([a-z]+ \([0-9]+\)|[0-9]+)\s+times the fee');
  v_src  := case when v_days is not null and v_aed is not null and v_mult is not null
                 then 'read from the published Supplier Agreement and pricing_config just now'
                 else 'pricing_config live; the Supplier Agreement text did not match the expected clause wording, so the last published figures are stated' end;

  return '# THE FOUR HARD RULES - the published Terms and Supplier Agreement; the founder''s ONLY rules ('||v_src||'). No employee may relax them.'||E'\n'
    ||'1. REVEAL FEE: the CUSTOMER pays '||v_pct||'% of the selected quotation value - NO cap, NO discount, NO promotional rate, NO coupon and NO free reveal (founder, 6 Sep 2026; pricing_config forbids them by constraint) - ex-VAT, once per reveal, to reveal a supplier. Comparing quotes is FREE. Suppliers pay NO commission, ever'
    ||case when v_free is not null
           then '; supplier registration is free until '||to_char(v_free - 1, 'DD Mon YYYY')||', then AED '||coalesce(v_fee::text,'1000')||'/year (first '||v_free_n||' registrants permanently exempt)'
           else '; supplier registration is FREE for the first '||v_free_n||' registrations (permanently exempt), then AED '||coalesce(v_fee::text,'1000')||'/year - there is NO calendar start date: charging begins with registration '||(v_free_n + 1)||', whenever that happens (founder, 6 Sep 2026)' end||'.'||E'\n'
    ||'2. TOP-3 COMPARISON REPORT: however many quotations arrive (3 or 100+), the report ranks them ALL and shows the best THREE on technical AND commercial merit - never cheapest-wins.'||E'\n'
    ||'3. SUPPLIER NON-RESPONSE: a revealed supplier must begin responding within '||coalesce(v_days, v_win::text)||' working days of the customer''s PAYMENT (UAE week: Mon-Fri, Sat+Sun off, public holidays excluded). '
    ||'THE LADDER (founder ruling 6 Sep 2026, final; pricing_config): the supplier has '||v_win||' working days from payment. No response by working day '||v_chase||' - the Customer Success Director chases the supplier, customer copied; still silent on working day '||v_win||' - the founder is notified for his final call; no response to that - the refund is issued. '
    ||'Every refund of any amount is the founder''s decision, never automatic. The customer gets the FULL reveal fee back (the '||v_pct||'% paid, nothing deducted) and is told banks take '||coalesce(v_bmin,7)||'-'||coalesce(v_bmax,14)||' working days. '
    ||'The supplier then owes that reveal fee ('||v_pct||'%) + AED '||v_admin||' administrative fee + '||v_int||'% per annum simple interest (UAE statutory maximum), and is blocked from matching until it is paid. Never ask the founder about any of this again.'||E'\n'
    ||'4. ANTI-CIRCUMVENTION: identities stay anonymous until the reveal and there is no off-platform contact before it. A supplier that takes an introduced customer off-platform within 24 months owes AED '||coalesce(v_aed, '15,000')||' per incident OR '||coalesce(v_mult, 'three (3)')||' times the fee, whichever is higher, plus the unpaid fee.'||E'\n'
    ||'5. CATEGORY OPENING (founder''s standing decision, 6 Sep 2026): a category is OPEN once it has '||v_cat_min||' verified registered suppliers (public.v_category_open); matching an RFQ still needs at least one confirmed supplier. Never ask the founder about any figure in these five lines.'||E'\n';
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_knowledge_search(p_question text, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with q as (select public.fn_task_tsquery(p_question) as tsq)
  select coalesce(jsonb_agg(jsonb_build_object(
           'title', title,
           'scope', case when scope_type='company' then 'company-wide' else coalesce(dept_key, scope_key, layer) end,
           'layer', layer,
           'content', left(content, 1500))
         order by rank desc), '[]'::jsonb)
  from (
    select k.title, k.scope_type, k.dept_key, k.scope_key, k.layer, k.content,
           ts_rank(k.tsv, (select tsq from q)) as rank
      from public.ops_knowledge k
     where k.runtime_eligible and k.supersession_state = 'current'
       and k.layer is distinct from 'it_security_deep' -- IT/cyber layer is scoped, not universal
       and (select tsq from q) is not null and k.tsv @@ (select tsq from q)
     order by ts_rank(k.tsv, (select tsq from q)) desc, coalesce(k.effective_date,'1900-01-01') desc
     limit greatest(least(coalesce(p_limit,8), 30), 1)
  ) x;
$function$


CREATE OR REPLACE FUNCTION public.fn_company_knowledge_upsert(p_rid text, p_module text, p_title text, p_content text, p_kw text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  insert into public.ops_knowledge(
    record_id, scope_type, scope_key, layer, module, record_type, title, content,
    structured_data, source_ids, implementation_status, validation_status, authority_tier,
    risk_level, version, keywords, dependencies, escalation_rule, jurisdiction, source_freshness,
    confidentiality, runtime_eligible, deterministic, supersession_state, embedding_status, effective_date)
  values (
    'qd-company:'||p_rid, 'company', 'company_core', 'company_core', p_module, 'md', p_title,
    p_content || E'\n\nYou can answer questions about: ' || array_to_string(p_kw, ', ') || '.',
    '{}'::jsonb, array['fn_company_org_directory_sync'], 'active', 'validated', 'autonomous',
    'low', '1', p_kw, '{}'::text[], '{}'::jsonb, 'UAE', 'current',
    'internal', true, true, 'current', 'pending', current_date)
  on conflict (record_id) do update set
    module=excluded.module, title=excluded.title, content=excluded.content,
    keywords=excluded.keywords, effective_date=excluded.effective_date,
    supersession_state='current', embedding_status='pending';
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_map(p_per_class integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with cap as (select greatest(1, least(coalesce(p_per_class, 40), 200)) n),
  ranked as (
    select g.kind, g.ref_id, g.label, g.props,
           row_number() over (partition by g.kind order by g.label, g.ref_id) rn
      from graph_nodes g
  ),
  kept as (select * from ranked, cap where ranked.rn <= cap.n),
  totals as (select kind, count(*) total from graph_nodes group by kind)
  select jsonb_build_object(
    'rebuilt_at', (select max(updated_at) from graph_nodes),
    'node_total', (select count(*) from graph_nodes),
    'edge_total', (select count(*) from graph_edges),
    'per_class_cap', (select n from cap),
    'classes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kind', t.kind, 'total', t.total,
               'shown', (select count(*) from kept k where k.kind = t.kind))
             order by t.total desc)
        from totals t), '[]'::jsonb),
    'nodes', coalesce((
      select jsonb_agg(jsonb_build_object(
               'kind', k.kind, 'id', k.ref_id, 'label', k.label, 'props', k.props)
             order by k.kind, k.label)
        from kept k), '[]'::jsonb),
    'edges', coalesce((
      select jsonb_agg(distinct jsonb_build_object(
               'src_kind', e.src_kind, 'src', e.src_ref, 'rel', e.rel,
               'dst_kind', e.dst_kind, 'dst', e.dst_ref))
        from graph_edges e
       where exists (select 1 from kept a where a.kind = e.src_kind and a.ref_id = e.src_ref)
         and exists (select 1 from kept b where b.kind = e.dst_kind and b.ref_id = e.dst_ref)),
      '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_company_org_directory_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d record; s record; a_txt text; sec_txt text; v_social text; v_blog text; v_web text; v_cat text;
        v_wf text; v_legal text; v_compl text; v_biz jsonb; v_n int := 0;
begin
  -- 1. THE WHOLE ORG DIRECTORY — one record per department; everyone knows everyone's role, line
  --    manager, what they are measured on and their live rating.
  for d in select dept_key, name, charter, north_star, lead_agent from public.org_departments where active order by dept_key loop
    select string_agg(
             '  - ' || a.agent_key || ' (' || coalesce(a.title, a.role, '') || ') — reports to ' || coalesce(a.manager_key,'—')
             || coalesce((select ' — measured on: ' || string_agg(k.kpi || ' [target ' || coalesce(k.target_value::text,'—')
                          || ', current ' || coalesce(k.actual_value::text,'—') || ']', '; ')
                          from public.employee_kpi k where k.agent_key = a.agent_key and coalesce(k.active,true)), ''),
             E'\n' order by a.agent_key)
      into a_txt from public.org_agents a where a.active and a.department = d.dept_key;
    perform public.fn_company_knowledge_upsert(
      'org-' || d.dept_key, 'organization',
      'QuotesDone Org — the ' || coalesce(d.name, d.dept_key) || ' team',
      'DEPARTMENT: ' || coalesce(d.name, d.dept_key) || ' [' || d.dept_key || ']. Lead: ' || coalesce(d.lead_agent,'—')
      || '. North star: ' || coalesce(d.north_star,'—') || E'\n'
      || 'Members — agent — role — reports to (line manager) — measured on [target, current rating]:' || E'\n'
      || coalesce(a_txt, '(none)'),
      array[d.dept_key, coalesce(d.name,''), 'who works in ' || coalesce(d.name,d.dept_key), 'department team',
            'line manager', 'who reports to whom', 'kpi', 'measured on', 'current rating', 'colleagues',
            'who leads ' || coalesce(d.name,d.dept_key)]);
    v_n := v_n + 1;
  end loop;

  -- 2. THE PUBLISHED FAQ — grouped by section; the 484 answers a colleague could give a customer or supplier.
  for s in select coalesce(nullif(btrim(section),''),'general') sec, string_agg('Q: '||question||E'\n'||'A: '||coalesce(answer,''), E'\n' order by sort nulls last, id) qa
             from public.company_faq where coalesce(public,true) and coalesce(status,'approved') <> 'rejected'
             group by 1 loop
    perform public.fn_company_knowledge_upsert(
      'faq-' || regexp_replace(lower(s.sec),'[^a-z0-9]+','-','g'), 'faq',
      'QuotesDone FAQ — ' || s.sec,
      'FREQUENTLY ASKED (published answers — you may give these to customers and suppliers):' || E'\n' || left(s.qa, 6000),
      array['faq', 'frequently asked', s.sec, 'question', 'answer', 'how do i', 'what is', 'customer question', 'supplier question']);
    v_n := v_n + 1;
  end loop;

  -- 3. SOCIAL, BLOG, WEBSITE — the company's own published content.
  select string_agg('  - ['||to_char(created_at,'DD Mon YYYY')||', '||coalesce(channels::text,'')||', '||coalesce(status,'')||'] '
                    || left(coalesce(content->>'text', content->>'body', content::text), 200), E'\n' order by created_at desc)
    into v_social from public.social_posts;
  perform public.fn_company_knowledge_upsert('content-social','content','QuotesDone — Our Social Media Posts',
    'SOCIAL MEDIA POSTS (most recent first):' || E'\n' || coalesce(v_social,'(none yet)'),
    array['social media','social post','last post','latest post','instagram','linkedin','what did we post','our content','marketing post']);
  v_n := v_n + 1;

  select string_agg('  - ['||coalesce(to_char(published_at,'DD Mon YYYY'),'draft')||', '||coalesce(category,'')||'] '||title
                    ||coalesce(' — '||excerpt,''), E'\n' order by published_at desc nulls last)
    into v_blog from public.blog_posts where published;
  perform public.fn_company_knowledge_upsert('content-blog','content','QuotesDone — Our Blog Articles',
    'BLOG ARTICLES (published):' || E'\n' || left(coalesce(v_blog,'(none yet)'), 6000),
    array['blog','article','blog post','our articles','what have we written','content','seo','latest blog']);
  v_n := v_n + 1;

  select string_agg('  - /'||slug, E'\n' order by slug) into v_web from public.pages;
  perform public.fn_company_knowledge_upsert('content-website','content','QuotesDone — Our Website Pages',
    'WEBSITE PAGES we publish (the public site an agent should know exists):' || E'\n' || coalesce(v_web,'(none)')
    || E'\n\nThe published legal terms, services and marketing copy live on these pages; the terms and commercials are also summarised in the company terms and commercials knowledge.',
    array['website','web page','our site','pages','website content','what is on our website','public site']);
  v_n := v_n + 1;

  -- 4. THE SUPPLIER CATEGORY TAXONOMY — every category an RFQ can be routed to.
  select string_agg('  ' || num || '. ' || name || case when regulated then ' (regulated)' else '' end, E'\n' order by sort, num)
    into v_cat from public.catalog_supplier_categories;
  perform public.fn_company_knowledge_upsert('categories', 'taxonomy',
    'QuotesDone — The Supplier Categories We Cover',
    'SUPPLIER CATEGORIES (' || (select count(*) from public.catalog_supplier_categories)::text
      || ' in total) — every category an RFQ can be routed to, in order:' || E'\n' || coalesce(v_cat, '(none)'),
    array['categories','supplier categories','what do we cover','category list','taxonomy','trades','how many categories','what categories','regulated categories','which category','list the categories']);
  v_n := v_n + 1;

  -- 5. THE FULL OPERATING CATALOG — all 30 workflows the company runs, every domain (not just the funnel).
  select string_agg('  ' || workflow_id || ' [' || coalesce(domain,'') || '] ' || workflow_name, E'\n' order by workflow_id)
    into v_wf from public.phase_b_workflow;
  perform public.fn_company_knowledge_upsert('workflows', 'operating_model',
    'QuotesDone — The 30 Workflows We Run',
    'THE COMPANY''S FULL OPERATING MODEL — every workflow the company runs, by id, domain and purpose:' || E'\n'
    || coalesce(v_wf,'') || E'\n'
    || 'The marketplace core (customer to suppliers to reveal) is W05 to W06 to W07 to W08 to W12 to W13 to W14 to W15 to W16; '
    || 'the rest run growth (W01-W03,W20,W21), product/AI (W22-W24), finance (W16,W27), legal (W28), assurance/security (W24,W29), '
    || 'data/knowledge (W25,W26) and people/org (W30).',
    array['workflows','processes','how we operate','operating model','what workflows do we run','what does workflow','the 30 workflows','how does work flow end to end','our processes','company operations']);
  v_n := v_n + 1;

  -- 6. LEGAL, COMPLIANCE AND POLICY FRAMEWORK.
  select string_agg('  - ' || coalesce(title, slug) || case when coalesce(category,'') <> '' then ' [' || category || ']' else '' end
         || case when coalesce(summary,'') <> '' then ': ' || left(summary,140) else '' end, E'\n' order by category, title)
    into v_legal from public.legal_documents;
  select string_agg('  - ' || requirement || ' (' || case when present then 'in place' else 'pending' end || ')', E'\n' order by priority nulls last, id)
    into v_compl from public.legal_checklist;
  perform public.fn_company_knowledge_upsert('legal', 'legal_compliance',
    'QuotesDone — Legal, Compliance and Policy Framework',
    'LEGAL & COMPLIANCE. QuotesDone operates under UAE law (Asia/Dubai; PDPL data protection). Published legal documents:' || E'\n'
    || coalesce(v_legal,'(none)') || E'\n' || 'Compliance checklist:' || E'\n' || coalesce(v_compl,'(none)') || E'\n'
    || 'Posture: anonymous marketplace, buyer/supplier identities protected until reveal, EVERY refund is founder-approved, '
    || 'late fees under UAE Federal Decree-Law 50/2022, disputes handled through a defined escalation ladder.',
    array['legal','compliance','regulatory','policy','terms of service','privacy policy','pdpl','data protection','uae law','are we compliant','legal documents','what laws apply','governing law','gdpr']);
  v_n := v_n + 1;

  -- 7. THE BUSINESS ENTITIES — the live customer/supplier/order landscape, and HOW to look up any one.
  begin v_biz := public.fn_business_entity_summary(); exception when others then v_biz := '{}'::jsonb; end;
  perform public.fn_company_knowledge_upsert('business-entities', 'business_data',
    'QuotesDone — Our Customers, Suppliers and Orders (live), and how to look them up',
    'THE BUSINESS RIGHT NOW (live counts):' || E'\n' ||
    '  Customers: ' || coalesce(v_biz->>'customers','0') || ' (with an inquiry: ' || coalesce(v_biz->>'customers_with_inquiry','0') || ')' || E'\n' ||
    '  Suppliers: ' || coalesce(v_biz->>'suppliers_total','0') || ' total — ' || coalesce(v_biz->>'suppliers_approved','0') || ' approved, '
      || coalesce(v_biz->>'suppliers_prospective','0') || ' prospective; sendable pool ' || coalesce(v_biz->>'sendable_supplier_pool','0') || E'\n' ||
    '  Inquiries/RFQs: ' || coalesce(v_biz->>'inquiries','0') || '  ·  Quotes: ' || coalesce(v_biz->>'quotes','0') || '  ·  Transactions/orders: ' || coalesce(v_biz->>'transactions','0') || E'\n' ||
    '  Categories: ' || coalesce(v_biz->>'categories_total','0') || ' (' || coalesce(v_biz->>'categories_at_target','0') || ' at the 10-supplier target)' || E'\n' ||
    'HOW TO KNOW A SPECIFIC ONE (do not memorise the records — look them up live):' || E'\n' ||
    '  - fn_business_entity_lookup(entity, key): one customer/supplier/inquiry/quote/transaction by id, email, company name or phone -> its full profile.' || E'\n' ||
    '  - fn_business_entity_list(entity, filter, limit): list or search them (e.g. all approved suppliers, recent inquiries).' || E'\n' ||
    '  - fn_business_entity_summary(): these live counts. Call these functions directly — you run with the database access to do so.',
    array['customers','suppliers','how many customers','how many suppliers','who are our customers','who are our suppliers','their profiles','their orders','look up a supplier','find a customer','list suppliers','our orders','the crm','business data','inquiries','quotes','transactions','entity lookup']);
  v_n := v_n + 1;

  return jsonb_build_object('ok', true, 'records', v_n, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_self_knowledge_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_state jsonb := public.fn_company_state();
  v_snap  jsonb := public.fn_company_snapshot();
  v_brief text  := public.fn_company_brief(6000);
  v_fee   numeric; v_sup_fee numeric; v_charge date; v_refund_wd int; v_cur text; v_free_n int; v_cat_min int;
  v_chase_wd int; v_bank_min int; v_bank_max int; v_admin numeric; v_pct numeric; v_founder_words text;
  v_target text; v_deadline text;
  v_social text; v_social_at text; v_blog text; v_blog_at text;
  v_funnel text;
  v_founder text;
  v_tmpl text;
  v_rev numeric; v_exp numeric; v_pnl text;
  v_stance record; v_decisions text; v_cat_open text;
  v_records jsonb; r jsonb; v_rid text; v_n int := 0;
  reg public.company_registration%rowtype;
  -- 6 SEP 2026: the two supplier loops (acquisition, sanctions screening) — live values for the record below
  v_golive boolean; v_reg_target text; v_reg_month text; v_bd text; v_co text; v_last_un text; v_last_uae text;
  v_hits_open int; v_invited int; v_registered int; v_followups int; v_intake int;
begin
  v_golive := public.fn_supplier_outreach_golive();
  select coalesce(target_value::text, '300') into v_reg_target from public.company_goals where key = 'suppliers_registered_monthly';
  select coalesce(actual_value::text, '0') || ' (measured ' || coalesce(to_char(measured_at, 'DD Mon YYYY HH24:MI'), 'not yet') || ' UTC)'
    into v_reg_month from public.employee_kpi where agent_key = 'bd' and kpi = 'Suppliers registered per month' and active;
  select display_name into v_bd from public.org_role where role_id = 'business_development';
  select display_name into v_co from public.org_role where role_id = 'ceo';
  select entries || ' entries, fetched ' || to_char(fetched_at, 'DD Mon YYYY HH24:MI') || ' UTC, sha256 ' || left(coalesce(sha256, '?'), 12) || ', ' || status
    into v_last_un from public.screening_run where source = 'un_consolidated' and run_tag is null order by id desc limit 1;
  select entries || ' entries, fetched ' || to_char(fetched_at, 'DD Mon YYYY HH24:MI') || ' UTC, sha256 ' || left(coalesce(sha256, '?'), 12) || ', ' || status
    into v_last_uae from public.screening_run where source = 'uae_local_terrorist_list' and run_tag is null order by id desc limit 1;
  select count(*) into v_hits_open from public.supplier_screening_hit where status = 'open';
  select count(*) filter (where invite_status is not null), count(*) filter (where lifecycle_stage = 'registered'), coalesce(sum(invite_followups), 0)
    into v_invited, v_registered, v_followups from public.leads where coalesce(email, '') not ilike '%@example.invalid';
  select count(*) into v_intake from public.supplier_lead_intake where run_tag is null;
  select * into reg from public.company_registration order by recorded_at desc limit 1;
  -- the founder identity (who leads the company)
  select string_agg(identity, ' / ' order by identity) into v_founder
    from public.phase_c_founder_identity where active and kind = 'email';
  -- the live P&L (financial state beyond headline revenue)
  select coalesce(sum(amount) filter (where type='revenue'),0), coalesce(sum(amount) filter (where type='expense'),0),
         string_agg(case when amount <> 0 then '  - '||type||': '||name||' = AED '||amount::text else null end, E'\n' order by type, code)
    into v_rev, v_exp, v_pnl from public.gl_pnl;
  select standard_reveal_rate, supplier_reg_fee, supplier_charging_starts, refund_window_working_days,
         coalesce(reveal_currency,'AED'), chase_after_working_days, bank_settlement_working_days_min, bank_settlement_working_days_max,
         coalesce(supplier_free_count,1000), coalesce(category_open_min_suppliers,10)
    into v_fee, v_sup_fee, v_charge, v_refund_wd, v_cur, v_chase_wd, v_bank_min, v_bank_max, v_free_n, v_cat_min
    from public.pricing_config order by id limit 1;
  -- 6 SEP 2026: the refund ladder's money side and the founder's own words, from decision_policy
  v_admin := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_admin_fee_aed'), 250);
  v_pct   := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_late_fee_annual_pct'), 9);
  v_founder_words := (select d.value #>> '{}' from public.decision_policy d where d.key = 'refund_policy_founder_decision_2026_09_06');
  -- 6 SEP 2026: the founder's budget stance and his decisions on record (company_financial_stance,
  -- company_policy_decision), and the category-open count (v_category_open)
  select * into v_stance from public.company_financial_stance where id = 1;
  select string_agg('- ' || upper(decision_key) || ' (decided ' || to_char(decided_on,'DD Mon YYYY') || ' by the ' || decided_by
                    || case when never_ask_again then '; NEVER ask about it again' else '' end || '): ' || decision_text
                    || case when cardinality(applies_to) > 0 then ' [applies to: ' || array_to_string(applies_to, ', ') || ']' else '' end,
                    E'\n' order by decision_key)
    into v_decisions from public.company_policy_decision;
  select count(*) filter (where is_open) || ' of ' || count(*) || ' categories are OPEN today (' ||
         coalesce(max(verified_registered_suppliers),0) || ' is the highest verified-registered count in any category)'
    into v_cat_open from public.v_category_open;

  select coalesce(target_value::text,'1000000'), coalesce(to_char(deadline,'DD Mon YYYY'),'31 Aug 2027')
    into v_target, v_deadline
    from public.company_goals
   where active and (lower(coalesce(key,'')) like '%revenue%' or lower(coalesce(goal,'')) like '%revenue%'
                     or category = 'Financial')
   order by sort nulls last limit 1;

  select left(coalesce(content->>'text', content->>'body', content::text), 240), to_char(created_at,'DD Mon YYYY')
    into v_social, v_social_at from public.social_posts order by created_at desc limit 1;
  select title, to_char(coalesce(published_at, updated_at),'DD Mon YYYY')
    into v_blog, v_blog_at from public.blog_posts where published order by published_at desc nulls last limit 1;

  select string_agg('  ' || workflow_id || ' — ' || workflow_name, E'\n' order by workflow_id)
    into v_funnel from public.phase_b_workflow
   where workflow_id in ('W04','W05','W06','W07','W08','W09','W10','W12','W13','W14','W15','W16','W17','W18');

  -- 6 SEP 2026: the WhatsApp template ledger (messaging_template), one line per template, live.
  select coalesce(string_agg('  - ' || template_key || ' [' || lang || ']: ' || upper(status) || ' (' || sid
           || coalesce(', ' || category, '') || coalesce(', submitted ' || to_char(submitted_at, 'DD Mon YYYY'), '')
           || coalesce(', approved (first seen ' || to_char(approved_at, 'DD Mon YYYY') || ')', '')
           || coalesce(', reason: ' || left(rejection_reason, 90), '') || coalesce(', ' || note, '') || ')',
           E'\n' order by template_key, lang), '  (no templates recorded)')
    into v_tmpl from public.messaging_template where channel = 'whatsapp';

  v_records := jsonb_build_array(

    -- 6 SEP 2026: the company's registration and tax status, from company_registration (the founder
    -- supplied the trade licence and ruled on VAT, Corporate Tax and the auditor that day; all are
    -- closed facts, never questions).
    jsonb_build_object('rid','registration','module','company_registration',
      'title','QuotesDone — Trade licence, registration and tax status',
      'kw', to_jsonb(array['trade licence','trade license','licence number','license number','DET','department of economy and tourism',
        'issuing authority','licence expiry','renewal','activity code','portal','software design','trader licence','e-trader',
        'VAT','vat registered','TRN','tax registration number','FTA','federal tax authority','threshold','375,000','corporate tax',
        'corporate tax registration','CT registration','small business relief','auditor','external auditor','audit firm','who audits us',
        'are we vat registered','do we charge vat','company registration','legal entity','owner','who owns the licence']),
      'content',
        case when reg.license_no is null then 'REGISTRATION: not recorded.' else
        'TRADE LICENCE: ' || reg.authority || ' ' || reg.license_type || ' no. ' || reg.license_no || ', trade name "' || reg.trade_name || '"; issued ' ||
        to_char(reg.issued_on,'DD Mon YYYY') || ', expires ' || to_char(reg.expires_on,'DD Mon YYYY') || ' (renew before then; renewal is a company task, not a founder question).' || E'\n' ||
        'OWNER: ' || reg.owner_name || ' (' || reg.owner_share || '); licensed activities: ' || reg.activities || '.' || E'\n' ||
        'REGISTERED CONTACT: ' || reg.registered_email || ', ' || reg.registered_mobile || '; e-stores on the licence: ' || reg.e_stores || '.' || E'\n' ||
        'LICENCE CLASS: ' || reg.license_class_note || E'\n' ||
        'TAX STATUS: ' || case when reg.vat_registered then 'VAT-registered, TRN ' || coalesce(reg.trn,'?') else
          'NOT VAT-registered (founder ruling ' || to_char(reg.vat_ruling_on,'DD Mon YYYY') || '): no VAT is charged or shown on any QuotesDone invoice until taxable supplies reach the FTA mandatory registration threshold of AED ' ||
          to_char(reg.vat_threshold_aed,'FM999,999,999') || ' in a rolling 12 months. Do not ask the founder about VAT or the TRN; when revenue approaches the threshold the CFO opens a registration task.' end || E'\n' ||
        'CORPORATE TAX: ' || coalesce(reg.corporate_tax_note,'registration status not recorded.') || E'\n' ||
        'AUDITOR: ' || coalesce(reg.auditor,'not recorded.')
        end),

    jsonb_build_object('rid','identity','module','company_identity',
      'title','QuotesDone — Identity, Vision and Mission',
      'kw', to_jsonb(array['vision','mission','what is quotesdone','who are we','company','marketplace','target','revenue goal','anonymous','uae','b2b',
        'who is the founder','company founder','who owns quotesdone','founder name','ahmad alzain','the owner',
        'company target and deadline','revenue target','what is our goal','aed 1 million target','1000000 by 2027','when is the deadline']),
      'content',
        'WHO WE ARE. ' || coalesce(v_state->>'mission','') || E'\n' ||
        'VISION: ' || coalesce(v_state->>'vision','') || E'\n' ||
        'TARGET: AED ' || v_target || ' in revenue by ' || v_deadline ||
          ' — every department''s objectives trace to this one number.' || E'\n' ||
        'HOW IT WORKS IN ONE LINE: an anonymous UAE B2B quotation marketplace — buyers post an RFQ, verified UAE '
        'suppliers submit quotes, and the buyer pays a small reveal fee to unlock and contact a chosen supplier. '
        'Every department is an autonomous AI expert that plans and executes toward the vision.' || E'\n' ||
        'FOUNDER / OWNER: Ahmad Alzain (' || coalesce(v_founder,'management@quotesdone.com') || '). The company is '
        'founder-led: he sets the vision, the target and the boundaries, and he is the ONLY approver of refunds. '
        'The AI departments run everything else on their own.'),

    jsonb_build_object('rid','financials','module','financials',
      'title','QuotesDone — Our Financials (live P&L) and the Budget Policy',
      'kw', to_jsonb(array['financials','finance','p&l','profit and loss','expenses','costs','revenue','how much did we spend','what were our expenses','net','burn','money','accounting','are we profitable',
