      structured_data, source_ids, implementation_status, validation_status, authority_tier,
      risk_level, version, keywords, dependencies, escalation_rule, jurisdiction, source_freshness,
      confidentiality, runtime_eligible, deterministic, supersession_state, embedding_status,
      effective_date)
    values (
      v_rid, 'company', 'company_core', 'company_core', r->>'module', 'md', r->>'title',
      -- fold the keyword vocabulary into the content so the generated tsv (title+content) indexes the
      -- phrasings agents actually ask in, not only the prose. This is what makes deep questions match.
      (r->>'content') || E'\n\nYou can answer questions about: ' ||
        array_to_string(array(select jsonb_array_elements_text(r->'kw')), ', ') || '.',
      '{}'::jsonb, array['fn_company_self_knowledge_sync'], 'active', 'validated', 'autonomous',
      'low', '1', array(select jsonb_array_elements_text(r->'kw')), '{}'::text[], '{}'::jsonb, 'UAE', 'current',
      'internal', true, true, 'current', 'pending', current_date)
    on conflict (record_id) do update set
      module = excluded.module, title = excluded.title, content = excluded.content,
      keywords = excluded.keywords, effective_date = excluded.effective_date,
      supersession_state = 'current', embedding_status = 'pending';
    v_n := v_n + 1;
  end loop;

  -- The org directory (everyone knows everyone: role, line manager, KPI, live rating) and the
  -- published content (FAQ, social, blog, website) are recomposed in the same refresh.
  perform public.fn_company_org_directory_sync();

  return jsonb_build_object('ok', true, 'records', v_n, 'ran_at', now(),
    'revenue_30d_aed', v_snap->>'revenue_30d_aed', 'reveal_fee_pct', round(v_fee*100,2),
    'employees', v_snap->>'employees');
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s jsonb;
begin
  s := jsonb_build_object(
    'employees',        (select count(*) from org_agents where active),
    -- THE CUSTOMER BASE, which the snapshot has never recorded. Zero is the measurement today —
    -- 0 customers and 0 inquiries carrying one — and writing it down daily is what makes the day
    -- it stops being zero visible in the replay.
    'customers',              (select count(*) from customers),
    'customers_with_inquiry', (select count(distinct customer_id) from inquiries where customer_id is not null),
    'departments',      (select count(*) from org_departments where active),
    'operating_systems',(select count(*) from operating_system where active),
    'kpis',             (select count(*) from employee_kpi where active),
    'kpis_measurable',  (select count(*) from employee_kpi where active and measure_sql is not null),
    'kpi_gaps_open',    (select count(*) from org_tasks where title like 'KPI missed:%' and status<>'done'),
    'open_tasks',       (select count(*) from org_tasks where status<>'done'),
    'needs_founder',    (select count(*) from org_tasks where status<>'done' and needs_founder),
    'approved_suppliers',(select count(*) from leads where approval_status='approved'),
    'sendable_pool',    (select coalesce(sum(sendable),0) from v_supply_gap),
    'categories_at_target',(select count(*) from v_supply_gap where approved>=10),
    'revenue_30d_aed',  (select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) from transactions where revealed_at>now()-interval '30 days'),
    'ai_cost_30d_aed',  (select round(coalesce(sum(cost_aed),0),2) from ai_cost_log where occurred_at>now()-interval '30 days'),
    'knowledge_items',  (select count(*) from agent_knowledge),
    'knowledge_quarantined',(select count(*) from agent_knowledge where validation_status='quarantined'),
    'outcomes_pending', (select count(*) from outcome_record where verdict='pending'),
    'outcomes_improved',(select count(*) from outcome_record where verdict='improved'),
    'decisions_7d',     (select count(*) from decision_log where created_at>now()-interval '7 days'),
    'agent_runs_7d',    (select count(*) from agent_runs where started_at>now()-interval '7 days'),
    'error_rate_7d',    (select round(100.0*count(*) filter (where status='error')/nullif(count(*),0),2) from agent_runs where started_at>now()-interval '7 days'),
    'os_health',        (select jsonb_object_agg(os_key,health) from os_review where period=to_char(now(),'IYYY-"W"IW')),
    'indices',          (select jsonb_object_agg(index_name,score) from company_index where measured_on=current_date),
    'autonomy_enabled', (select value from app_secrets where key='agent_autonomy_enabled'),
    'invite_enabled', (select value from app_secrets where key='invite_enabled'),
      -- THE PULSE (3 Sep 2026): the signals the founder's one screen lacked, from the instruments that
      -- already measure them. Liveness (a cron that never fires), what is dead-lettered, what failed in
      -- the last day, what is parked behind the paid-model hold, what paged him, and the ad money.
      'crons_stale',        (select coalesce(jsonb_agg(jobname order by jobname), '[]'::jsonb) from public.v_cron_stale),
      'dead_letters_open',  (select count(*) from public.dead_letter where resolved_at is null),
      'failed_runs_24h',    (select count(*) from public.agent_runs where status = 'error' and started_at > now() - interval '24 hours'),
      'runs_skipped_24h',   (select count(*) from public.agent_runs where status = 'skipped' and started_at > now() - interval '24 hours'),
      'actions_held',       (select count(*) from public.action_execution where status = 'held'),
      'founder_alerts_24h', (select count(*) from public.founder_alerts where channel in ('email','whatsapp') and created_at > now() - interval '24 hours'),
      'ad_spend', jsonb_build_object(
        'active_campaigns', (select count(*) from public.ad_campaign_state where not is_demo and status = 'ACTIVE'),
        'active_daily_aed', (select coalesce(sum(daily_budget_aed), 0) from public.ad_campaign_state where not is_demo and status = 'ACTIVE'),
        'daily_ceiling_aed', public.fn_ad_spend_daily_ceiling(),
        'decisions_pending', (select count(*) from public.ad_decision where executed_at is null),
        'meta_token_present', exists (select 1 from app_secrets where key = 'meta_access_token' and coalesce(value, '') <> '')));

  insert into company_snapshot (snapshot_on, state) values (current_date, s)
  on conflict (snapshot_on) do update set state=excluded.state, created_at=now();

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_snapshot',now(),now(),'ok',jsonb_build_object('keys',(select count(*) from jsonb_object_keys(s))),
    'Company state snapshotted for '||current_date||'. Any past day can now be reconstructed.');
  return s;
end $function$


CREATE OR REPLACE FUNCTION public.fn_company_state()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with depts as (
    select d.dept_key, d.name, d.charter, d.north_star, d.lead_agent, d.active,
           coalesce((select array_agg(a.agent_key order by a.agent_key) from org_agents a where a.department=d.dept_key and a.active), '{}') as brain_agents,
           (select count(*) from org_agents a where a.department=d.dept_key and a.active) as brain_count,
           (select count(*) from org_action_executor e where e.department=d.dept_key and e.active) as tool_count
    from org_departments d where d.active
  )
  select jsonb_build_object(
    'vision', (select vision from company_vision where id=1),
    'mission', (select mission from company_vision where id=1),
    'as_of', now(),
    'totals', jsonb_build_object(
      'departments', (select count(*) from depts),
      'brain_agents', (select count(*) from org_agents where active),
      'category_sales_agents', (select count(*) from category_agents),
      'tools_wired', (select count(*) from org_action_executor where active),
      'open_objectives', (select count(*) from department_objective where active and status not in ('done','cancelled','superseded')),
      'open_tasks', (select count(*) from org_tasks where status in ('assigned','proposed','in_progress'))
    ),
    'departments', (select jsonb_agg(jsonb_build_object(
        'dept', dept_key, 'name', name, 'charter', charter, 'north_star', north_star,
        'lead_agent', lead_agent, 'brain_agents', brain_agents,
        'headcount', brain_count + case when dept_key='procurement' then (select count(*) from category_agents) else 0 end,
        'tools_wired', tool_count) order by dept_key) from depts)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_context_slice(p_dept text, p_role_ids text[], p_category text, p_layer text, p_q tsquery, p_budget integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with scoped as (
    select record_id, title, content, version, source_freshness, effective_date, review_after,
           layer, record_type, authority_tier, tsv
      from ops_knowledge
     where runtime_eligible
       and supersession_state = 'current'
       and layer = p_layer
       and (
         (p_layer = 'company_core'        and scope_type = 'company')
      -- THE MERGE ARM. A department that absorbed another owns its predecessor's knowledge; the
      -- 5,775 rows tagged with the 22 absorbed keys are not rewritten, they are scoped in.
      or (p_layer = 'department_shared'   and dept_key = any(public.fn_dept_scope(p_dept)))
      or (p_layer = 'role_specific'       and role_key = any(coalesce(p_role_ids, '{}')))
      or (p_layer = 'category_specialist' and category_key = p_category)
       )
  ), matched as (
    -- THE FILTER THAT WAS DEAD. No `or true`: when a query is supplied it now decides membership.
    select *, ts_rank(tsv, p_q) as rank, 'query'::text as match
      from scoped
     where p_q is not null and tsv @@ p_q
  ), fallback as (
    -- Only consulted when topical retrieval under-delivers. Highest authority first, and every row
    -- carries match='fallback' so the caller can tell the difference.
    select *, 0::real as rank, 'fallback'::text as match
      from scoped
     where p_q is null or (select count(*) from matched) < 3
  ), unioned as (
    select * from matched
    union all
    select * from fallback f where not exists (select 1 from matched m where m.record_id = f.record_id)
  ), deduped as (
    -- Duplicate suppression: the same record can be reachable by more than one scope arm, and the
    -- same TITLE often repeats across package generations. Keep the freshest of each title.
    select distinct on (coalesce(nullif(title,''), record_id))
           record_id, title, content, version, source_freshness, effective_date, review_after,
           layer, record_type, authority_tier, rank, match
      from unioned
     order by coalesce(nullif(title,''), record_id),
              (match = 'query') desc, rank desc,
              coalesce(effective_date, '1900-01-01'::date) desc, record_id
  ), ranked as (
    select *,
           -- freshness is carried, not judged here: review_after in the past is stale and the
           -- caller must be able to see that rather than infer it.
           (review_after is not null and review_after < current_date) as stale,
           sum(least(length(content), 1800)) over (
             order by (match = 'query') desc, rank desc, record_id
             rows between unbounded preceding and current row) as running
      from deduped
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'record_id', record_id, 'title', title, 'layer', layer, 'record_type', record_type,
           'version', version, 'source_freshness', source_freshness,
           'review_after', review_after, 'stale', stale,
           'authority_tier', authority_tier, 'match', match,
           'content', left(content, 1800))
         order by (match = 'query') desc, rank desc, record_id), '[]'::jsonb)
    from ranked
   where running <= greatest(p_budget, 1800);
$function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_require(p_actor_email text, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_class text; v_s record;
begin
  -- AUDIT 8.3 TIER 0. Phase 1 rolled back to observe-only. Still audited, deliberately: during an
  -- incident, the record of what was done under the relaxed control is the most valuable thing here.
  if public.fn_phase1_disarmed() then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_allowed_phase1_disarmed', p_action, true,
            'Phase 1 Control Mode is disarmed - see public.phase1_rollback_log for who disarmed it and why');
    return jsonb_build_object('allowed', true, 'mode', 'disarmed',
      'reason', 'Phase 1 Control Mode is disarmed (rollback tier 0)');
  end if;

  select classification into v_class from public.control_mode_action where action = p_action;

  -- FAIL CLOSED. An action nobody classified is an action nobody thought about, and the cost of
  -- being wrong is asymmetric: refusing a read is an inconvenience, allowing an unreviewed mutation
  -- is the incident. The refusal is audited so the missing classification is discoverable.
  if v_class is null then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_unclassified', p_action, false, 'action is not in control_mode_action');
    return jsonb_build_object(
      'allowed', false, 'mode', 'observe', 'error', 'action_classification_required',
      'message', 'This action has not been classified as read-only or mutating, so it is refused. '
              || 'Classify it in control_mode_action (and in os_api ACTION_CLASS) before using it.');
  end if;

  if v_class = 'read_only' then
    return jsonb_build_object('allowed', true, 'mode', 'observe', 'reason', 'action is registered read-only');
  end if;

  if v_class = 'mode_control' then
    return jsonb_build_object('allowed', true, 'mode', 'observe', 'reason', 'Control Mode plumbing; handled before the gate');
  end if;

  -- FOUNDER-GATED (15 Aug 2026). The founder's own command channel. It writes, so it is audited
  -- exactly like a Control Mode action; it is not gated by Control Mode, because the identity
  -- allow-list in phase_c_founder_identity is the control, and it is a stronger one than a
  -- fifteen-minute session — a stolen admin session is not the founder.
  if v_class = 'founder_gated' then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_allowed_founder_gated', p_action, true,
            'founder-identity gated: writes a work plan only, and fn_founder_command_submit refuses a caller who is not the registered founder');
    return jsonb_build_object('allowed', true, 'mode', 'founder',
      'reason', 'founder-identity gated; Control Mode does not apply to the founder''s own command channel');
  end if;

  select * into v_s from public.control_mode_session
   where actor_email = p_actor_email and closed_at is null and expires_at > now()
   order by opened_at desc limit 1;

  if not found then
    insert into public.control_mode_audit (actor_email, event, action, allowed, reason)
    values (p_actor_email, 'action_denied', p_action, false, 'no active Control Mode session');
    return jsonb_build_object('allowed', false, 'mode', 'observe', 'error', 'control_mode_required',
      'message', 'This changes something, so it needs Control Mode. Open it with a code sent to your phone, and say why.');
  end if;

  update public.control_mode_session set actions_used = actions_used + 1 where id = v_s.id;
  insert into public.control_mode_audit (actor_email, event, action, session_id, allowed, reason)
  values (p_actor_email, 'action_allowed', p_action, v_s.id, true, v_s.reason);

  return jsonb_build_object('allowed', true, 'mode', 'control', 'session_id', v_s.id, 'reason', v_s.reason,
                            'seconds_remaining', greatest(0, extract(epoch from (v_s.expires_at - now()))::int));
end $function$


CREATE OR REPLACE FUNCTION public.fn_control_mode_session_mfa_is_real()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v public.control_mode_challenge%rowtype;
begin
  select * into v from public.control_mode_challenge where id = new.mfa_ref;
  if not found then
    raise exception 'control mode: mfa_ref % is not a challenge', new.mfa_ref using errcode = '23514';
  end if;
  if lower(btrim(v.admin_email)) <> lower(btrim(new.actor_email)) then
    raise exception 'control mode: challenge belongs to %, not %', v.admin_email, new.actor_email using errcode = '23514';
  end if;
  if v.purpose <> 'control_mode' then
    raise exception 'control mode: challenge % was issued for %, not control_mode', v.id, v.purpose using errcode = '23514';
  end if;
  if v.consumed_at is null or coalesce(v.consumed_why,'') <> 'opened' then
    raise exception 'control mode: challenge % was not consumed by an open (consumed_why=%)',
      v.id, coalesce(v.consumed_why,'<null>') using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_cos_work_gate()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_budget int;
  v_used   int;
  v_demand int;
  v_reflect int;
  v_classes jsonb;
begin
  select coalesce((value #>> '{}')::int, 6) into v_budget
    from public.decision_policy where key = 'cos_reflection_tasks_per_day';
  v_budget := coalesce(v_budget, 6);

  select count(*) into v_used
    from public.org_tasks k
   where k.last_run_at >= date_trunc('day', (now() at time zone 'utc')) at time zone 'utc'
     and not public.fn_task_is_demand(k.action_class)
     -- NOT `result->>'mode' <> 'executed_by_invoker'`, which is what this said first and it
     -- over-counted by ten on the first run. That mode is written by fn_action_invoke_collect at
     -- COLLECT time, so a task the invoker dispatched at :45 and has not collected yet still reads
     -- mode NULL and was counted as model work. The ten 'Supply gap' knowledge_acquire tasks in
     -- flight this morning are exactly that: kb_deepen at 0.026 AED a call, charged against a
     -- ceiling meant for a 25,000-token one. The invoker ALWAYS leaves an action_execution row and
     -- the cos_execute model path never does, so the row is the reliable discriminator and it is
     -- true from dispatch, not from collection.
     and not exists (
       select 1 from public.action_execution a
        where (a.request->>'org_task_id') = k.id::text
          and a.created_at >= date_trunc('day', (now() at time zone 'utc')) at time zone 'utc');

  select count(*) filter (where not public.fn_task_is_demand(action_class))
    into v_reflect
    from public.org_tasks where status in ('assigned','in_progress');

  -- The concrete classes cos_execute may select on. PostgREST cannot evaluate the regex above, so
  -- the gate resolves it here against the classes that ACTUALLY have open work and hands back a
  -- list. One source of truth, and the edge function carries no copy of the pattern.
  --
  -- AND IT REFUSES ANY CLASS WIRED TO AN UNSAFE EXECUTOR. This gate moves demand work to the FRONT
  -- of cos_execute's queue, and a cost control must never widen a risk. Found on the first run, and
  -- it was not hypothetical: org_tasks 1360 and 1361 - "Start invites: kitchen-and-bathroom-
  -- suppliers", "Start invites: real-estate-agencies" - are action_class='invite', tier='autonomous',
  -- status='assigned', wired to fn_org_exec_invite with risk_tier='high', advisory_safe=false,
  -- reversible=false. They carry the HIGHEST ids in a 385-row FIFO queue, so today they are
  -- unreachable; promoting 'invite' to the head of the queue would have put a high-risk irreversible
  -- supplier mailing first in line, on the exact day the founder wrote "LAST — supplier invites. DO
  -- NOT ENABLE YET" because the bounce rate is at the platform's own 0.08 brake.
  --
  -- A class is eligible only if NO active executor for it is high-risk, irreversible or not
  -- advisory-safe. This is the same triple fn_org_task_execute_sweep already requires before it will
  -- invoke anything; the two paths now agree instead of disagreeing.
  select coalesce(jsonb_agg(distinct k.action_class), '[]'::jsonb) into v_classes
    from public.org_tasks k
   where k.status in ('assigned','in_progress')
     and k.action_class is not null
     and public.fn_task_is_demand(k.action_class)
     and not exists (
       select 1 from public.org_action_executor e
        where e.action_class = k.action_class and e.active
          and (e.risk_tier <> 'low' or not e.advisory_safe or not e.reversible));

  -- demand_open counts ELIGIBLE demand only — the same set cos_execute can actually select. Counting
  -- every demand-classed row here would report "2 revenue-path tasks still run uncapped" for two
  -- invite tasks the gate has just refused to hand over, and gated=false would then describe a run
  -- that in fact calls no model. The number and the decision have to come from one set.
  select count(*) into v_demand
    from public.org_tasks
   where status in ('assigned','in_progress')
     and action_class is not null
     and v_classes ? action_class;

  return jsonb_build_object(
    'demand_classes',         v_classes,
    'reflection_budget',      v_budget,
    'reflection_used_today',  v_used,
    'reflection_allowed',     v_used < v_budget,
    'demand_open',            v_demand,
    'reflection_open',        v_reflect,
    -- nothing at all to do without a model: the ceiling is spent AND no revenue-path task is waiting
    'gated',                  (v_used >= v_budget and v_demand = 0),
    'reason', case
        when v_used < v_budget then
          'reflection ' || v_used || '/' || v_budget || ' today; working normally'
        when v_demand > 0 then
          'reflection ceiling reached (' || v_used || '/' || v_budget || '); ' || v_demand ||
          ' revenue-path task(s) still run uncapped'
        else
          'reflection ceiling reached (' || v_used || '/' || v_budget || ') and no revenue-path task '
          'is waiting, so no model is called this run'
      end
  );
end
$function$


CREATE OR REPLACE FUNCTION public.fn_cron_liveness()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'cron'
AS $function$
declare v_age numeric; v_last timestamptz;
begin
  select max(start_time) into v_last from cron.job_run_details;
  if v_last is null then
    return jsonb_build_object('healthy', false, 'newest_run_age_min', null, 'note', 'no cron run history');
  end if;
  v_age := extract(epoch from (now() - v_last))/60.0;
  return jsonb_build_object(
    'healthy', v_age <= 20,               -- crons run every few minutes; >20min silence = scheduler down
    'newest_run_age_min', round(v_age,1),
    'checked_at', now());
exception when others then
  return jsonb_build_object('healthy', null, 'error', sqlerrm);
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_decision_support(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- A median over fewer than this many quotes is an anecdote wearing a statistic's clothes.
  MIN_PRICE_N constant int := 5;
  v_recommend jsonb;
  v_chase     jsonb;
  v_market    jsonb;
begin
  if p_customer is null then return jsonb_build_object('error','no_customer'); end if;

  -- ── 1. WHICH QUOTE, AND WHY ────────────────────────────────────────────────────────────────
  -- lead_time is free text ('3 weeks', '10-14 days', 'ASAP'). The first integer is taken and
  -- scaled by the unit word; anything that yields no integer is UNKNOWN and never claimed as fast.
  -- A quote with no parseable lead time cannot win the speed comparison, which is the honest
  -- outcome: we would be guessing on the customer's behalf.
  with q as (
    select i.id inq, i.summary, i.category, q.id qid, q.supplier_id,
           coalesce(q.customer_price, q.quote_amount) price,
           q.lead_time,
           case
             when q.lead_time ~ '\d' then
               (regexp_match(q.lead_time, '(\d+)'))[1]::int
               * case when q.lead_time ~* 'week' then 7 when q.lead_time ~* 'month' then 30 else 1 end
             else null
           end days
    from inquiries i
    join quotes q on q.inquiry_id = i.id
    where i.customer_id = p_customer
      and coalesce(q.status,'') not in ('withdrawn','expired','rejected')
      and coalesce(q.customer_price, q.quote_amount) is not null
  ),
  agg as (
    select inq, min(summary) summary, min(category) category, count(*) n,
           min(price) lo, max(price) hi,
           (array_agg(qid order by price asc))[1]                       cheapest_id,
           (array_agg(price order by price asc))[1]                     cheapest_price,
           (array_agg(price order by price asc))[2]                     next_price,
           (array_agg(qid  order by days asc) filter (where days is not null))[1] fastest_id,
           (array_agg(days order by days asc) filter (where days is not null))[1] fastest_days,
           (array_agg(days order by price asc))[1]                      cheapest_days,
           count(*) filter (where days is not null)                     n_with_days
    from q group by inq
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'inquiry_id', inq, 'summary', summary, 'category', category, 'quotes', n,
           'cheapest_quote_id', cheapest_id, 'cheapest_price', cheapest_price,
           'saving_vs_next', case when next_price is not null then next_price - cheapest_price end,
           'fastest_quote_id', fastest_id, 'fastest_days', fastest_days,
           'same_quote_wins', (fastest_id is not null and fastest_id = cheapest_id),
           -- Only a real trade-off gets a trade-off sentence. Null here means either one quote
           -- won both ways, or too few lead times were stated to compare speed at all.
           'days_sooner', case when fastest_id is distinct from cheapest_id and fastest_days is not null
                                 and cheapest_days is not null then cheapest_days - fastest_days end,
           'spread', hi - lo,
           'lead_times_stated', n_with_days
         ) order by n desc), '[]'::jsonb)
    into v_recommend from agg where n >= 2;

  -- ── 2. WHAT A JOB LIKE THIS NORMALLY COSTS ─────────────────────────────────────────────────
  -- Answered per category the customer actually uses, or - for a customer with no requests yet -
  -- left empty rather than filled with the platform average of nothing.
  -- fn_norm_trades is resolved ONCE PER CATEGORY here, not inside the correlated subqueries below.
  -- Called per row it is re-evaluated against all 15,306 supplier_capabilities rows twice over and
  -- the whole function times out - measured, it did.
  with cats as (
    select distinct i.category, i.emirate, public.fn_norm_trades(i.category) norm from inquiries i
    where i.customer_id = p_customer and i.category is not null
  ),
  m as (
    select c.category, c.emirate,
           s.n price_n, s.median, s.p25, s.p75,
           -- THROUGH THE LEXICON, NOT THE RAW CATEGORY. A probe with category 'marble' counted 0
           -- suppliers against 15,306 capability rows, because no supplier lists a trade called
           -- "marble" - fn_norm_trades('marble') is {flooring}, and that is the vocabulary the
           -- capability rows are written in. Comparing the customer's word directly against the
           -- supplier's word is the same defect that left discover() returning nothing while
           -- route_inquiry worked: one path got the lexicon and its sibling did not.
           (select count(*) from supplier_capabilities sc
             where (sc.trades && c.norm or sc.services && c.norm)
               and (c.emirate is null or sc.coverage_emirates && array[c.emirate])) suppliers_covering,
           (select count(*) from supplier_capabilities sc
             where (sc.trades && c.norm or sc.services && c.norm)
               and (c.emirate is null or sc.coverage_emirates && array[c.emirate])
               and sc.review_status = 'confirmed')                                  suppliers_confirmed,
           (select round(avg(extract(epoch from (q.created_at - i2.created_at))/86400)::numeric, 1)
              from inquiries i2 join quotes q on q.inquiry_id = i2.id
             where i2.category = c.category)                                        avg_days_to_quote
    from cats c left join category_price_stats s on s.category = c.category
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'category', category, 'emirate', emirate,
           -- The price block is present ONLY when it rests on enough quotes to mean something.
           -- Absent is a statement; a median over two quotes is a different and false one.
           'price_known', (coalesce(price_n,0) >= MIN_PRICE_N),
           'price_n', coalesce(price_n,0),
           'median', case when coalesce(price_n,0) >= MIN_PRICE_N then median end,
           'p25',    case when coalesce(price_n,0) >= MIN_PRICE_N then p25 end,
           'p75',    case when coalesce(price_n,0) >= MIN_PRICE_N then p75 end,
           'suppliers_covering', suppliers_covering,
           'suppliers_confirmed', suppliers_confirmed,
           'avg_days_to_quote', avg_days_to_quote
         )), '[]'::jsonb)
    into v_market from m;

  -- ── 3. A REQUEST HAS GONE QUIET ────────────────────────────────────────────────────────────
  -- One state per open request, each with the action that actually moves it. The thresholds are
  -- deliberately generous: telling somebody their request is stalled on day one is noise, and a
  -- portal that cries stalled is one a customer stops reading.
  with open_i as (
    select i.id, i.summary, i.category, i.created_at,
           extract(epoch from (now() - i.created_at))/86400 age_days,
           (select count(*) from inquiry_matches m where m.inquiry_id = i.id) invited,
           (select count(*) from quotes q where q.inquiry_id = i.id
              and coalesce(q.status,'') not in ('withdrawn','expired','rejected')) quotes
    from inquiries i
    where i.customer_id = p_customer
      and coalesce(i.status,'open') not in ('closed','cancelled','completed','archived')
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'inquiry_id', id, 'summary', summary, 'category', category,
           'age_days', round(age_days::numeric,1), 'invited', invited, 'quotes', quotes,
           -- QUOTE-BEARING STATES ARE TESTED FIRST. Written the other way round, a request that had
           -- collected two quotes but no inquiry_matches row reported 'not_yet_sent' - the portal
           -- telling a customer we had not reached any supplier while two of their quotes sat on
           -- the screen. A quote is proof of delivery; the absence of a match row is only proof
           -- that one path recorded it. Caught by an aborted-transaction probe that seeded exactly
           -- that shape; an empty result would have proved nothing.
           'state', case
             when quotes >= 2 and age_days >= 7              then 'undecided'
             when quotes  = 1 and age_days >= 5              then 'only_one'
             when quotes  = 0 and invited = 0 and age_days >= 1 then 'not_yet_sent'
             when quotes  = 0 and age_days >= 3              then 'no_replies'
             else 'healthy' end
         ) order by age_days desc), '[]'::jsonb)
    into v_chase
    from open_i
   where case
           when quotes >= 2 and age_days >= 7 then true
           when quotes  = 1 and age_days >= 5 then true
           when quotes  = 0 and invited = 0 and age_days >= 1 then true
           when quotes  = 0 and age_days >= 3 then true
           else false end;

  return jsonb_build_object(
    'recommend', v_recommend,
    'market',    v_market,
    'chase',     v_chase,
    'min_price_n', MIN_PRICE_N,
    'as_of', now()
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_document_refs()
 RETURNS TABLE(ref_table text, ref_id text, source text, supplier_id bigint, supplier_name text, revealed boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (
    select c.id
      from public.customers c
     where lower(c.email) = lower(nullif(auth.email(), ''))
        or c.id = auth.uid()
     order by (lower(c.email) = lower(nullif(auth.email(), ''))) desc nulls last
     limit 1
  )
  -- the customer's own uploads
  select 'inquiries'::text, i.id::text, 'inquiry'::text, null::bigint, null::text, true
    from public.inquiries i join me on i.customer_id = me.id
  union all
  -- quotation files sent against their RFQs. A draft quote is not shown to the customer by
  -- customer_api, so its attachment is not shown here either.
  select 'quotes'::text, q.id::text, 'quote'::text, q.supplier_id,
         case when t.id is not null then l.company_name end,
         t.id is not null
    from public.quotes q
    join public.inquiries i on i.id = q.inquiry_id
    join me on i.customer_id = me.id
    left join public.leads l on l.id = q.supplier_id
    left join public.transactions t
           on t.quote_id = q.id and t.customer_id = me.id and t.revealed_at is not null
   where coalesce(q.status, '') <> 'draft'
  union all
  -- supplier documents, and ONLY for a supplier this customer has paid to reveal
  select 'leads'::text, l.id::text, 'supplier'::text, l.id, l.company_name, true
    from public.leads l
   where exists (select 1 from public.transactions t join me on t.customer_id = me.id
                  where t.supplier_id = l.id and t.revealed_at is not null);
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_documents(p_q text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_lim integer DEFAULT 50, p_related_refs text[] DEFAULT NULL::text[])
 RETURNS TABLE(id bigint, kind text, file_name text, bucket text, path text, mime text, status text, created_at timestamp with time zone, source text, ref_table text, ref_id text, supplier text, supplier_revealed boolean, expiry_date date, expiry_source text, covers text, covers_source text, summary text, specifications text[], certifications text[], brands text[], extracted_at timestamp with time zone, match_reason text, score real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with q as (
    -- A QUESTION IS NOT A SEARCH STRING. plainto_tsquery ANDs every content word, so the spec's own
    -- example — "Find warranty documents for HVAC" — becomes find & warranti & document & hvac and
    -- matches nothing a human would call a warranty document. Measured on staging: 0 hits against a
    -- fixture whose filename is literally hvac-warranty-agreement.pdf. The lexemes are therefore
    -- OR-ed, and ts_rank does the discriminating — a document carrying two of the four terms
    -- outranks one carrying a single term, which is what "ask in natural language" has to mean.
    select nullif(btrim(coalesce(p_q, '')), '') as qtext,
           (select nullif(string_agg('''' || replace(l.lexeme, '''', '''''') || '''', ' | '), '')::tsquery
              from unnest(to_tsvector('english', coalesce(p_q, ''))) l) as tsq,
           coalesce(p_related_refs, '{}'::text[]) as rel
  ),
  base as (
    select d.id, d.kind, d.file_name, d.bucket, d.path, d.mime, d.status, d.created_at,
           d.processed_at, r.source, d.ref_table, d.ref_id,
           case when r.revealed then r.supplier_name end as supplier,
           coalesce(r.revealed, false) as supplier_revealed,
           l.license_expiry, l.insurance_expiry, l.iso_expiry, l.manufacturer_auth_expiry,
           l.license_activity, l.iso_certifications,
           case when jsonb_typeof(d.extracted) = 'object' then d.extracted else '{}'::jsonb end as ex
      from public.documents d
      join public.fn_customer_document_refs() r
        on r.ref_table = d.ref_table and r.ref_id = d.ref_id
      left join public.leads l on r.revealed and l.id = r.supplier_id
  ),
  arr as (
    select b.*,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.ex->'specifications') = 'array' then b.ex->'specifications'
                   else '[]'::jsonb end) x) as specs,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.ex->'certifications') = 'array' then b.ex->'certifications'
                   else '[]'::jsonb end) x) as certs,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.ex->'brands') = 'array' then b.ex->'brands'
                   else '[]'::jsonb end) x) as brnds,
           (select coalesce(array_agg(x), '{}'::text[]) from jsonb_array_elements_text(
              case when jsonb_typeof(b.iso_certifications) = 'array' then b.iso_certifications
                   else '[]'::jsonb end) x) as iso_certs
      from base b
  ),
  shaped as (
    select a.id, a.kind, a.file_name, a.bucket, a.path, a.mime, a.status, a.created_at,
           a.source, a.ref_table, a.ref_id, a.supplier, a.supplier_revealed,
           -- EXPIRY: only from a field that means expiry.
           coalesce(
             case when a.ex->>'expiry_date' ~ '^\d{4}-\d{2}-\d{2}$' then (a.ex->>'expiry_date')::date end,
             case when a.ex->>'valid_until' ~ '^\d{4}-\d{2}-\d{2}$' then (a.ex->>'valid_until')::date end,
             case when a.kind in ('licence', 'license') then a.license_expiry end,
             case when a.kind = 'insurance' then a.insurance_expiry end,
             case when a.kind in ('iso', 'certificate') then a.iso_expiry end,
             case when a.kind = 'manufacturer' then a.manufacturer_auth_expiry end
           ) as expiry_date,
           case
             when a.ex->>'expiry_date' ~ '^\d{4}-\d{2}-\d{2}$' then 'extracted.expiry_date'
             when a.ex->>'valid_until' ~ '^\d{4}-\d{2}-\d{2}$' then 'extracted.valid_until'
             when a.kind in ('licence', 'license') and a.license_expiry is not null then 'leads.license_expiry'
             when a.kind = 'insurance' and a.insurance_expiry is not null then 'leads.insurance_expiry'
             when a.kind in ('iso', 'certificate') and a.iso_expiry is not null then 'leads.iso_expiry'
             when a.kind = 'manufacturer' and a.manufacturer_auth_expiry is not null then 'leads.manufacturer_auth_expiry'
           end as expiry_source,
           -- COVERAGE: what the document covers, from the extractor's own key first.
           coalesce(
             nullif(btrim(coalesce(a.ex->>'covers', '')), ''),
             nullif(btrim(coalesce(a.ex->>'coverage', '')), ''),
             case when a.kind in ('licence', 'license') then nullif(btrim(coalesce(a.license_activity, '')), '') end,
             case when a.kind in ('iso', 'certificate') then nullif(array_to_string(a.iso_certs, ', '), '') end,
             nullif(array_to_string(a.certs, ', '), '')
           ) as covers,
           case
             when nullif(btrim(coalesce(a.ex->>'covers', '')), '') is not null then 'extracted.covers'
             when nullif(btrim(coalesce(a.ex->>'coverage', '')), '') is not null then 'extracted.coverage'
             when a.kind in ('licence', 'license')
              and nullif(btrim(coalesce(a.license_activity, '')), '') is not null then 'leads.license_activity'
             when a.kind in ('iso', 'certificate')
              and nullif(array_to_string(a.iso_certs, ', '), '') is not null then 'leads.iso_certifications'
             when nullif(array_to_string(a.certs, ', '), '') is not null then 'extracted.certifications'
           end as covers_source,
           left(nullif(btrim(coalesce(a.ex->>'text', '')), ''), 600) as summary,
           a.specs, a.certs, a.brnds, a.processed_at,
           -- THE HAYSTACK IS THE WHOLE EXTRACTION. jsonb_to_tsvector with a ["string"] filter walks
           -- every string value in the jsonb, so doc_extract's text/specifications/certifications/
           -- brands AND license_extract's issuer/covers/reference are all searchable without this
           -- function having to know which extractor wrote the row. A hand-picked key list is how
           -- `covers: "Full system"` ended up unsearchable in the first version.
           -- The filename is de-punctuated first: the parser lexes hvac-warranty-agreement.pdf as a
           -- single `file` token, so "warranty" did not match the file actually called that.
           to_tsvector('english',
             regexp_replace(coalesce(a.file_name, ''), '[^a-zA-Z0-9]+', ' ', 'g') || ' ' ||
             coalesce(a.kind, '') || ' ' || coalesce(a.supplier, '') || ' ' ||
             coalesce(a.license_activity, ''))
           || jsonb_to_tsvector('english', a.ex, '["string"]') as hay
      from arr a
  ),
  ranked as (
    -- match_reason and the rank are computed here, and the final select orders by THIS alias.
    -- RETURNS TABLE makes `score` and `created_at` OUT parameters, and an unqualified ORDER BY
    -- against a name that is also a parameter is how a SQL function starts erroring at call time.
    select s.*,
           case when q.qtext is null then 'all'
                when s.hay @@ q.tsq then 'text'
                else 'related_request' end as mreason,
           case when q.qtext is null then 0::real else ts_rank(s.hay, q.tsq) end as rank_score
      from shaped s, q
     where (p_kind is null or s.kind = lower(btrim(p_kind)))
       and (q.qtext is null
            or s.hay @@ q.tsq
            or (s.ref_table || ':' || s.ref_id) = any (q.rel))
  )
  select z.id, z.kind, z.file_name, z.bucket, z.path, z.mime, z.status, z.created_at,
         z.source, z.ref_table, z.ref_id, z.supplier, z.supplier_revealed,
         z.expiry_date, z.expiry_source, z.covers, z.covers_source,
         z.summary, z.specs, z.certs, z.brnds, z.processed_at, z.mreason, z.rank_score
    from ranked z
   order by z.rank_score desc, z.created_at desc nulls last
   limit greatest(1, coalesce(p_lim, 50));
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_forecast(p_customer uuid, p_horizon_days integer DEFAULT 365)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_rfqs int; v_months int; v_first timestamptz; v_last timestamptz;
  v_spend numeric; v_span_days numeric;
  v_series jsonb; v_by_cat jsonb; v_predictions jsonb;
  v_sufficient boolean; v_reason text;
  v_proj_rfqs numeric; v_proj_spend numeric;
begin
  select count(*), min(i.created_at), max(i.created_at),
         count(distinct date_trunc('month', i.created_at))
    into v_rfqs, v_first, v_last, v_months
    from inquiries i
   where i.customer_id = p_customer and i.parent_inquiry_id is null;

  select coalesce(sum(coalesce(t.quote_amount, 0)), 0) into v_spend
    from transactions t
   where t.customer_id = p_customer and coalesce(t.refund_status, '') <> 'approved';

  -- No history at all. Say so; do not project.
  if coalesce(v_rfqs, 0) = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'as_of', now(), 'horizon_days', p_horizon_days,
      'basis', 'no_history', 'sufficient_data', false,
      'empty_reason', 'No requests recorded on this account yet. This forecast is derived from your own past RFQs and orders, so there is nothing to project from until you post your first request.',
      'observed', jsonb_build_object('rfqs', 0, 'months_active', 0, 'spend_aed', 0,
                                     'first_rfq', null, 'last_rfq', null),
      'series', '[]'::jsonb,
      'next_year', jsonb_build_object('horizon_days', p_horizon_days, 'projected_rfqs', null,
                                      'projected_spend_aed', null, 'by_category', '[]'::jsonb),
      'predictions', '[]'::jsonb);
  end if;

  -- The observed window only. The series starts at the customer's FIRST request, never at a padded
  -- twelve months back, so a three-month-old account shows three points and not nine empty ones.
  with months as (
    select generate_series(date_trunc('month', v_first), date_trunc('month', now()), interval '1 month') m
  ), actual as (
    select date_trunc('month', i.created_at) m, count(*) c,
           round(coalesce(sum(i.expected_value), 0), 0) v
      from inquiries i
     where i.customer_id = p_customer and i.parent_inquiry_id is null
     group by 1
  )
  select jsonb_agg(jsonb_build_object('month', to_char(months.m, 'Mon YY'),
                                      'rfqs', coalesce(actual.c, 0),
                                      'value_aed', coalesce(actual.v, 0)) order by months.m)
    into v_series
    from months left join actual on actual.m = months.m;

  -- Two months of activity and three requests is the floor for a run-rate projection. Below it the
  -- figures are null and the reason is printed rather than a straight line drawn through one point.
  v_span_days  := greatest(30, extract(epoch from (now() - v_first)) / 86400.0);
  v_sufficient := v_rfqs >= 3 and v_months >= 2;
  if v_sufficient then
    v_proj_rfqs  := round((v_rfqs::numeric / v_span_days) * p_horizon_days, 1);
    v_proj_spend := round((coalesce(v_spend, 0) / v_span_days) * p_horizon_days, 0);
    v_reason     := null;
  else
    v_proj_rfqs  := null;
    v_proj_spend := null;
    v_reason     := format('Only %s request(s) across %s active month(s) so far. A run-rate projection needs at least 3 requests spanning 2 months, so the next-year figures are withheld rather than extrapolated from a single point.',
                           v_rfqs, v_months);
  end if;

  -- Category mix, projected forward at the same run rate. Shares come from the customer's own
  -- requests, so a customer who only ever bought joinery is not shown an HVAC line.
  with cat as (
    select coalesce(i.category, 'uncategorised') c, count(*) n,
           round(coalesce(sum(i.expected_value), 0), 0) v
      from inquiries i
     where i.customer_id = p_customer and i.parent_inquiry_id is null
     group by 1
  )
  select jsonb_agg(jsonb_build_object(
           'category', c,
           'observed_rfqs', n,
           'observed_value_aed', v,
           'share_pct', round(100.0 * n / nullif(v_rfqs, 0), 1),
           'projected_rfqs', case when v_sufficient
                                  then round(v_proj_rfqs * n / nullif(v_rfqs, 0), 1) end,
           'projected_spend_aed', case when v_sufficient
                                  then round(v_proj_spend * n / nullif(v_rfqs, 0), 0) end
         ) order by n desc, c)
    into v_by_cat from cat;

  -- ── §20: what this customer will likely need next, and by when ────────────────────────────────
  -- Derived, never guessed: for each of the customer's OPEN projects that has a target open date,
  -- the categories they have procured on their other projects and have not yet raised here. The
  -- horizon is that project's own deadline minus the lead time this customer has actually observed
  -- in that category (median days between raising a request and the project's target open date).
  with own as (
    select i.project_id, coalesce(i.category, 'uncategorised') c, i.created_at, p.target_open_date
      from inquiries i join projects p on p.id = i.project_id
     where i.customer_id = p_customer and i.project_id is not null
  ), lead_time as (
    select c, percentile_cont(0.5) within group (
             order by (target_open_date - created_at::date)) med_days
      from own where target_open_date is not null
     group by c
  ), history as (
    select c, count(distinct project_id) projects_used, max(created_at) last_used
      from own group by c
  ), open_projects as (
    select p.id, p.name, p.target_open_date
      from projects p
     where p.customer_id = p_customer
       and coalesce(p.status, 'active') not in ('completed', 'archived', 'cancelled')
       and p.target_open_date is not null
  ), gaps as (
    select op.id project_id, op.name project_name, op.target_open_date, h.c category,
           h.projects_used, lt.med_days,
           greatest(0, (op.target_open_date - current_date)
                       - coalesce(round(lt.med_days)::int, 0)) within_days
      from open_projects op
      cross join history h
      left join lead_time lt on lt.c = h.c
     where not exists (select 1 from inquiries i2
                        where i2.project_id = op.id
                          and coalesce(i2.category, 'uncategorised') = h.c)
  )
  select jsonb_agg(jsonb_build_object(
           'project_id', project_id,
           'project_name', project_name,
           'category', category,
           'target_open_date', target_open_date,
           'within_days', within_days,
           'expected_by', current_date + within_days,
           'confidence', case when projects_used >= 2 and med_days is not null then 'high'
                              when projects_used >= 1 and med_days is not null then 'medium'
                              else 'low' end,
           'reason', format('You have procured %s on %s of your other project(s)%s, and %s has no %s request yet.',
                            category, projects_used,
                            case when med_days is null then ''
                                 else format(', typically %s days before the target open date', round(med_days)) end,
                            project_name, category),
           'recommended_action', case
             when within_days = 0 then format('Post the %s RFQ now — the lead time you have historically needed has already started.', category)
             else format('Contact suppliers and post the %s RFQ within %s day(s) to keep %s on its target open date of %s.',
                         category, within_days, project_name, target_open_date) end
         ) order by within_days, category)
    into v_predictions from gaps;

  return jsonb_build_object(
    'customer_id', p_customer, 'as_of', now(), 'horizon_days', p_horizon_days,
    'basis', 'history', 'sufficient_data', v_sufficient, 'empty_reason', v_reason,
    'observed', jsonb_build_object('rfqs', v_rfqs, 'months_active', v_months,
                                   'spend_aed', round(coalesce(v_spend, 0), 0),
                                   'first_rfq', v_first, 'last_rfq', v_last),
    'series', coalesce(v_series, '[]'::jsonb),
    'next_year', jsonb_build_object('horizon_days', p_horizon_days,
                                    'projected_rfqs', v_proj_rfqs,
                                    'projected_spend_aed', v_proj_spend,
                                    'by_category', coalesce(v_by_cat, '[]'::jsonb)),
    'predictions', coalesce(v_predictions, '[]'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_mandatory_check(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; miss text[] := '{}'; have text[] := '{}';
begin
  select * into c from public.customers where id = p_customer_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'No such customer.');
  end if;

  if coalesce(btrim(c.full_name),'') = '' then miss := array_append(miss,'Name');
  else have := array_append(have,'Name'); end if;

  -- The founder said "mobile" for a customer without naming a country, so this checks that a number
  -- exists and has been verified, rather than imposing a UAE prefix he did not ask for. A buyer may
  -- reasonably be abroad; a supplier holding a UAE trade licence may not.
  if coalesce(btrim(c.phone),'') = '' then miss := array_append(miss,'Mobile number');
  elsif not coalesce(c.phone_verified,false) then miss := array_append(miss,'Mobile number (not yet verified)');
  else have := array_append(have,'Mobile number'); end if;

  if coalesce(btrim(c.email),'') = '' then miss := array_append(miss,'Email address');
  elsif not coalesce(c.email_verified,false) then miss := array_append(miss,'Email address (not yet verified)');
  else have := array_append(have,'Email address'); end if;

  if coalesce(btrim(c.signed_terms_path),'') = '' and c.tos_accepted_at is null
  then miss := array_append(miss,'Signed terms and conditions');
  else have := array_append(have,'Signed terms and conditions'); end if;

  return jsonb_build_object(
    'ok', true, 'party_kind','customer', 'id', p_customer_id::text, 'name', c.full_name,
    'complete', coalesce(array_length(miss,1),0) = 0,
    'have', to_jsonb(have), 'missing', to_jsonb(miss),
    'missing_count', coalesce(array_length(miss,1),0),
    'mandatory_total', 4
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_orders(p_customer uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', o.id, 'po_no', o.po_no, 'status', o.status,
      'order_date', o.order_date, 'expected_date', o.expected_date,
      'currency', o.currency, 'subtotal', o.subtotal, 'memo', o.memo,
      'inquiry_id', o.inquiry_id, 'quote_id', o.quote_id, 'project_id', o.project_id,
      'approved_at', o.approved_at,
      'lines', coalesce((select jsonb_agg(jsonb_build_object(
                  'line_no', l.line_no, 'description', l.description, 'qty', l.qty,
                  'unit_price', l.unit_price, 'qty_received', l.qty_received) order by l.line_no)
                from public.po_lines l where l.po_id = o.id), '[]'::jsonb))
      order by o.order_date desc, o.id desc), '[]'::jsonb)
    from public.po_orders o
   where o.customer_id = p_customer;
$function$


CREATE OR REPLACE FUNCTION public.fn_customer_preference_learn(p_customer_id uuid, p_stated jsonb DEFAULT '{}'::jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_consent timestamptz;
  v_existing jsonb;
  v_inferred jsonb;
begin
  if p_customer_id is null then return 0; end if;

  -- CONSENT IS THE GATE, and it reuses the consent the customer already gave. No new column, no
  -- new UI, no second consent vocabulary.
  --
  -- WITHDRAWAL DELETES. The fixture caught this: clearing customer_preference.consented_at is not
  -- withdrawing consent, because consent lives on customers.tos_accepted_at and the next inquiry
  -- simply re-learned and restored the copy. So the absence of consent actively REMOVES the
  -- profile rather than merely declining to refresh it — row absent is indistinguishable from
  -- never consented, which is the property the readers rely on.
  select c.tos_accepted_at into v_consent from customers c where c.id = p_customer_id;
  if v_consent is null then
    delete from customer_preference where customer_id = p_customer_id;
    return 0;
  end if;

  select p.preferences into v_existing from customer_preference p where p.customer_id = p_customer_id;

  -- The same aggregates fn_ws_customer_360 computes live today, persisted instead of recomputed.
  select jsonb_build_object(
           'categories', coalesce(jsonb_agg(distinct i.category) filter (where i.category is not null), '[]'::jsonb),
           'emirates',   coalesce(jsonb_agg(distinct i.emirate)  filter (where i.emirate  is not null), '[]'::jsonb),
           'scope_type', mode() within group (order by i.scope_type),
           'budget_aed_avg', round(avg(nullif(i.expected_value, 0))::numeric, 2),
           'rfqs_seen', count(*))
    into v_inferred
    from inquiries i where i.customer_id = p_customer_id;

  insert into customer_preference (customer_id, preferences, consented_at, updated_at)
  values (p_customer_id,
          jsonb_build_object(
            -- stated is merged, never replaced: an inference must not clear a typed choice.
            'stated',   coalesce(v_existing->'stated', '{}'::jsonb) || coalesce(p_stated, '{}'::jsonb),
            'inferred', coalesce(v_inferred, '{}'::jsonb),
            'source',   'fn_customer_preference_learn'),
          v_consent, now())
  on conflict (customer_id) do update
    set preferences = excluded.preferences,
        consented_at = excluded.consented_at,
        updated_at   = now();
  return 1;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_savings(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_min_sample int;
  v_rows int;
  v_by_cat jsonb;
  v_spread numeric; v_bench numeric;
begin
  select coalesce((p.policy ->> 'min_sample')::int, 4) into v_min_sample
    from supplier_negotiation_policy p where p.scope = 'default';
  v_min_sample := coalesce(v_min_sample, 4);

  select count(*) into v_rows
    from quotes q join inquiries i on i.id = q.inquiry_id
   where i.customer_id = p_customer and coalesce(q.status, '') <> 'draft'
     and q.quote_amount is not null and q.quote_amount > 0;

  if v_rows = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'as_of', now(), 'min_sample', v_min_sample,
      'by_category', '[]'::jsonb,
      'total_spread_saving_aed', null, 'total_benchmark_saving_aed', null,
      'quotes_considered', 0,
      'empty_reason', 'No quotes on your requests yet. Potential savings are measured from the quotes you actually hold — the spread between them, and each one against the market median for its category — so there is nothing to compute until suppliers respond.');
  end if;

  with live as (
    select q.id, q.inquiry_id, q.quote_amount, coalesce(i.category, 'uncategorised') category
      from quotes q join inquiries i on i.id = q.inquiry_id
     where i.customer_id = p_customer and coalesce(q.status, '') <> 'draft'
       and q.quote_amount is not null and q.quote_amount > 0
       and coalesce(i.status, '') not in ('completed', 'cancelled', 'closed')
  ), per_rfq as (
    select inquiry_id, category, count(*) n_quotes,
           max(quote_amount) - min(quote_amount) spread, min(quote_amount) cheapest
      from live group by inquiry_id, category
  ), bench as (
    select l.category, l.inquiry_id, min(l.quote_amount) cheapest, s.median, s.n
      from live l left join category_price_stats s on s.category = l.category
     group by l.category, l.inquiry_id, s.median, s.n
  )
  select jsonb_agg(x order by x ->> 'category'), sum((x ->> 'spread_saving_aed')::numeric),
         sum(coalesce((x ->> 'benchmark_saving_aed')::numeric, 0))
    into v_by_cat, v_spread, v_bench
    from (
      select jsonb_build_object(
               'category', p.category,
               'rfqs', count(distinct p.inquiry_id),
               'quotes', sum(p.n_quotes),
               'spread_saving_aed', round(sum(case when p.n_quotes >= 2 then p.spread else 0 end), 0),
               'market_median', max(b.median),
               'market_sample_n', max(b.n),
               'benchmark_saving_aed', case when max(b.n) >= v_min_sample
                 then round(greatest(0, sum(b.cheapest) - sum(b.median)), 0) end,
               'benchmark_basis', case when coalesce(max(b.n), 0) >= v_min_sample
                 then format('cheapest quote(s) held against a market median over %s comparable quote(s)', max(b.n))
                 else format('no market benchmark: only %s comparable quote(s) recorded in this category, and %s are needed',
                             coalesce(max(b.n), 0), v_min_sample) end
             ) x
        from per_rfq p join bench b on b.inquiry_id = p.inquiry_id and b.category = p.category
       group by p.category
    ) z;

  return jsonb_build_object(
    'customer_id', p_customer, 'as_of', now(), 'min_sample', v_min_sample,
    'by_category', coalesce(v_by_cat, '[]'::jsonb),
    'total_spread_saving_aed', v_spread,
    'total_benchmark_saving_aed', case when v_bench > 0 then v_bench end,
    'quotes_considered', v_rows,
    'empty_reason', case when coalesce(v_bench, 0) = 0
      then format('No market benchmark saving is shown: no category on your open requests yet has the %s comparable quotes this house policy requires before it will quote a market median.', v_min_sample) end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_stats(p_customer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb; v_inq int; v_open int; v_quotes int; v_deals int; v_spend numeric; v_list jsonb; v_hist jsonb;
begin
  select count(*) into v_inq from inquiries where customer_id=p_customer and parent_inquiry_id is null;
  select count(*) into v_open from inquiries where customer_id=p_customer and parent_inquiry_id is null and coalesce(status,'') not in ('completed','closed','cancelled','split');
  select count(*) into v_quotes from quotes q where q.status <> 'draft' and q.inquiry_id in (select id from inquiries where customer_id=p_customer);
  select count(*) into v_deals from transactions where customer_id=p_customer;
  select coalesce(sum(coalesce(reveal_fee,0)+coalesce(app_fee,0)),0) into v_spend from transactions where customer_id=p_customer and coalesce(refund_status,'')<>'approved';
  select jsonb_agg(x order by (x->>'created_at') desc) into v_list from (
    select jsonb_build_object(
      'id', i.id, 'category', i.category, 'emirate', i.emirate, 'status', i.status,
      'created_at', i.created_at, 'pipeline_stage', i.pipeline_stage, 'outcome', i.outcome,
      'has_drawing', (i.drawing_file_path is not null), 'boq_confidence', i.boq_confidence,
      'quotes_count', (select count(*) from quotes q where q.inquiry_id=i.id and q.status <> 'draft'),
      'minutes_since', round(extract(epoch from (now()-i.created_at))/60.0)::int,
      'editable', (i.status='sent') and (now()-i.created_at) < interval '60 minutes',
      'edit_minutes_left', greatest(0, 60 - round(extract(epoch from (now()-i.created_at))/60.0)::int)
    ) x from inquiries i where i.customer_id=p_customer and i.parent_inquiry_id is null
  ) t;
  with months as (select date_trunc('month',(now()-(n||' month')::interval)) m from generate_series(0,11) n),
  ib as (select date_trunc('month',created_at) m, count(*) c from inquiries where customer_id=p_customer and parent_inquiry_id is null group by 1)
  select jsonb_agg(jsonb_build_object('month',to_char(months.m,'Mon YY'),'inquiries',coalesce(ib.c,0)) order by months.m)
    into v_hist from months left join ib on ib.m=months.m;
  v := jsonb_build_object(
    'customer_id', p_customer,'inquiries_total', v_inq,'open_inquiries', v_open,
    'quotes_received', v_quotes,'avg_quotes_per_inquiry', round(v_quotes::numeric/nullif(v_inq,0),1),
    'deals', v_deals,'total_spend', v_spend,
    'inquiries', coalesce(v_list,'[]'::jsonb),'history_12m', v_hist);
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_supplier_score(p_customer uuid, p_supplier bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sent int; v_quoted int; v_awarded int; v_reveals int; v_acked int; v_refunds int;
  v_avg_quote numeric; v_resp_hours numeric; v_last timestamptz;
  v_rating numeric; v_dims jsonb; v_reviews int;
  v_responsiveness numeric; v_award_rate numeric; v_delivery numeric;
  v_quality numeric; v_refund_free numeric;
  v_parts jsonb := '[]'::jsonb; v_sum numeric := 0; v_wt numeric := 0;
  v_global jsonb; v_supplier text;
  -- each component contributes only when the customer's history actually carries it, so a single
  -- review does not become the whole verdict and a missing dimension does not read as a zero
  v_method text := 'weighted mean over the components with data';
begin
  select l.company_name into v_supplier from leads l where l.id = p_supplier;
  if v_supplier is null then
    return jsonb_build_object('error', 'unknown_supplier', 'supplier_id', p_supplier);
  end if;

  select count(*) into v_sent
    from inquiry_matches m join inquiries i on i.id = m.inquiry_id
   where m.supplier_id = p_supplier and i.customer_id = p_customer;

  select count(*), round(avg(q.quote_amount), 0),
         round(avg(extract(epoch from (q.created_at - i.created_at)) / 3600.0)::numeric, 1),
         max(q.created_at)
    into v_quoted, v_avg_quote, v_resp_hours, v_last
    from quotes q join inquiries i on i.id = q.inquiry_id
   where q.supplier_id = p_supplier and i.customer_id = p_customer
     and coalesce(q.status, '') <> 'draft';

  select count(*) into v_awarded
    from inquiries i
   where i.customer_id = p_customer and i.hired_supplier_id = p_supplier;

  select count(*),
         count(*) filter (where t.supplier_ack_at is not null),
         count(*) filter (where coalesce(t.refund_status, '') = 'approved')
    into v_reveals, v_acked, v_refunds
    from transactions t
   where t.customer_id = p_customer and t.supplier_id = p_supplier;

  select count(*), round(avg(r.rating)::numeric, 2),
         jsonb_build_object(
           'communication', round(avg(r.r_communication)::numeric, 2),
           'quality', round(avg(r.r_quality)::numeric, 2),
           'punctuality', round(avg(r.r_punctuality)::numeric, 2),
           'documentation', round(avg(r.r_documentation)::numeric, 2),
           'after_sales', round(avg(r.r_after_sales)::numeric, 2),
           'compliance', round(avg(r.r_compliance)::numeric, 2))
    into v_reviews, v_rating, v_dims
    from reviews r
   where r.customer_id = p_customer and r.supplier_id = p_supplier;

  select jsonb_build_object('reliability', s.reliability, 'quality_rating', s.quality_rating,
                            'price_index', s.price_index, 'response_rate', s.response_rate,
                            'avg_response_hours', s.avg_response_hours,
                            'quotes_submitted', s.quotes_submitted, 'quotes_won', s.quotes_won,
                            'computed_at', s.computed_at)
    into v_global from supplier_score s where s.lead_id = p_supplier;

  -- Nothing shared: report the global figures and refuse to invent a relationship.
  if coalesce(v_sent, 0) = 0 and coalesce(v_quoted, 0) = 0 and coalesce(v_reveals, 0) = 0
     and coalesce(v_reviews, 0) = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'supplier_id', p_supplier, 'supplier_name', v_supplier,
      'basis', 'no_shared_history', 'relationship_score', null,
      'empty_reason', format('You have not worked with %s yet. A relationship score is built from your own RFQs, quotes, orders and reviews with a supplier, so there is nothing to score until the first one.', v_supplier),
      'history', jsonb_build_object('rfqs_sent', 0, 'quotes_received', 0, 'orders', 0,
                                    'reveals', 0, 'reviews', 0),
      'delivery_pct', null, 'quality_pct', null, 'win_rate_pct', null,
      'avg_response_hours', null, 'avg_quote_aed', null, 'last_interaction_at', null,
      'your_rating', null, 'your_rating_dimensions', null,
      'components', '[]'::jsonb,
      'platform_wide', coalesce(v_global, 'null'::jsonb));
  end if;

  if v_sent > 0 then
    v_responsiveness := round(least(100, 100.0 * v_quoted / v_sent), 1);
    v_parts := v_parts || jsonb_build_object('name', 'responsiveness', 'value', v_responsiveness,
      'weight', 30, 'basis', format('%s of %s RFQs you sent came back with a quote', v_quoted, v_sent));
    v_sum := v_sum + v_responsiveness * 30; v_wt := v_wt + 30;
  end if;

  if v_quoted > 0 then
    v_award_rate := round(100.0 * v_awarded / v_quoted, 1);
    v_parts := v_parts || jsonb_build_object('name', 'award_rate', 'value', v_award_rate,
      'weight', 15, 'basis', format('you awarded %s of their %s quote(s)', v_awarded, v_quoted));
    v_sum := v_sum + v_award_rate * 15; v_wt := v_wt + 15;
  end if;

  if v_reveals > 0 then
    v_delivery      := round(100.0 * v_acked / v_reveals, 1);
    v_refund_free   := round(100.0 * (v_reveals - v_refunds) / v_reveals, 1);
    v_parts := v_parts || jsonb_build_object('name', 'delivery', 'value', v_delivery,
      'weight', 30, 'basis', format('%s of %s reveal(s) were acknowledged by the supplier', v_acked, v_reveals));
    v_parts := v_parts || jsonb_build_object('name', 'no_refund', 'value', v_refund_free,
      'weight', 10, 'basis', format('%s of %s reveal(s) ended in a refund', v_refunds, v_reveals));
    v_sum := v_sum + v_delivery * 30 + v_refund_free * 10; v_wt := v_wt + 40;
  end if;

  if v_reviews > 0 and v_rating is not null then
    v_quality := round(100.0 * v_rating / 5.0, 1);
    v_parts := v_parts || jsonb_build_object('name', 'your_rating', 'value', v_quality,
      'weight', 25, 'basis', format('your %s review(s) average %s out of 5', v_reviews, v_rating));
    v_sum := v_sum + v_quality * 25; v_wt := v_wt + 25;
  end if;

  return jsonb_build_object(
    'customer_id', p_customer, 'supplier_id', p_supplier, 'supplier_name', v_supplier,
    'basis', 'shared_history', 'empty_reason', null,
    'relationship_score', case when v_wt > 0 then round(v_sum / v_wt, 0)::int end,
    'score_method', v_method,
    'history', jsonb_build_object('rfqs_sent', v_sent, 'quotes_received', v_quoted,
                                  'orders', v_awarded, 'reveals', v_reveals, 'reviews', v_reviews),
    'delivery_pct', v_delivery,
    'quality_pct', v_quality,
    'win_rate_pct', v_award_rate,
    'avg_response_hours', v_resp_hours,
    'avg_quote_aed', v_avg_quote,
    'last_interaction_at', v_last,
    'your_rating', v_rating,
    'your_rating_dimensions', case when v_reviews > 0 then v_dims end,
    'components', v_parts,
    'platform_wide', coalesce(v_global, 'null'::jsonb));
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_terms_accept(p_customer_id uuid, p_ip text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c            public.customers%rowtype;
  v_slug       text;
  v_version    text;
  v_digest     text;
  v_bkey       text;
  v_owner      text := p_customer_id::text;
  v_existing   text;
  v_write      jsonb;
  v_acc_ref    text;
  v_run        bigint;
  v_step_run   bigint;
  v_actor      text;
  v_disp       jsonb := null;
  v_effect     bigint := null;
begin
  select * into c from public.customers where id = p_customer_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no such customer ' || p_customer_id);
  end if;

  -- The document this acceptance object accepts, and its published version + digest (never trusted
  -- from the caller). This is the same relation and pair BR-025 judges against.
  select a.document_slug into v_slug
    from public.phase_d_acceptance_document a where a.object_id = 'customer_terms_acceptance';
  v_slug := coalesce(v_slug, 'customer-terms');
  -- The currently published document: newest effective_date wins (version is a label, not an order).
  select d.version, encode(sha256(convert_to(coalesce(d.body_html,''),'UTF8')),'hex')
    into v_version, v_digest
    from public.legal_documents d where d.slug = v_slug
    order by d.effective_date desc nulls last, d.version desc limit 1;
  if v_version is null then
    return jsonb_build_object('ok', false, 'reason', 'no published document for slug ' || v_slug);
  end if;

  -- Keep the product's own fast-path columns in step, idempotently.
  update public.customers
     set tos_accepted_at = coalesce(tos_accepted_at, now()),
         tos_version = v_version,
         tos_ip = coalesce(nullif(btrim(p_ip),''), tos_ip)
   where id = p_customer_id;

  -- One acceptance record per (customer, version). APPEND_ONLY refuses a second write to a key that
  -- already holds a record, so reuse the current one rather than let that surface as an error.
  v_bkey := v_owner || ':' || v_version;
  select o.business_key into v_existing
    from public.phase_d_object_record o
   where o.object_id = 'customer_terms_acceptance' and o.business_key = v_bkey
     and o.superseded_by is null
   order by o.record_id desc limit 1;

  if v_existing is not null then
    v_acc_ref := v_existing;
  else
    v_write := public.fn_phase_d_object_write(jsonb_build_object(
      'object_id',   'customer_terms_acceptance',
      'business_key', v_bkey,
      'owner_ref',    v_owner,
      'state',        'accepted',
      'created_by',   'customer_support',
      'payload', jsonb_build_object(
        'terms_version', v_version,
        'terms_hash',    v_digest,
        'accepted_at',   to_char(now() at time zone 'utc','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
        'ip',            nullif(btrim(p_ip),''),
        'document_slug', v_slug,
        'source',        'kyc.accept_terms')));
    v_acc_ref := coalesce(v_write->>'business_key', v_bkey);
  end if;

  -- Re-dispatch the open W04-S01 for this customer through the canonical door. The kernel opened it
  -- on registration; nothing re-entered it after the refusal. With the acceptance now on record,
  -- terms_version, terms_hash and acceptance_ref all resolve and the step can execute.
  select r.run_id into v_run
    from public.phase_c_workflow_run r
   where r.workflow_id = 'W04'
     and r.business_object_id = 'customer_account:' || v_owner
     and r.state not in ('closed','cancelled','failed','completed')
   order by r.run_id desc limit 1;

  if v_run is not null then
    select sr.step_run_id, sr.accountable_role_id into v_step_run, v_actor
      from public.phase_c_workflow_step_run sr
     where sr.run_id = v_run and sr.step_id = 'W04-S01' and sr.state = 'active'
     order by sr.step_run_id desc limit 1;

    if v_step_run is not null then
      v_disp := public.fn_phase_d_dispatch_step(jsonb_build_object(
        'step_run_id',   v_step_run,
        'actor_role_id', coalesce(v_actor, 'customer_support'),
        'opened_by_kind','terms_accepted',
        'opened_by_ref', 'fn_customer_terms_accept:' || v_owner,
        'idempotency_key','W04-accept:' || v_run || ':W04-S01'));
      v_effect := nullif(v_disp->>'effect_id','')::bigint;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'acceptance_ref', v_acc_ref,
    'terms_version', v_version,
    'terms_hash', v_digest,
    'run_id', v_run,
    'step_run_id', v_step_run,
    'dispatch_outcome', v_disp->>'outcome',
    'effect_id', v_effect,
    'dispatch', v_disp);
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_terms_accepted_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v jsonb;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;
  begin
    v := public.fn_customer_terms_accept(new.id, new.tos_ip);
    if coalesce((v->>'ok')::boolean, false) is not true then
      insert into public.error_events (source, kind, severity, detail)
      values ('customer_terms_accepted_trg', 'acceptance_record_not_written', 'high',
              jsonb_build_object('customer_id', new.id, 'result', v));
    end if;
  exception when others then
    insert into public.error_events (source, kind, severity, detail)
    values ('customer_terms_accepted_trg', 'acceptance_record_failed', 'high',
            jsonb_build_object('customer_id', new.id, 'sqlstate', sqlstate, 'error', left(sqlerrm, 500)));
  end;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customer_welcome_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(btrim(new.email),'') <> '' then
    begin
      perform public.fn_customer_welcome(new.id, true);
    exception when others then
      -- Never let onboarding courtesy break account creation.
      null;
    end;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_customers_board(p_search text DEFAULT ''::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select c.id::text as id, coalesce(nullif(trim(c.full_name),''),'(unnamed)') as full_name, c.email, c.phone,
      coalesce(c.email_verified,false) as email_verified, coalesce(c.phone_verified,false) as phone_verified, c.banned, c.created_at,
      case when c.banned then 'banned' when coalesce(c.email_verified,false) or coalesce(c.phone_verified,false) then 'verified' else 'new' end as stage
    from customers c
    where coalesce(p_search,'')='' or c.full_name ilike '%'||p_search||'%' or c.email ilike '%'||p_search||'%' or c.phone ilike '%'||p_search||'%'
  ), ranked as (select *, row_number() over (partition by stage order by created_at desc) rn from base),
  sc as (select stage, count(*) c from base group by stage)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'stages',(select jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'count',coalesce((select c from sc where sc.stage=s.key),0),
      'cards',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'full_name',r.full_name,'email',r.email,'phone',r.phone,'email_verified',r.email_verified,'banned',r.banned) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
      order by s.ord)
      from (values ('new','New',1),('verified','Verified',2),('banned','Banned',3)) s(key,label,ord)),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'full_name',b.full_name,'email',b.email,'phone',b.phone,'email_verified',b.email_verified,'phone_verified',b.phone_verified,'banned',b.banned,'stage',b.stage,'created_at',b.created_at) order by b.created_at desc),'[]'::jsonb)
             from (select * from base order by created_at desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_data_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'category_growth', (select coalesce(fn_marketplace_analytics()->'category_growth','[]'::jsonb)),
    'competitive_categories', (select coalesce(fn_marketplace_analytics()->'competitive_categories','[]'::jsonb)),
    'price_spread', (select coalesce(jsonb_agg(jsonb_build_object('category',category,'n',n,'median',median,'p25',p25,'p75',p75) order by n desc),'[]'::jsonb)
        from (select * from category_price_stats order by n desc limit 10) z),
    'monthly_volume', (select coalesce(jsonb_agg(jsonb_build_object('month',m,'rfqs',c) order by m),'[]'::jsonb)
        from (select to_char(date_trunc('month',created_at),'YYYY-MM') m, count(*) c from inquiries where created_at > now()-interval '6 months' group by 1) z)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dbx_category(p_lead_id bigint)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select public.fn_dbx_safe(coalesce(
    -- 1. the supplier's primary catalog category (the real 86-item taxonomy)
    (select c.name from public.lead_category lc
       join public.catalog_supplier_categories c on c.slug = lc.slug
      where lc.lead_id = p_lead_id and lc.is_primary
      order by lc.score desc nulls last limit 1),
    -- 2. any catalog category we managed to map, best score first
    (select c.name from public.lead_category lc
       join public.catalog_supplier_categories c on c.slug = lc.slug
      where lc.lead_id = p_lead_id
      order by lc.score desc nulls last limit 1),
    -- 3. legacy text, but only when it is literally a catalog slug or catalog name
    (select c.name from public.leads l
       join public.catalog_supplier_categories c
         on c.slug = btrim(split_part(coalesce(l.categories,''),',',1))
         or lower(c.name) = lower(btrim(split_part(coalesce(l.categories,''),',',1)))
         or c.slug = btrim(coalesce(l.sector,''))
      where l.id = p_lead_id limit 1),
    'Uncategorized'));
$function$


CREATE OR REPLACE FUNCTION public.fn_dbx_safe(x text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select btrim(regexp_replace(regexp_replace(coalesce(x,''),'[\\/:*?"<>|\r\n\t]+',' ','g'),'\s+',' ','g'))
$function$


CREATE OR REPLACE FUNCTION public.fn_decide(p_kind text, p_ctx jsonb, p_actor text DEFAULT 'agent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  res jsonb; conf numeric; reasons jsonb := '[]'::jsonb; route text; decision text;
  sources jsonb := '[]'::jsonb;
  v_alt text; v_alt_why text; v_alt_score numeric;
  v_ctx jsonb := coalesce(p_ctx, '{}'::jsonb);
  v_q text; v_cands text[]; v_hits jsonb := '[]'::jsonb; v_evidence jsonb;
  v_options jsonb; v_amount numeric; v_dept text;
  v_problem text; v_imp_bus text; v_imp_fin text; v_imp_leg text; v_imp_cus text;
  v_escalates boolean; v_status text; v_approver text; v_authorised boolean;
  v_actor_tier text;   -- reputation tier of the acting agent (gap 8)
  v_dr_id bigint; v_dr_status text; v_verdict text; v_gate_reason text;
  v_corr uuid; v_trace uuid; v_prior jsonb;
begin
  begin v_amount := nullif(coalesce(v_ctx->>'amount_aed', v_ctx->>'amount'), '')::numeric;
  exception when others then v_amount := null; end;
  v_dept := nullif(v_ctx->>'dept_key', '');

  if p_kind='escalate' then
    -- p_actor goes IN. Without it the router has no line to send the escalation up and answers
    -- every caller with the same company-wide owner; see fn_should_escalate's reporting-line rung.
    res := public.fn_should_escalate(v_ctx || jsonb_build_object('actor', p_actor));
    decision := case when (res->>'escalate')::boolean then 'escalate' else 'proceed' end;
    reasons := res->'reasons'; route := res->>'route_to';
    conf := case when (res->>'escalate')::boolean then 0.9 else 0.8 end;
    -- WHY THIS PARTY, NOT JUST WHICH. 'decision_policy' was a label naming a table; the router's
    -- own verdict — route_basis, route_note and the reasons it fired on — is the retrieval this
    -- decision was actually taken on, and it is what makes the routing auditable after the fact.
    sources := to_jsonb(array['decision_policy'])
      || jsonb_build_array(jsonb_build_object('kind','policy_check','ref','fn_should_escalate','result',res));
    v_alt := case when decision='escalate' then 'proceed' else 'escalate' end;
    v_alt_why := 'the opposite verdict from fn_should_escalate on the same context';

  elsif p_kind='price' then
    res := public.fn_price_confidence(coalesce(v_ctx->>'category','default'), nullif(v_ctx->>'amount_aed','')::numeric);
    decision := 'priced'; conf := coalesce((res->>'confidence')::numeric, 0.5);
    reasons := jsonb_build_array(coalesce(res->>'band', 'price band computed')); sources := to_jsonb(array['price_confidence']);
    route := null;   -- a price band hands off to nobody; 'none' was a name that named nobody
    v_alt := 'quote_manually'; v_alt_why := 'refer the price to a human estimator instead of the band';

  elsif p_kind='route_category' then
    route := public.fn_resolve_cat_agent(coalesce(v_ctx->>'category',''));
    decision := coalesce(route,'unmatched'); conf := case when route is null then 0.3 else 0.85 end;
    reasons := jsonb_build_array('mapped category "'||coalesce(v_ctx->>'category','')||'" to agent '||coalesce(route,'(none)'));
    sources := to_jsonb(array['category_agents']);
    v_alt := 'Secretary'; v_alt_why := 'the unrouted-work fallback, which is slower but never drops the item';

  elsif p_kind='invite' then
    -- rank approved suppliers for a category (+ optional emirate)
    with pool as (
      select id, company_name, coalesce(capability_score,0) cap, coalesce(app_rating,rating,0) rat, coalesce(rv_response_rate,0) resp
      from leads
      where coalesce(approval_status,'')='approved'
        and (coalesce(v_ctx->>'category','')='' or lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(v_ctx->>'category')||'%')
        and (coalesce(v_ctx->>'emirate','')='' or coalesce(v_ctx->>'emirate')= any(coalesce(service_emirates,array[emirate])))
      order by (coalesce(capability_score,0)*0.5 + coalesce(app_rating,rating,0)*8 + coalesce(rv_response_rate,0)*0.3) desc
      limit coalesce((v_ctx->>'n')::int, 5))
    select jsonb_agg(jsonb_build_object('id',id,'name',company_name,'cap',cap,'rating',rat,'response',resp)) into res from pool;
    decision := 'invite_ranked'; conf := case when res is null then 0.2 when jsonb_array_length(res)>=3 then 0.8 else 0.5 end;
    reasons := jsonb_build_array('ranked by capability_score, rating and response rate');
    sources := to_jsonb(array['leads','supplier_capability','response_rate']);
    res := jsonb_build_object('suppliers', coalesce(res,'[]'));
    v_alt := 'broadcast_to_all_approved';
    v_alt_why := 'invite every approved supplier instead of the ranked shortlist — more coverage, worse response rate';

  elsif p_kind='approve' then
    res := public.fn_should_escalate(v_ctx || jsonb_build_object('actor', p_actor));
    if (res->>'escalate')::boolean then decision:='human_review'; conf:=0.9; reasons:=res->'reasons';
    else decision:='auto_approve'; conf:=0.85; reasons:=jsonb_build_array('within autonomous thresholds'); end if;
    route := res->>'route_to';
    sources := to_jsonb(array['decision_policy'])
      || jsonb_build_array(jsonb_build_object('kind','policy_check','ref','fn_should_escalate','result',res));
    v_alt := case when decision='human_review' then 'auto_approve' else 'human_review' end;
    v_alt_why := 'the opposite side of the autonomous threshold in decision_policy';

  else
    decision := 'unsupported_kind'; conf := 0; reasons := jsonb_build_array('no handler for kind '||p_kind); route:='Secretary';
    v_alt := 'add_a_handler'; v_alt_why := 'teach fn_decide this kind rather than routing it to a person every time';
  end if;

  -- ROUTE_TO NAMES A PARTY, OR IT NAMES NOBODY AND IS NULL.
  --
  -- MEASURED DEFECT, production, 6 Aug 2026: every routed decision this engine has ever written
  -- names something the org model does not contain. route_category wrote 'cat:signage' (9 rows) —
  -- a knowledge persona in category_agents, not an employee; price wrote the literal string
  -- 'none'; the unsupported-kind branch wrote 'Secretary', which matches no agent_key, no title
  -- and no dept_key across all 67 employees. The requirement is "Should I escalate? routes to a
  -- NAMED PARTY", and a column that is merely non-null answers it with a string.
  --
  -- The ladder resolves whatever the branch above chose, and it invents nobody: each rung returns
  -- a party the org model already contains, and if none does, the value is whatever
  -- fn_should_escalate itself answers — so a configuration gap stays visible as an unresolvable
  -- route rather than being papered over here.
  --   1. the name is already an active employee or a staffed department -> keep it
  --   2. 'cat:x' is a knowledge persona; the party is 'x' if 'x' is one  -> cat:it -> it
  --   3. the deciding actor's own department, if staffed — the work stays where it arose
  --   4. the escalation resolver's answer, which is the same one every other kind gets
  -- A decision that hands off to nobody carries NULL, which is what `invite` already did. The
  -- category agent itself is not lost: it is already the value of `decision` and is quoted in
  -- `reasons`, which is where "which persona holds this knowledge" belongs.
  route := nullif(btrim(coalesce(route, '')), '');
  if route in ('none', 'unmatched') then route := null; end if;
  if route is not null then
    route := coalesce(
      public.fn_route_party(route),
      public.fn_route_party(regexp_replace(route, '^cat:', '')),
      public.fn_route_party((select a.department from public.org_agents a
                              where a.agent_key = p_actor and a.active limit 1)),
      public.fn_should_escalate(jsonb_build_object('actor', p_actor)) ->> 'route_to');
  end if;

  -- STEP 3, KNOWLEDGE RETRIEVAL. fn_memory_search had zero callers, which is the whole defect:
  -- the engine decided without consulting anything the company already knew.
  --
  -- NARROW FIRST, THEN WIDER. fn_memory_search builds its query with plainto_tsquery, which ANDs
  -- every lexeme, so handing it a whole sentence retrieves NOTHING: 'Which agent owns Printing /
  -- Packaging / Signage work when an RFQ arrives' returned 0 hits on production while 'signage'
  -- returned 5. The candidates are therefore tried shortest-first and the first one that retrieves
  -- wins. A failed search must not lose the decision, so it degrades to "searched, no hits".
  v_cands := array_remove(array[
      nullif(btrim(coalesce(v_ctx->>'category','')), ''),
      nullif(array_to_string((regexp_split_to_array(
        btrim(coalesce(v_ctx->>'question', v_ctx->>'problem','')), '\s+'))[1:4], ' '), ''),
      nullif(btrim(coalesce(v_ctx->>'question', v_ctx->>'problem','')), ''),
      p_kind], null);

  foreach v_q in array v_cands loop
    begin
      select coalesce(jsonb_agg(jsonb_build_object(
               'kind', m.kind, 'ref', m.ref, 'snippet', left(m.snippet, 180),
               'score', round(m.score::numeric, 4))), '[]'::jsonb)
        into v_hits
        from public.fn_memory_search(v_q, null::text[], 5) m;
    exception when others then v_hits := '[]'::jsonb; end;
    exit when jsonb_array_length(v_hits) > 0;
  end loop;

  sources := sources || jsonb_build_array(jsonb_build_object(
               'kind', 'memory_search', 'q', v_q, 'hits', jsonb_array_length(v_hits))) || v_hits;

  -- HOW THE LAST DECISIONS OF THIS KIND TURNED OUT. decision_trace.outcome_status was written by
  -- fn_execution_sweep and read by nobody; it is retrieved here, recorded as a source, and it
  -- BITES: a kind whose executions have failed more often than they succeeded loses the confidence
  -- it needs to be taken autonomously and escalates instead. That is the difference between a
  -- measured outcome and a stored one.
  v_prior := public.fn_decision_outcomes(p_kind, 90);
  sources := sources || jsonb_build_array(jsonb_build_object(
               'kind', 'prior_outcomes', 'ref', 'decision_trace', 'result', v_prior));
  if coalesce((v_prior->>'graded')::int, 0) >= 3
     and coalesce((v_prior->>'failed')::int, 0) > coalesce((v_prior->>'succeeded')::int, 0) then
    conf := least(conf, 0.65);
    reasons := coalesce(reasons,'[]'::jsonb) || jsonb_build_array(format(
      'the last %s graded %s decisions went %s failed against %s succeeded, so this one is not taken autonomously',
      v_prior->>'graded', p_kind, v_prior->>'failed', v_prior->>'succeeded'));
  end if;

  v_evidence := sources;

  -- STEP 6. Two scored alternatives, always. One "option" is a conclusion, not a choice.
  v_options := jsonb_build_array(
    jsonb_build_object('option', decision, 'score', conf, 'selected', true, 'rationale', reasons),
    jsonb_build_object('option', coalesce(v_alt,'no_action'),
                       'score', coalesce(v_alt_score, round(1 - conf, 2)), 'selected', false,
                       'rationale', jsonb_build_array(coalesce(v_alt_why, 'the alternative the engine scored lower'))));

  -- STEP 1 and STEP 4. The problem in words, and the four impacts derived from what was computed.
  v_problem := format('Decision requested (%s) by %s: %s', p_kind, p_actor,
                 left(coalesce(nullif(btrim(concat_ws(' ', nullif(v_ctx->>'question',''), nullif(v_ctx->>'problem',''))), ''),
                               v_ctx::text), 400));
  v_imp_bus := format('Business: the engine selected "%s" over "%s" for %s. %s',
                 decision, coalesce(v_alt,'no_action'), p_actor, coalesce(v_alt_why,''));
  v_imp_fin := case when coalesce(v_amount,0) > 0
                 then format('Financial: AED %s is committed by this decision and is checked against %s spend authority before the gate lets it through.',
                             v_amount, coalesce(v_dept,'company'))
                 else format('Financial: no money moves. A %s decision consumes no spend authority and financial_aed stays null.', p_kind) end;
  v_imp_leg := case when p_kind in ('price','approve','invite')
                 then format('Legal: %s decisions are visible to a counterparty, so the record is retained for audit and PDPL subject access.', p_kind)
                 else format('Legal: internal routing only; a %s decision creates no counterparty obligation.', p_kind) end;
  v_imp_cus := case when coalesce(route,'none') in ('none','')
                 then format('Customer: no customer-facing step changes; the %s decision stays inside the operating system.', p_kind)
                 else format('Customer: the work moves to %s, which sets who answers the customer next and how quickly.', route) end;

  -- STEP 7. Whether this is the engine's to take. Escalating decisions stay 'proposed' and never
  -- reach the gate; autonomous ones are written as 'approved' so trg_decision_gate must inspect
  -- them, and it is free to refuse — 'blocked_by_gate' coming back out is a working gate, not a bug.
  --
  -- THE ACTOR MUST HAVE AUTHORITY ON FILE. This is now belt AND braces: fn_decision_gate consults
  -- the register itself for every writer (scripts/sql/fn_decision_gate_authority_register.sql), and
  -- the engine declines to even propose an autonomous decision for an actor it cannot find there —
  -- an escalation is a better answer than a refusal for something the engine could see coming.
  -- 'founder' is the one identity the gate treats as top authority without an employee_authority
  -- row, so it resolves here too; every other actor must be on the list.
  v_authorised := p_actor = 'founder'
                  or exists (select 1 from public.employee_authority ea where ea.agent_key = p_actor);
  if not v_authorised then
    reasons := coalesce(reasons,'[]'::jsonb) || jsonb_build_array(
      format('%s has no employee_authority record, so this decision is escalated rather than taken autonomously', p_actor));
  end if;

  -- Reputation is load-bearing beyond spend: an agent on probation does not take a decision
  -- autonomously, whatever its kind. This is the demotion signal the spend check already reads.
  select r.tier into v_actor_tier from public.agent_reputation r where r.agent_key = p_actor;
  if v_actor_tier = 'probation' then
    reasons := coalesce(reasons,'[]'::jsonb) || jsonb_build_array(
      format('%s is on probation in the reputation system, so this decision is escalated to a person rather than taken autonomously', p_actor));
  end if;

  v_escalates := decision in ('escalate','human_review','unsupported_kind')
                 or conf < 0.7
                 or jsonb_array_length(v_evidence) = 0
                 or not v_authorised
                 or v_actor_tier = 'probation';
  v_status   := case when v_escalates then 'proposed' else 'approved' end;
  v_approver := case when v_escalates then null else p_actor end;

  insert into public.decision_record(
      decided_by, dept_key, problem, context, options, risks, benefits, recommendation,
      confidence, expected_outcome, rollback_plan, approved_by, status,
      impact_business, impact_financial, financial_aed, impact_legal, impact_customer,
      evidence, reversible)
  values (
      p_actor, v_dept, v_problem, left(v_ctx::text, 2000), v_options,
      format('Risk: if "%s" is the wrong call, %s. Scored %s against %s for the alternative.',
             decision, coalesce(v_alt_why,'the rejected alternative was the better one'),
             conf, coalesce(v_alt_score, round(1 - conf, 2))),
      format('Benefit: the %s step is taken now instead of waiting for a person, on %s retrieved reference(s).',
             p_kind, jsonb_array_length(v_hits)),
      -- recommendation is the ONE decision_record field fn_agent_context actually emits to an
      -- employee ('# DECISIONS ALREADY ON RECORD FOR YOUR DEPARTMENT', left(...,150)). The step-3
      -- retrieval was landing on evidence, which travels nowhere, so the count of references the
      -- engine consulted is carried here instead of being computed and thrown away.
      format('%s (confidence %s, route %s, %s reference(s) retrieved)',
             decision, conf, coalesce(route,'none'), jsonb_array_length(v_hits)),
      conf,
      format('Expected: %s is carried out and the outcome recorded against decision_record.', decision),
      case when v_escalates then 'Rollback: nothing executed; the decision sits at proposed and is routed to the accountable department''s lead through the org_task lane (fn_decision_record_route). Only a Stripe refund reaches the founder.'
           else format('Rollback: set status back to proposed and re-run fn_decide(%L, ...) with corrected context.', p_kind) end,
      v_approver, v_status,
      v_imp_bus, v_imp_fin, v_amount, v_imp_leg, v_imp_cus,
      v_evidence, coalesce(v_amount,0) = 0)
  returning id, status, gate_verdict, gate_reason
       into v_dr_id, v_dr_status, v_verdict, v_gate_reason;

  insert into public.decision_log(actor,kind,ctx,decision,confidence,reasons,sources,route_to)
  values (p_actor,p_kind,v_ctx,decision,conf,reasons,sources,route);

  -- STEP 9. Execution linked BACK to the decision. One correlation_id ties the trace to the
  -- action, and the action carries the decision_record id it came from, so
  -- v_executions_without_decision_trace stays empty for anything this engine produced.
  -- The row is written 'queued' and public.fn_execution_run (cron execution_run_hourly) performs
  -- it: it delivers the decision to the actor the decision named and settles the row against the
  -- artefact it created. Claiming 'succeeded' here would be claiming an outcome before the act.
  if v_verdict = 'passed' then
    begin v_corr := nullif(current_setting('app.correlation_id', true), '')::uuid;
    exception when others then v_corr := null; end;
    v_corr := coalesce(v_corr, gen_random_uuid());

    insert into public.decision_trace(
        correlation_id, entity_type, entity_id, decision_type, proposed_by, decided_by,
        policy_keys, knowledge_refs, evidence_refs, alternatives, assumptions, risk,
        confidence, authority_result, decision)
    values (v_corr, 'decision_record', v_dr_id::text, p_kind, p_actor, coalesce(v_approver, p_actor),
        array['decision_policy'], v_hits, v_evidence, v_options,
        jsonb_build_array(format('context supplied by %s is current', p_actor)),
        jsonb_build_object('escalated', v_escalates, 'route_to', route, 'financial_aed', v_amount),
        conf,
        jsonb_build_object('gate_verdict', v_verdict, 'approved_by', v_approver, 'status', v_dr_status),
        jsonb_build_object('kind', p_kind, 'decision', decision, 'decision_record_id', v_dr_id,
                           'confidence', conf))
    returning id into v_trace;

    insert into public.action_execution(
        correlation_id, action_class, executor, idempotency_key, risk_tier, reversible, request, status)
    values (v_corr, 'decision.'||p_kind, p_actor, 'decision_record:'||v_dr_id::text,
        case when coalesce(v_amount,0) >= 1000 then 'high'
             when coalesce(v_amount,0) > 0 then 'medium' else 'low' end,
        coalesce(v_amount,0) = 0,
        jsonb_build_object('decision_record_id', v_dr_id, 'decision_trace_id', v_trace,
                           'kind', p_kind, 'decision', decision, 'route_to', route, 'ctx', v_ctx),
        'queued');
  end if;


  -- A PROPOSED DECISION HAS AN OWNER WHO IS NOT THE FOUNDER (5 Sep 2026). An escalating decision used
  -- to sit at 'proposed' with nobody routed to it and the OS showed it to the founder as his. It is now
  -- handed to the accountable department through the org_task lane in the same transaction. The routing
  -- must never lose the decision it routes, so a failure is a warning on the record, not an abort.
  if v_escalates and v_dr_id is not null then
    begin
      perform public.fn_decision_record_route(v_dr_id);
    exception when others then
      raise warning 'fn_decision_record_route failed for decision_record % : %', v_dr_id, sqlerrm;
    end;
  end if;

  -- BOARD BEFORE A MAJOR DECISION (spec #3 s24). Every active advisor gives an independent opinion
  -- on the problem this decision answers, keyed to the decision_record by id -- so the link is a
  -- foreign key and not the text match the scorer had to fall back on when subject_ref was null on
  -- all 28 rows. fn_challenge underneath is pure SQL, so this costs no model call.
  -- Guarded twice: only when a record was actually written, and an advisor that throws must not
  -- lose the decision it was advising on. The failure is raised as a warning rather than swallowed.
  if v_dr_id is not null then
    begin
      perform public.fn_board_review(
        coalesce((select d.problem from public.decision_record d where d.id = v_dr_id), p_kind),
        v_dr_id::text);
    exception when others then
      raise warning 'fn_board_review failed for decision_record % : %', v_dr_id, sqlerrm;
    end;
  end if;

  return jsonb_build_object('kind',p_kind,'decision',decision,'confidence',conf,'reasons',reasons,
                            'route_to',route,'sources',sources,'detail',res,
                            'decision_record_id',v_dr_id,'status',v_dr_status,
                            'gate_verdict',v_verdict,'gate_reason',v_gate_reason,
                            'options',v_options,'knowledge_hits',jsonb_array_length(v_hits),
                            'prior_outcomes',v_prior);
end $function$


CREATE OR REPLACE FUNCTION public.fn_decision_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_was text; v_spend jsonb; v_reason text; v_limit numeric; v_actor text; v_auth integer;
begin
  v_was := case when tg_op = 'UPDATE' then coalesce(old.status,'') else '' end;

  if new.status in ('approved','executed') and v_was not in ('approved','executed') then
    v_reason := null;

    if coalesce(length(new.impact_business),0)  < 20
    or coalesce(length(new.impact_financial),0) < 20
    or coalesce(length(new.impact_legal),0)     < 10
    or coalesce(length(new.impact_customer),0)  < 20
    or jsonb_array_length(coalesce(new.evidence,'[]'::jsonb)) = 0 then
      v_reason := 'Impact analysis incomplete: business, financial, legal and customer impact plus at least one evidence reference are all required before approval.';
    end if;

    -- THE AUTHORITY REGISTER, CONSULTED. Not "is this affordable" — that is the spend question
    -- below and it only asks anything when money moves. This asks the step-7 question: is the
    -- approver someone this company has recorded as able to decide anything at all?
    if v_reason is null then
      v_actor := coalesce(nullif(btrim(new.approved_by),''), new.decided_by);
      if coalesce(v_actor,'') <> 'founder' then
        select count(*) into v_auth
          from public.employee_authority ea
         where ea.agent_key = v_actor;
        if coalesce(v_auth,0) = 0 then
          v_reason := format('%s has no employee_authority record. The authority register is the '
                          || 'list of who may decide what; an actor absent from it cannot approve a '
                          || 'decision, whatever the amount involved.',
                          coalesce(v_actor, '(no approver named)'));
        end if;
      end if;
    end if;

    -- Reputation gate (gap 8): an approver on probation may not approve any decision, money or not,
    -- mirroring how the spend gate already refuses a demoted agent.
    if v_reason is null and coalesce(v_actor,'') <> 'founder'
       and exists (select 1 from public.agent_reputation r where r.agent_key = v_actor and r.tier = 'probation') then
      v_reason := format('%s is on probation in the reputation system and may not approve a decision until reinstated.', v_actor);
    end if;

    if v_reason is null and coalesce(new.financial_aed,0) > 0 then
      -- fn_emit_budget_exceeded is fn_check_spend plus a company_event on a breach. Same verdict,
      -- and the breach now leaves a trace the founder actually reads.
      v_spend := public.fn_emit_budget_exceeded(new.dept_key, new.financial_aed, new.approved_by,
                   coalesce(left(new.problem, 200), 'decision_record #' || coalesce(new.id::text,'?')));
      v_limit := nullif(v_spend->>'agent_limit_aed','')::numeric;

      if not coalesce((v_spend->>'affordable')::boolean, false) then
        v_reason := v_spend->>'reason';
      elsif v_limit is not null and coalesce(new.financial_aed,0) > v_limit then
        -- THE PERSONAL GRANT, ENFORCED. Previously computed and thrown away.
        v_reason := format('AED %s exceeds %s''s personal authority limit of AED %s recorded in '
                        || 'employee_authority. Affordable for the department, but not this '
                        || 'employee''s to approve — route to %s.',
                        new.financial_aed, coalesce(new.approved_by,'(unnamed approver)'), v_limit,
                        coalesce(v_spend->>'route_to','the Chief of Staff'));
      elsif coalesce(new.financial_aed,0) > 10000 and coalesce(new.approved_by,'') not in ('founder','ceo') then
        v_reason := format('AED %s is above the AED 10,000 founder threshold and approved_by is "%s".', new.financial_aed, coalesce(new.approved_by,'(none)'));
      elsif coalesce(new.financial_aed,0) >= 1000 and coalesce(new.approved_by,'') not in ('brief','founder','ceo') then
        v_reason := format('AED %s needs Chief of Staff approval and approved_by is "%s".', new.financial_aed, coalesce(new.approved_by,'(none)'));
      end if;
    end if;

    if v_reason is not null then
      -- Refuse, and leave the refusal on the row rather than aborting the transaction
      -- and losing every trace of it.
      new.status          := 'blocked_by_gate';
      new.gate_verdict    := 'refused';
      new.gate_reason     := v_reason;
      new.gate_checked_at := now();
      raise warning 'decision refused by gate: %', v_reason;
    else
      new.gate_verdict    := 'passed';
      new.gate_reason     := null;
      new.gate_checked_at := now();
    end if;
  end if;
  return new;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_decision_outcomes(p_kind text, p_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- 'cancelled' is counted and reported but is NOT a failure: it means the decision was withdrawn
  -- or refused before it ran, which the authority gate has already ruled on and which says nothing
  -- about whether decisions OF THIS KIND work when they are carried out. Folding it in would make
  -- three gate refusals suppress a whole decision kind for ninety days, which is a punishment, not
  -- a measurement.
  select jsonb_build_object(
           'decision_type', p_kind,
           'window_days',   greatest(coalesce(p_days, 90), 1),
           'traced',        count(*),
           'graded',        count(*) filter (where t.outcome_status is not null),
           'succeeded',     count(*) filter (where t.outcome_status = 'succeeded'),
           'failed',        count(*) filter (where t.outcome_status in ('failed','stalled')),
           'cancelled',     count(*) filter (where t.outcome_status = 'cancelled'),
           'last_evaluated_at', max(t.evaluated_at))
    from public.decision_trace t
   where t.decision_type = p_kind
     and t.created_at > now() - make_interval(days => greatest(coalesce(p_days, 90), 1));
$function$


CREATE OR REPLACE FUNCTION public.fn_decision_record_route(p_decision_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  d record; t record;
  v_dept text; v_lead text; v_task bigint; v_title text; v_detail text; v_hops int;
  v_routed int := 0; v_shared int := 0; v_closed int := 0; v_status text;
begin
  for d in
    select r.id, r.decided_by, r.dept_key, r.problem, r.recommendation, r.options, r.created_at
      from public.decision_record r
     where r.status = 'proposed' and r.approved_by is null
       and (p_decision_id is null or r.id = p_decision_id)
       and not exists (select 1 from public.org_tasks o
                        where o.detail like '%[decision_record:' || r.id || ']%')
     order by r.id
  loop
    -- the owning department: the record's, followed through merges; else the actor's; else exec
    v_dept := d.dept_key; v_hops := 0;
    while v_dept is not null and v_hops < 6
          and not exists (select 1 from public.org_departments x where x.dept_key = v_dept and x.active) loop
      select x.merged_into into v_dept from public.org_departments x where x.dept_key = v_dept;
      v_hops := v_hops + 1;
    end loop;
    if v_dept is null then
      select a.department into v_dept from public.org_agents a where a.agent_key = d.decided_by and a.active;
    end if;
    if v_dept is null or not exists (select 1 from public.org_departments x where x.dept_key = v_dept and x.active) then
      v_dept := 'exec';
    end if;
    select x.lead_agent into v_lead from public.org_departments x where x.dept_key = v_dept;
    if not exists (select 1 from public.org_agents a where a.agent_key = v_lead and a.active and coalesce(a.available, true)) then
      v_lead := null;   -- a05_org_task_fill_ownership picks the least-loaded colleague
    end if;

    v_title := left('Decision requested: ' || regexp_replace(coalesce(d.problem, 'decision_record ' || d.id), '^Decision requested \([^)]*\) by [^:]+: ', ''), 200);

    -- the same open question in the same department is one task, not one per retry
    select o.id into v_task from public.org_tasks o
     where o.dept_key = v_dept and o.title = v_title
       and o.status not in ('done', 'cancelled')
       and o.detail like '[decision_record:%'
     order by o.id limit 1;

    if v_task is not null then
      update public.org_tasks
         set detail = detail || ' [decision_record:' || d.id || ']', updated_at = now()
       where id = v_task;
      v_shared := v_shared + 1;
    else
      v_detail := '[decision_record:' || d.id || '] ' || coalesce(d.problem, '')
        || E'\n\nEngine recommendation: ' || coalesce(d.recommendation, '(none)')
        || E'\nOptions scored: ' || left(coalesce(d.options::text, '[]'), 1500)
        || E'\nRaised by ' || coalesce(d.decided_by, '?') || ' at ' || d.created_at
        || '. fn_decide escalated it instead of taking it; the department determines it in the org_task lane '
        || 'and the decision_record closes on that determination. Only a Stripe refund reaches the founder.';
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, decided_by,
                                    action_class, assigned_agent, priority, result)
      values (v_dept, v_title, v_detail, 'assigned', 'advisory', false, 'fn_decision_record_route',
              'analysis', v_lead, 1,
              jsonb_build_object('source', jsonb_build_object('decision_record_id', d.id,
                                 'routed_at', now(), 'routed_by', 'fn_decision_record_route')))
      returning id into v_task;
      v_routed := v_routed + 1;
    end if;
  end loop;

  -- close-back: a decision whose task the department has determined is approved by that employee, and
  -- the gate rules on it
  for d in
    select r.id, o.id as task_id, coalesce(o.result->>'employee', o.assigned_agent, o.dept_key) as employee,
           left(coalesce(o.result->>'deliverable', o.result->>'summary', ''), 2000) as determination
      from public.decision_record r
      join public.org_tasks o on o.detail like '%[decision_record:' || r.id || ']%' and o.status = 'done'
     where r.status = 'proposed' and r.approved_by is null
       and (p_decision_id is null or r.id = p_decision_id)
     order by r.id
  loop
    update public.decision_record
       set status = 'approved', approved_by = d.employee, decided_at = now(),
           actual_outcome = 'Determined in the org_task lane by ' || d.employee || ' (org_task ' || d.task_id || '): '
                            || coalesce(nullif(d.determination, ''), '(no deliverable text on the task)')
     where id = d.id
     returning status into v_status;
    v_closed := v_closed + 1;
  end loop;

  return jsonb_build_object('routed', v_routed, 'shared_existing_task', v_shared,
                            'closed_on_determination', v_closed, 'ran_at', now());
end
$function$


CREATE OR REPLACE FUNCTION public.fn_decision_trace_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if old.sealed_at is not null then
    -- Only the outcome may be graded after sealing. Everything the decision was BASED on is frozen.
    if (new.decision        is distinct from old.decision)
    or (new.evidence_refs   is distinct from old.evidence_refs)
    or (new.knowledge_refs  is distinct from old.knowledge_refs)
    or (new.tool_result_refs is distinct from old.tool_result_refs)
    or (new.confidence      is distinct from old.confidence)
    or (new.authority_result is distinct from old.authority_result)
    or (new.agent_key       is distinct from old.agent_key)
    or (new.role_id         is distinct from old.role_id)
    or (new.proposed_action is distinct from old.proposed_action) then
      raise exception 'decision_trace % is sealed. Evidence, confidence, authority and identity cannot be edited after the fact; grade the outcome instead.', old.id;
    end if;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_authority(p_dept text, p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v jsonb;
  v_tier text;
  v_reason text;
  v_avg numeric; v_measured int; v_probation int;
  v_capped boolean := false;
begin
  v := public.fn_ops_authority_check(p_dept, p_action_class, p_amount_aed, null);
  v_tier := v->>'effective_tier';
  v_reason := v->>'reason';

  -- The department's earned reputation: only employees with a measured tier count.
  select round(avg(r.score), 1), count(*), count(*) filter (where r.tier = 'probation')
    into v_avg, v_measured, v_probation
    from public.agent_reputation r
    join public.org_agents a on a.agent_key = r.agent_key
   where a.active and a.department = p_dept and r.tier <> 'unmeasured' and r.score is not null;

  if v_tier = 'autonomous' and coalesce(v_measured, 0) > 0 and v_avg < 50 then
    v_tier := 'supervised';
    v_capped := true;
    v_reason := format('capped by reputation: %s measured employee(s) in %s average %s, below the '
                       || 'probation line of 50, so autonomous work runs supervised until the '
                       || 'department earns it back (%s)', v_measured, p_dept, v_avg, v_reason);
  end if;

  return jsonb_build_object(
    'dept', p_dept,
    'action_class', p_action_class,
    'tier', v_tier,
    'threshold_aed', (v->>'threshold_aed')::numeric,
    'capped', coalesce(v->>'production_tier', 'gated') is distinct from v_tier,
    'capped_by_reputation', v_capped,
    'reputation', jsonb_build_object('avg_score', v_avg, 'measured', coalesce(v_measured, 0),
                                     'on_probation', coalesce(v_probation, 0)),
    'reviewed', (v->>'reviewed')::boolean,
    'reason', v_reason);
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_canonical(p_dept text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select d.merged_into from public.org_departments d
      where d.dept_key = p_dept and d.merged_into is not null),
    p_dept);
$function$


CREATE OR REPLACE FUNCTION public.fn_dept_decision_thresholds(p_dept text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with keys as (
    select k, ord from unnest(case p_dept
      when 'marketplace' then array['match_relevance_floor','match_max_fanout','match_max_fanout_per_trade','score_w_product','score_w_brand','score_w_project_type','score_w_size_fit','score_w_track_record','matching_strike_limit','sensitive_categories','confidence_min','fraud_score_max','use_capability_matching']
      when 'supply' then array['matching_strike_limit','match_relevance_floor','match_max_fanout','match_max_fanout_per_trade','score_w_track_record','sensitive_categories','confidence_min','fraud_score_max']
      when 'finance' then array['financial_review_aed','auto_action_max_aed','refund_reveal_fee_pct','refund_admin_fee_aed','refund_late_fee_annual_pct','refund_notify_after_working_days','refund_call_after_working_days','refund_claim_after_call_working_days','founder_review_gates','confidence_min']
      when 'customer_experience' then array['refund_notify_after_working_days','refund_call_after_working_days','refund_claim_after_call_working_days','refund_reveal_fee_pct','refund_admin_fee_aed','founder_review_gates','legal_triggers','confidence_min']
      when 'legal' then array['fraud_score_max','legal_triggers','founder_review_gates','financial_review_aed','sensitive_categories','confidence_min']
      when 'exec' then array['financial_review_aed','auto_action_max_aed','founder_review_gates','confidence_min','fraud_score_max']
      when 'growth' then array['confidence_min','legal_triggers','sensitive_categories','founder_review_gates']
      else array['confidence_min','fraud_score_max','founder_review_gates'] end) with ordinality as u(k, ord))
  select '# YOUR THRESHOLDS (decision_policy, live - these are the numbers the deterministic gates enforce; reason with THESE, never with a remembered figure)'||E'\n'
      || left(string_agg('- '||p.key||' = '||left(p.value::text, 120)
                         ||coalesce(' ('||left(regexp_replace(p.description, '\s+', ' ', 'g'), 80)||')', ''), E'\n' order by keys.ord), 1500)
    from keys join public.decision_policy p on p.key = keys.k;
$function$


CREATE OR REPLACE FUNCTION public.fn_dept_library_search(p_dept text, p_query text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id bigint, department text, title text, content text, rank real)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare q_or tsquery; words text[];
begin
  words := array(select w from unnest(regexp_split_to_array(lower(regexp_replace(coalesce(p_query,''),'[^a-z0-9 ]',' ','g')),'\s+')) w where length(w)>2);
  if array_length(words,1) is null then return; end if;
  begin q_or := to_tsquery('english', array_to_string(words,' | ')); exception when others then return; end;
  return query
    select l.id, l.department, l.title, l.content, ts_rank(l.tsv, q_or) as rank
    from dept_library l
    where (p_dept is null or l.department = p_dept) and l.tsv @@ q_or
    order by ts_rank(l.tsv, q_or) desc, l.id
    limit greatest(1, least(coalesce(p_limit,5),20));
end $function$


CREATE OR REPLACE FUNCTION public.fn_dept_module_scope(p_dept text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(array(select a.alias_key from public.dept_knowledge_alias a
                         where a.dept_key = p_dept and a.alias_kind = 'module'), '{}'::text[]);
$function$


CREATE OR REPLACE FUNCTION public.fn_dept_scope(p_dept text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select array(select p_dept
               union
               select d.dept_key from public.org_departments d where d.merged_into = p_dept
               union
               select a.alias_key from public.dept_knowledge_alias a where a.dept_key = p_dept and a.alias_kind = 'dept');
$function$


CREATE OR REPLACE FUNCTION public.fn_derive_supplier_registration_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_fee numeric; v_start date; v_free int;
begin
  -- Only registered suppliers carry a registration state. The other ~20k scraped listings are
  -- left completely untouched so bulk maintenance on leads stays cheap.
  if coalesce(new.claimed,false) is not true and new.founding_rank is null then
    return new;
  end if;

  select coalesce(p.supplier_reg_fee,1000), p.supplier_charging_starts, coalesce(p.supplier_free_count,1000)
    into v_fee, v_start, v_free from public.pricing_config p where p.id = 1;
  v_fee := coalesce(v_fee,1000); v_free := coalesce(v_free,1000);

  if coalesce(new.subscription_exempt,false) then
    new.registration_status := 'exempt'; new.registration_fee_due := 0;
  elsif new.subscription_paid_until is not null and new.subscription_paid_until >= current_date then
    new.registration_status := 'paid'; new.registration_fee_due := 0;
  elsif v_start is not null and current_date < v_start then
    new.registration_status := 'not_due'; new.registration_fee_due := 0;
  elsif v_start is null and (new.founding_rank is null or new.founding_rank <= v_free) then
    -- 6 Sep 2026 (founder): no calendar start. Charging begins with the registration after the free
    -- count; a rank not yet stamped, or inside the free count, owes nothing.
    new.registration_status := 'not_due'; new.registration_fee_due := 0;
  else
    new.registration_status := 'due'; new.registration_fee_due := v_fee;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_dispatch_agent_knowledge_gaps(p_stale_days integer DEFAULT 14, p_thin_min integer DEFAULT 4)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare a jsonb; g jsonb; opened int := 0; resolved_before int; resolved_after int; total_gap int := 0;
begin
  g := fn_knowledge_gaps(p_stale_days, p_thin_min);
  select count(*) into resolved_before from agent_actions where kind='knowledge_task' and detail->>'signal' like 'agent_knowledge:%' and status in ('pending','needs_review');
  for a in select * from jsonb_array_elements(g->'agents') loop
    declare v_gap boolean := (a->>'status') in ('stale','thin'); v_slug text := a->>'slug';
    begin
      if v_gap then total_gap := total_gap + 1; end if;
      perform kn_task('agent_knowledge:'||v_slug, v_gap, case when (a->>'status')='thin' then 'low' else 'medium' end,
        'Refresh knowledge: '||coalesce(a->>'name',v_slug),
        coalesce(a->>'name',v_slug)||' has '||coalesce(a->>'items','0')||' knowledge item(s), last refreshed '||
        coalesce((a->>'days_stale')||' days ago','never')||' (status: '||(a->>'status')||'). Regenerate its field brief so it advises with current expertise. Auto-closes once refreshed.',
        jsonb_build_array(
          'Item count and refresh date measure the SHELF, not the reading. '||coalesce(a->>'name',v_slug)||' could hold a large, fresh brief it never retrieves and look identical here to one that reads it on every call.',
          'The thresholds are chosen, not derived: under '||p_thin_min||' item(s) is "thin" and '||p_stale_days||' day(s) is "stale". An agent whose field genuinely changes twice a year is stale here every fortnight.',
          '"Regenerate" assumes the source material has moved on. Regenerating against an unchanged world produces a new date and the same knowledge, which closes this task without improving anything.',
          coalesce(a->>'name',v_slug)||' is doing work worth briefing. An agent that has never run is stale in exactly the same way as one that runs hourly.'),
        coalesce(a->>'name',v_slug)||' currently advises from '||coalesce(a->>'items','0')||' item(s) last refreshed '||coalesce((a->>'days_stale')||' days ago','never')||'. Refreshing changes what it tells suppliers and customers; leaving it means confident advice from a stale field brief, which does not fail visibly.',
        'Model spend, one generation per agent. The cheap failure is regenerating everything on a schedule; the expensive one is an agent quoting last quarter''s rules to a customer.');
    end;
  end loop;
  select count(*) into resolved_after from agent_actions where kind='knowledge_task' and detail->>'signal' like 'agent_knowledge:%' and status in ('pending','needs_review');
  return jsonb_build_object('ran_at', now(), 'gaps_found', total_gap, 'open_tasks', resolved_after,
    'summary', g->'summary');
end $function$


CREATE OR REPLACE FUNCTION public.fn_doc_final_notice(p_days integer DEFAULT 7)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  rec record; v_email int := 0; v_wa int := 0; v_skipped int := 0;
  v_horizon date := current_date + make_interval(days => p_days);
  v_phone text; v_to text; v_label text; v_exp date;
begin
  for rec in
    select id, company_name, claimed_by, email, phone, whatsapp,
           license_expiry, insurance_expiry
      from leads
     where approval_status = 'approved'
       and coalesce(banned,false) = false
       and coalesce(matching_blocked,false) = false
       and ((license_expiry   is not null and license_expiry   between current_date and v_horizon)
         or (insurance_expiry is not null and insurance_expiry between current_date and v_horizon))
  loop
    -- Whichever gating document expires first is the one we lead with.
    if rec.license_expiry is not null and rec.license_expiry between current_date and v_horizon
       and (rec.insurance_expiry is null or rec.license_expiry <= rec.insurance_expiry) then
      v_label := 'trade licence'; v_exp := rec.license_expiry;
    else
      v_label := 'insurance certificate'; v_exp := rec.insurance_expiry;
    end if;

    -- One final notice per document per expiry cycle. Without this the daily cron would send
    -- the same warning seven days running.
    if exists (select 1 from notifications
                where type = 'doc_final_notice' and lead_id = rec.id
                  and subject like '%' || v_label || '%'
                  and created_at > now() - interval '20 days') then
      v_skipped := v_skipped + 1; continue;
    end if;

    v_to := nullif(trim(coalesce(rec.claimed_by, rec.email)), '');
    if v_to is null or position('@' in v_to) = 0 then v_skipped := v_skipped + 1; continue; end if;

    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_final_notice', v_to, 'supplier', rec.id, 'email',
      'Final reminder: your ' || v_label || ' expires on ' || v_exp,
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your ' || v_label || ' on file with QuotesDone expires on ' || v_exp || '.' || chr(10) || chr(10) ||
      'If we do not have a valid copy by then, your account will be paused automatically and you will stop receiving customer requests until it is renewed. This is temporary and there is no fee to restore it.' || chr(10) || chr(10) ||
      'Two ways to fix it, either is fine:' || chr(10) ||
      '  1. Reply to this email with the renewed document attached. Our system reads it and updates your profile automatically.' || chr(10) ||
      '  2. Upload it in the Documents tab of your supplier portal: https://quotesdone.com/portal' || chr(10) || chr(10) ||
      'If you have already renewed, please send us the latest copy so our records match.',
      'queued');
    v_email := v_email + 1;

    -- WhatsApp: queued for the same supplier when we hold a number. Delivery depends on the
    -- approved template described in the header comment.
    v_phone := nullif(trim(coalesce(rec.whatsapp, rec.phone)), '');
    if v_phone is not null then
      insert into notifications(type,to_email,to_role,lead_id,channel,to_phone,subject,body,status)
      values ('supplier_doc_expiry', v_to, 'supplier', rec.id, 'whatsapp', v_phone,
        'Your ' || v_label || ' expires on ' || v_exp,
        'Your ' || v_label || ' expires on ' || v_exp || '. Renew it to keep receiving QuotesDone requests: https://quotesdone.com/portal',
        'queued');
      v_wa := v_wa + 1;
    end if;
  end loop;

  return json_build_object('emails_queued', v_email, 'whatsapp_queued', v_wa,
                           'skipped', v_skipped, 'days_ahead', p_days,
                           'whatsapp_deliverable', false,
                           'whatsapp_note', 'Queued but not deliverable until a supplier_doc_expiry template SID is registered in wa_template_sids.',
                           'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_document_classify(p_caption text, p_path text, p_declared text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_cap text := lower(coalesce(p_caption, '') || ' ' || coalesce(p_path, ''));
begin
  -- A DECLARED TYPE BEATS A GUESS. The portal has a dropdown; when the uploader has told us what the
  -- file is, reading the filename instead would be replacing knowledge with inference.
  if p_declared in ('licence','profile','signed_terms') then
    return jsonb_build_object('kind', p_declared, 'by', 'declared', 'confidence', 'high');
  end if;
  if v_cap ~ '(trade|licence|license|رخصة|رخصه)' then
    return jsonb_build_object('kind', 'licence', 'by', 'caption', 'confidence', 'high');
  elsif v_cap ~ '(profile|company profile|brochure|ملف|بروفايل)' then
    return jsonb_build_object('kind', 'profile', 'by', 'caption', 'confidence', 'high');
  elsif v_cap ~ '(terms|t&c|agreement|signed|شروط|اتفاقية)' then
    return jsonb_build_object('kind', 'signed_terms', 'by', 'caption', 'confidence', 'high');
  end if;
  return jsonb_build_object('kind', 'unknown', 'by', 'caption', 'confidence', 'low');
end $function$


CREATE OR REPLACE FUNCTION public.fn_dr_restore_clear(p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_run_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20000)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_n integer;
begin
  if p_before is null and p_run_id is null then
    raise exception 'fn_dr_restore_clear needs p_before or p_run_id: an unbounded clear would race a running drill chain';
  end if;
  delete from public.dr_restore d
   where d.ctid = any(array(
           select r.ctid from public.dr_restore r
            where (p_before is not null and r.drill_at < p_before)
               or (p_run_id is not null and r.run_id = p_run_id)
            limit greatest(1, least(coalesce(p_limit, 20000), 50000))));
  get diagnostics v_n = row_count;
  return v_n;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_dropbox_list(p_prefix text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'prefix', p_prefix,
    'items', coalesce((
      select jsonb_agg(to_jsonb(t) order by t.is_folder desc, lower(t.name))
      from (
        select id, path, name, is_folder, size, server_modified
        from dropbox_files
        where substring(path, 1, length(path) - length(split_part(path,'/', -1)) - 1) = p_prefix
      ) t
    ), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_dues_to_escalate(p_days integer)
 RETURNS TABLE(due_id bigint, supplier_id bigint, principal numeric, currency text, reveal_date date, due_date date, days_overdue integer, company_name text, contact_name text, email text, phone text, trade_license_no text, emirate text, category text, signed_terms_path text, claimed_by text, accepted_terms_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select d.id, d.supplier_id, d.amount_due, coalesce(d.currency,'AED'), d.reveal_date, d.due_date::date,
         (current_date - d.due_date::date) as days_overdue,
         l.company_name, l.contact_name, coalesce(l.claimed_by,l.email) as email, coalesce(l.phone_e164,l.phone),
         l.trade_license_no, l.emirate,
         coalesce(nullif(btrim(split_part(coalesce(l.categories,''),',',1)),''), nullif(l.sector,''),'Uncategorized') as category,
         l.signed_terms_path, l.claimed_by, l.accepted_terms_at
  from public.supplier_dues d
  join public.leads l on l.id = d.supplier_id
  where d.status not in ('paid','waived','cancelled','legal')
    and d.legal_escalated_at is null
    and coalesce(d.amount_due,0) > 0
    and current_date >= add_working_days(d.due_date::date, p_days);
$function$


CREATE OR REPLACE FUNCTION public.fn_ea_agenda(p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'as_of', now(),
    'today', jsonb_build_object(
      'events', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'starts_at',starts_at,'location',location,'attendees',attendees) order by starts_at)
          from ea_events where status='scheduled' and coalesce(starts_at, now())::date = current_date),'[]'::jsonb),
      'reminders_due', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'remind_at',remind_at) order by remind_at)
          from ea_reminders where not done and remind_at <= now()+interval '1 day'),'[]'::jsonb)
    ),
    'upcoming_events', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'starts_at',starts_at,'location',location) order by starts_at)
        from ea_events where status='scheduled' and starts_at > current_date and starts_at <= (current_date + (p_days||' days')::interval)),'[]'::jsonb),
    'open_tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'priority',priority,'due',due_date,'source',source) order by (due_date is null), due_date)
        from (select * from crm_tasks where coalesce(status,'open') not in ('done','cancelled') order by (due_date is null), due_date limit 15) t),'[]'::jsonb),
    'overdue_tasks', (select count(*) from crm_tasks where coalesce(status,'open') not in ('done','cancelled') and due_date < now()),
    -- HIS, AND ONLY HIS. fn_founder_queue is the one reader of what waits on the founder (a refund decision);
    -- an agent_action held with a department is that department's and is never counted here again.
    'approvals_to_clear', (
      select jsonb_build_object(
        'total', coalesce((q->>'waiting_on_you_total')::int, 0),
        'high_risk', coalesce((q->>'waiting_on_you_total')::int, 0),
        'top', coalesce((select jsonb_agg(jsonb_build_object(
                 'agent', y->>'from', 'title', y->>'title', 'risk', 'money', 'kind', y->>'kind',
                 'reason', coalesce(y->>'kind_label', 'Refund decision') || ' — the only decision that is yours',
                 'os', 'finance', 'source', y->>'source', 'subject_ref', y->>'subject_ref',
                 'raised', y->'raised', 'age_days', y->'age_days',
                 'outcome', 'waiting on you since ' || left(coalesce(y->>'raised', ''), 10)))
               from jsonb_array_elements(coalesce(q->'waiting_on_you', '[]'::jsonb)) y), '[]'::jsonb))
      from (select public.fn_founder_queue(8) q) fq
    ),
    'recent_meetings', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'meeting_at',meeting_at,'summary',left(summary,240)) order by meeting_at desc)
        from (select * from ea_meetings order by meeting_at desc limit 5) m),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_edge_health_scan()
 RETURNS TABLE(fn_key text, verdict text, silent_minutes numeric, opened_incident boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r            record;
  v_beat       timestamptz;
  v_silent     numeric;
  v_verdict    text;
  v_note       text;
  v_open       boolean;
  v_title      text;
  v_kind       text;
  v_severity   text;
  v_platform   jsonb;
  v_task       bigint;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_platform
  from (
    select coalesce(headers->>'sb-error-code', 'status_' || coalesce(status_code::text,'null')) as code,
           count(*) as n
    from net._http_response
    where created > timezone('utc', now()) - interval '30 minutes'
      and (status_code is null or status_code < 200 or status_code >= 300)
    group by 1 order by 2 desc limit 10
  ) x;

  for r in select * from edge_expectation where active order by fn_key loop
    v_beat := null; v_note := null; v_open := false;
    begin
      execute r.heartbeat_sql into v_beat;
    exception when others then
      v_verdict := 'PROBE FAILED';
      v_note := 'heartbeat_sql could not be evaluated: ' || left(sqlerrm, 200);
    end;

    if v_note is null then
      v_silent := case when v_beat is null then null
                       else round(extract(epoch from (now() - v_beat)) / 60.0, 1) end;
      v_verdict := case
        when v_beat is null then 'STALE'
        when v_silent > r.max_silence_minutes then 'STALE'
        else 'ALIVE' end;
    else
      v_silent := null;
    end if;

    insert into edge_health_probe (fn_key, last_beat_at, silent_minutes, verdict, note)
    values (r.fn_key, v_beat, v_silent, v_verdict, v_note);

    if v_verdict <> 'ALIVE' then
      -- 4 SEP 2026: a probe that could not run is reported as a broken probe, never as the capability's
      -- silence. Distinct kind, distinct title, its own severity; the same fn_key-keyed resolve clears it.
      if v_verdict = 'PROBE FAILED' then
        v_kind := 'probe_failed'; v_severity := 'low';
        v_title := 'Probe broken: the heartbeat_sql for ' || r.fn_key || ' could not run — ' ||
                   coalesce(v_note, 'no detail') || ' (the capability was NOT measured)';
      else
        v_kind := 'silent_failure'; v_severity := r.severity;
        v_title := 'Silent failure: ' || r.fn_key || ' has produced no effect for ' ||
                   coalesce(v_silent::text || ' minutes', 'an unknown period') ||
                   ' (threshold ' || r.max_silence_minutes || ')';
      end if;

      if not exists (
        select 1 from os_incidents
        where status = 'open' and detail->>'fn_key' = r.fn_key
      ) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (
          left(v_title, 300), v_kind, v_severity, 'open',
          jsonb_build_object(
            'fn_key', r.fn_key,
            'cron_jobname', r.cron_jobname,
            'purpose', r.purpose,
            'blast_radius', r.blast_radius,
            'last_beat_at', v_beat,
            'silent_minutes', v_silent,
            'threshold_minutes', r.max_silence_minutes,
            'probe_note', v_note,
            'heartbeat_sql', case when v_kind = 'probe_failed' then r.heartbeat_sql end,
            'platform_errors_30m', v_platform,
            'detected_by', 'fn_edge_health_scan'),
          'edge_health_watchdog');
        v_open := true;

        insert into org_tasks (dept_key, title, detail, status, tier, action_class, needs_founder)
        values (
          coalesce(r.dept_key, 'product_eng'),  -- 4 Sep 2026: 'technology' is not an org_departments row (FK 23503); Platform & Reliability is
          left(v_title, 300),
          case when v_kind = 'probe_failed' then
            'The watchdog''s own probe for ' || r.fn_key || ' failed to run, so whether the capability is alive is UNKNOWN. ' ||
            E'\n\nStatement that failed: ' || coalesce(r.heartbeat_sql, '(none)') ||
            E'\nError: ' || coalesce(v_note, '') ||
            E'\n\nFix the edge_expectation row (heartbeat_sql) or the relation it reads; do not treat this as an outage of the capability itself.'
          else
            r.purpose || E'\n\nWhat breaks while this stays down: ' || r.blast_radius ||
            E'\n\nLast observed effect: ' || coalesce(v_beat::text, 'never') ||
            E'\nCron job: ' || coalesce(r.cron_jobname, 'unknown') ||
            E'\nSeverity: ' || r.severity ||
            E'\nPlatform error codes in the last 30 minutes: ' || v_platform::text ||
            E'\n\nNote: this was detected by watching the capability''s EFFECT, not its logs. ' ||
            'A function killed by the platform (546 WORKER_RESOURCE_LIMIT, OOM, timeout) never ' ||
            'reaches its own error handler, so agent_runs will look clean. Check ' ||
            'net._http_response and the edge function logs directly.'
          end,
          'proposed', 'supervised', 'investigate',
          -- IT owns technical failures: a dark capability is the technology department's to
          -- investigate and auto-heal, never the founder's to triage. Only refunds reach the founder
          -- (founder standing rule, 2 Sep 2026). The task carries dept_key so the owning department
          -- picks it up; needs_founder stays false. Audit AP-01.
          false);
      end if;
    else
      update os_incidents
         set status = 'resolved', resolved_at = now(), resolved_by = 'edge_health_watchdog',
             resolution = 'Capability resumed producing effects; last beat ' || coalesce(v_beat::text,'?')
       where status = 'open' and detail->>'fn_key' = r.fn_key;
      -- 5 SEP 2026: a recovered capability closes its investigate task through fn_org_task_close_as_fact,
      -- so the close carries the deliverable, the decider, a decision_trace and a review — what the spine
      -- records — instead of status='done' with result NULL. The guard a10_org_task_done_needs_a_determination
      -- refuses the bare form now.
      for v_task in
        select t.id from org_tasks t
         where t.status in ('proposed','assigned','in_progress')
           and t.action_class = 'investigate'
           and (t.title like 'Silent failure: ' || r.fn_key || ' %' or t.title like 'Probe broken: the heartbeat_sql for ' || r.fn_key || ' %')
      loop
        perform fn_org_task_close_as_fact(v_task, 'edge_health_watchdog',
          'Capability ' || r.fn_key || ' resumed producing effects; last beat ' || coalesce(v_beat::text, '?')
            || ' (threshold ' || r.max_silence_minutes || ' minutes). ' || coalesce(r.purpose, '')
            || ' The watchdog measures the EFFECT of the capability, not its logs, so this close is the observed recovery itself.',
          jsonb_build_object('fn_key', r.fn_key, 'last_beat_at', v_beat, 'threshold_minutes', r.max_silence_minutes,
                             'auto_closed', 'capability recovered', 'source', 'fn_edge_health_scan'));
      end loop;
    end if;

    fn_key := r.fn_key; verdict := v_verdict; silent_minutes := v_silent; opened_incident := v_open;
    return next;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_edit_inquiry(p_inquiry uuid, p_customer uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v inquiries%rowtype; v_paid boolean; v_deadline timestamptz;
  v_material boolean := false; v_reason text; v_stale int := 0; v_notified int := 0;
  v_cust_email text; v_admin text;
begin
  select * into v from inquiries where id=p_inquiry;
  if not found then return jsonb_build_object('error','inquiry_not_found'); end if;
  if p_customer is not null and v.customer_id is distinct from p_customer then
    return jsonb_build_object('error','not_your_inquiry'); end if;
  select exists(select 1 from transactions where inquiry_id=p_inquiry) into v_paid;
  if v_paid or v.status in ('revealed','completed','cancelled','closed') or v.pipeline_stage in ('revealed','won','cancelled') then
    return jsonb_build_object('error','not_editable','status',v.status,
      'message','This request can no longer be edited.'); end if;
  v_deadline := v.created_at + interval '1 hour';
  if now() > v_deadline then
    return jsonb_build_object('error','edit_window_closed','editable_until',v_deadline,
      'message','Inquiries can be edited within 1 hour of submitting. Please create a new request for changes after that.'); end if;

  -- Decide materiality BEFORE the update, while the old row is still in hand.
  v_material :=
       (p_patch ? 'spec'       and (p_patch->'spec')       is distinct from v.spec)
    or (p_patch ? 'boq'        and (p_patch->'boq')        is distinct from v.boq)
    or (p_patch ? 'budget'     and (p_patch->>'budget')    is distinct from v.budget)
    or (p_patch ? 'scope_type' and (p_patch->>'scope_type') is distinct from v.scope_type)
    or (p_patch ? 'emirate'    and (p_patch->>'emirate')   is distinct from v.emirate)
    or (p_patch ? 'trades'     and array(select jsonb_array_elements_text(p_patch->'trades')) is distinct from v.trades);

  update inquiries set
    summary   = coalesce(p_patch->>'summary', summary),
    raw_input = coalesce(p_patch->>'raw_input', raw_input),
    budget    = coalesce(p_patch->>'budget', budget),
    emirate   = coalesce(p_patch->>'emirate', emirate),
    scope_type= coalesce(p_patch->>'scope_type', scope_type),
    spec      = case when p_patch ? 'spec' then p_patch->'spec' else spec end,
    boq       = case when p_patch ? 'boq' then p_patch->'boq' else boq end,
    trades    = case when p_patch ? 'trades' then array(select jsonb_array_elements_text(p_patch->'trades')) else trades end,
    keywords  = case when p_patch ? 'keywords' then array(select jsonb_array_elements_text(p_patch->'keywords')) else keywords end
    where id=p_inquiry;

  if v_material then
    v_reason := 'The customer changed the requirements of this request on '
             || to_char(now() at time zone 'Asia/Dubai','DD Mon YYYY HH24:MI')
             || ' (Dubai), after this quote was submitted.';

    -- Stale the live quotes and tell each supplier, in one statement so a quote can never be
    -- reverted without its supplier being told.
    with staled as (
      update quotes q
         set stale_at = now(), stale_reason = v_reason, status = 'draft'
       where q.inquiry_id = p_inquiry
         and q.stale_at is null
         and coalesce(q.status,'') in ('submitted','draft')
      returning q.id, q.supplier_id
    ),
    told as (
      insert into notifications(type, to_email, to_role, lead_id, inquiry_id, quote_id, channel, subject, body, status)
      select 'quote_requirements_changed',
             coalesce(l.claimed_by, l.email), 'supplier', s.supplier_id, p_inquiry, s.id, 'email',
             'The customer changed this request — please re-quote',
             'Hello ' || coalesce(l.company_name,'') || ',' || chr(10) || chr(10) ||
             'A customer has changed the requirements of a request you had already quoted, so your quote has been set back to draft and is no longer being shown to them.' || chr(10) || chr(10) ||
             v_reason || chr(10) || chr(10) ||
             'Please open the request in your supplier portal, review what changed, and submit an updated quote. Your original figures are still there — nothing has been deleted.' || chr(10) || chr(10) ||
             'QuotesDone',
             'queued'
        from staled s join leads l on l.id = s.supplier_id
       where coalesce(l.claimed_by, l.email) is not null
      returning 1
    )
    select (select count(*) from staled), (select count(*) from told) into v_stale, v_notified;

    if v_stale > 0 then
      select email into v_cust_email from customers where id = v.customer_id;
      v_admin := coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),
                          'management@quotesdone.com');

      -- The customer must know their edit cost them their quotes, or they will wait for prices
      -- that are never coming back on their own.
      if v_cust_email is not null then
        insert into notifications(type, to_email, to_role, inquiry_id, channel, subject, body, status)
        values ('inquiry_edit_staled_quotes', v_cust_email, 'customer', p_inquiry, 'email',
                'Your change means we have asked for fresh prices',
                'Hello,' || chr(10) || chr(10) ||
                'You changed the requirements on your request, so the ' || v_stale ||
                ' quote(s) already submitted no longer match what you are asking for. We have asked those suppliers to re-quote against your updated requirements.' || chr(10) || chr(10) ||
                'You do not need to do anything — the new prices will appear as they arrive.' || chr(10) || chr(10) ||
                'QuotesDone', 'queued');
      end if;

      insert into agent_actions(agent, kind, status, risk, title, recommendation, detail, target_table, target_id)
      values ('procurement','requote_required','needs_review','medium',
              'Requirements changed after ' || v_stale || ' quote(s) were submitted',
              'Watch that the invited suppliers actually re-quote. If they do not, the customer is left with a request that had prices and now has none.',
              jsonb_build_object('inquiry_id', p_inquiry, 'quotes_staled', v_stale,
                                 'suppliers_notified', v_notified, 'changed_at', now()),
              'inquiries', p_inquiry::text);
    end if;
  end if;

  return jsonb_build_object('ok',true,'edited',true,'editable_until',v_deadline,
                            'material_change', v_material,
                            'quotes_staled', v_stale,
                            'suppliers_notified', v_notified);
end $function$


CREATE OR REPLACE FUNCTION public.fn_email_sendable(p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_e text; v_pat record; v_dom text;
begin
  v_e := lower(btrim(coalesce(p_email,'')));
  if v_e = '' then
    return jsonb_build_object('ok', false, 'reason', 'no address');
  end if;
  if v_e !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}$' then
    return jsonb_build_object('ok', false, 'reason', 'not a valid address shape');
  end if;
  if exists (select 1 from email_suppressions s where lower(s.email) = v_e) then
    return jsonb_build_object('ok', false, 'reason', 'suppressed');
  end if;
  v_dom := split_part(v_e, '@', 2);
  if exists (select 1 from email_domain_mx m
              where m.domain = v_dom and m.has_mx = false
                and m.kind in ('nxdomain','no_records')) then
    return jsonb_build_object('ok', false, 'reason', 'domain does not accept mail');
  end if;
  for v_pat in select pattern, reason from email_block_pattern where active loop
    if v_e ~ v_pat.pattern then
      return jsonb_build_object('ok', false, 'reason', v_pat.reason);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'reason', 'sendable');
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_emit(p_event_type text, p_entity_type text, p_entity_id text, p_actor text DEFAULT 'system'::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint;
begin
  -- correlation_id and causation_id are deliberately NOT named here. They carry the column
  -- defaults, which read app.correlation_id / app.causation_event_id — so an event emitted inside
  -- fn_event_dispatch's loop joins the chain it came from, and one emitted from a cron starts its
  -- own. Naming them here would override that and silently break the chain.
  insert into company_event (event_type, entity_type, entity_id, actor, payload)
  values (p_event_type, p_entity_type, p_entity_id, coalesce(p_actor,'system'), coalesce(p_payload,'{}'::jsonb))
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_emit_budget_exceeded(p_dept text, p_amount numeric, p_requested_by text, p_purpose text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  v := fn_check_spend(p_dept, p_amount, p_requested_by);
  if not coalesce((v->>'affordable')::boolean, true) then
    insert into company_event (event_type, entity_type, entity_id, actor, payload)
    values ('budget.exceeded','department', p_dept, coalesce(p_requested_by,'system'),
            jsonb_build_object('requested_aed', p_amount, 'available_aed', v->>'available_aed',
                               'purpose', p_purpose, 'reason', v->>'reason'));
  end if;
  return v;
end; $function$


