CREATE OR REPLACE FUNCTION public.fn_phase_a_organization_violations()
 RETURNS TABLE(rule text, subject text, detail text)
 LANGUAGE sql
 STABLE
AS $function$
  -- active canonical department
  select 'department_not_active', r.role_id, r.primary_department_id
    from public.org_role r
    left join public.org_departments d on d.dept_key = r.primary_department_id
   where r.status='active' and (d.dept_key is null or not d.active)
  union all
  -- primary manager, with the CEO/founder boundary as the single exception
  select 'no_primary_manager', r.role_id, 'manager_role_id is null'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and r.manager_role_id is null and r.role_id <> 'ceo'
  union all
  select 'manager_not_active', r.role_id, r.manager_role_id
    from public.org_role r
   where r.status='active' and r.manager_role_id is not null
     and not exists (select 1 from public.org_role m where m.role_id=r.manager_role_id and m.status='active')
  union all
  -- role class: every active role declares which kind of thing it is
  select 'no_role_class', r.role_id, coalesce(r.runtime_mode,'(null)')
    from public.org_role r
   where r.status='active' and coalesce(r.runtime_mode,'') = ''
  union all
  -- necessity, and the reason for it
  select 'no_necessity_status', r.role_id, 'necessity_status is null'
    from public.org_role r
   where r.status='active' and coalesce(btrim(r.necessity_status),'') = ''
  union all
  -- organizational purpose
  select 'no_organizational_purpose', r.role_id, 'necessity_reason/responsibilities empty'
    from public.org_role r
   where r.status='active'
     and coalesce(length(btrim(r.necessity_reason)),0) < 10
     and coalesce(length(btrim(r.responsibilities)),0) < 10
  union all
  -- owned decisions. Overlays own category judgement rather than decisions, and say so in their
  -- necessity_reason, so the rule is scoped to accountable roles rather than relaxed for everyone.
  select 'no_owned_decisions', r.role_id, 'owned_decisions is empty'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and coalesce(cardinality(r.owned_decisions),0) = 0
  union all
  -- forbidden decisions: a role with no stated limits has no limits
  select 'no_forbidden_decisions', r.role_id, 'forbidden_decisions is empty'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and coalesce(cardinality(r.forbidden_decisions),0) = 0
  union all
  -- AT LEAST ONE WORKFLOW, REVIEW OR MANAGEMENT RESPONSIBILITY. This is also the rule that catches
  -- a role retained only to keep a count at 90: such a role manages nobody, owns no workflow,
  -- appears in no step and reviews nothing.
  select 'no_responsibility', r.role_id, 'owns no workflow, no step, manages nobody, reviews nothing'
    from public.org_role r
   where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
     and not exists (select 1 from public.org_workflow_ownership o where o.accountable_role_id = r.role_id)
     and not exists (select 1 from public.org_workflow_step s where s.accountable_role_id = r.role_id)
     and not exists (select 1 from public.org_workflow_ownership o where o.independent_reviewer = r.role_id)
     and not exists (select 1 from public.org_role m where m.manager_role_id = r.role_id and m.status='active')
     and not exists (select 1 from public.workflow_step w where w.actor_role = r.role_id)
     and not exists (select 1 from public.employee_workflow e where e.agent_key = r.runtime_agent_key)
     -- contributing to a workflow IS a responsibility. It is not ACCOUNTABILITY, which is why
     -- contributors are still refused as owners two rules down, but a role that contributes to a
     -- workflow is doing something and is not a row kept to make a count.
     and not exists (select 1 from public.org_workflow_ownership o where r.role_id = any(o.contributors))
  union all
  -- a contributor must be an active role or one of the three declared class terms
  select 'contributor_resolves_to_nobody', o.workflow_id, c
    from public.org_workflow_ownership o, unnest(o.contributors) c
   where not exists (select 1 from public.org_role r where r.role_id = c and r.status='active')
     and c not in ('department heads', 'category overlays', 'broad domain specialists')
  union all
  -- creator/reviewer separation, at the workflow and at the role
  select 'owner_reviews_own_workflow', o.workflow_id, o.accountable_role_id
    from public.org_workflow_ownership o
   where o.independent_reviewer = o.accountable_role_id
  union all
  select 'contributor_is_owner', o.workflow_id, o.accountable_role_id
    from public.org_workflow_ownership o
   where o.accountable_role_id = any(o.contributors)
  union all
  -- founder boundary
  select 'owns_founder_reserved_decision', r.role_id, d.decision_key
    from public.org_role r, public.founder_reserved_decision d, unnest(d.match_any) m(needle)
   where r.status='active'
     and position(m.needle in lower(array_to_string(r.owned_decisions,' | '))) > 0
  union all
  -- reporting cycles, walked rather than assumed
  select 'reporting_cycle', u.root, 'chain does not terminate'
    from (
      with recursive up(root, cur, depth, path) as (
        select role_id, manager_role_id, 1, array[role_id] from public.org_role where status='active'
        union all
        select u.root, r.manager_role_id, u.depth+1, u.path || r.role_id
          from up u join public.org_role r on r.role_id = u.cur and r.status='active'
         where u.depth < 30 and not r.role_id = any(u.path))
      select distinct root from up where depth >= 30) u
  union all
  select 'self_management', r.role_id, r.manager_role_id
    from public.org_role r where r.status='active' and r.manager_role_id = r.role_id
  union all
  -- duplicate active role identity
  select 'duplicate_active_identity', x.runtime_agent_key, 'held by more than one active role'
    from (select runtime_agent_key from public.org_role
           where status='active' and runtime_agent_key is not null
           group by 1 having count(*) > 1) x
  union all
  -- unresolved historical alias, both directions
  select 'retired_role_resolves_to_nobody', r.role_id, 'no alias'
    from public.org_role r
   where r.status = 'retired'
     and not exists (select 1 from public.org_role_alias a where a.alias = r.role_id)
  union all
  select 'alias_points_at_a_dead_role', a.alias, a.role_id
    from public.org_role_alias a
    join public.org_role r on r.role_id = a.role_id
   where r.status <> 'active'
  union all
  -- overlay ownership
  select 'overlay_is_not_a_category_overlay', r.role_id, 'not category_overlay_NNN_'
    from public.org_role r
   where r.status='active' and r.runtime_mode='knowledge_overlay'
     and r.role_id !~ '^category_overlay_[0-9]{3}_'
  union all
  select 'overlay_holds_a_runtime_employee', r.role_id, r.runtime_agent_key
    from public.org_role r
   where r.status='active' and r.runtime_mode='knowledge_overlay' and r.runtime_agent_key is not null
  union all
  select 'overlay_owns_a_workflow', o.workflow_id, o.accountable_role_id
    from public.org_workflow_ownership o join public.org_role r on r.role_id = o.accountable_role_id
   where r.runtime_mode = 'knowledge_overlay'
  union all
  select 'overlay_states_no_limit', r.role_id, 'necessity_reason does not say what it cannot decide'
    from public.org_role r
   where r.status='active' and r.runtime_mode='knowledge_overlay'
     and coalesce(r.necessity_reason,'') not ilike '%cannot decide%';
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_change_request_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_b_change_request is append-only. % on % is refused. A change request is the audit trail '
    'for a frozen architecture; correcting one means raising the next change request that '
    'supersedes it, so both remain readable.',
    tg_op, coalesce(old.change_request_id, new.change_request_id);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_effective_errata()
 RETURNS TABLE(erratum text, condition text, measured text, resolved boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select 'EX-006',
         'exception is complete: escalation owner, required response and closure condition present, and escalation is independent of detection',
         format('escalation=%s detection=%s response=%s closure=%s',
                e.escalation_owner_role_id, e.detection_owner_role_id,
                case when e.required_response <> '' then 'present' else 'MISSING' end,
                case when e.closure_condition <> '' then 'present' else 'MISSING' end),
         e.escalation_owner_role_id <> '' and e.required_response <> ''
           and e.closure_condition <> '' and e.escalation_owner_role_id <> e.detection_owner_role_id
  from public.phase_b_exception e where e.exception_id = 'EX-006'

  union all
  select 'W13',
         'primary business object references an existing canonical object',
         format('primary_object=%s exists=%s', w.primary_object, (o.object_id is not null)),
         o.object_id is not null
  from public.phase_b_workflow w
  left join public.phase_b_business_object o on o.object_id = w.primary_object
  where w.workflow_id = 'W13'

  union all
  select 'W22',
         'workflow has exactly one explicit closure step, it is the step reaching WORKFLOW_COMPLETE, and GATE-008 is attached to it',
         format('closure_steps=%s reaches_complete=%s gate_008_attached_to=%s',
                (select count(*) from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step),
                (select bool_and(next_step_if_pass = 'WORKFLOW_COMPLETE')
                   from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step),
                coalesce((select string_agg(a.step_id, ',') from public.fn_phase_b_gate_attachment() a
                           where a.gate_id='GATE-008' and a.workflow_id='W22'), 'NONE')),
         (select count(*) from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step) = 1
         and (select bool_and(next_step_if_pass = 'WORKFLOW_COMPLETE')
                from public.phase_b_workflow_step where workflow_id='W22' and is_closure_step)
         and exists (select 1 from public.fn_phase_b_gate_attachment() a
                      where a.gate_id='GATE-008' and a.workflow_id='W22' and a.step_id is not null);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_gate_attachment()
 RETURNS TABLE(gate_id text, workflow_id text, step_id text, attachment_basis text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with scoped as (
    -- expand workflow_scope; 'ALL' means every canonical workflow. Both ';' and '/' appear as
    -- separators across the package's registries, so both are split on.
    select g.gate_id, g.gate_name, g.gate_type, w.workflow_id
    from public.phase_b_gate g
    join public.phase_b_workflow w
      on g.workflow_scope = 'ALL'
      or w.workflow_id = any (string_to_array(replace(g.workflow_scope, '/', ';'), ';'))
  )
  -- gates that govern the phase rather than a step
  select s.gate_id, s.workflow_id, null::text, 'phase_level'
  from scoped s
  where s.gate_type = 'phase_boundary' or s.gate_id = 'GATE-001'

  union all
  -- GATE-008 closure completeness -> the workflow's closure step
  select s.gate_id, s.workflow_id, st.step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id and st.is_closure_step
  where s.gate_id = 'GATE-008'

  union all
  -- GATE-005 founder boundary -> steps that carry a founder gate
  select s.gate_id, s.workflow_id, st.step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
   and st.founder_gate is not null and lower(st.founder_gate) <> 'none'
  where s.gate_id = 'GATE-005'

  union all
  -- GATE-004 creator/reviewer separation -> steps that carry an independent reviewer
  select s.gate_id, s.workflow_id, st.step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
   and st.independent_reviewer_role_id is not null
  where s.gate_id = 'GATE-004'

  union all
  -- GATE-007 complete handoff -> steps that send one
  select distinct s.gate_id, s.workflow_id, h.from_step_id, 'declared_step_property'
  from scoped s
  join public.phase_b_handoff h on h.workflow_id = s.workflow_id
  where s.gate_id = 'GATE-007'

  union all
  -- gates that govern every step
  select s.gate_id, s.workflow_id, st.step_id, 'universal'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
  where s.gate_id in ('GATE-002','GATE-003','GATE-006')

  union all
  -- workflow-scoped gates with no finer anchor declared in the package
  select s.gate_id, s.workflow_id, st.step_id, 'workflow_scope'
  from scoped s
  join public.phase_b_workflow_step st on st.workflow_id = s.workflow_id
  where s.gate_id not in ('GATE-001','GATE-002','GATE-003','GATE-004','GATE-005',
                          'GATE-006','GATE-007','GATE-008')
    and s.gate_type <> 'phase_boundary';
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_b_structure_digest()
 RETURNS TABLE(subject text, rows bigint, sha256 text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with
-- workflow ownership: who is accountable, and who independently reviews
workflow_ownership as (
  select w.workflow_id sortkey,
         w.workflow_id||'|'||w.accountable_role_id||'|'||coalesce(w.independent_reviewer_role_id,'') x
  from public.phase_b_workflow w
),
step_ownership as (
  select s.step_id sortkey,
         s.step_id||'|'||s.accountable_role_id||'|'||coalesce(s.independent_reviewer_role_id,'')
         ||'|'||s.actor_kind x
  from public.phase_b_workflow_step s
),
-- workflow order: sequence and both onward paths
workflow_order as (
  select s.step_id sortkey,
         s.workflow_id||'|'||s.step_no::text||'|'||s.step_id||'|'||s.next_step_if_pass
         ||'|'||s.next_step_if_fail||'|'||s.is_closure_step::text x
  from public.phase_b_workflow_step s
),
-- states and transitions, workflow and step
states_and_transitions as (
  select 'A'||state sortkey, 'wf_state|'||state||'|'||terminal::text x from public.phase_b_workflow_state
  union all
  select 'B'||state, 'step_state|'||state||'|'||terminal::text from public.phase_b_step_state
  union all
  select 'C'||from_state||'>'||to_state, 'wf_transition|'||from_state||'|'||to_state
    from public.phase_b_workflow_transition
  union all
  select 'D'||from_state||'>'||to_state, 'step_transition|'||from_state||'|'||to_state
    from public.phase_b_step_transition
),
gates as (
  select g.gate_id sortkey,
         g.gate_id||'|'||g.gate_name||'|'||g.workflow_scope||'|'||g.gate_type
         ||'|'||g.required_evidence||'|'||g.pass_result||'|'||g.fail_result x
  from public.phase_b_gate g
),
business_rules as (
  select r.rule_id sortkey, r.rule_id||'|'||r.rule_name||'|'||r.workflow_scope||'|'||r.rule_type
         ||'|'||r.rule_text x
  from public.phase_b_business_rule r
),
-- handoff accountability: the three named parties and the edge they sit on
handoff_accountability as (
  select h.handoff_id sortkey,
         h.handoff_id||'|'||h.from_step_id||'|'||h.to_step_id||'|'||h.sending_role_id
         ||'|'||h.receiving_role_id||'|'||h.return_owner_role_id||'|'||h.handoff_type x
  from public.phase_b_handoff h
),
-- category-overlay authority: where an overlay may be accountable, and which placeholders may be
overlay_authority as (
  select 'A'||s.step_id sortkey, 'overlay_step|'||s.step_id||'|'||s.workflow_id||'|'||s.step_type x
  from public.phase_b_workflow_step s where s.actor_kind = 'category_overlay'
  union all
  select 'B'||a.actor_token, 'actor|'||a.actor_token||'|'||a.actor_type||'|'||a.may_be_accountable::text
  from public.phase_b_dynamic_actor a
),
founder_boundaries as (
  select b.boundary_id sortkey,
         b.boundary_id||'|'||b.boundary_name||'|'||b.workflow_scope||'|'||b.decision_owner
         ||'|'||b.phase_b_enforcement x
  from public.phase_b_founder_boundary b
),
all_subjects as (
  select 'workflow_ownership' s, sortkey, x from workflow_ownership
  union all select 'step_ownership', sortkey, x from step_ownership
  union all select 'workflow_order', sortkey, x from workflow_order
  union all select 'states_and_transitions', sortkey, x from states_and_transitions
  union all select 'gates', sortkey, x from gates
  union all select 'business_rules', sortkey, x from business_rules
  union all select 'handoff_accountability', sortkey, x from handoff_accountability
  union all select 'overlay_authority', sortkey, x from overlay_authority
  union all select 'founder_boundaries', sortkey, x from founder_boundaries
)
select s,
       count(*)::bigint,
       encode(sha256(convert_to(string_agg(x, chr(10) order by sortkey), 'UTF8')), 'hex')
from all_subjects group by s order by s;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_actor_may_own(p_token text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select kind = 'canonical' from public.fn_phase_c_resolve_actor(p_token)), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_baseline_drift()
 RETURNS TABLE(subject text, approved text, live text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select check_name, expected, actual from public.fn_phase_c_invariants() where not ok;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_change_request_approval_is_derived()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_dec bigint := nullif(btrim(current_setting('app.phase_c_governance_decision', true)),'')::bigint;
  v_touches_approval boolean;
begin
  if TG_OP = 'INSERT' then
    v_touches_approval := NEW.approved_by is not null
                       or NEW.governance_decision_id is not null
                       or NEW.disposition = 'APPROVED';
  else
    v_touches_approval := (NEW.approved_by, NEW.approved_at, NEW.approval_basis, NEW.approval_route,
                           NEW.approval_auth_subject, NEW.approved_amendment_table_digest,
                           NEW.approval_reason, NEW.governance_decision_id, NEW.disposition)
                       is distinct from
                          (OLD.approved_by, OLD.approved_at, OLD.approval_basis, OLD.approval_route,
                           OLD.approval_auth_subject, OLD.approved_amendment_table_digest,
                           OLD.approval_reason, OLD.governance_decision_id, OLD.disposition);
  end if;

  if not v_touches_approval then
    return NEW;
  end if;

  -- The write must be THIS transaction's governance decision, for THIS change request.
  if v_dec is null
     or not exists (select 1 from public.phase_c_governance_decision d
                     where d.decision_id = v_dec
                       and d.txid = txid_current()
                       and d.change_request_ref = NEW.change_request_ref
                       and d.decision = NEW.disposition) then
    raise exception 'phase_c_change_request %: the disposition and every approval column are DERIVED from public.phase_c_governance_decision and may not be written directly. Call public.fn_phase_c_governance_decide with a founder bearer token. A migration, a service_role connection and a typed founder email are all refused here, which is the whole point of PCCR-006. (pccr_governance_decision_required)',
      NEW.change_request_ref using errcode = '42501';
  end if;

  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_change_request_disposition_follows_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- PCCR-006. The forward half is gone. Writing an approver no longer moves the disposition:
  --   update … set approved_by='management@quotesdone.com' where change_request_ref='PCCR-004'
  -- used to come out as disposition=APPROVED carrying the DEFERRAL's own reason text. It is now
  -- refused twice over — by a05 for not being a derived write, and by the CHECK, which finally sees
  -- a deferred row because nothing rewrote it first.
  if TG_OP = 'UPDATE' and NEW.approved_by is null and OLD.approved_by is not null then
    -- The reverse still holds: an APPROVED row whose approver is cleared would be an approval
    -- nobody gave.
    NEW.disposition             := 'RAISED';
    NEW.disposition_reason      := null;
    NEW.disposition_recorded_at := null;
    NEW.approval_reason         := null;
    NEW.approval_basis          := null;
    NEW.approval_route          := null;
    NEW.approval_auth_subject   := null;
    NEW.approved_amendment_table_digest := null;
    NEW.governance_decision_id  := null;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_command_specificity(p_text text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(string_agg(s.signal_id || '=' || s.kind, '; ' order by s.signal_id), '')
  from public.phase_c_command_specificity_signal s
  where p_text ~* s.pattern;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_component_classification_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'cron', 'pg_temp'
AS $function$
declare
  d           jsonb;
  v_derived   text;
  v_reachable boolean;
  v_unexpect  boolean;
begin
  d := public.fn_kernel_component_reachability(new.component_id);
  v_derived := d->>'derived_classification';

  if v_derived in ('UNDERIVABLE','EXTENSION_OWNED_EXCLUDED') then
    return new;
  end if;

  v_reachable := (d->>'reachable')::boolean;
  v_unexpect  := (d->>'unexpectedly_active')::boolean;

  if new.classification in ('DEFERRED_RUNTIME_IMPLEMENTATION','INACTIVE_HISTORICAL',
                            'INTENTIONALLY_INACTIVE','HISTORICAL_ONLY','NO_CALLER_UNCLASSIFIED')
     and v_reachable then
    -- RAISE has no %L. It is % and a stray literal L, which is how the sibling event-binding guard
    -- ends up printing "CONNECTEDL". Quotes are written into the format string instead.
    raise exception
      'phase_c_component %: classification "%" says this component has no way in, and it has one. '
      'The derivation reaches it via %. Derived classification is "%". '
      'Wire the missing leg, or record what is true; do not relabel the row.',
      new.component_id, new.classification, d->>'decided_by', v_derived
      using errcode = '23514';
  end if;

  if new.classification like 'ACTIVE\_%' and not v_reachable then
    raise exception
      'phase_c_component %: classification "%" claims a live entry point and the derivation finds '
      'none — %. Derived classification is "%". '
      'Wire the missing leg, or record what is true; do not relabel the row.',
      new.component_id, new.classification, d->>'decided_by', v_derived
      using errcode = '23514';
  end if;

  if new.activation_state = 'inactive' and v_unexpect then
    raise exception
      'phase_c_component %: activation_state ''inactive'' cannot stop it — %. Derived state is "%". '
      'Wire the missing leg, or record what is true; do not relabel the row.',
      new.component_id, d->>'decided_by', d->>'derived_activation_state'
      using errcode = '23514';
  end if;

  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_event_binding_status(p_event_id text)
 RETURNS TABLE(status text, evidence text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e public.phase_b_event%rowtype;
  v_has_producer boolean; v_has_consumer boolean; v_step text; v_consumer_ok boolean;
begin
  select * into e from public.phase_b_event where event_id = p_event_id;
  if not found then
    return query select 'BROKEN'::text,
      'no row in the frozen Phase B event registry for this binding'::text; return;
  end if;

  -- the consumer role must resolve, or nothing downstream can own the result
  select (select kind from public.fn_phase_c_resolve_actor(e.primary_consumer_role_id)) is not null
    into v_consumer_ok;
  if not coalesce(v_consumer_ok, false) then
    return query select 'BROKEN'::text,
      format('primary consumer %L does not resolve to a canonical actor', e.primary_consumer_role_id);
    return;
  end if;

  -- the emitting leg
  if e.event_name like '%.started' then
    v_has_producer := true; v_has_consumer := true;
    return query select 'CONNECTED'::text, format(
      'producer fn_phase_c_event_ingress / fn_founder_command_submit via fn_phase_c_lifecycle_event(%L,''started''); '
      'durable row phase_c_event_outbox; claim fn_phase_c_outbox_claim (FOR UPDATE SKIP LOCKED); '
      'worker fn_phase_c_outbox_deliver (cron phase_c_outbox_deliver_1min); '
      'consumer fn_phase_c_event_consume -> fn_phase_c_event_ingress creates run, step run and task; '
      'evidence phase_c_event_delivery_attempt', e.workflow_id);
    return;
  end if;

  select s.step_id into v_step
    from public.phase_b_workflow_step s
   where s.workflow_id = e.workflow_id
     and public.fn_phase_c_step_event(s.step_id, 'completed') = p_event_id
   limit 1;
  if v_step is not null then
    return query select 'CONNECTED'::text, format(
      'producer fn_phase_c_step_advance via fn_phase_c_step_event(%L,''completed''); '
      'durable row phase_c_event_outbox; claim fn_phase_c_outbox_claim; '
      'worker fn_phase_c_outbox_deliver; consumer fn_phase_c_event_consume hands the successor '
      'step to its accountable owner through phase_b_handoff; evidence phase_c_event_delivery_attempt',
      v_step);
    return;
  end if;

  -- everything else: the registry describes it, nothing emits it, nothing consumes it
  return query select 'DEFERRED_RUNTIME_IMPLEMENTATION'::text, format(
    'no deployed producer emits %L and fn_phase_c_event_consume has no branch for it; '
    'Phase D must add the emitter at the state change this event names and a consumer branch',
    p_event_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_event_binding_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status text;
begin
  select status into v_status from public.fn_phase_c_event_binding_status(new.event_id);
  if new.connection_status is distinct from v_status then
    raise exception 'phase_c_event_binding %: status %L is not what the legs support (%L). '
                    'Wire the missing leg; do not relabel the row.',
      new.event_id, new.connection_status, v_status using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_event_consume(p_outbox_id bigint)
 RETURNS TABLE(handled boolean, downstream_ref text, result jsonb, reason text)
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select * from public.fn_kernel_event_consume(p_outbox_id);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_event_ingress(p_event_id text, p_business_object_id text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'fn_phase_c_event_ingress is retired: an event records that a state change happened, it does '
    'not cause one. Start work with fn_kernel_workflow_start, or submit a request through '
    'fn_kernel_trigger_submit.'
    using errcode = '23514',
          hint = 'public.kernel_retired_path names the replacement for every retired path.';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_event_runtime_observation(p_event_id text)
 RETURNS TABLE(observation text, outbox_rows bigint, delivered_rows bigint, delivery_attempts bigint, first_seen timestamp with time zone, last_seen timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
           when count(*) filter (where o.status = 'delivered') > 0 then 'OBSERVED_DELIVERED'
           when count(*) > 0                                       then 'EMITTED_NOT_DELIVERED'
           else                                                         'NEVER_OBSERVED'
         end::text,
         count(*)::bigint,
         count(*) filter (where o.status = 'delivered')::bigint,
         (select count(*) from public.phase_c_event_delivery_attempt a
            join public.phase_c_event_outbox o2 on o2.outbox_id = a.outbox_id
           where o2.event_id = p_event_id)::bigint,
         min(o.created_at),
         max(o.created_at)
    from public.phase_c_event_outbox o
   where o.event_id = p_event_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_approval_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- E40. This message was hard-coded to `public.phase_c_founder_approval` while the trigger sits on
  -- phase_c_frozen_subject as well, so a person hitting it was told the wrong table -- and then
  -- advised to "record a NEW row", which until this file was the one door standing open on that
  -- register. It names what it is actually protecting now.
  raise exception '% is append-only and its rows are permanent: % is refused. A founder approval and the frozen subjects it covers are the record that everything else is measured against, so they are never edited or deleted -- record a new row through a migration applied as the owner. (phase_c_approval_immutable)',
    TG_TABLE_NAME, TG_OP
    using errcode = '23514';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_approver_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.approved_by is null then
    return new;
  end if;

  if not exists (
        select 1 from public.phase_c_founder_identity fi
         where fi.active
           and lower(btrim(fi.identity)) = lower(btrim(new.approved_by))) then
    raise exception '%: approved_by % does not resolve to an active identity in public.phase_c_founder_identity. A governance record is approved by the founder or it is not approved. (pccr_approver_not_the_founder)',
      TG_TABLE_NAME, coalesce(nullif(btrim(new.approved_by),''), '(empty)')
      using errcode = '23514';
  end if;

  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_auth_event_is_server_minted()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP = 'DELETE' then
    raise exception 'phase_c_founder_auth_event is append-only: a consumed founder session may not be deleted, because deleting it is how a replay stops looking like one. (pccr_auth_event_append_only)'
      using errcode = '42501';
  end if;

  if TG_OP = 'UPDATE' then
    -- The only legal update is the single-use consumption stamp, in the same transaction that
    -- minted the event.
    if (NEW.event_id, NEW.auth_subject, NEW.identity, NEW.route, NEW.txid, NEW.bound_by,
        NEW.bound_at, NEW.action_class, NEW.object_ref, NEW.decision, NEW.amendment_table_digest,
        NEW.nonce, NEW.issued_at, NEW.expires_at)
       is distinct from
       (OLD.event_id, OLD.auth_subject, OLD.identity, OLD.route, OLD.txid, OLD.bound_by,
        OLD.bound_at, OLD.action_class, OLD.object_ref, OLD.decision, OLD.amendment_table_digest,
        OLD.nonce, OLD.issued_at, OLD.expires_at) then
      raise exception 'phase_c_founder_auth_event: only consumed_at and consumed_by may be updated, and only once. Everything else about a verified session is a fact about the past. (pccr_auth_event_append_only)'
        using errcode = '42501';
    end if;
    if OLD.consumed_at is not null then
      raise exception 'phase_c_founder_auth_event: event % was consumed at % and a single-use session may not be spent twice. (pccr_auth_event_replayed)',
        OLD.event_id, OLD.consumed_at using errcode = '23505';
    end if;
    if OLD.txid is distinct from txid_current() then
      raise exception 'phase_c_founder_auth_event: event % belongs to transaction % and is being consumed in %. A session bound to another transaction is a value a caller typed. (pccr_auth_event_wrong_transaction)',
        OLD.event_id, OLD.txid, txid_current() using errcode = '28000';
    end if;
    return NEW;
  end if;

  -- INSERT.
  if session_user <> 'authenticator' then
    raise exception 'phase_c_founder_auth_event: a founder session may only be minted on the PostgREST connection (session_user authenticator); this call arrives as session_user %, which is the management/migration path and carries no bearer token. Knowing the founder''s auth subject is not being the founder. (pccr_auth_event_untrusted_connection)',
      session_user using errcode = '28000';
  end if;
  if NEW.txid is distinct from txid_current() then
    raise exception 'phase_c_founder_auth_event: an event must name the transaction that mints it (got %, current %) (pccr_auth_event_wrong_transaction)',
      NEW.txid, txid_current() using errcode = '28000';
  end if;
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_identity_human_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.active and new.kind <> 'email' then
    raise exception
      'phase_c_founder_identity: only an email identity may be active; % is kind %',
      new.identity, new.kind
      using errcode = '23514',
            hint = 'A build-mode or service identity must never be enabled as the founder. '
                || 'This is the defect the 16 Aug audit found (FAIL 1).';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_founder_subject_bind(p_subject uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id text; v_ev bigint; v_uid uuid; v_role text;
begin
  -- PCCR-006. THE POSITIVE CONDITION, NOT A DENY-LIST WITH NO THIRD ANSWER.
  -- 'anon' and 'authenticated' were named and 'postgres' was not, so migration SQL bound the
  -- founder's subject with no bearer token in existence. session_user is the connection role; SET
  -- ROLE cannot change it and postgres may not SET SESSION AUTHORIZATION on this project.
  if session_user <> 'authenticator' then
    raise exception 'fn_phase_c_founder_subject_bind: this is the server path. A founder subject may only be bound on the PostgREST connection that verified the bearer token (session_user authenticator); this call arrives as session_user % / current_user %. (pccr_founder_bind_untrusted_connection)',
      session_user, current_user using errcode = '28000';
  end if;

  -- 27 Aug 2026. THE CALLER MAY ONLY BIND ITSELF.
  -- The role check that stood here named 'anon' and stopped. service_role holds EXECUTE through
  -- PostgREST, arrives as session_user 'authenticator', and could hand this door the founder's own
  -- auth_user_id -- which is readable from public.phase_c_founder_identity, the very table this
  -- routine validates against. Knowing a uuid is not holding a session.
  -- AND IT IS NOT current_user THAT SAYS WHO THE CALLER IS. This routine is SECURITY DEFINER, so
  -- current_user is the OWNER — `postgres` — on every call, including anon's. The line that stood
  -- here, `if current_user = 'anon'`, could therefore never be true and had never refused anything;
  -- it was a guard on a condition that cannot occur. The role PostgREST switched to is in the JWT
  -- it verified, and that is what is read.
  v_role := coalesce(
    nullif(btrim(current_setting('request.jwt.claim.role', true)), ''),
    (nullif(btrim(current_setting('request.jwt.claims', true)), '')::jsonb ->> 'role'));
  if coalesce(v_role,'') <> 'authenticated' then
    raise exception 'fn_phase_c_founder_subject_bind: a founder subject is bound by an authenticated user session and by nothing else; this call presents JWT role %. service_role is a server key, not a person, and a key that can name any subject can name his. (pd_founder_bind_not_a_user_session)',
      coalesce(v_role,'(none)') using errcode = '42501';
  end if;

  begin v_uid := auth.uid(); exception when others then v_uid := null; end;
  if v_uid is null then
    raise exception 'fn_phase_c_founder_subject_bind: no verified auth subject on this call. The bind door records a session that already exists; it does not create one. (pd_founder_bind_no_verified_subject)'
      using errcode = '28000';
  end if;

  if p_subject is null then
    raise exception 'fn_phase_c_founder_subject_bind: a verified auth subject is required, and null is not one'
      using errcode = '28000';
  end if;

  -- THE PREDICATE THAT WAS MISSING. p_subject is now an ASSERTION about who the caller is, checked
  -- against the subject PostgREST verified, exactly as p_actor became an assertion in PCCR-003.
  if p_subject <> v_uid then
    raise exception 'fn_phase_c_founder_subject_bind: this call asks to bind subject % and the verified session belongs to %. A caller may bind itself and no one else. (pd_founder_bind_subject_is_not_the_caller)',
      p_subject, v_uid using errcode = '28000';
  end if;

  select f.identity into v_id
    from public.phase_c_founder_identity f
   where f.auth_user_id = p_subject and f.active and f.kind = 'email';
  if v_id is null then
    raise exception 'not the founder: auth subject % does not resolve to an enabled founder identity', p_subject
      using errcode = '28000';
  end if;

  insert into public.phase_c_founder_auth_event
    (auth_subject, identity, route, txid, bound_by)
  values (p_subject, v_id, 'server_verified_subject', txid_current(), current_user)
  returning event_id into v_ev;

  perform set_config('app.phase_c_founder_auth_event', v_ev::text, true);
  return jsonb_build_object('ok', true, 'identity', v_id, 'event_id', v_ev,
    'note','transaction-local; the verifier requires this event to name the current txid');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_freeze_amendment_session_claim_is_verified()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ev      bigint;
  e         public.phase_c_founder_auth_event%rowtype;
  v_moved   boolean;
begin
  -- ---- 0. AN APPROVAL ALREADY GIVEN MAY NOT MOVE ------------------------------------------------
  if TG_OP = 'UPDATE' and OLD.approved_by is not null then
    if (NEW.approved_by, NEW.approved_at, NEW.approval_basis, NEW.approval_route,
        NEW.approval_auth_subject, NEW.approved_amendment_table_path,
        NEW.approved_amendment_table_digest)
       is distinct from
       (OLD.approved_by, OLD.approved_at, OLD.approval_basis, OLD.approval_route,
        OLD.approval_auth_subject, OLD.approved_amendment_table_path,
        OLD.approved_amendment_table_digest) then
      raise exception 'phase_c_freeze_amendment %: the approval columns are a fact about the past and may not be changed once given. Rewriting approved_amendment_table_digest changes which document the founder is recorded as having read. (pccr007_amendment_approval_immutable)',
        OLD.amendment_id using errcode = '42501';
    end if;
    return NEW;   -- an unrelated column moved on an already-approved row
  end if;

  -- ---- 1. IS THIS WRITE MAKING AN APPROVAL CLAIM AT ALL? ----------------------------------------
  v_moved := NEW.approved_by is not null or NEW.approval_basis is not null;
  if TG_OP = 'UPDATE' then
    v_moved := v_moved and
      (NEW.approved_by, NEW.approval_basis) is distinct from (OLD.approved_by, OLD.approval_basis);
  end if;
  if not v_moved then
    return NEW;
  end if;

  -- ---- 2. A WRITTEN INSTRUCTION IS NOT AN APPROVAL, AND IS NOW REFUSED RATHER THAN REPORTED -----
  if NEW.approval_basis = 'WRITTEN_INSTRUCTION' then
    raise exception 'phase_c_freeze_amendment %: WRITTEN_INSTRUCTION may not be written. An approval recorded from a written instruction is not a founder session, and fn_phase_c_freeze_drift has reported that for as long as this column has existed. It is refused here instead. (pccr007_amendment_written_instruction_refused)',
      coalesce(NEW.amendment_id::text,'(new)') using errcode = '28000';
  end if;

  -- ---- 3. THE ONE-TIME COMMAND BOOTSTRAP WAS SPENT BY PCCR-006 ----------------------------------
  if NEW.approval_basis = 'AUTHENTICATED_FOUNDER_COMMAND_BOOTSTRAP' then
    raise exception 'phase_c_freeze_amendment %: AUTHENTICATED_FOUNDER_COMMAND_BOOTSTRAP was used exactly once, by PCCR-006, to approve the change request that created the governance ledger. fn_phase_c_freeze_drift expects exactly one and nothing enforced it. Every approval after that one goes through a verified session. (pccr007_amendment_bootstrap_already_spent)',
      coalesce(NEW.amendment_id::text,'(new)') using errcode = '28000';
  end if;

  -- ---- 4. THE CONNECTION. This is the predicate a set_config cannot forge. ----------------------
  if session_user <> 'authenticator' then
    raise exception 'phase_c_freeze_amendment %: an approval may only be recorded on the PostgREST connection that verified a founder bearer token (session_user authenticator); this call arrives as session_user %. auth.uid() reads request.jwt.claims, which a management or migration connection can set for itself, so the claim is not evidence and the connection is. (pccr007_amendment_untrusted_connection)',
      coalesce(NEW.amendment_id::text,'(new)'), session_user using errcode = '28000';
  end if;

  -- ---- 5. THE VERIFIED SUBJECT, unchanged from PCCR-006 -----------------------------------------
  v_ev := nullif(btrim(current_setting('app.phase_c_founder_auth_event', true)),'')::bigint;
  select * into e from public.phase_c_founder_auth_event
   where event_id = v_ev and txid = txid_current();
  if not found then
    if coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
       is distinct from NEW.approval_auth_subject then
      raise exception 'phase_c_freeze_amendment %: a row may not claim % without a verified session. There is no founder auth event bound to this transaction and auth.uid() does not resolve to the subject the row names. (pccr_amendment_session_claim_unverified)',
        coalesce(NEW.amendment_id::text,'(new)'), NEW.approval_basis using errcode = '28000';
    end if;
    return NEW;
  end if;
  if e.identity is distinct from NEW.approved_by or e.auth_subject is distinct from NEW.approval_auth_subject then
    raise exception 'phase_c_freeze_amendment %: the row is attributed to %/% and the verified session resolved to %/%. (pccr_amendment_session_claim_mismatched)',
      coalesce(NEW.amendment_id::text,'(new)'), NEW.approved_by, NEW.approval_auth_subject,
      e.identity, e.auth_subject using errcode = '28000';
  end if;
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_gate_evaluate(p_gate_id text, p_evidence jsonb)
 RETURNS TABLE(passed boolean, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g public.phase_b_gate%rowtype; v_missing text;
begin
  select * into g from public.phase_b_gate where gate_id = p_gate_id;
  if not found then
    passed := false; reason := format('unknown gate %L — fail closed', p_gate_id); return next; return;
  end if;
  -- Deterministic evidence check: the gate declares what it requires; the caller supplies it.
  -- An absent evidence object is a refusal, never a pass.  pct(got, 0) returning 100 is the
  -- shape of defect this avoids: no evidence is not full evidence.
  if p_evidence is null or jsonb_typeof(p_evidence) <> 'object' or p_evidence = '{}'::jsonb then
    passed := false;
    reason := format('gate %s (%s) requires evidence and none was supplied', g.gate_id, g.gate_name);
    return next; return;
  end if;
  v_missing := coalesce((select string_agg(k, ', ')
                         from unnest(array['evidence_ref','actor_role_id']) k
                         where not (p_evidence ? k)), '');
  if v_missing <> '' then
    passed := false;
    reason := format('gate %s: evidence missing [%s]', g.gate_id, v_missing);
    return next; return;
  end if;
  if not public.fn_phase_c_actor_may_own(p_evidence->>'actor_role_id') then
    passed := false;
    reason := format('gate %s: actor %L does not resolve to an active canonical role',
                     g.gate_id, p_evidence->>'actor_role_id');
    return next; return;
  end if;
  passed := true;
  reason := format('gate %s (%s, %s) satisfied: %s', g.gate_id, g.gate_name, g.gate_type, g.pass_result);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_gates_for_step(p_step_id text)
 RETURNS TABLE(gate_id text, gate_name text, gate_type text, workflow_scope text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select g.gate_id, g.gate_name, g.gate_type, g.workflow_scope
  from public.phase_b_workflow_step s
  join public.phase_b_gate g
    on g.workflow_scope = 'ALL'
    or s.workflow_id = any (string_to_array(replace(g.workflow_scope, ' ', ''), ';'))
  where s.step_id = p_step_id
  order by g.gate_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_governance_decide(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  cr        public.phase_c_change_request%rowtype;
  v_ref     text := nullif(btrim(coalesce(p_input->>'change_request_ref','')),'');
  v_dec     text := upper(nullif(btrim(coalesce(p_input->>'decision','')),''));
  v_digest  text := lower(nullif(btrim(coalesce(p_input->>'approved_amendment_digest','')),''));
  v_path    text := nullif(btrim(coalesce(p_input->>'amendment_table_path','')),'');
  v_reason  text := nullif(btrim(coalesce(p_input->>'reason','')),'');
  v_sub     uuid;
  v_id      text;
  v_route   text;
  v_nonce   text;
  v_ev      bigint;
  v_did     bigint;
  v_msg     bigint;
  v_prior   public.phase_c_governance_decision%rowtype;
begin
  -- ---- 0. THE CONNECTION. A governance decision arrives on the connection that verifies tokens.
  if session_user <> 'authenticator' then
    raise exception 'fn_phase_c_governance_decide: a governance decision may only be recorded on the PostgREST connection that verified a founder bearer token (session_user authenticator); this call arrives as session_user %. Migration and management SQL cannot approve a Phase C change request, which is the defect PCCR-006 exists to close. (pccr_governance_untrusted_connection)',
      session_user using errcode = '28000';
  end if;

  -- ---- 1. THE VERIFIED FOUNDER. Nothing here is read from p_input.
  begin v_sub := auth.uid(); exception when others then v_sub := null; end;
  if v_sub is not null then
    v_route := 'auth.uid()';
  else
    v_ev := nullif(btrim(current_setting('app.phase_c_founder_auth_event', true)),'')::bigint;
    select e.auth_subject into v_sub from public.phase_c_founder_auth_event e
     where e.event_id = v_ev and e.txid = txid_current() and e.action_class is null;
    v_route := 'fn_phase_c_founder_subject_bind';
  end if;
  if v_sub is null then
    raise exception 'fn_phase_c_governance_decide: no verified auth subject on this call. A caller-supplied email, auth subject or route label is not authentication, and neither is a written instruction. (pccr_governance_no_verified_session)'
      using errcode = '28000',
            hint = 'Call /rest/v1/rpc/fn_phase_c_governance_decide with the founder''s bearer token.';
  end if;
  select f.identity into v_id from public.phase_c_founder_identity f
   where f.auth_user_id = v_sub and f.active and f.kind = 'email';
  if v_id is null then
    raise exception 'not the founder: auth subject % does not resolve to an enabled founder identity (pccr_governance_not_the_founder)',
      v_sub using errcode = '28000';
  end if;

  -- ---- 2. THE CALL NAMES EXACTLY WHAT IT DECIDES.
  if v_ref is null or v_dec is null or v_digest is null or v_path is null or v_reason is null then
    raise exception 'fn_phase_c_governance_decide: change_request_ref, decision, approved_amendment_digest, amendment_table_path and reason are all required (got %, %, %, %, %) (pccr_governance_incomplete_call)',
      coalesce(v_ref,'(none)'), coalesce(v_dec,'(none)'),
      coalesce(left(v_digest,12),'(none)'), coalesce(v_path,'(none)'),
      case when v_reason is null then '(none)' else '(given)' end using errcode = '22023';
  end if;
  if p_input ?| array['approved_by','approved_at','approval_basis','approval_route',
                      'approval_auth_subject','disposition','decided_by'] then
    raise exception 'fn_phase_c_governance_decide: approved_by, approved_at, the approval basis, the route, the auth subject and the disposition are DERIVED from the verified session and may not be supplied. A call that states who approved it is stating a conclusion. (pccr_governance_caller_supplied_approval)'
      using errcode = '22023';
  end if;
  if v_digest !~ '^[0-9a-f]{64}$' then
    raise exception 'fn_phase_c_governance_decide: approved_amendment_digest must be the sha256 of the committed amendment table; got % (pccr_governance_bad_digest)',
      left(coalesce(v_digest,'(none)'),20) using errcode = '22023';
  end if;

  select * into cr from public.phase_c_change_request where change_request_ref = v_ref;
  if not found then
    raise exception 'fn_phase_c_governance_decide: no change request % (pccr_governance_unknown_change_request)', v_ref
      using errcode = '23503';
  end if;

  -- ---- 2b. THE DIGEST IS THE ONE HE QUOTED, NOT MERELY SIXTY-FOUR HEX CHARACTERS.
  -- public.founder_command_message is append-only, holds his words verbatim, recomputes its own
  -- sha256, and carries no anon or authenticated grant. A digest he never typed against this
  -- change request is a value a caller chose.
  select m.message_id into v_msg
    from public.founder_command_message m
    join public.phase_c_founder_identity f
      on f.identity = m.founder_identity and f.active and f.kind = 'email'
   where position(v_digest in lower(m.raw_text)) > 0
     and position(lower(v_ref) in lower(m.raw_text)) > 0
   order by m.received_at
   limit 1;
  if v_msg is null then
    raise exception 'fn_phase_c_governance_decide: no founder command message names both % and the digest %…. The founder approves the document he read, and public.founder_command_message is where his words are recorded immutably. A sixty-four character hex string that appears in none of them is a value this call chose, not a document he approved. (pccr007_governance_digest_never_quoted)',
      v_ref, left(v_digest,16) using errcode = '22023';
  end if;

  -- ---- 3. REPLAY IS IDEMPOTENT AND MAKES NO SECOND ROW.
  select * into v_prior from public.phase_c_governance_decision
   where change_request_ref = v_ref and decision = v_dec
     and approved_amendment_table_digest = v_digest;
  if found then
    return jsonb_build_object('ok', true, 'outcome','ALREADY_DECIDED',
      'decision_id', v_prior.decision_id, 'change_request_ref', v_ref, 'decision', v_dec,
      'decided_by', v_prior.decided_by, 'decided_at', v_prior.decided_at,
      'note','this door is idempotent and does not restamp a decision it has already recorded');
  end if;

  -- ---- 4. THE PURPOSE-BOUND, SINGLE-USE SESSION. Minted and spent inside this transaction, so a
  -- failure between minting and writing cannot leave a reusable session behind.
  v_nonce := encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.phase_c_founder_auth_event
    (auth_subject, identity, route, txid, bound_by,
     action_class, object_ref, decision, amendment_table_digest, nonce, issued_at, expires_at)
  values (v_sub, v_id, 'server_verified_subject', txid_current(), current_user,
          'GOVERNANCE_DECISION', v_ref, v_dec, v_digest, v_nonce, now(), now() + interval '5 minutes')
  returning event_id into v_ev;

  update public.phase_c_founder_auth_event
     set consumed_at = now(), consumed_by = 'fn_phase_c_governance_decide'
   where event_id = v_ev;

  -- ---- 5. THE APPEND-ONLY DECISION. Its own trigger re-reads the event and refuses a mismatch.
  insert into public.phase_c_governance_decision
    (change_request_ref, decision, approval_reason, approved_amendment_table_path,
     approved_amendment_table_digest, decided_by, approval_basis, approval_route,
     approval_auth_subject, auth_event_id, nonce, txid)
  values (v_ref, v_dec, v_reason, v_path, v_digest, v_id, 'AUTHENTICATED_FOUNDER_SESSION',
          v_route, v_sub, v_ev, v_nonce, txid_current())
  returning decision_id into v_did;

  return jsonb_build_object('ok', true, 'outcome','DECIDED_IN_VERIFIED_SESSION',
    'decision_id', v_did, 'change_request_ref', v_ref, 'decision', v_dec,
    'decided_by', v_id, 'approval_route', v_route, 'approval_auth_subject', v_sub,
    'approved_amendment_table_path', v_path,
    'approved_amendment_table_digest', v_digest,
    'auth_event_id', v_ev,
    'founder_message_id', v_msg,
    'prior_disposition', cr.disposition);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_governance_decision_applies()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform set_config('app.phase_c_governance_decision', NEW.decision_id::text, true);

  update public.phase_c_change_request
     set disposition             = NEW.decision,
         disposition_reason      = NEW.approval_reason,
         disposition_recorded_at = NEW.decided_at,
         approved_by             = case when NEW.decision = 'APPROVED' then NEW.decided_by end,
         approved_at             = case when NEW.decision = 'APPROVED' then NEW.decided_at end,
         approval_reason         = case when NEW.decision = 'APPROVED' then NEW.approval_reason end,
         approval_basis          = case when NEW.decision = 'APPROVED' then NEW.approval_basis end,
         approval_route          = case when NEW.decision = 'APPROVED' then NEW.approval_route end,
         approval_auth_subject   = case when NEW.decision = 'APPROVED' then NEW.approval_auth_subject end,
         approved_amendment_table_digest
                                 = case when NEW.decision = 'APPROVED' then NEW.approved_amendment_table_digest end,
         governance_decision_id  = case when NEW.decision = 'APPROVED' then NEW.decision_id end
   where change_request_ref = NEW.change_request_ref;

  perform set_config('app.phase_c_governance_decision', '', true);
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_governance_decision_is_session_backed()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e public.phase_c_founder_auth_event%rowtype;
begin
  if TG_OP <> 'INSERT' then
    raise exception 'phase_c_governance_decision is append-only: a recorded governance decision is a fact about the past and may not be % (pccr_governance_decision_append_only)',
      lower(TG_OP) using errcode = '42501';
  end if;

  select * into e from public.phase_c_founder_auth_event where event_id = NEW.auth_event_id;
  if not found then
    raise exception 'phase_c_governance_decision: auth event % does not exist (pccr_governance_no_auth_event)',
      NEW.auth_event_id using errcode = '28000';
  end if;
  if e.txid is distinct from txid_current() or NEW.txid is distinct from txid_current() then
    raise exception 'phase_c_governance_decision: auth event % belongs to transaction % and this decision is being written in %. A session bound to another transaction is not a session. (pccr_governance_wrong_transaction)',
      e.event_id, e.txid, txid_current() using errcode = '28000';
  end if;
  if e.action_class is distinct from 'GOVERNANCE_DECISION' then
    raise exception 'phase_c_governance_decision: auth event % carries action class % and a governance decision requires GOVERNANCE_DECISION. A session issued for one act may not pay for another. (pccr_governance_wrong_action_class)',
      e.event_id, coalesce(e.action_class,'(none)') using errcode = '28000';
  end if;
  if e.object_ref is distinct from NEW.change_request_ref then
    raise exception 'phase_c_governance_decision: auth event % is bound to % and this decision names %. A verified session approves the request it was issued for. (pccr_governance_wrong_object)',
      e.event_id, e.object_ref, NEW.change_request_ref using errcode = '28000';
  end if;
  if e.decision is distinct from NEW.decision then
    raise exception 'phase_c_governance_decision: auth event % is bound to decision % and this row records %. (pccr_governance_wrong_decision)',
      e.event_id, e.decision, NEW.decision using errcode = '28000';
  end if;
  if e.amendment_table_digest is distinct from NEW.approved_amendment_table_digest then
    raise exception 'phase_c_governance_decision: auth event % is bound to amendment-table digest % and this row records %. The founder approves the document he read. (pccr_governance_wrong_digest)',
      e.event_id, left(e.amendment_table_digest,16)||'…', left(NEW.approved_amendment_table_digest,16)||'…'
      using errcode = '28000';
  end if;
  if e.nonce is distinct from NEW.nonce then
    raise exception 'phase_c_governance_decision: the decision names nonce % and its auth event carries % (pccr_governance_wrong_nonce)',
      NEW.nonce, e.nonce using errcode = '28000';
  end if;
  if e.identity is distinct from NEW.decided_by or e.auth_subject is distinct from NEW.approval_auth_subject then
    raise exception 'phase_c_governance_decision: the decision is attributed to %/% and the verified session resolved to %/%. (pccr_governance_wrong_identity)',
      NEW.decided_by, NEW.approval_auth_subject, e.identity, e.auth_subject using errcode = '28000';
  end if;
  if e.expires_at <= now() then
    raise exception 'phase_c_governance_decision: auth event % expired at % (pccr_governance_auth_event_expired)',
      e.event_id, e.expires_at using errcode = '28000';
  end if;
  if e.consumed_at is null then
    raise exception 'phase_c_governance_decision: auth event % has not been consumed. The session is spent before the decision is written, so a failure between the two cannot leave a reusable session behind. (pccr_governance_auth_event_unconsumed)',
      e.event_id using errcode = '28000';
  end if;
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_decide(p_handoff_run_id bigint, p_decision text, p_actor text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare hr public.phase_c_handoff_run%rowtype; v_actor text; v_trace bigint;
begin
  select * into hr from public.phase_c_handoff_run where handoff_run_id = p_handoff_run_id for update;
  if not found then return jsonb_build_object('ok', false, 'error','not_found'); end if;
  if hr.status <> 'open' then
    return jsonb_build_object('ok', false, 'error','already_decided', 'status', hr.status);
  end if;
  select role_id into v_actor from public.fn_phase_c_resolve_actor(p_actor);
  if v_actor is distinct from hr.receiving_role_id then
    return jsonb_build_object('ok', false, 'error','not_the_receiver',
      'receiver', hr.receiving_role_id, 'actor', coalesce(v_actor, p_actor));
  end if;
  if p_decision = 'reject'
     and (coalesce(p_ctx->>'reason','') = '' or coalesce(p_ctx->>'missing','') = '') then
    return jsonb_build_object('ok', false, 'error','rejection_must_be_specific',
      'message','A rejection must state the exact missing or invalid item and the return owner.');
  end if;

  update public.phase_c_handoff_run set
    status = case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    rejection_reason = case when p_decision = 'accept' then '' else p_ctx->>'reason' end,
    missing_items = case when p_decision = 'accept' then '' else p_ctx->>'missing' end,
    return_owner_role_id = case when p_decision = 'accept' then return_owner_role_id
                                else coalesce(nullif(p_ctx->>'return_owner',''), return_owner_role_id, sending_role_id) end
  where handoff_run_id = p_handoff_run_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
    'subject_kind','handoff', 'subject_ref', p_handoff_run_id::text, 'run_id', hr.run_id,
    'actor_role_id', v_actor, 'state_before','open',
    'state_after', case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    'status','sealed'));
  return jsonb_build_object('ok', true, 'handoff_run_id', p_handoff_run_id,
    'status', case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    'accountable_now', (select accountable_until_accept_role_id from public.phase_c_handoff_run
                        where handoff_run_id = p_handoff_run_id),
    'trace_id', v_trace);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_overdue()
 RETURNS TABLE(handoff_run_id bigint, handoff_id text, sender text, receiver text, due_at timestamp with time zone, hours_late numeric)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select h.handoff_run_id, h.handoff_id, h.sending_role_id, h.receiving_role_id, h.due_at,
         round(extract(epoch from (now() - h.due_at)) / 3600.0, 1)
  from public.phase_c_handoff_run h
  where h.status = 'open' and h.due_at is not null and h.due_at < now()
  order by h.due_at;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_packet_valid(p_handoff_id text, p_packet jsonb)
 RETURNS TABLE(valid boolean, missing text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare h public.phase_b_handoff%rowtype; v_missing text;
begin
  select * into h from public.phase_b_handoff where handoff_id = p_handoff_id;
  if not found then
    valid := false; missing := format('unknown handoff %L — fail closed', p_handoff_id); return next; return;
  end if;
  if p_packet is null or jsonb_typeof(p_packet) <> 'object' then
    valid := false; missing := 'no packet supplied'; return next; return;
  end if;
  v_missing := coalesce((select string_agg(k, ', ')
    from unnest(array['business_object_id','object_version','output','evidence_refs','requested_action']) k
    where not (p_packet ? k)), '');
  valid := (v_missing = '');
  missing := v_missing;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_handoff_sender_retains()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    if new.accountable_until_accept_role_id is distinct from new.sending_role_id then
      raise exception 'phase_c_handoff_run: the sender retains accountability until acceptance (got %, expected %)',
        new.accountable_until_accept_role_id, new.sending_role_id using errcode = '23514';
    end if;
    if not public.fn_phase_c_actor_may_own(new.sending_role_id)
       or not public.fn_phase_c_actor_may_own(new.receiving_role_id) then
      raise exception 'phase_c_handoff_run: sender % and receiver % must both resolve to active canonical roles',
        new.sending_role_id, new.receiving_role_id using errcode = '23514';
    end if;
    return new;
  end if;
  if old.status = 'open' and new.status = 'accepted' then
    new.accountable_until_accept_role_id := new.receiving_role_id;
    new.decided_at := now();
  elsif old.status = 'open' and new.status = 'rejected' then
    new.accountable_until_accept_role_id := coalesce(nullif(new.return_owner_role_id, ''), old.sending_role_id);
    new.decided_at := now();
  elsif old.status <> new.status and old.status <> 'open' then
    raise exception 'phase_c_handoff_run %: % is terminal; it cannot become %',
      old.handoff_run_id, old.status, new.status using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_historical_repair_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_c_historical_repair is append-only: % on repair_id % is refused',
    tg_op, coalesce(old.repair_id::text, '?')
    using errcode = '23514',
          hint = 'This table is the record of which historical records were defective, why, and '
              || 'what was done about them. A correction is a NEW row that names the repair_id it '
              || 'corrects in its evidence, written as its own migration — never an edit to the '
              || 'row that stated the original finding.';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_invariants()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_bad bigint; v_pop bigint;
  v_deployed text[];
begin
  -- every routine any binding row names, so a binding cannot claim an undeployed function
  select array_agg(distinct p.proname) into v_deployed
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.proname like 'fn_phase_c%' or p.proname like 'fn_founder_command%';

  -- ---------------------------------------------------------------- organisation properties
  -- 4 SEP 2026 (Phase E): the five rows that stood here compared production to org_phase_baseline —
  -- fn_phase_a_baseline_drift(), fn_phase_b_baseline_drift() and three frozen counts. The founder
  -- removed every phase freeze on 2 Sep, so a board that reddens when the organisation legitimately
  -- changes protected nothing and reddened for bookkeeping. What those rows DEFENDED is a property,
  -- asserted here directly: the organisation has no structural violation (every active department
  -- has a head, every canonical role resolves, no cycle in the reporting graph — see
  -- fn_phase_a_organization_violations), and every effective Phase B erratum is resolved.
  check_name := 'organization_structural_violations'; expected := '0';
  actual := (select count(*)::text from public.fn_phase_a_organization_violations());
  ok := actual = expected; return next;

  check_name := 'phase_b_unresolved_errata'; expected := '0';
  actual := (select count(*)::text from public.fn_phase_b_effective_errata() where not resolved);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- binding coverage
  check_name := 'roles_bound';
  expected := (select count(*)::text from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay');
  actual := (select count(*)::text from public.phase_c_role_binding where connection_status = 'CONNECTED');
  ok := actual = expected; return next;

  check_name := 'roles_without_binding'; expected := '0';
  actual := (select count(*)::text from public.org_role r
             where r.status='active' and r.runtime_mode <> 'knowledge_overlay'
               and not exists (select 1 from public.phase_c_role_binding b
                               where b.canonical_role_id = r.role_id
                                  or b.canonical_role_id in (select alias from public.org_role_alias a where a.role_id = r.role_id)));
  ok := actual = expected; return next;

  check_name := 'overlays_bound';
  expected := (select count(*)::text from public.org_role where status='active' and runtime_mode = 'knowledge_overlay');
  actual := (select count(*)::text from public.phase_c_overlay_binding where connection_status = 'CONNECTED');
  ok := actual = expected; return next;

  check_name := 'overlay_bindings_resolve'; expected := '0';
  actual := (select count(*)::text from public.phase_c_overlay_binding b
             where not exists (select 1 from public.org_role r
                               where r.role_id = b.live_role_id and r.status='active'
                                 and r.runtime_mode='knowledge_overlay'));
  ok := actual = expected; return next;

  check_name := 'workflows_bound';
  expected := (select count(*)::text from public.phase_b_workflow);
  actual := (select count(*)::text from public.phase_c_workflow_binding);
  ok := actual = expected; return next;

  check_name := 'workflows_without_binding'; expected := '0';
  actual := (select count(*)::text from public.phase_b_workflow w
             where not exists (select 1 from public.phase_c_workflow_binding b where b.workflow_id = w.workflow_id));
  ok := actual = expected; return next;

  check_name := 'steps_bound_or_classified';
  expected := (select count(*)::text from public.phase_b_workflow_step);
  actual := (select count(*)::text from public.phase_c_step_binding);
  ok := actual = expected; return next;

  check_name := 'steps_without_binding'; expected := '0';
  actual := (select count(*)::text from public.phase_b_workflow_step s
             where not exists (select 1 from public.phase_c_step_binding b where b.step_id = s.step_id));
  ok := actual = expected; return next;

  -- A deferral is only acceptable with an owner, a safe entry boundary and the Phase D work.
  check_name := 'deferred_steps_without_owner_or_action'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding
             where connection_status = 'DEFERRED_RUNTIME_IMPLEMENTATION'
               and (accountable_role_id = '' or canonical_runtime_handler = '' or phase_d_action = ''));
  ok := actual = expected; return next;

  -- "Resolves" here means the FROZEN Phase B rule, not the narrower "is a standing employee":
  -- exactly one of the 257 steps (W14-S05, an analysis step in W14) is owned by the
  -- relevant_category_overlay placeholder, which master spec §12 permits for an analysis step in
  -- W05/W06/W07/W10/W14.  fn_phase_c_step_owner_valid encodes that and nothing wider; the
  -- absolute "an overlay may never own a TASK" guard is separate and unchanged.
  check_name := 'step_owners_resolve'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding b
             where not public.fn_phase_c_step_owner_valid(b.step_id, b.accountable_role_id));
  ok := actual = expected; return next;

  check_name := 'steps_owned_by_overlay_outside_declared_scope'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding b
             join public.phase_b_workflow_step s on s.step_id = b.step_id
             where not public.fn_phase_c_actor_may_own(b.accountable_role_id)
               and not (s.step_type = 'analysis' and s.workflow_id in ('W05','W06','W07','W10','W14')));
  ok := actual = expected; return next;

  check_name := 'handoffs_bound';
  expected := (select count(*)::text from public.phase_b_handoff);
  actual := (select count(*)::text from public.phase_c_handoff_binding);
  ok := actual = expected; return next;

  check_name := 'handoffs_without_binding'; expected := '0';
  actual := (select count(*)::text from public.phase_b_handoff h
             where not exists (select 1 from public.phase_c_handoff_binding b where b.handoff_id = h.handoff_id));
  ok := actual = expected; return next;

  check_name := 'events_classified';
  expected := (select count(*)::text from public.phase_b_event);
  actual := (select count(*)::text from public.phase_c_event_binding);
  ok := actual = expected; return next;

  check_name := 'events_without_producer_or_consumer'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_binding
             where outbox_writer = '' or delivery_worker = '' or dedupe_key = '');
  ok := actual = expected; return next;

  check_name := 'gates_classified';
  expected := (select count(*)::text from public.phase_b_gate);
  actual := (select count(*)::text from public.phase_c_gate_binding);
  ok := actual = expected; return next;

  check_name := 'rules_classified';
  expected := (select count(*)::text from public.phase_b_business_rule);
  actual := (select count(*)::text from public.phase_c_rule_binding);
  ok := actual = expected; return next;

  -- Every routine a binding names must actually be deployed.  This is the check that stops a
  -- binding CSV from being a document: it re-reads pg_proc.
  check_name := 'bindings_naming_undeployed_routines'; expected := '0';
  actual := (
    with named as (
      select distinct (regexp_match(x, 'public\.(fn_[a-z0-9_]+)'))[1] as fn
      from (
        select gate_enforcer x from public.phase_c_step_binding
        union all select authority_enforcer from public.phase_c_step_binding
        union all select review_enforcer from public.phase_c_step_binding
        union all select event_emitter from public.phase_c_step_binding
        union all select handoff_writer from public.phase_c_step_binding
        union all select canonical_runtime_handler from public.phase_c_step_binding
        union all select resolver_path from public.phase_c_role_binding
        union all select task_receiver_path from public.phase_c_role_binding
        union all select authority_binding_path from public.phase_c_role_binding
        union all select review_binding_path from public.phase_c_role_binding
        union all select knowledge_scope_path from public.phase_c_role_binding
        union all select tool_policy_path from public.phase_c_role_binding
        union all select invocation_entrypoint from public.phase_c_overlay_binding
        union all select runtime_entrypoint from public.phase_c_workflow_binding
        union all select event_outbox_writer from public.phase_c_workflow_binding
        union all select runtime_writer from public.phase_c_handoff_binding
        union all select runtime_receiver from public.phase_c_handoff_binding
        union all select packet_schema_validator from public.phase_c_handoff_binding
        union all select sla_timer_handler from public.phase_c_handoff_binding
        union all select enforcement_function from public.phase_c_gate_binding
        union all select enforcement_function from public.phase_c_rule_binding
      ) s where x is not null
    )
    select count(*)::text from named
    where fn is not null
      and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                      where n.nspname='public' and p.proname = named.fn));
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- runtime accountability
  check_name := 'components_inventoried'; expected := '>=1794';
  actual := (select count(*)::text from public.phase_c_component);
  ok := (select count(*) from public.phase_c_component) >= 1794; return next;  -- re-baselined 2026-09-02: 13 phase-freeze trigger components removed by founder order

  check_name := 'active_state_changing_without_role'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and accountable_role_id = '');
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_system_actor'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and canonical_system_actor = '');
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_scope'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and workflow_id = '');
  ok := actual = expected; return next;

  -- WAS: where classification = '' — the empty string, which no row has ever held, while 286 rows
  -- carried the literal 'NO_CALLER_UNCLASSIFIED' and 99 of those were active and state-changing.
  -- The check now measures the population gate 4 actually names.
  check_name := 'unclassified_components'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and classification in ('', 'NO_CALLER_UNCLASSIFIED'));
  ok := actual = expected; return next;

  check_name := 'unclassified_edge_functions'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where component_type = 'edge_function'
               and activation_state not in ('inactive','disabled')
               and classification in ('', 'NO_CALLER_UNCLASSIFIED'));
  ok := actual = expected; return next;

  check_name := 'unclassified_db_functions_and_triggers'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where component_type in ('database_function','database_trigger') and classification = '');
  ok := actual = expected; return next;

  check_name := 'unclassified_cron_jobs'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where component_type = 'cron_job' and classification = '');
  ok := actual = expected; return next;

  check_name := 'generic_owner_used'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where accountable_role_id in ('Director','director','service_role','pg_cron','postgres','system','admin','code_runner','unknown',''));
  ok := actual = expected; return next;

  check_name := 'component_owners_resolve'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component c
             where not public.fn_phase_c_actor_may_own(c.accountable_role_id));
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- founder autonomy
  check_name := 'non_refund_founder_approvals'; expected := '0';
  actual := public.fn_phase_c_non_refund_founder_approvals()::text;
  ok := actual = expected; return next;

  check_name := 'action_classes_requiring_founder_approval'; expected := '1';
  actual := (select count(*)::text from public.phase_c_action_class where founder_approval_required);
  ok := actual = expected; return next;

  check_name := 'the_founder_approval_class_is_refund_decision'; expected := 'refund_decision';
  actual := coalesce((select action_class from public.phase_c_action_class where founder_approval_required), 'NONE');
  ok := actual = expected; return next;

  check_name := 'refund_executions_without_founder_decision'; expected := '0';
  actual := (select count(*)::text from public.phase_c_refund_decision
             where executed_at is not null and decision <> 'approved');
  ok := actual = expected; return next;

  check_name := 'refund_executor_equals_reconciler'; expected := '0';
  actual := (select count(*)::text from public.phase_c_refund_decision
             where executor_role_id = reconciler_role_id);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- founder commands
  check_name := 'founder_messages_without_command'; expected := '0';
  actual := (select count(*)::text from public.founder_command_message m
             where not exists (select 1 from public.founder_command c where c.message_id = m.message_id));
  ok := actual = expected; return next;

  check_name := 'routed_commands_without_tasks'; expected := '0';
  actual := (select count(*)::text from public.founder_command c
             where c.state in ('tasks_created','in_progress','partially_blocked','completed')
               and c.intent_id not in ('CMD-STATUS','CMD-CANCEL','CMD-REPRIORITIZE','CMD-EXPLAIN')
               and c.outcome <> 'REFUND_APPROVAL'
               and not exists (select 1 from public.founder_command_task_link l where l.command_id = c.command_id));
  ok := actual = expected; return next;

  check_name := 'ambiguous_commands_that_created_tasks'; expected := '0';
  actual := (select count(*)::text from public.founder_command c
             where c.intent_id = 'AMBIGUOUS'
               and exists (select 1 from public.founder_command_task_link l where l.command_id = c.command_id));
  ok := actual = expected; return next;

  check_name := 'command_tasks_without_canonical_owner'; expected := '0';
  actual := (select count(*)::text from public.phase_c_task t
             where t.command_id is not null and not public.fn_phase_c_actor_may_own(t.accountable_role_id));
  ok := actual = expected; return next;

  check_name := 'command_plans_without_ceo_owner'; expected := '0';
  actual := (select count(*)::text from public.founder_command where command_owner_role_id <> 'ceo');
  ok := actual = expected; return next;

  check_name := 'duplicate_command_from_same_idempotency_key'; expected := '0';
  actual := (select coalesce(sum(n - 1), 0)::text from (
               select count(*) n from public.founder_command_message group by client_idempotency_key having count(*) > 1) s);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- authority and review
  check_name := 'creator_reviewer_collisions'; expected := '0';
  actual := (select count(*)::text from public.phase_c_task
             where reviewer_required and not public.fn_phase_c_reviewer_independent(accountable_role_id, reviewer_role_id));
  ok := actual = expected; return next;

  check_name := 'step_bindings_with_self_review'; expected := '0';
  actual := (select count(*)::text from public.phase_c_step_binding
             where independent_reviewer_role_id <> ''
               and not public.fn_phase_c_reviewer_independent(accountable_role_id, independent_reviewer_role_id));
  ok := actual = expected; return next;

  check_name := 'overlay_owning_a_task'; expected := '0';
  actual := (select count(*)::text from public.phase_c_task t
             where (select kind from public.fn_phase_c_resolve_actor(t.accountable_role_id)) = 'overlay');
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- traces
  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'completed_commands_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.founder_command where state in ('completed','cancelled','failed','refused','superseded');
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'closed_tasks_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_task where closed_at is not null;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'completed_step_runs_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_workflow_step_run where state = 'completed';
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- DENOMINATOR-AWARE. This reported 0 over a table that held 0 rows, which is not coverage.
  check_name := 'handoff_runs_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_handoff_run;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;
  -- (the shared tail below is skipped for this check)

  -- ---------------------------------------------------------------- idempotency and delivery
  check_name := 'duplicate_outbox_dedupe_values'; expected := '0';
  actual := (select coalesce(sum(n - 1), 0)::text from (
               select count(*) n from public.phase_c_event_outbox group by event_id, dedupe_value having count(*) > 1) s);
  ok := actual = expected; return next;

  check_name := 'delivered_without_downstream_record'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox o
             where o.status = 'delivered'
               and not exists (select 1 from public.phase_c_event_delivery_attempt a
                               where a.outbox_id = o.outbox_id and a.ok and a.downstream_ref <> ''));
  ok := actual = expected; return next;

  check_name := 'retry_erased_the_first_failure'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox
             where attempts > 1 and status = 'delivered' and first_failure is null
               and exists (select 1 from public.phase_c_event_delivery_attempt a
                           where a.outbox_id = phase_c_event_outbox.outbox_id and not a.ok));
  ok := actual = expected; return next;

  check_name := 'duplicate_task_idempotency_keys'; expected := '0';
  actual := (select coalesce(sum(n - 1), 0)::text from (
               select count(*) n from public.phase_c_task group by idempotency_key having count(*) > 1) s);
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- cost
  check_name := 'paid_inference_since_phase_c_started'; expected := '0';
  -- WAS anchored to max(recorded_at) from phase_c_package_erratum: recording any new erratum moved
  -- the window forward and the check went green over whatever spend it had just stepped over, and
  -- emptying that table moved the anchor to now()-1 day. The start of Phase C is a fixed instant,
  -- and BOTH cost ledgers are counted, not one.
  -- 4 SEP 2026: a row in a cost ledger is not a paid call. Since the company loop restarted, a HELD
  -- call writes an ai_cost_log row with model_used = 'none', cost 0 and no provider round trip
  -- (the gate said so in model_selected_because), and this line counted it as paid inference.
  -- "Paid" means a provider was reached: tokens, cost or an HTTP status on the attempt.
  actual := ((select count(*) from public.ai_cost_log
               where occurred_at > timestamptz '2026-08-15 02:51:36+00'
                 and (coalesce(cost_aed, 0) > 0 or coalesce(prompt_tokens, 0) > 0 or coalesce(model_used, 'none') <> 'none'))
           + (select count(*) from public.llm_attempt
               where created_at > timestamptz '2026-08-15 02:51:36+00'
                 and (coalesce(cost_aed, 0) > 0 or coalesce(prompt_tokens, 0) > 0 or http_status is not null)))::text;
  ok := actual = expected; return next;

  check_name := 'openrouter_routes_open'; expected := '0';
  actual := (select count(*)::text from public.llm_route_health where open_until <= now());
  ok := actual = expected; return next;

  -- ---------------------------------------------------------------- correction 2026-08-16
  -- Every one of these exists because the audit found the thing it measures, and found no check
  -- that could have seen it.

  check_name := 'tasks_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop from public.phase_c_task;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;

  check_name := 'workflow_runs_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop
    from public.phase_c_workflow_run;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;

  check_name := 'outbox_rows_without_trace'; expected := '0 of >0';
  select count(*) filter (where trace_id is null), count(*) into v_bad, v_pop
    from public.phase_c_event_outbox;
  actual := v_bad::text || ' of ' || v_pop::text;
  ok := (v_bad = 0 and v_pop > 0); return next;

  -- A command whose root trace describes a different moment than the command itself.
  check_name := 'commands_ahead_of_their_trace'; expected := '0';
  actual := (select count(*)::text from public.founder_command c
             join public.phase_c_trace t on t.trace_id = c.trace_id
             where t.state_after is distinct from c.state);
  ok := actual = expected; return next;

  -- The founder-command event must name the workflow the command actually selected.
  -- `superseded` rows are excluded because that status IS the finding: three rows emitted before
  -- the fix are quarantined there, unreachable by the claim (which takes only pending/retry_wait)
  -- and carrying the reason on the row. The companion check below makes that quarantine cost
  -- something, so this exclusion cannot become a hiding place.
  check_name := 'outbox_events_naming_another_workflow'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox o
             where o.payload ? 'command_id' and o.status <> 'superseded'
               and not exists (select 1 from public.founder_command_workflow_link l2
                               where l2.command_id = (o.payload->>'command_id')::bigint
                                 and l2.workflow_id = o.workflow_id));
  ok := actual = expected; return next;

  check_name := 'outbox_superseded_without_a_stated_reason'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox
             where status = 'superseded' and coalesce(btrim(last_error),'') = '');
  ok := actual = expected; return next;

  -- The queue has to have been drained by something, at least once.
  check_name := 'outbox_delivery_attempts_exist'; expected := '>0 when the outbox is non-empty';
  select count(*) into v_pop from public.phase_c_event_outbox;
  select count(*) into v_bad from public.phase_c_event_delivery_attempt;
  actual := v_bad::text || ' attempt(s) for ' || v_pop::text || ' outbox row(s)';
  ok := (v_pop = 0 or v_bad > 0); return next;

  check_name := 'outbox_rows_stuck_pending_over_an_hour'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox
             where status = 'pending' and created_at < now() - interval '1 hour');
  ok := actual = expected; return next;

  check_name := 'outbox_dead_letter'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_outbox where status = 'dead_letter');
  ok := actual = expected; return next;

  -- An event binding may only claim CONNECTED when the derivation agrees.
  check_name := 'event_bindings_claiming_more_than_the_legs_support'; expected := '0';
  actual := (select count(*)::text from public.phase_c_event_binding b
             where b.connection_status
                   is distinct from (select status from public.fn_phase_c_event_binding_status(b.event_id)));
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_authority'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and coalesce(authority_class,'') = '');
  ok := actual = expected; return next;

  check_name := 'active_state_changing_without_trace_policy'; expected := '0';
  actual := (select count(*)::text from public.phase_c_component
             where mutates_state and activation_state not in ('inactive','disabled')
               and coalesce(trace_policy_id,'') = '');
  ok := actual = expected; return next;

  -- A clarification the founder can never close was the seventh audit failure.
  check_name := 'clarification_required_has_an_exit'; expected := '2';
  actual := (select count(*)::text from public.phase_c_command_transition
             where from_state = 'clarification_required');
  ok := actual = expected; return next;

  return;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_kernel_epoch_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_c_kernel_epoch is append-only: % on epoch % refused. The instant that separates new '
    'work from historical work is not allowed to move — a window that follows its own newest row '
    'reports green over the period it just stepped across.',
    tg_op, coalesce(old.epoch_id, new.epoch_id)
    using errcode = '23514';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_lifecycle_event(p_workflow_id text, p_lifecycle text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select e.event_id
    from public.phase_b_event e
   where e.workflow_id = nullif(btrim(coalesce(p_workflow_id, '')), '')
     and e.event_name like '%.' || lower(btrim(coalesce(p_lifecycle, '')))
   order by e.event_id
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_no_new_founder_approval_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'Phase C founder autonomy: % is not an approval path any more. The founder receives exactly one routine manual approval, a specific refund decision. Route this to the internal authority gate (fn_phase_c_authority_check) instead.',
    tg_table_name using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_non_refund_founder_approvals()
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select (select count(*) from public.founder_approval_request
           where action_class <> 'refund_decision' and state = 'pending')
       + (select count(*) from public.founder_release_approval where approved_at is null)
       + (select count(*) from public.procurement_approval_request where status = 'pending');
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_outbox_claim(p_limit integer DEFAULT 20)
 RETURNS SETOF phase_c_event_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  update public.phase_c_event_outbox o set status = 'claimed', claimed_at = now(), attempts = o.attempts + 1
  where o.outbox_id in (
    select outbox_id from public.phase_c_event_outbox
    where status in ('pending','retry_wait') and next_attempt_at <= now()
    order by outbox_id for update skip locked limit greatest(1, coalesce(p_limit, 20)))
  returning *;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_outbox_deliver(p_limit integer DEFAULT 25, p_worker text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.fn_kernel_outbox_deliver(p_limit, coalesce(p_worker, '') || ' (via retired fn_phase_c_outbox_deliver)');
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_output_validate(p_contract text, p_output jsonb)
 RETURNS TABLE(valid boolean, reason text)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_required text[]; v_missing text[]; v_txt text;
begin
  if p_output is null then
    valid := false; reason := 'null output is not a successful result'; return next; return;
  end if;
  if jsonb_typeof(p_output) <> 'object' then
    valid := false; reason := format('output is %s, expected an object', jsonb_typeof(p_output)); return next; return;
  end if;
  v_required := array['status','output'];
  select array_agg(k) into v_missing from unnest(v_required) k where not (p_output ? k);
  if v_missing is not null then
    valid := false; reason := format('required fields missing [%s]', array_to_string(v_missing, ', '));
    return next; return;
  end if;
  if coalesce(p_output->>'truncated', 'false') = 'true'
     or coalesce(p_output->>'stop_reason', '') in ('length','max_tokens','output_limit')
     or coalesce(p_output->>'incomplete', 'false') = 'true' then
    valid := false; reason := 'output carries an explicit truncation or output-limit marker'; return next; return;
  end if;
  v_txt := coalesce(p_output->>'output', '');
  if v_txt <> '' and right(v_txt, 3) = '...' and length(v_txt) > 16 then
    valid := false; reason := 'output ends in an unresolved continuation marker'; return next; return;
  end if;
  if coalesce(p_output->>'status','') not in ('ok','success','completed','refused','empty') then
    valid := false; reason := format('status %L is not an allowed output status', p_output->>'status');
    return next; return;
  end if;
  valid := true; reason := format('output valid against contract %s', coalesce(p_contract, 'default'));
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_overlay_invoke(p_overlay_id text, p_ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare b public.phase_c_overlay_binding%rowtype; v_trace bigint; v_missing text;
begin
  select * into b from public.phase_c_overlay_binding where overlay_id = p_overlay_id;
  if not found then
    select * into b from public.phase_c_overlay_binding
      where live_role_id = (select role_id from public.fn_phase_c_resolve_actor(p_overlay_id));
  end if;
  if not found then
    return jsonb_build_object('ok', false, 'error','unknown_overlay', 'overlay_id', p_overlay_id);
  end if;
  v_missing := coalesce((select string_agg(k, ', ') from unnest(array['inquiry_id']) k
                         where not (coalesce(p_ctx,'{}'::jsonb) ? k)), '');
  v_trace := public.fn_phase_c_trace_write('TRACE-CATEGORY-ADVICE', jsonb_build_object(
    'subject_kind','overlay', 'subject_ref', b.overlay_id,
    'actor_role_id', b.live_role_id, 'status', case when v_missing = '' then 'sealed' else 'open' end,
    'evidence_refs', coalesce(p_ctx->'evidence_refs','[]'::jsonb)));
  return jsonb_build_object(
    'ok', v_missing = '', 'overlay_id', b.overlay_id, 'live_role_id', b.live_role_id,
    'inquiry_id', p_ctx->>'inquiry_id',
    'retrieved_fields', coalesce(p_ctx->'retrieved_fields','[]'::jsonb),
    'never_infer_checks', jsonb_build_array('quantity','specification','delivery_date','budget'),
    'missing_fields', v_missing,
    'return_owner', b.result_returns_to_role_id,
    'may_dispatch', false,
    'status', case when v_missing = '' then 'success' else 'empty' end,
    'trace_id', v_trace);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_overlay_may_not_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_kind text;
begin
  select kind into v_kind from public.fn_phase_c_resolve_actor(new.accountable_role_id);
  if v_kind = 'overlay' then
    raise exception 'phase_c_task: category overlay % may advise but may never own a task or hold dispatch authority. Invoke it with fn_phase_c_overlay_invoke and return its advice to a canonical owner. (pd_overlay_cannot_own_task)',
      new.accountable_role_id using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_readonly_exemption_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.trace_policy_id <> all (array['TRACE-MONITORING','TRACE-INFRASTRUCTURE']) then
    return new;
  end if;

  if new.mutates_state then
    raise exception
      'phase_c_component %: mutates_state is true and trace_policy_id is "%". A component that '
      'changes business state may not use the read-only exemption. TRACE-INFRASTRUCTURE is scoped '
      'to "execution that changes no business state and produces no official output" and '
      'TRACE-MONITORING to "read-only health probes". Trace the execution, or record honestly '
      'that it mutates and leave it on TRACE-SYSTEM-EXECUTION.',
      new.component_id, new.trace_policy_id
      using errcode = '23514';
  end if;

  if not exists (select 1 from public.phase_c_component_trace_exemption e
                  where e.component_id = new.component_id
                    and e.exempt_to_policy = new.trace_policy_id) then
    raise exception
      'phase_c_component %: no exemption recorded for policy "%". The policy allows completion '
      'without a trace only YES_WITH_DOCUMENTED_REASON, so the document is the precondition, not '
      'the paperwork. Insert the reason, the source measurement and the derivation into '
      'phase_c_component_trace_exemption first.',
      new.component_id, new.trace_policy_id
      using errcode = '23514';
  end if;

  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_refund_decision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  perform public.fn_phase_c_require_founder(new.decided_by);   -- raises 28000 for anyone else

  if new.executed_at is not null and new.decision <> 'approved' then
    raise exception 'phase_c_refund_decision %: execution recorded against a % decision',
      new.decision_id, new.decision using errcode = '23514';
  end if;
  if new.reconciled_at is not null and new.executed_at is null then
    raise exception 'phase_c_refund_decision %: reconciled before it was executed', new.decision_id
      using errcode = '23514';
  end if;
  if new.executor_role_id is not null and new.reconciler_role_id is not null
     and new.executor_role_id = new.reconciler_role_id then
    raise exception 'phase_c_refund_decision %: the executor and the reconciler are the same role (%)',
      new.decision_id, new.executor_role_id using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_refund_decision_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception
      'phase_c_refund_decision %: a founder refund decision cannot be deleted', old.decision_id
      using errcode = '23514',
            hint = 'A decision that changed is a NEW row citing the old one in '
                || 'supersedes_decision_id, with supersession_reason. The record of what was '
                || 'decided, by whom and when is the point of the table.';
  end if;

  -- The decision itself is frozen. Only the post-decision execution record may be filled in, and
  -- only once, and only from NULL: an executor cannot rewrite who approved, or why, or when.
  if new.decided_by  is distinct from old.decided_by
     or new.decision is distinct from old.decision
     or new.reason   is distinct from old.reason
     or new.decided_at is distinct from old.decided_at
     or new.request_id is distinct from old.request_id then
    raise exception
      'phase_c_refund_decision %: the decision is append-only; supersede it, do not edit it',
      old.decision_id
      using errcode = '23514',
            hint = 'Insert a NEW decision whose supersedes_decision_id points at this one.';
  end if;

  if old.executed_at   is not null and new.executed_at   is distinct from old.executed_at   then
    raise exception 'phase_c_refund_decision %: executed_at is written once', old.decision_id using errcode = '23514';
  end if;
  if old.reconciled_at is not null and new.reconciled_at is distinct from old.reconciled_at then
    raise exception 'phase_c_refund_decision %: reconciled_at is written once', old.decision_id using errcode = '23514';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_refund_execution_requires_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_money_moved constant text[] := array['approved','processing','succeeded'];
  -- Named originators of money this platform did not move. A refund Stripe already issued is a
  -- FACT to be recorded, not a request to be approved; refusing the row would delete our only
  -- record of real money leaving, which is worse than admitting it.
  v_external    constant text[] := array['stripe_webhook','stripe_dashboard','stripe'];
  d public.phase_c_refund_decision%rowtype;
begin
  if not (NEW.status = any(v_money_moved)) then return NEW; end if;
  if tg_op = 'UPDATE' and OLD.status = any(v_money_moved)
     and NEW.refund_decision_id is not distinct from OLD.refund_decision_id then
    -- already past this boundary and not changing which decision it cites
    return NEW;
  end if;

  if lower(coalesce(NEW.requested_by,'')) = any(v_external) then
    return NEW;   -- counted separately by fn_kernel_refund_ledger_state, never as founder-approved
  end if;

  if NEW.refund_decision_id is null then
    raise exception 'refunds %: a platform-originated refund may not reach status % without naming the founder decision that authorised it. His ruling of 17 Aug 2026 is that every refund needs him, at any amount. Record one with fn_kernel_refund_decision_record. (pd_refund_execution_without_founder_decision)',
      coalesce(NEW.id::text,'(new)'), NEW.status using errcode = '23514';
  end if;

  select * into d from public.phase_c_refund_decision where decision_id = NEW.refund_decision_id;
  if not found or d.decision <> 'approved' then
    raise exception 'refunds %: decision % is %, which does not authorise a refund. (pd_refund_execution_without_founder_decision)',
      coalesce(NEW.id::text,'(new)'), NEW.refund_decision_id,
      coalesce(d.decision,'absent') using errcode = '23514';
  end if;
  if exists (select 1 from public.phase_c_refund_decision s
              where s.supersedes_decision_id = NEW.refund_decision_id) then
    raise exception 'refunds %: decision % has been superseded and is no longer his decision. (pd_refund_execution_without_founder_decision)',
      coalesce(NEW.id::text,'(new)'), NEW.refund_decision_id using errcode = '23514';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_require_founder(p_actor text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sub    uuid;
  v_id     text;
  v_ev     bigint;
  v_route  text;
begin
  -- ---- PCCR-007. THE CONNECTION, BEFORE ANY CLAIM IS READ ---------------------------------------
  -- session_user is the role this connection authenticated as. A caller cannot change it: SET ROLE
  -- leaves it alone and SET SESSION AUTHORIZATION is refused to postgres on this deployment. Every
  -- claim examined below — auth.uid(), the bound event — is read from session state that a
  -- management or migration connection can write for itself, so the connection is checked first.
  if session_user <> 'authenticator' then
    raise exception 'not the founder: the founder is resolved from a bearer token verified by PostgREST (session_user authenticator); this call arrives as session_user %. auth.uid() reads request.jwt.claims, which a management or migration connection can set for itself, so a resolved subject on this connection is a value the caller wrote rather than a session anyone opened. (pccr007_founder_untrusted_connection)',
      session_user using errcode = '28000',
            hint = 'Approve on the OS. A migration cannot approve a refund, cancel a workflow or answer a founder command.';
  end if;

  -- ---- ROUTE A: a bearer token PostgREST already verified -------------------------------------
  -- auth.uid() is null for a service_role connection and for anything that did not arrive with a
  -- user JWT. It CAN be set by a caller — that was PCCR-007's finding, and it is why the connection
  -- is checked above before this value is trusted.
  begin
    v_sub := auth.uid();
  exception when others then
    v_sub := null;
  end;
  if v_sub is not null then
    select f.identity into v_id
      from public.phase_c_founder_identity f
     where f.auth_user_id = v_sub and f.active and f.kind = 'email';
    v_route := 'auth.uid()';
  end if;

  -- ---- ROUTE B: the server path bound a subject it verified ------------------------------------
  if v_id is null then
    v_ev := nullif(btrim(current_setting('app.phase_c_founder_auth_event', true)),'')::bigint;
    if v_ev is not null then
      select e.identity, e.auth_subject into v_id, v_sub
        from public.phase_c_founder_auth_event e
        join public.phase_c_founder_identity f on f.identity = e.identity
       where e.event_id = v_ev
         -- BOUND TO THIS TRANSACTION. A GUC pointing at an event from another transaction is not a
         -- session: it is a value a caller typed.
         and e.txid = txid_current()
         -- PCCR-006. A PURPOSE-BOUND SESSION IS NOT A GENERAL ONE. An event minted to carry one
         -- governance decision may not also open the refund door in the same transaction.
         -- fn_phase_c_governance_decide reads its own event directly and does not come through here.
         and e.action_class is null
         and f.active and f.kind = 'email';
      v_route := 'fn_phase_c_founder_subject_bind';
    end if;
  end if;

  if v_id is null then
    -- E39's vector, refused: knowing the email is no longer being the founder.
    raise exception 'not the founder: no verified auth subject on this call. The founder is resolved from auth.uid() or from a subject os_api verified and bound with fn_phase_c_founder_subject_bind; a caller-supplied identity is not authentication. (PCCR-003)'
      using errcode = '28000',
            hint = 'Call with the founder''s bearer token so auth.uid() resolves, or verify the JWT in os_api and bind the verified subject first.';
  end if;

  -- p_actor is now an ASSERTION, not a source. Supplying one that disagrees with the verified
  -- identity is a caller claiming to be someone else and is refused; supplying none is fine.
  if coalesce(btrim(p_actor),'') <> '' and lower(btrim(p_actor)) <> lower(v_id) then
    raise exception 'not the founder: the call asserts identity % and the verified auth subject resolves to %',
      lower(btrim(p_actor)), v_id using errcode = '28000';
  end if;

  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_resolve_actor(p_token text)
 RETURNS TABLE(kind text, role_id text, department_id text, system_actor_id text, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tok  text := btrim(coalesce(p_token, ''));
  v_id   text;
  v_role public.org_role%rowtype;
  v_succ public.org_role%rowtype;
begin
  if v_tok = '' then
    kind := 'refused'; reason := 'empty actor token'; return next; return;
  end if;

  -- the founder is an external decision boundary, not an employee
  if v_tok = 'founder' then
    kind := 'founder'; role_id := 'founder'; department_id := 'exec';
    reason := 'external decision boundary; may hold refund_decision only'; return next; return;
  end if;

  -- a registered system actor executes, but never replaces the accountable employee
  select a.system_actor_id, a.accountable_role_id, a.department_id
    into system_actor_id, role_id, department_id
  from public.phase_c_system_actor a where a.system_actor_id = v_tok;
  if found then
    kind := 'system_actor';
    reason := 'system actor; accountable_role_id is the business owner, not the executor';
    return next; return;
  end if;

  -- canonical role id, then any registered alias: legacy key, merged key, packaged role
  -- identity or approved title.  org_role_alias.kind records which.
  v_id := (select r.role_id from public.org_role r where r.role_id = v_tok);
  if v_id is null then
    v_id := (select a.role_id from public.org_role_alias a where a.alias = v_tok limit 1);
  end if;

  if v_id is null then
    kind := 'unknown'; reason := format('no active canonical role, alias or system actor named %L', v_tok);
    return next; return;
  end if;

  select * into v_role from public.org_role r where r.role_id = v_id;
  if not found then
    kind := 'unknown'; reason := format('alias %L points at missing role %L', v_tok, v_id);
    return next; return;
  end if;
  if v_role.status <> 'active' then
    -- ONE HOP OF RECORDED SUCCESSION. The org_role row survives being parked, so it shadowed the
    -- merged_role alias written for exactly this case. Follow it here, where the shadow falls.
    select r2.* into v_succ
      from public.org_role_alias a
      join public.org_role r2 on r2.role_id = a.role_id
     where a.alias = v_role.role_id
       and a.kind = 'merged_role'
       and r2.role_id is distinct from v_role.role_id
       and r2.status = 'active'
     limit 1;
    if found then
      role_id := v_succ.role_id;
      department_id := v_succ.primary_department_id;
      kind := case when v_succ.runtime_mode = 'knowledge_overlay' then 'overlay' else 'canonical' end;
      reason := format('role %L is %L; its recorded merged_role succession names %L, which is active and answers for it',
                       v_role.role_id, v_role.status, v_succ.role_id);
      return next; return;
    end if;
    kind := 'inactive'; role_id := v_role.role_id; department_id := v_role.primary_department_id;
    reason := format('role %L has status %L and may not receive or execute current work', v_id, v_role.status);
    return next; return;
  end if;

  role_id := v_role.role_id;
  department_id := v_role.primary_department_id;
  if v_role.runtime_mode = 'knowledge_overlay' then
    kind := 'overlay';
    reason := 'category overlay: may be invoked and may advise, may never hold dispatch authority or own a required step';
  else
    kind := 'canonical';
    reason := 'active canonical role';
  end if;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_reviewer_independent(p_creator text, p_reviewer text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a text; b text;
begin
  if coalesce(p_reviewer, '') = '' then return false; end if;
  select role_id into a from public.fn_phase_c_resolve_actor(p_creator);
  select role_id into b from public.fn_phase_c_resolve_actor(p_reviewer);
  if a is null or b is null then return false; end if;
  return a <> b;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_advance(p_run_id bigint, p_step_id text, p_actor text, p_body jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'fn_phase_c_step_advance is retired: it derived successors from phase_b_handoff alone, so a '
    'step with a real next_step_if_pass and no edge returned terminal success and stopped the '
    'chain mid-workflow. Use fn_kernel_step_complete.'
    using errcode = '23514',
          hint = 'public.kernel_retired_path names the replacement for every retired path.';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_event(p_step_id text, p_lifecycle text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select e.event_id
    from public.phase_b_workflow_step s
    join public.phase_b_event e on e.workflow_id = s.workflow_id
   where s.step_id = p_step_id
     and e.event_name like '%.' || lower(replace(p_step_id, '-', '_')) || '.'
                                || lower(btrim(coalesce(p_lifecycle,'')))
   order by e.event_id
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_owner_valid(p_step_id text, p_owner text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s public.phase_b_workflow_step%rowtype; v_kind text;
begin
  if public.fn_phase_c_actor_may_own(p_owner) then return true; end if;
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then return false; end if;
  -- W14 removed: W14-S05 is now the canonical role quote_evaluation (PBCR-001), so no W14 step uses a
  -- category overlay. W05/W06/W07/W10 analysis steps legitimately still do.
  if p_owner = 'relevant_category_overlay'
     and s.step_type = 'analysis'
     and s.workflow_id in ('W05','W06','W07','W10') then
    return true;
  end if;
  select kind into v_kind from public.fn_phase_c_resolve_actor(p_owner);
  return v_kind = 'overlay' and s.step_type = 'analysis'
     and s.workflow_id in ('W05','W06','W07','W10');
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_run_owner_admissible()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a record;
begin
  -- Only a row that ARRIVES with an owner, or CHANGES its owner, is judged. An update that leaves
  -- accountable_role_id alone is none of this guard's business, so a row written before this guard
  -- existed cannot be made unfinishable by it.
  if tg_op = 'UPDATE' and NEW.accountable_role_id is not distinct from OLD.accountable_role_id then
    return NEW;
  end if;

  select * into a from public.fn_phase_d_owner_admissibility(NEW.accountable_role_id);
  if a.admissible then return NEW; end if;

  if a.refusal_code = 'pd_overlay_cannot_own_task' then
    raise exception 'phase_c_workflow_step_run: % resolves to category overlay %, which may advise and may never be accountable for a step run. Invoke it with fn_phase_c_overlay_invoke and return its advice to a standing accountable role. (pd_overlay_cannot_own_task)',
      NEW.accountable_role_id, coalesce(a.resolved_role_id, '(unresolved)')
      using errcode = '23514';
  end if;

  raise exception 'phase_c_workflow_step_run: owner % is %, not an active canonical role, so it may not be accountable for a step run. (%)',
    coalesce(nullif(btrim(NEW.accountable_role_id),''), '(empty)'),
    coalesce(a.resolved_kind, 'absent'), a.refusal_code
    using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_run_review_verdict_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_verdict text; v_reviewer text; v_task bigint;
begin
  -- Only a move INTO completed is judged. A state that did not change, and any other target
  -- state -- failed, cancelled, blocked -- is none of this guard's business.
  if NEW.state is not distinct from OLD.state then return NEW; end if;
  if NEW.state <> 'completed' then return NEW; end if;

  -- The LATEST sealed review verdict for this run and step, across every task the step has had.
  -- Latest, so a correction that was subsequently approved is not held against the step.
  select t.task_id, tr.reviewer_role_id, ev->>'review_decision'
    into v_task, v_reviewer, v_verdict
    from public.phase_c_task t
    join public.phase_c_trace tr on tr.task_id = t.task_id
   cross join lateral jsonb_array_elements(
           case when jsonb_typeof(coalesce(tr.evidence_refs,'[]'::jsonb)) = 'array'
                then tr.evidence_refs else '[]'::jsonb end) ev
   where t.run_id = NEW.run_id
     and t.step_id = NEW.step_id
     and tr.trace_policy_id = 'TRACE-ROLE-ACTION'
     and ev ? 'review_decision'
   order by tr.trace_id desc
   limit 1;

  if coalesce(v_verdict,'') in ('rejected','changes_requested') then
    raise exception 'step % cannot complete: the latest internal review verdict on task % is %, recorded by %. A verdict that is recorded and then walked past is not a review. Record an approved verdict through fn_kernel_review_decide, or fail the step. (pd_review_verdict_rejected)',
      NEW.step_id, v_task, v_verdict, coalesce(v_reviewer,'(unstamped)')
      using errcode = '23514';
  end if;

  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_run_trace_committed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_trace bigint; v_state text;
begin
  select state, trace_id into v_state, v_trace
    from public.phase_c_workflow_step_run where step_run_id = new.step_run_id;
  if not found then return null; end if;

  if v_state not in ('active','waiting_review','waiting_input','blocked',
                     'completed','failed','cancelled','superseded','skipped') then
    return null;                          -- not_ready / ready: the step has not started
  end if;

  if v_trace is null then
    raise exception 'phase_c_workflow_step_run %: committed in state % with no trace',
      new.step_run_id, v_state using errcode = '23514',
      hint = 'TRACE-STEP declares trace_required=YES and completed_without_trace_allowed=NO. The '
          || 'trace is written by z90_phase_c_step_run_trace_subject on AFTER INSERT.';
  end if;
  if not exists (select 1 from public.phase_c_trace where trace_id = v_trace) then
    raise exception 'phase_c_workflow_step_run %: trace % does not exist at commit',
      new.step_run_id, v_trace using errcode = '23503',
      hint = 'Evidence is superseded, never removed.';
  end if;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_step_run_trace_subject()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_parent bigint; v_trace bigint;
begin
  if new.trace_id is not null then
    update public.phase_c_trace
       set step_run_id = new.step_run_id, subject_ref = new.step_run_id::text
     where trace_id = new.trace_id and step_run_id is null and sealed_at is null;
    return null;
  end if;

  select r.trace_id into v_parent from public.phase_c_workflow_run r where r.run_id = new.run_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-STEP', jsonb_build_object(
    'subject_kind','step_run', 'subject_ref', new.step_run_id::text,
    'run_id', new.run_id, 'step_run_id', new.step_run_id,
    'actor_role_id', new.accountable_role_id, 'reviewer_role_id', new.reviewer_role_id,
    'system_actor_id','system.workflow_engine',
    'authority_result', new.authority_result, 'gates', new.gates_evaluated,
    'input_hash', new.input_hash, 'output_hash', new.output_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'step_id', new.step_id, 'attempt_no', new.attempt_no,
      'idempotency_key', new.idempotency_key)),
    'parent_trace_id', v_parent,
    'state_before','', 'state_after', new.state, 'status','open'));

  update public.phase_c_workflow_step_run set trace_id = v_trace where step_run_id = new.step_run_id;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_system_execution_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception
    'phase_c_system_execution is append-only: % on trace % refused. An execution record that can '
    'be edited after the fact records the editor, not the execution.',
    tg_op, coalesce(old.trace_id, new.trace_id)
    using errcode = '23514';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_task_create(p_body jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_owner text; v_manager text; v_dept text; v_key text;
begin
  select role_id into v_owner from public.fn_phase_c_resolve_actor(p_body->>'accountable_role_id');
  if v_owner is null or not public.fn_phase_c_actor_may_own(v_owner) then
    raise exception 'fn_phase_c_task_create: owner % does not resolve to an active canonical role',
      coalesce(p_body->>'accountable_role_id', '(null)') using errcode = '23514';
  end if;
  select r.manager_role_id, r.primary_department_id into v_manager, v_dept
    from public.org_role r where r.role_id = v_owner;
  v_key := coalesce(nullif(p_body->>'idempotency_key',''),
    'task:' || md5(coalesce(p_body->>'source_ref','') || ':' || v_owner || ':' || coalesce(p_body->>'objective','')));
  insert into public.phase_c_task (
    source_kind, source_ref, command_id, run_id, workflow_id, step_id, accountable_role_id,
    manager_role_id, department_id, objective, required_inputs, requested_output,
    acceptance_criteria, closure_criteria, priority, due_at, sla_policy_id, reviewer_required,
    reviewer_role_id, authority_class, idempotency_key, state)
  values (
    coalesce(p_body->>'source_kind','management'), coalesce(p_body->>'source_ref',''),
    (p_body->>'command_id')::bigint, (p_body->>'run_id')::bigint,
    nullif(p_body->>'workflow_id',''), nullif(p_body->>'step_id',''),
    v_owner, coalesce(v_manager,''), coalesce(v_dept,''),
    coalesce(p_body->>'objective','(objective not stated)'),
    coalesce(p_body->>'required_inputs',''), coalesce(p_body->>'requested_output',''),
    coalesce(p_body->>'acceptance_criteria','Evidence-backed outcome accepted by the manager.'),
    coalesce(p_body->>'closure_criteria','Closure criteria of the bound workflow satisfied.'),
    coalesce(p_body->>'priority','P2'), (p_body->>'due_at')::timestamptz,
    coalesce(p_body->>'sla_policy_id',''),
    coalesce((p_body->>'reviewer_required')::boolean, false),
    coalesce(p_body->>'reviewer_role_id',''),
    coalesce(p_body->>'authority_class','routine_operational_decision'),
    v_key, 'queued')
  on conflict (idempotency_key) do nothing
  returning task_id into v_id;
  if v_id is null then
    select task_id into v_id from public.phase_c_task where idempotency_key = v_key;
  end if;
  if v_id is null then
    raise exception 'fn_phase_c_task_create wrote no row and found none for key %', v_key using errcode = '23502';
  end if;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_task_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'UPDATE' and new.state is distinct from old.state
     and not public.fn_phase_c_task_transition_allowed(old.state, new.state) then
    raise exception 'phase_c_task %: transition % -> % is not in the Phase C task state model (pd_task_transition_not_permitted)',
      old.task_id, old.state, new.state using errcode = '23514';
  end if;
  -- No generic Director, code-runner name, service-role name or unresolved alias may own a task.
  if not public.fn_phase_c_actor_may_own(new.accountable_role_id) then
    raise exception 'phase_c_task: owner % does not resolve to an active canonical role (%)',
      new.accountable_role_id,
      coalesce((select refusal_code from public.fn_phase_d_owner_admissibility(new.accountable_role_id)),
               'pd_owner_not_canonical')
      using errcode = '23514';
  end if;
  if new.reviewer_required
     and not public.fn_phase_c_reviewer_independent(new.accountable_role_id, new.reviewer_role_id) then
    raise exception 'phase_c_task: reviewer % is not independent of owner % (pd_creator_reviewer_collision)',
      new.reviewer_role_id, new.accountable_role_id using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_task_trace_committed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_trace bigint; v_state text; t public.phase_c_trace%rowtype;
begin
  select state, trace_id into v_state, v_trace
    from public.phase_c_task where task_id = new.task_id;
  if not found then return null; end if;          -- deleted in this transaction; nothing to assert

  if v_trace is null then
    raise exception 'phase_c_task %: committed in state % with no trace', new.task_id, v_state
      using errcode = '23514',
            hint = 'TRACE-TASK declares trace_required=YES and completed_without_trace_allowed=NO. '
                || 'The trace is written by z90_phase_c_task_trace_subject on AFTER INSERT; if it '
                || 'is missing at commit, something cleared trace_id after the row was created.';
  end if;

  select * into t from public.phase_c_trace where trace_id = v_trace;
  if not found then
    raise exception 'phase_c_task %: trace % does not exist at commit', new.task_id, v_trace
      using errcode = '23503',
            hint = 'The task points at a trace that was deleted in this transaction. Evidence is '
                || 'superseded, never removed.';
  end if;
  if t.task_id is distinct from new.task_id then
    raise exception 'phase_c_task %: trace % names task % — the ledger and the task disagree',
      new.task_id, v_trace, coalesce(t.task_id::text,'NULL')
      using errcode = '23514',
            hint = 'A trace whose task_id does not resolve is exactly the orphan class K6 exists '
                || 'to make impossible.';
  end if;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_task_trace_subject()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_parent bigint; v_trace bigint;
begin
  if new.trace_id is not null then
    -- A caller supplied the trace. Stamp the subject on it if it does not already carry one.
    update public.phase_c_trace
       set task_id = new.task_id, subject_ref = new.task_id::text
     where trace_id = new.trace_id and task_id is null and sealed_at is null;
    return null;
  end if;

  -- The root this task hangs from: its command's trace, or its workflow run's trace.
  select c.trace_id into v_parent from public.founder_command c where c.command_id = new.command_id;
  if v_parent is null then
    select r.trace_id into v_parent from public.phase_c_workflow_run r where r.run_id = new.run_id;
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-TASK', jsonb_build_object(
    'subject_kind','task', 'subject_ref', new.task_id::text, 'task_id', new.task_id,
    'command_id', new.command_id, 'run_id', new.run_id,
    'actor_role_id', new.accountable_role_id, 'manager_role_id', new.manager_role_id,
    'system_actor_id', case when new.command_id is not null
                            then 'system.command_router' else 'system.workflow_engine' end,
    'authority_result', coalesce(new.authority_class,''),
    'reviewer_role_id', coalesce(new.reviewer_role_id,''),
    'input_hash', encode(sha256(convert_to(coalesce(new.objective,''), 'UTF8')), 'hex'),
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'idempotency_key', new.idempotency_key, 'source_kind', new.source_kind,
      'source_ref', new.source_ref)),
    'parent_trace_id', v_parent,
    'state_before','', 'state_after', coalesce(new.state,'queued'), 'status','open'));

  update public.phase_c_task set trace_id = v_trace where task_id = new.task_id;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_task_transition(p_task_id bigint, p_to_state text, p_actor text, p_ctx jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.phase_c_task%rowtype; v_trace bigint; v_cmd_state text;
begin
  select * into t from public.phase_c_task where task_id = p_task_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error','not_found','task_id', p_task_id);
  end if;
  if not public.fn_phase_c_task_transition_allowed(t.state, p_to_state) then
    return jsonb_build_object('ok', false, 'error','invalid_transition',
      'from', t.state, 'to', p_to_state,
      'message','The Phase C task state model does not allow that move.');
  end if;
  if p_to_state = 'completed' and t.reviewer_required
     and not public.fn_phase_c_reviewer_independent(t.accountable_role_id, t.reviewer_role_id) then
    return jsonb_build_object('ok', false, 'error','reviewer_not_independent',
      'owner', t.accountable_role_id, 'reviewer', t.reviewer_role_id);
  end if;
  if p_to_state = 'blocked' and coalesce(p_ctx->>'blocker','') = '' then
    return jsonb_build_object('ok', false, 'error','blocker_required',
      'message','A blocked task must name its blocker and the owner who resolves it.');
  end if;

  update public.phase_c_task set
    state = p_to_state,
    blocker = case when p_to_state = 'blocked' then p_ctx->>'blocker' else '' end,
    blocker_owner_role_id = case when p_to_state = 'blocked' then coalesce(p_ctx->>'blocker_owner_role_id','') else '' end,
    closed_at = case when p_to_state in ('completed','cancelled','failed','superseded') then now() else null end
  where task_id = p_task_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-TASK', jsonb_build_object(
    'subject_kind','task', 'subject_ref', p_task_id::text, 'task_id', p_task_id,
    'command_id', t.command_id, 'actor_role_id', p_actor, 'manager_role_id', t.manager_role_id,
    'state_before', t.state, 'state_after', p_to_state, 'status', 'sealed'));
  update public.phase_c_task set trace_id = v_trace where task_id = p_task_id;

  -- The founder's half of the chain: the command follows its tasks.
  if t.command_id is not null then
    v_cmd_state := public.fn_founder_command_rollup(t.command_id);
  end if;

  return jsonb_build_object('ok', true, 'task_id', p_task_id, 'from', t.state, 'to', p_to_state,
                            'trace_id', v_trace, 'command_moved_to', v_cmd_state);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_task_transition_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (select 1 from public.phase_c_task_transition
                 where from_state = p_from and to_state = p_to);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_trace_advance(p_trace_id bigint, p_state_after text, p_seal boolean DEFAULT false, p_body jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.phase_c_trace%rowtype; v_new bigint;
begin
  if p_trace_id is null then return null; end if;
  select * into t from public.phase_c_trace where trace_id = p_trace_id;
  if not found then
    raise exception 'fn_phase_c_trace_advance: no trace %', p_trace_id using errcode = '23503';
  end if;

  -- A sealed trace is evidence. It is superseded, never rewritten.
  if t.sealed_at is not null then
    v_new := public.fn_phase_c_trace_write(t.trace_policy_id, jsonb_build_object(
      'subject_kind', t.subject_kind, 'subject_ref', t.subject_ref,
      'command_id', t.command_id, 'run_id', t.run_id, 'step_run_id', t.step_run_id,
      'task_id', t.task_id, 'actor_role_id', t.actor_role_id,
      'manager_role_id', t.manager_role_id, 'system_actor_id', t.system_actor_id,
      'state_before', t.state_after, 'state_after', p_state_after,
      'evidence_refs', coalesce(p_body->'evidence_refs', '[]'::jsonb),
      'parent_trace_id', coalesce(t.parent_trace_id, t.trace_id),
      'status', case when p_seal then 'sealed' else 'open' end));
    update public.phase_c_trace set superseded_by = v_new where trace_id = p_trace_id;
    return v_new;
  end if;

  update public.phase_c_trace set
    state_before  = coalesce(nullif(t.state_before,''), t.state_after),
    state_after   = p_state_after,
    status        = case when p_seal then 'sealed' else 'open' end,
    sealed_at     = case when p_seal then now() else null end,
    output_hash   = coalesce(nullif(p_body->>'output_hash',''), t.output_hash),
    evidence_refs = case when p_body ? 'evidence_refs'
                         then coalesce(t.evidence_refs,'[]'::jsonb) || (p_body->'evidence_refs')
                         else t.evidence_refs end
  where trace_id = p_trace_id;
  return p_trace_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_trace_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if old.sealed_at is null then return new; end if;
  if new.superseded_by is distinct from old.superseded_by
     and to_jsonb(new) - 'superseded_by' = to_jsonb(old) - 'superseded_by' then
    return new;
  end if;
  raise exception 'phase_c_trace %: sealed trace evidence is append-only; write a superseding row instead of editing it', old.trace_id
    using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_trace_write(p_policy text, p_body jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_status text;
begin
  if not exists (select 1 from public.phase_c_trace_policy where trace_policy_id = p_policy) then
    raise exception 'unknown trace policy %', p_policy using errcode = '23503';
  end if;
  v_status := coalesce(p_body->>'status','open');
  insert into public.phase_c_trace (
    trace_policy_id, subject_kind, subject_ref, command_id, run_id, step_run_id, task_id,
    actor_role_id, manager_role_id, system_actor_id, component_id, authority_result,
    reviewer_role_id, reviewer_independent, gates, rules, evidence_refs, input_hash,
    output_hash, state_before, state_after, event_ids, status, sealed_at, parent_trace_id)
  values (
    p_policy,
    coalesce(p_body->>'subject_kind', 'unknown'), coalesce(p_body->>'subject_ref', ''),
    (p_body->>'command_id')::bigint, (p_body->>'run_id')::bigint,
    (p_body->>'step_run_id')::bigint, (p_body->>'task_id')::bigint,
    coalesce(p_body->>'actor_role_id',''), coalesce(p_body->>'manager_role_id',''),
    coalesce(p_body->>'system_actor_id',''), coalesce(p_body->>'component_id',''),
    coalesce(p_body->>'authority_result',''), coalesce(p_body->>'reviewer_role_id',''),
    (p_body->>'reviewer_independent')::boolean,
    coalesce(p_body->'gates','[]'::jsonb), coalesce(p_body->'rules','[]'::jsonb),
    coalesce(p_body->'evidence_refs','[]'::jsonb), coalesce(p_body->>'input_hash',''),
    coalesce(p_body->>'output_hash',''), coalesce(p_body->>'state_before',''),
    coalesce(p_body->>'state_after',''), coalesce(p_body->'event_ids','[]'::jsonb),
    v_status,
    case when v_status = 'sealed' then now() end,
    (p_body->>'parent_trace_id')::bigint)
  returning trace_id into v_id;
  if v_id is null then
    raise exception 'phase_c_trace_write produced no row for policy %', p_policy using errcode = '23502';
  end if;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_workflow_start(p_workflow_id text, p_business_object_id text, p_ctx jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare w public.phase_b_workflow%rowtype; v_id bigint; v_dedupe text; v_state text; v_trace bigint;
begin
  select * into w from public.phase_b_workflow where workflow_id = p_workflow_id;
  if not found then
    raise exception 'unknown workflow % — fail closed', p_workflow_id using errcode = '23503';
  end if;
  if not public.fn_phase_c_actor_may_own(w.accountable_role_id) then
    raise exception 'workflow % owner % does not resolve to an active canonical role',
      p_workflow_id, w.accountable_role_id using errcode = '23514';
  end if;
  v_dedupe := p_workflow_id || ':' || p_business_object_id || ':' || coalesce(p_ctx->>'object_version', '1');
  select run_id into v_id from public.phase_c_workflow_run where dedupe_key = v_dedupe;
  if v_id is not null then return v_id; end if;         -- idempotent start, not a duplicate run
  select state into v_state from public.phase_b_workflow_state
    where state in ('queued','not_started','initiated') order by state limit 1;
  insert into public.phase_c_workflow_run
    (workflow_id, business_object_id, object_version, start_event, accountable_role_id,
     state, dedupe_key, command_id)
  values (p_workflow_id, p_business_object_id, coalesce((p_ctx->>'object_version')::bigint, 1),
          coalesce(p_ctx->>'start_event', w.start_event), w.accountable_role_id,
          coalesce(v_state, (select state from public.phase_b_workflow_state order by state limit 1)),
          v_dedupe, (p_ctx->>'command_id')::bigint)
  returning run_id into v_id;
  if v_id is null then
    raise exception 'fn_phase_c_workflow_start wrote no row for %', p_workflow_id using errcode = '23502';
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-WORKFLOW', jsonb_build_object(
    'subject_kind','workflow_run', 'subject_ref', v_id::text, 'run_id', v_id,
    'command_id', (p_ctx->>'command_id')::bigint,
    'actor_role_id', w.accountable_role_id, 'system_actor_id','system.workflow_engine',
    'input_hash', encode(sha256(convert_to(coalesce(p_ctx::text,'{}'), 'UTF8')), 'hex'),
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'business_object_id', p_business_object_id, 'dedupe_key', v_dedupe,
      'source', coalesce(p_ctx->>'source','unspecified'))),
    'state_before','', 'state_after', coalesce(v_state,'queued'), 'status','open'));
  update public.phase_c_workflow_run set trace_id = v_trace where run_id = v_id;
  if (select trace_id from public.phase_c_workflow_run where run_id = v_id) is null then
    raise exception 'workflow run % has no trace after start', v_id using errcode = '23502';
  end if;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_c_workflow_state_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.state is distinct from old.state
     and not public.fn_phase_c_workflow_transition_allowed(old.state, new.state) then
    raise exception 'phase_c_workflow_run %: transition % -> % is not in the frozen Phase B state model',
      old.run_id, old.state, new.state using errcode = '23514';
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_capability_answer(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
           'result_id', r.result_id, 'request_id', r.request_id, 'provider_mode', r.provider_mode,
           'fixture_id', r.fixture_id, 'fixture_version', r.fixture_version,
           'fixture_hash', r.fixture_hash, 'payload', r.payload,
           'payload_digest', r.payload_digest, 'evidence', r.evidence)
    from public.phase_d_capability_result r
    join public.phase_d_capability_request q on q.request_id = r.request_id
   where q.step_run_id = p_step_run_id
   order by r.result_id desc limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_capability_request_open(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr  public.phase_c_workflow_step_run%rowtype;
  b   public.phase_d_handler_binding%rowtype;
  q   public.phase_d_capability_request%rowtype;
  v_step_run bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_by       text   := nullif(btrim(coalesce(p_input->>'requested_by','')),'');
  v_id       bigint;
begin
  if v_step_run is null or v_by is null then
    raise exception 'fn_phase_d_capability_request_open: step_run_id and requested_by are required (pd_capability_request_invalid)'
      using errcode = '22023';
  end if;
  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if not found then
    raise exception 'fn_phase_d_capability_request_open: no step run % (pd_step_state_invalid)', v_step_run
      using errcode = '23503';
  end if;
  select * into b from public.phase_d_handler_binding where step_id = sr.step_id;
  if not found or b.capability_dependency = 'NONE' then
    raise exception 'fn_phase_d_capability_request_open: step % declares no capability dependency, so there is nothing to request (pd_capability_not_declared)',
      sr.step_id using errcode = '22023';
  end if;

  select * into q from public.phase_d_capability_request
   where step_run_id = v_step_run and capability = b.capability_dependency;
  if found then
    return jsonb_build_object('ok', true, 'replay', true, 'request_id', q.request_id,
                              'state', q.state, 'capability', q.capability);
  end if;

  insert into public.phase_d_capability_request
    (step_run_id, run_id, step_id, workflow_id, capability, requested_by, request_digest,
     fixture_run_id)
  values (v_step_run, sr.run_id, sr.step_id, b.workflow_id, b.capability_dependency, v_by,
          encode(sha256(convert_to(format('%s|%s|%s', sr.step_id, v_step_run,
                                          b.capability_dependency),'UTF8')),'hex'),
          public.fn_phase_d_fixture_context())
  returning request_id into v_id;

  return jsonb_build_object('ok', true, 'replay', false, 'request_id', v_id,
                            'state','open', 'capability', b.capability_dependency,
                            'note','a request is open; no provider is available in Phase D, so it '
                                || 'is answered by a Phase D fixture result or not at all');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_capability_result_accept(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  q    public.phase_d_capability_request%rowtype;
  c    public.phase_d_capability_contract%rowtype;
  ex   public.phase_d_capability_result%rowtype;
  v_req   bigint := nullif(p_input->>'request_id','')::bigint;
  v_mode  text   := lower(nullif(btrim(coalesce(p_input->>'provider_mode','')),''));
  v_pay   jsonb  := p_input->'payload';
  v_fid   text   := nullif(btrim(coalesce(p_input->>'fixture_id','')),'');
  v_fver  int    := nullif(p_input->>'fixture_version','')::int;
  v_by    text   := nullif(btrim(coalesce(p_input->>'accepted_by','')),'');
  v_run   bigint := public.fn_phase_d_fixture_context();
  v_cat   public.phase_d_fixture_catalogue%rowtype;
  v_k     text;
  v_want  text;
  v_got   text;
  v_miss  text[] := '{}';
  v_bad   text[] := '{}';
  v_id    bigint;
begin
  if v_req is null or v_mode is null or v_by is null then
    raise exception 'fn_phase_d_capability_result_accept: request_id, provider_mode and accepted_by are all required (pd_capability_result_invalid)'
      using errcode = '22023';
  end if;
  select * into q from public.phase_d_capability_request where request_id = v_req;
  if not found then
    raise exception 'fn_phase_d_capability_result_accept: no capability request % (pd_capability_request_absent)', v_req
      using errcode = '23503';
  end if;

  -- ---- idempotent replay: one result per request, and the first one stands -------------------
  select * into ex from public.phase_d_capability_result where request_id = v_req;
  if found then
    return jsonb_build_object('ok', true, 'replay', true, 'result_id', ex.result_id,
      'provider_mode', ex.provider_mode, 'payload_digest', ex.payload_digest,
      'note','this request already carries a result; no second result and no second effect');
  end if;

  -- ---- THE PROVIDER ARM IS REFUSED WHILE THE HOLD STANDS ------------------------------------
  -- It is written out rather than omitted so that the Phase E path is this path, and so that the
  -- refusal is a measured fact rather than the absence of code.
  if v_mode = 'provider' then
    raise exception 'fn_phase_d_capability_result_accept: a provider result cannot be accepted while the founder''s paid-inference hold stands (NO_PAID_AI=true, OPENROUTER_DISABLED=true, AI_PROVIDER_MODE=mock). No provider was called to produce this refusal. (pd_provider_disabled)'
      using errcode = '23514';
  end if;

  -- ---- THE FIXTURE ARM NEEDS A CONTEXT NO UNTRUSTED CALLER CAN MANUFACTURE --------------------
  if v_mode = 'fixture' then
    if v_run is null then
      raise exception 'fn_phase_d_capability_result_accept: a fixture capability result requires a verified Phase D fixture context. In production there is none, so a fixture result is refused before its payload is read. (pd_capability_fixture_context_absent)'
        using errcode = '42501';
    end if;
    if v_fid is null then
      raise exception 'fn_phase_d_capability_result_accept: a fixture result must name the committed catalogue row it came from (fixture_id) (pd_capability_fixture_unidentified)'
        using errcode = '22023';
    end if;
    select * into v_cat from public.phase_d_fixture_catalogue
     where fixture_id = v_fid and scope = 'CAPABILITY_RESULT';
    if not found then
      raise exception 'fn_phase_d_capability_result_accept: fixture % is not a CAPABILITY_RESULT row in the committed catalogue (pd_capability_fixture_unknown)',
        v_fid using errcode = '23503';
    end if;
    if v_fver is not null and v_fver <> v_cat.fixture_version then
      raise exception 'fn_phase_d_capability_result_accept: fixture % is version % in the committed catalogue and the call names version % (pd_capability_fixture_version_mismatch)',
        v_fid, v_cat.fixture_version, v_fver using errcode = '22023';
    end if;
    v_fver := v_cat.fixture_version;
    -- The payload is the catalogue's, merged over by nothing. A caller may not hand a fixture id
    -- and then a different payload: that would be an unmarked value wearing a marked label.
    v_pay := v_cat.value;
  end if;

  -- ---- OUTPUT VALIDATION, THE SAME FOR BOTH MODES -------------------------------------------
  select * into c from public.phase_d_capability_contract where step_id = q.step_id;
  if not found then
    raise exception 'fn_phase_d_capability_result_accept: step % has no capability contract, so no result can be validated against anything. Fail closed. (pd_capability_contract_absent)',
      q.step_id using errcode = '23503';
  end if;
  if v_pay is null or jsonb_typeof(v_pay) <> 'object' then
    raise exception 'fn_phase_d_capability_result_accept: the result payload for step % is not an object (pd_capability_result_malformed)',
      q.step_id using errcode = '22023';
  end if;
  foreach v_k in array c.required_keys loop
    if not (v_pay ? v_k) then
      v_miss := v_miss || v_k;
    else
      v_want := c.key_types->>v_k;
      v_got  := jsonb_typeof(v_pay->v_k);
      if v_want is not null and v_got <> v_want then
        v_bad := v_bad || format('%s is %s, contract says %s', v_k, v_got, v_want);
      end if;
    end if;
  end loop;
  if cardinality(v_miss) > 0 or cardinality(v_bad) > 0 then
    raise exception 'fn_phase_d_capability_result_accept: the result for step % does not satisfy its capability contract — missing [%], wrongly typed [%] (pd_capability_result_malformed)',
      q.step_id, array_to_string(v_miss, ', '), array_to_string(v_bad, ', ')
      using errcode = '22023';
  end if;
  -- provider_mode travels INSIDE the payload as well as beside it, and the two must agree, so a
  -- result cannot be re-labelled after acceptance by editing one of them.
  if lower(coalesce(v_pay->>'provider_mode','')) <> v_mode then
    raise exception 'fn_phase_d_capability_result_accept: the payload says provider_mode % and the call says %. A result that disagrees with itself about where it came from is refused. (pd_capability_result_malformed)',
      coalesce(v_pay->>'provider_mode','(absent)'), v_mode
      using errcode = '22023';
  end if;

  insert into public.phase_d_capability_result
    (request_id, provider_mode, fixture_id, fixture_version, fixture_hash, provider_event_ref,
     payload, payload_digest, trace_id, evidence, accepted_by, fixture_run_id)
  values (v_req, v_mode, v_fid, v_fver, v_cat.checksum, nullif(p_input->>'provider_event_ref',''),
          v_pay, encode(sha256(convert_to(v_pay::text,'UTF8')),'hex'),
          nullif(p_input->>'trace_id','')::bigint,
          format('capability %s for step %s answered in mode %s from %s; validated against '
              || 'phase_d_capability_contract keys [%s]; 0 paid inference requests were made to '
              || 'produce this result',
                 q.capability, q.step_id, v_mode,
                 coalesce(v_fid || ' v' || v_fver::text, coalesce(p_input->>'provider_event_ref','(unstated)')),
                 array_to_string(c.required_keys, ', ')),
          v_by, v_run)
  returning result_id into v_id;

  update public.phase_d_capability_request set state = 'answered' where request_id = v_req;

  return jsonb_build_object('ok', true, 'replay', false, 'result_id', v_id, 'request_id', v_req,
    'provider_mode', v_mode, 'fixture_id', v_fid, 'fixture_version', v_fver,
    'fixture_hash', v_cat.checksum,
    'payload_digest', encode(sha256(convert_to(v_pay::text,'UTF8')),'hex'));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_catalogue_payment_state_declared()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Only the key that names a monetary state. Every other fixture is untouched.
  if NEW.field_key = 'monetary_state'
     and not exists (select 1 from public.phase_d_payment_state s
                      where s.state_key = (NEW.value #>> '{}')) then
    raise exception 'phase_d_fixture_catalogue: % commits monetary_state %, which is not a rung of public.phase_d_payment_state. BR-020 and BR-033 both read that ladder; a money state outside it is not a state. (pd_catalogue_payment_state_undeclared)',
      NEW.fixture_id, coalesce(NEW.value #>> '{}', '(null)') using errcode = '23514';
  end if;
  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_comparison_visible(p_comparison_id text, p_caller_customer_id text, p_caller_kind text DEFAULT 'customer'::text)
 RETURNS TABLE(visible boolean, refusal_code text, reason text, publication_state text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c public.quote_comparisons%rowtype; v_kind text := lower(coalesce(btrim(p_caller_kind),'customer'));
begin
  if coalesce(btrim(p_comparison_id),'') = '' then
    visible := false; refusal_code := 'pd_comparison_not_named';
    reason := 'No comparison named.'; return next; return;
  end if;
  select * into c from public.quote_comparisons where id::text = btrim(p_comparison_id);
  if not found then
    visible := false; refusal_code := 'pd_comparison_not_named';
    reason := format('%L is not a comparison.', p_comparison_id); return next; return;
  end if;
  publication_state := c.publication_state;

  -- OWNERSHIP FIRST, AND IT IS NEVER SKIPPED FOR ANY CALLER KIND EXCEPT admin. An unrelated
  -- customer must be refused on a PUBLISHED comparison too, which is the arm that proves the
  -- publication leg did not replace the ownership leg.
  if v_kind <> 'admin'
     and c.customer_id::text is distinct from nullif(btrim(coalesce(p_caller_customer_id,'')),'') then
    visible := false; refusal_code := 'pd_comparison_not_the_owner';
    reason := format('comparison %s does not belong to the calling customer', c.id);
    return next; return;
  end if;

  -- The owning SUPPLIER-side and admin callers may read a comparison before publication; a
  -- customer may not. That is the whole of PD-QUOTE-004.
  if v_kind in ('admin','owner_supplier') then
    visible := true; refusal_code := null;
    reason := format('comparison %s read as %s: publication state %s is readable by this caller kind',
                     c.id, v_kind, c.publication_state);
    return next; return;
  end if;

  if c.publication_state <> 'PUBLISHED' then
    visible := false; refusal_code := 'pd_comparison_unpublished';
    reason := format('comparison %s is %s. A customer sees a comparison when it is published, not when it exists.',
                     c.id, c.publication_state);
    return next; return;
  end if;
  if c.superseded_by_comparison_id is not null then
    visible := false; refusal_code := 'pd_comparison_superseded';
    reason := format('comparison %s was superseded by %s', c.id, c.superseded_by_comparison_id);
    return next; return;
  end if;

  visible := true; refusal_code := null;
  reason := format('comparison %s belongs to the calling customer and was published at %s',
                   c.id, c.published_at);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_dispatch_step(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr public.phase_c_workflow_step_run%rowtype;
  v_step_run bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_actor    text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_kind     text   := coalesce(nullif(btrim(p_input->>'opened_by_kind'),''),'(unstated)');
  v_ref      text   := coalesce(nullif(btrim(p_input->>'opened_by_ref'),''),'(unstated)');
  v_idem     text   := coalesce(nullif(btrim(p_input->>'idempotency_key'),''),'');
  v_wf       text;
  v_on       text;
  v_depth    int;
  v_in       jsonb;
  v_cx       jsonb;
  v_res      jsonb;
  v_unres    text[];
  v_err      text;
  v_bkey     text;   -- E25
  v_owner    text;   -- E25
  v_scope    text;   -- E25
  v_own_rel  text;   -- J06
  v_own_col  text;   -- J07
  v_owner_unfit boolean;   -- J07
  v_owner_fit   text;      -- J07
  v_own_ns   text;   -- J06
  v_code     text;
begin
  if v_step_run is null or v_actor is null then
    raise exception 'fn_phase_d_dispatch_step: step_run_id and actor_role_id are required (got %, %)',
      coalesce(v_step_run::text,'(null)'), coalesce(v_actor,'(null)') using errcode = '22023';
  end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if not found then
    raise exception 'fn_phase_d_dispatch_step: no step run %', v_step_run using errcode = '23503';
  end if;

  if not exists (select 1 from public.phase_d_handler_binding hb where hb.step_id = sr.step_id)
     or not exists (select 1 from public.phase_d_step_effect se where se.step_id = sr.step_id) then
    return jsonb_build_object('dispatched', false, 'outcome', 'NO_BINDING', 'step_id', sr.step_id);
  end if;

  select b2.workflow_id into v_wf from public.phase_d_handler_binding b2 where b2.step_id = sr.step_id;
  if v_idem = '' then v_idem := 'kernel|' || sr.run_id || '|' || sr.step_id; end if;

  v_on    := lower(coalesce(nullif(btrim(current_setting('app.phase_d_dispatch', true)),''), 'on'));
  v_depth := coalesce(nullif(btrim(current_setting('app.phase_d_dispatch_depth', true)),'')::int, 0);

  if v_on = 'off' then
    insert into public.phase_d_dispatch
      (step_run_id, run_id, step_id, workflow_id, opened_by_kind, opened_by_ref, actor_role_id,
       outcome, refusal_code, reason, dispatch_depth)
    values (v_step_run, sr.run_id, sr.step_id, v_wf, v_kind, v_ref, v_actor,
            'DISPATCH_OFF', 'pd_dispatch_off',
            'app.phase_d_dispatch is off for this transaction', v_depth);
    return jsonb_build_object('dispatched', false, 'outcome', 'DISPATCH_OFF');
  end if;

  if v_depth >= 64 then
    insert into public.phase_d_dispatch
      (step_run_id, run_id, step_id, workflow_id, opened_by_kind, opened_by_ref, actor_role_id,
       outcome, refusal_code, reason, dispatch_depth)
    values (v_step_run, sr.run_id, sr.step_id, v_wf, v_kind, v_ref, v_actor,
            'DEPTH_LIMIT', 'pd_dispatch_depth_limit',
            format('dispatch depth %s reached at step %s', v_depth, sr.step_id), v_depth);
    return jsonb_build_object('dispatched', false, 'outcome', 'DEPTH_LIMIT', 'depth', v_depth);
  end if;

  perform set_config('app.phase_d_dispatch_depth', (v_depth + 1)::text, true);

  begin
    v_in := public.fn_phase_d_step_inputs(v_step_run);
    select array_agg(x) into v_unres
      from jsonb_array_elements_text(coalesce(v_in->'unresolved','[]'::jsonb)) x;
    v_unres := coalesce(v_unres, '{}');

    if cardinality(v_unres) > 0 then
      insert into public.phase_d_dispatch
        (step_run_id, run_id, step_id, workflow_id, opened_by_kind, opened_by_ref, actor_role_id,
         outcome, refusal_code, reason, unresolved_keys, inputs_provenance, dispatch_depth)
      values (v_step_run, sr.run_id, sr.step_id, v_wf, v_kind, v_ref, v_actor,
              'INPUTS_UNRESOLVED', 'pd_input_unresolved',
              format('%s of the %s declared input keys resolve from no real source: %s',
                     cardinality(v_unres),
                     jsonb_array_length(coalesce(v_in->'declared_keys','[]'::jsonb)),
                     array_to_string(v_unres, ', ')),
              v_unres, coalesce(v_in->'provenance','{}'::jsonb), v_depth);
      perform set_config('app.phase_d_dispatch_depth', v_depth::text, true);
      return jsonb_build_object('dispatched', false, 'outcome', 'INPUTS_UNRESOLVED',
                                'unresolved', to_jsonb(v_unres));
    end if;

    -- D37. The same treatment for what the RULES and GATES read. Unresolved keys are not supplied,
    -- so a rule that needs one refuses instead of passing on a placeholder.
    v_cx := public.fn_phase_d_step_context(v_step_run);

    -- E25. THE DISPATCH WITHHELD THE TWO FIELDS THE WRITE SERVICE REQUIRES, AND IT KNEW BOTH.
    --
    -- fn_phase_d_effect_produce raises pd_effect_owner_or_key_missing for DOMAIN_MUTATION and
    -- VERSIONED_ARTIFACT unless the CALL names business_key and owner_ref. That is the right
    -- behaviour for the routine -- a record written under an owner it chose for itself would be the
    -- auto-vivified account defect in a new place -- but the kernel dispatch passed neither and had
    -- no branch that could. The R3 independent acceptance measured the consequence: 125 of 257 steps
    -- structurally excluded before any rule was consulted, and the only two steps that executed were
    -- KERNEL_ONLY_TRANSITION ones that write no business object at all.
    --
    -- Neither field is invented here. Both are READ, and where they cannot be read the step still
    -- refuses:
    --
    --   owner_ref  COMPANY-scoped object -> phase_c_workflow_step_run.accountable_role_id, which is
    --              the frozen registry's own answer to who is accountable for this step. Not chosen.
    --              CUSTOMER- or SUPPLIER-scoped -> the owner column of the run's OWN business row,
    --              and null when no such row exists. A customer is never conjured to own a record.
    --
    --   business_key  the run's business_object_id, and ONLY when it actually carried the
    --              '<object>:' prefix of the object this step writes -- 'inquiry:<uuid>' is an
    --              identity, 'outbox:195' and a probe label are not. fn_phase_d_step_context reports
    --              key_is_prefixed for exactly this decision.
    --
    -- jsonb_strip_nulls means an underivable field is ABSENT rather than null, so the write service
    -- sees precisely what it saw before and refuses in precisely the same way.
    v_scope := v_cx#>>'{business_object,ownership_scope}';
    if coalesce((v_cx#>>'{business_object,key_is_prefixed}')::boolean, false) then
      v_bkey := nullif(btrim(coalesce(v_cx#>>'{business_object,object_key}','')),'');
    end if;

    -- F13. A STEP THAT WRITES AN OBJECT OTHER THAN ITS RUN'S PRIMARY HAD NO KEY IT COULD EVER GET.
    --
    -- E25 derives business_key from the run's business_object_id and only when it carries the
    -- '<object>:' prefix of the object THIS STEP writes -- which is right, and which means a step
    -- like W01-S07 (run is company_objective:..., step writes the initiative object) can never be prefixed
    -- and refuses with pd_effect_owner_or_key_missing on every drive. That is correct in
    -- production: nothing has told the estate which initiative this is.
    --
    -- Inside a verified Phase D fixture run there IS an answer, and it is a read rather than an
    -- invention: the scenario either already created a record of that object -- in which case this
    -- step mutates THAT record -- or it did not, in which case the key is derived deterministically
    -- from (fixture run, object, run), so the same scenario driven twice produces the same key and
    -- a replay collides with itself instead of creating a second record.
    if v_bkey is null and public.fn_phase_d_fixture_context() is not null then
      -- H05. AN APPEND_ONLY OBJECT IS NEVER WRITTEN UNDER THE SCENARIO'S EXISTING KEY. Its policy is
      -- that a correction is a NEW key, so the scenario's record is not "the record this step
      -- mutates" -- this step appends beside it. The key is derived from the step as well as the
      -- run, so each appending step is its own record and a replay of one step run is one record.
      if exists (select 1 from public.phase_d_business_object_binding bb
                  where bb.object_id = (v_cx#>>'{business_object,object_id}')
                    and bb.policy_family = 'APPEND_ONLY') then
        v_bkey := md5(format('phase_d_fixture:%s:%s:%s:%s',
                             public.fn_phase_d_fixture_context(),
                             v_cx#>>'{business_object,object_id}', sr.run_id, sr.step_id))::uuid::text;
      end if;
    end if;
    if v_bkey is null and public.fn_phase_d_fixture_context() is not null then
      select coalesce(sc.contributed_value, sc.business_key) into v_bkey
        from public.phase_d_scenario_record sc
       where sc.fixture_run_id = public.fn_phase_d_fixture_context()
         and sc.object_id = (v_cx#>>'{business_object,object_id}')
       order by sc.scenario_record_id limit 1;
      if v_bkey is null and (v_cx#>>'{business_object,object_id}') is not null then
        v_bkey := md5(format('phase_d_fixture:%s:%s:%s',
                             public.fn_phase_d_fixture_context(),
                             v_cx#>>'{business_object,object_id}', sr.run_id))::uuid::text;
      end if;
    end if;
    v_owner := nullif(btrim(coalesce(v_cx#>>'{business_object,row_owner_ref}','')),'');
    if v_owner is null and coalesce(v_scope,'COMPANY') = 'COMPANY' then
      v_owner := nullif(btrim(coalesce(sr.accountable_role_id,'')),'');

      -- J07. A ROLE IS NOT ALWAYS WHAT THE OWNER COLUMN HOLDS. E25 made the accountable role the
      -- owner of a COMPANY-scoped write, which is right about WHO is accountable and says nothing
      -- about what the column stores. Measured 23 Aug 2026 on W01-S07: the object is initiative,
      -- the relation public.org_tasks, the owner column dept_key, and
      --
      --   insert or update on table "org_tasks" violates foreign key constraint
      --   "org_tasks_dept_key_fkey"      -- FOREIGN KEY (dept_key) REFERENCES org_departments(dept_key)
      --
      -- because a role id is not a department key. The column's own foreign key settles it: where
      -- the accountable role does not satisfy that key, the answer is the value from this role's
      -- OWN registry row that does. public.org_role.primary_department_id resolves against
      -- public.org_departments for all 180 roles; public.org_agents.department is the same fact
      -- under the runtime key, and is tried second for a role recorded only there.
      --
      -- Nothing is invented and nothing is chosen: two candidates, both read off the role's own
      -- record, each TESTED against the foreign key before it is used. A role whose registry row
      -- satisfies neither leaves the owner exactly as E25 left it, and the write refuses as before.
      select cl3.relname, ns3.nspname, a4.attname
        into v_own_rel, v_own_ns, v_own_col
        from public.phase_d_object_write_map wm3
        join pg_attribute a3 on a3.attrelid = to_regclass(wm3.target_relation)
                            and a3.attname = wm3.owner_column and a3.attnum > 0
        join pg_constraint c3 on c3.conrelid = a3.attrelid and c3.contype = 'f'
                             and a3.attnum = any (c3.conkey)
        join pg_class cl3 on cl3.oid = c3.confrelid
        join pg_namespace ns3 on ns3.oid = cl3.relnamespace
        join pg_attribute a4 on a4.attrelid = c3.confrelid and a4.attnum = c3.confkey[1]
       where wm3.object_id = v_cx#>>'{business_object,object_id}'
         and coalesce(btrim(wm3.owner_column),'') <> ''
       limit 1;

      if v_own_rel is not null and v_owner is not null then
        execute format('select not exists (select 1 from %I.%I where %I::text = $1)',
                       v_own_ns, v_own_rel, v_own_col)
          into v_owner_unfit using v_owner;
        if coalesce(v_owner_unfit, false) then
          execute format(
            'select c.v from (select r.primary_department_id::text v, 1 ord from public.org_role r'
            || ' where r.role_id = $1'
            || ' union all select a.department::text, 2 from public.org_agents a where a.agent_key = $1) c'
            || ' where c.v is not null'
            || '   and exists (select 1 from %I.%I t where t.%I::text = c.v)'
            || ' order by c.ord limit 1',
            v_own_ns, v_own_rel, v_own_col)
            into v_owner_fit using v_owner;
          if v_owner_fit is not null then v_owner := v_owner_fit; end if;
        end if;
      end if;
      v_own_rel := null; v_own_ns := null; v_own_col := null;
    end if;

    -- F37. THE SAME HOLE F13 CLOSED FOR THE KEY, STILL OPEN FOR THE OWNER.
    --
    -- E25 gave a COMPANY-scoped object an owner -- the frozen registry's own accountable role for
    -- the step -- and left CUSTOMER- and SUPPLIER-scoped objects to row_owner_ref, which reads the
    -- owner column of the run's OWN business row. A step that CREATES the first record of such an
    -- object has no such row yet, so the owner is unresolvable by construction and the step refuses
    -- with pd_effect_owner_or_key_missing on every drive. Measured: W10-S01
    -- (supplier_verification_case), W18-S01 (customer_case) and W19-S01 (supplier_retention_case)
    -- are the FIRST handler refusal of their whole workflow, for exactly this.
    --
    -- In production that refusal is right and it stays: a supplier case owned by a supplier this
    -- routine picked would be the auto-vivified account defect one table over.
    --
    -- Inside a verified Phase D fixture run there is a real answer and it is a READ. The scenario
    -- factory created the parent -- a supplier, a customer -- through the canonical services and
    -- recorded it in public.phase_d_scenario_record with its own owner_ref and ownership_scope.
    -- This takes THAT owner, matched on the scope the object declares. It invents nothing, it
    -- cannot fire outside a fixture context, and where the scenario created no parent of that scope
    -- the owner is still null and the step still refuses.
    if v_owner is null
       and coalesce(v_scope,'COMPANY') <> 'COMPANY'
       and public.fn_phase_d_fixture_context() is not null then
      -- J06. WHICH SCENARIO RECORD IS THE OWNER. The block below took the FIRST record of the same
      -- ownership scope, and "same scope" is not an identity. Measured 23 Aug 2026 on one built
      -- scenario, SUPPLIER-scoped records in scenario_record_id order:
      --
      --   supplier_safe_package   owner=9385a4f3-...   <- the INQUIRY's uuid, and the first row
      --   supplier_account        owner=5909be81-...   key=37090
      --   supplier_terms_acceptance owner=37090
      --   supplier_capability     owner=37090
      --   supplier_assignment     owner=37090
      --
      -- so every SUPPLIER-scoped write inherited an inquiry's uuid as its supplier, and
      -- public.supplier_capabilities.supplier_id is bigint: "invalid input syntax for type bigint:
      -- 65d2c329-64dd-0209-1544-e87ef8a30684" -- pd_effect_value_malformed, on W09-S03 and W12-S06.
      --
      -- The owner column already says what it wants, in the schema: it carries a FOREIGN KEY to the
      -- relation that holds the owning party. Read that, find the business object bound to that
      -- relation, and take the key the scenario gave THAT object. Nothing is chosen by position, by
      -- naming convention or by a list of scopes; every step is a read of a record the estate
      -- already holds. Where the owner column carries no foreign key, or the scenario created no
      -- such party, the previous behaviour stands and the step still refuses when it resolves
      -- nothing.
      select cl2.relname, ns2.nspname into v_own_rel, v_own_ns
        from public.phase_d_object_write_map wm2
        join pg_attribute a2 on a2.attrelid = to_regclass(wm2.target_relation)
                            and a2.attname = wm2.owner_column and a2.attnum > 0
        join pg_constraint c2 on c2.conrelid = a2.attrelid and c2.contype = 'f'
                             and a2.attnum = any (c2.conkey)
        join pg_class cl2 on cl2.oid = c2.confrelid
        join pg_namespace ns2 on ns2.oid = cl2.relnamespace
       where wm2.object_id = v_cx#>>'{business_object,object_id}'
         and coalesce(btrim(wm2.owner_column),'') <> ''
       limit 1;

      if v_own_rel is not null then
        select nullif(btrim(coalesce(sc.business_key,'')),'') into v_owner
          from public.phase_d_scenario_record sc
          join public.phase_d_business_object_binding bb on bb.object_id = sc.object_id
         where sc.fixture_run_id = public.fn_phase_d_fixture_context()
           and bb.canonical_relation = v_own_ns || '.' || v_own_rel
           and coalesce(btrim(sc.business_key),'') <> ''
         order by sc.scenario_record_id
         limit 1;
      end if;

      -- L04. AND AN OBJECT THE ESTATE STORES IN public.phase_d_object_record HAS NO WRITE MAP, SO
      -- IT HAS NO OWNER COLUMN AND NO FOREIGN KEY FOR J06 TO READ. All 22 PHASE_D_OBJECT_VIEW
      -- objects fall straight past that block to the positional fallback below -- "the first
      -- scenario record of the same ownership scope" -- which J06 itself recorded is not an
      -- identity. It went unseen because the fixture scenario built those objects too, so nothing
      -- downstream ever had to read one the product had written.
      --
      -- Measured 23 Aug 2026 with the harness withholding the object the workflow under test
      -- produces: W09-S06 wrote the supplier terms acceptance owned by ca99c3de-..., which is the
      -- supplier_safe_package's uuid and the first SUPPLIER-scoped scenario record. The acceptance
      -- therefore belonged to no supplier, "the acceptance this run's party owns" found nothing at
      -- W09-S07, S08 and S09, and BR-025 refused all three from the catalogue.
      --
      -- THE REGISTRY SAYS WHOSE IT IS. The object's governing workflow has a primary object, and
      -- where that primary object is a DIFFERENT object of the SAME ownership scope, that object is
      -- the party. supplier_terms_acceptance is governed by W09 whose primary object is
      -- supplier_account, both SUPPLIER. Nothing is chosen by position. An object that is its own
      -- governing workflow's primary object, or whose governing workflow names none (the two
      -- registered as W16/W27 and W09/W10), resolves nothing here and the fallback below still
      -- runs, so no object loses an owner it had.
      if v_owner is null then
        select nullif(btrim(coalesce(sc.business_key,'')),'') into v_owner
          from public.phase_d_business_object_binding bb
          join public.phase_b_workflow w on w.workflow_id = bb.governing_workflow_id
          join public.phase_d_business_object_binding pb on pb.object_id = w.primary_object
          join public.phase_d_scenario_record sc on sc.object_id = pb.object_id
         where bb.object_id = v_cx#>>'{business_object,object_id}'
           and pb.object_id <> bb.object_id
           and pb.ownership_scope = bb.ownership_scope
           and sc.fixture_run_id = public.fn_phase_d_fixture_context()
           and coalesce(btrim(sc.business_key),'') <> ''
         order by sc.scenario_record_id
         limit 1;
      end if;

      if v_owner is null then
        select nullif(btrim(coalesce(sc.owner_ref,'')),'') into v_owner
          from public.phase_d_scenario_record sc
         where sc.fixture_run_id = public.fn_phase_d_fixture_context()
           and sc.ownership_scope = v_scope
           and coalesce(btrim(sc.owner_ref),'') <> ''
         order by sc.scenario_record_id
         limit 1;
      end if;
    end if;

    v_res := public.fn_phase_d_handler_execute(jsonb_build_object(
      'step_run_id',       v_step_run,
      'actor_role_id',     v_actor,
      'idempotency_key',   v_idem || '|phase_d',
      'inputs',            v_in->'inputs',
      'context',           v_cx->'context',
      'gate_evidence',     v_cx->'context',
      'execution_context', 'production',
      'correlation_id',    p_input->>'correlation_id',
      'causation_id',      'kernel_dispatch:' || v_kind || ':' || v_ref)
      || jsonb_strip_nulls(jsonb_build_object(
      'business_key',      v_bkey,
      'owner_ref',         v_owner)));

    insert into public.phase_d_dispatch
      (step_run_id, run_id, step_id, workflow_id, opened_by_kind, opened_by_ref, actor_role_id,
       outcome, inputs_provenance, effect_id, dispatch_depth)
    values (v_step_run, sr.run_id, sr.step_id, v_wf, v_kind, v_ref, v_actor,
            'EXECUTED',
            coalesce(v_in->'provenance','{}'::jsonb) || coalesce(v_cx->'provenance','{}'::jsonb),
            nullif(v_res#>>'{phase_d,business_effect,effect_id}','')::bigint, v_depth);

    perform set_config('app.phase_d_dispatch_depth', v_depth::text, true);
    return jsonb_build_object('dispatched', true, 'outcome', 'EXECUTED',
             'handler_id', v_res#>>'{phase_d,handler_id}',
             'effect_id',  v_res#>'{phase_d,business_effect,effect_id}');

  exception
    when others then
      v_err  := SQLERRM;
      -- E26. AN UNCLASSIFIED REFUSAL IS AN INSTRUMENT GAP, NOT A CATEGORY.
      -- Once E25 stopped the dispatch withholding business_key and owner_ref, two steps reached the
      -- real business write for the first time and failed on a NOT NULL column of the target
      -- relation -- public.opportunity.kind. That is a genuine and interesting refusal: the payload
      -- carries an IDENTITY for the record but not its CONTENT, and the content of an opportunity is
      -- a judgement no deterministic handler can make while the reasoning capability is held. It
      -- deserves to be named. Recorded as pd_unclassified it looked like a bug in the dispatch.
      --
      -- A raised Phase D or kernel code still wins; this only names what used to fall through.
      v_code := coalesce((regexp_match(v_err, '\((pd_[a-z0-9_]+|k[0-9]+_[a-z0-9_]+)\)'))[1],
        case SQLSTATE
          when '23502' then 'pd_effect_payload_incomplete'   -- not-null column the payload did not fill
          when '23503' then 'pd_effect_reference_unresolved'  -- foreign key the payload pointed nowhere
          when '23505' then 'pd_effect_identity_collision'    -- unique key already taken
          when '23514' then 'pd_effect_check_violated'        -- a check constraint on the target relation
          when '22P02' then 'pd_effect_value_malformed'       -- a value the target column cannot parse
          else 'pd_unclassified' end);
      insert into public.phase_d_dispatch
        (step_run_id, run_id, step_id, workflow_id, opened_by_kind, opened_by_ref, actor_role_id,
         outcome, refusal_code, sqlstate_code, reason, unresolved_keys, inputs_provenance,
         dispatch_depth)
      values (v_step_run, sr.run_id, sr.step_id, v_wf, v_kind, v_ref, v_actor,
              -- E19. This column used to say REFUSED whether the handler had judged the evidence
              -- and rejected it, or had never been given any. Those are different events, and the
              -- 2026-08-20 acceptance audit read the second as the first. Both are refusals and
              -- neither is a pass; only the name differs.
              case when v_code = 'pd_evidence_absent' then 'REFUSED_EVIDENCE_ABSENT' else 'REFUSED' end,
              v_code, SQLSTATE, left(v_err, 1000),
              coalesce((select array_agg(x) from jsonb_array_elements_text(
                          coalesce(v_cx->'unresolved','[]'::jsonb)) x), '{}'),
              coalesce(v_cx->'provenance','{}'::jsonb), v_depth);
      perform set_config('app.phase_d_dispatch_depth', v_depth::text, true);
      return jsonb_build_object('dispatched', false,
                                'outcome', case when v_code = 'pd_evidence_absent'
                                                then 'REFUSED_EVIDENCE_ABSENT' else 'REFUSED' end,
                                'refusal_code', v_code, 'sqlstate', SQLSTATE);
  end;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_drive_workflow(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  w         public.phase_b_workflow%rowtype;
  sr        public.phase_c_workflow_step_run%rowtype;
  hr        public.phase_c_handoff_run%rowtype;
  hc        public.phase_d_handoff_contract%rowtype;
  d         public.phase_d_dispatch%rowtype;
  v_prev    public.phase_c_workflow_step_run%rowtype;
  v_wf      text := nullif(btrim(coalesce(p_input->>'workflow_id','')),'');
  v_label   text := coalesce(nullif(btrim(p_input->>'label'),''), 'phase-d-drive');
  v_ctx     text := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),'production'));
  v_max     int  := coalesce(nullif(p_input->>'max_steps','')::int, 40);
  -- HOLD AT AN OPEN STEP. A caller that means to drive a step's FAILURE branch needs that step
  -- open and owned, and cannot get there by asking the kernel to stop: since PCCR-001 the dispatch
  -- fires when the step OPENS, so a handler that can execute closes its step and the kernel opens
  -- the next one before any caller is consulted. max_steps 0 therefore does not leave a step open
  -- -- measured 23 Aug 2026 on all 30 workflows, 19 of them came back with the run in
  -- waiting_handoff or waiting_review and NO open step run at all, because the successor is not
  -- opened until the receiving owner accepts the handoff. The failure and cancellation probes then
  -- had nothing to act on and were refused 22023 for a null step_run_id, which is a fact about the
  -- probe and not about the estate.
  --
  -- These two inputs let the caller drive the canonical path -- the same handoff acceptances, the
  -- same capability results, the same recorded reviews, the same fn_kernel_step_complete for every
  -- earlier step -- and STOP with one named step open, having completed nothing on it. Nothing is
  -- skipped and no state is written by hand: the run is exactly where a real actor would find it.
  v_hold_step text := nullif(btrim(coalesce(p_input->>'hold_at_step_id','')),'');
  v_hold_any  boolean := coalesce((p_input->>'hold_at_first_open_step')::boolean, false);
  v_held_srid bigint := null;
  v_held_step text := null;
  v_boid    text := nullif(btrim(coalesce(p_input->>'business_object_id','')),'');
  v_caller_reviewer text := nullif(btrim(coalesce(p_input->>'reviewer_role_id','')),'');
  v_cands   text[] := coalesce((select array_agg(x)
                                  from jsonb_array_elements_text(p_input->'reviewer_candidates') x),
                               '{}'::text[]);
  v_run     bigint;
  v_start   jsonb;
  v_steps   jsonb := '[]'::jsonb;
  v_handoffs jsonb := '[]'::jsonb;
  v_i       int := 0;
  v_driven  int := 0;
  v_haccept int := 0;
  v_dispatched int := 0;
  v_executed   int := 0;
  v_before  bigint;
  v_declared text;
  v_rev     text;
  v_task    bigint;
  v_decide  jsonb;
  v_hoff    jsonb;
  v_hpk     jsonb;
  v_err     text; v_sqlstate text; v_code text;
  v_run_state text;
  v_cap_fixture text;      -- F17: the committed CAPABILITY_RESULT row for this step
  v_cap_req   jsonb;       -- F17
  v_cap_res   jsonb;       -- F17
  v_caps      jsonb := '[]'::jsonb;   -- F17: what the capability path did, per step
  v_capn      int := 0;    -- F17: capability results accepted
  v_redisp    jsonb;
  sr2         public.phase_c_workflow_step_run%rowtype;  -- F38: the step run, re-read after dispatch
  v_handler_closed int := 0;          -- F38: steps the handler closed through the kernel itself
  v_seen           bigint[] := '{}';  -- G07: every step run this loop actually observed
  v_unseen         int := 0;          -- G07: handler closures that happened before the loop began
  v_rtask     bigint;                 -- F35: the task the internal review decides
  v_rrev      text;                   -- F35: the reviewer, frozen-declared or independence-tested
  v_rdec      jsonb;                  -- F35: what fn_kernel_review_decide returned
  v_revs      jsonb := '[]'::jsonb;   -- F35: what the review path did, per step
  v_revn      int := 0;               -- F35: internal reviews recorded
  v_stopped jsonb := null;        -- where the DRIVE could go no further, and why
  v_first_refusal jsonb := null;  -- where the deterministic HANDLER first declined, and why
  v_founder_cmd   bigint := null; -- G05: the fixture founder command this run arises from, where one applies
  v_premature     boolean := false;   -- H06: the kernel reported the run already existed
  v_redispatched  int := 0;           -- H06: open steps dispatched again once the scenario was complete
begin
  if v_wf is null then
    raise exception 'fn_phase_d_drive_workflow: workflow_id is required' using errcode = '22023';
  end if;
  -- The kernel dispatch hard-codes 'execution_context','production'. Accepting any other value
  -- here would be this routine promising a mode it has no way to pass on.
  if v_ctx <> 'production' then
    raise exception 'fn_phase_d_drive_workflow: execution_context % is not available. This driver goes through fn_kernel_step_complete, and fn_phase_d_dispatch_step executes the handler in production context with no other mode. (pd_drive_context_unavailable)',
      v_ctx using errcode = '22023';
  end if;

  select * into w from public.phase_b_workflow where workflow_id = v_wf;
  if not found then
    raise exception 'fn_phase_d_drive_workflow: % is not a frozen workflow', v_wf using errcode = '23503';
  end if;

  select count(*) into v_before from public.phase_d_effect_ledger;

  -- THE ARRIVAL NAMES THE OBJECT IT IS ABOUT. E25 derives business_key from the run's
  -- business_object_id and only when it carries the '<object>:' prefix of the object the step
  -- writes - 'inquiry:<uuid>' is an identity, a bare object name is not. The previous driver
  -- passed w.primary_object, which is the object's NAME, so the prefix test was false on every
  -- run it started and the derivation E25 built could never fire through this path.
  v_boid := coalesce(v_boid, w.primary_object || ':' || v_label);

  -- G05. EVERY RUN AROSE BY ITSELF, SO NO RUN COULD REST ON FOUNDER AUTHORITY.
  --
  -- This started every one of the 30 workflows with source_kind 'autonomous' and no command_id.
  -- fn_phase_d_step_context resolves founder_authority_ref from founder_command_workflow_link for
  -- the run, or failing that from phase_c_workflow_run.command_id -- and an autonomous start
  -- leaves both empty by construction. So the key was unresolvable on every run of every workflow,
  -- and the six rules that read it refused every founder-gated step in the estate. Measured:
  -- W03-S01 and W18-S05 refused with "BR-003 requires [founder_authority_ref] and the call names
  -- none of it", and the scenario factory had created a founder command four statements earlier
  -- and handed back founder_authority_ref in its parent_refs, where nothing read it.
  --
  -- The correction is an ARRIVAL, not an injection. fn_kernel_workflow_start already accepts
  -- source_kind 'founder_command' with a command_id, and that is how a founder-instructed run is
  -- really started in production; F12's fixture command is a real row in public.founder_command
  -- created through its own canonical service inside this aborted transaction. Starting the run
  -- from it makes the run's origin TRUE rather than absent. Handing the rule a reference for a run
  -- that arose autonomously would have been the forgery; a run that has no origin at all is simply
  -- a run nothing instructed.
  --
  -- THE FOUNDER COMMAND IS ONLY USED WHERE THE FROZEN REGISTRY SAYS THE WORKFLOW IS FOUNDER-GATED,
  -- and which workflows those are is read from phase_b_business_rule.workflow_scope and
  -- phase_b_workflow_step.founder_gate, never listed here. A workflow with no founder-reserved
  -- step still starts autonomously, and BR-003 stays unresolvable there -- as it should, since
  -- BR-003 does not govern it.
  --
  -- IT AUTHORISES NOTHING BEYOND ITS OWN SENTENCE. The fixture command carries
  -- founder_initiated_only false and refund_semantics false, its founder_identity resolves to
  -- nobody, and founder AUTHENTICATION is fn_phase_c_require_founder, which reads a verified auth
  -- subject and never this table. z00_refund_founder_decision_only on public.refunds is untouched
  -- and still refuses a refund without a founder decision -- measured after this change, not
  -- assumed.
  if exists (select 1 from public.phase_b_workflow_step fs
              where fs.workflow_id = v_wf
                and lower(coalesce(btrim(fs.founder_gate),'none')) <> 'none')
     or exists (select 1 from public.phase_b_business_rule br
                 where br.rule_id in (select re.rule_id from public.phase_d_rule_enforcement re
                                       where 'founder_authority_ref' = any(re.required_context))
                   and (upper(br.workflow_scope) = 'ALL'
                        or v_wf = any(string_to_array(replace(br.workflow_scope,' ',''),';'))))
  then
    -- The command the factory recorded, read from the evidence manifest it wrote — the same row
    -- fn_phase_d_founder_authority_fixture returned, not a second lookup that might find another.
    select nullif(split_part(l.contributed_value, ':', 2),'')::bigint into v_founder_cmd
      from public.phase_d_scenario_record l
     where l.fixture_run_id = public.fn_phase_d_fixture_context()
       and l.contributes_ref = 'founder_authority_ref'
     order by l.scenario_record_id desc limit 1;
  end if;

  v_start := public.fn_kernel_workflow_start(jsonb_build_object(
    'workflow_id',        v_wf,
    'business_object_id', v_boid,
    'source_kind',        case when v_founder_cmd is null then 'autonomous' else 'founder_command' end,
    'source_ref',         format('zz-phase-d-%s-%s', v_label, v_wf),
    'requested_by',       w.accountable_role_id,
    'trigger_ctx',        jsonb_build_object('driver','fn_phase_d_drive_workflow',
                                             'path','kernel doors only'))
    || case when v_founder_cmd is null then '{}'::jsonb
            else jsonb_build_object('command_id', v_founder_cmd) end);
  if v_founder_cmd is not null then
    -- fn_kernel_event_consume refuses an event naming a workflow the command did not select, so the
    -- selection is recorded here rather than left implied by the run alone.
    -- K01. THE run_id WAS NEVER WRITTEN. fn_phase_d_step_context reads this table by run_id
    -- first, and all 15 rows carried run_id null, so that read had never matched a row in the
    -- estate's history. It is stamped here -- and ONLY where the kernel's own row says this command
    -- started this run. Where the arrival started the run first (H06) the command did not instruct
    -- it, and claiming otherwise would put founder authority under a customer's inquiry.
    insert into public.founder_command_workflow_link (command_id, workflow_id, run_id)
    values (v_founder_cmd, v_wf,
            (select r2.run_id from public.phase_c_workflow_run r2
              where r2.run_id = v_run and r2.command_id = v_founder_cmd))
    on conflict (command_id, workflow_id) do update
      set run_id = excluded.run_id
      where public.founder_command_workflow_link.run_id is null
        and excluded.run_id is not null;
  end if;
  v_run := (v_start->>'run_id')::bigint;
  if v_run is null then
    return jsonb_build_object('ok', false, 'workflow_id', v_wf,
      'stopped_because', 'the kernel returned no run_id', 'kernel_result', v_start);
  end if;

  -- H06. THE RUN ALREADY EXISTED: the scenario's own arrival started it before the scenario was
  -- complete, and its first dispatch judged half a world. Each open step run whose latest dispatch
  -- was a refusal is dispatched once more, through the same door, under the kernel's own key.
  if coalesce((v_start->>'duplicate')::boolean, false) then
    v_premature := true;
    for sr in select * from public.phase_c_workflow_step_run
               where run_id = v_run
                 and state in ('ready','active','not_ready','waiting_input','waiting_review','blocked')
               order by step_run_id
    loop
      select * into d from public.phase_d_dispatch
       where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;
      if found and d.outcome <> 'EXECUTED' then
        begin
          perform public.fn_phase_d_dispatch_step(jsonb_build_object(
            'step_run_id',     sr.step_run_id,
            'actor_role_id',   sr.accountable_role_id,
            'opened_by_kind',  'scenario_complete',
            'opened_by_ref',   format('the scenario finished after the arrival opened %s', sr.step_id),
            'idempotency_key', (select ws.idempotency_scope from public.phase_b_workflow_step ws
                                 where ws.step_id = sr.step_id) || '|' || v_run || '|' || sr.step_id || '|kernel'));
          v_redispatched := v_redispatched + 1;
        exception when others then null;
        end;
      end if;
    end loop;
  end if;

  loop
    v_i := v_i + 1;
    exit when v_i > v_max;

    select * into sr from public.phase_c_workflow_step_run
     where run_id = v_run
       and state in ('ready','active','not_ready','waiting_input','waiting_review','blocked')
     order by step_run_id
     limit 1;

    -- ---- NO OPEN STEP RUN IS NOT NECESSARILY A STOPPED RUN -----------------------------------
    -- The kernel opens no successor until the receiving owner accepts the handoff.
    if not found then
      select * into hr from public.phase_c_handoff_run
       where run_id = v_run and status = 'open'
       order by handoff_run_id limit 1;
      -- A DRIVER THAT STOPS WITHOUT SAYING WHY IS THE INSTRUMENT GAP THIS ESTATE KEEPS FINDING.
      -- Both of these were a bare `exit when not found` in my first draft, so a run that ended in
      -- waiting_handoff with no D9 contract reported a stop with an empty reason, and a reader
      -- would have taken the blank for "nothing went wrong".
      if not found then
        if v_stopped is null then
          v_stopped := jsonb_build_object(
            'at', (select state from public.phase_c_workflow_run where run_id = v_run),
            'refused_with','pd_drive_no_open_work',
            -- NO run_id IN A REPRODUCIBLE DELIVERABLE. This read "...on run 25384", and a run_id is
            -- different every drive, so the committed CSV could never reproduce byte-for-byte and
            -- phase_d_deliverables_match_production.test.mjs failed on thirty lines that differed
            -- only in that number. The run_id is on the row already, as run_id; a reason is a
            -- reason.
            'reason', 'no step run is open and no handoff run is open; the run is as far as the kernel will take it');
        end if;
        exit;
      end if;

      select * into hc from public.phase_d_handoff_contract where handoff_id = hr.handoff_id;
      if not found then
        if v_stopped is null then
          v_stopped := jsonb_build_object('at', hr.handoff_id, 'refused_with','pd_handoff_contract_absent',
            'reason', format('handoff %s is open and public.phase_d_handoff_contract holds no row for it, so this driver has no packet contract to satisfy', hr.handoff_id));
        end if;
        v_handoffs := v_handoffs || jsonb_build_array(jsonb_build_object(
          'handoff_id', hr.handoff_id, 'handoff_run_id', hr.handoff_run_id,
          'ok', false, 'refused_with', 'pd_handoff_contract_absent'));
        exit;
      end if;

      select * into v_prev from public.phase_c_workflow_step_run
       where step_run_id = hr.from_step_run_id;

      -- Derived where the estate can derive it; a labelled caller assertion for the work-product
      -- keys, which are what the sending PERSON hands over and no business rule ever reads.
      v_hpk := coalesce((select jsonb_object_agg(k, format('ZZ DEMO - %s declared by the driver standing in for %s', k, hc.sending_role_id))
                           from unnest(hc.packet_keys) k), '{}'::jsonb)
             || jsonb_build_object(
                  'business_object_id',
                    coalesce((select business_object_id from public.phase_c_workflow_run
                               where run_id = v_run), v_boid),
                  'object_version', coalesce(hr.object_version, 1),
                  'output', coalesce(v_prev.output_hash,
                                     'no output hash recorded on the sending step run'),
                  'evidence_refs',
                    coalesce((select string_agg(result_reference, '; ' order by effect_id)
                                from public.phase_d_effect_ledger
                               where step_run_id = hr.from_step_run_id),
                             'no Phase D effect recorded for the sending step run'),
                  'requested_action',
                    coalesce((select required_action from public.phase_b_workflow_step
                               where step_id = hc.to_step_id),
                             'the frozen receiving step names no required action'));

      begin
        v_hoff := public.fn_phase_d_handoff_accept(jsonb_build_object(
          'handoff_run_id',  hr.handoff_run_id,
          'actor_role_id',   hc.receiving_role_id,
          'packet',          v_hpk,
          'idempotency_key', format('%s:%s:%s', v_label, hr.handoff_id, hr.handoff_run_id)));
        v_haccept := v_haccept + 1;
        v_handoffs := v_handoffs || jsonb_build_array(jsonb_build_object(
          'handoff_id', hr.handoff_id, 'handoff_run_id', hr.handoff_run_id,
          'ok', v_hoff->'ok', 'to_step_id', v_hoff->>'to_step_id',
          'accountable_after', v_hoff->>'accountable_after'));
        continue;
      exception when others then
        v_sqlstate := SQLSTATE; v_err := SQLERRM;
        v_code := coalesce((regexp_match(v_err, '\((pd_[a-z0-9_]+|k[0-9]+_[a-z0-9_]+)\)'))[1], '(none)');
        v_handoffs := v_handoffs || jsonb_build_array(jsonb_build_object(
          'handoff_id', hr.handoff_id, 'handoff_run_id', hr.handoff_run_id,
          'ok', false, 'refused_with', v_code, 'sqlstate', v_sqlstate,
          'reason', left(v_err, 400)));
        if v_stopped is null then
          v_stopped := jsonb_build_object('at', hr.handoff_id, 'refused_with', v_code,
                                          'reason', left(v_err, 400));
        end if;
        -- A driver that skipped a refused handoff would report a closure the workflow never reached.
        exit;
      end;
    end if;

    -- ---- THE HOLD ----------------------------------------------------------------------------
    -- Reached only through the doors above: every earlier step was completed through
    -- fn_kernel_step_complete and every earlier handoff through fn_phase_d_handoff_accept. This
    -- step run is open because the kernel opened it and nothing has closed it.
    if v_hold_any or (v_hold_step is not null and sr.step_id = v_hold_step) then
      v_held_srid := sr.step_run_id;
      v_held_step := sr.step_id;
      v_seen := v_seen || sr.step_run_id;
      if v_stopped is null then
        v_stopped := jsonb_build_object('at', sr.step_id, 'refused_with', 'pd_drive_held_open',
          'reason', 'the caller asked this drive to stop with this step open; nothing was completed on it');
      end if;
      exit;
    end if;

    -- ---- WHAT THE DETERMINISTIC HANDLER DID WITH THIS STEP ------------------------------------
    -- It has already happened. The dispatch fires when the kernel OPENS the step, so by the time
    -- this loop sees an open step run the row is on the table. Reading it is the whole of what this
    -- driver has to do to measure Phase D; it never calls the handler itself.
    select * into d from public.phase_d_dispatch
     where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;

    -- ---- F17. THE CAPABILITY RESULT ARRIVES, AND THE STEP IS DISPATCHED AGAIN ------------------
    -- The founder's section C sequence is: capability request -> capability result -> output
    -- validation -> evidence/provenance -> handler continuation. F05 built the first four and left
    -- the fifth to the caller, because the request is opened INSIDE fn_kernel_open_step and there is
    -- no moment between the open and the refusal for anyone to answer it. This is that moment: the
    -- kernel opened the step, the handler asked and was refused for want of an answer, and the
    -- driver -- standing in for whoever supplies the capability -- submits the pre-authored fixture
    -- result through the canonical acceptance service and asks the estate to dispatch the step
    -- again.
    --
    -- Nothing here bypasses anything. fn_phase_d_capability_result_accept still requires a verified
    -- Phase D fixture context, still validates the payload against the step's own output contract,
    -- still records the fixture id, version and hash, and still refuses provider_mode = provider
    -- while the hold stands. If any of that refuses, the step stays refused and the refusal is
    -- recorded below rather than swallowed.
    if found and d.refusal_code = 'pd_capability_unavailable'
       and public.fn_phase_d_fixture_context() is not null then
      select c.fixture_id into v_cap_fixture
        from public.phase_d_fixture_catalogue c
       where c.scope = 'CAPABILITY_RESULT' and c.step_id = sr.step_id
       order by c.fixture_id limit 1;
      begin
        if v_cap_fixture is null then
          raise exception 'no committed CAPABILITY_RESULT fixture for step % (pd_capability_fixture_unknown)', sr.step_id
            using errcode = '23503';
        end if;
        v_cap_req := public.fn_phase_d_capability_request_open(jsonb_build_object(
          'step_run_id', sr.step_run_id, 'requested_by', sr.accountable_role_id));
        v_cap_res := public.fn_phase_d_capability_result_accept(jsonb_build_object(
          'request_id',    v_cap_req->'request_id',
          'provider_mode', 'fixture',
          'fixture_id',    v_cap_fixture,
          'accepted_by',   sr.accountable_role_id));
        v_capn := v_capn + 1;
        -- HANDLER CONTINUATION: the same door the kernel used, on the same step run.
        v_redisp := public.fn_phase_d_dispatch_step(jsonb_build_object(
          'step_run_id',     sr.step_run_id,
          'actor_role_id',   sr.accountable_role_id,
          'opened_by_kind',  'capability_result',
          'opened_by_ref',   format('%s:result=%s', v_cap_fixture, v_cap_res->>'result_id'),
          'idempotency_key', format('%s:%s:%s:cap', v_label, sr.step_id, sr.step_run_id)));
        v_caps := v_caps || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'request_id', v_cap_req->'request_id',
          'result_id', v_cap_res->'result_id', 'provider_mode', v_cap_res->>'provider_mode',
          'fixture_id', v_cap_res->>'fixture_id', 'fixture_version', v_cap_res->'fixture_version',
          'fixture_hash', v_cap_res->>'fixture_hash',
          'redispatch_outcome', v_redisp->>'outcome',
          'redispatch_refusal', v_redisp->>'refusal_code'));
        select * into d from public.phase_d_dispatch
         where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;
      exception when others then
        v_caps := v_caps || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'fixture_id', v_cap_fixture, 'ok', false,
          'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
          'reason', left(SQLERRM, 300)));
      end;
      v_cap_fixture := null;
    end if;

    -- ---- THE INTERNAL REVIEW, THROUGH THE KERNEL'S OWN DOOR, THEN ASK AGAIN (F35) -----------
    -- The mirror of the capability block above, for the other input class the handler cannot
    -- invent. F34 made fn_phase_d_handler_execute read the verdict and the reviewer from the review
    -- the estate RECORDED -- phase_c_task.reviewer_role_id and the sealed TRACE-ROLE-ACTION -- and
    -- refuse with pd_review_not_recorded when there is none. There is none at step-open time,
    -- because the kernel dispatches the handler the instant the step opens and no review has
    -- happened yet. This is the moment one can: the step is open and owned, the handler has said
    -- what it is missing, and the driver -- standing in for the reviewer -- records the decision
    -- through fn_kernel_review_decide and asks the estate to dispatch the step again.
    --
    -- NOTHING IS BYPASSED. fn_kernel_review_decide refuses a reviewer the frozen registry did not
    -- name where it names one, refuses a reviewer who resolves to the creator, refuses a review
    -- with no stated reason, and seals its own trace. The reviewer is never chosen by preference
    -- here: it is the frozen independent_reviewer_role_id, or a candidate the kernel's own
    -- independence test allows. If it refuses, the step stays refused and the refusal is recorded.
    -- H11. Also record a review when a gate refused for want of the reviewer, not only when the
    -- REVIEW_HANDLER raised pd_review_not_recorded. Same review, same door, same independence check.
    if found and (d.refusal_code = 'pd_review_not_recorded'
                  or (d.refusal_code in ('pd_evidence_absent','pd_gate_refused')
                      and coalesce(d.reason,'') ilike '%reviewer_role_id%')) then
      begin
        select t.task_id into v_rtask from public.phase_c_task t
         where t.run_id = sr.run_id and t.step_id = sr.step_id
         order by t.task_id desc limit 1;

        select s2.independent_reviewer_role_id into v_rrev
          from public.phase_b_workflow_step s2 where s2.step_id = sr.step_id;
        v_rrev := nullif(btrim(coalesce(v_rrev,'')),'');
        if v_rrev is null then
          v_rrev := (select c from unnest(v_cands) c
                      where public.fn_kernel_reviewer_independent(sr.accountable_role_id, c)
                      limit 1);
        end if;
        if v_rrev is null and v_caller_reviewer is not null
           and public.fn_kernel_reviewer_independent(sr.accountable_role_id, v_caller_reviewer) then
          v_rrev := v_caller_reviewer;
        end if;

        if v_rtask is null then
          raise exception 'step % has no task to review (pd_review_no_task)', sr.step_id
            using errcode = '23503';
        end if;
        if v_rrev is null then
          raise exception 'step % is owned by % and no candidate role passes the kernel independence test against it (pd_review_no_independent_reviewer)',
            sr.step_id, sr.accountable_role_id using errcode = '23503';
        end if;

        -- The stated reason is the committed rationale fixture, not a sentence written here.
        v_rdec := public.fn_kernel_review_decide(jsonb_build_object(
          'task_id',          v_rtask,
          'reviewer_role_id', v_rrev,
          'decision',         'approved',
          'reason',           coalesce(
                                public.fn_phase_d_fixture_output(sr.step_id,'rationale') #>> '{}',
                                'PHASE_D_FIXTURE_DO_NOT_PUBLISH - no committed rationale fixture')));

        if coalesce((v_rdec->>'ok')::boolean, false) then
          v_redisp := public.fn_phase_d_dispatch_step(jsonb_build_object(
            'step_run_id',     sr.step_run_id,
            'actor_role_id',   sr.accountable_role_id,
            'opened_by_kind',  'internal_review',
            'opened_by_ref',   format('task=%s;reviewer=%s', v_rtask, v_rrev),
            'idempotency_key', format('%s:%s:%s:rev', v_label, sr.step_id, sr.step_run_id)));
          select * into d from public.phase_d_dispatch
           where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;
        end if;

        v_revn := v_revn + 1;
        v_revs := v_revs || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'task_id', v_rtask, 'reviewer_role_id', v_rrev,
          'review_ok', v_rdec->'ok', 'review_error', v_rdec->>'error',
          'redispatch_outcome', v_redisp->>'outcome',
          'redispatch_refusal', v_redisp->>'refusal_code'));
      exception when others then
        v_revs := v_revs || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'ok', false,
          'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
          'reason', left(SQLERRM, 300)));
      end;
    end if;

    if found then
      v_dispatched := v_dispatched + 1;
      if d.outcome = 'EXECUTED' then v_executed := v_executed + 1; end if;
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'ok', (d.outcome = 'EXECUTED'), 'dispatch_outcome', d.outcome,
        'refused_with', nullif(d.refusal_code,''), 'reason', left(coalesce(d.reason,''), 400),
        'unresolved_keys', to_jsonb(coalesce(d.unresolved_keys,'{}'::text[])),
        'effect_id', d.effect_id));
      -- TWO SUBJECTS, TWO FIELDS. My first draft folded both into one 'stopped' object, and the
      -- deliverable then reported W21 as stopping at W21-S01 when the drive had in fact reached
      -- W21-S07 -- because step 1's dispatch refused, as nearly every dispatch does, and that was
      -- the first thing to claim the field. Where the HANDLER first declined is a Phase D fact;
      -- where the DRIVE could go no further is a fact about this harness and the kernel.
      if d.outcome <> 'EXECUTED' and v_first_refusal is null then
        v_first_refusal := jsonb_build_object('at', sr.step_id,
                                              'refused_with', nullif(d.refusal_code,''),
                                              'reason', left(coalesce(d.reason,''), 400));
      end if;
    else
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'ok', false, 'dispatch_outcome', 'NOT_DISPATCHED',
        'refused_with', 'pd_no_dispatch_row',
        'reason', 'the kernel opened this step and no phase_d_dispatch row exists for it'));
      if v_first_refusal is null then
        v_first_refusal := jsonb_build_object('at', sr.step_id, 'refused_with','pd_no_dispatch_row',
          'reason','the kernel opened this step and no phase_d_dispatch row exists for it');
      end if;
    end if;

    -- ---- F38. THE HANDLER MAY HAVE ALREADY COMPLETED THIS STEP -----------------------------
    -- fn_phase_d_handler_execute section 7 hands the completed step to the FROZEN KERNEL itself.
    -- When it succeeds, the kernel closes the step run, opens the successor, and -- where the step
    -- ends in a handoff -- moves the whole run to waiting_handoff. The driver then arrived at its
    -- own fn_kernel_step_complete for a step that was already closed, against a run that was no
    -- longer active, and was refused:
    --
    --   k3_run_not_active: workflow run N is in state waiting_handoff, not active
    --
    -- and the drive stopped there. MEASURED, and it is the reason a fix made the headline fall:
    -- after F36 let the five capability steps execute, total EXECUTED across the estate went from
    -- 45 to 36, because every workflow whose handler succeeded early now died at the next
    -- iteration. Success in one place was being converted into an earlier stop.
    --
    -- The kernel is right on both counts and neither is touched. What was wrong is that this
    -- driver assumed every step needs an actor to close it. A step the HANDLER closed is closed;
    -- the driver re-reads the step run and, if the kernel has moved it out of every open state,
    -- takes the next piece of work instead of trying to close it twice.
    --
    -- This is also the §4 distinction the founder asked for: a step closed here is
    -- CANONICAL_HANDLER_EFFECT, and a step closed below is CANONICAL_ACTOR_INPUT. They are counted
    -- apart because they are different claims.
    v_seen := v_seen || sr.step_run_id;   -- G07: what this loop saw, so what it did not see is derivable
    select * into sr2 from public.phase_c_workflow_step_run where step_run_id = sr.step_run_id;
    if found and sr2.state not in
       ('ready','active','not_ready','waiting_input','waiting_review','blocked') then
      v_handler_closed := v_handler_closed + 1;
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'closed_by', 'CANONICAL_HANDLER_EFFECT', 'step_run_state', sr2.state));
      continue;
    end if;

    -- ---- A STEP THAT NEEDS AN INDEPENDENT VERDICT GETS ONE, THROUGH THE KERNEL'S OWN DOOR ------
    -- The reviewer is never chosen here: it is the one the frozen registry declares, or one the
    -- CALLER offered, and fn_kernel_review_decide decides independence either way. A driver that
    -- picked a reviewer would be fn_pick_reviewer returning the department head, one layer up.
    select s.independent_reviewer_role_id into v_declared
      from public.phase_b_workflow_step s where s.step_id = sr.step_id;
    v_rev := nullif(btrim(coalesce(v_declared,'')),'');
    if v_rev is null then
      v_rev := (select c from unnest(v_cands) c
                 where public.fn_kernel_reviewer_independent(sr.accountable_role_id, c) limit 1);
    end if;
    if v_rev is null and v_caller_reviewer is not null
       and public.fn_kernel_reviewer_independent(sr.accountable_role_id, v_caller_reviewer) then
      v_rev := v_caller_reviewer;
    end if;
    if v_rev is not null then
      select t.task_id into v_task from public.phase_c_task t
       where t.run_id = v_run and t.step_id = sr.step_id order by t.task_id desc limit 1;
      if v_task is not null then
        begin
          v_decide := public.fn_kernel_review_decide(jsonb_build_object(
            'task_id', v_task, 'reviewer_role_id', v_rev, 'decision', 'approved',
            'reason', format('%s: an independent reviewer approves %s', v_label, sr.step_id)));
        exception when others then
          -- Recorded, never swallowed: a verdict that could not be written is why the step may
          -- refuse a moment later, and a driver that hid it would make that refusal unexplainable.
          v_decide := jsonb_build_object('ok', false, 'error', left(SQLERRM, 240));
        end;
      end if;
    end if;

    -- ---- THE DOOR PRODUCTION USES ------------------------------------------------------------
    -- fn_kernel_step_complete, with what an ACTOR supplies and nothing else. No context, no gate
    -- evidence, no business_key, no owner_ref, no effect payload: the kernel dispatch resolves all
    -- of those from fn_phase_d_step_inputs and fn_phase_d_step_context, and will not accept them
    -- from a caller. That is the property this file exists to restore.
    begin
      perform public.fn_kernel_step_complete(jsonb_build_object(
        'step_run_id',      sr.step_run_id,
        'actor_role_id',    sr.accountable_role_id,
        'outcome',          'pass',
        'idempotency_key',  format('%s:%s:%s', v_label, sr.step_id, sr.step_run_id),
        'inputs',           jsonb_build_object('driver','fn_phase_d_drive_workflow',
                                               'note','no business content is supplied by this driver'),
        'output',           jsonb_build_object('status','completed',
                                               'output', format('%s completed %s', v_label, sr.step_id)),
        'evidence_refs',    jsonb_build_array(jsonb_build_object('driver_run', v_label)),
        'requested_action', 'proceed',
        'acceptance_criteria', format('%s drove %s through the kernel', v_label, sr.step_id),
        'object_version',   1));
      v_driven := v_driven + 1;
    exception when others then
      v_sqlstate := SQLSTATE; v_err := SQLERRM;
      v_code := coalesce((regexp_match(v_err, '\((pd_[a-z0-9_]+|k[0-9]+_[a-z0-9_]+)\)'))[1], '(none)');
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'ok', false, 'kernel_refused', true, 'refused_with', v_code,
        'sqlstate', v_sqlstate, 'reason', left(v_err, 400)));
      v_stopped := jsonb_build_object('at', sr.step_id, 'refused_with', v_code,
                                      'reason', left(v_err, 400),
                                      'refused_by', 'fn_kernel_step_complete');
      exit;
    end;
  end loop;

  select state into v_run_state from public.phase_c_workflow_run where run_id = v_run;

  -- G07. THE CLOSURES THIS LOOP NEVER SAW, read from the ledger that already recorded them.
  -- A step run carrying an EXECUTED dispatch and sitting in no open state was closed by the
  -- handler's own call into fn_kernel_step_complete. Excluding the step runs the loop handled makes
  -- the two counts disjoint by construction rather than by argument.
  -- ALIASED disp, NOT d: this routine declares a RECORD named d, and a plpgsql variable shadows a
  -- table alias of the same name rather than losing to it.
  select count(distinct disp.step_run_id) into v_unseen
    from public.phase_d_dispatch disp
    join public.phase_c_workflow_step_run x on x.step_run_id = disp.step_run_id
   where disp.run_id = v_run
     and disp.outcome = 'EXECUTED'
     and x.state not in ('ready','active','not_ready','waiting_input','waiting_review','blocked')
     and not (disp.step_run_id = any(v_seen));

  return jsonb_build_object(
    'ok', true,
    'workflow_id', v_wf,
    'run_id', v_run,
    'label', v_label,
    -- Named for what it measures, not for what a reader might hope it measures.
    'path', 'fn_kernel_workflow_start -> fn_kernel_review_decide -> fn_kernel_step_complete -> fn_phase_d_handoff_accept',
    'steps_in_workflow', (select count(*) from public.phase_b_workflow_step where workflow_id = v_wf),
    'held_step_id', v_held_step,
    'held_step_run_id', v_held_srid,
    'steps_driven', v_driven,
    'handoffs_accepted', v_haccept,
    'open_handoffs_left', (select count(*) from public.phase_c_handoff_run
                            where run_id = v_run and status = 'open'),
    -- What Phase D actually did: how many step-openings the kernel dispatched to the
    -- deterministic handler, and how many of those the handler completed unaided.
    -- COUNTED FROM THE TABLE, NOT FROM THIS LOOP. The first version incremented these as the loop
    -- walked the open steps, and it reported dispatches_executed = 0 on a run that had produced
    -- three effect-ledger rows. The reason is the whole of E33: a step whose handler EXECUTES has
    -- its task closed in the same statement that opened it, so it is never an open step and this
    -- loop never sees it. An instrument that counts only what it walks past cannot count the thing
    -- that finishes before the walk reaches it. The population is every dispatch the kernel
    -- produced for this run.
    'dispatches_seen', (select count(*) from public.phase_d_dispatch where run_id = v_run),
    'dispatches_executed', (select count(*) from public.phase_d_dispatch
                             where run_id = v_run and outcome = 'EXECUTED'),
    'dispatch_outcomes', (select coalesce(jsonb_object_agg(o, n), '{}'::jsonb) from (
        select coalesce(nullif(refusal_code,''), outcome) o, count(*) n
          from public.phase_d_dispatch where run_id = v_run group by 1) z),
    'steps_loop_walked', v_dispatched,
    'effects_for_this_run', (select count(*) from public.phase_d_effect_ledger where run_id = v_run),
    'effects_total_delta', (select count(*) from public.phase_d_effect_ledger) - v_before,
    'run_state', v_run_state,
    -- phase_b_workflow.allowed_terminal_states is TEXT, not an array: 'completed; cancelled;
    -- superseded'. My first draft wrote `v_run_state = any((select allowed_terminal_states ...))`,
    -- which Postgres parses as the SUBQUERY form of ANY — so it compared the run state against the
    -- whole semicolon-separated string as one value and was false for every run ever driven.
    -- closure_verdict could therefore only ever read STOPPED, and this deliverable reported 0 of 30
    -- closing while runs were reaching 'completed'. Caught by the deliverable's own reproduction
    -- test, not by reading the code.
    'terminal', exists (
       select 1 from public.phase_b_workflow w2,
            lateral unnest(string_to_array(coalesce(w2.allowed_terminal_states,''), ';')) s
        where w2.workflow_id = v_wf and btrim(s) = v_run_state),
    -- Where the DRIVE could go no further. Null only when the run reached a terminal state with
    -- nothing open, which is the one case where "it stopped" needs no explanation.
    'stopped', coalesce(v_stopped, case when v_i > v_max
      then jsonb_build_object('at','(step budget)','refused_with','pd_drive_max_steps',
             'reason', format('the drive ran %s steps and max_steps is %s', v_i - 1, v_max))
      else null end),
    -- Where the deterministic HANDLER first declined. This is the Phase D subject, and it is a
    -- different question from the one above. Read from the dispatch table in dispatch order for
    -- the same reason the counts are: the loop does not see every dispatched step.
    'first_handler_refusal', coalesce(
      (select jsonb_build_object('at', step_id, 'refused_with', nullif(refusal_code,''),
                                 'reason', left(coalesce(reason,''), 400))
         from public.phase_d_dispatch
        where run_id = v_run and outcome <> 'EXECUTED'
        order by dispatch_id limit 1), v_first_refusal),
    'capability_results_accepted', v_capn,
    'premature_arrival_run', v_premature,
    'steps_redispatched_after_scenario', v_redispatched,
    'capability_path', v_caps,
    'steps_closed_by_the_handler', v_handler_closed + v_unseen,
    'steps_closed_by_the_handler_before_the_loop_began', v_unseen,
    'internal_reviews_recorded', v_revn,
    'review_path', v_revs,
    'steps', v_steps,
    'handoffs', v_handoffs);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_effect_produce(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e            public.phase_d_step_effect%rowtype;
  sr           public.phase_c_workflow_step_run%rowtype;
  prior        public.phase_d_effect_ledger%rowtype;
  v_step_run   bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_idem       text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_actor      text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_payload    jsonb  := coalesce(p_input->'payload','{}'::jsonb);
  v_key        text   := nullif(btrim(coalesce(p_input->>'business_key','')),'');
  v_owner      text   := nullif(btrim(coalesce(p_input->>'owner_ref','')),'');
  v_state      text   := nullif(btrim(coalesce(p_input->>'state','')),'');
  v_ctx        text   := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),'production'));
  v_write      jsonb;
  v_result_ref text;
  v_relation   text;
  v_mode       text := 'none';
  v_eid        bigint;
  v_num        numeric; v_den numeric;
  v_cap        jsonb;   -- F05: the accepted capability result for this step run, or null
  v_parent_col text;    -- K02: the parent identity the object's binding declares
  v_parent_src text;    -- K02: the payload key the write map reads it from
  v_parent_val jsonb;   -- K02: what the step context resolves for it
begin
  if v_step_run is null or v_idem is null or v_actor is null then
    raise exception 'fn_phase_d_effect_produce: step_run_id, idempotency_key and actor_role_id are all required (pd_effect_input_invalid)'
      using errcode = '22023';
  end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if not found then
    raise exception 'fn_phase_d_effect_produce: no step run % (pd_step_state_invalid)', v_step_run
      using errcode = '23503';
  end if;

  select * into e from public.phase_d_step_effect where step_id = sr.step_id;
  if not found then
    raise exception 'fn_phase_d_effect_produce: step % has no declared effect contract — fail closed. All 257 frozen steps carry one. (pd_effect_undeclared)',
      sr.step_id using errcode = '23503';
  end if;

  -- ---- IDEMPOTENCY IS A READ, NOT A HOPE -------------------------------------------------
  -- A replayed handler must produce NO second effect. The assertion a duplicate-effect test makes
  -- is the ledger ROW COUNT, not the returned payload, so the check is done here and the prior
  -- row is returned verbatim.
  select * into prior from public.phase_d_effect_ledger
   where step_run_id = v_step_run and effect_type = e.expected_effect_type;
  if found then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'effect_id', prior.effect_id,
      'effect_type', prior.effect_type, 'effect_object_id', prior.effect_object_id,
      'result_reference', prior.result_reference, 'provider_mode', prior.provider_mode,
      'note', 'the effect for this step run already exists; no second effect was produced');
  end if;

  -- ---- K02. THE PARENT THE OBJECT DECLARES -------------------------------------------------
  -- public.phase_d_object_write skips a mapped column whose source key the payload does not carry,
  -- and fn_phase_d_fixture_effect_payload only fills columns the RELATION demands. A parent column
  -- that is nullable demands nothing, so supplier_assignment was written with no inquiry_id and a
  -- BEFORE trigger dropped the row. The object's own binding already names its parent; that is read
  -- here, and the value comes from the step context, which resolves an identity from the row it
  -- names. Nothing is invented and no constant is used: an identity is never a fixture.
  select bb.parent_identity, wm.column_map->>bb.parent_identity
    into v_parent_col, v_parent_src
    from public.phase_d_business_object_binding bb
    join public.phase_d_object_write_map wm on wm.object_id = bb.object_id
   where bb.object_id = e.effect_object_id
     and coalesce(btrim(bb.parent_identity),'') <> ''
     and wm.column_map ? bb.parent_identity;
  if v_parent_src is not null
     and v_parent_src not in ('business_key','owner_ref','state')
     and (not (v_payload ? v_parent_src) or v_payload->v_parent_src = 'null'::jsonb) then
    v_parent_val := (public.fn_phase_d_step_context(v_step_run))->'context'->v_parent_src;
    if v_parent_val is not null and v_parent_val <> 'null'::jsonb then
      v_payload := v_payload || jsonb_build_object(v_parent_src, v_parent_val);
    end if;
  end if;

  -- ---- the seven types -------------------------------------------------------------------
  if e.expected_effect_type = 'KERNEL_ONLY_TRANSITION' then
    -- Nothing is written here beyond the ledger entry. The effect IS the kernel's step run and
    -- run-state move, which is persistent and kernel-verifiable; a domain row invented to make a
    -- count look better would be a fabricated effect.
    v_result_ref := format('public.phase_c_workflow_step_run:step_run_id=%s', v_step_run);
    v_relation   := 'public.phase_c_workflow_step_run';

  elsif e.expected_effect_type = 'CAPABILITY_REQUEST' then
    -- Fail closed in production, and record the refusal as the effect. A capability step whose
    -- effect was a success record would be a mock completing a business step.
    -- F05. This read `if v_ctx <> 'test' then raise`, which is the bypass the founder prohibited
    -- seen from the effect side: the string 'test' turned the refusal into a record. The subject
    -- is now the same one the handler asks about -- is there an ACCEPTED capability result for
    -- this step run? The declared effect of a capability step IS the request; what the result
    -- adds is the answer it can point at, and its provider_mode is recorded rather than assumed.
    v_cap := public.fn_phase_d_capability_answer(v_step_run);
    if v_cap is null then
      raise exception 'fn_phase_d_effect_produce: step % is capability-dependent and its capability request carries no accepted result. The declared effect is a refusal, not a record. No execution context lifts this. (pd_capability_unavailable)',
        sr.step_id using errcode = '23514';
    end if;
    v_result_ref := format('capability_request:%s:result=%s:mode=%s:digest=%s',
                           v_cap->>'request_id', v_cap->>'result_id', v_cap->>'provider_mode',
                           left(coalesce(v_cap->>'payload_digest',''), 12));
    v_relation   := 'public.phase_d_capability_result';
    v_mode       := v_cap->>'provider_mode';

  elsif e.expected_effect_type = 'EXTERNAL_EFFECT_INTENT' then
    -- MOCK, ALWAYS. provider_mode has no 'live' value, so this cannot be turned into a send by
    -- changing a parameter. A recipient and a consent basis are REQUIRED and are not defaulted:
    -- an intent that cannot say who it is for is not an intent.
    if not (v_payload ? 'recipient') or not (v_payload ? 'consent_basis') then
      raise exception 'fn_phase_d_effect_produce: step % declares an external effect and the payload names no %. An intent with no recipient or no consent basis must not be recorded as one. (pd_effect_intent_incomplete)',
        sr.step_id,
        case when not (v_payload ? 'recipient') then 'recipient' else 'consent_basis' end
        using errcode = '22023';
    end if;
    if coalesce(v_payload->>'suppressed','false') = 'true' then
      v_result_ref := format('external_intent:SUPPRESSED:%s', v_payload->>'recipient');
    else
      v_result_ref := format('external_intent:MOCK:%s', v_payload->>'recipient');
    end if;
    v_relation := 'public.phase_d_effect_ledger';
    v_mode     := 'mock';

  elsif e.expected_effect_type = 'MEASUREMENT_RECORD' then
    -- least(100, NULL) returns 100 and put 97.7% attainment in the founder's email on a
    -- zero-revenue day. Nothing is defaulted, and a zero denominator raises.
    if not (v_payload ? 'numerator') or not (v_payload ? 'denominator') then
      raise exception 'fn_phase_d_effect_produce: step % is a measurement step and the payload names no %. An absent input must not score as satisfied. (pd_effect_measurement_incomplete)',
        sr.step_id,
        case when not (v_payload ? 'numerator') then 'numerator' else 'denominator' end
        using errcode = '22023';
    end if;
    v_num := (v_payload->>'numerator')::numeric;
    v_den := (v_payload->>'denominator')::numeric;
    if v_den = 0 then
      raise exception 'fn_phase_d_effect_produce: step % reported a denominator of 0. A ratio over nothing is not a measurement. (pd_effect_zero_denominator)',
        sr.step_id using errcode = '22023';
    end if;
    v_result_ref := format('measurement:%s/%s', v_num, v_den);
    v_relation   := 'public.phase_d_effect_ledger';

  elsif e.expected_effect_type = 'REVIEW_VERDICT' then
    -- The verdict is the caller's. An absent one is a refusal, not an approval: a review handler
    -- that supplied its own verdict would make all 47 review steps a rubber stamp.
    if not (v_payload ? 'verdict') or nullif(btrim(v_payload->>'verdict'),'') is null then
      raise exception 'fn_phase_d_effect_produce: step % is a review step and the payload names no verdict. This routine does not have one to give. (pd_effect_verdict_absent)',
        sr.step_id using errcode = '22023';
    end if;
    if not public.fn_kernel_reviewer_independent(
             sr.accountable_role_id, nullif(btrim(v_payload->>'reviewer_role_id'),'')) then
      raise exception 'fn_phase_d_effect_produce: step % is accountable to % and names % as reviewer; those resolve to one effective identity (BR-002). (pd_rule_refused)',
        sr.step_id, sr.accountable_role_id, coalesce(v_payload->>'reviewer_role_id','(none)')
        using errcode = '23514';
    end if;
    -- H10. review_chain demands subject_type, subject_id, author_agent and stage. The caller's
    -- payload wins where it names them; otherwise each is the fact the run already holds -- what is
    -- under review, its identity, and who reviewed it -- never invented. dept_key comes from the
    -- owner_ref derivation, which resolves a real department for a COMPANY-scoped write.
    v_write := public.fn_phase_d_object_write(jsonb_build_object(
      'object_id','review_record',
      'business_key', coalesce(v_key, format('%s:%s', sr.step_id, v_step_run)),
      'owner_ref', coalesce(v_owner, sr.accountable_role_id),
      'created_by', v_actor,
      'state', coalesce(v_state, v_payload->>'verdict'),
      'payload', jsonb_build_object(
        'subject_type', e.effect_object_id,
        'subject_id',   coalesce(v_key, format('%s:%s', sr.step_id, v_step_run)),
        'author_agent', v_actor,
        'stage',        sr.step_id,
        'notes',        coalesce(v_payload->>'notes', 'phase_d review verdict'))
        || v_payload));
    v_result_ref := v_write->>'result_reference';
    v_relation   := v_write->>'canonical_relation';

  else
    -- DOMAIN_MUTATION and VERSIONED_ARTIFACT: the object's own canonical service.
    if v_key is null or v_owner is null then
      raise exception 'fn_phase_d_effect_produce: step % writes business object % and the call names no %. (pd_effect_owner_or_key_missing)',
        sr.step_id, e.effect_object_id,
        case when v_key is null then 'business_key' else 'owner_ref' end
        using errcode = '22023';
    end if;
    v_write := public.fn_phase_d_object_write(jsonb_build_object(
      'object_id', e.effect_object_id, 'business_key', v_key, 'owner_ref', v_owner,
      'created_by', v_actor, 'state', v_state, 'payload', v_payload,
      'run_id', sr.run_id, 'step_run_id', v_step_run, 'trace_id', p_input->>'trace_id'));
    v_result_ref := v_write->>'result_reference';

    -- O14. A SUPPLIER-SAFE PACKAGE ARRIVES WITH ITS FILE SET, INSIDE A TEST CONTEXT AND NOWHERE ELSE.
    -- BR-012 and GATE-013 now require every live revision of a package to be redaction-approved and
    -- metadata-clean, and a package naming no file is refused. In production that refusal is
    -- correct and stays: this estate has no path that produces a supplier-facing file set, and that
    -- absence must remain visible rather than be defaulted away. Inside a Phase D fixture context
    -- there is no such path either, so the harness supplies the one thing it can honestly supply --
    -- a revision pointing at COMMITTED bytes this estate has actually scanned and found clean.
    -- The guard is fn_phase_d_fixture_context(), which is an hmac over txid_current() minted only
    -- against an approved audited operation; it is not a GUC a caller can set.
    if e.effect_object_id = 'supplier_safe_package'
       and public.fn_phase_d_fixture_context() is not null then
      perform public.fn_phase_d_fixture_file_revision(v_key);
    end if;
    v_relation   := coalesce(v_write->>'canonical_relation', e.effect_relation);
  end if;

  insert into public.phase_d_effect_ledger
    (step_run_id, step_id, workflow_id, run_id, effect_type, effect_object_id, effect_relation,
     effect_operation, result_reference, state_before, state_after, provider_mode,
     payload_digest, idempotency_key, produced_by, trace_id)
  values (v_step_run, sr.step_id, e.workflow_id, sr.run_id, e.expected_effect_type,
          e.effect_object_id, v_relation, e.effect_operation, v_result_ref,
          nullif(p_input->>'state_before',''), v_state, v_mode,
          encode(sha256(convert_to(v_payload::text,'UTF8')),'hex'), v_idem, v_actor,
          nullif(p_input->>'trace_id','')::bigint)
  returning effect_id into v_eid;

  if v_eid is null then
    raise exception 'fn_phase_d_effect_produce: the ledger insert for step run % returned no effect_id. (pd_effect_produced_nothing)',
      v_step_run using errcode = '23502';
  end if;

  return jsonb_build_object(
    'ok', true, 'replay', false, 'effect_id', v_eid,
    'effect_type', e.expected_effect_type, 'effect_object_id', e.effect_object_id,
    'effect_relation', v_relation, 'effect_operation', e.effect_operation,
    'result_reference', v_result_ref, 'provider_mode', v_mode,
    'completion_condition', e.completion_condition,
    'object_write', v_write);
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_effect_reachability()
 RETURNS TABLE(step_id text, workflow_id text, expected_effect_type text, reachability text, blocker text, blocker_source text, writes_relation text, has_produced_an_effect boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- THE JOIN IS ON WHAT THE BRANCH WRITES, NOT ON WHAT THE ROW DECLARES. fn_phase_d_effect_produce
  -- hardcodes 'review_record' for every REVIEW_VERDICT step and writes only the ledger for
  -- EXTERNAL_EFFECT_INTENT and MEASUREMENT_RECORD, so e.effect_object_id is the wrong key for 60 of
  -- the 257 and reading it was the E5 defect.
  with resolved as (
    select e.step_id, e.workflow_id, e.expected_effect_type,
           case
             when e.expected_effect_type = 'CAPABILITY_REQUEST'
               then '(nothing — the branch raises pd_capability_unavailable)'
             when e.expected_effect_type in
                  ('KERNEL_ONLY_TRANSITION','EXTERNAL_EFFECT_INTENT','MEASUREMENT_RECORD')
               then 'public.phase_d_effect_ledger'
             else (select ob.canonical_relation
                     from public.phase_d_business_object_binding ob
                    where ob.object_id = case when e.expected_effect_type = 'REVIEW_VERDICT'
                                              then 'review_record' else e.effect_object_id end)
           end as writes_relation,
           case
             when e.expected_effect_type in
                  ('CAPABILITY_REQUEST','KERNEL_ONLY_TRANSITION','EXTERNAL_EFFECT_INTENT',
                   'MEASUREMENT_RECORD')
               then null
             else (select ob.relation_kind
                     from public.phase_d_business_object_binding ob
                    where ob.object_id = case when e.expected_effect_type = 'REVIEW_VERDICT'
                                              then 'review_record' else e.effect_object_id end)
           end as relation_kind
      from public.phase_d_step_effect e
  ),
  -- THE ATTEMPT, WHERE THERE IS ONE. Last dispatch per step, by dispatch_id. This is the only
  -- source in the function that is a record of something that happened.
  observed as (
    select distinct on (d.step_id)
           d.step_id, d.outcome, d.refusal_code, d.reason, d.unresolved_keys, d.dispatched_at
      from public.phase_d_dispatch d
     order by d.step_id, d.dispatch_id desc
  ),
  -- THE PRECONDITIONS, LABELLED AS PRECONDITIONS. Applicability is asked of fn_phase_d_rule_applies
  -- for every rule bound to the step; a rule that is bound but not applicable blocks nothing.
  pre as (
    select hb.step_id,
           (hb.capability_dependency <> 'NONE') as capability_held,
           (hb.provider_dependency   <> 'NONE') as provider_held,
           (select array_agg(rid order by rid) from unnest(hb.rule_ids) rid
             where (select a.applies from public.fn_phase_d_rule_applies(rid, hb.step_id) a)) as applicable_rules
      from public.phase_d_handler_binding hb
  )
  select r.step_id, r.workflow_id, r.expected_effect_type,
         case
           when r.expected_effect_type = 'CAPABILITY_REQUEST' then 'REFUSAL_IS_THE_DECLARED_EFFECT'
           when r.writes_relation = 'public.phase_d_effect_ledger' then 'WRITES_ONLY_THE_PHASE_D_LEDGER'
           when r.relation_kind = 'PHASE_D_OBJECT_VIEW' then 'WRITES_ONLY_THE_PHASE_D_OBJECT_STORE'
           when r.writes_relation in ('public.customers','public.inquiries','public.quotes',
                                      'public.transactions','public.notifications')
             then 'WRITES_A_ZERO_RESIDUE_TABLE'
           when r.relation_kind = 'EXISTING_TABLE' then 'WRITES_AN_EXISTING_TABLE_NOT_UNDER_THE_RULE'
           else 'UNRESOLVED'
         end,
         -- blocker
         case
           when o.step_id is not null and o.outcome = 'EXECUTED'
             then format('none — the last dispatch of this step reached EXECUTED at %s', o.dispatched_at)
           when o.step_id is not null
             then format('%s (%s): %s', o.outcome, coalesce(o.refusal_code,'(no code)'),
                         left(coalesce(o.reason,'(no reason recorded)'), 400))
           when p.capability_held or p.provider_held
             then 'PRECONDITION: the capability or provider boundary raises for any execution_context '
                  || 'other than test, and the kernel path hard-codes production. The refusal is the '
                  || 'contract, not a defect.'
           when r.expected_effect_type in ('DOMAIN_MUTATION','VERSIONED_ARTIFACT')
             then 'PRECONDITION: fn_phase_d_effect_produce requires a caller-supplied business_key '
                  || 'and owner_ref for a step that writes ' || coalesce(r.writes_relation,'a business object')
                  || '. It refuses rather than choosing them, deliberately.'
           when coalesce(cardinality(p.applicable_rules),0) > 0
             then 'PRECONDITION: ' || cardinality(p.applicable_rules)::text
                  || ' hard rule(s) apply to this step and read facts about a business subject — '
                  || array_to_string(p.applicable_rules, ', ')
           else 'PRECONDITION: none identified at contract level; no dispatch has been committed for '
                || 'this step, so nothing here is a measurement of why.'
         end,
         -- blocker_source: the whole point of this file
         case when o.step_id is not null then 'OBSERVED_DISPATCH'
              else 'CONTRACT_PRECONDITION_NOT_YET_OBSERVED' end,
         coalesce(r.writes_relation, '(unresolved — no binding for the object this branch writes)'),
         exists (select 1 from public.phase_d_effect_ledger l where l.step_id = r.step_id)
    from resolved r
    left join observed o on o.step_id = r.step_id
    left join pre p      on p.step_id = r.step_id;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_effect_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int; m int; v text;
begin
  select count(*) into m from public.phase_b_workflow_step;

  select count(*) into n from public.phase_d_step_effect;
  check_name := 'every_frozen_step_declares_an_effect';
  expected := m::text; actual := n::text; ok := (n = m); return next;

  select count(*) into n from public.phase_d_step_effect where expected_effect_type is null;
  check_name := 'steps_with_no_expected_effect_type';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_step_effect
   where expected_effect_type not in ('KERNEL_ONLY_TRANSITION','CAPABILITY_REQUEST')
     and effect_object_id is null;
  check_name := 'domain_effects_with_no_object';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  -- Built from the catalogue, not rendered by a cast whose output depends on search_path.
  select count(*) into n from public.phase_d_step_effect e
   where not exists (
     select 1 from pg_proc p join pg_namespace nn on nn.oid = p.pronamespace
      where nn.nspname = 'public'
        and nn.nspname || '.' || p.proname || '('
            || coalesce((select string_agg(format_type(t.o, null), ', ' order by t.ord)
                           from unnest(p.proargtypes) with ordinality t(o, ord)), '')
            || ')' = e.effect_service);
  check_name := 'effect_services_that_do_not_resolve';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_step_effect e
    join public.phase_d_business_object_binding ob on ob.object_id = e.effect_object_id
   where e.expected_effect_type in ('DOMAIN_MUTATION','VERSIONED_ARTIFACT')
     and ob.relation_kind = 'EXISTING_TABLE'
     and not exists (select 1 from public.phase_d_object_write_map w where w.object_id = ob.object_id);
  check_name := 'existing_table_effects_with_no_write_map';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n
    from public.phase_d_object_write_map w
    cross join lateral jsonb_object_keys(w.column_map) k
   where not exists (select 1 from information_schema.columns c
                      where c.table_schema = split_part(w.target_relation,'.',1)
                        and c.table_name   = split_part(w.target_relation,'.',2)
                        and c.column_name  = k);
  check_name := 'write_map_columns_absent_from_the_target';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_object_write_map w
    join public.phase_d_business_object_binding ob on ob.object_id = w.object_id
   where ob.governing_workflow_id = 'ALL' and ob.canonical_relation like 'public.phase_c_%';
  check_name := 'kernel_owned_objects_with_a_phase_d_writer';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_object_write_map
   where target_relation = 'public.notifications';
  check_name := 'phase_d_write_maps_into_the_outbound_notification_table';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_step_effect
   where effect_object_id in ('notification','notification_attempt')
     and expected_effect_type <> 'EXTERNAL_EFFECT_INTENT';
  check_name := 'notification_effects_not_classified_as_intent';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_effect_ledger
   where provider_mode not in ('none','mock','disabled');
  check_name := 'ledger_rows_claiming_a_live_external_effect';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from (
    select step_run_id, effect_type from public.phase_d_effect_ledger
     group by 1,2 having count(*) > 1) d;
  check_name := 'duplicate_effects_for_one_step_run';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  -- DISCLOSURE, NOT A PASS. Counts steps whose effect has actually been produced at least once,
  -- which is a different question from whether the path exists.
  --
  -- NAME, DERIVATION AND VALUE UNCHANGED SINCE IT WAS WRITTEN. scripts/checks/kernel-boards.json
  -- keys its ratchet on this exact string, and a ratchet whose subject is renamed goes on silencing
  -- whatever later takes the name. The rows that follow say what is holding it; they neither replace
  -- it nor lower it, and E7 did not touch it either.
  select count(distinct step_id) into n from public.phase_d_effect_ledger;
  check_name := 'steps_with_no_effect_ever_produced';
  expected := '0'; actual := (m - n)::text; ok := (n = m); return next;

  -- ---- THE RED, DECOMPOSED BY THE BRANCH EACH EFFECT ACTUALLY EXECUTES ------------------------
  -- E5 wrote three rows here and derived them from the DECLARED effect object. E7 replaces them
  -- with five derived from the branch, because fn_phase_d_effect_produce hardcodes 'review_record'
  -- for all 41 REVIEW_VERDICT steps and writes only the ledger for EXTERNAL_EFFECT_INTENT and
  -- MEASUREMENT_RECORD. The E5 rows are gone rather than kept beside these: two of them carried a
  -- number this file proves wrong, and a board showing both readings makes the reader choose.
  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'REFUSAL_IS_THE_DECLARED_EFFECT' and not has_produced_an_effect;
  check_name := 'no_effect_because_the_refusal_is_the_effect';
  expected := 'informational — the provider hold, and it is the founder''s to lift';
  actual := n::text || ' CAPABILITY_REQUEST step(s): the branch raises pd_capability_unavailable in '
         || 'production rather than recording. A ledger row needs execution_context=test, which is '
         || 'not a result.';
  ok := true; return next;

  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'WRITES_A_ZERO_RESIDUE_TABLE' and not has_produced_an_effect;
  check_name := 'no_effect_because_the_effect_writes_a_zero_residue_table';
  expected := 'informational — the zero-residue rule, and it is the founder''s to lift';
  actual := n::text || ' step(s) whose effect writes customers, inquiries, quotes or transactions. '
         || 'The estate holds 0 of each since the 16 Aug purge and may not be given one.';
  ok := true; return next;

  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'WRITES_AN_EXISTING_TABLE_NOT_UNDER_THE_RULE' and not has_produced_an_effect;
  check_name := 'no_effect_and_the_effect_writes_a_real_table_the_rule_does_not_name';
  expected := 'informational — the fixture rule, plus a row in a table the company uses';
  actual := n::text || ' step(s) writing review_chain, refunds, company_goals, opportunity, '
         || 'os_incidents, legal_reviews, documents, quote_comparisons, supplier_capabilities, '
         || 'leads, stripe_events, inquiry_matches, department_objective, content_drafts, '
         || 'reveal_invoices or org_tasks. Permitted by the letter of the zero-residue rule and '
         || 'still not Phase D''s own storage — 41 of them are the REVIEW_VERDICT steps, which write '
         || 'review_chain through a hardcoded object_id their own effect row does not name.';
  ok := true; return next;

  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability in ('WRITES_ONLY_THE_PHASE_D_LEDGER','WRITES_ONLY_THE_PHASE_D_OBJECT_STORE')
     and not has_produced_an_effect;
  check_name := 'no_effect_although_the_effect_leaves_phase_d_tables_only';
  expected := 'informational — NEITHER hold touches these; the fixture rule does';
  actual := n::text || ' step(s) writing only phase_d_effect_ledger or phase_d_object_record. '
         || 'They are not waiting on a business arrival. The only driver, fn_phase_d_drive_workflow, '
         || 'opens every run with source_ref zz-phase-d-… and trigger_ctx.fixture=true, so '
         || 'committing one leaves residue that fn_phase_d_fixture_residue() must report as 0.';
  ok := true; return next;

  -- A decomposition that stops covering the thing it decomposes is worse than no decomposition, and
  -- UNRESOLVED is its own failure: a branch whose written relation cannot be resolved is a step
  -- nobody can say anything about.
  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'UNRESOLVED';
  check_name := 'steps_whose_written_relation_does_not_resolve';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.fn_phase_d_effect_reachability();
  check_name := 'every_step_carries_a_reachability_class';
  expected := m::text; actual := n::text; ok := (n = m); return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select reachability t, count(*)::text c
            from public.fn_phase_d_effect_reachability() group by 1) x;
  check_name := 'reachability_class_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select expected_effect_type t, count(*)::text c
            from public.phase_d_step_effect group by 1) x;
  check_name := 'effect_type_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select implementation_depth t, count(*)::text c
            from public.phase_d_step_effect group by 1) x;
  check_name := 'implementation_depth_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select object_resolution t, count(*)::text c
            from public.phase_d_step_effect group by 1) x;
  check_name := 'object_resolution_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_file_revision_dispatchable(p_revision_ref text, p_dispatch_sha256 text DEFAULT NULL::text)
 RETURNS TABLE(dispatchable boolean, refusal_code text, reason text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.phase_d_file_revision%rowtype; s public.phase_d_metadata_scan%rowtype;
begin
  if coalesce(btrim(p_revision_ref),'') = '' then
    dispatchable := false; refusal_code := 'pd_revision_redaction_state_absent';
    reason := 'No file revision named. A file nobody identified cannot be certified safe to send.';
    return next; return;
  end if;
  select * into r from public.phase_d_file_revision where revision_ref = btrim(p_revision_ref);
  if not found then
    dispatchable := false; refusal_code := 'pd_revision_redaction_state_absent';
    reason := format('%L is not a registered supplier-facing file revision.', p_revision_ref);
    return next; return;
  end if;

  if r.superseded_by is not null or r.redaction_state = 'SUPERSEDED' then
    dispatchable := false; refusal_code := 'pd_revision_superseded';
    reason := format('%s was superseded by %s: %s', r.revision_ref,
                     coalesce(r.superseded_by,'(unnamed)'), coalesce(r.supersession_reason,''));
    return next; return;
  end if;

  if r.redaction_state in ('PENDING','REVIEW_REQUIRED') then
    dispatchable := false; refusal_code := 'pd_revision_redaction_unapproved';
    reason := format('%s is %s. A revision whose redaction has not been approved may not reach a supplier.',
                     r.revision_ref, r.redaction_state);
    return next; return;
  end if;
  if r.redaction_state = 'REJECTED' then
    dispatchable := false; refusal_code := 'pd_revision_redaction_rejected';
    reason := format('%s was rejected by %s. It may not reach a supplier and it may not be re-offered unchanged.',
                     r.revision_ref, coalesce(r.reviewer_role_id,'(unnamed)'));
    return next; return;
  end if;

  -- THE DIGEST IS THE POINT. An approval is an approval OF BYTES, so a dispatch naming different
  -- bytes is not covered by it however green the state word looks.
  if p_dispatch_sha256 is not null and lower(btrim(p_dispatch_sha256)) <> coalesce(r.safe_sha256,'') then
    dispatchable := false; refusal_code := 'pd_revision_digest_mismatch';
    reason := format('%s is approved at %s and the dispatch names %s. The approval is of bytes, not of a file name.',
                     r.revision_ref, left(coalesce(r.safe_sha256,'(none)'),12),
                     left(lower(btrim(p_dispatch_sha256)),12));
    return next; return;
  end if;

  -- THE METADATA SCAN, OVER THE SAFE DIGEST AND ONLY THE DIGEST. O11: this was keyed on
  -- (revision_ref, scanned_sha256), which made the same bytes unscanned as soon as a second
  -- revision claimed them. A scanner reads a digest and reports on a digest.
  --
  -- The WORST outcome over that digest is taken, not the most recent. Two scanners disagreeing
  -- about one file must not be settled by whichever ran last, or a clean re-scan buries a dirty one.
  select * into s from public.phase_d_metadata_scan
   where scanned_sha256 = r.safe_sha256
   order by case outcome when 'IDENTIFIERS_FOUND' then 0 when 'SCAN_FAILED' then 1
                         when 'UNSUPPORTED' then 2 else 3 end, scan_id desc
   limit 1;
  if not found then
    dispatchable := false; refusal_code := 'pd_metadata_scan_absent';
    reason := format('%s carries no hidden-metadata scan over its approved bytes %s. Fail closed: an unscanned file is not a clean file.',
                     r.revision_ref, left(coalesce(r.safe_sha256,'(none)'),12));
    return next; return;
  end if;
  if s.outcome in ('SCAN_FAILED','UNSUPPORTED') then
    dispatchable := false; refusal_code := 'pd_metadata_scan_failed_closed';
    reason := format('%s: the scanner reported %s (%s). A scan that could not read is not a scan that found nothing.',
                     r.revision_ref, s.outcome, coalesce(s.detail,'no detail'));
    return next; return;
  end if;
  if s.outcome = 'IDENTIFIERS_FOUND' then
    dispatchable := false; refusal_code := 'pd_hidden_metadata_identifier_found';
    reason := format('%s carries %s hidden-metadata identifier(s) of class(es) %s.',
                     r.revision_ref, jsonb_array_length(s.findings),
                     (select string_agg(distinct f->>'identifier_class', ', ')
                        from jsonb_array_elements(s.findings) f));
    return next; return;
  end if;

  dispatchable := true; refusal_code := null;
  reason := format('%s: redaction %s by %s at %s, method %s, safe digest %s, metadata scan CLEAN over %s classes by %s %s.',
                   r.revision_ref, r.redaction_state, coalesce(r.reviewer_role_id,'(not required)'),
                   coalesce(r.reviewed_at::text,'(n/a)'), coalesce(r.redaction_method,'(n/a)'),
                   left(r.safe_sha256,12), cardinality(s.classes_inspected), s.scanner, s.scanner_version);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_file_revision_reviewer_independent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(NEW.reviewer_role_id,'') = '' then return NEW; end if;
  if not public.fn_kernel_reviewer_independent(NEW.authored_by_role_id, NEW.reviewer_role_id) then
    raise exception 'phase_d_file_revision %: reviewer % resolves to the same employee as the author %. A self-review is not a review. (pd_creator_reviewer_collision)',
      NEW.revision_ref, NEW.reviewer_role_id, NEW.authored_by_role_id using errcode = '23514';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_catalogue_checksum()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- THE CHECKSUM IS COMPUTED, NEVER ACCEPTED. A caller-supplied checksum is a claim about a row.
  new.checksum := public.fn_phase_d_fixture_row_digest(new);
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_context()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_raw text := nullif(btrim(current_setting('app.phase_d_fixture_context', true)),'');
  v_id  bigint;
  v_tok text;
  v_exp text;
  g     public.phase_d_test_context_grant%rowtype;
begin
  if v_raw is null then return null; end if;
  begin
    v_id := nullif(split_part(v_raw, '.', 1),'')::bigint;
  exception when others then
    return null;
  end;
  v_tok := nullif(split_part(v_raw, '.', 2),'');
  if v_id is null or v_tok is null then return null; end if;

  select * into g from public.phase_d_test_context_grant where fixture_run_id = v_id;
  if not found then return null; end if;
  -- A grant is only a context inside the transaction it was minted in.
  if g.txid <> txid_current() then return null; end if;

  select encode(extensions.hmac(convert_to(format('%s:%s:%s', g.txid, g.operation_key, g.fixture_run_id),'UTF8'), s.secret, 'sha256'), 'hex')
    into v_exp from public.phase_d_fixture_secret s where s.singleton;

  if v_exp is null or v_exp <> v_tok then return null; end if;
  return v_id;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_effect_payload(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run bigint := public.fn_phase_d_fixture_context();
  sr    public.phase_c_workflow_step_run%rowtype;
  e     public.phase_d_step_effect%rowtype;
  v_rel text;
  v_out jsonb := '{}'::jsonb;
  r     record;
  fi    record;
  v_ctx_val jsonb;   -- G14: what the step context already resolved for this key
begin
  -- NO VERIFIED FIXTURE CONTEXT, NO CONTENT. In production this returns an empty object, the
  -- effect payload is exactly what it is today, and a NOT NULL column with no value still raises
  -- 23502 and is still classified pd_effect_payload_incomplete.
  if v_run is null then return '{}'::jsonb; end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = p_step_run_id;
  if not found then return '{}'::jsonb; end if;
  select * into e from public.phase_d_step_effect where step_id = sr.step_id;
  if not found then return '{}'::jsonb; end if;

  select wm.target_relation into v_rel from public.phase_d_object_write_map wm
   where wm.object_id = e.effect_object_id;

  -- THE POPULATION IS THE COLUMNS THE TARGET RELATION ACTUALLY DEMANDS, read from the catalogue of
  -- the database rather than listed by hand. A column that is NOT NULL, has no default, is not
  -- generated, and is mapped by the object's write map to a payload key -- that is exactly the set
  -- fn_phase_d_effect_produce raises 23502 on today.
  if v_rel is not null and to_regclass(v_rel) is not null then
    for r in
      with m as (
        select k.col, k.key
          from public.phase_d_object_write_map wm,
               lateral jsonb_each_text(wm.column_map) k(col, key)
         where wm.object_id = e.effect_object_id)
      select m.key as src
        from m
        join pg_attribute a on a.attrelid = to_regclass(v_rel) and a.attname = m.col
        left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
       where a.attnum > 0 and a.attidentity = '' and a.attgenerated = ''
         and m.key not in ('business_key','owner_ref','state')
         and (   (a.attnotnull and d.adbin is null)
              -- H04 (3). A mapped column the committed catalogue speaks for, at this step or in
              -- this workflow. Scoped rows only: a global fixture fills nothing here.
              or exists (select 1 from public.phase_d_fixture_catalogue c
                          where c.scope = 'EFFECT_PAYLOAD' and c.field_key = m.key
                            and (c.step_id = sr.step_id
                                 or (c.step_id is null and c.workflow_id = e.workflow_id))))
    loop
      -- G14. A KEY THAT NAMES A ROW IS ANSWERED FROM THE ROW, NOT FROM A CONSTANT.
      -- Five of the sixteen keys in this population name something: inquiry_id, transaction_id,
      -- group_id, field_id, requested_by. fn_phase_d_step_context resolves an object key from the
      -- object it names, from a declared foreign key on the run's own relation, or from the
      -- canonical reference the scenario recorded -- so it is asked first, and the committed
      -- catalogue answers only what it could not. Handing a committed constant to a key that names
      -- a row is the mistake this estate has now corrected four times in one session.
      v_ctx_val := (public.fn_phase_d_step_context(p_step_run_id))->'context'->(r.src);
      if v_ctx_val is not null and v_ctx_val <> 'null'::jsonb then
        v_out := v_out || jsonb_build_object(r.src, v_ctx_val);
        continue;
      end if;
      -- H04 (1). A KEY THAT NAMES AN OBJECT IS ANSWERED FROM THE OBJECT THE SCENARIO CREATED, whether
      -- or not this step's rules declared the key. The register is public.phase_d_context_key_object;
      -- the identity is the canonical reference the scenario recorded for that object.
      select to_jsonb(sc.canonical_ref->>'canonical_identity') into v_ctx_val
        from public.phase_d_context_key_object cko
        join public.phase_d_scenario_record sc
          on sc.object_id = cko.object_id and sc.fixture_run_id = v_run
       where cko.context_key = r.src and cko.key_role = 'IDENTIFIES'
         and coalesce(btrim(sc.canonical_ref->>'canonical_identity'),'') <> ''
       order by sc.scenario_record_id desc
       limit 1;
      if v_ctx_val is not null then
        v_out := v_out || jsonb_build_object(r.src, v_ctx_val);
        continue;
      end if;
      select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'EFFECT_PAYLOAD', r.src) fi;
      if fi.value is not null then
        -- H04 (2). A CONSTANT CANNOT BE AN IDENTITY. Where this column belongs to a UNIQUE index of
        -- the target relation, the step run id is appended so each versioned row of one run is its
        -- own row and a replay of the same step run lands on the same value.
        if jsonb_typeof(fi.value) = 'string'
           and exists (select 1
                         from pg_index i
                         join pg_attribute a2 on a2.attrelid = i.indrelid and a2.attnum = any(i.indkey)
                        where i.indrelid = to_regclass(v_rel) and i.indisunique
                          and a2.attname = (select m2.col
                                              from public.phase_d_object_write_map wm2,
                                                   lateral jsonb_each_text(wm2.column_map) m2(col, key)
                                             where wm2.object_id = e.effect_object_id and m2.key = r.src
                                             limit 1)) then
          v_out := v_out || jsonb_build_object(r.src,
                     to_jsonb((fi.value #>> '{}') || '/' || sr.step_id || '/' || p_step_run_id::text));
        else
          v_out := v_out || jsonb_build_object(r.src, fi.value);
        end if;
      end if;
    end loop;
  end if;

  -- The three effect types that demand named keys of their own, whatever the relation is.
  if e.expected_effect_type = 'EXTERNAL_EFFECT_INTENT' then
    for r in select unnest(array['recipient','consent_basis']) src loop
      select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'EFFECT_PAYLOAD', r.src) fi;
      if fi.value is not null then v_out := v_out || jsonb_build_object(r.src, fi.value); end if;
    end loop;
    v_out := v_out || jsonb_build_object('suppressed', true);
  elsif e.expected_effect_type = 'MEASUREMENT_RECORD' then
    for r in select unnest(array['numerator','denominator']) src loop
      select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'CONTEXT_KEY', r.src) fi;
      if fi.value is not null then v_out := v_out || jsonb_build_object(r.src, fi.value); end if;
    end loop;
  elsif e.expected_effect_type = 'REVIEW_VERDICT' then
    select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'EFFECT_PAYLOAD', 'verdict') fi;
    if fi.value is not null then v_out := v_out || jsonb_build_object('verdict', fi.value); end if;
  end if;

  return v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_file_revision(p_package_ref text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- scripts/staging/fixtures/metadata/supplier_drawing_clean.pdf, 736 bytes. Its CLEAN verdict in
  -- public.phase_d_metadata_scan was produced by scripts/phase_d/run_metadata_scan_probe.mjs
  -- reading these exact bytes; nothing here fabricates a scan.
  v_clean constant text := 'd1311fb75b6d5c012a5dbf4513f098896b371dd65802526e9689951f6b2025a2';
  v_dirty constant text := '617d50b1a1654b3b612d1981a55e84d8746f5f7821781a99b6b10da7948844a7';
  v_ref text;
begin
  if coalesce(btrim(p_package_ref),'') = '' then return null; end if;
  v_ref := 'fxrev:' || btrim(p_package_ref);
  insert into public.phase_d_file_revision
    (revision_ref, package_ref, file_name, media_type, source_sha256, safe_sha256,
     redaction_state, redaction_method, elements_removed, reviewer_role_id, reviewer_verdict,
     reviewed_at, authored_by_role_id)
  values (v_ref, btrim(p_package_ref), 'supplier_drawing_clean.pdf', 'application/pdf',
          v_dirty, v_clean, 'APPROVED', 'title_block_mask_and_info_dictionary_cleared',
          '["pdf:/Info//Author","pdf:/Info//Subject","pdf:/Info//Keywords","pdf:/Info//Creator","title_block"]'::jsonb,
          'ceo', 'approved', now(),
          'marketplace_content_privacy_reviewer')
  on conflict (revision_ref) do nothing;
  return v_ref;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_input(p_step_run_id bigint, p_scope text, p_key text)
 RETURNS TABLE(value jsonb, provenance text, fixture_id text, fixture_version integer, checksum text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run  bigint := public.fn_phase_d_fixture_context();
  sr     public.phase_c_workflow_step_run%rowtype;
  v_wf   text;
  r      record;
  v_ckey text;   -- F47: the identity a context key that names an object resolves to
begin
  -- NO VERIFIED FIXTURE CONTEXT, NO FIXTURE. This single line is the production boundary.
  if v_run is null then return; end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = p_step_run_id;
  if not found then return; end if;
  select b.workflow_id into v_wf from public.phase_d_handler_binding b where b.step_id = sr.step_id;

  if p_scope = 'CONTEXT_KEY' then
    -- (1) A REFERENCE RESOLVES TO WHAT THIS RUN ACTUALLY CREATED, and to the value the stage
    --     CONTRIBUTED rather than to its row id -- see F09 on inquiry_route_set.
    -- F40. A STAGE THAT CONTRIBUTED NOTHING STILL ANSWERED, WITH ITS OWN ROW ID.
    --
    -- coalesce(contributed_value, business_key) means a stage whose contributed_value was never set
    -- answers the key with the primary key of the row it created. Measured: the artifact_revision
    -- stage declares contributes_ref = 'artifact_sha256', sets no contributed_value, and so
    -- resolved artifact_sha256 to 44208 -- a row id. BR-036 then refused with "artifact_sha256
    -- 44208 is not a SHA-256 digest (64 hexadecimal characters), so it was not computed over any
    -- artifact", which was true, and which no fixture could correct: a non-null wrong value blocks
    -- the catalogue fallback below, because that fallback exists only for a key NOTHING answered.
    --
    -- The fallback to business_key is kept where it is right -- a RESULT_KEY stage contributes the
    -- identity of what it created, and that IS its business key -- and refused where it is not.
    -- A stage that declares it contributes a value and supplies none now contributes NOTHING, so
    -- the object-payload branch below and then the committed catalogue get their turn, and a key
    -- with no answer anywhere stays unresolved and its rule refuses.
    -- ---- F47. A KEY THAT NAMES AN OBJECT IS ANSWERED FROM THAT OBJECT'S REFERENCE --------------
    --
    -- Twelve of the 33 context keys the 54 business rules declare are references to a business
    -- object rather than values in their own right. Which object each names is recorded in
    -- public.phase_d_context_key_object, and the identity then comes from that object's canonical
    -- reference -- so the answer is the same one fn_phase_d_ref_resolve would give and the same one
    -- the rule looks up, whichever store the object lives in.
    --
    -- THIS RUNS BEFORE THE STAGE'S OWN contributes_ref, and that is the point. Before F43 the
    -- answer depended on which stage happened to declare it and what that stage set; now it depends
    -- on the OBJECT, which is what the key is about. A stage no longer has to be classified
    -- correctly for a rule to be given the right subject.
    select sc.canonical_ref->>'canonical_identity' into v_ckey
      from public.phase_d_context_key_object m
      join public.phase_d_scenario_record sc
        on sc.object_id = m.object_id
       and sc.fixture_run_id = v_run
     where m.context_key = p_key and m.key_role = 'IDENTIFIES'
       and sc.canonical_ref is not null
     order by sc.scenario_record_id
     limit 1;
    if v_ckey is not null then
      value := to_jsonb(v_ckey);
      provenance := format('the canonical reference of the %s this fixture run created, resolved '
                        || 'through public.phase_d_context_key_object',
                           (select object_id from public.phase_d_context_key_object
                             where context_key = p_key and key_role = 'IDENTIFIES'));
      select sc.fixture_id, sc.fixture_version, sc.source_checksum
        into fixture_id, fixture_version, checksum
        from public.phase_d_context_key_object m
        join public.phase_d_scenario_record sc
          on sc.object_id = m.object_id and sc.fixture_run_id = v_run
       where m.context_key = p_key and m.key_role = 'IDENTIFIES'
       order by sc.scenario_record_id limit 1;
      return next; return;
    end if;

    -- F45. THE CANONICAL REFERENCE, OR NOTHING. There is no coalesce chain here on purpose: a
    -- fallback among the scenario row id, the object-record key, the business key and the relation
    -- primary key is precisely the guessing the founder's ruling of 23 Aug 2026 removes. An identity
    -- stage answers from the reference the write service returned; a PAYLOAD_VALUE or STATE stage
    -- answers with the value it settled; anything else contributes nothing and the key falls through
    -- to the object payload, then to the committed catalogue, then to an explicit refusal.
    select case when sc.contributes_kind in ('PAYLOAD_VALUE','STATE') then sc.contributed_value
                when sc.canonical_ref is not null
                  then sc.canonical_ref->>'canonical_identity'
                else null end v,
           sc.object_id o,
           sc.canonical_relation cr, sc.fixture_id fi, sc.fixture_version fv, sc.source_checksum ck
      into r
      from public.phase_d_scenario_record sc
     where sc.fixture_run_id = v_run and sc.contributes_ref = p_key
     order by sc.scenario_record_id limit 1;
    if found and r.v is not null then
      value := to_jsonb(r.v);
      provenance := format('phase_d_scenario_record: the %s created by fixture run %s through %s',
                           r.o, v_run, coalesce(r.cr,'its canonical service'));
      fixture_id := r.fi; fixture_version := r.fv; checksum := r.ck;
      return next; return;
    end if;

    -- (1b) A FACT THE SCENARIO RECORDED ON ONE OF ITS OWN ROWS. terms_version and terms_hash are
    --      the example: they are not keys and not authorable content -- they are read off the
    --      published document and written onto the acceptance record, so the honest place to find
    --      them is that record's own payload.
    select o.payload->p_key v, sc.object_id ob, sc.canonical_relation cr, sc.fixture_id fi,
           sc.fixture_version fv, sc.source_checksum ck
      into r
      from public.phase_d_scenario_record sc
      join public.phase_d_object_record o
        on o.object_id = sc.object_id and o.business_key = sc.business_key
     where sc.fixture_run_id = v_run and o.payload ? p_key
       and jsonb_typeof(o.payload->p_key) <> 'null'
     order by sc.scenario_record_id desc limit 1;
    if found then
      value := r.v;
      provenance := format('phase_d_object_record.payload of the %s created by fixture run %s',
                           r.ob, v_run);
      fixture_id := r.fi; fixture_version := r.fv; checksum := r.ck;
      return next; return;
    end if;
  end if;

  -- (2) CONTENT COMES FROM THE COMMITTED CATALOGUE, most specific row first.
  for r in
    select c.* from public.phase_d_fixture_catalogue c
     where c.scope = p_scope and c.field_key = p_key
       and (c.step_id is null or c.step_id = sr.step_id)
       and (c.workflow_id is null or c.workflow_id = v_wf)
     order by (c.step_id is not null) desc, (c.workflow_id is not null) desc, c.fixture_id
     limit 1
  loop
    value := r.value;
    provenance := format('phase_d_fixture_catalogue %s v%s (%s) — %s',
                         r.fixture_id, r.fixture_version, r.checksum, r.expected_result);
    fixture_id := r.fixture_id; fixture_version := r.fixture_version; checksum := r.checksum;
    return next; return;
  end loop;
  return;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_inquiry_payload(p_label text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- The generic six, and the three keys public.category_specs marks required for `general`
  -- (describe, property, scope) — read from the table, not guessed. The verdict is still
  -- fn_rfq_score's; this supplies facts, not a readiness flag.
  select jsonb_build_object(
    'summary',   format('ZZ DEMO — %s inquiry', p_label),
    'spec',      jsonb_build_object(
                   'describe','ZZ DEMO fixture requirement described in full: supply and installation of a general works package to the stated scope and quantities.',
                   'property','Commercial fit-out, Dubai',
                   'scope','ZZ DEMO fixture scope of works with sufficient descriptive detail for the readiness scorer to register scope_detail',
                   'quantity','1 lot'),
    'category',  'general',
    'emirate',   'Dubai',
    'scope_type','supply_and_install',
    'budget',    'AED 100,000 - 200,000',
    'trades',    '["general"]'::jsonb);
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_output(p_step_id text, p_field_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
  select c.value
    from public.phase_d_fixture_catalogue c
   where c.scope = 'HANDLER_OUTPUT'
     and c.field_key = p_field_key
     and (c.step_id = p_step_id or c.step_id is null)
   order by (c.step_id is null), c.fixture_version desc, c.fixture_id
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_residue()
 RETURNS TABLE(relation text, surviving_rows bigint)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_n bigint; v_pred text;
begin
  for r in
    select distinct wm.target_relation as rel from public.phase_d_object_write_map wm
     union select 'public.phase_d_object_record'
  loop
    v_pred := (select string_agg(format(
                 '(coalesce(%I::text,'''') like ''ZZ DEMO — %%'' or coalesce(%I::text,'''') like ''%%@example.invalid'' or coalesce(%I::text,'''') like ''zz-phase-d-%%'')',
                 a.attname, a.attname, a.attname), ' or ')
               from pg_attribute a
              where a.attrelid = r.rel::regclass and a.attnum > 0 and not a.attisdropped
                and format_type(a.atttypid, a.atttypmod) in ('text','character varying','jsonb'));
    if v_pred is null then continue; end if;
    execute format('select count(*) from %s where %s', r.rel, v_pred) into v_n;
    if v_n > 0 then
      relation := r.rel; surviving_rows := v_n; return next;
    end if;
  end loop;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_fixture_scenario(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  st       public.phase_d_fixture_stage%rowtype;
  v_label  text := nullif(btrim(coalesce(p_input->>'label','')),'');
  v_ctx    text := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),''));
  v_upto   int  := coalesce(nullif(p_input->>'up_to_stage','')::int, 9999);
  v_actor  text := coalesce(nullif(btrim(p_input->>'created_by'),''), 'phase_d_fixture_factory');
  v_refs   jsonb := '{}'::jsonb;
  v_man    jsonb := '[]'::jsonb;
  v_w      jsonb;
  v_pay    jsonb;
  v_key    text;
  v_owner  text;
  v_state  text;
  v_name   text;
  v_missing text[];
  v_ref_n  bigint;
  v_err    text;
  v_ok     int := 0; v_blocked int := 0; v_owned int := 0;
  v_for_wf text := nullif(btrim(coalesce(p_input->>'for_workflow','')),'');
  v_notif_before bigint; v_notif_after bigint;
  v_notif_id_before bigint;              -- G11: the high-water mark, so new rows are identifiable
  v_notif_id_start  bigint;              -- G13: the same, for the whole scenario rather than one stage
  v_inbox_before bigint; v_inbox_after bigint;
  v_notif_start  bigint; v_inbox_start  bigint;
  v_net_start    bigint;
  v_fixture_run  bigint;                     -- F01: the audited fixture run this build belongs to
  v_terms_ver    text;   v_terms_hash text;  -- F08: a REAL published document, not an invented one
  v_sup_ver      text;   v_sup_hash   text;
  v_art_sha      text;                       -- F08: the digest BR-036 resolves
  v_cat          jsonb;                      -- F08: a committed catalogue value
  v_scenario_id  bigint;
  v_state_col    text;    -- F15: the column the write map points at the state
  v_actual       text;    -- F15: what the product left in it
begin
  if v_label is null then
    raise exception 'fn_phase_d_fixture_scenario: label is required; it is what makes the ids deterministic and the residue findable (pd_fixture_label_missing)'
      using errcode = '22023';
  end if;
  if v_ctx <> 'test' then
    raise exception 'fn_phase_d_fixture_scenario: execution_context is %; this factory runs only in test (pd_fixture_not_test_context)',
      coalesce(nullif(v_ctx,''),'(unset)') using errcode = '23514';
  end if;
  -- F01. THIS READ A GUC ANY CALLER COULD SET. `set local app.phase_d_test_context = 'on'` was
  -- accepted from service_role, so the "protected test context" was a string the caller supplied
  -- about itself -- the same shape as a guard authenticating an email. The context is now an hmac
  -- over the current txid, keyed by a secret no role can SELECT, minted only by
  -- fn_phase_d_test_context_open against an approved audited operation.
  v_fixture_run := public.fn_phase_d_fixture_context();
  if v_fixture_run is null then
    raise exception 'fn_phase_d_fixture_scenario: no verified Phase D fixture context in this transaction (pd_fixture_no_test_context)'
      using errcode = '23514',
            hint = 'select public.fn_phase_d_test_context_open(''{"operation_key":"pdop_scenario_factory","label":"..."}''); and abort the transaction when finished.';
  end if;
  if current_user in ('anon','authenticated') then
    raise exception 'fn_phase_d_fixture_scenario: % may not build fixtures (pd_fixture_untrusted_caller)',
      current_user using errcode = '42501';
  end if;

  -- F08. BR-025 REQUIRES THE EXACT DISPLAYED VERSION AND ITS DIGEST, and this factory was writing
  -- 'zz-terms-v1' with sha256('zz-terms-v1') -- a hash OF THE VERSION STRING, not of any terms.
  -- The rule resolves the pair against public.legal_documents where the displayed body hashes to
  -- exactly that digest, so the acceptance the factory created could never be an acceptance of
  -- anything, and BR-025 refused every terms step for the right reason. The pair is now READ from
  -- the published document, so the fixture accepts terms that actually exist.
  select d.version, encode(sha256(convert_to(coalesce(d.body_html,''),'UTF8')),'hex')
    into v_terms_ver, v_terms_hash
    from public.legal_documents d where d.slug = 'customer-terms' order by d.version desc limit 1;
  select d.version, encode(sha256(convert_to(coalesce(d.body_html,''),'UTF8')),'hex')
    into v_sup_ver, v_sup_hash
    from public.legal_documents d where d.slug = 'supplier-agreement' order by d.version desc limit 1;
  -- The artifact digest is the digest of the committed artifact fixture's own text, so BR-036
  -- resolves it against a record this scenario writes rather than against a string.
  select encode(sha256(convert_to(c.value #>> '{}','UTF8')),'hex') into v_art_sha
    from public.phase_d_fixture_catalogue c
   where c.scope = 'CONTEXT_KEY' and c.field_key = 'artifact_ref';

  select coalesce(max(id),0) into v_net_start from net.http_request_queue;
  select count(*) into v_notif_start from public.notifications;
  select coalesce(max(id),0) into v_notif_id_start from public.notifications;  -- G13
  select count(*) into v_inbox_start from public.kernel_trigger_inbox;

  for st in select * from public.phase_d_fixture_stage where stage_no <= v_upto order by stage_no
  loop
    -- A SCENARIO MUST NOT PRE-CREATE THE OBJECT THE WORKFLOW UNDER TEST PRODUCES. W09 writes
    -- supplier_capability, W14 writes quotation, W16 writes payment_transaction; building those
    -- first made the workflow collide with its own output on a unique constraint, and a harness
    -- that seeds the row the step is supposed to create is answering its own question. The set is
    -- read from phase_d_step_effect for that workflow, never listed by hand.
    -- D22. THE EXCLUSION SKIPS LEAVES ONLY, SO A CASCADE IS IMPOSSIBLE BY CONSTRUCTION.
    --
    -- Measured with the old rule: for_workflow on W09 skipped 3 stages and the requires_stages
    -- cascade then blocked 13 MORE, because supplier_account is a parent of half the lineage. The
    -- D9 closure recorded the same shape as closure falling 14 -> 3, which is why the exclusion was
    -- left available and unused. Removing a parent to avoid a collision costs more than it saves.
    --
    -- A stage no other stage requires cannot cascade. supplier_assignment and provider_event are
    -- both leaves, and they are exactly the two collisions left: W12 writes supplier_assignment and
    -- GATE-015 correctly refused the fixture's as a duplicate dispatch. The skip is still recorded
    -- in the manifest as SKIPPED_PRODUCED_BY_THE_WORKFLOW_UNDER_TEST, never silently.
    if v_for_wf is not null
       and not exists (select 1 from public.phase_d_fixture_stage t
                        where st.stage_key = any(t.requires_stages))
       and exists (
         select 1 from public.phase_d_step_effect x
          where x.workflow_id = v_for_wf and x.effect_object_id = st.object_id) then
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status', 'SKIPPED_PRODUCED_BY_THE_WORKFLOW_UNDER_TEST', 'detail', v_for_wf));
      v_owned := v_owned + 1;
      continue;
    end if;

    select array_agg(r) into v_missing
      from unnest(st.requires_stages) r
     where not exists (select 1 from jsonb_array_elements(v_man) m
                        where m->>'stage_key' = r and m->>'status' = 'CREATED');
    if v_missing is not null then
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status', 'SKIPPED_PARENT_NOT_CREATED', 'detail', array_to_string(v_missing, ', ')));
      v_blocked := v_blocked + 1;
      continue;
    end if;

    if st.reference_relation is not null then
      execute format('select count(*) from %s', st.reference_relation) into v_ref_n;
      if v_ref_n = 0 then
        v_man := v_man || jsonb_build_array(jsonb_build_object(
          'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
          'status', 'BLOCKED_NO_REFERENCE_DATA', 'detail',
          format('%s holds 0 rows and this factory does not create business reference data',
                 st.reference_relation)));
        v_blocked := v_blocked + 1;
        continue;
      end if;
    end if;

    v_name  := format('ZZ DEMO — %s %s', v_label, st.stage_key);
    v_key   := md5(format('%s:%s', v_label, st.stage_key))::uuid::text;
    v_owner := v_key;
    -- F10. THE STATE IS THE STAGE'S OWN DECLARATION. This line used to read v_state := 'open' and
    -- every branch below then assigned a literal over it, so public.phase_d_fixture_stage.working_state
    -- -- the column whose sibling working_state_evidence explains, per stage, WHY that state -- was
    -- read by nothing at all. Five stages carried a state their object's contract does not declare
    -- and refused on every build since they were written; correcting the table changed nothing,
    -- because the table was not the source. It is now.
    v_state := coalesce(nullif(btrim(st.working_state),''), 'open');
    v_pay   := jsonb_build_object('fixture_label', v_label, 'stage', st.stage_key,
                                  'phase_d_test_context', true);

    -- D22. company_objective HAS NEVER ONCE CREATED ITS OBJECT.
    --
    -- D16 added this stage to fix W01-S03 dying on department_objective_goal_key_fkey, and it has
    -- refused on every build since with
    --     null value in column "goal" of relation "company_goals" violates not-null
    -- because the chain below has no branch for it, so the payload carried only the three
    -- bookkeeping keys every stage gets. The write map declares goal and metric; both are NOT NULL
    -- with no default.
    --
    -- Nothing failed loudly. stages_created read 23 of 25 and the missing one was recorded as
    -- REFUSED inside the manifest, where no caller was looking. A stage added to fix a foreign key
    -- and never observed creating anything is the "finished capability with no entry point" shape,
    -- and the only reason it surfaced is that a control started counting stages_not_created.
    if st.stage_key = 'company_objective' then
      v_pay := v_pay || jsonb_build_object(
        'goal', 1, 'metric', format('zz_demo_%s', v_label), 'active', true, 'direction', 'at_least');

    elsif st.stage_key = 'customer_account' then
      -- NO EMAIL AND NO PHONE. trg_inquiry_received_a queues a customer email for any inquiry whose
      -- customer has an address, and trg_new_quote_sms / trg_reveal_receipt_a do the same on a
      -- phone. The fixture identity carries neither, and the per-stage assertion below is what
      -- proves it rather than this comment.
      v_pay := v_pay || jsonb_build_object('full_name', v_name, 'locale', 'en');

    elsif st.stage_key = 'customer_terms_acceptance' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object(
        'terms_version', v_terms_ver,
        'terms_hash',    v_terms_hash,
        'accepted_by',   v_refs->>'customer_id');

    elsif st.stage_key = 'inquiry' then
      -- The FACTS fn_rfq_score reads, never a readiness flag. rfq_ready is derived by
      -- trg_rfq_complete and the verdict stays the product's own.
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || public.fn_phase_d_fixture_inquiry_payload(v_label);

    elsif st.stage_key = 'inquiry_answer' then
      v_owner := v_refs->>'inquiry_id';
      -- G11. THE GROUP IS A CHILD OF THIS SCENARIO'S OWN INQUIRY, so this stage creates it.
      -- public.inquiry_workstream_group holds 0 rows on production and this stage reported
      -- BLOCKED_NO_REFERENCE_DATA on every build since D9c. A group carries an inquiry_id foreign
      -- key and a defaulted rfq_mode and nothing else -- it is structure belonging to one inquiry,
      -- not a supplier or a field definition the estate shares. It is created for the inquiry this
      -- scenario created and rolled back with it.
      insert into public.inquiry_workstream_group (inquiry_id)
      values ((v_refs->>'inquiry_id')::uuid)
      on conflict do nothing;
      v_pay := v_pay || jsonb_build_object(
        'answer_scope','inquiry_shared', 'source_kind','customer', 'precedence','customer_confirmed',
        'value', to_jsonb('PHASE_D_FIXTURE_DO_NOT_PUBLISH — fixture answer'::text),
        'field_id', (select fd.field_id from public.field_definition fd order by fd.field_id limit 1),
        'group_id', (select g.id from public.inquiry_workstream_group g
                      where g.inquiry_id = (v_refs->>'inquiry_id')::uuid
                      order by g.id desc limit 1));

    elsif st.stage_key = 'notification' then
      -- G11. The recipient is the committed catalogue's reserved .invalid address and the channel
      -- is none. status is NOT set here: fn_phase_d_object_write's outbound-door loop overwrites it
      -- with the declared suppression in verified fixture context and does not let a caller opt out,
      -- which is exactly the D19 property -- a generated payload must not be able to re-arm a door.
      v_owner := 'phase_d_fixture';
      v_pay := v_pay || jsonb_build_object(
        'type', 'phase_d_fixture',
        'channel', 'none',
        'to_email', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'recipient'),
        'subject', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — Phase D fixture notification record',
        'body', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture notification. It is written at the suppression the outbound door declares, no sender selects it, and it is created inside a transaction that is aborted.');

    elsif st.stage_key = 'inquiry_version' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id', 'version', 1);

    elsif st.stage_key = 'inquiry_route_set' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'route_state','confirmed', 'routes', '["general"]'::jsonb,
                                           'evidence','ZZ DEMO — fixture route evidence');

    elsif st.stage_key = 'inquiry_document' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object('kind','boq', 'mime','application/pdf',
                                           'bucket','zz-phase-d-fixtures',
                                           'path', format('zz/%s/%s.pdf', v_label, st.stage_key),
                                           'file_name', format('zz-%s.pdf', v_label));

    elsif st.stage_key = 'document_extraction' then
      v_owner := v_refs->>'document_id';
      v_pay := v_pay || jsonb_build_object('document_id', v_refs->>'document_id',
                                           'method','deterministic', 'paid_model_used', false);

    elsif st.stage_key = 'supplier_safe_package' then
      v_owner := v_refs->>'inquiry_id';
      -- O11. THE PACKAGE NAMES A FILE, BECAUSE AN EMPTY FILE SET IS NOT AN APPROVED ONE.
      -- Before this line the stage built an inquiry, an approver and a prose 'contents' string and
      -- no files at all. Once BR-012 and GATE-013 gained the file-set leg PD-PRIV-002 needs, that
      -- made every W08, W12 and W13 drive refuse -- 41 of the 1,799 step-contract cases, all
      -- 'positive', all pd_rule_refused or pd_gate_refused. The fixture was incomplete under the
      -- new contract, and the fix is to complete it rather than to soften the rule back to the one
      -- that passed a package with an unredacted drawing.
      --
      -- The revision it registers points at the COMMITTED clean fixture bytes, whose CLEAN metadata
      -- verdict is a real recorded scan of those bytes. A fixture that fabricated its own scan
      -- verdict would be answering the question the scan exists to ask.
      perform public.fn_phase_d_fixture_file_revision(v_key);
      v_pay := v_pay || jsonb_build_object(
        'inquiry_id', v_refs->>'inquiry_id',
        'safe_package_ref', v_key,
        'safe_package_approved_by', 'ceo',
        'file_revisions', jsonb_build_array('fxrev:' || v_key),
        'contents','ZZ DEMO — scope and quantities only; no customer identity');

    elsif st.stage_key = 'supplier_account' then
      v_pay := v_pay || jsonb_build_object('company_name', v_name, 'verified', true);

    elsif st.stage_key = 'supplier_terms_acceptance' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('terms_version', v_sup_ver,
        'terms_hash',  v_sup_hash,
        'supplier_id', v_refs->>'supplier_id');

    elsif st.stage_key = 'supplier_capability' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('trades', '["general"]'::jsonb);

    elsif st.stage_key = 'supplier_verification_case' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('supplier_id', v_refs->>'supplier_id',
                                           'evidence','ZZ DEMO — fixture verification evidence',
                                           'verified_by','customer_support');

    elsif st.stage_key = 'supplier_assignment' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'similarity', 0.9,
                                           'match_reason','ZZ DEMO — fixture assignment');

    elsif st.stage_key = 'quotation' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id', 'quote_amount', 1000);

    elsif st.stage_key = 'quotation_revision' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('quote_id', v_refs->>'quote_id',
                                           'quote_revision_ref', v_key, 'platform_edited', false);

    elsif st.stage_key = 'quotation_comparison' then
      v_owner := v_refs->>'customer_id';
      -- O13. THE COMPARISON STATES ITS PUBLICATION. quote_comparisons.publication_state defaults to
      -- DRAFT on purpose -- a row written by a path that does not know about publication must be
      -- invisible to a customer rather than visible -- and this factory was such a path, so BR-019
      -- and GATE-018 refused every W14 and W15 drive on a comparison nobody had published. The
      -- workflows those steps model are reading a comparison that IS published, so the fixture says
      -- so. published_at is stamped by a20_quote_comparison_publication_stamp rather than supplied,
      -- because a caller should not be trusted to date a state change it is making right now.
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'analysis', jsonb_build_object('note','ZZ DEMO — fixture comparison'),
                                           'quote_count', 1,
                                           'publication_state', 'PUBLISHED',
                                           'signature', encode(sha256(convert_to(v_key,'UTF8')),'hex'));

    elsif st.stage_key = 'customer_selection' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('comparison_id', v_refs->>'comparison_id',
                                           'selected_quote_id', v_refs->>'quote_id');

    elsif st.stage_key = 'payment_transaction' then
      -- THE REVEAL TIME IS SET HERE, WHERE THE ROW IS CREATED. Stage 190 inserts the transaction and
      -- stage 220 upserts the same id, so the refund window is stamped from THIS statement:
      -- trg_reveal_window fills refund_deadline only while it is null, and a later correction to
      -- revealed_at does not move a deadline that already exists. Setting it at stage 220 alone
      -- therefore changed nothing, measured -- the deadline stayed at now() + 3 working days and
      -- stage 230 stayed refused.
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'quote_id', v_refs->>'quote_id',
                                           'quote_amount', 1000, 'reveal_fee', 100,
                                           'revealed_at', now() - interval '30 days',
                                           'payment_ref', format('zz-pay-%s', v_label));

    elsif st.stage_key = 'provider_event' then
      v_owner := v_refs->>'transaction_id';
      v_key := format('evt_zz_%s', v_label);
      v_pay := v_pay || jsonb_build_object('event_type','checkout.session.completed');

    elsif st.stage_key = 'reconciliation_case' then
      v_owner := v_refs->>'transaction_id';
      v_pay := v_pay || jsonb_build_object('transaction_id', v_refs->>'transaction_id',
                                           'monetary_state','reconciled');

    elsif st.stage_key = 'reveal_transaction' then
      v_key := v_refs->>'transaction_id';
      v_owner := v_refs->>'customer_id';
      -- REVEALED THIRTY DAYS AGO, NOT THIS MINUTE. 26 Aug 2026: the founder's rule that a refund
      -- may only be claimed after the reveal window -- "only the option of refund is clickable after
      -- the period of 3 working days" -- is now enforced on public.refunds itself, and this chain
      -- paid and demanded its money back in the same transaction. Measured: stage 230
      -- refund_dispute_case REFUSED, "the refund window on transaction ... opens at 2026-08-31 and
      -- it is now 2026-08-26 (refund_window_not_yet_open)". A refund case follows a reveal that has
      -- already matured, so the fixture now describes one; the window it must clear is read from the
      -- same decision_policy the product reads, never assumed to be three days here.
      v_pay := v_pay || jsonb_build_object('reveal_fee', 100,
                                           'payment_ref', format('zz-pay-%s', v_label),
                                           'revealed_at', now() - interval '30 days',
                                           'supplier_id', (v_refs->>'supplier_id')::bigint);

    elsif st.stage_key = 'refund_dispute_case' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('transaction_id', v_refs->>'transaction_id',
                                           'amount_fils', 10000, 'reason_code','other',
                                           'reason_note','ZZ DEMO — fixture refund case; no refund is executed',
                                           'requested_by', v_refs->>'customer_id');

    elsif st.stage_key = 'artifact_revision' then
      -- F08. BR-036 resolves artifact_sha256 against an artifact_review row or a business object
      -- record CARRYING that digest. public.artifact_review holds 0 rows, so the record is the
      -- only honest route: this stage writes one whose payload carries the digest of the committed
      -- artifact fixture's own text. The digest is computed, never typed.
      -- F48. v_art_sha WAS DECLARED AND NEVER ASSIGNED, SO THIS PAYLOAD CARRIED A NULL.
      --
      -- F08 added the variable with the comment "the digest BR-036 resolves" and the stage below
      -- writes it into the artifact record's payload. Nothing ever assigned it. Measured: BR-036
      -- refuses W08, W20, W22 and W24 with "review names artifact <id> at digest 5be99093ba73,
      -- which resolves to 0 artifact_review row(s) and 0 business object record(s) carrying exactly
      -- that digest" -- and the reason no record carries it is that this line wrote null.
      --
      -- The digest is the committed one F39 computed over the committed artifact body, read here
      -- rather than recomputed, so the value in the record is the same value the context resolver
      -- hands the rule and anyone can recompute both from the catalogue.
      v_art_sha := public.fn_phase_d_stage_content(st.object_id, 'CONTEXT_KEY', 'artifact_sha256');
      if v_art_sha is null then
        raise exception 'fn_phase_d_fixture_scenario: no committed artifact_sha256 fixture, so the artifact record would carry no digest and BR-036 could never pass or fail for a real reason (pd_fixture_artifact_digest_missing)'
          using errcode = '23502';
      end if;

      v_pay := v_pay || jsonb_build_object(
        'artifact_ref', public.fn_phase_d_stage_content(st.object_id, 'CONTEXT_KEY', 'artifact_ref'),
        'artifact_sha256', v_art_sha,
        'revision', 1);

    elsif st.stage_key = 'system_incident' then
      v_pay := v_pay || jsonb_build_object(
        'title',    public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'severity', 'low');

    elsif st.stage_key = 'marketing_content' then
      v_pay := v_pay || jsonb_build_object(
        'title', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'body',  public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'body'),
        'channel','none', 'published', false);

    elsif st.stage_key = 'knowledge_capability_request' then
      v_pay := v_pay || jsonb_build_object(
        'requested_capability','REASONING',
        'note', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a knowledge/capability request record; no provider is called by Phase D');

    elsif st.stage_key = 'workforce_performance_case' then
      v_pay := v_pay || jsonb_build_object(
        'subject_role','phase_d_fixture_role',
        'note', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a workforce performance case about no real person and no real agent');

    elsif st.stage_key = 'notification_intent' then
      v_pay := v_pay || jsonb_build_object(
        'recipient',     public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'recipient'),
        'consent_basis', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'consent_basis'),
        'provider_mode','mock', 'suppressed', true);

    elsif st.stage_key = 'department_mandate' then
      v_pay := v_pay || jsonb_build_object(
        'objective', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'objective'),
        'goal_key',  v_refs->>'goal_key',
        'dept_key',  (select dept_key from public.org_departments where active order by dept_key limit 1));
      v_owner := (select dept_key from public.org_departments where active order by dept_key limit 1);

    elsif st.stage_key = 'review_record' then
      v_pay := v_pay || jsonb_build_object('verdict','approved',
                                           'subject_type','phase_d_fixture', 'subject_id', v_label,
                                           'author_agent','customer_support',
                                           'reviewer_role_id','customer_support',
                                           'stage', st.stage_key, 'notes','ZZ DEMO — fixture review');

    -- G10. THE FOUR EXISTING RELATIONS WHOSE COLUMNS A HANDLER MUST NOT INVENT.
    elsif st.stage_key = 'initiative' then
      -- public.org_tasks.dept_key is a foreign key into public.org_departments and title is NOT
      -- NULL. The department is read from the estate and the title from the committed catalogue.
      v_owner := (select dept_key from public.org_departments where active order by dept_key limit 1);
      v_pay := v_pay || jsonb_build_object(
        'title',  public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'detail', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture initiative. It assigns no real work to any department and is created inside a transaction that is aborted.',
        'dept_key', (select dept_key from public.org_departments where active order by dept_key limit 1));

    elsif st.stage_key = 'legal_risk_review' then
      v_pay := v_pay || jsonb_build_object(
        'title',      public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'summary',    'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture legal risk review. No document was reviewed, no legal opinion is expressed, and it is created inside a transaction that is aborted.',
        'doc_kind',   'phase_d_fixture',
        'risk_level', 'low');

    elsif st.stage_key = 'partnership_opportunity' then
      v_pay := v_pay || jsonb_build_object(
        'kind',   public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'kind'),
        'title',  public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'detail', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture partnership opportunity. No partner is named, no approach is made, and it is created inside a transaction that is aborted.');

    elsif st.stage_key = 'invoice_receipt' then
      -- transaction_id is NOT NULL and a foreign key, so this stage depends on payment_transaction
      -- and takes the transaction the scenario created rather than choosing one.
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object(
        'transaction_id', v_refs->>'transaction_id',
        'bucket', 'zz-phase-d-fixtures',
        'path',   format('zz/%s/invoice-%s.pdf', v_label, st.stage_key));

    else
      -- G10. EVERY STAGE THE CHAIN ABOVE DOES NOT NAME, WHICH IS SIXTEEN PHASE D STORE OBJECTS AND
      -- ANY ADDED LATER. The object store writes from the payload every stage already carries, so
      -- the only thing these need is the one fact the store checks and a bookkeeping payload cannot
      -- supply: WHO OWNS THE RECORD. That is derived from the object's own declared ownership_scope
      -- rather than repeated sixteen times, so a CUSTOMER-scoped case is owned by the scenario's
      -- customer and a SUPPLIER-scoped one by its supplier. D9h found the opposite of this once --
      -- a customer-scoped object owned by something that was not a customer -- and a derivation
      -- cannot drift back into it one object at a time.
      v_owner := case (select ob.ownership_scope from public.phase_d_business_object_binding ob
                        where ob.object_id = st.object_id)
                   when 'CUSTOMER' then coalesce(nullif(v_refs->>'customer_id',''), v_key)
                   when 'SUPPLIER' then coalesce(nullif(v_refs->>'supplier_id',''), v_key)
                   else v_key end;
      v_pay := v_pay || jsonb_build_object('note', format(
        'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture %s, created through fn_phase_d_object_write inside a transaction that is aborted. It states nothing about the business and is never published.',
        st.object_id));
    end if;

    select count(*) into v_notif_before from public.notifications;
    select coalesce(max(id),0) into v_notif_id_before from public.notifications;  -- G11
    select count(*) into v_inbox_before from public.kernel_trigger_inbox;

    begin
      v_w := public.fn_phase_d_object_write(jsonb_build_object(
        'object_id', st.object_id, 'business_key', v_key, 'owner_ref', v_owner,
        'created_by', v_actor, 'state', v_state, 'payload', v_pay));

      select count(*) into v_notif_after from public.notifications;
      if v_notif_after <> v_notif_before then
        -- G11. A STAGE MAY WRITE INTO ITS OWN OBJECT'S CANONICAL RELATION, AND ONLY SUPPRESSED.
        -- The assertion exists because a canonical write to some OTHER object queued a message as a
        -- side effect, and that property is what the Phase D hold rests on. It could not tell that
        -- apart from the one stage whose DECLARED object is the notification. Narrowed by
        -- derivation, never by naming a stage: the relation must be this object's own canonical
        -- relation, and every row written must carry the suppression the outbound door declares for
        -- it. A stage writing here for any other object still aborts the build, and so does this one
        -- if the row it wrote is deliverable.
        if not exists (select 1 from public.phase_d_object_write_map wm2
                        where wm2.object_id = st.object_id
                          and wm2.target_relation = 'public.notifications')
           -- and every row this stage wrote must carry the state the stage declares, which is the
           -- value the outbound door forces and no sender selects. A row at any other status is a
           -- deliverable message and aborts the build exactly as before.
           or exists (select 1 from public.notifications n
                       where n.id > v_notif_id_before
                         and n.status is distinct from st.working_state)
        then
          raise exception 'fn_phase_d_fixture_scenario: stage % wrote % row(s) into public.notifications. A fixture may not queue an outbound message. (pd_fixture_external_effect_produced)',
            st.stage_key, v_notif_after - v_notif_before using errcode = '23514';
        end if;
      end if;

      -- F15. THE PRODUCT'S OWN TRIGGERS GET THE LAST WORD ON AN INSERT, SO SETTLE THE STATE.
      -- public.trg_inquiry_enrich is a BEFORE INSERT trigger that sets the status a NEW inquiry
      -- has, so the inquiry stage asked for quote_ready and the row came out open, and GATE-011
      -- and BR-013 refused it -- correctly, because it was not quote-ready. A real inquiry is
      -- created open and BECOMES quote-ready, so the factory now does that: create, read back the
      -- column the write map points at the state, and if the product moved it, write again through
      -- the same canonical service. Skipped entirely when the readback already agrees.
      select c.k into v_state_col
        from public.phase_d_object_write_map wm,
             lateral (select k from jsonb_object_keys(wm.column_map) k where wm.column_map->>k = 'state') c
       where wm.object_id = st.object_id limit 1;
      if v_state_col is not null then
        begin
          execute format('select %I::text from %s where %I::text = $1',
                         v_state_col,
                         (select wm.target_relation from public.phase_d_object_write_map wm
                           where wm.object_id = st.object_id),
                         (select wm.key_column from public.phase_d_object_write_map wm
                           where wm.object_id = st.object_id))
            into v_actual using coalesce(split_part(v_w->>'result_reference','=',2), v_key);
          if v_actual is distinct from v_state then
            -- H08. ADDRESS THE ROW THE FIRST WRITE RETURNED. v_key is the stage's own uuid and names
            -- nothing on a generated-key relation; the returned identity is the row.
            v_w := public.fn_phase_d_object_write(jsonb_build_object(
              'object_id', st.object_id,
              'business_key', coalesce(split_part(v_w->>'result_reference','=',2), v_key),
              'owner_ref', v_owner,
              'created_by', v_actor, 'state', v_state, 'payload', v_pay));
            v_man := v_man || jsonb_build_array(jsonb_build_object(
              'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
              'status','SETTLED',
              'detail', format('%s.%s was %s after the create and the stage declares %s; a second write through the same canonical service settled it',
                               v_state_col, st.object_id, coalesce(v_actual,'(null)'), v_state)));
          end if;
        exception when others then
          v_man := v_man || jsonb_build_array(jsonb_build_object(
            'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
            'status','SETTLE_REFUSED',
            'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
            'reason', left(SQLERRM, 300)));
        end;
        v_state_col := null; v_actual := null;
      end if;

      -- F02. THE EVIDENCE MANIFEST THE FOUNDER ASKED FOR. Written from what the canonical write
      -- RETURNED, in the same statement block, so a manifest entry cannot exist for an object the
      -- service did not create -- and so an object the service created cannot be missing from it.
      v_scenario_id := public.fn_phase_d_scenario_record_write(jsonb_build_object(
        'fixture_id',        format('PDS-%s', st.stage_key),
        'fixture_version',   1,
        'source_checksum',   encode(sha256(convert_to(v_pay::text,'UTF8')),'hex'),
        'object_id',         st.object_id,
        'business_key',      coalesce(split_part(v_w->>'result_reference','=',2), v_key),
        'owner_ref',         v_owner,
        'ownership_scope',   coalesce((select ob.ownership_scope
                                         from public.phase_d_business_object_binding ob
                                        where ob.object_id = st.object_id), 'COMPANY'),
        'state',             v_w->>'state',
        'canonical_relation',v_w->>'canonical_relation',
        'canonical_service', 'fn_phase_d_object_write',
        'result_reference',  v_w->>'result_reference',
        'contributes_ref',   st.contributes_ref,
        'contributes_kind',  st.contributes_kind,
        'canonical_ref',     v_w->'canonical_ref',
        'contributed_value', case when st.stage_key = 'inquiry_route_set' then 'confirmed'
                                  -- F41. A PAYLOAD_VALUE STAGE CONTRIBUTES A VALUE, NOT ITS ROW ID.
                                  -- artifact_revision declares it contributes artifact_sha256, and
                                  -- this expression handed over split_part(result_reference,'=',2)
                                  -- -- the primary key of the row it had just written. BR-036 read
                                  -- 44208 and refused it as "not a SHA-256 digest", correctly.
                                  -- The digest is in the record's own payload, written by F08 over
                                  -- the committed artifact body, so it is read from there.
                                  -- F42. AN OBJECT_KEY STAGE CONTRIBUTES THE KEY THE PHASE D
                                  -- OBJECT STORE USES, WHICH IS NOT THE RELATION'S ROW ID.
                                  -- F45. OBJECT_KEY AND RESULT_KEY WERE THE SAME QUESTION ASKED TWICE.
                                  -- Which identity an object is known by is a property of the
                                  -- object, recorded once in phase_d_object_reference_strategy and
                                  -- derived from the frozen map -- not something a stage decides.
                                  -- Both arms are now the canonical reference the writer returned.
                                  when st.contributes_kind in ('OBJECT_KEY','RESULT_KEY')
                                    then v_w->'canonical_ref'->>'canonical_identity'
                                  when st.contributes_kind = 'PAYLOAD_VALUE' then
                                    (select o.payload #>> array[st.contributes_ref]
                                       from public.phase_d_object_record o
                                      where o.object_id = st.object_id
                                        and o.business_key = split_part(v_w->>'result_reference', '=', 2)
                                      limit 1)
                                  else split_part(v_w->>'result_reference', '=', 2) end,
        'expected_effect',   coalesce(st.note,'(none recorded on the stage)')));

      if st.contributes_ref is not null then
        v_refs := v_refs || jsonb_build_object(st.contributes_ref,
          case when st.stage_key = 'inquiry_route_set' then 'confirmed'
               when st.contributes_kind in ('OBJECT_KEY','RESULT_KEY')
                 then v_w->'canonical_ref'->>'canonical_identity'
               when st.contributes_kind = 'PAYLOAD_VALUE' then
                 (select o.payload #>> array[st.contributes_ref]
                    from public.phase_d_object_record o
                   where o.object_id = st.object_id
                     and o.business_key = split_part(v_w->>'result_reference', '=', 2)
                   limit 1)
               else split_part(v_w->>'result_reference', '=', 2) end);
      end if;

      select count(*) into v_inbox_after from public.kernel_trigger_inbox;
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status','CREATED', 'relation', v_w->>'canonical_relation',
        'result_reference', v_w->>'result_reference', 'state', v_w->>'state',
        'policy_family', v_w->>'policy_family',
        'notifications_written', v_notif_after - v_notif_before,
        'kernel_trigger_rows_written', v_inbox_after - v_inbox_before,
        'contributes', st.contributes_ref));
      v_ok := v_ok + 1;

    exception when others then
      v_err := SQLERRM;
      if position('pd_fixture_external_effect_produced' in v_err) > 0 then raise; end if;
      -- D17. An outbound HTTP request is not a stage that failed; it is the whole scenario losing
      -- its zero-external-effect property. It aborts the build exactly as a notification does.
      if position('pd_object_outbound_request_produced' in v_err) > 0 then raise; end if;
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status','REFUSED',
        'refused_with', coalesce((regexp_match(v_err,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
        'reason', left(v_err, 300)));
      v_blocked := v_blocked + 1;
    end;
  end loop;

  -- G12. THE THREE OBJECTS ONLY THE KERNEL MAY CREATE, asked for through the kernel's own doors.
  -- fn_phase_d_object_write refuses workflow_run, workflow_step_run and handoff_record by name --
  -- "a Phase D handler that wrote it would be a second creator for one object" -- so no stage of
  -- the chain above can create them and the round-trip proof reported all three as
  -- NOT_CREATED_BY_ANY_STAGE, counted as neither pass nor fail. This does not write them either: it
  -- calls fn_kernel_workflow_start and fn_kernel_step_complete and records what the kernel made.
  begin
    v_w := public.fn_phase_d_kernel_object_fixture(jsonb_build_object('label', v_label));
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 998, 'stage_key','kernel_objects', 'object_id','workflow_run/workflow_step_run/handoff_record',
      'status', case when coalesce((v_w->>'objects_recorded')::int,0) > 0 then 'CREATED' else 'REFUSED' end,
      'relation','public.phase_c_workflow_run + _step_run + _handoff_run',
      'result_reference', format('run_id=%s step_run_id=%s handoff_run_id=%s',
        coalesce(v_w->>'run_id','(none)'), coalesce(v_w->>'step_run_id','(none)'),
        coalesce(v_w->>'handoff_run_id','(none)')),
      'state','open', 'contributes', null, 'detail', v_w->>'note'));
    if coalesce((v_w->>'objects_recorded')::int,0) > 0 then v_ok := v_ok + 1;
    else v_blocked := v_blocked + 1; end if;
  exception when others then
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 998, 'stage_key','kernel_objects', 'object_id','workflow_run/workflow_step_run/handoff_record',
      'status','REFUSED',
      'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
      'reason', left(SQLERRM, 300)));
    v_blocked := v_blocked + 1;
  end;

  -- F12. THE FOUNDER AUTHORITY FIXTURE, LAST, BECAUSE NOTHING DEPENDS ON IT. Six rules resolve
  -- founder_authority_ref against public.founder_command; a Phase D run has no founder command
  -- behind it, so all six refuse on every founder-gated step. This creates one, marked, at state
  -- received, founder_initiated_only false and refund_semantics false, inside the same aborted
  -- transaction -- and it authenticates nobody: see the header of F12.
  begin
    v_w := public.fn_phase_d_founder_authority_fixture(jsonb_build_object('label', v_label));
    v_refs := v_refs || jsonb_build_object('founder_authority_ref', v_w->>'founder_authority_ref');
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 999, 'stage_key','founder_authority', 'object_id','founder_command_fixture',
      'status','CREATED', 'relation','public.founder_command',
      'result_reference', v_w->>'founder_authority_ref', 'state','received',
      'contributes','founder_authority_ref'));
    v_ok := v_ok + 1;
  exception when others then
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 999, 'stage_key','founder_authority', 'object_id','founder_command_fixture',
      'status','REFUSED',
      'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
      'reason', left(SQLERRM, 300)));
    v_blocked := v_blocked + 1;
  end;

  select count(*) into v_notif_after from public.notifications;
  select count(*) into v_inbox_after from public.kernel_trigger_inbox;

  select coalesce(max(id),0) into v_notif_id_before from public.notifications;  -- reused as a bound

  return jsonb_build_object(
    'ok', v_blocked = 0, 'label', v_label, 'fixture_run_id', v_fixture_run,
    'evidence_manifest', (select coalesce(jsonb_agg(to_jsonb(x) order by x.scenario_record_id),'[]'::jsonb)
                            from public.phase_d_scenario_record x
                           where x.fixture_run_id = v_fixture_run),
    'stages_created', v_ok, 'stages_not_created', v_blocked,
    'stages_left_to_the_workflow_under_test', v_owned, 'for_workflow', v_for_wf,
    'stages_declared', (select count(*) from public.phase_d_fixture_stage where stage_no <= v_upto),
    'parent_refs', v_refs,
    -- THE RULE CONTEXT IS WHAT THIS SCENARIO ACTUALLY PERSISTED, not a set of plausible strings.
    -- Every value below is either a key returned by a write above or the exact value that write
    -- recorded on the row. A rule reading one of these is reading the scenario, and a rule whose
    -- key is absent still gets the driver's generated fixture and still refuses.
    -- F08. `rule_context` used to be returned here as a set of plausible strings for a caller to
    -- hand the rules. E32 removed the caller's ability to hand the kernel anything, so nothing has
    -- read it since; and two of its values were false -- terms_hash was the digest of the VERSION
    -- STRING, and safe_package_approved_by and assignment_result were literals with no record
    -- behind them. It is replaced by evidence_manifest above, which is what this scenario actually
    -- persisted, and by the committed catalogue for the values that are content rather than record.
    'parent_ref_keys', (select coalesce(jsonb_agg(k order by k),'[]'::jsonb)
                          from jsonb_object_keys(v_refs) k),
    'manifest', v_man,
    'notifications_written_by_this_scenario', v_notif_after - v_notif_start,
    -- G13. THE ONE THAT MUST BE ZERO. A row a sender would select is a queued outbound message; a
    -- row at the suppression the outbound door forces is a record. The suppression is read from the
    -- stage that declares it rather than written here, so there is no second copy of the word.
    'deliverable_notifications_written_by_this_scenario',
      (select count(*) from public.notifications n
        where n.id > coalesce(v_notif_id_start, 0)
          and n.status is distinct from (
            select st2.working_state from public.phase_d_fixture_stage st2
             where st2.object_id in (select wm3.object_id from public.phase_d_object_write_map wm3
                                      where wm3.target_relation = 'public.notifications')
             limit 1)),
    'kernel_trigger_rows_written_by_this_scenario', v_inbox_after - v_inbox_start,
    -- D17. MEASURED, NOT ASSERTED. Before D17 this object said 'external_effects', 0 while every
    -- build enqueued two POSTs to production edge functions, because the only thing counted was
    -- public.notifications. Both doors are now counted and the writer refuses on either.
    'outbound_http_requests_written_by_this_scenario',
      (select r.n from public.fn_phase_d_outbound_requests_by_this_transaction(v_net_start) r),
    'external_effects', 0, 'paid_calls', 0,
    'note', 'every row here was written through fn_phase_d_object_write; abort the transaction to leave nothing behind');
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_founder_authority(p_run_id bigint, p_step_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_wf       text;
  v_cmd      bigint;
  v_state    text;
  v_reserved text;
  v_reserving text;
  v_digest   text;
  v_baseline text;
  v_covers   boolean;
  v_exists   boolean;
  v_current  boolean;
begin
  select s.workflow_id into v_wf from public.phase_b_workflow_step s where s.step_id = p_step_id;
  if v_wf is null then
    return jsonb_build_object('ref', null, 'kind', 'UNKNOWN_STEP',
      'exists', false, 'current', false, 'covers', false, 'valid', false,
      'why', format('%s is not a step of the frozen registry', coalesce(p_step_id, '(null)')));
  end if;

  -- WHAT THE FOUNDER RESERVED, read from the register he approved. Never a list in this body.
  select string_agg(b.boundary_id, ';' order by b.boundary_id) into v_reserved
    from public.phase_b_founder_boundary b
   where v_wf = any (string_to_array(replace(b.workflow_scope, ' ', ''), ';'));

  -- 1. A FOUNDER COMMAND, where one instructed this run.
  select l.command_id into v_cmd from public.founder_command_workflow_link l
   where l.run_id = p_run_id limit 1;
  if v_cmd is null then
    select r.command_id into v_cmd from public.phase_c_workflow_run r where r.run_id = p_run_id;
  end if;

  if v_cmd is not null then
    select fc.state into v_state from public.founder_command fc where fc.command_id = v_cmd;
    v_exists  := v_state is not null;
    v_current := v_exists and v_state <> 'cancelled';
    v_covers  := exists (select 1 from public.founder_command_workflow_link l2
                          where l2.command_id = v_cmd and l2.workflow_id = v_wf)
              or exists (select 1 from public.phase_c_workflow_run r2
                          where r2.run_id = p_run_id and r2.command_id = v_cmd);
    return jsonb_build_object(
      'ref',     'founder_command:' || v_cmd::text,
      'kind',    'FOUNDER_COMMAND',
      'source',  'founder_command that started this run',
      'artefact','public.founder_command',
      'reserved_by', v_reserved,
      'exists',  v_exists, 'current', v_current, 'covers', v_covers,
      'valid',   v_exists and v_current and v_covers,
      'why', format('founder command %s is %s and %s workflow %s', v_cmd,
                    case when not v_exists then 'not on record'
                         when v_current then 'live (state ' || v_state || ')'
                         else 'cancelled' end,
                    case when v_covers then 'selected' else 'DID NOT select' end, v_wf));
  end if;

  -- 2. DELEGATED AUTHORITY, read off the founder-approved frozen boundary register.
  select d.sha256 into v_digest
    from public.fn_phase_b_structure_digest() d where d.subject = 'founder_boundaries';
  select bl.registry_sha256->'structure'->'founder_boundaries'->>'database' into v_baseline
    from public.org_phase_baseline bl where bl.phase = 'B';

  v_exists  := v_digest is not null
               and exists (select 1 from public.phase_b_founder_boundary)
               and v_baseline is not null;
  v_current := v_exists and v_digest = v_baseline;
  -- HIS RULING OF 26 AUG 2026, ENCODED WHERE IT CAN BE CHECKED RATHER THAN REMEMBERED.
  --
  -- This read `v_reserved is null` -- a workflow named in ANY boundary's scope could never proceed
  -- on delegated authority. FDR-002's own enforcement clause says otherwise: "Systems may calculate
  -- only from approved configuration." Calculating from what he approved IS the permitted act, not
  -- a reason to stop and ask him.
  --
  -- In his words, asked what FDR-002 reserves: the reveal fee "is three percent, and it's
  -- automated. It doesn't need me"; supplier subscription "the first one thousand suppliers are for
  -- free... anyone after, he is paying one thousand dirham per year... all automated, nothing to be
  -- done by me"; and "regarding the refund, that's the only thing where my decision is involved."
  --
  -- So a covering boundary blocks delegation only when it is classified as reserving the ACT.
  -- public.phase_d_founder_boundary_disposition holds that classification, and a boundary with NO
  -- row defaults to RESERVING -- fail closed, so nothing is loosened by omission. FDR-002 is the
  -- only row today.
  select string_agg(b.boundary_id, ';' order by b.boundary_id) into v_reserving
    from public.phase_b_founder_boundary b
   where v_wf = any (string_to_array(replace(b.workflow_scope, ' ', ''), ';'))
     and not exists (
       select 1 from public.phase_d_founder_boundary_disposition dp
        where dp.boundary_id = b.boundary_id
          and dp.disposition = 'CONSTRAINS_THE_CONFIGURATION'
          -- THE CLASSIFICATION IS ABOUT A SENTENCE, SO IT NAMES THAT SENTENCE'S DIGEST. If the
          -- frozen enforcement text is ever amended, the digest stops matching and the boundary
          -- reverts to reserving until someone re-reads it against his ruling.
          and dp.enforcement_digest = encode(sha256(convert_to(b.phase_b_enforcement, 'UTF8')), 'hex'));
  v_covers  := v_reserving is null;

  if not v_covers then
    return jsonb_build_object(
      'ref', null, 'kind', 'FOUNDER_RESERVED',
      'source', 'public.phase_b_founder_boundary',
      'artefact', 'public.phase_b_founder_boundary@' || coalesce(left(v_digest, 16), '(none)'),
      'reserved_by', v_reserving, 'in_scope_of', v_reserved,
      'exists', v_exists, 'current', v_current, 'covers', false, 'valid', false,
      'why', format('%s is reserved to the founder by %s and no founder command instructed this run%s',
                    v_wf, v_reserving,
                    case when v_reserved is distinct from v_reserving
                         then format(' (in scope of %s; the rest constrain configuration only)', v_reserved)
                         else '' end));
  end if;

  return jsonb_build_object(
    'ref',     'founder_policy:phase_b_founder_boundary@' || coalesce(left(v_digest, 16), 'unknown'),
    'kind',    'DELEGATED_AUTHORITY',
    'source',  'public.phase_b_founder_boundary, the founder-approved frozen register of what he '
            || 'reserves: '
            || case when v_reserved is null
                    then 'it names no boundary over ' || v_wf
                    else 'every boundary naming ' || v_wf || ' (' || v_reserved || ') constrains the '
                      || 'configuration operations run within rather than reserving the act' end
            || ', so the decision is delegated to the step''s accountable role',
    'artefact','public.phase_b_founder_boundary@' || coalesce(left(v_digest, 16), 'unknown'),
    'reserved_by', null, 'in_scope_of', v_reserved,
    'exists',  v_exists, 'current', v_current, 'covers', true,
    'valid',   v_exists and v_current,
    'why', format('the founder-approved boundary register (%s rows, digest %s) %s the Phase B '
               || 'baseline and reserves no ACT in %s%s',
                  (select count(*) from public.phase_b_founder_boundary),
                  coalesce(left(v_digest, 16), '(none)'),
                  case when v_current then 'matches' else 'DOES NOT match' end, v_wf,
                  case when v_reserved is null then ''
                       else format(' (%s name it and constrain configuration only)', v_reserved) end));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_founder_authority_fixture(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run   bigint := public.fn_phase_d_fixture_context();
  v_label text   := nullif(btrim(coalesce(p_input->>'label','')),'');
  v_id    bigint;
  v_msg   bigint;
  v_text  text;
  v_trace bigint;   -- G19: the root trace the guard requires before the command may move
begin
  if v_run is null then
    raise exception 'fn_phase_d_founder_authority_fixture: no verified Phase D fixture context. A founder command fixture exists only inside an audited fixture run, inside a transaction that is aborted. (pd_fixture_no_test_context)'
      using errcode = '42501';
  end if;
  if v_label is null then
    raise exception 'fn_phase_d_founder_authority_fixture: label is required (pd_fixture_label_missing)'
      using errcode = '22023';
  end if;

  v_text := format('PHASE_D_FIXTURE_DO_NOT_PUBLISH — Phase D fixture command for run %s (%s). '
                || 'This is not an instruction from the founder. It exists so that the six rules '
                || 'which resolve founder_authority_ref against public.founder_command have a row '
                || 'to resolve, and it is created inside a transaction that is aborted.',
                   v_run, v_label);

  -- founder_identity is DELIBERATELY a string that resolves to nobody. E39's finding was that a
  -- guard authenticating a string is not authenticating an actor; writing the founder's real
  -- identity here would be the same mistake made on purpose.
  insert into public.founder_command_message
    (founder_identity, raw_text, raw_text_hash, client_idempotency_key, channel)
  values ('PHASE_D_FIXTURE_DO_NOT_PUBLISH',
          v_text,
          encode(sha256(convert_to(v_text,'UTF8')),'hex'),
          format('phase_d_fixture:%s:%s', v_run, v_label),
          'phase_d_fixture')
  returning message_id into v_msg;

  insert into public.founder_command
    (message_id, intent_id, outcome, command_owner_role_id, state, priority, primary_role_id,
     founder_initiated_only, refund_semantics)
  values (v_msg,
          format('PHASE_D_FIXTURE_DO_NOT_PUBLISH:%s', v_label),
          'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture founder command. It is not an instruction from the founder, it authorises nothing, and it is created inside a transaction that is aborted.',
          'ceo',
          'received',
          'low',
          'ceo',
          false,
          false)
  returning command_id into v_id;

  -- G19. THE ROOT TRACE, OPENED THE WAY THE ROUTER OPENS IT.
  -- Without this the command is stuck at 'received' for the rest of its life:
  -- fn_founder_command_trace_guard refuses every later transition with "cannot leave received
  -- without a root trace", and that refusal is correct. The command is created at received above
  -- (the one state the guard allows trace-less at birth) and the trace is stamped on it here, in
  -- the same transaction, which is the sequence the guard's own comment describes.
  v_trace := public.fn_phase_c_trace_write('TRACE-FOUNDER-COMMAND', jsonb_build_object(
    'subject_kind',   'founder_command',
    'subject_ref',    v_id::text,
    'command_id',     v_id,
    'actor_role_id',  'ceo',
    'system_actor_id','fn_phase_d_founder_authority_fixture',
    'state_before',   '',
    'state_after',    'received',
    'status',         'open',
    'evidence_refs',  jsonb_build_array(jsonb_build_object(
      'phase_d_fixture_run', v_run, 'label', v_label,
      'note', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — the root trace of a Phase D fixture founder command. It records that this command exists inside an aborted fixture transaction and authorises nothing.'))));

  update public.founder_command set trace_id = v_trace where command_id = v_id;

  perform public.fn_phase_d_scenario_record_write(jsonb_build_object(
    'fixture_id',        'PDS-founder_authority',
    'fixture_version',   1,
    'source_checksum',   encode(sha256(convert_to(v_text,'UTF8')),'hex'),
    'object_id',         'founder_command_fixture',
    'business_key',      v_id::text,
    'owner_ref',         'ceo',
    'ownership_scope',   'COMPANY',
    'state',             'received',
    'canonical_relation','public.founder_command',
    'canonical_service', 'fn_phase_d_founder_authority_fixture',
    'result_reference',  format('public.founder_command:command_id=%s', v_id),
    'contributes_ref',   'founder_authority_ref',
    'contributes_kind',  'RESULT_KEY',
    'contributed_value', format('founder_command:%s', v_id),
    'expected_effect',   'BR-003, BR-021..BR-024 and BR-043 resolve founder_authority_ref against public.founder_command and find this row. It authorises nothing: founder AUTHENTICATION is fn_phase_c_require_founder, which reads a verified auth subject and never this table.'));

  return jsonb_build_object('ok', true, 'command_id', v_id, 'message_id', v_msg,
    'founder_authority_ref', format('founder_command:%s', v_id),
    'founder_identity_on_the_message', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — resolves to nobody',
    'founder_initiated_only', false, 'refund_semantics', false,
    'note','a fixture command; it satisfies "a founder command exists" and nothing else');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_gate_applies(p_gate_id text, p_step_id text)
 RETURNS TABLE(applies boolean, why text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g public.phase_b_gate%rowtype; s public.phase_b_workflow_step%rowtype;
        v_subject text; v_producer text; v_predicate text;   -- K07
begin
  select * into g from public.phase_b_gate where gate_id = p_gate_id;
  if not found then applies := false; why := format('unknown gate %s', p_gate_id); return next; return; end if;
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then applies := false; why := format('unknown step %s', p_step_id); return next; return; end if;

  if upper(g.workflow_scope) <> 'ALL'
     and not (s.workflow_id = any (string_to_array(replace(g.workflow_scope,' ',''), ';'))) then
    applies := false;
    why := format('%s is scoped to %s and %s is in %s', g.gate_id, g.workflow_scope, p_step_id, s.workflow_id);
    return next; return;
  end if;

  if p_gate_id = 'GATE-004' and coalesce(btrim(s.independent_reviewer_role_id),'') = '' then
    applies := false;
    why := format('GATE-004 governs the independence of a named reviewer and %s names none', p_step_id);
    return next; return;
  end if;

  if p_gate_id = 'GATE-005' and lower(coalesce(btrim(s.founder_gate),'none')) = 'none' then
    applies := false;
    why := format('GATE-005 governs a founder-reserved decision and %s declares founder_gate none', p_step_id);
    return next; return;
  end if;

  -- GATE-020 — "Refund authority and idempotency", pass_result "Execute once". It guards the money
  -- movement, and the frozen registry names that step by carrying a founder_gate on it and on no
  -- other step of W17: "Money movement beyond approved policy requires founder approval." Demanding
  -- an approved case decision at the step that OPENS the case is a condition the workflow itself is
  -- what satisfies, four steps later. Refund authority is unaffected: it is held by the trigger
  -- z00_refund_founder_decision_only on public.refunds, which raises unless an approved refund was
  -- decided by an active founder identity, on every path, workflow or not.
  -- D28. GATE-015 — "No existing assignment for same supplier, inquiry version and dispatch scope."
  --
  -- It prevents a DUPLICATE dispatch, so it governs every step up to AND INCLUDING the one that
  -- creates the assignment. That is where a duplicate is actually stopped. A step running AFTER the
  -- creating step in the same workflow is premised on the assignment EXISTING: W12-S07 is "Create
  -- exactly one notification per assignment", and refusing it because an assignment exists refuses
  -- the workflow for having done its own job one step earlier.
  --
  -- THIS IS NOT THE WHOLE-WORKFLOW EXEMPTION THAT WAS TRIED AS D17 AND DISCARDED. GATE-015 is
  -- scoped to W12 alone, so exempting W12 would leave it governing nothing — the session brief says
  -- exactly that and it is right. This exempts only the steps that come after the assignment has
  -- been legitimately created, and the gate still governs W12-S01 through S06, the creating step
  -- included. Its purpose survives intact.
  --
  -- THE PRODUCING STEP IS DERIVED, NEVER NAMED HERE. The object the gate measures is resolved by
  -- matching the gate contract's own evidence_source against the canonical relation of the object,
  -- and the producing step is then read from phase_d_step_effect. Renaming a step or moving the
  -- effect moves this with it.
  --
  -- The same shape as the GATE-020 refinement immediately below, which the estate already accepted:
  -- a condition that the workflow itself is what satisfies, demanded before the workflow satisfies it.
  if p_gate_id = 'GATE-015'
     and exists (
       select 1
         from public.phase_d_step_effect e
         join public.phase_d_business_object_binding bb on bb.object_id = e.effect_object_id
         join public.phase_d_gate_contract gc on gc.gate_id = p_gate_id
        where e.workflow_id = s.workflow_id
          and e.step_id < p_step_id
          and bb.canonical_relation is not null
          and gc.evidence_source ilike '%' || bb.canonical_relation || '%')
  then
    applies := false;
    why := format('GATE-015 stops a DUPLICATE dispatch, so it governs up to and including the step that creates the assignment; %s runs after it and is premised on the assignment existing', p_step_id);
    return next; return;
  end if;

  if p_gate_id = 'GATE-020' and lower(coalesce(btrim(s.founder_gate),'none')) = 'none' then
    applies := false;
    why := format('GATE-020 guards the execution of an approved financial action; %s declares founder_gate none and is not the money-movement step', p_step_id);
    return next; return;
  end if;

  if p_gate_id = 'GATE-007'
     and not exists (select 1 from public.phase_b_handoff h where h.from_step_id = p_step_id) then
    applies := false;
    why := format('GATE-007 governs a handoff packet and %s opens no handoff', p_step_id);
    return next; return;
  end if;

  if p_gate_id = 'GATE-008' and not coalesce(s.is_closure_step, false) then
    applies := false;
    why := format('GATE-008 is a closure gate and %s is not the closure step', p_step_id);
    return next; return;
  end if;

  -- G03. A GATE THAT DEMANDS A REVIEWER'S VERDICT AT A STEP THAT RUNS BEFORE ANY REVIEW.
  --
  -- Measured, on the three gates whose evidence_keys name reviewer_role_id:
  --
  --   GATE-021 "Marketing artifact approval", pass_result "Publish approved revision.", scope W03;W20
  --            refused W03-S01 "Set acquisition objective" and W20-S01 "Define content objective
  --            and hypothesis" for want of the reviewer of a final asset the workflow has not yet
  --            produced. W03 first reviews at S06; W20 at S04.
  --   GATE-026 "Knowledge validation", pass_result "Publish runtime-eligible version.", scope W26
  --            refused W26-S01 "Open knowledge gap or change", an INTAKE step. W26 first reviews
  --            at S05.
  --
  -- Both are the shape this function already refines twice. GATE-020 was narrowed because it
  -- demanded an approved case decision at the step that OPENS the case; GATE-015 because it
  -- refused a workflow for having done its own job one step earlier. This is the same sentence:
  -- a condition that the workflow itself is what satisfies, demanded before the workflow
  -- satisfies it.
  --
  -- NOTHING IS WEAKENED. The gate still applies from the workflow's first review step to its last
  -- step, which is where the artifact exists, where the review happens, and where publication is
  -- decided -- W03-S06..S09, W20-S04..S09, W26-S05..S09. A step at or after that point with no
  -- recorded reviewer still refuses.
  --
  -- NO GATE AND NO STEP IS NAMED. The condition is derived: the gate's own evidence_keys carry
  -- reviewer_role_id, and the frozen registry says which of this workflow's steps are reviews.
  -- A workflow with no review step at all is untouched -- there is no point before which to be
  -- early -- and GATE-004 keeps its own, narrower, earlier exemption.
  if exists (select 1 from public.phase_d_gate_contract gc
              where gc.gate_id = p_gate_id
                and 'reviewer_role_id' = any(gc.evidence_keys))
     and p_step_id < (select min(rs.step_id) from public.phase_b_workflow_step rs
                       where rs.workflow_id = s.workflow_id and rs.step_type = 'review')
  then
    applies := false;
    why := format('%s requires an independent reviewer''s verdict and %s runs before %s, the first review step of %s; the review this gate reads is produced by the workflow itself, later',
                  p_gate_id, p_step_id,
                  (select min(rs.step_id) from public.phase_b_workflow_step rs
                    where rs.workflow_id = s.workflow_id and rs.step_type = 'review'),
                  s.workflow_id);
    return next; return;
  end if;

  -- K07. THE GENERAL RULE THE FOUR NARROWINGS ABOVE ARE INSTANCES OF: a gate does not govern a
  -- step that runs BEFORE the step which produces the gate's own subject. GATE-013 asked W08-S01 --
  -- the first step of the workflow whose purpose is to build the supplier-safe package -- to
  -- already name that package.
  --
  -- IT IS A BEFORE-RULE, NOT A WHOLE-WORKFLOW EXEMPTION. The gate still applies at the producing
  -- step and at every step after it, so a gate scoped to one workflow still governs it. Nothing is
  -- named here: the subject is the gate contract's own evidence key matched against
  -- public.phase_d_fixture_stage.contributes_ref -- the same derivation fn_phase_d_rule_applies
  -- uses -- and the producing step is read from public.phase_d_step_effect.
  select st.object_id, gc.predicate_kind into v_subject, v_predicate
    from public.phase_d_gate_contract gc
    join public.phase_d_fixture_stage st on st.contributes_ref = any(gc.evidence_keys)
   where gc.gate_id = p_gate_id
   limit 1;
  if v_subject is not null then
    select min(x.step_id) into v_producer
      from public.phase_d_step_effect x
     where x.workflow_id = s.workflow_id and x.effect_object_id = v_subject;
    if v_producer is not null
       and (p_step_id < v_producer
            -- AT the producing step too, but only where the gate's test is the PRESENCE of the
            -- subject's identity. A MEASURED gate is untouched: GATE-015 exists to judge the
            -- creating step, and exempting it there would leave it governing nothing.
            or (p_step_id = v_producer and v_predicate = 'EVIDENCE_REQUIRED')) then
      applies := false;
      why := format('%s judges %s and %s runs %s %s, the step of %s that produces it; the gate '
                 || 'governs its use %s, not before it exists',
                    p_gate_id, v_subject, p_step_id,
                    case when p_step_id = v_producer then 'at' else 'before' end,
                    v_producer, s.workflow_id,
                    case when v_predicate = 'EVIDENCE_REQUIRED'
                         then 'after the producing step' else 'from the producing step onward' end);
      return next; return;
    end if;
  end if;

  applies := true;
  why := format('%s (%s, scope %s) applies to %s', g.gate_id, g.gate_type, g.workflow_scope, p_step_id);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_gate_evaluate(p_gate_id text, p_evidence jsonb)
 RETURNS TABLE(state text, passed boolean, gate_type text, reason text, refusal_code text, evidence_absent boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_g13_ok boolean; v_g13_code text; v_g13_why text;   -- O07
  g public.phase_b_gate%rowtype;
  c public.phase_d_gate_contract%rowtype;
  s public.phase_b_workflow_step%rowtype;
  v_missing text[]; v_n bigint; v_ok boolean; v_txt text;
  v_auth jsonb;   -- K01
begin
  evidence_absent := false;   -- E19, see fn_phase_d_rule_check
  select * into g from public.phase_b_gate where gate_id = p_gate_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; passed := false; gate_type := 'unknown';
    reason := format('unknown gate %s — blocked, not defaulted', p_gate_id);
    refusal_code := 'gate_unknown'; return next; return;
  end if;
  gate_type := g.gate_type;

  select * into c from public.phase_d_gate_contract where gate_id = p_gate_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; passed := false;
    reason := format('gate %s has no Phase D evidence contract — blocked', p_gate_id);
    refusal_code := 'gate_uncontracted'; return next; return;
  end if;
  refusal_code := c.refusal_code;

  if cardinality(c.evidence_keys) > 0 then
    select array_agg(k order by k) into v_missing
      from unnest(c.evidence_keys) k
     where p_evidence is null or not (p_evidence ? k)
        or jsonb_typeof(p_evidence->k) = 'null'
        or (jsonb_typeof(p_evidence->k) = 'string' and btrim(p_evidence->>k) = '');
    if v_missing is not null then
      -- E19. Same distinction as the rule side. The gate is BLOCKED either way; this column says
      -- which kind of blocked. Here the gate never saw its evidence -- it did not judge it.
      evidence_absent := true;
      state := 'BLOCKED'; passed := false;
      reason := format('gate %s (%s) requires [%s] and the call names none of it. Declared evidence: %s',
                       g.gate_id, g.gate_name, array_to_string(v_missing, ', '),
                       coalesce(g.required_evidence,'(none stated)'));
      return next; return;
    end if;
  end if;

  -- ============================ N06. READ FAILURE IS NOT REFUSAL ============================
  -- Until this block existed the routine carried ZERO exception handlers, so a read error inside a
  -- predicate -- permission denied, a relation renamed, a statement cancelled -- propagated and
  -- aborted the CALLER'S transaction. There was no state, refusal_code or evidence_absent value
  -- that said "the gate could not read", as distinct from the BLOCKED/false it returns when it
  -- read the evidence and judged it. Those are different facts with different remedies: one is
  -- fixed by correcting the evidence, the other by fixing the estate, and a caller that cannot
  -- tell them apart will retry the wrong one forever.
  --
  -- IT FAILS CLOSED. state BLOCKED, passed false, evidence_absent true -- the gate did not see its
  -- evidence, because it could not read it. A gate that answered PASSED on a read error would be
  -- the far worse defect.
  --
  -- THE FAULT HOOK. A read error cannot be provoked from inside an aborted transaction by revoking
  -- a grant -- the routine pins its own search_path and runs as the owner of every relation it
  -- reads, so nothing a caller sets reaches it. app.phase_d_gate_read_fault names one gate whose
  -- read is made to fail, and it is the ONLY way this branch can be reached deliberately. Said
  -- plainly: the fault is injected, not a revoked production grant. What the test proves is that
  -- the DISTINCTION exists and fails closed -- which is the whole of the defect -- and the control
  -- is the identical call with the hook unset.
  begin
    if coalesce(nullif(current_setting('app.phase_d_gate_read_fault', true),''), '') = p_gate_id then
      perform 1 / (case when true then 0 else 1 end);
    end if;

  if p_gate_id = 'GATE-001' then
    -- 4 SEP 2026 (Phase E). This gate read fn_phase_a_baseline_drift(): "the organisation still
    -- matches the frozen Phase A digest". The founder removed the phase freezes on 2 Sep, so a
    -- hard gate with workflow_scope ALL that refused every step the moment a department was
    -- re-carved was a freeze by another name. The property the gate is FOR — the organisation the
    -- step runs in is structurally valid — is measured directly.
    select count(*) into v_n from public.fn_phase_a_organization_violations();
    v_ok := (v_n = 0);
    reason := format('GATE-001: the organisation has %s structural violation(s) (fn_phase_a_organization_violations)', v_n);

  elsif p_gate_id = 'GATE-002' then
    v_ok := public.fn_phase_c_actor_may_own(p_evidence->>'actor_role_id');
    reason := format('GATE-002: actor %s %s', p_evidence->>'actor_role_id',
                     case when v_ok then 'resolves to an active canonical role or permitted overlay'
                          else 'does not resolve' end);

  elsif p_gate_id = 'GATE-003' then
    select count(*) into v_n from public.phase_b_workflow_step x
     where x.step_id = p_evidence->>'step_id' and coalesce(btrim(x.accountable_role_id),'') <> '';
    v_ok := (v_n = 1);
    reason := format('GATE-003: step %s has %s accountable owner(s); exactly one is required',
                     p_evidence->>'step_id', v_n);

  elsif p_gate_id = 'GATE-004' then
    select * into s from public.phase_b_workflow_step where step_id = p_evidence->>'step_id';
    v_ok := public.fn_kernel_reviewer_independent(s.accountable_role_id, p_evidence->>'reviewer_role_id');
    reason := format('GATE-004: %s and %s %s', s.accountable_role_id, p_evidence->>'reviewer_role_id',
                     case when v_ok then 'are different effective identities'
                          else 'resolve to the same effective identity' end);

  elsif p_gate_id = 'GATE-005' then
    -- K01. THIS WAS `v_ok := true`. The gate checked that a string was present and never that it
    -- meant anything, so any caller could have handed it any text and passed the founder boundary.
    -- It now resolves the authority for itself, from the founder command that instructed the run or
    -- from the founder-approved frozen boundary register, and requires the reference the call
    -- presents to be the one that resolves.
    select * into s from public.phase_b_workflow_step where step_id = p_evidence->>'step_id';
    v_auth := public.fn_phase_d_founder_authority(
                nullif(p_evidence->>'run_id','')::bigint, p_evidence->>'step_id');
    v_ok := coalesce((v_auth->>'valid')::boolean, false)
            and v_auth->>'ref' is not null
            and (p_evidence->>'founder_authority_ref') = (v_auth->>'ref');
    reason := format('GATE-005: step declares founder_gate %s; the call names authority %s; the '
                  || 'estate resolves %s (%s) -- %s',
                     left(coalesce(s.founder_gate,'none'),60),
                     coalesce(p_evidence->>'founder_authority_ref','(none)'),
                     coalesce(v_auth->>'ref','(none)'), coalesce(v_auth->>'kind','-'),
                     coalesce(v_auth->>'why','(no reason stated)'));

  elsif p_gate_id = 'GATE-006' then
    if p_evidence->>'from_state' = p_evidence->>'to_state' then
      v_ok := true;
      reason := format('GATE-006: the run stays in %s — this step applies no workflow-state '
                    || 'transition, so there is none to declare. The frozen model holds no '
                    || 'self-transition and 55 of 257 steps declare the state they are already in.',
                       p_evidence->>'from_state');
    else
      select count(*) into v_n from public.phase_b_workflow_transition t
       where t.from_state = p_evidence->>'from_state' and t.to_state = p_evidence->>'to_state';
      v_ok := (v_n > 0);
      reason := format('GATE-006: transition %s -> %s is %s in the frozen model',
                       p_evidence->>'from_state', p_evidence->>'to_state',
                       case when v_ok then 'declared' else 'NOT declared' end);
    end if;

  elsif p_gate_id = 'GATE-007' then
    v_ok := true;
    reason := 'GATE-007: packet, source version and requested action are all present and non-empty';

  elsif p_gate_id = 'GATE-008' then
    -- THE CLOSING STEP IS NOT AN OUTSTANDING PIECE OF WORK. It is necessarily open while it asks,
    -- so counting it made this gate unpassable for all 30 closure steps. Every other open step run
    -- still blocks.
    select count(*) into v_n from public.phase_c_workflow_step_run x
     where x.run_id = (p_evidence->>'run_id')::bigint
       and x.step_run_id is distinct from (p_evidence->>'step_run_id')::bigint
       and x.state not in ('completed','cancelled','failed','superseded','skipped');
    v_ok := (v_n = 0);
    reason := format('GATE-008: %s step run(s) still open on run %s, excluding the closing step run %s itself',
                     v_n, p_evidence->>'run_id', p_evidence->>'step_run_id');

  elsif p_gate_id = 'GATE-009' then
    v_ok := true;
    reason := format('GATE-009: acceptance %s names version %s at hash %s',
                     p_evidence->>'acceptance_ref', p_evidence->>'terms_version',
                     left(p_evidence->>'terms_hash',12));

  elsif p_gate_id = 'GATE-010' then
    v_ok := lower(btrim(p_evidence->>'route_state')) = 'confirmed';
    reason := format('GATE-010: route state %s; only a confirmed route carries dispatch authority',
                     p_evidence->>'route_state');

  elsif p_gate_id = 'GATE-011' then
    select count(*) into v_n from public.inquiries i
     where i.id::text = p_evidence->>'inquiry_id'
       and coalesce(i.status,'') in ('quote_ready','dispatched','quoted','completed');
    v_ok := (v_n = 1);
    reason := format('GATE-011: inquiry %s %s', p_evidence->>'inquiry_id',
                     case when v_ok then 'is quote-ready' else 'is not quote-ready or does not exist' end);

  elsif p_gate_id = 'GATE-012' then
    select count(*) into v_n from public.documents d
     where d.id::text = p_evidence->>'document_id'
       and coalesce(d.status,'') not in ('error','quarantined','rejected')
       and coalesce(d.error,'') = '';
    v_ok := (v_n = 1);
    reason := format('GATE-012: document %s %s', p_evidence->>'document_id',
                     case when v_ok then 'is supported, readable and carries no error'
                          else 'is missing, errored or quarantined' end);

  elsif p_gate_id = 'GATE-013' then
    -- O04/O07. THIS NEVER DEREFERENCED safe_package_ref. The value was required present by the
    -- generic evidence_keys loop and then used only inside format() for the reason string, so the
    -- gate could be satisfied by any package at all provided the approver was not the author.
    -- It now consults the same file-set verdict BR-012 does.
    select pr.dispatchable, pr.refusal_code, pr.reason into v_g13_ok, v_g13_code, v_g13_why
      from public.fn_phase_d_package_revisions_dispatchable(p_evidence->>'safe_package_ref') pr;
    v_ok := public.fn_kernel_reviewer_independent(
              coalesce(p_evidence->>'actor_role_id', 'unknown'),
              p_evidence->>'safe_package_approved_by')
            and v_g13_ok;
    if not v_g13_ok then refusal_code := v_g13_code; end if;
    reason := format('GATE-013: package %s approved by %s; independence %s; file set %s',
                     p_evidence->>'safe_package_ref', p_evidence->>'safe_package_approved_by',
                     case when public.fn_kernel_reviewer_independent(
                            coalesce(p_evidence->>'actor_role_id','unknown'),
                            p_evidence->>'safe_package_approved_by')
                          then 'holds' else 'FAILS — the approver is the author' end,
                     coalesce(v_g13_why,'(no verdict)'));

  elsif p_gate_id = 'GATE-014' then
    select count(*) into v_n from public.leads l
     where l.id::text = p_evidence->>'supplier_id'
       and coalesce(l.approval_status,'') = 'approved' and coalesce(l.verified,false);
    v_ok := (v_n = 1);
    reason := format('GATE-014: supplier %s %s', p_evidence->>'supplier_id',
                     case when v_ok then 'is currently approved and verified'
                          else 'is not an approved, verified supplier' end);

  elsif p_gate_id = 'GATE-015' then
    select count(*) into v_n from public.inquiry_matches m
     where m.inquiry_id::text = p_evidence->>'inquiry_id'
       and m.supplier_id::text = p_evidence->>'supplier_id';
    v_ok := (v_n = 0);
    reason := format('GATE-015: %s existing assignment(s) for that supplier and inquiry; a dispatch would be a duplicate', v_n);

  elsif p_gate_id = 'GATE-016' then
    select count(*) into v_n from public.email_suppressions e
     where lower(e.email) = lower(p_evidence->>'notify_email');
    v_ok := (v_n = 0)
            and lower(coalesce(p_evidence->>'assignment_result','')) in ('delivered','accepted','sent');
    reason := format('GATE-016: %s is %s; assignment result %s',
                     p_evidence->>'notify_email',
                     case when v_n = 0 then 'not suppressed' else 'SUPPRESSED' end,
                     p_evidence->>'assignment_result');

  elsif p_gate_id = 'GATE-017' then
    select count(*) into v_n from public.quotes q
     where q.id::text = p_evidence->>'quote_id'
       and q.quote_amount is not null and coalesce(btrim(q.status),'') <> '';
    v_ok := (v_n = 1);
    reason := format('GATE-017: quote %s %s', p_evidence->>'quote_id',
                     case when v_ok then 'carries a stated amount and status'
                          else 'is missing mandatory commercial fields' end);

  elsif p_gate_id = 'GATE-018' then
    -- O06/O07. The byte-identical ownership count BR-019 carried, with the same defect: its
    -- refusal_code is gate018_comparison_not_publishable and it never read publishability.
    -- Changed with the rule and not after it -- fixing only one leaves the gate green on the same
    -- unpublished comparison, which is how a pair of predicates disagrees in silence.
    select cv.visible, cv.refusal_code, cv.reason into v_g13_ok, v_g13_code, v_g13_why
      from public.fn_phase_d_comparison_visible(
             p_evidence->>'comparison_id', p_evidence->>'caller_customer_id',
             coalesce(nullif(btrim(p_evidence->>'caller_kind'),''), 'customer')) cv;
    v_ok := v_g13_ok;
    if not v_ok then refusal_code := v_g13_code; end if;
    reason := 'GATE-018: ' || coalesce(v_g13_why, 'no verdict returned by fn_phase_d_comparison_visible');

  elsif p_gate_id = 'GATE-019' then
    select rp.permitted, rp.reason into v_ok, v_txt
      from public.fn_phase_d_reveal_permitted(p_evidence->>'transaction_id') rp;
    reason := coalesce(v_txt, 'GATE-019: no verdict returned by the reveal decision');

  elsif p_gate_id = 'GATE-020' then
    select count(*) into v_n from public.refunds rf
     where rf.id::text = p_evidence->>'refund_id'
       and coalesce(btrim(rf.decided_by),'') <> '' and rf.decided_at is not null;
    v_ok := (v_n = 1);
    reason := format('GATE-020: refund %s %s, financial action key %s',
                     p_evidence->>'refund_id',
                     case when v_ok then 'carries a recorded decision and decider'
                          else 'has no recorded founder decision' end,
                     p_evidence->>'financial_action_key');

  elsif p_gate_id = 'GATE-021' then
    v_ok := public.fn_kernel_reviewer_independent(
              coalesce(p_evidence->>'actor_role_id','unknown'), p_evidence->>'reviewer_role_id');
    reason := format('GATE-021: artifact %s at digest %s reviewed by %s; independence %s',
                     p_evidence->>'artifact_ref', left(p_evidence->>'artifact_sha256',12),
                     p_evidence->>'reviewer_role_id',
                     case when v_ok then 'holds' else 'FAILS' end);

  elsif p_gate_id = 'GATE-031' then
    v_ok := not coalesce((public.fn_kernel_paid_provider_gate('openai/gpt-4o-mini')->>'allowed')::boolean, true);
    select count(*) into v_n from public.llm_attempt where created_at > now() - interval '24 hours';
    v_ok := v_ok and (v_n = 0);
    reason := format('GATE-031: paid-provider gate %s; %s llm_attempt row(s) in 24h',
                     case when v_ok then 'refuses every route' else 'ALLOWED a route' end, v_n);

  elsif p_gate_id = 'GATE-032' then
    -- Founder lifted the selective automation hold on 2 Sep 2026 ("lift all previous limits or frozen
    -- gates; the only thing that remains blocked is OpenRouter"), and on 3 Sep 2026 asked for these
    -- gates to be fixed permanently so they stop blocking authorized activation. The ceiling WAS the
    -- stand-down hold; it is now purely a runaway-explosion guard. It is sized ABOVE the whole authorized
    -- cron universe rather than at an arbitrary low number: the company DEFINES 221 cron jobs and the
    -- founder has authorized activating them, so any count up to that whole set is legitimate, not a
    -- runaway. The guard therefore fires only when active crons exceed the full defined set by a clear
    -- margin (a bug spawning brand-new jobs beyond the ~221 known) — 240 — which is what "runaway"
    -- actually means here. This stops the gate reddening on every legitimate cron the activation turns on
    -- (the recurring failure) while still catching an uncontrolled explosion. Recorded in
    -- public.company_stand_down (full resume, 2 Sep 2026).
    select count(*) into v_n from cron.job where active;
    v_ok := (v_n <= 240);
    reason := format('GATE-032: %s active cron job(s) of 221 defined; automation hold lifted by founder 2 Sep 2026, runaway guard 240 (above the full authorized cron set)', v_n);

  elsif p_gate_id in ('GATE-027','GATE-028') then
    -- O03/O07. THE LEGAL AND TAX CURRENCY LEG, AND WHAT IT DELIBERATELY DOES NOT DO.
    --
    -- GATE-027 binds 10 W27 steps and GATE-028 binds 9 W28 steps. Making a source reference a
    -- REQUIRED evidence key would block all 19 on every drive, because fn_phase_d_step_context
    -- resolves no such key -- so nineteen steps would stop for a control that is about the two
    -- steps whose frozen acceptance criteria actually demand it. That is the "tightening a guard
    -- reddens its own probes" shape, and the trade is not worth making here: the HARD boundary for
    -- this control is a10_phase_d_legal_assertion_source on public.phase_d_legal_assertion, where
    -- naming a source is mandatory and a stale one is refused outright.
    --
    -- What this leg does is judge a source WHEN ONE IS NAMED, which is strictly more than the
    -- v_ok := true it replaces, and it says so in the reason either way rather than implying it.
    v_g13_why := btrim(coalesce(p_evidence->>(case when p_gate_id = 'GATE-027'
                                                   then 'tax_source_ref' else 'legal_source_ref' end), ''));
    if v_g13_why <> '' then
      select ls.usable, ls.refusal_code, ls.reason into v_g13_ok, v_g13_code, v_g13_why
        from public.fn_phase_d_legal_source_current(v_g13_why, true) ls;
      v_ok := v_g13_ok;
      if not v_ok then refusal_code := v_g13_code; end if;
      reason := format('%s (%s): declared evidence present [%s], and the %s it cites -- %s',
                       g.gate_id, g.gate_name, array_to_string(c.evidence_keys, ', '),
                       case when p_gate_id = 'GATE-027' then 'tax authority' else 'legal source' end,
                       coalesce(v_g13_why,'(no verdict)'));
    else
      v_ok := true;
      reason := format('%s (%s): all declared evidence is present and non-empty [%s]. No %s was '
                    || 'cited, so no currency test was performed -- said rather than implied. A '
                    || 'legal or tax assertion itself is refused at public.phase_d_legal_assertion '
                    || 'unless it cites a current, authoritative, unsuperseded source.',
                       g.gate_id, g.gate_name, array_to_string(c.evidence_keys, ', '),
                       case when p_gate_id = 'GATE-027' then 'tax_source_ref' else 'legal_source_ref' end);
    end if;

  elsif p_gate_id in ('GATE-022','GATE-023','GATE-024','GATE-025','GATE-026',
                      'GATE-029','GATE-030') then
    v_ok := true;
    reason := format('%s (%s): all declared evidence is present and non-empty [%s]. '
                  || 'The keys are checked; the CONTENT behind them is not yet verifiable from '
                  || 'this database, which is stated rather than implied.',
                     g.gate_id, g.gate_name, array_to_string(c.evidence_keys, ', '));

  else
    state := 'NOT_IMPLEMENTED'; passed := false;
    reason := format('gate %s has no predicate in fn_phase_d_gate_evaluate — blocked', p_gate_id);
    return next; return;
  end if;

  exception when others then
    -- Anything the predicate chain could not READ. Not "anything that went wrong": a predicate
    -- that judges evidence and returns false never arrives here, because returning false is not
    -- an exception.
    state := 'BLOCKED'; passed := false; evidence_absent := true;
    refusal_code := 'gate_read_failed';
    reason := format('gate %s could not READ what it needed to judge: %s (%s). This is not a '
                  || 'refusal -- the gate reached no verdict on the evidence, and a caller must '
                  || 'fix the estate rather than the evidence.',
                     p_gate_id, left(SQLERRM, 160), SQLSTATE);
    return next; return;
  end;

  state := case when v_ok then 'PASSED' else 'BLOCKED' end;
  passed := coalesce(v_ok, false);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_handler_execute(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_review jsonb;   -- F34: the recorded canonical internal review for this step run
  b   public.phase_d_handler_binding%rowtype;
  s   public.phase_b_workflow_step%rowtype;
  sr  public.phase_c_workflow_step_run%rowtype;
  ec  public.phase_d_step_effect%rowtype;
  v_step_run bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_actor    text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_idem     text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_inputs   jsonb  := coalesce(p_input->'inputs','{}'::jsonb);
  v_ctx      text   := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),'production'));
  v_ok       boolean; v_reason text; v_missing text[];
  v_rule     record; v_rule_ok boolean; v_rule_type text; v_rule_reason text;
  v_applies  boolean; v_why text; v_enforced boolean; v_refusal text; v_state text;
  v_ev_absent boolean := false;   -- E19
  v_refused  jsonb := '[]'::jsonb;
  v_skipped  jsonb := '[]'::jsonb;
  v_gate     record; v_gstate text; v_gpassed boolean; v_gtype text;
  v_greason  text; v_grefusal text; v_gapplies boolean; v_gwhy text;
  v_gates    jsonb := '[]'::jsonb;
  v_gblocked jsonb := '[]'::jsonb;
  v_evaluated jsonb := '[]'::jsonb;
  v_output   jsonb;
  v_assert   jsonb;
  v_result   jsonb;
  v_effect   jsonb;
  v_cap      jsonb;   -- F05: the accepted capability result for this step run, or null
  v_cap_req  jsonb;   -- F05: the capability request this handler opened
begin
  -- ---- 0. the call itself ------------------------------------------------------------------
  if v_step_run is null or v_actor is null or v_idem is null then
    raise exception 'fn_phase_d_handler_execute: step_run_id, actor_role_id and idempotency_key are all required (got %, %, %) (pd_input_schema_invalid)',
      coalesce(v_step_run::text,'(null)'), coalesce(v_actor,'(null)'), coalesce(v_idem,'(null)')
      using errcode = '22023';
  end if;
  if v_ctx not in ('production','test') then
    raise exception 'fn_phase_d_handler_execute: execution_context must be production or test, got %',
      v_ctx using errcode = '22023';
  end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if not found then
    raise exception 'fn_phase_d_handler_execute: no step run % (pd_step_state_invalid)', v_step_run
      using errcode = '23503';
  end if;

  -- ---- 0b. THE BRANCH PROBE'S HOLD --------------------------------------------------------
  -- Section 1 of the founder's ruling asks for BRANCH coverage of all 257 frozen steps. The frozen
  -- model is a linear chain: next_step_if_pass names the next step (or WORKFLOW_COMPLETE), and
  -- next_step_if_fail names one of three symbolic outcomes and never a step. So a step's fail edge
  -- is exercised by an ACTOR reporting failure on it, which requires the step to be OPEN.
  --
  -- MEASURED 23 Aug 2026: 249 of 257 steps are completed by this handler in the same statement the
  -- kernel opens them, so they are never open and no actor can ever take them. W18 is the extreme
  -- case -- all seven steps EXECUTED unaided, the run reaching completed inside
  -- fn_kernel_workflow_start, nothing left to fail or cancel. A handler that succeeds is the
  -- system working; it also means the fail edge of the frozen model is unreachable through the
  -- actor door, and an unexercised branch cannot be reported as covered.
  --
  -- This is the hold, and every part of it is deliberately narrow:
  --   * it acts only inside an open Phase D fixture context, which fn_phase_d_test_context_open
  --     grants for one operation inside one transaction that ends in raise exception;
  --   * it names ONE step, set by the caller at transaction level, and never a workflow or a class;
  --   * it refuses with its own code, pd_handler_held_for_branch_probe, which appears in
  --     phase_d_dispatch.refusal_code -- so no reader, and no deliverable, can mistake a held step
  --     for a handler that could not do its work;
  --   * it changes nothing else. The kernel then does exactly what it does for any refused
  --     dispatch: the step stays open and owned.
  --
  -- What the fail-branch case then proves is the KERNEL's edge for that step -- outcome fail moves
  -- the step to failed and the run to the step's declared failure_workflow_state, with no partial
  -- effect and no residue -- and NOT that the handler could have failed. Those are different
  -- claims and the coverage matrix records which one it has, per step.
  if nullif(btrim(coalesce(current_setting('app.phase_d_hold_step', true), '')), '') = sr.step_id
     and public.fn_phase_d_fixture_context() is not null then
    raise exception 'fn_phase_d_handler_execute: step % is held open by an audited Phase D branch probe; the handler declined so an actor can take the step (pd_handler_held_for_branch_probe)',
      sr.step_id using errcode = '23505';
  end if;

  select * into b from public.phase_d_handler_binding where step_id = sr.step_id;
  if not found then
    raise exception 'fn_phase_d_handler_execute: step % has no Phase D handler binding — fail closed. Every one of the 257 frozen steps must carry exactly one. (pd_input_schema_invalid)',
      sr.step_id using errcode = '23503';
  end if;
  select * into s from public.phase_b_workflow_step where step_id = sr.step_id;

  select * into ec from public.phase_d_step_effect where step_id = sr.step_id;
  if not found then
    raise exception 'fn_phase_d_handler_execute: step % has no declared effect contract. A handler with no declared effect is the schema-only handler this phase exists to remove. (pd_effect_undeclared)',
      sr.step_id using errcode = '23503';
  end if;

  -- ---- 1. TYPED INPUT ----------------------------------------------------------------------
  select valid, reason, missing into v_ok, v_reason, v_missing
    from public.fn_phase_d_schema_validate(b.input_schema_id, v_inputs);
  if not v_ok then
    raise exception 'fn_phase_d_handler_execute: step % input rejected: % (pd_input_schema_invalid)',
      sr.step_id, v_reason using errcode = '22023';
  end if;

  -- ---- 2. RULES IN SCOPE -------------------------------------------------------------------
  -- SCOPE IS NOT APPLICABILITY. The frozen registry scopes rules by WORKFLOW, so BR-002 is in
  -- scope for all 257 steps while only 28 of them name an independent reviewer. Asking
  -- fn_kernel_reviewer_independent about a NULL reviewer returns false, which refused an intake
  -- step for a creator/reviewer collision that could not exist. fn_phase_d_rule_applies decides
  -- both, and records the reason either way.
  --
  -- Refusals are collected rather than short-circuited: a caller told only the first thing wrong
  -- fixes one thing and comes back.
  for v_rule in select unnest(b.rule_ids) rid loop
    select applies, why into v_applies, v_why
      from public.fn_phase_d_rule_applies(v_rule.rid, sr.step_id);
    if not coalesce(v_applies,false) then
      v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
        'rule_id', v_rule.rid, 'applies', false, 'why', v_why));
      continue;
    end if;

    select state, ok, rule_type, enforced, reason, refusal_code, coalesce(evidence_absent,false)
      into v_state, v_rule_ok, v_rule_type, v_enforced, v_rule_reason, v_refusal, v_ev_absent
      from public.fn_phase_d_rule_check(v_rule.rid,
        jsonb_build_object(
          'accountable_role_id', sr.accountable_role_id,
          'reviewer_role_id',    nullif(b.independent_reviewer_role_id,''),
          'actor_role_id',       v_actor,
          'step_id',             sr.step_id,
          'workflow_id',         b.workflow_id,
          'run_id',              sr.run_id,
          'founder_gate',        b.founder_gate,
          'execution_context',   v_ctx)
        || coalesce(p_input->'context','{}'::jsonb));

    v_evaluated := v_evaluated || jsonb_build_array(jsonb_build_object(
      'rule_id', v_rule.rid, 'state', v_state, 'rule_type', v_rule_type, 'ok', v_rule_ok,
      'enforced', v_enforced, 'reason', v_rule_reason));

    if v_rule_type = 'hard' and v_state in ('ENFORCED_FAIL','NOT_IMPLEMENTED') then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object(
        'rule_id', v_rule.rid, 'state', v_state, 'rule_type', v_rule_type,
        'refusal_code', v_refusal, 'reason', v_rule_reason,
        'evidence_absent', v_ev_absent));
    end if;
  end loop;
  if jsonb_array_length(v_refused) > 0 then
    -- E19. TWO DIFFERENT EVENTS DESERVE TWO DIFFERENT NAMES. If EVERY refusal on this step is an
    -- absence of evidence, the code says so and fn_phase_d_dispatch_step records
    -- REFUSED_EVIDENCE_ABSENT. If even one rule read its evidence and judged it against policy, the
    -- whole refusal is pd_rule_refused: a genuine violation is not diluted by the absences beside
    -- it. Both refuse, and neither is a pass.
    if not exists (select 1 from jsonb_array_elements(v_refused) x
                    where not coalesce((x->>'evidence_absent')::boolean, false)) then
      raise exception 'fn_phase_d_handler_execute: step % refused by % hard business rule(s), every one of them for evidence the call did not name rather than for a policy the call broke: % (pd_evidence_absent)',
        sr.step_id, jsonb_array_length(v_refused), v_refused::text using errcode = '23514';
    end if;
    raise exception 'fn_phase_d_handler_execute: step % refused by % hard business rule(s): % (pd_rule_refused)',
      sr.step_id, jsonb_array_length(v_refused), v_refused::text using errcode = '23514';
  end if;

  -- ---- 2b. GATES IN SCOPE, EACH AGAINST ITS OWN DECLARED EVIDENCE --------------------------
  for v_gate in select unnest(b.gate_ids) gid loop
    select ga.applies, ga.why into v_gapplies, v_gwhy
      from public.fn_phase_d_gate_applies(v_gate.gid, sr.step_id) ga;
    if not coalesce(v_gapplies,false) then
      v_gates := v_gates || jsonb_build_array(jsonb_build_object(
        'gate_id', v_gate.gid, 'state', 'NOT_APPLICABLE', 'why', v_gwhy));
      continue;
    end if;
    select ge.state, ge.passed, ge.gate_type, ge.reason, ge.refusal_code, coalesce(ge.evidence_absent,false)
      into v_gstate, v_gpassed, v_gtype, v_greason, v_grefusal, v_ev_absent
      from public.fn_phase_d_gate_evaluate(v_gate.gid,
        jsonb_build_object('step_id', sr.step_id, 'run_id', sr.run_id,
                           'step_run_id', v_step_run,
                           'step_run_id', v_step_run,
                           'actor_role_id', v_actor,
                           'reviewer_role_id', nullif(b.independent_reviewer_role_id,''))
        || coalesce(p_input->'gate_evidence','{}'::jsonb)) ge;

    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'gate_id', v_gate.gid, 'state', v_gstate, 'gate_type', v_gtype,
      'passed', v_gpassed, 'reason', v_greason));

    if v_gtype = 'hard' and v_gstate in ('BLOCKED','NOT_IMPLEMENTED') then
      v_gblocked := v_gblocked || jsonb_build_array(jsonb_build_object(
        'gate_id', v_gate.gid, 'state', v_gstate,
        'refusal_code', v_grefusal, 'reason', v_greason,
        'evidence_absent', v_ev_absent));
    end if;
  end loop;
  if jsonb_array_length(v_gblocked) > 0 then
    if not exists (select 1 from jsonb_array_elements(v_gblocked) x
                    where not coalesce((x->>'evidence_absent')::boolean, false)) then
      raise exception 'fn_phase_d_handler_execute: step % blocked by % hard gate(s), every one of them for evidence the call did not name rather than for a condition the gate judged and rejected: % (pd_evidence_absent)',
        sr.step_id, jsonb_array_length(v_gblocked), v_gblocked::text using errcode = '23514';
    end if;
    raise exception 'fn_phase_d_handler_execute: step % refused by % hard gate(s): % (pd_gate_refused)',
      sr.step_id, jsonb_array_length(v_gblocked), v_gblocked::text using errcode = '23514';
  end if;

  -- ---- 3. CAPABILITY BOUNDARY, FAIL CLOSED, AND NO LONGER A MODE STRING --------------------
  -- F05. This read `if b.capability_dependency <> 'NONE' and v_ctx <> 'test'`, so the literal
  -- 'test' arriving in one field turned twenty-one fail-closed business boundaries off at once.
  -- The founder prohibited exactly that shape on 21 Aug 2026. The mode is no longer consulted:
  -- the handler asks whether an ACCEPTED capability result exists for this step run, and the only
  -- way one exists is through fn_phase_d_capability_result_accept, which validates it against the
  -- step's own output contract and which refuses a fixture result outright unless a Phase D
  -- fixture context verifies (F01).
  --
  -- In production there is no fixture context and no provider, so there is no result, so this
  -- raises -- the same refusal, at the same point, for a reason that is now a read rather than a
  -- comparison against a caller-supplied string.
  if b.capability_dependency <> 'NONE' then
    -- The request is opened first and in every context: it is the row a Phase E provider answers,
    -- and a step that never asked cannot be said to have been refused.
    v_cap_req := public.fn_phase_d_capability_request_open(jsonb_build_object(
      'step_run_id', v_step_run, 'requested_by', v_actor));
    v_cap := public.fn_phase_d_capability_answer(v_step_run);
    if v_cap is null then
      raise exception 'fn_phase_d_handler_execute: step % depends on capability % (matched on the frozen required_action at: %) and capability request % carries no accepted result. Paid inference is held until Phase E; a Phase D fixture result must be submitted through fn_phase_d_capability_result_accept, which requires a verified Phase D fixture context. Refusing rather than completing a business step from nothing. (pd_capability_unavailable)',
        sr.step_id, b.capability_dependency, coalesce(nullif(b.capability_evidence,''),'(none)'),
        coalesce(v_cap_req->>'request_id','(none)')
        using errcode = '23514';
    end if;
  end if;

  -- ---- 4. PROVIDER BOUNDARY, FAIL CLOSED ---------------------------------------------------
  -- Same correction, same reason. A provider dependency is refused whatever the execution context
  -- says, because the hold is on the provider and not on the caller's description of itself.
  if b.provider_dependency <> 'NONE' then
    raise exception 'fn_phase_d_handler_execute: step % depends on external provider % which is disabled for the whole of Phase D. No execution context lifts this. (pd_provider_disabled)',
      sr.step_id, b.provider_dependency using errcode = '23514';
  end if;

  -- ---- 4b. H01. THE VERDICT THE KERNEL WILL DEMAND, ASKED FOR HERE FIRST ----------------------
  -- fn_kernel_step_complete 3g refuses a pass on a step whose frozen row names an independent
  -- reviewer unless an approved, independent verdict from that role is sealed on the task. The
  -- handler used to discover that only after producing its effect, and the refusal came out of the
  -- kernel as k3_reviewer_verdict_missing. The same predicate is asked here, before anything is
  -- built, and the refusal is the one the driver answers through fn_kernel_review_decide. Nothing
  -- about the kernel check changes; it still decides at 3g.
  if coalesce(btrim(s.independent_reviewer_role_id),'') <> ''
     and not exists (
       select 1
         from public.phase_c_task t
         join public.phase_c_trace tr on tr.task_id = t.task_id
        where t.run_id = sr.run_id and t.step_id = sr.step_id
          and tr.trace_policy_id = 'TRACE-ROLE-ACTION'
          and tr.evidence_refs @> '[{"review_decision":"approved"}]'::jsonb
          and public.fn_kernel_reviewer_independent(sr.accountable_role_id, tr.reviewer_role_id)
          and (select role_id from public.fn_phase_c_resolve_actor(tr.reviewer_role_id))
              = (select role_id from public.fn_phase_c_resolve_actor(s.independent_reviewer_role_id)))
  then
    raise exception 'fn_phase_d_handler_execute: step % names % as its independent reviewer and no approved, independent verdict from that role has been recorded on its task. fn_kernel_review_decide seals the verdict and stamps the reviewer; until it has run the kernel will refuse the completion, so the handler refuses here first. (pd_review_not_recorded)',
      sr.step_id, s.independent_reviewer_role_id using errcode = '23514';
  end if;

  -- ---- 5. THE FAMILY HANDLER ---------------------------------------------------------------
  -- F34. The recorded canonical review for this step run, read once.
  v_review := public.fn_phase_d_recorded_review(v_step_run);

  v_assert := (
    select coalesce(jsonb_agg(jsonb_build_object(
             'criterion', btrim(c), 'satisfied_by',
             'named inputs [' || array_to_string(
               (select array_agg(k order by k) from jsonb_object_keys(v_inputs) k), ', ') || ']')
             order by ord), '[]'::jsonb)
      from unnest(string_to_array(coalesce(s.acceptance_criteria,''), ';')) with ordinality u(c, ord)
     where btrim(c) <> '');

  v_output := jsonb_build_object(
    'status', 'completed',
    'output', format('%s — %s', s.step_name, coalesce(s.required_output,'output produced')),
    'acceptance_assertions', case when jsonb_array_length(v_assert) = 0
                                  then jsonb_build_array(jsonb_build_object(
                                         'criterion', coalesce(s.acceptance_criteria,'(none declared)'),
                                         'satisfied_by','named inputs'))
                                  else v_assert end,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
       'step_id', sr.step_id, 'step_run_id', v_step_run, 'run_id', sr.run_id,
       'handler_id', b.handler_id, 'handler_version', b.handler_version,
       'input_schema_id', b.input_schema_id, 'output_schema_id', b.output_schema_id,
       'inputs_named', v_inputs, 'execution_context', v_ctx)))
    || case when v_cap is null then '{}'::jsonb
            else jsonb_build_object('capability_result', jsonb_build_object(
              'request_id',    v_cap->'request_id',
              'result_id',     v_cap->'result_id',
              'provider_mode', v_cap->>'provider_mode',
              'fixture_id',    v_cap->>'fixture_id',
              'fixture_version', v_cap->'fixture_version',
              'fixture_hash',  v_cap->>'fixture_hash',
              'payload_digest',v_cap->>'payload_digest',
              'evidence',      v_cap->>'evidence')) end
    || case b.handler_class
         when 'INTAKE_HANDLER' then jsonb_build_object(
           'source_ref', coalesce(p_input->>'source_ref', 'step_run:' || v_step_run),
           'captured_verbatim', v_inputs)
         when 'ANALYSIS_HANDLER' then jsonb_build_object(
           'method', 'deterministic reconciliation of the named inputs against the frozen step contract',
           'inputs_used', v_inputs,
           'findings', jsonb_build_array(coalesce(s.required_action,'')),
           'assumptions', jsonb_build_array(
             'only the inputs named in this call were used; no external source was consulted'))
         when 'EXECUTION_HANDLER' then jsonb_build_object(
           -- P01. A FIELD NAMED state_change THAT CARRIED A SENTENCE.
           -- This was coalesce(s.required_output,'') — the frozen step's PROSE description of the
           -- artefact it produces ("Active customer account."), not a state. Gate 5 of the final
           -- independent acceptance audit measured 58 output schemas typing it as a bare string
           -- with no domain, and no domain could be declared over a sentence.
           --
           -- The value now states the post-condition the effect is ABOUT to record, from the same
           -- two sources fn_phase_d_effect_produce already reads twelve lines below — the caller's
           -- stated state, then the committed catalogue — and falls back to the object's own
           -- declared initial_state rather than to fn_phase_d_object_write's hard-coded 'open'.
           -- Every arm is inside public.phase_d_object_state_contract.allowed_states by
           -- construction, which is the domain the output contract now declares, so a correct run
           -- can never be refused by the new constraint. A caller who supplies an out-of-domain
           -- effect_state is refused HERE, by the step's own contract, instead of sixteen lines
           -- later by z40_phase_d_object_record_contract.
           --
           -- The nine steps whose frozen effect declares that no object state moves say so with
           -- the explicit sentinel instead of borrowing a state they never write:
           -- 7 EXTERNAL_EFFECT_INTENT ("intent recorded as mock; no provider state moves and
           -- nothing is sent") and 2 CAPABILITY_REQUEST ("no state moves: the capability is
           -- unavailable in Phase D and the step refuses"). fn_phase_d_effect_produce's branches
           -- for those two types write no phase_d_object_record at all.
           'state_change', case
             when ec.expected_effect_type in ('EXTERNAL_EFFECT_INTENT','CAPABILITY_REQUEST')
               then 'NO_STATE_CHANGE'
             else coalesce(
                    nullif(btrim(coalesce(p_input->>'effect_state','')), ''),
                    (select fi.value #>> '{}'
                       from public.fn_phase_d_fixture_input(v_step_run,'EFFECT_PAYLOAD','state') fi),
                    (select c.initial_state from public.phase_d_object_state_contract c
                      where c.object_id = coalesce(ec.effect_object_id,
                              (select primary_object from public.phase_b_workflow w
                                where w.workflow_id = b.workflow_id))))
           end,
           'target_object', coalesce(ec.effect_object_id,
             (select primary_object from public.phase_b_workflow w
               where w.workflow_id = b.workflow_id), b.workflow_id),
           'authorization_ref', format('accountable owner %s on step %s',
                                       sr.accountable_role_id, sr.step_id))
         -- F34. A REVIEW READ OFF THE CALLER'S OWN STRING.
         -- Both keys came from p_input, so the kernel dispatch -- which passes neither -- produced
         -- an output naming no reviewer, and BR-002 then refused the step for "names (none) as
         -- reviewer". That refusal was true and it was about this harness, not about the business.
         -- The founder's section 4 names CANONICAL_INTERNAL_REVIEW as an allowed execution input
         -- when it travels through its real interface, and that interface is fn_kernel_review_decide:
         -- it checks independence itself, seals a TRACE-ROLE-ACTION carrying the decision, and
         -- stamps phase_c_task.reviewer_role_id. Both values are therefore READ FROM THOSE ROWS.
         -- A caller can no longer assert either one.
         when 'REVIEW_HANDLER' then jsonb_strip_nulls(jsonb_build_object(
           'verdict', v_review->'verdict',
           'reviewer_role_id', v_review->'reviewer_role_id'))
         when 'DECISION_HANDLER' then jsonb_strip_nulls(jsonb_build_object(
           -- P01. A FIELD NAMED decision THAT CARRIED A SENTENCE.
           -- This was coalesce(s.required_output,'') — the same prose the 'output' key twelve
           -- lines above already carries in full as format('%s — %s', step_name, required_output).
           -- So 'decision' was a duplicate of 'output' with the step name stripped, and
           -- schema_output_w17_s06 accepted decision = NOT_A_DECISION because there was no decision
           -- in the field for a domain to be about.
           --
           -- Q02. AND FOR EIGHTEEN STEPS THE ANSWER WAS THAT THE KEY SHOULD NOT BE THERE AT ALL.
           -- PBCR-002 class B: eighteen steps whose frozen required_action names an act with a
           -- single artefact outcome — "Define affordable department resource envelopes…",
           -- "Prioritize gaps by customer impact…" — so `decision` carried no choice and was a
           -- duplicate of `output`. Seventeen of the eighteen no longer declare the key; W16-S04
           -- declares it BOUND to public.phase_d_object_state_contract.payment_transaction, whose
           -- six states are the vocabulary its frozen action names ("only an ALLOWED
           -- transaction-state transition").
           --
           -- SO THE KEY IS EMITTED ONLY WHERE THE CONTRACT DECLARES IT. These output schemas are
           -- closed (additional_properties = false), so emitting a key the schema no longer names
           -- would make fn_phase_d_schema_validate refuse every run of those seventeen steps. The
           -- condition reads the contract rather than a list typed here, so when the founder
           -- decides PBCR-002 for the fifteen class-C steps the arm follows the schema without a
           -- second edit — and a step whose schema regains the key regains the value.
           --
           -- Where the key IS declared the value comes from the caller, then from the committed
           -- catalogue, and only then falls back to the frozen prose. The fallback is narrow: the
           -- fifteen class-C steps have NO decision vocabulary anywhere in the frozen estate and
           -- inventing one for them is what section 4 of the founder's instruction forbids. They
           -- declare no domain and are raised as PBCR-002; a step with no declared domain cannot be
           -- refused by one, so the prose fallback keeps them working unchanged until he decides.
           --
           -- The 3 that DO have an enforcing authority declare it, and for them the catalogue
           -- answers so the prose never reaches the field:
           --   W17-S06  approved | rejected                  CHECK phase_c_refund_decision_ck and
           --                                                  fn_kernel_refund_decision_record
           --   W08-S06  approved | rejected | changes_requested
           --                                                  CHECK phase_d_file_revision_verdict_ck
           --   W16-S04  open | pending | settled | refunded | failed | reconciled
           --                                                  phase_d_object_state_contract, the
           --                                                  authority z40_phase_d_object_record_contract enforces
           'decision', case when exists (
                  select 1 from public.phase_d_handler_schema hs
                   where hs.step_id = sr.step_id and hs.schema_kind = 'output'
                     and 'decision' = any (hs.required_keys || coalesce(hs.optional_keys, '{}'::text[])))
             then to_jsonb(coalesce(
                    nullif(btrim(coalesce(p_input->>'decision','')), ''),
                    (select fi.value #>> '{}'
                       from public.fn_phase_d_fixture_input(v_step_run,'EFFECT_PAYLOAD','decision') fi),
                    coalesce(s.required_output,'')))
             end,
           'rationale', to_jsonb(coalesce(s.acceptance_criteria,'')),
           'authority_ref', to_jsonb(format('founder_gate=%s; accountable owner %s',
                                   b.founder_gate, sr.accountable_role_id))))
         when 'HANDOFF_HANDLER' then jsonb_build_object(
           'packet', v_inputs,
           -- P04. THE FALLBACK WAS A RUNTIME TOKEN, NOT A FROZEN ROLE.
           -- 17 of the 25 handoff steps resolve from public.phase_b_handoff, which is frozen and
           -- always canonical. The other 8 — W04-S06, W07-S07, W08-S05, W08-S07, W09-S08, W12-S07,
           -- W14-S06, W25-S07 — have no handoff row and fell back to sr.accountable_role_id, where
           -- sr is public.phase_c_workflow_step_run: a RUNTIME row whose accountable_role_id
           -- fn_kernel_open_step takes from the caller as owner_role_id, validates only with
           -- fn_phase_c_actor_may_own, and stores VERBATIM. That predicate returns true for an
           -- ALIAS — measured true for 'cs_onboarding', 'moderation_specialist' and
           -- 'Content Moderation Reviewer' — and public.org_role_alias holds 324 aliases over 171
           -- roles, with 20 across the 7 roles behind those 8 steps. phase_c_workflow_step_run
           -- carries no foreign key on the column either.
           --
           -- So P01's per-step domain would have refused a run opened under any registered alias of
           -- the very role it names: fn_phase_d_schema_validate('schema_output_w04_s06', …) returns
           -- "receiving_role_id='cs_onboarding' is not one of [customer_onboarding]". That is a
           -- guard firing when the system works, and the fix is to canonicalise the value rather
           -- than to widen the domain to 324 spellings or drop it.
           --
           -- fn_phase_c_resolve_actor is the estate's canonical resolver and the kernel's own
           -- progression path already uses it; this makes the handler agree with the kernel.
           'receiving_role_id', coalesce(
              (select h.receiving_role_id from public.phase_b_handoff h
                where h.from_step_id = sr.step_id limit 1),
              (select ra.role_id from public.fn_phase_c_resolve_actor(sr.accountable_role_id) ra),
              sr.accountable_role_id),
           'acceptance_criteria', coalesce(s.acceptance_criteria,''))
         -- F34. THE FOUR VALUES CAME FROM p_input, AND NOTHING PASSES p_input HERE.
         -- E32 stopped the harness supplying handler inputs, correctly, and the kernel dispatch
         -- passes no measurement keys, so denominator, numerator, formula and window were null on
         -- every call, jsonb_strip_nulls removed them, and the step's own output contract refused
         -- the output the handler had just built. They now come from the committed catalogue
         -- through fn_phase_d_fixture_output, which returns NULL when no row exists -- so a step
         -- with no committed measurement is still refused by its contract, and the denominator-of-0
         -- guard below is untouched.
         when 'MEASUREMENT_HANDLER' then jsonb_strip_nulls(jsonb_build_object(
           'metric', coalesce(public.fn_phase_d_fixture_output(sr.step_id,'metric'),
                              to_jsonb(nullif(btrim(coalesce(s.required_output,'')),''))),
           'denominator', public.fn_phase_d_fixture_output(sr.step_id,'denominator'),
           'numerator', public.fn_phase_d_fixture_output(sr.step_id,'numerator'),
           'formula', public.fn_phase_d_fixture_output(sr.step_id,'formula'),
           'window', public.fn_phase_d_fixture_output(sr.step_id,'window')))
         when 'CLOSURE_HANDLER' then jsonb_build_object(
           'blockers_resolved', jsonb_build_array(
             'the frozen fn_kernel_step_complete measures the four mandatory closure blocker '
             || 'classes itself and raises k3_closure_blocked if any is open'),
           'closure_evidence', coalesce(s.closure_criteria,''))
         else '{}'::jsonb end;

  -- ---- 5a. TWO REFUSALS THE SCHEMA ALONE CANNOT MAKE ---------------------------------------
  -- F34. TWO REFUSALS THAT WORE ONE NAME. "no review has been recorded for this step" and "the
  -- recorded review names the creator" are different facts with different remedies, and both came
  -- out as pd_rule_refused/BR-002. The first is now its own code, so a driver can answer it by
  -- recording the review through the kernel's own door and asking for the step again.
  if b.handler_class = 'REVIEW_HANDLER'
     and coalesce(btrim(coalesce(v_output->>'reviewer_role_id','')),'') = '' then
    raise exception 'fn_phase_d_handler_execute: step % is a review step and no internal review has been recorded for it. fn_kernel_review_decide seals the verdict and stamps the reviewer on the task; until it has run there is no reviewer to name and no verdict to carry. (pd_review_not_recorded)',
      sr.step_id using errcode = '23514';
  end if;

  if b.handler_class = 'REVIEW_HANDLER'
     and not public.fn_kernel_reviewer_independent(
               sr.accountable_role_id, v_output->>'reviewer_role_id') then
    raise exception 'fn_phase_d_handler_execute: step % is accountable to % and the review names % as reviewer; those resolve to the same effective identity. A creator cannot be the sole independent reviewer of the same output (BR-002). (pd_rule_refused)',
      sr.step_id, sr.accountable_role_id, coalesce(v_output->>'reviewer_role_id','(none)')
      using errcode = '23514';
  end if;

  if b.handler_class = 'MEASUREMENT_HANDLER'
     and jsonb_typeof(v_output->'denominator') = 'number'
     and (v_output->>'denominator')::numeric = 0 then
    raise exception 'fn_phase_d_handler_execute: step % reported a denominator of 0. A ratio over nothing is not a measurement, and reporting it as one is how an unmeasured goal scores as perfect. (pd_output_schema_invalid)',
      sr.step_id using errcode = '22023';
  end if;

  -- ---- 6. TYPED OUTPUT ---------------------------------------------------------------------
  select valid, reason, missing into v_ok, v_reason, v_missing
    from public.fn_phase_d_schema_validate(b.output_schema_id, v_output);
  if not v_ok then
    raise exception 'fn_phase_d_handler_execute: step % produced an output its own contract rejects: % (pd_output_schema_invalid)',
      sr.step_id, v_reason using errcode = '22023';
  end if;

  -- ---- 6b. THE BUSINESS EFFECT -------------------------------------------------------------
  -- D7. Until this line existed, 257 of 257 handlers produced a typed output the kernel accepted
  -- and no business effect whatsoever, and fn_phase_d_handler_state() said so in red.
  --
  -- The effect payload comes from the CALLER, merged over the step's own facts. Nothing about the
  -- business record is invented here: a step that needs a business_key and an owner_ref and is
  -- given neither refuses, because a record written under an owner this routine chose would be
  -- the auto-vivified customer account defect in a new place.
  v_effect := public.fn_phase_d_effect_produce(
    jsonb_build_object(
      'step_run_id', v_step_run, 'idempotency_key', v_idem, 'actor_role_id', v_actor,
      'execution_context', v_ctx)
    || jsonb_strip_nulls(jsonb_build_object(
      'business_key', p_input->>'business_key',
      'owner_ref',    p_input->>'owner_ref',
      -- H01 (4). The caller's stated state, else the state the committed catalogue declares for
      -- THIS step (EFFECT_PAYLOAD key 'state', step-scoped, fixture context only), else none -- and
      -- none means the writer keeps the row's state or takes the relation's default. Never 'open'.
      'state',        coalesce(p_input->>'effect_state',
                               (select fi.value #>> '{}'
                                  from public.fn_phase_d_fixture_input(v_step_run, 'EFFECT_PAYLOAD', 'state') fi)),
      'state_before', p_input->>'state_before',
      'trace_id',     p_input->>'trace_id'))
    -- F16. THE CONTENT THE OBJECT'S OWN RELATION DEMANDS, from the committed catalogue.
    --
    -- pd_effect_payload_incomplete is the deepest refusal in the drive: the step has passed every
    -- rule and gate, the dispatch has derived a business key and an owner, and the write to the
    -- object's canonical relation fails on a NOT NULL column -- opportunity.kind, org_tasks.title,
    -- department_objective.objective, content_drafts.body. The builder closure of 2026-08-20
    -- recorded 18 of 56 business objects in that state and reported it as a Phase E boundary,
    -- correctly, because a deterministic handler must not invent a title or an amount.
    --
    -- The founder's ruling of 21 Aug 2026 supplies them instead, from a committed catalogue, and
    -- this is where they arrive. The handler still invents nothing: the value comes from
    -- fn_phase_d_fixture_effect_payload, which reads the columns the RELATION demands and the
    -- values the CATALOGUE holds, and which returns an empty object in production.
    --
    -- The order is caller, then capability result, then catalogue, and the catalogue is last so it
    -- can only fill what nothing else filled.
    || jsonb_build_object('payload',
         public.fn_phase_d_fixture_effect_payload(v_step_run)
         || coalesce(p_input->'effect_payload', v_inputs)
         || case when v_cap is null then '{}'::jsonb
                 else coalesce(v_cap->'payload','{}'::jsonb) end
         -- H01 (1). THE RECORDED REVIEW, LAST, FOR A REVIEW_VERDICT EFFECT. F34 read it into the
         -- output and never into the payload, and BR-002 is judged on the payload. The sealed
         -- verdict and the stamped reviewer outrank the catalogue and any caller, so they close
         -- the concatenation. Absent, nothing is added and fn_phase_d_effect_produce still refuses.
         || case when ec.expected_effect_type = 'REVIEW_VERDICT'
                 then jsonb_strip_nulls(jsonb_build_object(
                        'verdict',          v_review->>'verdict',
                        'reviewer_role_id', v_review->>'reviewer_role_id'))
                 else '{}'::jsonb end
         -- H01 (3). WHO DECIDED AND WHEN, FOR A DECISION STEP. The decider is the accountable role
         -- of the deciding step run, read off the kernel's row; the time is now(). A write map that
         -- carries neither key ignores both.
         || case when b.handler_class = 'DECISION_HANDLER'
                 then jsonb_build_object('decided_by', v_actor, 'decided_at', now())
                 else '{}'::jsonb end
         -- L03. THE VERSION AND THE DIGEST THAT WERE ACCEPTED, FOR A STEP THAT RECORDS AN
         -- ACCEPTANCE. W09-S06's own frozen completion condition is "Displayed version, recorded
         -- version and document hash match", and the record it wrote carried none of the three:
         -- the payload was the workflow_record blob and nothing else. It went unseen because the
         -- fixture scenario built the acceptance itself, with the published pair on it, so every
         -- downstream read found the FIXTURE's record rather than the product's. Withhold that
         -- stage and W09-S07, S08 and S09 refuse on BR-025.
         -- The pair is the step's own resolved context -- the same value BR-025 has just judged at
         -- this step -- so the record states what was accepted and BR-025 can judge it again
         -- downstream. A step whose object is not a registered acceptance adds nothing, and a
         -- context that resolved neither key adds nothing.
         || case when exists (select 1 from public.phase_d_acceptance_document a
                               where a.object_id = ec.effect_object_id)
                 then jsonb_strip_nulls(jsonb_build_object(
                        'terms_version', p_input->'context'->>'terms_version',
                        'terms_hash',    p_input->'context'->>'terms_hash'))
                 else '{}'::jsonb end));

  v_output := v_output || jsonb_build_object('business_effect', jsonb_build_object(
    'effect_type', v_effect->>'effect_type',
    'effect_object_id', v_effect->'effect_object_id',
    'result_reference', v_effect->>'result_reference',
    'effect_id', v_effect->'effect_id',
    'provider_mode', v_effect->>'provider_mode',
    'replay', v_effect->'replay'));

  -- ---- 7. HAND TO THE FROZEN KERNEL --------------------------------------------------------
  -- Everything from here — idempotency, locks, authority, gates, the task state machine,
  -- progression, handoffs, run state and events — belongs to fn_kernel_step_complete and is not
  -- reimplemented. A handler that wrote any of it would be the parallel engine the spec forbids.
  v_result := public.fn_kernel_step_complete(jsonb_build_object(
    'step_run_id', v_step_run, 'actor_role_id', v_actor, 'outcome', 'pass',
    'idempotency_key', v_idem, 'inputs', v_inputs, 'output', v_output,
    'evidence_ref', format('phase_d:%s:%s:effect=%s',
                           b.handler_id, v_step_run, coalesce(v_effect->>'result_reference','none')),
    'correlation_id', p_input->>'correlation_id',
    'causation_id', coalesce(p_input->>'causation_id', 'phase_d_handler:' || b.handler_id)));

  return v_result || jsonb_build_object(
    'phase_d', jsonb_build_object(
      'handler_id', b.handler_id, 'handler_version', b.handler_version,
      'handler_class', b.handler_class, 'execution_context', v_ctx,
      'input_schema_id', b.input_schema_id, 'output_schema_id', b.output_schema_id,
      'rules_in_scope', cardinality(b.rule_ids),
      'rules_evaluated', v_evaluated, 'rules_not_applicable', v_skipped,
      'rules_enforced_count', (select count(*) from jsonb_array_elements(v_evaluated) e2
                                where (e2->>'enforced')::boolean),
      'rules_outstanding_count', (select count(*) from jsonb_array_elements(v_evaluated) e2
                                   where not (e2->>'enforced')::boolean),
      'gates_in_scope', cardinality(b.gate_ids), 'gates_evaluated', v_gates,
      'capability_dependency', b.capability_dependency,
      'provider_dependency', b.provider_dependency,
      'external_effect_policy', b.external_effect_policy,
      'expected_effect_type', ec.expected_effect_type,
      'implementation_depth', ec.implementation_depth,
      'business_effect', v_effect));
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_handler_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_steps int; n_bound int; n_amb int; n_sch int; n_drift int; n_blocked int; n_def int;
        n_produced int;
        n_wired int; n_needwrite int;
begin
  select count(*) into n_steps from public.phase_b_workflow_step;
  select count(*) into n_bound from public.phase_d_handler_binding;

  check_name := 'every_frozen_step_has_a_handler_binding';
  expected := n_steps::text; actual := n_bound::text; ok := (n_bound = n_steps); return next;

  select count(*) into n_amb from public.phase_d_handler_binding b
   where not exists (select 1 from public.phase_b_workflow_step s where s.step_id = b.step_id);
  check_name := 'no_binding_for_an_unfrozen_step';
  expected := '0'; actual := n_amb::text; ok := (n_amb = 0); return next;

  select count(*) into n_sch from public.phase_d_handler_schema;
  check_name := 'two_schemas_per_step';
  expected := (n_steps * 2)::text; actual := n_sch::text; ok := (n_sch = n_steps * 2); return next;

  select count(*) into n_drift from public.phase_d_handler_schema sc
    join public.phase_b_workflow_step s on s.step_id = sc.step_id
   where sc.source_digest <> encode(sha256(convert_to(
           case sc.schema_kind
             when 'input' then coalesce(s.required_inputs,'')
             else coalesce(s.required_output,'') || ' || ' || coalesce(s.acceptance_criteria,'')
           end, 'UTF8')), 'hex');
  check_name := 'no_schema_drift_against_frozen_phase_b';
  expected := '0'; actual := n_drift::text; ok := (n_drift = 0); return next;

  select count(*) into n_blocked from public.phase_d_handler_binding
   where phase_d_status = 'BLOCKED_DEFECT';
  check_name := 'blocked_defects';
  expected := '0'; actual := n_blocked::text; ok := (n_blocked = 0); return next;

  select count(*) into n_def
    from public.phase_d_handler_binding b
    join public.kernel_retired_path rp
      on b.handler_routine like '%' || rp.path_name || '%'
   where rp.disposition = 'DISABLED';
  check_name := 'no_binding_names_a_retired_routine';
  expected := '0'; actual := n_def::text; ok := (n_def = 0); return next;

  -- THE HONEST ONE. Red until a handler actually writes its business object. This check exists
  -- so the 236 NEW_DETERMINISTIC_HANDLER rows cannot be read as 236 steps with a business effect.
  --
  -- Counted as the GAP, not as the coverage, so the number FALLS as the work lands and the
  -- kernel-boards ratchet can cap it. A check reading "0 of 257 wired" would have to be ratcheted
  -- at a number that must grow, which the ratchet cannot express and which would invert its
  -- meaning: it asserts disclosed debt does not get worse.
  select count(*) into n_wired from public.phase_d_handler_binding where business_write_wired;
  select count(*) into n_needwrite from public.phase_d_handler_binding;
  -- E20 / finding 10. RENAMED TO WHAT IT COMPUTES. It reads business_write_wired, a stored boolean
  -- that records a binding DECLARING a business write. A declaration is not a write, and a check
  -- whose name says "not writing" while its body counts a column asserts something untrue about
  -- itself. E10 added a comment saying so; the name still said the other thing.
  check_name := 'handler_bindings_that_declare_no_business_write';
  expected := '0'; actual := (n_needwrite - n_wired)::text
           || ' of ' || n_needwrite::text || ' (source: phase_d_handler_binding.business_write_wired, '
           || 'a declaration; see handlers_that_have_actually_produced_an_effect below for writes)';
  ok := (n_needwrite - n_wired = 0); return next;

  -- E10. WHAT THAT ZERO IS, AND WHAT IT IS NOT. It is derived from the handler's declared call to
  -- fn_phase_d_effect_produce plus a stored boolean — a statement that the PATH EXISTS. It is not a
  -- statement that any handler has ever written a business object, and the two read identically at
  -- a glance because both are the number 0 beside a green tick.
  -- The question it does not answer is on fn_phase_d_effect_state as
  -- steps_with_no_effect_ever_produced, which reads 257 and is this phase's only red. Both numbers
  -- are quoted here so a reader of this board cannot take the green one for the other.
  select count(distinct step_id) into n_produced from public.phase_d_effect_ledger;

  check_name := 'handlers_that_have_actually_produced_an_effect';
  expected := 'informational — the green above says the path EXISTS, this says whether it has RUN';
  actual := n_produced::text || ' of ' || n_steps::text
         || ' steps have ever produced an effect; see fn_phase_d_effect_state.'
         || 'steps_with_no_effect_ever_produced for what holds the remainder';
  ok := true; return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_handoff_accept(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c        public.phase_d_handoff_contract%rowtype;
  hr       public.phase_c_handoff_run%rowtype;
  r        public.phase_c_workflow_run%rowtype;
  prior    public.phase_d_handoff_acceptance%rowtype;
  v_id     bigint := nullif(p_input->>'handoff_run_id','')::bigint;
  v_actor  text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_packet jsonb  := p_input->'packet';
  v_idem   text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_valid  record;
  v_res    jsonb;
  v_resolved text;
  v_due    timestamptz;
  v_tasks  int;
  v_aid    bigint;
  v_pd_executed boolean;   -- E33: did the Phase D handler execute the receiving step at open?
begin
  if v_id is null or v_actor is null then
    raise exception 'fn_phase_d_handoff_accept: handoff_run_id and actor_role_id are both required (pd_handoff_input_invalid)'
      using errcode = '22023';
  end if;
  v_idem := coalesce(v_idem, format('pd-handoff-accept:%s', v_id));

  select * into hr from public.phase_c_handoff_run where handoff_run_id = v_id;
  if not found then
    raise exception 'fn_phase_d_handoff_accept: no handoff run % (pd_handoff_not_found)', v_id
      using errcode = '23503';
  end if;

  -- IDEMPOTENCY IS A READ. The kernel would raise k3_handoff_not_open on a second call, which is
  -- correct but tells a replaying caller nothing about what happened the first time. The stored
  -- decision is returned verbatim and NOTHING is created.
  select * into prior from public.phase_d_handoff_acceptance where handoff_run_id = v_id;
  if found then
    return jsonb_build_object(
      'ok', prior.outcome = 'accepted', 'replay', true,
      'handoff_run_id', v_id, 'handoff_id', prior.handoff_id, 'outcome', prior.outcome,
      'run_id', prior.run_id, 'to_step_id', prior.to_step_id,
      'step_run_id', prior.opened_step_run_id, 'task_id', prior.opened_task_id,
      'accountable_now', prior.accountable_after,
      'note', 'this handoff run already carries a Phase D decision; no second task was opened');
  end if;

  select * into c from public.phase_d_handoff_contract where handoff_id = hr.handoff_id;
  if not found then
    raise exception 'fn_phase_d_handoff_accept: handoff % carries no Phase D contract — refusing to accept under a contract nobody declared (pd_handoff_uncontracted)',
      hr.handoff_id using errcode = '23503';
  end if;

  if hr.status <> 'open' then
    raise exception 'fn_phase_d_handoff_accept: handoff run % is % and only an open handoff may be accepted (pd_handoff_not_open)',
      v_id, hr.status using errcode = '23514';
  end if;

  select * into r from public.phase_c_workflow_run where run_id = hr.run_id;
  if not found then
    raise exception 'fn_phase_d_handoff_accept: handoff run % names workflow run %, which does not exist (pd_handoff_run_missing)',
      v_id, hr.run_id using errcode = '23503';
  end if;
  -- A run that has reached a terminal state, or is blocked, cannot take work back. The kernel
  -- would move it to active regardless, because its transition guard permits waiting_* -> active
  -- and says nothing about cancelled -> active being reached from here.
  if r.state not in ('waiting_handoff','waiting_review','active','waiting_input') then
    raise exception 'fn_phase_d_handoff_accept: run % is in state % and no handoff may be accepted into it (pd_handoff_run_state_invalid)',
      r.run_id, r.state using errcode = '23514';
  end if;

  -- THE RECEIVER, DECIDED FROM THE CONTRACT AND NOT FROM THE RUN ROW. The kernel checks the same
  -- thing against phase_c_handoff_run.receiving_role_id; checking the frozen contract as well means
  -- a handoff run whose receiver was written wrong cannot be accepted by the wrong role and then
  -- have the kernel agree with it.
  select role_id into v_resolved from public.fn_phase_c_resolve_actor(v_actor);
  if v_resolved is null
     or v_resolved is distinct from (select role_id from public.fn_phase_c_resolve_actor(c.receiving_role_id)) then
    raise exception 'fn_phase_d_handoff_accept: handoff % is addressed to % and % may not accept it (pd_handoff_wrong_receiver)',
      c.handoff_id, c.receiving_role_id, v_actor using errcode = '23514';
  end if;

  select * into v_valid from public.fn_phase_d_handoff_packet_valid(hr.handoff_id, v_packet);
  if not v_valid.valid then
    raise exception 'fn_phase_d_handoff_accept: handoff % packet is missing [%]. Its frozen required_packet is: % (pd_handoff_packet_incomplete)',
      c.handoff_id, array_to_string(v_valid.missing, ', '),
      left((select required_packet from public.phase_b_handoff where handoff_id = c.handoff_id), 180)
      using errcode = '23514';
  end if;

  -- SLA is a measurement, not a second gate. A late acceptance is still an acceptance; recording it
  -- as a breach is the contract element, and refusing it would invent a rule Phase B does not state.
  v_due := coalesce(hr.due_at, hr.opened_at + c.sla_target);

  -- ---- the frozen kernel does the state move ---------------------------------------------------
  v_res := public.fn_kernel_handoff_accept(jsonb_build_object(
    'handoff_run_id', v_id, 'actor_role_id', v_actor, 'packet', v_packet,
    'priority', coalesce(nullif(p_input->>'priority',''), 'P2')));

  if not coalesce((v_res->>'ok')::boolean, false) then
    raise exception 'fn_phase_d_handoff_accept: the kernel refused handoff run %: % (pd_handoff_kernel_refused)',
      v_id, coalesce(v_res::text, '(no result)') using errcode = '23514';
  end if;

  -- AT MOST ONE OPEN TASK ON THE RECEIVING STEP, AND ZERO HAS TWO DIFFERENT CAUSES. Asserted on
  -- the row count, not inferred from the kernel's own summary. `phase_c_task` carries
  -- (run_id, step_id) and no step_run_id, so the population is the receiving step of this run; a
  -- duplicate acceptance that opened a second task makes this 2, which is precisely the failure
  -- "duplicate acceptance creating duplicate task = 0" names.
  --
  -- E33. THIS WAS WRITTEN AS <> 1 AND SO IT ALSO REFUSED ZERO, WHICH SINCE D36 IS WHAT PHASE D
  -- WORKING LOOKS LIKE. The dispatch runs in the kernel's OPENER, so this very acceptance opens the
  -- receiving step and the deterministic handler attempts it in the same statement. If the handler
  -- EXECUTES, the step's work is done and the kernel closes its task - and this count is 0. W01-S05
  -- and W21-S08 are the only two steps in the estate whose handler executes, and they were the only
  -- two whose incoming handoff was refused. A guard that fires exactly when the system works.
  --
  -- Measured before changing it: two drives of W01 differing only in app.phase_d_dispatch. With the
  -- dispatch ON the run stops after W01-S05, whose dispatch reads EXECUTED and whose task is
  -- closed. With it OFF the run reaches W01-S06 with an OPEN task. One variable, opposite outcomes.
  select count(*) into v_tasks from public.phase_c_task t
   where t.run_id = r.run_id and t.step_id = c.to_step_id and t.closed_at is null;

  v_pd_executed := exists (
    select 1 from public.phase_d_dispatch d
     where d.run_id = r.run_id and d.step_id = c.to_step_id and d.outcome = 'EXECUTED');

  if v_tasks > 1 then
    raise exception 'fn_phase_d_handoff_accept: accepting handoff run % left % open task(s) on %; a second open task is a duplicate acceptance (pd_handoff_task_count_wrong)',
      v_id, v_tasks, c.to_step_id using errcode = '23514';
  end if;
  if v_tasks = 0 and not v_pd_executed then
    raise exception 'fn_phase_d_handoff_accept: accepting handoff run % left no open task on % and no Phase D dispatch executed that step, so nothing is carrying the work (pd_handoff_task_count_wrong)',
      v_id, c.to_step_id using errcode = '23514';
  end if;

  insert into public.phase_d_handoff_acceptance
    (handoff_run_id, handoff_id, run_id, workflow_id, outcome, actor_role_id,
     accountable_before, accountable_after, to_step_id, opened_step_run_id, opened_task_id,
     packet_digest, packet_keys_present, packet_keys_missing, sla_policy_id, due_at, sla_breached,
     idempotency_key, trace_id)
  values (v_id, c.handoff_id, r.run_id, r.workflow_id, 'accepted', v_resolved,
          c.accountable_before_accept, c.accountable_after_accept, c.to_step_id,
          (v_res->>'step_run_id')::bigint, (v_res->>'task_id')::bigint,
          encode(sha256(convert_to(coalesce(v_packet,'{}'::jsonb)::text,'UTF8')),'hex'),
          v_valid.present, null, c.sla_policy_id, v_due,
          case when v_due is null then null else now() > v_due end,
          v_idem, (v_res->>'handoff_trace_id')::bigint)
  returning acceptance_id into v_aid;

  if v_aid is null then
    raise exception 'fn_phase_d_handoff_accept: the acceptance ledger insert for handoff run % returned no id (pd_handoff_ledger_produced_nothing)',
      v_id using errcode = '23502';
  end if;

  return jsonb_build_object(
    'ok', true, 'replay', false, 'acceptance_id', v_aid,
    'handoff_run_id', v_id, 'handoff_id', c.handoff_id,
    'run_id', r.run_id, 'workflow_id', r.workflow_id,
    'accepted_by', v_resolved,
    'accountable_before', c.accountable_before_accept,
    'accountable_after', c.accountable_after_accept,
    'to_step_id', c.to_step_id,
    'step_run_id', (v_res->>'step_run_id')::bigint,
    'task_id', (v_res->>'task_id')::bigint,
    -- E33. WHO IS CARRYING THE RECEIVING STEP, on the row rather than only in a comment. An
    -- acceptance that opened a task for a person and one whose step the deterministic handler had
    -- already completed are different events, and a reader must not have to infer which from a
    -- null.
    'open_tasks_on_receiving_step', v_tasks,
    'receiving_step_handled_by',
      case when v_tasks = 1 then 'actor'
           when v_pd_executed then 'phase_d_handler'
           else 'nobody' end,
    'tasks_opened', v_tasks,
    'packet_keys_checked', v_valid.required,
    'sla_policy_id', c.sla_policy_id, 'due_at', v_due,
    'sla_breached', case when v_due is null then null else now() > v_due end,
    'run_state', v_res->>'run_state',
    'closure_condition', c.closure_condition);
end 
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_handoff_packet_valid(p_handoff_id text, p_packet jsonb)
 RETURNS TABLE(valid boolean, missing text[], required text[], present text[])
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c public.phase_d_handoff_contract%rowtype;
  v_all text[];
begin
  select * into c from public.phase_d_handoff_contract where handoff_id = p_handoff_id;
  if not found then
    -- Fail closed. An uncontracted handoff is not a permissive one.
    valid := false;
    missing := array['(no Phase D contract for ' || coalesce(p_handoff_id,'(null)') || ')'];
    required := '{}'; present := '{}';
    return next; return;
  end if;

  if p_packet is null or jsonb_typeof(p_packet) <> 'object' then
    valid := false; missing := c.packet_keys || c.kernel_packet_keys;
    required := c.packet_keys || c.kernel_packet_keys; present := '{}';
    return next; return;
  end if;

  -- BOTH sets. The contract keys come from the frozen prose; the kernel keys come from the kernel.
  -- Dropping either would mean a packet that satisfies this routine and is then refused downstream,
  -- or the reverse — a check that disagrees with the thing it guards.
  v_all := c.packet_keys || c.kernel_packet_keys;

  select array_agg(k order by k) into missing
    from unnest(v_all) k
   where not (p_packet ? k)
      or jsonb_typeof(p_packet->k) = 'null'
      or (jsonb_typeof(p_packet->k) = 'string' and btrim(p_packet->>k) = '');

  select array_agg(k order by k) into present
    from unnest(v_all) k where p_packet ? k;

  required := v_all;
  present  := coalesce(present, '{}');
  valid    := (missing is null);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_kernel_object_fixture(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run_ctx bigint := public.fn_phase_d_fixture_context();
  v_label   text   := nullif(btrim(coalesce(p_input->>'label','')),'');
  v_wf      text;
  v_step    text;
  v_start   jsonb;
  v_run     bigint;
  v_step_run bigint;
  v_handoff bigint;
  v_made    int := 0;
  v_note    text := '';
begin
  if v_run_ctx is null then
    raise exception 'fn_phase_d_kernel_object_fixture: no verified Phase D fixture context. A kernel run fixture exists only inside an audited fixture run, inside a transaction that is aborted. (pd_fixture_no_test_context)'
      using errcode = '42501';
  end if;
  if v_label is null then
    raise exception 'fn_phase_d_kernel_object_fixture: label is required (pd_fixture_label_missing)'
      using errcode = '22023';
  end if;

  -- DERIVED: the lowest-numbered workflow whose first step opens a handoff. Naming one here would
  -- make this stage a fact about a workflow rather than about the kernel.
  select h.from_step_id, split_part(h.from_step_id, '-', 1)
    into v_step, v_wf
    from public.phase_b_handoff h
   where h.from_step_id like '%-S01'
   order by h.from_step_id limit 1;
  if v_wf is null then
    -- No first step in the frozen registry opens a handoff. Fall back to the lowest workflow, which
    -- still creates the run and the step run; the handoff is then honestly absent.
    select w.workflow_id into v_wf from public.phase_b_workflow w order by w.workflow_id limit 1;
    v_note := 'no frozen first step opens a handoff, so handoff_record is not created by this stage';
  end if;

  v_start := public.fn_kernel_workflow_start(jsonb_build_object(
    'workflow_id',        v_wf,
    'business_object_id', 'phase_d_fixture:' || v_label,
    'source_kind',        'autonomous',
    'source_ref',         format('zz-phase-d-kernel-%s', v_label),
    'requested_by',       (select w.accountable_role_id from public.phase_b_workflow w
                            where w.workflow_id = v_wf),
    'trigger_ctx',        jsonb_build_object('driver','fn_phase_d_kernel_object_fixture',
                                             'path','kernel doors only')));
  v_run := (v_start->>'run_id')::bigint;
  if v_run is null then
    raise exception 'fn_phase_d_kernel_object_fixture: the kernel returned no run_id for %. Refusing to record a run that was not created. (pd_fixture_kernel_run_absent)',
      v_wf using errcode = '23502';
  end if;

  select sr.step_run_id into v_step_run from public.phase_c_workflow_step_run sr
   where sr.run_id = v_run order by sr.step_run_id limit 1;

  -- The kernel opens a handoff when the step that declares one COMPLETES. That is the door, and it
  -- is the same one the driver and the handler use.
  if v_step is not null and v_step_run is not null then
    begin
      perform public.fn_kernel_step_complete(jsonb_build_object(
        'step_run_id', v_step_run,
        'actor_role_id', (select s.accountable_role_id from public.phase_b_workflow_step s
                           where s.step_id = v_step),
        -- The kernel requires an idempotency key and is right to: the same completion arriving
        -- twice must close one step, not two. It is derived from the step run, so a replay of this
        -- fixture inside one transaction cannot produce a second handoff.
        'idempotency_key', format('phase_d_kernel_fixture:%s:%s', v_label, v_step_run),
        'outcome','pass',
        -- The kernel refuses a completion that does not carry the step's declared inputs, an
        -- output, evidence and a requested action. It is right to, and the shape below is the one
        -- fn_phase_d_drive_workflow already uses through the same door: no business content is
        -- supplied, only the bookkeeping the kernel's own contract requires.
        'inputs', jsonb_build_object('driver','fn_phase_d_kernel_object_fixture',
                                     'note','no business content is supplied by this fixture'),
        'output', jsonb_build_object('status','completed',
                                     'output', format('%s completed %s', v_label, v_step)),
        'evidence_refs', jsonb_build_array(jsonb_build_object('fixture_run', v_label)),
        'requested_action','proceed',
        'acceptance_criteria', format('the kernel opened the handoff %s declares', v_step),
        'object_version', 1,
        'note','PHASE_D_FIXTURE_DO_NOT_PUBLISH — completing one step so the kernel opens the handoff whose reference this stage records'));
    exception when others then
      v_note := coalesce(nullif(v_note,''), '') ||
        format(' the kernel declined to complete %s: %s', v_step, left(SQLERRM, 160));
    end;
    select hr.handoff_run_id into v_handoff from public.phase_c_handoff_run hr
     where hr.run_id = v_run order by hr.handoff_run_id limit 1;
  end if;

  -- RECORD ONLY WHAT EXISTS. Each of the three is recorded if and only if the kernel made it.
  if v_run is not null then
    perform public.fn_phase_d_scenario_record_write(jsonb_build_object(
      'fixture_id','PDS-workflow_run', 'fixture_version', 1,
      'source_checksum', encode(sha256(convert_to(v_run::text,'UTF8')),'hex'),
      'object_id','workflow_run', 'business_key', v_run::text, 'owner_ref','kernel',
      'ownership_scope','COMPANY', 'state','open',
      'canonical_relation','public.phase_c_workflow_run',
      'canonical_service','fn_kernel_workflow_start',
      'result_reference', format('public.phase_c_workflow_run:run_id=%s', v_run),
      'contributes_ref', null, 'contributes_kind','RESULT_KEY',
      'contributed_value', v_run::text,
      'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
        'object_id','workflow_run', 'identity', v_run::text, 'owner_ref','kernel')),
      'expected_effect','The kernel created this run through fn_kernel_workflow_start; no Phase D routine may write public.phase_c_workflow_run.'));
    v_made := v_made + 1;
  end if;

  if v_step_run is not null then
    perform public.fn_phase_d_scenario_record_write(jsonb_build_object(
      'fixture_id','PDS-workflow_step_run', 'fixture_version', 1,
      'source_checksum', encode(sha256(convert_to(v_step_run::text,'UTF8')),'hex'),
      'object_id','workflow_step_run', 'business_key', v_step_run::text, 'owner_ref','kernel',
      'ownership_scope','COMPANY', 'state','open',
      'canonical_relation','public.phase_c_workflow_step_run',
      'canonical_service','fn_kernel_open_step',
      'result_reference', format('public.phase_c_workflow_step_run:step_run_id=%s', v_step_run),
      'contributes_ref', null, 'contributes_kind','RESULT_KEY',
      'contributed_value', v_step_run::text,
      'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
        'object_id','workflow_step_run', 'identity', v_step_run::text, 'owner_ref','kernel')),
      'expected_effect','The kernel opened this step run inside fn_kernel_workflow_start; no Phase D routine may write public.phase_c_workflow_step_run.'));
    v_made := v_made + 1;
  end if;

  if v_handoff is not null then
    perform public.fn_phase_d_scenario_record_write(jsonb_build_object(
      'fixture_id','PDS-handoff_record', 'fixture_version', 1,
      'source_checksum', encode(sha256(convert_to(v_handoff::text,'UTF8')),'hex'),
      'object_id','handoff_record', 'business_key', v_handoff::text, 'owner_ref','kernel',
      'ownership_scope','COMPANY', 'state','open',
      'canonical_relation','public.phase_c_handoff_run',
      'canonical_service','fn_kernel_step_complete',
      'result_reference', format('public.phase_c_handoff_run:handoff_run_id=%s', v_handoff),
      'contributes_ref', null, 'contributes_kind','RESULT_KEY',
      'contributed_value', v_handoff::text,
      'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
        'object_id','handoff_record', 'identity', v_handoff::text, 'owner_ref','kernel')),
      'expected_effect','The kernel opened this handoff run when the step that declares it completed; no Phase D routine may write public.phase_c_handoff_run.'));
    v_made := v_made + 1;
  end if;

  return jsonb_build_object('ok', v_made > 0, 'workflow_id', v_wf,
    'run_id', v_run, 'step_run_id', v_step_run, 'handoff_run_id', v_handoff,
    'objects_recorded', v_made, 'note', coalesce(nullif(v_note,''),
    'every row recorded here was created by the frozen kernel through its own doors'));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_legal_assertion_source_is_current()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v record;
begin
  select * into v from public.fn_phase_d_legal_source_current(NEW.source_id, NEW.requires_authoritative);
  if v.usable then return NEW; end if;
  raise exception 'phase_d_legal_assertion: this position may not rest on %. % (%)',
    NEW.source_id, v.reason, v.refusal_code using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_legal_source_current(p_source_id text, p_require_authoritative boolean DEFAULT true, p_as_of date DEFAULT CURRENT_DATE)
 RETURNS TABLE(usable boolean, refusal_code text, reason text, authority_tier text, review_by date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s public.phase_d_legal_source%rowtype;
begin
  if coalesce(btrim(p_source_id),'') = '' then
    usable := false; refusal_code := 'pd_legal_source_missing';
    reason := 'No legal or tax source named. An interpretation resting on a source nobody cited is not evidence.';
    return next; return;
  end if;

  select * into s from public.phase_d_legal_source where source_id = btrim(p_source_id);
  if not found then
    usable := false; refusal_code := 'pd_legal_source_missing';
    reason := format('%L is not a registered legal or tax source.', p_source_id);
    return next; return;
  end if;
  authority_tier := s.authority_tier;
  review_by      := s.review_by;

  if s.superseded_by is not null then
    usable := false; refusal_code := 'pd_legal_source_superseded';
    reason := format('%s was superseded by %s: %s', s.source_id, s.superseded_by, s.supersession_reason);
    return next; return;
  end if;

  -- A DATE THAT IS ABSENT IS NOT A DATE THAT IS FINE. This is the arm the estate has been caught by
  -- before in another shape: a missing input scoring as satisfied.
  if s.freshness_policy = 'REVIEW_BY_DATE'
     and (s.review_by is null or s.published_on is null or s.effective_from is null) then
    usable := false; refusal_code := 'pd_legal_source_missing';
    reason := format('%s carries no %s. A source whose currency cannot be established may not support a current position.',
      s.source_id,
      concat_ws(' and ',
        case when s.published_on   is null then 'published date'  end,
        case when s.effective_from is null then 'effective date'  end,
        case when s.review_by      is null then 'review-by date'  end));
    return next; return;
  end if;

  if s.freshness_policy = 'REVIEW_BY_DATE' and s.review_by < p_as_of then
    usable := false; refusal_code := 'pd_legal_source_stale';
    reason := format('%s was due for review on %s and it is %s. A current legal or tax position may not rest on it.',
                     s.source_id, s.review_by, p_as_of);
    return next; return;
  end if;

  if s.effective_from is not null and s.effective_from > p_as_of then
    usable := false; refusal_code := 'pd_legal_source_not_yet_effective';
    reason := format('%s does not take effect until %s.', s.source_id, s.effective_from);
    return next; return;
  end if;

  if p_require_authoritative
     and s.authority_tier not in ('AUTHORITATIVE_PRIMARY','AUTHORITATIVE_SECONDARY') then
    usable := false; refusal_code := 'pd_legal_source_not_authoritative';
    reason := format('%s is %s (%s by %s). This step requires an authoritative source.',
                     s.source_id, s.authority_tier, s.source_type, s.authority_name);
    return next; return;
  end if;

  usable := true; refusal_code := null;
  reason := format('%s: %s by %s, effective %s, in review until %s, digest %s.',
                   s.source_id, s.source_type, s.authority_name, s.effective_from, s.review_by,
                   left(s.content_sha256, 12));
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_normalisation_does_not_restate_the_original()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_bad text[];
begin
  select array_agg(f.field_key order by f.field_key) into v_bad
    from public.phase_d_supplier_authored_field f
   where NEW.normalised ? f.field_key;
  if v_bad is not null then
    raise exception 'phase_d_quote_normalisation: the normalised projection restates supplier-authored field(s) [%]. A derived record references the original; it does not republish it under the same name. (pd_normalisation_restates_original)',
      array_to_string(v_bad, ', ') using errcode = '23514';
  end if;
  if not (NEW.transformation ? 'source_fields') then
    raise exception 'phase_d_quote_normalisation: transformation must name source_fields -- which original values this projection was derived from. A derived value whose derivation nobody recorded is a new number. (pd_normalisation_transformation_absent)'
      using errcode = '23514';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_object_identity_state()
 RETURNS TABLE(check_name text, expected text, actual text, state text, detail text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
with wm as (select * from public.phase_d_object_write_map where operation = 'UPSERT_STATE'),
uq as (
  select 'public.' || t.relname as rel, ic.relname as idx_name,
         array_agg(a.attname::text order by a.attnum) as cols
    from pg_index i
    join pg_class ic on ic.oid = i.indexrelid
    join pg_class t  on t.oid  = i.indrelid
    join pg_namespace n on n.oid = t.relnamespace and n.nspname = 'public'
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = any(i.indkey)
   where i.indisunique
   group by 1, 2
),
resolvable as (
  select wm.object_id,
         -- pass 1: the key column is mapped, so the writer can probe the value it will write
         (wm.column_map ? wm.key_column) as by_key_column,
         -- pass 2: some other unique index is entirely covered by the map
         exists (select 1 from uq
                  where uq.rel = wm.target_relation
                    and uq.cols <> array[wm.key_column]
                    and (select bool_and(wm.column_map ? c) from unnest(uq.cols) c)) as by_natural_key
    from wm
)
select 'every_upsert_state_map_can_resolve_an_identity',
       (select count(*)::text from resolvable),
       (select count(*)::text from resolvable where by_key_column or by_natural_key),
       case when exists (select 1 from resolvable where not (by_key_column or by_natural_key))
            then 'RED' else 'GREEN' end,
       coalesce((select string_agg(object_id, ', ' order by object_id) from resolvable
                  where not (by_key_column or by_natural_key)),
                'every UPSERT_STATE map resolves an identity')
       || ' — an UPSERT_STATE that resolves no identity can only ever INSERT, so its second write is'
       || ' a duplicate row rather than a state move. Owner: Phase D. Closing it needs an identity'
       || ' the business declares, not one a harness invents.'

union all
-- THE REGRESSION GUARD. This is the check that would have caught the original defect, and it is
-- written against the mechanism rather than against a count of failures.
select 'no_upsert_state_map_probes_a_column_it_does_not_write',
       '0',
       (select count(*)::text from wm
         where (wm.column_map ? wm.key_column)
           and (wm.column_map->>wm.key_column) <> 'business_key'
           and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                            where n.nspname = 'public' and p.proname = 'fn_phase_d_object_write'
                              and p.prosrc like '%v_supplied->>(wm.column_map->>wm.key_column)%')),
       case when exists (
              select 1 from wm
               where (wm.column_map ? wm.key_column)
                 and (wm.column_map->>wm.key_column) <> 'business_key'
                 and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                                  where n.nspname = 'public' and p.proname = 'fn_phase_d_object_write'
                                    and p.prosrc like '%v_supplied->>(wm.column_map->>wm.key_column)%'))
            then 'RED' else 'GREEN' end,
       'supplier_capability points key_column supplier_id at owner_ref; if the writer ever goes back '
       || 'to probing business_key it reads one value and writes another, and the second write dies '
       || 'on the primary key'

union all
select 'the_writer_carries_the_natural_key_pass',
       '1',
       (select count(*)::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public' and p.proname = 'fn_phase_d_object_write'
           and p.prosrc like '%indisunique%' and p.prosrc like '%pg_get_expr(i.indpred%'),
       case when exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                          where n.nspname = 'public' and p.proname = 'fn_phase_d_object_write'
                            and p.prosrc like '%indisunique%' and p.prosrc like '%pg_get_expr(i.indpred%')
            then 'GREEN' else 'RED' end,
       'quotes(inquiry_id,supplier_id) and the PARTIAL transactions(quote_id) are only reachable '
       || 'through the natural-key pass, and the partial predicate has to travel with it'

union all
select 'the_update_targets_the_row_the_probe_found',
       '1',
       (select count(*)::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public' and p.proname = 'fn_phase_d_object_write'
           and p.prosrc like '%using v_supplied, v_existing%'),
       case when exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                          where n.nspname = 'public' and p.proname = 'fn_phase_d_object_write'
                            and p.prosrc like '%using v_supplied, v_existing%')
            then 'GREEN' else 'RED' end,
       'updating by business_key after a natural-key probe reintroduces the same mismatch one '
       || 'statement later'
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_object_owner_is_stable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_scope text; v_prior text;
begin
  select b.ownership_scope into v_scope
    from public.phase_d_business_object_binding b where b.object_id = NEW.object_id;
  -- COMPANY-scoped objects are owned by the company; only a tenant scope has a foreign owner to be
  -- crossed. Stated rather than left implicit, because widening this to COMPANY would refuse the
  -- estate's own bookkeeping.
  if coalesce(v_scope,'') not in ('CUSTOMER','SUPPLIER') then return NEW; end if;

  select o.owner_ref into v_prior
    from public.phase_d_object_record o
   where o.object_id = NEW.object_id and o.business_key = NEW.business_key
     and o.superseded_by is null and o.record_id is distinct from NEW.record_id
   order by o.record_id desc limit 1;

  if v_prior is not null and v_prior is distinct from NEW.owner_ref then
    raise exception 'phase_d_object_record: %/% is owned by %, and this write names owner %. A %-scoped record does not change hands, and a caller does not get to name whose records these are. (pd_object_cross_owner_write)',
      NEW.object_id, NEW.business_key, v_prior, coalesce(NEW.owner_ref,'(none)'), v_scope
      using errcode = '23514';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_object_policy_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_family text;
begin
  -- Pinned lookup. A trigger runs with the WRITER's search_path, so an unqualified read here
  -- could be answered by a table the caller shadowed.
  select b.policy_family into v_family
    from public.phase_d_business_object_binding b
   where b.object_id = coalesce(new.object_id, old.object_id);

  if v_family is null then
    raise exception 'phase_d_object_record: object % has no Phase D binding — fail closed rather than store a record under a policy nobody declared',
      coalesce(new.object_id, old.object_id) using errcode = '23503';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'phase_d_object_record: % is a % object and business records are never deleted. Cancellation preserves the record, its reason and its authority (BR-046). (pd_object_delete_refused)',
      old.object_id, v_family using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' then
    -- The ONLY update any family permits is the supersession pointer being set once, plus the
    -- state moving. Everything that carries the business fact is frozen on write.
    if new.object_id  is distinct from old.object_id
       or new.business_key is distinct from old.business_key
       or new.version   is distinct from old.version
       or new.payload   is distinct from old.payload
       or new.owner_scope is distinct from old.owner_scope
       or new.owner_ref is distinct from old.owner_ref
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at then
      raise exception 'phase_d_object_record: record % belongs to % (%). Its identity, owner and payload are frozen on write; a change creates a NEW version and supersedes this one. (pd_object_overwrite_refused)',
        old.record_id, old.object_id, v_family using errcode = '23514';
    end if;
    if old.superseded_by is not null and new.superseded_by is distinct from old.superseded_by then
      raise exception 'phase_d_object_record: record % is already superseded by % and a supersession pointer is written once. (pd_object_resupersede_refused)',
        old.record_id, old.superseded_by using errcode = '23514';
    end if;
    if v_family = 'APPEND_ONLY' and new.state is distinct from old.state then
      raise exception 'phase_d_object_record: % is APPEND_ONLY (%); even its state does not move after write. A correction is a new record. (pd_object_append_only)',
        old.object_id, (select record_policy from public.phase_d_business_object_binding
                         where object_id = old.object_id) using errcode = '23514';
    end if;
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_object_record_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c public.phase_d_object_state_contract%rowtype;
  b public.phase_d_business_object_binding%rowtype;
  v_money text[];
begin
  select * into c from public.phase_d_object_state_contract where object_id = new.object_id;
  if not found then
    -- FAIL CLOSED. An object with no state contract is a gap in the registry, not a licence.
    raise exception 'phase_d_object_record: object % has no row in phase_d_object_state_contract, so there is no domain to check its state against. Register the object before writing it. (pd_object_no_state_contract)',
      new.object_id using errcode = '23514';
  end if;

  if not (new.state = any (c.allowed_states)) then
    -- RAISE has no %L. It is a format() placeholder, and using it here printed the state followed
    -- by a stray "L" until this line said so.
    raise exception 'phase_d_object_record: % is a %-family object and state "%" is not one of [%]. (pd_object_state_outside_domain)',
      new.object_id, c.policy_family, new.state, array_to_string(c.allowed_states, ', ')
      using errcode = '23514';
  end if;

  select * into b from public.phase_d_business_object_binding where object_id = new.object_id;
  if found then
    if new.owner_scope is distinct from b.ownership_scope then
      raise exception 'phase_d_object_record: % declares ownership_scope % and this record carries %. The scope is the object''s, not the caller''s. (pd_object_owner_scope_mismatch)',
        new.object_id, coalesce(b.ownership_scope,'(none)'), coalesce(new.owner_scope,'(none)')
        using errcode = '23514';
    end if;

    -- Every one of the 56 objects is owned by COMPANY, CUSTOMER or SUPPLIER. There is no unowned
    -- object, so an empty owner_ref is a record nobody is accountable for.
    if coalesce(btrim(coalesce(new.owner_ref,'')),'') = '' then
      raise exception 'phase_d_object_record: % is owned at % scope and this record names no owner_ref. (pd_object_owner_missing)',
        new.object_id, coalesce(b.ownership_scope,'(unstated)') using errcode = '23514';
    end if;

    -- A MONEY AMOUNT MAY NOT RIDE IN ON A NON-FINANCIAL OBJECT, AT ANY DEPTH, IN ANY NOTATION.
    -- Three conditions, and the FIRST is the one E27 added: an IDENTIFIER is never an amount.
    -- `refund_id`, `invoice_no`, `price_ref` name things; whether their value happens to be numeric
    -- is irrelevant, and E24 got this wrong by allowing a numeric string without excluding them.
    if coalesce(b.policy_family,'') <> 'TRANSACTION_RECORD' then
      select array_agg(distinct k order by k) into v_money
        from jsonb_path_query(new.payload, '$.**') node,
             lateral jsonb_each(case when jsonb_typeof(node) = 'object' then node else '{}'::jsonb end) e(k, v)
       where k !~* '_(id|ref|no|key|code)$'
         and (k ~* '(^|_)(amount|price|charge|payout|subtotal|total|fee|cost|refund|invoice)(_|$)'
              or k ~* '_(aed|usd|eur|gbp)$')
         and (jsonb_typeof(v) = 'number'
              -- E35. THE STRING ARM REQUIRED A WHOLLY NUMERIC STRING, so two notations for the
              -- same amount walked past it and the R4 acceptance named both:
              --     refund_amount_aed: "AED 999999"   ACCEPTED - a currency prefix
              --     refund_amount_aed: "1e6"          ACCEPTED - scientific notation
              -- Neither is an identifier and neither was ever going to be one: they are quantities
              -- written the way a person and a JSON serialiser respectively write them. A rule that
              -- reads a number but not the same number with AED in front of it is testing the
              -- notation, not the subject.
              --
              -- The identifier exclusion above still settles those cases first and is unchanged, so
              -- refund_id, invoice_no and price_ref are as accepted as they were after E27 -
              -- whatever notation their value takes.
              --
              -- The third residual note the audit raised, price_code: 999999, is NOT closed here
              -- and I am not pretending it is. `_code` is on the identifier-exclusion list by
              -- deliberate choice in E27, the auditor judged that trade correct, and widening the
              -- money side to reach it would put every *_code key back in front of the rule that
              -- blocked eleven legitimate workflows. It is a named hole, and it stays named.
              -- E40. A THIRD AND FOURTH NOTATION, AND THE SECOND ONE SHOULD NOT HAVE TAKEN FOUR
              -- INCREMENTS TO FIND. E24 caught numbers, E27 numeric strings, E35 currency prefixes
              -- and scientific notation; the R7 acceptance found two more on a money-shaped
              -- non-identifier key:
              --     refund_amount_aed: "0x1F"      ACCEPTED -- hexadecimal
              --     refund_amount_aed: "AED٩٩٩"    ACCEPTED -- ٩٩٩ is 999
              -- This company sells in the UAE. An amount written in the digit script of its own
              -- market is not an edge case, and every arm of this rule anchored on ASCII [0-9].
              or (jsonb_typeof(v) = 'string'
                  and (v #>> '{}' ~* '^[[:space:]]*(aed|usd|eur|gbp|\$|€|£)?[[:space:]]*-?[0-9][0-9,]*(\.[0-9]+)?([eE][+-]?[0-9]+)?[[:space:]]*(aed|usd|eur|gbp)?[[:space:]]*$'
                       or v #>> '{}' ~* '^[[:space:]]*(aed|usd|eur|gbp|\$|€|£)?[[:space:]]*0x[0-9a-f]+[[:space:]]*$'
                       -- Arabic-Indic U+0660..0669 and Extended Arabic-Indic U+06F0..06F9. A
                       -- money-shaped key that is not an identifier, carrying digits in any script,
                       -- is carrying a quantity.
                       or v #>> '{}' ~ '[٠-٩۰-۹]')));
      if v_money is not null then
        raise exception 'phase_d_object_record: % is a %-family object and its payload carries money amount(s) [%] — a money-shaped key that is not an identifier, holding a quantity, at any depth. Only a TRANSACTION_RECORD object may. (pd_object_money_key_on_non_financial_object)',
          new.object_id, b.policy_family, array_to_string(v_money, ', ') using errcode = '23514';
      end if;
    end if;
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_object_write(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  b            public.phase_d_business_object_binding%rowtype;
  wm           public.phase_d_object_write_map%rowtype;
  v_object     text  := nullif(btrim(coalesce(p_input->>'object_id','')),'');
  v_key        text  := nullif(btrim(coalesce(p_input->>'business_key','')),'');
  v_owner_ref  text  := nullif(btrim(coalesce(p_input->>'owner_ref','')),'');
  v_payload    jsonb := p_input->'payload';
  v_actor      text  := nullif(btrim(coalesce(p_input->>'created_by','')),'');
  v_state      text  := coalesce(nullif(btrim(p_input->>'state'),''), 'open');
  v_state_given text := nullif(btrim(p_input->>'state'),'');   -- H02: what the caller actually said
  v_unchanged  boolean := false;                               -- H02: a confirmation, not a write
  v_prior      public.phase_d_object_record%rowtype;
  v_version    integer := 1;
  v_id         bigint;
  v_readback   public.phase_d_object_record%rowtype;
  v_cols       text[] := '{}';
  v_vals       text[] := '{}';
  v_sets       text[] := '{}';
  v_col        record;
  v_expr       text;
  v_existing   text;
  v_result_ref text;
  v_sql        text;
  v_supplied   jsonb;
  -- D17: the outbound door.
  v_testctx    boolean := public.fn_phase_d_fixture_context() is not null;
  v_door       record;
  v_door_val   jsonb;
  v_net_max    bigint;
  v_net_new    bigint;
  v_net_urls   text;
  -- K02: the parent the object declares.
  v_parent_src text;
  -- D18: identity resolution for UPSERT_STATE.
  v_ident_val  text;
  v_uq         record;
  v_where      text;
begin
  if v_object is null or v_key is null or v_actor is null then
    raise exception 'fn_phase_d_object_write: object_id, business_key and created_by are all required (got %, %, %) (pd_object_input_invalid)',
      coalesce(v_object,'(null)'), coalesce(v_key,'(null)'), coalesce(v_actor,'(null)')
      using errcode = '22023';
  end if;

  select * into b from public.phase_d_business_object_binding where object_id = v_object;
  if not found then
    raise exception 'fn_phase_d_object_write: % is not a bound Phase D business object — fail closed rather than store a record under a policy nobody declared (pd_object_unbound)',
      v_object using errcode = '23503';
  end if;

  if v_payload is null or jsonb_typeof(v_payload) <> 'object' or v_payload = '{}'::jsonb then
    raise exception 'fn_phase_d_object_write: % sent payload of type %. An empty object is not evidence that anything was recorded. (pd_object_payload_empty)',
      v_object, coalesce(jsonb_typeof(v_payload),'null') using errcode = '22023';
  end if;

  if v_owner_ref is null then
    raise exception 'fn_phase_d_object_write: % is %-scoped and the call names no owner_ref. An unowned business record is the accountability gap this map exists to close. (pd_object_owner_missing)',
      v_object, b.ownership_scope using errcode = '22023';
  end if;

  -- ================= EXISTING TABLE: a real write, through the declared map =================
  if b.relation_kind = 'EXISTING_TABLE' then
    -- THE KERNEL'S OWN TABLES ARE NOT WRITABLE FROM HERE, AND THIS IS THE POINT OF THE BRANCH.
    -- workflow_run, workflow_step_run and handoff_record are created and moved by
    -- fn_kernel_step_complete. Two creators for one object is what deadlocked 16 of 30 workflows
    -- when workflow_start and step_complete both made the same handoff run; it is not repeated
    -- here because a handler asked politely.
    if b.governing_workflow_id = 'ALL' and v_object <> 'review_record' then
      raise exception 'fn_phase_d_object_write: % is written by the frozen kernel (%). A Phase D handler that wrote it would be a second creator for one object. Use fn_kernel_step_complete. (pd_object_kernel_owned)',
        v_object, b.canonical_relation using errcode = '23514';
    end if;

    select * into wm from public.phase_d_object_write_map where object_id = v_object;
    if not found then
      raise exception 'fn_phase_d_object_write: % is bound to existing relation % and no write map is declared for it. Refusing to guess a column layout. (pd_object_no_write_map)',
        v_object, b.canonical_relation using errcode = '23503';
    end if;

    -- The payload the caller actually sent, plus the four facts every write carries. state and
    -- owner_ref are named here so a map can point a column at either without the caller repeating
    -- them; nothing else is defaulted.
    -- H02 (1). NO STATE THE CALLER DID NOT STATE. An insert takes the relation's default and an
    -- update leaves the column alone; a stated state for a relation whose map carries no state
    -- column is refused rather than dropped on the floor.
    -- H09. A stated state the map cannot carry is reported on the return, not refused: review_record
    -- carries its verdict as content and has never had a state column.
    v_supplied := v_payload
                  || jsonb_build_object('owner_ref', v_owner_ref, 'business_key', v_key)
                  || case when v_state_given is null then '{}'::jsonb
                          else jsonb_build_object('state', v_state_given) end;

    -- D17. OUTBOUND SUPPRESSION, IN TEST CONTEXT ONLY, THROUGH EACH TRIGGER'S OWN GUARD.
    -- In production this loop does not run: a real Phase D handler dispatching a real inquiry is
    -- the intended behaviour and must not be suppressed. Under the Phase D hold the writer sets
    -- the product's own already-done marker, and a caller that supplied one keeps it.
    if v_testctx then
      for v_door in
        select d.guard_column, d.suppression_sql
          from public.phase_d_outbound_door d
         where d.relation = wm.target_relation
           and d.disposition = 'SUPPRESSED_BY_ITS_OWN_GUARD'
      loop
        -- D19. THE SUPPRESSION IS NOT DEFEASIBLE BY THE CALLER.
        --
        -- This was `if not (v_supplied ? guard_column)` — respect a value the caller supplied.
        -- Adding `routing` to the inquiry write map in D17 made the DRIVER's payload builder start
        -- generating a value for it, because it invents a typed value for every declared column.
        -- The generated jsonb carried no dispatched_at, the injection stood aside for it, and
        -- W05-S01 POSTed dispatch_inquiry again. A harness that generates a value for the key the
        -- guard reads is the same defect D9 recorded as "a generated fixture beat the real
        -- reference", and here it silently re-armed a door the writer had just closed.
        --
        -- Under the Phase D hold a caller does not get to opt out, so the writer overwrites. Both
        -- registered guard columns were measured as read by nothing: 0 rules, 0 gate contracts,
        -- 0 references in fn_rfq_score / fn_rfq_required_check. Overwriting them changes no
        -- decision any workflow makes; leaving them writable changes whether a POST leaves the
        -- database.
        execute format('select %s', v_door.suppression_sql) into v_door_val;
        v_supplied := v_supplied || jsonb_build_object(v_door.guard_column, v_door_val);
      end loop;
    end if;

    -- K02. AN ORPHAN IS REFUSED BY NAME. Where the object's binding declares a parent identity,
    -- the write map maps a column of that name, and this call supplies no value for it, the row
    -- about to be written belongs to nothing. Issuing it can only end in a silent BEFORE-trigger
    -- skip -- which is exactly how W12-S06 lost its effect -- or a foreign-key error two layers
    -- down. A NOT NULL column is left to the relation's own 23502; this covers the nullable ones,
    -- which is where the hole was.
    select wm.column_map->>b.parent_identity into v_parent_src
      from pg_attribute a
     where a.attrelid = wm.target_relation::regclass
       and a.attname = b.parent_identity and a.attnum > 0 and not a.attnotnull
       and coalesce(btrim(b.parent_identity),'') <> ''
       and wm.column_map ? b.parent_identity;
    if v_parent_src is not null
       and v_parent_src not in ('business_key','owner_ref','state')
       and (not (v_supplied ? v_parent_src) or v_supplied->v_parent_src = 'null'::jsonb) then
      raise exception 'fn_phase_d_object_write: % declares parent identity %, the write map reads it from payload key %, and this call supplies none. A % row that belongs to no % is not a business record. (pd_object_parent_missing)',
        v_object, b.parent_identity, v_parent_src, wm.target_relation, b.parent_identity
        using errcode = '23502';
    end if;

    for v_col in
      select k.key as col, wm.column_map->>k.key as src,
             format_type(a.atttypid, a.atttypmod) as ftype,
             (select typcategory from pg_type ty where ty.oid = a.atttypid) as tcat,
             a.attidentity, a.attgenerated
        from jsonb_each(wm.column_map) k
        join pg_attribute a
          on a.attrelid = wm.target_relation::regclass and a.attname = k.key and a.attnum > 0
       order by k.key
    loop
      -- A GENERATED ALWAYS identity or generated column cannot be written. The map validator
      -- excludes them from "required"; this excludes them from the statement.
      if v_col.attidentity = 'a' or v_col.attgenerated <> '' then continue; end if;
      if not (v_supplied ? v_col.src) then continue; end if;

      v_expr := case
        when v_col.ftype = 'jsonb' or v_col.ftype = 'json' then
          format('($1->%L)', v_col.src)
        when v_col.tcat = 'A' then
          format('(select coalesce(array_agg(x::text),''{}'')::%s from jsonb_array_elements_text($1->%L) x)',
                 v_col.ftype, v_col.src)
        else
          format('($1->>%L)::%s', v_col.src, v_col.ftype)
      end;
      v_cols := v_cols || quote_ident(v_col.col);
      v_vals := v_vals || v_expr;
      if v_col.col <> wm.key_column then
        v_sets := v_sets || format('%I = %s', v_col.col, v_expr);
      end if;
    end loop;

    if cardinality(v_cols) = 0 then
      raise exception 'fn_phase_d_object_write: % supplied no column the write map for % can use. Payload keys were %. (pd_object_payload_unmapped)',
        v_object, wm.target_relation,
        coalesce((select string_agg(k,', ' order by k) from jsonb_object_keys(v_supplied) k),'(none)')
        using errcode = '22023';
    end if;

    -- D17. The high-water mark, taken immediately before the write. Counting rows with a HIGHER id
    -- afterwards rather than differencing two counts is deliberate: pg_net's worker DELETES rows it
    -- has processed, so a plain count delta can be masked to zero by a concurrent drain and report
    -- silence over two real POSTs.
    if v_testctx then
      select coalesce(max(id),0) into v_net_max from net.http_request_queue;
    end if;

    -- K04. THE IDENTITY PROBE RUNS FOR AN INSERT TOO. An INSERT that would violate a unique
    -- index on values this call supplies is not a new record: it is the record that already exists.
    -- W16-S05 collided on reveal_invoices_pkey because operation INSERT skipped the probe entirely
    -- and the scenario had already issued the invoice for that transaction. For an INSERT the
    -- existing reference is returned and NOTHING is updated -- see the branch below -- so an
    -- immutable_revision object is never rewritten by a replay.
    if wm.operation in ('UPSERT_STATE', 'INSERT') then
      -- D18. AN UPSERT MUST LOOK FOR THE ROW IT WOULD WRITE, NOT FOR A DIFFERENT ONE.
      --
      -- This probe used to be `where key_column::text = business_key` unconditionally, which is
      -- only correct when the map points key_column at business_key. Two shapes broke on it:
      --
      --   supplier_capability  key_column = supplier_id, column_map.supplier_id = 'owner_ref'
      --                        -> probed supplier_id = <business key>, INSERTED supplier_id =
      --                           <owner ref>. It read one value and wrote another, so it could
      --                           never find its own row and the second write died on the pkey.
      --
      --   quotation / payment_transaction   key_column = id, a generated bigint
      --                        -> probed a bigint id against a uuid business key, never matched,
      --                           always inserted, and collided on the relation's NATURAL key
      --                           (quotes(inquiry_id,supplier_id), transactions(quote_id)).
      --
      -- Identity is now resolved in two derived passes and nothing is hand-listed:
      --   1. key_column, using THE VALUE THAT WILL BE WRITTEN INTO IT.
      --   2. failing that, any other unique index on the relation whose columns are ALL declared
      --      in the map and ALL supplied by this call — the row's natural key. The index's own
      --      predicate is carried through verbatim from pg_get_expr, so a PARTIAL unique index
      --      such as transactions(quote_id) WHERE quote_id IS NOT NULL is matched on exactly the
      --      rows it actually constrains rather than on a guess about what the predicate means.
      --
      -- Where neither pass resolves an identity the write stays an INSERT and a unique violation
      -- remains a real business duplicate. That is reported by fn_phase_d_object_identity_state()
      -- rather than papered over.
      v_existing := null;

      if wm.column_map ? wm.key_column then
        v_ident_val := v_supplied->>(wm.column_map->>wm.key_column);
        if v_ident_val is not null then
          v_sql := format('select %I::text from %s where %I::text = $1 limit 1',
                          wm.key_column, wm.target_relation, wm.key_column);
          execute v_sql into v_existing using v_ident_val;
        end if;
      end if;

      -- H02 (2). THE CALLER'S KEY IS THE RELATION'S KEY when the map writes no key column: probe it
      -- as text, which matches nothing when the shapes differ and the row when they do not.
      if v_existing is null and not (wm.column_map ? wm.key_column) then
        begin
          v_sql := format('select %I::text from %s where %I::text = $1 limit 1',
                          wm.key_column, wm.target_relation, wm.key_column);
          execute v_sql into v_existing using v_key;
        exception when others then
          v_existing := null;
        end;
      end if;

      if v_existing is null then
        for v_uq in
          select ic.relname as idx_name,
                 array_agg(a.attname::text order by a.attnum) as cols,
                 min(pg_get_expr(i.indpred, i.indrelid)) as pred
            from pg_index i
            join pg_class ic on ic.oid = i.indexrelid
            join pg_attribute a on a.attrelid = i.indrelid and a.attnum = any(i.indkey)
           where i.indrelid = wm.target_relation::regclass
             and i.indisunique
           group by ic.relname, i.indexrelid
           order by ic.relname
        loop
          -- an index on exactly the key column is pass 1's job, and it already ran
          continue when v_uq.cols = array[wm.key_column];
          continue when not (select bool_and(wm.column_map ? c) from unnest(v_uq.cols) c);
          continue when not (select bool_and(v_supplied ? (wm.column_map->>c)) from unnest(v_uq.cols) c);
          continue when exists (select 1 from unnest(v_uq.cols) c
                                 where v_supplied->>(wm.column_map->>c) is null);

          select string_agg(format('%I::text = ($1->>%L)', c, wm.column_map->>c), ' and ')
            into v_where from unnest(v_uq.cols) c;
          if v_uq.pred is not null then
            v_where := v_where || ' and (' || v_uq.pred || ')';
          end if;

          v_sql := format('select %I::text from %s where %s limit 1',
                          wm.key_column, wm.target_relation, v_where);
          execute v_sql into v_existing using v_supplied;
          exit when v_existing is not null;
        end loop;
      end if;
      if v_existing is not null then
        -- K04. AN INSERT NEVER UPDATES WHAT IT FOUND. The row already exists under the identity
        -- this call carries; that is the declared completion condition met, not a second record and
        -- not a rewrite of the first.
        if wm.operation = 'INSERT' or cardinality(v_sets) = 0 then
          -- H02 (3). The row already carries everything this call asked for. That is the declared
          -- completion condition of an OBJECT_STATE_WRITE met, not a transition refused: the
          -- existing reference is returned, nothing is written, and unchanged = true says so.
          v_unchanged := true;
          v_result_ref := v_existing;
        end if;
        -- D18. Update the row the probe actually FOUND. Re-deriving the target from business_key
        -- here would reintroduce the same mismatch one statement later: the natural-key probe can
        -- resolve a row whose key_column value equals neither the business key nor anything in the
        -- payload.
        if not v_unchanged then
          v_sql := format('update %s set %s where %I::text = $2 returning %I::text',
                          wm.target_relation, array_to_string(v_sets, ', '),
                          wm.key_column, wm.key_column);
          execute v_sql into v_result_ref using v_supplied, v_existing;
        end if;
      else
        v_sql := format('insert into %s (%s) values (%s) returning %I::text',
                        wm.target_relation, array_to_string(v_cols, ', '),
                        array_to_string(v_vals, ', '), wm.key_column);
        execute v_sql into v_result_ref using v_supplied;
      end if;
    else
      v_sql := format('insert into %s (%s) values (%s) returning %I::text',
                      wm.target_relation, array_to_string(v_cols, ', '),
                      array_to_string(v_vals, ', '), wm.key_column);
      execute v_sql into v_result_ref using v_supplied;
    end if;

    -- A NULL RETURN IS NOT A WRITE. A BEFORE trigger returning NULL gives a statement that
    -- "succeeded" with no row; the returned key is what separates the two.
    if v_result_ref is null then
      -- K05. NAME THE GATE THAT REFUSED. A BEFORE trigger returning null gives a statement that
      -- "succeeded" with no row, and this message used to report only the silence -- which is how
      -- W12-S06's cause was recorded wrongly in the 23 Aug hand-over. Where the refusing gate
      -- published a verdict, it is quoted here.
      raise exception 'fn_phase_d_object_write: the write to % for % returned no key. Refusing to report a write that produced nothing. Gate verdict: % — %. (pd_object_write_produced_nothing)',
        wm.target_relation, v_object,
        coalesce(nullif(current_setting('app.inquiry_match_gate_verdict', true),''), '(no gate published a verdict)'),
        coalesce(nullif(current_setting('app.inquiry_match_gate_reason', true),''), 'no reason was published')
        using errcode = '23502';
    end if;

    -- D17. THE ASSERTION. A Phase D test write may not leave an outbound request behind it.
    if v_testctx then
      -- WHOSE REQUEST IS IT. This counted every row above an id watermark, so a request enqueued
      -- by ANY concurrent transaction was attributed to this write. Measured 23 Aug 2026: the
      -- step-coverage drive failed with "writing inquiry to public.inquiries enqueued 2 outbound
      -- HTTP request(s): POST .../dropbox_backup, POST .../uptime_check" -- and neither came from
      -- the write. cron.job 88 (dropbox_backup_scan) and 35 (uptime_check_15min) both run
      -- */15 * * * *, they commit while a Phase D transaction is open, and READ COMMITTED then
      -- shows their rows to the next statement here. A drive that fails four times an hour, on the
      -- quarter hour, because a scheduled job ran is an instrument reporting on the wrong subject.
      -- The requests are attributed to this transaction now; see the helper for how.
      select r.n, r.urls into v_net_new, v_net_urls
        from public.fn_phase_d_outbound_requests_by_this_transaction(v_net_max) r;
      if coalesce(v_net_new,0) > 0 then
        raise exception 'fn_phase_d_object_write: writing % to % enqueued % outbound HTTP request(s): %. A Phase D test write may not leave an outbound request behind it. (pd_object_outbound_request_produced)',
          v_object, wm.target_relation, v_net_new, v_net_urls using errcode = '23514',
          hint = 'A trigger on this relation calls net.http_post. Register it in public.phase_d_outbound_door with the product''s own already-done guard column, or explain why the request is legitimate under the hold.';
      end if;
    end if;

    return jsonb_build_object(
      'ok', true, 'object_id', v_object, 'relation_kind', 'EXISTING_TABLE',
      'canonical_relation', wm.target_relation, 'operation', wm.operation,
      'result_reference', format('%s:%s=%s', wm.target_relation, wm.key_column, v_result_ref),
      -- F44. THE CANONICAL REFERENCE, RETURNED BY THE WRITER ITSELF.
      -- Which identity is canonical for this object is a property of the object, recorded once in
      -- public.phase_d_object_reference_strategy and derived from the frozen 56-object map. For an
      -- EXISTING_TABLE object it is the relation's own primary key -- the value this write just
      -- produced -- and every caller downstream now takes it from here rather than choosing.
      'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
                         'object_id', v_object, 'identity', v_result_ref,
                         'owner_ref', v_owner_ref)),
      'business_key', v_key, 'state', v_state_given,
      'policy_family', b.policy_family, 'record_policy', b.record_policy,
      'owner_scope', b.ownership_scope, 'owner_ref', v_owner_ref,
      'columns_written', case when v_unchanged then '[]'::jsonb else to_jsonb(v_cols) end,
      'unchanged', v_unchanged,
      'state_carried_by_relation', (v_state_given is null
         or exists (select 1 from jsonb_each_text(wm.column_map) k where k.value = 'state')),
      'outbound_requests_enqueued', coalesce(v_net_new, 0),
      'quarantine_note', wm.quarantine_note,
      'payload_digest', encode(sha256(convert_to(v_payload::text,'UTF8')),'hex'));
  end if;

  -- ================= PHASE D STORE: unchanged behaviour from D2 =================
  select * into v_prior from public.phase_d_object_record
   where object_id = v_object and business_key = v_key and superseded_by is null
   order by version desc limit 1;

  if found then
    if b.policy_family = 'APPEND_ONLY' then
      raise exception 'fn_phase_d_object_write: % is APPEND_ONLY (%) and business key % already holds record %. A correction is a NEW key, never a second version of this one. (pd_object_append_only)',
        v_object, b.record_policy, v_key, v_prior.record_id using errcode = '23514';
    end if;
    -- D27. "MOVE ITS STATE" — AND THE WRITER OFFERED NO WAY TO MOVE IT.
    --
    -- This refusal told the caller to move the record's state instead of writing a second, and then
    -- returned before anything could. In the store branch it governs exactly ONE object:
    --
    --     dispatch_batch   PHASE_D_OBJECT_VIEW   TRANSACTION_RECORD
    --
    -- payment_transaction, reveal_transaction and supplier_assignment are the other three
    -- TRANSACTION_RECORDs and all three are EXISTING_TABLE, so they never reach this branch — their
    -- second write is an UPSERT_STATE that moves the row, which is exactly what this text asks for.
    --
    -- And the frozen registry writes dispatch_batch at FIVE successive steps of W12:
    --     S01 Accept dispatch-ready package        INTAKE_HANDLER
    --     S02 Build eligible supplier pool         ANALYSIS_HANDLER
    --     S03 Apply fairness and capacity policy   ANALYSIS_HANDLER
    --     S04 Review policy exception if needed    REVIEW_HANDLER
    --     S08 Record selection and exclusion evidence  EXECUTION_HANDLER
    --
    -- A batch that is accepted, then built, then policy-applied, then reviewed, then evidenced. Five
    -- writes to one identity is the DESIGN, so a rule refusing the second could never be satisfied
    -- by the workflow that owns the object. That is a misclassification meeting a missing mechanism,
    -- not a business constraint doing its job.
    --
    -- ONE RECORD PER IDENTITY IS PRESERVED, and that is the part that must not be lost. The move is
    -- a superseding version, the same mechanism VERSIONED, IMMUTABLE_REVISION, CASE_RECORD and
    -- MUTABLE_CONTROLLED already use: the prior row is retained and marked superseded, so after five
    -- writes there is exactly ONE current record and four retained predecessors. Nothing is
    -- overwritten in place, which matters because Phase B's frozen mutation_rule for this object is
    -- "immutable selection evidence" — history is evidence.
    --
    -- THE REFUSAL IS KEPT, NARROWED TO WHAT IT CAN ACTUALLY MEAN: a repeat that moves nothing. The
    -- EXISTING_TABLE branch already refuses on exactly that ground — "a write that changes nothing
    -- is not a state transition" — so the two branches now agree about one family instead of giving
    -- it opposite answers. record_policy is FROZEN Phase B and is untouched; policy_family is Phase
    -- D's own fold and is also untouched. Only the writer's behaviour changes.
    if b.policy_family = 'TRANSACTION_RECORD'
       and v_prior.state is not distinct from v_state
       and v_prior.payload = v_payload then
      raise exception 'fn_phase_d_object_write: % is a %-family record and business key % already exists as record % with the same state and payload. One record per identity; move its state, do not write a second. (pd_object_duplicate_identity)',
        v_object, b.policy_family, v_key, v_prior.record_id using errcode = '23505';
    end if;
    v_version := v_prior.version + 1;
  end if;

  insert into public.phase_d_object_record
    (object_id, business_key, version, state, owner_scope, owner_ref, payload,
     run_id, step_run_id, trace_id, created_by)
  values (v_object, v_key, v_version, v_state, b.ownership_scope, v_owner_ref, v_payload,
          nullif(p_input->>'run_id','')::bigint, nullif(p_input->>'step_run_id','')::bigint,
          nullif(p_input->>'trace_id','')::bigint, v_actor)
  returning record_id into v_id;

  if v_id is null then
    raise exception 'fn_phase_d_object_write: the insert for % / % returned no record_id. Refusing to report a write that produced nothing. (pd_object_write_produced_nothing)',
      v_object, v_key using errcode = '23502';
  end if;
  select * into v_readback from public.phase_d_object_record where record_id = v_id;
  if not found then
    raise exception 'fn_phase_d_object_write: record % is not readable back in the same transaction. (pd_object_write_not_readable)',
      v_id using errcode = '23502';
  end if;

  if v_prior.record_id is not null
     -- D27. TRANSACTION_RECORD joins the supersede list so that "one record per identity" stays
     -- literally true: the prior version is retained and marked superseded, never left as a second
     -- live record alongside the new one.
     and b.policy_family in ('VERSIONED','IMMUTABLE_REVISION','CASE_RECORD','MUTABLE_CONTROLLED','TRANSACTION_RECORD') then
    update public.phase_d_object_record
       set superseded_by = v_id, superseded_at = now()
     where record_id = v_prior.record_id;
  end if;

  return jsonb_build_object(
    'ok', true, 'object_id', v_object, 'relation_kind', 'PHASE_D_OBJECT_VIEW',
    'record_id', v_id, 'business_key', v_key,
    'result_reference', format('public.phase_d_object_record:record_id=%s', v_id),
    -- F44. For a PHASE_D_STORE object the canonical identity is object_id + business_key + version.
    -- record_id stays in the envelope as the physical detail it is, never as the identity.
    'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
                       'object_id', v_object, 'identity', v_key,
                       'version', v_version::text, 'owner_ref', v_owner_ref)),
    'version', v_version, 'state', v_readback.state,
    'policy_family', b.policy_family, 'record_policy', b.record_policy,
    'owner_scope', b.ownership_scope, 'owner_ref', v_owner_ref,
    'canonical_relation', b.canonical_relation,
    'superseded_record_id', v_prior.record_id,
    'payload_digest', encode(sha256(convert_to(v_payload::text,'UTF8')),'hex'));
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_outbound_requests_by_this_transaction(p_after bigint)
 RETURNS TABLE(n integer, urls text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- The 64-bit id carries the epoch; the 32-bit form is what a row's xmin holds.
  v_top8  bigint := pg_current_xact_id()::text::bigint;
  v_top32 bigint := mod(pg_current_xact_id()::text::bigint, 4294967296);
begin
  return query
  select count(*)::int,
         string_agg(distinct q.method || ' ' || q.url, ', ')
    from net.http_request_queue q
   where q.id > p_after
     -- Anything below our own xid was written before this transaction started and cannot be ours.
     -- Filtering it first also fixes the epoch for the conversion on the next line.
     and q.xmin::text::bigint >= v_top32
     -- A visible row whose writer is still in progress is ours: another in-flight transaction's
     -- rows are not visible here at all, and a committed one reports 'committed'.
     and pg_xact_status(((v_top8 - v_top32) + q.xmin::text::bigint)::text::xid8) = 'in progress';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_package_revisions_dispatchable(p_package_ref text)
 RETURNS TABLE(dispatchable boolean, refusal_code text, reason text, revisions bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_bad record; v_n bigint := 0; v_ref text; v_keys text[];
begin
  v_ref := btrim(coalesce(p_package_ref,''));

  -- EVERY SHAPE THIS ONE PACKAGE IS KNOWN BY, not the first that matches. The ref itself is always
  -- one of them, so a package whose revisions were registered directly under the ref the caller
  -- holds still resolves even when it is not an object record at all.
  select array_agg(distinct k) into v_keys from (
    select v_ref as k
    union all
    select o.business_key from public.phase_d_object_record o
     where o.object_id = 'supplier_safe_package'
       and (o.record_id::text = v_ref
            or o.business_key = v_ref
            or 'supplier_safe_package:' || o.business_key = v_ref)
    union all
    select o.record_id::text from public.phase_d_object_record o
     where o.object_id = 'supplier_safe_package'
       and (o.record_id::text = v_ref
            or o.business_key = v_ref
            or 'supplier_safe_package:' || o.business_key = v_ref)
  ) x where coalesce(btrim(k),'') <> '';

  for r in select fr.revision_ref from public.phase_d_file_revision fr
            where fr.package_ref = any(v_keys) and fr.superseded_by is null
            order by fr.revision_ref loop
    v_n := v_n + 1;
    select * into v_bad from public.fn_phase_d_file_revision_dispatchable(r.revision_ref);
    if not v_bad.dispatchable then
      dispatchable := false; refusal_code := v_bad.refusal_code; reason := v_bad.reason;
      revisions := v_n; return next; return;
    end if;
  end loop;
  revisions := v_n;
  if v_n = 0 then
    -- A PACKAGE THAT NAMES NO FILE IS NOT A CLEAN PACKAGE. Zero here would otherwise be the shape
    -- this estate has been caught by twice: an absent input scoring as satisfied.
    dispatchable := false; refusal_code := 'pd_revision_redaction_state_absent';
    reason := format('package %s names no registered file revision under any of the %s identit(ies) it resolves to. An empty file set is not an approved one.',
                     p_package_ref, coalesce(cardinality(v_keys),0));
    return next; return;
  end if;
  dispatchable := true; refusal_code := null;
  reason := format('package %s: all %s live revision(s) are redaction-approved and metadata-clean.',
                   p_package_ref, v_n);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_quote_original_intact(p_revision_ref text)
 RETURNS TABLE(intact boolean, refusal_code text, reason text, normalisations bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_live text; v_n bigint; v_bad bigint; v_ref text; v_key text;
begin
  v_ref := btrim(coalesce(p_revision_ref,''));
  if v_ref = '' then
    intact := false; refusal_code := 'pd_quote_revision_not_named';
    reason := 'No supplier revision named. Nothing can be certified unedited against nothing.';
    normalisations := 0; return next; return;
  end if;

  -- THE SAME KEY IN TWO SHAPES. A caller holding the record id and a caller holding the business
  -- key are asking about one row, and a predicate that knows only one of them invents a hole.
  select o.business_key,
         encode(extensions.digest(convert_to(o.payload::text, 'UTF8'), 'sha256'), 'hex')
    into v_key, v_live
    from public.phase_d_object_record o
   where o.object_id = 'quotation_revision' and o.superseded_by is null
     and (o.business_key = v_ref
          or o.record_id::text = v_ref
          or 'quotation_revision:' || o.business_key = v_ref)
   order by o.record_id desc limit 1;

  if v_live is null then
    intact := false; refusal_code := 'pd_quote_revision_not_named';
    reason := format('%L resolves to no live quotation_revision record, by business key or by record id.', p_revision_ref);
    normalisations := 0; return next; return;
  end if;

  -- Normalisations may cite either shape too, so both are counted.
  select count(*), count(*) filter (where n.source_payload_sha256 is distinct from v_live)
    into v_n, v_bad
    from public.phase_d_quote_normalisation n
   where n.source_revision_ref in (v_key, v_ref) and n.superseded_by is null;
  normalisations := v_n;

  if v_bad > 0 then
    intact := false; refusal_code := 'pd_quote_original_overwritten';
    reason := format('%s of %s live normalisation(s) of %s were derived from a payload that hashes to something other than the revision''s current %s. Either the original was edited after normalisation, or the projection is describing a revision that no longer exists.',
                     v_bad, v_n, v_key, left(v_live, 12));
    return next; return;
  end if;

  intact := true; refusal_code := null;
  reason := format('%s is unedited at %s and carries %s live normalised projection(s), none of which restates a supplier-authored field.',
                   v_key, left(v_live, 12), v_n);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_recorded_review(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
  select jsonb_strip_nulls(jsonb_build_object(
           'task_id', t.task_id,
           'reviewer_role_id', nullif(btrim(coalesce(t.reviewer_role_id,'')),''),
           'verdict', (select ev->>'review_decision'
                         from public.phase_c_trace tr,
                              lateral jsonb_array_elements(
                                case when jsonb_typeof(coalesce(tr.evidence_refs,'[]'::jsonb)) = 'array'
                                     then tr.evidence_refs else '[]'::jsonb end) ev
                        where tr.task_id = t.task_id
                          and ev ? 'review_decision'
                        order by tr.trace_id desc
                        limit 1)))
    from public.phase_c_workflow_step_run sr
    join public.phase_c_task t
      on t.run_id = sr.run_id and t.step_id = sr.step_id
   where sr.step_run_id = p_step_run_id
   order by t.task_id desc
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_ref(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  s        public.phase_d_object_reference_strategy%rowtype;
  b        public.phase_d_business_object_binding%rowtype;
  v_obj    text := nullif(btrim(coalesce(p_input->>'object_id','')),'');
  v_ident  text := nullif(btrim(coalesce(p_input->>'identity','')),'');
  v_ver    int  := nullif(btrim(coalesce(p_input->>'version','')),'')::int;
  v_owner  text := nullif(btrim(coalesce(p_input->>'owner_ref','')),'');
begin
  if v_obj is null then
    raise exception 'fn_phase_d_ref: object_id is required (pd_ref_unknown_object)'
      using errcode = '22023';
  end if;

  select * into s from public.phase_d_object_reference_strategy where object_id = v_obj;
  if not found then
    raise exception 'fn_phase_d_ref: % is not one of the 56 frozen business objects, so no reference strategy exists for it (pd_ref_unknown_object)',
      v_obj using errcode = '23503';
  end if;
  select * into b from public.phase_d_business_object_binding where object_id = v_obj;

  -- THE IDENTITY IS REQUIRED AND IS NEVER INVENTED. A reference with no identity is the defect this
  -- whole contract exists to remove: it is what let a resolver pick whichever key was nearest.
  if v_ident is null then
    raise exception 'fn_phase_d_ref: % needs an identity (%). A reference with no identity is not a reference. (pd_ref_unresolved)',
      v_obj,
      case s.canonical_identity_type
        when 'OBJECT_ID_BUSINESS_KEY_VERSION' then 'its business key'
        else 'its ' || s.physical_relation || '.' || s.physical_pk_column end
      using errcode = '22023';
  end if;

  -- F46. ONE FIELD THAT ALWAYS HOLDS THE IDENTITY, WHATEVER THE STORAGE KIND.
  --
  -- The round-trip proof of section 2 found this on its first run, which is what it is for. The
  -- envelope carried the identity in physical_ref.pk_value on the way IN and the physical row id in
  -- the same field on the way OUT, because for a PHASE_D_STORE object those are different things:
  -- the identity is object_id + business_key + version, and the physical row is
  -- phase_d_object_record.record_id, which nobody knows until the object is resolved. Three of seven
  -- round trips compared the two and reported "wrong identity" on objects that had resolved
  -- perfectly.
  --
  -- canonical_identity is now the single field every consumer reads. It is the business key for a
  -- PHASE_D_STORE object and the relation's primary key for the other two kinds, and no caller has
  -- to know which -- that is the whole point of recording the strategy once. physical_ref now
  -- describes where the object physically lives and carries pk_value only when the caller actually
  -- knows it; for the store it is filled in by fn_phase_d_ref_resolve.
  return jsonb_strip_nulls(jsonb_build_object(
    'object_id',          v_obj,
    'storage_kind',       s.storage_kind,
    'canonical_identity', v_ident,
    'business_key',       v_ident,
    'version',            coalesce(v_ver, 1),
    'physical_ref', jsonb_build_object(
                      'schema',    s.physical_schema,
                      'relation',  case when s.storage_kind = 'PHASE_D_STORE'
                                        then 'phase_d_object_record' else s.physical_relation end,
                      'pk_column', case when s.storage_kind = 'PHASE_D_STORE'
                                        then 'record_id' else s.physical_pk_column end,
                      'pk_value',  case when s.storage_kind = 'PHASE_D_STORE'
                                        then null else v_ident end),
    'owner_scope',  b.ownership_scope,
    'owner_ref',    v_owner,
    'source_object_ref', p_input->'source_object_ref',
    'trace_id',     nullif(btrim(coalesce(p_input->>'trace_id','')),''),
    'fixture_run_id', nullif(btrim(coalesce(p_input->>'fixture_run_id','')),'')::bigint));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_ref_resolve(p_ref jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  s       public.phase_d_object_reference_strategy%rowtype;
  v_obj   text := nullif(btrim(coalesce(p_ref->>'object_id','')),'');
  -- F46. canonical_identity first: it is the one field that always holds the identity. The other
  -- two are read only for an envelope built before F46, and physical_ref.pk_value is deliberately
  -- LAST because for a PHASE_D_STORE object it is the physical row, not the identity.
  v_key   text := nullif(btrim(coalesce(p_ref->>'canonical_identity',
                                        p_ref->>'business_key',
                                        p_ref->'physical_ref'->>'pk_value','')),'');
  v_ver   int  := nullif(btrim(coalesce(p_ref->>'version','')),'')::int;
  v_n     int;
  v_rec   record;
  v_sql   text;
begin
  if v_obj is null or v_key is null then
    raise exception 'fn_phase_d_ref_resolve: a reference must name an object_id and an identity; got % / % (pd_ref_unresolved)',
      coalesce(v_obj,'(none)'), coalesce(v_key,'(none)') using errcode = '22023';
  end if;

  select * into s from public.phase_d_object_reference_strategy where object_id = v_obj;
  if not found then
    raise exception 'fn_phase_d_ref_resolve: % is not one of the 56 frozen business objects (pd_ref_unknown_object)',
      v_obj using errcode = '23503';
  end if;

  if s.storage_kind = 'PHASE_D_STORE' then
    -- THE VERSION IS PART OF THE IDENTITY. With no version the live one is the record that has not
    -- been superseded; with a version it is that version exactly, superseded or not, because
    -- evidence about what was approved must stay readable after a later revision.
    if v_ver is null then
      select count(*) into v_n from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and superseded_by is null;
    else
      select count(*) into v_n from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and version = v_ver;
    end if;

    if v_n = 0 then
      raise exception 'fn_phase_d_ref_resolve: % / % %resolves to no record in public.phase_d_object_record (pd_ref_unresolved)',
        v_obj, v_key, case when v_ver is null then '' else 'version ' || v_ver || ' ' end
        using errcode = '23503';
    elsif v_n > 1 then
      raise exception 'fn_phase_d_ref_resolve: % / % %resolves to % records; a reference must name exactly one (pd_ref_ambiguous)',
        v_obj, v_key, case when v_ver is null then '' else 'version ' || v_ver || ' ' end, v_n
        using errcode = '23505';
    end if;

    if v_ver is null then
      select record_id, business_key, version, state, owner_scope, owner_ref, trace_id
        into v_rec from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and superseded_by is null;
    else
      select record_id, business_key, version, state, owner_scope, owner_ref, trace_id
        into v_rec from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and version = v_ver;
    end if;

    return jsonb_build_object(
      'ok', true, 'object_id', v_obj, 'storage_kind', s.storage_kind,
      'canonical_identity', v_rec.business_key,
      'business_key', v_rec.business_key, 'version', v_rec.version, 'state', v_rec.state,
      'owner_scope', v_rec.owner_scope, 'owner_ref', v_rec.owner_ref,
      'trace_id', v_rec.trace_id,
      'physical_ref', jsonb_build_object('schema','public','relation','phase_d_object_record',
                                         'pk_column','record_id','pk_value', v_rec.record_id::text));
  end if;

  -- EXISTING_TABLE and KERNEL_OWNED: the relation's own primary key, compared as text so a uuid, a
  -- bigint and a natural key all work without the caller having to know which it is.
  v_sql := format('select count(*) from %I.%I where %I::text = $1',
                  s.physical_schema, s.physical_relation, s.physical_pk_column);
  execute v_sql into v_n using v_key;

  if v_n = 0 then
    raise exception 'fn_phase_d_ref_resolve: % / % resolves to no row in %.% by % (pd_ref_unresolved)',
      v_obj, v_key, s.physical_schema, s.physical_relation, s.physical_pk_column
      using errcode = '23503';
  elsif v_n > 1 then
    raise exception 'fn_phase_d_ref_resolve: % / % resolves to % rows in %.%; a reference must name exactly one (pd_ref_ambiguous)',
      v_obj, v_key, v_n, s.physical_schema, s.physical_relation
      using errcode = '23505';
  end if;

  return jsonb_build_object(
    'ok', true, 'object_id', v_obj, 'storage_kind', s.storage_kind,
    'canonical_identity', v_key,
    'business_key', v_key, 'version', coalesce(v_ver, 1),
    'physical_ref', jsonb_build_object('schema', s.physical_schema, 'relation', s.physical_relation,
                                       'pk_column', s.physical_pk_column, 'pk_value', v_key));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_reveal_permitted(p_transaction_id text)
 RETURNS TABLE(permitted boolean, state_key text, rung integer, reason text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.transactions%rowtype; s public.phase_d_payment_state%rowtype; v_raw text;
begin
  select * into t from public.transactions where id::text = p_transaction_id;
  if not found then
    permitted := false; state_key := 'no_transaction'; rung := 0;
    reason := format('BR-020: no transaction %s. A reveal with no transaction is not an edge case, it is the whole defect.', coalesce(p_transaction_id,'(null)'));
    return next; return;
  end if;

  v_raw := lower(btrim(coalesce(t.fee_status, '')));
  if v_raw = '' then
    permitted := false; state_key := 'unstated'; rung := 0;
    reason := 'BR-020: transaction carries no fee_status. An absent payment state is not a paid one.';
    return next; return;
  end if;

  -- The table is ALIASED and the column QUALIFIED. This function's OUT parameter is also named
  -- state_key, and an unqualified reference resolves to the plpgsql variable rather than the
  -- column. Postgres refuses that as ambiguous instead of silently choosing, which is the good
  -- outcome — but only once it is written correctly.
  select * into s from public.phase_d_payment_state ps where ps.state_key = v_raw;
  if not found then
    -- FAIL CLOSED. An unrecognised value is not mapped to the nearest rung and not assumed paid.
    permitted := false; state_key := v_raw; rung := 0;
    reason := format('BR-020: fee_status %s is not a declared payment state. Refusing rather than guessing which rung it means.', v_raw);
    return next; return;
  end if;

  if not s.authorizes_reveal then
    permitted := false; state_key := s.state_key; rung := s.rung;
    reason := format('BR-020: transaction is at rung %s (%s) and reveal requires payment_reconciled at rung 5. %s',
                     s.rung, s.state_key, s.why);
    return next; return;
  end if;

  -- Reconciled is claimed. The claim must carry the two facts that make it one.
  if coalesce(btrim(t.payment_ref),'') = '' then
    permitted := false; state_key := s.state_key; rung := s.rung;
    reason := 'BR-020: the transaction claims a reconciled state with no payment_ref. A reconciliation with nothing to reconcile against is a label.';
    return next; return;
  end if;
  if t.reveal_fee is null then
    permitted := false; state_key := s.state_key; rung := s.rung;
    reason := 'BR-020: the transaction claims a reconciled state with a null reveal_fee. A null amount is an unmeasured amount, not a settled one.';
    return next; return;
  end if;

  permitted := true; state_key := s.state_key; rung := s.rung;
  reason := format('BR-020: transaction %s is at rung %s (%s) with payment_ref and a stated reveal_fee.',
                   t.id, s.rung, s.state_key);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_rule_applies(p_rule_id text, p_step_id text)
 RETURNS TABLE(applies boolean, why text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r public.phase_b_business_rule%rowtype;
  s public.phase_b_workflow_step%rowtype;
  e public.phase_d_rule_enforcement%rowtype;
  v_in_scope boolean;
  v_governs text;
  v_primary text;
  v_producer text;   -- K06
  v_prod_no  int;          -- L02
  v_subjects text[];       -- L02
  v_needs_identity boolean; -- L02
begin
  select * into r from public.phase_b_business_rule where rule_id = p_rule_id;
  if not found then
    applies := false; why := format('unknown rule %L', p_rule_id); return next; return;
  end if;
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then
    applies := false; why := format('unknown step %L', p_step_id); return next; return;
  end if;
  select * into e from public.phase_d_rule_enforcement where rule_id = p_rule_id;

  -- 1. WORKFLOW SCOPE, from the frozen registry.
  v_in_scope := (lower(r.workflow_scope) = 'all'
                 or s.workflow_id = any (string_to_array(replace(r.workflow_scope,' ',''), ';')));
  if not v_in_scope then
    applies := false;
    why := format('%s is scoped to %s and %s is in %s', r.rule_id, r.workflow_scope, p_step_id, s.workflow_id);
    return next; return;
  end if;

  -- 2. STEP-LEVEL APPLICABILITY. Scope is not applicability, and conflating the two is what made
  --    the first executor refuse an intake step for a creator/reviewer collision.
  if p_rule_id in ('BR-002','BR-030','BR-031','BR-037','BR-038') then
    if coalesce(btrim(s.independent_reviewer_role_id),'') = '' then
      applies := false;
      why := format('%s governs the independence of a named reviewer and %s names none', r.rule_id, p_step_id);
      return next; return;
    end if;
  end if;

  if p_rule_id = 'BR-003' then
    if lower(coalesce(btrim(s.founder_gate),'none')) = 'none' then
      applies := false;
      why := format('BR-003 governs founder-reserved decisions and %s declares founder_gate none', p_step_id);
      return next; return;
    end if;
  end if;

  if p_rule_id = 'BR-009' and not coalesce(s.is_closure_step,false) then
    applies := false;
    why := format('BR-009 is a closure rule and %s is not the closure step', p_step_id);
    return next; return;
  end if;

  if p_rule_id = 'BR-042' and s.step_type <> 'analysis' then
    applies := false;
    why := format('BR-042 governs analysis output and %s is a %s step', p_step_id, s.step_type);
    return next; return;
  end if;

  if p_rule_id = 'BR-040' and s.step_type <> 'measurement' then
    applies := false;
    why := format('BR-040 governs metric definition and %s is a %s step', p_step_id, s.step_type);
    return next; return;
  end if;

  if p_rule_id = 'BR-044'
     and not exists (select 1 from public.phase_b_handoff h where h.from_step_id = p_step_id) then
    applies := false;
    why := format('BR-044 governs a step that opens a handoff and %s opens none', p_step_id);
    return next; return;
  end if;

  -- D50. BR-008 governs the CONTENTS OF A HANDOFF PACKET, so it can only apply to a step that opens
  -- one. Until D47 it fell through to ENFORCED_PASS and could not fail; giving it a real predicate
  -- without giving it this applicability rule turned it into the opposite defect — it refused 29 of
  -- the 30 workflows' first steps for not carrying a packet no handoff had asked for. The condition
  -- is the same one BR-044 already uses, and it is used here for the same reason.
  if p_rule_id = 'BR-008'
     and not exists (select 1 from public.phase_b_handoff h where h.from_step_id = p_step_id) then
    applies := false;
    why := format('BR-008 governs the packet a handoff carries and %s opens no handoff', p_step_id);
    return next; return;
  end if;

  -- 3. A RULE DOES NOT GOVERN THE WORKFLOW THAT PRODUCES ITS SUBJECT.
  if e.required_context is not null and cardinality(e.required_context) > 0 then
    -- L02 (1). A CONTEXT KEY CAN NAME MORE THAN ONE OBJECT AND `limit 1` INVENTED AN ANSWER FOR IT.
    -- terms_version and terms_hash are facts about the customer acceptance AND about the supplier
    -- acceptance. Resolving the rule's subject to whichever row came first is the "a key written in
    -- two shapes" defect, so every register that maps a context key to an object is asked and the
    -- whole set is kept.
    select array_agg(distinct o) into v_subjects from (
      select st.object_id o from public.phase_d_fixture_stage st
       where st.contributes_ref = any(e.required_context)
      union
      select k.object_id o from public.phase_d_context_key_object k
       where k.context_key = any(e.required_context)) z;
    if v_subjects is not null and cardinality(v_subjects) > 0 then
      -- K06. A WORKFLOW PRODUCES MORE THAN ITS PRIMARY OBJECT. This compared the rule's subject
      -- with phase_b_workflow.primary_object alone, so BR-018 asked W14 to already hold the
      -- quotation revision W14 exists to produce, and BR-032 asked W16 to already hold the provider
      -- event W16-S03 receives. The producing step is read from the frozen effect registry; the
      -- primary object is still reported in the reason when it is the one that matched.
      select w.primary_object into v_primary
        from public.phase_b_workflow w where w.workflow_id = s.workflow_id;
      if v_primary is not null and v_primary = any(v_subjects) then
        applies := false;
        why := format('%s governs %s and %s is the workflow whose primary object that is; the rule guards its use downstream, not its creation',
                      r.rule_id, v_primary, s.workflow_id);
        return next; return;
      end if;

      -- L02 (2). NOT A WHOLE-WORKFLOW EXEMPTION. K06 removed the rule from EVERY step of the
      -- producing workflow. K07, written the same day for gates, had already recorded why that
      -- shape is wrong and had already written the right one:
      --
      --     before the producing step  -- every gate. The subject does not exist yet and cannot.
      --     AT the producing step      -- only where the test is the PRESENCE of the subject.
      --     a MEASURED predicate       -- untouched: it exists to judge the creating step.
      --
      -- BR-025 is the rule that made the difference visible. Its scope is W04;W09, W09-S06 is the
      -- only step in the estate that produces a supplier terms acceptance, and its own frozen
      -- completion condition is "Displayed version, recorded version and document hash match" --
      -- so a whole-workflow exemption of W09 leaves nothing anywhere asking whether a SUPPLIER
      -- acceptance names its exact terms. That is a repeal, not an exemption.
      --
      -- WHICH OF THE TWO A RULE IS, IS DERIVED, NOT LISTED. A rule that requires a key which
      -- IDENTIFIES its subject is asking the step to name a record; at the step that creates that
      -- record there is nothing to name (BR-018 needs quote_revision_ref, BR-032 needs
      -- provider_event_id). A rule whose keys only DESCRIBE the subject is judging the content of
      -- what is being written and must be asked exactly there (BR-025 needs terms_version and
      -- terms_hash). The distinction is public.phase_d_context_key_object.key_role, the same column
      -- the three identity doors in fn_phase_d_step_context read; a subject reached through
      -- phase_d_fixture_stage.contributes_ref counts as identifying, because a contributed
      -- reference is a reference.
      select min(x.step_id), min(p.step_no) into v_producer, v_prod_no
        from public.phase_d_step_effect x
        join public.phase_b_workflow_step p on p.step_id = x.step_id
       where x.workflow_id = s.workflow_id and x.effect_object_id = any(v_subjects);
      if v_prod_no is not null and s.step_no <= v_prod_no then
        select coalesce(bool_or(idf), false) into v_needs_identity from (
          select true as idf from public.phase_d_fixture_stage st
           where st.contributes_ref = any(e.required_context) and st.object_id = any(v_subjects)
          union all
          select (k.key_role = 'IDENTIFIES') from public.phase_d_context_key_object k
           where k.context_key = any(e.required_context) and k.object_id = any(v_subjects)) z2;
        if s.step_no < v_prod_no or v_needs_identity then
          select x.effect_object_id into v_governs from public.phase_d_step_effect x
           where x.step_id = v_producer limit 1;
          applies := false;
          why := format('%s governs %s, which %s produces at %s; %s',
                        r.rule_id, v_governs, s.workflow_id, v_producer,
                        case when s.step_no < v_prod_no
                             then format('%s runs before it, so the subject does not exist and cannot', p_step_id)
                             else format('%s is that step and the rule requires a key that IDENTIFIES the subject, '
                                      || 'so it would be asking the step to name what the step creates', p_step_id) end);
          return next; return;
        end if;
      end if;
    end if;
  end if;

  applies := true;
  why := format('%s (%s, %s) applies to %s: in scope %s%s', r.rule_id, r.rule_type,
                coalesce(e.enforcement_kind,'UNREGISTERED'), p_step_id, r.workflow_scope,
                case when e.status = 'OUTSTANDING'
                     then ' — enforcement OUTSTANDING, pending the D2 object map' else '' end);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_rule_can_refuse()
 RETURNS TABLE(rule_id text, refusing_context text, states text, can_refuse boolean, note text)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_full jsonb; v_held jsonb; v_overlay text;
  r record; e public.phase_d_rule_enforcement%rowtype; s1 text; s2 text; s3 text;
begin
  select ob.overlay_id into v_overlay from public.phase_c_overlay_binding ob order by 1 limit 1;

  -- (2) everything named, including the authority that permits it
  v_full := jsonb_build_object(
    'accountable_role_id','ceo','actor_role_id','ceo',
    'reviewer_role_id','inquiry_quality_analyst','step_id','W05-S01','workflow_id','W05',
    'run_id', 1, 'founder_gate','NONE','execution_context','production',
    'evidence_refs', jsonb_build_array('e1'), 'assumptions', jsonb_build_array('a real assumption'),
    'formula','numerator/denominator','denominator', 2, 'numerator', 1,
    'inquiry_owner','ceo','evidence_authority','A NEW_WORK_REQUEST',
    'commercial_policy_change','raise reveal fee','founder_authority_ref','founder_command:1',
    'policy_exception','waive fee','exception_authority_ref','founder_command:1',
    'sla_policy_id', (select sp.sla_policy_id from public.phase_b_sla_policy sp order by 1 limit 1),
    'handoff_id', (select hc.handoff_id from public.phase_d_handoff_contract hc order by 1 limit 1),
    'packet', '{}'::jsonb);

  -- (3) the same subjects with the AUTHORITY WITHHELD, and an actor that resolves to an overlay.
  -- This is the context the first two could not express, and it is where six of the seven refuse.
  v_held := (v_full - 'founder_authority_ref' - 'exception_authority_ref')
            || jsonb_build_object('actor_role_id', coalesce(v_overlay,'ceo'));

  for r in select br.rule_id from public.phase_b_business_rule br order by br.rule_id loop
    select rc.state into s1 from public.fn_phase_d_rule_check(r.rule_id, '{}'::jsonb) rc limit 1;
    select rc.state into s2 from public.fn_phase_d_rule_check(r.rule_id, v_full)      rc limit 1;
    select rc.state into s3 from public.fn_phase_d_rule_check(r.rule_id, v_held)      rc limit 1;
    select * into e from public.phase_d_rule_enforcement en where en.rule_id = r.rule_id;

    rule_id := r.rule_id;
    states  := format('empty=%s full=%s authority_withheld=%s', s1, s2, s3);
    can_refuse := 'ENFORCED_FAIL' in (s1, s2, s3);
    refusing_context := case
      when s1 = 'ENFORCED_FAIL' then 'empty'
      when s3 = 'ENFORCED_FAIL' then 'authority_withheld'
      when s2 = 'ENFORCED_FAIL' then 'full'
      else '(none)' end;
    -- E20. DERIVED FROM THE ENFORCEMENT ROW, NEVER FROM A RULE ID. The prior body matched
    -- 'BR-028' and 'BR-053'/'BR-054' as literals, so the excuse would have printed unchanged if any
    -- of them had started or stopped refusing. Every branch below reads a column.
    note := case
      when can_refuse then 'a context producing ENFORCED_FAIL exists'
      when s1 = 'DELEGATED_TO_KERNEL_GUARD' then 'delegated: the kernel guard decides, this predicate cannot invoke it'
      when e.rule_id is null then 'this rule has no row in phase_d_rule_enforcement, so nothing here can explain it'
      when e.enforcement_kind = 'EXECUTOR_ENFORCED'
        then format('enforced at %s, which is not this predicate; the predicate is not where this rule refuses',
                    coalesce(e.enforcement_point,'(unstated)'))
      when s1 = s2 and s2 = s3 and coalesce(cardinality(e.required_context),0) = 0
        then format('constant under every context tried, and it must be: this rule declares no required_context, so its verdict comes from %s — estate state, not the call. It will vary when that does.',
                    coalesce(e.enforcement_point,'(unstated)'))
      else 'NO CONTEXT PRODUCED A REFUSAL — this rule cannot fail' end;
    return next;
  end loop;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_rule_check(p_rule_id text, p_context jsonb)
 RETURNS TABLE(state text, ok boolean, rule_type text, enforced boolean, reason text, refusal_code text, evidence_absent boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_txt3 text; v_rev_ok boolean; v_rev_code text; v_rev_why text;   -- O07
  r public.phase_b_business_rule%rowtype;
  e public.phase_d_rule_enforcement%rowtype;
  v_missing text[]; v_n bigint; v_txt text; v_ok boolean; v_reason text;
  -- E30. A second count and a second string. A reference that must RESOLVE is two questions --
  -- is it shaped like the thing it claims to be, and does it name something that exists -- and
  -- more than once the answer lives in two relations.
  v_n2 bigint; v_txt2 text;
begin
  -- E19. FALSE UNLESS A BRANCH SAYS OTHERWISE. An OUT parameter left unset is NULL, and a null
  -- read as "not evidence-absent" by one caller and as "unknown" by another is how one column
  -- ends up meaning two things.
  evidence_absent := false;
  select * into r from public.phase_b_business_rule where rule_id = p_rule_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; ok := false; rule_type := 'unknown'; enforced := false;
    reason := format('unknown business rule %s — fail closed', p_rule_id);
    refusal_code := 'unknown_rule'; return next; return;
  end if;
  rule_type := r.rule_type;

  select * into e from public.phase_d_rule_enforcement where rule_id = p_rule_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; ok := false; enforced := false;
    reason := format('rule %s has no row in phase_d_rule_enforcement — fail closed rather than assume it is satisfied', p_rule_id);
    refusal_code := 'rule_unregistered'; return next; return;
  end if;
  refusal_code := e.refusal_code;
  enforced := (e.status = 'ENFORCED');

  -- ============================ the predicates ============================================
  -- Each reads the relation D2 bound for the object it governs. A rule whose evidence is absent
  -- REFUSES; it never passes for want of data.

  if p_rule_id in ('BR-001','BR-005') then
    v_ok := public.fn_phase_c_actor_may_own(p_context->>'accountable_role_id');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: owner %s %s', p_rule_id, coalesce(p_context->>'accountable_role_id','(none)'),
                     case when v_ok then 'resolves to one active canonical role'
                          else 'does not resolve to an active canonical role' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-004' then
    v_ok := coalesce((select kind from public.fn_phase_c_resolve_actor(p_context->>'actor_role_id')),'') = 'canonical';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-004: actor %s %s', coalesce(p_context->>'actor_role_id','(none)'),
                     case when v_ok then 'is canonical' else 'is not canonical; aliases are input compatibility only' end);
    return next; return;
  end if;

  if p_rule_id in ('BR-002','BR-030','BR-031','BR-037','BR-038') then
    v_ok := public.fn_kernel_reviewer_independent(p_context->>'accountable_role_id', p_context->>'reviewer_role_id');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: %s and %s %s', p_rule_id, coalesce(p_context->>'accountable_role_id','(none)'),
                     coalesce(p_context->>'reviewer_role_id','(none)'),
                     case when v_ok then 'are different effective identities'
                          else 'resolve to the same effective identity' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-048' then
    v_ok := not exists (select 1 from public.phase_c_overlay_binding ob
                         where ob.live_role_id = (select role_id from public.fn_phase_c_resolve_actor(p_context->>'actor_role_id')));
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then 'BR-048: the acting identity is not a category overlay'
                   else format('BR-048: %s is a category overlay and may not dispatch, approve suppliers, reveal identity or change policy',
                               p_context->>'actor_role_id') end;
    return next; return;
  end if;

  if p_rule_id in ('BR-053','BR-054') then
    v_ok := not coalesce((public.fn_kernel_paid_provider_gate('openai/gpt-4o-mini')->>'allowed')::boolean, true);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: the paid-provider gate %s', p_rule_id,
                     case when v_ok then 'refuses a paid route' else 'ALLOWED a paid route' end);
    return next; return;
  end if;

  -- E28. BR-003 CHECKED THAT A KEY WAS PRESENT, NEVER THAT IT MEANT ANYTHING.
  -- It fell through to the generic CONTEXT_REQUIRED branch, whose whole test is "is the key present
  -- and non-empty". Measured 2026-08-20: BR-003 returned ENFORCED_PASS for
  -- founder_authority_ref = 'ZZ DEMO — founder_authority_ref for W16-S01', and for the single word
  -- 'banana'. A rule whose name is "founder-reserved decisions require founder authority" was
  -- satisfied by any non-empty string, which means the harness driving the workflow deliverable was
  -- forging founder authority and being told it had it. The founder's standing rule, written into
  -- this estate's own injected-defect catalogue, is that a fixture may never forge one.
  --
  -- The reference must now RESOLVE. 'founder_command:<id>' has to name a row in
  -- public.founder_command; nothing else is accepted, and the refusal says which of the two
  -- failures it is so a caller can tell "you named nothing" from "you named something that is not
  -- a founder decision". Fixing it here rather than in the harness closes it for every caller.
  if p_rule_id = 'BR-003' then
    v_txt := btrim(coalesce(p_context->>'founder_authority_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-003 requires [founder_authority_ref] and the call names none of it.';
      return next; return;
    end if;
    v_ok := exists (select 1 from public.founder_command fc
                     where 'founder_command:' || fc.command_id::text = v_txt);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok
                   then format('BR-003: %s resolves to a founder command on record', v_txt)
                   else format('BR-003: %s does not resolve to any row in public.founder_command. A founder-reserved decision needs the founder''s actual decision, not a string in its shape.', v_txt) end;
    return next; return;
  end if;

  if p_rule_id = 'BR-043' then
    -- E30. BR-043 REFUSED NOTHING, FOR TWO INDEPENDENT REASONS, AND BOTH HAD TO GO.
    -- (1) Applicability keyed on 'policy_exception', which is NOT in its required_context, so the
    --     rule was NOT_APPLICABLE on every call the estate actually makes -- including calls that
    --     named an exception authority.
    -- (2) The authority test was "is the string non-empty", so 'banana' authorised an exception.
    -- Bound, applicable and ACTUALLY REFUSES are three different questions. A brief and two
    -- audits named this rule as a blocker; it had only ever answered the first.
    v_txt  := btrim(coalesce(p_context->>'policy_exception',''));
    v_txt2 := btrim(coalesce(p_context->>'exception_authority_ref',''));
    if v_txt = '' and v_txt2 = '' then
      state := 'NOT_APPLICABLE'; ok := true;
      reason := 'BR-043: the call proposes no policy exception and names no exception authority, so there is no exception to authorise';
      return next; return;
    end if;
    if v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-043: exception %s is proposed with no exception_authority_ref', v_txt);
      return next; return;
    end if;
    -- Does the exception reach founder-reserved subject matter? public.founder_reserved_decision
    -- carries the eleven decision keys and their match terms. That table is the boundary list;
    -- it is not a literal typed into this predicate, so the predicate follows it when it moves.
    select count(*) into v_n from public.founder_reserved_decision d
     where v_txt <> ''
       and (position(lower(replace(d.decision_key,'_',' ')) in lower(replace(v_txt,'_',' '))) > 0
            or exists (select 1 from unnest(d.match_any) t
                        where btrim(t) <> '' and position(lower(btrim(t)) in lower(v_txt)) > 0));
    -- The founder's own authority, resolved exactly as E28 resolved BR-003.
    v_n2 := case when exists (select 1 from public.founder_command fc
                               where 'founder_command:' || fc.command_id::text = v_txt2)
                 then 1 else 0 end;
    if v_n > 0 then
      -- "cannot bypass ... founder boundaries": a delegated authority is not enough here.
      v_ok := (v_n2 = 1);
      reason := format('BR-043: exception %s touches %s founder-reserved decision(s) and names authority %s, which %s',
                       v_txt, v_n, v_txt2,
                       case when v_ok then 'resolves to a founder command on record'
                            else 'does not resolve to any row in public.founder_command -- a delegated authority cannot clear a founder boundary' end);
    else
      v_ok := (v_n2 = 1)
              or exists (select 1 from public.employee_authority ea
                          where 'employee_authority:' || ea.agent_key || ':' || ea.action_class = v_txt2);
      reason := format('BR-043: exception %s names authority %s, which %s',
                       coalesce(nullif(v_txt,''),'(unnamed)'), v_txt2,
                       case when v_ok then 'resolves to a founder command or a granted employee authority'
                            else 'resolves to no row in public.founder_command or public.employee_authority' end);
    end if;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    return next; return;
  end if;

  if p_rule_id in ('BR-021','BR-022','BR-023','BR-024') then
    -- E31. THE SAME DEFECT E30 FOUND IN BR-043, IN THE FOUR RULES E29 HAD JUST FIXED.
    -- E29 made the AUTHORITY resolve, and that half holds. But applicability still keyed on
    -- 'commercial_policy_change', which is NOT in these rules' required_context -- all four
    -- declare only [founder_authority_ref]. So a call that named a founder authority and no
    -- commercial_policy_change was NOT_APPLICABLE, and the authority E29 taught the rule to
    -- resolve was never looked at. Measured after E30: feeding every rule 'banana' for each key
    -- it declares, BR-021..BR-024 were four of the five remaining passes, and all four passed as
    -- NOT_APPLICABLE rather than on the merits.
    --
    -- Bound, applicable and ACTUALLY REFUSES are three questions. E28 and E29 answered the third
    -- for these rules and left the second. A rule is now applicable when EITHER key is named: if
    -- a call in a founder-gated workflow asserts a founder authority, that assertion is judged.
    if coalesce(btrim(p_context->>'commercial_policy_change'),'') = ''
       and coalesce(btrim(p_context->>'founder_authority_ref'),'') = '' then
      state := 'NOT_APPLICABLE'; ok := true;
      reason := format('%s: the call proposes no change to a founder-reserved commercial term and asserts no founder authority', p_rule_id);
      return next; return;
    end if;
    -- E29. THE SAME DEFECT E28 FOUND IN BR-003, IN FOUR MORE RULES.
    -- This tested only that founder_authority_ref was non-empty, so BR-021 through BR-024 --
    -- the rules guarding founder-reserved COMMERCIAL terms -- returned ENFORCED_PASS for the
    -- literal string 'banana'. Measured 2026-08-20: 17 of the 30 rules that declare a
    -- required_context pass on that string. These four are the ones where the consequence is a
    -- forged founder decision on pricing, and they get the same resolution E28 gave BR-003.
    v_txt := btrim(coalesce(p_context->>'founder_authority_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('%s: change %s names no founder authority', p_rule_id,
                       coalesce(nullif(btrim(p_context->>'commercial_policy_change'),''),'(unnamed)'));
      return next; return;
    end if;
    v_ok := exists (select 1 from public.founder_command fc
                     where 'founder_command:' || fc.command_id::text = v_txt);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: change %s %s', p_rule_id,
                     coalesce(nullif(btrim(p_context->>'commercial_policy_change'),''),'(unnamed)'),
                     case when v_ok then format('carries founder authority %s, which resolves to a founder command on record', v_txt)
                          else format('names %s, which does not resolve to any row in public.founder_command', v_txt) end);
    return next; return;
  end if;

  -- ---------------- BR-020: reveal only after reconciliation -------------------------------
  if p_rule_id = 'BR-020' then
    if p_context->>'transaction_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-020: no transaction_id in context. A reveal decision with no transaction to reconcile is refused.';
      return next; return;
    end if;
    -- Aliased for the same reason as the lookup inside fn_phase_d_reveal_permitted: this
    -- function's OUT parameter is also called `reason`, so an unqualified reference is ambiguous
    -- between the plpgsql variable and the callee's returned column.
    select rp.permitted, rp.reason into v_ok, v_reason
      from public.fn_phase_d_reveal_permitted(p_context->>'transaction_id') rp;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := v_reason;
    return next; return;
  end if;

  -- ---------------- the object-backed rules D2 unblocked -----------------------------------
  if p_rule_id = 'BR-011' then           -- no customer identity in a supplier-facing payload
    v_txt := coalesce(p_context->>'supplier_payload','');
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-011: no supplier_payload named. A payload nobody showed cannot be certified free of customer identity.';
      return next; return;
    end if;
    select count(*) into v_n from public.customers c
     where (coalesce(c.email,'') <> '' and position(lower(c.email) in lower(v_txt)) > 0)
        or (coalesce(c.phone,'') <> '' and position(c.phone   in v_txt) > 0)
        or (coalesce(c.full_name,'') <> '' and length(c.full_name) > 3
            and position(lower(c.full_name) in lower(v_txt)) > 0);
    -- The test is simply whether any customer identity appears in the payload. An earlier draft
    -- also ORed in a reveal_state check, which collapsed to the same expression under operator
    -- precedence and read as if it were doing something it was not.
    -- E30. I DID NOT CHANGE WHAT THIS RULE MEANS, BECAUSE ITS 'banana' PASS IS A TRUE PASS: the
    -- string 'banana' carries no customer identity, and BR-011 is a content test, not a reference
    -- test. What was wrong is that its only evidence source is a table held at zero. The row-match
    -- arm answers 0 for every payload ever shown to it, and 0 is also what it would answer if it
    -- were broken. So the SHAPE is tested too: a supplier-facing payload carrying an email address
    -- or a dialable UAE mobile is a customer identity leak whether or not that person is a row in
    -- this estate yet.
    -- O04/O07. THE TWO REGEX CLASSES WERE A LIST INSIDE THIS PREDICATE, AND THE LIST WAS SHORT.
    -- Measured on the live body, 24 Aug 2026: the payload
    --   '/Author (Omar Bin Faisal) /Title (Villa 42 plot 345-8871) /Creator (AL NAHDA CONSULTANTS)'
    -- returned ok = TRUE. The row arm searches public.customers, which holds 0 rows, and the shape
    -- arm tested an email and a UAE mobile and nothing else -- so the exact injection PD-PRIV-005
    -- names, a customer's NAME in a PDF /Info dictionary, passed the one rule that names it.
    --
    -- The classes now come from public.phase_d_personal_identifier_class, so extending the list is
    -- a row and not a redeploy, and the scanner in scripts/phase_d/metadata_scan.mjs reads the same
    -- table -- the rule and the scanner cannot disagree about what a personal identifier is.
    select count(*) into v_n2
      from public.phase_d_personal_identifier_class pic
     where pic.detection = 'REGEX' and not pic.supplier_facing_allowed
       and v_txt ~* pic.pattern;

    -- AND A FILE REVISION, WHERE ONE IS NAMED. A payload is text; the file that goes with it
    -- carries metadata this predicate cannot see. Where the caller names the revision, its recorded
    -- scan is part of the same answer, and a revision that is named and not dispatchable refuses
    -- here rather than at the point the file is already on its way.
    v_txt3 := btrim(coalesce(p_context->>'file_revision_ref',''));
    if v_txt3 <> '' then
      select fr.dispatchable, fr.refusal_code, fr.reason into v_rev_ok, v_rev_code, v_rev_why
        from public.fn_phase_d_file_revision_dispatchable(v_txt3) fr;
    else
      v_rev_ok := true; v_rev_code := null; v_rev_why := 'no file revision named in this context';
    end if;

    v_ok := (v_n = 0 and v_n2 = 0 and v_rev_ok);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    if not v_rev_ok then refusal_code := v_rev_code; end if;
    reason := format('BR-011: %s customer identity match(es) over %s customer row(s) searched for email, phone and full name; %s of %s registered machine-decidable identifier class(es) matched the payload itself; file revision %s. %s of the registered classes are HUMAN_REVIEW and are never scored automatically as absent.',
                     v_n, (select count(*) from public.customers), v_n2,
                     (select count(*) from public.phase_d_personal_identifier_class
                       where detection = 'REGEX' and not supplier_facing_allowed),
                     coalesce(nullif(v_txt3,''),'(none named)') || ': ' || coalesce(v_rev_why,''),
                     (select count(*) from public.phase_d_personal_identifier_class
                       where detection = 'HUMAN_REVIEW'));
    return next; return;
  end if;

  if p_rule_id = 'BR-012' then           -- an approved immutable supplier-safe package exists
    -- E30. This asked only whether two strings were non-empty, so 'banana' approved by 'banana'
    -- was an approved immutable supplier-safe package. supplier_safe_package is a REGISTERED
    -- business object of the IMMUTABLE_REVISION family: the ref must name one of those records in
    -- the approved state, and the approver must be someone who may own work here.
    v_txt  := btrim(coalesce(p_context->>'safe_package_ref',''));
    v_txt2 := btrim(coalesce(p_context->>'safe_package_approved_by',''));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-012: no approved supplier-safe package named, or no approver named. No assignment or notification may be created without one.';
      return next; return;
    end if;
    select count(*) into v_n from public.phase_d_object_record o
     where o.object_id = 'supplier_safe_package' and o.state = 'approved' and o.superseded_by is null
       and (o.business_key = v_txt or 'supplier_safe_package:' || o.business_key = v_txt);
    -- O04/O07. THE FILE SET WAS NEVER OPENED. This counted an approved package record and resolved
    -- the approver string, and stopped. Measured before the change: a package whose drawing carried
    -- an unapproved redaction and one whose drawing was clean returned the IDENTICAL ENFORCED_PASS.
    -- An identical answer to the injection and its control is the defect PD-PRIV-002 names, whatever
    -- the answer happens to be.
    --
    -- The leg below is the whole of the change: every LIVE revision registered against this package
    -- must be redaction-approved AND metadata-clean AT THE APPROVED DIGEST. The package answer is
    -- the WORST revision answer -- one leaking file in a set is a leak, so this is never an average
    -- and never a majority.
    select pr.dispatchable, pr.refusal_code, pr.reason into v_rev_ok, v_rev_code, v_rev_why
      from public.fn_phase_d_package_revisions_dispatchable(v_txt) pr;

    v_ok := (v_n >= 1) and public.fn_phase_c_actor_may_own(v_txt2) and v_rev_ok;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    if not v_rev_ok then refusal_code := v_rev_code; end if;
    reason := format('BR-012: package %s resolves to %s approved supplier_safe_package record(s) in public.phase_d_object_record, approver %s %s, and its file set: %s',
                     v_txt, v_n, v_txt2,
                     case when public.fn_phase_c_actor_may_own(v_txt2)
                          then 'resolves to an active canonical role'
                          else 'does not resolve to an active canonical role' end,
                     coalesce(v_rev_why,'(no verdict)'));
    return next; return;
  end if;

  if p_rule_id = 'BR-013' then           -- the inquiry is quote-ready
    if p_context->>'inquiry_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-013: no inquiry_id named; readiness cannot be measured against nothing.';
      return next; return;
    end if;
    select count(*) into v_n from public.inquiries i
     where i.id::text = p_context->>'inquiry_id'
       and coalesce(i.status,'') in ('quote_ready','dispatched','quoted','completed');
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-013: inquiry %s %s', p_context->>'inquiry_id',
                     case when v_ok then 'is in a quote-ready state'
                          else 'is not quote-ready; mandatory qualification, route or document blockers remain' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-014' then           -- only a CONFIRMED route authorises dispatch
    v_ok := lower(coalesce(btrim(p_context->>'route_state'),'')) = 'confirmed';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-014: route state %s. Proposed, ambiguous, rejected and excluded routes cannot authorise dispatch.',
                     coalesce(nullif(btrim(p_context->>'route_state'),''),'(unstated)'));
    return next; return;
  end if;

  if p_rule_id = 'BR-015' then           -- only an approved, eligible supplier is dispatched to
    if p_context->>'supplier_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-015: no supplier_id named.'; return next; return;
    end if;
    select count(*) into v_n from public.leads l
     where l.id::text = p_context->>'supplier_id'
       and coalesce(l.approval_status,'') = 'approved' and coalesce(l.verified,false);
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-015: supplier %s %s. public.leads already enforces approved implies verified as a CHECK constraint.',
                     p_context->>'supplier_id',
                     case when v_ok then 'is approved and verified' else 'is not an approved, verified supplier' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-016' then           -- one assignment per supplier per inquiry version
    if p_context->>'inquiry_id' is null or p_context->>'supplier_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-016: inquiry_id and supplier_id are both required to decide duplicate assignment.';
      return next; return;
    end if;
    select count(*) into v_n from public.inquiry_matches m
     where m.inquiry_id::text = p_context->>'inquiry_id'
       and m.supplier_id::text = p_context->>'supplier_id';
    v_ok := (v_n <= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-016: %s existing assignment(s) for that supplier and inquiry. NOTE: public.inquiry_matches carries no version column and no unique constraint, so this is enforced here and NOT structurally — recorded as the D2 REPAIR on supplier_assignment.', v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-017' then           -- a refused assignment is not a contact
    v_ok := lower(coalesce(btrim(p_context->>'assignment_result'),'')) in ('delivered','accepted','sent');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-017: assignment result %s. Refused and failed assignments are not counted as contacted and create no success notification.',
                     coalesce(nullif(btrim(p_context->>'assignment_result'),''),'(unstated)'));
    return next; return;
  end if;

  if p_rule_id = 'BR-018' then           -- the supplier's own revision is never platform-edited
    -- O06/O07. THIS COMPARED NOTHING. The whole predicate was
    --   quote_revision_ref is non-empty AND platform_edited = 'false'
    -- which reads the CALLER'S OWN CLAIM ABOUT ITSELF: a normalisation that genuinely overwrote the
    -- supplier's figure and reported platform_edited = false passed. It is now a comparison of two
    -- records -- the live quotation_revision payload against the digest every live normalisation
    -- says it was derived from -- so an original that moved after it was normalised is visible
    -- whatever the caller says about itself.
    v_txt := btrim(coalesce(p_context->>'quote_revision_ref',''));
    select qi.intact, qi.refusal_code, qi.reason into v_rev_ok, v_rev_code, v_rev_why
      from public.fn_phase_d_quote_original_intact(v_txt) qi;
    v_ok := v_rev_ok;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    if not v_ok then refusal_code := v_rev_code; end if;
    reason := 'BR-018: ' || coalesce(v_rev_why, 'no verdict returned by fn_phase_d_quote_original_intact');
    return next; return;
  end if;

  if p_rule_id = 'BR-019' then           -- a customer sees only their own published comparison
    if p_context->>'comparison_id' is null or p_context->>'caller_customer_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-019: comparison_id and caller_customer_id are both required.'; return next; return;
    end if;
    -- O06/O07. THIS TESTED OWNERSHIP AND CALLED IT PUBLICATION. The rule is "a customer sees only
    -- their own PUBLISHED comparison" and the predicate was count(*) ... where id = ? and
    -- customer_id = ?. A customer's own unpublished comparison passed, so the injection
    -- PD-QUOTE-004 names changed nothing a control could separate. Ownership is still tested --
    -- fn_phase_d_comparison_visible tests it FIRST and refuses an unrelated customer on a published
    -- comparison too, which is the arm proving the publication leg did not replace the ownership leg.
    select cv.visible, cv.refusal_code, cv.reason into v_rev_ok, v_rev_code, v_rev_why
      from public.fn_phase_d_comparison_visible(
             p_context->>'comparison_id', p_context->>'caller_customer_id',
             coalesce(nullif(btrim(p_context->>'caller_kind'),''), 'customer')) cv;
    v_ok := v_rev_ok;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    if not v_ok then refusal_code := v_rev_code; end if;
    reason := 'BR-019: ' || coalesce(v_rev_why, 'no verdict returned by fn_phase_d_comparison_visible');
    return next; return;
  end if;

  if p_rule_id = 'BR-025' then           -- acceptance names the exact version and hash
    -- E30. "the exact displayed version AND hash" was tested as "two non-empty strings", so
    -- 'banana' was an exact hash of version 'banana'. public.legal_documents holds the displayed
    -- documents and their versions. The hash must be a real SHA-256 digest, and it must be the
    -- digest OF THAT DOCUMENT AT THAT VERSION -- a hash that matches nothing is not a reference
    -- to anything specific, which is the whole of what this rule asks for.
    v_txt  := btrim(coalesce(p_context->>'terms_version',''));
    v_txt2 := lower(btrim(coalesce(p_context->>'terms_hash','')));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-025: acceptance must reference the exact displayed version AND hash; one without the other is not an acceptance of anything specific.';
      return next; return;
    end if;
    if v_txt2 !~ '^[0-9a-f]{64}$' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-025: terms_hash %s is not a SHA-256 digest (64 hexadecimal characters), so it was never computed over the displayed terms.',
                       left(v_txt2, 24));
      return next; return;
    end if;
    select count(*) into v_n from public.legal_documents d
     where d.version = v_txt
       and encode(sha256(convert_to(coalesce(d.body_html,''), 'UTF8')), 'hex') = v_txt2;
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-025: acceptance names version %s at digest %s, which matches %s row(s) in public.legal_documents whose displayed body hashes to exactly that digest',
                     v_txt, left(v_txt2, 12), v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-026' then           -- no certificate before an acceptance record
    -- E30. The reason string read "acceptance record %s exists" while the predicate had only
    -- checked that a string was non-empty -- evidence stating the premise it never tested.
    -- customer_terms_acceptance and supplier_terms_acceptance are registered APPEND_ONLY business
    -- objects; the ref must name one of those records.
    v_txt := btrim(coalesce(p_context->>'acceptance_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-026: no acceptance record named. A certificate generated before acceptance would assert a fact that has not happened.';
      return next; return;
    end if;
    select count(*) into v_n from public.phase_d_object_record o
     where o.object_id in ('customer_terms_acceptance','supplier_terms_acceptance')
       and (o.business_key = v_txt or o.object_id || ':' || o.business_key = v_txt);
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-026: acceptance_ref %s resolves to %s terms-acceptance record(s) in public.phase_d_object_record. A certificate may not precede one.',
                     v_txt, v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-029' then           -- conflicting evidence is preserved, not overwritten
    -- E30. Two arms, both weak. conflict_preserved='true' was the CALLER asserting its own
    -- compliance, which is not evidence of it; and evidence_authority was tested for
    -- non-emptiness, so 'banana' was an authority ranking. This rule is about RANK -- lower
    -- authority may not overwrite higher -- and this estate has a ranking:
    -- public.mep_evidence_weight, with its weight keys, evidence sources and source authorities.
    -- An authority that is not in the ranking cannot be ordered against another, so it cannot be
    -- preserved against one either.
    v_txt := btrim(coalesce(p_context->>'evidence_authority',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-029: no evidence authority named. Lower-authority evidence may not silently overwrite higher, and an unranked authority cannot be ordered against any other.';
      return next; return;
    end if;
    select count(*) into v_n from public.mep_evidence_weight w
     where w.weight_key = v_txt or w.evidence_source = v_txt or w.source_authority = v_txt;
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-029: evidence authority %s matches %s row(s) in the public.mep_evidence_weight ranking (weight_key, evidence_source or source_authority)%s',
                     v_txt, v_n,
                     case when v_ok then ', so conflicting evidence can be retained in rank order'
                          else ' -- it is not a ranked authority in this estate' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-032' then           -- provider events are unique and replay-safe
    if coalesce(btrim(p_context->>'provider_event_id'),'') = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-032: no provider_event_id named; duplicate delivery cannot be decided without one.';
      return next; return;
    end if;
    -- E30. THE TEST WAS "appears AT MOST once", so an event id appearing ZERO times satisfied a
    -- rule about the safety of REAL provider events -- one never delivered, or the literal
    -- 'banana'. Zero cannot tell an unknown event from a safe one. It must resolve to EXACTLY ONE
    -- recorded delivery, in the provider event log or in the registered provider_event object.
    v_txt := btrim(coalesce(p_context->>'provider_event_id',''));
    select count(*) into v_n  from public.stripe_events se where se.event_id = v_txt;
    select count(*) into v_n2 from public.phase_d_object_record o
     where o.object_id = 'provider_event'
       and (o.business_key = v_txt or 'provider_event:' || o.business_key = v_txt);
    v_ok := (v_n + v_n2) = 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-032: provider event %s resolves to %s row(s) in public.stripe_events and %s registered provider_event record(s). Exactly one is replay-safe: zero is an event nobody received, more than one is a duplicate.',
                     v_txt, v_n, v_n2);
    return next; return;
  end if;

  if p_rule_id = 'BR-033' then           -- unknown money is quarantined, never success
    -- E30. A DENY-LIST OF THREE WORDS LEFT EVERY OTHER STRING AS A GOOD MONETARY STATE. The
    -- acceptance audit watched the harness hand this rule 'checkout_created' and get ok=true;
    -- 'banana' did just as well. An unrecognised monetary state IS an unknown one, which is
    -- precisely what this rule exists to quarantine. The permitted set is read from the state
    -- contracts of the TRANSACTION_RECORD family -- the money-carrying objects -- and not typed
    -- in here, so it follows the registry instead of drifting from it.
    -- G04. THE RULE ABOUT MONEY WAS ASKING THE REGISTER THAT DOES NOT MODEL MONEY.
    --
    -- E30 corrected a deny-list of three words by reading the allowed_states of the
    -- TRANSACTION_RECORD family, which was right about the method and wrong about the register.
    -- Two vocabularies describe a transaction in this estate:
    --
    --   public.phase_d_object_state_contract  open, pending, settled, refunded, failed, reconciled
    --       the generic OBJECT-RECORD lifecycle, derived from policy_family and applied identically
    --       to dispatch_batch, payment_transaction, reveal_transaction and supplier_assignment.
    --   public.phase_d_payment_state          checkout_created, payment_initiated, provider_success,
    --       payment_confirmed, payment_reconciled, reveal_authorized -- a SIX-RUNG LADDER, each rung
    --       carrying authorizes_reveal and a stated reason, and it is what public.transactions
    --       .fee_status actually holds and what BR-020 reads.
    --
    -- MEASURED: the intersection of those two sets is EMPTY. Not "different in places" -- no value
    -- appears in both. So BR-033 refused every real monetary state this estate can produce,
    -- including payment_reconciled, the founder-approved bar in BR-020, and would have PASSED
    -- 'settled' or 'refunded' for a payment that never reconciled. Two rules about one transaction,
    -- unable to agree about any transaction, because one of them was reading the wrong register.
    --
    -- THE FROZEN TEXT DECIDES WHICH REGISTER IS RIGHT: "Unknown, conflicting or unreconciled
    -- monetary states are blocked/quarantined and cannot be treated as success." Recognised, and
    -- reconciled. The ladder is the register of recognised monetary states and authorizes_reveal is
    -- the ladder's own mark for the reconciled rungs, so both halves of the frozen sentence are
    -- read from the register that states them.
    --
    -- THIS IS STRICTLY TIGHTER THAN WHAT IT REPLACES, and that is the test of it. Before: five
    -- words passed that say nothing about reconciliation. After: an unrecognised state is refused
    -- as unrecognised, a recognised state below reconciliation is refused as unreconciled, and the
    -- three quarantine words are refused by name as they always were. Only payment_reconciled and
    -- reveal_authorized pass, which is the relationship the founder's section 5 asked BR-020 and
    -- BR-033 to evaluate between them.
    --
    -- public.phase_d_object_state_contract IS NOT AMENDED. The founder's section 5 forbids putting
    -- reveal_authorized into the TRANSACTION_RECORD family to make this rule green, and nothing
    -- here does: the family keeps the generic lifecycle it describes, and this rule stops asking
    -- it a question it was never the register for.
    v_txt := lower(coalesce(btrim(p_context->>'monetary_state'),''));
    select count(*) into v_n
      from public.phase_d_payment_state ps
     where lower(ps.state_key) = v_txt and ps.authorizes_reveal;
    v_ok := v_txt <> '' and v_txt not in ('unknown','conflicting','unreconciled') and v_n >= 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-033: monetary state %s matches %s reconciled rung(s) of the payment ladder public.phase_d_payment_state (%s of its %s rungs are reconciled: %s). Unknown, conflicting, unreconciled and unrecognised states are blocked and quarantined, never treated as success.',
                     coalesce(nullif(v_txt,''),'(unstated)'), v_n,
                     (select count(*) from public.phase_d_payment_state where authorizes_reveal),
                     (select count(*) from public.phase_d_payment_state),
                     (select string_agg(ps2.state_key, ', ' order by ps2.rung)
                        from public.phase_d_payment_state ps2 where ps2.authorizes_reveal));
    return next; return;
  end if;

  if p_rule_id = 'BR-034' then           -- consent and suppression are respected
    if coalesce(btrim(p_context->>'notify_email'),'') = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-034: no notify_email named; consent cannot be decided for an unnamed recipient.';
      return next; return;
    end if;
    -- E30. 'banana' is not in the suppression list, so 'banana' was a consenting recipient. A
    -- string that cannot be an email address cannot have been checked for consent: it has to be
    -- an address before the suppression lookup means anything at all.
    v_txt := btrim(coalesce(p_context->>'notify_email',''));
    if v_txt !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}$' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-034: %s is not an email address, so no consent or suppression decision about it exists to respect.', v_txt);
      return next; return;
    end if;
    select count(*) into v_n from public.email_suppressions s
     where lower(s.email) = lower(v_txt);
    v_ok := (v_n = 0);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-034: %s is %s in public.email_suppressions (%s matching row(s) over %s suppression(s) on record)',
                     v_txt,
                     case when v_ok then 'not suppressed' else 'SUPPRESSED and must not be contacted' end,
                     v_n, (select count(*) from public.email_suppressions));
    return next; return;
  end if;

  if p_rule_id = 'BR-035' then           -- only the approved revision publishes
    -- E30. Feeding the same junk string to both keys satisfied this rule, because equality of two
    -- unresolved strings is not evidence that either names an approved revision. The approved ref
    -- must resolve to an IMMUTABLE_REVISION business object record in the approved state -- the
    -- estate's own registry of revisions -- and the revision being published must be that one.
    v_txt  := btrim(coalesce(p_context->>'approved_revision_ref',''));
    v_txt2 := btrim(coalesce(p_context->>'publishing_revision_ref',''));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-035: the revision being published is not the independently approved revision, or neither was named.';
      return next; return;
    end if;
    if v_txt <> v_txt2 then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-035: the publishing revision %s is not the approved revision %s', v_txt2, v_txt);
      return next; return;
    end if;
    select count(*) into v_n from public.phase_d_object_record o
      join public.phase_d_object_state_contract c on c.object_id = o.object_id
     where c.policy_family = 'IMMUTABLE_REVISION' and o.state = 'approved'
       and (o.business_key = v_txt or o.object_id || ':' || o.business_key = v_txt);
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-035: the publishing revision is the approved one (%s), and that reference resolves to %s approved IMMUTABLE_REVISION record(s) in public.phase_d_object_record',
                     v_txt, v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-036' then           -- review inspects the artifact, not the brief
    -- E30. The acceptance audit caught this one from the other end: it read back
    -- "review names artifact ZZ DEMO - artifact_ref at digest ZZ DEMO - artifact_sha256" and got
    -- ok=true. A SHA-256 is 64 hexadecimal characters; a value that is not one was never computed
    -- over any artifact. And the digest must be OF something -- an artifact_review row, or a
    -- business object record carrying it. In an estate whose vision model once listed eight
    -- identifiers verbatim from a solid black rectangle, the digest is the only part of an
    -- artifact review that cannot be imagined.
    v_txt  := btrim(coalesce(p_context->>'artifact_ref',''));
    v_txt2 := lower(btrim(coalesce(p_context->>'artifact_sha256','')));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-036: the review names no artifact and digest. A verifier that reads the brief instead of the artifact has already produced a false pass in this estate.';
      return next; return;
    end if;
    if v_txt2 !~ '^[0-9a-f]{64}$' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-036: artifact_sha256 %s is not a SHA-256 digest (64 hexadecimal characters), so it was not computed over any artifact.',
                       left(v_txt2, 24));
      return next; return;
    end if;
    select count(*) into v_n  from public.artifact_review ar where lower(ar.artifact_sha256) = v_txt2;
    select count(*) into v_n2 from public.phase_d_object_record o
     where lower(o.payload->>'artifact_sha256') = v_txt2;
    v_ok := (v_n + v_n2) >= 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-036: review names artifact %s at digest %s, which resolves to %s artifact_review row(s) and %s business object record(s) carrying exactly that digest',
                     v_txt, left(v_txt2, 12), v_n, v_n2);
    return next; return;
  end if;

  if p_rule_id = 'BR-039' then           -- a release needs an executable rollback
    -- E30. The rule says DEFINED AND EXECUTABLE; the predicate tested only that a string had been
    -- typed, so 'banana' was an executable rollback path. Executable means the estate can name the
    -- thing that would run: a registered action class carrying a compensating action, or a routine
    -- that exists in this database.
    v_txt := btrim(coalesce(p_context->>'rollback_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-039: no rollback or recovery path named. A consequential release without one is not approvable.';
      return next; return;
    end if;
    select count(*) into v_n from public.org_action_executor x
     where x.action_class = v_txt and coalesce(btrim(x.compensation_action_class),'') <> '';
    select count(*) into v_n2 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = regexp_replace(v_txt, '^public[.]', '');
    v_ok := (v_n + v_n2) >= 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-039: rollback path %s resolves to %s registered action class(es) carrying a compensating action and %s routine(s) in this database%s',
                     v_txt, v_n, v_n2,
                     case when v_ok then '' else ' -- nothing that could be executed to undo the release' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-041' then           -- activity is not outcome
    -- E30. "when a business outcome is DEFINED" was tested as "a string was typed that differs
    -- from the activity metric", so 'banana' was a business outcome. public.metric_definition IS
    -- this estate's register of defined metrics. A metric that is not in it has not been defined,
    -- and success declared on it is exactly the vanity claim this rule forbids.
    v_txt  := btrim(coalesce(p_context->>'outcome_metric',''));
    v_txt2 := coalesce(p_context->>'activity_metric','');
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-041: no business outcome metric named.';
      return next; return;
    end if;
    if v_txt = v_txt2 then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-041: the declared outcome metric %s IS the activity metric under another name', v_txt);
      return next; return;
    end if;
    select count(*) into v_n from public.metric_definition m where m.metric_key = v_txt;
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-041: success is declared on outcome metric %s, distinct from the activity metric, and that key resolves to %s row(s) in public.metric_definition (of %s defined metrics)',
                     v_txt, v_n, (select count(*) from public.metric_definition));
    return next; return;
  end if;

  if p_rule_id = 'BR-049' then           -- inquiry accountability does not drift
    v_ok := coalesce(btrim(p_context->>'inquiry_owner'),'') = 'ceo'
            or coalesce(btrim(p_context->>'accountability_transfer_approved'),'') = 'true';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-049: inquiry owner is %s. Specialist and document handoffs do not move overall inquiry accountability away from rfq_qualification_manager without an approved workflow that says so.',
                     coalesce(nullif(btrim(p_context->>'inquiry_owner'),''),'(unstated)'));
    return next; return;
  end if;

  -- ---------------- D47. FIVE RULES THAT NOW DECIDE FOR THEMSELVES --------------------------
  -- BR-027, BR-040 and BR-042 were SCHEMA_ENFORCED fall-throughs returning ENFORCED_PASS with the
  -- reason "is enforced ... later in this same call". True, and useless: the schema they deferred
  -- to checked presence and emptiness only, so none of the three could refuse anything. D46 gave
  -- the validator declared types and domains; these three read the same facts directly.

  if p_rule_id = 'BR-027' then           -- a finding names the evidence it rests on
    v_ok := jsonb_typeof(p_context->'evidence_refs') = 'array'
            and jsonb_array_length(coalesce(p_context->'evidence_refs','[]'::jsonb)) > 0;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-027: %s evidence reference(s) named',
                                         jsonb_array_length(p_context->'evidence_refs'))
                   else 'BR-027: no evidence_refs array. A finding that names no evidence is an assertion.' end;
    return next; return;
  end if;

  if p_rule_id = 'BR-040' then           -- a ratio states its formula and its denominator
    -- THE DENOMINATOR IS TYPED HERE, not merely present. jsonb_typeof('"0"') is 'string', so a
    -- denominator of "0" as text satisfied every presence check in this estate and still divided
    -- something by nothing. least(100, NULL) = 100 is the same defect in another costume.
    v_ok := coalesce(btrim(p_context->>'formula'),'') <> ''
            and jsonb_typeof(p_context->'denominator') = 'number'
            and (p_context->>'denominator')::numeric > 0;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-040: formula %L over a numeric denominator of %s',
                                         p_context->>'formula', p_context->>'denominator')
                   else format('BR-040: formula %L, denominator %s of type %s. A ratio needs a stated formula and a numeric denominator greater than zero.',
                               coalesce(p_context->>'formula','(none)'),
                               coalesce(p_context->>'denominator','(none)'),
                               coalesce(jsonb_typeof(p_context->'denominator'),'absent')) end;
    return next; return;
  end if;

  if p_rule_id = 'BR-042' then           -- an analysis states its assumptions
    -- AND THEY MAY NOT BE THE ONES THE EXECUTOR WRITES FOR ITSELF. fn_phase_d_handler_execute
    -- writes ANALYSIS_HANDLER's assumptions unconditionally as the fixed one-element literal
    -- 'only the inputs named in this call were used; no external source was consulted'. A rule
    -- satisfied by a constant its own caller supplies is a rule that cannot fail, so that exact
    -- value is refused by name.
    v_ok := jsonb_typeof(p_context->'assumptions') = 'array'
            and jsonb_array_length(coalesce(p_context->'assumptions','[]'::jsonb)) > 0
            and p_context->'assumptions' <> jsonb_build_array(
                  'only the inputs named in this call were used; no external source was consulted');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-042: %s assumption(s) stated',
                                         jsonb_array_length(p_context->'assumptions'))
                   when p_context->'assumptions' = jsonb_build_array(
                          'only the inputs named in this call were used; no external source was consulted')
                     then 'BR-042: the only assumption stated is the executor''s own boilerplate. A constant the caller writes for itself is not a stated assumption.'
                   else 'BR-042: no assumptions array. An analysis that states no assumptions has hidden them.' end;
    return next; return;
  end if;

  -- D51. BR-008 HAD ITS PREDICATE REMOVED AGAIN, AND THE REGISTRY WAS RIGHT THE FIRST TIME.
  -- D47 gave it one because fn_phase_d_handoff_packet_valid is STABLE and therefore callable.
  -- Callable is not the same as answerable HERE. The packet is what the SENDING STEP PRODUCES;
  -- at the moment fn_phase_d_rule_check runs — the step has just opened and nobody has done it —
  -- the packet does not exist yet. So the predicate refused 29 of 30 first steps, then 15 of 30
  -- once the applicability rule was added, and every one of those refusals was the rule being
  -- asked a question the lifecycle had not reached.
  --
  -- Its enforcement_kind was KERNEL_ENFORCED for exactly that reason: the kernel checks the packet
  -- when the handoff is accepted, which is when there is one to check. It falls through to the
  -- delegated branch below, where it is honestly labelled rather than given a pass or a refusal it
  -- has not earned. BR-044 keeps its predicate: an SLA due time IS computable when the step opens.
  if p_rule_id = 'BR-044' then           -- an SLA has a computable due time
    if coalesce(btrim(p_context->>'sla_policy_id'),'') = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-044: no sla_policy_id named, so no due time can be computed.';
      return next; return;
    end if;
    -- D51. THE DELEGATE DEFAULTS, SO "is not null" COULD NEVER FAIL. fn_kernel_sla_due ends in
    -- coalesce(<the policy lookup>, 24), so an sla_policy_id that exists nowhere silently gets a
    -- 24-hour deadline and a non-null answer. Measured: fn_kernel_sla_due('zz-demo-no-such-policy')
    -- returns a timestamp 24 hours out. The predicate therefore asks the question the default hides:
    -- is this policy REGISTERED, and does it then compute a due time. The 24-hour fallback lives in
    -- a frozen kernel routine and is not changed here; it is named so it can be seen.
    v_ok := exists (select 1 from public.phase_b_sla_policy sp
                     where sp.sla_policy_id = p_context->>'sla_policy_id')
            and public.fn_kernel_sla_due(p_context->>'sla_policy_id', now()) is not null;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-044: policy %s resolves to a due time',
                                         p_context->>'sla_policy_id')
                   else format('BR-044: policy %L computes no due time', p_context->>'sla_policy_id') end;
    return next; return;
  end if;
  -- ---------------- structurally enforced elsewhere ----------------------------------------
  if e.enforcement_kind in ('SCHEMA_ENFORCED','EXECUTOR_ENFORCED') then
    state := 'ENFORCED_PASS'; ok := true;
    reason := format('%s is enforced at %s later in this same call, which refuses with %s',
                     p_rule_id, e.enforcement_point, e.refusal_code);
    return next; return;
  end if;
  if e.enforcement_kind in ('KERNEL_ENFORCED','TRIGGER_ENFORCED') then
    -- D47. THIS USED TO SAY ENFORCED_PASS, AND THE PLAN ASKED FOR THE DELEGATE TO BE INVOKED
    -- INSTEAD. Measured, that is possible for two of these and impossible for the other eleven:
    --
    --   BR-006 BR-007 BR-009 BR-045  public.fn_kernel_step_complete(jsonb)  VOLATILE SECDEF, writes
    --   BR-046                       public.fn_kernel_cancel(jsonb)         VOLATILE SECDEF, writes
    --   BR-010                       public.fn_phase_c_trace_append_only()  returns trigger
    --   BR-047                       public.fn_org_authority_guard()        returns trigger
    --   BR-050 BR-051 BR-052         public.fn_kernel_write_guard()         returns trigger
    --
    -- A routine returning trigger cannot be called at all, and a volatile writer cannot be called
    -- from this STABLE predicate without performing the very act it is being asked about. BR-008
    -- and BR-044 CAN be called, and now are, above.
    --
    -- So these get a state of their own rather than a pass they did not earn. Nothing about the
    -- runtime changes: fn_phase_d_handler_execute refuses on ENFORCED_FAIL and NOT_IMPLEMENTED, and
    -- DELEGATED_TO_KERNEL_GUARD is neither. What changes is the count that may be claimed. A rule
    -- enforced by a guard this call never reaches is not a rule this predicate enforces.
    state := 'DELEGATED_TO_KERNEL_GUARD'; ok := true;
    reason := format('%s is enforced at %s, which raises %s. That routine %s, so this predicate cannot invoke it: the guard decides and this call does not.',
                     p_rule_id, e.enforcement_point, e.refusal_code,
                     case when e.enforcement_kind = 'TRIGGER_ENFORCED'
                          then 'returns trigger' else 'is a volatile writer' end);
    return next; return;
  end if;
  if e.enforcement_kind = 'CONTEXT_REQUIRED' then
    select array_agg(k order by k) into v_missing
      from unnest(e.required_context) k
     where not (p_context ? k) or coalesce(btrim(p_context->>k),'') = '';
    v_ok := (v_missing is null);
    -- E19. THE REFUSAL STANDS; ONLY ITS NAME CHANGES. This branch fires when the call names none of
    -- the evidence the rule reads, which is not the same event as the rule reading that evidence and
    -- finding it violates policy. Both refuse. The state stays ENFORCED_FAIL so that every existing
    -- reader -- fn_phase_d_handler_execute, fn_phase_d_rule_can_refuse, fn_phase_d_rule_state --
    -- behaves exactly as before; evidence_absent is the new fact, and it is what lets
    -- fn_phase_d_dispatch_step record REFUSED_EVIDENCE_ABSENT instead of REFUSED. A reader could
    -- previously take an absence of evidence for a business violation, and the 2026-08-20
    -- acceptance audit did exactly that and said so in finding 3.
    evidence_absent := not v_ok;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('%s: the call names %s', p_rule_id, array_to_string(e.required_context,', '))
                   else format('%s requires [%s] and the call names none of it.', p_rule_id, array_to_string(v_missing,', ')) end;
    return next; return;
  end if;

  -- ---------------- NO PREDICATE. This is the answer that used to be `true`. ----------------
  state := 'NOT_IMPLEMENTED'; ok := false; enforced := false;
  reason := format('%s has no predicate in fn_phase_d_rule_check. NOT_IMPLEMENTED is not a pass.', p_rule_id);
  refusal_code := coalesce(e.refusal_code, 'rule_not_implemented');
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_rule_state()
 RETURNS TABLE(check_name text, expected text, actual text, ok boolean)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_rules int; n_reg int; n_out int; n_unres int; n_alwaystrue int;
        n_can int; n_deleg int; n_held int; n_exec int;
begin
  select count(*) into n_rules from public.phase_b_business_rule;
  select count(*) into n_reg   from public.phase_d_rule_enforcement;

  check_name := 'every_frozen_rule_has_an_enforcement_row';
  expected := n_rules::text; actual := n_reg::text; ok := (n_reg = n_rules); return next;

  -- A named mechanism that does not exist is prose. Every enforcement_point naming a public
  -- routine is resolved in pg_proc; the two naming a table are resolved in pg_class.
  select count(*) into n_unres from public.phase_d_rule_enforcement e
   where e.enforcement_point like 'public.fn_%'
     and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                      where n.nspname = 'public'
                        and p.proname = split_part(split_part(e.enforcement_point,'.',2),'(',1));
  check_name := 'every_named_enforcement_routine_resolves';
  expected := '0'; actual := n_unres::text; ok := (n_unres = 0); return next;

  select count(*) into n_out from public.phase_d_rule_enforcement where status = 'OUTSTANDING';
  check_name := 'rules_with_outstanding_enforcement';
  expected := '0'; actual := n_out::text; ok := (n_out = 0); return next;

  -- The regression guard: the routine this replaced ended with an unconditional ok := true.
  select count(*) into n_alwaystrue
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'fn_phase_d_rule_check'
     and pg_get_functiondef(p.oid) !~ 'rule_unregistered';
  check_name := 'rule_check_refuses_an_unregistered_rule';
  expected := '0'; actual := n_alwaystrue::text; ok := (n_alwaystrue = 0); return next;

  -- ---- E10. WHAT "ENFORCED" MEANS ON THIS BOARD, SAID BESIDE THE NUMBER ----------------------
  -- rules_with_outstanding_enforcement counts phase_d_rule_enforcement.status, which is ENFORCED on
  -- all 54. That is a statement about a declared MECHANISM. It is not a statement about whether the
  -- predicate can produce a refusal, and the two were being read as one.
  -- fn_phase_d_rule_can_refuse() already answers the harder question by driving each rule against
  -- three probe contexts. Its answer has never been on this board. It is now, as disclosure rows:
  -- the mechanism count does not move, and a reader can no longer take 54/54 for 54 that refuse.
  select count(*) into n_can from public.fn_phase_d_rule_can_refuse() where can_refuse;
  check_name := 'rules_whose_predicate_can_actually_refuse';
  expected := 'informational — 54/54 ENFORCED is a mechanism count, not this';
  actual := n_can::text || ' of ' || n_reg::text
         || ' produce ENFORCED_FAIL on at least one of the three probe contexts';
  ok := true; return next;

  select count(*) into n_deleg from public.fn_phase_d_rule_can_refuse()
   where not can_refuse and note like 'delegated%';
  check_name := 'rules_the_kernel_guard_decides_not_the_predicate';
  expected := 'informational — enforced, and not by anything this predicate can invoke';
  actual := n_deleg::text || ' rule(s) delegated to a kernel guard';
  ok := true; return next;

  select count(*) into n_held from public.fn_phase_d_rule_can_refuse()
   where not can_refuse and note like 'constant%';
  check_name := 'rules_constant_while_a_founder_hold_stands';
  expected := 'informational — the founder''s to lift, not a defect';
  actual := n_held::text || ' rule(s) cannot vary while the provider hold stands';
  ok := true; return next;

  select count(*) into n_exec from public.fn_phase_d_rule_can_refuse()
   where not can_refuse and note not like 'delegated%' and note not like 'constant%';
  check_name := 'rules_enforced_somewhere_other_than_the_predicate';
  expected := 'informational';
  actual := n_exec::text || ' rule(s) enforced at the executor''s capability boundary';
  ok := true; return next;

  -- The four groups must still account for every registered rule. A decomposition that stops
  -- covering its subject is worse than none: the parts would sum to fewer than the whole and
  -- nothing would say so.
  check_name := 'every_registered_rule_carries_a_refusal_class';
  expected := n_reg::text; actual := (n_can + n_deleg + n_held + n_exec)::text;
  ok := (n_can + n_deleg + n_held + n_exec = n_reg); return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_scenario_record_write(p_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run bigint := public.fn_phase_d_fixture_context();
  v_id  bigint;
begin
  if v_run is null then
    raise exception 'fn_phase_d_scenario_record_write: no verified Phase D fixture context. The evidence manifest is written only inside an audited fixture run. (pd_fixture_no_test_context)'
      using errcode = '42501';
  end if;
  insert into public.phase_d_scenario_record
    (fixture_run_id, fixture_id, fixture_version, source_checksum, object_id, business_key,
     owner_ref, ownership_scope, state, canonical_relation, canonical_service, result_reference,
     contributes_ref, contributed_value, contributes_kind, trace_id, provenance, expected_effect,
     canonical_ref)
  values (v_run,
          p_input->>'fixture_id',
          coalesce(nullif(p_input->>'fixture_version','')::int, 1),
          p_input->>'source_checksum',
          p_input->>'object_id',
          p_input->>'business_key',
          nullif(p_input->>'owner_ref',''),
          coalesce(nullif(p_input->>'ownership_scope',''),'COMPANY'),
          nullif(p_input->>'state',''),
          nullif(p_input->>'canonical_relation',''),
          coalesce(nullif(p_input->>'canonical_service',''),'fn_phase_d_object_write'),
          nullif(p_input->>'result_reference',''),
          nullif(p_input->>'contributes_ref',''),
          nullif(p_input->>'contributed_value',''),
          nullif(p_input->>'contributes_kind',''),
          nullif(p_input->>'trace_id','')::bigint,
          coalesce(nullif(p_input->>'provenance',''),
                   'PHASE_D_FIXTURE_DO_NOT_PUBLISH — created by the zero-persistence scenario factory inside a transaction that is aborted'),
          nullif(p_input->>'expected_effect',''),
          -- F44/F45. The canonical reference the write service returned. The scenario row's own
          -- scenario_record_id is never the business object identity.
          p_input->'canonical_ref')
  on conflict (fixture_run_id, object_id, business_key) do update
     set state = excluded.state, result_reference = excluded.result_reference,
         contributed_value = excluded.contributed_value
  returning scenario_record_id into v_id;
  return v_id;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_schema_validate(p_schema_id text, p_payload jsonb)
 RETURNS TABLE(valid boolean, reason text, missing text[])
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sc public.phase_d_handler_schema%rowtype;
  v_missing text[];
  v_empty   text[];
  v_untyped text[];
  v_wrong   text[];
  v_badenum text[];
  v_unknown text[];
  v_known   text[];
  v_nodomain text[];
  v_undeclared text[];
begin
  select * into sc from public.phase_d_handler_schema where schema_id = p_schema_id;
  if not found then
    valid := false;
    reason := format('unknown schema %L — fail closed', p_schema_id);
    missing := '{}'; return next; return;
  end if;

  -- An absent payload is a refusal, never an empty pass. pct(got, 0) returning 100 is the shape
  -- of defect this avoids: no evidence is not full evidence.
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    valid := false;
    reason := format('schema %s expects an object, got %s',
                     p_schema_id, coalesce(jsonb_typeof(p_payload),'null'));
    missing := sc.required_keys; return next; return;
  end if;

  select array_agg(k order by k) into v_missing
    from unnest(sc.required_keys) k where not (p_payload ? k);
  if v_missing is not null then
    valid := false;
    reason := format('schema %s: required keys missing [%s]',
                     p_schema_id, array_to_string(v_missing, ', '));
    missing := v_missing; return next; return;
  end if;

  -- A key present and empty is the same absence wearing a different hat.
  select array_agg(k order by k) into v_empty
    from unnest(sc.required_keys) k
   where jsonb_typeof(p_payload->k) = 'null'
      or (jsonb_typeof(p_payload->k) = 'string' and btrim(p_payload->>k) = '')
      or (jsonb_typeof(p_payload->k) = 'array'  and jsonb_array_length(p_payload->k) = 0)
      or (jsonb_typeof(p_payload->k) = 'object' and p_payload->k = '{}'::jsonb);
  if v_empty is not null then
    valid := false;
    reason := format('schema %s: required keys present but empty [%s]',
                     p_schema_id, array_to_string(v_empty, ', '));
    missing := v_empty; return next; return;
  end if;

  -- ---- D46 (a) A KEY WITH NO RECORDED TYPE IS A BROKEN SCHEMA, NOT A PERMITTED ONE --------------
  -- If field_types does not mention a key the schema requires, the schema itself is refused. The
  -- alternative — treating an unstated type as "anything goes" — is how a missing declaration reads
  -- as a satisfied one.
  select array_agg(k order by k) into v_untyped
    from unnest(sc.required_keys) k where not (sc.field_types ? k);
  if v_untyped is not null then
    valid := false;
    reason := format('schema %s is incomplete: no declared type for [%s]. An unstated type is not an unconstrained one.',
                     p_schema_id, array_to_string(v_untyped, ', '));
    missing := v_untyped; return next; return;
  end if;

  -- ---- P01 (e) A KEY WITH NO REGISTERED SEMANTIC DOMAIN IS A BROKEN SCHEMA ----------------------
  -- Same shape as D46(a), one layer up. Gate 5 of the final acceptance audit failed because 140
  -- consequential keys carried no domain and nothing said so; an unregistered key is now refused
  -- rather than silently treated as free-form. public.phase_d_output_domain_registry classifies
  -- EVERY field on all 514 schemas, including the ones it classifies FREE_FORM — so this fires only
  -- when a schema has gained a key the registry has not been rebuilt for.
  select array_agg(k order by k) into v_nodomain
    from unnest(sc.required_keys || coalesce(sc.optional_keys,'{}')) k
   where not exists (select 1 from public.phase_d_output_domain_registry r
                      where r.schema_id = p_schema_id and r.field_name = k);
  if v_nodomain is not null then
    valid := false;
    reason := format('schema %s declares [%s] and public.phase_d_output_domain_registry classifies no semantic domain for %s. An unknown semantic domain fails closed: a field nobody has classified is not a field everybody may fill.',
                     p_schema_id, array_to_string(v_nodomain, ', '),
                     case when cardinality(v_nodomain) = 1 then 'it' else 'them' end);
    missing := v_nodomain; return next; return;
  end if;

  -- ---- P01 (f) THE REGISTRY AND THE ENFORCEMENT SURFACE MAY NOT DISAGREE -----------------------
  -- A field the registry calls CLOSED_ENUM whose schema declares no domain for it would be an
  -- unenforced closed domain — the exact state Gate 5 measured, wearing a registry row as cover.
  select array_agg(k order by k) into v_undeclared
    from public.phase_d_output_domain_registry r, lateral (select r.field_name k) x
   where r.schema_id = p_schema_id
     and r.field_semantic_type = 'CLOSED_ENUM'
     and not (sc.enum_domains ? r.field_name);
  if v_undeclared is not null then
    valid := false;
    reason := format('schema %s: [%s] are registered CLOSED_ENUM and the schema declares no domain for them. The registry and enum_domains may not disagree; rebuild the schema from the registry.',
                     p_schema_id, array_to_string(v_undeclared, ', '));
    missing := v_undeclared; return next; return;
  end if;

  -- ---- D46 (b) DECLARED TYPES ------------------------------------------------------------------
  select array_agg(format('%s expected %s got %s', k, sc.field_types->>k, jsonb_typeof(p_payload->k))
                   order by k)
    into v_wrong
    from unnest(sc.required_keys || coalesce(sc.optional_keys,'{}')) k
   where p_payload ? k
     and coalesce(sc.field_types->>k,'unconstrained') <> 'unconstrained'
     and jsonb_typeof(p_payload->k) is distinct from (sc.field_types->>k);
  if v_wrong is not null then
    valid := false;
    reason := format('schema %s: wrong types [%s]', p_schema_id, array_to_string(v_wrong, '; '));
    missing := '{}'; return next; return;
  end if;

  -- ---- D46 (c) DECLARED DOMAINS ----------------------------------------------------------------
  select array_agg(format('%s=%L is not one of [%s]', k, p_payload->>k,
                          (select string_agg(d, ', ')
                             from jsonb_array_elements_text(sc.enum_domains->k) d))
                   order by k)
    into v_badenum
    from jsonb_object_keys(sc.enum_domains) k
   where p_payload ? k
     and not (sc.enum_domains->k @> to_jsonb(p_payload->>k));
  if v_badenum is not null then
    valid := false;
    reason := format('schema %s: outside the declared domain [%s]',
                     p_schema_id, array_to_string(v_badenum, '; '));
    missing := '{}'; return next; return;
  end if;

  -- ---- D46 (d) UNKNOWN KEYS, WHERE THE CONTRACT IS CLOSED --------------------------------------
  if not coalesce(sc.additional_properties, true) then
    v_known := sc.required_keys || coalesce(sc.optional_keys, '{}');
    select array_agg(k order by k) into v_unknown
      from jsonb_object_keys(p_payload) k where not (k = any (v_known));
    if v_unknown is not null then
      valid := false;
      reason := format('schema %s declares a closed contract and the payload carries [%s]',
                       p_schema_id, array_to_string(v_unknown, ', '));
      missing := '{}'; return next; return;
    end if;
  end if;

  valid := true;
  reason := format('payload satisfies %s v%s (%s keys, %s typed, %s domain(s), %s, source digest %s)',
                   p_schema_id, sc.schema_version, cardinality(sc.required_keys),
                   (select count(*) from jsonb_each_text(sc.field_types) t
                     where t.value <> 'unconstrained'),
                   (select count(*) from jsonb_object_keys(sc.enum_domains)),
                   case when coalesce(sc.additional_properties,true)
                        then 'open to further keys' else 'closed' end,
                   left(sc.source_digest,12));
  missing := '{}'; return next;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_stage_content(p_object_id text, p_scope text, p_key text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_wf  text;
  v_n   int;
  v_val text;
begin
  select b.governing_workflow_id into v_wf
    from public.phase_d_business_object_binding b where b.object_id = p_object_id;

  -- The fixture written FOR this object's workflow, if there is one.
  select count(*), min(c.value #>> '{}') into v_n, v_val
    from public.phase_d_fixture_catalogue c
   where c.scope = p_scope and c.field_key = p_key
     and c.workflow_id is not null
     and (c.workflow_id = v_wf or v_wf like '%' || c.workflow_id || '%');
  if v_n = 1 then return v_val; end if;
  if v_n > 1 then
    raise exception 'fn_phase_d_stage_content: % fixtures at scope % for key % are scoped to the workflow of %. Refusing to choose one. (pd_fixture_ambiguous_content)',
      v_n, p_scope, p_key, p_object_id using errcode = '21000';
  end if;

  -- Otherwise the unscoped one, and there must be exactly one of those too.
  select count(*), min(c.value #>> '{}') into v_n, v_val
    from public.phase_d_fixture_catalogue c
   where c.scope = p_scope and c.field_key = p_key and c.workflow_id is null;
  if v_n > 1 then
    raise exception 'fn_phase_d_stage_content: % unscoped fixtures at scope % for key %. Refusing to choose one; scope them to the workflow they were written for. (pd_fixture_ambiguous_content)',
      v_n, p_scope, p_key using errcode = '21000';
  end if;
  return v_val;   -- null when nothing is committed, which the caller's own NOT NULL will report
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_stage_payment_state_declared()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.object_id in ('payment_transaction','reveal_transaction')
     and not exists (select 1 from public.phase_d_payment_state s
                      where s.state_key = NEW.working_state) then
    raise exception 'phase_d_fixture_stage: % declares working_state %, which is not a rung of public.phase_d_payment_state. BR-020 reads that ladder; a money state outside it is not a state. (pd_stage_payment_state_undeclared)',
      NEW.stage_key, NEW.working_state using errcode = '23514';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_step_context(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr public.phase_c_workflow_step_run%rowtype;
  v_val_txt text;  -- G02: the acceptance value read back before it becomes jsonb
  v_key_obj text;  -- G08: the object a context key names, from phase_d_context_key_object
  v_link    text;  -- G08: the column on this run's relation that reaches that object
  v_link_v  text;  -- G08: what that column holds
  v_scn_ref jsonb; -- G08: the canonical reference the scenario recorded for that object
  r  public.phase_c_workflow_run%rowtype;
  s  public.phase_b_workflow_step%rowtype;
  b  public.phase_d_handler_binding%rowtype;
  ec public.phase_d_step_effect%rowtype;
  v_keys   text[];
  v_k      text;
  v_val    jsonb;
  v_src    text;
  v_ctx    jsonb := '{}'::jsonb;
  v_prov   jsonb := '{}'::jsonb;
  v_unres  text[] := '{}';
  v_obj    text;
  v_boid   text;
  v_run_key text;
  v_rel    text;
  v_keycol text;
  v_owncol text;
  v_row_id text;
  v_row_own text;
  v_found  boolean := false;
  v_key_prefixed boolean := false;   -- E25
  v_sql    text;
  v_from   text;
  v_to     text;
  v_route  text;
  v_cmd    bigint;
  v_auth   jsonb;   -- K01
  v_src_ref   text;
  v_src_kind  text;
  v_src_class text;
  v_src_actor text;
  v_src_act   text;
  v_email     text;
  v_fx_val    jsonb;   -- F11
  v_fx_src    text;    -- F11
begin
  select * into sr from public.phase_c_workflow_step_run where step_run_id = p_step_run_id;
  if not found then
    raise exception 'fn_phase_d_step_context: no step run %', p_step_run_id using errcode = '23503';
  end if;
  select * into r  from public.phase_c_workflow_run    where run_id  = sr.run_id;
  select * into s  from public.phase_b_workflow_step   where step_id = sr.step_id;
  select * into b  from public.phase_d_handler_binding where step_id = sr.step_id;
  select * into ec from public.phase_d_step_effect     where step_id = sr.step_id;

  select coalesce(array_agg(distinct k), '{}') into v_keys from (
    select unnest(re.required_context) k from public.phase_d_rule_enforcement re
     where re.rule_id = any (coalesce(b.rule_ids,'{}'))
    union
    select unnest(gc.evidence_keys) k from public.phase_d_gate_contract gc
     where gc.gate_id = any (coalesce(b.gate_ids,'{}'))
    -- K03. THE PARENT OF THE RECORD THIS STEP WRITES. The list was the union of what the step's
    -- rules and gates ask for, and nothing else, so a key no rule happens to name was never
    -- resolved even where the estate could answer it. W16-S01 wrote a reveal payment that belonged
    -- to no quote for exactly that reason. The object's own frozen binding names its parent and the
    -- write map names the payload key that carries it; both are read here. A step that writes no
    -- business object adds nothing, and a key a rule already asks for is unchanged -- this is a
    -- distinct union.
    union
    select wm.column_map->>bb.parent_identity k
      from public.phase_d_business_object_binding bb
      join public.phase_d_object_write_map wm on wm.object_id = bb.object_id
     where bb.object_id = ec.effect_object_id
       and coalesce(btrim(bb.parent_identity),'') <> ''
       and wm.column_map ? bb.parent_identity
       and wm.column_map->>bb.parent_identity not in ('business_key','owner_ref','state')
    ) q(k);

  -- ---- the frozen state model ------------------------------------------------------------------
  v_from  := r.state;
  -- E12. THE RESOLVER NULLED A FACT THE GATE EXISTS TO JUDGE.
  --
  -- to_state is the step's own frozen declaration: phase_b_workflow_step.success_workflow_state.
  -- Until now this line also re-ran GATE-006's test on it, and blanked the value when the test
  -- failed. That is a different act from resolving, and it had two consequences.
  --
  -- First, it made the answer depend on WHEN the resolver was called rather than on what the
  -- registry says. fn_phase_d_dispatch_step runs inside fn_kernel_open_step, and a step opened out
  -- of a handoff is dispatched while its run is still in waiting_handoff -- the state it is
  -- leaving. The old guard therefore asked whether the run could go waiting_handoff ->
  -- waiting_handoff, which the frozen model rightly says it cannot, and nulled the key. Called a
  -- moment later, against the same step run, the same function resolved it. Measured 2026-08-20:
  -- W01-S04/S05/S06 record to_state in phase_d_dispatch.unresolved_keys, and a direct call for the
  -- same step runs resolves it to waiting_handoff.
  --
  -- Second, and worse, it turned a judgeable fact into an absent one. GATE-006 already tests the
  -- transition against public.phase_b_workflow_transition, and already holds the reasoned branch
  -- for the case where a step declares the state it is already in (55 of 257 steps do). With the
  -- key blanked, the gate could not reach either branch and reported "requires [to_state] and the
  -- call names none of it" -- an evidence-absence message standing in for a judgement the
  -- instrument was built to make.
  --
  -- The resolution is therefore the declaration, and the judgement stays with the gate. This is a
  -- REMOVAL: nothing new is asserted, and a transition the frozen model does not declare is still
  -- refused -- by GATE-006, which is the check that owns it.
  v_to    := nullif(btrim(coalesce(s.success_workflow_state,'')),'');
  -- D42. route_state IS NOT "the first declared transition, alphabetically". That is what this
  -- resolver did, and GATE-010 duly reported "route state approved; only a confirmed route carries
  -- dispatch authority" for an inquiry that had never been routed. Picking a plausible value out of
  -- the declared set is the placeholder defect wearing a schema. A route state exists when a route
  -- has been confirmed; until then the key is unresolved and GATE-010 refuses, which is the gate
  -- doing its job.
  v_route := null;

  -- ---- the arrival that caused this run, and how the register classifies it ---------------------
  select ti.source_system, 'trigger' into v_src_ref, v_src_kind
    from public.kernel_trigger_inbox ti where ti.run_id = sr.run_id order by ti.inbox_id desc limit 1;
  if v_src_ref is null and coalesce(btrim(coalesce(r.business_object_id,'')),'') <> '' then
    -- D39(2). The first step of a run dispatches INSIDE fn_kernel_workflow_start, before the inbox
    -- row is stamped with run_id. business_object_id is on both sides already, derived from the same
    -- object rule, so it is what links them at the only moment that matters.
    select ti.source_system, 'trigger' into v_src_ref, v_src_kind
      from public.kernel_trigger_inbox ti
     where ti.business_object_id = r.business_object_id
     order by ti.inbox_id desc limit 1;
  end if;
  if v_src_ref is null then
    select si.source_type, 'signal' into v_src_ref, v_src_kind
      from public.kernel_signal_inbox si
     where si.workflow_run_id = sr.run_id order by si.signal_id desc limit 1;
  end if;
  if v_src_ref is null then
    select tk.source_ref, tk.source_kind into v_src_ref, v_src_kind
      from public.phase_c_task tk where tk.run_id = sr.run_id order by tk.task_id limit 1;
  end if;
  -- D40. THE INBOX ROW IS NOT READABLE BY run_id OR business_object_id AT FIRST-STEP DISPATCH TIME.
  -- fn_kernel_trigger_submit inserts the inbox row, then calls fn_kernel_workflow_start passing
  -- source_ref = 'trigger_inbox:<inbox_id>', and stamps run_id and business_object_id onto that row
  -- only AFTER the call returns. The dispatch happens inside it, so both earlier matches were looking
  -- for columns the row does not carry yet. The inbox id IS in the source_ref the kernel already
  -- passes, and fn_kernel_workflow_start writes it onto the task before it opens the step — the one
  -- identifier available at the only moment that matters.
  if v_src_ref like 'trigger_inbox:%' then
    select ti.source_system, 'trigger' into v_src_ref, v_src_kind
      from public.kernel_trigger_inbox ti
     where ti.inbox_id = nullif(substr(v_src_ref, 15), '')::bigint;
  end if;
  if coalesce(btrim(coalesce(v_src_ref,'')),'') <> '' then
    select c.source_class, c.system_actor, c.current_activation
      into v_src_class, v_src_actor, v_src_act
      from public.phase_c_source_cutover c
     where c.source_component_id = v_src_ref limit 1;
  end if;

  -- ---- the run's own business object -----------------------------------------------------------
  v_obj := coalesce(nullif(btrim(coalesce(ec.effect_object_id,'')),''),
                    (select bo.object_id from public.phase_d_business_object_binding bo
                      where bo.governing_workflow_id = r.workflow_id limit 1));
  v_boid := nullif(btrim(coalesce(r.business_object_id,'')),'');
  -- THE RUN'S OWN PARTY, KEPT SEPARATELY. v_boid below is consumed by the STEP's object: where the
  -- step writes something other than what the run is about, the prefix does not match, the lookup
  -- fails and v_found is false. That is correct for the step's own subject and wrong for anything
  -- that belongs to the run as a whole. Measured 23 Aug 2026 on W09-S03: the run's
  -- business_object_id is 'supplier_account:37085' and the step's business object is
  -- supplier_capability on public.supplier_capabilities with row_found false, so the terms branch
  -- below had no anchor and fell through to the catalogue.
  v_run_key := case when v_boid like '%:%' then substr(v_boid, position(':' in v_boid) + 1) else null end;
  -- D39(1). The kernel writes the object rule out in full: 'inquiry:<uuid>'. Strip ONLY that
  -- object's own prefix; a blind split on ':' would corrupt an identifier that contains one.
  -- E25. WHETHER THE PREFIX MATCHED IS ITSELF A FACT, and the caller needs it. A run whose
  -- business_object_id is 'inquiry:<uuid>' names the object this step writes; one that reads
  -- 'outbox:195' or a probe label does not, and using the raw string as a business key would invent
  -- an identity for a record. Only a stripped key is a key.
  v_key_prefixed := (v_obj is not null and v_boid is not null and v_boid like (v_obj || ':%'));
  if v_key_prefixed then
    v_boid := substr(v_boid, length(v_obj) + 2);
  end if;
  if v_obj is not null and coalesce(v_boid,'') <> '' then
    select wm.target_relation, wm.key_column, wm.owner_column
      into v_rel, v_keycol, v_owncol
      from public.phase_d_object_write_map wm where wm.object_id = v_obj limit 1;
    if v_rel is not null and coalesce(btrim(v_keycol),'') <> ''
       and to_regclass(v_rel) is not null then
      begin
        v_sql := format('select %I::text, %s from %s where %I::text = $1 limit 1',
                        v_keycol,
                        case when coalesce(btrim(v_owncol),'') = '' then 'null::text'
                             else quote_ident(v_owncol) || '::text' end,
                        to_regclass(v_rel)::text, v_keycol);
        execute v_sql into v_row_id, v_row_own using v_boid;
        v_found := v_row_id is not null;
      exception when others then
        v_found := false;
      end;
    end if;
  end if;

  foreach v_k in array v_keys loop
    v_val := null; v_src := null;

    if v_k = 'from_state' then
      v_val := to_jsonb(v_from); v_src := 'phase_c_workflow_run.state';
    elsif v_k = 'to_state' then
      if v_to is not null then
        v_val := to_jsonb(v_to);
        v_src := 'phase_b_workflow_step.success_workflow_state, confirmed against phase_b_workflow_transition';
      end if;
    elsif v_k = 'route_state' then
      -- Resolved only from a route that actually exists. See the note above v_route.
      if v_route is not null then
        v_val := to_jsonb(v_route); v_src := 'the confirmed route for this inquiry';
      end if;

    elsif v_k in ('inquiry_id','supplier_id','quote_id','transaction_id','document_id',
                  'comparison_id','refund_id') then
      -- G08. THIS ANSWERED ALL SEVEN WITH THE RUN'S OWN ROW ID. See the file header: BR-015 was told
      -- a quote was a supplier, BR-020 that a comparison was a transaction, BR-013 that a document
      -- was an inquiry. Each key names an object, that object is recorded, and the answer must come
      -- from the object it names or not at all.
      select cko.object_id into v_key_obj
        from public.phase_d_context_key_object cko
       where cko.context_key = v_k and cko.key_role = 'IDENTIFIES';

      if v_found and v_key_obj is not null and v_key_obj = v_obj then
        -- The key names the object this run is about. The row id is the answer.
        v_val := to_jsonb(v_row_id);
        v_src := format('%s.%s, looked up by the run''s business_object_id', v_rel, v_keycol);

      elsif v_found and v_key_obj is not null then
        -- The key names a DIFFERENT object. Reach it from this run's own row, through a declared
        -- foreign key to that object's canonical relation where one exists, and otherwise through a
        -- column named exactly like the key. Both are read from the catalog; neither is listed here.
        select a.attname into v_link
          from pg_constraint con
          join lateral unnest(con.conkey) k(attnum) on true
          join pg_attribute a on a.attrelid = con.conrelid and a.attnum = k.attnum
         where con.contype = 'f'
           and con.conrelid = to_regclass(v_rel)
           and con.confrelid = (select to_regclass(bb.canonical_relation)
                                  from public.phase_d_business_object_binding bb
                                 where bb.object_id = v_key_obj)
         order by a.attname limit 1;
        if v_link is null then
          select a.attname into v_link from pg_attribute a
           where a.attrelid = to_regclass(v_rel) and a.attnum > 0 and not a.attisdropped
             and a.attname = v_k;
        end if;
        if v_link is not null then
          begin
            execute format('select %I::text from %s where %I::text = $1',
                           v_link, to_regclass(v_rel)::text, v_keycol)
              into v_link_v using v_row_id;
          exception when others then v_link_v := null; end;
          if coalesce(btrim(v_link_v),'') <> '' then
            v_val := to_jsonb(v_link_v);
            v_src := format('%s.%s of the run''s own row, which reaches %s', v_rel, v_link, v_key_obj);
          end if;
          v_link := null; v_link_v := null;
        end if;
      end if;
    elsif v_k = 'caller_customer_id' then
      -- G18. THE OWNER IS THE ANSWER ONLY WHEN THE OWNER IS A CUSTOMER.
      -- On a W14 run the business object is a quotation and its owner column is
      -- public.quotes.supplier_id, so this branch handed BR-019 a supplier and BR-019 refused,
      -- correctly, about the wrong party. Whether the owner column reaches the customer relation is
      -- read from the catalog, not assumed from the column's name.
      if v_found and v_row_own is not null and v_owncol is not null
         and exists (select 1
                       from pg_constraint con
                       join lateral unnest(con.conkey) k(attnum) on true
                       join pg_attribute a on a.attrelid = con.conrelid and a.attnum = k.attnum
                      where con.contype = 'f'
                        and con.conrelid = to_regclass(v_rel)
                        and a.attname = v_owncol
                        and con.confrelid = (select to_regclass(bb.canonical_relation)
                                               from public.phase_d_business_object_binding bb
                                              where bb.object_id = 'customer_account')) then
        v_val := to_jsonb(v_row_own);
        v_src := format('%s.%s of the run''s own object, which is a declared foreign key into the customer relation', v_rel, v_owncol);
      end if;

    elsif v_k = 'inquiry_owner' then
      -- D41. inquiry_owner IS A ROLE, NOT A CUSTOMER. BR-049 is the only consumer of this key —
      -- no gate declares it — and its predicate compares it to the literal role
      -- 'ceo'. Resolving it from inquiries.customer_id handed a rule about
      -- ACCOUNTABILITY a customer UUID, so it refused every inquiry the moment the owner started
      -- resolving at all. The frozen rule text is unambiguous: "Specialist and document handoffs do
      -- not transfer overall inquiry accountability away from RFQ Qualification Manager unless an
      -- explicit approved workflow says so."
      --
      -- The subject is therefore the role accountable for the INQUIRY, which is
      -- phase_c_workflow_run.accountable_role_id of the run that owns it. For a W05 run that is this
      -- run; for W06 and W07, which are the specialist workflows the rule is about, it is the W05
      -- run for the same inquiry, and where no such run exists the key stays unresolved rather than
      -- being answered with this run''s own role.
      --
      -- This is what makes the rule able to FAIL: it fails exactly when a run''s accountable role
      -- has drifted from the frozen registry''s, which is the drift BR-049 exists to catch.
      if r.workflow_id = 'W05' then
        v_val := to_jsonb(r.accountable_role_id);
        v_src := 'phase_c_workflow_run.accountable_role_id of this inquiry''s own run';
      elsif v_found then
        select to_jsonb(r2.accountable_role_id) into v_val
          from public.phase_c_workflow_run r2
         where r2.workflow_id = 'W05'
           and r2.business_object_id = ('inquiry:' || v_row_id)
         order by r2.run_id desc limit 1;
        v_src := 'phase_c_workflow_run.accountable_role_id of the W05 run that owns this inquiry';
        -- G09. AN INQUIRY NO RUN HAS CLAIMED HAS NOT DRIFTED FROM ANYTHING.
        -- Measured: W06-S01 and W07-S01 refused with "inquiry owner is (unstated)" because the
        -- inquiry exists and no W05 run does. The branch above still comes first, so an inquiry a
        -- run HAS claimed is answered by that run's actual role and BR-049 still refuses when it
        -- has drifted. Only the unclaimed case changes, and there the frozen registry's own
        -- accountable role for the workflow that owns the inquiry object is the answer -- read from
        -- public.phase_b_workflow, never named here.
      end if;
      -- G14. THE FALLBACK WAS INSIDE THE BRANCH THAT NEEDS THE RUN'S OWN ROW, AND W06 HAS NONE.
      -- W06's primary object is inquiry_route_set, whose fixture stage contributes a STATE rather
      -- than a key, so the run's business object never resolves and the branch above never ran.
      -- W06-S01 kept refusing with "inquiry owner is (unstated)" after G09 had supposedly answered
      -- it. The fallback belongs wherever nothing else has answered, which is here.
      if v_val is null then
        select to_jsonb(w2.accountable_role_id) into v_val
          from public.phase_b_workflow w2
         where w2.primary_object = 'inquiry' order by w2.workflow_id limit 1;
        v_src := 'phase_b_workflow.accountable_role_id of the workflow whose primary object is '
              || 'the inquiry -- no workflow run has claimed this inquiry, so accountability is '
              || 'where the frozen registry puts it and has not moved';
      end if;
    elsif v_k = 'monetary_state' then
      if v_found and v_rel like '%transactions' then
        select to_jsonb(t.fee_status) into v_val from public.transactions t
          where t.id::text = v_row_id limit 1;
        v_src := 'public.transactions.fee_status of the run''s own transaction';
      end if;

    elsif v_k = 'evidence_authority' then
      -- F13. THIS RESOLVED, AND RESOLVED TO SOMETHING THE RULE CANNOT RANK.
      --
      -- BR-029 is about RANK: lower-authority evidence may not silently overwrite higher, and the
      -- estate's ranking is public.mep_evidence_weight (alias, customer_text, document_extraction,
      -- scope_rule, structured_answer). This branch answered with the arrival CLASSIFICATION --
      -- "A NEW_WORK_REQUEST (system.task_engine) via dbtrigger:public.inquiries:trg_inquiry_received_a,
      -- activation ACTIVE" -- which is a true fact about how the run started and is not an evidence
      -- authority at all. Measured on every drive: 0 rows matched, so BR-029 refused for the whole
      -- estate, and it refused with a reason that read as though the authority were unranked rather
      -- than as though the resolver had answered a different question.
      --
      -- The correction is a REMOVAL plus a test: the classification is offered only if it actually
      -- appears in the ranking. When it does not, the key is UNRESOLVED, which is the honest state
      -- -- and which is what lets the Phase D fixture door supply a ranked authority, and what
      -- keeps BR-029 refusing in production where no such authority is named.
      if v_src_class is not null
         and exists (select 1 from public.mep_evidence_weight w
                      where w.weight_key = v_src_class or w.evidence_source = v_src_class
                         or w.source_authority = v_src_class) then
        v_val := to_jsonb(v_src_class);
        v_src := 'phase_c_source_cutover classification of the arrival that caused this run, confirmed present in the public.mep_evidence_weight ranking';
      elsif exists (select 1 from public.phase_d_object_record o
                     where o.object_id = 'document_extraction'
                       and o.payload->>'document_id' = coalesce(v_row_id,'')) then
        -- The run's own object carries a document extraction, and document_extraction IS a ranked
        -- evidence source. This is a read of what the run rests on, not a choice.
        v_val := to_jsonb('document_extraction'::text);
        v_src := 'public.mep_evidence_weight: the run''s own object carries a document extraction, which is a ranked evidence source';
      end if;

    elsif v_k = 'notify_email' then
      if v_found and v_row_own is not null then
        v_email := null;
        if v_owncol = 'customer_id' then
          select c.email into v_email from public.customers c where c.id::text = v_row_own limit 1;
        elsif v_owncol in ('supplier_id','lead_id') then
          select l.email into v_email from public.leads l where l.id::text = v_row_own limit 1;
        end if;
        if coalesce(btrim(coalesce(v_email,'')),'') <> '' then
          v_val := to_jsonb(v_email);
          v_src := format('the email of %s.%s, the owner of the run''s own object', v_rel, v_owncol);
        end if;
      end if;

    elsif v_k = 'evidence_refs' then
      -- E22. A CONDITION THE FIRST STEP OF A RUN COULD NEVER MEET.
      --
      -- This resolved evidence_refs from public.phase_d_effect_ledger for the run and nothing else.
      -- The FIRST step of a run has no predecessor, so it has no prior effect, so the key was
      -- unresolvable for it by construction — not sometimes, ever. BR-027 is bound to 59 steps and
      -- applies to 7 of the estate's first steps; six of those seven (the seventh is held by the
      -- capability boundary) were refused by a rule they had no way to satisfy. Measured 2026-08-20.
      --
      -- The fix is not to hand the key a placeholder. It is to notice that a first step DOES have
      -- evidence, and that the resolver was reading the wrong subject for it: what a first step
      -- rests on is THE ARRIVAL THAT OPENED THE RUN. That is a row — phase_c_workflow_run carries
      -- start_event, command_id and opened_at, and phase_c_source_cutover classifies the source
      -- component — so naming it is a read, not an invention.
      --
      -- THE ARRIVAL COUNTS ONLY FOR A STEP WITH NO PREDECESSOR, and that restriction is what keeps
      -- BR-027 able to fail. A later step must still show what the run has PRODUCED; if its
      -- predecessors produced nothing, it still gets nothing and BR-027 still refuses. Handing every
      -- call an automatic arrival reference would have turned a rule that refuses into a rule that
      -- cannot, which is the defect this file is fixing, in the other direction.
      select case when count(*) = 0 then null
                  else jsonb_agg(jsonb_build_object(
                         'effect_id', el.effect_id, 'step_id', el.step_id,
                         'effect_type', el.effect_type,
                         'result_reference', el.result_reference) order by el.effect_id) end
        into v_val
        from public.phase_d_effect_ledger el where el.run_id = sr.run_id;
      v_src := 'phase_d_effect_ledger for this run';

      if v_val is null
         and not exists (select 1 from public.phase_c_workflow_step_run pr
                          where pr.run_id = sr.run_id and pr.step_run_id < sr.step_run_id) then
        v_val := jsonb_build_array(jsonb_build_object(
          'kind',          'arrival',
          'run_id',        sr.run_id,
          'workflow_id',   r.workflow_id,
          'start_event',   nullif(btrim(coalesce(r.start_event,'')),''),
          'command_id',    r.command_id,
          'source_ref',    nullif(btrim(coalesce(v_src_ref,'')),''),
          'source_class',  v_src_class,
          'system_actor',  v_src_actor,
          'opened_at',     r.opened_at));
        v_src := 'the arrival that opened this run (phase_c_workflow_run.start_event/command_id '
              || 'plus its phase_c_source_cutover classification) — this step has no predecessor, '
              || 'so the arrival is the evidence it rests on';
      end if;

    elsif v_k = 'handoff_id' then
      -- D50. The handoff this step opens is a row of the frozen registry, not something a caller has
      -- to remember to pass. BR-008 was refusing for want of an identifier sitting in a table.
      select to_jsonb(hc.handoff_id) into v_val
        from public.phase_d_handoff_contract hc where hc.from_step_id = sr.step_id
       order by hc.handoff_id limit 1;
      v_src := 'phase_d_handoff_contract.handoff_id for the handoff this step opens';

    elsif v_k = 'sla_policy_id' then
      -- Likewise: the SLA policy of that handoff is recorded against it in the frozen registry.
      select to_jsonb(nullif(btrim(coalesce(h.sla_policy_id,'')),'')) into v_val
        from public.phase_b_handoff h where h.from_step_id = sr.step_id
       order by h.handoff_id limit 1;
      v_src := 'phase_b_handoff.sla_policy_id of the handoff this step opens';

    elsif v_k in ('packet','requested_action','source_version') then
      select case v_k
               when 'packet' then case when hc.packet_keys is null or cardinality(hc.packet_keys) = 0
                                       then null else to_jsonb(hc.packet_keys) end
               when 'requested_action' then to_jsonb(nullif(btrim(coalesce(hc.acceptance_criteria,'')),''))
               else to_jsonb(nullif(btrim(coalesce(hc.source_object_version_key,'')),'')) end
        into v_val
        from public.phase_d_handoff_contract hc where hc.from_step_id = sr.step_id limit 1;
      v_src := 'phase_d_handoff_contract for this step';

    elsif v_k = 'founder_authority_ref' then
      -- K01. GATE-005's frozen evidence is "Decision is within delegated authority OR founder
      -- approval exists", and this resolved only the second half, so a step whose run no founder
      -- instructed could never answer it. One resolver now answers both, from the founder's own
      -- frozen boundary register where no command instructed the run, and it reports the reference
      -- only when that reference is valid -- exists, current, and covering this workflow.
      v_auth := public.fn_phase_d_founder_authority(sr.run_id, sr.step_id);
      if coalesce((v_auth->>'valid')::boolean, false) then
        v_val := to_jsonb(v_auth->>'ref');
        v_src := v_auth->>'source';
      end if;

    elsif v_k = 'run_id' then
      -- E11. This function loads sr and r in its first ten lines and then declared run_id
      -- unresolved, which refused GATE-008 on every step in the estate for want of a number the
      -- same function was already holding.
      v_val := to_jsonb(sr.run_id);
      v_src := 'phase_c_workflow_step_run.run_id of this step run';

    elsif v_k = 'actor_role_id' then
      -- The role ACCOUNTABLE for this step run, read from the kernel's own row. Not the caller's
      -- claim about who they are: this function is given a step_run_id and nothing else, and a
      -- context resolver that took an identity from its caller would be answering the question it
      -- was asked to check.
      v_val := to_jsonb(nullif(btrim(coalesce(sr.accountable_role_id,'')),''));
      v_src := 'phase_c_workflow_step_run.accountable_role_id';

    elsif v_k = 'reviewer_role_id' then
      -- The INDEPENDENT reviewer the frozen binding declares, and only that. 45 of the 47 review
      -- steps name none, and for those this stays unresolved so GATE-004 and GATE-021 refuse —
      -- which is the gate working. Choosing a reviewer here would be fn_pick_reviewer returning the
      -- department head 182 times, one layer up.
      -- G02. THE REVIEWER WHO ACTUALLY REVIEWED, BEFORE THE ONE THE REGISTRY DECLARES.
      --
      -- This read only phase_d_handler_binding.independent_reviewer_role_id, which 229 of the 257
      -- steps leave blank, so every gate asking who reviewed something was answered "nobody" even
      -- after fn_kernel_review_decide had sealed a verdict and STAMPED THE REVIEWER on the task.
      -- fn_phase_d_recorded_review already reads that stamp and nothing consulted it here.
      --
      -- Order matters and this order is deliberate: the reviewer who actually reviewed outranks the
      -- reviewer a registry column names, because the gate's question is about the review that
      -- happened. Where no review has been recorded the declared reviewer still answers, and where
      -- neither exists the key stays unresolved and the gate refuses -- which is the gate working,
      -- and is what the previous comment here was protecting. Nothing chooses a reviewer: this
      -- resolver reports one or reports none, exactly as fn_pick_reviewer should have.
      v_val := to_jsonb(nullif(btrim(coalesce(
                 (public.fn_phase_d_recorded_review(p_step_run_id))->>'reviewer_role_id','')),''));
      if v_val is not null then
        v_src := 'phase_c_task.reviewer_role_id, stamped by fn_kernel_review_decide on the review '
              || 'actually recorded for this step run';
      else
        v_val := to_jsonb(nullif(btrim(coalesce(b.independent_reviewer_role_id,'')),''));
        v_src := 'phase_d_handler_binding.independent_reviewer_role_id, declared not chosen';
      end if;
      -- H03. A STEP THAT IS NOT A REVIEW IS ASKED ABOUT THE REVIEW THE RUN RECORDED. GATE-021 and
      -- GATE-026 apply from the first review step to the last step; at a publish step the reviewer
      -- is whoever reviewed earlier in this run. Read from the same task stamp, on an earlier step
      -- run of the same run, only where this step reviews nothing itself.
      if (v_val is null or v_val = 'null'::jsonb)
         and b.handler_class is distinct from 'REVIEW_HANDLER'
         and coalesce(btrim((select s3.independent_reviewer_role_id
                              from public.phase_b_workflow_step s3 where s3.step_id = sr.step_id)),'') = '' then
        select to_jsonb(nullif(btrim(coalesce(t2.reviewer_role_id,'')),'')) into v_val
          from public.phase_c_task t2
          join public.phase_c_workflow_step_run sr2
            on sr2.run_id = t2.run_id and sr2.step_id = t2.step_id
         where t2.run_id = sr.run_id
           and sr2.step_run_id < p_step_run_id
           and coalesce(btrim(t2.reviewer_role_id),'') <> ''
         order by sr2.step_run_id desc, t2.task_id desc
         limit 1;
        if v_val is not null then
          v_src := 'phase_c_task.reviewer_role_id of the most recent review fn_kernel_review_decide '
                || 'recorded on an earlier step run of this same run -- this step reviews nothing '
                || 'itself, and the gate asks about the review that happened';
        end if;
      end if;

    elsif v_k = 'step_id' then
      -- MENTIONED IN THIS FUNCTION AND NOT BRANCHED, which is why the first measurement of this
      -- defect missed it. sr.step_id appears in the return object at the bottom, so a grep for
      -- 'step_id' finds it and a reader concludes the key resolves. It did not. A mention is not a
      -- branch — the same lens that cost the 19 Aug audit its central premise, applied here to the
      -- very file that was measuring it.
      v_val := to_jsonb(sr.step_id);
      v_src := 'phase_c_workflow_step_run.step_id';

    elsif v_k = 'step_run_id' then
      v_val := to_jsonb(p_step_run_id);
      v_src := 'the step_run_id this function was called with';

    elsif v_k = 'acceptance_ref' then
      -- M01 (6 Sep 2026). THE ACCEPTANCE THIS RUN'S PARTY OWNS, BY ITS OWN BUSINESS KEY.
      -- BR-026 asks whether a certificate is preceded by a real acceptance RECORD, and its predicate
      -- checks acceptance_ref against public.phase_d_object_record.business_key. When a customer
      -- accepts the published terms through the product (kyc.accept_terms -> fn_customer_terms_accept)
      -- an APPEND_ONLY customer_terms_acceptance record is written owned by that customer. Read that
      -- record's business_key here, exactly as terms_version/terms_hash below read the pair it carries
      -- and for the same reason (G02, J05, L03): a key that names a record is answered from the
      -- record, never from a constant. A run whose party owns no acceptance resolves nothing here and
      -- falls through to the effect-ledger and scenario doors after the loop, where BR-026 still
      -- matches 0 rows and still refuses -- so the rule keeps its ability to fail.
      if coalesce(v_row_id, v_run_key) is not null then
        select o.business_key into v_val_txt
          from public.phase_d_object_record o
         where o.superseded_by is null
           and o.object_id in ('customer_terms_acceptance','supplier_terms_acceptance')
           and o.owner_ref in (v_row_id, v_run_key)
         order by (o.owner_ref = v_row_id) desc, o.record_id desc limit 1;
        if coalesce(btrim(v_val_txt),'') <> '' then
          v_val := to_jsonb(v_val_txt);
          v_src := 'the terms-acceptance record this run''s own business object owns, in '
                || 'public.phase_d_object_record.business_key -- the record BR-026 checks against';
        end if;
        v_val_txt := null;
      end if;

    elsif v_k in ('terms_version','terms_hash') then
      -- G02. A KEY THAT NAMES A RECORD WAS ANSWERED FROM A CONSTANT, AND THE CONSTANT WON.
      --
      -- BR-025 asks whether an acceptance references the exact displayed version AND hash, and it
      -- resolves the pair against public.legal_documents. Measured on W04 and W09: it refused with
      --
      --   "acceptance names version phase-d-fixture-terms-v1 at digest 5d31c13d1f0f, which matches
      --    0 row(s) in public.legal_documents whose displayed body hashes to exactly that digest"
      --
      -- Those two values are the COMMITTED CATALOGUE FIXTURES PDF-3104 and PDF-3105. Nothing was
      -- wrong with them; they are a real pair over a real fixture body. What was wrong is that they
      -- were the answer at all. The scenario factory reads the version and digest of the ACTUALLY
      -- PUBLISHED documents -- public.legal_documents customer-terms v3 and supplier-agreement v5 --
      -- and writes them onto the acceptance record it creates. Both keys then fell through every
      -- branch of this resolver to the fixture door, which answered from the catalogue, and the
      -- catalogue value shadowed the record the scenario had just written. That is D9g's "a
      -- generated fixture beat the real reference", one layer up, and F47's "a key that names an
      -- object is answered from that object's reference" stated for a third time.
      --
      -- THE ACCEPTANCE RECORD IS FOUND BY WHAT IT CARRIES, NOT BY WHAT IT IS CALLED. The record
      -- sought is the live object record owned by this run's own business object that carries both
      -- terms keys -- no object name, no naming convention, no workflow list. A run whose object
      -- row was not found, or that owns no acceptance, resolves nothing here and falls through to
      -- the catalogue exactly as before, where BR-025 still matches 0 rows and still refuses. The
      -- rule keeps its ability to fail, and it now also has a way to pass for a true reason.
      -- J05. AND THE ACCEPTANCE BELONGS TO THE RUN'S PARTY, NOT TO THE STEP'S SUBJECT. The block
      -- above anchored on v_row_id, which is the row the STEP is about. Measured on W09-S03, S05
      -- and S06: the run is about supplier_account 37085 and the step is about a
      -- supplier_capability that does not exist yet, so v_found was false, this branch never ran,
      -- and BR-025 was answered from catalogue fixtures PDF-3104/PDF-3105 --
      -- "acceptance names version phase-d-fixture-terms-v1 at digest 5d31c13d1f0f, which matches 0
      -- row(s) in public.legal_documents". The acceptance the scenario actually wrote names
      -- supplier-agreement v5, owned by 37085, and it was one join away the whole time.
      --
      -- A terms acceptance is a fact about the PARTY the run concerns; no step in a workflow makes
      -- it a fact about that step's own subject. So the step's subject is tried first, and the
      -- run's own party second. A run whose party owns no acceptance still resolves nothing and
      -- BR-025 still matches 0 rows and still refuses: the rule keeps its ability to fail.
      if coalesce(v_row_id, v_run_key) is not null then
        select o.payload ->> v_k into v_val_txt
          from public.phase_d_object_record o
         where o.superseded_by is null
           and o.payload ? 'terms_version' and o.payload ? 'terms_hash'
           and o.owner_ref in (v_row_id, v_run_key)
         order by (o.owner_ref = v_row_id) desc, o.record_id desc limit 1;
        if coalesce(btrim(v_val_txt),'') <> '' then
          v_val := to_jsonb(v_val_txt);
          v_src := 'the terms-acceptance record this run''s own business object owns, in '
                || 'public.phase_d_object_record -- the pair the acceptance actually names';
        end if;
        v_val_txt := null;
      end if;
      -- L03. AND AT THE STEP THAT RECORDS THE ACCEPTANCE THERE IS NOTHING TO FIND YET.
      -- W09-S06 is the only step in the estate whose declared effect object is a terms acceptance.
      -- Asked to withhold the object the workflow under test produces -- which is what a harness
      -- that does not answer its own question must do -- no acceptance record exists at S06, both
      -- keys fell to the catalogue door, and BR-025 refused with "matches 0 row(s) in
      -- public.legal_documents" for fixture PDF-3104/PDF-3105: a version string and a digest over
      -- a fixture terms body that is not a published document and never can be one.
      -- An acceptance step accepts THE CURRENTLY DISPLAYED DOCUMENT. Which document that is, for
      -- which acceptance object, is registered once in public.phase_d_acceptance_document and read
      -- from public.legal_documents here -- the same relation BR-025 judges against, so the rule
      -- keeps its ability to fail: a step that produces no registered acceptance resolves nothing
      -- here and falls through to the catalogue exactly as before.
      if coalesce(btrim(coalesce(v_val #>> '{}','')),'') = '' then
        select case when v_k = 'terms_version' then d.version
                    else encode(sha256(convert_to(coalesce(d.body_html,''),'UTF8')),'hex') end
          into v_val_txt
          from public.phase_d_step_effect x
          join public.phase_d_acceptance_document a on a.object_id = x.effect_object_id
          join public.legal_documents d on d.slug = a.document_slug
         where x.step_id = sr.step_id
         order by d.version desc limit 1;
        if coalesce(btrim(v_val_txt),'') <> '' then
          v_val := to_jsonb(v_val_txt);
          v_src := 'public.legal_documents — the currently published document this step''s own '
                || 'acceptance object accepts, per public.phase_d_acceptance_document';
        end if;
        v_val_txt := null;
      end if;

    elsif v_k = 'source_ref' then
      -- The arrival that caused this run, already computed into v_src_ref from kernel_trigger_inbox
      -- at the top of this function. Unresolved when no arrival is recorded, which is a fact about
      -- the run rather than a gap in this resolver.
      v_val := to_jsonb(nullif(btrim(coalesce(v_src_ref,'')),''));
      v_src := 'kernel_trigger_inbox.source_system for this run';

    else
      -- 40 of the 71 declared context keys still land here, and that is correct: artifact_sha256,
      -- terms_hash, legal_review_ref, denominator, formula, outcome_metric and the rest are facts a
      -- CALLER produces at runtime, not facts this estate holds. They stay unresolved and their
      -- rules and gates refuse, which is the contract working.
      -- exception_authority_ref is here on purpose too: BR-043 applies only when the call names a
      -- policy exception, and inventing an authority reference would be the placeholder defect the
      -- D42 comment above already refused once for route_state.
      v_val := null; v_src := null;
    end if;


    -- G08. THE SCENARIO-REFERENCE DOOR, in front of the catalogue and behind every real source.
    --
    -- public.quote_comparisons carries no transaction column and public.documents relates to its
    -- inquiry through a polymorphic (ref_table, ref_id) pair, so no derivation from the schema can
    -- reach W15's transaction_id or W07's inquiry_id from the run's own row. The scenario created
    -- both objects and recorded the canonical reference of each. This answers from THAT -- a row the
    -- scenario actually wrote through fn_phase_d_object_write -- rather than from the committed
    -- constant the fixture door below would otherwise supply.
    --
    -- It returns nothing unless fn_phase_d_fixture_context() verifies an hmac over the current txid
    -- keyed by a secret no role can SELECT. In production this block resolves nothing at all.
    -- K07. THE OBJECT THIS RUN ALREADY CREATED, before any fixture is consulted.
    --
    -- A key that names an object was answered from the run's own row, from a declared foreign key
    -- on it, or -- fixture context only -- from the canonical reference the SCENARIO recorded.
    -- Nothing answered "the object THIS RUN produced at an earlier step", so W17-S07 asked for the
    -- refund_id of a refund_dispute_case that W17-S01 had created six steps earlier and was told
    -- there was none. public.phase_d_effect_ledger holds it: run_id, effect_object_id and the
    -- canonical result_reference fn_phase_d_object_write returned. This is not a fixture and it runs
    -- in production; it is asked after every source that reads the run's own row, and before the
    -- scenario record, because a fact this run produced outranks one a scenario planted.
    if (v_val is null or v_val = 'null'::jsonb
        or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = '')) then
      select cko.object_id into v_key_obj
        from public.phase_d_context_key_object cko
       where cko.context_key = v_k and cko.key_role = 'IDENTIFIES';
      if v_key_obj is not null then
        select nullif(btrim(substring(el.result_reference from position('=' in el.result_reference) + 1)),'')
          into v_link_v
          from public.phase_d_effect_ledger el
          join public.phase_d_business_object_binding bb on bb.object_id = el.effect_object_id
         where el.run_id = sr.run_id
           and el.effect_object_id = v_key_obj
           -- AN EFFECT NAMED FOR AN OBJECT IS NOT ALWAYS A REFERENCE TO ONE. phase_d_effect_ledger
           -- records effect_object_id from the step's DECLARED object, so a REVIEW_VERDICT step of
           -- W15 carries effect_object_id quotation_comparison and result_reference
           -- public.review_chain:id=15748 -- the identity of the review, not of the comparison.
           -- Taking it made GATE-018 judge a review row as a comparison and refuse W15-S05 for
           -- 'comparison 15748 does NOT belong to the calling customer', which was true and was
           -- about the wrong row. Only a reference into the object's OWN canonical relation is an
           -- identity of that object.
           and el.effect_relation = bb.canonical_relation
           and coalesce(btrim(el.result_reference),'') <> ''
           and position('=' in el.result_reference) > 0
         order by el.effect_id desc limit 1;
        if v_link_v is not null then
          v_ctx  := v_ctx  || jsonb_build_object(v_k, to_jsonb(v_link_v));
          v_prov := v_prov || jsonb_build_object(v_k,
            format('the canonical reference of the %s this run itself created, read from '
                || 'public.phase_d_effect_ledger.result_reference', v_key_obj));
          v_link_v := null; v_key_obj := null;
          continue;
        end if;
      end if;
      v_key_obj := null;
    end if;

    if (v_val is null or v_val = 'null'::jsonb
        or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = ''))
       and public.fn_phase_d_fixture_context() is not null then
      select cko.object_id into v_key_obj
        from public.phase_d_context_key_object cko
       where cko.context_key = v_k and cko.key_role = 'IDENTIFIES';
      if v_key_obj is not null then
        select sc.canonical_ref into v_scn_ref
          from public.phase_d_scenario_record sc
         where sc.fixture_run_id = public.fn_phase_d_fixture_context()
           and sc.object_id = v_key_obj
         order by sc.scenario_record_id desc limit 1;
        if v_scn_ref is not null
           and coalesce(btrim(v_scn_ref->>'canonical_identity'),'') <> '' then
          v_ctx  := v_ctx  || jsonb_build_object(v_k, to_jsonb(v_scn_ref->>'canonical_identity'));
          v_prov := v_prov || jsonb_build_object(v_k,
            format('the canonical reference the scenario recorded for %s in '
                || 'public.phase_d_scenario_record -- a row this scenario created through '
                || 'fn_phase_d_object_write, not a committed constant', v_key_obj));
          v_scn_ref := null; v_key_obj := null;
          continue;
        end if;
        v_scn_ref := null;
      end if;
      v_key_obj := null;
    end if;

    -- F11. THE FIXTURE DOOR, AND ONLY AFTER EVERY REAL SOURCE HAS BEEN TRIED.
    --
    -- The founder's section B: "A deterministic handler must not invent business content. The
    -- scenario catalogue supplies explicit test values... The handler receives the fixture as
    -- input. The handler must not generate the fixture itself."
    --
    -- This is where the fixture becomes an input. It runs in the RESOLVER, which is called by
    -- fn_phase_d_dispatch_step before fn_phase_d_handler_execute is entered, so the handler is
    -- handed a value and never reaches for one. And it runs LAST: a key a real row can answer is
    -- answered by that row, and the fixture never shadows a fact.
    --
    -- fn_phase_d_fixture_input returns NO ROW unless fn_phase_d_fixture_context() verifies an hmac
    -- over the current txid keyed by a secret no role can read. In production there is no such
    -- context, so this block resolves nothing, the key stays unresolved, and its rule or gate
    -- refuses exactly as it did before this file existed.
    if v_val is null or v_val = 'null'::jsonb
       or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = '') then
      select fi.value, fi.provenance || format(' [fixture %s v%s %s]', fi.fixture_id,
                                               fi.fixture_version, left(fi.checksum, 12))
        into v_fx_val, v_fx_src
        from public.fn_phase_d_fixture_input(p_step_run_id, 'CONTEXT_KEY', v_k) fi;
      if v_fx_val is not null then
        v_ctx := v_ctx || jsonb_build_object(v_k, v_fx_val);
        v_prov := v_prov || jsonb_build_object(v_k, v_fx_src);
        v_fx_val := null; v_fx_src := null;
        continue;
      end if;
    end if;
    if v_val is null or v_val = 'null'::jsonb
       or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = '') then
      v_unres := v_unres || v_k;
    else
      v_ctx  := v_ctx  || jsonb_build_object(v_k, v_val);
      v_prov := v_prov || jsonb_build_object(v_k, v_src);
    end if;
  end loop;

  return jsonb_build_object(
    'step_run_id', p_step_run_id, 'step_id', sr.step_id,
    'declared_keys', to_jsonb(v_keys),
    'context', v_ctx, 'provenance', v_prov, 'unresolved', to_jsonb(v_unres),
    'arrival', jsonb_build_object('source_ref', v_src_ref, 'source_kind', v_src_kind,
                                  'source_class', v_src_class, 'activation', v_src_act),
    'business_object', jsonb_build_object(
      'object_id', v_obj, 'object_key', v_boid, 'relation', v_rel, 'key_column', v_keycol,
      'owner_column', v_owncol, 'row_found', v_found,
      -- E25. The two facts fn_phase_d_effect_produce demands of its caller, reported here because
      -- this is the routine that already resolved them and the dispatch had no way to know them.
      'key_is_prefixed', v_key_prefixed,
      'row_owner_ref', v_row_own,
      'ownership_scope', (select ob.ownership_scope
                            from public.phase_d_business_object_binding ob
                           where ob.object_id = v_obj)));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_step_inputs(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr public.phase_c_workflow_step_run%rowtype;
  r  public.phase_c_workflow_run%rowtype;
  w  public.phase_b_workflow%rowtype;
  s  public.phase_b_workflow_step%rowtype;
  b  public.phase_d_handler_binding%rowtype;
  v_keys   text[];
  v_k      text;
  v_val    jsonb;
  v_src    text;
  v_in     jsonb := '{}'::jsonb;
  v_prov   jsonb := '{}'::jsonb;
  v_res    text[] := '{}';
  v_unres  text[] := '{}';
  v_fx_val jsonb;   -- F11
  v_fx_src text;    -- F11
  v_cmd    bigint;
begin
  select * into sr from public.phase_c_workflow_step_run where step_run_id = p_step_run_id;
  if not found then
    raise exception 'fn_phase_d_step_inputs: no step run %', p_step_run_id using errcode = '23503';
  end if;
  select * into r  from public.phase_c_workflow_run    where run_id  = sr.run_id;
  select * into s  from public.phase_b_workflow_step   where step_id = sr.step_id;
  select * into w  from public.phase_b_workflow        where workflow_id = r.workflow_id;
  select * into b  from public.phase_d_handler_binding where step_id = sr.step_id;

  select coalesce(sc.required_keys, '{}') into v_keys
    from public.phase_d_handler_schema sc
   where sc.step_id = sr.step_id and sc.schema_kind = 'input';
  if v_keys is null then v_keys := '{}'; end if;

  -- The founder command that caused this run, if one did. W01 is started by
  -- fn_founder_command_submit through os_api, so for that workflow this is the real instruction.
  select l.command_id into v_cmd
    from public.founder_command_workflow_link l where l.run_id = sr.run_id limit 1;
  if v_cmd is null then v_cmd := r.command_id; end if;

  foreach v_k in array v_keys loop
    v_val := null; v_src := null;

    if v_k = 'workflow_record' then
      v_src := 'phase_c_workflow_run + phase_b_workflow + phase_b_workflow_step';
      v_val := jsonb_build_object(
        'run_id', r.run_id, 'workflow_id', r.workflow_id, 'workflow_name', w.workflow_name,
        'domain', w.domain, 'criticality', w.criticality, 'primary_object', w.primary_object,
        'business_object_id', nullif(btrim(coalesce(r.business_object_id,'')),''),
        'object_version', r.object_version, 'run_state', r.state, 'start_event', r.start_event,
        'run_accountable_role_id', r.accountable_role_id, 'opened_at', r.opened_at,
        'step_id', sr.step_id, 'step_name', s.step_name,
        'step_accountable_role_id', sr.accountable_role_id,
        'required_inputs', s.required_inputs, 'required_output', s.required_output,
        'acceptance_criteria', s.acceptance_criteria, 'closure_criteria', s.closure_criteria);

    elsif v_k = 'prior_accepted_outputs' then
      -- THE RECORD of what this run has already accepted. The kernel stores the accepted output's
      -- sha256, never the payload, so the hash IS the identity of the accepted output and the
      -- effect ledger row IS what it produced. Nothing here is reconstructed from prose.
      -- A count of 0 is a fact about a first step, not an absence: the object is returned with
      -- count 0 rather than an empty array, because fn_phase_d_schema_validate reads [] as missing.
      v_src := 'phase_c_workflow_step_run(completed) + phase_d_effect_ledger, this run only';
      select jsonb_build_object(
               'count', count(*),
               'run_id', sr.run_id,
               'outputs', coalesce(jsonb_agg(jsonb_build_object(
                   'step_id', pr.step_id, 'step_run_id', pr.step_run_id,
                   'output_hash', pr.output_hash, 'authority_result', pr.authority_result,
                   'gates_evaluated', pr.gates_evaluated, 'finished_at', pr.finished_at,
                   'effects', coalesce((select jsonb_agg(jsonb_build_object(
                                  'effect_id', el.effect_id, 'effect_type', el.effect_type,
                                  'effect_object_id', el.effect_object_id,
                                  'result_reference', el.result_reference,
                                  'state_after', el.state_after) order by el.effect_id)
                                from public.phase_d_effect_ledger el
                               where el.step_run_id = pr.step_run_id), '[]'::jsonb))
                 order by pr.step_run_id), '[]'::jsonb))
        into v_val
        from public.phase_c_workflow_step_run pr
       where pr.run_id = sr.run_id
         and pr.state = 'completed'
         and pr.step_run_id < sr.step_run_id;

    elsif v_k = 'applicable_policy' then
      v_src := 'phase_d_rule_enforcement + phase_d_gate_contract, in scope for this step';
      v_val := jsonb_build_object(
        'step_id', sr.step_id, 'founder_gate', b.founder_gate,
        'rule_count', coalesce(cardinality(b.rule_ids), 0),
        'gate_count', coalesce(cardinality(b.gate_ids), 0),
        'rules', coalesce((select jsonb_agg(jsonb_build_object(
                    'rule_id', re.rule_id, 'rule_type', re.rule_type,
                    'enforcement_kind', re.enforcement_kind, 'enforcement_point', re.enforcement_point,
                    'refusal_code', re.refusal_code, 'applies_when', re.applies_when,
                    'status', re.status) order by re.rule_id)
                  from public.phase_d_rule_enforcement re
                 where re.rule_id = any (coalesce(b.rule_ids,'{}'))), '[]'::jsonb),
        'gates', coalesce((select jsonb_agg(jsonb_build_object(
                    'gate_id', gc.gate_id, 'predicate_kind', gc.predicate_kind,
                    'refusal_code', gc.refusal_code, 'evidence_keys', to_jsonb(gc.evidence_keys),
                    'correction_owner', gc.correction_owner) order by gc.gate_id)
                  from public.phase_d_gate_contract gc
                 where gc.gate_id = any (coalesce(b.gate_ids,'{}'))), '[]'::jsonb));

    elsif v_k in ('founder_instruction','founder_mandate') then
      v_src := 'founder_command via founder_command_workflow_link / phase_c_workflow_run.command_id';
      select jsonb_build_object(
               'command_id', fc.command_id, 'outcome', fc.outcome, 'state', fc.state,
               'priority', fc.priority, 'command_owner_role_id', fc.command_owner_role_id,
               'primary_role_id', fc.primary_role_id,
               'founder_initiated_only', fc.founder_initiated_only,
               'refund_semantics', fc.refund_semantics, 'created_at', fc.created_at)
        into v_val
        from public.founder_command fc where fc.command_id = v_cmd;

    elsif v_k = 'current_approved_founder_policies' then
      v_src := 'governance_policy + policy_rules(active)';
      select jsonb_build_object(
               'governance_policy_count', (select count(*) from public.governance_policy),
               'governance_policy', coalesce((select jsonb_agg(jsonb_build_object(
                   'id', gp.id, 'domain', gp.domain, 'policy', gp.policy, 'rule', gp.rule,
                   'enforced_by', gp.enforced_by, 'enforcement', gp.enforcement,
                   'owner_dept', gp.owner_dept) order by gp.id)
                   from public.governance_policy gp), '[]'::jsonb),
               'policy_rules', coalesce((select jsonb_agg(jsonb_build_object(
                   'id', pr2.id, 'name', pr2.name, 'severity', pr2.severity, 'scope', pr2.scope)
                   order by pr2.id) from public.policy_rules pr2 where pr2.active), '[]'::jsonb))
        into v_val;

    elsif v_k in ('current_company_objective','approved_company_objectives_and_department_mandates') then
      v_src := 'company_goals(active) + org_departments(active)';
      select jsonb_build_object(
               'goal_count', (select count(*) from public.company_goals where active),
               'goals', coalesce((select jsonb_agg(jsonb_build_object(
                   'key', cg.key, 'goal', cg.goal, 'metric', cg.metric,
                   'target_value', cg.target_value, 'unit', cg.unit, 'period', cg.period,
                   'owner_dept', cg.owner_dept, 'horizon', cg.horizon, 'deadline', cg.deadline)
                   order by cg.sort, cg.key) from public.company_goals cg where cg.active), '[]'::jsonb),
               'departments', coalesce((select jsonb_agg(jsonb_build_object(
                   'dept_key', od.dept_key, 'name', od.name) order by od.dept_key)
                   from public.org_departments od where od.active), '[]'::jsonb))
        into v_val;

    elsif v_k = 'department_mandates' then
      v_src := 'org_departments(active)';
      select jsonb_build_object(
               'count', count(*),
               'departments', coalesce(jsonb_agg(jsonb_build_object(
                   'dept_key', od.dept_key, 'name', od.name, 'charter', od.charter,
                   'north_star', od.north_star) order by od.dept_key), '[]'::jsonb))
        into v_val
        from public.org_departments od where od.active;

    elsif v_k = 'kpi_tree' then
      v_src := 'company_goals(active) grouped by owner_dept';
      select jsonb_build_object(
               'metric_count', (select count(*) from public.company_goals where active),
               'by_department', coalesce(jsonb_object_agg(q.dept, q.metrics), '{}'::jsonb))
        into v_val
        from (select coalesce(nullif(btrim(cg.owner_dept),''),'(unassigned)') as dept,
                     jsonb_agg(jsonb_build_object('key', cg.key, 'metric', cg.metric,
                       'target_value', cg.target_value, 'unit', cg.unit) order by cg.key) as metrics
                from public.company_goals cg where cg.active group by 1) q;

    elsif v_k = 'current_company_state' then
      v_src := 'measured counts: active goals, active departments, open runs, open tasks';
      select jsonb_build_object(
               'measured_at', now(),
               'active_goals', (select count(*) from public.company_goals where active),
               'active_departments', (select count(*) from public.org_departments where active),
               'open_workflow_runs', (select count(*) from public.phase_c_workflow_run
                                       where closed_at is null),
               'open_tasks', (select count(*) from public.phase_c_task where closed_at is null))
        into v_val;

    elsif v_k in ('strategy_options','strategy_option','current_baseline','issued_initiatives',
                  'complete_ownership_and_measurement_setup') then
      -- These are produced by an EARLIER step of the same run. They resolve only once that step has
      -- completed; before that they are genuinely absent and the step must wait, not guess.
      v_src := 'prior completed step runs of this run';
      select jsonb_build_object(
               'produced_by_count', count(*),
               'produced_by', coalesce(jsonb_agg(jsonb_build_object(
                 'step_id', pr.step_id, 'output_hash', pr.output_hash,
                 'finished_at', pr.finished_at) order by pr.step_run_id), '[]'::jsonb))
        into v_val
        from public.phase_c_workflow_step_run pr
       where pr.run_id = sr.run_id and pr.state = 'completed' and pr.step_run_id < sr.step_run_id;
      if coalesce((v_val->>'produced_by_count')::int, 0) = 0 then
        v_val := null;   -- nothing has produced it yet: unresolved, not an empty pass
      end if;

    elsif v_k = 'budget_envelope' then
      -- E9. The prior body said "NO TABLE IN THIS ESTATE HOLDS THESE" and named this key.
      -- public.department_budget holds monthly_aed, spent_aed and the two degrade/halt thresholds
      -- for every active department. That IS a budget envelope. It is read here, not invented.
      v_src := 'department_budget joined to org_departments(active)';
      select jsonb_build_object(
               'measured_at', now(),
               'department_count', count(*),
               'monthly_aed_total', coalesce(sum(db.monthly_aed), 0),
               'spent_aed_total',   coalesce(sum(db.spent_aed), 0),
               'departments', coalesce(jsonb_agg(jsonb_build_object(
                   'dept_key', db.dept_key, 'monthly_aed', db.monthly_aed,
                   'spent_aed', db.spent_aed, 'period_label', db.period_label,
                   'degrade_at_pct', db.degrade_at_pct, 'halt_at_pct', db.halt_at_pct,
                   'updated_at', db.updated_at) order by db.dept_key), '[]'::jsonb))
        into v_val
        from public.department_budget db
        join public.org_departments od on od.dept_key = db.dept_key and od.active;
      -- No budget row is not an empty envelope; it is an unanswered question.
      if coalesce((v_val->>'department_count')::int, 0) = 0 then v_val := null; end if;

    elsif v_k = 'resource_envelope' then
      -- Money AND people, because a resource envelope that names only money cannot bound a plan
      -- this company executes with 90 active agents across 10 departments.
      v_src := 'department_budget + org_departments(active) + org_agents(active)';
      select jsonb_build_object(
               'measured_at', now(),
               'active_departments', (select count(*) from public.org_departments where active),
               'active_agents',      (select count(*) from public.org_agents where active),
               'monthly_aed_total',  coalesce((select sum(monthly_aed) from public.department_budget), 0),
               'spent_aed_total',    coalesce((select sum(spent_aed)   from public.department_budget), 0),
               'by_department', coalesce((select jsonb_agg(jsonb_build_object(
                   'dept_key', od.dept_key, 'name', od.name,
                   'monthly_aed', db.monthly_aed, 'spent_aed', db.spent_aed,
                   'agents', (select count(*) from public.org_agents a
                               where a.active and a.department = od.dept_key))
                   order by od.dept_key)
                 from public.org_departments od
                 left join public.department_budget db on db.dept_key = od.dept_key
                where od.active), '[]'::jsonb))
        into v_val;
      if coalesce((v_val->>'active_departments')::int, 0) = 0 then v_val := null; end if;

    elsif v_k = 'current_cash_budget_and_commitments' then
      -- Budget is what may be spent; commitments are what already has been. Both come from rows:
      -- department_budget for the envelope and the posted general journal for the commitments.
      -- A cash POSITION is not claimed — no table in this estate holds a bank balance, and saying
      -- so is better than deriving one.
      v_src := 'department_budget + gl_journal(posted) — budget and commitments; NO cash position, '
            || 'because no relation in this estate holds one';
      select jsonb_build_object(
               'measured_at', now(),
               'cash_position_available', false,
               'cash_position_note', 'no relation in this estate holds a bank balance',
               'budget_monthly_aed', coalesce((select sum(monthly_aed) from public.department_budget), 0),
               'budget_spent_aed',   coalesce((select sum(spent_aed)   from public.department_budget), 0),
               'budget_by_department', coalesce((select jsonb_agg(jsonb_build_object(
                   'dept_key', db.dept_key, 'monthly_aed', db.monthly_aed, 'spent_aed', db.spent_aed,
                   'halt_at_pct', db.halt_at_pct) order by db.dept_key)
                 from public.department_budget db), '[]'::jsonb),
               'posted_journal_entries', (select count(*) from public.gl_journal where status = 'posted'),
               'commitments', coalesce((select jsonb_agg(jsonb_build_object(
                   'entry_no', j.entry_no, 'entry_date', j.entry_date, 'memo', j.memo,
                   'source', j.source, 'currency', j.currency) order by j.entry_date desc, j.entry_no desc)
                 from (select * from public.gl_journal
                        where status = 'posted' order by entry_date desc, entry_no desc limit 50) j),
                 '[]'::jsonb))
        into v_val;
      if coalesce((v_val->>'budget_monthly_aed')::numeric, 0) = 0
         and coalesce((v_val->>'posted_journal_entries')::int, 0) = 0 then
        v_val := null;   -- neither a budget nor a commitment on file: genuinely unanswered
      end if;

    elsif v_k = 'external_and_internal_evidence' then
      -- INTERNAL evidence is what the company recorded about itself; EXTERNAL is what it recorded
      -- about the world. Both halves are named separately so a reader can see which one is thin,
      -- and external_available is a measured boolean rather than an implied one.
      v_src := 'company_event(30d) + company_index(90d) + decision_trace(30d)';
      select jsonb_build_object(
               'measured_at', now(),
               'window', '30 days for events and decisions, 90 days for measured indices',
               'internal_event_count',    (select count(*) from public.company_event
                                            where occurred_at > now() - interval '30 days'),
               'internal_decision_count', (select count(*) from public.decision_trace
                                            where created_at > now() - interval '30 days'),
               'measured_index_count',    (select count(*) from public.company_index
                                            where measured_on > current_date - 90),
               'measured_indices', coalesce((select jsonb_agg(jsonb_build_object(
                   'index_name', ci.index_name, 'score', ci.score, 'band', ci.band,
                   'measured_on', ci.measured_on) order by ci.measured_on desc, ci.index_name)
                 from (select distinct on (index_name) index_name, score, band, measured_on
                         from public.company_index where measured_on > current_date - 90
                        order by index_name, measured_on desc) ci), '[]'::jsonb),
               'event_types', coalesce((select jsonb_object_agg(t.event_type, t.n)
                 from (select event_type, count(*) n from public.company_event
                        where occurred_at > now() - interval '30 days'
                        group by 1 order by 2 desc limit 25) t), '{}'::jsonb),
               'external_available', false,
               'external_note', 'no external-signal relation is on file; supplier discovery has been '
                             || 'paused since 2026-08-10 and nothing else in this estate records an '
                             || 'outside source')
        into v_val;
      if coalesce((v_val->>'internal_event_count')::int, 0) = 0
         and coalesce((v_val->>'measured_index_count')::int, 0) = 0
         and coalesce((v_val->>'internal_decision_count')::int, 0) = 0 then
        v_val := null;
      end if;

    else
      -- Every key the frozen registry declares is now named above. This branch is the fail-closed
      -- default for a key added later: unresolved, never a placeholder, because a placeholder makes
      -- the step complete on a fact it never had.
      v_val := null;
      v_src := null;
    end if;


    -- F11. THE FIXTURE DOOR, AND ONLY AFTER EVERY REAL SOURCE HAS BEEN TRIED.
    --
    -- The founder's section B: "A deterministic handler must not invent business content. The
    -- scenario catalogue supplies explicit test values... The handler receives the fixture as
    -- input. The handler must not generate the fixture itself."
    --
    -- This is where the fixture becomes an input. It runs in the RESOLVER, which is called by
    -- fn_phase_d_dispatch_step before fn_phase_d_handler_execute is entered, so the handler is
    -- handed a value and never reaches for one. And it runs LAST: a key a real row can answer is
    -- answered by that row, and the fixture never shadows a fact.
    --
    -- fn_phase_d_fixture_input returns NO ROW unless fn_phase_d_fixture_context() verifies an hmac
    -- over the current txid keyed by a secret no role can read. In production there is no such
    -- context, so this block resolves nothing, the key stays unresolved, and its rule or gate
    -- refuses exactly as it did before this file existed.
    if v_val is null or v_val = 'null'::jsonb then
      select fi.value, fi.provenance || format(' [fixture %s v%s %s]', fi.fixture_id,
                                               fi.fixture_version, left(fi.checksum, 12))
        into v_fx_val, v_fx_src
        from public.fn_phase_d_fixture_input(p_step_run_id, 'CONTEXT_KEY', v_k) fi;
      if v_fx_val is not null then
        v_in := v_in || jsonb_build_object(v_k, v_fx_val);
        v_prov := v_prov || jsonb_build_object(v_k, v_fx_src);
        v_res := v_res || v_k;
        v_fx_val := null; v_fx_src := null;
        continue;
      end if;
    end if;
    if v_val is null or v_val = 'null'::jsonb then
      v_unres := v_unres || v_k;
    else
      v_in   := v_in   || jsonb_build_object(v_k, v_val);
      v_prov := v_prov || jsonb_build_object(v_k, v_src);
      v_res  := v_res  || v_k;
    end if;
  end loop;

  return jsonb_build_object(
    'step_run_id', p_step_run_id, 'step_id', sr.step_id, 'run_id', sr.run_id,
    'declared_keys', to_jsonb(v_keys),
    'inputs', v_in, 'provenance', v_prov,
    'resolved', to_jsonb(v_res), 'unresolved', to_jsonb(v_unres));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_phase_d_test_context_open(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_op    text := nullif(btrim(coalesce(p_input->>'operation_key','')),'');
  v_label text := nullif(btrim(coalesce(p_input->>'label','')),'');
  v_id    bigint;
  v_tok   text;
begin
  if v_op is null or v_label is null then
    raise exception 'fn_phase_d_test_context_open: operation_key and label are both required (pd_test_context_input_invalid)'
      using errcode = '22023';
  end if;

  -- The frontend and an ordinary signed-in user are refused before anything else is read. This is
  -- the same refusal fn_phase_d_fixture_scenario already made; it is repeated here because this
  -- routine is now the only door and a door must carry its own lock.
  if current_user in ('anon','authenticated') then
    raise exception 'fn_phase_d_test_context_open: % may not open a Phase D test context (pd_test_context_untrusted_caller)',
      current_user using errcode = '42501';
  end if;

  if not exists (select 1 from public.phase_d_test_operation o
                  where o.operation_key = v_op and o.enabled) then
    raise exception 'fn_phase_d_test_context_open: % is not an enabled approved Phase D test operation. A service-role caller with no approved audit context may not build fixtures. (pd_test_context_operation_unapproved)',
      v_op using errcode = '42501';
  end if;

  insert into public.phase_d_test_context_grant
    (operation_key, label, txid, backend_pid, granted_to, session_user_name)
  values (v_op, v_label, txid_current(), pg_backend_pid(), current_user, session_user)
  returning fixture_run_id into v_id;

  -- BOUND TO THE TRANSACTION. A token minted here does not verify in any other transaction, so it
  -- cannot be lifted out of a log, a query plan or an error message and replayed.
  select encode(extensions.hmac(convert_to(format('%s:%s:%s', txid_current(), v_op, v_id),'UTF8'), s.secret, 'sha256'), 'hex')
    into v_tok from public.phase_d_fixture_secret s where s.singleton;

  perform set_config('app.phase_d_fixture_context', format('%s.%s', v_id, v_tok), true);

  return jsonb_build_object(
    'ok', true, 'fixture_run_id', v_id, 'operation_key', v_op, 'label', v_label,
    'txid', txid_current(),
    'note', 'transaction-local; abort this transaction when finished. The token is bound to this '
         || 'txid and to nothing else.');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_pick_reviewer(p_dept_key text, p_author text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_head text; v_ok boolean; v_delegate text; v_basis text;
        v_head_tier text; v_head_score numeric; v_score numeric; v_up text;
begin
  -- THE AUTHOR ARRIVES UNDER WHATEVER NAME THE CALLER HAD (14 Aug 2026).
  -- Every comparison below is a raw string test - p_author = v_head, and three
  -- "a.agent_key is distinct from p_author" filters. All ten department heads carry aliases, so
  -- an author passed as 'finance_ai', 'marketplace_director' or 'CEO AI' was not equal to 'ceo',
  -- 'procurement' or 'ceo', the guard did not fire, and this function returned the author as its
  -- own reviewer. Measured on production before this line: 10 of 10 departments.
  -- Resolving once here fixes every comparison at the same time, because they all read p_author.
  p_author := coalesce(public.fn_org_agent_resolve(p_author), p_author);

  select lead_agent into v_head from org_departments where dept_key = p_dept_key;

  if v_head is null then
    return jsonb_build_object('reviewer', null, 'available', false,
      'basis', 'no lead_agent recorded for department ' || p_dept_key);
  end if;

  -- THE AUTHOR IS THE HEAD. Measured 14 Aug 2026: 285 of 1,882 review_chain rows had
  -- author_agent = reviewer_agent and 182 of those were approvals, because this function was only
  -- ever told the department and answered with its head. When the head wrote the work, review
  -- climbs: first to an independent reviewer inside the same department, then to the head's own
  -- manager. It never returns the author.
  if p_author is not null and p_author = v_head then
    select a.agent_key into v_delegate
      from org_agents a
      join org_role r on r.runtime_agent_key = a.agent_key and r.status = 'active'
     where a.department = p_dept_key and a.agent_key <> p_author
       and r.runtime_mode = 'independent_reviewer'
       and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
     order by a.agent_key limit 1;

    if v_delegate is not null then
      return jsonb_build_object('reviewer', v_delegate, 'available', true, 'delegated_from', v_head,
        'basis', 'the department head authored this work; review routed to the department''s '
                 || 'independent reviewer, which never approves its own output');
    end if;

    select m.agent_key into v_up
      from org_agents o join org_agents m on m.agent_key = o.manager_key and m.active
     where o.agent_key = v_head
       and m.available and (m.unavailable_until is null or m.unavailable_until < current_date);

    if v_up is not null and v_up <> p_author then
      return jsonb_build_object('reviewer', v_up, 'available', true, 'delegated_from', v_head,
        'basis', 'the department head authored this work and the department has no independent '
                 || 'reviewer available; review escalated one level up the reporting chain');
    end if;

    return jsonb_build_object('reviewer', null, 'available', false, 'delegated_from', v_head,
      'basis', 'the department head authored this work and no independent reviewer or manager is '
               || 'available - escalate rather than approve it');
  end if;

  select (a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date))
    into v_ok from org_agents a where a.agent_key = v_head;

  select p.tier, p.score into v_head_tier, v_head_score
    from agent_reputation p where p.agent_key = v_head;

  if coalesce(v_ok, false) then
    if coalesce(v_head_tier, '') = 'probation' then
      select a.agent_key, p.score into v_delegate, v_score
        from org_agents a
        join agent_reputation p on p.agent_key = a.agent_key
       where a.department = p_dept_key and a.agent_key <> v_head
         and a.agent_key is distinct from p_author
         and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
         and p.tier <> 'probation' and p.score > coalesce(v_head_score, 0)
       order by p.score desc, a.agent_key
       limit 1;

      if v_delegate is not null then
        return jsonb_build_object('reviewer', v_delegate, 'available', true, 'delegated_from', v_head,
          'basis', 'department head ' || v_head || ' is on the probation reputation tier ('
                   || coalesce(v_head_score::text, '?') || '); review routed to the highest-scoring '
                   || 'available employee in ' || p_dept_key || ' (' || coalesce(v_score::text, '?') || ')');
      end if;
    end if;

    return jsonb_build_object('reviewer', v_head, 'available', true, 'delegated_from', null,
      'basis', 'department head (reputation ' || coalesce(v_head_score::text, 'unscored')
               || ', tier ' || coalesce(v_head_tier, 'unscored') || ')');
  end if;

  select d.delegate_to, d.basis into v_delegate, v_basis
  from delegation_rule d
  join org_agents a on a.agent_key = d.delegate_to
  where d.active and d.dept_key = p_dept_key and d.when_agent = v_head
    and a.agent_key is distinct from p_author
    and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
  order by d.rank limit 1;

  if v_delegate is null then
    select a.agent_key,
           'highest-scoring available employee in ' || p_dept_key
             || ' (reputation ' || coalesce(p.score::text, 'unscored') || ')'
      into v_delegate, v_basis
    from org_agents a
    left join agent_reputation p on p.agent_key = a.agent_key
    where a.department = p_dept_key and a.agent_key <> v_head
      and a.agent_key is distinct from p_author
      and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
      and coalesce(p.tier, 'standard') <> 'probation'
    order by p.score desc nulls last, fn_seniority_rank(a.seniority), a.agent_key
    limit 1;
  end if;

  if v_delegate is null then
    return jsonb_build_object('reviewer', null, 'available', false, 'delegated_from', v_head,
      'basis', 'department head unavailable and no delegate available - escalate');
  end if;

  return jsonb_build_object('reviewer', v_delegate, 'available', true,
    'delegated_from', v_head, 'basis', coalesce(v_basis, 'delegation'));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_po_approve(p_po bigint, p_by text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare st text;
begin
  select status into st from public.po_orders where id=p_po;
  if st is null then raise exception 'PO % not found', p_po; end if;
  if st <> 'draft' then raise exception 'PO % is % (only draft can be approved)', p_po, st; end if;
  update public.po_orders set status='approved', approved_by=p_by, approved_at=now() where id=p_po;
  return p_po;
end $function$


CREATE OR REPLACE FUNCTION public.fn_po_orders_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if new.quote_id is not null and new.inquiry_id is null then
    select q.inquiry_id into new.inquiry_id from public.quotes q where q.id = new.quote_id;
  end if;
  if new.inquiry_id is not null and (new.customer_id is null or new.project_id is null) then
    select coalesce(new.customer_id, i.customer_id), coalesce(new.project_id, i.project_id)
      into new.customer_id, new.project_id
      from public.inquiries i where i.id = new.inquiry_id;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_price_confidence(p_category text, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s record; iqr numeric; z numeric; conf int; band text;
begin
  select * into s from category_price_stats where category = p_category;
  if s is null or s.n < 4 then
    return jsonb_build_object('confidence', null, 'band', 'insufficient_data', 'n', coalesce(s.n,0));
  end if;
  iqr := nullif(s.p75 - s.p25, 0);
  if iqr is null then iqr := nullif(s.sd, 0); end if;
  if iqr is null then
    return jsonb_build_object('confidence', null, 'band', 'insufficient_data', 'n', s.n);
  end if;
  z := abs(p_amount - s.median) / iqr;
  conf := greatest(5, least(99, round(100 * exp(-0.6 * z))::int));
  if    p_amount < s.p25 - 1.5*iqr then band := 'suspiciously_low';
  elsif p_amount > s.p75 + 1.5*iqr then band := 'suspiciously_high';
  elsif p_amount between s.p25 and s.p75 then band := 'fair';
  else band := 'within_range';
  end if;
  return jsonb_build_object('confidence', conf, 'band', band,
    'median', s.median, 'p25', s.p25, 'p75', s.p75, 'n', s.n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_priority_backlog_reorder()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_rank smallint; v_n int;
begin
  v_rank := case new.payload->>'max_severity' when 'high' then 2 when 'medium' then 1 else 0 end;
  if v_rank = 0 or new.correlation_id is null then return new; end if;
  update public.org_tasks t
     set priority = greatest(t.priority, v_rank), updated_at = now()
   where t.status not in ('done','closed','cancelled')
     and t.priority < v_rank
     and t.id in (select d.task_id from public.event_delivery d
                    join public.company_event e on e.id = d.event_id
                   where e.correlation_id = new.correlation_id and d.task_id is not null);
  get diagnostics v_n = row_count;
  if v_n > 0 then
    insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
    values ('priority_backlog_reorder', now(), now(), 'ok',
            jsonb_build_object('event_id', new.id, 'correlation_id', new.correlation_id, 'rank', v_rank, 'tasks_moved', v_n),
            'priority.updated (' || coalesce(new.payload->>'max_severity','?') || ') moved ' || v_n
            || ' open task(s) of the episode ahead of the created_at queue.');
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_procurement_analysis(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare minp numeric; maxp numeric; medp numeric; nq int;
        matrix jsonb := '[]'::jsonb; r record; rec jsonb := null; best numeric := -1;
        price_score numeric; qual numeric; rep numeric; warr_m int; warr_score numeric;
        lead_w int; lead_score numeric; comp numeric; value numeric; risks text[]; letter text; idx int := 0;
begin
  select count(*), min(quote_amount), max(quote_amount), percentile_cont(0.5) within group (order by quote_amount)
    into nq, minp, maxp, medp
  from public.quotes where inquiry_id=p_id and coalesce(quote_amount,0) > 0
    and coalesce(status,'') not in ('withdrawn','rejected','expired');
  if nq = 0 then return jsonb_build_object('ready',false,'quote_count',0,'note','No priced quotes yet.'); end if;

  for r in
    select q.*, l.company_name, l.rating,
           rp.reputation_index, rp.dispute_rate_pct
    from public.quotes q
    left join public.leads l on l.id=q.supplier_id
    left join public.supplier_reputation rp on rp.supplier_id=q.supplier_id
    where q.inquiry_id=p_id and coalesce(q.quote_amount,0) > 0
      and coalesce(q.status,'') not in ('withdrawn','rejected','expired')
    order by q.quote_amount asc
  loop
    idx := idx + 1; letter := chr(64+idx);  -- A, B, C...
    price_score := case when maxp=minp then 100 else round((maxp - r.quote_amount)/(maxp-minp)*100) end;
    qual := coalesce((r.quality->>'score')::numeric, 0);
    rep := coalesce(r.reputation_index, r.rating*20, 50);
    warr_m := coalesce((regexp_match(coalesce(r.warranty,''),'(\d+)'))[1]::int, 0);
    warr_score := case when r.warranty is null then 0 else least(100, warr_m::numeric/24*100) end;
    lead_w := coalesce((regexp_match(coalesce(r.lead_time,''),'(\d+)'))[1]::int, null);
    lead_score := case when lead_w is null then 50 else greatest(0, 100 - lead_w*8) end;
    comp := case when (r.quality->>'mandatory_total') is not null and (r.quality->>'mandatory_total')::numeric>0
                 then round((r.quality->>'mandatory_present')::numeric/(r.quality->>'mandatory_total')::numeric*100) else qual end;
    value := round(0.35*qual + 0.30*price_score + 0.15*rep + 0.10*warr_score + 0.10*lead_score);

    risks := '{}';
    if qual < 50 then risks := array_append(risks,'Quote incomplete — low quality score ('||qual||'/100)'); end if;
    if r.expires_at is not null and r.expires_at < now() then risks := array_append(risks,'Quote has expired'); end if;
    if medp>0 and r.quote_amount < 0.75*medp then risks := array_append(risks,'Price well below median — verify the scope is not under-quoted'); end if;
    if r.warranty is null then risks := array_append(risks,'No warranty stated'); end if;
    if coalesce(r.payment_terms,'')='' then risks := array_append(risks,'No payment terms stated'); end if;
    if coalesce(r.dispute_rate_pct,0) > 10 then risks := array_append(risks,'Supplier has a dispute history ('||round(r.dispute_rate_pct)||'%)'); end if;
    if array_length(risks,1) is null then risks := array_append(risks,'No major risks flagged'); end if;

    matrix := matrix || jsonb_build_object(
      'label','Supplier '||letter, 'quote_id',r.id, 'supplier_id',r.supplier_id, 'company_name',r.company_name,
      'price', r.quote_amount, 'price_vs_low_pct', case when minp>0 then round((r.quote_amount-minp)/minp*100,1) else 0 end,
      'lead_time', r.lead_time, 'warranty', r.warranty, 'payment_terms', r.payment_terms, 'validity', r.validity,
      'quality_score', qual, 'completeness_pct', comp, 'reputation', round(rep),
      'value_score', value, 'risks', to_jsonb(risks));

    if value > best then best := value;
      rec := jsonb_build_object('label','Supplier '||letter,'supplier_id',r.supplier_id,'company_name',r.company_name,
        'value_score',value,'price',r.quote_amount,
        'why','Best overall value: quality '||qual||'/100, price score '||price_score||'/100'
          ||case when qual>=70 then ', well-documented' else ', but confirm the missing quote details' end
          ||case when r.quote_amount=minp then ', and it is the lowest price' else '' end||'.');
    end if;
  end loop;

  return jsonb_build_object(
    'ready', nq>=2, 'quote_count', nq,
    'price_range', jsonb_build_object('low',minp,'median',medp,'high',maxp,'spread_pct',case when minp>0 then round((maxp-minp)/minp*100,1) else 0 end),
    'matrix', matrix,
    'recommendation', rec,
    'note', case when nq=1 then 'Only one quote so far — comparison needs at least two.' else null end
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_prompt_approve_draft(p_key text, p_version integer, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not exists(select 1 from prompt_versions where prompt_key=p_key and version=p_version and status='draft') then
    return jsonb_build_object('error','draft_not_found'); end if;
  update prompt_versions set status='deprecated' where prompt_key=p_key and status='active';
  update prompt_versions set status='active', rollout_pct=100, approved_by=p_by where prompt_key=p_key and version=p_version;
  update prompts set active_version=p_version, updated_at=now() where key=p_key;
  update agent_actions set status='approved', decided_at=now(), decided_by=p_by
    where kind='prompt_approval' and detail->>'key'=p_key and (detail->>'version')::int=p_version and status in ('pending','needs_review');
  return jsonb_build_object('ok',true,'active_version',p_version);
end $function$


CREATE OR REPLACE FUNCTION public.fn_prompt_draft(p_key text, p_content text, p_by text DEFAULT 'ai_trainer'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v int;
begin
  insert into public.prompts(key,owner) values(p_key,p_by) on conflict(key) do update set updated_at=now();
  select coalesce(max(version),0)+1 into v from prompt_versions where prompt_key=p_key;
  insert into prompt_versions(prompt_key,version,content,status,rollout_pct,approved_by)
    values(p_key,v,p_content,'draft',0,null);
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_prompt_get(p_key text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select content from prompt_versions pv join prompts p on p.key=pv.prompt_key
  where pv.prompt_key=p_key and pv.version=p.active_version limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_prompt_reject_draft(p_key text, p_version integer, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  update prompt_versions set status='discarded' where prompt_key=p_key and version=p_version and status='draft';
  update agent_actions set status='rejected', decided_at=now(), decided_by=p_by
    where kind='prompt_approval' and detail->>'key'=p_key and (detail->>'version')::int=p_version and status in ('pending','needs_review');
  return jsonb_build_object('ok',true);
end $function$


CREATE OR REPLACE FUNCTION public.fn_prompt_rollback(p_key text, p_to_version integer, p_by text DEFAULT 'agent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status text; v_approved text;
begin
  select status, approved_by into v_status, v_approved
    from prompt_versions where prompt_key = p_key and version = p_to_version;

  if v_status is null then
    return jsonb_build_object('error', 'version not found');
  end if;

  -- ROLLBACK RESTORES TRUST, IT DOES NOT CONFER IT.
  if v_approved is null or v_status not in ('deprecated', 'active') then
    return jsonb_build_object(
      'error', 'refused',
      'reason', format(
        'version %s of %s is %s and was approved by %s, so it has never been trusted in '
        || 'production. Rollback restores a version that was previously approved; it is not a '
        || 'route to activate one that was not. Use fn_prompt_approve_draft to approve it first.',
        p_to_version, p_key, v_status, coalesce(v_approved, 'nobody')),
      'status', v_status, 'approved_by', v_approved);
  end if;

  update prompt_versions set status = 'deprecated'
   where prompt_key = p_key and status = 'active';

  -- approved_by is NOT touched: it records who approved this version, not who restored it.
  -- rollout_pct is set, or a version cut off mid-rollout returns to serving that fraction.
  update prompt_versions set status = 'active', rollout_pct = 100
   where prompt_key = p_key and version = p_to_version;

  update prompts set active_version = p_to_version, updated_at = now() where key = p_key;

  return jsonb_build_object('ok', true, 'active_version', p_to_version,
    'approved_by', v_approved, 'rolled_back_by', p_by);
end $function$


CREATE OR REPLACE FUNCTION public.fn_protect_app_secret()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  protected text[] := array['inbound_secret','deploy_secret','stripe_secret_key','service_role_key','resend_api_key'];
  k text := coalesce(old.key, new.key);
begin
  if tg_op = 'DELETE' then
    if old.key = any(protected) then
      raise exception 'app_secrets.% is load-bearing for edge-function authentication and cannot be deleted; rotate the value instead', old.key
        using errcode = 'raise_exception';
    end if;
    return old;
  end if;
  if new.key = any(protected) then
    if new.value is null or length(btrim(new.value)) < 24 then
      raise exception 'app_secrets.% must stay a non-empty secret of at least 24 characters (got %); an empty value would make every __secret guard pass',
        new.key, coalesce(length(btrim(new.value)), 0)
        using errcode = 'raise_exception';
    end if;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_quality_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'rfqs_missing_fields_30d', (select count(*) from inquiries where created_at > now()-interval '30 days'
        and (category is null or coalesce(summary,'')='' or emirate is null)),
    'rfqs_few_suppliers_30d', (select count(*) from inquiries i where i.created_at > now()-interval '30 days'
        and (select count(*) from inquiry_matches m where m.inquiry_id=i.id) < 3),
    'avg_quote_completeness', (select round(avg((quality->>'score')::numeric),1) from quotes where quality is not null),
    'low_quality_quotes', (select count(*) from quotes where (quality->>'score')::numeric < 50),
    'rfqs_not_comparable', (select count(*) from (select inquiry_id from quotes group by inquiry_id having count(*)=1) z)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_quality_snapshot_resolve_agent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_key text;
begin
  if new.agent is null then return new; end if;
  if exists (select 1 from public.org_agents o where o.agent_key = new.agent and o.active) then
    return new;
  end if;
  v_key := public.fn_org_agent_resolve(new.agent);
  if v_key is not null then new.agent := v_key; end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_query_platform(p_topic text, p_args jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v jsonb;
begin
  case lower(coalesce(p_topic,''))
    when 'topics' then
      v := jsonb_build_object('topics', jsonb_build_array(
        'knowledge','agents','agent_ops','ai','analytics','company','customers','documents',
        'ea','exec','finance','fraud','governance','marketing','marketplace','operations',
        'refunds','reports','strategy','suppliers','supplier_360','customer_360','rfq_360','funnel'));
    when 'knowledge'   then v := to_jsonb(fn_ws_knowledge());
    when 'agents'      then v := to_jsonb(fn_ws_agents());
    when 'agent_ops'   then v := to_jsonb(fn_ws_agent_ops(coalesce(p_args->>'agent','')));
    when 'ai'          then v := to_jsonb(fn_ws_ai());
    when 'analytics'   then v := to_jsonb(fn_ws_analytics());
    when 'company'     then v := to_jsonb(fn_ws_company());
    when 'customers'   then v := to_jsonb(fn_ws_customers());
    when 'documents'   then v := to_jsonb(fn_ws_documents());
    when 'ea'          then v := to_jsonb(fn_ws_ea());
    when 'exec'        then v := to_jsonb(fn_ws_exec());
    when 'finance'     then v := to_jsonb(fn_ws_finance());
    when 'fraud'       then v := to_jsonb(fn_ws_fraud());
    when 'governance'  then v := to_jsonb(fn_ws_governance());
    when 'marketing'   then v := to_jsonb(fn_ws_marketing());
    when 'marketplace' then v := to_jsonb(fn_ws_marketplace());
    when 'operations'  then v := to_jsonb(fn_ws_operations());
    when 'refunds'     then v := to_jsonb(fn_ws_refunds());
    when 'reports'     then v := to_jsonb(fn_ws_reports());
    when 'strategy'    then v := to_jsonb(fn_ws_strategy());
    when 'suppliers'   then v := to_jsonb(fn_ws_suppliers(coalesce(p_args,'{}'::jsonb)));
    when 'supplier_360' then v := to_jsonb(fn_ws_supplier_360((p_args->>'id')::bigint));
    when 'customer_360' then v := to_jsonb(fn_ws_customer_360((p_args->>'id')::uuid));
    when 'rfq_360'      then v := to_jsonb(fn_ws_rfq_360((p_args->>'id')::uuid));
    when 'funnel'       then v := to_jsonb(funnel_metrics(coalesce((p_args->>'days')::int,30)));
    else v := jsonb_build_object('error','unknown_topic','hint','call with topic=topics to list valid topics');
  end case;
  return coalesce(v,'{}'::jsonb);
exception when others then
  return jsonb_build_object('error','query_failed','topic',p_topic,'detail',sqlerrm);
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_coach(p_quote uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare sc jsonb; lbls text[]; miss text; sup record; co text; subject text; msg text;
begin
  sc := public.fn_quote_structured_score(p_quote::text);
  if (sc->>'submittable')::boolean then return jsonb_build_object('ok',true,'submittable',true); end if;
  lbls := '{}';
  for miss in select jsonb_array_elements_text(sc->'missing') loop
    lbls := array_append(lbls, case miss
      when 'line_items' then 'an itemised breakdown — add each item as a line'
      when 'unit_prices_on_all_items' then 'a unit price on every line item'
      when 'brand_model_per_item' then 'the brand and model for each item'
      when 'specifications' then 'technical specifications for the items'
      when 'labour_or_installation' then 'labour / installation cost'
      when 'warranty' then 'the warranty offered'
      when 'lead_time' then 'the lead time / delivery timeline'
      when 'payment_terms' then 'your payment terms'
      when 'exclusions' then 'what is excluded from the quote'
      when 'validity' then 'how long the quote is valid'
      else miss end);
  end loop;
  select l.company_name, l.claimed_by, l.email into sup
    from public.quotes q join public.leads l on l.id=q.supplier_id where q.id=p_quote;
  co := coalesce(sup.company_name,'there');
  if not exists (select 1 from public.notifications n where n.type='quote_coaching'
                   and n.to_email=coalesce(sup.claimed_by,sup.email) and n.created_at > now()-interval '24 hours'
                   and n.body like '%'||p_quote::text||'%') then
    subject := 'Your quote needs a few more details before we can send it';
    msg := 'Hi '||co||','||E'\n\n'||'Thanks for your quote. To make it competitive and send it to the customer, please add the following in your supplier portal:'||E'\n\n'
      ||'• '||array_to_string(lbls, E'\n• ')||E'\n\n'
      ||'Detailed quotes (with brands, specifications and a clear itemised breakdown) win far more often. Open your portal, complete these, and we will send it to the customer right away.'||E'\n\n'||'(ref '||p_quote::text||')';
    insert into public.notifications(type,to_email,to_role,channel,subject,body,status)
      values('quote_coaching', coalesce(sup.claimed_by,sup.email), 'supplier','email',subject,msg,'queued');
  end if;
  return jsonb_build_object('ok',true,'submittable',false,'missing',lbls,'score',sc->>'score');
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_comparison_publication_stamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.publication_state = 'PUBLISHED' and NEW.published_at is null then
    NEW.published_at := now();
  end if;
  -- Leaving PUBLISHED does not erase when it was published; that is a fact about the past.
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_recompute_submittable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare qid uuid; sc jsonb; cat jsonb; ok boolean;
begin
  qid := coalesce(NEW.quote_id, OLD.quote_id);
  begin sc := public.fn_quote_structured_score(qid::text); exception when others then sc := null; end;
  begin cat := public.fn_quote_category_score(qid::text); exception when others then cat := null; end;
  if sc is not null then
    ok := (sc->>'submittable')::boolean
          and (cat is null or (cat->>'applicable')::boolean is not true or (cat->>'category_pass')::boolean);
    update public.quotes set submittable = ok
      where id = qid and submittable is distinct from ok;
  end if;
  return coalesce(NEW, OLD);
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_score_json(p_quote jsonb, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int; priced int; branded int; laboured int; spec_n int; pts int:=0; miss text[]:='{}'; it jsonb;
begin
  n:=0; priced:=0; branded:=0; laboured:=0; spec_n:=0;
  for it in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop
    n:=n+1;
    if coalesce((it->>'unit_price')::numeric,0) > 0 then priced:=priced+1; end if;
    if coalesce(it->>'brand','')<>'' and coalesce(it->>'model','')<>'' then branded:=branded+1; end if;
    if (it->>'labour') is not null or (it->>'install') is not null then laboured:=laboured+1; end if;
    if coalesce(it->>'specification','')<>'' then spec_n:=spec_n+1; end if;
  end loop;
  if n=0 then miss:=array_append(miss,'line_items');
  else pts:=pts+15; if priced=n then pts:=pts+20; else miss:=array_append(miss,'unit_prices_on_all_items'); end if; end if;
  if n>0 and branded=n then pts:=pts+15; else miss:=array_append(miss,'brand_model_per_item'); end if;
  if n>0 and spec_n>=greatest(1,n/2) then pts:=pts+10; else miss:=array_append(miss,'specifications'); end if;
  if laboured>0 then pts:=pts+10; else miss:=array_append(miss,'labour_or_installation'); end if;
  if coalesce(p_quote->>'warranty','')<>'' then pts:=pts+6; else miss:=array_append(miss,'warranty'); end if;
  if coalesce(p_quote->>'lead_time','')<>'' then pts:=pts+6; else miss:=array_append(miss,'lead_time'); end if;
  if coalesce(p_quote->>'payment_terms','')<>'' then pts:=pts+6; else miss:=array_append(miss,'payment_terms'); end if;
  if coalesce(p_quote->>'exclusions','')<>'' then pts:=pts+6; else miss:=array_append(miss,'exclusions'); end if;
  if coalesce(p_quote->>'validity','')<>'' then pts:=pts+6; else miss:=array_append(miss,'validity'); end if;
  return jsonb_build_object('score',pts,'submittable',pts>=70,'items',n,'missing',to_jsonb(miss));
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_spec_group(p_category text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_category ~* 'duct.?clean|ac.?duct' then 'acduct'
    when p_category ~* 'facade.?clean|facade cleaning' then 'facade'
    when p_category ~* 'water.?tank' then 'watertank'
    when p_category ~* 'cctv|surveillance|security|access.?control|intercom|alarm' then 'security'
    when p_category ~* 'fire|safety|sprinkler|extinguisher|civil.?defen' then 'fire'
    when p_category ~* 'scaffold' then 'scaffolding'
    when p_category ~* 'demolition|strip.?out' then 'demolition'
    when p_category ~* 'garage.?door|shutter|rolling' then 'shutters'
    when p_category ~* 'elevator|escalator|^lift|lifts' then 'elevators'
    when p_category ~* 'generator' then 'generators'
    when p_category ~* 'solar|photovolt|shams' then 'solar'
    when p_category ~* 'swimming|pool' then 'pools'
    when p_category ~* 'tent|shade|pergola|awning|gazebo' then 'shade'
    when p_category ~* 'landscap|garden|softscape|hardscape|irrigation' then 'landscaping'
    when p_category ~* 'pest' then 'pestcontrol'
    when p_category ~* 'mover|moving|relocation|packing' then 'movers'
    when p_category ~* 'upholstery|curtain|blind|sofa' then 'upholstery'
    when p_category ~* 'wallpaper|wall covering' then 'wallpaper'
    when p_category ~* 'carpet' then 'carpet'
    when p_category ~* 'tiling|tile|marble|granite' then 'tiling'
    when p_category ~* 'floor|spc|vinyl|lvt|epoxy.?floor|parquet|laminate' then 'flooring'
    when p_category ~* 'paint' then 'painting'
    when p_category ~* 'gypsum|false.?ceiling|ceiling|drywall|plasterboard|partition' then 'gypsum'
    when p_category ~* 'waterproof' then 'waterproofing'
    when p_category ~* 'insulation' then 'insulation'
    when p_category ~* 'roofing|^roof|roof ' then 'roofing'
    when p_category ~* 'steel|fabrication' then 'steel'
    when p_category ~* 'masonry|block|^plaster' then 'masonry'
    when p_category ~* 'smart.?home|home.?automation|automation|knx' then 'smarthome'
    when p_category ~* 'av.?system|audio.?visual|audio visual' then 'avsystems'
    when p_category ~* 'network|structured.?cabl' then 'networking'
    when p_category ~* 'signage|sign.?board|3d letter' then 'signage'
    when p_category ~* 'acrylic|perspex|plexiglass' then 'acrylic'
    when p_category ~* 'interior.?design' then 'interiordesign'
    when p_category ~* 'fit.?out' then 'fitout'
    when p_category ~* 'combined.?mep|^mep$|mep' then 'mep'
    when p_category ~* 'glass|glaz|alumin|curtain.?wall|shopfront|balustrad' then 'glazing'
    when p_category ~* 'joinery|kitchen|furniture|carpentr|cabinet|wardrobe|cupboard' then 'joinery'
    when p_category ~* 'hvac|^ac-|air.?con|duct|chiller|cooling|ac.?maintenance' then 'hvac'
    when p_category ~* 'electric|wiring|dewa' then 'electrical'
    when p_category ~* 'plumb|sanitary|drainage' then 'plumbing'
    when p_category ~* 'facade' then 'glazing'
    when p_category ~* 'clean|housekeep' then 'cleaning'
    when p_category ~* 'handyman' then 'handyman'
    when p_category ~* 'facilit|general.?service|miscellaneous|^other|^general' then 'general'
    else null end;
$function$


CREATE OR REPLACE FUNCTION public.fn_quote_structured_score(p_quote text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int; priced int; branded int; laboured int; spec_n int; q record; pts int:=0; miss text[]:='{}';
begin
  select count(*), count(*) filter (where unit_price is not null and unit_price>0),
         count(*) filter (where coalesce(brand,'')<>'' and coalesce(model,'')<>''),
         count(*) filter (where labour is not null or install is not null),
         count(*) filter (where coalesce(specification,'')<>'')
    into n, priced, branded, laboured, spec_n from quote_items where quote_id=p_quote;
  select * into q from quotes where id=p_quote::uuid;
  if n=0 then miss:=array_append(miss,'line_items');
  else pts:=pts+15; if priced=n then pts:=pts+20; else miss:=array_append(miss,'unit_prices_on_all_items'); end if; end if;
  if n>0 and branded=n then pts:=pts+15; else miss:=array_append(miss,'brand_model_per_item'); end if;
  if n>0 and spec_n>=greatest(1,n/2) then pts:=pts+10; else miss:=array_append(miss,'specifications'); end if;
  if laboured>0 then pts:=pts+10; else miss:=array_append(miss,'labour_or_installation'); end if;
  if coalesce(q.warranty,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'warranty'); end if;
  if coalesce(q.lead_time,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'lead_time'); end if;
  if coalesce(q.payment_terms,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'payment_terms'); end if;
  if coalesce(q.exclusions,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'exclusions'); end if;
  if coalesce(q.validity,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'validity'); end if;
  return jsonb_build_object('score',pts,'submittable',pts>=70,'items',n,'priced_items',priced,'missing',to_jsonb(miss),'scored_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_supplier_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.supplier_id is not distinct from OLD.supplier_id then return NEW; end if;
  raise exception 'quotes %: this quotation belongs to supplier % and the write names supplier %. A quotation does not change hands; a correction is a new revision by its own author. (pd_object_cross_owner_write)',
    OLD.id, OLD.supplier_id, coalesce(NEW.supplier_id::text,'(none)') using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_rate_limit(p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r ai_rate_limit%rowtype;
begin
  insert into ai_rate_limit (bucket, window_start, count) values (p_bucket, now(), 0)
    on conflict (bucket) do nothing;
  select * into r from ai_rate_limit where bucket = p_bucket for update;
  if r.window_start < now() - make_interval(secs => p_window_seconds) then
    update ai_rate_limit set window_start = now(), count = 1 where bucket = p_bucket;
    return jsonb_build_object('allowed', true, 'count', 1, 'limit', p_limit);
  end if;
  if r.count >= p_limit then
    return jsonb_build_object('allowed', false, 'count', r.count, 'limit', p_limit,
      'retry_after_seconds', greatest(1, p_window_seconds - extract(epoch from (now() - r.window_start))::int));
  end if;
  update ai_rate_limit set count = count + 1 where bucket = p_bucket;
  return jsonb_build_object('allowed', true, 'count', r.count + 1, 'limit', p_limit);
end $function$


CREATE OR REPLACE FUNCTION public.fn_receipt_hand_to_bookkeeper(p_inbound_id bigint, p_review_ids bigint[], p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m record; v_owner text := 'bookkeeper'; v_task bigint;
begin
  select * into m from public.inbound_messages where id = p_inbound_id;
  if not found then return null; end if;

  -- one task per inbound email, however many times the email is redelivered
  select t.id into v_task from public.org_tasks t
   where t.detail like '[inbound_message:' || p_inbound_id || ']%'
     and t.status not in ('done', 'cancelled')
   order by t.id limit 1;

  if v_task is null then
    if not exists (select 1 from public.org_agents o where o.agent_key = v_owner and o.active and coalesce(o.available, true)) then
      v_owner := null;   -- a05_org_task_fill_ownership picks the least-loaded finance colleague
    end if;
    insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, decided_by,
                                  action_class, assigned_agent, priority, result)
    values ('finance',
            left('Book a forwarded receipt the parser could not read: ' || coalesce(m.subject, '(no subject)'), 200),
            '[inbound_message:' || p_inbound_id || '] ' || coalesce(p_reason, 'no amount could be read from the text')
              || E'\n\nFrom ' || coalesce(m.from_email, '?') || ' to ' || coalesce(m.to_email, '?') || ' at ' || m.created_at
              || '. Stored documents: doc_reviews ' || coalesce(array_to_string(p_review_ids, ', '), '(none)')
              || '. Read the document, book the expense in expense_entries (source ''receipt''), close the doc_reviews rows '
              || 'as auto_applied and the inbound row as replied. Only a Stripe refund reaches the founder.',
            'assigned', 'advisory', false, 'fn_receipt_hand_to_bookkeeper',
            'analysis', v_owner, 1,
            jsonb_build_object('source', jsonb_build_object('inbound_message_id', p_inbound_id,
                               'doc_review_ids', to_jsonb(coalesce(p_review_ids, '{}'::bigint[])),
                               'reason', p_reason, 'handed_at', now())))
    returning id into v_task;
  end if;

  update public.inbound_messages set owner_role = 'bookkeeper' where id = p_inbound_id and owner_role is null;
  update public.doc_reviews set owner_role = 'bookkeeper'
   where id = any(coalesce(p_review_ids, '{}'::bigint[])) and owner_role is null;
  return v_task;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_recommend_deterministic(p_step_run_id bigint DEFAULT NULL::bigint, p_record boolean DEFAULT true)
 RETURNS TABLE(determination text, employee text, department text, workflow_key text, step_no integer, step text, outcome text, deliverable text, inputs jsonb, recommendations jsonb, used_llm boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sid bigint := p_step_run_id;
  v_actor text; v_employee text; v_dept text; v_wf text; v_wfname text; v_step_no int; v_step text;
  v_run uuid; v_ctx jsonb := '{}'::jsonb; v_located text := 'p_step_run_id';
  v_framing text;
  v_kpis jsonb; v_kpi_rows int := 0; v_kpi_measured int := 0; v_kpi_missed int := 0; v_kpi_met int := 0;
  v_sc jsonb; v_sc_rows int := 0; v_sc_off int := 0;
  v_meta jsonb; v_meta_rows int := 0;
  v_recs jsonb; v_n int := 0;
  v_text text; v_one text; rec record;
  v_old_depts text[];
begin
  used_llm := false;
  -- 1. WHO IS ASKING. The step, or the queued action_execution row this invocation is running.
  if v_sid is null then
    select x.workflow_step_run_id, x.request->>'actor'
      into v_sid, v_actor
      from public.action_execution x
      join public.org_action_executor e on e.action_class = x.action_class and e.kind = 'rpc'
     where x.action_class = 'recommend' and x.status = 'queued'
     order by x.created_at limit 1;
    v_located := case when v_sid is not null then 'action_execution.workflow_step_run_id'
                      when v_actor is not null then 'action_execution.request.actor' else 'nothing queued' end;
  end if;
  if v_sid is not null then
    select s.actor, s.step_no, s.input->>'step', s.workflow_run_id, r.workflow_key, coalesce(r.context,'{}'::jsonb), w.name
      into v_actor, v_step_no, v_step, v_run, v_wf, v_ctx, v_wfname
      from public.workflow_step_run s
      join public.workflow_run r on r.id = s.workflow_run_id
      left join public.workflow w on w.workflow_key = r.workflow_key
     where s.id = v_sid;
    v_employee := public.fn_workflow_actor_resolve(v_run, v_actor);
  elsif v_actor is not null then
    v_employee := public.fn_org_agent_resolve(v_actor);
  end if;
  select o.department into v_dept from public.org_agents o where o.agent_key = v_employee and o.active;
  if v_dept is null then
    determination := 'no_scope'; employee := v_employee; department := null; workflow_key := v_wf; step_no := v_step_no; step := v_step;
    outcome := 'no determination: the caller resolves to no active employee, so there is no department whose numbers to read';
    deliverable := outcome;
    inputs := jsonb_build_object('located_by', v_located, 'step_run_id', v_sid, 'actor', v_actor, 'employee', v_employee);
    recommendations := null;
    return next; return;
  end if;
  -- metric_definition.owner_dept still speaks the pre-merge vocabulary (marketing, it, knowledge ...);
  -- org_departments.merged_into is the crosswalk, so a growth step also reads 'marketing' metrics.
  select coalesce(array_agg(d.dept_key), '{}') into v_old_depts
    from public.org_departments d where d.merged_into = v_dept or d.dept_key = v_dept;

  -- 2. THE STEP'S OWN WORDS choose the framing; the numbers are the same engine.
  v_framing := case
    when v_step ilike '%variance%' then 'variance'
    when v_step ilike '%root cause%' then 'root_cause'
    when v_step ilike '%revise%' or v_step ilike '%retire%' then 'revise_or_retire'
    when v_step ilike '%option%' then 'options'
    when v_step ilike '%grade%' or v_step ilike '%monitor%' then 'grade'
    when v_step ilike '%baseline%' then 'baseline'
    when v_step ilike '%define the metric%' then 'define'
    else 'recommend' end;

  -- 3. THE DEPARTMENT'S KPIs, with yesterday's (or the last recorded) value beside today's.
  with k as (
    select k.id, k.agent_key, k.metric, k.kpi, k.unit, k.cadence, k.target_value t, k.actual_value v,
           k.measured_at, k.no_measure_reason, k.serves_goal,
           (select h.actual_value from public.employee_kpi_history h
             where h.kpi_id = k.id and (k.measured_at is null or h.measured_at < k.measured_at - interval '1 hour')
             order by h.measured_at desc limit 1) prev,
           (select h.measured_on from public.employee_kpi_history h
             where h.kpi_id = k.id and (k.measured_at is null or h.measured_at < k.measured_at - interval '1 hour')
             order by h.measured_at desc limit 1) prev_on,
           (select count(*) from public.employee_kpi_history h
             where h.kpi_id = k.id and h.verdict = 'MISSED' and h.measured_on >= current_date - 14) missed_14d
      from public.employee_kpi k join public.org_agents a on a.agent_key = k.agent_key
     where k.active and a.department = v_dept
  ), s as (
    select k.*,
      case when v is null or t is null then null
           when t = 0 then case when v <= 0 then 100.0 else 0.0 end
           when unit = 'percent_max' then round(least(100.0, 100.0 * t / nullif(v,0)), 1)
           else round(100.0 * v / t, 1) end attainment
      from k
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'kpi_id', id, 'agent', agent_key, 'metric', metric, 'unit', unit, 'cadence', cadence,
           'target', t, 'actual', v, 'attainment', attainment,
           'verdict', case when v is null then 'NO DATA' when attainment is null then 'NO TARGET'
                           when attainment >= 100 then 'MET' when attainment >= 90 then 'NEAR' else 'MISSED' end,
           'measured_at', measured_at, 'previous', prev, 'previous_on', prev_on,
           'delta', case when v is not null and prev is not null then round(v - prev, 2) end,
           'missed_days_14d', missed_14d, 'no_measure_reason', no_measure_reason, 'serves_goal', serves_goal)
           order by (v is null), attainment nulls last, id), '[]'::jsonb),
         count(*), count(*) filter (where v is not null),
         count(*) filter (where v is not null and attainment is not null and attainment < 90),
         count(*) filter (where attainment >= 100)
    into v_kpis, v_kpi_rows, v_kpi_measured, v_kpi_missed, v_kpi_met
    from s;

  -- 4. THE COMPANY SCORECARD rows this department owns, with the prior snapshot beside the latest.
  select coalesce(jsonb_agg(jsonb_build_object(
           'metric_key', b.metric_key, 'label', b.label, 'owner_dept', b.owner_dept, 'value', b.value,
           'target', b.target, 'direction', b.direction, 'state', b.state, 'taken_at', b.taken_at,
           'previous', (select m.value from public.metric_snapshot m where m.metric_key = b.metric_key
                          and m.taken_at < b.taken_at - interval '20 hours' and m.error is null
                          order by m.taken_at desc limit 1),
           'delta', case when b.value is not null then round(b.value - (select m.value from public.metric_snapshot m
                          where m.metric_key = b.metric_key and m.taken_at < b.taken_at - interval '20 hours' and m.error is null
                          order by m.taken_at desc limit 1), 2) end)
           order by case b.state when 'OFF_TARGET' then 0 when 'BEHIND' then 1 when 'ERROR' then 2 when 'UNMEASURED' then 3 else 4 end, b.metric_key), '[]'::jsonb),
         count(*), count(*) filter (where b.state in ('OFF_TARGET','BEHIND'))
    into v_sc, v_sc_rows, v_sc_off
    from public.v_bi_scorecard b
   where b.owner_dept = any (v_old_depts);

  -- 5. AD DATA, when the sync has written any. Only the growth scope reads it; it is that department's.
  if v_dept = 'growth' then
    select coalesce(jsonb_agg(jsonb_build_object('campaign', m.campaign_name, 'status', m.effective_status,
             'window', m.time_window, 'spend', m.spend, 'currency', m.currency, 'impressions', m.impressions,
             'clicks', m.clicks, 'ctr', m.ctr, 'cpc', m.cpc, 'results', m.results, 'synced_at', m.synced_at,
             'synced_via', m.synced_via) order by m.synced_at desc), '[]'::jsonb), count(*)
      into v_meta, v_meta_rows
      from (select distinct on (campaign_id, time_window) * from public.meta_insights order by campaign_id, time_window, synced_at desc) m;
  end if;

  inputs := jsonb_build_object(
    'located_by', v_located, 'step_run_id', v_sid, 'actor', v_actor, 'employee', v_employee, 'department', v_dept,
    'scorecard_owner_depts', to_jsonb(v_old_depts), 'framing', v_framing,
    'kpi_rows', v_kpi_rows, 'kpi_measured', v_kpi_measured, 'kpi_missed', v_kpi_missed, 'kpi_met', v_kpi_met,
    'scorecard_rows', v_sc_rows, 'scorecard_off_target', v_sc_off, 'meta_rows', v_meta_rows,
    'kpis', v_kpis, 'scorecard', v_sc, 'meta', coalesce(v_meta, '[]'::jsonb),
    'run_context', case when v_ctx ? 'failing_metrics' or v_ctx ? 'goals_at_risk' or v_ctx ? 'title'
                        then v_ctx - 'at' - 'ref' - 'functions' else null end,
    'measured_at', now());

  employee := v_employee; department := v_dept; workflow_key := v_wf; step_no := v_step_no; step := v_step;

  -- 6. NO DATA is its own answer, in its own shape.
  if v_kpi_measured = 0 and v_sc_rows = 0 and v_meta_rows = 0 then
    determination := 'no_data';
    outcome := format('no determination for %s: %s KPI row(s) in scope and %s of them measured, %s scorecard metric(s) owned, %s ad-insight row(s)',
                      v_dept, v_kpi_rows, v_kpi_measured, v_sc_rows, v_meta_rows);
    deliverable := outcome || case when v_kpi_rows > 0 then '. The KPIs exist but carry no measurement: '
        || (select string_agg(x->>'metric' || coalesce(' (' || (x->>'no_measure_reason') || ')', ''), '; ') from jsonb_array_elements(v_kpis) x)
        || '. Instrument the measure before asking for a recommendation.' else '.' end;
    recommendations := null;
    return next; return;
  end if;

  -- 7. THE RANKED MOVERS. Missed KPIs by attainment, off-target company metrics, then anything worsening.
  with cand as (
    select 'kpi' src, x->>'metric' metric, x->>'agent' owner, (x->>'actual')::numeric actual, (x->>'target')::numeric target,
           x->>'unit' unit, (x->>'attainment')::numeric attainment, x->>'verdict' verdict,
           (x->>'previous')::numeric previous, (x->>'delta')::numeric delta, x->>'measured_at' measured_at,
           (x->>'missed_days_14d')::int missed_14d, x->>'serves_goal' goal,
           case x->>'verdict' when 'MISSED' then 0 when 'NEAR' then 1 when 'NO TARGET' then 3 else 4 end sev
      from jsonb_array_elements(v_kpis) x where x->>'verdict' <> 'NO DATA'
    union all
    select 'scorecard', x->>'label', x->>'owner_dept', (x->>'value')::numeric, (x->>'target')::numeric, x->>'direction',
           case when (x->>'target')::numeric is null or (x->>'value')::numeric is null then null
                when (x->>'direction') = 'down' then round(least(100.0, 100.0 * (x->>'target')::numeric / nullif((x->>'value')::numeric,0)), 1)
                else round(100.0 * (x->>'value')::numeric / nullif((x->>'target')::numeric,0), 1) end,
           x->>'state', (x->>'previous')::numeric, (x->>'delta')::numeric, x->>'taken_at', null, null,
           case x->>'state' when 'OFF_TARGET' then 0 when 'BEHIND' then 1 when 'ERROR' then 2 else 4 end
      from jsonb_array_elements(v_sc) x where x->>'state' not in ('UNMEASURED')
  ), ranked as (
    select c.*, row_number() over (order by sev, attainment nulls last, delta nulls last, metric) rk from cand c
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'rank', rk, 'source', src, 'metric', metric, 'owner', owner, 'actual', actual, 'target', target, 'unit', unit,
           'attainment_pct', attainment, 'verdict', verdict, 'previous', previous, 'delta', delta, 'measured_at', measured_at,
           'missed_days_14d', missed_14d, 'serves_goal', goal,
           'trend', case when delta is null then 'no prior measurement' when delta > 0 then 'up ' || delta when delta < 0 then 'down ' || abs(delta) else 'flat' end,
           'determination', case v_framing
             when 'variance' then case when verdict in ('MISSED','OFF_TARGET','BEHIND')
                 then format('variance: %s at %s against target %s (%s%% attainment); %s',
                             metric, actual, target, attainment, case when delta is null then 'no prior point to trend' when delta < 0 then 'worsened by ' || abs(delta) || ' since the previous measurement' when delta > 0 then 'improved by ' || delta || ' but still short' else 'unchanged' end)
                 else format('within tolerance: %s at %s against target %s (%s%%)', metric, actual, target, attainment) end
             when 'root_cause' then case
                 when verdict in ('MET','ON_TARGET','NEAR') then format('%s is at %s%% of target: no gap to explain', metric, attainment)
                 when coalesce(missed_14d, 0) >= 10 and coalesce(delta, 0) <= 0 then format('the TARGET: %s missed on %s of the last 14 measured days with no improving trend (actual %s vs target %s); propose a revised target with the run of actuals as evidence', metric, missed_14d, actual, target)
                 when delta is not null and delta > 0 then format('the WORK: %s is moving toward target (%s -> %s, target %s); keep the current plan and re-measure on cadence', metric, previous, actual, target)
                 else format('the WORK: %s at %s vs target %s (%s%%) with %s missed day(s) in 14; the gap is recent enough to be closed by the owner %s', metric, actual, target, attainment, coalesce(missed_14d,0), owner) end
             when 'revise_or_retire' then case
                 when coalesce(missed_14d, 0) >= 14 then format('REVISE: %s missed every one of the last 14 measured days (actual %s vs target %s); the target does not describe this business yet', metric, actual, target)
                 when verdict in ('MET','ON_TARGET') and coalesce(missed_14d, 0) = 0 then format('KEEP: %s met at %s against %s and never missed in 14 days', metric, actual, target)
                 else format('KEEP and watch: %s at %s%% attainment, %s missed day(s) in 14', metric, attainment, coalesce(missed_14d,0)) end
             when 'options' then format('option: close the gap on %s (actual %s, target %s, gap %s %s); cost proxy = gap size, risk = %s', metric, actual, target, round(abs(coalesce(target,0) - coalesce(actual,0)), 2), coalesce(unit,''), case when attainment is null then 'unknown' when attainment < 50 then 'high (below half of target)' when attainment < 90 then 'medium' else 'low' end)
             when 'grade' then format('grade: %s %s (%s -> %s against target %s)', metric, case when delta is null then 'UNGRADED, no prior measurement' when (unit = 'percent_max' or unit = 'down') and delta < 0 then 'BETTER' when (unit = 'percent_max' or unit = 'down') and delta > 0 then 'WORSE' when delta > 0 then 'BETTER' when delta < 0 then 'WORSE' else 'FLAT' end, previous, actual, target)
             when 'baseline' then format('baseline captured: %s = %s (%s) measured %s, target %s', metric, actual, coalesce(unit,''), measured_at, target)
             else format('%s: %s at %s against target %s (%s%%), owner %s', verdict, metric, actual, target, attainment, owner) end)
           order by rk), '[]'::jsonb), count(*)
    into v_recs, v_n
    from ranked where rk <= 5;

  determination := 'recommendation';
  recommendations := v_recs;
  v_one := coalesce((select x->>'determination' from jsonb_array_elements(v_recs) x order by (x->>'rank')::int limit 1), 'nothing in scope moved');
  outcome := left(format('%s: %s of %s KPIs measured, %s missed, %s met; %s of %s owned scorecard metrics off target%s. Top mover: %s',
                    v_dept, v_kpi_measured, v_kpi_rows, v_kpi_missed, v_kpi_met, v_sc_off, v_sc_rows,
                    case when v_meta_rows > 0 then format('; %s ad-insight row(s) read', v_meta_rows) else '' end, v_one), 600);
  v_text := format(E'%s\nWorkflow %s step %s (%s), worked by %s for %s on %s.\nInputs: %s KPI rows (%s measured, %s missed, %s met), %s scorecard metrics (%s off target), %s ad-insight rows.\n',
                   case v_framing when 'variance' then 'VARIANCE AGAINST TARGET' when 'root_cause' then 'ROOT CAUSE: THE WORK OR THE TARGET' when 'revise_or_retire' then 'REVISE OR RETIRE' when 'options' then 'OPTIONS WITH COST AND RISK' when 'grade' then 'GRADE AGAINST BASELINE' when 'baseline' then 'BASELINE' when 'define' then 'METRIC DEFINITION REVIEW' else 'RECOMMENDATION' end,
                   coalesce(v_wfname, v_wf, '(no workflow)'), coalesce(v_step_no::text, '-'), coalesce(v_step, 'direct call'), v_employee, v_dept, to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI') || ' UTC',
                   v_kpi_rows, v_kpi_measured, v_kpi_missed, v_kpi_met, v_sc_rows, v_sc_off, v_meta_rows);
  for rec in select x from jsonb_array_elements(v_recs) x order by (x->>'rank')::int loop
    v_text := v_text || format(E'%s. %s [%s; trend %s; measured %s]\n', rec.x->>'rank', rec.x->>'determination', rec.x->>'source', rec.x->>'trend', coalesce(left(rec.x->>'measured_at', 16), '?'));
  end loop;
  if v_meta_rows > 0 then
    v_text := v_text || 'Ad data: ' || (select string_agg(format('%s [%s] %s: spend %s %s, %s impressions, %s clicks, ctr %s, cpc %s (synced %s via %s)',
        m->>'campaign', m->>'status', m->>'window', m->>'spend', m->>'currency', m->>'impressions', m->>'clicks', coalesce(m->>'ctr','-'), coalesce(m->>'cpc','-'), left(m->>'synced_at',10), m->>'synced_via'), '; ')
        from jsonb_array_elements(v_meta) m) || E'\n';
  end if;
  if v_ctx ? 'failing_metrics' then
    v_text := v_text || 'Trigger context named failing metrics ' || (v_ctx->'failing_metrics')::text || coalesce(' and goals at risk ' || (v_ctx->'goals_at_risk')::text, '') || E'.\n';
  end if;
  v_text := v_text || 'Basis: employee_kpi actual/target as measured, employee_kpi_history for the previous point and the 14-day miss count, v_bi_scorecard + metric_snapshot for company metrics' || case when v_dept = 'growth' then ', meta_insights for ad data' else '' end || '. No model call.';
  deliverable := v_text;

  if p_record then
    insert into public.org_memory(scope, kind, content, source)
    values ('analytics', 'insight', left(coalesce(v_wf,'direct') || ' step ' || coalesce(v_step_no::text,'-') || ' — ' || outcome, 500) || E'\n\n' || left(v_text, 3000), 'fn_recommend_deterministic');
  end if;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_reconcile_doc_blocks(p_grace_days integer DEFAULT 0)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lic_susp int := 0; v_ins_susp int := 0; v_restored int := 0;
  v_cut date := current_date - make_interval(days => p_grace_days);
  rec record;
begin
  -- ---- SUSPEND: trade licence expired -------------------------------------------------
  -- Only touches rows that are unblocked or already blocked for a document reason, so a
  -- manual block set by the team is never overwritten or silently cleared.
  for rec in
    select id, company_name, claimed_by, email, phone, whatsapp, license_expiry
      from leads
     where approval_status = 'approved' and coalesce(banned,false) = false
       and license_expiry is not null and license_expiry < v_cut
       and (coalesce(matching_blocked,false) = false
            or matching_block_reason in ('licence_expired','insurance_expired'))
       and coalesce(matching_block_reason,'') is distinct from 'licence_expired'
  loop
    update leads set matching_blocked = true, matching_block_reason = 'licence_expired'
     where id = rec.id;
    v_lic_susp := v_lic_susp + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_suspended', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is paused - trade licence expired',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your trade licence expired on ' || rec.license_expiry || ', so your account has been temporarily paused and you will not receive new customer requests until it is renewed.' || chr(10) || chr(10) ||
      'To restore your account: reply to this email with the renewed licence attached, or upload it in the Documents tab of your supplier portal. Your account is restored automatically as soon as we have a valid copy - nothing else is needed and no fee applies.',
      'queued');
  end loop;

  -- ---- SUSPEND: insurance expired -----------------------------------------------------
  for rec in
    select id, company_name, claimed_by, email, insurance_expiry
      from leads
     where approval_status = 'approved' and coalesce(banned,false) = false
       and insurance_expiry is not null and insurance_expiry < v_cut
       and (coalesce(matching_blocked,false) = false
            or matching_block_reason in ('licence_expired','insurance_expired'))
       and coalesce(matching_block_reason,'') is distinct from 'insurance_expired'
       -- a licence block is the more serious of the two, so do not downgrade its reason
       and coalesce(matching_block_reason,'') is distinct from 'licence_expired'
  loop
    update leads set matching_blocked = true, matching_block_reason = 'insurance_expired'
     where id = rec.id;
    v_ins_susp := v_ins_susp + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_suspended', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is paused - insurance expired',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your insurance certificate expired on ' || rec.insurance_expiry || ', so your account has been temporarily paused and you will not receive new customer requests until it is renewed.' || chr(10) || chr(10) ||
      'To restore your account: reply to this email with the renewed certificate attached, or upload it in the Documents tab of your supplier portal. Your account is restored automatically as soon as we have a valid copy.',
      'queued');
  end loop;

  -- ---- RESTORE: the blocking document is valid again -----------------------------------
  -- Only clears blocks this job set. A manual block stays put.
  for rec in
    select id, company_name, claimed_by, email, matching_block_reason
      from leads
     where matching_block_reason in ('licence_expired','insurance_expired')
       and ((matching_block_reason = 'licence_expired'
             and (license_expiry is null or license_expiry >= v_cut))
         or (matching_block_reason = 'insurance_expired'
             and (insurance_expiry is null or insurance_expiry >= v_cut)))
  loop
    update leads set matching_blocked = false, matching_block_reason = null where id = rec.id;
    v_restored := v_restored + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_restored', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is active again',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Thank you - your documents are up to date and your account is active again. You will start receiving matching customer requests immediately.',
      'queued');
  end loop;

  return json_build_object('licence_suspended', v_lic_susp, 'insurance_suspended', v_ins_susp,
                           'restored', v_restored, 'grace_days', p_grace_days, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_context_retrieval(p_agent_key text, p_task_class text, p_category text, p_ids text[], p_budget integer, p_chars integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  insert into agent_context_retrieval
    (agent_key, task_class, category_key, knowledge_ids, knowledge_count, budget_chars, chars_returned)
  values (p_agent_key, p_task_class, p_category, coalesce(p_ids,'{}'),
          coalesce(array_length(p_ids,1),0), p_budget, p_chars)
  returning id into v_id;

  if coalesce(array_length(p_ids, 1), 0) > 0 then
    insert into kb_usage_log (agent, query, category)
    values (p_agent_key,
            'context assembly: ' || coalesce(array_length(p_ids,1), 0) || ' knowledge record(s) — '
              || left(array_to_string(p_ids[1:5], ', '), 400),
            coalesce(p_category, p_task_class, 'context_assembly'));
  end if;

  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_llm_attempt(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req      uuid    := coalesce(nullif(p->>'request_id','')::uuid, gen_random_uuid());
  v_model    text    := nullif(p->>'model_route','');
  v_ok       boolean := coalesce((p->>'ok')::boolean, false);
  v_no       integer;
  v_cls      jsonb;
  v_key      text;
  v_trips    boolean;
  v_first    boolean;
  v_thresh   integer;
  v_cool     integer;
  v_conseq   integer;
  v_state    text := 'closed';
  v_id       uuid;
  v_in       integer := nullif(p->>'prompt_tokens','')::integer;
  v_out      integer := nullif(p->>'output_tokens','')::integer;
  v_cached   integer := coalesce(nullif(p->>'cached_in_tokens','')::integer, 0);
  v_cost     numeric := nullif(p->>'cost_aed','')::numeric;
begin
  if v_model is null then
    raise exception 'fn_record_llm_attempt requires model_route: the route is what the breaker keys on';
  end if;

  if not v_ok then
    v_cls := fn_classify_llm_failure(p->>'err_excerpt',
                                     nullif(p->>'http_status','')::integer,
                                     p->>'finish_reason', v_model,
                                     nullif(p->>'latency_ms','')::integer);
    v_key := v_cls->>'class_key';
  end if;

  -- attempt_no is assigned HERE, never accepted from the caller. A caller cannot claim to be
  -- attempt 1 twice, and cannot renumber an earlier attempt out of the way.
  select coalesce(max(attempt_no), 0) + 1 into v_no from llm_attempt where request_id = v_req;

  insert into llm_route_health (model_id) values (v_model) on conflict (model_id) do nothing;
  select failure_threshold, cooldown_seconds into v_thresh, v_cool
    from llm_route_health where model_id = v_model;

  if v_ok then
    update llm_route_health
       set consecutive_failures = 0, open_until = null, opened_reason = null, opened_class = null,
           last_ok_at = now(), total_attempts = total_attempts + 1, total_ok = total_ok + 1,
           updated_at = now()
     where model_id = v_model;
  else
    select trips_breaker, opens_on_first into v_trips, v_first
      from llm_failure_class where class_key = v_key;
    update llm_route_health
       set consecutive_failures = case when coalesce(v_trips,false)
                                       then consecutive_failures + 1 else consecutive_failures end,
           last_failure_at = now(), total_attempts = total_attempts + 1, updated_at = now()
     where model_id = v_model
     returning consecutive_failures into v_conseq;

    if coalesce(v_trips,false) and (coalesce(v_first,false) or v_conseq >= v_thresh) then
      update llm_route_health
         set open_until = now() + make_interval(secs => v_cool),
             opened_reason = case when coalesce(v_first,false)
                             then 'opened on first occurrence of ' || v_key
                             else v_conseq || ' consecutive failures, threshold ' || v_thresh end,
             opened_class = v_key
       where model_id = v_model;
      v_state := 'opened_by_this';
    end if;
  end if;

  -- DERIVE THE MONEY HERE, from the same pricing source ai_cost_log uses, rather than trusting a
  -- caller to convert. A caller that computes its own AED is a second pricing implementation, and
  -- two of those drift. An explicit cost_aed in the payload still wins, so a provider that reports
  -- its own charge can be recorded verbatim.
  --
  -- Deliberately only when tokens are present: a failed attempt that produced no usage block has
  -- no measurable cost, and inventing 0 there would make "this retry was free" indistinguishable
  -- from "nobody recorded what this retry cost".
  if v_cost is null and (v_in is not null or v_out is not null) then
    begin
      v_cost := public.fn_model_cost_usd(v_model, coalesce(v_in,0), coalesce(v_out,0), v_cached)
                * public.fn_usd_to_aed();
    exception when others then v_cost := null;   -- pricing is reporting, never a gate
    end;
  end if;

  insert into llm_attempt (request_id, attempt_no, fn, agent_key, task_class, model_route, tier,
                           ok, class_key, http_status, finish_reason, err_excerpt,
                           evidence_truncated, latency_ms, prompt_tokens, output_tokens, cost_aed,
                           breaker_state)
  values (v_req, v_no, p->>'fn', p->>'agent_key', p->>'task_class', v_model, p->>'tier',
          v_ok, v_key, nullif(p->>'http_status','')::integer, p->>'finish_reason',
          left(coalesce(p->>'err_excerpt',''), 4000),
          coalesce((v_cls->>'evidence_truncated')::boolean, false),
          nullif(p->>'latency_ms','')::integer, v_in, v_out, v_cost,
          v_state)
  returning attempt_id into v_id;

  return jsonb_build_object(
    'attempt_id', v_id, 'request_id', v_req, 'attempt_no', v_no,
    'class_key', v_key, 'breaker', v_state,
    'cost_aed', v_cost,
    'retry_allowed', case when v_ok then false
                          when v_state = 'opened_by_this' then false   -- fail closed, do not retry into a wall
                          else fn_llm_retry_allowed(v_key, v_no) end,
    'retry_backoff_ms', coalesce((v_cls->>'retry_backoff_ms')::integer, 0),
    'evidence_truncated', coalesce((v_cls->>'evidence_truncated')::boolean, false));
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_tool_call(p_correlation uuid, p_agent_key text, p_role_id text, p_tool_id text, p_args jsonb, p_status text, p_result_hash text, p_result_rows integer, p_result_bytes integer, p_error text, p_attempt integer, p_latency_ms integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  insert into agent_tool_call (correlation_id, agent_key, role_id, tool_id, args, status,
                               result_hash, result_rows, result_bytes, error, attempt, latency_ms)
  values (p_correlation, p_agent_key, p_role_id, p_tool_id, coalesce(p_args,'{}'::jsonb), p_status,
          p_result_hash, p_result_rows, p_result_bytes, left(p_error, 500),
          coalesce(p_attempt,1), p_latency_ms)
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_red_view_alert(p_boards boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now        timestamptz := clock_timestamp();
  v_t0         timestamptz := clock_timestamp();
  v_red        int;
  v_opened     int := 0;
  v_resolved   int := 0;
  v_pending    int := 0;
  v_shown      int;
  v_open_total int;
  v_level      text;
  v_high       boolean;
  v_detail     text;
  v_keys       text;
  v_dedupe     text;
  v_req        bigint;
  v_suppressed int := 0;
begin
  create temp table if not exists red_now (source text, check_key text, detail text, opened_at timestamptz) on commit drop;
  delete from red_now;

  -- 1. kernel boards
  if p_boards then
    insert into red_now
    select 'board', 'board:' || b.board || ':' || b.check_name,
           left('expected ' || coalesce(b.expected,'') || ' | actual ' || coalesce(b.actual,''), 300), v_now
      from public.fn_kernel_all_boards() b
     where not b.ok;
  end if;

  -- 2. crons: latest run failed (pg_cron's own record) ...
  insert into red_now
  select 'cron', 'cron:' || j.jobname, left(coalesce(d.return_message,''), 300), d.start_time
    from cron.job j
    join (select distinct on (jobid) jobid, status, start_time, return_message
            from cron.job_run_details
           where start_time > v_now - interval '8 days'
           order by jobid, start_time desc, runid desc) d on d.jobid = j.jobid
   where j.active and d.status = 'failed';
  -- ... or latest kernel trace failed (the wrapper records the failure and returns normally)
  insert into red_now
  select 'cron', 'cron:' || j.jobname, left(coalesce(e.failure,''), 300), e.finished_at
    from cron.job j
    join public.phase_c_system_execution_wrapper w on w.jobid = j.jobid
    join (select distinct on (component_id) component_id, result, failure, finished_at
            from public.phase_c_system_execution
           where finished_at > v_now - interval '8 days'
           order by component_id, finished_at desc, trace_id desc) e on e.component_id = w.component_id
   where j.active and e.result = 'failed';

  -- 2b. credentials: an internal credential within 7 days of expiry. credential_rotate_daily
  -- renews every fn.<edge> credential 30 days ahead, so a row still here at 7 days means the
  -- rotation has been failing for three weeks -- and fn_internal_auth refuses it on the day.
  insert into red_now
  select 'credential', 'credential:' || c.context,
         left('expires ' || to_char(c.expires_at, 'YYYY-MM-DD HH24:MI') || ' UTC and no rotation has replaced it (credential_rotate_daily)', 300),
         c.expires_at - interval '7 days'
    from public.internal_credential c
   where c.active and c.retired_at is null and c.expires_at is not null and c.expires_at <= v_now + interval '7 days';
  -- 3. health checks: the latest row per target is failing
  insert into red_now
  select 'health', 'health:' || h.check_kind || ':' || h.target,
         left(coalesce(h.detail,'') || case when h.status_code is not null then ' (http ' || h.status_code || ')' else '' end, 300),
         h.created_at
    from (select distinct on (check_kind, target) *
            from public.health_checks
           where created_at > v_now - interval '24 hours'
           order by check_kind, target, created_at desc, id desc) h
   where h.ok = false;

  -- 4. connectivity register
  insert into red_now
  select 'connectivity', 'connectivity:' || r.gap_class || ':' || left(r.subject, 120), left(r.detail, 300), v_now
    from public.fn_company_connectivity_register() r;

  -- 5. department health board
  insert into red_now
  select 'department', 'department:' || v.dept_key,
         left(v.department || ' score ' || v.score::text || ' — ' || v.basis, 300), v_now
    from public.v_department_health v
    join public.org_departments d on d.dept_key = v.dept_key and d.active
   where v.status = 'at risk';

  -- 6. what the failed-runs watcher already paged (kept in the register, never paged twice)
  insert into red_now
  select 'watcher', 'watcher:' || left(s.signature, 150), left(s.signature, 300), s.first_seen_at
    from public.alert_signature s
   where s.watcher = 'failed_runs' and s.last_alerted_at is not null
     and s.last_seen_at > v_now - interval '24 hours'
     -- 5 Sep 2026: a signature the watcher has resolved on merit (its subject succeeded since) is green
     and s.resolved_at is null;

  select count(distinct check_key) into v_red from red_now;

  -- open what is new
  insert into public.red_episode (source, check_key, detail, opened_at, observed_at, last_seen_at, alerted_at, paged_by)
  select r.source, r.check_key, r.detail, r.opened_at, v_now, v_now,
         case when r.source = 'watcher' then v_now end,
         case when r.source = 'watcher' then 'failed_runs' end
    from (select distinct on (check_key) * from red_now order by check_key, opened_at) r
   where not exists (select 1 from public.red_episode e where e.check_key = r.check_key and e.resolved_at is null);
  get diagnostics v_opened = row_count;

  -- keep what is still red current
  update public.red_episode e
     set last_seen_at = v_now, detail = r.detail
    from (select distinct on (check_key) * from red_now order by check_key, opened_at) r
   where r.check_key = e.check_key and e.resolved_at is null;

  -- resolve what is green again (board episodes only on a pass that read the boards)
  update public.red_episode e
     set resolved_at = v_now
   where e.resolved_at is null
     and (p_boards or e.source <> 'board')
     and not exists (select 1 from red_now r where r.check_key = e.check_key);
  get diagnostics v_resolved = row_count;

  -- page the founder once for everything open and not yet alerted
  select count(*) into v_pending from public.red_episode where resolved_at is null and alerted_at is null;
  if v_pending > 0 then
    if public.fn_rehearsal_window_covers(v_now) then
      v_suppressed := v_pending;      -- a declared rehearsal: posted by the first pass after it closes
    else
      select count(*) into v_open_total from public.red_episode where resolved_at is null;
      -- the EPISODE ids are in the hash, not just the keys: the same key going red a second time is a
      -- new episode and must not be held by alert_founder's 24 h dedupe on the previous message's key
      -- (the probe caught exactly that before this line carried the id)
      select string_agg(check_key || '#' || id, ',' order by check_key, id),
             bool_or(source = 'health')
        into v_keys, v_high
        from public.red_episode where resolved_at is null and alerted_at is null;
      -- a page down is 'high' (alert_founder sends WhatsApp for high); everything else is 'error' (email)
      v_level  := case when v_high then 'high' else 'error' end;
      v_dedupe := 'red_view:' || md5(v_keys);
      select string_agg(left(check_key, 70) || ' — ' || left(coalesce(detail,''), 90), E'\n' order by opened_at), count(*)
        into v_detail, v_shown
        from (select check_key, detail, opened_at from public.red_episode
               where resolved_at is null and alerted_at is null
               order by opened_at limit 12) x;
      v_detail := v_pending || ' signal(s) went red and had not been alerted; ' || v_open_total
               || ' red in total right now.' || E'\n\n' || v_detail
               || case when v_pending > v_shown then E'\n… and ' || (v_pending - v_shown) || ' more (public.red_episode)' else '' end;

      -- 6 SEP 2026: fn_notify_founder, not an HTTP hop to alert_founder. A page down (source = 'health') is
      -- the platform_down kind and may reach him; every other red is the red_view kind, which
      -- founder_mail_policy routes to the IT operations engineer as ONE org_task per condition.
      perform public.fn_notify_founder(
        'Red view: ' || v_pending || ' new red signal(s)', left(v_detail, 1000), v_level,
        p_kind => case when v_high then 'platform_down' else 'red_view' end,
        p_dedupe_key => v_dedupe);
      update public.red_episode
         set alerted_at = clock_timestamp(), alert_dedupe_key = v_dedupe, paged_by = 'red_view'
       where resolved_at is null and alerted_at is null;
    end if;
  end if;

  return jsonb_build_object(
    'red_now', v_red, 'opened', v_opened, 'resolved', v_resolved,
    'paged', case when v_suppressed = 0 then v_pending else 0 end,
    'pending_in_rehearsal', v_suppressed,
    'level', v_level, 'dedupe_key', v_dedupe, 'request_id', v_req,
    'boards_read', p_boards,
    'elapsed_ms', round(extract(epoch from (clock_timestamp() - v_t0)) * 1000));
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_amount_aed(p_paid_aed numeric, p_paid_at timestamp with time zone, p_refund_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_paid numeric; v_admin numeric; v_pct numeric; v_days integer; v_interest numeric;
  v_min integer; v_max integer;
begin
  -- The customer's refund is the fee actually paid, in full: the published Refund Policy promises no
  -- administrative deduction and fn_refund_amount_is_the_fee_paid enforces it on the refunds row.
  v_paid  := round(coalesce(p_paid_aed, 0), 2);
  -- The AED 250 administrative fee and the 9% p.a. (UAE statutory maximum) are what the SUPPLIER whose
  -- silence caused the refund owes on top of the fee: founder decision 6 Sep 2026, verbatim in
  -- decision_policy.refund_policy_founder_decision_2026_09_06.
  v_admin := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_admin_fee_aed'), 250);
  v_pct   := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_late_fee_annual_pct'), 9);
  select bank_settlement_working_days_min, bank_settlement_working_days_max
    into v_min, v_max from public.pricing_config order by id limit 1;
  -- simple interest, pro-rated by CALENDAR days (Dubai dates) between the two instants
  v_days := greatest(0, (coalesce(p_refund_at, now()) at time zone 'Asia/Dubai')::date
                      - (coalesce(p_paid_at, coalesce(p_refund_at, now())) at time zone 'Asia/Dubai')::date);
  v_interest := round(v_paid * v_pct / 100.0 * v_days / 365.0, 2);
  return jsonb_build_object(
    'paid_aed', v_paid,
    'customer_refund_aed', v_paid,
    'admin_fee_aed', v_admin,
    'interest_pct_pa', v_pct,
    'interest_days', v_days,
    'interest_aed', v_interest,
    'supplier_charge_aed', round(v_paid + v_admin + v_interest, 2),
    'bank_settlement_working_days', coalesce(v_min, 7)::text || '-' || coalesce(v_max, 14)::text,
    'basis', 'customer: the reveal fee paid, refunded in full, no deduction; supplier: that fee + AED '
             || v_admin::text || ' administrative fee + ' || v_pct::text
             || '% p.a. simple interest for ' || v_days::text || ' calendar day(s)');
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_amount_is_the_fee_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.transactions%rowtype;
  v_expected bigint;
  -- The same three originators fn_phase_c_refund_execution_requires_decision names, read the same
  -- way. A refund Stripe already issued is a fact to be recorded, not a request to be approved.
  v_external constant text[] := array['stripe_webhook','stripe_dashboard','stripe'];
begin
  if lower(coalesce(NEW.requested_by,'')) = any(v_external) then
    return NEW;
  end if;

  if NEW.transaction_id is null then
    raise exception 'refunds: a refund must name the transaction it reverses. transaction_id is null, so this row asserts money is owed without saying which payment it came from. (refund_names_no_payment)'
      using errcode = '23514',
            hint = 'Set transaction_id to the public.transactions row whose reveal_fee is being returned. A refund this platform did not issue is recorded through fn_refund_settle with requested_by stripe_webhook, and that path is exempt.';
  end if;

  select * into t from public.transactions where id = NEW.transaction_id;
  if not found then
    raise exception 'refunds: transaction % does not exist. (refund_transaction_absent)',
      NEW.transaction_id using errcode = '23503';
  end if;

  if t.reveal_fee is null or t.reveal_fee <= 0 then
    raise exception 'refunds: transaction % records no reveal fee (reveal_fee %), so there is nothing to give back. A refund of an unpaid reveal is a payment, not a refund. (refund_no_fee_was_paid)',
      NEW.transaction_id, coalesce(t.reveal_fee::text,'null') using errcode = '23514';
  end if;

  if t.refund_deadline is null then
    raise exception 'refunds: transaction % has no refund window. trg_reveal_window opens one at reveal, so a transaction without it was never revealed and no refund can be due yet. (refund_window_not_open)',
      NEW.transaction_id using errcode = '23514';
  end if;
  if now() < t.refund_deadline then
    raise exception 'refunds: the refund window on transaction % opens at % and it is now %. The customer waits the founder-set period of working days after the reveal before a refund can be claimed. (refund_window_not_yet_open)',
      NEW.transaction_id, t.refund_deadline, now() using errcode = '23514';
  end if;

  v_expected := round(t.reveal_fee * 100)::bigint;
  if NEW.amount_fils is not null and NEW.amount_fils <> v_expected then
    raise exception 'refunds: the amount must equal the reveal fee the customer actually paid on transaction % — expected % fils (AED %), got % fils (AED %). A refund figure is read off the payment, never typed. (refund_amount_is_not_the_fee_paid)',
      NEW.transaction_id, v_expected, round(t.reveal_fee,2), NEW.amount_fils, round(NEW.amount_fils/100.0,2)
      using errcode = '23514';
  end if;

  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_decide(p_refund_id bigint, p_approve boolean, p_decided_by text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.refunds; v_new text;
begin
  select * into r from public.refunds where id = p_refund_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if r.status <> 'requested' then
    return jsonb_build_object('ok', false, 'error', 'not_decidable', 'status', r.status);
  end if;
  if coalesce(btrim(p_decided_by),'') = '' then
    return jsonb_build_object('ok', false, 'error', 'decider_required');
  end if;

  -- It used to be enough to be a non-empty string, which is how 'policy:auto_window' decided
  -- refunds. The decider must now be a person the founder identity register knows and has active.
  if not exists (select 1 from public.phase_c_founder_identity f
                  where f.active and lower(f.identity) = lower(btrim(p_decided_by))) then
    return jsonb_build_object('ok', false, 'error', 'founder_required',
      'hint', 'Every refund needs the founder, at any amount. public.phase_c_founder_identity is '
           || 'the register of who that is; ' || btrim(p_decided_by) || ' is not an active row in it.');
  end if;

  v_new := case when p_approve then 'approved' else 'rejected' end;
  update public.refunds set status = v_new, decided_by = p_decided_by, decided_at = now(), decision_note = p_note
   where id = p_refund_id;
  if r.transaction_id is not null then
    update public.transactions set refund_status = v_new, refund_resolved_at = now(),
           refund_note = coalesce(p_note, refund_note) where id = r.transaction_id;
  end if;
  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'status', v_new, 'decided_by', p_decided_by);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_execute_authorized(p_refund_id bigint, p_expect_amount numeric, p_expect_currency text, p_provider_ref text, p_provider_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; t record; v_dest text; v_basis text; v_state text;
begin
  select * into r from public.refund_case where refund_id = p_refund_id for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such refund case'); end if;

  -- THE SERVER-SIDE DECISION, read here rather than accepted from the caller. There is no parameter
  -- for "the CEO approved this", so a model cannot supply one.
  if r.state <> 'ceo_authorized' then
    return jsonb_build_object('ok', false, 'reason',
      format('this refund is %L, not ceo_authorized. Execution reads the decision from the record; it is not something a caller can assert.', r.state));
  end if;

  -- EXACT RESOURCE, AMOUNT AND CURRENCY. A mismatch is refused rather than rounded to the nearer of
  -- the two: "close enough" on money is the whole class of defect.
  if p_expect_amount is distinct from r.amount_aed then
    return jsonb_build_object('ok', false, 'reason',
      format('amount mismatch: the authorised refund is %s, the caller expected %s. Refusing rather than paying the difference in either direction.', r.amount_aed, p_expect_amount));
  end if;
  if upper(coalesce(p_expect_currency,'')) <> upper(r.currency) then
    return jsonb_build_object('ok', false, 'reason',
      format('currency mismatch: authorised in %s, caller expected %s.', r.currency, coalesce(p_expect_currency,'(none)')));
  end if;

  if r.attempts >= 5 then
    return jsonb_build_object('ok', false, 'reason',
      'retry policy exhausted at 5 attempts. The refund stays authorised and unpaid, which is a visible blocked state -- not a silent success and not an infinite retry against a provider that is down.');
  end if;

  -- THE DESTINATION IS DERIVED, NEVER PASSED. "Do not refund to an arbitrary new destination."
  select id, fee_status, reveal_fee, payment_ref into t
    from public.transactions where id = r.transaction_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'the settled payment behind this refund no longer exists; there is no destination of record to return money to.');
  end if;
  v_dest := t.payment_ref;
  v_basis := 'the original settled payment on transaction ' || r.transaction_id::text
          || '. Money returns the way it came; this function has no parameter for anywhere else.';
  if coalesce(v_dest,'') = '' then
    update public.refund_case set attempts = r.attempts + 1, last_attempt_at = now(),
      failure_reason = 'no payment reference on the settled transaction, so no destination of record.', updated_at = now()
     where refund_id = p_refund_id;
    return jsonb_build_object('ok', false, 'reason',
      'the settled payment carries no reference, so there is no destination of record. Held as authorised-and-blocked rather than sent somewhere plausible.');
  end if;

  v_state := case lower(coalesce(p_provider_outcome,''))
    when 'succeeded' then 'succeeded'
    when 'pending'   then 'provider_pending'
    when 'failed'    then 'failed'
    else 'submitted' end;

  update public.refund_case
     set state = v_state, destination_ref = v_dest, destination_basis = v_basis,
         provider_ref = p_provider_ref, provider_status = p_provider_outcome,
         submitted_at = coalesce(submitted_at, now()),
         settled_at = case when v_state = 'succeeded' then now() else settled_at end,
         failure_reason = case when v_state = 'failed' then coalesce(p_provider_outcome,'provider reported failure') else failure_reason end,
         attempts = r.attempts + 1, last_attempt_at = now(), updated_at = now()
   where refund_id = p_refund_id;

  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'state', v_state,
    'destination_ref', v_dest, 'destination_basis', v_basis, 'attempt', r.attempts + 1,
    'note', case v_state
      when 'succeeded' then 'Settled at the provider. The customer still has to be TOLD -- succeeded is not communicated.'
      when 'failed' then 'The provider refused it. This stays visible and retriable within policy; it is not a closed case.'
      else 'Submitted. Submitted is not settled, and the status tool reads the provider, not this row''s optimism.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_founder_decision_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status <> 'approved' then return new; end if;
  if exists (select 1 from public.phase_c_founder_identity f
              where f.active and lower(f.identity) = lower(btrim(coalesce(new.decided_by, '')))) then
    return new;
  end if;
  raise exception
    'refund %: approved by %, who is not an active founder identity.',
    coalesce(new.id::text, '(new)'), coalesce(nullif(btrim(new.decided_by), ''), '(nobody)')
    using errcode = '42501',
          hint = 'Every refund needs the founder, at any amount — his instruction, 17 Aug 2026. '
              || 'A refund reaches ''approved'' only through fn_refund_decide, and only with a '
              || 'decided_by that is an active row in public.phase_c_founder_identity. '
              || 'Before this guard, fn_refund_request auto-approved anything inside the promised '
              || 'window and under org_authority(customer_success, refund_within_window) — AED '
              || '2,000 — writing decided_by = ''policy:auto_window'' and setting '
              || 'transactions.refund_status = ''approved'', so it never appeared in his queue.';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_ladder_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t record; st jsonb; sup record; cust record;
  v_window int; v_chase int; v_agent text; v_dept text;
  v_subject text; v_body text; v_amounts jsonb; v_req jsonb; v_refund_id bigint; v_task bigint;
  v_chase_at timestamptz; v_final_at timestamptz; v_fee numeric;
  n_seen int := 0; n_chased int := 0; n_final int := 0; v_ids jsonb := '[]'::jsonb;
begin
  select refund_window_working_days, chase_after_working_days into v_window, v_chase
    from pricing_config order by id limit 1;
  v_window := coalesce(v_window, 5); v_chase := coalesce(v_chase, 3);

  -- THE OWNER of the chase is the existing employee who owns supplier follow-up: the Customer Success
  -- Director (org_role customer_success_director, runtime agent 'followup'; workflow_step refund #3/#4
  -- already names this role). Never a new agent (founder, 6 Sep 2026).
  select r.runtime_agent_key, r.primary_department_id into v_agent, v_dept
    from org_role r where r.role_id = 'customer_support' and r.status = 'active';
  v_agent := coalesce(v_agent, 'followup'); v_dept := coalesce(v_dept, 'customer_experience');

  for t in
    select x.* from transactions x
     where x.revealed_at is not null and coalesce(x.reveal_fee, 0) > 0
       and coalesce(x.refund_status, '') not in ('approved','refunded','processing','succeeded','rejected','cancelled','failed')
       and x.revealed_at > now() - interval '120 days'
     order by x.revealed_at
  loop
    n_seen := n_seen + 1;
    st := public.fn_refund_state(t.id);
    continue when st ? 'error' or coalesce((st->>'supplier_responded')::boolean, false);
    continue when st->>'state' not in ('chase_due', 'final_call_due');

    select company_name, coalesce(claimed_by, email) as email into sup from leads where id = t.supplier_id;
    select email, full_name into cust from customers where id = t.customer_id;
    v_chase_at := (st->>'chase_due_at')::timestamptz;
    v_final_at := (st->>'founder_call_due_at')::timestamptz;
    v_fee      := round(coalesce(t.reveal_fee, 0), 2);

    -- DAY 3: the chase. One email to the supplier, customer cc'd (fn_wa_fanout adds the WhatsApp copy
    -- when the supplier opted in), and one task on the owning employee. fn_refund_state reads the
    -- email back as chased_at, so a second tick cannot chase twice.
    if st->>'state' = 'chase_due' then
      v_subject := 'Action needed: a customer is waiting for your response — QuotesDone reveal #' || left(t.id::text, 8);
      v_body :=
        'Hello ' || coalesce(sup.company_name, '') || ',' || chr(10) || chr(10) ||
        'A customer paid to reveal your contact details on QuotesDone on ' ||
          to_char(t.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY') ||
          ' and has not heard from you. ' || v_chase::text || ' working days have passed. The customer is copied on this email so you can reply to all and pick it up here.' || chr(10) || chr(10) ||
        'Under the Supplier Agreement you must respond within ' || v_window::text || ' working days of the reveal, that is by ' ||
          to_char(v_final_at at time zone 'Asia/Dubai', 'DD Mon YYYY') ||
          '. If we have not seen a response by then, the case goes to our founder for a final call and the customer''s reveal fee is refunded. ' ||
        'Under the supplier terms that refund is then recovered from your account: the reveal fee (AED ' || v_fee::text ||
          '), an administrative fee of AED 250 and interest at 9% per annum until it is settled, and matching is paused until it is paid.' || chr(10) || chr(10) ||
        'If you have already been in touch with this customer, reply here and we will close this off.' || chr(10) || chr(10) ||
        'QuotesDone — Customer Success';
      insert into notifications(type, kind, to_email, cc_emails, to_role, lead_id, inquiry_id, quote_id, channel, subject, body, status)
      values ('supplier_no_response_chase', 'refund_ladder_chase', sup.email,
              array_remove(array[cust.email], null), 'supplier', t.supplier_id, t.inquiry_id, t.quote_id,
              'email', v_subject, v_body, 'queued');
      insert into org_tasks(dept_key, title, detail, status, tier, needs_founder, decided_by,
                            action_class, assigned_agent, priority, result)
      values (v_dept,
              left('Chase ' || coalesce(sup.company_name, 'supplier #' || t.supplier_id::text) || ': no response ' ||
                   v_chase::text || ' working days after a paid reveal', 200),
              'Reveal #' || t.id::text || ' (inquiry ' || coalesce(t.inquiry_id::text, '?') || '). The customer paid AED ' || v_fee::text ||
                ' on ' || to_char(t.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY') ||
                ' and the supplier has not responded. The chase email has been queued to ' || coalesce(sup.email, '(no email)') ||
                ' with the customer copied. Reach the supplier by every channel on file today. If they respond, record it ' ||
                '(supplier_ack_at or a portal message) so the case closes. If not, on ' ||
                to_char(v_final_at at time zone 'Asia/Dubai', 'DD Mon YYYY') ||
                ' the sweep files the refund and the founder makes the final call.',
              'assigned', 'advisory', false, 'fn_refund_ladder_sweep', 'routine_operational_decision', v_agent, 2,
              jsonb_build_object('refund_ladder', jsonb_build_object(
                'transaction_id', t.id, 'inquiry_id', t.inquiry_id, 'supplier_id', t.supplier_id,
                'step', 'chase', 'chase_due_at', v_chase_at, 'founder_call_due_at', v_final_at)))
      returning id into v_task;
      n_chased := n_chased + 1;
      v_ids := v_ids || jsonb_build_object('transaction_id', t.id, 'step', 'chase', 'task_id', v_task);
    end if;

    -- DAY 5: the founder's final call. The refund is FILED through the one existing door
    -- (fn_refund_request -> refunds 'requested', founder-gated by fn_refund_decide and the z00/z05
    -- guards) and he is notified with the facts. founder_alerts.dedupe_key is the idempotency record.
    if st->>'state' = 'final_call_due' then
      v_amounts := public.fn_refund_amount_aed(t.reveal_fee, t.revealed_at, now());
      if not exists (select 1 from refunds r where r.transaction_id = t.id) then
        v_req := public.fn_refund_request(
          round(t.reveal_fee * 100)::bigint, 'supplier_unresponsive', 'refund_ladder_sweep',
          t.inquiry_id, t.customer_id, t.supplier_id, t.quote_id, t.payment_ref, null,
          'Day ' || v_window::text || ' of the refund ladder: the supplier responded neither to the customer nor to the day-' ||
            v_chase::text || ' chase. Filed by the deterministic ladder sweep for the founder''s final call.',
          t.id);
      end if;
      select r.id into v_refund_id from refunds r where r.transaction_id = t.id order by r.id desc limit 1;

      perform public.fn_notify_founder(
        p_event => 'Refund final call: ' || coalesce(sup.company_name, 'supplier #' || t.supplier_id::text) ||
          ' silent for ' || v_window::text || ' working days on reveal #' || left(t.id::text, 8) || ' (AED ' || v_fee::text || ')',
        p_detail => 'Day ' || v_window::text || ' of the refund ladder. The supplier has not responded to the customer, to the day-' || v_chase::text ||
          ' chase' || case when (st->>'chased_at') is not null then ' sent ' || to_char((st->>'chased_at')::timestamptz at time zone 'Asia/Dubai', 'DD Mon YYYY') else ' (chase not recorded)' end ||
          case when t.customer_notified_at is not null then ', or to the customer''s formal notice of ' || to_char(t.customer_notified_at at time zone 'Asia/Dubai', 'DD Mon YYYY') else '' end || '.' || chr(10) || chr(10) ||
        'SUPPLIER: ' || coalesce(sup.company_name, '#' || t.supplier_id::text) || ' · ' || coalesce(sup.email, '(no email)') || ' · ' ||
          coalesce((select coalesce(nullif(btrim(l.whatsapp), ''), l.phone_e164, l.phone) from leads l where l.id = t.supplier_id), '(no phone)') || chr(10) ||
        'CUSTOMER: ' || coalesce(cust.full_name, '') || ' · ' || coalesce(cust.email, '') || chr(10) ||
        'REVEAL: transaction ' || t.id::text || ' · inquiry ' || coalesce(t.inquiry_id::text, '?') || ' · quotation AED ' || coalesce(t.quote_amount::text, '?') ||
          ' · reveal fee AED ' || v_fee::text || ' paid ' || to_char(t.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY HH24:MI') || chr(10) ||
        'REFUND REQUEST: #' || coalesce(v_refund_id::text, '?') || ' is in your queue (status requested).' || chr(10) ||
        'AMOUNTS (fn_refund_amount_aed): customer refund AED ' || (v_amounts->>'customer_refund_aed') || ' in full; supplier charge AED ' ||
          (v_amounts->>'supplier_charge_aed') || ' = fee ' || (v_amounts->>'paid_aed') || ' + admin fee AED ' || (v_amounts->>'admin_fee_aed') ||
          ' + ' || (v_amounts->>'interest_pct_pa') || '% p.a. interest (AED ' || (v_amounts->>'interest_aed') || ' for ' || (v_amounts->>'interest_days') || ' day(s) so far).' || chr(10) || chr(10) ||
        'YOUR CALL: phone the supplier. If there is still no response, approve refund #' || coalesce(v_refund_id::text, '?') ||
          ' in the OS; the customer is then refunded in full and told that banks take ' || (v_amounts->>'bank_settlement_working_days') ||
          ' working days, and the supplier''s charge is raised. If the supplier responds, reject it with a note and the case closes.',
        p_level => 'high', p_kind => 'refund_final_call', p_dedupe_key => 'refund_final_call:' || t.id::text, p_owner_agent => null);
      n_final := n_final + 1;
      v_ids := v_ids || jsonb_build_object('transaction_id', t.id, 'step', 'final_call', 'refund_id', v_refund_id);
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'seen', n_seen, 'chased', n_chased, 'final_calls', n_final,
                            'window_working_days', v_window, 'chase_after_working_days', v_chase,
                            'owner_agent', v_agent, 'cases', v_ids, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_quarantine(p_stripe_refund_id text, p_event_type text, p_reason text, p_payload jsonb DEFAULT NULL::jsonb, p_stripe_event_id text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.refund_event_quarantine (stripe_refund_id, stripe_event_id, event_type, reason, payload)
  values (nullif(btrim(coalesce(p_stripe_refund_id,'')),''), nullif(btrim(coalesce(p_stripe_event_id,'')),''),
          p_event_type, p_reason, p_payload)
  returning id;
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_read_status(p_refund_id bigint, p_mark_reported boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_say text;
begin
  select * into r from public.refund_case where refund_id = p_refund_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such refund case'); end if;

  -- THE CUSTOMER-FACING SENTENCE IS DERIVED FROM THE STATE, not composed. "Support sends accurate
  -- pending/failed/succeeded updates" -- accurate meaning the words cannot drift from the row.
  v_say := case r.state
    when 'requested'      then 'I have your refund request and I am looking into it now.'
    when 'investigating'  then 'I am still checking the payment and the delivery on your inquiry.'
    when 'eligible'       then 'I have finished checking and your request is going for a decision.'
    when 'ineligible'     then 'I have checked this and it is not eligible for a refund. ' || coalesce(r.eligibility_reason,'')
    when 'ceo_authorized' then 'Your refund has been approved. It has not left us yet -- I will tell you the moment it is sent.'
    when 'ceo_declined'   then 'Your refund was not approved. ' || coalesce(r.decision_rationale,'')
    when 'submitted'      then 'Your refund has been sent to the payment provider. It is not settled yet.'
    when 'provider_pending' then 'Your refund is with the payment provider and is still processing.'
    when 'succeeded'      then 'Your refund has been paid back to the card or account you originally paid from.'
    when 'failed'         then 'The refund did not go through at the payment provider. It is not lost -- I am on it and will come back to you.'
    when 'canceled'       then 'This refund was cancelled before it was sent.'
    when 'reconciled'     then 'Your refund is complete and reconciled on our side.'
    when 'communicated'   then 'Your refund is complete and you have been notified.'
    else 'I am checking the current state of your refund.' end;

  if p_mark_reported then
    update public.refund_case
       set status_reported_at = now(), status_reported_state = r.state, updated_at = now()
     where refund_id = p_refund_id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'state', r.state,
    'amount_aed', r.amount_aed, 'currency', r.currency, 'attempts', r.attempts,
    'provider_status', r.provider_status, 'destination_basis', r.destination_basis,
    'customer_message', v_say,
    -- A SUCCEEDED REFUND THE CUSTOMER HAS NOT BEEN TOLD ABOUT is an unfinished case, and this names it.
    'follow_through_owed', r.state in ('succeeded','failed','ceo_declined')
                           and (r.status_reported_state is distinct from r.state));
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_request(p_amount_fils bigint, p_reason_code text, p_requested_by text, p_inquiry_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_supplier_lead_id bigint DEFAULT NULL::bigint, p_quote_id uuid DEFAULT NULL::uuid, p_payment_intent text DEFAULT NULL::text, p_charge_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_in_window boolean := false; t public.transactions;
begin
  if p_amount_fils is null or p_amount_fils <= 0 then
    return jsonb_build_object('ok', false, 'error', 'amount_required');
  end if;

  select * into t from public.transactions
   where (p_transaction_id is not null and id = p_transaction_id)
      or (p_transaction_id is null and p_quote_id is not null and quote_id = p_quote_id)
      or (p_transaction_id is null and p_quote_id is null and p_payment_intent is not null and payment_ref = p_payment_intent)
   order by revealed_at desc nulls last limit 1;

  -- Recorded, never acted on. Whether the request arrived inside the window promised at reveal
  -- (transactions.refund_deadline, computed by fn_add_working_days when the quote was revealed) is
  -- exactly the kind of thing the founder wants in front of him when he decides — and exactly the
  -- kind of thing that must not decide for him.
  if t.id is not null and t.refund_deadline is not null and t.refund_deadline >= now() then
    v_in_window := true;
  end if;

  insert into public.refunds (transaction_id, inquiry_id, customer_id, supplier_lead_id, quote_id,
                              stripe_payment_intent, stripe_charge_id,
                              amount_fils, reason_code, reason_note, requested_by,
                              within_auto_window, status, reconciliation_note)
  values (t.id, coalesce(p_inquiry_id, t.inquiry_id), coalesce(p_customer_id, t.customer_id),
          coalesce(p_supplier_lead_id, t.supplier_id), coalesce(p_quote_id, t.quote_id),
          coalesce(p_payment_intent, t.payment_ref), p_charge_id,
          p_amount_fils, p_reason_code, p_note, p_requested_by,
          v_in_window, 'requested',
          'HELD FOR THE FOUNDER. Every refund waits for his decision, whatever the amount and '
       || 'whether or not it is inside the promised window — founder instruction, 17 Aug 2026. '
       || 'This one is ' || round(p_amount_fils / 100.0, 2) || ' AED and is '
       || case when v_in_window then 'inside' else 'outside' end || ' the window promised at reveal.')
  returning id into v_id;

  if t.id is not null then
    update public.transactions
       set refund_status = 'requested',
           refund_reason = coalesce(refund_reason, p_reason_code),
           refund_requested_at = coalesce(refund_requested_at, now()),
           refund_note = coalesce(p_note, refund_note)
     where id = t.id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'transaction_id', t.id,
                            'status', 'requested',
                            'within_auto_window', v_in_window,
                            'auto_approved', false,
                            'awaiting', 'founder');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_settle(p_stripe_refund_id text, p_status text, p_amount_fils bigint DEFAULT NULL::bigint, p_payment_intent text DEFAULT NULL::text, p_charge_id text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_amount_source text DEFAULT 'webhook_event'::text, p_stripe_event_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.refunds; v_status text; v_amount bigint; v_src text; v_q bigint;
begin
  if coalesce(btrim(p_stripe_refund_id),'') = '' then
    v_q := public.fn_refund_quarantine(null, 'refund', 'event carried no refund id',
             jsonb_build_object('status', p_status, 'payment_intent', p_payment_intent), p_stripe_event_id);
    return jsonb_build_object('ok', false, 'error', 'stripe_refund_id_required', 'quarantined', v_q);
  end if;

  v_status := case lower(coalesce(p_status,''))
                when 'succeeded' then 'succeeded' when 'failed' then 'failed'
                when 'canceled' then 'cancelled'  when 'cancelled' then 'cancelled'
                else 'processing' end;
  v_amount := nullif(coalesce(p_amount_fils, 0), 0);
  v_src    := case when v_amount is null then null else coalesce(p_amount_source, 'webhook_event') end;

  select * into r from public.refunds where stripe_refund_id = p_stripe_refund_id for update;

  if not found then
    select * into r from public.refunds
     where stripe_refund_id is null and p_payment_intent is not null
       and stripe_payment_intent = p_payment_intent and status in ('approved','processing','requested')
     order by created_at limit 1 for update;

    if found then
      update public.refunds set stripe_refund_id = p_stripe_refund_id,
             stripe_charge_id = coalesce(p_charge_id, stripe_charge_id) where id = r.id;
    else
      -- Issued outside the platform. Recorded with whatever is actually known, and NOTHING invented:
      -- if the amount is unknown it stays NULL and the row is marked unreconciled.
      insert into public.refunds (stripe_refund_id, stripe_payment_intent, stripe_charge_id,
                                  amount_fils, amount_source, reason_code, reason_note, requested_by, status,
                                  decided_by, decided_at, decision_note, reconciliation_note)
      values (p_stripe_refund_id, p_payment_intent, p_charge_id, v_amount,
              coalesce(v_src, 'unknown'), 'other',
              'Issued outside QuotesDone (Stripe dashboard or API). Recorded by the webhook.',
              'stripe_webhook', coalesce(v_status, 'processing'), 'stripe_dashboard', now(),
              'No in-platform request existed for this refund.',
              case when v_amount is null
                   then 'AMOUNT UNKNOWN - the event carried none and Stripe could not be read. Excluded from all financial totals until resolved.'
                   else null end)
      returning * into r;

      if v_amount is null then
        perform public.fn_refund_quarantine(p_stripe_refund_id, 'refund',
          'amount unknown: absent from the event and not retrievable from Stripe',
          jsonb_build_object('status', v_status, 'payment_intent', p_payment_intent, 'refund_row', r.id),
          p_stripe_event_id);
      end if;

      return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status, 'applied', true,
                                'created', true, 'amount_known', v_amount is not null);
    end if;
  end if;

  -- Duplicate delivery: same state twice. Cheap, silent, correct - but still take the chance to fill
  -- in an amount we did not have before.
  if r.status = v_status then
    if r.amount_fils is null and v_amount is not null then
      update public.refunds
         set amount_fils = v_amount, amount_source = v_src,
             reconciliation_note = 'amount resolved from a later ' || coalesce(p_amount_source,'event'),
             updated_at = now()
       where id = r.id;
      return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status,
                                'idempotent', true, 'applied', false, 'amount_resolved', true);
    end if;
    return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status,
                              'idempotent', true, 'applied', false);
  end if;

  -- The matrix decides. Not a rank, not an ordering heuristic - a declared policy with a reason
  -- attached to every refusal.
  if not public.fn_refund_transition_allowed(r.status, v_status) then
    v_q := public.fn_refund_quarantine(p_stripe_refund_id, 'refund',
      'transition not permitted: ' || r.status || ' -> ' || v_status || '. '
      || coalesce((select note from public.refund_status_transition
                    where from_status = r.status and to_status = v_status), 'no rule declared for this pair'),
      jsonb_build_object('refund_row', r.id, 'from', r.status, 'to', v_status,
                         'amount_fils', p_amount_fils, 'payment_intent', p_payment_intent),
      p_stripe_event_id);
    update public.refunds
       set reconciliation_note = left(coalesce(reconciliation_note || ' | ', '')
           || 'refused ' || r.status || '->' || v_status || ' at ' || to_char(now(),'YYYY-MM-DD HH24:MI'), 500),
           updated_at = now()
     where id = r.id;
    return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status, 'applied', false,
                              'refused_transition', r.status || '->' || v_status, 'quarantined', v_q);
  end if;

  update public.refunds
     set status = v_status,
         amount_fils   = coalesce(v_amount, amount_fils),
         amount_source = case when v_amount is not null then v_src else amount_source end,
         stripe_charge_id = coalesce(p_charge_id, stripe_charge_id),
         stripe_payment_intent = coalesce(p_payment_intent, stripe_payment_intent),
         settled_at = case when v_status = 'succeeded' then coalesce(settled_at, now()) else settled_at end,
         failure_reason = case when v_status = 'failed' then p_failure_reason else failure_reason end,
         reconciliation_note = case
             when v_status = 'succeeded' and coalesce(v_amount, amount_fils) is null
             then 'AMOUNT UNKNOWN on a settled refund - excluded from all financial totals until resolved.'
             else reconciliation_note end,
         updated_at = now()
   where id = r.id;

  if r.transaction_id is not null then
    update public.transactions
       set refund_status = v_status, refund_stripe_id = p_stripe_refund_id,
           refund_amount_aed = case when v_amount is not null then round(v_amount/100.0, 2) else refund_amount_aed end,
           refund_confirmed_at = case when v_status = 'succeeded' then coalesce(refund_confirmed_at, now())
                                      else refund_confirmed_at end
     where id = r.transaction_id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', v_status, 'applied', true,
                            'amount_known', coalesce(v_amount, r.amount_fils) is not null);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_state(p_transaction uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; v_window int; v_chase int; v_notify_days int; v_min int; v_max int;
        v_responded boolean; v_chase_at timestamptz; v_final_at timestamptz; v_notify_at timestamptz;
        v_chased_at timestamptz; v_final_sent_at timestamptz; v_state text;
begin
  select * into t from transactions where id = p_transaction;
  if not found then return jsonb_build_object('error','transaction_not_found'); end if;

  -- THE LADDER (founder, 6 Sep 2026): the clock starts when the customer PAYS (revealed_at), never at
  -- a nudge or a notice. Day 3 without a supplier response: the owning employee chases. Day 5: the
  -- founder is notified for the final call and the refund becomes approvable. All from pricing_config.
  select refund_window_working_days, chase_after_working_days,
         bank_settlement_working_days_min, bank_settlement_working_days_max
    into v_window, v_chase, v_min, v_max from pricing_config order by id limit 1;
  v_window := coalesce(v_window, 5); v_chase := coalesce(v_chase, 3);
  v_notify_days := coalesce((select value::text::int from decision_policy where key='refund_notify_after_working_days'),1);

  v_responded := t.supplier_ack_at is not null
    or exists (select 1 from messages m
               where m.inquiry_id = t.inquiry_id and m.supplier_id = t.supplier_id
                 and m.sender = 'supplier' and coalesce(m.blocked,false) = false
                 and m.created_at > t.revealed_at);

  v_chase_at  := case when t.revealed_at is null then null else public.fn_add_working_days(t.revealed_at, v_chase) end;
  v_final_at  := case when t.revealed_at is null then null
                      else coalesce(t.refund_deadline, public.fn_add_working_days(t.revealed_at, v_window)) end;
  v_notify_at := case when t.revealed_at is null then null else public.fn_add_working_days(t.revealed_at, v_notify_days) end;

  select min(n.created_at) into v_chased_at from notifications n
   where n.type = 'supplier_no_response_chase' and n.channel = 'email'
     and n.inquiry_id = t.inquiry_id and n.lead_id = t.supplier_id
     and t.revealed_at is not null and n.created_at > t.revealed_at;
  select min(f.created_at) into v_final_sent_at from founder_alerts f
   where f.dedupe_key = 'refund_final_call:' || t.id::text;

  v_state := case
    when t.revealed_at is null                                                          then 'not_revealed'
    when v_responded                                                                    then 'supplier_responded'
    when coalesce(t.refund_status,'') in ('approved','refunded','processing','succeeded') then 'refunded'
    when coalesce(t.refund_status,'') = 'rejected'                                      then 'refund_rejected'
    when now() < v_chase_at                                                             then 'waiting'
    when now() < v_final_at then case when v_chased_at is null then 'chase_due' else 'chased' end
    else case when v_final_sent_at is null then 'final_call_due' else 'final_call_sent' end end;

  return jsonb_build_object(
    'transaction_id', t.id,
    'state', v_state,
    'revealed_at', t.revealed_at,
    'supplier_responded', v_responded,
    'refund_window_working_days', v_window,
    'chase_after_working_days', v_chase,
    'chase_due_at', v_chase_at,
    'chased_at', v_chased_at,
    'founder_call_due_at', v_final_at,
    'final_call_sent_at', v_final_sent_at,
    'refund_deadline', t.refund_deadline,
    'notify_available_at', v_notify_at,
    'can_notify', (t.revealed_at is not null and not v_responded and t.customer_notified_at is null
                   and now() >= v_notify_at and v_state not in ('refunded','refund_rejected')),
    'notified_at', t.customer_notified_at,
    'auto_nudged_at', t.nudged_24_at,
    'refund_approvable', v_state in ('final_call_due','final_call_sent'),
    'refund_status', t.refund_status,
    'working_days_since_reveal', case when t.revealed_at is null then 0
                                      else public.fn_working_days_between(t.revealed_at, now()) end,
    'working_days_since_notice', case when t.customer_notified_at is null then 0
                                      else public.fn_working_days_between(t.customer_notified_at, now()) end,
    'bank_settlement_working_days', coalesce(v_min,7)::text || '-' || coalesce(v_max,14)::text
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_transition_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select allowed from public.refund_status_transition
                    where from_status = p_from and to_status = p_to), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_refunds_settled_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'succeeded' and new.settled_at is null then new.settled_at := now(); end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_register_document(p_bucket text, p_path text, p_kind text, p_ref_table text, p_ref_id text, p_file_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_kind text;
begin
  if p_path is null or p_path = '' then return; end if;
  v_kind := lower(btrim(coalesce(p_kind, '')));
  v_kind := case v_kind
    when 'quotation'      then 'quote'
    when 'quotations'     then 'quote'
    when 'quotes'         then 'quote'
    when 'agreement'      then 'contract'
    when 'agreements'     then 'contract'
    when 'contracts'      then 'contract'
    when 'bill'           then 'invoice'
    when 'bills'          then 'invoice'
    when 'invoices'       then 'invoice'
    when 'license'        then 'licence'
    when 'licenses'       then 'licence'
    when 'licences'       then 'licence'
    when 'cert'           then 'certificate'
    when 'certs'          then 'certificate'
    when 'certificates'   then 'certificate'
    when 'dwg'            then 'drawing'
    when 'drawings'       then 'drawing'
    when 'plan'           then 'drawing'
    when 'plans'          then 'drawing'
    when 'boq'            then 'drawing'
    when 'po'             then 'purchase_order'
    when 'pos'            then 'purchase_order'
    when 'purchase order' then 'purchase_order'
    when 'purchase-order' then 'purchase_order'
    else v_kind
  end;
  if v_kind is null or v_kind = '' then v_kind := 'other'; end if;
  insert into public.documents(bucket, path, kind, ref_table, ref_id, file_name)
  values (p_bucket, p_path, v_kind, p_ref_table, p_ref_id,
          coalesce(p_file_name, split_part(p_path, '/', array_length(string_to_array(p_path, '/'), 1))))
  on conflict (bucket, path) do nothing;
end $function$


CREATE OR REPLACE FUNCTION public.fn_rehearsal_window_covers(p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.rehearsal_window w
    where p_at >= w.started_at
      and p_at <= coalesce(w.ended_at, w.started_at + interval '6 hours')
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_remediation_step(p_id bigint, p_score numeric, p_cost_aed numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r agent_remediation;
begin
  select * into r from agent_remediation where id = p_id for update;
  if r.id is null then raise exception 'unknown remediation %', p_id; end if;

  update agent_remediation
     set attempts = attempts + 1,
         cost_aed = cost_aed + coalesce(p_cost_aed, 0),
         baseline_score = coalesce(baseline_score, p_score),
         latest_score = p_score,
         status = case
           when p_score >= 0.8 and coalesce(baseline_score, p_score) <= p_score then 'passed'
           when attempts + 1 >= max_attempts or cost_aed + coalesce(p_cost_aed,0) >= max_cost_aed then 'escalated'
           else 'retesting' end,
         blocks_autonomy = not (p_score >= 0.8 and coalesce(baseline_score, p_score) <= p_score),
         closed_at = case when p_score >= 0.8 then now() else null end
   where id = p_id
   returning * into r;

  return jsonb_build_object('id', r.id, 'status', r.status, 'attempts', r.attempts,
                            'baseline', r.baseline_score, 'latest', r.latest_score,
                            'blocks_autonomy', r.blocks_autonomy, 'cost_aed', r.cost_aed);
end $function$


CREATE OR REPLACE FUNCTION public.fn_report_drilldown(p_metric text, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with b as (select coalesce(nullif(btrim(p_metric), ''), '~none~') m,
                    greatest(coalesce(p_days, 30), 1) d),
  series as (
    select s.taken_at, s.value from public.metric_snapshot s, b
     where s.metric_key ilike '%' || b.m || '%'
       and s.taken_at > now() - (b.d || ' days')::interval
     order by s.taken_at desc limit 60
  )
  select jsonb_build_object(
    'metric', (select m from b), 'window_days', (select d from b),

    -- WHY IT MOVED: the last two readings, and the change between them.
    'series', coalesce((select jsonb_agg(jsonb_build_object('at', taken_at, 'value', value) order by taken_at desc) from series), '[]'::jsonb),
    'latest', (select value from series order by taken_at desc limit 1),
    'previous', (select value from series order by taken_at desc offset 1 limit 1),
    'change', (select (select value from series order by taken_at desc limit 1)
                    - (select value from series order by taken_at desc offset 1 limit 1)),
    'readings', (select count(*) from series),

    'index', (select jsonb_build_object('index_name', c.index_name, 'score', c.score, 'band', c.band,
                'measured_on', c.measured_on, 'dimensions', c.dimensions)
                from public.company_index c, b
               where c.index_name ilike '%' || b.m || '%'
               order by c.measured_on desc limit 1),

    -- THE TARGET it is measured against.
    'target', (select jsonb_build_object('goal_key', g.goal_key, 'horizon', g.horizon,
                 'period_label', g.period_label, 'target_value', g.target_value,
                 'actual_value', g.actual_value, 'status', g.status,
                 'gap', g.target_value - g.actual_value, 'updated_at', g.updated_at)
                from public.goal_period g, b
               where g.goal_key ilike '%' || b.m || '%'
               order by g.updated_at desc limit 1),

    -- WHO CONTRIBUTED: the decisions that named this metric in the window.
    'contributors', coalesce((select jsonb_agg(jsonb_build_object(
          'actor', l.actor, 'os', public.fn_owning_os(l.actor), 'kind', l.kind,
          'decision', l.decision, 'confidence', l.confidence, 'at', l.created_at)
        order by l.created_at desc)
      from (select l.* from public.decision_log l, b
             where l.created_at > now() - (b.d || ' days')::interval
               and (l.decision ilike '%' || b.m || '%' or l.ctx::text ilike '%' || b.m || '%')
             order by l.created_at desc limit 10) l), '[]'::jsonb),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_report_pdf_enqueue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_source text;
begin
  v_source := case tg_table_name when 'board_reports' then 'board' when 'exec_reports' then 'exec' when 'finance_reports' then 'finance' end;
  begin
    insert into public.action_execution (action_class, executor, idempotency_key, risk_tier, reversible, request, status, author, correlation_id)
    values ('report.pdf', 'report_pdf', 'report_pdf:' || v_source || ':' || new.id, 'low', true,
            jsonb_build_object('source', v_source, 'id', new.id), 'queued', 'report_pdf_trigger', gen_random_uuid());
  exception
    when unique_violation then null;                       -- already queued for this row
    when others then raise warning 'fn_report_pdf_enqueue: % (the report row is kept; its PDF can be minted on demand)', sqlerrm;
  end;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_report_recommendation_approve(p_report_id bigint, p_index integer, p_by text, p_source text DEFAULT 'exec_reports'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_rec jsonb; v_title text; v_id bigint; v_officer text; v_dept text; v_task bigint;
begin
  if p_source = 'exec_reports' then
    select r.recommendations -> p_index, r.officer into v_rec, v_officer
      from public.exec_reports r where r.id = p_report_id;
  else
    select r.kpis -> p_index, 'board' into v_rec, v_officer
      from public.board_reports r where r.id = p_report_id;
  end if;
  if v_rec is null then
    return jsonb_build_object('ok', false, 'error', 'no recommendation at that index');
  end if;
  v_title := coalesce(v_rec ->> 'title', v_rec ->> 'recommendation', left(v_rec::text, 160));

  insert into public.agent_actions(agent, kind, status, risk, title, recommendation,
      target_table, target_id, decided_by, decided_at, detail)
    values (coalesce(v_officer, 'exec'), 'report_recommendation', 'approved',
      coalesce(v_rec ->> 'risk', 'medium'), v_title, v_rec::text,
      p_source, p_report_id::text, p_by, now(),
      jsonb_build_object('report_id', p_report_id, 'index', p_index, 'source', p_source, 'recommendation', v_rec))
    returning id into v_id;

  -- ROUTE IT AS REAL WORK. The department is the accountable officer's; a05_org_task_fill_ownership
  -- gives it an owner and, when the recommendation names a goal, ties it to that objective. Idempotent
  -- on the report+index marker, so approving the same recommendation twice does not double the work.
  v_dept := coalesce((select department from public.org_agents
                        where agent_key = coalesce(public.fn_org_agent_resolve(v_officer), v_officer)), 'exec');
  select id into v_task from public.org_tasks t
   where t.action_class = 'report_recommendation'
     and t.detail like '%report #'||p_report_id||' rec '||p_index||' by %'
     and t.status <> 'done'
   order by id limit 1;
  if v_task is null then
    insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    values (v_dept, v_title,
      coalesce(v_rec ->> 'why', v_rec ->> 'recommendation', v_title)
        ||'  [Approved from the '||p_source||' report #'||p_report_id||' rec '||p_index||' by '||p_by
        ||'. Do it, or bring evidence the standard is wrong.]',
      'assigned', 'advisory', false, 'report_recommendation')
    returning id into v_task;
    update public.agent_actions set detail = detail || jsonb_build_object('org_task_id', v_task) where id = v_id;
  end if;

  return jsonb_build_object('ok', true, 'action_id', v_id, 'org_task_id', v_task,
                            'title', v_title, 'report_id', p_report_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_reputation_recompute()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; n int := 0; v_score numeric; v_tier text;
  v_gated int := 0; v_restored int := 0; v_unmeasured int := 0; v_provisional int := 0;
  v_hold record;
  k_prior constant numeric := 5;    -- weight of the neutral prior, in observations
  k_mid   constant numeric := 50;   -- the prior itself
  k_floor constant numeric := 10;   -- observations needed before a tier other than standard is assigned
  -- per-dimension (hits, n)
  c_hit numeric; c_n numeric;  q_hit numeric; q_n numeric;  l_hit numeric; l_n numeric;
  e_hit numeric; e_n numeric;  b_hit numeric; b_n numeric;  y_hit numeric; y_n numeric;
  v_corr numeric; v_decq numeric; v_learn numeric; v_cost numeric; v_collab numeric; v_rel numeric;
  v_total numeric; v_dims int; v_provisional_row boolean;
  post constant text := 'posterior';
begin
  -- A hold the founder actually holds open still pauses scoring; authority must not move under it.
  select s.id, s.stood_down_at into v_hold
    from public.company_stand_down s where s.resumed_at is null
   order by s.stood_down_at desc limit 1;
  if v_hold.id is not null then
    return jsonb_build_object('ok', false, 'status', 'PAUSED_BY_FOUNDER_STANDDOWN',
      'scored', 0, 'gated', 0, 'restored', 0, 'unmeasured', 0,
      'stand_down_id', v_hold.id, 'since', v_hold.stood_down_at,
      'note', 'No employee is scored, promoted or demoted while a stand-down is open.');
  end if;

  for r in select a.agent_key from public.org_agents a order by a.agent_key loop
    -- correctness: graded outcomes of its actions + review verdicts on work it authored
    select count(*) filter (where verdict = 'improved'),
           count(*) filter (where verdict in ('improved','no_change','worse'))
      into c_hit, c_n from public.outcome_record where actor = r.agent_key;
    select c_hit + count(*) filter (where decision = 'approve'),
           c_n + count(*)
      into c_hit, c_n from public.review_chain
     where author_agent = r.agent_key and decision in ('approve','reject','request_revision');

    -- decision quality: decisions a human could review (confidence + source + reason)
    select count(*) filter (where l.confidence is not null
                              and l.sources is not null and l.sources::text not in ('null','[]','{}','""')
                              and l.reasons is not null and l.reasons::text not in ('null','[]','{}','""')),
           count(*)
      into q_hit, q_n from public.decision_log l where l.actor = r.agent_key;

    -- learning speed: graded training attempts it passed
    select count(*) filter (where passed), count(*)
      into l_hit, l_n from public.agent_training_attempt
     where agent_key = r.agent_key and passed is not null;

    -- cost efficiency: calls a cheaper model could NOT have served
    select count(*) filter (where not coalesce(could_be_cheaper, false)), count(*)
      into e_hit, e_n from public.ai_cost_log where agent_key = r.agent_key;

    -- collaboration: reviews it gave as reviewer that carry a reason
    select count(*) filter (where nullif(btrim(coalesce(reason,'')), '') is not null), count(*)
      into b_hit, b_n from public.review_chain
     where reviewer_agent = r.agent_key and decision in ('approve','reject','request_revision','hold');

    -- reliability: assigned tasks that reached done (escalated counts against; cancelled excluded)
    -- + runs under its own key that did not error
    select count(*) filter (where status = 'done'), count(*)
      into y_hit, y_n from public.org_tasks
     where assigned_agent = r.agent_key and status in ('done','escalated');
    select y_hit + count(*) filter (where status <> 'error'), y_n + count(*)
      into y_hit, y_n from public.agent_runs where agent = r.agent_key;

    v_corr  := round((k_mid*k_prior + 100.0*c_hit) / (k_prior + c_n), 1);
    v_decq  := round((k_mid*k_prior + 100.0*q_hit) / (k_prior + q_n), 1);
    v_learn := round((k_mid*k_prior + 100.0*l_hit) / (k_prior + l_n), 1);
    v_cost  := round((k_mid*k_prior + 100.0*e_hit) / (k_prior + e_n), 1);
    v_collab:= round((k_mid*k_prior + 100.0*b_hit) / (k_prior + b_n), 1);
    v_rel   := round((k_mid*k_prior + 100.0*y_hit) / (k_prior + y_n), 1);
    v_total := c_n + q_n + l_n + e_n + b_n + y_n;
    v_dims  := (c_n > 0)::int + (q_n > 0)::int + (l_n > 0)::int + (e_n > 0)::int + (b_n > 0)::int + (y_n > 0)::int;
    v_provisional_row := false;

    if v_total = 0 then
      v_score := null; v_tier := 'unmeasured'; v_unmeasured := v_unmeasured + 1;
    else
      v_score := round(v_corr*0.30 + v_rel*0.30 + v_cost*0.15 + v_learn*0.15 + v_collab*0.10, 1);
      if v_total < k_floor or v_dims < 2 then
        v_tier := 'standard'; v_provisional_row := true; v_provisional := v_provisional + 1;
      else
        v_tier := case when v_score >= 85 then 'senior_trusted'
                       when v_score >= 70 then 'trusted'
                       when v_score >= 50 then 'standard' else 'probation' end;
      end if;
    end if;

    insert into public.agent_reputation
      (agent_key, correctness, reliability, cost_efficiency, learning_speed, collaboration,
       decision_quality, score, tier, computed_at, evidence)
    values (r.agent_key, v_corr, v_rel, v_cost, v_learn, v_collab, v_decq, v_score, v_tier, now(),
            jsonb_build_object('method', post, 'prior', k_mid, 'prior_weight', k_prior,
              'tier_floor', k_floor, 'provisional', v_provisional_row, 'dimensions_with_evidence', v_dims,
              'correctness', c_n, 'decision_quality', q_n, 'learning_speed', l_n,
              'cost_efficiency', e_n, 'collaboration', b_n, 'reliability', y_n, 'total', v_total))
    on conflict (agent_key) do update set
      correctness = excluded.correctness, reliability = excluded.reliability,
      cost_efficiency = excluded.cost_efficiency, learning_speed = excluded.learning_speed,
      collaboration = excluded.collaboration, decision_quality = excluded.decision_quality,
      score = excluded.score, tier = excluded.tier, computed_at = now(), evidence = excluded.evidence;
    n := n + 1;
  end loop;

  -- probation is a real consequence: any agent below the floor loses autonomous authority.
  with demoted as (
    update public.employee_authority a set max_tier = 'gated'
      from public.agent_reputation p
     where p.agent_key = a.agent_key and p.tier = 'probation' and a.max_tier = 'autonomous'
    returning a.agent_key, a.action_class)
  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  select 'employee_authority:' || agent_key || '/' || action_class, 'reputation_demote', 'tighten',
         'autonomous', 'gated', 'reputation tier fell to probation'
    from demoted;
  get diagnostics v_gated = row_count;

  -- ...and recovery is a real consequence too: a grant this routine demoted comes back when the
  -- tier is no longer probation, and an advisory-safe grant comes back on any earned tier.
  with restored as (
    update public.employee_authority a set max_tier = 'autonomous'
      from public.agent_reputation p
     where p.agent_key = a.agent_key
       and a.max_tier = 'gated'
       and p.tier in ('standard','trusted','senior_trusted')
       and (a.note = 'Advisory-safe action, may run autonomously'
            or exists (select 1 from public.autonomy_control_audit u
                        where u.op = 'reputation_demote'
                          and u.object = 'employee_authority:' || a.agent_key || '/' || a.action_class
                          and not exists (select 1 from public.autonomy_control_audit v
                                           where v.op = 'reputation_restore' and v.object = u.object and v.at > u.at)))
    returning a.agent_key, a.action_class)
  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  select 'employee_authority:' || agent_key || '/' || action_class, 'reputation_restore', 'loosen',
         'gated', 'autonomous',
         'reputation tier is no longer probation (a tier below standard needs 10 observations on two dimensions); a demotion this routine made is lifted'
    from restored;
  get diagnostics v_restored = row_count;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('reputation', now(), now(), 'ok',
    jsonb_build_object('scored', n, 'gated', v_gated, 'restored', v_restored, 'unmeasured', v_unmeasured, 'provisional', v_provisional),
    'Reputation recomputed for ' || n || ' employee(s) on six dimensions from recorded facts '
    || '(posterior mean, prior 50 with weight 5; evidence counts stored per dimension). '
    || v_unmeasured || ' have no evidence on any dimension and carry a NULL score; ' || v_provisional
    || ' are provisional standard with fewer than 10 observations or evidence on one dimension only. '
    || 'Probation demoted ' || v_gated || ' autonomous grant(s) to gated; recovery restored ' || v_restored || '.');
  return jsonb_build_object('ok', true, 'scored', n, 'gated', v_gated, 'restored', v_restored,
                            'unmeasured', v_unmeasured, 'provisional', v_provisional);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_resolve_cat_agent(cat text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text; c text := lower(trim(coalesce(cat,'')));
begin
  if c = '' then return null; end if;

  -- Hop 1 and 2, unchanged: the caller already holds a catalogue slug.
  if exists(select 1 from category_agents where slug=c and coalesce(active,true)) then return 'cat:'||c; end if;
  if exists(select 1 from agent_knowledge where agent_key='cat:'||c limit 1) then return 'cat:'||c; end if;

  -- Hop 3, NEW: the declared trade -> catalogue bridge, the same one fn_category_knowledge walks.
  -- Before the name LIKE, because a mapping somebody decided beats a substring that happens to hit.
  select 'cat:'||m.catalog_slug into k
    from lead_trade_map m
   where m.trade_key = c
     and exists (select 1 from agent_knowledge a where a.agent_key = 'cat:'||m.catalog_slug)
   limit 1;
  if k is not null then return k; end if;

  -- Hop 4, unchanged: the display-name fallback, now only reached when nothing declared a mapping.
  select 'cat:'||slug into k from category_agents
    where coalesce(active,true) and (lower(name) like '%'||c||'%' or c like '%'||slug||'%' or lower(name)=c)
    order by length(slug) desc limit 1;
  return k;
end $function$


CREATE OR REPLACE FUNCTION public.fn_review_decide(p_kind text, p_ref_id bigint, p_decision text, p_comment text DEFAULT NULL::text, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare dec text := lower(coalesce(p_decision,'')); ok boolean := false;
begin
  if dec not in ('approve','changes','reject') then return jsonb_build_object('error','decision must be approve|changes|reject'); end if;

  if p_kind = 'marketing_post' then
    update content_drafts set
      review_status = case dec when 'approve' then 'approved' when 'changes' then 'changes_requested' else 'rejected' end,
      founder_comment = coalesce(p_comment, founder_comment), reviewed_at = now()
    where id = p_ref_id and status='draft';
    ok := found;
    -- On approve, social_stage will publish it live (gated by marketing_golive). On changes, the marketing loop revises it.

  elsif p_kind = 'refund' then
    update transactions set
      refund_status = case dec when 'approve' then 'approved' when 'reject' then 'declined' else 'requested' end,
      refund_note = coalesce(p_comment, refund_note),
      refund_resolved_at = case when dec in ('approve','reject') then now() else refund_resolved_at end
    where id = p_ref_id and refund_status='requested';
    ok := found;

  elsif p_kind = 'boost_budget' then
    update review_queue set
      status = case dec when 'approve' then 'approved' when 'changes' then 'changes_requested' else 'rejected' end,
      founder_comment = coalesce(p_comment, founder_comment), decided_at = now(), decided_by = p_by
    where id = p_ref_id and status='pending';
    ok := found;
  else
    return jsonb_build_object('error','unknown kind '||p_kind);
  end if;

  return jsonb_build_object('ok', ok, 'kind', p_kind, 'ref_id', p_ref_id, 'decision', dec);
end $function$


CREATE OR REPLACE FUNCTION public.fn_review_pending()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'marketing_posts', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','marketing_post','ref_id',c.id,'title',c.title,'channel',c.channel,'body',c.body,'image_url',c.image_url,
        'media_missing', case when c.image_url is null then 'no media designed yet' end,
        'created_at',c.created_at)
        order by c.created_at desc)
      from content_drafts c where c.status='draft' and coalesce(c.review_status,'pending')='pending'), '[]'::jsonb),
    'refunds', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','refund','ref_id',t.id,'customer_id',t.customer_id,'reason',t.refund_reason,'requested_at',t.refund_requested_at)
        order by t.refund_requested_at desc)
      from transactions t where t.refund_status='requested'), '[]'::jsonb),
    'boost_budgets', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','boost_budget','ref_id',r.id,'title',r.title,'summary',r.summary,'payload',r.payload,'created_at',r.created_at)
        order by r.created_at desc)
      from review_queue r where r.kind='boost_budget' and r.status='pending'), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_review_submit(p_subject_type text, p_subject_id text, p_dept_key text, p_author text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_crit        jsonb;
  v_rule        jsonb;
  v_violations  jsonb := '[]'::jsonb;
  v_unenforced  jsonb := '[]'::jsonb;
  v_critical    int := 0;
  v_major       int := 0;
  v_pick        jsonb;
  v_head        text;
  v_deleg_from  text;
  v_deleg_basis text;
  v_cos         text := 'brief';
  v_decision    text;
  v_reason      text;
  v_conf        numeric;
  v_first_rule  text;
  v_res         jsonb;
begin
  -- CANONICAL AUTHOR, OR THE LEDGER CANNOT SEE ITS OWN SELF-REVIEWS.
  -- review_chain.author_agent was written with whatever string the caller passed while
  -- reviewer_agent was always resolved. A head authoring under an alias therefore produced a row
  -- whose author and reviewer were the SAME employee under two names - and every self-review
  -- count in this system is "author_agent = reviewer_agent", which such a row passes.
  -- So the reported zero was a property of the spelling, not of the behaviour.
  p_author := coalesce(public.fn_org_agent_resolve(p_author), p_author);

  -- Who is actually able to approve for this department right now, GIVEN WHO WROTE IT.
  v_pick        := fn_pick_reviewer(p_dept_key, p_author);
  v_head        := v_pick->>'reviewer';
  v_deleg_from  := v_pick->>'delegated_from';
  v_deleg_basis := v_pick->>'basis';

  -- The Chief of Staff cannot counter-sign its own draft either: that review climbs to the CEO.
  if p_author = coalesce(public.fn_org_agent_resolve(v_cos), v_cos) then v_cos := 'ceo'; end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, stage, decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, 'drafted', null,
          'Draft submitted for department review', null);

  if v_head is null then
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                              decision, reason, confidence, delegated_from, delegation_basis)
    values (p_subject_type, p_subject_id, p_dept_key, p_author, null, 'dept_review',
            'escalate', 'No available approver in ' || p_dept_key || ': ' || coalesce(v_deleg_basis,''), 1.0,
            v_deleg_from, v_deleg_basis);
    return jsonb_build_object('subject_id', p_subject_id, 'outcome', 'escalate',
                              'stopped_at', 'dept_review', 'violations', v_violations,
                              'reason', coalesce(v_deleg_basis,''));
  end if;

  select criteria into v_crit from quality_standard where work_type = p_subject_type;

  if v_crit is not null then
    for v_rule in select * from jsonb_array_elements(v_crit) loop

      if (v_rule ? 'check_fn') then
        begin
          execute format('select %I($1,$2)', v_rule->>'check_fn')
            into v_res using p_subject_id, p_content;
        exception when others then
          v_res := jsonb_build_object('passed', false, 'detail', 'check ' || (v_rule->>'check_fn') || ' errored: ' || sqlerrm);
        end;
        if not coalesce((v_res->>'passed')::boolean, false) then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity',
            'why', v_rule->>'why', 'detail', v_res->>'detail');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        end if;

      elsif (v_rule ? 'pattern') and (v_rule ? 'fails_when') then
        if (v_rule->>'fails_when') = 'match' and p_content ~ (v_rule->>'pattern') then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        elsif (v_rule->>'fails_when') = 'no_match' and p_content !~ (v_rule->>'pattern') then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        end if;

      else
        v_unenforced := v_unenforced || jsonb_build_object(
          'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
      end if;

    end loop;
  end if;

  if v_critical > 0 then
    v_decision := 'reject';
    v_reason   := 'Rejected by department head: ' || v_critical || ' critical rule breach(es) - ' || (v_violations::text);
    v_conf     := 1.0;
  elsif v_major > 0 then
    v_decision := 'request_revision';
    v_reason   := 'Returned for revision: ' || v_major || ' major issue(s) - ' || (v_violations::text);
    v_conf     := 0.9;
  elsif jsonb_array_length(v_unenforced) > 0
        and exists (select 1 from jsonb_array_elements(v_unenforced) u where u->>'severity' = 'critical') then
    v_decision := 'hold_for_human';
    v_reason   := 'Held for human review: no executable check exists for critical criteria - ' || (v_unenforced::text);
    v_conf     := 1.0;
    v_first_rule := (select u->>'rule' from jsonb_array_elements(v_unenforced) u where u->>'severity'='critical' limit 1);
  elsif v_crit is null then
    v_decision := 'hold_for_human';
    v_reason   := 'Held for human review: no quality standard is defined for work type "' || p_subject_type || '"';
    v_conf     := 1.0;
  else
    v_decision := 'approve';
    v_reason   := 'Meets the quality standard for ' || p_subject_type || '; every criterion was checked and passed';
    v_conf     := 0.95;
  end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, violated_rule, confidence, delegated_from, delegation_basis)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_head, 'dept_review',
          v_decision, v_reason, v_first_rule, v_conf, v_deleg_from,
          case when v_deleg_from is not null then v_deleg_basis else null end);

  if v_decision <> 'approve' then
    return jsonb_build_object('subject_id', p_subject_id, 'outcome', v_decision,
                              'stopped_at', 'dept_review', 'violations', v_violations,
                              'unenforceable', v_unenforced,
                              'reviewer', v_head, 'delegated_from', v_deleg_from);
  end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_cos, 'cos_review',
          'approve', 'Approved by Chief of Staff: brand-compliant and serves a company goal', 0.9);

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_cos, 'published',
          'approve', 'Published after full approval chain', 1.0);

  -- 4 Sep 2026: the content.published emit that stood here is retired. It fired on every approved
  -- review of any subject (org_tasks, posts, documents) — 360 events, 1,003 deliveries, 163 tasks
  -- minted and 87 still open for two subscribers who wanted campaign.published. The 'published'
  -- review_chain row above is the log; the real publish path emits campaign.published from
  -- content_drafts.status = 'posted' (fn_emit_campaign_published_from_content).

  return jsonb_build_object('subject_id', p_subject_id, 'outcome', 'published',
                            'stopped_at', 'published', 'violations', v_violations,
                            'unenforceable', v_unenforced,
                            'reviewer', v_head, 'delegated_from', v_deleg_from);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_rfq_board(p_search text DEFAULT ''::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select i.id, coalesce(nullif(trim(i.category),''),'general') as category,
      coalesce(nullif(trim(i.emirate),''),'—') as emirate,
      left(coalesce(nullif(trim(i.summary),''), i.raw_input, ''),140) as summary,
      i.expected_value as value, nullif(btrim(i.budget),'') as budget, i.urgency, i.status, i.outcome, i.created_at,
      case lower(coalesce(i.pipeline_stage, i.status, ''))
        when 'won' then 'won' when 'revealed' then 'revealed' when 'quoted' then 'quoted' when 'matched' then 'matched'
        else (case when i.outcome='won' then 'won' else 'new' end) end as stage
    from inquiries i
    where coalesce(p_search,'')='' or i.category ilike '%'||p_search||'%' or i.summary ilike '%'||p_search||'%' or i.emirate ilike '%'||p_search||'%'
  ), ranked as (select *, row_number() over (partition by stage order by created_at desc, id desc) rn from base),
  sc as (select stage, count(*) c from base group by stage)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'stages',(select jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'count',coalesce((select c from sc where sc.stage=s.key),0),
      'cards',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'category',r.category,'emirate',r.emirate,'summary',r.summary,'value',r.value,'budget',r.budget,'urgency',r.urgency,'status',r.status) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
      order by s.ord)
      from (values ('new','New',1),('matched','Matched',2),('quoted','Quoted',3),('revealed','Revealed',4),('won','Won',5)) s(key,label,ord)),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'category',b.category,'emirate',b.emirate,'summary',b.summary,'value',b.value,'budget',b.budget,'urgency',b.urgency,'status',b.status,'stage',b.stage,'created_at',b.created_at) order by b.created_at desc, b.id desc),'[]'::jsonb)
             from (select * from base order by created_at desc, id desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_redispatch_sweep(p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  v_ref text; v_secret text;
  v_sent int := 0; v_eligible int := 0;
begin
  select value into v_secret from app_secrets where key = 'cred_db_internal';
  if v_secret is null then
    return jsonb_build_object('error', 'cred_db_internal missing', 'ran_at', now());
  end if;

  select value into v_ref from app_secrets where key = 'project_ref';
  if v_ref is null then
    select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
      from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
  end if;
  if v_ref is null then
    return jsonb_build_object('error', 'cannot determine project ref', 'ran_at', now());
  end if;

  select count(*) into v_eligible
    from public.inquiries i
   where i.rfq_ready is true
     and i.status in ('open', 'sent', 'split')
     and (i.routing->>'dispatched_at') is not null
     and (i.routing->>'fanout') is not null and (i.routing->>'fanout')::int = 0
     and i.created_at > now() - interval '90 days'
     and coalesce((i.routing->>'redispatch_count')::int, 0) < 30
     and coalesce((i.routing->>'redispatch_last')::timestamptz, 'epoch'::timestamptz)
           < now() - interval '6 hours';

  for r in
    select i.id
      from public.inquiries i
     where i.rfq_ready is true
       and i.status in ('open', 'sent', 'split')
       and (i.routing->>'dispatched_at') is not null
       and (i.routing->>'fanout') is not null and (i.routing->>'fanout')::int = 0
       and i.created_at > now() - interval '90 days'
       and coalesce((i.routing->>'redispatch_count')::int, 0) < 30
       and coalesce((i.routing->>'redispatch_last')::timestamptz, 'epoch'::timestamptz)
             < now() - interval '6 hours'
     order by i.created_at
     limit greatest(p_limit, 0)
  loop
    -- Stamped BEFORE the call, so a request that never comes back still consumes its attempt and
    -- the backoff holds. dispatched_at is left alone: it records a real historical event and the
    -- fixed guard no longer treats a zero-fanout run as a dispatch.
    update public.inquiries
       set routing = coalesce(routing, '{}'::jsonb)
                   || jsonb_build_object(
                        'redispatch_last', now(),
                        'redispatch_count', coalesce((routing->>'redispatch_count')::int, 0) + 1)
     where id = r.id;

    perform net.http_post(
      url     := 'https://' || v_ref || '.supabase.co/functions/v1/dispatch_inquiry',
      headers := jsonb_build_object('Content-Type', 'application/json'),
      body    := jsonb_build_object('__secret', v_secret, 'inquiry_id', r.id));

    v_sent := v_sent + 1;
  end loop;

  return jsonb_build_object(
    'ran_at', now(), 'eligible', v_eligible, 'retried', v_sent, 'limit', p_limit,
    'note', case when v_eligible = 0
                 then 'No RFQ is waiting on supply. Nothing to retry.'
                 else v_sent || ' of ' || v_eligible || ' RFQs that reached zero suppliers were '
                      || 'offered to the matcher again; supply may have arrived since they were created.'
            end);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_rfq_required_check(i inquiries)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  spec_fields jsonb; f jsonb; bag jsonb := '{}'::jsonb; blob text;
  k text; v text; bk text; opt text; tok text; toks text[];
  reqn int := 0; have text[] := '{}';
  miss jsonb := '[]'::jsonb; advisory jsonb := '[]'::jsonb; found boolean;
begin
  select cs.fields into spec_fields
    from public.category_specs cs
   where lower(cs.category) = lower(coalesce(i.category,''))
   limit 1;

  if spec_fields is null or jsonb_typeof(spec_fields) <> 'array' then
    return jsonb_build_object('applicable', false, 'reason', 'no category_specs row',
      'category', i.category, 'required_ok', true, 'required_total', 0,
      'present','[]'::jsonb, 'missing','[]'::jsonb, 'advisory_missing','[]'::jsonb, 'checked_at', now());
  end if;

  if i.spec is not null and jsonb_typeof(i.spec) = 'object' then
    for k, v in
      select e.key, case when jsonb_typeof(e.value) in ('object','array')
                         then e.value::text else coalesce(e.value #>> '{}','') end
        from jsonb_each(i.spec) e
    loop
      bag := bag || jsonb_build_object(lower(k), v);
    end loop;

    for k, v in
      select e2.key, case when jsonb_typeof(e2.value) in ('object','array')
                          then e2.value::text else coalesce(e2.value #>> '{}','') end
        from jsonb_each(i.spec) e1
        join lateral jsonb_each(case when jsonb_typeof(e1.value)='object'
                                     then e1.value else '{}'::jsonb end) e2 on true
    loop
      if not public._rfq_answered(bag->>lower(k)) then
        bag := bag || jsonb_build_object(lower(k), v);
      end if;
    end loop;
  end if;

  bag := bag
    || case when coalesce(i.emirate,'') <> '' then
            jsonb_build_object('emirate', i.emirate,
              'location', coalesce(nullif(bag->>'location',''), i.emirate)) else '{}'::jsonb end
    || case when coalesce(i.scope_type,'') <> '' then
            jsonb_build_object('scope', coalesce(nullif(bag->>'scope',''), i.scope_type)) else '{}'::jsonb end
    || case when coalesce(i.budget,'') <> '' then jsonb_build_object('budget', i.budget) else '{}'::jsonb end
    || case when coalesce(array_length(i.trades,1),0) > 0 then
            jsonb_build_object('trades', array_to_string(i.trades,', ')) else '{}'::jsonb end
    || case when coalesce(i.drawing_file_path,'') <> '' or i.boq is not null then
            jsonb_build_object('drawing','provided') else '{}'::jsonb end;

  blob := lower(concat_ws(' ', i.summary, i.raw_input, i.spec::text));
  foreach tok in array coalesce(regexp_split_to_array(lower(coalesce(i.category,'')), '[^a-z0-9]+'), '{}'::text[]) loop
    if length(coalesce(tok,'')) >= 4 then blob := replace(blob, tok, ' '); end if;
  end loop;

  for f in select value from jsonb_array_elements(spec_fields)
            where coalesce((value->>'required')::boolean, false)
  loop
    k := nullif(btrim(lower(coalesce(f->>'key',''))), '');

    -- Keyless required field: unaddressable, so ADVISORY ONLY (never blocks dispatch).
    if k is null then
      advisory := advisory || jsonb_build_object(
        'question', f->>'question', 'reason', 'category_specs field has no key - cannot be gated');
      continue;
    end if;

    reqn := reqn + 1; found := false;

    if public._rfq_answered(bag->>k) then found := true; end if;

    if not found then
      for bk in select key from jsonb_each_text(bag) loop
        if public._rfq_answered(bag->>bk) then
          if public._rfq_concept(k) is not null
             and public._rfq_concept(k) = public._rfq_concept(bk) then
            found := true;
          else
            foreach tok in array coalesce(string_to_array(k,'_'), '{}'::text[]) loop
              if length(coalesce(tok,'')) >= 4
                 and (bk = tok or bk like '%'||tok||'%' or tok like '%'||bk||'%') then
                found := true;
              end if;
            end loop;
          end if;
        end if;
        exit when found;
      end loop;
    end if;

    if not found and jsonb_typeof(f->'options') = 'array' then
      for opt in select lower(o) from jsonb_array_elements_text(f->'options') o loop
        toks := coalesce(regexp_split_to_array(regexp_replace(coalesce(opt,''),'[^a-z0-9 ]',' ','g'), '\s+'), '{}'::text[]);
        foreach tok in array toks loop
          if length(coalesce(tok,'')) >= 4 and blob like '%'||tok||'%' then found := true; end if;
        end loop;
        exit when found;
      end loop;
    end if;

    if found then
      have := array_append(have, k);
    else
      miss := miss || jsonb_build_object('key', k, 'question', f->>'question', 'type', f->>'type');
    end if;
  end loop;

  return jsonb_build_object(
    'applicable', true, 'category', i.category,
    'required_total', reqn,
    'required_ok', (jsonb_array_length(miss) = 0),
    'present', to_jsonb(have),
    'missing', miss,
    'advisory_missing', advisory,
    'checked_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_score(i inquiries)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare pts int:=0; miss text[]:='{}'; have text[]:='{}'; spectxt text;
        catchk jsonb; catmiss text[]:='{}'; m jsonb; gready boolean; catok boolean;
begin
  spectxt := coalesce(i.spec::text,'');
  if coalesce(i.category,'')<>'' then pts:=pts+20; have:=array_append(have,'category'); else miss:=array_append(miss,'category'); end if;
  if coalesce(i.emirate,'')<>'' then pts:=pts+10; have:=array_append(have,'emirate'); else miss:=array_append(miss,'emirate'); end if;
  if length(regexp_replace(spectxt,'[^a-zA-Z0-9]','','g')) > 20 then pts:=pts+25; have:=array_append(have,'scope_detail'); else miss:=array_append(miss,'scope_detail'); end if;
  if coalesce(i.scope_type,'')<>'' then pts:=pts+15; have:=array_append(have,'scope_type'); else miss:=array_append(miss,'scope_type'); end if;
  if i.budget is not null then pts:=pts+15; have:=array_append(have,'budget'); else miss:=array_append(miss,'budget'); end if;
  if coalesce(array_length(i.trades,1),0)>0 or coalesce(i.drawing_file_path,'')<>'' or i.boq is not null then
     pts:=pts+15; have:=array_append(have,'supporting_detail'); else miss:=array_append(miss,'supporting_detail'); end if;

  gready := pts >= 70;

  catchk := public.fn_rfq_required_check(i);
  catok  := coalesce((catchk->>'required_ok')::boolean, true);

  if coalesce((catchk->>'applicable')::boolean,false) then
    for m in select value from jsonb_array_elements(coalesce(catchk->'missing','[]'::jsonb)) loop
      catmiss := array_append(catmiss, coalesce(nullif(m->>'question',''), m->>'key'));
    end loop;
  end if;

  return jsonb_build_object(
    'score', pts,
    'generic_ready', gready,
    'category_required_ok', catok,
    'ready', (gready and catok),
    'have', to_jsonb(have),
    'missing', to_jsonb(miss || catmiss),
    'category_missing', coalesce(catchk->'missing','[]'::jsonb),
    'category_check', catchk,
    'scored_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_role_identity_isolation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_other text;
begin
  select string_agg(o.packaged_role_id || ' (' || o.archetype || ')', ', '
                    order by o.packaged_role_id)
    into v_other
    from public.org_role_identity o
   where o.agent_key = new.agent_key
     and o.packaged_department = new.packaged_department
     and o.packaged_role_id <> new.packaged_role_id
     and ( (    new.archetype = 'reviewer-auditor'
            and o.archetype in ('director','operations-specialist','analyst-controller'))
        or (    o.archetype = 'reviewer-auditor'
            and new.archetype in ('director','operations-specialist','analyst-controller')) );

  if v_other is null then
    return new;
  end if;

  -- The conflict may exist, but only as a decision somebody signed for — and signed for THIS
  -- archetype.  Matching on (agent_key, packaged_role_id) alone was tried and probed: it let
  -- payments-and-revenue-operations-analyst-controller be redefined to reviewer-auditor on the
  -- strength of a decision that had been recorded about the analyst-controller identity.  A
  -- decision about one identity is not consent for a different one.
  if exists (select 1 from public.role_isolation_decision d
              where d.agent_key = new.agent_key
                and d.packaged_role_id = new.packaged_role_id
                and d.archetype = new.archetype) then
    return new;
  end if;

  raise exception
    'agent % would be both producer and independent reviewer of % (this row: % as %; also holds: %)',
    new.agent_key, new.packaged_department, new.packaged_role_id, new.archetype, v_other
    using errcode = '23514',
          hint = 'record the call in role_isolation_decision first: '
                 'isolate | split | restrict_to_advisory | block';
end $function$


CREATE OR REPLACE FUNCTION public.fn_role_of(p_email text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e text := lower(trim(coalesce(p_email,'')));
  v_role text;
  v_from date;
  v_on boolean;
begin
  if e = '' then return 'guest'; end if;

  -- Human identities first: unchanged behaviour, still wins over everything.
  select ur.role into v_role from user_roles ur
   where ur.email = e
   order by array_position(array['owner','admin','ops','finance','support','agent'], ur.role)
   limit 1;
  if v_role is not null then return v_role; end if;

  if e = any (string_to_array(lower(coalesce((select value from app_secrets where key='admin_emails'),'')), ','))
    then return 'owner'; end if;

  -- AGENT IDENTITY. Only for values that are not email addresses, so a real
  -- person can never be mistaken for an employee record.
  if position('@' in e) = 0 then
    if exists (select 1 from org_agents where lower(agent_key) = e and active) then
      v_on := lower(coalesce((select value from app_secrets where key='agent_autonomy_enabled'),'true')) = 'true';
      begin
        v_from := coalesce((select value from app_secrets where key='agent_autonomy_from'),'2026-07-30')::date;
      exception when others then v_from := date '2026-07-30';
      end;
      if v_on and current_date >= v_from then
        return 'agent';
      else
        return 'guest';   -- pre-arming: behaviour identical to today
      end if;
    end if;
  end if;

  if exists (select 1 from leads where lower(coalesce(claimed_by,'')) = e) then return 'supplier'; end if;
  if exists (select 1 from customers where lower(coalesce(email,'')) = e) then return 'customer'; end if;
  return 'guest';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_route_party(p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select a.agent_key from public.org_agents a
      where a.active and a.agent_key = nullif(btrim(coalesce(p_name, '')), '') limit 1),
    (select d.dept_key from public.org_departments d
      where d.dept_key = nullif(btrim(coalesce(p_name, '')), '')
        and exists (select 1 from public.org_agents a2
                     where a2.department = d.dept_key and a2.active) limit 1));
$function$


CREATE OR REPLACE FUNCTION public.fn_routing_tier_model(p_agent_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when a.routing_tier is null then null else jsonb_build_object(
      'routing_tier', a.routing_tier,
      'registry_tier', t.rt,
      'model', (select r.model_id from model_registry r
                 where r.active and r.approved and r.tier = t.rt
                 order by r.in_per_mtok_usd limit 1)) end
    from org_agents a
    cross join lateral (select case a.routing_tier
                                 when 'reviewer_auditor'      then 'large'
                                 when 'operations_specialist' then 'small'
                                 else 'medium' end as rt) t
   where a.agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
     and coalesce(a.active, true)
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_run_vt()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_files jsonb;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  select coalesce(jsonb_agg(jsonb_build_object('bucket', o.bucket_id, 'path', o.name, 'size', coalesce((o.metadata->>'size')::bigint,0))), '[]'::jsonb)
    into v_files
  from (
    select bucket_id, name, metadata, created_at
    from storage.objects
    where bucket_id in ('quote-files','drawing-files','supplier-docs','receipt-files')
      and right(name,1) <> '/'
      and name not in (select path from vt_results where path is not null)
    order by created_at desc
    limit 4
  ) o;
  perform net.http_post(
    url := 'https://' || public.qd_project_ref() || '.supabase.co/functions/v1/vt_scan',
    body := jsonb_build_object('__secret', v_secret, 'files', v_files),
    headers := '{"Content-Type":"application/json"}'::jsonb
  );
end;$function$


CREATE OR REPLACE FUNCTION public.fn_runner_silence_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_run bigint; n_alert int := 0; n_watched int := 0; v_email text;
begin
  insert into agent_runs(agent, started_at) values ('runner_silence_watch', clock_timestamp()) returning id into v_run;

  select to_email into v_email from notifications
   where type='founder_brief' and to_email is not null order by created_at desc limit 1;

  -- RE-DERIVE, NEVER SEED. One pass over 30 days of runs gives every runner its own observed
  -- cadence. A runner seen fewer than 5 times has no cadence worth calling regular and is recorded
  -- as on-demand rather than alerted on — which is what stops this becoming the noise generator the
  -- 18 July snapshot would have been if anything had ever read it.
  with runs as (
    select agent, started_at, counts,
           started_at - lag(started_at) over (partition by agent order by started_at) gap
      from agent_runs where started_at > now() - interval '30 days'),
  agg as (
    select agent,
           count(*) as n,
           -- A CADENCE IS NOT A BURST. Measured on the first run: doc_extract, match, quote_compare,
           -- inquiry_intake and stripe_webhook all showed a "median gap" of 0.00-0.08 hours, because
           -- they are EVENT-DRIVEN and fire in clusters when work arrives. Treating a cluster as a
           -- schedule makes every quiet day an alert. A real cadence shows up on separate DAYS, so
           -- that is what is counted.
           count(distinct started_at::date) as active_days,
           -- A RUNNER LOGGED ONLY ON EXCEPTIONS HAS NO CADENCE EITHER. cos_execute writes an
           -- agent_runs row under its own name ONLY when it has a throttled signal to report (a
           -- refused task start); its ordinary hourly work is logged under 'ceo'. So its
           -- rows stop the moment it stops having a PROBLEM, and the first version of this watch
           -- read that as the runner going silent -- alerting daily on a loop that was working.
           count(*) filter (where coalesce(counts ? 'signal', false)) as signal_rows,
           max(started_at) as last_seen,
           percentile_cont(0.5) within group (order by extract(epoch from gap)/3600.0) as median_gap_h
      from runs group by agent)
  insert into agent_expectations (agent, kind, max_silence_hours, on_demand, median_gap_hours,
                                  runs_observed, last_seen, note, updated_at)
  select a.agent,
         case when exists (select 1 from org_agents o where o.agent_key = a.agent) then 'employee' else 'code' end,
         -- Three times its own median, floored at 6 hours and capped at two weeks. Derived from the
         -- runner rather than from its schedule, because the schedule is what fn_agent_silence_watch
         -- already checks and is exactly what stayed green while the work stopped.
         case when a.n >= 5 and a.active_days >= 5 and a.median_gap_h >= 0.5 and a.n > a.signal_rows
              then least(336, greatest(6, ceil(a.median_gap_h * 3)))
              else 999999 end,
         not (a.n >= 5 and a.active_days >= 5 and a.median_gap_h >= 0.5 and a.n > a.signal_rows),
         round(a.median_gap_h::numeric, 2),
         a.n,
         a.last_seen,
         case when a.n >= 5 and a.active_days >= 5 and a.median_gap_h >= 0.5 and a.n > a.signal_rows
              then 'cadence learned from '||a.n||' run(s) across '||a.active_days||' day(s) in 30d, median gap '||round(a.median_gap_h::numeric,2)||'h'
              else 'no steady cadence ('||a.n||' run(s) across '||a.active_days||' day(s), median gap '
                   ||coalesce(round(a.median_gap_h::numeric,2)::text,'n/a')||'h) — event-driven or on-demand, not watched' end,
         now()
    from agg a
  on conflict (agent) do update set
    kind = excluded.kind, max_silence_hours = excluded.max_silence_hours,
    on_demand = excluded.on_demand, median_gap_hours = excluded.median_gap_hours,
    runs_observed = excluded.runs_observed, last_seen = excluded.last_seen,
    note = excluded.note, updated_at = now();

  select count(*) into n_watched from agent_expectations where not on_demand;

  -- EVERY row, not just the watched ones. Scoping this to `not on_demand` left a stale silent=true
  -- on any runner that moved INTO on_demand — measured on the first run: five event-driven runners
  -- kept a silent flag they could no longer clear.
  update agent_expectations e
     set silent = (not e.on_demand
                   and e.last_seen is not null
                   and e.last_seen < now() - (e.max_silence_hours || ' hours')::interval);

  -- ONCE PER SILENCE EPISODE, ONE EMAIL PER RUN (3 Sep 2026). This loop paged the founder once per
  -- silent employee per DAY — 21 "Employee has stopped working" emails in the 24 hours measured on
  -- 3 Sep, 59 all-time — for runners whose schedules were switched off by his own 16 Aug stand-down
  -- and re-enabled on 2-3 Sep. A silence is one fact, not a daily one: an episode is (runner,
  -- last_seen); it is paged the first time it is seen and never again until the runner has run
  -- (a new last_seen is a new episode). And the employees newly silent in one pass go into ONE
  -- email, never one email each. Nothing is hidden: every silent runner is still in
  -- agent_expectations.silent and in the company snapshot.
  declare v_new text := ''; v_new_n int := 0;
  begin
  for r in select agent, kind, last_seen, max_silence_hours, median_gap_hours
             from agent_expectations where silent and not on_demand order by agent
  loop
    if not exists (select 1 from founder_alerts
                    where event='runner_silent'
                      and detail like '%"runner": "'||r.agent||'"%'
                      and detail like '%"last_run": "'||coalesce(r.last_seen::text,'')||'"%') then
      insert into founder_alerts(level, event, detail, channel)
      values (case when r.kind='employee' then 'high' else 'warn' end, 'runner_silent',
        jsonb_build_object('runner', r.agent, 'kind', r.kind,
          'last_run', r.last_seen::text,
          'silent_hours', round(extract(epoch from (now()-r.last_seen))/3600),
          'own_median_gap_hours', r.median_gap_hours,
          'expected_within_hours', r.max_silence_hours)::text, 'email');
      if r.kind = 'employee' then
        v_new_n := v_new_n + 1;
        v_new := v_new || '- ' || r.agent || ': last did anything at ' || coalesce(r.last_seen::text,'unknown')
              || ' (own cadence one run every ' || coalesce(r.median_gap_hours::text,'?') || ' hours)' || E'\n';
      end if;
      n_alert := n_alert + 1;
    end if;
  end loop;
  if v_new_n > 0 then
    -- 6 SEP 2026: routed to the COO as one org_task per condition, never emailed
    -- (founder_mail_policy.runner_silence); this watcher's own founder_alerts rows are its ledger.
    perform public.fn_founder_mail_route('runner_silence',
      v_new_n || ' employee(s) have stopped working',
      'These runners went past their own observed cadence for the first time since they last ran:' || E'\n' || v_new ||
      E'\n' || 'Each is reported once per silence; it will be reported again only after it runs and stops again. ' ||
      'A scheduled job may still be succeeding — this watch looks at what the runner DID, not at whether its schedule fired.',
      'high');
  end if;
  end;

  update agent_runs set finished_at=clock_timestamp(), status='ok',
      counts=jsonb_build_object('runners', (select count(*) from agent_expectations),
                                'watched', n_watched, 'silent', (select count(*) from agent_expectations where silent),
                                'alerts', n_alert,
                                'employees', (select count(*) from agent_expectations where kind='employee'))
   where id=v_run;

  return jsonb_build_object('runners',(select count(*) from agent_expectations),
                            'watched',n_watched,'alerts',n_alert);
exception when others then
  update agent_runs set finished_at=clock_timestamp(), status='error', note=left(sqlerrm,500) where id=v_run;
  raise;
end $function$


CREATE OR REPLACE FUNCTION public.fn_sanctions_screen_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net', 'pg_temp'
AS $function$
declare v_ref text; v_secret text; v_req bigint;
begin
  select value into v_ref    from public.app_secrets where key = 'project_ref';
  select value into v_secret from public.app_secrets where key = 'cred_cron_compliance';
  if v_ref is null or v_secret is null then
    raise exception 'fn_sanctions_screen_tick: % is missing from app_secrets, so the weekly screening cannot be posted',
      case when v_ref is null then 'project_ref' else 'cred_cron_compliance' end;
  end if;
  select net.http_post(
    url     := 'https://' || v_ref || '.supabase.co/functions/v1/sanctions_screen',
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body    := jsonb_build_object('__secret', v_secret, 'caller', 'cron.sanctions_screen_weekly'),
    timeout_milliseconds := 120000
  ) into v_req;
  return jsonb_build_object('posted', true, 'request_id', v_req);
end $function$


CREATE OR REPLACE FUNCTION public.fn_schema_export()
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with t as (
  select c.relname as rel,
    'CREATE TABLE IF NOT EXISTS public.'||quote_ident(c.relname)||E' (\n'||
    string_agg('  '||quote_ident(a.attname)||' '||format_type(a.atttypid,a.atttypmod)||
      case a.attidentity when 'a' then ' GENERATED ALWAYS AS IDENTITY' when 'd' then ' GENERATED BY DEFAULT AS IDENTITY' else '' end||
      case when a.attgenerated='s' then ' GENERATED ALWAYS AS ('||pg_get_expr(ad.adbin,ad.adrelid)||') STORED'
           when ad.adbin is not null then ' DEFAULT '||pg_get_expr(ad.adbin,ad.adrelid) else '' end||
      case when a.attnotnull then ' NOT NULL' else '' end, E',\n' order by a.attnum)
    ||E'\n);' as tbl_ddl
  from pg_class c join pg_namespace n on n.oid=c.relnamespace and n.nspname='public'
  join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
  left join pg_attrdef ad on ad.adrelid=c.oid and ad.adnum=a.attnum
  where c.relkind='r' and not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='e')
  group by c.relname
)
select
  '-- QuotesDone — FULL SCHEMA EXPORT (generated from the live database)'||E'\n'
  ||'-- Excludes: secret VALUES (key names listed below), and table ROW DATA (PII).'||E'\n'
  ||'-- Order is best-effort; this is a faithful reference mirror, not a guaranteed one-click restore.'||E'\n\n'
  ||'-- ===== EXTENSIONS =====' ||E'\n'|| coalesce((select string_agg('CREATE EXTENSION IF NOT EXISTS '||quote_ident(extname)||' WITH SCHEMA '||quote_ident(nx.nspname)||';', E'\n' order by extname) from pg_extension e join pg_namespace nx on nx.oid=e.extnamespace),'')
  ||E'\n\n-- ===== SEQUENCES =====\n'|| coalesce((select string_agg('CREATE SEQUENCE IF NOT EXISTS public.'||quote_ident(sequence_name)||';', E'\n' order by sequence_name) from information_schema.sequences where sequence_schema='public'),'')
  ||E'\n\n-- ===== TABLES ('||(select count(*) from t)||') =====\n'|| coalesce((select string_agg(tbl_ddl, E'\n\n' order by rel) from t),'')
  ||E'\n\n-- ===== CONSTRAINTS =====\n'|| coalesce((select string_agg('ALTER TABLE public.'||quote_ident(c.relname)||' ADD CONSTRAINT '||quote_ident(con.conname)||' '||pg_get_constraintdef(con.oid)||';', E'\n' order by case con.contype when 'p' then 1 when 'u' then 2 when 'c' then 3 else 9 end, c.relname, con.conname) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where con.contype in ('p','u','c','f')),'')
  ||E'\n\n-- ===== INDEXES =====\n'|| coalesce((select string_agg(pg_get_indexdef(i.indexrelid)||';', E'\n' order by ic.relname) from pg_index i join pg_class ic on ic.oid=i.indexrelid join pg_namespace n on n.oid=ic.relnamespace and n.nspname='public' where not exists(select 1 from pg_constraint con where con.conindid=i.indexrelid) and not exists(select 1 from pg_depend d where d.objid=ic.oid and d.deptype='e')),'')
  ||E'\n\n-- ===== VIEWS =====\n'|| coalesce((select string_agg('CREATE OR REPLACE VIEW public.'||quote_ident(viewname)||' AS '||definition, E'\n\n' order by viewname) from pg_views where schemaname='public'),'')
  ||E'\n\n-- ===== FUNCTIONS =====\n'|| coalesce((select string_agg(pg_get_functiondef(p.oid), E'\n\n' order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace and n.nspname='public' where p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),'')
  ||E'\n\n-- ===== TRIGGERS =====\n'|| coalesce((select string_agg(pg_get_triggerdef(tg.oid)||';', E'\n' order by c.relname) from pg_trigger tg join pg_class c on c.oid=tg.tgrelid join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where not tg.tgisinternal),'')
  ||E'\n\n-- ===== ROW LEVEL SECURITY (enable) =====\n'|| coalesce((select string_agg('ALTER TABLE public.'||quote_ident(relname)||' ENABLE ROW LEVEL SECURITY;', E'\n' order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where relkind='r' and relrowsecurity),'')
  ||E'\n\n-- ===== POLICIES =====\n'|| coalesce((select string_agg('CREATE POLICY '||quote_ident(policyname)||' ON public.'||quote_ident(tablename)||' AS '||permissive||' FOR '||cmd||' TO '||array_to_string(roles,', ')||coalesce(' USING ('||qual||')','')||coalesce(' WITH CHECK ('||with_check||')','')||';', E'\n' order by tablename,policyname) from pg_policies where schemaname='public'),'')
  ||E'\n\n-- ===== CRON JOBS =====\n'|| coalesce((select string_agg('select cron.schedule('||quote_literal(jobname)||','||quote_literal(schedule)||',$CRON$'||command||'$CRON$);', E'\n' order by jobid) from cron.job),'')
  ||E'\n\n-- ===== APP_SECRETS KEY NAMES (values intentionally excluded) =====\n'|| coalesce((select string_agg('--   '||key, E'\n' order by key) from public.app_secrets),'')
  ||E'\n'
$function$


CREATE OR REPLACE FUNCTION public.fn_screening_normalise(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select nullif(btrim(regexp_replace(
           regexp_replace(
             ' ' || regexp_replace(
               translate(lower(coalesce(p, '')), 'áàâäãåéèêëíìîïóòôöõúùûüçñýÿ', 'aaaaaaeeeeiiiiooooouuuucnyy'),
               '[^[:alnum:][:space:]]+', ' ', 'g') || ' ',
             '\s(llc|l l c|fze|fzc|fzco|fz|ltd|limited|inc|co|company|corp|corporation|est|establishment|trading|general|contracting|contractors|services|group|international|technical|the|of|and|for|in|dmcc|plc|sarl|sal|gmbh|bv|sole|proprietorship)(?=\s)', ' ', 'g'),
           '\s+', ' ', 'g')), '');
$function$


CREATE OR REPLACE FUNCTION public.fn_screening_tokens(p text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(array(
    select distinct t from unnest(string_to_array(coalesce(public.fn_screening_normalise(p), ''), ' ')) t
     where length(t) >= 3
       and t <> all (array['abd','abdul','abdel','bin','ibn','abu','bint','umm','von','van','der','del','della','les','das','dos'])
     order by t), '{}'::text[]);
$function$


CREATE OR REPLACE FUNCTION public.fn_seal_decision_trace(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update decision_trace set sealed_at = now() where id = p_id and sealed_at is null returning true;
$function$


CREATE OR REPLACE FUNCTION public.fn_security_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_old jsonb; v_new jsonb; v_pk text;
begin
  v_old := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end;
  v_new := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end;
  if tg_table_name = 'app_secrets' then
    if v_old ? 'value' then v_old := jsonb_set(v_old, '{value}', '"***REDACTED***"'); end if;
    if v_new ? 'value' then v_new := jsonb_set(v_new, '{value}', '"***REDACTED***"'); end if;
  end if;
  v_pk := coalesce(v_new->>'id', v_old->>'id', v_new->>'key', v_old->>'key',
                   v_new->>'name', v_old->>'name', v_new->>'role', v_old->>'role');
  insert into public.security_audit_log(action, table_name, row_pk, old_data, new_data)
  values (tg_op, tg_table_name, v_pk, v_old, v_new);
  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_security_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception 'security_audit_log is append-only; % is not permitted', tg_op;
end $function$


CREATE OR REPLACE FUNCTION public.fn_security_scan()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_run bigint; v_scanned int := 0; v_susp int := 0; v_high int := 0; v_viol int; v_banned int; v_owner text;
  r record; v_path text; v_sev text; v_why text; v_size bigint; v_mime text;
begin
  insert into agent_runs(agent, started_at) values ('security', now()) returning id into v_run;
  for r in
    select bucket_id, name, coalesce((metadata->>'size')::bigint,0) as size, coalesce(metadata->>'mimetype','') as mime
    from storage.objects
    where bucket_id in ('quote-files','drawing-files','supplier-docs')   -- receipt-files removed: system/owner-generated, not a threat surface
    order by created_at desc limit 400
  loop
    v_path := r.name; if v_path is null or v_path = '' or right(v_path,1) = '/' then continue; end if;
    v_scanned := v_scanned + 1; v_size := r.size; v_mime := r.mime; v_sev := null; v_why := null;
    if v_path ~* '\.[a-z0-9]{2,5}\.(exe|js|scr|bat|html?|svg|hta)$' then v_sev := 'high'; v_why := 'double extension';
    elsif v_path ~* '\.(exe|bat|cmd|com|scr|msi|ps1|vbs|js|jar|sh|apk|dll|hta|wsf|docm|xlsm|pptm|iso|img)$' then v_sev := 'high'; v_why := 'dangerous file type';
    elsif v_path ~* '\.(html?|svg)$' then v_sev := 'high'; v_why := 'active-content file';
    elsif v_size > 30*1024*1024 then v_sev := 'medium'; v_why := 'oversized';
    end if;
    -- dedupe: only flag a file the FIRST time it is seen
    if v_sev is not null and not exists (select 1 from security_events se where se.kind='suspicious_upload' and se.subject=left(v_path,200)) then
      v_susp := v_susp + 1;
      insert into security_events(kind,severity,source,subject,detail) values ('suspicious_upload',v_sev,r.bucket_id,left(v_path,200),jsonb_build_object('mime',v_mime,'size',v_size,'why',v_why));
      if v_sev = 'high' then
        v_high := v_high + 1;
        insert into agent_actions(agent,kind,status,risk,title,recommendation,target_table,detail)
        values ('security','security_alert','pending','high','Suspicious upload ('||v_why||'): '||left(v_path,80),'inspect/remove the file in storage; do NOT open it directly','security_events',jsonb_build_object('bucket',r.bucket_id,'path',v_path,'why',v_why,'size',v_size));
      end if;
    end if;
  end loop;
  select count(*) into v_viol from chat_violations where created_at >= now()-interval '7 days';
  select (select count(*) from leads where banned=true)+(select count(*) from customers where banned=true) into v_banned;
  if v_viol > 0 then insert into security_events(kind,severity,source,subject,detail) values ('contact_disclosure','medium','chat',v_viol||' contact-sharing attempt(s) in 7d',jsonb_build_object('count',v_viol)); end if;
  if v_susp > 0 then
    select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';
    insert into notifications(type,to_email,to_role,channel,subject,body) values ('security_alert',coalesce(v_owner,'management@quotesdone.com'),'admin','email','QuotesDone security: '||v_susp||' suspicious file(s) flagged','The Security agent flagged '||v_susp||' newly uploaded file(s) ('||v_high||' high-severity). Open the Security agent in admin. Do not open flagged files directly.');
  end if;
  update agent_runs set finished_at=now(), status='ok', counts=jsonb_build_object('scanned',v_scanned,'suspicious',v_susp,'high',v_high,'violations7d',v_viol,'banned',v_banned) where id=v_run;
end;$function$


CREATE OR REPLACE FUNCTION public.fn_select_model(p_task_class text, p_dept_key text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select fn_ai_route(p_task_class, p_dept_key, p_confidence, null, false); $function$


CREATE OR REPLACE FUNCTION public.fn_self_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_found int := 0;
begin
  -- Stale knowledge: past its review date
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'stale_knowledge', k.agent_key||' / '||k.topic,
         'Knowledge past its review date',
         'review_due '||k.review_due||', owner '||coalesce(k.owner_agent,'none')||', confidence '||coalesce(k.confidence::text,'unset'),
         'Re-research and revalidate, or mark superseded'
  from agent_knowledge k
  where k.review_due < current_date
    and not exists (select 1 from self_review s where s.review_type='stale_knowledge'
                     and s.subject = k.agent_key||' / '||k.topic and s.status='proposed');
  get diagnostics v_found = row_count;

  -- Departments that cannot act
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'overloaded_dept', d.dept_key,
         'Department has authority but no wired executor',
         (select count(*)::text from org_authority a where a.dept_key=d.dept_key)||' authority rules, 0 executors',
         'Wire an executor or remove the authority rule'
  from org_departments d
  where d.active
    and not exists (select 1 from org_action_executor e where e.department=d.dept_key and e.active)
    and not exists (select 1 from self_review s where s.review_type='overloaded_dept' and s.subject=d.dept_key and s.status='proposed');

  -- Employees with no KPI
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'missed_kpi', a.agent_key,
         'Employee has no measurable KPI',
         'title '||coalesce(a.title,'none')||', department '||a.department,
         'Assign a KPI tied to a company goal, or retire the role'
  from org_agents a
  where a.active
    and not exists (select 1 from employee_kpi k where k.agent_key=a.agent_key and k.active)
    and not exists (select 1 from self_review s where s.review_type='missed_kpi' and s.subject=a.agent_key and s.status='proposed');

  -- Recurring failures: any agent failing more than 3 times in 7 days
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'recurring_failure', r.agent,
         'Agent failing repeatedly',
         count(*)||' failures in 7 days; latest: '||left(coalesce(max(r.note),''),160),
         'Diagnose root cause; this is an automation candidate if the fix is mechanical'
  from agent_runs r
  where r.started_at > now() - interval '7 days' and r.status='error'
  group by r.agent having count(*) > 3
    and not exists (select 1 from self_review s where s.review_type='recurring_failure' and s.subject=r.agent and s.status='proposed');

  -- Categories with supply but no standard knowledge
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'stale_sop', v.catalog_slug,
         'Category has supplier supply but no standard knowledge base',
         v.supplier_supply||' suppliers in pipeline, coverage '||v.coverage,
         'Build the 14-module knowledge base; supplier supply is already there'
  from v_category_coverage v
  where v.coverage <> 'COMPLIANT' and v.supplier_supply >= 100
    and not exists (select 1 from self_review s where s.review_type='stale_sop' and s.subject=v.catalog_slug and s.status='proposed');

  return jsonb_build_object(
    'stale_knowledge', (select count(*) from self_review where review_type='stale_knowledge' and status='proposed'),
    'depts_cannot_act', (select count(*) from self_review where review_type='overloaded_dept' and status='proposed'),
    'employees_no_kpi', (select count(*) from self_review where review_type='missed_kpi' and status='proposed'),
    'recurring_failures', (select count(*) from self_review where review_type='recurring_failure' and status='proposed'),
    'categories_needing_knowledge', (select count(*) from self_review where review_type='stale_sop' and status='proposed'),
    'total_open', (select count(*) from self_review where status='proposed'));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_seniority_rank(p text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case lower(coalesce(p,''))
           when 'executive' then 1 when 'director' then 2
           when 'manager'   then 3 when 'specialist' then 4 else 9 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_should_escalate(ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  reasons text[] := '{}';
  conf_min numeric; fin_review numeric; auto_max numeric; fraud_max numeric;
  legal jsonb; sens jsonb; owner text;
  c_conf numeric := nullif(ctx->>'confidence','')::numeric;
  c_amt  numeric := nullif(ctx->>'amount_aed','')::numeric;
  c_fraud numeric := nullif(ctx->>'fraud_score','')::numeric;
  c_cat  text := lower(coalesce(ctx->>'category',''));
  c_txt  text := lower(coalesce(ctx->>'text',''));
  c_kind text := lower(coalesce(ctx->>'kind',''));
  REPORTING_KINDS constant text[] := array['handoff','incident','report_task'];
  c_money boolean := coalesce((ctx->>'moves_money')::boolean,false);
  trg text;
  c_actor text := nullif(btrim(coalesce(ctx->>'actor', ctx->>'agent_key', '')), '');
  v_route text; v_basis text; v_note text;
  v_mgr text; v_mgr_dept text; v_pick jsonb;
  v_actor_res text;
  v_apex_backup text;   -- D11: the named deputy-apex
begin
  select value::numeric into conf_min   from decision_policy where key='confidence_min';
  select value::numeric into fin_review  from decision_policy where key='financial_review_aed';
  select value::numeric into auto_max    from decision_policy where key='auto_action_max_aed';
  select value::numeric into fraud_max   from decision_policy where key='fraud_score_max';
  select value into legal                from decision_policy where key='legal_triggers';
  select value into sens                 from decision_policy where key='sensitive_categories';
  select value #>> '{}' into owner       from decision_policy where key='review_owner';

  if c_conf is not null and c_conf < conf_min then
     reasons := array_append(reasons, 'confidence '||round(c_conf,2)::text||' < min '||round(conf_min,2)::text); end if;
  if c_amt is not null and c_amt >= fin_review then
     reasons := array_append(reasons, 'amount AED '||c_amt::text||' >= review threshold '||fin_review::text); end if;
  if c_money and (c_amt is null or c_amt > auto_max) then
     reasons := array_append(reasons, 'action moves money beyond autonomous limit'); end if;
  if c_fraud is not null and c_fraud >= fraud_max then
     reasons := array_append(reasons, 'fraud score '||round(c_fraud,2)::text||' >= max '||round(fraud_max,2)::text); end if;
  if c_cat <> '' and sens ? c_cat and (c_conf is null or c_conf < conf_min) then
     reasons := array_append(reasons, 'sensitive category "'||c_cat||'" with low/absent confidence'); end if;
  for trg in select jsonb_array_elements_text(legal) loop
     if c_txt <> '' and position(trg in c_txt) > 0 then
        reasons := array_append(reasons, 'legal trigger: "'||trg||'"'); end if;
  end loop;

  if c_txt <> '' and not (c_kind = any (REPORTING_KINDS)) then
    for trg in
      select m.headline from institutional_memory m
       where m.outcome = 'worse' and coalesce(m.headline,'') <> ''
         and (select count(distinct w) from regexp_split_to_table(lower(m.headline), '[^a-z0-9_]+') w
               where length(w) >= 6 and position(w in c_txt) > 0) >= 3
       order by m.created_at desc limit 2
    loop
      reasons := array_append(reasons,
        'a prior attempt on record ended worse: "'||left(trg, 120)||'"');
    end loop;
  end if;

  -- THE APEX ESCALATES TO THE FOUNDER. Resolved FIRST: the active agent with no manager_key (the CEO)
  -- reports to the founder, not to another agent.
  if c_actor is not null then
    v_actor_res := coalesce(public.fn_org_agent_resolve(c_actor), c_actor);
    perform 1 from org_agents a where a.agent_key = v_actor_res and a.active and a.manager_key is null;
    if found then
      v_route := 'founder'; v_basis := 'apex_to_founder';
      v_note  := 'the company apex ('||v_actor_res||') has no manager; the only party above it is the '
              || 'founder, whose major-issue channel is the single human signal the design allows';
    end if;
  end if;

  -- RESOLVE THE PARTY. The configured review_owner (employee / staffed department / title).
  if v_route is null and owner is not null and btrim(owner) <> '' then
    select a.agent_key into v_route from org_agents a
     where a.active and a.agent_key = owner limit 1;
    if v_route is not null then v_basis := 'employee'; end if;

    if v_route is null then
      select d.dept_key into v_route from org_departments d
       where d.dept_key = owner
         and exists (select 1 from org_agents a where a.department = d.dept_key and a.active)
       limit 1;
      if v_route is not null then v_basis := 'staffed_department'; end if;
    end if;

    if v_route is null then
      select a.agent_key into v_route from org_agents a
       where a.active and a.title ilike '%'||owner||'%'
       order by a.agent_key limit 1;
      if v_route is not null then v_basis := 'employee_by_title'; end if;
    end if;
  end if;

  -- THE REPORTING LINE. The actor's manager (active AND available), else the standing deputy.
  if v_route is null and c_actor is not null then
    select a.manager_key into v_mgr from org_agents a where a.agent_key = c_actor and a.active;
    if v_mgr is not null and v_mgr <> c_actor then
      select a.agent_key into v_route from org_agents a
       where a.agent_key = v_mgr and a.active and a.available
         and (a.unavailable_until is null or a.unavailable_until < current_date);
      if v_route is not null then v_basis := 'reporting_line'; end if;

      if v_route is null then
        select a.department into v_mgr_dept from org_agents a where a.agent_key = v_mgr;
        begin v_pick := public.fn_pick_reviewer(v_mgr_dept);
        exception when others then v_pick := null; end;
        v_route := public.fn_route_party(v_pick->>'reviewer');
        if v_route = c_actor then v_route := null; end if;
        if v_route is not null then
          v_basis := 'reporting_line_delegated';
          v_note  := 'manager '||v_mgr||' is unavailable; '
                  || coalesce(v_pick->>'basis','delegation_rule standing deputy');
        end if;
      end if;
    end if;
  end if;

  -- D11: THE APEX BACKUP. Before the generic executive fallback, a named deputy-apex (the COO) takes
  -- an escalation that did not resolve up the line, so an apex-level item reaches a designated backup
  -- rather than whichever exec member the fallback names. Configured in decision_policy.apex_backup.
  if v_route is null then
    select value #>> '{}' into v_apex_backup from decision_policy where key='apex_backup';
    if v_apex_backup is not null and btrim(v_apex_backup) <> '' then
      select a.agent_key into v_route from org_agents a
       where a.active and a.agent_key = coalesce(public.fn_org_agent_resolve(v_apex_backup), v_apex_backup)
       limit 1;
      if v_route is not null then
        v_basis := 'apex_backup';
        v_note := 'no manager or configured owner resolved; the designated apex backup ('||v_route
               || ') stands in before the generic executive fallback';
      end if;
    end if;
  end if;

  -- The configured owner names nobody and no apex backup resolved. Escalate to the executive
  -- department's own head, recorded as a fallback so the configuration gap stays visible.
  if v_route is null then
    select coalesce(
             (select d.brain_agent from org_departments d where d.dept_key='exec'
               and exists (select 1 from org_agents a where a.agent_key=d.brain_agent and a.active)),
             (select d.lead_agent  from org_departments d where d.dept_key='exec'
               and exists (select 1 from org_agents a where a.agent_key=d.lead_agent and a.active)),
             (select a.agent_key from org_agents a where a.active and a.department='exec'
               order by a.agent_key limit 1))
      into v_route;
    if v_route is not null then
      v_basis := 'fallback_exec';
      v_note := 'configured review_owner "'||coalesce(owner,'(unset)')||'" names no active employee '
             || 'and no staffed department; escalation addressed to '||v_route||' instead';
    end if;
  end if;

  if v_route is null then
    v_route := owner; v_basis := 'unresolved';
    v_note := 'configured review_owner "'||coalesce(owner,'(unset)')||'" resolves to no party in the '
           || 'org model, and no active executive employee was available to take it';
  end if;

  return jsonb_build_object(
    'escalate', array_length(reasons,1) is not null,
    'reasons', to_jsonb(reasons),
    'route_to', v_route,
    'route_basis', v_basis,
    'route_note', v_note,
    'route_owner_configured', owner);
end $function$


CREATE OR REPLACE FUNCTION public.fn_smoke()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_owner text; v jsonb:='[]'::jsonb; v_fail int:=0; v_sig text;
  a int; b int; c int; d int; e int;
begin
  insert into agent_runs(agent,started_at) values('smoke',now()) returning id into v_run;
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';

  select count(*) into a from quotes q where q.status='revealed' and not exists(select 1 from transactions t where t.quote_id=q.id);
  if a>0 then v:=v||jsonb_build_object('check','revealed_quote_without_transaction','count',a); v_fail:=v_fail+1; end if;

  select count(*) into b from transactions where fee_status='paid' and coalesce(reveal_fee,0)<=0;
  if b>0 then v:=v||jsonb_build_object('check','paid_tx_zero_fee','count',b); v_fail:=v_fail+1; end if;

  -- 6 SEP 2026: EMAIL only. This counted the WhatsApp rows that wait on an unapproved Twilio template
  -- (the founder's input, not a broken write path) and paged him "data-integrity check failed" 20 times.
  select count(*) into c from notifications where status='queued' and channel='email' and created_at < now()-interval '2 hours';
  if c>0 then v:=v||jsonb_build_object('check','email_backlog_stuck','count',c); v_fail:=v_fail+1; end if;

  select count(*) into d from supplier_dues where coalesce(amount_due,0)<0 or amount_due is null;
  if d>0 then v:=v||jsonb_build_object('check','bad_due_amount','count',d); v_fail:=v_fail+1; end if;

  select count(*) into e from inquiries i where i.status='revealed' and not exists(select 1 from transactions t where t.inquiry_id=i.id);
  if e>0 then v:=v||jsonb_build_object('check','revealed_inquiry_without_tx','count',e); v_fail:=v_fail+1; end if;

  if v_fail>0 then
    insert into error_events(source,kind,severity,detail) values('smoke','integrity_violation','high',v);
    select coalesce(string_agg(x->>'check', ',' order by x->>'check'),'') into v_sig from jsonb_array_elements(v) x;
    if v_owner is not null and not exists(
         select 1 from notifications where type='smoke_alert'
           and created_at >= now() - interval '24 hours'
           and body like '%[sig:'||v_sig||']%') then
      insert into notifications(type,to_email,to_role,channel,subject,body)
        values('smoke_alert',v_owner,'admin','email','QuotesDone: data-integrity check failed',
          v_fail||' integrity check(s) failed: '||v::text||'. This usually means a recent change broke a write path. Open the IT agent. [sig:'||v_sig||']');
    end if;
  end if;
  update agent_runs set finished_at=now(),status='ok',counts=jsonb_build_object('checks',5,'failures',v_fail,'detail',v) where id=v_run;
  return jsonb_build_object('checks',5,'failures',v_fail,'detail',v);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_strategy_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  with dem as (select category, count(*) rfqs from inquiries where created_at > now()-interval '90 days' and category is not null group by category),
  sup as (select i.category, count(distinct q.supplier_id) sups from quotes q join inquiries i on i.id=q.inquiry_id where q.created_at > now()-interval '90 days' and i.category is not null group by i.category)
  select jsonb_build_object(
    'under_supplied', (select coalesce(jsonb_agg(x order by x.rfqs desc),'[]'::jsonb) from (
        select d.category, d.rfqs, coalesce(s.sups,0) as active_suppliers
        from dem d left join sup s on s.category=d.category
        where coalesce(s.sups,0) < greatest(2, d.rfqs/3) order by d.rfqs desc limit 12) x),
    'coverage', jsonb_build_object(
        'categories_total', (select count(*) from category_specs),
        'with_requirements', (select count(*) from category_specs where supplier_requirements is not null),
        'with_playbook', (select count(distinct category) from qualification_playbooks where status='active'),
        'regulation_category_tags', (select count(distinct c) from regulations r, unnest(coalesce(r.categories,'{}')) c where r.status='active')),
    'funnel', (select coalesce(fn_marketplace_analytics(),'{}'::jsonb))
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_stripe_event_seen(p_event_id text, p_type text, p_status text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.stripe_events (event_id, type, payment_status)
  VALUES (p_event_id, p_type, p_status)
  ON CONFLICT (event_id) DO UPDATE
    SET last_seen_at = now(),
        delivery_count = public.stripe_events.delivery_count + 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_subscription_billing_run(p_dry_run boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_flagged int := 0; v_cfg record; v_admin text;
begin
  select * into v_cfg from public.fn_supplier_subscription();
  v_admin := coalesce((select split_part(value,',',1) from app_secrets where key='admin_emails'),'management@quotesdone.com');

  for r in
    select b.* from v_supplier_billing b
    where b.billing_status in ('due','past_due')
      and coalesce(b.email,'') <> ''
      and not exists (
        select 1 from notifications n
        where n.type='subscription_due' and n.lead_id = b.supplier_id
          and n.created_at > now() - interval '30 days')
  loop
    if not p_dry_run then
      update leads set registration_fee_due = v_cfg.fee, registration_status = 'due' where id = r.supplier_id;
      insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
      values('subscription_due', r.email, 'supplier', r.supplier_id, 'email',
        'Your QuotesDone annual subscription is due',
        'Dear '||coalesce(r.company_name,'there')||E',\n\nYour QuotesDone annual supplier subscription of '||v_cfg.currency||' '||v_cfg.fee||E' is now due.\n\nYou keep paying no commission on the jobs you win — this is the annual subscription only. You can settle it securely on the supplier portal: https://quotesdone.com/suppliers\n\nIf it is not settled, your profile is paused from receiving new customer requests until it is.\n\nThank you for being part of QuotesDone.',
        'queued');
    end if;
    v_flagged := v_flagged + 1;
  end loop;

  if v_flagged > 0 and not p_dry_run then
    insert into notifications(type,to_email,to_role,channel,subject,body,status)
    values('subscription_billing_summary', v_admin,'admin','email','Supplier subscriptions invoiced',
      v_flagged||' supplier(s) were invoiced '||v_cfg.currency||' '||v_cfg.fee||' for their annual subscription. Founding suppliers (first '||
      v_cfg.free_limit||') are exempt and were not billed.','queued');
  end if;

  return json_build_object('billing_starts', v_cfg.start_date, 'fee', v_cfg.fee, 'currency', v_cfg.currency,
    'free_limit', v_cfg.free_limit, 'invoiced', v_flagged, 'dry_run', p_dry_run, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_advisor(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with l as (select * from public.leads where id = p_lead_id),
  s as (select * from public.supplier_score where lead_id = p_lead_id),
  -- The opportunity population a closed gap would unlock. Counted, never assumed.
  live_inq as (
    select count(*) as n from public.inquiries i
    where coalesce(i.status, '') not in ('closed', 'cancelled', 'expired')
  ),
  gaps as (
    select g.* from (
      select 'trade_licence' as key, 'Upload your trade licence' as action,
             'You cannot be matched to any opportunity without a current trade licence.' as why,
             'high' as severity, 'documents' as goes_to, 1 as sort
      from l where l.license_doc_path is null
      union all
      select 'licence_expired', 'Replace your expired trade licence',
             'Your trade licence expired on ' || to_char(l.license_expiry, 'DD Mon YYYY') || '.',
             'high', 'documents', 2
      from l where l.license_doc_path is not null and l.license_expiry is not null
                and l.license_expiry < current_date
      union all
      select 'iso_certificate', 'Upload an ISO certificate',
             'Buyers filter on ISO 9001 and 14001. Adding one opens the projects that require it.',
             'medium', 'documents', 3
      from l where l.iso_doc_path is null
      union all
      select 'iso_expired', 'Renew your ISO certificate',
             'Your ISO certificate expired on ' || to_char(l.iso_expiry, 'DD Mon YYYY') || '.',
             'high', 'documents', 4
      from l where l.iso_doc_path is not null and l.iso_expiry is not null and l.iso_expiry < current_date
      union all
      select 'not_verified', 'Complete verification',
             'Unverified suppliers are excluded from matching entirely.',
             'high', 'profile', 5
      from l where not coalesce(l.verified, false)
      union all
      select 'capability_summary', 'Describe what you actually do',
             'Requests are matched on your capability summary. An empty one matches nothing.',
             'high', 'profile', 6
      from l where l.capability_summary is null or btrim(l.capability_summary) = ''
      union all
      select 'no_products', 'Upload a product catalogue',
             'Your catalogue is what buyers search. Without it you compete on company name alone.',
             'medium', 'products', 7
      from l where not exists (select 1 from public.supplier_product sp where sp.supplier_id = l.id)
      union all
      select 'no_service_area', 'Set the emirates you serve',
             'Opportunities are filtered by location before anything else is considered.',
             'medium', 'profile', 8
      from l where coalesce(array_length(l.service_emirates, 1), 0) = 0
      union all
      select 'slow_response', 'Improve your response time',
             'Your response rate is ' || coalesce((select response_rate from s)::text, '0')
               || '%. Buyers see it, and it is 55% of your reliability score.',
             'medium', 'twin', 9
      from l where coalesce((select response_rate from s), 0) < 60
    ) g
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,

    -- ── §15's LOSS BREAKDOWN — empty, and saying why ────────────────────────────────────────────
    'loss_analysis', jsonb_build_object(
      'quotes_submitted', coalesce((select quotes_submitted from s), 0),
      'quotes_won',       coalesce((select quotes_won from s), 0),
      'rejections',       coalesce((select rejection_count from s), 0),
      'loss_reasons', case
        when coalesce((select quotes_submitted from s), 0) = 0 then '[]'::jsonb
        else jsonb_build_array(
          jsonb_build_object('reason', 'Rejected after quoting', 'count', coalesce((select rejection_count from s), 0),
            'pct', round(100.0 * coalesce((select rejection_count from s), 0)
                         / nullif((select quotes_submitted from s), 0)))
        ) end,
      -- The evidence for an EMPTY breakdown, so nobody mistakes it for a computation that failed.
      'basis', case when coalesce((select quotes_submitted from s), 0) = 0
                    then 'no_completed_opportunities' else 'quotes_submitted' end
    ),

    -- ── §15's RECOMMENDATIONS, and §4's actionable assistant line ───────────────────────────────
    'recommendations', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'key', g.key, 'action', g.action, 'why', g.why,
        'severity', g.severity, 'goes_to', g.goes_to,
        -- Quantified upside, counted from the live population. 0 when there is nothing live, and
        -- the basis says so rather than the number standing alone.
        'impact_rfqs', (select n from live_inq)
      ) order by g.sort), '[]'::jsonb) from gaps g
    ),
    'gap_count', (select count(*) from gaps),
    'impact_basis', jsonb_build_object(
      'live_inquiries', (select n from live_inq),
      'note', 'impact_rfqs counts live inquiries a closed gap would let this supplier compete for'
    ),

    -- The one-line headline §4's command centre shows. Names a concrete gap and its upside, or says
    -- plainly that there is nothing to fix — never a vague "improve your profile".
    -- Three cases, because "can qualify for 0 more opportunities" is TRUE and reads as though
    -- closing the gaps were pointless. When nothing is live the honest statement is that the gaps
    -- block eligibility — the supplier still needs to fix them, they just cannot be told a number
    -- yet. Quoting an upside of 0 would discourage exactly the action the advisor is recommending.
    'headline', (
      select case
        when (select count(*) from gaps) = 0
          then 'Your profile is complete. You are eligible for every opportunity we can match.'
        when (select n from live_inq) = 0
          then 'You have ' || (select count(*) from gaps)::text
               || ' gap(s) blocking you from being matched at all. Start with: '
               || (select g.action from gaps g order by g.sort limit 1)
               || '. There are no live opportunities right now, so there is time to fix them.'
        else 'Your profile can qualify for ' || (select n from live_inq)::text
             || ' more opportunities if you close ' || (select count(*) from gaps)::text
             || ' gap(s), starting with: ' || (select g.action from gaps g order by g.sort limit 1) || '.'
      end
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_apply_change(p_phone text, p_field text, p_value text, p_inbound text, p_quote_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'whatsapp'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_lead bigint; v_num numeric; v_q record; v_n int; v_refusal text; v_old numeric; v_list text;
        v_company text;
begin
  -- SCOPE FIRST, AND FROM THE PHONE. Nothing downstream takes a supplier id from the caller.
  v_lead := public.fn_wa_lead_id(p_phone);
  if v_lead is null then
    insert into public.channel_directive(actor_type, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, 'no supplier account matches this number');
    return jsonb_build_object('ok', false, 'refusal',
      'This number is not linked to a supplier account, so there is nothing of yours I can change. Sign in at https://quotesdone.com/suppliers.');
  end if;
  select company_name into v_company from public.leads where id = v_lead;

  if not exists (select 1 from public.fn_supplier_changeable() c where c.field = p_field) then
    v_refusal := 'I cannot change "' || coalesce(p_field,'(nothing)') || '" from a message. What I can change this way: '
              || (select string_agg(c.field, ', ' order by c.field) from public.fn_supplier_changeable() c)
              || '. Everything else — your licence, your company details, and generating a new quotation — is in the portal.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  begin v_num := p_value::numeric; exception when others then v_num := null; end;
  if v_num is null or v_num <= 0 then
    v_refusal := '"' || coalesce(p_value,'') || '" is not an amount I can put on a quotation.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  -- WHICH QUOTATION. Editable means: theirs, still open, nobody has paid to reveal them, not
  -- committed, not already accepted. Each of those is a different reason and each gets said.
  select count(*) into v_n
    from public.quotes q
    join public.inquiries i on i.id = q.inquiry_id
   where q.supplier_id = v_lead
     and (p_quote_id is null or q.id = p_quote_id)
     and q.committed_at is null
     and coalesce(q.status,'') not in ('accepted','withdrawn','expired')
     and coalesce(i.status,'') not in ('concluded','closed','cancelled','awarded')
     and not exists (select 1 from public.transactions t
                      where t.inquiry_id = q.inquiry_id and t.supplier_id = q.supplier_id
                        and t.revealed_at is not null);

  if v_n = 0 then
    -- Say WHY there is nothing to change rather than "no quotation found", which is true of a
    -- supplier who has never quoted and of one whose customer paid an hour ago.
    select string_agg(distinct r, '; ') into v_refusal from (
      select case
               when q.committed_at is not null then 'one is committed and cannot be re-priced'
               when coalesce(q.status,'') = 'accepted' then 'one has already been accepted'
               when exists (select 1 from public.transactions t where t.inquiry_id = q.inquiry_id
                             and t.supplier_id = q.supplier_id and t.revealed_at is not null)
                 then 'the customer has already paid to reveal you on one, so the price they paid to see stands'
               else 'the request is closed on one' end as r
        from public.quotes q where q.supplier_id = v_lead
         and (p_quote_id is null or q.id = p_quote_id)) z;
    v_refusal := coalesce('I cannot change a price right now: ' || v_refusal || '.',
                          'You have no open quotation for me to re-price. You can send a new one from the portal.');
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  if v_n > 1 then
    select string_agg(i.category || ' in ' || coalesce(i.emirate,'the UAE') || ' (currently AED ' || q.quote_amount || ')', '; ' order by q.created_at desc)
      into v_list
      from public.quotes q join public.inquiries i on i.id = q.inquiry_id
     where q.supplier_id = v_lead and q.committed_at is null
       and coalesce(q.status,'') not in ('accepted','withdrawn','expired');
    v_refusal := 'You have ' || v_n || ' open quotations, so I will not guess which one you mean: ' || v_list
              || '. Tell me which, or change it in the portal.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'open_quotes', v_n);
  end if;

  select q.* into v_q
    from public.quotes q join public.inquiries i on i.id = q.inquiry_id
   where q.supplier_id = v_lead
     and (p_quote_id is null or q.id = p_quote_id)
     and q.committed_at is null
     and coalesce(q.status,'') not in ('accepted','withdrawn','expired')
     and coalesce(i.status,'') not in ('concluded','closed','cancelled','awarded')
     and not exists (select 1 from public.transactions t
                      where t.inquiry_id = q.inquiry_id and t.supplier_id = q.supplier_id
                        and t.revealed_at is not null);
  v_old := v_q.quote_amount;

  -- THE FAT-FINGER BOUND. A supplier may price their own work at whatever they like — that is
  -- their commercial decision and not ours. But this arrives as a sentence typed on a phone, where
  -- a missing or extra zero is one keystroke, and a quotation is a number a customer will compare
  -- against others and pay to unlock. Beyond half up or half down, the portal asks for it twice.
  if v_old is not null and v_old > 0 and (v_num > v_old * 1.5 or v_num < v_old * 0.5) then
    v_refusal := 'That would move the price from AED ' || v_old || ' to AED ' || v_num
              || ', which is more than half up or down. I have not changed it — if you do mean that, please set it in the portal so you can see the whole quotation while you do.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'old', v_old, 'asked', v_num);
  end if;

  if v_old is not distinct from v_num then
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, false, 'already at that value');
    return jsonb_build_object('ok', true, 'unchanged', true, 'old', v_old, 'new', v_num,
      'message', 'Your quotation is already AED ' || v_num || '. Nothing to change.');
  end if;

  update public.quotes set quote_amount = v_num where id = v_q.id;

  insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied)
  values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, true);

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('supplier_directive', 'ok',
          jsonb_build_object('lead_id', v_lead, 'quote_id', v_q.id, 'old', v_old, 'new', v_num, 'channel', p_channel),
          coalesce(v_company,'lead ' || v_lead) || ' changed a quotation from AED ' || coalesce(v_old::text,'(unset)')
          || ' to AED ' || v_num || ' by ' || p_channel || '. Instruction: ' || left(coalesce(p_inbound,''),200),
          now(), now());

  return jsonb_build_object('ok', true, 'quote_id', v_q.id, 'old', v_old, 'new', v_num,
    'message', 'Done — your quotation is now AED ' || v_num || ' (it was AED ' || coalesce(v_old::text,'unset') || '). The customer sees the new price from now on.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_certifications(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  docs as (
    select * from (values
      ('trade_licence',      'Trade licence',              'critical', 'Approval is impossible without it — the licence gate refuses every profile that has none.'),
      ('insurance',          'Insurance',                  'high',     'Many customers will not award work to an uninsured supplier.'),
      ('vat',                'VAT certificate',            'high',     'Needed before you can invoice with VAT.'),
      ('iso',               'ISO certification',           'medium',   'Strengthens your capability score and unlocks quality-gated requests.'),
      ('manufacturer_auth', 'Manufacturer authorisation',  'medium',   'Proves you are authorised for the brands you carry.'),
      ('establishment',     'Establishment card',          'low',      'Administrative record. Does not gate work.'),
      ('bank_iban',         'Bank details (IBAN)',         'medium',   'We cannot pay you without it.')
    ) d(key, label, impact, impact_why)
  ),
  held as (
    select d.key, d.label, d.impact, d.impact_why,
      case d.key
        when 'trade_licence'      then (select license_doc_path from me)
        when 'insurance'          then (select insurance_doc_path from me)
        when 'vat'                then (select vat_doc_path from me)
        when 'iso'                then (select iso_doc_path from me)
        when 'manufacturer_auth'  then (select manufacturer_auth_doc_path from me)
        when 'establishment'      then (select egr_doc_path from me)
        when 'bank_iban'          then (select iban_doc_path from me)
      end as path,
      case d.key
        when 'trade_licence'     then (select license_expiry from me)
        when 'insurance'         then (select insurance_expiry from me)
        when 'iso'               then (select iso_expiry from me)
        when 'manufacturer_auth' then (select manufacturer_auth_expiry from me)
        else null
      end::date as expiry
    from docs d
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'certifications', coalesce((select jsonb_agg(jsonb_build_object(
        'key', h.key, 'label', h.label,
        'held', h.path is not null,
        'expiry', h.expiry,
        'days_left', case when h.expiry is null then null else (h.expiry - current_date) end,
        -- THE FIELD §16 ASKS FOR. A document with no expiry column is 'valid' when held: it does
        -- not expire, so calling it 'unknown' would invent a problem the supplier cannot fix.
        'document_status', case
          when h.path is null then 'missing'
          when h.expiry is null then 'valid'
          when h.expiry < current_date then 'expired'
          when h.expiry < current_date + 60 then 'expiring'
          else 'valid' end,
        'impact_level', h.impact,
        'impact_why', h.impact_why)
      order by case h.impact when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end, h.label)
      from held h), '[]'::jsonb),
    'impact_basis', 'impact_level is a stated QuotesDone policy about what each document gates — not a number derived from your history',
    'summary', jsonb_build_object(
      'held', (select count(*) from held where path is not null),
      'total', (select count(*) from held),
      'expired', (select count(*) from held where path is not null and expiry is not null and expiry < current_date),
      'expiring', (select count(*) from held where path is not null and expiry is not null
                     and expiry >= current_date and expiry < current_date + 60),
      -- The one number that decides whether they can trade at all, surfaced on its own.
      'blocking_missing', (select count(*) from held where path is null and impact = 'critical'))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_changeable()
 RETURNS TABLE(field text, kind text, description text)
 LANGUAGE sql
 STABLE
AS $function$
  select 'quote_price', 'number',
         'The amount on your open quotation. It can be changed while the customer has not paid to reveal you, the quotation is not committed, and the request is still open.';
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_document_impact(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  flag as (select coalesce((select source from me), '') = 'qd_demo_fixture' as is_demo),

  -- Open enquiries this supplier's trade could serve. This is the population a missing document
  -- is measured against, so it is scoped to their sector and to briefs that are still open.
  reachable as (
    select count(*) n from public.inquiries i, me, flag
    where i.status = 'open'
      and me.sector is not null and i.category = me.sector
      and (coalesce(i.brief_source, '') = 'qd_demo_fixture') = flag.is_demo
  ),
  -- Their own priced history.
  priced as (
    select count(distinct q.inquiry_id) n from public.quotes q, flag
    where q.supplier_id = p_lead_id
      and (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
  ),

  docs as (
    select d.* from (
      select 'trade_licence' as key, 'Trade licence' as label,
             (select license_doc_path from me) as path,
             (select license_expiry from me) as expiry,
             true as gates_matching
      union all
      select 'iso', 'ISO certification',
             (select iso_doc_path from me), (select iso_expiry from me), false
      union all
      select 'insurance', 'Insurance',
             (select insurance_doc_path from me), (select insurance_expiry from me), false
      union all
      select 'manufacturer_auth', 'Manufacturer authorisation',
             (select manufacturer_auth_doc_path from me), (select manufacturer_auth_expiry from me), false
      union all
      select 'company_profile', 'Company profile',
             (select company_profile_doc_path from me), null::date, false
    ) d
  ),
  scored as (
    select d.key, d.label, d.gates_matching,
           d.path is not null as on_file,
           d.expiry,
           coalesce(d.expiry < current_date, false) as expired,
           (d.path is not null and not coalesce(d.expiry < current_date, false)) as effective
    from docs d
  )

  select jsonb_build_object(
    'lead_id', p_lead_id,
    'open_in_my_trade', (select n from reachable),
    'basis', 'open enquiries in your trade, and the enquiries you have already priced',
    'documents', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'key', s.key,
        'label', s.label,
        'on_file', s.on_file,
        'expiry', s.expiry,
        'expired', s.expired,
        -- What it has already earned. Only attributable while the document is genuinely in force.
        'unlocked', case when s.effective then (select n from priced) else 0 end,
        -- What its absence is costing. Only the licence blocks matching outright, so only the
        -- licence can claim the whole open population; the others are supporting evidence and
        -- claim nothing they cannot demonstrate.
        'would_unlock', case
          when s.effective then 0
          when s.gates_matching then (select n from reachable)
          else 0 end,
        'note', case
          when s.effective then 'On file and in force.'
          when s.expired and s.gates_matching then 'Expired. Renewing it reopens every open enquiry in your trade.'
          when s.expired then 'Expired. Customers see this as a gap when comparing you.'
          when s.gates_matching then 'Missing. It is the document that decides whether you can be matched at all.'
          else 'Missing. It is optional, but it is what a customer looks for when comparing two similar quotes.'
          end
      ) order by s.gates_matching desc, s.key), '[]'::jsonb)
      from scored s)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_exception_close(p_lead_id bigint, p_outcome text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.leads
     set exception_closed_at = now(),
         exception_outcome = p_outcome,
         licence_gate_reason = case when p_outcome = 'resolved' then null else licence_gate_reason end
   where id = p_lead_id and exception_closed_at is null;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_exception_days()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select greatest(1, coalesce((select nullif(btrim(value),'')::int from app_secrets where key='supplier_exception_days'), 14));
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_exception_open(p_lead_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_days int := public.fn_supplier_exception_days(); r public.leads;
begin
  select * into r from public.leads where id = p_lead_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'lead_not_found'); end if;

  if r.exception_opened_at is not null and r.exception_closed_at is null then
    return jsonb_build_object('ok', true, 'reopened', false, 'due_at', r.exception_due_at,
                              'note', 'already open - the clock does not restart on a repeat failure');
  end if;

  update public.leads
     set exception_opened_at = now(),
         exception_due_at = now() + make_interval(days => v_days),
         exception_reminders = 0, exception_last_reminder_at = null,
         exception_closed_at = null, exception_outcome = null,
         licence_gate_reason = coalesce(p_reason, licence_gate_reason)
   where id = p_lead_id;

  return jsonb_build_object('ok', true, 'reopened', true,
                            'due_at', now() + make_interval(days => v_days), 'days', v_days);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_expiries(p_supplier_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with l as (select * from leads where id=p_supplier_id)
  select coalesce(jsonb_agg(e order by (e->>'days_left')::int), '[]'::jsonb) from (
    select jsonb_build_object('doc',d.label,'expiry',d.exp,
      'days_left',(d.exp - current_date),
      'status', case when d.exp < current_date then 'expired'
                     when d.exp <= current_date + 30 then 'expiring'
                     when d.exp <= current_date + 90 then 'soon' else 'ok' end) e
    from l, lateral (values
      ('Trade license', l.license_expiry),
      ('ISO certification', l.iso_expiry),
      ('Insurance', l.insurance_expiry),
      ('Manufacturer authorization', l.manufacturer_auth_expiry)
    ) as d(label,exp)
    where d.exp is not null
  ) q;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_knowledge_graph(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with mine as (
    select lc.slug, lc.is_primary, lc.score
    from lead_category lc where lc.lead_id = p_lead_id
  ),
  -- Adjacency is stored once per unordered pair, so both directions are recovered here; reading
  -- only src_ref would silently hide half of every supplier's neighbourhood.
  neigh as (
    select case when e.src_ref = m.slug then e.dst_ref else e.src_ref end as slug,
           (e.props->>'companies')::int as companies
    from graph_edges e join mine m on m.slug in (e.src_ref, e.dst_ref)
    where e.rel = 'adjacent_to' and e.src_kind = 'category'
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'basis', 'categories this company is listed in, and the categories its competitors also serve',
    'my_categories', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'slug', m.slug,
        'label', (select n.label from graph_nodes n where n.kind='category' and n.ref_id=m.slug),
        'companies', (select (n.props->>'companies')::int from graph_nodes n where n.kind='category' and n.ref_id=m.slug),
        'primary', m.is_primary) order by m.is_primary desc nulls last, m.slug), '[]'::jsonb)
      from mine m),
    -- Excludes the supplier's own categories: telling them they are adjacent to themselves is noise.
    'adjacent', (
      select coalesce(jsonb_agg(x order by x->'shared_companies' desc), '[]'::jsonb) from (
        select jsonb_build_object(
          'slug', nb.slug,
          'label', (select n.label from graph_nodes n where n.kind='category' and n.ref_id=nb.slug),
          'shared_companies', max(nb.companies),
          'companies', (select (n.props->>'companies')::int from graph_nodes n where n.kind='category' and n.ref_id=nb.slug)
        ) x
        from neigh nb
        where nb.slug not in (select slug from mine)
        group by nb.slug
        order by max(nb.companies) desc
        limit 12) s),
    'population', jsonb_build_object(
      'category_nodes', (select count(*) from graph_nodes where kind='category'),
      'adjacency_edges', (select count(*) from graph_edges where rel='adjacent_to' and src_kind='category'),
      'listed_companies', (select count(distinct lead_id) from lead_category))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_mandatory_check(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l record; miss text[] := '{}'; have text[] := '{}';
begin
  select * into l from public.leads where id = p_lead_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'No such lead.');
  end if;

  if coalesce(btrim(l.company_name),'') = '' then miss := array_append(miss,'Company name');
  else have := array_append(have,'Company name'); end if;

  -- A UAE mobile is +9715x. A Dubai landline is +9714 and does not satisfy this, which is the exact
  -- case that put a landline on the company's only "approved" supplier.
  if coalesce(regexp_replace(coalesce(l.phone_e164, l.phone, ''), '[^0-9]', '', 'g'), '') !~ '^9715[0-9]{8}$'
  then miss := array_append(miss,'UAE mobile number');
  else have := array_append(have,'UAE mobile number'); end if;

  if coalesce(btrim(l.email),'') = '' then miss := array_append(miss,'Email address');
  elsif coalesce(l.email_verified,'') not in ('verified','true') then miss := array_append(miss,'Email address (not yet verified)');
  else have := array_append(have,'Email address'); end if;

  if coalesce(btrim(l.license_doc_path),'') = '' then miss := array_append(miss,'Trade licence');
  else have := array_append(have,'Trade licence'); end if;

  if coalesce(btrim(l.company_profile_doc_path),'') = '' then miss := array_append(miss,'Company profile');
  else have := array_append(have,'Company profile'); end if;

  if coalesce(btrim(l.signed_terms_path),'') = '' then miss := array_append(miss,'Signed terms and conditions');
  else have := array_append(have,'Signed terms and conditions'); end if;

  return jsonb_build_object(
    'ok', true, 'party_kind','supplier', 'id', p_lead_id, 'name', l.company_name,
    'complete', coalesce(array_length(miss,1),0) = 0,
    'have', to_jsonb(have), 'missing', to_jsonb(miss),
    'missing_count', coalesce(array_length(miss,1),0),
    'mandatory_total', 6
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_market(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  flag as (select coalesce((select source from me), '') = 'qd_demo_fixture' as is_demo),

  -- Competitors: same sector, overlapping service area, not this supplier, same side of the fence.
  peers as (
    select l.*
    from public.leads l, me, flag
    where l.id <> me.id
      and l.sector is not null
      and me.sector is not null
      and l.sector = me.sector
      and coalesce(l.permanently_closed, false) = false
      and (coalesce(l.source, '') = 'qd_demo_fixture') = flag.is_demo
  ),
  peers_here as (
    select p.* from peers p, me
    where me.service_emirates is null
       or coalesce(array_length(me.service_emirates, 1), 0) = 0
       or p.emirate is null
       or exists (select 1 from unnest(me.service_emirates) e where p.emirate ilike '%' || e || '%')
  ),

  -- ── THE DEMAND POPULATIONS ────────────────────────────────────────────────────────────────────
  -- Every enquiry on this side of the fence, and the subset in this supplier's own category.
  -- The window is 28 days split into two 14-day halves; `cur` is the half that just ended.
  demand_all as (
    select i.* from public.inquiries i, flag
    where (coalesce(i.brief_source, '') = 'qd_demo_fixture') = flag.is_demo
      and i.created_at >= now() - interval '28 days'
  ),
  demand_mine as (
    select d.* from demand_all d, me where me.sector is not null and d.category = me.sector
  ),
  -- Quotes are priced against enquiries, so the price population is the quotes ON those enquiries.
  priced as (
    select q.quote_amount amt
    from public.quotes q join demand_mine d on d.id = q.inquiry_id, flag
    where (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
      and q.quote_amount is not null and q.quote_amount > 0
  ),

  -- ── THE THREE FIGURES, EACH BUILT ONCE ────────────────────────────────────────────────────────
  -- Built in a CTE and referenced by key below, rather than inline, so each figure's empty branch
  -- sits with the computation it belongs to instead of beside the key it answers for.
  figures as (
    select
      -- Trend. Direction is a comparison of two counted halves; pct is only produced when there is
      -- a prior period to divide by.
      (with c as (
         select count(*) filter (where created_at >= now() - interval '14 days') as recent,
                count(*) filter (where created_at <  now() - interval '14 days') as earlier
         from demand_mine)
       select case when c.recent = 0 and c.earlier = 0
         then jsonb_build_object(
                'available', false, 'value', null, 'direction', null,
                'basis', 'enquiries in your category over the last 28 days',
                'population', 0,
                'note', 'no enquiries in your category yet, so there is no series to trend')
         else jsonb_build_object(
                'available', true,
                'category', (select sector from me),
                'value', c.recent,
                'prior', c.earlier,
                'direction', case when c.recent > c.earlier then 'up'
                                  when c.recent < c.earlier then 'down' else 'flat' end,
                'pct', case when c.earlier > 0
                            then round(((c.recent - c.earlier)::numeric / c.earlier) * 100, 1)
                            else null end,
                'from_zero', c.earlier = 0,
                'share_pct', case when (select count(*) from demand_all) > 0
                             then round((c.recent::numeric
                                  / nullif((select count(*) from demand_all), 0)) * 100, 1)
                             else null end,
                'series', (
                  select coalesce(jsonb_agg(jsonb_build_object('week', w.wk, 'count', w.c) order by w.wk), '[]'::jsonb)
                  from (select date_trunc('week', created_at)::date wk, count(*) c
                        from demand_mine group by 1) w),
                'basis', 'enquiries in your category, two 14-day halves',
                'population', (select count(*) from demand_mine),
                'note', case when c.earlier = 0
                        then 'first activity in this window, so there is no prior period to take a percentage against'
                        else null end)
         end from c) as trend_obj,

      -- The single most-asked-for category across the whole population, with its count.
      (with r as (select category cat, count(*) c from demand_all
                  where category is not null group by 1 order by count(*) desc limit 1)
       select case when not exists (select 1 from r)
         then jsonb_build_object(
                'available', false, 'value', null,
                'basis', 'enquiries over the last 28 days',
                'population', (select count(*) from demand_all),
                'note', 'that is a fact about requests, and none have been made')
         else jsonb_build_object(
                'available', true,
                'value', (select cat from r),
                'count', (select c from r),
                'basis', 'enquiries over the last 28 days, grouped by category',
                'population', (select count(*) from demand_all))
         end) as topcat_obj,

      -- What the market is actually charging. The median matters more than the mean to a supplier
      -- deciding where to sit, and the quartiles are what "you are high/low" is measured against,
      -- so all of them are returned rather than one number with no spread around it.
      (with s as (
         select count(*) n, round(avg(amt)) mean,
                round(percentile_cont(0.5)  within group (order by amt)) mid,
                round(percentile_cont(0.25) within group (order by amt)) lo,
                round(percentile_cont(0.75) within group (order by amt)) hi,
                min(amt) lowest, max(amt) highest
         from priced)
       select case when s.n = 0
         then jsonb_build_object(
                'available', false, 'value', null, 'currency', 'AED',
                'basis', 'quotes on enquiries in your category',
                'population', 0,
                'note', 'nothing in your category has been priced, so there is no market price')
         else jsonb_build_object(
                'available', true, 'currency', 'AED',
                'value', s.mean, 'median', s.mid, 'p25', s.lo, 'p75', s.hi,
                'low', s.lowest, 'high', s.highest,
                'basis', 'quotes on enquiries in your category over the last 28 days',
                'population', s.n)
         end from s) as money_obj
  )

  select jsonb_build_object(
    'lead_id', p_lead_id,
    'sector', (select sector from me),
    'population', case when (select is_demo from flag) then 'demo' else 'live' end,

    -- ── The competitive picture, real since the first scrape ─────────────────────────────────────
    'competitors', jsonb_build_object(
      'available', true,
      'basis', 'leads in the same sector',
      'total', (select count(*) from peers),
      'in_my_area', (select count(*) from peers_here),
      -- The number a scraped list hides: how many competitors can receive an RFQ at all.
      --
      -- COUNTED ON THE GATE THAT DECIDES, 13 Aug 2026. This asked fn_is_matchable — verified,
      -- banned, blocked, approval, closed, strikes — and called the answer "able to receive an RFQ".
      -- The path that builds an RFQ shortlist is fn_match_capability, whose candidate CTE ALSO
      -- requires supplier_capabilities.confirmed_at. 15,306 suppliers hold capability data and 1 has
      -- confirmed, so a peer could pass every clause counted here and still be unreachable. Both
      -- legs now, because the label names the RFQ.
      'matchable', (
        select count(*) from peers p
        where public.fn_is_matchable(p.verified, p.banned, p.matching_blocked,
                                     p.approval_status, p.permanently_closed, p.chat_strikes)
          and exists (select 1 from public.supplier_capabilities sc
                      where sc.supplier_id = p.id and sc.confirmed_at is not null)
      ),
      -- AND WHETHER THE READER IS ONE OF THEM. `peers` excludes self (l.id <> me.id), so every
      -- figure in this block is a fact about OTHER companies — yet the panel rendered a constant
      -- note reading "None of them is verified, so none can currently be matched to work —
      -- INCLUDING YOU" whenever matchable was 0. On 13 Aug that sentence was shown to MERIDIAN MEP:
      -- the one supplier in the estate that IS reachable, and the only one that had done the work.
      -- A claim about the reader has to be computed about the reader.
      'me_matchable', (
        select public.fn_is_matchable(m.verified, m.banned, m.matching_blocked,
                                      m.approval_status, m.permanently_closed, m.chat_strikes)
           and exists (select 1 from public.supplier_capabilities sc
                       where sc.supplier_id = m.id and sc.confirmed_at is not null)
        from public.leads m where m.id = p_lead_id
      ),
      -- Group FIRST, build the json after. `group by 1` over a jsonb_build_object containing
      -- count(*) raises 42803: the grouping key would be an expression containing an aggregate.
      'by_emirate', (
        select coalesce(jsonb_agg(jsonb_build_object('emirate', s.em, 'count', s.c) order by s.c desc), '[]'::jsonb)
        from (
          select p.emirate as em, count(*) as c
          from peers p where p.emirate is not null
          group by p.emirate order by count(*) desc limit 8
        ) s
      )
    ),

    'market_composition', jsonb_build_object(
      'available', true,
      'basis', 'leads in the same sector, grouped by category',
      'segments', (
        select coalesce(jsonb_agg(jsonb_build_object('name', s.nm, 'count', s.c) order by s.c desc), '[]'::jsonb)
        from (
          select coalesce(nullif(btrim(split_part(p.categories, ',', 1)), ''), 'Uncategorised') as nm,
                 count(*) as c
          from peers p group by 1 order by count(*) desc limit 8
        ) s
      )
    ),

    -- ── The demand half. Computed when there is a population, refused when there is not ──────────
    'demand_trend',     (select trend_obj  from figures),
    'most_requested',   (select topcat_obj from figures),
    'avg_market_price', (select money_obj  from figures)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_negotiation(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with q as (
    select id, inquiry_id, supplier_id, quote_amount, margin_rate, app_fee, customer_price, lead_time, warranty
      from public.quotes where id = p_quote_id
  ),
  -- The inbound side of the conversation only. What the supplier said is not evidence of pressure.
  inbound as (
    select m.id, m.body, m.created_at
      from public.messages m join q on q.inquiry_id = m.inquiry_id and q.supplier_id = m.supplier_id
     where m.sender = 'customer' order by m.created_at desc limit 10
  ),
  scen as (
    select v.pct,
           round((select quote_amount from q) * (1 - v.pct / 100.0), 2) new_quote,
           round((select quote_amount from q) * (1 - v.pct / 100.0)
                 * (1 + coalesce((select margin_rate from q), 0)), 2) new_customer_price,
           round((select quote_amount from q) * (v.pct / 100.0), 2) you_give_up
      from (values (3), (5), (10)) v(pct)
  )
  select jsonb_build_object(
    'quote_id', p_quote_id,
    -- The thread this quote belongs to. Returned because the drafted reply has to be SENDABLE, and
    -- messages_api keys a thread on (inquiry_id, supplier_id) — without both, the draft is a
    -- suggestion the supplier has to retype somewhere else.
    'inquiry_id', (select inquiry_id from q),
    'supplier_id', (select supplier_id from q),
    'quote_amount', (select quote_amount from q),
    'customer_price', (select customer_price from q),
    -- THE PLATFORM'S margin, named as such. app_fee / quote_amount is QuotesDone's cut, and calling
    -- it "your margin" would be a lie by label.
    'margin', jsonb_build_object(
      'whose', 'platform',
      'app_fee', (select app_fee from q),
      'margin_rate', (select margin_rate from q),
      'note', 'This is the QuotesDone fee on the reveal, not your profit.'),
    'supplier_cost_known', false,
    'possible_reduction', jsonb_build_object(
      'available', false,
      'why', 'QuotesDone does not know what this job costs you to deliver, so it cannot tell you how far you can go. The scenarios below are arithmetic, not advice.',
      'scenarios', coalesce((select jsonb_agg(jsonb_build_object(
          'reduction_pct', s.pct, 'you_receive', s.new_quote,
          'customer_pays', s.new_customer_price, 'you_give_up', s.you_give_up)
        order by s.pct) from scen s), '[]'::jsonb)),
    'inbound_messages', coalesce((select jsonb_agg(jsonb_build_object(
        'id', i.id, 'body', i.body, 'created_at', i.created_at) order by i.created_at desc)
      from inbound i), '[]'::jsonb),
    'population', jsonb_build_object(
      'customer_messages', (select count(*) from inbound),
      'note', case when (select count(*) from inbound) = 0
                   then 'the customer has not written anything yet, so there is no discount request to read'
                   else null end),
    'terms', jsonb_build_object('lead_time', (select lead_time from q), 'warranty', (select warranty from q))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_network_map()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with centroid(emirate, lat, lng) as (
    values ('Dubai', 25.2048, 55.2708),
           ('Abu Dhabi', 24.4539, 54.3773),
           ('Sharjah', 25.3463, 55.4209),
           ('Ajman', 25.4052, 55.5136),
           ('Ras Al Khaimah', 25.7895, 55.9432),
           ('Umm Al Quwain', 25.5647, 55.5552),
           ('Fujairah', 25.1288, 56.3265)
  ),
  -- Emirate names arrive in several spellings across 20,464 scraped rows, so they are normalised
  -- to the centroid table's keys. A row that matches nothing is counted as unplaced rather than
  -- dropped: silently discarding rows would make the map look tidier than the data is.
  norm as (
    select case
             when l.emirate ilike '%dubai%'      then 'Dubai'
             when l.emirate ilike '%abu%dhabi%'  then 'Abu Dhabi'
             when l.emirate ilike '%sharjah%'    then 'Sharjah'
             when l.emirate ilike '%ajman%'      then 'Ajman'
             when l.emirate ilike '%ras%khaim%'  then 'Ras Al Khaimah'
             when l.emirate ilike '%umm%quwain%' then 'Umm Al Quwain'
             when l.emirate ilike '%fujairah%'   then 'Fujairah'
             else null end as emirate,
           l.id, l.verified, l.matching_blocked
    from public.leads l
  )
  select jsonb_build_object(
    'generated_for', 'row5-section-19',

    -- ── LAYER 1: SUPPLIERS. Real, and the only populated one. ──────────────────────────────────
    'suppliers', jsonb_build_object(
      'basis', 'leads.emirate',
      'count', (select count(*) from norm where emirate is not null),
      'unplaced', (select count(*) from norm where emirate is null),
      'markers', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'name', c.emirate, 'lat', c.lat, 'lng', c.lng,
          'count', (select count(*) from norm n where n.emirate = c.emirate),
          -- Kept separate because they are different claims: how many companies we KNOW OF versus
          -- how many can actually receive an RFQ. On production the second is 0 and the map must
          -- not let the first stand in for it.
          'matchable', (select count(*) from norm n where n.emirate = c.emirate
                          and coalesce(n.verified, false) and not coalesce(n.matching_blocked, false))
        ) order by c.emirate), '[]'::jsonb)
        from centroid c
      )
    ),

    -- ── LAYERS 2-4: EMPTY, each saying so in its own words ─────────────────────────────────────
    'demand', jsonb_build_object(
      'basis', 'inquiries',
      'count', (select count(*) from public.inquiries),
      'markers', '[]'::jsonb,
      'note', 'no inquiries exist yet, so no demand is plotted'
    ),
    'projects', jsonb_build_object(
      'basis', 'inquiries with a project',
      'count', (select count(*) from public.inquiries),
      'markers', '[]'::jsonb,
      'note', 'no projects exist yet'
    ),
    'shipments', jsonb_build_object(
      'basis', 'none',
      'count', 0,
      'markers', '[]'::jsonb,
      'note', 'there is no shipments relation in this schema; nothing is tracked to plot'
    ),

    'totals', jsonb_build_object(
      'leads', (select count(*) from public.leads),
      'placed', (select count(*) from norm where emirate is not null),
      'matchable', (select count(*) from norm
                    where coalesce(verified, false) and not coalesce(matching_blocked, false))
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_opportunities(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (
    select l.id, lower(coalesce(l.sector, '')) sector, l.emirate,
           coalesce(l.service_emirates, '{}'::text[]) service_emirates,
           lower(coalesce(l.capability_summary, l.services, l.description, '')) capability,
           l.verified
      from public.leads l where l.id = p_lead_id
  ),
  -- Only inquiries this supplier could actually work: open, and not their own demo fence.
  cand as (
    select i.id, i.category, i.emirate, i.summary, i.scope_type, i.created_at, i.budget,
           -- WHAT THE CUSTOMER ACTUALLY NEEDS, which is not the project's title. raw_input is what
           -- they typed, in their words. `spec` is jsonb — the structured brief intake derived —
           -- and pouring that through ::text would put raw JSON in front of a supplier, so it is
           -- deliberately not a fallback. No brief typed means NULL, and the surface says so.
           nullif(btrim(coalesce(i.raw_input, '')), '') requirement,
           lower(coalesce(i.category, '')) cat
      from public.inquiries i
     where coalesce(i.status, 'open') = 'open'
  ),
  scored as (
    select c.*,
      (c.cat = me.sector and me.sector <> '')                                    as trade_hit,
      (c.emirate is not null and (c.emirate = me.emirate
        or c.emirate = any(me.service_emirates)))                                as location_hit,
      -- Capacity is only ASKED when the supplier has declared a capability. An empty capability
      -- makes this unanswerable for them, not a failure by them.
      (me.capability <> '')                                                      as capacity_known,
      (me.capability <> '' and c.cat <> '' and position(c.cat in me.capability) > 0) as capacity_hit,
      -- History needs a concluded job. Counted rather than assumed so the reason can name it.
      (select count(*) from public.quotes q
         join public.inquiries qi on qi.id = q.inquiry_id
        where q.supplier_id = p_lead_id and lower(coalesce(qi.category,'')) = c.cat) as similar_jobs
      from cand c cross join me
  ),
  ranked as (
    select s.*,
      -- Weights that applied / weights that could apply. Capacity leaves the denominator when the
      -- supplier has declared nothing; history leaves it while the estate has no completed work.
      round(100.0 * (
        (case when s.trade_hit then 40 else 0 end)
      + (case when s.location_hit then 30 else 0 end)
      + (case when s.capacity_known and s.capacity_hit then 30 else 0 end)
      ) / nullif(40 + 30 + (case when s.capacity_known then 30 else 0 end), 0)) as fit_score
      from scored s
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'count', (select count(*) from ranked),
    'ordered_by', 'fit_score desc — a ranked list, never chronological',
    'population', jsonb_build_object(
      'open_inquiries', (select count(*) from public.inquiries where coalesce(status,'open')='open'),
      'quotes_in_estate', (select count(*) from public.quotes)
    ),
    'note', case when (select count(*) from ranked) = 0
                 then 'no open opportunities yet — nothing to rank'
                 else null end,
    'opportunities', coalesce((
      select jsonb_agg(x order by x->>'fit_score' desc) from (
        select jsonb_build_object(
          'inquiry_id', r.id,
          'project_title', coalesce(nullif(btrim(coalesce(r.summary,'')),''), r.category, 'Untitled project'),
          'category', r.category,
          'emirate', r.emirate,
          -- NULL, not an empty string: an inquiry with no brief has not been described yet, and the
          -- surface must be able to say that rather than render a blank line.
          'requirement', r.requirement,
          'estimated_value', r.budget,
          'fit_score', r.fit_score,
          'match_pct', r.fit_score,
          -- THE "WHY". Each reason states whether it applied, and an unanswerable one says why it
          -- could not be asked rather than reading as a failed test.
          'reasons', jsonb_build_array(
            jsonb_build_object(
              'key', 'trade',
              'applies', r.trade_hit,
              'text', case when r.trade_hit
                           then 'This is your trade — ' || coalesce(r.category,'the same category')
                           else 'Outside your registered trade' end),
            jsonb_build_object(
              'key', 'location',
              'applies', r.location_hit,
              'text', case when r.location_hit
                           then 'Nearby location — ' || coalesce(r.emirate,'your service area')
                           else 'Outside the emirates you serve' end),
            jsonb_build_object(
              'key', 'capacity',
              'applies', r.capacity_known and r.capacity_hit,
              'available', r.capacity_known,
              'text', case when not r.capacity_known
                           then 'Your capacity fits: not assessable — you have not described your capability yet'
                           when r.capacity_hit
                           then 'Your capacity fits — you list this work in your capability'
                           else 'Not in your described capability' end),
            jsonb_build_object(
              'key', 'history',
              'applies', r.similar_jobs > 0,
              -- available:false is the whole point. 0 quotes exist in the estate, so this is
              -- unanswerable for EVERY supplier and must never read as "you have no experience".
              'available', (select count(*) from public.quotes) > 0,
              'similar_jobs', r.similar_jobs,
              'text', case when (select count(*) from public.quotes) = 0
                           then 'Previous similar project: no completed work has been recorded on QuotesDone yet, for anyone'
                           when r.similar_jobs > 0
                           then 'You worked on ' || r.similar_jobs || ' previous similar project(s)'
                           else 'No previous similar project on record' end)
          )
        ) x from ranked r
      ) s
    ), '[]'::jsonb)
  )
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_outreach_golive()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select lower(btrim(value)) = 'true' from public.app_secrets where key = 'supplier_outreach_golive'), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_product_match(p_inquiry_id uuid, p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with inq as (
    -- EVERYTHING THE CUSTOMER SAID, not the first field that happens to be non-empty. The first
    -- version preferred raw_input and fell back to summary, and on the demo enquiry that discarded
    -- the only line describing the work — every product scored 0% while the store held a curtain
    -- wall profile and the enquiry was for curtain walling. A brief's title carries meaning too,
    -- and dropping it to honour a precedence rule loses signal for nothing.
    select lower(coalesce(category, '')) cat,
           lower(concat_ws(' ', coalesce(summary, ''), coalesce(raw_input, ''), coalesce(category, ''))) want
      from public.inquiries where id = p_inquiry_id
  ),
  -- Words worth matching on. Anything under four characters is noise ("we", "for", "the"), and a
  -- stop list would be a maintenance burden for no gain at this size.
  terms as (
    select distinct w from inq, unnest(regexp_split_to_array(inq.want, '[^a-z0-9]+')) w
     where length(w) >= 4
  ),
  prod as (
    select p.id, p.name, p.brand, p.model, p.category_slug,
           lower(concat_ws(' ', p.name, p.brand, p.model, p.description, p.category_slug)) hay
      from public.supplier_product p
     where p.supplier_id = p_lead_id
  ),
  -- ── THE DENOMINATOR IS THE PRODUCT, NOT THE BRIEF ──────────────────────────────────────────────
  -- Scoring matched-terms over ALL the brief's words made the exactly-right product read 6%:
  -- "Aluminium curtain wall profile" matched 2 of 32 words in a paragraph that also discussed
  -- square metres, retail units and powder coating. That understates as badly as an inflated score
  -- overstates, and a supplier seeing 6% on their best product would conclude the matching is
  -- broken — which it would be.
  --
  -- The question is not "how much of the brief does this product cover" (no single product covers
  -- a brief) but "how much of THIS PRODUCT does the brief ask for". Aluminium ✓ curtain ✓ wall ✓
  -- profile ✗ is a strong match, and reads as one.
  pterms as (
    select pr.id pid, w from prod pr,
      unnest(regexp_split_to_array(lower(concat_ws(' ', pr.name, pr.category_slug)), '[^a-z0-9]+')) w
     where length(w) >= 4
  ),
  hit as (
    select pr.id, pr.name, pr.brand, pr.model, pr.category_slug, pr.hay,
           (select count(*) from pterms pt, inq where pt.pid = pr.id and position(pt.w in inq.want) > 0) matched_terms,
           (select count(*) from pterms pt where pt.pid = pr.id) total_terms,
           (pr.category_slug is not null and pr.category_slug = (select cat from inq)) cat_hit,
           ((select cat from inq) <> '' and pr.category_slug is not null) cat_askable
      from prod pr
  ),
  scored as (
    select h.*,
      round(100.0 * (
          (case when h.cat_hit then 40 else 0 end)
        + (case when h.total_terms > 0 then 60.0 * h.matched_terms / h.total_terms else 0 end)
      ) / nullif((case when h.cat_askable then 40 else 0 end)
               + (case when h.total_terms > 0 then 60 else 0 end), 0)) match_pct
      from hit h
  )
  select jsonb_build_object(
    'inquiry_id', p_inquiry_id,
    'supplier_id', p_lead_id,
    'basis', 'lexical: the enquiry''s own words against the product record. Not semantic — supplier_product carries no embedding, so a synonym will not match.',
    'population', jsonb_build_object(
      'products', (select count(*) from prod),
      'terms_from_enquiry', (select count(*) from terms),
      'note', case when (select count(*) from prod) = 0
                   then 'you have no products yet — upload a catalog and these become matchable'
                   when (select count(*) from terms) = 0
                   then 'the enquiry has no description to match against, so only category could be asked'
                   else null end),
    'matches', coalesce((
      select jsonb_agg(jsonb_build_object(
          'product_id', s.id, 'name', s.name, 'brand', s.brand, 'model', s.model,
          'match_pct', s.match_pct,
          'matched_terms', s.matched_terms, 'terms_considered', s.total_terms,
          'category_match', s.cat_hit)
        order by s.match_pct desc nulls last, s.name)
      from scored s), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_products(p_lead_id bigint, p_query text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with base as (
    select p.*
    from public.supplier_product p
    where p.supplier_id = p_lead_id
      and coalesce(p.status, 'active') <> 'archived'
  ),
  -- §7 "Searchable: YES". Matched over name, brand, model, category and the ATTRIBUTE VALUES, so a
  -- search for "5000 CFM" finds the unit whose spec says so rather than only matching its title.
  filtered as (
    select b.* from base b
    where p_query is null or btrim(p_query) = '' or (
         b.name              ilike '%' || btrim(p_query) || '%'
      or coalesce(b.brand, '')          ilike '%' || btrim(p_query) || '%'
      or coalesce(b.model, '')          ilike '%' || btrim(p_query) || '%'
      or coalesce(b.category_slug, '')  ilike '%' || btrim(p_query) || '%'
      or coalesce(b.subcategory_slug,'')ilike '%' || btrim(p_query) || '%'
      or coalesce(b.description, '')    ilike '%' || btrim(p_query) || '%'
      or exists (
           select 1 from jsonb_each_text(coalesce(b.attributes, '{}'::jsonb)) a
           where a.value ilike '%' || btrim(p_query) || '%'
              or a.key   ilike '%' || btrim(p_query) || '%')
      -- Certifications are a jsonb ARRAY and were unreachable by the attribute scan above, so
      -- "show me my Eurovent-certified units" returned nothing. A supplier searching their own
      -- catalogue by certification is the obvious case for §7's "Searchable: YES".
      or exists (
           select 1 from jsonb_array_elements_text(
             case when jsonb_typeof(b.certifications) = 'array' then b.certifications else '[]'::jsonb end) c
           where c ilike '%' || btrim(p_query) || '%')
    )
  )
  select jsonb_build_object(
    'supplier_id', p_lead_id,
    'query', p_query,

    -- ── §7's THREE COUNTS, over the supplier's whole catalogue, not the filtered page ───────────
    'product_count',  (select count(*) from base),
    -- coalesce(SUBcategory, category), not the reverse. category_slug is the broad family ('hvac')
    -- and is identical across a whole catalogue, so coalescing to it FIRST collapsed four distinct
    -- product categories into 1. The spec's "Categories: 18" means product categories, not sectors.
    'category_count', (select count(distinct coalesce(subcategory_slug, category_slug))
                       from base where coalesce(subcategory_slug, category_slug) is not null),
    -- The real number of specification keys the platform holds. Counted, never estimated.
    'attribute_count', (
      select coalesce(sum((select count(*) from jsonb_object_keys(coalesce(b.attributes, '{}'::jsonb)))), 0)
      from base b
    ),
    'searchable', true,

    -- ── §5's WAREHOUSE PANEL: the three quantities, over the SUPPLIER's own stock ────────────────
    -- inv_items is NOT this, and the distinction matters. Measured: inv_items has no supplier_id at
    -- all, and carries inventory_account / cogs_account / reorder_point — it is QuotesDone's OWN
    -- accounting ledger. A supplier's warehouse could never appear in it, so scoring §5 against it
    -- would have been unsatisfiable by any correct implementation.
    -- A supplier's stock lives on the variant, which is also where §8's "Available: 120" comes from.
    'stock', (
      select jsonb_build_object(
        'available',     coalesce(sum(nullif(v.attributes ->> 'available_units', '')::numeric), 0),
        'reserved',      coalesce(sum(nullif(v.attributes ->> 'reserved_units', '')::numeric), 0),
        'in_production', coalesce(sum(nullif(v.attributes ->> 'in_production_units', '')::numeric), 0),
        'skus', count(*)
      )
      from public.supplier_product_variant v
      join base b2 on b2.id = v.product_id
      where v.active
    ),

    'match_count', (select count(*) from filtered),

    'catalogs', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', c.id, 'status', c.status, 'version', c.version,
        'extracted_at', c.extracted_at, 'source', c.source_document_path
      ) order by c.created_at desc), '[]'::jsonb)
      from public.supplier_catalog c where c.supplier_id = p_lead_id
    ),

    -- ── §8 AI PRODUCT CARDS ─────────────────────────────────────────────────────────────────────
    -- Every field the spec draws on a card, from real columns. `ai_match` is NOT invented: it is
    -- null unless the product carries a computed match in its attributes, because §8's "AI Match
    -- 96%" is a claim about a specific opportunity and there are 0 inquiries on production. A card
    -- showing a confident percentage against nothing would be the exact fabrication this row's
    -- scorer exists to catch.
    'products', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', f.id,
        'name', f.name,
        'category', coalesce(f.subcategory_slug, f.category_slug),
        'brand', f.brand,
        'model', f.model,
        'description', f.description,
        'attributes', coalesce(f.attributes, '{}'::jsonb),
        'attribute_count', (select count(*) from jsonb_object_keys(coalesce(f.attributes, '{}'::jsonb))),
        'certifications', coalesce(f.certifications, '[]'::jsonb),
        'documents', coalesce(f.documents, '[]'::jsonb),
        'status', f.status,
        -- Availability comes from the variants, which is where stock policy lives.
        'variants', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'sku', v.sku, 'attributes', v.attributes,
            'price_policy', v.price_policy, 'lead_time_policy', v.lead_time_policy,
            'active', v.active) order by v.sku), '[]'::jsonb)
          from public.supplier_product_variant v where v.product_id = f.id
        ),
        'reserved_units', (
          select sum(nullif(v.attributes ->> 'reserved_units', '')::numeric)
          from public.supplier_product_variant v where v.product_id = f.id and v.active
        ),
        'in_production_units', (
          select sum(nullif(v.attributes ->> 'in_production_units', '')::numeric)
          from public.supplier_product_variant v where v.product_id = f.id and v.active
        ),
        'available_units', (
          select sum((v.attributes ->> 'available_units')::numeric)
          from public.supplier_product_variant v
          where v.product_id = f.id and v.active
            and (v.attributes ->> 'available_units') ~ '^[0-9]+$'
        ),
        -- §8's "Compatible Projects". Real when the extractor recorded it, null otherwise.
        'compatible_projects', coalesce(f.attributes -> 'compatible_projects', 'null'::jsonb),
        'ai_match', (f.attributes ->> 'ai_match')::numeric,
        'evidence_refs', coalesce(f.evidence_refs, '[]'::jsonb)
      ) order by f.name), '[]'::jsonb)
      from (select * from filtered order by name limit 200) f
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_quote_recommend(p_lead_id bigint, p_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  flag as (select coalesce((select source from me), '') = 'qd_demo_fixture' as is_demo),
  inq as (select * from public.inquiries where id = p_inquiry_id),

  -- The competing bids: what every OTHER supplier has priced this same enquiry at.
  bids as (
    select q.quote_amount amt, q.lead_time, q.warranty, q.payment_terms
    from public.quotes q, flag
    where q.inquiry_id = p_inquiry_id
      and q.supplier_id is distinct from p_lead_id
      and q.quote_amount is not null and q.quote_amount > 0
      and (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
  ),
  stat as (
    select count(*) n,
           round(percentile_cont(0.5)  within group (order by amt)) mid,
           round(percentile_cont(0.25) within group (order by amt)) lo,
           round(percentile_cont(0.75) within group (order by amt)) hi,
           min(amt) lowest, max(amt) highest
    from bids
  ),

  -- The supplier's own habit, measured rather than assumed: across every enquiry they have priced,
  -- where did they sit against the midpoint of that enquiry's other bids? An index of 1.04 means
  -- this company prices 4% above the middle of the market, and it is computed from their own rows.
  habit as (
    select round(avg(ratio)::numeric, 3) idx, count(*) n
    from (
      select q.quote_amount / nullif((
               select percentile_cont(0.5) within group (order by o.quote_amount)
               from public.quotes o
               where o.inquiry_id = q.inquiry_id and o.supplier_id is distinct from q.supplier_id
                 and o.quote_amount > 0), 0) as ratio
      from public.quotes q, flag
      where q.supplier_id = p_lead_id and q.quote_amount > 0
        and (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
    ) r where r.ratio is not null
  ),

  -- ── DELIVERY, WARRANTY AND TERMS ARE TEXT, SO THEY ARE PICKED, NOT AVERAGED ───────────────────
  -- The average of "8-10 weeks" and "12-14 weeks" is not a promise anybody made, so the routine
  -- returns an answer a real supplier actually gave.
  --
  -- WHICH answer took two attempts, and the first one was wrong in a way worth recording. Taking
  -- `order by count(*) desc, <text>` looks like "the most common", but when all four bids are
  -- distinct every count is 1 and the tie breaks ALPHABETICALLY — which recommended "12-14 weeks",
  -- the slowest delivery on the board, and "12 months on equipment", the weakest warranty. A
  -- tie-break is not a market consensus, and dressing one up as the modal answer is the same defect
  -- class as an invented percentage: arithmetic that ran correctly over the wrong population.
  --
  -- So: when a value genuinely repeats, that mode is the answer and `agreed_by` says how many said
  -- it. When nothing repeats there IS no consensus, and the answer is the MIDDLE of the observed
  -- range ranked by its leading number — a real bid, neither the fastest nor the slowest — with
  -- `consensus` false so the surface can say the suppliers disagreed.
  ranked as (
    select 'lead' kind, lead_time v, count(*) c,
           min(coalesce(substring(lead_time from '\d+')::int, 999)) ord
    from bids where lead_time is not null group by 1, 2
    union all
    select 'warranty', warranty, count(*),
           min(coalesce(substring(warranty from '\d+')::int, 999))
    from bids where warranty is not null group by 1, 2
    union all
    select 'terms', payment_terms, count(*),
           min(coalesce(substring(payment_terms from '\d+')::int, 999))
    from bids where payment_terms is not null group by 1, 2
  ),
  picked as (
    select kind, v, c, has_mode from (
      select r.kind, r.v, r.c,
             max(r.c) over (partition by r.kind) >= 2 as has_mode,
             row_number() over (partition by r.kind order by r.c desc, r.ord) rn_mode,
             row_number() over (partition by r.kind order by r.ord) rn_ord,
             count(*) over (partition by r.kind) tot
      from ranked r
    ) z
    where (z.has_mode and z.rn_mode = 1)
       or (not z.has_mode and z.rn_ord = (z.tot + 1) / 2)
  ),
  lead_pick  as (select v, c, has_mode from picked where kind = 'lead'),
  warr_pick  as (select v, c, has_mode from picked where kind = 'warranty'),
  terms_pick as (select v, c, has_mode from picked where kind = 'terms'),

  -- ── RISK, AS NAMED SIGNALS RATHER THAN A MOOD ─────────────────────────────────────────────────
  -- Each signal is a condition on a real column, each carries the sentence a supplier would need to
  -- act on it, and the level is the count. A risk score with no reasons attached is a number the
  -- supplier can neither check nor fix.
  risk as (
    select coalesce(jsonb_agg(jsonb_build_object('signal', s.k, 'detail', s.d)) filter (where s.hit), '[]'::jsonb) items,
           count(*) filter (where s.hit) n
    from (
      select 'not_matchable' k,
             not public.fn_is_matchable(m.verified, m.banned, m.matching_blocked,
                                        m.approval_status, m.permanently_closed, m.chat_strikes) hit,
             'Your account cannot currently receive work, so a quote sent now may not reach the customer.' d
      from me m
      union all
      select 'licence_missing',
             (select license_expiry is null from me),
             'No licence expiry is on file, and approval depends on it.'
      union all
      select 'licence_expired',
             (select coalesce(license_expiry < current_date, false) from me),
             'Your trade licence has expired.'
      union all
      select 'brief_incomplete',
             coalesce(((select completeness->>'score' from inq))::int < 60, true),
             'The customer brief is incomplete, so the scope you price may move after you send this.'
      union all
      select 'thin_market',
             (select n from stat) < 3,
             'Fewer than three other suppliers have priced this, so the midpoint is a weak signal.'
      union all
      select 'wide_spread',
             (select case when mid > 0 then (highest - lowest) / mid > 0.4 else false end from stat),
             'The other bids disagree by more than 40%, which usually means the scope is being read differently.'
    ) s
  )

  select case when (select n from stat) = 0
    then jsonb_build_object(
      'available', false,
      'lead_id', p_lead_id, 'inquiry_id', p_inquiry_id,
      'basis', 'quotes from other suppliers on this enquiry',
      'population', 0,
      'note', 'no other supplier has priced this enquiry yet, so there is no market midpoint to '
              'recommend against. A figure taken from a different project of a different size '
              'would look identical on screen and mean nothing.')
    else jsonb_build_object(
      'available', true,
      'lead_id', p_lead_id, 'inquiry_id', p_inquiry_id,
      'summary', (select summary from inq),
      'population', (select n from stat),
      'basis', 'the midpoint of every other supplier''s bid on this enquiry',

      -- The recommended price, with the spread it came from.
      'recommended_price', jsonb_build_object(
        'value', (select mid from stat), 'currency', 'AED',
        'p25', (select lo from stat), 'p75', (select hi from stat),
        'low', (select lowest from stat), 'high', (select highest from stat),
        'basis', 'median of ' || (select n from stat)::text || ' competing bid(s) on this enquiry'),

      -- Where that recommendation sits, and where this supplier usually sits.
      'market_position', jsonb_build_object(
        'verdict', 'at the market midpoint',
        'your_index', (select idx from habit),
        'your_quotes_measured', (select n from habit),
        'detail', case when (select idx from habit) is null
                  then 'You have not priced enough enquiries yet for us to know where you usually sit.'
                  when (select idx from habit) > 1.02
                  then 'You normally price about ' || round(((select idx from habit) - 1) * 100)::text
                       || '% above the middle of the market, so this suggestion is lower than your habit.'
                  when (select idx from habit) < 0.98
                  then 'You normally price about ' || round((1 - (select idx from habit)) * 100)::text
                       || '% below the middle of the market, so this suggestion is higher than your habit.'
                  else 'You normally price close to the middle of the market, in line with this suggestion.' end),

      -- Delivery, suggested from what the competition actually promised.
      'delivery_estimate', jsonb_build_object(
        'value', (select v from lead_pick),
        'agreed_by', (select c from lead_pick),
        'consensus', (select has_mode from lead_pick),
        'observed', (select coalesce(jsonb_agg(distinct lead_time), '[]'::jsonb) from bids where lead_time is not null),
        'basis', case when (select has_mode from lead_pick)
                 then 'the lead time most of the competing bids gave'
                 else 'no two bids gave the same lead time, so this is the middle of the range' end),

      -- Warranty, picked the same way and with the same honesty about disagreement.
      'warranty', jsonb_build_object(
        'value', (select v from warr_pick),
        'agreed_by', (select c from warr_pick),
        'consensus', (select has_mode from warr_pick),
        'observed', (select coalesce(jsonb_agg(distinct warranty), '[]'::jsonb) from bids where warranty is not null),
        'basis', case when (select has_mode from warr_pick)
                 then 'the warranty most of the competing bids offered'
                 else 'no two bids offered the same warranty, so this is the middle of the range' end),

      'payment_terms', jsonb_build_object(
        'value', (select v from terms_pick),
        'agreed_by', (select c from terms_pick),
        'consensus', (select has_mode from terms_pick),
        'basis', case when (select has_mode from terms_pick)
                 then 'the payment terms most of the competing bids asked for'
                 else 'no two bids asked for the same terms, so this is the middle of the range' end),

      -- ── RISK: A LEVEL, ITS REASONS, AND WHAT TO DO ABOUT IT ───────────────────────────────────
      -- The first version returned a level and its signals and stopped there, which leaves the
      -- supplier holding the word "high" and no next move. Every other figure on this screen is a
      -- proposal, and the risk should be one too: the routine names the single action that would
      -- most reduce it, drawn from the same signals rather than from a phrasebook.
      'risk_level', jsonb_build_object(
        'value', case when (select n from risk) >= 3 then 'high'
                      when (select n from risk) >= 1 then 'medium' else 'low' end,
        'count', (select n from risk),
        'signals', (select items from risk),
        'recommended_action', case
          when (select n from risk) = 0
            then 'Nothing is working against this quote. We suggest sending it as proposed.'
          when exists (select 1 from jsonb_array_elements((select items from risk)) e
                       where e->>'signal' in ('not_matchable', 'licence_expired', 'licence_missing'))
            then 'We suggest fixing your account before you send this: a quote from an account that '
                 || 'cannot be matched may never reach the customer, whatever price is on it.'
          when exists (select 1 from jsonb_array_elements((select items from risk)) e
                       where e->>'signal' = 'wide_spread')
            then 'We suggest asking the customer to confirm the scope before you commit to a price. '
                 || 'The other bids disagree enough that they are probably not all pricing the same job.'
          when exists (select 1 from jsonb_array_elements((select items from risk)) e
                       where e->>'signal' = 'brief_incomplete')
            then 'We suggest putting your assumptions in writing with this quote, so a change of '
                 || 'scope later is a variation rather than an argument.'
          else 'We suggest treating the suggested price as indicative until more suppliers have priced this.'
          end,
        'basis', 'six checked signals on your account, the brief and the shape of the competing bids'))
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_registration_state(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_exempt boolean; v_rank int; v_paid_until date; v_claimed boolean;
  v_fee numeric; v_ccy text; v_start date; v_free int;
  v_status text; v_due numeric; v_reason text;
begin
  select coalesce(l.subscription_exempt,false), l.founding_rank, l.subscription_paid_until, coalesce(l.claimed,false)
    into v_exempt, v_rank, v_paid_until, v_claimed
  from public.leads l where l.id = p_lead_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'lead_not_found', 'lead_id', p_lead_id);
  end if;

  select coalesce(p.supplier_reg_fee,1000), coalesce(p.supplier_reg_currency,'AED'), p.supplier_charging_starts, coalesce(p.supplier_free_count,1000)
    into v_fee, v_ccy, v_start, v_free
  from public.pricing_config p where p.id = 1;
  v_fee := coalesce(v_fee,1000); v_ccy := coalesce(v_ccy,'AED'); v_free := coalesce(v_free,1000);

  if v_exempt then
    v_status := 'exempt'; v_due := 0;
    v_reason := 'founding rank ' || coalesce(v_rank::text,'(unranked)') || ' is inside the permanently exempt founding cohort';
  elsif v_paid_until is not null and v_paid_until >= current_date then
    v_status := 'paid'; v_due := 0;
    v_reason := 'subscription paid until ' || v_paid_until::text;
  elsif v_start is not null and current_date < v_start then
    v_status := 'not_due'; v_due := 0;
    v_reason := 'charging does not start until ' || v_start::text;
  elsif v_start is null and (v_rank is null or v_rank <= v_free) then
    v_status := 'not_due'; v_due := 0;
    v_reason := case when v_rank is null then 'founding rank not yet stamped (stamped at verification); the first ' || v_free || ' verified registrations are free and there is no calendar start date'
                     else 'founding rank ' || v_rank || ' is within the first ' || v_free || ' free registrations; charging starts with registration ' || (v_free + 1) || ', on no calendar date' end;
  else
    v_status := 'due'; v_due := v_fee;
    v_reason := case when v_paid_until is null then 'never paid' else 'subscription lapsed on ' || v_paid_until::text end;
  end if;

  return jsonb_build_object(
    'ok', true, 'lead_id', p_lead_id, 'status', v_status, 'fee_due', v_due, 'currency', v_ccy,
    'may_quote', (v_status <> 'due'), 'exempt', v_exempt, 'founding_rank', v_rank,
    'paid_until', v_paid_until, 'charging_starts', v_start, 'free_count', v_free, 'claimed', v_claimed, 'reason', v_reason);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_sanctions_screen(p_run_ids bigint[], p_rehearsal_tag text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_reh boolean := p_rehearsal_tag is not null;
  v_suppliers int := 0; v_entries int := 0; v_new int := 0; v_leads_hit int := 0; v_open int := 0;
  v_sources text; r record; h record; v_task bigint; v_bd bigint; v_title text; v_bd_title text; v_hits text;
begin
  select string_agg(distinct source || ' (' || entries || ' entries, fetched ' || to_char(fetched_at, 'DD Mon YYYY HH24:MI') || ' UTC, sha256 ' || left(coalesce(sha256, '?'), 12) || ')', '; ')
    into v_sources from public.screening_run where id = any(p_run_ids);

  create temp table tmp_screen_sup on commit drop as
    select l.id, f.field, f.val, public.fn_screening_normalise(f.val) as norm, public.fn_screening_tokens(f.val) as toks
      from public.leads l
      cross join lateral (values ('legal_name', l.company_name), ('licence_name', l.name_corrected_from),
                                 ('owner', l.signatory_name), ('contact', l.contact_name),
                                 ('email_domain', split_part(coalesce(l.email_domain, split_part(coalesce(l.email, ''), '@', 2)), '.', 1))) f(field, val)
     where (l.lifecycle_stage = 'registered' or l.approval_status = 'approved')
       and case when v_reh then l.company_name like 'ZZ DEMO — %'
                else coalesce(l.company_name, '') not like 'ZZ DEMO — %' and coalesce(l.email, '') not ilike '%@example.invalid' end
       and nullif(btrim(coalesce(f.val, '')), '') is not null;
  select count(distinct id) into v_suppliers from tmp_screen_sup;
  select count(*) into v_entries from public.screening_entry where run_id = any(p_run_ids);

  for h in
    select s.id as lead_id, s.field, s.val, e.id as entry_id, e.run_id, e.name, e.source, coalesce(e.reference, '') as reference, e.entry_type,
           case when s.field = 'email_domain' or s.norm = e.name_norm then 'exact' else 'token_overlap' end as kind,
           case when s.field = 'email_domain' or s.norm = e.name_norm then 1.0
                else round(least(cardinality(s.toks), cardinality(e.tokens))::numeric / greatest(cardinality(s.toks), cardinality(e.tokens), 1), 2) end as score
      from tmp_screen_sup s
      join public.screening_entry e
        on e.run_id = any(p_run_ids)
       and ((s.field <> 'email_domain' and s.norm = e.name_norm and length(s.norm) >= 6)
         or (s.field <> 'email_domain' and cardinality(s.toks) >= 2 and cardinality(e.tokens) >= 2
             and (s.toks <@ e.tokens or e.tokens <@ s.toks))
         or (s.field = 'email_domain' and length(s.norm) >= 6 and replace(e.name_norm, ' ', '') = s.norm))
  loop
    insert into public.supplier_screening_hit (run_id, lead_id, field, supplier_value, entry_id, entry_name, entry_source, entry_reference, entry_type, match_kind, score)
    values (h.run_id, h.lead_id, h.field, h.val, h.entry_id, h.name, h.source, h.reference, h.entry_type, h.kind, h.score)
    on conflict (lead_id, entry_source, entry_reference, field) do nothing;
    if found then v_new := v_new + 1; end if;
  end loop;

  -- the team update: one task on compliance with the evidence, one on BD to hold outreach; never the founder
  for r in
    select x.lead_id, l.company_name, count(*) as n,
           string_agg(format('%s %L matched %L [%s %s] %s, score %s', x.field, x.supplier_value, x.entry_name, x.entry_source, x.entry_reference, x.match_kind, x.score), E'\n' order by x.score desc, x.id) as ev,
           string_agg(x.id::text, ', ' order by x.id) as ids
      from public.supplier_screening_hit x join public.leads l on l.id = x.lead_id
     where x.status = 'open' and x.task_id is null and x.run_id = any(p_run_ids)
     group by x.lead_id, l.company_name
  loop
    v_title := 'Sanctions screening hit: ' || coalesce(r.company_name, 'lead #' || r.lead_id) || ' — lead #' || r.lead_id;
    select id into v_task from public.org_tasks where title = v_title and status not in ('done', 'cancelled') order by id limit 1;
    if v_task is null then
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class, assigned_agent)
      values ('legal', v_title,
              'The weekly sanctions screening (' || coalesce(v_sources, 'fixture run') || ') matched a REGISTERED supplier. EVIDENCE:' || E'\n' || r.ev
              || E'\n\n' || 'No automatic removal has happened. Compare the supplier''s trade licence, owner and address against the listing and decide, per hit: '
              || 'select public.fn_supplier_screening_decide(<hit_id>, ''confirmed'' | ''false_positive'', ''compliance_mgr''). '
              || 'A confirmed hit moves the supplier through the existing status path (leads.banned + banned_reason, matching_blocked, approval_status rejected) and closes this task and the BD hold; a false positive closes the hit. '
              || 'Hit id(s): ' || r.ids || '.',
              'assigned', 'supervised', false, 'compliance_check', 'compliance_mgr')
      returning id into v_task;
    end if;
    v_bd_title := 'Hold outreach and onboarding: ' || coalesce(r.company_name, 'lead #' || r.lead_id) || ' — lead #' || r.lead_id || ' (sanctions screening)';
    select id into v_bd from public.org_tasks where title = v_bd_title and status not in ('done', 'cancelled') order by id limit 1;
    if v_bd is null then
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class, assigned_agent)
      values ('supply', v_bd_title,
              'Compliance is reviewing a sanctions-screening match on this supplier (task #' || v_task || '). Send no invitation, follow-up or onboarding step to lead #' || r.lead_id
              || ' until compliance decides; this task closes with that decision.',
              'assigned', 'autonomous', false, 'coordinate', 'bd')
      returning id into v_bd;
    end if;
    update public.supplier_screening_hit set task_id = v_task, bd_task_id = v_bd
     where lead_id = r.lead_id and status = 'open' and task_id is null;
    v_leads_hit := v_leads_hit + 1;
  end loop;

  -- retention: the latest fetch per source is the list; older entries go (their run rows stay as the record)
  if not v_reh then
    delete from public.screening_entry e
     where e.run_id not in (select max(id) from public.screening_run where status = 'ok' group by source);
  end if;

  select count(*) into v_open from public.supplier_screening_hit where status = 'open';
  insert into public.agent_runs (agent, status, counts, note, started_at, finished_at)
  values ('supplier_sanctions_screen', 'ok',
          jsonb_build_object('suppliers', v_suppliers, 'entries', v_entries, 'hits_new', v_new, 'leads_hit', v_leads_hit, 'hits_open', v_open,
                             'runs', to_jsonb(p_run_ids), 'rehearsal', v_reh),
          'Sanctions screening: ' || v_suppliers || ' registered supplier(s) screened against ' || v_entries || ' list entries (' || coalesce(v_sources, 'no run') || '): '
          || v_new || ' new hit(s) on ' || v_leads_hit || ' supplier(s); ' || v_open || ' open. A hit opens a compliance task and a BD hold; nobody is removed automatically.'
          || case when v_reh then ' [rehearsal ' || p_rehearsal_tag || ']' else '' end, now(), now());
  return jsonb_build_object('suppliers', v_suppliers, 'entries', v_entries, 'hits_new', v_new, 'leads_hit', v_leads_hit, 'hits_open', v_open, 'sources', v_sources);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_score_refresh()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  insert into supplier_score (lead_id, response_rate, avg_response_hours, quotes_submitted, quotes_won,
                              rejection_count, price_index, quality_rating, reliability, last_active, computed_at)
  select l.id,
         -- NO COALESCE. A null rv_response_rate means nobody has asked this supplier for anything,
         -- and 0% is a different claim entirely.
         l.rv_response_rate,
         null,
         coalesce(q.submitted, 0),
         coalesce(q.won, 0),
         coalesce(q.rejected, 0),
         q.price_index,
         -- QUALITY RATING IS EARNED ON THE PLATFORM, NOT SCRAPED FROM GOOGLE.
         -- Founder decision, 2026-08-08: rating exists only for VERIFIED suppliers, and comes from
         -- the customer's own 1-5 review after a job. leads.rating is the Google Maps star rating of
         -- a business we have never worked with; presenting it as a QuotesDone quality rating is a
         -- claim the platform has not earned. NULL when unverified or unreviewed -- an unrated
         -- supplier is unrated, and must never look like one every customer disliked.
         case when not coalesce(l.verified, false) then null
              else (select round(avg(rv.rating)::numeric * 20, 1)
                      from reviews rv where rv.supplier_id = l.id) end,
         -- Reliability: response behaviour dominates, win rate confirms it, rejections and refunds subtract.
         -- UNMEASURED IS NOT UNRELIABLE (12 Aug 2026). With no response history AND no quotes there is
         -- nothing to score, so this is NULL rather than 0 -- the same call the quality_rating comment
         -- above makes, and the same one fn_reputation_recompute now makes for employees. Note that
         -- verification alone must not manufacture a score either: the +20 below is a bonus on top of
         -- evidence, not evidence.
         case when l.rv_response_rate is null and coalesce(q.submitted, 0) = 0 then null
              else round(least(100, greatest(0,
                     coalesce(l.rv_response_rate,0) * 0.55
                   + (case when coalesce(q.submitted,0) > 0 then 100.0*coalesce(q.won,0)/q.submitted else 0 end) * 0.25
                   + (case when l.verified then 20 else 0 end)
                   - coalesce(q.rejected,0) * 2
                   - coalesce(l.rv_nonresponse_refunds,0) * 5
                 )), 1)
         end,
         greatest(l.portal_updated_at, l.approved_at, l.scraped_at),
         now()
  from leads l
  left join (
    select q.supplier_id,
           count(*) as submitted,
           count(*) filter (where q.status = 'won')      as won,
           count(*) filter (where q.status = 'rejected') as rejected,
           round(avg(q.quote_amount) filter (where q.quote_amount > 0), 2) as price_index
    from quotes q group by q.supplier_id
  ) q on q.supplier_id = l.id
  where l.id is not null
  on conflict (lead_id) do update set
    response_rate = excluded.response_rate, quotes_submitted = excluded.quotes_submitted,
    quotes_won = excluded.quotes_won, rejection_count = excluded.rejection_count,
    price_index = excluded.price_index, quality_rating = excluded.quality_rating,
    reliability = excluded.reliability, last_active = excluded.last_active, computed_at = now();
  get diagnostics n = row_count;
  return n;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_screening_decide(p_hit_id bigint, p_decision text, p_actor text DEFAULT 'compliance_mgr'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare h record; v_open int; v_closed int := 0; t bigint; v jsonb;
begin
  if p_decision not in ('confirmed', 'false_positive') then
    raise exception 'fn_supplier_screening_decide: decision must be confirmed or false_positive, not %', p_decision;
  end if;
  select * into h from public.supplier_screening_hit where id = p_hit_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such hit ' || p_hit_id); end if;
  if h.status <> 'open' then return jsonb_build_object('ok', false, 'reason', 'hit ' || p_hit_id || ' is already ' || h.status); end if;

  update public.supplier_screening_hit set status = p_decision, decided_by = p_actor, decided_at = now() where id = p_hit_id;

  if p_decision = 'confirmed' then
    -- the same columns fn_ban_overdue_dues writes: banned + reason, matching blocked, and the approval withdrawn
    update public.leads
       set banned = true,
           banned_reason = 'Sanctions screening hit confirmed by ' || p_actor || ' on ' || to_char(now(), 'DD Mon YYYY') || ': '
                           || h.entry_source || ' ' || h.entry_reference || ' (' || h.entry_name || ') matched ' || h.field || ' "' || coalesce(h.supplier_value, '') || '".',
           matching_blocked = true,
           matching_block_reason = 'Banned: sanctions screening hit confirmed (' || h.entry_source || ')',
           approval_status = case when approval_status = 'approved' then 'rejected' else approval_status end,
           rejection_reason = coalesce(rejection_reason, 'sanctions screening hit confirmed')
     where id = h.lead_id;
    -- every other open hit on the same supplier is decided by the same fact
    update public.supplier_screening_hit set status = 'confirmed', decided_by = p_actor, decided_at = now()
     where lead_id = h.lead_id and status = 'open';
  end if;

  select count(*) into v_open from public.supplier_screening_hit where lead_id = h.lead_id and status = 'open';
  if v_open = 0 then
    foreach t in array array_remove(array[h.task_id, h.bd_task_id], null) loop
      v := public.fn_org_task_close_as_fact(t, p_actor,
             case when p_decision = 'confirmed'
                  then 'Sanctions screening hit CONFIRMED by ' || p_actor || ': ' || h.entry_source || ' ' || h.entry_reference || ' (' || h.entry_name || '). The supplier (lead #' || h.lead_id || ') is banned through the existing status path: leads.banned, matching_blocked, approval withdrawn. Outreach and onboarding stop.'
                  else 'Sanctions screening hit reviewed by ' || p_actor || ' and recorded as a FALSE POSITIVE: ' || h.entry_source || ' ' || h.entry_reference || ' (' || h.entry_name || ') is not lead #' || h.lead_id || '. No status change; outreach and onboarding may continue.' end,
             jsonb_build_object('hit_id', p_hit_id, 'decision', p_decision, 'lead_id', h.lead_id, 'owner', p_actor));
      if coalesce((v ->> 'ok')::boolean, false) then v_closed := v_closed + 1; end if;
    end loop;
  end if;
  return jsonb_build_object('ok', true, 'hit_id', p_hit_id, 'decision', p_decision, 'lead_id', h.lead_id, 'open_hits_left', v_open, 'tasks_closed', v_closed);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_stats(p_supplier_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb; v_quotes int; v_reveals int; v_hired int; v_lost int;
  v_qd_rev numeric; v_deal_val numeric; v_avg_lead numeric;
  v_pos jsonb; v_hist jsonb; v_rating numeric; v_rating_pct numeric; v_resp numeric;
  v_pending_reviews int; v_active_rfqs int;
begin
  select count(*) into v_quotes from quotes where supplier_id=p_supplier_id;
  select count(*) into v_reveals from transactions where supplier_id=p_supplier_id;
  select count(*) into v_hired from inquiries where hired_supplier_id=p_supplier_id;
  select count(*) into v_lost from inquiries i
     where i.hired_supplier_id is not null and i.hired_supplier_id<>p_supplier_id
       and exists (select 1 from quotes q where q.inquiry_id=i.id and q.supplier_id=p_supplier_id);
  select coalesce(sum(coalesce(reveal_fee,0)+coalesce(app_fee,0)),0),
         coalesce(sum(coalesce(quote_amount,0)),0)
    into v_qd_rev, v_deal_val
    from transactions where supplier_id=p_supplier_id and coalesce(refund_status,'')<>'approved';
  select round(avg(nullif(regexp_replace(coalesce(lead_time,''),'[^0-9.]','','g'),'')::numeric),1)
    into v_avg_lead from quotes where supplier_id=p_supplier_id and lead_time ~ '[0-9]';
  select coalesce(app_rating,rating), rv_response_rate into v_rating, v_resp from leads where id=p_supplier_id;
  select round(100.0*(count(*) filter (where coalesce(l2.app_rating,l2.rating,0) <= coalesce(v_rating,0)))/nullif(count(*),0),0)
    into v_rating_pct
    from leads l2 where l2.sector = (select sector from leads where id=p_supplier_id) and coalesce(l2.app_rating,l2.rating) is not null;
  select count(*) into v_pending_reviews from quotes where supplier_id=p_supplier_id and coalesce(review_status,'')='pending';
  select count(distinct q.inquiry_id) into v_active_rfqs from quotes q join inquiries i on i.id=q.inquiry_id
    where q.supplier_id=p_supplier_id and coalesce(i.status,'') in ('open','active','collecting','live');
  with myq as (select inquiry_id, quote_amount from quotes where supplier_id=p_supplier_id and quote_amount is not null and quote_amount>0),
  peer as (select inquiry_id, min(quote_amount) lo, avg(quote_amount) av, count(*) n
             from quotes where quote_amount is not null and quote_amount>0 group by inquiry_id),
  pos as (select m.quote_amount, p.lo, p.av,
                 case when p.lo>0 then (m.quote_amount-p.lo)/p.lo*100 end pct_low,
                 case when p.av>0 then (m.quote_amount-p.av)/p.av*100 end pct_avg,
                 (m.quote_amount<=p.lo*1.0001) as is_lowest
            from myq m join peer p using(inquiry_id) where p.n>=2)
  select jsonb_build_object('competitive_rfqs', count(*),'times_lowest', count(*) filter (where is_lowest),
    'lowest_rate', round(100.0*count(*) filter (where is_lowest)/nullif(count(*),0),0),
    'avg_pct_above_lowest', round(avg(pct_low)::numeric,1),'avg_pct_vs_average', round(avg(pct_avg)::numeric,1),
    'band', case when count(*)=0 then 'not enough data' when avg(pct_avg) <= -4 then 'below market average'
                 when avg(pct_avg) < 5 then 'around market average' else 'above market average' end
  ) into v_pos from pos;
  with months as (select date_trunc('month', (now() - (n||' month')::interval)) m from generate_series(0,11) n),
  qb as (select date_trunc('month',created_at) m, count(*) c from quotes where supplier_id=p_supplier_id group by 1),
  rb as (select date_trunc('month',revealed_at) m, count(*) c from transactions where supplier_id=p_supplier_id group by 1)
  select jsonb_agg(jsonb_build_object('month', to_char(months.m,'Mon YY'),'quotes', coalesce(qb.c,0), 'reveals', coalesce(rb.c,0)) order by months.m)
    into v_hist from months left join qb on qb.m=months.m left join rb on rb.m=months.m;
  v := jsonb_build_object('supplier_id', p_supplier_id,'quotes_total', v_quotes,'reveals', v_reveals,'hired', v_hired,
    'lost_to_others', v_lost,'win_ratio', round(100.0*v_hired/nullif(v_quotes,0),1),'reveal_ratio', round(100.0*v_reveals/nullif(v_quotes,0),1),
    'qd_revenue', v_qd_rev,'deal_value_awarded', v_deal_val,'avg_lead_time_days', v_avg_lead,'rating', v_rating,
    'rating_percentile', v_rating_pct,'response_rate', v_resp,'pending_reviews', v_pending_reviews,'active_rfqs', v_active_rfqs,
    'price_positioning', v_pos,'history_12m', v_hist,'document_expiries', fn_supplier_expiries(p_supplier_id));
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_subscription()
 RETURNS TABLE(fee numeric, currency text, period text, start_date date, free_limit integer, fee_source text, start_source text, free_source text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with pc as (select * from public.pricing_config order by id limit 1),
       s as (
         select
           (select nullif(value,'')::numeric from public.app_secrets where key='supplier_subscription_aed')  as fee,
           (select nullif(value,'')::int     from public.app_secrets where key='founding_free_limit')         as free_limit
       )
  select
    coalesce((select supplier_reg_fee::numeric from pc), (select fee from s), 1000)                as fee,
    coalesce((select supplier_reg_currency from pc), 'AED')                                        as currency,
    coalesce((select supplier_reg_period   from pc), 'yearly')                                     as period,
    (select supplier_charging_starts from pc)                                                      as start_date,
    coalesce((select supplier_free_count from pc), (select free_limit from s), 1000)               as free_limit,
    case when (select supplier_reg_fee from pc) is not null then 'pricing_config'
         when (select fee from s) is not null then 'app_secrets' else 'default' end                as fee_source,
    case when (select supplier_charging_starts from pc) is not null then 'pricing_config'
         else 'no date: charging starts with the registration after the free count (founder, 6 Sep 2026)' end as start_source,
    case when (select supplier_free_count from pc) is not null then 'pricing_config'
         when (select free_limit from s) is not null then 'app_secrets' else 'default' end         as free_source;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_tier(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with s as (
    select coalesce(quotes_submitted, 0) submitted, coalesce(quotes_won, 0) won,
           response_rate, quality_rating, reliability
      from public.supplier_score where lead_id = p_lead_id
  ),
  -- ACTIVITY IS THE GATE, and it is checked before the score is consulted. A supplier who has never
  -- quoted has no performance to measure, and averaging nulls into a number would manufacture one.
  a as (select coalesce((select submitted from s), 0) > 0 active),
  t as (
    select case
      when not (select active from a) then 'unranked'
      when (select won from s) >= 10 and coalesce((select quality_rating from s), 0) >= 85 then 'platinum'
      when (select won from s) >= 5  and coalesce((select quality_rating from s), 0) >= 70 then 'gold'
      when (select won from s) >= 1                                                        then 'silver'
      else 'bronze'
    end tier
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'tier', (select tier from t),
    -- available:false is the difference between "we ranked you low" and "we cannot rank you yet".
    -- The supplier must never read the first when the second is true.
    'available', (select active from a),
    'basis', case when (select active from a)
                  then 'quotes won and quality rating, from supplier_score'
                  else 'no quote has been submitted yet, so there is nothing to rank — this is not a low score' end,
    'ladder', jsonb_build_array(
      jsonb_build_object('tier','bronze',  'needs','submit your first quote'),
      jsonb_build_object('tier','silver',  'needs','win 1 job'),
      jsonb_build_object('tier','gold',    'needs','win 5 jobs and hold a 70% quality rating'),
      jsonb_build_object('tier','platinum','needs','win 10 jobs and hold an 85% quality rating')
    ),
    'progress', jsonb_build_object(
      'quotes_submitted', (select submitted from s),
      'quotes_won', (select won from s),
      -- NULL, not 0. A rating is earned; nobody has earned one, and 0 would read as "rated badly".
      'quality_rating', (select quality_rating from s),
      'response_rate', (select response_rate from s)
    ),
    -- ── THE TIER DOES NOT AFFECT MATCHING. FOUNDER DECISION, 2026-08-08, VERBATIM: ──────────────
    --     "no cancel that totally. a tier shouldnt effect a match."
    --
    -- §20 asks for a tier that changes RFQ distribution, preferred status and search visibility.
    -- The founder has refused it, and the refusal is the correct call: a score computed by this
    -- platform deciding which real companies get sent work would quietly sort suppliers into
    -- winners and losers on a number none of them agreed to.
    --
    -- This field used to say "not YET" — which was a promise, and is now a false one. A supplier
    -- reading "not yet" waits for an advantage that is never coming and may chase the ladder for
    -- it. So the payload states the settled position instead, and the three §20 benefit
    -- requirements stay permanently unmet BY DECISION rather than by omission.
    'benefits_active', false,
    'affects_matching', false,
    'benefits_note', 'Your tier never affects which work you are matched to, how you rank in search, '
      || 'or whether you are shown as preferred. Every supplier is matched on fit alone. '
      || 'This is a record of your track record, not a queue position.'
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_twin(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with l as (
    select * from public.leads where id = p_lead_id
  ),
  s as (
    -- ── THE TWO-SCALE PROBLEM IS GONE AT THE SOURCE, SO THE NORMALISATION IS TOO ────────────────
    -- This CTE used to rescale quality_rating, because fn_supplier_score_refresh wrote leads.rating
    -- — a 0-5 GOOGLE MAPS star — into a column read as 0-100, and a 4.5-star business displayed as
    -- "5%". The founder settled it on 2026-08-08: a QuotesDone rating is EARNED, exists only for
    -- verified suppliers, and comes from the customer's own review after a job. The refresh no
    -- longer writes the Maps number at all, so quality_rating is now either a real 0-100 or NULL.
    --
    -- The rescaling is therefore deleted rather than left in "just in case". A defensive transform
    -- guarding against a value that can no longer occur is a lie about what the data means, and the
    -- next reader would have to work out which of the two scales is live.
    select *, quality_rating as q_pct
    from public.supplier_score where lead_id = p_lead_id
  ),
  -- §3 capability checklist. Derived from what the company actually declared it can do, never
  -- assumed: a supplier with no machinery on file is not claimed to manufacture.
  caps as (
    select
      (select coalesce(jsonb_array_length(case when jsonb_typeof(l.machinery)='array' then l.machinery else '[]'::jsonb end), 0) > 0
              or l.capability_summary ilike '%manufactur%' from l)          as manufacturing,
      (select coalesce(l.engineers_count, 0) > 0
              or l.capability_summary ilike '%install%' from l)             as installation,
      (select l.capability_summary ilike '%maintenance%'
              or l.capability_summary ilike '%service%' from l)             as maintenance,
      (select l.capability_summary ilike '%design%' from l)                 as design
  ),
  -- §6 AI confidence: how completely does the platform actually understand this company? A ratio
  -- of populated profile facts, so it moves when the supplier fills their profile in. Not a guess.
  conf as (
    select round(100.0 * (
        (case when l.company_name       is not null then 1 else 0 end)
      + (case when l.sector             is not null then 1 else 0 end)
      + (case when l.capability_summary is not null then 1 else 0 end)
      + (case when l.founded_year        is not null then 1 else 0 end)
      + (case when l.employee_count      is not null or l.team_size is not null then 1 else 0 end)
      + (case when coalesce(array_length(l.service_emirates, 1), 0) > 0 then 1 else 0 end)
      + (case when coalesce(l.certifications, '') <> ''
                or (jsonb_typeof(l.iso_certifications)='array' and jsonb_array_length(l.iso_certifications) > 0) then 1 else 0 end)
      + (case when l.products is not null and l.products <> '' then 1 else 0 end)
      + (case when l.website is not null then 1 else 0 end)
      + (case when l.description is not null then 1 else 0 end)
      ) / 10.0) as pct
    from l
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'company_name', (select company_name from l),

    -- ── §4 COMMAND CENTRE ───────────────────────────────────────────────────────────────────────
    -- The intelligence score is the composite of the four health metrics that are actually
    -- present. coalesce-to-zero is deliberately NOT used: a metric with no data is excluded from
    -- the average rather than dragging it down, so a new supplier is not scored as a bad one.
    'verified', (select coalesce(verified, false) from l),
    'approval_status', (select approval_status from l),
    'intelligence_score', (
      select round(avg(v)) from (
        select (select q_pct from s) as v
        union all select (select reliability    from s)
        union all select (select response_rate  from s)
        union all select (select price_index    from s)
      ) t where v is not null
    ),
    'star_rating', (
      select case when avg(v) is null then null else greatest(1, least(5, round(avg(v) / 20.0))) end
      from (
        select (select q_pct from s) as v
        union all select (select reliability   from s)
        union all select (select response_rate from s)
      ) t where v is not null
    ),

    -- ── §13 SUPPLIER HEALTH — the five bars ─────────────────────────────────────────────────────
    'health', jsonb_build_object(
      -- Quality is the customer-earned rating: verified suppliers only, NULL when unrated.
      -- quality_scale is kept in the payload so a reader can see WHICH source produced it.
      'quality', (select q_pct from s),
      'quality_raw',   (select quality_rating from s),
      'quality_scale', (select case when quality_rating is null then 'unrated' else 'earned_pct' end from s),
      'delivery', (select reliability    from s),
      'response', (select response_rate  from s),
      'pricing',  (select price_index    from s),
      'overall', (
        select round(avg(v)) from (
          select (select q_pct from s) as v
          union all select (select reliability   from s)
          union all select (select response_rate from s)
          union all select (select price_index   from s)
        ) t where v is not null
      ),
      'computed_at',        (select computed_at        from s),
      'avg_response_hours', (select avg_response_hours from s),
      'quotes_submitted',   (select quotes_submitted   from s),
      'quotes_won',         (select quotes_won         from s)
    ),

    -- ── §3 DIGITAL TWIN ─────────────────────────────────────────────────────────────────────────
    'company_strength', (select capability_score from l),
    'capabilities', (
      select jsonb_build_array(
        jsonb_build_object('name', 'Manufacturing', 'has', (select manufacturing from caps)),
        jsonb_build_object('name', 'Installation',  'has', (select installation  from caps)),
        jsonb_build_object('name', 'Maintenance',   'has', (select maintenance   from caps)),
        jsonb_build_object('name', 'Design',        'has', (select design        from caps))
      )
    ),
    'product_count', (
      select case when l.products is null or l.products = '' then 0
             else array_length(string_to_array(l.products, ','), 1) end from l
    ),
    'certifications', (
      select (case when jsonb_typeof(l.iso_certifications)='array' then l.iso_certifications else '[]'::jsonb end)
          || (case when coalesce(l.certifications,'') = '' then '[]'::jsonb
                   else to_jsonb(string_to_array(l.certifications, ',')) end) from l
    ),
    -- NO BACKING COLUMN. Raw inputs plus a labelled estimate, NULL when the inputs are absent.
    'production_capacity', (
      select jsonb_build_object(
        'estimated', case
          when l.team_size is null and l.engineers_count is null and l.warehouse_area is null then null
          else coalesce(l.team_size, 0) * 40 + coalesce(l.engineers_count, 0) * 120
               + coalesce(round(nullif(regexp_replace(coalesce(l.warehouse_area,''), '[^0-9]', '', 'g'), '')::numeric / 10.0), 0) end,
        'is_estimate', true,
        'basis', jsonb_build_object('team_size', l.team_size, 'engineers', l.engineers_count,
                                    'warehouse_area', l.warehouse_area,
                                    'machinery_lines', coalesce(jsonb_array_length(case when jsonb_typeof(l.machinery)='array' then l.machinery else '[]'::jsonb end), 0))
      ) from l
    ),
    'best_opportunities', (
      select case when coalesce(l.categories,'') = '' then '[]'::jsonb
                  else to_jsonb(string_to_array(l.categories, ',')) end from l
    ),
    -- §3 risk level and §17's inputs. Expiry drives it because an expired document is the estate's
    -- own reason for blocking a supplier (fn_reconcile_doc_blocks).
    'risk_level', (
      select case
        when l.banned then 'BANNED'
        when l.matching_blocked then 'BLOCKED'
        when l.license_expiry is not null and l.license_expiry < current_date then 'HIGH'
        when l.iso_expiry     is not null and l.iso_expiry     < current_date then 'HIGH'
        when l.license_expiry is not null and l.license_expiry < current_date + 60 then 'MEDIUM'
        when coalesce(l.chat_strikes, 0) > 0 then 'MEDIUM'
        when (select reliability from s) is not null and (select reliability from s) < 60 then 'MEDIUM'
        else 'LOW' end
      from l
    ),

    -- ── §6 PROFILE ──────────────────────────────────────────────────────────────────────────────
    'established_year', (select founded_year from l),
    'employee_count',   (select coalesce(l.employee_count, l.team_size) from l),
    'countries',        (select coalesce(to_jsonb(coalesce(l.service_emirates, '{}'::text[])), '[]'::jsonb) from l),
    'ai_confidence',    (select pct from conf),
    -- §6's capability map: a root category with capability children, as a graph rather than a list.
    'capability_map', (
      select jsonb_build_object(
        'root', coalesce(l.sector, 'Supplier'),
        'children', (
          select jsonb_agg(jsonb_build_object('name', c.name))
          from (
            select 'Manufacturing' as name where (select manufacturing from caps)
            union all select 'Installation' where (select installation from caps)
            union all select 'Maintenance'  where (select maintenance  from caps)
            union all select 'Design'       where (select design       from caps)
          ) c
        )
      ) from l
    ),

    -- ── §16 DOCUMENT INTELLIGENCE — status and expiry, per document ─────────────────────────────
    'documents', (
      select jsonb_agg(d) from (
        select jsonb_build_object(
          'kind', 'Trade licence', 'expiry', l.license_expiry,
          'doc_status', case when l.license_doc_path is null then 'MISSING'
                             when l.license_expiry is null then 'UNDATED'
                             when l.license_expiry < current_date then 'EXPIRED'
                             else 'VALID' end) as d from l
        union all
        select jsonb_build_object(
          'kind', 'ISO certification', 'expiry', l.iso_expiry,
          'doc_status', case when l.iso_doc_path is null then 'MISSING'
                             when l.iso_expiry is null then 'UNDATED'
                             when l.iso_expiry < current_date then 'EXPIRED'
                             else 'VALID' end) from l
        union all
        select jsonb_build_object(
          'kind', 'Manufacturer authorisation', 'expiry', l.manufacturer_auth_expiry,
          'doc_status', case when l.manufacturer_auth_doc_path is null then 'MISSING'
                             when l.manufacturer_auth_expiry is null then 'UNDATED'
                             when l.manufacturer_auth_expiry < current_date then 'EXPIRED'
                             else 'VALID' end) from l
      ) docs
    ),

    -- The demo fence, surfaced so the UI can label a fixture as a fixture rather than pass it off
    -- as a live account. A demo row that looks real on screen is the harm this whole fence exists
    -- to prevent, arriving one layer higher up.
    'is_demo', (select coalesce(l.matching_blocked, false)
                       and coalesce(array_to_string(l.tags, ','), '') ilike '%demo%' from l),
    'matchable', (select public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                          l.approval_status, l.permanently_closed, l.chat_strikes) from l)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_workspaces(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with rel as (
    -- One row per customer relationship this supplier actually has: an inquiry they were matched
    -- to, or one they have exchanged messages about.
    select distinct i.id as inquiry_id
    from public.inquiries i
    where exists (select 1 from public.inquiry_matches m
                  where m.inquiry_id = i.id and m.supplier_id = p_lead_id)
       or exists (select 1 from public.messages g
                  where g.inquiry_id = i.id and g.supplier_id = p_lead_id)
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'count', (select count(*) from rel),
    -- The populations behind an empty list, so nobody has to guess whether the query worked.
    'population', jsonb_build_object(
      'inquiries', (select count(*) from public.inquiries),
      'matches_for_me', (select count(*) from public.inquiry_matches where supplier_id = p_lead_id)
    ),
    'note', case when (select count(*) from rel) = 0
                 then 'no customer relationships yet — nothing has been matched or messaged'
                 else null end,
    'workspaces', (
      select coalesce(jsonb_agg(w order by w->>'last_activity' desc nulls last), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'inquiry_id', i.id,
          -- §18's project identity.
          'project', jsonb_build_object(
            -- inquiries has no `title` column. The human-readable name is the summary, then the
            -- category, then the RFQ number — falling through in that order means a workspace
            -- always has a name rather than rendering as blank.
            'title', coalesce(nullif(btrim(coalesce(i.summary, '')), ''), i.category,
                              'RFQ ' || coalesce(i.rfq_no::text, i.id::text)),
            'category', i.category,
            'emirate', i.emirate,
            'status', i.status,
            'created_at', i.created_at
          ),
          -- §18's files, CATEGORISED. The spec names drawings, specifications and contracts, so the
          -- bucket is derived from the document's own kind rather than left as one undifferentiated
          -- pile — a workspace whose files are a flat list is the thing §18 replaces.
          'files', (
            select coalesce(jsonb_agg(jsonb_build_object(
              'name', d.file_name, 'kind', d.kind, 'created_at', d.created_at,
              'category', case
                when d.kind ~* 'drawing|dwg|plan|layout'        then 'drawings'
                when d.kind ~* 'spec|datasheet|boq|schedule'    then 'specifications'
                when d.kind ~* 'contract|agreement|po|purchase' then 'contracts'
                else 'other' end
            ) order by d.created_at desc), '[]'::jsonb)
            from public.documents d
            where d.ref_table = 'inquiries' and d.ref_id = i.id::text
          ),
          'file_categories', (
            select jsonb_build_object(
              'drawings', count(*) filter (where d.kind ~* 'drawing|dwg|plan|layout'),
              'specifications', count(*) filter (where d.kind ~* 'spec|datasheet|boq|schedule'),
              'contracts', count(*) filter (where d.kind ~* 'contract|agreement|po|purchase'),
              'other', count(*) filter (where d.kind !~* 'drawing|dwg|plan|layout|spec|datasheet|boq|schedule|contract|agreement|po|purchase')
            )
            from public.documents d
            where d.ref_table = 'inquiries' and d.ref_id = i.id::text
          ),
          -- §18's message count, and the unread split a supplier actually acts on.
          'message_count', (
            select count(*) from public.messages g
            where g.inquiry_id = i.id and g.supplier_id = p_lead_id and not coalesce(g.blocked, false)
          ),
          'unread', (
            select count(*) from public.messages g
            where g.inquiry_id = i.id and g.supplier_id = p_lead_id
              and g.sender = 'customer' and not coalesce(g.read_by_supplier, false)
              and not coalesce(g.blocked, false)
          ),
          'last_activity', (
            select max(g.created_at) from public.messages g
            where g.inquiry_id = i.id and g.supplier_id = p_lead_id
          ),
          -- §18's timeline percentage. Derived from the stages the relationship has actually
          -- passed, so it moves for a real reason and is null before anything has happened rather
          -- than sitting at a meaningless 0%.
          'timeline', (
            select jsonb_build_object(
              'pct', case when total = 0 then null else round(100.0 * hit / total) end,
              'stages', jsonb_build_object(
                'matched', matched, 'messaged', messaged, 'quoted', quoted, 'awarded', awarded)
            )
            from (
              select 4 as total,
                (exists (select 1 from public.inquiry_matches m where m.inquiry_id = i.id and m.supplier_id = p_lead_id))::int
                  as matched,
                (exists (select 1 from public.messages g where g.inquiry_id = i.id and g.supplier_id = p_lead_id))::int
                  as messaged,
                (exists (select 1 from public.quotes q where q.inquiry_id = i.id and q.supplier_id = p_lead_id))::int
                  as quoted,
                (exists (select 1 from public.quotes q where q.inquiry_id = i.id and q.supplier_id = p_lead_id
                         and q.status = 'won'))::int as awarded
            ) s, lateral (select (s.matched + s.messaged + s.quoted + s.awarded) as hit) h
          )
        ) as w
        from rel r join public.inquiries i on i.id = r.inquiry_id
      ) t
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_suppliers_board(p_search text DEFAULT ''::text, p_sector text DEFAULT ''::text, p_limit integer DEFAULT 60, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select l.id, l.company_name,
      coalesce(nullif(trim(l.sector),''),'general') as sector,
      coalesce(nullif(trim(l.emirate),''),'—') as emirate,
      coalesce(l.rating, l.app_rating) as rating,
      l.verified, (l.approved_at is not null) as approved, l.banned,
      (l.invited_at is not null) as invited, l.claimed, (l.registration_submitted_at is not null) as registered,
      coalesce(l.capability_score,0) as capability_score, l.created_at,
      case when l.approved_at is not null then 'approved' when l.verified then 'verified'
           when l.registration_submitted_at is not null then 'registered' when l.invited_at is not null then 'invited'
           when l.contacted then 'contacted' else 'sourced' end as stage
    from leads l
    where (coalesce(p_search,'') = '' or l.company_name ilike '%'||p_search||'%' or l.sector ilike '%'||p_search||'%' or l.emirate ilike '%'||p_search||'%')
      and (coalesce(p_sector,'') = '' or l.sector = p_sector)
  ),
  ranked as (select *, row_number() over (partition by stage order by created_at desc, id desc) as rn from base),
  stagecounts as (select stage, count(*) as c from base group by stage)
  select jsonb_build_object(
    'total', (select count(*) from base),
    'stages', (
      select jsonb_agg(jsonb_build_object('key', s.key, 'label', s.label,
        'count', coalesce((select c from stagecounts sc where sc.stage=s.key),0),
        'cards', coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'company_name',r.company_name,'sector',r.sector,'emirate',r.emirate,'rating',r.rating,'verified',r.verified,'approved',r.approved,'banned',r.banned,'capability_score',r.capability_score) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
        order by s.ord)
      from (values ('sourced','Sourced',1),('contacted','Contacted',2),('invited','Invited',3),('registered','Registered',4),('verified','Verified',5),('approved','Approved',6)) s(key,label,ord)
    ),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'company_name',b.company_name,'sector',b.sector,'emirate',b.emirate,'rating',b.rating,'verified',b.verified,'approved',b.approved,'banned',b.banned,'invited',b.invited,'registered',b.registered,'stage',b.stage,'capability_score',b.capability_score,'created_at',b.created_at) order by b.created_at desc, b.id desc),'[]'::jsonb)
             from (select * from base order by created_at desc, id desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b),
    'sectors', (select coalesce(jsonb_agg(jsonb_build_object('label',x.sector,'n',x.n) order by x.n desc),'[]'::jsonb) from (select sector, count(*) n from base group by sector order by count(*) desc limit 12) x)
  ) into out;
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_anonymity_scan(p_text text, p_subject text, p_attachment_ref text, p_supplier_lead_id bigint, p_quote_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s record; v_hay text; v_hits text[] := '{}'; v_digits text;
begin
  v_hay := lower(coalesce(p_text,'') || ' ' || coalesce(p_subject,'') || ' ' || coalesce(p_attachment_ref,''));

  select company_name, email, phone, trade_license_no into s from public.leads where id = p_supplier_lead_id;
  if not found then
    return jsonb_build_object('safe', false, 'reason',
      'the supplier row could not be read, so nothing about it could be checked for', 'hits', '[]'::jsonb);
  end if;

  if coalesce(btrim(s.company_name),'') <> '' and position(lower(btrim(s.company_name)) in v_hay) > 0
    then v_hits := array_append(v_hits, 'company_name'); end if;
  if coalesce(btrim(s.email),'') <> '' and position(lower(btrim(s.email)) in v_hay) > 0
    then v_hits := array_append(v_hits, 'email'); end if;
  v_digits := regexp_replace(coalesce(s.phone,''), '[^0-9]', '', 'g');
  if length(v_digits) >= 7 and position(v_digits in regexp_replace(v_hay, '[^0-9]', '', 'g')) > 0
    then v_hits := array_append(v_hits, 'phone'); end if;
  if coalesce(btrim(s.trade_license_no),'') <> '' and position(lower(btrim(s.trade_license_no)) in v_hay) > 0
    then v_hits := array_append(v_hits, 'trade_license_no'); end if;

  if p_quote_id is not null then
    if exists (select 1 from public.quotes q
                where q.id::text = p_quote_id and q.quote_amount is not null
                  and position(regexp_replace(round(q.quote_amount)::text, '[^0-9]', '', 'g')
                               in regexp_replace(v_hay, '[^0-9]', '', 'g')) > 0)
      then v_hits := array_append(v_hits, 'quoted_amount'); end if;
  end if;

  return jsonb_build_object(
    'safe', array_length(v_hits, 1) is null,
    'hits', to_jsonb(v_hits),
    'checked', jsonb_build_array('company_name','email','phone','trade_license_no','quoted_amount'),
    'scanned_at', now(),
    'note', case when array_length(v_hits,1) is null
                 then 'No supplier-identifying or commercial value from the live row appears in the subject, body or attachment name.'
                 else 'REFUSED: the message contains ' || array_to_string(v_hits, ', ') || ' from the live supplier row.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_answer_identity_challenge(p_sender_ref text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ch record; v_filed int := 0;
begin
  select * into ch from public.support_identity_challenge
   where sender_ref = p_sender_ref and consumed_at is null
   order by created_at desc limit 1 for update;

  if not found then
    return jsonb_build_object('ok', false, 'verified', false, 'reason', 'no_open_challenge',
      'message', 'I do not have a code outstanding for you. Send me the email address you registered with and I will start again.');
  end if;

  if ch.expires_at <= now() then
    update public.support_identity_challenge
       set consumed_at = now(), outcome = 'expired' where challenge_id = ch.challenge_id;
    return jsonb_build_object('ok', true, 'verified', false, 'reason', 'expired',
      'message', 'That code has expired. Send me the email address again and I will issue a fresh one.');
  end if;

  if ch.attempts >= 4 then
    update public.support_identity_challenge
       set attempts = ch.attempts + 1, consumed_at = now(), outcome = 'exhausted'
     where challenge_id = ch.challenge_id;
    return jsonb_build_object('ok', true, 'verified', false, 'reason', 'exhausted',
      'message', 'Too many attempts on that code, so I have cancelled it. Send me the email address again for a new one.');
  end if;

  if encode(sha256(convert_to(btrim(p_code) || '|' || ch.lead_id::text, 'UTF8')), 'hex') <> ch.code_hash then
    update public.support_identity_challenge
       set attempts = ch.attempts + 1 where challenge_id = ch.challenge_id;
    return jsonb_build_object('ok', true, 'verified', false, 'reason', 'wrong_code',
      'attempts_left', 4 - ch.attempts,
      'message', 'That code does not match. Please check the email and try again.');
  end if;

  update public.support_identity_challenge
     set consumed_at = now(), outcome = 'verified' where challenge_id = ch.challenge_id;

  -- NOTE ON THE ORDERING BELOW: received_at alone is not a tie-break. Two documents that arrive in
  -- the SAME transaction carry the same now(), so "the latest licence" was decided by whichever row
  -- the planner returned first. The intake_id settles it, and the probe that caught this is the
  -- reason the tie-break is here rather than a comment saying it cannot happen.
  -- NOW the held documents may be filed -- and only the ones this sender actually sent, on this
  -- channel. Verifying an identity does not adopt every orphan document in the table.
  update public.support_document_intake i
     set lead_id = ch.lead_id, attached = classified_as <> 'unknown',
         attach_note = case when classified_as = 'unknown'
           then 'Owner confirmed by identity challenge; type still unknown, so still held.'
           else format('Attached as %s to lead %s after identity challenge %s.', classified_as, ch.lead_id, ch.challenge_id) end
   where i.sender_ref = p_sender_ref and i.lead_id is null;
  get diagnostics v_filed = row_count;

  update public.leads l set
    license_doc_path = coalesce((select storage_path from public.support_document_intake
      where lead_id = ch.lead_id and classified_as = 'licence' order by received_at desc, intake_id desc limit 1), l.license_doc_path),
    company_profile_doc_path = coalesce((select storage_path from public.support_document_intake
      where lead_id = ch.lead_id and classified_as = 'profile' order by received_at desc, intake_id desc limit 1), l.company_profile_doc_path),
    signed_terms_path = coalesce((select storage_path from public.support_document_intake
      where lead_id = ch.lead_id and classified_as = 'signed_terms' order by received_at desc, intake_id desc limit 1), l.signed_terms_path)
  where l.id = ch.lead_id;

  -- The same rule at the other door: the owner was unknown when the document arrived, so the chase
  -- could not be stopped then. It is stopped now, at the moment the account is proven.
  perform public.fn_licence_ask_close_for_lead(ch.lead_id, 'identity_challenge', null);

  return jsonb_build_object('ok', true, 'verified', true, 'lead_id', ch.lead_id,
    'documents_released', v_filed,
    'mandatory', public.fn_supplier_mandatory_check(ch.lead_id),
    'message', 'Confirmed, thank you. I have filed the document you sent against your account.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_artifact_attachable(p_artifact_id bigint, p_for_party_id text, p_max_bytes bigint DEFAULT 15000000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a record;
begin
  select * into a from public.support_artifact where artifact_id = p_artifact_id;
  if not found then
    return jsonb_build_object('attachable', false, 'reason', 'unavailable',
      'note', 'no such artifact. Send the portal route and open a repair; do not describe a file that does not exist.');
  end if;
  if a.obsolete_at is not null then
    return jsonb_build_object('attachable', false, 'reason', 'obsolete',
      'note', 'this export was superseded. Attaching it would deliver an answer the company has already replaced.');
  end if;
  if a.privacy_state <> 'approved' then
    return jsonb_build_object('attachable', false, 'reason', 'unsafe',
      'note', format('privacy_state is %L. Only an artifact whose check RAN and passed may be attached.', a.privacy_state));
  end if;
  -- PER-PARTY ENTITLEMENT. "A payment for one supplier never reveals all suppliers; use
  -- per-customer, per-inquiry, per-supplier entitlements."
  if a.owner_party_id is not null and p_for_party_id is not null and a.owner_party_id <> p_for_party_id then
    return jsonb_build_object('attachable', false, 'reason', 'not_entitled',
      'note', 'this artifact belongs to a different party. Ownership is checked per artifact, not per payment.');
  end if;
  if a.byte_size is not null and a.byte_size > p_max_bytes then
    return jsonb_build_object('attachable', false, 'reason', 'oversized',
      'note', format('%s bytes exceeds the channel limit of %s. A link is the honest fallback and must be described as one.', a.byte_size, p_max_bytes));
  end if;
  return jsonb_build_object('attachable', true, 'checksum', a.checksum, 'version', a.version,
    'storage_path', a.storage_path,
    'note', 'Attachable. The message may say "attached" only because a file is genuinely going with it.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_context(p_query text, p_max_chars integer DEFAULT 12000, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; v_out jsonb := '[]'::jsonb; v_used int := 0; v_n int := 0; v_how text;
begin
  for r in select * from public.fn_support_knowledge_search(p_query, p_limit) loop
    exit when v_used + length(r.body) > greatest(1500, p_max_chars);
    v_how := coalesce(v_how, r.matched_how);
    v_out := v_out || jsonb_build_object(
      'record_id', r.record_id, 'record_kind', r.record_kind, 'title', r.title,
      'body', r.body, 'source_ids', to_jsonb(r.source_ids), 'review_status', r.review_status,
      'relevance', r.relevance, 'matched_how', r.matched_how, 'warning', r.warning);
    v_used := v_used + length(r.body); v_n := v_n + 1;
  end loop;

  return jsonb_build_object(
    'query', p_query,
    -- PINNED EVERY TIME, never retrieved and never rankable. These are the rules that must hold
    -- when the retrieval finds nothing, which is exactly when an agent is most tempted to improvise.
    'invariants', jsonb_build_array(
      'Never say you checked, sent, escalated, fixed, refunded or approved anything without tool evidence for it.',
      'A tool error means "cannot verify right now". It never means "no inquiry", "unpaid" or "no discount".',
      'Never reveal a supplier name, contact, logo, amount or quotation content in a notification. The quotation stays in the portal, including after a reveal payment.',
      'Never invent a fee, discount, promotion, policy, deadline or guaranteed outcome.',
      'A supplied email, number or reference is a search clue, never proof of account ownership.',
      'Never request a password, full card number or a banking OTP.',
      'Identify as QuotesDone Support. Never impersonate a person and never claim to be human.',
      'Escalation goes to the CEO. Never to the founder, and never to an invented department.'),
    'advisory_records', v_out,
    'record_count', v_n,
    'matched_how', v_how,
    'sufficient', v_n > 0,
    -- The caller fills this from the database. It is named rather than left implicit so that a
    -- caller who forgets it produces an obviously empty slot instead of a confident general answer.
    'account_facts', null,
    'account_facts_note', 'The CALLER must fill account_facts from authorised live data. Advisory records never contain this customer''s facts.',
    'signal', case when v_n = 0
                   then 'NO ADVISORY COVERAGE for this query. Answer from company policy and live account facts, or say you will check. Do not improvise from these records.'
                   else 'Advisory guidance only. Account facts come from the database.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_deliver_artifact(p_artifact_id bigint, p_case_id bigint, p_recipient_party_id text, p_whatsapp text, p_email text, p_inquiry_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a record; e jsonb; v_portal text; v_body text; v_subject text; v_attach text;
  v_out jsonb := '[]'::jsonb; v_dedupe text; v_id bigint; v_grant jsonb;
begin
  v_grant := public.fn_support_may_act('notification');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason');
  end if;

  select * into a from public.support_artifact where artifact_id = p_artifact_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such artifact'); end if;

  e := public.fn_support_artifact_attachable(p_artifact_id, p_recipient_party_id);
  v_portal := coalesce((select value from public.app_secrets where key = 'public_site_url'), 'https://quotesdone.com') || '/portal';

  if (e->>'attachable') = 'true' then
    v_attach := a.storage_path;
    v_body := case a.artifact_kind
      when 'comparison_report' then
        'Your comparison report for inquiry ' || p_inquiry_ref || ' is ready. A copy is attached, and you can view it in your portal: '
        || v_portal || '. Individual quotations are available in the portal.'
      else
        'Your reveal-fee payment for inquiry ' || p_inquiry_ref || ' has been confirmed. Your invoice ' || coalesce(a.subject_ref,'')
        || ' is attached. You can also access it in your portal: ' || v_portal || '.' end;
  else
    -- THE WORDING CHANGES BECAUSE THE FACT CHANGED. Not a softened version of the same sentence: the
    -- word "attached" is absent, the reason is stated, and the message says where the file is.
    v_attach := null;
    v_body := case a.artifact_kind
      when 'comparison_report' then
        'Your comparison report for inquiry ' || p_inquiry_ref || ' is ready. I could not include a copy with this message ('
        || (e->>'reason') || '), so please open it in your portal: ' || v_portal || '.'
      else
        'Your reveal-fee payment for inquiry ' || p_inquiry_ref || ' has been confirmed. I could not include the invoice with this message ('
        || (e->>'reason') || '), so please open it in your portal: ' || v_portal || '.' end;
  end if;
  v_subject := case a.artifact_kind when 'comparison_report'
                 then 'Your comparison report for inquiry ' || p_inquiry_ref
                 else 'Your invoice for inquiry ' || p_inquiry_ref end;

  -- THE DEDUPE KEY IS THE ARTIFACT PLUS ITS CHECKSUM. A re-send of the same file to the same person
  -- is silently absorbed; a REGENERATED file has a different checksum and is therefore a different
  -- delivery rather than a duplicate.
  if coalesce(btrim(p_whatsapp),'') <> '' then
    insert into public.support_notification (dedupe_key, case_id, purpose, channel, recipient,
      inquiry_ref, publication_version, subject, body, attachment_ref, anonymity_checked_at, anonymity_result)
    values ('artifact|' || p_artifact_id::text || '|' || coalesce(a.checksum,'nocs') || '|whatsapp|' || p_whatsapp,
            p_case_id, a.artifact_kind, 'whatsapp', p_whatsapp, p_inquiry_ref, a.version,
            null, v_body, v_attach, now(),
            jsonb_build_object('safe', true, 'note', 'deterministic artifact delivery; the artifact itself carries its own privacy result', 'artifact_privacy', a.privacy_result))
    on conflict (dedupe_key) do nothing returning id into v_id;
    v_out := v_out || jsonb_build_object('channel','whatsapp','queued', v_id is not null, 'attached', v_attach is not null);
  end if;

  if coalesce(btrim(p_email),'') <> '' then
    insert into public.support_notification (dedupe_key, case_id, purpose, channel, recipient,
      inquiry_ref, publication_version, subject, body, attachment_ref, anonymity_checked_at, anonymity_result)
    values ('artifact|' || p_artifact_id::text || '|' || coalesce(a.checksum,'nocs') || '|email|' || p_email,
            p_case_id, a.artifact_kind, 'email', p_email, p_inquiry_ref, a.version,
            v_subject, v_body, v_attach, now(),
            jsonb_build_object('safe', true, 'note', 'deterministic artifact delivery; the artifact itself carries its own privacy result', 'artifact_privacy', a.privacy_result))
    on conflict (dedupe_key) do nothing returning id into v_id;
    v_out := v_out || jsonb_build_object('channel','email','queued', v_id is not null, 'attached', v_attach is not null);
  end if;

  return jsonb_build_object(
    'ok', true, 'artifact_id', p_artifact_id, 'attachable', e->>'attachable',
    'refusal_reason', e->>'reason', 'queued', v_out,
    -- THE COUNT THE SPEC ASKS FOR. "Do not count a portal link as a delivered attachment."
    'file_copy_delivered', (e->>'attachable') = 'true',
    'note', case when (e->>'attachable') = 'true'
                 then 'A copy is attached and the message says so because it is true.'
                 else 'NOT a file-copy delivery. A link was sent instead, the reason was stated to the customer, and this must not be counted as an attachment.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_investigate_refund(p_transaction_id uuid, p_reason text, p_case_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t record; v_grant jsonb; v_id bigint; v_elig text; v_why text; v_prior int;
begin
  v_grant := public.fn_support_may_act('refund');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason', 'route', v_grant->>'route');
  end if;

  select id, quote_amount, reveal_fee, fee_status, refund_status, refund_amount_aed
    into t from public.transactions where id = p_transaction_id;
  if not found then
    -- "A tool error means cannot verify now, not no inquiry." A missing transaction is a real answer;
    -- it is reported as one and not as an ineligibility.
    return jsonb_build_object('ok', false, 'reason',
      'no such transaction. This is not an eligibility finding -- nothing was assessed.');
  end if;

  -- AGGREGATE OVER-REFUNDING. Everything already refunded on this transaction, counted before
  -- anything new is proposed.
  select count(*) into v_prior from public.refund_case
   where transaction_id = p_transaction_id and state in ('succeeded','reconciled','communicated');

  if coalesce(t.fee_status,'') not in ('paid','collected','succeeded') then
    v_elig := 'ineligible';
    v_why := format('the reveal fee is %L, so nothing has settled. There is no payment to refund; this is a settlement question, not a refund one.', coalesce(t.fee_status,'(none)'));
  elsif v_prior > 0 then
    v_elig := 'ineligible';
    v_why := format('%s refund(s) already succeeded on this transaction. A second would be an aggregate over-refund.', v_prior);
  else
    v_elig := 'eligible';
    v_why := 'the reveal fee settled and no prior refund has succeeded on this transaction.';
  end if;

  insert into public.refund_case
    (transaction_id, case_id, state, amount_aed, requested_reason, investigated_at,
     evidence, eligibility, eligibility_reason)
  values
    (p_transaction_id, p_case_id,
     case when v_elig = 'eligible' then 'eligible' else 'ineligible' end,
     coalesce(t.reveal_fee, 0), p_reason, now(),
     jsonb_build_object('fee_status', t.fee_status, 'reveal_fee', t.reveal_fee,
                        'prior_successful_refunds', v_prior, 'read_at', now()),
     v_elig, v_why)
  on conflict do nothing
  returning refund_id into v_id;

  if v_id is null then
    return jsonb_build_object('ok', false, 'duplicate', true, 'reason',
      'a live refund already exists on this transaction. Concurrent remedies are prevented by index, not by hoping.');
  end if;

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'eligibility', v_elig, 'why', v_why,
    'next', case when v_elig = 'eligible'
                 then 'Put it to the CEO. Support investigated; it does not decide.'
                 else 'No decision is needed: the investigation found it ineligible, with the reason recorded.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_knowledge_search(p_query text, p_limit integer DEFAULT 6, p_kind text DEFAULT NULL::text)
 RETURNS TABLE(record_id text, record_kind text, title text, body text, body_sha256 text, source_ids text[], source_path text, review_status text, authority_effect text, contains_synthetic_example boolean, structured_data jsonb, relevance real, matched_how text, warning text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_q tsquery; v_lex text[]; v_found boolean := false; v_how text := 'all_terms';
begin
  if coalesce(btrim(p_query), '') = '' then return; end if;

  v_q := websearch_to_tsquery('english', p_query);
  if v_q is not null then
    select exists (select 1 from public.support_knowledge k
                    where k.runtime_index_eligible and k.search @@ v_q
                      and (p_kind is null or k.record_kind = p_kind)) into v_found;
  end if;

  if not v_found then
    v_lex := tsvector_to_array(to_tsvector('english'::regconfig, p_query));
    if v_lex is null or array_length(v_lex, 1) is null then return; end if;
    begin
      v_q := to_tsquery('english'::regconfig,
               array_to_string(array(select '''' || replace(x, '''', '''''') || '''' from unnest(v_lex) x), ' | '));
    exception when others then return;
    end;
    v_how := 'best_terms';
  end if;

  return query
  select k.record_id, k.record_kind, k.title, k.body, k.body_sha256,
         k.source_ids, k.source_path, k.review_status, k.authority_effect,
         k.contains_synthetic_example, k.structured_data,
         ts_rank(k.search, v_q) as relevance, v_how as matched_how,
         'Advisory only. authority_effect=none: this may not approve a refund, grant an entitlement, '
         || 'change a price or become policy. review_status=' || k.review_status || '. '
         || case when k.record_kind = 'message_template'
                 then 'DRAFT TEMPLATE -- not an approved provider template. Check wa_template_registry before sending. ' else '' end
         || case when k.contains_synthetic_example
                 then 'CONTAINS A SYNTHETIC EXAMPLE -- authored, not a real QuotesDone conversation. ' else '' end
         || case when v_how = 'best_terms'
                 then 'MATCHED ON BEST TERMS, not all of them -- read the title before relying on it. ' else '' end
         || 'Account facts come from the database, never from this record.' as warning
    from public.support_knowledge k
   where k.runtime_index_eligible
     and k.search @@ v_q
     and (p_kind is null or k.record_kind = p_kind)
   order by ts_rank(k.search, v_q) desc, k.record_id
   limit greatest(1, least(coalesce(p_limit, 6), 30));
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_knowledge_search_vector()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.search :=
      setweight(to_tsvector('english'::regconfig, coalesce(new.title,'')), 'A')
   || setweight(to_tsvector('english'::regconfig, coalesce(array_to_string(new.tags,' '),'')), 'B')
   || setweight(to_tsvector('english'::regconfig, coalesce(new.body,'')), 'C');
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_may_act(p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare g record;
begin
  select * into g from public.ceo_standing_grant
   where grantee_role_id = 'customer_support' and action_class = p_action_class and active
     and (expires_at is null or expires_at > now())
   order by issued_at desc limit 1;

  if not found then
    -- NOT a founder question. The constitution is explicit that an uncovered action goes to the CEO.
    return jsonb_build_object('may_act', false, 'route', 'ceo_case_decision',
      'reason', format('No current standing grant covers %L. This needs a scoped CEO decision -- not a founder approval, which does not exist.', p_action_class));
  end if;

  if g.max_amount_aed is not null and p_amount_aed is not null and p_amount_aed > g.max_amount_aed then
    return jsonb_build_object('may_act', false, 'route', 'ceo_case_decision',
      'reason', format('AED %s exceeds the standing limit of AED %s on %L.', p_amount_aed, g.max_amount_aed, g.grant_key));
  end if;

  return jsonb_build_object('may_act', true, 'grant', g.grant_key, 'scope', g.scope_note,
    'limit', g.limit_note);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_notification_sync_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status is distinct from old.status then
    update public.support_notification
       set state = case new.status
             when 'sent'       then 'sent'
             when 'suppressed' then 'suppressed'
             when 'failed'     then 'failed'
             when 'skipped'    then 'suppressed'
             when 'held'       then 'queued'
             else state end,
           sent_at = case when new.status = 'sent' then coalesce(new.sent_at, now()) else sent_at end,
           provider_id = coalesce(new.id::text, provider_id),
           provider_status = new.status,
           attempts = coalesce(new.attempts, attempts),
           -- The provider's own words, kept rather than summarised. A bounce reason is the only
           -- thing that distinguishes "the address is wrong" from "our domain is in trouble".
           failure_reason = case when new.status in ('failed','skipped')
                                 then new.last_error else failure_reason end
     where outbox_id = new.id;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_notification_to_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text; v_id bigint; v_kind text;
begin
  -- WHO IS THIS PERSON TO US. send_outbox routes the from-address, the reply-to, the template and
  -- the unsubscribe header off to_role, so getting it wrong sends a supplier a customer-branded
  -- email from the wrong mailbox. Read from the case rather than guessed.
  select case when c.party_kind = 'supplier' then 'supplier' else 'customer' end
    into v_role
    from public.support_case c where c.case_id = new.case_id;
  v_role := coalesce(v_role, 'customer');

  if new.channel = 'email' then
    if coalesce(btrim(new.recipient), '') = '' then
      new.bridge_note := 'no email address on the row; nothing to hand over';
      return new;
    end if;

    -- THE TYPE CARRIES THE PURPOSE, and that is load-bearing rather than cosmetic: send_outbox
    -- exempts anything matching licence/renew/expiry from the supplier bulk gate, because a
    -- document request is transactional. Passing the purpose through means a licence reminder is
    -- recognised as one instead of being held with the marketing.
    v_kind := coalesce(new.purpose, 'support');

    -- KIND CARRIES THE PURPOSE TOO, and this is not cosmetic. a10_notifications_founder_mail_policy
    -- governs anything addressed to the founder by KIND, reading it before type. An earlier version
    -- of this bridge stamped every row 'support_agent', which collapsed every kind of support mail
    -- into one governance decision: allow the label and he gets all of it, refuse it and he gets
    -- none -- and the policy table could not tell a refund decision from a licence reminder. The
    -- provenance that label was carrying is already on the support_notification row it came from,
    -- so nothing is lost by letting the purpose through.
    insert into public.notifications (type, kind, to_email, to_role, subject, body, status, channel)
    values (v_kind, v_kind, btrim(new.recipient), v_role,
            coalesce(new.subject, 'QuotesDone'), new.body, 'queued', 'email')
    returning id into v_id;

    new.outbox_id := v_id;
    new.bridged_at := now();
    new.bridge_note := format('handed to notifications #%s as a %L to a %s', v_id, v_kind, v_role);

  elsif new.channel = 'whatsapp' then
    -- NOT BRIDGED, AND SAYING SO. send_outbox is email only, and a business-initiated WhatsApp
    -- message needs an approved template and recorded opt-in, which no recipient has yet. Writing
    -- it into an email queue would produce a delivery that never happened; leaving it silent would
    -- be indistinguishable from working. It is held, with the reason on the row.
    new.bridge_note := 'not bridged: WhatsApp is business-initiated here and no recipient has recorded opt-in. '
                    || 'This is held deliberately, not lost. An inbound reply inside the 24-hour window goes '
                    || 'through wa_inbound and does not use this table.';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_notify_new_quotation(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  q record; c record; v_case bigint; v_ref text; v_portal text;
  v_body text; v_subject text; v_scan jsonb;
  v_queued jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb;
  v_dedupe text; v_id bigint;
begin
  -- THE COMMITTED STATE, AND THE CURRENT ONE. Both are required: committed_at proves it was
  -- published, and the status re-read proves it has not been withdrawn since. A quotation withdrawn
  -- between publication and this call must not be announced, and only a fresh read can know that.
  select qq.id, qq.inquiry_id, qq.supplier_id, qq.committed_at, qq.committed_hash, qq.status, qq.anonymized
    into q from public.quotes qq where qq.id = p_quote_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', format('no quotation %s', p_quote_id::text));
  end if;
  if q.committed_at is null then
    return jsonb_build_object('ok', false, 'reason',
      'this quotation is not committed. A draft or a failed upload is not a publication and must never reach a customer.');
  end if;
  if coalesce(q.status,'') in ('withdrawn','cancelled','rejected','expired') then
    return jsonb_build_object('ok', false, 'reason',
      format('the quotation is %L now. It was committed once; it is not visible today, and the customer is not told about it.', q.status));
  end if;

  select i.rfq_no, cu.id cust_id, cu.full_name, cu.phone, cu.email, cu.wa_optin, cu.banned
    into c
    from public.inquiries i
    join public.customers cu on cu.id = i.customer_id
   where i.id = q.inquiry_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason',
      'the inquiry or its owner could not be read. Nothing is sent: a notification with no verified recipient is a message to a guess.');
  end if;
  if coalesce(c.banned, false) then
    return jsonb_build_object('ok', false, 'reason', 'the inquiry owner is banned; no notification is sent.');
  end if;

  -- rfq_no is an INTEGER sequence number. The customer-facing reference is rendered from it when
  -- it exists and from the inquiry id when it does not, so the shape is stable either way.
  v_ref := case when c.rfq_no is not null then 'RFQ-' || c.rfq_no::text
                else 'INQ-' || q.inquiry_id::text end;
  v_portal := coalesce((select value from public.app_secrets where key = 'public_site_url'), 'https://quotesdone.com') || '/portal';

  -- DETERMINISTIC RENDERING. The spec requires it for notifications, and it is also the only way the
  -- anonymity scan means anything: a model could compose a different sentence next time, and the
  -- scan would be checking a message nobody will send.
  v_body := 'You have received a new quotation for inquiry ' || v_ref
         || '. Sign in to your QuotesDone portal to review it: ' || v_portal || '.';
  v_subject := 'A new quotation for inquiry ' || v_ref;

  -- THE SCAN, before anything is queued. It reads the live supplier row and the live quotation, so
  -- it is checking for THIS supplier's actual name, email, phone and amount -- not a word list.
  v_scan := public.fn_support_anonymity_scan(v_body, v_subject, null, q.supplier_id, q.id::text);
  if (v_scan->>'safe') <> 'true' then
    return jsonb_build_object('ok', false, 'blocked', true, 'reason', v_scan->>'note', 'scan', v_scan);
  end if;

  -- The case that owns this conversation.
  insert into public.support_case (case_ref, party_kind, party_id, inquiry_ref, subject)
  values ('case:quote:' || q.id::text, 'customer', c.cust_id::text, v_ref,
          'New quotation published for ' || v_ref)
  on conflict (case_ref) do update set last_activity_at = now()
  returning case_id into v_case;
  if v_case is null then
    select case_id into v_case from public.support_case where case_ref = 'case:quote:' || q.id::text;
  end if;

  -- BOTH CHANNELS, EACH JUDGED ON ITS OWN PERMISSION. The spec: "Check both-channel permissions
  -- independently and record blocked/suppressed outcomes honestly." A missing email is not a reason
  -- to skip WhatsApp, and no consent on WhatsApp is not a reason to skip email.
  --
  -- The dedupe key carries the publication version (committed_hash), so re-committing a changed
  -- quotation notifies again and the same commit arriving twice does not.
  if coalesce(btrim(c.phone),'') <> '' and coalesce(c.wa_optin, false) then
    v_dedupe := 'quote_published|' || q.id::text || '|' || coalesce(q.committed_hash,'nohash') || '|whatsapp|' || c.phone;
    insert into public.support_notification
      (dedupe_key, case_id, purpose, channel, recipient, inquiry_ref, publication_version,
       subject, body, anonymity_checked_at, anonymity_result)
    values (v_dedupe, v_case, 'quote_published', 'whatsapp', c.phone, v_ref, q.committed_hash,
            null, v_body, now(), v_scan)
    on conflict (dedupe_key) do nothing
    returning id into v_id;
    v_queued := v_queued || jsonb_build_object('channel','whatsapp','queued', v_id is not null,
                  'note', case when v_id is null then 'already queued for this publication version' else 'queued' end);
  else
    v_skipped := v_skipped || jsonb_build_object('channel','whatsapp','reason',
      case when coalesce(btrim(c.phone),'') = '' then 'no mobile on the customer record'
           else 'no WhatsApp opt-in recorded' end);
  end if;

  if coalesce(btrim(c.email),'') <> '' then
    v_dedupe := 'quote_published|' || q.id::text || '|' || coalesce(q.committed_hash,'nohash') || '|email|' || c.email;
    insert into public.support_notification
      (dedupe_key, case_id, purpose, channel, recipient, inquiry_ref, publication_version,
       subject, body, anonymity_checked_at, anonymity_result)
    values (v_dedupe, v_case, 'quote_published', 'email', c.email, v_ref, q.committed_hash,
            v_subject, v_body, now(), v_scan)
    on conflict (dedupe_key) do nothing
    returning id into v_id;
    v_queued := v_queued || jsonb_build_object('channel','email','queued', v_id is not null,
                  'note', case when v_id is null then 'already queued for this publication version' else 'queued' end);
  else
    v_skipped := v_skipped || jsonb_build_object('channel','email','reason','no email on the customer record');
  end if;

  return jsonb_build_object(
    'ok', true, 'quote_id', q.id, 'inquiry_ref', v_ref, 'case_id', v_case,
    'publication_version', q.committed_hash,
    'queued', v_queued, 'skipped', v_skipped, 'anonymity', v_scan,
    'note', 'Queued only. Delivery is the sender''s job and its outcome is recorded on the row, never assumed here.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_open_identity_challenge(p_channel text, p_sender_ref text, p_claimed_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lead bigint; v_to text; v_code text; v_id bigint; v_grant jsonb; v_open int;
begin
  v_grant := public.fn_support_may_act('document');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason');
  end if;

  -- RATE LIMIT PER SENDER, not per account. Limiting per account would let a stranger lock a real
  -- supplier out of their own verification by spamming challenges at them.
  select count(*) into v_open from public.support_identity_challenge
   where sender_ref = p_sender_ref and created_at > now() - interval '1 hour';
  if v_open >= 5 then
    return jsonb_build_object('ok', true, 'challenge_opened', false, 'reason', 'rate_limited',
      'message', 'I have sent several codes to this account recently. Please use the most recent one, or try again in an hour.');
  end if;

  select id, email into v_lead, v_to from public.leads
   where lower(email) = lower(btrim(p_claimed_email)) order by id limit 1;

  v_code := lpad((floor(random() * 1000000))::int::text, 6, '0');

  if v_lead is not null then
    insert into public.support_identity_challenge
      (channel, sender_ref, claimed_email, lead_id, sent_to, code_hash, expires_at)
    values (p_channel, p_sender_ref, p_claimed_email, v_lead, v_to,
            encode(sha256(convert_to(v_code || '|' || v_lead::text, 'UTF8')), 'hex'), now() + interval '15 minutes')
    returning challenge_id into v_id;

    insert into public.support_notification (dedupe_key, case_id, purpose, channel, recipient,
      subject, body, anonymity_checked_at, anonymity_result)
    values ('idchallenge|' || v_id::text, null, 'identity_challenge', 'email', v_to,
            'Your QuotesDone confirmation code',
            'Your confirmation code is ' || v_code || '. It expires in 15 minutes. If you did not ask '
            || 'to confirm a document upload, you can ignore this message and nothing will be filed.',
            now(), jsonb_build_object('safe', true, 'note', 'code to the address of record; no counterparty data'));
  end if;

  -- THE SAME ANSWER EITHER WAY. Whether or not that account exists, the sender is told a code was
  -- sent to the address they named. Saying "no account with that email" would turn this into a
  -- free tool for discovering who is registered with us.
  return jsonb_build_object('ok', true, 'challenge_opened', v_lead is not null,
    'message', 'I have sent a 6-digit code to ' || p_claimed_email || '. Reply with the code and I '
            || 'will file your document against that account. The code expires in 15 minutes.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_open_reports()
 RETURNS TABLE(report_id bigint, severity text, subject text, status text, owner_role_id text, age interval, next_review_at timestamp with time zone, attempts integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select r.id, r.severity, r.subject, r.status, r.owner_role_id,
         now() - r.created_at, r.next_review_at, r.delivery_attempts
    from public.support_ceo_report r
   where r.status in ('sent','failed','blocked')
   order by case r.severity when 'critical' then 0 when 'serious' then 1
                            when 'elevated' then 2 else 3 end,
            r.created_at;
$function$


CREATE OR REPLACE FUNCTION public.fn_support_receive_document(p_channel text, p_sender_ref text, p_storage_path text, p_caption text DEFAULT NULL::text, p_media_kind text DEFAULT NULL::text, p_declared text DEFAULT NULL::text, p_lead_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c jsonb; v_lead bigint; v_id bigint; v_note text; v_reply text;
  v_before jsonb; v_after jsonb; v_grant jsonb; v_missing text;
begin
  v_grant := public.fn_support_may_act('document');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason');
  end if;
  if p_channel not in ('email','portal') then
    return jsonb_build_object('ok', false, 'reason',
      'this function serves the email and portal paths; WhatsApp has fn_wa_attach_document.');
  end if;
  if coalesce(btrim(p_storage_path), '') = '' then
    return jsonb_build_object('ok', false, 'reason',
      'no stored file. A receipt for a document that was never stored is the lost-document failure with a friendlier message.');
  end if;

  -- WHO SENT IT. The portal already knows -- the session is the identity, which is why it may pass a
  -- lead directly. Email has only the From address, so it is matched against the address of record.
  if p_channel = 'portal' then
    v_lead := p_lead_id;
  else
    select id into v_lead from public.leads
     where lower(email) = lower(btrim(p_sender_ref)) order by id limit 1;
  end if;

  c := public.fn_document_classify(p_caption, p_storage_path, p_declared);

  if v_lead is not null then v_before := public.fn_supplier_mandatory_check(v_lead); end if;

  if v_lead is null then
    v_note := 'No account matches this sender. Held, and an identity challenge is the only route to attaching it.';
    v_reply := 'Thank you -- I have your file safely. I could not match it to a registered account '
            || 'from this address, so I have not filed it yet. Reply with the email address you '
            || 'registered with and I will send a short code to that address to confirm it is you.';
  elsif (c->>'kind') = 'unknown' then
    v_note := 'Owner known, type not. Held rather than filed on a guess.';
    v_reply := 'Thank you, I have saved that to your file. I could not tell which document it is, so '
            || 'to file it correctly please tell me: is it your trade licence, your company profile, '
            || 'or the signed terms?';
  else
    v_note := format('Attached as %s to lead %s.', c->>'kind', v_lead);
  end if;

  insert into public.support_document_intake
    (channel, sender_ref, lead_id, storage_path, media_kind, caption,
     classified_as, classified_by, confidence, attached, attach_note)
  values (p_channel, p_sender_ref, v_lead, p_storage_path, p_media_kind, p_caption,
          c->>'kind', c->>'by', c->>'confidence',
          v_lead is not null and (c->>'kind') <> 'unknown', coalesce(v_note, ''))
  returning intake_id into v_id;

  if v_lead is not null and (c->>'kind') <> 'unknown' then
    if (c->>'kind') = 'licence' then
      update public.leads set license_doc_path = p_storage_path where id = v_lead;
    elsif (c->>'kind') = 'profile' then
      update public.leads set company_profile_doc_path = p_storage_path where id = v_lead;
    else
      update public.leads set signed_terms_path = p_storage_path where id = v_lead;
    end if;

    -- A LICENCE THAT ARRIVED STOPS THE CHASE FOR IT. Without this the supplier keeps being asked
    -- for a document the company already holds, which is how a chase teaches people we do not read
    -- what they send.
    if (c->>'kind') = 'licence' then
      perform public.fn_licence_ask_close_for_lead(v_lead, p_channel, v_id);
    end if;

    v_after := public.fn_supplier_mandatory_check(v_lead);
    -- THE RECEIPT SAYS WHAT IS STILL MISSING, the same as the WhatsApp path. A receipt that only
    -- confirms arrival leaves the supplier believing they are finished when they are not, which is
    -- how 81 invitations became 0 registrations.
    if coalesce((v_after->>'complete')::boolean, false) then
      v_reply := 'Got it -- your ' || replace(c->>'kind','_',' ') || ' is saved. Your file is now '
              || 'complete and goes for verification. I will let you know when it is approved.';
    else
      select string_agg(value #>> '{}', ', ') into v_missing
        from jsonb_array_elements(v_after->'missing');
      v_reply := 'Got it -- your ' || replace(c->>'kind','_',' ') || ' is saved. Still needed: '
              || coalesce(v_missing, '(nothing listed)') || '. You can send them the same way.';
    end if;
  end if;

  return jsonb_build_object('ok', true, 'intake_id', v_id, 'channel', p_channel,
    'lead_id', v_lead, 'classified_as', c->>'kind', 'confidence', c->>'confidence',
    'attached', v_lead is not null and (c->>'kind') <> 'unknown',
    'needs_identity_challenge', v_lead is null,
    'mandatory_before', v_before, 'mandatory_after', v_after, 'reply', v_reply);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_report_to_ceo(p_idempotency_key text, p_severity text, p_subject text, p_evidence jsonb, p_attempted jsonb, p_requested text, p_case_ref text DEFAULT NULL::text, p_task_ref text DEFAULT NULL::text, p_review_in interval DEFAULT '1 day'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_parent text;
  v_id     bigint;
  v_existing public.support_ceo_report%rowtype;
begin
  -- THE MANAGER IS READ, NOT ASSUMED. The spec: "Inspect the repository and current agent registry
  -- to locate the new CEO... Do not search deleted role records for a replacement manager." If the
  -- edge is gone or the parent is not active, this refuses rather than picking someone.
  select e.parent_role_id into v_parent
    from public.org_reporting_edge e
    join public.org_role r on r.role_id = e.parent_role_id and r.status = 'active'
   where e.child_role_id = 'customer_support';

  if v_parent is null then
    return jsonb_build_object('ok', false, 'reason',
      'No active reporting parent for customer_support. The report is NOT sent and NOT silently '
      || 'redirected: inventing a recipient is how work goes to nobody.');
  end if;

  if coalesce(btrim(p_requested), '') = '' then
    return jsonb_build_object('ok', false, 'reason',
      'requested_outcome is required. A report that does not say what it wants is a notification, '
      || 'and the CEO cannot act on it.');
  end if;

  -- IDEMPOTENT BY THE BUSINESS EVENT. A webhook that fires twice, a retry after a timeout and a
  -- restart mid-flight must all produce ONE report. Returning the existing row is the correct
  -- answer, not an error: the caller's intent was satisfied the first time.
  select * into v_existing from public.support_ceo_report where idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('ok', true, 'duplicate', true, 'report_id', v_existing.id,
      'status', v_existing.status,
      'note', 'This matter was already reported. Returning the original rather than sending a second.');
  end if;

  insert into public.support_ceo_report
    (idempotency_key, source_agent, case_ref, task_ref, severity, subject,
     verified_evidence, attempted_actions, requested_outcome, owner_role_id, next_review_at)
  values
    (p_idempotency_key, 'customer_support', p_case_ref, p_task_ref, p_severity, p_subject,
     p_evidence, coalesce(p_attempted, '[]'::jsonb), p_requested,
     'customer_support',            -- support keeps it until the CEO accepts
     now() + coalesce(p_review_in, interval '1 day'))
  returning id into v_id;

  return jsonb_build_object('ok', true, 'report_id', v_id, 'reported_to', v_parent,
    'owner', 'customer_support',
    'note', 'Sent. Ownership stays with support until the CEO accepts it with a receipt.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_target_baseline(p_contract_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c record;
  v_val numeric;
  v_state text;
  v_note text;
begin
  select * into c from public.target_contract where id = p_contract_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'No such contract.');
  end if;

  if coalesce(btrim(c.measure_sql), '') = '' then
    v_state := 'not_instrumented';
    v_note  := 'NO INSTRUMENT EXISTS. The contract names an authoritative source but carries no measure. '
            || 'This needs an instrument built before it needs a number, and that is not a SQL task.';
    v_val   := null;
  else
    begin
      execute c.measure_sql into v_val;
      if v_val is null then
        v_state := 'unknown';
        v_note  := 'The measure ran and returned NULL. That is an unknown, not a zero.';
      else
        v_state := 'measured';
        v_note  := 'Measured live from the contract''s own measure_sql.';
      end if;
    exception when others then
      -- An error is never a zero. This is the distinction the estate got wrong once already.
      v_state := 'unknown';
      v_val   := null;
      v_note  := 'The measure FAILED and the baseline is therefore unknown, not zero. Error: '
              || left(sqlerrm, 200);
    end;
  end if;

  update public.target_contract
     set baseline_value = v_val,
         baseline_state = v_state,
         baseline_at    = now(),
         baseline_note  = v_note
   where id = p_contract_id;

  return jsonb_build_object(
    'ok', true,
    'contract_id', p_contract_id,
    'baseline_value', v_val,
    'baseline_state', v_state,
    'baseline_at', now(),
    'note', v_note
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_target_feasibility(p_contract_id bigint, p_record boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c            record;
  d            record;
  v_days       int;
  v_remaining  numeric;
  v_cum_rate   numeric := 1.0;
  v_down_rate  numeric := 1.0;
  v_up_rate    numeric := 1.0;
  v_total_lag  int := 0;
  v_measured   int := 0;
  v_assumed    int := 0;
  v_stages     int := 0;
  v_top        numeric;
  v_top_down   numeric;
  v_top_up     numeric;
  v_binding    text := null;
  v_binding_why text := null;
  v_cap_limit  numeric;
  v_cost       numeric := 0;
  v_headroom   numeric;
  v_verdict    text;
  v_reason     text;
  v_changes    text[] := '{}';
  v_run_rate   numeric;
  v_required   numeric;
  v_eta        date;
  v_chain      jsonb := '[]'::jsonb;
  -- Stages that declare NO capacity ceiling. Treating an undeclared capacity as an infinite one is
  -- how this function first blessed 16,129 invitations in 30 days from a list of 19,896 addresses on
  -- a domain already bouncing at 10%. Silence about a ceiling is not evidence of headroom.
  v_undeclared text[] := '{}';
  -- THE SAFETY ENVELOPE. A channel's safe throughput is a property of the channel, not of how badly
  -- we want the target. Budget and internal capacity are negotiable; sender reputation is not, because
  -- losing it costs every sign-in code and receipt that shares the domain. So this overrides.
  v_chan       jsonb;
  v_chan_block text := null;
  v_chan_why   text := null;
  v_chan_safe  numeric;
begin
  select * into c from public.target_contract where id = p_contract_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'No such contract.');
  end if;

  v_days := greatest(0, (c.deadline - (now() at time zone c.timezone)::date));

  -- Remaining outcome. For an incremental target the baseline does not subtract.
  if c.desired_basis = 'incremental' then
    v_remaining := c.desired_value;
  else
    v_remaining := c.desired_value - coalesce(c.baseline_value, 0);
  end if;

  -- Walk the chain. cum_rate is the product of every stage's conversion, so the top of funnel
  -- required is remaining / cum_rate.
  for d in
    select * from public.target_driver where contract_id = p_contract_id order by stage_order
  loop
    v_stages := v_stages + 1;
    v_cum_rate := v_cum_rate * d.rate;

    -- Downside and upside bracket an assumed rate by half and double, bounded at 1. A measured rate
    -- is bracketed far more tightly, because we actually know it.
    if d.rate_source = 'measured' then
      v_measured := v_measured + 1;
      v_down_rate := v_down_rate * greatest(d.rate * 0.75, 0.0001);
      v_up_rate   := v_up_rate   * least(d.rate * 1.25, 1.0);
    else
      v_assumed := v_assumed + 1;
      v_down_rate := v_down_rate * greatest(d.rate * 0.5, 0.0001);
      v_up_rate   := v_up_rate   * least(d.rate * 2.0, 1.0);
    end if;

    v_total_lag := v_total_lag + d.lag_days;

    v_chain := v_chain || jsonb_build_object(
      'stage', d.stage_key,
      'label', d.stage_label,
      'rate', d.rate,
      'rate_source', d.rate_source,
      'lag_days', d.lag_days,
      'capacity_per_day', d.capacity_per_day,
      'unit_cost', d.unit_cost
    );
  end loop;

  -- No chain means no model. Say so rather than inventing one.
  if v_stages = 0 then
    v_verdict := 'CANNOT_ASSESS';
    v_reason  := 'No driver model exists for this contract. Without a causal chain there is no way to '
              || 'say what volume of activity produces the outcome, and any number would be invented.';
    v_changes := array['Build the driver model: name each stage from controllable activity to outcome, with its rate and whether that rate was measured or assumed.'];
  elsif c.baseline_state <> 'measured' then
    v_verdict := 'CANNOT_ASSESS';
    v_reason  := 'The baseline is ' || c.baseline_state || '. A gap cannot be computed from an unknown '
              || 'starting point, and treating it as zero is the error this column exists to prevent.';
    v_changes := array['Instrument the baseline, or record explicitly that it is a measured zero.'];
  end if;

  v_top      := case when v_cum_rate  > 0 then v_remaining / v_cum_rate  else null end;
  v_top_down := case when v_down_rate > 0 then v_remaining / v_down_rate else null end;
  v_top_up   := case when v_up_rate   > 0 then v_remaining / v_up_rate   else null end;

  -- Cost: sum the unit cost of every stage against the volume that stage must carry.
  declare
    v_vol numeric := v_top;
  begin
    for d in select * from public.target_driver where contract_id = p_contract_id order by stage_order loop
      if d.unit_cost is not null and v_vol is not null then
        v_cost := v_cost + (v_vol * d.unit_cost);
      end if;
      if v_vol is not null then v_vol := v_vol * d.rate; end if;
    end loop;
  end;

  -- Capacity: the first stage whose per-day ceiling cannot carry its required volume in the time left
  -- is the binding constraint. Lag is subtracted, because a stage that takes 7 days to convert does
  -- not get all 30 days of runway.
  declare
    v_vol numeric := v_top;
    v_usable_days int;
  begin
    for d in select * from public.target_driver where contract_id = p_contract_id order by stage_order loop
      v_usable_days := greatest(1, v_days - v_total_lag);
      if d.capacity_per_day is not null and v_vol is not null then
        v_cap_limit := d.capacity_per_day * v_usable_days;
        if v_vol > v_cap_limit and v_binding is null then
          v_binding := d.stage_key;
          v_binding_why := format(
            'Stage %s must carry %s units but its ceiling is %s per day over %s usable days, which is %s.',
            d.stage_key, round(v_vol, 1), d.capacity_per_day, v_usable_days, round(v_cap_limit, 1));
        end if;
      elsif d.capacity_per_day is null and d.channel_key is null then
        v_undeclared := array_append(v_undeclared,
          format('%s (must carry %s over %s usable days)', d.stage_key, round(coalesce(v_vol,0),0), v_usable_days));
      end if;

      -- The channel check. A stage that names a channel is capped by that channel's policy no matter
      -- what the budget or the internal capacity allows.
      if d.channel_key is not null and v_vol is not null then
        v_chan := public.fn_channel_safe_volume(d.channel_key, v_vol, v_usable_days);
        if coalesce((v_chan->>'ok')::boolean, false) = false and v_chan_block is null then
          v_chan_block := d.stage_key;
          v_chan_safe  := (v_chan->>'safe_max')::numeric;
          v_chan_why   := v_chan->>'reason';
        end if;
      end if;
      if v_vol is not null then v_vol := v_vol * d.rate; end if;
    end loop;
  end;

  v_headroom := case when c.budget_amount is null then null else c.budget_amount - v_cost end;

  -- Run rate so far, and the pace required from here.
  v_run_rate := case when c.baseline_at is not null and c.activated_at is not null
                       and c.baseline_at > c.activated_at
                     then coalesce(c.baseline_value,0) / greatest(1, extract(day from c.baseline_at - c.activated_at))
                     else null end;
  v_required := case when v_days > 0 then v_remaining / v_days else null end;
  v_eta := case when v_run_rate is not null and v_run_rate > 0
                then (now() at time zone c.timezone)::date + ceil(v_remaining / v_run_rate)::int
                else null end;

  -- The verdict, if the two hard refusals above did not already set it.
  if v_verdict is null then
    -- THE SAFETY ENVELOPE IS CHECKED FIRST, because it is the only constraint that cannot be bought
    -- out of. A cheaper plan, a longer deadline or more staff do not restore a blacklisted domain.
    if v_chan_block is not null then
      v_verdict := 'NOT_ACHIEVABLE';
      v_reason  := 'The channel that carries this plan cannot carry it safely. ' || v_chan_why;
      v_changes := array_append(v_changes, format(
        'Cap stage %s at %s, which is what the channel can safely carry, and make up the difference on '
        || 'another channel or renegotiate the target. Raising the volume is not an option here: budget '
        || 'and capacity are negotiable, sender reputation is not.',
        v_chan_block, round(coalesce(v_chan_safe,0),0)));
      v_changes := array_append(v_changes,
        'Open a separate outreach domain and warm it, so cold volume never shares a reputation with sign-in codes and receipts.');
    elsif v_binding is not null then
      v_verdict := 'NOT_ACHIEVABLE';
      v_reason  := 'A capacity ceiling binds before the deadline. ' || v_binding_why;
      v_changes := array_append(v_changes, format('Raise capacity at stage %s, extend the deadline, or reduce the desired value.', v_binding));
    elsif c.budget_amount is not null and v_cost > c.budget_amount then
      v_verdict := 'NOT_ACHIEVABLE';
      v_reason  := format('The plan costs %s against a budget of %s, so it cannot be funded as designed.',
                          round(v_cost,2), c.budget_amount);
      v_changes := array_append(v_changes, format('Raise the budget to %s, improve a conversion rate, or reduce the desired value.', round(v_cost,2)));
    elsif array_length(v_undeclared, 1) > 0 then
      -- An undeclared ceiling is not headroom. Say the volume out loud and make someone declare it.
      v_verdict := 'AT_RISK';
      v_reason  := format('The arithmetic is fundable, but %s stage(s) declare no capacity ceiling: %s. '
                       || 'An undeclared ceiling is an unchecked assumption, not evidence of headroom, and it is '
                       || 'exactly how a plan that looks affordable turns out to be physically impossible.',
                          array_length(v_undeclared,1), array_to_string(v_undeclared, '; '));
      v_changes := array_append(v_changes,
        format('Declare a real capacity_per_day for: %s. If the true ceiling cannot carry the volume, the target changes, not the ceiling.',
               array_to_string(v_undeclared, ', ')));
    elsif v_measured = 0 then
      v_verdict := 'AT_RISK';
      v_reason  := format('The chain is arithmetically fundable and within capacity, but every one of its %s '
                       || 'rates is assumed rather than measured here. The plan is a hypothesis, not a forecast.', v_stages);
      v_changes := array_append(v_changes, 'Measure at least the first conversion rate on a small controlled batch before scaling.');
    elsif v_assumed > v_measured then
      v_verdict := 'AT_RISK';
      v_reason  := format('%s of %s rates are assumed rather than measured, so the downside case (%s at top of funnel) '
                       || 'is far from the base case (%s).', v_assumed, v_stages, round(coalesce(v_top_down,0),0), round(coalesce(v_top,0),0));
      v_changes := array_append(v_changes, 'Convert the largest assumed rate into a measured one before committing the full budget.');
    else
      v_verdict := 'ACHIEVABLE';
      v_reason  := format('Requires %s at the top of the funnel over %s days, within capacity and budget, '
                       || 'on %s measured rates of %s.', round(coalesce(v_top,0),0), v_days, v_measured, v_stages);
    end if;
  end if;

  if p_record then
    insert into public.target_verdict (
      contract_id, remaining_outcome, days_remaining, current_run_rate, required_run_rate,
      expected_completion, scenario_downside, scenario_base, scenario_upside,
      binding_stage, binding_reason, required_top_of_funnel, projected_cost, budget_headroom,
      verdict, verdict_reason, what_must_change, measured_rate_count, assumed_rate_count
    ) values (
      p_contract_id, v_remaining, v_days, v_run_rate, v_required,
      v_eta, v_top_down, v_top, v_top_up,
      v_binding, v_binding_why, v_top, nullif(v_cost,0), v_headroom,
      v_verdict, v_reason, v_changes, v_measured, v_assumed
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'contract', c.contract_key,
    'version', c.version,
    'objective', c.objective,
    'baseline', jsonb_build_object('value', c.baseline_value, 'state', c.baseline_state, 'at', c.baseline_at),
    'remaining_outcome', v_remaining,
    'days_remaining', v_days,
    'total_lag_days', v_total_lag,
    'required_run_rate_per_day', round(coalesce(v_required,0), 2),
    'chain', v_chain,
    'cumulative_rate', v_cum_rate,
    'required_top_of_funnel', jsonb_build_object(
       'downside', round(coalesce(v_top_down,0),0),
       'base',     round(coalesce(v_top,0),0),
       'upside',   round(coalesce(v_top_up,0),0)),
    'projected_cost', round(v_cost, 2),
    'budget_amount', c.budget_amount,
    'budget_headroom', round(coalesce(v_headroom,0), 2),
    'binding_stage', v_binding,
    'binding_reason', v_binding_why,
    'channel_blocked_stage', v_chan_block,
    'channel_safe_max', v_chan_safe,
    'channel_reason', v_chan_why,
    'rates_measured', v_measured,
    'rates_assumed', v_assumed,
    'verdict', v_verdict,
    'verdict_reason', v_reason,
    'what_must_change', to_jsonb(v_changes)
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_task_approve(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  r            record;
  v_auth       jsonb;
  v_granted    text;
  v_ceiling    text;
  v_tier       text;
  v_final      text;
  v_why        text;
  v_reason     text;
  v_decision   text;
  v_authreason text;
  v_rep_key    text;
  v_rep_tier   text;
  v_promoted   int := 0;
  v_held       int := 0;
  v_lane       int := 0;
  v_sample     jsonb := '[]'::jsonb;
  -- Mirrors AUTONOMOUS_CEILING in supabase/functions/dept_plan/index.ts byte for byte.
  c_ceiling constant text[] := array['content_draft','knowledge_fill','recommend','invite',
                                     'analysis','research','seo','monitor','reconcile','outreach_draft'];
begin
  for r in
    select id, dept_key, action_class, tier, coalesce(needs_founder,false) needs_founder,
           coalesce(decided_by,'(unattributed)') decided_by, title, assigned_agent
      from org_tasks
     where status = 'proposed'
     order by id
  loop
    v_auth       := fn_dept_authority(r.dept_key, r.action_class);
    v_authreason := coalesce(v_auth->>'reason', 'no reason given');
    v_granted    := coalesce(nullif(v_auth->>'tier',''), 'gated');
    if v_granted not in ('advisory','gated','supervised','autonomous') then v_granted := 'gated'; end if;

    -- WHO WILL DO IT, AND HOW HAS THEIR WORK BEEN GRADED. The assignee when one exists, else the
    -- proposer; an employee on reputation probation does not get its task waved through.
    v_rep_key := coalesce(r.assigned_agent, nullif(r.decided_by, '(unattributed)'));
    select p.tier into v_rep_tier from public.agent_reputation p where p.agent_key = v_rep_key;

    v_ceiling := case when r.action_class = any(c_ceiling) then 'autonomous' else 'gated' end;
    v_tier    := case when fn_authority_rank(v_granted) > fn_authority_rank(v_ceiling)
                      then v_ceiling else v_granted end;
    v_final   := case when r.needs_founder and fn_authority_rank(v_tier) > fn_authority_rank('gated')
                      then 'gated' else v_tier end;
    if v_rep_tier = 'probation' and v_final <> 'gated' then v_final := 'gated'; end if;

    -- Name the ACTUAL cause. Four different things produce a hold and they need different fixes:
    -- a hard gate is permanent, a missing org_authority row is a configuration gap someone should
    -- close, a ceiling clamp is a deliberate refusal to widen autonomy from a file, and a probation
    -- tier is the employee's own record.
    if v_final <> 'gated' then
      v_decision := 'approve';
      v_reason := 'Approved by the authority model: ' || r.dept_key || '/' || r.action_class
        || ' resolves to tier "' || v_final || '" (' || v_authreason || '); '
        || coalesce(v_rep_key, 'nobody') || ' holds reputation tier '
        || coalesce(v_rep_tier, 'unmeasured') || '. '
        || 'No founder gate applies — decision_policy.founder_review_gates covers refunds outside '
        || 'policy, money moves above the limit, published marketing, legal action, strategy '
        || 'changes, partnerships and executive security incidents only.';
    else
      v_decision := 'hold';
      if v_rep_tier = 'probation' then
        v_why := coalesce(v_rep_key, 'the proposer') || ' is on reputation probation, and a task '
              || 'of theirs is reviewed before it runs';
      elsif v_granted = 'gated' then
        v_why := 'the authority model itself grants no more than "gated" — ' || v_authreason;
      elsif fn_authority_rank(v_granted) > fn_authority_rank(v_ceiling) then
        v_why := 'org_authority grants "' || v_granted || '" but "' || r.action_class
              || '" sits outside AUTONOMOUS_CEILING, so it is clamped to "gated". Widening that set '
              || 'is a change to this routine''s AUTONOMOUS_CEILING constant, not an edit to the task';
      else
        v_why := 'the task was written with needs_founder=true by ' || r.decided_by
              || ', and needs_founder can only tighten';
      end if;
      v_reason := 'Held for review: ' || r.dept_key || '/' || r.action_class || ' — ' || v_why || '.';
    end if;

    if not p_dry_run then
      -- Idempotent on the DECISION, not on the run. An hourly sweep must not restate the same
      -- verdict 24 times a day; it must speak the moment a verdict CHANGES.
      insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                                stage, decision, reason, confidence)
      select 'org_task', r.id::text, r.dept_key, r.decided_by, 'approval_path',
             'approval', v_decision, v_reason, 1.0
      where not exists (
        select 1 from review_chain rc
         where rc.subject_type = 'org_task' and rc.subject_id = r.id::text
           and rc.stage = 'approval' and rc.decision = v_decision);

      if v_decision = 'hold' and not r.needs_founder then
        -- A HOLD HAS AN OWNER (5 Sep 2026). A gated proposal used to stay 'proposed' with nobody named,
        -- and the OS showed it to the founder as his decision. His standing rule: nothing reaches him
        -- except a Stripe refund — and the only class that may carry needs_founder is refund_decision
        -- (a00_org_tasks_founder_routing_refund_only). So a hold enters the org_task lane at tier
        -- 'gated': the department determines it from company knowledge, the accountable colleague
        -- reviews it, and the lane invokes no executor above low/advisory_safe/reversible at that tier.
        -- The review_chain 'hold' verdict above stays on record; the row also says why it was held.
        update org_tasks
           set status = 'assigned', tier = 'gated', needs_founder = false,
               decided_by = 'approval_path', updated_at = now(),
               result = coalesce(result, '{}'::jsonb) || jsonb_build_object(
                 'held', jsonb_build_object('at', now(), 'by', 'fn_task_approve', 'reason', v_reason,
                   'owner_basis', 'a hold is reviewed by the department in the org_task lane at tier gated, never by the founder'))
         where id = r.id;
        v_lane := v_lane + 1;
      end if;

      if v_decision = 'approve' then
        -- Write the RESOLVED tier, exactly as dept_plan does. Leaving the stale tier behind is the
        -- same "permission in the payload" defect audit 7.3 fixed in fn_event_dispatch, and
        -- cos_execute reads t.tier for its advisory_safe and review_pending decisions.
        update org_tasks
           set status = 'assigned', tier = v_final, needs_founder = false,
               decided_by = 'approval_path', updated_at = now()
         where id = r.id;
      end if;
    end if;

    if v_decision = 'approve' then v_promoted := v_promoted + 1; else v_held := v_held + 1; end if;
    if jsonb_array_length(v_sample) < 12 then
      v_sample := v_sample || jsonb_build_array(jsonb_build_object(
        'task', r.id, 'dept', r.dept_key, 'class', r.action_class,
        'granted', v_granted, 'final', v_final, 'decision', v_decision,
        'reputation', jsonb_build_object('agent', v_rep_key, 'tier', v_rep_tier)));
    end if;
  end loop;

  return jsonb_build_object(
    'dry_run', p_dry_run,
    'considered', v_promoted + v_held,
    'approved', v_promoted,
    -- 'held' counts every hold verdict; of those, only a needs_founder (refund) row stays 'proposed'.
    'held', v_held,
    'held_into_lane', v_lane,
    'held_for_founder', v_held - v_lane,
    'sample', v_sample);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_task_is_demand(p_action_class text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(p_action_class,'') ~*
    -- the revenue path: someone outside the company is on the other end of it
    '(invite|quote|rfq|inquir|lead|customer|supplier|onboard|registration|approv|kyc|collection|payment|refund|dispute|contract|delivery|fulfil)'
$function$


CREATE OR REPLACE FUNCTION public.fn_task_lesson(p_task_id bigint, p_outcome text, p_review jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  t record; v_id bigint; v_kind text; v_conf numeric; v_detail text; v_what text;
  v_verdict text; v_result text; v_basis text;
begin
  select o.id, o.dept_key, o.title, o.action_class, o.tier, o.result, o.status from org_tasks o
    into t where o.id = p_task_id;
  if t.id is null then return null; end if;

  -- What the review actually found, in the review's own words. Violations first because a failure
  -- is the lesson; dissents next; otherwise the approval and who gave it.
  select string_agg(distinct (v->>'rule') || ' (' || (v->>'severity') || '): ' || coalesce(v->>'why',''), ' | ')
    into v_detail from jsonb_array_elements(coalesce(p_review->'violations','[]'::jsonb)) v;

  if v_detail is null or v_detail = '' then
    select string_agg((d->>'by') || ' ' || (d->>'stance') || ': ' || left(coalesce(d->>'reasoning',''), 300), ' | ')
      into v_detail from jsonb_array_elements(coalesce(p_review->'dissents','[]'::jsonb)) d;
  end if;

  if p_outcome = 'event_closed' then
    -- xos-10. The Knowledge OS captures what a DISPATCHED EVENT produced, GRADED against the row.
    select c.decision into v_verdict
      from review_chain c
     where c.subject_type = 'org_task' and c.subject_id = t.id::text
       and c.stage in ('published','cos_review','dept_review') and c.decision is not null
     order by c.created_at desc, c.id desc
     limit 1;

    v_result := coalesce(nullif(t.result->>'summary',''), '');
    v_kind   := 'lesson';

    if coalesce(v_verdict,'') in ('reject','request_revision','hold_for_human','escalate')
       or coalesce(t.result->'executed'->>'error','') <> ''
       or v_result ~* '^\s*executor error'
       or coalesce(t.status,'') not in ('done','closed') then
      v_kind  := 'lesson_learned';
      v_conf  := 0.85;   -- a failure is the most useful thing this loop can record
      v_what  := 'worse';
      v_basis := case when coalesce(v_verdict,'') <> '' then 'the review verdict "' || v_verdict || '"'
                      else 'the outcome the task itself recorded' end;
    elsif v_result = '' then
      v_conf  := 0.4;    -- below the 0.6 retrieval floor: nothing was recorded, so there is nothing to serve
      v_what  := 'no_change';
      v_basis := 'the absence of any recorded result';
    else
      v_conf  := 0.6;    -- the floor fn_agent_institutional_memory serves from
      v_what  := 'success';
      v_basis := case when coalesce(v_verdict,'') <> '' then 'the review verdict "' || v_verdict || '"'
                      else 'the result the task recorded on closing' end;
    end if;

    v_detail := 'Raised by ' || coalesce(p_review->>'event_type','a company event')
             || ' on the bus and closed by ' || t.dept_key || '. Result: '
             -- org_tasks.result is JSONB, not text: the OS writes {at, mode, brain, summary} and
             -- the summary is the part that is a lesson. `nullif(t.result,'')` casts '' to jsonb
             -- at CALL time — it survived a staging apply that had no closed tasks to iterate and
             -- failed on production's 58. ->> returns text and never has to cast.
             || left(coalesce(nullif(v_result,''), 'closed with no recorded result'), 600)
             || '. Correlation ' || coalesce(p_review->>'correlation_id','unknown')
             || '. Graded ' || v_what || ' on ' || v_basis || '.';
  elsif p_outcome = 'published' and (v_detail is null or v_detail = '') then
    v_kind   := 'lesson';
    v_conf   := 0.5;   -- recorded for the audit trail; below fn_agent_institutional_memory's 0.6 floor
    v_detail := 'Cleared the quality standard for a department deliverable on the first pass and was '
             || 'approved by ' || coalesce(p_review->>'reviewer','the department head') || ' and the Chief of Staff.';
    v_what   := 'success';
  elsif p_outcome = 'published' then
    v_kind   := 'lesson_learned';
    v_conf   := 0.85;  -- shipped OVER a recorded objection: the most useful thing to remember
    v_detail := 'Approved and published despite a recorded objection. ' || v_detail;
    v_what   := 'success_over_dissent';
  else
    v_kind   := 'lesson_learned';
    v_conf   := 0.85;
    v_detail := 'Returned by review (' || p_outcome || '). ' || coalesce(v_detail, 'see review_chain');
    v_what   := 'worse';
  end if;

  insert into institutional_memory
    (kind, subject_type, subject_id, headline, detail, outcome, learned_by, confidence,
     evidence_ref, visible_to, occurred_at)
  values (v_kind, 'org_task', t.id::text,
          left(t.dept_key || ': ' || coalesce(t.title,'(untitled task)'), 200),
          left(v_detail, 2000), v_what, t.dept_key, v_conf,
          case when p_outcome = 'event_closed'
               then 'event_delivery:org_task:' || t.id
               else 'review_chain:org_task:' || t.id end,
          array[t.dept_key], now())
  returning id into v_id;

  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_task_review(p_task_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  t             record;
  v_text        text;
  v_deliverable text;
  v_author      text;
  v_chain       jsonb;
  v_outcome     text;
  v_rule        record;
  v_ch          jsonb;
  v_dept        text;
  v_blocked     boolean := false;
  v_blocker     text;
  v_dissents    jsonb := '[]'::jsonb;
  v_involved    jsonb := '[]'::jsonb;
  v_rules_hit   int := 0;
  v_own_resp    text;
  v_own_os      text;
  v_own_agent   text;
begin
  select o.id, o.dept_key, o.title, o.detail, o.action_class, o.result, o.tier, o.assigned_agent
    into t from org_tasks o where o.id = p_task_id;
  if t.id is null then
    return jsonb_build_object('error', 'no such task', 'task_id', p_task_id);
  end if;

  v_deliverable := coalesce(t.result->>'deliverable', '');
  if v_deliverable = '' then
    return jsonb_build_object('task_id', p_task_id, 'outcome', 'no_deliverable',
      'reason', 'The task carries no deliverable to review.');
  end if;

  -- WHO ACTUALLY WROTE IT (4 Sep 2026). This was `coalesce(d.brain_agent, d.lead_agent, dept_key)` —
  -- the department head, whoever performed the work. fn_pick_reviewer then correctly refuses to let a
  -- head approve its own output, and for the Office of the CEO there is nobody above the ceo, so every
  -- exec task escalated on an authorship nobody claimed. The row records its worker; read it.
  select coalesce(nullif(t.result->>'employee',''), nullif(t.assigned_agent,''),
                  d.brain_agent, d.lead_agent, t.dept_key)
    into v_author
    from org_departments d where d.dept_key = t.dept_key;
  if v_author is null then
    v_author := coalesce(nullif(t.result->>'employee',''), nullif(t.assigned_agent,''), t.dept_key);
  end if;

  -- STAGE 1+2: department head, then Chief of Staff. This is fn_review_submit unchanged — the
  -- reviewer is resolved live through delegation_rule and seniority, so a head who is unavailable
  -- delegates rather than silently approving.
  v_chain   := fn_review_submit('org_task', p_task_id::text, t.dept_key, v_author, v_deliverable);
  v_outcome := v_chain->>'outcome';

  -- STAGE 3: the challenge. Deterministic, so it runs on every task rather than being rationed.
  v_text := coalesce(t.title,'') || ' ' || coalesce(t.detail,'') || ' ' || coalesce(t.action_class,'');

  -- STAGE 0 OF THE RECORD, WRITTEN HERE: WHO OWNS THIS PROCESS.
  -- The responsibility is matched on its own words, longest first, so 'business development' wins
  -- over 'sales' when both occur. position() and not LIKE: 35 of the 72 responsibility values carry
  -- an underscore, and on the pattern side of LIKE an underscore is a single-character wildcard.
  select r.responsibility, r.os_key into v_own_resp, v_own_os
    from os_responsibility r
   where position(replace(r.responsibility, '_', ' ') in lower(v_text)) > 0
   order by length(r.responsibility) desc, r.responsibility
   limit 1;
  if v_own_os is null then
    select d.os_key into v_own_os from os_department d
     where d.dept_key = t.dept_key order by d.os_key limit 1;
  end if;
  select o.owner_agent into v_own_agent from operating_system o
   where o.os_key = v_own_os and o.active
     and exists (select 1 from org_agents a where a.agent_key = o.owner_agent and a.active);
  if v_own_agent is not null and v_own_agent is distinct from v_author then   -- an owner who authored it is already accountable; a self-review row is refused by the chain guard
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                              stage, decision, reason, confidence)
    select 'org_task', p_task_id::text, t.dept_key, v_author, v_own_agent, 'ownership', 'owned',
           'os_responsibility routes this work to the ' || v_own_os || ' OS'
             || case when v_own_resp is null
                     then ', taken from the owning OS of the ' || t.dept_key || ' department because '
                          || 'no declared responsibility matched the task'
                     else ', which is the declared owner of the responsibility "' || v_own_resp || '"'
                end
             || '. Accountable to the company for it: ' || v_own_agent || '.', 1.0
     where not exists (select 1 from review_chain rc
                        where rc.subject_type = 'org_task' and rc.subject_id = p_task_id::text
                          and rc.stage = 'ownership');
  end if;

  for v_rule in
    select c.*,
           -- ponytail: word-overlap matcher, deliberately conservative. A rule applies only when
           -- the task belongs to the rule's OWN department and at least two of the situation's
           -- distinctive words appear in the task. It under-matches rather than over-matches:
           -- "Publishing anything externally" will not fire on a task titled "Draft Q3 posts".
           -- Upgrade path when the founder wants precision is an action_class[] or match_pattern
           -- column on collaboration_rule, matched here instead of the word overlap.
           (select count(*) from unnest(string_to_array(
                    regexp_replace(lower(c.situation), '[^a-z ]', ' ', 'g'), ' ')) w
             where length(w) > 4 and position(w in lower(v_text)) > 0) hits
      from collaboration_rule c
     where c.owner_dept = t.dept_key
  loop
    if v_rule.hits < 2 then continue; end if;
    v_rules_hit := v_rules_hit + 1;

    -- Who the rule says must take part, recorded as its own reviewable stage so that "this needed
    -- legal and legal never saw it" is answerable after the fact.
    v_involved := v_involved || jsonb_build_object(
      'situation', v_rule.situation, 'must_involve', to_jsonb(v_rule.must_involve),
      'must_review', to_jsonb(v_rule.must_review), 'blocking', v_rule.blocking);

    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                              stage, decision, reason, confidence)
    values ('org_task', p_task_id::text, t.dept_key, v_author,
            coalesce((v_rule.must_review)[1], 'exec'), 'collaboration',
            case when v_rule.blocking then 'required' else 'advisory' end,
            'collaboration_rule #' || v_rule.id || ' applies ("' || v_rule.situation || '"): '
              || 'involve ' || coalesce(array_to_string(v_rule.must_involve, ', '), '(none)')
              || '; review by ' || coalesce(array_to_string(v_rule.must_review, ', '), '(none)')
              || '; may be challenged by ' || coalesce(array_to_string(v_rule.may_challenge, ', '), '(none)')
              || '. Why this rule exists: ' || v_rule.reason, 1.0);

    -- Each department the rule permits to challenge actually challenges.
    foreach v_dept in array coalesce(v_rule.may_challenge, array[]::text[]) loop
      v_ch := fn_challenge(v_text, t.dept_key, v_dept);
      if (v_ch->>'stance') <> 'support' then
        v_dissents := v_dissents || jsonb_build_object(
          'by', v_dept, 'stance', v_ch->>'stance', 'confidence', v_ch->>'confidence',
          'reasoning', v_ch->>'reasoning', 'blocking', v_rule.blocking);

        insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                                  stage, decision, reason, violated_rule, confidence)
        values ('org_task', p_task_id::text, t.dept_key, v_author, v_dept, 'challenge',
                case when v_rule.blocking and (v_ch->>'stance') = 'recommend_against'
                     then 'reject' else 'dissent' end,
                upper(v_ch->>'stance') || ' from ' || v_dept || ': ' || coalesce(v_ch->>'reasoning','')
                  || case when v_ch->'alternatives' <> '[]'::jsonb
                          then ' Alternative offered: ' || (v_ch->'alternatives'->>0) else '' end,
                v_ch->>'conflicts_with', (v_ch->>'confidence')::numeric);

        -- THE FOUNDER'S RULE, 6 Aug 2026: the blocking flag decides whether a rejection stops the
        -- work or is recorded against it. The reason is written either way.
        if v_rule.blocking and (v_ch->>'stance') = 'recommend_against' then
          v_blocked := true;
          v_blocker := v_dept || ' — ' || left(coalesce(v_ch->>'reasoning',''), 200);
        end if;
      end if;
    end loop;
  end loop;

  if v_blocked and v_outcome in ('published', 'approve') then
    v_outcome := 'request_revision';
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                              stage, decision, reason, confidence)
    values ('org_task', p_task_id::text, t.dept_key, v_author, 'brief', 'cos_review',
            'request_revision',
            'Returned for revision by the Chief of Staff: a BLOCKING collaboration rule was '
            || 'challenged and the challenge recommended against it. ' || v_blocker, 1.0);
  end if;

  -- "Every completed task should generate learning." Written here, by the reviewer, at the moment
  -- the verdict is known — the review already establishes what was wrong, so the lesson costs
  -- nothing. Never let recording the lesson fail the review itself.
  begin
    perform fn_task_lesson(p_task_id, v_outcome,
      jsonb_build_object('violations', coalesce(v_chain->'violations','[]'::jsonb),
                         'dissents',   v_dissents,
                         'reviewer',   v_chain->>'reviewer'));
  exception when others then null;
  end;

  return jsonb_build_object(
    'task_id',        p_task_id,
    'outcome',        v_outcome,
    'stopped_at',     v_chain->>'stopped_at',
    'author',         v_author,
    'reviewer',       v_chain->>'reviewer',
    'delegated_from', v_chain->>'delegated_from',
    'violations',     coalesce(v_chain->'violations', '[]'::jsonb),
    'unenforceable',  coalesce(v_chain->'unenforceable', '[]'::jsonb),
    'rules_applied',  v_rules_hit,
    'collaboration',  v_involved,
    'dissents',       v_dissents,
    'owned_by_os',    v_own_os,
    'owner_agent',    v_own_agent,
    'owns_responsibility', v_own_resp,
    'blocked',        v_blocked);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_task_tsquery(p_text text)
 RETURNS tsquery
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_words text[]; v_q tsquery;
begin
  if p_text is null or btrim(p_text) = '' then return null; end if;

  -- Lexemes the text actually contains, after stemming and stop-word removal. Using to_tsvector
  -- rather than a hand-rolled split means the stop-word list is Postgres's own and the stems match
  -- the ones in the stored tsv, which is the whole point.
  select array_agg(distinct lexeme) into v_words
    from unnest(to_tsvector('english', left(p_text, 4000))) t(lexeme, positions, weights)
   where length(lexeme) > 2;

  if v_words is null or array_length(v_words, 1) = 0 then return null; end if;

  -- Cap the term count. A 60-word task ORed in full ranks almost the whole corpus as a weak match
  -- and the budget window then keeps whatever sorts first, which is the failure we are leaving.
  if array_length(v_words, 1) > 24 then v_words := v_words[1:24]; end if;

  -- Cast the already-stemmed lexemes straight to tsquery. Passing them back through
  -- to_tsquery('english', ...) STEMS THEM A SECOND TIME — 'expens' becomes 'expen', 'analys' becomes
  -- 'analy' — and the double-stemmed term no longer matches the tsv it came from, so whole classes of
  -- questions (expenses, analysis, ...) silently retrieved nothing. The cast preserves the single
  -- stemming to_tsvector already did, which is the whole point of building the words from to_tsvector.
  v_q := array_to_string(v_words, ' | ')::tsquery;
  return v_q;
exception when others then
  -- A malformed lexeme must degrade to "no query" (and therefore to labelled fallback), never to
  -- an exception that takes the agent's whole context down with it.
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_twin(p_kind text, p_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  if p_kind='customer' then
    select jsonb_build_object('kind','customer','id',c.id,'name',c.full_name,'email',c.email,
      'industry',c.industry,
      'rfqs',(select count(*) from inquiries where customer_id=c.id),
      'deals',(select count(*) from transactions where customer_id=c.id),
      'spend_aed',(select coalesce(sum(reveal_fee),0) from transactions where customer_id=c.id and coalesce(fee_status,'')='paid'),
      'categories',(select coalesce(jsonb_agg(distinct category),'[]') from inquiries where customer_id=c.id),
      -- BUYING PATTERNS (§2) — categories ORDERED BY how often the customer actually buys them,
      -- with the count beside each. `categories` above is a set and a set is not a pattern.
      'preferred_categories',(select coalesce(jsonb_agg(jsonb_build_object('category',k.category,'rfqs',k.n) order by k.n desc),'[]')
         from (select category, count(*) n from inquiries where customer_id=c.id and category is not null
               group by category order by count(*) desc limit 8) k),
      'projects_active',(select count(*) from projects
         where customer_id=c.id and coalesce(status,'') not in ('closed','cancelled','completed','done')),
      'projects_total',(select count(*) from projects where customer_id=c.id),
      -- PREFERRED SUPPLIERS (§2) — the suppliers this customer has actually paid to reveal. A
      -- preference the customer demonstrated, not one they were asked to declare.
      'preferred_suppliers',(select count(distinct supplier_id) from transactions
         where customer_id=c.id and coalesce(fee_status,'')='paid' and supplier_id is not null),
      -- The chain the spec's §2 profile draws (Engineer -> Manager -> Finance). Resolved through
      -- the same two relations fn_approval_policy_match uses — owned organizations and memberships
      -- — so the twin and the approval engine can never disagree about whose chain this is.
      'approval_chain',(select coalesce(p.steps,'[]'::jsonb) from procurement_approval_policy p
         where p.active and p.organization_id in (
           select o.id from customer_organization o where o.owner_customer_id=c.id
           union
           select m.organization_id from customer_organization_member m
            where m.user_id=c.id and coalesce(m.active,true))
         limit 1),
      'last_active',(select max(created_at) from inquiries where customer_id=c.id),
      -- AI UNDERSTANDING (§2) — the share of the eight profile facts the system actually holds for
      -- this customer. The spec prints 96%; a constant would be a decoration, so this counts.
      'understanding_pct',(select round(100.0 * (
             (c.full_name is not null and c.full_name <> '')::int
           + (c.phone is not null and c.phone <> '')::int
           + coalesce(c.email_verified,false)::int
           + (c.tos_accepted_at is not null)::int
           + (c.locale is not null)::int
           + (c.industry is not null and c.industry <> '')::int
           + (exists (select 1 from inquiries where customer_id=c.id))::int
           + (exists (select 1 from customer_preference cp where cp.customer_id=c.id))::int
         ) / 8.0)),
      'banned',c.banned) into res from customers c where c.id::text=p_id;

  elsif p_kind='rfq' then
    select jsonb_build_object('kind','rfq','id',i.id,'category',i.category,'emirate',i.emirate,'status',i.status,
      'completeness',i.completeness,'ready',i.rfq_ready,'budget',i.budget,
      'quotes',(select count(*) from quotes where inquiry_id=i.id),
      'avg_quote_quality',(select round(avg(nullif(quality->>'score','')::numeric),1) from quotes where inquiry_id=i.id),
      'matched_suppliers',(select count(*) from inquiry_matches where inquiry_id=i.id),
      'created',i.created_at,'completed',i.completed_at,'outcome',i.outcome) into res from inquiries i where i.id::text=p_id;

  elsif p_kind='category' then
    res := jsonb_build_object('kind','category','category',p_id,
      'demand_rfqs',(select count(*) from inquiries where category=p_id),
      'approved_suppliers',(select count(*) from leads where coalesce(approval_status,'')='approved' and (lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(p_id)||'%')),
      'supplier_pool_total',(select count(*) from leads where lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(p_id)||'%'),
      'avg_quote_quality',(select round(avg(nullif(q.quality->>'score','')::numeric),1) from quotes q join inquiries i on i.id=q.inquiry_id where i.category=p_id),
      'agent',public.fn_resolve_cat_agent(p_id));

  elsif p_kind='company' then
    res := jsonb_build_object('kind','company','name','QuotesDone',
      'health',public.fn_health_index(),
      'suppliers_total',(select count(*) from leads),'suppliers_approved',(select count(*) from leads where coalesce(approval_status,'')='approved'),
      'customers',(select count(*) from customers),'rfqs',(select count(*) from inquiries),'quotes',(select count(*) from quotes),
      'revenue_paid_aed',(select coalesce(sum(reveal_fee),0) from transactions where coalesce(fee_status,'')='paid'),
      'eval',public.fn_eval_snapshot(30));
  else
    res := jsonb_build_object('error','kind must be customer|rfq|category|company');
  end if;
  return coalesce(res, jsonb_build_object('error','not found','kind',p_kind,'id',p_id));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ui_label(p_domain text, p_key text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(
           (select l.label from public.ui_label l
             where l.domain = p_domain and l.key = p_key),
           -- No row: humanise rather than blank. 'supplier_risk_complaints' -> 'Supplier Risk
           -- Complaints'. Worse than a written label, better than showing the founder a key, and
           -- v_ui_label_missing reports that it happened.
           nullif(initcap(replace(coalesce(p_key, ''), '_', ' ')), ''),
           'Unlabelled');
$function$


CREATE OR REPLACE FUNCTION public.fn_unsafe_match_eligibility_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare l record; v_reason text; v_verdict text;
begin
  select id, company_name, banned, matching_blocked, permanently_closed, license_expiry,
         approval_status, verified, registration_expires_at
    into l from public.leads where id = new.supplier_id;

  if l.id is null then
    -- N01. The supplier is not on record. The old body published PASS here; a gate that cannot
    -- find its subject has measured nothing, and saying PASS about it is a claim, not a finding.
    -- inquiry_matches_supplier_id_fkey is what refuses the row; this is what tells the caller why.
    perform set_config('app.inquiry_match_gate_verdict', 'BLOCKED_MISSING_MATCH_EVIDENCE', true);
    perform set_config('app.inquiry_match_gate_reason',
      format('supplier %s is not in public.leads; eligibility cannot be judged against a supplier that does not exist',
             new.supplier_id), true);
    raise warning 'a00_unsafe_match_eligibility: BLOCKED_MISSING_MATCH_EVIDENCE — supplier % is not on record',
      new.supplier_id;
    return null;
  end if;

  -- (1) A STANDING BAR on the supplier: banned, blocked, closed, or a lapsed credential.
  v_reason := case
    when coalesce(l.banned,false)             then 'supplier is banned'
    when coalesce(l.matching_blocked,false)   then 'supplier is blocked from matching'
    when coalesce(l.permanently_closed,false) then 'supplier is permanently closed'
    when l.license_expiry is not null and l.license_expiry < current_date
                                              then 'supplier licence expired ' || l.license_expiry
    when l.registration_expires_at is not null and l.registration_expires_at < now()
                                              then 'supplier registration expired ' || l.registration_expires_at
    else null end;
  if v_reason is not null then
    v_verdict := 'BLOCKED_INELIGIBLE_SUPPLIER';
  else
    -- (2) APPROVAL, which is a different question from eligibility and was never asked here.
    --     The three states BR-015 and GATE-014 cannot tell apart are named separately.
    v_reason := case
      when coalesce(btrim(coalesce(l.approval_status,'')),'') = ''
        then 'supplier has no approval decision on record (pending)'
      when l.approval_status <> 'approved'
        then format('supplier approval_status is %s', l.approval_status)
      when not coalesce(l.verified,false)
        then 'supplier is approved but not verified'
      else null end;
    if v_reason is not null then
      v_verdict := 'BLOCKED_SUPPLIER_NOT_APPROVED';
    end if;
  end if;

  if v_reason is null then
    perform set_config('app.inquiry_match_gate_verdict', 'PASS', true);
    perform set_config('app.inquiry_match_gate_reason',
      format('supplier %s is approved, verified and eligible to receive a match', new.supplier_id), true);
    return new;
  end if;

  -- K05. A REFUSAL THAT STATES ITSELF. The ledger row below is the safety record; this is the
  -- verdict the writer and the caller read, on the same key the readiness gate publishes.
  perform set_config('app.inquiry_match_gate_verdict', v_verdict, true);
  perform set_config('app.inquiry_match_gate_reason',
    format('supplier %s: %s', new.supplier_id, v_reason), true);

  perform public.fn_unsafe_block(
    'ineligible_supplier_match', 'trigger:a00_unsafe_match_eligibility',
    'inquiry_matches', coalesce(new.inquiry_id::text,'') || '/' || new.supplier_id::text,
    'insert match row',
    jsonb_build_object('supplier_id', new.supplier_id, 'company', l.company_name,
                       'inquiry_id', new.inquiry_id, 'reason', v_reason, 'verdict', v_verdict));
  raise warning 'unsafe_block: refused match of inquiry % to supplier % — % (%)',
        new.inquiry_id, new.supplier_id, v_reason, v_verdict;
  return null;   -- row not inserted; the ledger row survives
end $function$


CREATE OR REPLACE FUNCTION public.fn_usd_to_aed()
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 3.672450::numeric $function$


CREATE OR REPLACE FUNCTION public.fn_voice_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  select jsonb_build_object(
    'low_ratings_90d', (select count(*) from reviews where created_at > now()-interval '90 days' and rating is not null and rating <= 2),
    'recent_low_comments', (select coalesce(jsonb_agg(comment),'[]'::jsonb) from (select comment from reviews where rating <= 2 and coalesce(comment,'')<>'' order by created_at desc limit 8) z),
    'disputes', (select coalesce(jsonb_object_agg(coalesce(refund_status,'none'), c),'{}'::jsonb) from (select refund_status, count(*) c from transactions group by refund_status) z),
    'abandoned_rfqs', (select (fn_marketplace_analytics()->>'abandoned_rfqs')::int),
    'repeat_customers', (select count(*) from (select customer_id from inquiries where customer_id is not null group by customer_id having count(*)>1) z)
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_answer(p_from text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_body     text := lower(btrim(coalesce(p_body, '')));
  i          record;
  v_intent   record := null;
  v_pat      text;
  v_reply    text;
  v_lead     record;
  v_lead_id  bigint;
  v_ident_k  text := 'unknown';
  v_ident_id text := null;
  v_id       bigint;
  v_missing  text;
  v_cfg      record;
  v_log      bigint;
begin
  if v_body = '' then
    return jsonb_build_object('ok', false, 'reason', 'Empty message.');
  end if;

  select standard_reveal_rate, supplier_free_count, supplier_reg_fee into v_cfg
    from public.pricing_config order by id limit 1;

  -- WHO IS ASKING. Identity gates every 'own_records' answer, so one supplier can never be told
  -- another supplier's business by sending a lucky message.
  v_lead_id := public.fn_wa_lead_id(p_from);
  if v_lead_id is not null then
    select * into v_lead from public.leads where id = v_lead_id;
    v_ident_k := 'lead'; v_ident_id := v_lead_id::text;
  end if;

  -- MATCH. First intent whose pattern appears in the body wins, in sort order, so a specific
  -- intent can be placed ahead of a general one.
  for i in select * from public.wa_reply_intent where active order by sort, intent_key loop
    foreach v_pat in array i.match_patterns loop
      -- WORD BOUNDARIES, NOT SUBSTRINGS. A plain substring test matched the greeting pattern 'hi'
      -- inside the word 'something', so 'i want to buy something' was answered with hello. Patterns that
      -- begin and end on a word character are matched on word boundaries; punctuation patterns such as
      -- '#' keep the substring test, because a boundary around a symbol never matches.
      -- Whole-token matching WITHOUT regex escapes. The transport between this file and the database
      -- strips backslashes, so a regex word boundary arrives as a literal letter and the statement
      -- will not even parse. Padding both sides with spaces and normalising punctuation to spaces
      -- gives the same result with no escape to lose.
      if (case
            when v_pat ~ '[a-z0-9]'
              then position(' ' || v_pat || ' '
                            in ' ' || regexp_replace(v_body, '[^a-z0-9 ]', ' ', 'g') || ' ') > 0
            else position(v_pat in v_body) > 0
          end)
         and (not i.requires_number or v_body ~ '[0-9]{2,}') then
        v_intent := i;
        exit;
      end if;
    end loop;
    exit when v_intent is not null;
  end loop;

  -- NO MATCH. An honest refusal that names what it would need. Never a guess, and never a claim
  -- that some service is unavailable.
  if v_intent is null then
    v_reply := public.fn_wa_unmatched_reply();
    insert into public.wa_answer_log (from_phone, body, identity_kind, identity_id, matched, reply, refusal_reason)
    values (p_from, p_body, v_ident_k, v_ident_id, false, v_reply,
            'No enumerated intent matched. This row is the backlog: a real question with no resolver.')
    returning id into v_log;
    return jsonb_build_object('ok', true, 'matched', false, 'reply', v_reply, 'log_id', v_log);
  end if;

  -- IDENTITY REQUIRED BUT UNKNOWN.
  if v_intent.requires_identity and v_lead_id is null then
    v_reply := 'I do not recognise this number yet, so I cannot look up your records. Reply with the '
            || 'email address you registered with, or REGISTER to start a new registration.';
    insert into public.wa_answer_log (from_phone, body, identity_kind, identity_id, intent_key, matched, reply, refusal_reason)
    values (p_from, p_body, v_ident_k, v_ident_id, v_intent.intent_key, true, v_reply,
            'Intent matched but the sender is not a known party.')
    returning id into v_log;
    return jsonb_build_object('ok', true, 'matched', true, 'intent', v_intent.intent_key, 'reply', v_reply, 'log_id', v_log);
  end if;

  v_reply := v_intent.answer_template;

  -- COMPANY SLOTS, the same for everyone.
  v_reply := replace(v_reply, '{{reveal_rate}}', coalesce(round(v_cfg.standard_reveal_rate * 100, 1)::text || '%', '3%'));
  v_reply := replace(v_reply, '{{free_count}}',  coalesce(v_cfg.supplier_free_count::text, '1000'));
  v_reply := replace(v_reply, '{{reg_fee}}',     coalesce(round(v_cfg.supplier_reg_fee)::text, '1000'));

  -- THE APPROVED PUBLIC CONTACT, filled the same way. It is read from the settings that say
  -- publication in their names -- never from founder_mobile, which is a private contact record that
  -- happens to hold the same digits. Two values matching is not permission to publish either.
  --
  -- When the setting is absent the slot renders a sentence that ADMITS it rather than an empty
  -- string. "You can contact  on  " is worse than saying the contact is not configured, and the
  -- build spec asks for a blocker reported to the CEO rather than a placeholder shown to a customer.
  v_reply := replace(v_reply, '{{founder_public_phone}}',
    coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
             '(no approved public contact is configured yet)'));
  v_reply := replace(v_reply, '{{founder_public_name}}',
    coalesce((select value from public.app_secrets where key = 'founder_public_name'),
             'the owner'));

  -- OWN-RECORD SLOTS, read from this sender's row only.
  if v_lead_id is not null then
    v_reply := replace(v_reply, '{{company_name}}', coalesce(v_lead.company_name, 'your company'));
    v_reply := replace(v_reply, '{{reg_status}}',   coalesce(v_lead.registration_status, 'not started'));
    v_reply := replace(v_reply, '{{approval_status}}', coalesce(v_lead.approval_status, 'not yet reviewed'));

    -- The founder's mandatory six, not the ten the scoring view happens to list.
    select string_agg(m, ', ') into v_missing from (
      select 'a UAE mobile number' as m where coalesce(btrim(v_lead.phone_e164), '') = ''
      union all select 'an email address' where coalesce(btrim(v_lead.email), '') = ''
      union all select 'your trade licence' where coalesce(btrim(v_lead.license_doc_path), '') = ''
      union all select 'your company profile' where coalesce(btrim(v_lead.company_profile_doc_path), '') = ''
      union all select 'a signed copy of our terms' where coalesce(btrim(v_lead.signed_terms_path), '') = ''
    ) x;
    v_reply := replace(v_reply, '{{missing_list}}', coalesce(v_missing, 'nothing, your file is complete'));
    v_reply := replace(v_reply, '{{missing_line}}',
      case when v_missing is null then 'Your file is complete.'
           else 'We still need: ' || v_missing || '.' end);

    v_reply := replace(v_reply, '{{quote_count}}', '0');
    v_reply := replace(v_reply, '{{quote_detail}}',
      'No quotes yet. Once a buyer posts a request in your category you will be invited to quote.');
    v_reply := replace(v_reply, '{{awarded_count}}', '0');
    v_reply := replace(v_reply, '{{awarded_detail}}',
      'No jobs awarded yet. You will get a message here the moment one is.');
  end if;

  -- BY-ID LOOKUP. A number in the body is resolved against the real records, and returned ONLY to a
  -- party who appears on that record. An id is not a password.
  if v_intent.scope = 'by_id' then
    -- The first run of two or more digits. Stripping every digit from the whole sentence turns
    -- 'i have 2 questions about job 55' into 255, which is a different job belonging to someone else.
    v_id := nullif((regexp_match(v_body, '([0-9]{2,})'))[1], '')::bigint;
    if v_id is null then
      v_reply := 'Send me the number and I will look it up. For example: quote 1234, or job 5678.';
    else
      v_reply := replace(v_reply, '{{id_answer}}',
        'I could not find a record numbered ' || v_id || ' that you are a party to. Check the number, '
        || 'or reply HUMAN and the team will look into it.');
    end if;
  end if;

  insert into public.wa_answer_log (from_phone, body, identity_kind, identity_id, intent_key, matched, reply)
  values (p_from, p_body, v_ident_k, v_ident_id, v_intent.intent_key, true, v_reply)
  returning id into v_log;

  return jsonb_build_object(
    'ok', true, 'matched', true, 'intent', v_intent.intent_key,
    'identity_kind', v_ident_k, 'identity_id', v_ident_id,
    'reply', v_reply, 'log_id', v_log, 'answered_by', 'deterministic'
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_attach_document(p_phone text, p_storage_path text, p_caption text DEFAULT NULL::text, p_media_kind text DEFAULT NULL::text, p_turn_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lead   bigint;
  v_cap    text := lower(coalesce(p_caption, '') || ' ' || coalesce(p_storage_path, ''));
  v_kind   text := 'unknown';
  v_by     text := 'caption';
  v_conf   text := 'low';
  v_intake bigint;
  v_before jsonb;
  v_after  jsonb;
  v_reply  text;
begin
  v_lead := public.fn_wa_lead_id(p_phone);

  -- Classify from the caption and the filename. Deliberately conservative: an unrecognised document
  -- is recorded as unknown and waits, rather than being filed as a trade licence on a guess.
  if v_cap ~ '(trade|licence|license|رخصة|رخصه)' then
    v_kind := 'licence'; v_conf := 'high';
  elsif v_cap ~ '(profile|company profile|brochure|ملف|بروفايل)' then
    v_kind := 'profile'; v_conf := 'high';
  elsif v_cap ~ '(terms|t&c|agreement|signed|شروط|اتفاقية)' then
    v_kind := 'signed_terms'; v_conf := 'high';
  end if;

  if v_lead is not null then
    v_before := public.fn_supplier_mandatory_check(v_lead);
  end if;

  insert into public.wa_document_intake
    (phone_e164, lead_id, turn_id, storage_path, media_kind, caption,
     classified_as, classified_by, confidence, attached, attach_note)
  values (regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g'), v_lead, p_turn_id,
          p_storage_path, p_media_kind, p_caption, v_kind, v_by, v_conf, false, null)
  returning id into v_intake;

  -- Attach ONLY when we know whose file it is and what it is. Anything else waits for a person.
  if v_lead is null then
    v_reply := 'Thank you. I could not match this number to a registered company yet, so I have kept '
            || 'your file and someone will match it to your account. If you reply with the email '
            || 'address you registered with, I can do it straight away.';
    update public.wa_document_intake set attach_note = 'No lead matches this number.' where id = v_intake;

  elsif v_kind = 'unknown' then
    v_reply := 'Thank you, I have saved that to your file. I could not tell which document it is, so '
            || 'to file it correctly please tell me: is it your trade licence, your company profile, '
            || 'or the signed terms?';
    update public.wa_document_intake set attach_note = 'Received but unclassified; asked the sender.' where id = v_intake;

  else
    if v_kind = 'licence' then
      update public.leads set license_doc_path = p_storage_path where id = v_lead;
    elsif v_kind = 'profile' then
      update public.leads set company_profile_doc_path = p_storage_path where id = v_lead;
    elsif v_kind = 'signed_terms' then
      update public.leads set signed_terms_path = p_storage_path where id = v_lead;
    end if;

    update public.wa_document_intake
       set attached = true,
           attach_note = format('Attached as %s to lead %s.', v_kind, v_lead)
     where id = v_intake;

    v_after := public.fn_supplier_mandatory_check(v_lead);

    -- Tell them what changed and what is left. This is the difference between a receipt and a service.
    if coalesce((v_after->>'complete')::boolean, false) then
      v_reply := 'Got it, that is your ' || replace(v_kind,'_',' ') || ' saved. Your file is now '
              || 'complete and it goes to our team for verification. I will message you here when it '
              || 'is approved.';
    else
      v_reply := 'Got it, that is your ' || replace(v_kind,'_',' ') || ' saved. Still needed: '
              || (select string_agg(value #>> '{}', ', ') from jsonb_array_elements(v_after->'missing'))
              || '. You can send them here the same way.';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'intake_id', v_intake,
    'lead_id', v_lead,
    'classified_as', v_kind,
    'confidence', v_conf,
    'attached', (v_lead is not null and v_kind <> 'unknown'),
    'mandatory_before', v_before,
    'mandatory_after', v_after,
    'reply', v_reply
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_context(p_audience text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_e164 text; v_email text; v_lead record; v_cust record;
begin
  -- ONE IDENTIFIER, TWO SHAPES. wa_from arrives as 'whatsapp:+9715...'; a browser session arrives
  -- as an email address. An '@' is the discriminator: nothing that is a phone number contains one,
  -- and an address stripped of non-digits is meaningless, which is how a mis-shaped identifier used
  -- to fall through to "known: false" instead of an answer.
  v_email := nullif(lower(btrim(coalesce(p_phone, ''))), '');
  if v_email is not null and position('@' in v_email) = 0 then v_email := null; end if;
  v_e164 := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  if v_e164 = '' and v_email is null then return jsonb_build_object('scope','none'); end if;

  -- ---------------------------------------------------------------- FOUNDER: the company itself
  if p_audience = 'founder' then
    return jsonb_build_object(
      'scope','company',
      'suppliers', jsonb_build_object(
        'leads_total',      (select count(*) from leads),
        'claimed',          (select count(*) from leads where coalesce(claimed,false)),
        'claimed_real',     (select count(*) from leads where coalesce(claimed,false)
                              and not (coalesce(company_name,'') ilike 'ZZ DEMO%' or coalesce(email,'') ilike '%@example.invalid')),
        'approved',         (select count(*) from leads where approval_status = 'approved'),
        'licence_verified', (select count(*) from leads where coalesce(verified,false)),
        'with_email',       (select count(*) from leads where coalesce(btrim(email),'') <> '')),
      'invites', jsonb_build_object(
        'enabled',      (select value from app_secrets where key='invite_enabled'),
        'daily_cap',    (select value from app_secrets where key='invite_daily_cap'),
        'sent_today',   (select count(*) from leads where invited_at >= date_trunc('day', now() at time zone 'utc')),
        'sent_7d',      (select count(*) from leads where invited_at > now() - interval '7 days'),
        'bounced_7d',   (select count(*) from leads where invite_status='bounced' and invited_at > now() - interval '7 days'),
        'uncontacted',  (select count(*) from leads where invited_at is null and coalesce(btrim(email),'') <> '')),
      'demand', jsonb_build_object(
        'customers',        (select count(*) from customers),
        'inquiries_total',  (select count(*) from inquiries),
        'inquiries_7d',     (select count(*) from inquiries where created_at > now() - interval '7 days'),
        'quotes_total',     (select count(*) from quotes),
        'quotes_7d',        (select count(*) from quotes where created_at > now() - interval '7 days')),
      'money', jsonb_build_object(
        'transactions',      (select count(*) from transactions),
        'revealed',          (select count(*) from transactions where revealed_at is not null),
        'ai_spend_today_aed',(select round(coalesce(sum(cost_aed),0)::numeric,2) from ai_cost_log where occurred_at >= current_date),
        'ai_spend_month_aed',(select round(coalesce(sum(cost_aed),0)::numeric,2) from ai_cost_log where occurred_at >= date_trunc('month', now()))),
      'health', jsonb_build_object(
        'agent_runs_failed_24h', (select count(*) from agent_runs where status in ('error','failed') and started_at > now() - interval '24 hours'),
        'actions_pending',       (select count(*) from agent_actions where status in ('pending','needs_review')),
        'escalations_open',      (select count(*) from agent_actions where coalesce(escalated,false) and status in ('pending','needs_review'))),
      -- THE PART THAT IS HIS. Named so the model cannot read it as more company telemetry: these
      -- are items no agent is allowed to settle, and they are waiting for him specifically.
      'your_decision_queue', public.fn_founder_queue(12));
  end if;

  -- ---------------------------------------------------------------- SUPPLIER: only their own row
  if p_audience = 'supplier' then
    select * into v_lead from leads l
     where (v_e164 <> '' and (regexp_replace(coalesce(l.phone_e164, l.phone, ''), '[^0-9]', '', 'g') = v_e164
                           or regexp_replace(coalesce(l.whatsapp,''), '[^0-9]', '', 'g') = v_e164))
        or (v_email is not null and (lower(coalesce(l.claimed_by,'')) = v_email or lower(coalesce(l.email,'')) = v_email))
     order by coalesce(l.claimed,false) desc, l.id limit 1;
    if not found then return jsonb_build_object('scope','supplier','known', false); end if;

    return jsonb_build_object(
      'scope','supplier', 'known', true,
      'company', v_lead.company_name,
      'account', jsonb_build_object('email', v_lead.claimed_by, 'phone', coalesce(v_lead.phone_e164, v_lead.phone)),
      'profile', jsonb_build_object(
        'claimed',          coalesce(v_lead.claimed,false),
        'approval_status',  coalesce(v_lead.approval_status,'not submitted'),
        'verified',         coalesce(v_lead.verified,false),
        'email_verified',   coalesce(v_lead.owner_email_verified,false),
        'phone_verified',   coalesce(v_lead.owner_phone_verified,false),
        'trade_licence_no', v_lead.trade_license_no,
        'licence_authority',v_lead.license_authority,
        'licence_expiry',   v_lead.license_expiry,
        'licence_on_file',  (v_lead.license_doc_path is not null),
        'blocked_because',  v_lead.licence_gate_reason),
      'work', jsonb_build_object(
        'inquiries_received',  (select count(*) from inquiry_matches m where m.supplier_id = v_lead.id),
        'inquiries_quoted',    (select count(distinct q.inquiry_id) from quotes q where q.supplier_id = v_lead.id),
        'inquiries_missed',    (select count(*) from inquiry_matches m where m.supplier_id = v_lead.id
                                  and not exists (select 1 from quotes q where q.inquiry_id = m.inquiry_id and q.supplier_id = v_lead.id)),
        'quotes_submitted',    (select count(*) from quotes q where q.supplier_id = v_lead.id),
        'last_quote',          (select jsonb_build_object('amount_aed', q.quote_amount, 'status', q.status, 'when', q.created_at)
                                  from quotes q where q.supplier_id = v_lead.id order by q.created_at desc limit 1),
        'jobs_won',            (select count(*) from quotes q where q.supplier_id = v_lead.id and q.status = 'accepted')));
  end if;

  -- ---------------------------------------------------------------- CUSTOMER: only their own rows
  if p_audience = 'customer' then
    select * into v_cust from customers c
     where (v_e164 <> '' and regexp_replace(coalesce(c.phone,''), '[^0-9]', '', 'g') = v_e164)
        or (v_email is not null and lower(coalesce(c.email,'')) = v_email)
     limit 1;
    if not found then return jsonb_build_object('scope','customer','known', false); end if;

    return jsonb_build_object(
      'scope','customer', 'known', true,
      'name', v_cust.full_name,
      -- WHAT WE HOLD FOR THEM. "what is my email registered" was one of the four questions the
      -- assistant could not answer, and the answer was one column away the whole time.
      'account', jsonb_build_object(
        'email', v_cust.email, 'phone', v_cust.phone,
        'language', v_cust.locale, 'industry', v_cust.industry,
        'customer_since', v_cust.created_at),
      'profile', jsonb_build_object(
        'phone_verified', coalesce(v_cust.phone_verified,false),
        'email_verified', coalesce(v_cust.email_verified,false),
        'terms_signed',   (v_cust.signed_terms_url is not null),
        -- create_inquiry's own gate, stated as the fact it is, so the assistant answers "can I post
        -- a request" with the truth rather than an encouragement.
        'can_post_request', (coalesce(v_cust.phone_verified,false) and coalesce(v_cust.email_verified,false)
                             and v_cust.signed_terms_url is not null)),
      'inquiries', coalesce((
        select jsonb_agg(x order by x->>'created_at' desc) from (
          select jsonb_build_object(
            'id', i.id, 'category', i.category, 'emirate', i.emirate, 'status', i.status,
            'created_at', i.created_at,
            'suppliers_received', (select count(*) from inquiry_matches m where m.inquiry_id = i.id),
            'quotes_received',    (select count(*) from quotes q where q.inquiry_id = i.id and q.status='submitted'),
            -- PRE-REVEAL: a band and a count, never the individual quotes and never a supplier name.
            'revealed', exists (select 1 from transactions t where t.inquiry_id = i.id and t.revealed_at is not null),
            'price_band', case
              when exists (select 1 from transactions t where t.inquiry_id = i.id and t.revealed_at is not null)
                then (select jsonb_build_object('low', min(q.quote_amount), 'high', max(q.quote_amount), 'average', round(avg(q.quote_amount)::numeric,0))
                        from quotes q where q.inquiry_id = i.id and q.status='submitted')
              else (select case when count(*) = 0 then null
                                else jsonb_build_object('average_rounded_to_nearest_1000',
                                        round(avg(q.quote_amount)::numeric / 1000) * 1000, 'note',
                                        'rounded band only - the exact quotes and the supplier names unlock when you reveal')
                           end from quotes q where q.inquiry_id = i.id and q.status='submitted') end) as x
          from inquiries i where i.customer_id = v_cust.id order by i.created_at desc limit 10) z), '[]'::jsonb));
  end if;

  return jsonb_build_object('scope','unknown');
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_fact_pack(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lead_id bigint;
  l         record;
  c         record;
  v_cfg     record;
  v_conv    record;
  v_hist    jsonb := '[]'::jsonb;
  v_mand    jsonb;
  v_digits  text;
  -- Built before the return, NOT inside a CASE. Postgres evaluates a record field reference even in
  -- an unreached CASE branch, so with an unknown sender 'record l is not assigned yet' aborts the
  -- whole function. An unknown caller is the most common case, so that bug would have fired first.
  v_ident   jsonb;
  v_found_c boolean := false;
  v_conv_j  jsonb;
begin
  v_digits := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  select standard_reveal_rate, supplier_free_count, supplier_reg_fee, category_open_min_suppliers,
         refund_window_working_days, chase_after_working_days
    into v_cfg from public.pricing_config order by id limit 1;

  v_lead_id := public.fn_wa_lead_id(p_phone);
  if v_lead_id is not null then
    select * into l from public.leads where id = v_lead_id;
    v_mand  := public.fn_supplier_mandatory_check(v_lead_id);
    v_ident := jsonb_build_object(
      'kind','supplier','id',v_lead_id,'company',l.company_name,
      'approval_status', coalesce(l.approval_status,'not reviewed'),
      'registration_status', coalesce(l.registration_status,'not started'),
      'mandatory', v_mand);
  else
    select * into c from public.customers
      where regexp_replace(coalesce(phone,''), '[^0-9]', '', 'g') = v_digits limit 1;
    v_found_c := found;
    if v_found_c then
      v_mand  := public.fn_customer_mandatory_check(c.id);
      v_ident := jsonb_build_object(
        'kind','customer','id',c.id::text,'name',c.full_name,
        'email_verified', c.email_verified, 'phone_verified', c.phone_verified,
        'mandatory', v_mand);
    else
      v_ident := jsonb_build_object('kind','unknown',
        'note','This number matches no lead and no customer. Do not discuss anyone''s records.');
    end if;
  end if;

  v_conv_j := jsonb_build_object('state','new');
  select * into v_conv from public.wa_conversation where phone_e164 = v_digits;
  if found then
    v_conv_j := jsonb_build_object(
      'state', v_conv.thread_state, 'topic', v_conv.topic, 'language', v_conv.language,
      'messages_so_far', v_conv.message_count,
      'window_open', (v_conv.window_expires_at is not null and v_conv.window_expires_at > now()));
    select coalesce(jsonb_agg(jsonb_build_object('at', t.at, 'dir', t.direction,
             'text', coalesce(t.transcript, t.body)) order by t.at), '[]'::jsonb)
      into v_hist
      from (select * from public.wa_turn where conversation_id = v_conv.id order by at desc limit 12) t;
  end if;

  return jsonb_build_object(
    -- WHO. Identity is a fact, never an inference. An unknown sender stays unknown.
    'identity', v_ident,

    -- WHAT IS TRUE ABOUT THE COMPANY. Read live, never remembered.
    'company', jsonb_build_object(
      'reveal_rate_pct', round(coalesce(v_cfg.standard_reveal_rate,0.03) * 100, 1),
      'supplier_free_count', v_cfg.supplier_free_count,
      'supplier_reg_fee_aed', v_cfg.supplier_reg_fee,
      'category_opens_at_suppliers', v_cfg.category_open_min_suppliers,
      'refund_window_working_days', v_cfg.refund_window_working_days,
      'supplier_chase_after_working_days', v_cfg.chase_after_working_days,
      'founder_contact', (coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
                   '(no approved public contact is configured — tell the CEO)')),
      'supplier_mandatory', jsonb_build_array('company name','UAE mobile','email','trade licence','company profile','signed terms'),
      'customer_mandatory', jsonb_build_array('name','mobile','email','signed terms')),

    -- THE THREAD.
    'conversation', v_conv_j,
    'history', v_hist,

    -- WHAT IS NOT KNOWN. Stating this is what stops a model filling the gap with something plausible.
    'unknown', jsonb_build_array(
      'There are no live requests, quotes or comparison reports in the system yet, so no job status can be given for any id.',
      'No category is open yet, so no supplier can currently be matched to a buyer request.',
      'Pricing beyond the reveal rate and registration fee is not set and must not be invented.'),

    -- WHAT MAY NOT BE SAID OR DONE. A boundary, not a suggestion.
    'must_not', jsonb_build_array(
      'Never state a fact that is not in this pack. If it is not here, say you will check and pass it to the team.',
      'Never quote a price, discount, delivery date or timescale that is not in this pack.',
      'Never reveal any other party''s identity, contact details or quote. Anonymity is the product.',
      'Never promise approval, a job, or a refund. Refunds are the founder''s decision alone.',
      'Never ask for a password, a card number or an OTP code.'),

    'generated_at', now()
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_fanout()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ph text; opt boolean := false;
begin
  -- only fan out plain email rows; never recurse on whatsapp rows
  if coalesce(NEW.channel,'email') <> 'email' then return NEW; end if;
  if NEW.to_email is null then return NEW; end if;

  if NEW.to_role = 'supplier' then
    select coalesce(nullif(btrim(l.whatsapp),''), l.phone), coalesce(l.wa_optin,false)
      into ph, opt from leads l
      where (NEW.lead_id is not null and l.id = NEW.lead_id)
         or (NEW.lead_id is null and lower(l.email) = lower(NEW.to_email))
      order by (l.id = NEW.lead_id) desc nulls last
      limit 1;
  elsif NEW.to_role = 'customer' then
    select c.phone, coalesce(c.wa_optin,false)
      into ph, opt from customers c where lower(c.email) = lower(NEW.to_email) limit 1;
  else
    return NEW;
  end if;

  if opt is true and ph is not null and length(regexp_replace(ph, '[^0-9]', '', 'g')) >= 8 then
    insert into notifications(type, to_email, to_role, to_phone, lead_id, inquiry_id, quote_id, subject, body, channel, status)
    values (NEW.type, NEW.to_email, NEW.to_role, ph, NEW.lead_id, NEW.inquiry_id, NEW.quote_id, NEW.subject, NEW.body, 'whatsapp', 'queued');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_lead_id(p_phone text)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select l.id
    from public.leads l
   where regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g') <> ''
     and (regexp_replace(coalesce(l.phone_e164, l.phone, ''), '[^0-9]', '', 'g')
            = regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g')
       or regexp_replace(coalesce(l.whatsapp,''), '[^0-9]', '', 'g')
            = regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g'))
   order by coalesce(l.claimed,false) desc, l.id
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_model_brief()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select
     'You are the QuotesDone WhatsApp agent, talking to UAE suppliers and buyers. '

  || 'ABSOLUTE RULE ON FACTS: every detail about any customer, supplier, quote, job or price comes '
  || 'from fact_pack and from nowhere else. You know nothing about this company or these people '
  || 'except what fact_pack contains, and you must never fill such a gap from memory or from what '
  || 'seems likely. '

  || 'THE OWNER''S NUMBER IS ' || (coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
                   '(no approved public contact is configured — tell the CEO)')) || ' AND THERE ARE EXACTLY TWO REASONS TO GIVE IT. One: the '
  || 'sender asked to speak to a person, an agent or a human, or asked who owns or runs QuotesDone. '
  || 'Two: the message is a complaint, a dispute or an accusation, which needs a person whether they '
  || 'asked or not. In both cases give it plainly and without making them ask twice, because the '
  || 'owner is the only person in this company and an escalation that does not reach him reaches '
  || 'nobody. Give it for NOTHING ELSE: not for an off-topic question, not for small talk, not '
  || 'because you could not answer. '

  || 'ABSOLUTE RULE ON SUBJECT: if the message is not about QuotesDone, reply with EXACTLY this '
  || 'sentence and nothing else: "' || public.fn_wa_off_topic_reply() || '" '
  || 'Translate it into the sender''s language if they did not write in English, but do not reword '
  || 'it, do not add to it, do not apologise around it, and do not answer the question first. Never '
  || 'state a fact about the outside world as if you had checked it: you cannot see the weather, a '
  || 'score, a rate or the time. '

  || 'BUT PHRASING IS NOT SUBJECT. A QuotesDone question asked in unusual words is still a QuotesDone '
  || 'question. "any update on my file bro" is a registration-status question and must be understood '
  || 'and answered from the record. Judge what the message is ABOUT, never how it is worded. '

  || 'WHEN IT IS ABOUT US BUT THE PACK LACKS THE FACT: say you will check and that someone will come '
  || 'back to them. That gap is ours. '

  || 'The sender may write in any language: understand them and reply in their own. Follow the '
  || 'conversation history. Honour every entry in must_not. Match the courtesy you are given; a '
  || 'greeting gets a greeting, not a menu. Be brief, plain and useful, the way a competent person '
  || 'on a phone would be.'
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_off_topic_reply()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select 'I am here to assist you with QuotesDone inquiries only. Please let me know how I can help you.'
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_record_turn(p_phone text, p_direction text, p_body text DEFAULT NULL::text, p_media_url text DEFAULT NULL::text, p_media_kind text DEFAULT NULL::text, p_transcript text DEFAULT NULL::text, p_intent text DEFAULT NULL::text, p_answered_by text DEFAULT NULL::text, p_fact_pack jsonb DEFAULT NULL::jsonb, p_model text DEFAULT NULL::text, p_cost_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_digits text := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  v_conv   record;
  v_lead   bigint;
  v_cust   uuid;
  v_kind   text := 'unknown';
  v_pid    text;
  v_turn   bigint;
  v_dir    text;
begin
  -- THE DIRECTION IS NORMALISED HERE, WHERE THE CALLER'S VOCABULARY MEETS THE COLUMN'S.
  -- Every branch below compares p_direction to 'in', and wa_turn's CHECK allows only 'in' and
  -- 'out'. A caller writing 'INBOUND' -- the obvious word, and the one the edge function reached
  -- for -- hit the CHECK and the whole turn was lost. Worse would have been no CHECK: the row
  -- would have been stored and the 24-hour service window would never have opened, so the agent
  -- would have gone quiet a day later for a reason nothing recorded.
  v_dir := case lower(btrim(coalesce(p_direction, '')))
             when 'in' then 'in' when 'inbound' then 'in' when 'incoming' then 'in'
             when 'out' then 'out' when 'outbound' then 'out' when 'outgoing' then 'out'
             else null end;
  if v_dir is null then
    return jsonb_build_object('ok', false, 'reason',
      format('direction %L is neither inbound nor outbound; nothing was recorded', p_direction));
  end if;
  if v_digits = '' then
    return jsonb_build_object('ok', false, 'reason', 'No usable phone number on the message.');
  end if;

  v_lead := public.fn_wa_lead_id(p_phone);
  if v_lead is not null then
    v_kind := 'lead'; v_pid := v_lead::text;
  else
    select id into v_cust from public.customers
     where regexp_replace(coalesce(phone,''), '[^0-9]', '', 'g') = v_digits limit 1;
    if v_cust is not null then v_kind := 'customer'; v_pid := v_cust::text; end if;
  end if;

  insert into public.wa_conversation (phone_e164, party_kind, party_id, message_count,
                                      window_opened_at, window_expires_at)
  values (v_digits, v_kind, v_pid, 0,
          case when v_dir = 'in' then now() else null end,
          case when v_dir = 'in' then now() + interval '24 hours' else null end)
  on conflict (phone_e164) do update set
      last_seen_at   = now(),
      party_kind     = coalesce(excluded.party_kind, wa_conversation.party_kind),
      party_id       = coalesce(excluded.party_id,   wa_conversation.party_id),
      -- An INBOUND message opens or re-opens the 24-hour service window. An outbound one never does,
      -- which is the whole point of the rule: we cannot extend our own permission to keep talking.
      window_opened_at  = case when v_dir = 'in' then now() else wa_conversation.window_opened_at end,
      window_expires_at = case when v_dir = 'in' then now() + interval '24 hours'
                               else wa_conversation.window_expires_at end
  returning * into v_conv;

  update public.wa_conversation
     set message_count = message_count + 1,
         last_intent   = coalesce(p_intent, last_intent)
   where id = v_conv.id
  returning * into v_conv;

  insert into public.wa_turn (conversation_id, direction, body, media_url, media_kind, transcript,
                              transcript_source, intent_key, answered_by, fact_pack, model_id, cost_aed)
  values (v_conv.id, v_dir, p_body, p_media_url, p_media_kind, p_transcript,
          case when p_transcript is not null then 'model' else 'none' end,
          p_intent, p_answered_by, p_fact_pack, p_model, p_cost_aed)
  returning id into v_turn;

  return jsonb_build_object(
    'ok', true, 'conversation_id', v_conv.id, 'turn_id', v_turn,
    'party_kind', v_conv.party_kind, 'party_id', v_conv.party_id,
    'message_count', v_conv.message_count,
    'window_expires_at', v_conv.window_expires_at,
    'window_open', (v_conv.window_expires_at is not null and v_conv.window_expires_at > now())
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_route(p_phone text, p_body text, p_has_audio boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_digits text := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  v_det    jsonb;
  v_pack   jsonb;
  v_conv   record;
  v_needs  boolean;
  v_why    text;
  v_held   boolean;
  v_latin  boolean;
  v_trouble boolean;
  v_asked  boolean;
  v_person boolean;
  v_reason text;
  v_chain  jsonb;
  v_intent text;
  v_reply  text;
begin
  select coalesce((select value = 'true' from public.app_secrets where key = 'paid_inference_enabled'), false)
    into v_held;
  v_held := not v_held;

  v_det  := public.fn_wa_answer(p_phone, coalesce(p_body, '(voice note)'));
  v_pack := public.fn_wa_fact_pack(p_phone);
  v_intent := v_det->>'intent';
  v_reply  := v_det->>'reply';
  select * into v_conv from public.wa_conversation where phone_e164 = v_digits;

  v_latin := coalesce(p_body, '') ~ '^[\s\x20-\x7E]*$';

  -- The two ways a message needs a person.
  v_asked   := coalesce(v_intent = 'contact_human', false);
  v_trouble := coalesce(p_body,'') ~* '(complain|refund|dispute|angry|lawyer|legal|scam|cheat|fraud|شكوى|احتيال|نصب)';

  -- One decision now, not two. Needing a person and getting his number are the same thing here.
  v_person := v_asked or v_trouble;
  v_reason := case
    when v_asked   then 'They asked for a person, or asked who runs the company.'
    when v_trouble then 'This is a complaint, a dispute or an accusation. It needs a person whether '
                     || 'they asked for one or not, and the founder is the only person there is.'
    else 'Nobody asked for a person and nothing here needs one. A number given out by a machine '
      || 'cannot be taken back.' end;

  -- A complaint gets the number appended, because the escalation and the contact are the same act.
  if v_trouble and not v_asked then
    v_reply := v_reply || ' If you would rather speak to someone directly, call or message '
            || '+971 50 931 9355, which is answered by the owner.';
  end if;

  v_needs := false; v_why := 'A deterministic answer matched and the message is simple, so this turn costs nothing.';
  if p_has_audio then
    v_needs := true; v_why := 'The message is a voice note and must be transcribed before it can be answered.';
  elsif not v_latin then
    v_needs := true; v_why := 'The message is not in Latin script and the fixed answers exist only in English.';
  elsif v_intent in ('small_talk','off_topic','greeting','contact_human') then
    v_needs := false;
    v_why := format('Matched %s, which is answered completely without a model.', v_intent);
  elsif coalesce((v_det->>'matched')::boolean, false) = false then
    v_needs := true; v_why := 'No fixed answer matched. Wording varies, so this is the normal case rather than an exception.';
  elsif coalesce(v_conv.message_count, 0) >= 2 then
    v_needs := true; v_why := 'This is a continuing conversation; a fixed answer would ignore what came before.';
  elsif length(coalesce(p_body,'')) > 160 then
    v_needs := true; v_why := 'The message is long enough to contain more than one question.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'rung', rung, 'model', model, 'kind', kind, 'rationale', rationale) order by rung), '[]'::jsonb)
    into v_chain
    from public.model_fallback_chain
   where purpose = 'whatsapp_conversation' and active;

  return jsonb_build_object(
    'ok', true,
    'needs_model', v_needs,
    'why', v_why,
    'inference_held', v_held,
    'model', case when v_needs then 'google/gemini-3-flash' else null end,
    'fallback_chain', case when v_needs then v_chain else null end,
    'on_model_failure',
      'Try each rung in order. Record model_wanted, model_used and fell_back on llm_calls for every '
   || 'attempt, so a fallback that becomes permanent is visible rather than quietly expensive. The '
   || 'final rung is the deterministic reply and it cannot fail.',
    'model_reason', case
      when not v_needs then 'No model needed. The database answered it.'
      else 'google/gemini-3-flash first, by founder ruling. On failure claude-sonnet-5. On failure the '
        || 'deterministic reply. Every rung gets the same fact pack and the same boundaries.' end,

    -- One decision. Handing to a person and giving the number are the same act.
    'needs_a_person', v_person,
    'founder_number', case when v_person then (coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
                   '(no approved public contact is configured — tell the CEO)')) else null end,
    'person_reason', v_reason,
    'opened_by', case when v_asked then 'they asked'
                      when v_trouble then 'complaint or dispute'
                      else null end,

    'action', case
      when v_needs and v_held  then 'send_deterministic_and_log_shortfall'
      when v_needs             then 'walk_fallback_chain_with_fact_pack'
      else                          'send_deterministic' end,

    'transcription_gap', case when p_has_audio
      then 'Whether Gemini 3 Flash can take the Twilio media URL directly, or whether a speech model '
        || 'must be added to ai_model_register first, is NOT established and must be checked before '
        || 'audio is enabled.'
      else null end,

    'deterministic_reply', v_reply,
    'deterministic_intent', v_intent,
    'fact_pack', v_pack,
    'model_brief', public.fn_wa_model_brief()
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_unmatched_reply()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select 'I can help with your registration, your documents, your quotes, and any job by its number. '
      || 'I am not sure about that one, so let me check and someone will come back to you.'
$function$


CREATE OR REPLACE FUNCTION public.fn_watch_failed_runs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_stale record;
  v_stale_n int := 0;
  v_rehearsal int := 0;
  v_since    timestamptz;
  v_fail     record;
  v_alerts   int := 0;
  v_held     int := 0;
  v_real     int := 0;
  v_detail   text := '';
  v_models_answering boolean;
begin
  select coalesce(last_run_at, now() - interval '24 hours') into v_since
    from alert_watermark where watcher = 'failed_runs';
  if not found then
    insert into alert_watermark (watcher, last_run_at) values ('failed_runs', now() - interval '24 hours');
    v_since := now() - interval '24 hours';
  end if;

  -- IS A MODEL ANSWERING AT ALL? This one boolean is what separates "the AI is broken" from
  -- "the AI is switched off", and it is measured, not configured - nothing here reads a flag that
  -- someone could forget to clear. A single successful attempt in the last 24 hours is enough to
  -- put every model-unavailable error back on the failure side.
  select exists (select 1 from public.llm_attempt
                  where created_at > now() - interval '24 hours' and coalesce(ok, false))
    into v_models_answering;
  -- Rows inside a declared sandbox rehearsal window (demo_factory.withRun): counted, stated in the
  -- message if one goes out, never the reason one goes out. A rehearsal on the production database
  -- paged the founder twice on 3 Sep 2026 about the operator's own probes; this is the fix.
  select count(*) into v_rehearsal
    from agent_runs r
   where r.started_at > v_since and r.status = 'error'
     and public.fn_rehearsal_window_covers(r.started_at);

  for v_fail in
    select r.agent,
           count(*) as fails,
           max(r.started_at) as latest,
           left(coalesce(max(r.note), ''), 300) as sample_note,
           -- The signature is the agent plus the shape of the note, not the note itself: the same
           -- standing condition arrives with different numbers in it every pass ("3 step(s) are
           -- ready" one hour, "4" the next) and must still be recognised as the same condition.
           r.agent || ':' || left(regexp_replace(coalesce(max(r.note), ''), '[0-9]+', '#', 'g'), 120) as signature,
           bool_or(coalesce(r.note, '') ~* '(model returned nothing|returned no content|generation_failed|returned nothing for|model call failed|open-circuit|LLM call failed)') as model_shaped
      from agent_runs r
     where r.started_at > v_since and r.status = 'error'
       -- a row inside a DECLARED rehearsal window is counted below, not paged (3 Sep 2026)
       and not public.fn_rehearsal_window_covers(r.started_at)
     group by r.agent, left(regexp_replace(coalesce(r.note, ''), '[0-9]+', '#', 'g'), 120)
     order by count(*) desc
  loop
    -- HELD: a model did not answer, and no model has answered at all. Counted, recorded, not
    -- alerted. The moment v_models_answering flips true this branch stops being taken.
    if v_fail.model_shaped and not v_models_answering then
      v_held := v_held + v_fail.fails;
      insert into public.alert_signature (watcher, signature)
        values ('failed_runs', v_fail.signature)
        on conflict (watcher, signature) do update
          set last_seen_at = now(), seen_count = alert_signature.seen_count + 1, resolved_at = null;
      continue;
    end if;

    v_real := v_real + v_fail.fails;

    -- ONCE PER CONDITION. A signature alerted inside the last 24 hours is still recorded as seen,
    -- and does not interrupt him again.
    insert into public.alert_signature (watcher, signature)
      values ('failed_runs', v_fail.signature)
      on conflict (watcher, signature) do update
        set last_seen_at = now(), seen_count = alert_signature.seen_count + 1, resolved_at = null;

    if exists (select 1 from public.alert_signature s
                where s.watcher = 'failed_runs' and s.signature = v_fail.signature
                  and s.last_alerted_at > now() - interval '24 hours') then
      continue;
    end if;

    v_detail := v_detail || v_fail.agent || ': ' || v_fail.fails || ' failure(s). ' || v_fail.sample_note || E'\n';
    v_alerts := v_alerts + 1;
    update public.alert_signature set last_alerted_at = now()
      where watcher = 'failed_runs' and signature = v_fail.signature;
  end loop;

  -- The hold is stated once, in the same message, so it is never invisible: he should be able to
  -- see that the quiet is his own decision and not a working company.
  if v_held > 0 then
    v_detail := v_detail || E'\n' || v_held ||
      ' further run(s) could not reach a model. No model call has succeeded in 24 hours, so these ' ||
      'are counted as held by the paid-inference hold, not as failures. They will be reported as ' ||
      'failures again the moment a model answers.' || E'\n';
  end if;

  -- THE DEAD-GUARD BLIND SPOT (3 Sep 2026). A job that never fires produces no failure. v_cron_stale
  -- lists active jobs with no run of any status inside twice their schedule, measured from activation
  -- (scripts/sql/v_cron_stale_the_dead_guard_blind_spot.sql). Same ledger, same once-per-24h rule.
  for v_stale in select jobname, schedule, why from public.v_cron_stale order by jobname loop
    v_stale_n := v_stale_n + 1;
    insert into public.alert_signature (watcher, signature) values ('failed_runs', 'cron_stale:' || v_stale.jobname)
    on conflict (watcher, signature) do update set last_seen_at = now(), seen_count = alert_signature.seen_count + 1, resolved_at = null;
    if exists (select 1 from public.alert_signature s where s.watcher = 'failed_runs'
                 and s.signature = 'cron_stale:' || v_stale.jobname and s.last_alerted_at > now() - interval '24 hours') then
      continue;
    end if;
    v_detail := v_detail || 'cron ' || v_stale.jobname || ' has NOT FIRED: ' || v_stale.why || E'\n';
    v_alerts := v_alerts + 1;
    update public.alert_signature set last_alerted_at = now() where watcher = 'failed_runs' and signature = 'cron_stale:' || v_stale.jobname;
  end loop;

  -- A SIGNATURE RESOLVES ON MERIT, NOT ON THE CLOCK (5 Sep 2026). The red view carried a watcher
  -- episode for 24 h after the last sighting whatever the subject did next. kb_embed had run
  -- 'ok' 83 times after its last error and dr_drill 4 times, and both stayed red; monthly_report was
  -- listed stale every hour and paged every day because v_cron_stale read '0 7 1 * *' as daily.
  -- Two rules, both measured from the subject's own ledger:
  --   failed-run signature  -> resolved when the agent has a status='ok' run started AFTER the
  --                            watcher last saw the failure (last_seen_at). A later failure re-opens
  --                            it through the upsert above (resolved_at = null), which the red view
  --                            then treats as a NEW episode and pages again.
  --   cron_stale signature  -> resolved when the job is no longer listed by v_cron_stale on this
  --                            pass, i.e. a run of any status has been recorded since.
  update public.alert_signature s
     set resolved_at = now()
   where s.watcher = 'failed_runs' and s.resolved_at is null
     and s.signature not like 'cron_stale:%'
     and exists (select 1 from public.agent_runs ok
                  where ok.agent = split_part(s.signature, ':', 1)
                    and ok.status = 'ok' and ok.started_at > s.last_seen_at);
  update public.alert_signature s
     set resolved_at = now()
   where s.watcher = 'failed_runs' and s.resolved_at is null
     and s.signature like 'cron_stale:%'
     and not exists (select 1 from public.v_cron_stale c where 'cron_stale:' || c.jobname = s.signature);

  if v_rehearsal > 0 then
    v_detail := v_detail || E'\n' || v_rehearsal || ' further run(s) failed inside a declared sandbox rehearsal window and were not paged.' || E'\n';
  end if;

  if v_alerts > 0 then
    -- 6 SEP 2026: fn_notify_founder, not an HTTP hop to alert_founder. founder_mail_policy routes this kind
    -- (scheduled_runs_failed) to the IT operations engineer as ONE org_task per condition; it never emails him.
    perform public.fn_notify_founder(
      'Scheduled runs failed (' || v_alerts || ' new condition(s))', v_detail, 'error',
      p_kind => 'scheduled_runs_failed',
      -- Dedupe on the day, not the hour. The hour made the key change every pass, which is why
      -- a dedupe key existed for three weeks and never deduplicated anything.
      p_dedupe_key => 'failed_runs:' || to_char(now(),'YYYY-MM-DD'));
    update alert_watermark set last_alert_at = now() where watcher = 'failed_runs';
  end if;

  update alert_watermark set last_run_at = now() where watcher = 'failed_runs';
  return jsonb_build_object(
    'checked_since', v_since,
    'models_answering', v_models_answering,
    'runs_failed', v_real,
    'runs_held_by_ai_hold', v_held,
    'runs_in_declared_rehearsal', v_rehearsal,
    'crons_stale', v_stale_n,
    'new_conditions_alerted', v_alerts,
    'alerted', v_alerts > 0);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_what_if(p_question text, p_change jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sup int; v_rev numeric; v_cost numeric; v_conv numeric; v_pool int;
  v_impact jsonb; v_conf numeric; v_id bigint;
  v_d_rev numeric; v_d_leads numeric; v_d_profit numeric;
begin
  select count(*) into v_sup from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';
  select coalesce(sum(cost_aed),0) into v_cost from ai_cost_log where occurred_at>now()-interval '30 days';
  select coalesce(sum(sendable),0) into v_pool from v_supply_gap;
  v_conv := 0.05;

  if p_question ~* 'reveal fee|reduce.*fee|lower.*fee' then
    v_impact := jsonb_build_object('revenue_per_reveal','down by the discount percentage',
      'reveal_volume','unknown - no reveals have occurred, so elasticity is unmeasured',
      'net_revenue','indeterminate',
      'honest_answer','This cannot be simulated. Zero reveals have happened, so there is no price-response curve to extrapolate from. Any number would be invented.');
    v_conf := 0.15;
    -- All three stay NULL on purpose. The branch's own text says the question cannot be simulated,
    -- and a projection of 0 would contradict it.
    v_d_rev := null; v_d_leads := null; v_d_profit := null;

  elsif p_question ~* 'model price|openrouter|ai cost.*double|llm cost' then
    v_impact := jsonb_build_object('current_monthly_ai_cost_aed',round(v_cost,2),'if_doubled_aed',round(v_cost*2,2),
      'share_of_total_budget', round(100.0*v_cost*2/nullif((select sum(monthly_aed) from department_budget),0),1)||'%',
      'mitigation','Model policy already routes by task class. Prompt-cache reads are '
        ||coalesce((select round(100.0*sum(cached_in_tokens)/nullif(sum(prompt_tokens),0),1)::text
                      from ai_cost_log where occurred_at > now() - interval '30 days'),'0')
        ||'% of prompt tokens over 30 days ('
        ||coalesce((select sum(cached_in_tokens)::text from ai_cost_log
                     where occurred_at > now() - interval '30 days'),'0')
        ||' read against '
        ||coalesce((select sum(cache_write_tokens)::text from ai_cost_log
                     where occurred_at > now() - interval '30 days'),'0')
        ||' written at a 1.25x premium), so caching pays only above roughly 22% and is measured here rather than assumed.');
    v_conf := 0.8;
    -- Doubling the AI bill moves cost, not sales: the extra spend lands on profit one-for-one and
    -- the top line is untouched, so revenue is NULL rather than 0 (unmodelled, not unchanged).
    v_d_rev := null; v_d_leads := null; v_d_profit := -round(v_cost,2);

  elsif p_question ~* 'invite|supplier.*onboard|scale.*supplier' then
    v_impact := jsonb_build_object('sendable_pool',v_pool,'expected_approved_at_5pct',round(v_pool*v_conv),
      'target',860,'shortfall',greatest(0,860-round(v_pool*v_conv)),
      'note','Assumes a 5% invite-to-approved conversion, which is an assumption not an observation - no invite has converted yet.');
    v_conf := 0.45;
    -- Supply-side leads are the only dimension this branch models, and it says out loud that the
    -- 5% is an assumption. Revenue would need a conversion rate nobody has observed.
    v_d_rev := null; v_d_leads := round(v_pool*v_conv); v_d_profit := null;

  elsif p_question ~* 'saudi|expand|new market' then
    v_impact := jsonb_build_object('home_market_readiness',(select count(*) from v_supply_gap where approved>=10)||' of 86 categories at target',
      'assessment','Expanding before the home market has any onboarded supply spreads a thin pool thinner and the category knowledge is UAE-specific.');
    v_conf := 0.7;
    v_d_rev := null; v_d_leads := null; v_d_profit := null;
  else
    v_impact := jsonb_build_object('assessment','No model exists for this question yet. Add a scenario to scenario_library so it can be simulated rather than guessed.');
    v_conf := 0.2;
    v_d_rev := null; v_d_leads := null; v_d_profit := null;
  end if;

  -- THE THREE DIMENSIONS THE FOUNDER ASKED FOR, ALWAYS NAMED. Branch-shaped keys like
  -- 'net_revenue' and 'if_doubled_aed' answer the question but cannot be read uniformly across
  -- simulations, so a reader had to know which branch ran before it knew what it was looking at.
  v_impact := v_impact || jsonb_build_object(
    'projected_revenue_delta_aed', v_d_rev,
    'projected_leads_delta',       v_d_leads,
    'projected_profit_delta_aed',  v_d_profit,
    'delta_note', 'A null delta means this scenario does not model that dimension. It does not mean the delta is zero.');

  insert into simulations (scenario, result)
  values (jsonb_build_object('question',p_question,'change',p_change,'confidence',v_conf),
          -- The confidence belongs in the projection the caller reads, not only beside the question
          -- it was asked. coalesce guards the branch that builds it by hand already.
          v_impact || jsonb_build_object('confidence', coalesce((v_impact->>'confidence')::numeric, v_conf)))
  returning id into v_id;

  -- THE SIMULATION LEAVES SOMETHING TO APPROVE. Only when it actually modelled the question:
  -- v_conf is the simulator's own score for the branch it took, and below 0.5 are exactly the
  -- branches whose text says they are guesses ("No model exists for this question yet",
  -- "an assumption not an observation"). Those produce a projection to read and no action to take.
  if v_conf >= 0.5 then
    insert into agent_actions(agent, kind, status, risk, title, recommendation, detail,
                              target_table, target_id, confidence, evidence)
    values ('strategy_director', 'simulation_apply', 'pending', 'medium',
            left('Act on the simulation: ' || p_question, 200),
            coalesce(v_impact->>'assessment',
                     'The simulation returned a projection; open it to see the modelled figures.')
              || ' Approving this accepts the modelled change; the projection and its basis are on '
              || 'simulation #' || v_id || '.',
            jsonb_build_object('simulation_id', v_id, 'question', p_question,
                               'change', p_change, 'projection', v_impact),
            'simulations', v_id::text, v_conf,
            -- The real basis, not the generic stamped one: this rests on the simulation and the
            -- figures it computed, which are the two things a reader would want to check.
            jsonb_build_object('basis', 'simulation #' || v_id || ' of "' || p_question || '"',
                               'simulation_id', v_id, 'confidence', v_conf, 'projection', v_impact));
  end if;

  return jsonb_build_object('id',v_id,'question',p_question,'projection',v_impact,'confidence',v_conf,
    'basis', jsonb_build_object('approved_suppliers',v_sup,'revenue_30d',v_rev,'ai_cost_30d',round(v_cost,2),'sendable_pool',v_pool));
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_actor_coverage()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'catalogue_actor_roles',  (select count(distinct actor_role) from public.workflow_step),
    'catalogue_unresolved',   (select count(*) from (
                                 select distinct actor_role a from public.workflow_step) t
                                where t.a is not null
                                  and public.fn_org_agent_resolve(t.a) is null
                                  and lower(btrim(t.a)) not in ('owner','director','dept_head')),
    'catalogue_unresolved_names', (select coalesce(jsonb_agg(t.a order by t.a),'[]'::jsonb) from (
                                 select distinct actor_role a from public.workflow_step) t
                                where t.a is not null
                                  and public.fn_org_agent_resolve(t.a) is null
                                  and lower(btrim(t.a)) not in ('owner','director','dept_head')),
    'live_steps_unresolved',  (select count(*) from public.workflow_step_run sr
                                where sr.finished_at is null
                                  and public.fn_workflow_actor_resolve(sr.workflow_run_id, sr.actor) is null),
    'ready_dispatchable',     (select count(*) from public.workflow_step_run sr
                                join public.workflow_run r on r.id = sr.workflow_run_id
                               where sr.status='ready' and sr.finished_at is null and r.status='running'
                                 and r.workflow_key <> 'employee_task'
                                 and coalesce(sr.input->>'gate','') <> 'founder'
                                 and public.fn_workflow_actor_resolve(sr.workflow_run_id, sr.actor) is not null),
    'measured_at', now());
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_actor_resolve(p_run uuid, p_actor text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ctx jsonb; v_owner text; v_live text; v_tid bigint;
begin
  if p_actor is null or btrim(p_actor) = '' then return null; end if;

  if lower(btrim(p_actor)) not in ('owner', 'director', 'dept_head', 'department head') then
    return public.fn_org_agent_resolve(p_actor);
  end if;

  select r.context into v_ctx from public.workflow_run r where r.id = p_run;
  if v_ctx is null then return null; end if;

  -- The owner is the assignee of the task this run was raised for. employee_task runs carry
  -- context.task_id; the guard on the cast is there because context is free-form jsonb and a
  -- non-numeric task_id would abort the whole planning statement rather than skip one step.
  if coalesce(v_ctx->>'task_id','') ~ '^[0-9]+$' then
    v_tid := (v_ctx->>'task_id')::bigint;
    select t.assigned_agent into v_owner from public.org_tasks t where t.id = v_tid;
  end if;
  if v_owner is null then v_owner := nullif(v_ctx->>'agent',''); end if;
  if v_owner is null then v_owner := public.fn_org_agent_resolve(nullif(v_ctx->>'dept_key','')); end if;

  select o.agent_key into v_live from public.org_agents o where o.agent_key = v_owner and o.active;
  if v_live is null then return null; end if;

  if lower(btrim(p_actor)) = 'owner' then return v_live; end if;

  -- 'Director' on employee_task step 10 is "department head review" - the owner's own manager,
  -- which org_agents.manager_key already models for 93 of 94 employees, acyclically.
  -- The owner's active manager is the department head. If the owner has no active manager (only the
  -- ceo, the top of the org), the owner is its own department head, so 'Director' never resolves to
  -- no employee and never stalls a run at step 10.
  return coalesce(
    (select m.agent_key
       from public.org_agents o
       join public.org_agents m on m.agent_key = o.manager_key and m.active
      where o.agent_key = v_live),
    v_live);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_run_follow_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run uuid; v_run_status text;
begin
  if new.status is not distinct from old.status then return new; end if;
  if new.status not in ('done','failed','escalated','cancelled') then return new; end if;

  v_run_status := case when new.status = 'done' then 'done'
                       when new.status = 'cancelled' then 'cancelled'
                       else 'failed' end;

  for v_run in
    select r.id from public.workflow_run r
     where r.workflow_key = 'employee_task'
       and r.status = 'running'
       and (r.context->>'task_id') = new.id::text
  loop
    update public.workflow_step_run
       set status = 'skipped', finished_at = now(),
           output = coalesce(output, '{}'::jsonb) || jsonb_build_object(
             'closed_by', 'owning_org_task', 'org_task_id', new.id,
             'org_task_status', new.status,
             'used_llm', case when (new.result->>'used_llm') in ('true','false') then (new.result->>'used_llm')::boolean else null end,
             'note', case when new.status = 'cancelled'
                          then 'the owning task was cancelled; this step was never separately observed, so it is skipped rather than claimed as done'
                          else 'the owning task was performed and reviewed as one act; this step was never '
                            || 'separately observed, so it is skipped rather than claimed as done' end)
     where workflow_run_id = v_run and finished_at is null;

    update public.workflow_run
       set status      = v_run_status,
           finished_at = now(),
           updated_at  = now(),
           context     = coalesce(context,'{}'::jsonb)
                         || jsonb_build_object('closed_by','owning_org_task',
                                               'org_task_status', new.status,
                                               'used_llm', case when (new.result->>'used_llm') in ('true','false') then (new.result->>'used_llm')::boolean else null end),
           error       = case when new.status = 'done' then null
                              else jsonb_build_object('owning_org_task', new.id,
                                                      'org_task_status', new.status,
                                                      'reason', case when new.status = 'cancelled' then 'the owning org_task was cancelled' else 'the owning org_task ended ' || new.status end) end
     where id = v_run;
  end loop;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_start(p_workflow_key text, p_trigger_event_id bigint DEFAULT NULL::bigint, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run uuid; v_key text; v_corr uuid; v_first int;
begin
  if not exists (select 1 from workflow w where w.workflow_key = p_workflow_key and coalesce(w.active,true))
    then return null; end if;

  -- One run per (workflow, triggering event). Without the event there is nothing to be idempotent
  -- against, so a manual start gets its own key rather than silently colliding with the last one.
  v_key := p_workflow_key || ':' || coalesce(p_trigger_event_id::text, gen_random_uuid()::text);

  select e.correlation_id into v_corr from company_event e where e.id = p_trigger_event_id;
  -- 4 SEP 2026: a run started WITHOUT a triggering event begins its own correlation.
  -- The line above finds nothing when p_trigger_event_id is null, workflow_run.correlation_id is
  -- NOT NULL, and the insert below therefore raised 23502 on every eventless start. The line before
  -- it already anticipates exactly this case -- it mints a fresh idempotency key rather than
  -- colliding -- so the omission was in the next statement, not in the design.
  --
  -- It is the reason MASTER_PLAN 4.3's one-spine design never ran: fn_org_task_promote is the leg
  -- that lifts an org_task onto the workflow spine, it calls this with a null event because a
  -- backlog task has no event, every call raised, and the promoter's own
  -- `exception when others then null` swallowed it. Measured: 0 of 301 employee_task runs ever
  -- created carry promoted_by = fn_org_task_promote, and the raise reproduces on any backlog task.
  -- Correlation ties together work that shares a cause; a promoted task IS its own cause.
  v_corr := coalesce(v_corr, gen_random_uuid());

  insert into workflow_run (workflow_key, trigger_event_id, correlation_id, entity_type, entity_id,
                            idempotency_key, status, current_step, context, started_at)
  values (p_workflow_key, p_trigger_event_id, v_corr, p_entity_type, p_entity_id,
          v_key, 'running', 0, coalesce(p_context,'{}'::jsonb), now())
  on conflict (idempotency_key) do nothing
  returning id into v_run;

  if v_run is null then
    select id into v_run from workflow_run where idempotency_key = v_key;
    return v_run;                      -- already started; nothing to re-plan
  end if;

  -- Plan every step of the workflow up front. A run whose steps are only materialised as they are
  -- reached cannot be read as "where is this piece of work", which is the entire value of the table.
  --
  -- THE ACTOR IS RESOLVED HERE (11 Aug 2026). It used to copy workflow_step.actor_role verbatim,
  -- and actor_role is not one namespace - see the header. Resolving in the dispatcher instead
  -- would leave the stored row still addressed to nobody, which is the defect this codebase keeps
  -- reproducing. addressed_as keeps the original wording so no reassignment is silent.
  insert into workflow_step_run (workflow_run_id, step_no, actor, action_class, status,
                                 input, idempotency_key)
  select v_run, s.step_no, coalesce(x.resolved, s.actor_role), s.action_class, 'queued',
         jsonb_build_object('step', s.step, 'gate', s.gate)
           || case when x.resolved is not null and x.resolved is distinct from s.actor_role
                   then jsonb_build_object('addressed_as', s.actor_role)
                   else '{}'::jsonb end,
         v_key || '#' || s.step_no
    from workflow_step s
    cross join lateral (select public.fn_workflow_actor_resolve(v_run, s.actor_role) as resolved) x
   where s.workflow_key = p_workflow_key
   order by s.step_no
  on conflict (idempotency_key) do nothing;

  select min(step_no) into v_first from workflow_step_run where workflow_run_id = v_run;
  if v_first is null then
    -- A workflow with no steps cannot be in flight. Closing it here stops it sitting in the
    -- in-flight list forever pretending to be work.
    update workflow_run set status = 'done', finished_at = now(), updated_at = now()
     where id = v_run;
    return v_run;
  end if;

  update workflow_step_run set status = 'ready', started_at = now()
   where workflow_run_id = v_run and step_no = v_first;
  update workflow_run set current_step = v_first, updated_at = now() where id = v_run;
  return v_run;
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_start_due(p_lookback_minutes integer DEFAULT 1440)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0;
begin
  for r in
    select w.workflow_key, e.id, e.event_type, e.payload
      from company_event e
      join workflow w on w.trigger_event = e.event_type and coalesce(w.active,true)
     where p_lookback_minutes = 0
        or e.occurred_at > now() - make_interval(mins => p_lookback_minutes)
     order by e.id
     limit 200
  loop
    if not exists (select 1 from workflow_run x
                    where x.idempotency_key = r.workflow_key || ':' || r.id::text) then
      perform public.fn_workflow_start(r.workflow_key, r.id, 'company_event', r.id::text,
                                       coalesce(r.payload,'{}'::jsonb));
      n := n + 1;
    end if;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_claim(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_out jsonb; v_today int; v_cap int; v_demand_ready int; v_held boolean;
begin
  v_held := coalesce((public.fn_kernel_paid_provider_gate('anthropic/claude-sonnet-5')->>'allowed')::boolean, false) = false;

  update public.workflow_step_run sr
     set status = 'ready'
   where sr.status = 'running'
     and sr.finished_at is null
     and sr.started_at < now() - interval '15 minutes'
     and not exists (select 1 from public.action_execution x
                      where x.workflow_step_run_id = sr.id
                        and x.status in ('queued','running','succeeded'));

  select coalesce((value #>> '{}')::int, 6) into v_cap
    from public.decision_policy where key = 'workflow_reflection_steps_per_day';
  v_cap := coalesce(v_cap, 6);

  -- NON-DEMAND ONLY, and MODEL WORK ONLY: the ceiling exists to bound paid reasoning. A deterministic
  -- determination costs nothing and is not counted against it.
  select count(*) into v_today
    from public.workflow_step_run sr
   where sr.output->>'worked_by' = 'workflow_dispatch'
     and coalesce(sr.output->>'used_llm', 'true') <> 'false'
     and sr.finished_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
     and not public.fn_task_is_demand(sr.action_class);

  select count(*) into v_demand_ready
    from public.workflow_step_run sr
    join public.workflow_run r on r.id = sr.workflow_run_id
   where sr.status = 'ready'
     and sr.finished_at is null
     and r.status = 'running'
     and r.workflow_key <> 'employee_task'
     and coalesce(sr.input->>'gate','') <> 'founder'
     and public.fn_task_is_demand(sr.action_class)
     and public.fn_workflow_actor_resolve(sr.workflow_run_id, sr.actor) is not null
     and not exists (
           select 1 from public.org_action_executor e
            where e.action_class = sr.action_class and e.active and e.kind in ('edge','rpc')
              and e.risk_tier = 'low' and e.advisory_safe and e.reversible
              and not e.notifies_human
              and coalesce(e.required_authority,'') <> 'founder');

  if not v_held and v_today >= v_cap and v_demand_ready = 0 then
    return jsonb_build_object('capped', true, 'worked_today', v_today, 'cap', v_cap,
             'demand_ready', 0,
             'note', 'the daily reflection ceiling is spent and no revenue-path step is waiting; see '
                     || 'scripts/sql/the_dispatchers_ceiling_counted_revenue_work_against_reflection.sql');
  end if;

  with pick as (
    select sr.id
      from public.workflow_step_run sr
      join public.workflow_run r on r.id = sr.workflow_run_id
     where sr.status = 'ready'
       and sr.finished_at is null
       and r.status = 'running'
       -- THE ORG_TASK LANE (§4.3). An employee_task run is the promotion of one org_task into the
       -- spine; the dispatcher works it while the task is still open, and the follow trigger owns it
       -- once the task has closed or parked. A run whose task is gone is nobody's work.
       and (r.workflow_key <> 'employee_task'
            or exists (select 1 from public.org_tasks t
                        where t.id::text = r.context->>'task_id'
                          and t.status in ('assigned','in_progress')))
       and coalesce(sr.input->>'gate','') <> 'founder'
       -- the reflection ceiling is untouched: it bounds PAID reasoning, and while the model is held
       -- (v_held) nothing here can reach a paid provider. When the hold lifts the lane obeys it.
       and (public.fn_task_is_demand(sr.action_class) or v_today < v_cap or v_held)
       and public.fn_workflow_actor_resolve(sr.workflow_run_id, sr.actor) is not null
       -- parked awaiting the model: not claimed again until the hold lifts
       and not (v_held and coalesce(sr.error->>'disposition','') = 'awaiting_model')
       and (
         -- the org_task lane is always the dispatcher's: its executor (cos_execute on coordinate) was
         -- retired on 3 Sep and the sweep's low-risk predicate never accepted it
         r.workflow_key = 'employee_task'
         -- (a) no safe executor owns it: the dispatcher's row, as before
         or not exists (
             select 1 from public.org_action_executor e
              where e.action_class = sr.action_class and e.active and e.kind in ('edge','rpc')
                and e.risk_tier = 'low' and e.advisory_safe and e.reversible
                and not e.notifies_human
                and coalesce(e.required_authority,'') <> 'founder')
         -- (b) the model is held and the safe executor cannot finish it: it runs on the model, or it
         --     already left only terminal (held/cancelled/stalled) executions behind
         or (v_held and (
               exists (select 1 from public.org_action_executor e
                        where e.action_class = sr.action_class and e.active
                          and public.fn_executor_needs_model(e.target))
            -- stranded: parked held/stalled, or cancelled on a REFUSAL or a missing decision record.
            -- (A never-dispatched cancel is the sweep's to re-queue, not the dispatcher's.)
            or (exists (select 1 from public.action_execution x
                         where x.workflow_step_run_id = sr.id
                           and (x.status in ('held','stalled')
                                or (x.status = 'cancelled'
                                    and (x.response->>'invoker' = 'refused' or (x.request ? 'decision_record_id')))))
                and not exists (select 1 from public.action_execution x
                                 where x.workflow_step_run_id = sr.id
                                   and x.status in ('queued','running','succeeded')))))
       )
     -- fresh steps before retries: 24 change_deployment step-1 retries (3 attempts each before they
     -- park) must not starve a step that has never been looked at
     order by coalesce(sr.attempts, 0), sr.id
     limit greatest(least(coalesce(p_limit, 5),
                          case when v_held then coalesce(p_limit, 5)
                               else greatest(v_cap - v_today, 0) + v_demand_ready end), 1)
     for update of sr skip locked
  ), claimed as (
    update public.workflow_step_run sr
       set status = 'running', started_at = now()
      from pick
     where sr.id = pick.id
    returning sr.id, sr.workflow_run_id, sr.step_no, sr.actor, sr.action_class, sr.input, sr.attempts, sr.error
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'step_run_id',  c.id,
           'run_id',       c.workflow_run_id,
           'step_no',      c.step_no,
           'employee',     public.fn_workflow_actor_resolve(c.workflow_run_id, c.actor),
           'addressed_as', coalesce(c.input->>'addressed_as', c.actor),
           'action_class', c.action_class,
           'step',         c.input->>'step',
           'gate',         c.input->>'gate',
           'workflow_key', r.workflow_key,
           'workflow',     w.name,
           'context',      r.context,
           'attempts',     coalesce(c.attempts, 0),
           'model_held',   v_held,
           'deterministic_only', v_held,
           -- THE ORG_TASK LANE: the work is the task, not the loop step it is recorded under.
           'lane',                 case when r.workflow_key = 'employee_task' and t.id is not null then 'org_task' else 'workflow_step' end,
           'org_task_id',           t.id,
           'org_task_title',        t.title,
           'org_task_detail',       left(coalesce(t.detail, ''), 2000),
           'org_task_dept',         t.dept_key,
           'org_task_action_class', t.action_class,
           'org_task_subject',      case when t.id is null then null
                                         else public.fn_org_task_subject(t.title, t.action_class, t.dept_key) end,
           'stranded_reason', case
              when exists (select 1 from public.org_action_executor e
                            where e.action_class = c.action_class and e.active and e.kind in ('edge','rpc')
                              and e.risk_tier = 'low' and e.advisory_safe and e.reversible
                              and not e.notifies_human)
               then coalesce((select 'executor ' || coalesce(x.executor, e2.target) || ' left status=' || x.status
                                     || coalesce(' (' || (x.response->>'reason') || ')', '')
                                from public.action_execution x
                                join public.org_action_executor e2 on e2.action_class = c.action_class and e2.active
                               where x.workflow_step_run_id = c.id
                               order by x.created_at desc limit 1),
                             'executor runs on the held paid model; not queued')
              else null end,
           'prior_steps', (select coalesce(jsonb_agg(jsonb_build_object(
                                    'step_no', p.step_no,
                                    'step',    p.input->>'step',
                                    'by',      coalesce(p.output->>'employee', p.actor),
                                    'outcome', left(coalesce(p.output->>'outcome',
                                                             p.output->>'note', ''), 600))
                                  order by p.step_no), '[]'::jsonb)
                             from (select p2.* from public.workflow_step_run p2
                                    where p2.workflow_run_id = c.workflow_run_id
                                      and p2.step_no < c.step_no
                                      and p2.status = 'done'
                                      and coalesce(p2.output->>'outcome', p2.output->>'note','') <> ''
                                    order by p2.step_no desc
                                    limit 3) p)
         ) order by c.id), '[]'::jsonb)
    into v_out
    from claimed c
    join public.workflow_run r on r.id = c.workflow_run_id
    left join public.workflow w on w.workflow_key = r.workflow_key
    left join public.org_tasks t on r.workflow_key = 'employee_task'
                                and t.id::text = r.context->>'task_id';

  return v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_deterministic_done(p_step_run_id bigint, p_output jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr           record;
  v_sim        numeric;
  v_floor      numeric := 0.85;
  v_terms      int;
  v_employee   text;
  v_dept       text;
  v_trace      uuid;
  v_review     bigint;
  v_superseded int := 0;
  v_res        text;
  v_out        jsonb;
  -- the record applied
  v_pb_id text; v_pb_title text; v_pb_type text; v_pb_content text; v_pb_sd jsonb;
  -- facts + rendering
  v_facts jsonb; v_bound int; v_deliv text; v_outcome text;
  -- executor
  ex record; v_has_ex boolean := false; v_needs_model boolean := false; v_exec_status text; v_exec_id uuid;
  v_exec_result jsonb; v_req_args int; v_kind text := null; v_source text := 'playbook_rendered';
  v_queued boolean := false; v_refused text; v_err text; v_target text;
  -- measurement
  v_llm int := 0; v_cost int := 0; v_used_llm boolean;
  v_disp text; v_mode text;
begin
  select s.id, s.workflow_run_id, s.step_no, s.actor, s.action_class, s.input, s.attempts, s.started_at, s.output as prev_output,
         r.workflow_key, r.context, r.correlation_id, r.trigger_event_id
    into sr
    from public.workflow_step_run s
    join public.workflow_run r on r.id = s.workflow_run_id
   where s.id = p_step_run_id and s.status = 'running' and s.finished_at is null;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'step is not held running by a dispatcher');
  end if;

  v_sim      := nullif(p_output->>'similarity', '')::numeric;
  v_terms    := nullif(p_output->>'terms_matched', '')::int;
  v_employee := coalesce(nullif(p_output->>'employee',''), sr.actor);

  -- FALSE-SUCCESS GUARDS. Nothing below runs unless the determination has substance. The floors are the
  -- applier's own (0.85 cosine AND keyword corroboration), so a caller cannot pass on cosine alone.
  if coalesce(p_output->>'playbook_record_id','') = '' then
    return jsonb_build_object('ok', false, 'reason', 'no playbook_record_id: a determination must cite the company knowledge it applied');
  end if;
  if v_sim is null or v_sim < v_floor then
    return jsonb_build_object('ok', false, 'reason', 'similarity ' || coalesce(v_sim::text,'null') || ' is below the apply floor ' || v_floor);
  end if;
  if v_terms is null or v_terms < 2 then
    return jsonb_build_object('ok', false, 'reason', 'terms_matched ' || coalesce(v_terms::text,'null') || ' is below the corroboration floor of 2 step terms');
  end if;
  select k.record_id, k.title, k.record_type, k.content, k.structured_data
    into v_pb_id, v_pb_title, v_pb_type, v_pb_content, v_pb_sd
    from public.ops_knowledge k
   where k.record_id = p_output->>'playbook_record_id' and k.runtime_eligible;
  if v_pb_id is null then
    return jsonb_build_object('ok', false, 'reason', 'playbook ' || (p_output->>'playbook_record_id') || ' is not a runtime-eligible ops_knowledge record');
  end if;
  if v_pb_type not in ('decision_playbook','decision_rule','standard_operating_procedure','exception_playbook') then
    return jsonb_build_object('ok', false, 'reason', 'record ' || v_pb_id || ' is a ' || v_pb_type || ', not an actionable kind');
  end if;

  -- THE FACTS, then the deliverable AS A FUNCTION OF THEM.
  v_facts := public.fn_workflow_step_facts(sr.id);
  v_bound := coalesce((v_facts->>'facts_bound')::int, 0);

  -- THE EXECUTOR. Read the registry row and decide from it, in words.
  select e.action_class, e.kind, e.target, e.active, e.risk_tier, e.advisory_safe, e.reversible,
         e.notifies_human, e.unattended_ok, e.required_authority, e.compensation_action_class
    into ex
    from public.org_action_executor e
   where e.action_class = sr.action_class and e.active
   order by e.kind limit 1;
  v_has_ex := found;
  if v_has_ex then v_target := ex.target; end if;
  if not v_has_ex then
    v_exec_status := 'none: no active executor is mapped to action_class ' || coalesce(sr.action_class, '(null)');
  else
    v_kind := ex.kind;
    v_needs_model := public.fn_executor_needs_model(ex.target);
    if v_needs_model then
      v_exec_status := 'held: ' || ex.target || ' is routed to a model task class by fn_task_class and the paid provider is held; not invoked';
    elsif coalesce(ex.required_authority, '') = 'founder' then
      v_exec_status := 'withheld: ' || ex.target || ' is reserved to the founder';
    elsif ex.notifies_human then
      v_exec_status := 'withheld: ' || ex.target || ' notifies a human (org_action_executor.notifies_human); the deterministic close never sends';
    elsif not (ex.risk_tier = 'low' and ex.advisory_safe and ex.reversible) then
      v_exec_status := format('withheld: %s is risk_tier=%s advisory_safe=%s reversible=%s; the close invokes low/advisory_safe/reversible only',
                              ex.target, ex.risk_tier, ex.advisory_safe, ex.reversible);
    elsif ex.kind not in ('rpc', 'edge') then
      v_exec_status := 'withheld: ' || ex.target || ' is a ' || ex.kind || ' executor and no invoker handles that kind';
    elsif exists (select 1 from public.action_execution x where x.workflow_step_run_id = sr.id and x.status in ('queued','running')) then
      return jsonb_build_object('ok', false, 'reason', 'executor ' || ex.target || ' is already queued or running for this step; the sweep settles it');
    elsif ex.kind = 'rpc' then
      select coalesce(p.pronargs - p.pronargdefaults, -1) into v_req_args
        from pg_proc p where p.proname = ex.target and p.pronamespace = 'public'::regnamespace
       order by p.pronargs limit 1;
      if v_req_args is null then
        v_exec_status := 'failed: public.' || ex.target || '() does not exist';
      elsif v_req_args > 0 then
        v_exec_status := 'withheld: public.' || ex.target || '() requires ' || v_req_args || ' argument(s) a workflow step cannot supply';
      else
        v_exec_id := gen_random_uuid();
        begin
          execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from public.%I() t', ex.target) into v_exec_result;
          insert into public.action_execution(id, correlation_id, workflow_step_run_id, action_class, executor, idempotency_key,
                                              risk_tier, reversible, request, response, status, attempts, started_at, finished_at)
          values (v_exec_id, coalesce(sr.correlation_id, gen_random_uuid()), sr.id, sr.action_class, ex.target,
                  'workflow_step:' || sr.id || ':det:' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
                  ex.risk_tier, ex.reversible,
                  jsonb_build_object('workflow_step_run_id', sr.id, 'workflow_run_id', sr.workflow_run_id, 'step_no', sr.step_no,
                                     'actor', sr.actor, 'source', 'fn_workflow_step_deterministic_done', 'kind', 'rpc'),
                  jsonb_build_object('invoker', 'succeeded', 'at', now(), 'kind', 'rpc', 'inline', true,
                                     'result_rows', coalesce(jsonb_array_length(v_exec_result), 0),
                                     'result', case when pg_column_size(v_exec_result) > 20000 then to_jsonb(left(v_exec_result::text, 20000)) else v_exec_result end),
                  'succeeded', 1, now(), now());
          v_exec_status := 'ran: public.' || ex.target || '() inline, ' || coalesce(jsonb_array_length(v_exec_result), 0)
                           || ' row(s), action_execution ' || v_exec_id;
          v_source := 'executor:' || ex.target;
        exception when others then
          v_err := sqlstate || ' ' || left(sqlerrm, 400);
          -- the failure is a fact: record it and refuse the close, so the step is released with the reason
          insert into public.action_execution(id, correlation_id, workflow_step_run_id, action_class, executor, idempotency_key,
                                              risk_tier, reversible, request, response, status, attempts, started_at, finished_at)
          values (v_exec_id, coalesce(sr.correlation_id, gen_random_uuid()), sr.id, sr.action_class, ex.target,
                  'workflow_step:' || sr.id || ':det:' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
                  ex.risk_tier, ex.reversible,
                  jsonb_build_object('workflow_step_run_id', sr.id, 'workflow_run_id', sr.workflow_run_id, 'step_no', sr.step_no,
                                     'actor', sr.actor, 'source', 'fn_workflow_step_deterministic_done', 'kind', 'rpc'),
                  jsonb_build_object('invoker', 'failed', 'at', now(), 'kind', 'rpc', 'inline', true, 'error', v_err),
                  'failed', 1, now(), now());
          return jsonb_build_object('ok', false, 'reason', 'executor public.' || ex.target || '() failed: ' || v_err,
                                    'action_execution_id', v_exec_id);
        end;
      end if;
    else -- edge, deterministic
      select x.response->>'reason' into v_refused
        from public.action_execution x
       where x.workflow_step_run_id = sr.id and x.response->>'invoker' = 'refused'
       order by x.created_at desc limit 1;
      if v_refused is not null then
        v_exec_status := 'withheld: the invoker refused ' || ex.target || ' for this step earlier (' || left(v_refused, 200) || '); not re-queued';
      elsif exists (select 1 from public.action_execution x
                     where x.workflow_step_run_id = sr.id and x.request->>'source' = 'fn_workflow_step_deterministic_done') then
        select 'withheld: an earlier re-queue of ' || ex.target || ' for this step ended ' || x.status into v_exec_status
          from public.action_execution x
         where x.workflow_step_run_id = sr.id and x.request->>'source' = 'fn_workflow_step_deterministic_done'
         order by x.created_at desc limit 1;
      else
        v_exec_id := gen_random_uuid();
        insert into public.action_execution(id, correlation_id, workflow_step_run_id, action_class, executor, idempotency_key,
                                            risk_tier, reversible, request, status, attempts)
        values (v_exec_id, coalesce(sr.correlation_id, gen_random_uuid()), sr.id, sr.action_class, ex.target,
                'workflow_step:' || sr.id || ':det:' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
                ex.risk_tier, ex.reversible,
                jsonb_build_object('workflow_step_run_id', sr.id, 'workflow_run_id', sr.workflow_run_id, 'step_no', sr.step_no,
                                   'actor', sr.actor, 'input', coalesce(sr.input, '{}'::jsonb),
                                   'source', 'fn_workflow_step_deterministic_done', 'kind', 'edge'),
                'queued', 0);
        v_queued := true;
        v_exec_status := 'queued: ' || ex.target || ' as action_execution ' || v_exec_id || ' for the HTTP invoker; the step closes when the sweep settles it';
        v_source := 'executor:' || ex.target;
      end if;
    end if;
  end if;

  -- THE DELIVERABLE, rendered from the facts, with the executor line.
  v_deliv := public.fn_workflow_step_render(v_facts, v_pb_title, v_pb_type, v_pb_content, v_pb_sd);
  v_deliv := regexp_replace(v_deliv, E'\nAPPLIED RECORD: ',
               E'- executor: ' || coalesce(v_exec_status, '?') || E'\n\nAPPLIED RECORD: ');

  -- THE DISPOSITION, earned.
  -- 5 SEP 2026, from the skeptic that audited this routine: 'determined' used to mean "not routed
  -- to a model", and both rows that carried it had executed nothing (executor withheld). A label
  -- that reads as 'executed' must be EARNED by an execution: an action_execution this close created
  -- and which succeeded. Facts bound and rendered, but no executor ran (none mapped, withheld,
  -- queued for the HTTP invoker, refused) is 'rendered' -- true, and not the same word as done.
  v_disp := case when v_bound = 0 then 'needs_narrative'
                 when v_needs_model then 'advisory_held_model'
                 when v_exec_id is not null and exists (select 1 from public.action_execution x
                        where x.id = v_exec_id and x.status = 'succeeded') then 'determined'
                 else 'rendered' end;
  v_mode := case when v_disp = 'determined' then 'determined' else 'advisory' end;
  v_outcome := case when v_disp = 'needs_narrative'
                    then 'No fact was bound for this step (no metric, goal, event payload or prior conclusion); the record "'
                         || v_pb_title || '" applies as written and the step needs narrative from a reviewer or the model path.'
                    else coalesce(nullif(v_facts#>>'{derived,band}', '') || ' ' || coalesce(v_facts#>>'{metric,label}', '') || ': ', '')
                         || 'applied ' || v_pb_type || ' "' || v_pb_title || '" to ' || v_bound || ' bound fact(s)'
                         || case when v_facts#>>'{derived,cause}' is not null then '; cause ' || (v_facts#>>'{derived,cause}') else '' end
                         || '; executor ' || split_part(coalesce(v_exec_status, 'none'), ':', 1) end;

  -- used_llm IS A MEASUREMENT: the provider ledgers since the dispatcher claimed this step.
  select count(*) into v_llm  from public.llm_attempt a where a.fn = 'workflow_dispatch' and a.created_at >= sr.started_at;
  select count(*) into v_cost from public.ai_cost_log c where c.fn = 'workflow_dispatch' and c.occurred_at >= sr.started_at;
  v_used_llm := (v_llm + v_cost) > 0;

  select o.department into v_dept from public.org_agents o where o.agent_key = v_employee;

  -- The sealed record of what was decided, on what, by which rule, with what confidence.
  insert into public.decision_trace(
      correlation_id, causation_event_id, entity_type, entity_id, decision_type,
      proposed_by, decided_by, policy_keys, knowledge_refs, evidence_refs, alternatives,
      assumptions, risk, confidence, authority_result,
      decision, outcome_status, agent_key, department_id, task_class,
      knowledge_versions, source_freshness, tools_requested, tools_executed, tool_result_refs,
      uncertainty, escalation_decision, proposed_action, expected_outcome,
      model, provider, input_tokens, output_tokens, estimated_cost_aed, final_status, sealed_at)
  values (
      coalesce(sr.correlation_id, gen_random_uuid()), sr.trigger_event_id,
      'workflow_step_run', sr.id::text, 'deterministic_playbook_application',
      v_employee, 'fn_workflow_step_deterministic_done', array['deterministic_first']::text[],
      jsonb_build_array(jsonb_build_object('record_id', v_pb_id, 'title', v_pb_title, 'record_type', v_pb_type,
                                           'similarity', v_sim, 'terms_matched', v_terms)),
      jsonb_build_array(jsonb_build_object('workflow_run_id', sr.workflow_run_id, 'workflow_key', sr.workflow_key,
                                           'step_no', sr.step_no, 'step', sr.input->>'step',
                                           'facts', v_facts)),
      coalesce(p_output->'candidates', '[]'::jsonb),
      jsonb_build_array('the corroborated nearest actionable company record is the applicable one for this step',
                        'the facts read at close time are the facts the step is about'),
      jsonb_build_object('level', 'low', 'note', case when v_source like 'executor:%'
                                                      then 'a low-risk, advisory-safe, reversible executor was invoked; moves no money, sends nothing, approves nobody'
                                                      else 'determination only; moves no money, sends nothing, approves nobody' end),
      v_sim,
      jsonb_build_object('mode', v_mode, 'gate', coalesce(sr.input->>'gate', 'none'), 'paid_provider', 'held', 'executor', v_exec_status),
      jsonb_build_object('determination', left(v_deliv, 8000), 'outcome', v_outcome, 'disposition', v_disp,
                         'determination_source', v_source, 'basis', 'facts of the step rendered against the corroborated record; no model call'),
      'pending', v_employee, v_dept, 'workflow_step',
      '{}'::jsonb, jsonb_build_object('ops_knowledge', 'live at decision time', 'facts_read_at', v_facts->>'read_at'),
      case when v_target is not null then array[v_target] else '{}'::text[] end,
      case when v_source like 'executor:%' then array[v_target] else '{}'::text[] end,
      case when v_exec_id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('action_execution_id', v_exec_id)) end,
      case v_disp when 'determined' then 'determined from ' || v_bound || ' bound fact(s); queued for review'
                  when 'advisory_held_model' then 'determined from ' || v_bound || ' bound fact(s), but the step''s executor needs the held model; advisory until the hold lifts'
                  else 'no fact bound: the record applies as written; narrative is needed' end,
      'review_queued', 'close the workflow step with disposition ' || v_disp,
      'the run advances; a reviewer can overturn the determination',
      'none', 'deterministic', 0, 0, 0, 'auto_done', now())
  returning id into v_trace;

  -- Never a silent pass: the determination is queued for review, with everything needed to overturn it.
  insert into public.review_queue(kind, dept_key, title, summary, payload, status)
  values ('deterministic_step', v_dept,
          left(initcap(replace(v_disp, '_', ' ')) || ': ' || sr.workflow_key || ' step ' || sr.step_no || ' — ' || coalesce(sr.input->>'step',''), 240),
          left(v_outcome, 600),
          jsonb_build_object('workflow_run_id', sr.workflow_run_id, 'step_run_id', sr.id, 'step_no', sr.step_no,
                             'employee', v_employee, 'playbook_record_id', v_pb_id,
                             'playbook_title', v_pb_title, 'similarity', v_sim, 'terms_matched', v_terms,
                             'decision_trace_id', v_trace, 'disposition', v_disp,
                             'determination_source', v_source, 'executor_status', v_exec_status,
                             'facts_bound', v_bound, 'used_llm', v_used_llm),
          'pending')
  returning id into v_review;

  -- The executor's parked/stranded attempt is superseded: fn_action_release_held must not re-run it at
  -- launch over a step that is already closed.
  update public.action_execution
     set status = 'cancelled', finished_at = coalesce(finished_at, now()),
         response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
           'superseded_at', now(), 'superseded_by', 'deterministic determination',
           'decision_trace_id', v_trace, 'prior_status', status)
   where workflow_step_run_id = sr.id and status in ('held','stalled');
  get diagnostics v_superseded = row_count;

  v_out := coalesce(p_output, '{}'::jsonb) || jsonb_build_object(
             'mode', v_mode,
             'deliverable', left(v_deliv, 20000),
             'outcome', left(v_outcome, 400),
             'disposition', v_disp,
             'determination_source', v_source,
             'executor_status', v_exec_status,
             'executor_kind', v_kind,
             'action_execution_id', v_exec_id,
             'facts_bound', v_bound,
             'facts', v_facts,
             'used_llm', v_used_llm,
             'used_llm_basis', 'measured at close: ' || v_llm || ' llm_attempt + ' || v_cost
                               || ' ai_cost_log row(s) by workflow_dispatch since the step was claimed at ' || sr.started_at,
             'decision_trace_id', v_trace,
             'review_queue_id', v_review,
             'review_status', 'pending',
             'superseded_executions', v_superseded);

  if v_queued then
    -- the step stays running with a queued execution; fn_workflow_step_sweep settles it when the
    -- executor answers, merging the response over this determination
    update public.workflow_step_run set output = v_out where id = sr.id;
    return jsonb_build_object('ok', true, 'advanced', 'awaiting executor ' || v_target, 'decision_trace_id', v_trace,
                              'review_queue_id', v_review, 'superseded_executions', v_superseded,
                              'disposition', v_disp, 'determination_source', v_source,
                              'executor_status', v_exec_status, 'action_execution_id', v_exec_id,
                              'facts_bound', v_bound, 'used_llm', v_used_llm);
  end if;

  v_res := public.fn_workflow_step_done(sr.workflow_run_id, sr.step_no, v_out, 'done');

  return jsonb_build_object('ok', true, 'advanced', v_res, 'decision_trace_id', v_trace,
                            'review_queue_id', v_review, 'superseded_executions', v_superseded,
                            'disposition', v_disp, 'determination_source', v_source,
                            'executor_status', v_exec_status, 'action_execution_id', v_exec_id,
                            'facts_bound', v_bound, 'used_llm', v_used_llm);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_done(p_run uuid, p_step_no integer, p_output jsonb DEFAULT '{}'::jsonb, p_status text DEFAULT 'done'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_next int;
begin
  update workflow_step_run
     set status = p_status, output = coalesce(p_output,'{}'::jsonb), finished_at = now(),
         attempts = coalesce(attempts,0) + 1
   where workflow_run_id = p_run and step_no = p_step_no;
  if not found then return 'no such step'; end if;

  if p_status <> 'done' then
    update workflow_run set status = 'failed', finished_at = now(), updated_at = now(),
           error = jsonb_build_object('failed_step', p_step_no, 'status', p_status)
     where id = p_run;
    return 'failed at step ' || p_step_no;
  end if;

  select min(step_no) into v_next from workflow_step_run
   where workflow_run_id = p_run and step_no > p_step_no and status = 'queued';

  if v_next is null then
    update workflow_run set status = 'done', finished_at = now(), updated_at = now(),
           current_step = p_step_no
     where id = p_run;
    return 'run complete';
  end if;

  update workflow_step_run set status = 'ready', started_at = now()
   where workflow_run_id = p_run and step_no = v_next;
  update workflow_run set current_step = v_next, updated_at = now() where id = p_run;
  return 'advanced to step ' || v_next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_facts(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- step + run
  v_step_no int; v_actor text; v_action_class text; v_input jsonb; v_started timestamptz; v_run uuid;
  v_wf text; v_ctx jsonb; v_trigger bigint; v_r_entity_type text; v_r_entity_id text;
  -- event
  v_ev_type text; v_ev_entity_type text; v_ev_entity_id text; v_ev_payload jsonb; v_ev_at timestamptz; v_ev_actor text;
  -- metric
  v_mk text; v_label text; v_owner text; v_val numeric; v_tgt numeric; v_dir text; v_state text; v_err text;
  v_taken timestamptz; v_definition text; v_in_scorecard boolean := false;
  v_hist jsonb; v_consec int := 0; v_ever_met boolean := false; v_n_snap int := 0; snap record; v_off boolean;
  v_metric jsonb := null; v_band text; v_gap numeric; v_att numeric; v_cause text; v_cause_why text;
  -- goals
  v_goals jsonb := null; v_failing jsonb := null; v_prior jsonb := '[]'::jsonb;
  v_bound int := 0; v_derived jsonb := '{}'::jsonb;
begin
  select s.step_no, s.actor, s.action_class, s.input, s.started_at, s.workflow_run_id,
         r.workflow_key, coalesce(r.context, '{}'::jsonb), r.trigger_event_id, r.entity_type, r.entity_id
    into v_step_no, v_actor, v_action_class, v_input, v_started, v_run,
         v_wf, v_ctx, v_trigger, v_r_entity_type, v_r_entity_id
    from public.workflow_step_run s
    join public.workflow_run r on r.id = s.workflow_run_id
   where s.id = p_step_run_id;
  if v_run is null then return null; end if;

  select e.event_type, e.entity_type, e.entity_id, e.payload, e.occurred_at, e.actor
    into v_ev_type, v_ev_entity_type, v_ev_entity_id, v_ev_payload, v_ev_at, v_ev_actor
    from public.company_event e where e.id = v_trigger;
  v_ev_payload := coalesce(v_ev_payload, '{}'::jsonb);

  -- THE METRIC THIS RUN IS ABOUT. Keyed by the event's entity (kpi.missed carries metric_key as
  -- entity_id), else by the context's metric_key, else by the label the emitter wrote.
  v_mk := case when v_ev_entity_type = 'metric' then v_ev_entity_id
               when v_ctx ? 'metric_key' then v_ctx->>'metric_key'
               when v_r_entity_type = 'metric' then v_r_entity_id
               else (select d.metric_key from public.metric_definition d
                      where d.label = coalesce(v_ctx->>'label', v_ev_payload->>'label') limit 1) end;
  -- the emitter's numbers are facts even when the metric is a fixture with no definition row
  v_label := coalesce(v_ctx->>'label', v_ev_payload->>'label');
  v_val   := coalesce(nullif(v_ev_payload->>'value','')::numeric, nullif(v_ctx->>'value','')::numeric);
  v_tgt   := coalesce(nullif(v_ev_payload->>'target','')::numeric, nullif(v_ctx->>'target','')::numeric);
  v_state := coalesce(v_ev_payload->>'state', v_ctx->>'state');
  v_dir   := coalesce(v_ev_payload->>'direction', v_ctx->>'direction');

  if v_mk is not null then
    select sc.label, sc.owner_dept, sc.value, sc.target, sc.direction, sc.state, sc.error, sc.taken_at, sc.definition, true
      into v_label, v_owner, v_val, v_tgt, v_dir, v_state, v_err, v_taken, v_definition, v_in_scorecard
      from public.v_bi_scorecard sc where sc.metric_key = v_mk;
    v_in_scorecard := coalesce(v_in_scorecard, false);
    if not v_in_scorecard then
      -- the scorecard select found nothing and nulled the targets: restore the emitter's numbers
      v_label := coalesce(v_ctx->>'label', v_ev_payload->>'label');
      v_val   := coalesce(nullif(v_ev_payload->>'value','')::numeric, nullif(v_ctx->>'value','')::numeric);
      v_tgt   := coalesce(nullif(v_ev_payload->>'target','')::numeric, nullif(v_ctx->>'target','')::numeric);
      v_state := coalesce(v_ev_payload->>'state', v_ctx->>'state');
      v_dir   := coalesce(v_ev_payload->>'direction', v_ctx->>'direction');
    end if;

    -- snapshot history, newest first, and the leading run of misses — the metric_lifecycle playbooks'
    -- TARGET_MIS_SET test reads ">= 3 consecutive measured periods, never met since the target was set"
    v_hist := '[]'::jsonb;
    for snap in
      select s.value, s.error, s.taken_at from public.metric_snapshot s
       where s.metric_key = v_mk order by s.taken_at desc limit 12
    loop
      v_n_snap := v_n_snap + 1;
      if v_n_snap <= 6 then
        v_hist := v_hist || jsonb_build_object('value', snap.value, 'error', snap.error, 'taken_at', snap.taken_at);
      end if;
      v_off := snap.error is null and snap.value is not null and v_tgt is not null
               and ((v_dir = 'up' and snap.value < v_tgt * 0.7) or (v_dir = 'down' and snap.value > v_tgt * 1.3));
      if v_off and v_consec = v_n_snap - 1 then v_consec := v_consec + 1; end if;
      if snap.error is null and snap.value is not null and v_tgt is not null
         and ((v_dir = 'up' and snap.value >= v_tgt) or (v_dir = 'down' and snap.value <= v_tgt)) then
        v_ever_met := true;
      end if;
    end loop;
  end if;

  if v_label is not null or v_val is not null or v_mk is not null then
    -- band by the scorecard's own rule when the scorecard did not already say
    v_band := coalesce(v_state,
                case when v_err is not null then 'ERROR'
                     when v_val is null or v_tgt is null then 'UNMEASURED'
                     when v_dir = 'up'   and v_val >= v_tgt then 'ON_TARGET'
                     when v_dir = 'down' and v_val <= v_tgt then 'ON_TARGET'
                     when v_dir = 'up'   and v_val >= v_tgt * 0.7 then 'BEHIND'
                     when v_dir = 'down' and v_val <= v_tgt * 1.3 then 'BEHIND'
                     when v_val is not null and v_tgt is not null then 'OFF_TARGET' end);
    v_gap := case when v_val is not null and v_tgt is not null then v_val - v_tgt end;
    v_att := case when v_val is null or v_tgt is null then null
                  when coalesce(v_dir,'up') = 'up' then
                       case when v_tgt > 0 then round(100 * v_val / v_tgt, 1)
                            when v_val <= 0 then 100 else null end
                  else case when v_val > 0 then least(100, round(100 * v_tgt / v_val, 1)) else 100 end end;
    -- cause class, by the "root cause" playbook's own definitions, from what is measurable here
    if v_band = 'ERROR' or v_err is not null then
      v_cause := 'INSTRUMENT'; v_cause_why := 'the latest snapshot carries an error: ' || coalesce(v_err, '(null)');
    elsif v_band = 'UNMEASURED' then
      v_cause := 'INSTRUMENT'; v_cause_why := 'value or target is null; the metric is UNMEASURED, not failing';
    elsif v_band in ('ON_TARGET', 'BEHIND') then
      v_cause := 'NONE'; v_cause_why := 'band ' || v_band || ': no miss to attribute';
    elsif v_consec >= 3 and not v_ever_met and coalesce(btrim(v_definition), '') = '' then
      v_cause := 'TARGET_MIS_SET';
      v_cause_why := v_consec || ' consecutive OFF_TARGET snapshots, never met in ' || v_n_snap
                     || ' recorded, and metric_definition.definition is empty (no documented basis)';
    else
      v_cause := 'EXECUTION';
      v_cause_why := 'default per the playbook: input existed and the instrument is sound. TARGET_MIS_SET test: '
                     || v_consec || ' consecutive OFF_TARGET snapshot(s) (needs >= 3), ever met = ' || v_ever_met
                     || ', documented basis = ' || (coalesce(btrim(v_definition), '') <> '')
                     || case when v_n_snap = 0 then '; no snapshot history for this key' else '' end;
    end if;
    v_metric := jsonb_strip_nulls(jsonb_build_object(
      'metric_key', v_mk, 'label', v_label, 'owner_dept', v_owner, 'in_scorecard', v_in_scorecard,
      'value', v_val, 'target', v_tgt, 'direction', v_dir, 'state', v_state, 'error', v_err,
      'taken_at', v_taken, 'snapshots_newest_first', v_hist, 'snapshots_read', v_n_snap,
      'consecutive_off_target', v_consec, 'ever_met', v_ever_met));
    v_bound := v_bound + (v_val is not null)::int + (v_tgt is not null)::int + (v_band is not null)::int
               + (v_n_snap > 0)::int;
    v_derived := jsonb_strip_nulls(jsonb_build_object(
      'band', v_band, 'gap', v_gap, 'attainment_pct', v_att, 'cause', v_cause, 'cause_evidence', v_cause_why,
      'direction', v_dir));
  end if;

  -- GOALS AT RISK and FAILING METRICS (goal.at_risk carries both as arrays of keys / labels)
  if jsonb_typeof(v_ctx->'goals_at_risk') = 'array' or jsonb_typeof(v_ev_payload->'goals_at_risk') = 'array' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'key', g.key, 'goal', g.goal, 'metric', g.metric, 'target_value', g.target_value, 'unit', g.unit,
             'direction', g.direction, 'owner_dept', g.owner_dept, 'horizon', g.horizon, 'deadline', g.deadline,
             'active', g.active,
             'latest_period', (select jsonb_build_object('period', p.period_label, 'actual', p.actual_value,
                                                         'target', p.target_value, 'status', p.status)
                                 from public.goal_period p where p.goal_key = g.key
                                order by p.updated_at desc limit 1))) order by g.key), '[]'::jsonb)
      into v_goals
      from public.company_goals g
     where g.key in (select jsonb_array_elements_text(coalesce(v_ctx->'goals_at_risk', v_ev_payload->'goals_at_risk')));
    -- a fixture goal with no company_goals row is still a named fact of the trigger
    select coalesce(v_goals, '[]'::jsonb) || coalesce(jsonb_agg(jsonb_build_object('key', k, 'in_company_goals', false)), '[]'::jsonb)
      into v_goals
      from jsonb_array_elements_text(coalesce(v_ctx->'goals_at_risk', v_ev_payload->'goals_at_risk')) k
     where not exists (select 1 from public.company_goals g where g.key = k);
    v_bound := v_bound + coalesce(jsonb_array_length(v_goals), 0);
  end if;
  if jsonb_typeof(v_ctx->'failing_metrics') = 'array' or jsonb_typeof(v_ev_payload->'failing_metrics') = 'array' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'label', lbl, 'metric_key', sc.metric_key, 'value', sc.value, 'target', sc.target,
             'direction', sc.direction, 'state', sc.state, 'error', sc.error, 'taken_at', sc.taken_at,
             'owner_dept', sc.owner_dept, 'in_scorecard', (sc.metric_key is not null))) order by lbl), '[]'::jsonb)
      into v_failing
      from jsonb_array_elements_text(coalesce(v_ctx->'failing_metrics', v_ev_payload->'failing_metrics')) lbl
      left join public.v_bi_scorecard sc on sc.label = lbl;
    v_bound := v_bound + coalesce(jsonb_array_length(v_failing), 0);
  end if;

  -- WHAT THIS RUN ALREADY CONCLUDED (outcome lines only, in order)
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'step_no', p.step_no, 'step', p.input->>'step', 'by', coalesce(p.output->>'employee', p.actor),
           'outcome', left(coalesce(p.output->>'outcome', p.output->>'note', ''), 600),
           'disposition', p.output->>'disposition', 'determination_source', p.output->>'determination_source',
           'executor_status', p.output->>'executor_status')) order by p.step_no), '[]'::jsonb)
    into v_prior
    from public.workflow_step_run p
   where p.workflow_run_id = v_run and p.step_no < v_step_no and p.status = 'done';
  v_bound := v_bound + (select count(*) from jsonb_array_elements(v_prior) x where coalesce(x->>'outcome','') <> '')::int;

  -- the trigger payload's own scalar facts, beyond the ones already read above
  v_bound := v_bound + (select count(*) from jsonb_each(v_ev_payload) e
                         where jsonb_typeof(e.value) in ('string','number','boolean')
                           and e.key not in ('label','value','target','state','direction'))::int;

  return jsonb_strip_nulls(jsonb_build_object(
    'step', jsonb_build_object('workflow_key', v_wf, 'step_no', v_step_no, 'step', v_input->>'step',
                               'gate', v_input->>'gate', 'actor', v_actor, 'action_class', v_action_class,
                               'claimed_at', v_started),
    'trigger', case when v_ev_type is null then null else
                 jsonb_build_object('event_id', v_trigger, 'event_type', v_ev_type, 'entity_type', v_ev_entity_type,
                                    'entity_id', v_ev_entity_id, 'actor', v_ev_actor, 'occurred_at', v_ev_at,
                                    'payload', v_ev_payload) end,
    'context', v_ctx,
    'metric', v_metric,
    'goals_at_risk', v_goals,
    'failing_metrics', v_failing,
    'prior_steps', v_prior,
    'derived', v_derived,
    'facts_bound', v_bound,
    'read_at', now()));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_release(p_step_run_id bigint, p_reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_attempts int; v_disp text; v_task bigint; v_dept text; v_known int; v_parked int := 0;
begin
  select coalesce(attempts,0) + 1 into v_attempts from public.workflow_step_run
   where id = p_step_run_id and status = 'running' and finished_at is null;
  if not found then return 'not held'; end if;

  v_disp := case when v_attempts >= 3 and coalesce(p_reason,'') ~* '^no company playbook'
                 then 'awaiting_model' else 'retry' end;

  update public.workflow_step_run
     set status   = 'ready',
         attempts = v_attempts,
         error    = jsonb_build_object('released_at', now(), 'reason', left(coalesce(p_reason,''), 500),
                                       'released_by', 'workflow_dispatch',
                                       'attempts', v_attempts,
                                       'disposition', v_disp,
                                       'note', case when v_disp = 'awaiting_model'
                                                    then 'parked: no company playbook covered this step in ' || v_attempts
                                                      || ' deterministic attempts; it waits for the ~5% model path (held) and is not retried until the hold lifts'
                                                    else null end)
   where id = p_step_run_id and status = 'running' and finished_at is null;

  if v_disp = 'awaiting_model' then
    select t.id, t.dept_key into v_task, v_dept
      from public.workflow_step_run s
      join public.workflow_run r on r.id = s.workflow_run_id and r.workflow_key = 'employee_task'
      join public.org_tasks t on t.id::text = r.context->>'task_id'
     where s.id = p_step_run_id and t.status in ('assigned','in_progress');

    if v_task is not null then
      v_known := public.fn_org_task_lane_knowledge(v_dept);
      update public.org_tasks
         set status     = 'blocked',
             updated_at = now(),
             last_run_at = now(),
             result     = coalesce(result, '{}'::jsonb) || jsonb_build_object(
               'parked', jsonb_build_object(
                 'at', now(), 'by', 'workflow_dispatch (org_task lane)',
                 'attempts', v_attempts,
                 'reason', left(coalesce(p_reason,''), 500),
                 'knowledge_at_park', v_known,
                 'note', 'No corroborated actionable company playbook covers this task, so it was not '
                      || 'closed and it is not retried in a loop. The org_task lane is deterministic '
                      || 'only — its model executor (cos_execute on coordinate) was retired on 3 Sep — '
                      || 'so what this waits for is AUTHORED KNOWLEDGE, not inference. '
                      || 'fn_org_task_promote re-opens it when the department holds more actionable '
                      || 'in-scope knowledge than the ' || v_known || ' records it held here.'))
       where id = v_task;
      get diagnostics v_parked = row_count;
    end if;
  end if;

  return case when v_disp = 'awaiting_model'
              then 'parked awaiting model' || case when v_parked > 0 then ' (org_task ' || v_task || ' parked)' else '' end
              else 'released' end;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_render(p_facts jsonb, p_title text, p_record_type text, p_content text, p_structured jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  f jsonb := coalesce(p_facts, '{}'::jsonb);
  d jsonb := coalesce(p_facts->'derived', '{}'::jsonb);
  m jsonb := p_facts->'metric';
  t text := '';
  sel text[]; k text; v jsonb; s text; x jsonb; n int := 0; lines text := '';
begin
  t := 'DETERMINATION — ' || coalesce(f#>>'{step,workflow_key}', '?') || ' step ' || coalesce(f#>>'{step,step_no}', '?')
       || ': ' || coalesce(f#>>'{step,step}', '') || E'\n'
       || 'Decided by ' || coalesce(f#>>'{step,actor}', '?') || ' at ' || coalesce(f->>'read_at', '') || ' from '
       || coalesce(f->>'facts_bound', '0') || ' bound fact(s); no model call.' || E'\n\n';

  t := t || E'FACTS THIS STEP DECIDED FROM\n';
  if f ? 'trigger' then
    t := t || '- trigger: ' || coalesce(f#>>'{trigger,event_type}', '?') || ' on ' || coalesce(f#>>'{trigger,entity_type}', '?')
         || ' ' || coalesce(f#>>'{trigger,entity_id}', '?') || ' at ' || coalesce(f#>>'{trigger,occurred_at}', '?')
         || ' (event ' || coalesce(f#>>'{trigger,event_id}', '?') || ') payload ' || coalesce((f#>'{trigger,payload}')::text, '{}') || E'\n';
  else
    t := t || E'- trigger: none recorded on this run\n';
  end if;
  if m is not null then
    t := t || '- metric: ' || coalesce(m->>'label', m->>'metric_key', '?')
         || case when (m->>'metric_key') is not null then ' [' || (m->>'metric_key') || ']' else '' end
         || ' value=' || coalesce(m->>'value', 'null') || ' target=' || coalesce(m->>'target', 'null')
         || ' direction=' || coalesce(m->>'direction', 'unknown') || ' state=' || coalesce(m->>'state', d->>'band', 'unknown')
         || case when (m->>'error') is not null then ' ERROR=' || (m->>'error') else '' end
         || case when (m->>'taken_at') is not null then ' taken_at=' || (m->>'taken_at') else '' end
         || ' owner=' || coalesce(m->>'owner_dept', 'unknown')
         || ' in_scorecard=' || coalesce(m->>'in_scorecard', 'false') || E'\n'
         || '- snapshots (newest first, ' || coalesce(m->>'snapshots_read', '0') || ' read): ' || coalesce((m->'snapshots_newest_first')::text, '[]')
         || '; consecutive_off_target=' || coalesce(m->>'consecutive_off_target', '0') || ' ever_met=' || coalesce(m->>'ever_met', 'false') || E'\n';
  end if;
  if jsonb_typeof(f->'goals_at_risk') = 'array' then
    for x in select * from jsonb_array_elements(f->'goals_at_risk') loop
      t := t || '- goal at risk: ' || coalesce(x->>'key', '?')
           || case when coalesce(x->>'in_company_goals', 'true') = 'false' then ' (no company_goals row)'
                   else ' "' || coalesce(x->>'goal', '') || '" target ' || coalesce(x->>'target_value', 'null') || ' ' || coalesce(x->>'unit', '')
                        || ' dir=' || coalesce(x->>'direction', '?') || ' owner=' || coalesce(x->>'owner_dept', '?')
                        || ' deadline=' || coalesce(x->>'deadline', 'none')
                        || case when x ? 'latest_period' then ' latest period ' || (x->'latest_period')::text else ' (no goal_period yet)' end end
           || E'\n';
    end loop;
  end if;
  if jsonb_typeof(f->'failing_metrics') = 'array' then
    for x in select * from jsonb_array_elements(f->'failing_metrics') loop
      t := t || '- failing metric: ' || coalesce(x->>'label', '?')
           || case when coalesce(x->>'in_scorecard', 'false') = 'true'
                   then ' [' || (x->>'metric_key') || '] value=' || coalesce(x->>'value', 'null') || ' target=' || coalesce(x->>'target', 'null')
                        || ' state=' || coalesce(x->>'state', '?') || ' owner=' || coalesce(x->>'owner_dept', '?')
                        || case when (x->>'error') is not null then ' ERROR=' || (x->>'error') else '' end
                   else ' (not on v_bi_scorecard: the emitter''s label only)' end
           || E'\n';
    end loop;
  end if;
  if jsonb_typeof(f->'prior_steps') = 'array' and jsonb_array_length(f->'prior_steps') > 0 then
    for x in select * from jsonb_array_elements(f->'prior_steps') loop
      t := t || '- prior step ' || coalesce(x->>'step_no', '?') || ' (' || coalesce(x->>'by', '?') || ', '
           || coalesce(x->>'disposition', 'no disposition') || '): ' || coalesce(x->>'outcome', '') || E'\n';
    end loop;
  else
    t := t || E'- prior steps: none concluded yet; this is the first step of the run to decide anything\n';
  end if;
  if f ? 'context' and (f->'context') <> '{}'::jsonb then
    t := t || '- run context: ' || (f->'context')::text || E'\n';
  end if;

  t := t || E'\nDETERMINED\n';
  if m is not null then
    t := t || '- variance: ' || coalesce(m->>'label', '?') || ' is ' || coalesce(d->>'band', 'unknown')
         || case when d ? 'gap' then ' — gap ' || (d->>'gap') || ' against target ' || coalesce(m->>'target', 'null')
                                   || ' (direction ' || coalesce(d->>'direction', 'unknown') || ')' else '' end
         || case when d ? 'attainment_pct' then ', attainment ' || (d->>'attainment_pct') || '%' else '' end || E'\n'
         || '- cause class: ' || coalesce(d->>'cause', 'not established') || ' — ' || coalesce(d->>'cause_evidence', '') || E'\n';
  end if;

  -- resolve keyed maps in structured_data at the facts
  sel := array_remove(array[d->>'band', d->>'cause', d->>'direction', f#>>'{trigger,event_type}', f#>>'{step,gate}',
                            lower(d->>'band'), lower(d->>'cause')], null);
  if p_structured is not null and jsonb_typeof(p_structured) = 'object' then
    for k, v in select * from jsonb_each(p_structured) loop
      if jsonb_typeof(v) = 'object' then
        foreach s in array coalesce(sel, '{}'::text[]) loop
          if v ? s then
            n := n + 1;
            lines := lines || '- ' || k || '[' || s || '] → ' || case when jsonb_typeof(v->s) = 'string' then v->>s else (v->s)::text end || E'\n';
          end if;
        end loop;
      end if;
    end loop;
  end if;
  if n > 0 then
    t := t || 'Selected from "' || coalesce(p_title, '?') || '" at the facts above (' || n || ' rule(s)):' || E'\n' || lines;
  else
    t := t || 'No keyed rule in "' || coalesce(p_title, '?') || '" resolves at these facts; the record applies as written below.' || E'\n';
  end if;

  t := t || E'\nAPPLIED RECORD: ' || coalesce(p_record_type, '?') || ' "' || coalesce(p_title, '?') || E'"\n'
       || coalesce(p_content, '');
  if p_structured is not null and p_structured <> '{}'::jsonb then
    t := t || E'\n\nSTRUCTURED DATA OF THE RECORD:\n' || jsonb_pretty(p_structured);
  end if;
  return t;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_sweep(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s record; v_settled int := 0; v_q int := 0; v_key text; v_res text; v_out jsonb; v_parked int; v_noclass int;
        v_cap int; v_reflection_today int; v_throttled int; v_true_stall int; v_status text; v_note text;
        v_ineligible int; v_why text; v_held boolean;
begin
  v_held := coalesce((public.fn_kernel_paid_provider_gate('anthropic/claude-sonnet-5')->>'allowed')::boolean, false) = false;

  -- 1. SETTLE what the invoker has already finished. A determination stored on the step before its
  --    executor ran (fn_workflow_step_deterministic_done's queued-edge path) is kept under the response.
  for s in
    select x.status, x.response, x.executor, r.id sid, r.workflow_run_id, r.step_no, r.output prev_output
      from public.action_execution x
      join public.workflow_step_run r on r.id = x.workflow_step_run_id
     where x.workflow_step_run_id is not null
       and x.status in ('succeeded','failed')
       and r.finished_at is null
     order by r.id
     limit 50
  loop
    v_res := public.fn_workflow_step_done(
      s.workflow_run_id, s.step_no,
      coalesce(s.prev_output, '{}'::jsonb)
        || coalesce(s.response, '{}'::jsonb)
        || jsonb_build_object('worked_by', 'executor:' || coalesce(s.executor, '?'),
                              'executor_status', case when s.status = 'succeeded' then 'ran: ' else 'failed: ' end || coalesce(s.executor, '?'))
        || case when v_held then jsonb_build_object('used_llm', false, 'used_llm_basis', 'paid provider held (kernel K12) at settle time') else '{}'::jsonb end,
      case when s.status = 'succeeded' then 'done' else 'failed' end);
    v_settled := v_settled + 1;
  end loop;

  -- 1b. RE-QUEUE the executions the old fn_execution_sweep cancelled before the invoker ever ran them
  --     (observed=cancelled, never dispatched, no decision record, not superseded). A deterministic
  --     executor such as uptime_check or ai_health is simply run, late; a model-backed one stays for the
  --     dispatcher while the model is held. The idempotency key is the same row, so this is an UPDATE.
  for s in
    select x.id xid, r.id sid
      from public.action_execution x
      join public.workflow_step_run r on r.id = x.workflow_step_run_id
      join public.org_action_executor e on e.action_class = r.action_class and e.active
     where x.status = 'cancelled'
       and r.status = 'ready' and r.finished_at is null
       and x.response->>'invoker' is null
       and x.response->>'observed' = 'cancelled'
       and not (x.request ? 'decision_record_id')
       and not (x.response ? 'superseded_by')
       and e.kind in ('edge','rpc') and e.risk_tier = 'low' and e.advisory_safe and e.reversible
       and not e.notifies_human and coalesce(e.required_authority,'') <> 'founder'
       and not (v_held and public.fn_executor_needs_model(e.target))
     order by r.id
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    update public.action_execution
       set status = 'queued', finished_at = null,
           response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
             'requeued_at', now(),
             'requeue_reason', 'cancelled by fn_execution_sweep before the invoker ran it (no decision record was ever expected); re-queued 4 Sep 2026')
     where id = s.xid;
    update public.workflow_step_run set status = 'running' where id = s.sid and status = 'ready';
    v_q := v_q + 1;
  end loop;

  -- 2. QUEUE the ready steps a registered, low-risk, reversible edge executor can run WITHOUT
  --    delivering a message to a person — and, while the model is held, without needing the model.
  for s in
    select r.id, r.workflow_run_id, r.step_no, r.actor, r.action_class, r.input,
           e.target, e.risk_tier, e.reversible
      from public.workflow_step_run r
      join public.org_action_executor e on e.action_class = r.action_class
     where r.status = 'ready' and r.finished_at is null
       and e.kind in ('edge','rpc') and e.active
       and e.risk_tier = 'low' and e.advisory_safe and e.reversible
       and not e.notifies_human
       and coalesce(e.required_authority,'') <> 'founder'
       and not (v_held and public.fn_executor_needs_model(e.target))
       and not exists (select 1 from public.action_execution x
                        where x.idempotency_key = 'workflow_step:' || r.id)
     order by r.id
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    v_key := 'workflow_step:' || s.id;
    insert into public.action_execution(id, correlation_id, action_class, executor, idempotency_key,
                                        risk_tier, reversible, request, status, attempts,
                                        workflow_step_run_id)
    values (gen_random_uuid(), gen_random_uuid(), s.action_class, s.target, v_key,
            s.risk_tier, s.reversible,
            jsonb_build_object('workflow_step_run_id', s.id,
                               'workflow_run_id', s.workflow_run_id,
                               'step_no', s.step_no,
                               'actor', s.actor,
                               'input', coalesce(s.input, '{}'::jsonb),
                               'source', 'fn_workflow_step_sweep'),
            'queued', 0, s.id)
    on conflict (idempotency_key) do nothing;

    update public.workflow_step_run set status = 'running' where id = s.id and status = 'ready';
    v_q := v_q + 1;
  end loop;

  select count(*), count(*) filter (where action_class is null)
    into v_parked, v_noclass
    from public.workflow_step_run where status = 'ready' and finished_at is null;

  select coalesce((value #>> '{}')::int, 6) into v_cap
    from public.decision_policy where key = 'workflow_reflection_steps_per_day';
  v_cap := coalesce(v_cap, 6);

  select count(*) into v_reflection_today
    from public.action_execution x
   where x.workflow_step_run_id is not null
     and x.created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
     and not public.fn_task_is_demand(x.action_class);

  select count(*) into v_throttled
    from public.workflow_step_run sr
    join public.workflow_run r on r.id = sr.workflow_run_id
   where sr.status = 'ready' and sr.finished_at is null
     and sr.action_class is not null
     and r.status = 'running'
     and r.workflow_key <> 'employee_task'
     and coalesce(sr.input->>'gate','') <> 'founder'
     and not public.fn_task_is_demand(sr.action_class)
     and v_reflection_today >= v_cap;

  select count(*), string_agg(distinct why, '; ') into v_ineligible, v_why from (
    select sr.id,
           case when e.action_class is null then 'no executor is mapped to ' || sr.action_class
                when e.kind not in ('edge','rpc') then sr.action_class || ' is a ' || e.kind || ' executor and no invoker handles that kind'
                when not e.active then sr.action_class || ' executor is inactive'
                when e.risk_tier <> 'low' then sr.action_class || ' is risk_tier ' || e.risk_tier
                when not e.advisory_safe then sr.action_class || ' is not advisory_safe'
                when not e.reversible then sr.action_class || ' is not reversible'
                when e.notifies_human then sr.action_class || ' notifies a human'
                when v_held and public.fn_executor_needs_model(e.target) then
                     sr.action_class || ' runs on the paid model, which is held; the dispatcher works it deterministically'
                when exists(select 1 from public.action_execution x where x.workflow_step_run_id = sr.id)
                     and not exists(select 1 from public.action_execution x
                                     where x.workflow_step_run_id = sr.id
                                       and x.status in ('queued','running','succeeded')) then
                     sr.action_class || ' has only a terminal (cancelled/failed/held) action_execution; while the model is held the dispatcher works it deterministically'
           end as why
      from public.workflow_step_run sr
      left join public.org_action_executor e on e.action_class = sr.action_class
     where sr.status = 'ready' and sr.finished_at is null and sr.action_class is not null
  ) q where why is not null;
  v_ineligible := coalesce(v_ineligible, 0);
  v_true_stall := greatest(v_parked - v_noclass - v_throttled - v_ineligible, 0);

  v_out := jsonb_build_object(
    'settled', v_settled, 'queued', v_q, 'ran_at', now(), 'model_held', v_held,
    'parked', v_parked, 'parked_without_action_class', v_noclass,
    'parked_throttled_by_reflection_ceiling', v_throttled,
    'reflection_worked_today', v_reflection_today, 'reflection_cap', v_cap,
    'parked_ineligible_by_policy', v_ineligible,
    'parked_ineligible_because', coalesce(v_why, ''),
    'parked_unexplained', v_true_stall,
    'ready_runnable', (select count(*) from public.workflow_step_run r
                         join public.org_action_executor e on e.action_class = r.action_class
                        where r.status = 'ready' and e.kind in ('edge','rpc') and e.active
                          and e.risk_tier='low' and e.advisory_safe and e.reversible
                          and not e.notifies_human),
    'ready_held_notifies_human', (select count(*) from public.workflow_step_run r
                                    join public.org_action_executor e on e.action_class = r.action_class
                                   where r.status = 'ready' and e.notifies_human),
    'never_finished', (select count(*) from public.workflow_step_run where finished_at is null));

  v_status := case when v_true_stall > 0 and v_q = 0 and v_settled = 0 then 'error' else 'ok' end;
  v_note := 'settled ' || v_settled || ', queued ' || v_q || ', parked ' || v_parked
         || ' (' || v_noclass || ' awaiting an action_class, ' || v_throttled
         || ' held by the reflection ceiling at ' || v_reflection_today || '/' || v_cap || ' today, '
         || v_ineligible || ' ineligible by policy'
         || case when v_why is null or v_why = '' then '' else ' (' || left(v_why, 300) || ')' end
         || ', ' || v_true_stall || ' unexplained)';
  if v_status = 'error' then
    v_note := 'STALLED: ' || v_true_stall || ' workflow step(s) are ready, carry an action_class, '
           || 'and are not explained by the reflection ceiling. ' || v_note;
  end if;

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('workflow_step_sweep', v_status, v_out, v_note, now(), now());

  if v_noclass > 0 then
    begin
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select 'exec', 'Classify the workflow steps no executor can run',
             v_noclass || ' workflow_step_run row(s) are ready with no action_class, so nothing can '
             || 'ever pick them up and their runs never complete. The gap is in the DEFINITIONS: '
             || 'employee_task, rfq_handling, payment, refund, complaint, supplier_onboarding, '
             || 'customer_registration, invoice_approval, campaign_publishing and '
             || 'supplier_suspension carry no action_class on any step. Classifying them will make '
             || 'the queued backlog FIRE, so check org_action_executor.notifies_human, risk_tier '
             || 'and reversible per class first - refund reaches Stripe and needs the founder.',
             'proposed', 'gated', false, 'incident_fix'
      where not exists (select 1 from public.org_tasks
                         where title = 'Classify the workflow steps no executor can run'
                           and status <> 'done');
    exception when others then null; end;
  end if;

  -- Stranded steps are the dispatcher's while the model is held (fn_workflow_step_claim). The dedup
  -- backlog task is raised only when the hold is NOT in force, i.e. when nothing else will take them.
  if not v_held and (select count(*) from public.workflow_step_run sr
               where sr.status='ready' and sr.finished_at is null and sr.action_class is not null
                 and exists(select 1 from public.action_execution x where x.workflow_step_run_id=sr.id)
                 and not exists(select 1 from public.action_execution x
                                 where x.workflow_step_run_id=sr.id and x.status in ('queued','running','succeeded'))) > 0 then
    begin
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select 'exec', 'Re-open workflow steps stranded by a cancelled action',
             (select count(*) from public.workflow_step_run sr
               where sr.status='ready' and sr.finished_at is null and sr.action_class is not null
                 and exists(select 1 from public.action_execution x where x.workflow_step_run_id=sr.id)
                 and not exists(select 1 from public.action_execution x
                                 where x.workflow_step_run_id=sr.id and x.status in ('queued','running','succeeded')))
             || ' workflow step(s) are ready but each has only a terminal (cancelled/failed) '
             || 'action_execution, so the sweep will not re-queue over it. Re-open them for a fresh '
             || 'attempt or drive the review-decision loop they await; a cancelled action must also settle its step.',
             'proposed', 'gated', false, 'incident_fix'
      where not exists (select 1 from public.org_tasks
                         where title = 'Re-open workflow steps stranded by a cancelled action'
                           and status <> 'done');
    exception when others then null; end;
  end if;

  return v_out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_working_days_between(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date; n int := 0; last date;
begin
  if p_from is null or p_to is null or p_to <= p_from then return 0; end if;
  d := (p_from at time zone 'Asia/Dubai')::date + 1;
  last := (p_to at time zone 'Asia/Dubai')::date;
  while d <= last loop
    if public.fn_is_working_day(d) then n := n + 1; end if;
    d := d + 1;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_write_decision_trace(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id       uuid;
  v_agent    text := nullif(p->>'agent_key','');
  v_role     text;
  v_dept     text;
  v_mgr      text;
  v_dobj     text;
  v_corr     uuid := coalesce(nullif(p->>'correlation_id','')::uuid, gen_random_uuid());
begin
  if v_agent is null then
    raise exception 'fn_write_decision_trace: agent_key is required. A trace that cannot name who decided is not evidence.';
  end if;

  -- Identity is resolved SERVER-SIDE from the roster. A model cannot label its own trace with
  -- someone else's role, which is the whole point of separating role_id from agent_key.
  select a.department, a.manager_key, d.north_star
    into v_dept, v_mgr, v_dobj
    from org_agents a left join org_departments d on d.dept_key = a.department
   where a.agent_key = v_agent;

  v_role := coalesce(nullif(p->>'role_id',''),
                     (select i.packaged_role_id from org_role_identity i
                       where i.agent_key = v_agent order by i.packaged_role_id limit 1));

  insert into decision_trace (
    correlation_id, entity_type, entity_id, decision_type, proposed_by, decided_by,
    policy_keys, knowledge_refs, evidence_refs, alternatives, assumptions, risk,
    confidence, authority_result, decision, outcome_status,
    task_id, agent_key, role_id, department_id, manager_id, task_class,
    company_objective, department_objective, relevant_kpi,
    knowledge_versions, source_freshness, tools_requested, tools_executed, tool_result_refs,
    uncertainty, escalation_decision, proposed_action, expected_outcome, review_date,
    model, provider, input_tokens, output_tokens, estimated_cost_aed, final_status
  ) values (
    v_corr,
    coalesce(nullif(p->>'entity_type',''),'agent_task'),
    nullif(p->>'entity_id',''),
    coalesce(nullif(p->>'decision_type',''),'agent_decision'),
    v_agent,
    coalesce(nullif(p->>'decided_by',''), v_agent),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'policy_keys','[]'::jsonb)) x), '{}'),
    coalesce(p->'knowledge_refs','[]'::jsonb),
    coalesce(p->'evidence_refs','[]'::jsonb),
    coalesce(p->'alternatives','[]'::jsonb),
    coalesce(p->'assumptions','[]'::jsonb),
    coalesce(p->'risk','{}'::jsonb),
    nullif(p->>'confidence','')::numeric,
    coalesce(p->'authority_result','{}'::jsonb),
    coalesce(p->'decision','{}'::jsonb),
    coalesce(nullif(p->>'outcome_status',''),'pending'),
    nullif(p->>'task_id',''), v_agent, v_role, v_dept, v_mgr, nullif(p->>'task_class',''),
    -- The canonical company objective, read from the row that owns it rather than restated here:
    -- company_goals.revenue_annual = "Reach AED 1,000,000 annual revenue", target 1000000 AED.
    coalesce(nullif(p->>'company_objective',''),
             (select g.goal || ' (' || g.target_value::text || ' ' || coalesce(g.unit,'') || ')'
                from company_goals g where g.key = 'revenue_annual' and g.active limit 1)),
    coalesce(nullif(p->>'department_objective',''), v_dobj),
    nullif(p->>'relevant_kpi',''),
    coalesce(p->'knowledge_versions','{}'::jsonb),
    coalesce(p->'source_freshness','{}'::jsonb),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'tools_requested','[]'::jsonb)) x), '{}'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'tools_executed','[]'::jsonb)) x), '{}'),
    coalesce(p->'tool_result_refs','[]'::jsonb),
    nullif(p->>'uncertainty',''), nullif(p->>'escalation_decision',''),
    nullif(p->>'proposed_action',''), nullif(p->>'expected_outcome',''),
    nullif(p->>'review_date','')::date,
    nullif(p->>'model',''), nullif(p->>'provider',''),
    nullif(p->>'input_tokens','')::integer, nullif(p->>'output_tokens','')::integer,
    nullif(p->>'estimated_cost_aed','')::numeric, nullif(p->>'final_status','')
  ) returning id into v_id;

  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_agent_ops(p_agent text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare ca public.category_agents%rowtype; pr public.prompts%rowtype;
  runs_total int; runs_24h int; runs_7d int; ok_runs int; last_run timestamptz; last_status text;
  avg_ms numeric; kn_updated timestamptz; kn_count int; mem_count int; health text;
  v_dept text; v_cap int; v_open int; v_queue int; v_goal jsonb; v_rep public.agent_reputation%rowtype;
begin
  select * into ca from public.category_agents where slug=p_agent;
  select * into pr from public.prompts where key=p_agent;

  -- RESOLVE HERE, NOT AT THE TOP. PLACEMENT IS LOAD-BEARING (15 Aug 2026).
  --
  -- Everything below this line reads org_agents, agent_runs, agent_knowledge, agent_memory,
  -- agent_actions, decision_log, employee_kpi_history, knowledge_exam_results and skills_matrix by
  -- agent_key, and every one of those missed for an employee addressed by an alias - so the whole
  -- workspace drawer came back empty for them: no runs, no knowledge, no KPIs, no learning curve.
  --
  -- But the TWO lookups above are keyed differently. category_agents.slug and prompts.key are
  -- alias-shaped: 14 alias values are also category_agents slugs, and none of the 132 slugs equals
  -- any org_agents.agent_key. Resolving before them would blank the name, emoji and persona for
  -- exactly the employees this repairs - trading an empty drawer for an anonymous one.
  p_agent := coalesce(public.fn_org_agent_resolve(p_agent), p_agent);
  select count(*), count(*) filter (where started_at>now()-interval '24 hours'),
         count(*) filter (where started_at>now()-interval '7 days'),
         count(*) filter (where status='ok'),
         max(started_at),
         coalesce(round(avg(extract(epoch from (finished_at-started_at))*1000) filter (where finished_at is not null),0),0)
    into runs_total, runs_24h, runs_7d, ok_runs, last_run, avg_ms
    from public.agent_runs where agent=p_agent;
  select status into last_status from public.agent_runs where agent=p_agent order by started_at desc limit 1;
  select count(*), max(updated_at) into kn_count, kn_updated from public.agent_knowledge where agent_key=p_agent;
  select count(*) into mem_count from public.agent_memory where agent_key=p_agent;
  health := case
    when last_status is null then 'idle'
    when last_status in ('error','failed') then 'degraded'
    when last_run < now()-interval '3 days' then 'stale'
    else 'healthy' end;

  select a.department, a.max_open_tasks into v_dept, v_cap
    from public.org_agents a where a.agent_key = p_agent;
  select * into v_rep from public.agent_reputation where agent_key = p_agent;

  -- The employee's own open items, and the open work sitting in their department.
  select count(*) into v_queue from public.agent_actions
   where agent = p_agent and status in ('pending','held_for_review','proposed','open');
  select count(*) into v_open from public.org_tasks
   where dept_key = v_dept and coalesce(status,'') <> 'done';

  -- CURRENT GOAL, resolved down the chain until something real answers.
  select case
    when o.objective is not null then jsonb_build_object(
      'objective', o.objective, 'horizon', o.horizon, 'status', o.status,
      'goal_source', 'department_objective', 'dept', v_dept)
    when cg.goal is not null then jsonb_build_object(
      'objective', cg.goal, 'horizon', cg.horizon, 'metric', cg.metric,
      'target_value', cg.target_value, 'unit', cg.unit,
      'goal_source', 'company_goals', 'dept', v_dept)
    when d.north_star is not null then jsonb_build_object(
      'objective', d.north_star, 'horizon', 'standing',
      'goal_source', 'department_north_star', 'dept', v_dept)
    else jsonb_build_object('objective', null, 'goal_source', 'none', 'dept', v_dept)
  end into v_goal
  from (select 1) _
  left join lateral (select * from public.department_objective x
                      where x.dept_key = v_dept and x.active
                      order by x.sort nulls last, x.updated_at desc limit 1) o on true
  left join lateral (select * from public.company_goals c
                      where c.owner_dept = v_dept and c.active
                      order by c.sort nulls last limit 1) cg on true
  left join public.org_departments d on d.dept_key = v_dept;

  return jsonb_build_object(
    'identity', jsonb_build_object('key',p_agent,'name',coalesce(ca.name,pr.description,p_agent),
       'emoji',ca.emoji,'active',coalesce(ca.active,true),'persona',ca.persona,
       'department', v_dept,
       'prompt_version',pr.active_version,'prompt_desc',pr.description,'prompt_owner',pr.owner,'prompt_updated',pr.updated_at,
       'knowledge_updated',kn_updated),
    'health', jsonb_build_object('status',health,'last_run',last_run,'last_status',last_status),
    'performance', jsonb_build_object('runs_total',runs_total,'runs_24h',runs_24h,'runs_7d',runs_7d,
       'ok_rate', case when runs_total>0 then round(100.0*ok_runs/runs_total,1) else null end,
       'avg_duration_ms',avg_ms),

    -- PERFORMANCE AS A TREND, NOT A POINT (11 Aug 2026). Every number above is a single current
    -- value, so the drawer could show how this employee is doing and never whether it is getting
    -- better or worse. employee_kpi_history writes one row per KPI per UTC day with a unique index
    -- that makes a fabricated trend impossible; this is its first reader. Attainment is averaged
    -- across the employee's KPIs for the day, so the series is "how this person performed", not
    -- one arbitrary KPI of theirs. Oldest-first because that is the order a line is drawn in.
    'kpi_trend', (select coalesce(jsonb_agg(jsonb_build_object(
                        'label', to_char(t.measured_on, 'DD Mon'),
                        'v', t.attainment,
                        'kpis', t.n) order by t.measured_on), '[]'::jsonb)
                    from (select h.measured_on,
                                 round(avg(h.attainment)::numeric, 1) attainment,
                                 count(*) n
                            from public.employee_kpi_history h
                           where h.agent_key = p_agent
                             and h.measured_on > (now() at time zone 'utc')::date - 90
                           group by h.measured_on
                           order by h.measured_on desc
                           limit 30) t),

    -- ── THE SIX THAT WERE COMPUTED AND NEVER DELIVERED ─────────────────────────────────────────
    'goal', v_goal,

    'tasks', jsonb_build_object(
      'mine_open', v_queue,
      'department', v_dept,
      'department_open', v_open,
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'id',t.id,'title',t.title,'status',t.status,'tier',t.tier,
                 'needs_founder',t.needs_founder,'created_at',t.created_at,'last_run_at',t.last_run_at)
               order by (coalesce(t.status,'')='done'), t.created_at desc)
             from (select * from public.org_tasks where dept_key = v_dept
                    and coalesce(status,'') <> 'done' order by created_at desc limit 12) t), '[]'::jsonb)),

    'decisions', coalesce((select jsonb_agg(jsonb_build_object(
                 'id',l.id,'kind',l.kind,'decision',l.decision,'confidence',l.confidence,
                 'route_to',l.route_to,'reasons',l.reasons,'sources',l.sources,'at',l.created_at)
               order by l.created_at desc)
             from (select * from public.decision_log where actor = p_agent
                    order by created_at desc limit 10) l), '[]'::jsonb),

    'confidence', jsonb_build_object(
      'reputation_score', v_rep.score, 'tier', v_rep.tier,
      'correctness', v_rep.correctness, 'reliability', v_rep.reliability,
      'learning_speed', v_rep.learning_speed, 'computed_at', v_rep.computed_at,
      'avg_decided', (select round(avg(confidence)::numeric, 2) from public.decision_log
                       where actor = p_agent and confidence is not null),
      'decided_with_confidence', (select count(*) from public.decision_log
                                   where actor = p_agent and confidence is not null)),

    'workload', jsonb_build_object(
      'open_tasks', v_open, 'queue_depth', v_queue, 'capacity', v_cap,
      'workload_pct', case when coalesce(v_cap,0) > 0
                           then round(100.0 * (v_open + v_queue) / v_cap, 1) else null end,
      'state', case when coalesce(v_cap,0) = 0 then 'unset'
                    when (v_open + v_queue) > v_cap then 'over'
                    when (v_open + v_queue) > v_cap * 0.8 then 'tight' else 'ok' end),

    'plans', coalesce((select jsonb_agg(jsonb_build_object(
                 'objective',p.objective,'horizon',p.horizon,'status',p.status,'scope','department')
               order by p.sort nulls last)
             from public.department_objective p where p.dept_key = v_dept and p.active), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_build_object(
                 'objective',o.objective,'horizon',o.horizon,'measure',o.measure,'scope','operating_system')
               order by o.id)
             from public.os_objective o
             where o.active and o.os_key = (select r.os_key from public.os_responsibility r
                                             where r.responsibility = v_dept limit 1)), '[]'::jsonb),

    -- WHAT THIS EMPLOYEE IS SUPPOSED TO KNOW (13 Aug 2026). employee_knowledge holds 900 rows over
    -- 66 employees - the domains each one is expected to cover and at what depth - and had NO
    -- browser-reachable reader at all. The `knowledge` block below is a different table:
    -- agent_knowledge is what has been WRITTEN for them, this is the curriculum they are measured
    -- against. Showing only the first without the second means a drawer can look full while the
    -- employee covers one of twelve domains they are meant to hold.
    'curriculum', jsonb_build_object(
       'domains', (select count(*) from public.employee_knowledge ek where ek.agent_key = p_agent),
       'rows', coalesce((select jsonb_agg(jsonb_build_object('domain',ek.domain_key,'depth',ek.depth,'layer',ek.layer_no)
                                order by ek.layer_no nulls last, ek.domain_key)
                           from public.employee_knowledge ek where ek.agent_key = p_agent),'[]'::jsonb),
       'by_depth', coalesce((select jsonb_object_agg(d.depth, d.n)
                               from (select coalesce(ek.depth,'unspecified') depth, count(*) n
                                       from public.employee_knowledge ek where ek.agent_key = p_agent
                                      group by 1) d),'{}'::jsonb)),
    'knowledge', jsonb_build_object('count',kn_count,'updated',kn_updated,

       'topics', coalesce((select jsonb_agg(distinct topic) from public.agent_knowledge where agent_key=p_agent and topic is not null),'[]'::jsonb),
       'recent', coalesce((select jsonb_agg(jsonb_build_object('topic',topic,'priority',priority,'updated',updated_at) order by updated_at desc)
                    from (select * from public.agent_knowledge where agent_key=p_agent order by updated_at desc limit 6) x),'[]'::jsonb)),
    'memory', jsonb_build_object('count',mem_count,
       'recent', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'content',left(content,140),'importance',importance,'at',created_at) order by created_at desc)
                    from (select * from public.agent_memory where agent_key=p_agent order by created_at desc limit 6) x),'[]'::jsonb)),
    'queue', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'risk',risk,'status',status,'recommendation',recommendation,'created_at',created_at,
                   -- NOT HIS unless the kind's policy is 'founder' (a refund). The holder is the role that decides it.
                   'holder', public.fn_action_holder(x.kind, x.agent),
                   'yours', exists (select 1 from public.agent_action_kind_policy kp where kp.kind = x.kind and kp.policy = 'founder')) order by created_at desc)
                 from (select * from public.agent_actions where agent=p_agent and status in ('pending','held_for_review','proposed','open') order by created_at desc limit 12) x),'[]'::jsonb),
    'conversations', coalesce((select jsonb_agg(jsonb_build_object('role',role,'content',left(content,160),'at',created_at) order by created_at desc)
                 from (select * from public.agent_chats where agent_key=p_agent order by created_at desc limit 8) x),'[]'::jsonb),
    -- LEARNING PROGRESS. The employee workspace showed goal, tasks, decisions, confidence,
    -- workload, plans, knowledge, health, performance, queue, runs, memory, conversations and
    -- recommendations - everything except whether this employee is getting BETTER. The founder's
    -- operating model asks each employee to "learn from performance, failures, outcomes and new
    -- information" and to "improve its decisions and methods over time", and the drawer had no key
    -- for it, so knowledge_exam_results (576 rows over 98 employees) and skills_matrix (695 rows)
    -- were written and never read by any browser-reachable surface.
    --
    -- exam_trend is one point PER DAY, oldest first, because a curve is the only form in which
    -- "improving" is visible. A single aggregate score cannot say whether it went up.
    'learning', jsonb_build_object(
      'exam_results_total', (select count(*) from public.knowledge_exam_results where agent_key = p_agent),
      'exam_days',          (select count(distinct created_at::date) from public.knowledge_exam_results where agent_key = p_agent),
      'exam_score_pct',     (select round(100.0 * count(*) filter (where verdict = 'correct') / nullif(count(*),0), 1)
                               from public.knowledge_exam_results where agent_key = p_agent),
      'last_exam_at',       (select max(created_at) from public.knowledge_exam_results where agent_key = p_agent),
      'exam_trend', coalesce((select jsonb_agg(jsonb_build_object('day', d, 'asked', n, 'score_pct', pct) order by d)
                     from (select created_at::date d, count(*) n,
                                  round(100.0 * count(*) filter (where verdict = 'correct') / nullif(count(*),0), 1) pct
                             from public.knowledge_exam_results where agent_key = p_agent
                            group by 1 order by 1 desc limit 14) t), '[]'::jsonb),
      'knowledge_gaps_found', (select count(*) from public.knowledge_exam_results
                                where agent_key = p_agent and gap_fact is not null),
      'knowledge_gaps_filled', (select count(*) from public.knowledge_exam_results
                                 where agent_key = p_agent and filled),
      'skills', coalesce((select jsonb_agg(jsonb_build_object('skill', skill, 'rating', rating) order by skill)
                 from public.skills_matrix where agent_key = p_agent), '[]'::jsonb)),
    'recommendations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'recommendation',left(recommendation,180),'risk',risk,'at',created_at) order by created_at desc)
                 from (select * from public.agent_actions where agent=p_agent and recommendation is not null order by created_at desc limit 6) x),'[]'::jsonb),
    'audit', coalesce((select jsonb_agg(jsonb_build_object('title',title,'kind',kind,'status',status,'decided_by',decided_by,'decided_at',decided_at,'at',created_at) order by created_at desc)
                 from (select * from public.agent_actions where agent=p_agent order by created_at desc limit 12) x),'[]'::jsonb),
    'recent_runs', coalesce((select jsonb_agg(jsonb_build_object('id',id,'status',status,'note',note,'started_at',started_at,'finished_at',finished_at) order by started_at desc)
                 from (select * from public.agent_runs where agent=p_agent order by started_at desc limit 8) x),'[]'::jsonb)
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_agents()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_out jsonb;
begin
  create temp table if not exists _minds (k text primary key) on commit drop;
  insert into _minds
    select agent_key from public.org_agents where active
    union select 'cat:'||slug from public.category_agents where active
    union select slug from public.category_agents where active
    union select distinct agent_key from public.agent_knowledge where agent_key <> '_global'
  on conflict do nothing;

  with keys as (
    select distinct k from (
      select agent k from public.agent_runs where agent is not null and agent <> ''
      union select agent from public.agent_actions where agent is not null
      union select key from public.prompts where key is not null
      union select slug from public.category_agents where slug is not null
      union select agent_key from public.org_agents where active
    ) u
  ),
  -- ONE PASS PER SOURCE. Previously each of these was a subquery re-evaluated for all 356 keys.
  runs as (
    select agent k, count(*) runs_total,
           count(*) filter (where started_at > now() - interval '24 hours') runs_24h,
           max(started_at) last_run
      from public.agent_runs where agent is not null and agent <> '' group by agent
  ),
  -- The newest run's status, taken with a window rather than a per-key ORDER BY ... LIMIT 1.
  last_status as (
    select k, status from (
      select agent k, status, row_number() over (partition by agent order by started_at desc) rn
        from public.agent_runs where agent is not null and agent <> ''
    ) z where rn = 1
  ),
  acts as (
    select agent k, count(*) filter (where status in ('pending','held_for_review','proposed','open')) actions_pending
      from public.agent_actions where agent is not null group by agent
  ),
  mem as (select agent_key k, count(*) n from public.agent_memory group by agent_key),
  kn  as (select agent_key k, count(*) n from public.agent_knowledge group by agent_key)
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      -- THE WORKFORCE, and nothing else. Was a distinct count over a union of org_agents,
      -- category brains under two spellings, and every agent_key that ever had a knowledge row.
      'agents', (select count(*) from public.org_agents where active),
      -- The category brains still counted, under their own name, because they are real and useful
      -- - they are simply not employees.
      'category_brains', (select count(*) from public.category_agents where active),
      'automations', (select count(distinct ar.agent) from public.agent_runs ar
                      where ar.agent is not null and ar.agent <> ''
                        and not exists (select 1 from _minds m where m.k=ar.agent)),
      'runs_24h', (select count(*) from public.agent_runs where started_at > now()-interval '24 hours'),
      'actions_total', (select count(*) from public.agent_actions),
      'actions_pending', (select count(*) from public.agent_actions where status in ('pending','held_for_review','proposed','open')),
      'memory_items', (select count(*) from public.agent_memory),
      'knowledge_items', (select count(*) from public.agent_knowledge)
    ),
    'rows', coalesce((
      select jsonb_agg(r order by (r->>'runs_total')::int desc nulls last, r->>'name')
      from (
        select jsonb_build_object(
          'key', k.k,
          'name', coalesce(ca.name, pr.description, k.k),
          'emoji', ca.emoji,
          'kind', case when exists (select 1 from _minds m where m.k=k.k) then 'agent' else 'automation' end,
          'active', coalesce(ca.active, true),
          'prompt_version', pr.active_version,
          'runs_total', coalesce(ru.runs_total, 0),
          'runs_24h', coalesce(ru.runs_24h, 0),
          'last_run', ru.last_run,
          'last_status', ls.status,
          'actions_pending', coalesce(ac.actions_pending, 0),
          'memory', coalesce(me.n, 0),
          -- Both the bare key and its 'cat:' twin, exactly as the IN (k, 'cat:'||k) did.
          'knowledge', coalesce(kb.n, 0) + coalesce(kc.n, 0)
        ) r
        from keys k
        left join public.category_agents ca on ca.slug = k.k
        left join public.prompts pr on pr.key = k.k
        left join runs ru on ru.k = k.k
        left join last_status ls on ls.k = k.k
        left join acts ac on ac.k = k.k
        left join mem me on me.k = k.k
        left join kn kb on kb.k = k.k
        left join kn kc on kc.k = 'cat:' || k.k
      ) s), '[]'::jsonb)
  ) into v_out;

  return v_out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_ai()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'agents',(select count(*) from category_agents),
      'agents_active',(select count(*) from category_agents where active is true),
      'actions_total',(select count(*) from agent_actions),
      'actions_pending',(select count(*) from agent_actions where status='pending'),
      'runs_24h',(select count(*) from agent_runs where started_at > now()-interval '24 hours'),
      'avg_confidence',(select round(avg(confidence)::numeric,2) from decision_log where confidence is not null)
    ),
    'trainer', jsonb_build_object(
      'ai_health', (select (kpis->>'ai_health')::numeric from ai_trainer_snapshots order by snapshot_date desc limit 1),
      'metrics', (select kpis from ai_trainer_snapshots order by snapshot_date desc limit 1),
      'weak_agents', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'run_success_pct',run_success_pct,'rejection_rate_pct',rejection_rate_pct,'errors',errors) order by run_success_pct nulls last)
          from ai_agent_quality where runs_30d>=20 and (coalesce(run_success_pct,100)<95 or coalesce(rejection_rate_pct,0)>20)),'[]'::jsonb),
      'proposals', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation))
          from agent_actions where agent='ai_trainer' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    'prompt_reviews', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id, 'key', detail->>'key', 'version', (detail->>'version')::int,
        'reason', detail->>'reason',
        'active_version', (select active_version from prompts p where p.key = a.detail->>'key'),
        'active_score', (a.detail->'eval'->>'active_score'),
        'candidate_score', (a.detail->'eval'->>'candidate_score'),
        'delta', (a.detail->'eval'->>'delta'),
        'decision', a.detail->'eval'->>'decision',
        'sensitive', (a.detail->'eval'->>'sensitive'),
        'scored', (a.detail ? 'eval')
      ) order by created_at desc)
      from agent_actions a where kind='prompt_approval' and status in ('pending','needs_review')),'[]'::jsonb),
    'agents', coalesce((select jsonb_agg(jsonb_build_object('slug',ca.slug,'name',ca.name,'emoji',ca.emoji,'active',ca.active,
        'actions',(select count(*) from agent_actions a where a.agent=ca.slug),
        'pending',(select count(*) from agent_actions a where a.agent=ca.slug and a.status='pending')) order by ca.name) from category_agents ca),'[]'::jsonb),
    'kinds', coalesce((select jsonb_agg(jsonb_build_object('key',k,'count',c) order by c desc) from (
        select coalesce(nullif(kind,''),'other') k, count(*) c from agent_actions group by 1 order by 2 desc limit 12) kk),'[]'::jsonb),
    'runs', coalesce((select jsonb_agg(jsonb_build_object('id',id,'agent',agent,'status',status,'started_at',started_at,'finished_at',finished_at,'note',note)) from (select * from agent_runs order by started_at desc limit 12) r),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_analytics()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'marketplace', fn_marketplace_analytics(),
    'supplier_funnel', jsonb_build_object(
      'directory',(select count(*) from leads),
      'claimed',(select count(*) from leads where claimed is true),
      'registered',(select count(*) from leads where registration_paid_at is not null),
      'submitted',(select count(*) from leads where coalesce(approval_status,'') in ('submitted','under_review','pending','pending_review')),
      'approved',(select count(*) from leads where approval_status='approved')
    ),
    'top_sectors', coalesce((select jsonb_agg(jsonb_build_object('key',s,'count',c) order by c desc) from (
        select coalesce(nullif(sector,''),'other') s, count(*) c from leads group by 1 order by 2 desc limit 12) x),'[]'::jsonb),
    'top_emirates', coalesce((select jsonb_agg(jsonb_build_object('key',e,'count',c) order by c desc) from (
        select coalesce(nullif(emirate,''),'—') e, count(*) c from leads group by 1 order by 2 desc limit 8) x),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_company()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'legal', jsonb_build_object(
      'health', (select (kpis->>'legal_health')::numeric from legal_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from legal_kpis k),
      'missing_docs', coalesce((select jsonb_agg(jsonb_build_object('requirement',requirement,'priority',priority,'applies_to',applies_to) order by priority) from legal_checklist where not present),'[]'::jsonb),
      'flags', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk)) from agent_actions where agent='legal_ai' and status in ('pending','needs_review')),'[]'::jsonb),
      'reviews', coalesce((select jsonb_agg(jsonb_build_object('title',title,'kind',doc_kind,'risk',risk_level,'at',reviewed_at) order by reviewed_at desc) from (select * from legal_reviews order by reviewed_at desc limit 10) r),'[]'::jsonb)
    ),
    'departments', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'actions',c,'pending',pend,'last_active',la) order by c desc) from (
        select coalesce(agent,'—') agent, count(*) c,
               count(*) filter (where status='pending') pend, max(created_at) la
        from agent_actions where created_at >= public.fn_os_fresh_start_at() group by 1 order by 2 desc limit 20) d),'[]'::jsonb),
    'runs', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'status',status,'started_at',started_at,'note',note)) from (select * from agent_runs where started_at >= public.fn_os_fresh_start_at() order by started_at desc limit 12) r),'[]'::jsonb),
    'evals', coalesce((select jsonb_agg(jsonb_build_object('snapshot_at',snapshot_at,'window_days',window_days,'kpis',kpis)) from (select * from agent_evals where snapshot_at >= public.fn_os_fresh_start_at() order by snapshot_at desc limit 4) e),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_company_os()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(

    -- ── THE TEN OPERATING SYSTEMS ────────────────────────────────────────────────────────────
    'operating_systems', coalesce((select jsonb_agg(jsonb_build_object(
        'os_key', o.os_key, 'num', o.num, 'name', o.name, 'mission', o.mission,
        'charter', o.charter, 'mandate', o.mandate, 'owner_agent', o.owner_agent,
        'health_score', o.health_score, 'last_health_at', o.last_health_at, 'active', o.active,
        'responsibilities', (select coalesce(jsonb_agg(r.responsibility order by r.responsibility), '[]'::jsonb)
                               from public.os_responsibility r where r.os_key = o.os_key),
        'objectives', (select coalesce(jsonb_agg(jsonb_build_object(
                          'objective', j.objective, 'horizon', j.horizon, 'measure', j.measure,
                          'actual_value', j.actual_value) order by j.id), '[]'::jsonb)
                         from public.os_objective j where j.os_key = o.os_key and j.active),
        -- Only 4 of the 72 os_responsibility rows name a department; the rest name capabilities.
        -- So this reports the departments the OS demonstrably owns and the headcount inside THEM,
        -- rather than a company-wide headcount that would read as 0 for Leadership and be wrong.
        'owned_departments', (select coalesce(jsonb_agg(d.dept_key order by d.dept_key), '[]'::jsonb)
                                from public.org_departments d
                               where exists (select 1 from public.os_responsibility r2
                                              where r2.os_key = o.os_key and r2.responsibility = d.dept_key)),
        'staff_in_owned_departments', (select count(*) from public.org_agents a where a.active
                    and a.department in (select r2.responsibility from public.os_responsibility r2 where r2.os_key = o.os_key)))
      order by o.num) from public.operating_system o where o.active), '[]'::jsonb),

    -- ── THE COMPANY BRAIN, AS ONE GRAPH ──────────────────────────────────────────────────────
    'graph', jsonb_build_object(
      'node_count', (select count(*) from public.graph_nodes),
      'edge_count', (select count(*) from public.graph_edges),
      'rebuilt_at', (select max(updated_at) from public.graph_nodes),
      'node_kinds', coalesce((select jsonb_agg(jsonb_build_object('kind', k.kind, 'n', k.n) order by k.n desc)
                     from (select kind, count(*) n from public.graph_nodes group by 1) k), '[]'::jsonb),
      'edge_kinds', coalesce((select jsonb_agg(jsonb_build_object('rel', e.rel, 'src_kind', e.src_kind, 'dst_kind', e.dst_kind, 'n', e.n) order by e.n desc)
                     from (select rel, src_kind, dst_kind, count(*) n from public.graph_edges group by 1,2,3) e), '[]'::jsonb),
      'nodes', coalesce((select jsonb_agg(jsonb_build_object('kind', n.kind, 'ref_id', n.ref_id, 'label', n.label) order by n.kind, n.label)
                 from (select * from public.graph_nodes order by kind, label limit 200) n), '[]'::jsonb),
      'edges', coalesce((select jsonb_agg(jsonb_build_object('src_kind', g.src_kind, 'src_ref', g.src_ref, 'rel', g.rel, 'dst_kind', g.dst_kind, 'dst_ref', g.dst_ref) order by g.src_kind, g.rel)
                 from (select * from public.graph_edges order by src_kind, rel limit 300) g), '[]'::jsonb)),

    -- ── THE AI BOARD ─────────────────────────────────────────────────────────────────────────
    'board', jsonb_build_object(
      'advisors', coalesce((select jsonb_agg(jsonb_build_object(
          'advisor_key', b.advisor_key, 'name', b.name, 'lens', b.lens, 'asks', b.asks, 'weight', b.weight)
        order by b.advisor_key) from public.board_advisor b where coalesce(b.active, true)), '[]'::jsonb),
      'opinion_count', (select count(*) from public.board_opinion),
      'opinions', coalesce((select jsonb_agg(jsonb_build_object(
          'subject', p.subject, 'advisor_key', p.advisor_key, 'recommendation', p.recommendation,
          'rationale', left(p.rationale, 300), 'confidence', p.confidence, 'at', p.created_at)
        order by p.created_at desc)
        from (select * from public.board_opinion order by created_at desc limit 12) p), '[]'::jsonb)),

    -- ── THE INDICES: MATURITY, MARKETPLACE HEALTH, ORGANISATIONAL ENERGY ─────────────────────
    -- THE ENGINE ITSELF HAD NO SCREEN (12 Aug 2026). 238 workflow runs and the only thing any
    -- surface showed was a count tile: "Workflows run today". Which processes are in flight, where
    -- each one is parked and WHO it is waiting on were not on any screen in the company, so the
    -- engine going from 5 completed runs to 131 was invisible except in the database.
    -- waiting_on is the resolved employee, not the raw actor_role - the whole point of the
    -- resolver work is that a step now names somebody the company can actually reach.
    'workflow_state', jsonb_build_object(
      'by_status', coalesce((select jsonb_object_agg(s.status, s.n)
          from (select status, count(*) n from public.workflow_run group by 1) s), '{}'::jsonb),
      'steps_delivered', (select count(*) from public.workflow_step_run
                             where output->>'worked_by' = 'workflow_dispatch'),
      'ready_now', (select count(*) from public.workflow_step_run sr
                      join public.workflow_run r on r.id = sr.workflow_run_id
                     where sr.status = 'ready' and r.status = 'running'),
      'in_flight', coalesce((select jsonb_agg(jsonb_build_object(
            'run_id', r.id,
            'workflow', coalesce(w.name, r.workflow_key),
            'step_no', sr.step_no,
            'step', sr.input->>'step',
            'gate', nullif(sr.input->>'gate', 'none'),
            'waiting_on', public.fn_workflow_actor_resolve(r.id, sr.actor),
            'addressed_as', coalesce(sr.input->>'addressed_as', sr.actor),
            'waiting_since', sr.started_at,
            'hours_waiting', round(extract(epoch from (now() - sr.started_at))/3600.0)
          ) order by sr.started_at)
        from (select r2.id, r2.workflow_key, sr2.step_no, sr2.input, sr2.actor, sr2.started_at
                from public.workflow_run r2
                join public.workflow_step_run sr2
                  on sr2.workflow_run_id = r2.id and sr2.status = 'ready'
               where r2.status = 'running'
               order by sr2.started_at
               limit 25) q
        join public.workflow_run r on r.id = q.id
        join public.workflow_step_run sr on sr.workflow_run_id = q.id and sr.step_no = q.step_no
        left join public.workflow w on w.workflow_key = r.workflow_key), '[]'::jsonb)),

    -- WHAT THE COMPANY'S PROCESSES ACTUALLY PRODUCED (11 Aug 2026).
    -- workflow_step_run.output holds 3,700-4,700 characters of real analysis per step, written by
    -- the named employee who owns that step. Before this key, the ONLY readers of that column were
    -- the two functions that write it; this surface counted rows per day and showed none of the
    -- work. A deliverable nobody reads is the defect this estate keeps reproducing.
    -- The outcome line is surfaced, not the body: the founder wants to see what his company decided,
    -- and the full text stays one query away for anything that needs it.
    'process_work', coalesce((select jsonb_agg(jsonb_build_object(
        'at', sr.finished_at,
        'workflow', coalesce(w.name, r.workflow_key),
        'step_no', sr.step_no,
        'step', sr.input->>'step',
        'employee', coalesce(sr.output->>'employee', sr.actor),
        'outcome', left(coalesce(sr.output->>'outcome',''), 400),
        'chars', length(coalesce(sr.output->>'deliverable','')),
        'confidence', sr.output->>'self_confidence',
        'mode', sr.output->>'mode') order by sr.finished_at desc)
      from public.workflow_step_run sr
      join public.workflow_run r on r.id = sr.workflow_run_id
      left join public.workflow w on w.workflow_key = r.workflow_key
     where sr.status = 'done'
       and coalesce(sr.output->>'deliverable','') <> ''
       and sr.finished_at > now() - interval '14 days'
     limit 40), '[]'::jsonb),

    'indices', coalesce((select jsonb_agg(jsonb_build_object(
        'index_name', c.index_name, 'score', c.score, 'band', c.band,
        'measured_on', c.measured_on, 'dimensions', c.dimensions) order by c.index_name)
      from public.company_index c
      where c.measured_on = (select max(measured_on) from public.company_index c2 where c2.index_name = c.index_name)), '[]'::jsonb),
    'marketplace_health', (select jsonb_build_object('score', c.score, 'band', c.band, 'measured_on', c.measured_on, 'dimensions', c.dimensions)
        from public.company_index c where c.index_name = 'marketplace_health'
        order by c.measured_on desc, c.id desc limit 1),

    -- ── EXECUTIVE REPLAY ─────────────────────────────────────────────────────────────────────
    'replay', jsonb_build_object(
      -- THE SIX TRACKS OF THE CHOSEN DAY, in one place for the first time. The day is the newest
      -- company_snapshot day, which is the chip the Replay card is already showing, so these
      -- counts describe what the founder is looking at rather than a different day's activity.
      'tracks', (select jsonb_build_object(
          'day', dd.day,
          'decisions',     (select count(*) from public.decision_log      x where x.created_at::date = dd.day),
          'conversations', (select count(*) from public.agent_chats       x where x.created_at::date = dd.day),
          'approvals',     (select count(*) from public.agent_actions     x where coalesce(x.decided_at, x.created_at)::date = dd.day),
          'workflows',     (select count(*) from public.workflow_step_run x where coalesce(x.started_at, x.finished_at)::date = dd.day),
          'kpis',          (select count(*) from public.metric_snapshot   x where x.taken_at::date = dd.day),
          'outcomes',      (select count(*) from public.outcome_record    x where coalesce(x.observed_at, x.created_at)::date = dd.day))
        from (select coalesce(max(snapshot_on), current_date - 1) as day from public.company_snapshot) dd),
      'days_on_file', (select count(*) from public.company_snapshot),
      'newest', (select max(snapshot_on) from public.company_snapshot),
      'company_snapshot', coalesce((select jsonb_agg(jsonb_build_object('snapshot_on', s.snapshot_on, 'state', s.state) order by s.snapshot_on desc)
        from (select * from public.company_snapshot order by snapshot_on desc limit 8) s), '[]'::jsonb)),

    -- ── REPUTATION ───────────────────────────────────────────────────────────────────────────
    'reputation', jsonb_build_object(
      'graded', (select count(*) from public.agent_reputation),
      'by_tier', coalesce((select jsonb_agg(jsonb_build_object('tier', t.tier, 'n', t.n) order by t.n desc)
                   from (select coalesce(tier, 'ungraded') tier, count(*) n from public.agent_reputation group by 1) t), '[]'::jsonb),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'agent_key', r.agent_key, 'score', r.score, 'tier', r.tier, 'correctness', r.correctness,
          'reliability', r.reliability, 'cost_efficiency', r.cost_efficiency,
          'learning_speed', r.learning_speed, 'collaboration', r.collaboration)
        order by r.score desc nulls last)
        from (select * from public.agent_reputation order by score desc nulls last limit 20) r), '[]'::jsonb)),

    -- ── STRUCTURAL PROPOSALS AND THE LESSON LEDGER ───────────────────────────────────────────
    'evolution_proposals', coalesce((select jsonb_agg(jsonb_build_object(
        'id', e.id, 'trigger_kind', e.trigger_kind, 'subject', e.subject,
        'observation', left(e.observation, 240), 'proposal', left(e.proposal, 240),
        'change_class', e.change_class, 'status', e.status, 'decided_by', e.decided_by, 'at', e.created_at)
      order by e.created_at desc)
      from (select * from public.evolution_proposal order by created_at desc limit 12) e), '[]'::jsonb),
    -- THE FOUR STRATEGIC QUEUES, named by their own tables so the screen and the store cannot drift
    -- apart: evolution_proposal, challenge_record, opportunity and board_opinion. The spec's
    -- "strategic decisions rather than operational tasks" is exactly this set against the pending
    -- agent_actions queue the founder was being shown instead.
    'strategic_queues', jsonb_build_object(
      'evolution_proposal', (select count(*) from public.evolution_proposal where status = 'proposed'),
      'challenge_record', (select count(*) from public.challenge_record where responded_at is null),
      'opportunity', (select count(*) from public.opportunity where status = 'open'),
      'board_opinion', (select count(*) from public.board_opinion),
      'operational_pending', (select count(*) from public.agent_actions where status in ('pending','needs_review'))),
    'opportunity', coalesce((select jsonb_agg(jsonb_build_object(
        'id', o.id, 'kind', o.kind, 'title', o.title, 'detail', left(o.detail, 240),
        'value_score', o.value_score, 'effort', o.effort, 'confidence', o.confidence, 'at', o.created_at)
      order by o.value_score desc nulls last)
      from (select * from public.opportunity where status = 'open'
             order by value_score desc nulls last limit 10) o), '[]'::jsonb),

    -- The AI disagreeing with the founder, and what it offered instead. 47 challenges on file, 31
    -- carrying alternatives, and no surface has ever shown one.
    'challenge_record', coalesce((select jsonb_agg(jsonb_build_object(
        'id', h.id, 'proposal', h.proposal, 'proposed_by', h.proposed_by, 'challenged_by', h.challenged_by,
        'stance', h.stance, 'confidence', h.confidence, 'reasoning', left(h.reasoning, 320),
        'alternatives', h.alternatives, 'violates_principle', h.violates_principle,
        'violates_rank', h.violates_rank, 'founder_response', h.founder_response,
        'responded_at', h.responded_at, 'at', h.created_at)
      order by h.created_at desc)
      from (select * from public.challenge_record order by created_at desc limit 12) h), '[]'::jsonb),

    'institutional_memory', jsonb_build_object(
      'lessons', (select count(*) from public.institutional_memory),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'kind', m.kind, 'headline', m.headline, 'outcome', m.outcome, 'lesson', left(m.detail, 240),
          'os_key', m.os_key, 'confidence', m.confidence, 'occurred_at', m.occurred_at)
        order by m.occurred_at desc nulls last)
        from (select * from public.institutional_memory order by occurred_at desc nulls last limit 12) m), '[]'::jsonb)),

    -- ── RESILIENCE ───────────────────────────────────────────────────────────────────────────
    'resilience', jsonb_build_object(
      'critical_capability', coalesce((select jsonb_agg(jsonb_build_object(
          'capability_key', c.capability_key, 'capability', c.capability, 'owner_dept', c.owner_dept,
          'test_kind', c.test_kind, 'last_verdict', c.last_verdict, 'last_checked', c.last_checked)
        order by c.capability_key) from public.critical_capability c), '[]'::jsonb),
      'continuity_plan', coalesce((select jsonb_agg(jsonb_build_object(
          'service', p.service, 'criticality', p.criticality, 'failure_mode', p.failure_mode,
          'fallback', p.fallback, 'recovery', p.recovery, 'rto_minutes', p.rto_minutes,
          'owner_agent', p.owner_agent, 'last_tested', p.last_tested)
        order by p.criticality, p.service) from public.continuity_plan p), '[]'::jsonb)),

    -- ── THE OPERATING MANUAL ─────────────────────────────────────────────────────────────────
    'operating_manual', jsonb_build_object(
      'runbooks', (select count(*) from public.os_runbooks),
      'by_category', coalesce((select jsonb_agg(jsonb_build_object('category', k.category, 'n', k.n) order by k.n desc)
                      from (select coalesce(category, 'uncategorised') category, count(*) n from public.os_runbooks group by 1) k), '[]'::jsonb),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'slug', r.slug, 'title', r.title, 'category', r.category, 'when_to_use', left(r.when_to_use, 200), 'os_key', r.os_key)
        order by r.sort nulls last, r.slug)
        from (select * from public.os_runbooks order by sort nulls last, slug limit 24) r), '[]'::jsonb)),

    -- ── RESOURCE MOVEMENT, AUTONOMY, SUPPLY AND THE EVENT BUS ────────────────────────────────
    'allocation_change', coalesce((select jsonb_agg(jsonb_build_object(
        'resource', a.resource, 'subject', a.subject, 'from_value', a.from_value, 'to_value', a.to_value,
        'reason', left(a.reason, 200), 'policy', a.policy, 'reverted', a.reverted, 'at', a.created_at)
      order by a.created_at desc)
      from (select * from public.allocation_change order by created_at desc limit 12) a), '[]'::jsonb),
    'autonomy', jsonb_build_object(
      'changes', (select count(*) from public.autonomy_control_audit),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'object', u.object, 'op', u.op, 'direction', u.direction, 'old_value', u.old_value,
          'new_value', u.new_value, 'reason', left(u.reason, 160), 'at', u.at)
        order by u.at desc)
        from (select * from public.autonomy_control_audit order by at desc limit 10) u), '[]'::jsonb)),
    'supply_health', jsonb_build_object(
      'snapshots', (select count(*) from public.supply_health_snapshots),
      'latest_period_end', (select max(period_end) from public.supply_health_snapshots),
      'coverage_gaps', coalesce((select jsonb_agg(to_jsonb(s) order by s.period_end desc)
        from (select * from public.supply_health_snapshots order by period_end desc limit 6) s), '[]'::jsonb)),
    'invite_schedule', coalesce((select jsonb_agg(jsonb_build_object(
        'day', i.day, 'planned', i.planned, 'sent', i.sent, 'status', i.status) order by i.day desc)
      from (select * from public.invite_schedule order by day desc limit 10) i), '[]'::jsonb),
    'events', jsonb_build_object(
      'total', (select count(*) from public.company_event),
      'last_7d', (select count(*) from public.company_event where occurred_at > now() - interval '7 days'),
      'by_class', coalesce((select jsonb_agg(jsonb_build_object('event_type', c.event_type, 'n', c.n) order by c.n desc)
                   from (select event_type, count(*) n from public.company_event
                          where occurred_at > now() - interval '30 days' group by 1) c), '[]'::jsonb)),

    -- ── MODEL MIX ────────────────────────────────────────────────────────────────────────────
    'model_mix', coalesce((select jsonb_agg(jsonb_build_object(
        'model_used', m.model_used, 'calls', m.calls, 'aed', m.aed, 'latency_ms', m.latency_ms,
        'cache_hits', m.cache_hits) order by m.aed desc)
      from (select coalesce(nullif(model_used,''),'unknown') model_used, count(*) calls,
                   round(coalesce(sum(cost_aed),0),4) aed,
                   round(avg(latency_ms)) latency_ms,
                   count(*) filter (where cached) cache_hits
              from public.ai_cost_log where occurred_at > now() - interval '30 days' group by 1) m), '[]'::jsonb),

    -- ── INFORMATION FLOWING BETWEEN THE TEN SYSTEMS ─────────────────────────────────────────
    -- Derived from what was actually DELIVERED, not from what os_interface declares: the declared
    -- outputs and inputs are disjoint sets and join to zero cross-OS edges. The consumer is
    -- event_delivery.os_key; the producer is company_event.actor resolved through its department,
    -- or the actor itself when the actor IS a department. Deliveries whose actor is machinery
    -- (system, a cron, the brief) are counted as unattributed rather than assigned to a system.
    'flow', (with res as (
        select d.os_key as to_os, d.event_type, d.delivered_at,
               coalesce((select od.os_key from public.org_agents a
                          join public.os_department od on od.dept_key = a.department
                         where a.agent_key = e.actor limit 1),
                        (select od2.os_key from public.os_department od2
                          where od2.dept_key = e.actor limit 1)) as from_os
          from public.event_delivery d
          join public.company_event e on e.id = d.event_id
         where d.os_key is not null and d.delivered_at > now() - interval '7 days')
      select jsonb_build_object(
        'window_days', 7,
        'deliveries', (select count(*) from res),
        'attributed', (select count(*) from res where from_os is not null),
        'unattributed', (select count(*) from res where from_os is null),
        'unroutable', (select count(*) from public.event_delivery
                        where unroutable_reason is not null
                          and delivered_at > now() - interval '7 days'),
        'nodes', coalesce((select jsonb_agg(jsonb_build_object(
            'os_key', o.os_key, 'num', o.num, 'name', o.name,
            'received', (select count(*) from res where res.to_os = o.os_key),
            'sent', (select count(*) from res where res.from_os = o.os_key)) order by o.num)
          from public.operating_system o where o.active), '[]'::jsonb),
        'edges', coalesce((select jsonb_agg(x) from (
            select from_os, to_os, count(*) as n,
                   count(distinct event_type) as event_types,
                   max(delivered_at) as newest,
                   (array_agg(distinct event_type))[1:3] as kinds
              from res where from_os is not null
             group by from_os, to_os order by count(*) desc limit 40) x), '[]'::jsonb))),

    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_customer_360(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare c public.customers%rowtype; j jsonb;
  ltv numeric(18,2); deal_value numeric(18,2); reveals int;
  rfqs_total int; rfqs_active int; rfqs_done int; avg_budget numeric(18,2);
  last_act timestamptz; score int; cats text; docs jsonb := '[]'::jsonb; summary text;
begin
  select * into c from public.customers where id=p_id;
  if c.id is null then return jsonb_build_object('error','customer not found'); end if;

  select coalesce(sum(reveal_fee) filter (where fee_status='paid'),0), coalesce(sum(quote_amount),0), count(*)
    into ltv, deal_value, reveals from public.transactions where customer_id=p_id;
  select count(*), count(*) filter (where status not in ('completed','cancelled','closed','lost')),
         count(*) filter (where status in ('completed','closed') or outcome='completed'),
         coalesce(round(avg(nullif(expected_value,0)),2),0)
    into rfqs_total, rfqs_active, rfqs_done, avg_budget from public.inquiries where customer_id=p_id;
  select string_agg(distinct category, ', ') into cats from public.inquiries where customer_id=p_id and category is not null;

  select greatest(coalesce(max(i.created_at), c.created_at),
                  coalesce((select max(revealed_at) from public.transactions where customer_id=p_id), c.created_at),
                  c.created_at)
    into last_act from public.inquiries i where i.customer_id=p_id;
  last_act := coalesce(last_act, c.created_at);

  score := least(100, greatest(0,
      coalesce(rfqs_total,0)*12 + coalesce(reveals,0)*25 + round(coalesce(ltv,0)/20)::int
      + (case when last_act > now() - interval '30 days' then 15 else 0 end)));

  docs := coalesce((select jsonb_agg(jsonb_build_object('type','Drawing','name',coalesce(drawing_file_name,'drawing'),'path',drawing_file_path))
                    from public.inquiries where customer_id=p_id and drawing_file_path is not null),'[]'::jsonb);
  if c.signed_terms_path is not null then docs := docs || jsonb_build_object('type','Signed terms','name','terms','path',c.signed_terms_path); end if;

  summary := c.full_name||' joined '||to_char(c.created_at,'Mon YYYY')||'. '
    ||coalesce(rfqs_total,0)||' RFQ(s)'||coalesce(' across '||cats,'')||'. '
    ||coalesce(reveals,0)||' reveal(s), AED '||to_char(coalesce(ltv,0),'FM999999990.00')||' paid to date.'
    ||(case when avg_budget>0 then ' Avg project budget AED '||to_char(avg_budget,'FM999999990') else '' end)
    ||(case when c.banned then ' [BANNED]' when not coalesce(c.email_verified,false) then ' Email unverified.' else '' end);

  j := jsonb_build_object(
    'profile', jsonb_build_object('id',c.id,'full_name',c.full_name,'email',c.email,'phone',c.phone,
       'created_at',c.created_at,'phone_verified',c.phone_verified,'email_verified',c.email_verified,
       'banned',c.banned,'banned_reason',c.banned_reason,'wa_optin',c.wa_optin,'tos_accepted_at',c.tos_accepted_at,
       'chat_strikes',c.chat_strikes),
    'metrics', jsonb_build_object('ltv',ltv,'total_deal_value',deal_value,'reveals',reveals,
       'rfqs_total',rfqs_total,'rfqs_active',rfqs_active,'rfqs_completed',rfqs_done,
       'avg_project_budget',avg_budget,'relationship_score',score),
    'ai_summary', summary,
    'preferences', (
       with pref as (select p.preferences pj from public.customer_preference p
                       join public.customers cc on cc.id = p.customer_id
                      where p.customer_id = p_id and cc.tos_accepted_at is not null)
       select jsonb_build_object(
         'categories', coalesce((select pj->'stated'->'categories' from pref),
                                (select pj->'inferred'->'categories' from pref),
                                coalesce((select jsonb_agg(distinct category) from public.inquiries where customer_id=p_id and category is not null),'[]'::jsonb)),
         'emirates',   coalesce((select pj->'stated'->'emirates' from pref),
                                (select pj->'inferred'->'emirates' from pref),
                                coalesce((select jsonb_agg(distinct emirate) from public.inquiries where customer_id=p_id and emirate is not null),'[]'::jsonb)),
         'scope_type', (select pj->'inferred'->>'scope_type' from pref),
         'budget_aed_avg', (select pj->'inferred'->'budget_aed_avg' from pref),
         'remembered', exists(select 1 from pref))),
    'rfqs', coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'category',i.category,'emirate',i.emirate,
       'status',i.status,'pipeline_stage',i.pipeline_stage,'budget',i.expected_value,
       'outcome',i.outcome,'created_at',i.created_at) order by i.created_at desc)
       from (select * from public.inquiries where customer_id=p_id order by created_at desc limit 15) i),'[]'::jsonb),
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'amount',q.quote_amount,'status',q.status,'created_at',q.created_at) order by q.created_at desc)
       from public.quotes q join public.inquiries i on i.id=q.inquiry_id where i.customer_id=p_id),'[]'::jsonb),
    'transactions', coalesce((select jsonb_agg(jsonb_build_object('quote_amount',t.quote_amount,'reveal_fee',t.reveal_fee,'fee_status',t.fee_status,'revealed_at',t.revealed_at) order by t.revealed_at desc)
       from public.transactions t where t.customer_id=p_id),'[]'::jsonb),
    'documents', docs,
    'timeline', (select jsonb_agg(e order by e->>'at' desc) from (
        select jsonb_build_object('at',c.created_at,'event','Signed up') e
        union all select jsonb_build_object('at',i.created_at,'event','RFQ: '||coalesce(i.category,'inquiry')) from public.inquiries i where i.customer_id=p_id
        union all select jsonb_build_object('at',t.revealed_at,'event','Revealed supplier · AED '||coalesce(t.reveal_fee::text,'0')||' fee') from public.transactions t where t.customer_id=p_id and t.revealed_at is not null
      ) tl)
  );
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_customer_behavior()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'customers',        (select count(*) from customer_health),
    -- Averages over the real book. NULL when there is nobody to average, never 0.
    'avg_health',       (select round(avg(health)::numeric, 1)       from customer_health),
    'avg_engagement',   (select round(avg(engagement)::numeric, 1)   from customer_health),
    'avg_satisfaction', (select round(avg(satisfaction)::numeric, 1) from customer_health),
    'dormant',          (select count(*) from customer_health where coalesce(dormant, false)),
    'at_risk',          (select count(*) from customer_health where lower(coalesce(risk_tier,'')) in ('high','elevated','at_risk')),
    'with_rfqs',        (select count(*) from customer_health where coalesce(total_inq, 0) > 0),
    -- CHURN IS NOT MEASURED, AND SAYS SO RATHER THAN RETURNING A NUMBER. Every customer on this
    -- platform was created inside the last 30 days and none has completed a transaction, so there
    -- is no lapse to observe. A churn rate here would be arithmetic on an empty set.
    'churn_rate_pct',   null,
    'churn_note',       'Not measured: no customer is old enough to have lapsed and no transaction has completed, so there is nothing to compute a churn rate from.',
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
              'customer_id', c.customer_id, 'name', c.full_name, 'email', c.email,
              'health', c.health, 'engagement', c.engagement, 'satisfaction', c.satisfaction,
              'progress', c.progress, 'service', c.service, 'risk_tier', c.risk_tier,
              'dormant', c.dormant, 'total_inq', c.total_inq, 'active_inq', c.active_inq,
              'stalled_inq', c.stalled_inq, 'last_activity', c.last_activity)
            order by c.health nulls last)
            from customer_health c), '[]'::jsonb),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_customers()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'total',(select count(*) from customers),
      'verified',(select count(*) from customers where phone_verified is true or email_verified is true),
      'banned',(select count(*) from customers where banned is true),
      'with_rfqs',(select count(distinct customer_id) from inquiries where customer_id is not null)
    ),
    'success', jsonb_build_object(
      'kpis', coalesce((select to_jsonb(k) from customer_kpis k),'{}'::jsonb),
      'open_escalations', (select count(*) from agent_actions where kind='customer_escalation' and status in ('pending','needs_review')),
      'attention', coalesce((select jsonb_agg(a) from (
          select jsonb_build_object('id',customer_id,'name',coalesce(full_name,email),'health',health,
            'engagement',engagement,'satisfaction',satisfaction,'progress',progress,'service',service,
            'risk_tier',risk_tier,'stalled',stalled_inq,'disputes',disputes,'dormant',dormant) a
          from customer_health where risk_tier in ('high','medium') order by health asc limit 10) t),'[]'::jsonb),
      'trend', coalesce((select jsonb_agg(jsonb_build_object('d',snapshot_date,'health',(kpis->>'avg_health')) order by snapshot_date)
          from (select snapshot_date, kpis from customer_kpi_snapshots order by snapshot_date desc limit 14) s),'[]'::jsonb)
    ),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'full_name',c.full_name,'email',c.email,'phone',c.phone,
        'phone_verified',c.phone_verified,'email_verified',c.email_verified,'banned',c.banned,'created_at',c.created_at,
        'rfqs',(select count(*) from inquiries i where i.customer_id=c.id),
        'projects',(select count(*) from projects p where p.customer_id=c.id))) from (select * from customers order by created_at desc limit 100) c),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_documents()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'documents',(select count(*) from documents),
      'inventory_total',(select count(*) from document_inventory),
      'dropbox_files',(select count(*) from dropbox_files where not is_folder),
      'indexed',(select count(*) from documents where indexed is true),
      -- a review a department owns is not pending for the founder (6 Sep 2026)
      'reviews_pending',(select count(*) from doc_reviews where coalesce(status,'')='pending' and owner_role is null),
      'versions',(select count(*) from doc_versions)
    ),
    'controller', jsonb_build_object(
      'health', (select (kpis->>'doc_health')::numeric from document_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from document_kpis k),
      'by_bucket', coalesce((select jsonb_agg(jsonb_build_object('bucket',bucket,'docs',c,'bytes',b,'past_retention',pr,'class',cls) order by c desc)
          from (select bucket, count(*) c, sum(bytes) b, count(*) filter (where past_retention) pr, max(retention_class) cls from document_inventory group by bucket) t),'[]'::jsonb),
      'dropbox', jsonb_build_object(
        'connected', (select (max(synced_at) is not null) from dropbox_files),
        'files', (select count(*) from dropbox_files where not is_folder),
        'folders', (select count(*) from dropbox_files where is_folder),
        'bytes', (select coalesce(sum(size),0) from dropbox_files),
        'last_sync', (select max(synced_at) from dropbox_files),
        'top_folders', coalesce((select jsonb_agg(jsonb_build_object('path',path,'items',n) order by n desc)
            from (select split_part(path,'/',2) path, count(*) n from dropbox_files where path like '/%/%' group by 1 order by 2 desc limit 8) t),'[]'::jsonb)
      ),
      'retention', coalesce((select jsonb_agg(jsonb_build_object('bucket',bucket,'class',class,'retention_days',retention_days) order by bucket) from retention_policy),'[]'::jsonb),
      'tasks', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation)) from agent_actions where agent='document_controller' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    -- bucket + path: what os_api `file` signs so the shell can open the row (6 Sep 2026)
    'documents', coalesce((select jsonb_agg(jsonb_build_object('id',id,'file_name',file_name,'kind',kind,'ref_table',ref_table,'ref_id',ref_id,'status',status,'indexed',indexed,'created_at',created_at,'bucket',bucket,'path',path)) from (select * from documents order by created_at desc limit 40) d),'[]'::jsonb),
    -- the section is titled "Reviews pending" and carries Approve/Reject: it lists pending, unowned rows only
    'reviews', coalesce((select jsonb_agg(jsonb_build_object('id',id,'file_name',file_name,'ai_category',ai_category,'ai_summary',ai_summary,'ai_confidence',ai_confidence,'status',status,'created_at',created_at)) from (select * from doc_reviews where coalesce(status,'')='pending' and owner_role is null order by created_at desc limit 20) r),'[]'::jsonb),
    'kinds', coalesce((select jsonb_agg(jsonb_build_object('key',k,'count',c) order by c desc) from (select coalesce(nullif(kind,''),'other') k, count(*) c from documents group by 1) kk),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_ea()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'today_events', a->'today'->'events',
    'reminders_due', a->'today'->'reminders_due',
    'upcoming_events', a->'upcoming_events',
    'open_tasks', a->'open_tasks',
    'overdue_tasks', (a->>'overdue_tasks')::int,
    'approvals_total', (a->'approvals_to_clear'->>'total')::int,
    'approvals_high_risk', (a->'approvals_to_clear'->>'high_risk')::int,
    'approvals_top', a->'approvals_to_clear'->'top',
    'recent_meetings', a->'recent_meetings'
  )
  from (select fn_ea_agenda(7) a) x;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_exec()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'command', fn_os_command(),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'status',status,'priority',priority,'due',due_date,'entity',entity)) from (select * from crm_tasks where coalesce(status,'') not in ('done','cancelled') and created_at >= fn_os_fresh_start_at() order by created_at desc limit 8) t),'[]'::jsonb),
    'approvals', public.fn_founder_queue(6)->'waiting_on_you',
    'held', coalesce((select jsonb_agg(jsonb_build_object('id',id,'agent',agent,'title',title,'kind',kind,'kind_label',fn_ui_label('action_kind',kind),'holder',public.fn_action_holder(kind, agent),'risk',risk,'status',status,'created_at',created_at,'yours',false))
                from (select a.* from agent_actions a left join agent_action_kind_policy p on p.kind = a.kind
                       where a.status in ('pending','needs_review') and coalesce(p.policy,'') <> 'founder'
                         and a.created_at >= fn_os_fresh_start_at() order by a.created_at desc limit 6) a),'[]'::jsonb),
    'activity', coalesce((select jsonb_agg(jsonb_build_object('actor',actor,'kind',kind,'kind_label',fn_ui_label('action_kind',kind),'decision',decision,'confidence',confidence,'route_to',route_to,'created_at',created_at)) from (select * from decision_log where created_at >= fn_os_fresh_start_at() order by created_at desc limit 10) d),'[]'::jsonb),
    'notifications', coalesce((select jsonb_agg(jsonb_build_object('type',type,'type_label',fn_ui_label('notification_type',type),'subject',subject,'status',status,'created_at',created_at)) from (select * from notifications where created_at >= fn_os_fresh_start_at() order by created_at desc limit 6) n),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_exec_home()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with h as (select to_jsonb(public.fn_health_index()) j),
  gh as (
    select coalesce(
      (select 'monthly' where exists (select 1 from public.goal_period where horizon = 'monthly')),
      (select 'quarterly' where exists (select 1 from public.goal_period where horizon = 'quarterly')),
      'annual') hz
  ),
  g as (
    -- fn_goal_attainment handles the four ways the inline version was wrong (least() ignoring
    -- nulls, direction, period, row-count-as-goal-count). One copy, not two.
    select (a.j->>'pct')::numeric        pct,
           (a.j->>'goals_total')::int    n,
           (a.j->>'goals_measured')::int measured
      from gh, lateral (select public.fn_goal_attainment(gh.hz) j) a
  ),
  bott as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'department', r.owner_dept, 'resource', r.resource, 'used_pct', r.used_pct,
             'state', r.state, 'committed', r.committed, 'capacity', r.capacity, 'unit', r.unit)
           order by r.used_pct desc nulls last), '[]'::jsonb) j
      from public.v_resource_pressure r where r.state in ('HALT', 'DEGRADE')
  ),
  dept as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'department', coalesce(dh.department, e->>'label', e->>'key'),
             'dept_key', e->>'key',
             'runs', (e->'runs'),
             'busy', coalesce((e->>'runs')::int, 0) > 0,
             'health', dh.score, 'status', dh.status)
           order by coalesce((e->>'runs')::int, 0) desc), '[]'::jsonb) j
      from jsonb_array_elements(public.fn_agents_board()->'departments') e
      left join public.v_department_health dh on dh.dept_key = e->>'key'
  ),
  fq as (select public.fn_founder_queue(1) j),
  home as (select jsonb_build_object(
    'health_index',     (select (j->>'index')::numeric from h),
    'mood',             (select j->>'band' from h),
    'health_note',      (select j->>'note' from h),
    'revenue_today',    (select coalesce(sum(coalesce(reveal_fee, app_fee, 0)), 0)
                           from public.transactions where revealed_at::date = current_date),
    'revenue_30d',      (select coalesce(sum(coalesce(reveal_fee, app_fee, 0)), 0)
                           from public.transactions where revealed_at > now() - interval '30 days'),
    'goal_progress_pct', (select pct from g),
    'goal_horizon',     (select hz from gh),
    'goal_count',       (select n from g),
    'goal_measured',    (select measured from g),
    'customers_active', (select count(*) from public.customers where coalesce(banned, false) = false),
    'suppliers_active', coalesce((public.fn_marketplace_analytics()->>'active_suppliers_30d')::int, 0),
    'employees',        (select count(*) from public.org_agents where active),
    'employees_working', (select count(*) from public.org_agents o where o.active and (
                             exists (select 1 from public.agent_runs r
                                      where r.agent = o.agent_key and r.started_at > now() - interval '24 hours')
                          or exists (select 1 from public.agent_memory m
                                      where m.agent_key = o.agent_key and m.created_at > now() - interval '24 hours')
                          or exists (select 1 from public.agent_chats c
                                      where c.agent_key = o.agent_key and c.created_at > now() - interval '24 hours'))),
    'bottlenecks',      (select j from bott),
    'departments',      (select j from dept),
    'workflow_runs_24h', (select count(*) from public.workflow_run
                           where coalesce(started_at, created_at) > now() - interval '24 hours'),
    'handoffs_24h', (select count(*) from public.phase_c_handoff_run
                      where opened_at > now() - interval '24 hours'),
    'events_delivered_24h', (select count(*) from public.event_delivery
                              where delivered_at > now() - interval '24 hours'),
    'knowledge_revisions_7d', (select count(*) from public.kb_revisions
                                where created_at > now() - interval '7 days'),
    'uptime_pct_24h', (select round(100.0 * count(*) filter (where verdict = 'ALIVE')
                                    / nullif(count(*), 0), 1)
                         from public.edge_health_probe where checked_at > now() - interval '24 hours'),
    'leads_total',      (select count(*) from public.leads),
    'agent_runs_24h',   (select count(*) from public.agent_runs where started_at > now() - interval '24 hours'),
    'events_24h',       (select count(*) from public.company_event where occurred_at > now() - interval '24 hours'),
    -- HIS decisions: refund approvals and nothing else. The 14 open agent_actions this used to
    -- count are held with their roles and reported under that name.
    'decisions_open',   public.fn_founder_refund_approvals_open(),
    'held_with_roles',  (select (j->>'held_with_roles_total')::int from fq),
    'held_with',        (select j->'held_with_roles' from fq),
    -- ONE definition of an open task: public.v_org_open_tasks (see one_definition_of_an_open_task.sql).
    'tasks_open',       (select count(*) from public.v_org_open_tasks),
    'generated_at',     now()
  ) j)
  -- THE OVERNIGHT BRIEF, AS ONE SENTENCE. Written here so the Console's "speak the overnight brief"
  -- button and the founder command channel ("status", "brief", "how are we doing") read the SAME
  -- text from the SAME figures, instead of one composing it in the browser and the other having no
  -- answer at all (6 Sep 2026: "status" came back as "clarification required").
  select h.j || jsonb_build_object('brief_text',
       'Company health ' || coalesce(h.j->>'health_index', 'unknown') || ', mood ' || coalesce(h.j->>'mood', 'unknown') || '. '
    || 'Revenue today ' || coalesce(h.j->>'revenue_today', '0') || ' dirhams, ' || coalesce(h.j->>'revenue_30d', '0') || ' over thirty days. '
    || coalesce(h.j->>'suppliers_active', '0') || ' active suppliers, ' || coalesce(h.j->>'customers_active', '0') || ' active customers. '
    || coalesce(h.j->>'employees_working', '0') || ' of ' || coalesce(h.j->>'employees', '0') || ' AI employees worked overnight. '
    || 'Goal progress ' || coalesce(h.j->>'goal_progress_pct', '0') || ' percent. '
    || coalesce(h.j->>'tasks_open', '0') || ' open tasks across every department. '
    || case when jsonb_array_length(coalesce(h.j->'bottlenecks', '[]'::jsonb)) > 0
            then jsonb_array_length(h.j->'bottlenecks')::text || ' departments are over capacity.'
            else 'No department is over capacity.' end)
  from home h;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_finance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  cash_total numeric(18,2); rev_total numeric(18,2); exp_total numeric(18,2);
  rev30 numeric(18,2); exp30 numeric(18,2); monthly_burn numeric(18,2); runway numeric(18,1);
  j jsonb;
begin
  select coalesce(sum(balance),0) into cash_total from public.gl_account_balances where code in ('1000','1050');
  select coalesce(sum(balance),0) into rev_total from public.gl_account_balances where type='revenue';
  select coalesce(sum(balance),0) into exp_total from public.gl_account_balances where type='expense';

  -- 30-day run-rate (posted activity)
  select
    coalesce(sum(case when ga.type='revenue' then l.credit-l.debit else 0 end),0),
    coalesce(sum(case when ga.type='expense' then l.debit-l.credit else 0 end),0)
    into rev30, exp30
  from public.gl_journal_lines l
  join public.gl_journal j2 on j2.id=l.journal_id and j2.status='posted'
  join public.gl_accounts ga on ga.code=l.account_code
  where j2.entry_date >= current_date - 30;

  monthly_burn := exp30 - rev30;                       -- net cash burn (positive = burning)
  runway := case when monthly_burn > 0 and cash_total > 0 then round(cash_total/monthly_burn,1) else null end;

  j := jsonb_build_object(
    'as_of', now(),
    'cash', jsonb_build_object(
      'total', cash_total,
      'accounts', coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'balance',balance) order by code)
                   from public.gl_account_balances where code in ('1000','1050','1100','1110','1150','1500','1600')),'[]'::jsonb)
    ),
    'pnl', jsonb_build_object(
      'revenue', rev_total, 'expenses', exp_total, 'net_income', rev_total-exp_total,
      'margin_pct', case when rev_total>0 then round(100.0*(rev_total-exp_total)/rev_total,1) else null end
    ),
    'run_rate', jsonb_build_object(
      'revenue_30d', rev30, 'expense_30d', exp30, 'net_30d', rev30-exp30,
      'arr_estimate', round(rev30*12,2), 'monthly_burn', monthly_burn,
      'runway_months', runway
    ),
    'monetization', jsonb_build_object(
      'reveal_fees', (select coalesce(balance,0) from public.gl_account_balances where code='4000'),
      'commissions', (select coalesce(balance,0) from public.gl_account_balances where code='4100'),
      'registration', (select coalesce(balance,0) from public.gl_account_balances where code='4200'),
      'stripe_fees', (select coalesce(balance,0) from public.gl_account_balances where code='6100')
    ),
    'revenue_breakdown', coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'amount',balance) order by balance desc)
        from public.gl_account_balances where type='revenue' and balance<>0),'[]'::jsonb),
    'expense_breakdown', coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'amount',balance) order by balance desc)
        from public.gl_account_balances where type='expense' and balance<>0),'[]'::jsonb),
    'receivables', jsonb_build_object(
      'commission_receivable', (select coalesce(balance,0) from public.gl_account_balances where code='1110'),
      'trade_receivable', (select coalesce(balance,0) from public.gl_account_balances where code='1100'),
      'overdue_commissions', (select coalesce(sum(amount_due),0) from public.supplier_dues
                              where status not in ('paid','settled') and coalesce(due_date,reveal_date) < current_date)
    ),
    'payables', jsonb_build_object(
      'ap_open', (select coalesce(sum(total-amount_paid),0) from public.ap_bills where status in ('open','partial')),
      'aging', coalesce((select jsonb_agg(to_jsonb(a)) from public.ap_aging a),'[]'::jsonb)
    ),
    'cashflow', coalesce((
      select jsonb_agg(x order by x->>'month')
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month',j3.entry_date),'YYYY-MM'),
          'inflow', sum(l.debit), 'outflow', sum(l.credit), 'net', sum(l.debit-l.credit)
        ) x
        from public.gl_journal_lines l
        join public.gl_journal j3 on j3.id=l.journal_id and j3.status='posted'
        where l.account_code in ('1000','1050')
          and j3.entry_date >= (date_trunc('month',current_date) - interval '5 months')
        group by date_trunc('month',j3.entry_date)
      ) s
    ),'[]'::jsonb),
    'budgets', coalesce((select jsonb_agg(to_jsonb(b)) from public.budget_vs_actual_summary b),'[]'::jsonb)
  );
  j := j || jsonb_build_object('ai', jsonb_build_object(
    'kpis', (select to_jsonb(k) from public.finance_kpis k),
    'forecast', public.fn_finance_forecast(),
    'health', (select (kpis->>'health')::numeric from public.finance_kpi_snapshots order by snapshot_date desc limit 1),
    'open_alerts', (select count(*) from public.agent_actions where agent='finance_ai' and status in ('pending','needs_review')),
    'alerts', coalesce((select jsonb_agg(jsonb_build_object('signal',detail->>'signal','risk',risk,'title',title,'reco',recommendation))
        from public.agent_actions where agent='finance_ai' and status in ('pending','needs_review')),'[]'::jsonb),
    'trend', coalesce((select jsonb_agg(jsonb_build_object('d',snapshot_date,'health',(kpis->>'health'),'cash',(kpis->>'cash')) order by snapshot_date)
        from (select snapshot_date,kpis from public.finance_kpi_snapshots order by snapshot_date desc limit 14) s),'[]'::jsonb)
  ));
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_fraud()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'open_flags', (select count(*) from fraud_flags where coalesce(status,'open') not in ('dismissed','resolved','closed')),
      'high_severity', (select count(*) from fraud_flags where lower(coalesce(severity,'')) in ('high','critical') and coalesce(status,'open') not in ('dismissed','resolved','closed')),
      'flags_7d', (select count(*) from fraud_flags where created_at > now() - interval '7 days'),
      'banned_actors', (select (select count(*) from customers where banned) + (select count(*) from leads where banned))
    ),
    'open_flags', (select coalesce(jsonb_agg(f order by f.created desc),'[]'::jsonb) from (
        select kind, subject_type, subject_id, coalesce(severity,'—') severity, coalesce(status,'open') status,
               to_char(created_at,'YYYY-MM-DD HH24:MI') created, detail
        from fraud_flags where coalesce(status,'open') not in ('dismissed','resolved','closed')
        order by created_at desc limit 100) f),
    'banned', (select coalesce(jsonb_agg(b),'[]'::jsonb) from (
        select 'customer' kind, id::text subject_id, full_name name, banned_reason reason from customers where banned
        union all
        select 'supplier', id::text, company_name, banned_reason from leads where banned limit 100) b)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_governance()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    -- governance_kpis.open_for_review counts every open agent_action; overridden here with the
    -- founder's real number and the held count published beside it under its own name.
    'kpis', (select to_jsonb(k) from public.governance_kpis k)
            || jsonb_build_object('open_for_review', public.fn_founder_refund_approvals_open(),
                                  'held_with_roles', (public.fn_founder_queue(1)->>'held_with_roles_total')::int),
    'universal_rules', (select universal_rules from public.agent_governance where active order by version desc limit 1),
    'response_structure', (select response_structure from public.agent_governance where active order by version desc limit 1),
    'recent_escalations', (select coalesce(jsonb_agg(e),'[]'::jsonb) from (
        select id, agent, title, coalesce(escalation_reason,'—') as reason, confidence,
               public.fn_action_policies(kind, confidence) as policies,
               public.fn_owning_os(agent) as os,
               public.fn_action_holder(kind, agent) as holder,
               false as yours,
               (select d.alternatives from public.decision_log d where d.id = decision_log_id) as alternatives,
               case when decided_at is not null
        then coalesce(status,'decided') || ' by ' || coalesce(decided_by,'the system') || ' on ' || decided_at::date
        else 'held with ' || public.fn_action_holder(kind, agent) || ' since ' || created_at::date end as outcome,
               to_char(created_at,'YYYY-MM-DD') as created
        from public.agent_actions
        where escalated
          and status in ('pending','needs_review')
          and created_at >= public.fn_os_fresh_start_at()
        order by created_at desc limit 15) e),
    'agent_coverage', (select coalesce(jsonb_agg(c),'[]'::jsonb) from (
        select ca.name as agent, (ca.persona is not null) as has_persona,
               exists(select 1 from public.agent_knowledge k where k.agent_key='cat:'||ca.slug or k.agent_key=ca.slug) as has_knowledge,
               (select count(*) from public.agent_actions a where a.agent=ca.slug) as audit_items
        from public.category_agents ca where ca.active order by ca.name limit 60) c),
    'fresh_start_at', public.fn_os_fresh_start_at()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_intelligence()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with mat as (
    -- The company maturity index, in measurement order. This is the only series in the estate long
    -- enough to carry a trajectory, and it is rebuilt nightly.
    select measured_on, score from public.company_index
     where index_name = 'company_maturity'
     order by measured_on
  ), steps as (
    select (score - lag(score) over (order by measured_on))::double precision dx from mat
  ), moments as (
    select count(*)::int n,
           avg(dx) mu,
           coalesce(stddev_samp(dx), 0) sd
      from steps where dx is not null
  )
  select jsonb_build_object(

    -- ── OPPORTUNITIES ────────────────────────────────────────────────────────────────────────
    'opportunities', jsonb_build_object(
      'open', (select count(*) from public.opportunity where status = 'open'),
      'total', (select count(*) from public.opportunity),
      'newest', (select max(created_at) from public.opportunity),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', o.id, 'kind', o.kind, 'title', o.title, 'detail', o.detail,
                 'value_score', o.value_score, 'effort', o.effort, 'confidence', o.confidence,
                 'detected_by', o.detected_by, 'created_at', o.created_at)
               order by o.value_score desc nulls last, o.created_at desc)
             from public.opportunity o where o.status = 'open'), '[]'::jsonb)
    ),

    -- ── COMPETITORS ──────────────────────────────────────────────────────────────────────────
    'competitors', jsonb_build_object(
      'total', (select count(*) from public.competitor),
      'by_threat', coalesce((select jsonb_agg(jsonb_build_object('level', t.threat_level, 'n', t.n)
                     order by case t.threat_level when 'high' then 1 when 'medium' then 2 else 3 end)
                   from (select coalesce(nullif(threat_level, ''), 'unrated') threat_level, count(*) n
                           from public.competitor group by 1) t), '[]'::jsonb),
      'anonymity_rivals', (select count(*) from public.competitor where offers_anonymity is true),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', c.id, 'name', c.name, 'url', c.url, 'kind', c.kind,
                 'threat_level', c.threat_level, 'overlap', c.overlap, 'strength', c.strength,
                 'weakness', c.weakness, 'offers_anonymity', c.offers_anonymity,
                 'verified_at', c.verified_at)
               order by case coalesce(c.threat_level, '') when 'high' then 1 when 'medium' then 2 else 3 end, c.name)
             from public.competitor c), '[]'::jsonb),
      'positions', coalesce((select jsonb_agg(jsonb_build_object(
                 'dimension', p.dimension, 'quotesdone', p.quotesdone,
                 'market_norm', p.market_norm, 'verdict', p.verdict) order by p.id)
             from public.competitive_position p), '[]'::jsonb)
    ),

    -- ── AI SPENDING ──────────────────────────────────────────────────────────────────────────
    -- Every model call the company has paid for, in the window the spec's own cost row (#8) uses.
    'ai_spending', jsonb_build_object(
      'window_days', 30,
      'calls_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days'),
      'total_aed', (select round(coalesce(sum(cost_aed), 0), 4) from public.ai_cost_log where occurred_at > now() - interval '30 days'),
      'failed_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days' and ok is false),
      'cache_hits_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days' and cached is true),
      'cheaper_available_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days' and could_be_cheaper is true),
      'by_model', coalesce((select jsonb_agg(jsonb_build_object('model', m.model_used, 'calls', m.calls, 'aed', m.aed)
                    order by m.aed desc)
                  from (select coalesce(nullif(model_used, ''), 'unknown') model_used, count(*) calls,
                               round(coalesce(sum(cost_aed), 0), 4) aed
                          from public.ai_cost_log where occurred_at > now() - interval '30 days'
                         group by 1) m), '[]'::jsonb),
      'by_dept', coalesce((select jsonb_agg(jsonb_build_object('dept', d.dept_key, 'calls', d.calls, 'aed', d.aed)
                    order by d.aed desc)
                  from (select coalesce(nullif(dept_key, ''), 'unattributed') dept_key, count(*) calls,
                               round(coalesce(sum(cost_aed), 0), 4) aed
                          from public.ai_cost_log where occurred_at > now() - interval '30 days'
                         group by 1) d), '[]'::jsonb),
      'daily', coalesce((select jsonb_agg(jsonb_build_object('d', x.d, 'aed', x.aed, 'calls', x.calls) order by x.d)
                  from (select occurred_at::date d, round(coalesce(sum(cost_aed), 0), 4) aed, count(*) calls
                          from public.ai_cost_log where occurred_at > now() - interval '30 days'
                         group by 1) x), '[]'::jsonb)
    ),

    -- ── GROWTH PROBABILITY ───────────────────────────────────────────────────────────────────
    -- Not a point estimate dressed up as a forecast. The company maturity index is measured
    -- nightly; its daily changes give a drift and a volatility, and those give the probability the
    -- index is higher in 30 days than it is today under a random-walk-with-drift model. The
    -- logistic form is the standard approximation to the normal CDF (max error ~0.01), which is far
    -- below the uncertainty in a 13-point sample — and the sample size travels with the number so
    -- nobody can read it as more than it is.
    'growth_probability', (select jsonb_build_object(
        'horizon_days', 30,
        'observations', m.n,
        'index_name', 'company_maturity',
        'index_now', (select score from mat order by measured_on desc limit 1),
        'index_first', (select score from mat order by measured_on limit 1),
        'window_from', (select min(measured_on) from mat),
        'window_to', (select max(measured_on) from mat),
        'drift_per_day', round(m.mu::numeric, 4),
        'volatility_per_day', round(m.sd::numeric, 4),
        'growth_probability_pct', case when m.n < 3 or m.sd = 0 then null
            else round((100.0 / (1 + exp(-1.702 * (m.mu * sqrt(30.0) / m.sd))))::numeric, 1) end,
        'method', 'P(index in 30d > index today), from the measured daily drift and volatility of the company maturity index; random walk with drift, logistic approximation to the normal CDF'
      ) from moments m),

    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_knowledge()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'chunks',(select coalesce(sum(chunks),0) from kb_category_stats),
      'document_chunks',(select coalesce(sum(chunks),0) from kb_category_stats where source_kind='document'),
      'categories',(select count(distinct category) from kb_category_stats),
      'category_specs',(select count(*) from catalog_supplier_categories),
      'stats_as_of',(select max(refreshed_at) from kb_category_stats)
    ),
    'curator', jsonb_build_object(
      'health', (select (kpis->>'health')::numeric from knowledge_kpi_snapshots order by snapshot_date desc limit 1),
      'coverage_pct', k.coverage_pct, 'knowledge_coverage_pct', k.knowledge_coverage_pct, 'playbook_coverage_pct', k.playbook_coverage_pct,
      'accuracy_pct', k.accuracy_pct, 'freshness_pct', k.freshness_pct, 'usage_reach_pct', k.usage_reach_pct,
      'regulations', k.regulations, 'regulations_pending', k.regulations_pending, 'standards', k.standards, 'manufacturers', k.manufacturers, 'brands', k.brands, 'materials', k.materials, 'playbooks', k.playbooks,
      'open_items', (select count(*) from agent_actions where agent='knowledge_curator' and status in ('pending','needs_review')),
      'tasks', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation))
          from agent_actions where agent='knowledge_curator' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    'reg_library', jsonb_build_object(
      'coverage', (select to_jsonb(rc) from reg_coverage rc),
      'indexed', coalesce((select jsonb_agg(jsonb_build_object('authority',authority,'code',code_name,'domain',domain) order by authority) from reg_catalog where status='indexed'),'[]'::jsonb),
      'missing', coalesce((select jsonb_agg(jsonb_build_object('authority',authority,'code',code_name,'domain',domain,'priority',priority,'status',status) order by priority, authority) from reg_catalog where copyright='free' and status<>'indexed'),'[]'::jsonb),
      'reference_only', coalesce((select jsonb_agg(jsonb_build_object('authority',authority,'code',code_name) order by authority) from reg_catalog where copyright='copyrighted'),'[]'::jsonb)
    ),
    'regulations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'status',authority||coalesce(' · '||status,''),'source_url',source_url) order by coalesce(effective_date, created_at) desc)
        from (select * from regulations order by coalesce(effective_date, created_at) desc limit 20) rg),'[]'::jsonb),
    -- 6 SEP 2026: category counts come from kb_category_stats (refreshed every 30 min), not from a
    -- GROUP BY over 2.7M rows per click.
    'categories', coalesce((select jsonb_agg(jsonb_build_object('key',cat,'count',c) order by c desc) from (
        select coalesce(nullif(regexp_replace(category,'^cat:',''),''),'general') cat, sum(chunks) c from kb_category_stats group by 1 order by 2 desc limit 16) kk),'[]'::jsonb),
    'coverage', coalesce((select jsonb_agg(jsonb_build_object('category',v.category,'label',v.label,'chunks',v.chunks,'status',v.status) order by v.chunks asc, v.num)
        from v_kb_coverage v),'[]'::jsonb),
    'coverage_kpis', jsonb_build_object(
        'gaps',(select count(*) from v_kb_coverage where status='gap'),
        'thin',(select count(*) from v_kb_coverage where status='thin'),
        'covered',(select count(*) from v_kb_coverage where status='covered'),
        'total',(select count(*) from v_kb_coverage)
    ),
    -- WHICH KNOWLEDGE WAS ACTUALLY USED, and by whom. agent_brain writes a row here on every
    -- retrieval; until now nothing read them back, so "the knowledge is being used" was an
    -- assertion rather than something the founder could check.
    'used', coalesce((select jsonb_agg(jsonb_build_object(
        'agent', u.agent, 'query', left(coalesce(u.query,''), 90),
        'category', u.category, 'at', u.created_at) order by u.created_at desc)
      from (select * from kb_usage_log order by created_at desc limit 25) u),'[]'::jsonb),
    'used_kpis', jsonb_build_object(
      'lookups_7d', (select count(*) from kb_usage_log where created_at > now() - interval '7 days'),
      'agents_7d', (select count(distinct agent) from kb_usage_log where created_at > now() - interval '7 days'),
      'categories_7d', (select count(distinct category) from kb_usage_log
                         where created_at > now() - interval '7 days' and category is not null)
    ),
    'recent', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'category',category,'citation',citation)) from (select * from kb_chunks order by created_at desc limit 20) c),'[]'::jsonb)
  )
  from knowledge_kpis k;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_live_company()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(

    -- ── THE PATH: milestone by milestone, with the steps inside each ─────────────────────────
    'goal_path', coalesce((select jsonb_agg(jsonb_build_object(
        'milestone', v.label, 'year_no', v.year_no, 'statement', v.statement,
        'steps', (select coalesce(jsonb_agg(jsonb_build_object(
                     'step', g.goal, 'metric', g.metric, 'target', g.target_value,
                     'unit', g.unit, 'owner_dept', g.owner_dept,
                     'actual', (select p.actual_value from public.goal_period p
                                 where p.goal_key = g.key order by p.updated_at desc limit 1))
                   order by g.sort nulls last), '[]'::jsonb)
                   from public.company_goals g
                  where g.active and coalesce(g.horizon, 'year_' || v.year_no::text) ~* ('year_?' || v.year_no::text)))
      order by v.year_no)
      from public.vision_horizon v where v.active), '[]'::jsonb),
    'roadmap_summary', (select count(*) from public.vision_horizon where active),

    -- ── THE HANDOFF CHAIN: work passing from department to department ────────────────────────
    'handoff_chain', coalesce((select jsonb_agg(jsonb_build_object(
        'id', c.id, 'subject_type', c.subject_type, 'subject_id', c.subject_id,
        'from_dept', c.dept_key, 'hop', c.stage, 'author_agent', c.author_agent,
        'to_dept', (select g.department from public.org_agents g where g.agent_key = c.reviewer_agent limit 1),
        'reviewer_agent', c.reviewer_agent, 'decision', c.decision,
        'reason', left(coalesce(c.reason, ''), 200), 'confidence', c.confidence,
        'delegated_from', c.delegated_from, 'at', c.created_at)
      order by c.created_at desc)
      from (select * from public.review_chain order by created_at desc limit 25) c), '[]'::jsonb),
    'handoffs_total', (select count(*) from public.review_chain),
    'handoff_stages', coalesce((select jsonb_agg(jsonb_build_object('hop', s.stage, 'n', s.n) order by s.n desc)
      from (select stage, count(*) n from public.review_chain group by 1) s), '[]'::jsonb),

    -- Where an event actually landed, which is the other half of the same sequence.
    'event_delivery', coalesce((select jsonb_agg(jsonb_build_object(
        'event_type', e.event_type, 'to_dept', (select g.department from public.org_agents g where g.agent_key = e.agent_key limit 1),
        'agent_key', e.agent_key, 'os_key', e.os_key, 'delivered_at', e.delivered_at,
        'unroutable_reason', e.unroutable_reason) order by e.delivered_at desc)
      from (select * from public.event_delivery order by delivered_at desc limit 15) e), '[]'::jsonb),

    -- ── THE RISK REGISTER ────────────────────────────────────────────────────────────────────
    'risk_register', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'risk', r.risk, 'category', r.category, 'dept_key', r.dept_key,
        'probability', r.probability, 'impact', r.impact, 'owner_agent', r.owner_agent,
        'mitigation', left(coalesce(r.mitigation, ''), 240), 'status', r.status,
        'review_due', r.review_due)
      -- probability and impact are TEXT on this table, not numbers, so they cannot be multiplied
      -- into a score here. Ordered by review urgency instead, and both values travel to the screen.
      order by r.review_due nulls last, r.updated_at desc nulls last)
      from public.risk_register r where coalesce(r.status, '') <> 'closed'), '[]'::jsonb),

    -- ── INFRASTRUCTURE, the last twin class with no reader ───────────────────────────────────
    -- edge_health_probe is the thirteenth twin object class and the only one nothing the browser
    -- can reach had ever read, so the founder's twin was complete except for the machine it runs on.
    'infrastructure', jsonb_build_object(
      'probes', (select count(*) from public.edge_health_probe),
      'rows', coalesce((select jsonb_agg(to_jsonb(p) order by p.id desc)
        from (select * from public.edge_health_probe order by id desc limit 12) p), '[]'::jsonb)),

    -- ── DEPARTMENT HEALTH, for the twin ──────────────────────────────────────────────────────
    'department_health', coalesce((select jsonb_agg(jsonb_build_object(
        'dept_key', h.dept_key, 'department', h.department, 'score', h.score,
        'status', h.status, 'basis', h.basis) order by h.score nulls first)
      from public.v_department_health h), '[]'::jsonb),

    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_marketing()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'health', (select (kpis->>'health')::numeric from marketing_snapshots order by snapshot_date desc limit 1),
    'inquiries_30d', k.inquiries_30d, 'quoted_30d', k.quoted_30d, 'revealed_30d', k.revealed_30d,
    'revenue_30d', k.revenue_30d, 'inq_to_quote_pct', k.inq_to_quote_pct, 'quote_to_reveal_pct', k.quote_to_reveal_pct,
    'blog_published', k.blog_published, 'drafts_pending', k.drafts_pending,
    'social_staged', k.social_staged, 'social_published', k.social_published,
    'seo_pages', k.seo_pages, 'seo_gaps', k.seo_gaps, 'supply_gaps', k.supply_gaps,
    'leads_total', k.leads_total, 'outreach_sent', k.outreach_sent,
    'meta', jsonb_build_object(
      'spend_30d', k.meta_spend_30d, 'clicks_30d', k.meta_clicks_30d, 'results_30d', k.meta_results_30d,
      'impressions_30d', k.meta_impressions_30d, 'active_campaigns', k.meta_active_campaigns,
      'cpl', k.meta_cpl, 'roi', k.meta_roi,
      'sync', (select case when (select value from app_secrets where key='meta_access_token') is not null then 'connected' else 'awaiting_token' end),
      'campaigns', coalesce((select jsonb_agg(jsonb_build_object('name',campaign_name,'status',effective_status,'spend',spend,'clicks',clicks,'results',results))
          from meta_insights where time_window='last_30d' and campaign_name ilike '%quotesdone%'),'[]'::jsonb)
    ),
    'priorities', coalesce((select plan->'priorities' from marketing_snapshots order by snapshot_date desc limit 1),'[]'::jsonb),
    'push_supply', coalesce((select jsonb_agg(jsonb_build_object('category',category,'inquiries_90d',inquiries_90d,'suppliers',suppliers) order by inquiries_90d desc)
        from (select * from marketing_category_demand where inquiries_90d>0 and suppliers=0 order by inquiries_90d desc limit 10) t),'[]'::jsonb),
    'recommendations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation))
        from agent_actions where agent='marketing_ai' and status in ('pending','needs_review')),'[]'::jsonb)
  )
  from marketing_kpis k;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_marketplace()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'rfqs',(select count(*) from inquiries),
      'active',(select count(*) from inquiries where coalesce(status,'') not in ('completed','cancelled','closed')),
      'quotes',(select count(*) from quotes),
      'avg_value',(select round(avg(expected_value)) from inquiries where expected_value is not null),
      'hired',(select count(*) from inquiries where hired_supplier_id is not null),
      'transactions',(select count(*) from transactions)
    ),
    'kanban', coalesce((select jsonb_agg(jsonb_build_object('key',stg,'count',c) order by c desc) from (
        select coalesce(nullif(pipeline_stage,''),coalesce(nullif(status,''),'new')) stg, count(*) c from inquiries group by 1) k),'[]'::jsonb),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id',id,'category',category,'emirate',emirate,'summary',summary,
        'status',status,'pipeline_stage',pipeline_stage,'deal_owner',deal_owner,'expected_value',expected_value,
        'budget',budget,'rfq_ready',rfq_ready,'created_at',created_at) ) from (select * from inquiries order by created_at desc limit 50) i),'[]'::jsonb),
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',id,'inquiry_id',inquiry_id,'supplier_id',supplier_id,
        'quote_amount',quote_amount,'customer_price',customer_price,'status',status,'created_at',created_at)) from (select * from quotes order by created_at desc limit 30) q),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_notifications()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with fq as (select public.fn_founder_queue(8) j)
  select jsonb_build_object(
    -- CRITICAL — a founder alert raised at critical/high. An open agent_action at risk 'critical'
    -- used to be added here; it belongs to its role and is listed under 'held' instead.
    'critical', jsonb_build_object(
      'tier', 'critical',
      'count', (select count(*) from public.founder_alerts
                 where lower(coalesce(level,'')) in ('critical','high')
                   and created_at > now() - interval '7 days'
                   and created_at >= public.fn_os_fresh_start_at()),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', a.event, 'detail', left(a.detail::text, 200),
                          'level', a.level, 'at', a.created_at) order by a.created_at desc)
                from (select * from public.founder_alerts
                       where lower(coalesce(level,'')) in ('critical','high')
                         and created_at > now() - interval '7 days'
                         and created_at >= public.fn_os_fresh_start_at()
                       order by created_at desc limit 8) a), '[]'::jsonb)),

    -- IMPORTANT — waiting on the founder. That is a refund approval and nothing else.
    'important', jsonb_build_object(
      'tier', 'important',
      'count', public.fn_founder_refund_approvals_open(),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', x->>'title', 'detail', 'from ' || (x->>'from') || ' · ' || (x->>'kind_label'),
                          'kind', x->>'kind', 'agent', x->>'from', 'at', x->>'raised', 'id', x->>'id', 'source', x->>'source'))
                from fq, jsonb_array_elements(fq.j->'waiting_on_you') x), '[]'::jsonb)),

    -- HELD — open work that belongs to a named role. Informational: he is not asked to decide it.
    'held', jsonb_build_object(
      'tier', 'held',
      'count', (select (j->>'held_with_roles_total')::int from fq),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                          'title', 'held with ' || (x->>'holder') || ': ' || (x->>'count'),
                          'detail', (select string_agg(k, ', ') from jsonb_array_elements_text(x->'kinds') k),
                          'holder', x->>'holder', 'count', x->>'count'))
                from fq, jsonb_array_elements(fq.j->'held_with_roles') x), '[]'::jsonb)),

    -- SUGGESTED — nothing is blocked, but the company thinks the founder should look.
    'suggested', jsonb_build_object(
      'tier', 'suggested',
      'count', (select count(*) from public.opportunity where status = 'open'
                 and created_at >= public.fn_os_fresh_start_at())
             + (select count(*) from public.evolution_proposal where status = 'proposed'
                 and created_at >= public.fn_os_fresh_start_at()),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', o.title, 'detail', left(coalesce(o.detail,''), 200),
                          'kind', o.kind, 'at', o.created_at) order by o.value_score desc nulls last)
                from (select * from public.opportunity where status = 'open'
                       and created_at >= public.fn_os_fresh_start_at()
                       order by value_score desc nulls last limit 6) o), '[]'::jsonb)),

    -- COMPLETED TODAY — closed since midnight, whoever closed it.
    'completed_today', jsonb_build_object(
      'tier', 'completed_today',
      'count', (select count(*) from public.agent_actions where decided_at::date = current_date),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', a.title, 'status', a.status,
                          'decided_by', a.decided_by, 'at', a.decided_at) order by a.decided_at desc)
                from (select * from public.agent_actions where decided_at::date = current_date
                       order by decided_at desc limit 8) a), '[]'::jsonb)),

    'auto_cleared_24h', (select round(100.0 * count(*) filter (where coalesce(escalated, false) = false)
                                 / greatest(count(*), 1))
                           from public.agent_actions where created_at > now() - interval '24 hours'),
    'auto_handled_30d', (select round(100.0 * count(*) filter (where coalesce(escalated, false) = false)
                                 / greatest(count(*), 1))
                           from public.agent_actions where created_at > now() - interval '30 days'),
    'actions_24h', (select count(*) from public.agent_actions where created_at > now() - interval '24 hours'),
    'actions_30d', (select count(*) from public.agent_actions where created_at > now() - interval '30 days'),
    'outbound_queue', (select count(*) from public.notifications where coalesce(status,'') not in ('sent','delivered')),
    'fresh_start_at', public.fn_os_fresh_start_at(),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_operations()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with fq as (select public.fn_founder_queue(30) j)
  select jsonb_build_object(
    'ops', jsonb_build_object(
      'health', (select (kpis->>'ops_health')::numeric from ops_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from ops_kpis k),
      'recommendations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation)) from agent_actions where agent='operations_ai' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    'security', jsonb_build_object(
      'score', (select (kpis->>'security_score')::numeric from security_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from security_kpis k),
      'incidents', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk)) from agent_actions where agent='security_ai' and status in ('pending','needs_review')),'[]'::jsonb),
      'events', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'severity',severity,'source',source,'at',created_at) order by created_at desc) from (select * from security_events where created_at >= public.fn_os_fresh_start_at() order by created_at desc limit 10) e),'[]'::jsonb)
    ),
    'kpis', jsonb_build_object(
      'approvals_pending', public.fn_founder_refund_approvals_open(),
      'held_with_roles', (select (j->>'held_with_roles_total')::int from fq),
      'high_risk',(select count(*) from agent_actions where status='pending' and coalesce(risk,'') in ('high','critical')),
      -- ONE definition of an open task (was: crm_tasks, the founder's own to-do list, which is 0).
      'tasks_open',(select count(*) from public.v_org_open_tasks),
      'decisions_24h',(select count(*) from decision_log where created_at > now()-interval '24 hours' and created_at >= public.fn_os_fresh_start_at()),
      'disputes',(select count(*) from transactions where coalesce(refund_status,'') in ('requested','pending'))
    ),
    -- HIS: the refund queue, verbatim from fn_founder_queue.
    'approvals', (select j->'waiting_on_you' from fq),
    -- NOT HIS: open agent_actions with the role that holds each. No approve/reject for him.
    'held', coalesce((select jsonb_agg(jsonb_build_object('id',id,'agent',agent,'kind',kind,
        'kind_label', public.fn_ui_label('action_kind', kind),
        'holder', public.fn_action_holder(kind, agent),
        'risk',risk,'title',title,
        'policies', public.fn_action_policies(kind, confidence),
        'recommendation',recommendation,'status',status,'target_table',target_table,'created_at',created_at,
        'os', public.fn_owning_os(agent), 'confidence', confidence, 'yours', false,
        'alternatives', (select d.alternatives from public.decision_log d where d.id = decision_log_id),
        'outcome', 'held with ' || public.fn_action_holder(kind, agent) || ' since ' || created_at::date)) from (
        select a.* from agent_actions a
          left join agent_action_kind_policy p on p.kind = a.kind
         where a.status in ('pending','needs_review') and coalesce(p.policy,'') <> 'founder'
           and a.created_at >= public.fn_os_fresh_start_at()
         order by (coalesce(a.risk,'')='critical') desc, a.created_at desc limit 30) a),'[]'::jsonb),
    'decisions', coalesce((select jsonb_agg(jsonb_build_object('id',id,'actor',actor,'kind',kind,'decision',decision,
        'confidence',confidence,'route_to',route_to,'created_at',created_at)) from (select * from decision_log where created_at >= public.fn_os_fresh_start_at() order by created_at desc limit 20) d),'[]'::jsonb),
    -- The company's open org_tasks, owned by their departments' agents (not his to close: no Done button).
    'tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'status',status,'priority',priority,'due',null,
        'source', coalesce(dept_key,'—') || case when assigned_agent is not null then ' · ' || assigned_agent else '' end,
        'entity','org_task','created_at',created_at)) from (select * from public.v_org_open_tasks order by created_at desc limit 20) t),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_refunds()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'pending', (select count(*) from transactions where refund_status in ('requested','pending')),
      'within_window', (select count(*) from transactions where refund_status in ('requested','pending') and refund_deadline > now()),
      'resolved_30d', (select count(*) from transactions where refund_resolved_at > now() - interval '30 days')
    ),
    'pending', (select coalesce(jsonb_agg(r order by r.requested desc),'[]'::jsonb) from (
        select t.id as transaction_id, t.quote_id, t.reveal_fee, coalesce(t.refund_status,'—') refund_status, coalesce(t.refund_reason,'—') reason,
               to_char(t.refund_requested_at,'YYYY-MM-DD') requested, to_char(t.refund_deadline,'YYYY-MM-DD') deadline,
               (t.refund_deadline > now()) in_window, coalesce(c.full_name,'—') customer, coalesce(l.company_name,'—') supplier
        from transactions t left join customers c on c.id=t.customer_id left join leads l on l.id=t.supplier_id
        where t.refund_status in ('requested','pending') order by t.refund_requested_at desc limit 100) r),
    'recent_resolved', (select coalesce(jsonb_agg(r order by r.resolved desc),'[]'::jsonb) from (
        select t.id as transaction_id, t.quote_id, coalesce(t.refund_status,'—') refund_status, coalesce(t.refund_note,'—') note,
               to_char(t.refund_resolved_at,'YYYY-MM-DD') resolved
        from transactions t where t.refund_resolved_at is not null order by t.refund_resolved_at desc limit 25) r)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_reports()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', (select to_jsonb(k) from public.report_kpis k),
    -- THE LATEST EXECUTIVE MEETING, IN SEQUENCE. exec_reports.findings is the ordered transcript of
    -- what each of the ten officers said; report_registry projects only title/period/id, so until
    -- now the body reached nothing the browser could run. `contributions` keeps the array order
    -- the meeting wrote it in — that order IS the replay.
    'meeting', (select jsonb_build_object(
        'id', r.id, 'period', r.period, 'officer', r.officer, 'summary', r.summary,
        'at', to_char(r.created_at,'YYYY-MM-DD HH24:MI'),
        'contributions', coalesce(r.findings, '[]'::jsonb),
        'priorities', coalesce(r.recommendations, '[]'::jsonb),
        'challenges', (select coalesce(jsonb_agg(jsonb_build_object(
              'proposal', c.proposal, 'by', c.challenged_by, 'of', c.proposed_by,
              'stance', c.stance, 'confidence', c.confidence, 'reasoning', c.reasoning,
              'alternatives', c.alternatives) order by c.id), '[]'::jsonb)
            from public.challenge_record c
           where c.created_at between r.created_at - interval '30 minutes'
                                  and r.created_at + interval '6 hours'))
      from public.exec_reports r where r.officer='ceo' and r.created_at >= public.fn_os_fresh_start_at() order by r.created_at desc limit 1),
    'freshness', (select jsonb_build_object(
        'daily', daily_fresh, 'weekly', weekly_fresh, 'monthly', monthly_fresh, 'quarterly', quarterly_fresh,
        'department', department_fresh, 'supplier', supplier_fresh, 'customer', customer_fresh, 'ai', ai_fresh
      ) from public.report_kpis),
    'recent', (select coalesce(jsonb_agg(r), '[]'::jsonb) from (
        select id, source, report_type, title, period,
               case source when 'exec' then 'exec' when 'narrative' then 'board' else source end as src,
               to_char(created_at,'YYYY-MM-DD HH24:MI') as created
        from public.report_registry where created_at >= public.fn_os_fresh_start_at() order by created_at desc limit 25) r),
    'by_type', (select coalesce(jsonb_agg(t), '[]'::jsonb) from (
        select report_type, id, title,
               case source when 'exec' then 'exec' when 'narrative' then 'board' else source end as src,
               to_char(created_at,'YYYY-MM-DD HH24:MI') as created
        from (
          select distinct on (report_type) report_type, id, source, title, created_at
          from public.report_registry where created_at >= public.fn_os_fresh_start_at() order by report_type, created_at desc
        ) x order by report_type) t),
    -- WHO PRODUCES EACH TYPE, AND WHETHER IT IS RUNNING. A tile that shows only a last date reads
    -- as live; this says "paused" out loud when the cron behind a type is off. Keyed by report_type.
    'producers', (select coalesce(jsonb_object_agg(p.report_type, jsonb_build_object(
        'job', p.jobname, 'active', coalesce(j.active, false),
        'last_run', (select to_char(max(d.start_time),'YYYY-MM-DD HH24:MI') from cron.job_run_details d where d.jobid = j.jobid),
        'paused_reason', case when coalesce(j.active, false) then null
                              when j.jobid is null then 'no cron job named ' || p.jobname
                              else 'cron ' || p.jobname || ' is paused' end)), '{}'::jsonb)
      from (values ('daily','founder_brief_daily'), ('department','reporting_ai_daily'), ('supplier','reporting_ai_daily'),
                   ('customer','reporting_ai_daily'), ('ai','reporting_ai_daily'), ('weekly','board_report_weekly'),
                   ('monthly','monthly_report'), ('quarterly','quarterly_report'), ('finance','finance_ai_daily')) as p(report_type, jobname)
      left join cron.job j on j.jobname = p.jobname),
    'flags', (select coalesce(jsonb_agg(f), '[]'::jsonb) from (
        select title, risk, status, to_char(created_at,'YYYY-MM-DD') as created
        from public.agent_actions
        where agent='reporting_ai' and kind='report_task' and status in ('pending','needs_review')
        order by created_at desc) f)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_rfq_360(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare i public.inquiries%rowtype; j jsonb; docs jsonb := '[]'::jsonb; hired text;
begin
  select * into i from public.inquiries where id=p_id;
  if i.id is null then return jsonb_build_object('error','RFQ not found'); end if;
  if i.drawing_file_path is not null then docs := docs || jsonb_build_object('type','Drawing','name',coalesce(i.drawing_file_name,'drawing'),'path',i.drawing_file_path); end if;
  if i.drawing_redacted_paths is not null then
    docs := docs || coalesce((select jsonb_agg(jsonb_build_object('type','Drawing (redacted)','name','redacted','path',x)) from unnest(i.drawing_redacted_paths) x),'[]'::jsonb);
  end if;
  select company_name into hired from public.leads where id=i.hired_supplier_id;
  j := jsonb_build_object(
    'requirements', jsonb_build_object('category',i.category,'emirate',i.emirate,'role_needed',i.role_needed,
       'summary',i.summary,'spec',i.spec,'boq',i.boq,'boq_confidence',i.boq_confidence,'budget',i.budget,
       'scope_type',i.scope_type,'trades',i.trades,'keywords',i.keywords),
    'status', jsonb_build_object('status',i.status,'pipeline_stage',i.pipeline_stage,'deal_owner',i.deal_owner,
       'expected_value',i.expected_value,'outcome',i.outcome,'lost_reason',i.lost_reason,'completed_at',i.completed_at,
       'project_id',i.project_id,'created_at',i.created_at),
    'ai_qualification', jsonb_build_object('completeness',i.completeness,'rfq_ready',i.rfq_ready,'routing',i.routing,'brief_source',i.brief_source),
    'selected_supplier', case when i.hired_supplier_id is not null then jsonb_build_object('id',i.hired_supplier_id,'company_name',hired) else null end,
    'documents', docs,
    'matching', coalesce((select jsonb_agg(jsonb_build_object('supplier_id',m.supplier_id,'company_name',l.company_name,
       'similarity',m.similarity,'match_reason',m.match_reason,'sent_at',m.sent_at) order by m.similarity desc nulls last)
       from public.inquiry_matches m left join public.leads l on l.id=m.supplier_id where m.inquiry_id=p_id),'[]'::jsonb),
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'supplier_id',q.supplier_id,'company_name',l.company_name,
       'amount',q.quote_amount,'status',q.status,'lead_time',q.lead_time,'validity',q.validity,'quality',q.quality,
       'created_at',q.created_at) order by q.quote_amount asc nulls last)
       from public.quotes q left join public.leads l on l.id=q.supplier_id where q.inquiry_id=p_id),'[]'::jsonb),
    'procurement', public.fn_procurement_analysis(p_id),
    'clarifications', coalesce((select jsonb_agg(jsonb_build_object('question',qn.question,'answer',qn.answer,
       'supplier_id',qn.supplier_id,'asked_at',qn.asked_at,'answered_at',qn.answered_at) order by qn.asked_at desc)
       from public.questions qn where qn.inquiry_id=p_id),'[]'::jsonb),
    'timeline', (select jsonb_agg(e order by e->>'at' desc) from (
        select jsonb_build_object('at',i.created_at,'event','RFQ created') e
        union all select jsonb_build_object('at',m.sent_at,'event','Matched supplier') from public.inquiry_matches m where m.inquiry_id=p_id and m.sent_at is not null
        union all select jsonb_build_object('at',q.created_at,'event','Quote received: AED '||coalesce(q.quote_amount::text,'?')) from public.quotes q where q.inquiry_id=p_id
        union all select jsonb_build_object('at',i.completed_at,'event','Completed'||coalesce(' ('||i.outcome||')','')) where i.completed_at is not null
      ) tl)
  );
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_strategy()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', (select to_jsonb(k) from public.strategy_kpis k),
    'risks', (select coalesce(jsonb_agg(r),'[]'::jsonb) from (
        select title, category, score, likelihood, impact, status
        from public.strategy_risks where status<>'closed' order by score desc limit 20) r),
    'recommendations', (select coalesce(jsonb_agg(x),'[]'::jsonb) from (
        select title, risk, to_char(created_at,'YYYY-MM-DD') as created
        from public.agent_actions where agent='strategy_ai' and kind='strategy_rec'
          and status in ('pending','needs_review') order by array_position(array['high','medium','low']::text[],risk)) x),
    'under_supplied', coalesce(fn_strategy_metrics()->'under_supplied','[]'::jsonb),
    'market_intel', (select coalesce(jsonb_agg(m),'[]'::jsonb) from (
        select kind, title, impact, status, coalesce(source,'—') as source
        from public.market_intel where status<>'dismissed' order by created_at desc limit 20) m),
    'recent_simulations', (select coalesce(jsonb_agg(s),'[]'::jsonb) from (
        select coalesce(nullif(scenario->>'question',''), nullif(scenario->>'title',''), nullif(scenario->>'type',''), 'Scenario #' || id) as title,
               (scenario->>'confidence')::numeric as confidence,
               to_char(created_at,'YYYY-MM-DD HH24:MI') as created
        from public.simulations order by created_at desc limit 8) s)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_supplier_360(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare l public.leads%rowtype; j jsonb; docs jsonb := '[]'::jsonb;
begin
  select * into l from public.leads where id=p_id;
  if l.id is null then return jsonb_build_object('error','supplier not found'); end if;

  -- documents from path fields
  if l.license_doc_path is not null then docs:=docs||jsonb_build_object('type','Trade licence','name',coalesce(l.license_doc_name,'licence'),'path',l.license_doc_path); end if;
  if l.iban_doc_path is not null then docs:=docs||jsonb_build_object('type','Bank/IBAN','name',coalesce(l.iban_doc_name,'iban'),'path',l.iban_doc_path); end if;
  if l.egr_doc_path is not null then docs:=docs||jsonb_build_object('type','Establishment card','name',coalesce(l.egr_doc_name,'egr'),'path',l.egr_doc_path); end if;
  if l.insurance_doc_path is not null then docs:=docs||jsonb_build_object('type','Insurance','name','insurance','path',l.insurance_doc_path); end if;
  if l.vat_doc_path is not null then docs:=docs||jsonb_build_object('type','VAT certificate','name','vat','path',l.vat_doc_path); end if;
  if l.company_profile_doc_path is not null then docs:=docs||jsonb_build_object('type','Company profile','name','profile','path',l.company_profile_doc_path); end if;
  if l.signed_terms_path is not null then docs:=docs||jsonb_build_object('type','Signed terms','name','terms','path',l.signed_terms_path); end if;
  if l.catalog_doc_paths is not null then
    docs := docs || coalesce((select jsonb_agg(jsonb_build_object('type','Catalogue','name','catalogue','path',x))
                              from unnest(l.catalog_doc_paths) x),'[]'::jsonb);
  end if;

  j := jsonb_build_object(
    'profile', jsonb_build_object(
      'id', l.id, 'company_name', l.company_name, 'sector', l.sector, 'sub_type', l.sub_type,
      'emirate', l.emirate, 'city', l.city, 'phone', coalesce(l.phone_e164,l.phone), 'email', l.email,
      'website', l.website, 'contact_name', l.contact_name, 'founded_year', l.founded_year,
      'company_size', l.company_size, 'employee_count', l.employee_count, 'business_role', l.business_role,
      'lifecycle_stage', l.lifecycle_stage, 'claimed', l.claimed
    ),
    'status', jsonb_build_object(
      'approval_status', l.approval_status, 'verified', l.verified, 'verification_status', l.verification_status,
      'registration_status', l.registration_status, 'matching_blocked', l.matching_blocked,
      'matching_block_reason', l.matching_block_reason, 'banned', l.banned, 'banned_reason', l.banned_reason,
      'chat_strikes', l.chat_strikes
    ),
    'ai', jsonb_build_object(
      'capability_summary', l.capability_summary, 'capability_score', l.capability_score,
      'review_notes', l.ai_review_notes, 'review_flags', l.ai_review_flags, 'reviewed_at', l.ai_reviewed_at,
      'twin', coalesce((select to_jsonb(tw) from public.supplier_twin tw where tw.supplier_id=p_id),'{}'::jsonb)
    ),
    'compliance', jsonb_build_object(
      'trade_license_no', l.trade_license_no, 'license_authority', l.license_authority,
      'license_expiry', l.license_expiry, 'trn', l.trn, 'vat_number', l.vat_number,
      'insurance_expiry', l.insurance_expiry, 'iso_certifications', l.iso_certifications,
      'certifications', l.certifications, 'accepted_terms_at', l.accepted_terms_at,
      'registration_expires_at', l.registration_expires_at,
      'license_expiring', (l.license_expiry is not null and l.license_expiry < current_date + 30),
      'insurance_expiring', (l.insurance_expiry is not null and l.insurance_expiry < current_date + 30)
    ),
    'capabilities', jsonb_build_object(
      'brands_carried', l.brands_carried, 'machinery', l.machinery, 'engineers_count', l.engineers_count,
      'team_size', l.team_size, 'warehouse_area', l.warehouse_area, 'service_emirates', l.service_emirates,
      'manufacturer_authorizations', l.manufacturer_authorizations, 'client_references', l.client_references,
      'products', l.products, 'services', l.services,
      'detail', coalesce((select to_jsonb(c) from public.supplier_capabilities c where c.supplier_id=p_id),'{}'::jsonb)
    ),
    'performance', coalesce((select jsonb_build_object(
        'matched',pf.matched,'quoted',pf.quoted,'won',pf.won,'quote_rate',pf.quote_rate,
        'win_rate',pf.win_rate,'perf_score',pf.perf_score,'rating',pf.rating,'review_count',pf.review_count)
        from public.supplier_perf pf where pf.supplier_id=p_id),'{}'::jsonb)
      || jsonb_build_object('rv_reveals',l.rv_reveals,'rv_responded',l.rv_responded,'rv_response_rate',l.rv_response_rate,
                            'app_rating',l.app_rating,'app_reviews',l.app_reviews),
    'reputation', coalesce((select to_jsonb(rp) - 'supplier_id' - 'company_name' from public.supplier_reputation rp where rp.supplier_id=p_id),'{}'::jsonb),
    'financials', (
      select jsonb_build_object(
        'deals_count', count(*) filter (where t.id is not null),
        'deal_value_total', coalesce(sum(t.quote_amount),0),
        'reveal_fees_generated', coalesce(sum(t.reveal_fee) filter (where t.fee_status='paid'),0)
      ) from public.transactions t where t.supplier_id=p_id
    ) || (
      select jsonb_build_object(
        'commission_total', coalesce(sum(amount_due),0),
        'commission_paid', coalesce(sum(amount_due) filter (where status in ('paid','settled')),0),
        'commission_owed', coalesce(sum(amount_due) filter (where status not in ('paid','settled')),0)
      ) from public.supplier_dues where supplier_id=p_id
    ),
    'documents', docs,
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'amount',q.quote_amount,'status',q.status,'created_at',q.created_at) order by q.created_at desc)
                        from (select * from public.quotes where supplier_id=p_id order by created_at desc limit 10) q),'[]'::jsonb),
    'reviews', coalesce((select jsonb_agg(jsonb_build_object('rating',r.rating,'comment',r.comment,'created_at',r.created_at) order by r.created_at desc)
                        from (select * from public.reviews where supplier_id=p_id order by created_at desc limit 8) r),'[]'::jsonb),
    'timeline', (select jsonb_agg(e order by e->>'at' desc) from (
        select jsonb_build_object('at',l.created_at,'event','Added to directory') e where l.created_at is not null
        union all select jsonb_build_object('at',l.registration_submitted_at,'event','Registration submitted') where l.registration_submitted_at is not null
        union all select jsonb_build_object('at',l.approved_at,'event','Approved'||coalesce(' by '||l.approval_decided_by,'')) where l.approved_at is not null
        union all select jsonb_build_object('at',l.accepted_terms_at,'event','Accepted terms') where l.accepted_terms_at is not null
      ) tl),
    -- WHY WE DECIDED WHAT WE DECIDED about this supplier. decision_record holds the reasoning behind
    -- past decisions and decision_trace the policies that were applied; neither reached the supplier
    -- view, so "why did we reject Supplier X?" had no answer on the screen that shows X.
    'rejection_reason', coalesce((select jsonb_agg(jsonb_build_object(
        'id', dr.id, 'problem', dr.problem, 'recommendation', dr.recommendation,
        'risks', dr.risks, 'status', dr.status, 'decided_by', dr.decided_by,
        'actual_outcome', dr.actual_outcome, 'at', dr.created_at) order by dr.created_at desc)
      from public.decision_record dr
      where coalesce(l.company_name,'') <> ''
        and (dr.problem ilike '%'||l.company_name||'%' or dr.context ilike '%'||l.company_name||'%')), '[]'::jsonb),
    'decision_trace', coalesce((select jsonb_agg(jsonb_build_object(
        'entity_id', dt.entity_id, 'policy_keys', dt.policy_keys) order by dt.entity_id)
      from public.decision_trace dt where dt.entity_id = p_id::text), '[]'::jsonb)
  );
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_suppliers(p jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_q text := nullif(trim(coalesce(p->>'q','')),'');
  v_emirate text := nullif(p->>'emirate','');
  v_sector text := nullif(p->>'sector','');
  v_approval text := nullif(p->>'approval','');
  v_limit int := least(coalesce((p->>'limit')::int,50),100);
  v_offset int := greatest(coalesce((p->>'offset')::int,0),0);
  v_rows jsonb; v_total bigint;
begin
  select count(*) into v_total from leads
   where coalesce(source,'') <> 'canary'
     and (v_q is null or company_name ilike '%'||v_q||'%' or categories ilike '%'||v_q||'%')
     and (v_emirate is null or emirate=v_emirate)
     and (v_sector is null or sector=v_sector)
     and (v_approval is null or approval_status=v_approval);

  select coalesce(jsonb_agg(r),'[]'::jsonb) into v_rows from (
    select jsonb_build_object('id',id,'company_name',company_name,'sector',sector,'sub_type',sub_type,
      'emirate',emirate,'city',city,'rating',rating,'reviews',reviews,'categories',categories,
      'approval_status',approval_status,'lifecycle_stage',lifecycle_stage,'verified',verified,
      'verification_status',verification_status,'capability_score',capability_score,'invite_status',invite_status,
      'registration_status',registration_status,'license_expiry',license_expiry,'banned',banned,
      'matching_blocked',matching_blocked,'phone',phone,'website',website,'created_at',created_at) as r
    from leads
    where coalesce(source,'') <> 'canary'
      and (v_q is null or company_name ilike '%'||v_q||'%' or categories ilike '%'||v_q||'%')
      and (v_emirate is null or emirate=v_emirate)
      and (v_sector is null or sector=v_sector)
      and (v_approval is null or approval_status=v_approval)
    order by capability_score desc nulls last, reviews desc nulls last
    limit v_limit offset v_offset
  ) x;

  return jsonb_build_object(
    'kpis', jsonb_build_object(
      'total',(select count(*) from leads where coalesce(source,'') <> 'canary'),
      'approved',(select count(*) from leads where approval_status='approved'),
      'pending_review',(select count(*) from leads where coalesce(approval_status,'') in ('submitted','pending','under_review','pending_review')),
      'verified',(select count(*) from leads where verified is true),
      'registered',(select count(*) from leads where registration_paid_at is not null),
      'licenses_expiring',(select count(*) from leads where license_expiry is not null and license_expiry < (now()+interval '30 days')::date and license_expiry >= now()::date),
      'banned',(select count(*) from leads where banned is true),
      'matching_blocked',(select count(*) from leads where matching_blocked is true)
    ),
    'success', jsonb_build_object(
      'kpis', coalesce((select to_jsonb(k) from supplier_kpis k), '{}'::jsonb),
      'open_risk', (select count(*) from agent_actions where kind='supplier_risk' and status in ('pending','needs_review')),
      'attention', coalesce((select jsonb_agg(a) from (
          select jsonb_build_object('id',supplier_id,'company_name',company_name,'health',health,
            'quality',quality,'compliance',compliance,'response',response,'retention',retention,
            'risk_tier',risk_tier,'dormant',dormant) a
          from supplier_health where risk_tier in ('high','medium') order by health asc limit 10) t),'[]'::jsonb),
      'trend', coalesce((select jsonb_agg(jsonb_build_object('d',snapshot_date,'health',(kpis->>'avg_health')) order by snapshot_date)
          from (select snapshot_date, kpis from supplier_kpi_snapshots order by snapshot_date desc limit 14) s),'[]'::jsonb)
    ),
    'kanban', coalesce((select jsonb_agg(jsonb_build_object('key',stg,'count',c) order by c desc) from (
        select coalesce(nullif(lifecycle_stage,''),'directory') stg, count(*) c from leads where coalesce(source,'') <> 'canary' group by 1 order by 2 desc limit 8) k),'[]'::jsonb),
    'sectors', coalesce((select jsonb_agg(jsonb_build_object('key',s,'count',c) order by c desc) from (
        select coalesce(nullif(sector,''),'other') s, count(*) c from leads where coalesce(source,'') <> 'canary' group by 1 order by 2 desc limit 10) s),'[]'::jsonb),
    'emirates', coalesce((select jsonb_agg(jsonb_build_object('key',e,'count',c) order by c desc) from (
        select coalesce(nullif(emirate,''),'—') e, count(*) c from leads where coalesce(source,'') <> 'canary' group by 1 order by 2 desc limit 10) e),'[]'::jsonb),
    'total', v_total, 'limit', v_limit, 'offset', v_offset, 'rows', v_rows
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.funnel_metrics(days integer DEFAULT 30)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with w as (select (now() - make_interval(days => days)) as since)
  select json_build_object(
    'days', days,
    'inquiries', (select count(*) from public.inquiries i, w where i.created_at>=w.since),
    'matched', (select count(distinct m.inquiry_id) from public.inquiry_matches m join public.inquiries i on i.id=m.inquiry_id, w where i.created_at>=w.since),
    'quoted', (select count(distinct q.inquiry_id) from public.quotes q join public.inquiries i on i.id=q.inquiry_id, w where i.created_at>=w.since),
    'revealed', (select count(*) from public.transactions t join public.inquiries i on i.id=t.inquiry_id, w where t.revealed_at is not null and i.created_at>=w.since),
    'completed', (select count(*) from public.inquiries i, w where i.status='completed' and i.created_at>=w.since),
    'cancelled', (select count(*) from public.inquiries i, w where i.status='cancelled' and i.created_at>=w.since),
    'reveal_fees', (select coalesce(sum(t.reveal_fee),0) from public.transactions t join public.inquiries i on i.id=t.inquiry_id, w where t.revealed_at is not null and i.created_at>=w.since)
  );
$function$


