  return null;
end$function$


CREATE OR REPLACE FUNCTION public.mask_contacts(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s text := t;
begin
  if s is null or s = '' then return s; end if;
  -- emails
  s := regexp_replace(s, '[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}', '[hidden]', 'gi');
  -- explicit URLs
  s := regexp_replace(s, '(https?://|www\.)[^[:space:]]+', '[hidden]', 'gi');
  -- bare social / messenger short links (no scheme)
  s := regexp_replace(s, '(wa\.me|t\.me|bit\.ly|instagram\.com|facebook\.com|fb\.com|linkedin\.com|twitter\.com|x\.com)/[^[:space:]]*', '[hidden]', 'gi');
  -- international UAE numbers (+971 ...)
  s := regexp_replace(s, '\+?971[ \-]?[0-9][0-9 \-]{6,}[0-9]', '[hidden]', 'g');
  -- local UAE mobile  05x xxx xxxx  (9 digits starting 5, optional separators) — bounded so prices/qtys are safe
  s := regexp_replace(s, '\y0?5[0-9][ \-]?[0-9]{3}[ \-]?[0-9]{4}\y', '[hidden]', 'g');
  return s;
end;
$function$


CREATE OR REPLACE FUNCTION public.mask_contacts_jsonb(j jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r jsonb; k text; v jsonb; e jsonb;
begin
  if j is null then return j; end if;
  case jsonb_typeof(j)
    when 'string' then
      return to_jsonb(public.mask_contacts(j #>> '{}'));
    when 'object' then
      r := '{}'::jsonb;
      for k, v in select key, value from jsonb_each(j) loop
        r := r || jsonb_build_object(k, public.mask_contacts_jsonb(v));
      end loop;
      return r;
    when 'array' then
      r := '[]'::jsonb;
      for e in select value from jsonb_array_elements(j) loop
        r := r || jsonb_build_array(public.mask_contacts_jsonb(e));
      end loop;
      return r;
    else
      return j;
  end case;
end;
$function$


CREATE OR REPLACE FUNCTION public.mask_name(t text, nm text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s text := t; part text;
begin
  if s is null or s = '' or nm is null or btrim(nm) = '' then return s; end if;
  s := regexp_replace(s, '\y' || regexp_replace(btrim(nm), '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '\y', '[hidden]', 'gi');
  for part in select unnest(regexp_split_to_array(btrim(nm), '\s+')) loop
    if length(part) >= 3 then
      s := regexp_replace(s, '\y' || regexp_replace(part, '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '\y', '[hidden]', 'gi');
    end if;
  end loop;
  return s;
end;
$function$


CREATE OR REPLACE FUNCTION public.match_suppliers(query_embedding vector, match_count integer DEFAULT 10, p_emirate text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_product text DEFAULT NULL::text, p_min_rating numeric DEFAULT NULL::numeric)
 RETURNS TABLE(id bigint, company_name text, emirate text, business_role text, products text, services text, phone text, email text, whatsapp text, website text, rating numeric, reviews integer, capability_summary text, similarity double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select l.id, l.company_name, l.emirate, l.business_role, l.products, l.services,
         l.phone, l.email, l.whatsapp, l.website, l.rating, l.reviews, l.capability_summary,
         1 - (l.embedding_gte <=> query_embedding) as similarity
  from public.leads l
  left join public.supplier_perf sp on sp.supplier_id = l.id
  where l.embedding_gte is not null
    and public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                               l.approval_status, l.permanently_closed, l.chat_strikes)
    and (p_emirate is null or l.emirate ilike p_emirate)
    and (p_role    is null or l.business_role = p_role)
    and (p_product is null or l.products ilike '%'||p_product||'%' or l.capability_summary ilike '%'||p_product||'%')
    and (p_min_rating is null or l.rating >= p_min_rating)
  order by ( (1 - (l.embedding_gte <=> query_embedding))
             + 0.05 * coalesce(sp.perf_score,0) ) desc
  limit match_count;
$function$


CREATE OR REPLACE FUNCTION public.match_suppliers_kw(p_keywords text[] DEFAULT '{}'::text[], p_category text DEFAULT NULL::text, p_emirate text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_min_rating numeric DEFAULT NULL::numeric, p_limit integer DEFAULT 8, p_multi boolean DEFAULT false)
 RETURNS TABLE(id bigint, company_name text, emirate text, business_role text, products text, services text, phone text, email text, whatsapp text, website text, rating numeric, reviews integer, capability_summary text, match_score integer, in_emirate boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with base as (
    select l.id, l.company_name, l.emirate, l.business_role, l.products, l.services,
           l.phone, l.email, l.whatsapp, l.website, l.rating, l.reviews, l.capability_summary,
           (select count(*) from unnest(p_keywords) k
              where l.products ilike '%'||k||'%' or l.services ilike '%'||k||'%'
                 or l.categories ilike '%'||k||'%' or l.capability_summary ilike '%'||k||'%') as strong_hits,
           (select count(*) from unnest(p_keywords) k where l.company_name ilike '%'||k||'%') as name_hits,
           (p_category is not null and l.sector = p_category) as cat_match,
           (p_multi and (
                 l.sector='fitout'
                 or l.business_role ilike '%turnkey%' or l.business_role ilike '%contract%' or l.business_role ilike '%fit%out%' or l.business_role ilike '%interior%'
                 or l.capability_summary ilike '%turnkey%' or l.capability_summary ilike '%fit-out%' or l.capability_summary ilike '%fit out%' or l.capability_summary ilike '%fitout%' or l.capability_summary ilike '%renovation%' or l.capability_summary ilike '%general contract%' or l.capability_summary ilike '%main contract%'
                 or l.services ilike '%turnkey%' or l.services ilike '%fit-out%' or l.services ilike '%fit out%' or l.services ilike '%renovation%'
               )) as turnkey_match,
           (coalesce(l.app_reviews,0) > 0) as has_app_rev,
           coalesce(p_emirate is not null and l.emirate ilike p_emirate, false) as in_emirate
    from public.leads l
    where public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                                 l.approval_status, l.permanently_closed, l.chat_strikes)
      and (p_role is null or l.business_role=p_role)
      and (p_min_rating is null or l.rating>=p_min_rating)
      and (
            (p_category is not null and l.sector=p_category)
         or exists (select 1 from unnest(p_keywords) k
              where l.products ilike '%'||k||'%' or l.services ilike '%'||k||'%'
                 or l.categories ilike '%'||k||'%' or l.capability_summary ilike '%'||k||'%' or l.company_name ilike '%'||k||'%')
         or (p_multi and (l.sector='fitout' or l.business_role ilike '%turnkey%' or l.business_role ilike '%contract%' or l.business_role ilike '%interior%' or l.capability_summary ilike '%turnkey%' or l.capability_summary ilike '%fit-out%' or l.capability_summary ilike '%fitout%' or l.capability_summary ilike '%renovation%'))
      )
  )
  select id, company_name, emirate, business_role, products, services, phone, email, whatsapp,
         website, rating, reviews, capability_summary,
         ( least(strong_hits,6)*2 + least(name_hits,2)
           + case when cat_match then 3 else 0 end
           + case when turnkey_match then 5 else 0 end
           + case when has_app_rev then 1 else 0 end )::int as match_score,
         in_emirate
  from base
  where cat_match or strong_hits > 0 or turnkey_match
  order by in_emirate desc, match_score desc, rating desc nulls last, reviews desc nulls last
  limit coalesce(p_limit,8);
$function$


CREATE OR REPLACE FUNCTION public.notify_new_quote_sms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare inq record; c record;
begin
  -- K20 cutover. A new quotation row is the declared start of W14. Placed at the TOP, before the early return for an inquiry with no customer: a quotation exists and must be evaluated whether or not there is somebody to text about it.
  perform public.fn_kernel_source_emit('dbtrigger:public.quotes:trg_new_quote_sms', jsonb_build_object(
    'source_ref',  NEW.id::text,
    'raw_payload', jsonb_build_object('quotation_id', NEW.id::text, 'inquiry_id', NEW.inquiry_id::text, 'supplier_id', NEW.supplier_id::text)));
  select i.summary, i.customer_id into inq from public.inquiries i where i.id = NEW.inquiry_id;
  if inq.customer_id is null then return NEW; end if;
  select email, phone, phone_verified into c from public.customers where id = inq.customer_id;
  if c.phone is not null and coalesce(c.phone_verified,false) then
    insert into public.notifications(type, channel, to_phone, to_role, inquiry_id, quote_id, subject, body, status)
    values ('new_quote_sms','sms', c.phone, 'customer', NEW.inquiry_id, NEW.id, '',
      'QuotesDone: you have a new quote on your request'||coalesce(': '||left(inq.summary,80),'')||'. View & compare at quotesdone.com/app', 'queued');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.ops_begin_run(p_package text, p_version text, p_sha text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ops_kb_stage', 'public'
AS $function$
declare r ops_kb_stage.ingestion_runs;
begin
  select * into r from ops_kb_stage.ingestion_runs
   where package_name = p_package and package_version = p_version and coalesce(package_sha256,'') = coalesce(p_sha,'');
  if found then return jsonb_build_object('run_id', r.id, 'reused', true, 'status', r.status); end if;
  insert into ops_kb_stage.ingestion_runs (package_name, package_version, package_sha256, status)
  values (p_package, p_version, coalesce(p_sha,''), 'running') returning * into r;
  return jsonb_build_object('run_id', r.id, 'reused', false, 'status', r.status);
end $function$


CREATE OR REPLACE FUNCTION public.ops_finish_run(p_run_id uuid, p_status text, p_ins bigint, p_upd bigint, p_skip bigint, p_rej bigint, p_detail jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'ops_kb_stage', 'public'
AS $function$
  update ops_kb_stage.ingestion_runs
     set status = coalesce(p_status,'completed'), completed_at = now(),
         inserted_count = coalesce(p_ins,0), updated_count = coalesce(p_upd,0),
         skipped_count = coalesce(p_skip,0), rejected_count = coalesce(p_rej,0),
         detail = coalesce(p_detail,'{}'::jsonb)
   where id = p_run_id;
$function$


CREATE OR REPLACE FUNCTION public.ops_get_files(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'ops_kb_stage', 'public'
AS $function$
  select coalesce(jsonb_object_agg(relative_path, jsonb_build_object('sha256', sha256, 'status', status)), '{}'::jsonb)
  from ops_kb_stage.ingestion_files where run_id = p_run_id;
$function$


CREATE OR REPLACE FUNCTION public.ops_rollback_run(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ops_kb_stage', 'public'
AS $function$
declare v_restored int := 0; v_deleted int := 0;
begin
  with latest as (
    select distinct on (rv.record_id) rv.*
    from ops_kb_stage.record_versions rv
    join ops_kb_stage.records r on r.record_id = rv.record_id
    where r.ingestion_run_id = p_run_id
    order by rv.record_id, rv.replaced_at desc
  )
  update ops_kb_stage.records r
     set content = latest.payload->>'content', title = latest.payload->>'title',
         structured_data = coalesce(latest.payload->'structured_data','{}'::jsonb),
         version = latest.version, content_sha256 = latest.content_sha256,
         validation_status = latest.payload->>'validation_status',
         implementation_status = latest.payload->>'implementation_status',
         ingestion_run_id = (latest.payload->>'ingestion_run_id')::uuid
  from latest where latest.record_id = r.record_id;
  get diagnostics v_restored = row_count;

  -- child projections cascade from records
  delete from ops_kb_stage.records r
   where r.ingestion_run_id = p_run_id
     and not exists (select 1 from ops_kb_stage.record_versions v where v.record_id = r.record_id);
  get diagnostics v_deleted = row_count;

  delete from ops_kb_stage.ingestion_files where run_id = p_run_id;
  update ops_kb_stage.ingestion_runs set status = 'rolled_back', completed_at = now() where id = p_run_id;
  return jsonb_build_object('run_id', p_run_id, 'records_restored', v_restored, 'records_deleted', v_deleted);
end $function$


CREATE OR REPLACE FUNCTION public.ops_stage_upsert(p_target text, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'ops_kb_stage', 'public'
AS $function$
declare v_tbl text; v_conflict text; v_keys text[]; v_all text; v_set text; v_sql text; v_n int;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then return 0; end if;
  case p_target
    when 'sources'             then v_tbl:='sources';             v_conflict:='source_id';
    when 'records'             then v_tbl:='records';             v_conflict:='record_id';
    when 'departments'         then v_tbl:='departments';         v_conflict:='department_key';
    when 'roles'               then v_tbl:='roles';               v_conflict:='record_id';
    when 'sops'                then v_tbl:='sops';                v_conflict:='record_id';
    when 'decision_rules'      then v_tbl:='decision_rules';      v_conflict:='record_id';
    when 'exception_playbooks' then v_tbl:='exception_playbooks'; v_conflict:='record_id';
    when 'kpis'                then v_tbl:='kpis';                v_conflict:='record_id';
    when 'scenarios'           then v_tbl:='scenarios';           v_conflict:='record_id';
    when 'workflows'           then v_tbl:='workflows';           v_conflict:='workflow_key';
    when 'handoffs'            then v_tbl:='handoffs';            v_conflict:='record_id';
    when 'event_subscriptions' then v_tbl:='event_subscriptions'; v_conflict:='record_id';
    when 'templates'           then v_tbl:='templates';           v_conflict:='record_id';
    when 'policies'            then v_tbl:='policies';            v_conflict:='record_id';
    when 'hard_gates'          then v_tbl:='hard_gates';          v_conflict:='record_id';
    when 'live_bindings'       then v_tbl:='live_bindings';       v_conflict:='record_id';
    when 'department_crosswalk' then v_tbl:='department_crosswalk'; v_conflict:='production_dept_key,target_department_key';
    when 'mapping_decisions'   then v_tbl:='mapping_decisions';   v_conflict:='concept_type,concept_key';
    when 'ingestion_files'     then v_tbl:='ingestion_files';     v_conflict:='run_id,relative_path';
    else raise exception 'unknown ops target %', p_target;
  end case;

  select array_agg(a.attname::text order by a.attnum) into v_keys
  from pg_attribute a
  where a.attrelid = format('ops_kb_stage.%I', v_tbl)::regclass
    and a.attnum > 0 and not a.attisdropped
    and a.attname in (select jsonb_object_keys(p_rows->0));
  if v_keys is null then raise exception 'payload has no columns matching ops_kb_stage.%', v_tbl; end if;

  select string_agg(quote_ident(k), ',') into v_all from unnest(v_keys) k;
  select string_agg(format('%I = excluded.%I', k, k), ',') into v_set
  from unnest(v_keys) k where k <> all (string_to_array(v_conflict, ','));

  v_sql := format('insert into ops_kb_stage.%I (%s) select %s from jsonb_populate_recordset(null::ops_kb_stage.%I, $1) on conflict (%s) do %s',
                  v_tbl, v_all, v_all, v_tbl, v_conflict,
                  case when v_set is null then 'nothing' else 'update set ' || v_set end);
  execute v_sql using p_rows;
  get diagnostics v_n = row_count;
  return v_n;
end $function$


CREATE OR REPLACE FUNCTION public.qd_norm_customer_ver()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP = 'UPDATE' then
    if NEW.tos_accepted_at is not distinct from OLD.tos_accepted_at then
      -- Not a new acceptance: the recorded version is evidence and is never rewritten -- except
      -- (6 Sep 2026) by the acceptance's own trigger chain re-aligning the row to the version the
      -- registry publishes now, which is the version fn_customer_terms_accept just recorded in the
      -- kernel. Depth > 1 means we are inside z56's chain, not a later hand call or a profile edit.
      if pg_trigger_depth() > 1
         and NEW.tos_version is distinct from OLD.tos_version
         and NEW.tos_version = public.fn_terms_version('customer') then
        return NEW;
      end if;
      NEW.tos_version := OLD.tos_version;
      return NEW;
    end if;
    if NEW.tos_version is not distinct from OLD.tos_version then
      NEW.tos_version := public.fn_terms_version('customer');
      return NEW;
    end if;
  end if;
  if NEW.tos_accepted_at is not null and coalesce(NEW.tos_version,'') = '' then
    NEW.tos_version := public.fn_terms_version('customer');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_norm_supplier_ver()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP = 'UPDATE' then
    -- Not a new acceptance: the recorded version is evidence and is never rewritten.
    if NEW.accepted_terms_at is not distinct from OLD.accepted_terms_at then
      NEW.accepted_terms_version := OLD.accepted_terms_version;
      return NEW;
    end if;
    -- A genuine re-acceptance. If this statement did not explicitly set a version,
    -- resolve the one actually in force now rather than carrying the stale value forward.
    if NEW.accepted_terms_version is not distinct from OLD.accepted_terms_version then
      NEW.accepted_terms_version := public.fn_terms_version('supplier');
      return NEW;
    end if;
  end if;
  if NEW.accepted_terms_at is not null and coalesce(NEW.accepted_terms_version,'') = '' then
    NEW.accepted_terms_version := public.fn_terms_version('supplier');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_notify_refund_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_company text; v_window int; v_chase int;
begin
  select company_name into v_company from leads where id = NEW.supplier_id;
  select refund_window_working_days, chase_after_working_days into v_window, v_chase
    from pricing_config order by id limit 1;
  -- 6 Sep 2026: the complaint is the Customer Success Director's to work (founder_mail_policy
  -- refund_complaint, allowed_to_email = false). The founder hears about a refund exactly twice: the
  -- day-5 final call (refund_final_call) and the approval itself.
  perform public.fn_notify_founder(
    p_event => 'Refund requested — supplier not responding: ' || coalesce(v_company, '(id ' || NEW.supplier_id::text || ')'),
    p_detail => 'A customer has asked for the reveal fee back because a revealed supplier is not responding.' || chr(10) ||
    'Supplier: ' || coalesce(v_company, '(id ' || NEW.supplier_id::text || ')') || chr(10) ||
    'Inquiry: ' || coalesce(NEW.inquiry_id::text, '') || ' · Transaction: ' || NEW.id::text ||
      ' · Reveal fee: AED ' || coalesce(NEW.reveal_fee::text, '0') || ' · paid ' ||
      coalesce(to_char(NEW.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY'), '?') || chr(10) || chr(10) ||
    'Ladder: the supplier has ' || coalesce(v_window, 5)::text || ' working days from payment. The sweep chases at day ' ||
      coalesce(v_chase, 3)::text || ' and files the refund for the founder''s final call at day ' || coalesce(v_window, 5)::text ||
      '. Reach the supplier now; if they respond, record it (supplier_ack_at or a portal message) so the case closes. ' ||
      'Read fn_refund_state(''' || NEW.id::text || ''') for where it stands.',
    p_level => 'high', p_kind => 'refund_complaint', p_dedupe_key => 'refund_complaint:' || NEW.id::text, p_owner_agent => null);
  -- K20 cutover. A refund complaint raised against a revealed supplier is the declared start of W17. Placed at the final return so the owner notification is sent whether or not the kernel accepts the request.
  -- 4 Sep 2026: W17's case object is the refunds row, which by design does not exist at the
  -- request stage (the claim window has not opened), and the kernel re-raises a missing parent.
  -- The kernel is asked only once the case object exists; the request stage travels on the bus.
  if exists (select 1 from public.refunds r where r.transaction_id = NEW.id) then
    perform public.fn_kernel_source_emit('dbtrigger:public.transactions:trg_notify_refund', jsonb_build_object(
      'source_ref',  NEW.id::text,
      'raw_payload', jsonb_build_object('transaction_id', NEW.id::text, 'inquiry_id', NEW.inquiry_id::text, 'supplier_id', NEW.supplier_id::text, 'reveal_fee', NEW.reveal_fee)));
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_on_due_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if (coalesce(NEW.status,'')='paid' or NEW.paid_at is not null) and (OLD.status is distinct from NEW.status or OLD.paid_at is distinct from NEW.paid_at) then
  -- Kernel cutover. Settlement of an obligation that already exists. The reveal payment that OPENS W16 is trg_reveal_receipt_a; this is the callback on that run.
  perform public.fn_kernel_source_emit('dbtrigger:public.supplier_dues:trg_due_paid', jsonb_build_object(
    'source_ref',  NEW.id::text,
    'workflow_run_id', public.fn_kernel_run_for('payment_transaction:' || coalesce((select nullif(t.payment_ref,'') from public.transactions t where t.id = NEW.transaction_id), NEW.transaction_id::text)),
    'raw_payload', jsonb_build_object('due_id', NEW.id::text, 'supplier_id', NEW.supplier_id::text, 'transaction_id', NEW.transaction_id::text, 'status', NEW.status)));
    if not exists (select 1 from supplier_dues d where d.supplier_id=NEW.supplier_id and coalesce(d.status,'')<>'paid' and d.paid_at is null and d.id<>NEW.id) then
      update leads set matching_blocked=false, matching_block_reason=null where id=NEW.supplier_id and coalesce(rv_nonresponse_refunds,0)<2;
    end if;
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_on_refund_resolved()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_fee numeric; v_admin numeric; v_cust record; v_min int; v_max int; v_window int; v_amount numeric; v_amounts jsonb;
begin
  if NEW.refund_status in ('refunded','approved') and (OLD.refund_status is distinct from NEW.refund_status) then
    v_fee   := coalesce(NEW.reveal_fee, NEW.app_fee, 0);
    v_admin := coalesce((select num_value from public.gl_settings where key='clawback_admin_fee_aed'), 250);
    -- 6 Sep 2026: the one arithmetic. The supplier's charge at issue = the refunded fee + the AED 250
    -- administrative fee (unchanged, from gl_settings as before) + 9% p.a. simple interest pro-rated
    -- by calendar days from the customer's payment to this issue (founder ruling, verbatim in
    -- decision_policy.refund_policy_founder_decision_2026_09_06). collections_legal keeps accruing on
    -- the overdue balance from the due date exactly as before.
    v_amounts := public.fn_refund_amount_aed(v_fee, NEW.revealed_at, now());
  -- Kernel cutover. Resolution of a refund already inside a W17 run. Routing it as new work would open a second W17 for the same transaction.
  perform public.fn_kernel_source_emit('dbtrigger:public.transactions:trg_refund_resolved', jsonb_build_object(
    'source_ref',  NEW.id::text,
    'workflow_run_id', public.fn_kernel_run_for('refund_dispute_case:' || NEW.id::text),
    'raw_payload', jsonb_build_object('transaction_id', NEW.id::text, 'refund_status', NEW.refund_status, 'reveal_fee', v_fee)));


    if not exists (select 1 from public.supplier_dues where transaction_id=NEW.id and coalesce(status,'')<>'cancelled') then
      insert into public.supplier_dues(
        transaction_id, supplier_id, quote_id, quote_amount, commission_pct,
        amount_due, admin_fee, interest_amount, currency,
        reveal_date, due_date, due_date_30, status, created_at)
      values(
        NEW.id, NEW.supplier_id, NEW.quote_id, NEW.quote_amount, 3,
        v_fee,          -- the 3% reveal fee QuotesDone already refunded to the customer
        v_admin,        -- flat administration fee, charged immediately per the supplier terms
        coalesce((v_amounts->>'interest_aed')::numeric, 0),  -- 9% p.a. from the customer's payment to this issue (fn_refund_amount_aed)
        'AED',
        NEW.revealed_at, (now()+interval '7 days'), (now()+interval '30 days'), 'due', now());
    end if;

    update public.leads
      set matching_blocked = true,
          matching_block_reason = 'Unsettled non-response charge (customer refunded due to no response)',
          rv_nonresponse_refunds = coalesce(rv_nonresponse_refunds,0)+1
    where id = NEW.supplier_id;

    if NEW.refund_resolved_at is null then NEW.refund_resolved_at := now(); end if;

    -- 6 Sep 2026: once the money has actually moved ('refunded' is written by refunds_api after
    -- Stripe returned it), the customer is told, and told what the bank takes.
    if NEW.refund_status = 'refunded' then
      select email, full_name into v_cust from public.customers where id = NEW.customer_id;
      select bank_settlement_working_days_min, bank_settlement_working_days_max, refund_window_working_days
        into v_min, v_max, v_window from public.pricing_config order by id limit 1;
      v_amount := round(coalesce(NEW.refund_amount_aed, v_fee), 2);
      if v_cust.email is not null and not exists (
           select 1 from public.notifications n where n.type = 'refund_issued' and n.inquiry_id = NEW.inquiry_id
              and n.to_email = v_cust.email and n.lead_id = NEW.supplier_id) then
        insert into public.notifications(type, kind, to_email, to_role, lead_id, inquiry_id, quote_id, channel, subject, body, status)
        values ('refund_issued', 'refund_issued', v_cust.email, 'customer', NEW.supplier_id, NEW.inquiry_id, NEW.quote_id, 'email',
          'Your QuotesDone reveal fee refund of AED ' || v_amount::text || ' has been issued',
          'Hello ' || coalesce(nullif(btrim(v_cust.full_name), ''), 'there') || ',' || chr(10) || chr(10) ||
          'We have issued a refund of AED ' || v_amount::text || ' — the full reveal fee you paid on ' ||
            coalesce(to_char(NEW.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY'), 'the reveal date') ||
            ' — to your original payment method, because the supplier did not respond within ' ||
            coalesce(v_window, 5)::text || ' working days. No administrative charge is deducted from your refund.' || chr(10) || chr(10) ||
          'Banks and card issuers usually take ' || coalesce(v_min, 7)::text || '–' || coalesce(v_max, 14)::text ||
            ' working days to show it on your statement. If it has not appeared after ' || coalesce(v_max, 14)::text ||
            ' working days, reply to this email and we will trace it with the payment processor.' || chr(10) || chr(10) ||
          'You are welcome to post the request again; we will introduce you to another supplier.' || chr(10) || chr(10) ||
          'QuotesDone', 'queued');
      end if;
    end if;
  end if;
  return NEW;
end;
$function$


CREATE OR REPLACE FUNCTION public.qd_project_ref()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ref text;
begin
  select value into v_ref from app_secrets where key = 'project_ref';
  if v_ref is null then
    select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
      from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
  end if;
  if v_ref is null then
    raise exception 'qd_project_ref: cannot determine the Supabase project ref. Set app_secrets.project_ref.';
  end if;
  return v_ref;
end $function$


CREATE OR REPLACE FUNCTION public.qd_recompute_response()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  with stats as (
    select t.supplier_id, count(*) as reveals,
      count(*) filter (where t.supplier_ack_at is not null
        or exists(select 1 from messages m where m.inquiry_id=t.inquiry_id and m.supplier_id=t.supplier_id and m.sender='supplier' and coalesce(m.blocked,false)=false and m.created_at>t.revealed_at)
        or exists(select 1 from inquiries i where i.id=t.inquiry_id and i.hired_supplier_id=t.supplier_id)
        or (t.refund_status is null and t.revealed_at < now()-interval '7 days')) as responded
    from transactions t where t.revealed_at is not null group by t.supplier_id
  )
  update leads l set rv_reveals=s.reveals, rv_responded=s.responded,
    rv_response_rate=case when s.reveals>0 then round(s.responded::numeric/s.reveals,3) else null end
  from stats s where s.supplier_id=l.id;
end $function$


CREATE OR REPLACE FUNCTION public.qd_sign_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_ref text;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  -- Resolved defensively: a trigger on the Terms-acceptance path must never refuse the signature.
  begin
    v_ref := public.qd_project_ref();
  exception when others then
    v_ref := null;
  end;
  if v_ref is not null then
    perform net.http_post(
      'https://' || v_ref || '.supabase.co/functions/v1/compliance_archive',
      jsonb_build_object('__secret', v_secret, 'action','sign','kind','customer','email', NEW.email),
      '{}'::jsonb, '{"Content-Type":"application/json"}'::jsonb, 8000);
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_sign_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_ref text;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  -- Resolved defensively: a trigger on the Terms-acceptance path must never refuse the signature.
  begin
    v_ref := public.qd_project_ref();
  exception when others then
    v_ref := null;
  end;
  if v_ref is not null then
    perform net.http_post(
      'https://' || v_ref || '.supabase.co/functions/v1/compliance_archive',
      jsonb_build_object('__secret', v_secret, 'action','sign','kind','supplier','email', NEW.claimed_by),
      '{}'::jsonb, '{"Content-Type":"application/json"}'::jsonb, 8000);
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.quote_gate(p_category text, p_quote jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare reqs jsonb; sec jsonb; k text; mand boolean; present boolean; v jsonb;
  miss jsonb := '[]'::jsonb; pres jsonb := '[]'::jsonb; tot_m int := 0; ok_m int := 0;
begin
  select required_sections into reqs from quote_requirements where category = p_category;
  if reqs is null then select required_sections into reqs from quote_requirements where category = 'default'; end if;
  if reqs is null then return jsonb_build_object('pass', true, 'score', 100, 'missing', '[]'::jsonb, 'note', 'no standard defined'); end if;
  for sec in select * from jsonb_array_elements(reqs) loop
    k := sec->>'key'; mand := coalesce((sec->>'mandatory')::boolean, false);
    v := p_quote -> k;
    present := (v is not null) and (
       (jsonb_typeof(v) = 'string'  and length(trim(v #>> '{}')) > 0) or
       (jsonb_typeof(v) = 'array'   and jsonb_array_length(v) > 0) or
       (jsonb_typeof(v) = 'object'  and v <> '{}'::jsonb) or
       (jsonb_typeof(v) in ('number','boolean')));
    if mand then tot_m := tot_m + 1; if present then ok_m := ok_m + 1; end if; end if;
    if present then pres := pres || to_jsonb(k);
    else miss := miss || jsonb_build_object('key', k, 'label', sec->>'label', 'mandatory', mand); end if;
  end loop;
  return jsonb_build_object(
    'pass', (tot_m = 0 or ok_m = tot_m),
    'mandatory_total', tot_m, 'mandatory_present', ok_m,
    'score', case when jsonb_array_length(reqs) > 0 then round(100.0 * jsonb_array_length(pres) / jsonb_array_length(reqs)) else 100 end,
    'present', pres, 'missing', miss);
end $function$


CREATE OR REPLACE FUNCTION public.recent_duplicate_inquiry(p_customer uuid, p_summary text, p_window interval DEFAULT '48:00:00'::interval)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select i.id
  from inquiries i
  where i.customer_id = p_customer
    and i.created_at > now() - p_window
    and p_summary is not null and length(p_summary) > 12
    and similarity(coalesce(i.summary,''), p_summary) > 0.55
  order by i.created_at desc
  limit 1;
$function$


CREATE OR REPLACE FUNCTION public.recompute_supplier_rating(p_supplier bigint)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  update public.leads l set
    app_rating  = (select round(avg(rating)::numeric, 2) from public.reviews r where r.supplier_id = p_supplier),
    app_reviews = (select count(*)::int from public.reviews r where r.supplier_id = p_supplier)
  where l.id = p_supplier;
$function$


CREATE OR REPLACE FUNCTION public.registered_supplier_count()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(max(founding_rank), 0)::int from public.leads
$function$


CREATE OR REPLACE FUNCTION public.reveal_fee(amount numeric, at_time timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- 6 Sep 2026: no discount, no promo, no cap (founder). at_time is kept so callers need no change;
  -- it no longer selects a rate because there is only one rate.
  select case when amount is null or amount <= 0 then 0
              else round(amount * (select c.standard_reveal_rate from public.pricing_config c where c.id = 1), 2)
         end
$function$


CREATE OR REPLACE FUNCTION public.rl_check(p_key text, p_limit integer, p_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  delete from rl_hits where at < now() - (p_seconds || ' seconds')::interval and k = p_key;
  select count(*) into n from rl_hits where k = p_key and at > now() - (p_seconds || ' seconds')::interval;
  if n >= p_limit then return false; end if;
  insert into rl_hits(k) values (p_key);
  return true;
end $function$


